-- Dumping structure for procedure am_web_001.apply_inventory_update_in_price
DROP PROCEDURE IF EXISTS `apply_inventory_update_in_price`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `apply_inventory_update_in_price`(
    IN p_COMPANY_CD VARCHAR(20), IN p_STORE_CD VARCHAR(2000),
    IN p_FROM_YMD CHAR(8), IN p_TO_YMD CHAR(8),
    IN p_PRODUCT_CD VARCHAR(20), IN p_NEW_PRICE DECIMAL(18,6), IN p_USER VARCHAR(50)
)
proc: BEGIN
    DECLARE v_count INT DEFAULT 0;
    IF p_NEW_PRICE IS NULL OR p_NEW_PRICE < 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NEW_PRICE must be zero or greater';
    END IF;
    SELECT COUNT(*) INTO v_count FROM chit_inventory_input i
    WHERE i.COMPANY_CD=p_COMPANY_CD AND IFNULL(i.ISDEL,'0')='0'
      AND (TRIM(IFNULL(p_STORE_CD, '')) = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(i.STORE_CD),''),(SELECT s.STORE_CD FROM store_info s WHERE s.COMPANY_CD=i.COMPANY_CD AND s.STORE_ID=i.STORE_ID AND IFNULL(s.ISDEL,'0')='0' LIMIT 1),''), REPLACE(TRIM(IFNULL(p_STORE_CD, '')), '|', ',')) > 0)
      AND COALESCE(NULLIF(TRIM(i.PRODUCT_CD),''),(SELECT p.PRODUCT_CD FROM product_info p WHERE p.COMPANY_CD=i.COMPANY_CD AND p.PRODUCT_ID=i.PRODUCT_ID AND IFNULL(p.ISDEL,'0')='0' LIMIT 1),'')=p_PRODUCT_CD
      AND COALESCE(DATE_FORMAT(i.INVENTORY_YMD,'%Y%m%d'),(SELECT NULLIF(TRIM(t.INVENTORY_YMD),'') FROM chit_inventory_info t WHERE t.COMPANY_CD=i.COMPANY_CD AND t.INVENTORY_ID=i.INVENTORY_ID AND IFNULL(t.ISDEL,'0')='0' LIMIT 1)) BETWEEN p_FROM_YMD AND p_TO_YMD;
    IF v_count = 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No matching inventory input rows'; END IF;

    SELECT COUNT(*) INTO v_count
    FROM chit_inventory_input i
    LEFT JOIN chitdetailinfo d ON d.COMPANY_CD=i.COMPANY_CD AND d.CHITDETAIL_ID=i.CHITDETAIL_ID
    LEFT JOIN chitinfo h ON h.COMPANY_CD=d.COMPANY_CD AND h.CHIT_ID=d.CHIT_ID
    LEFT JOIN chitinfo_ext e ON e.COMPANY_CD=h.COMPANY_CD AND e.CHIT_ID=h.CHIT_ID AND IFNULL(e.ISDEL,'0')='0'
    WHERE i.COMPANY_CD=p_COMPANY_CD AND IFNULL(i.ISDEL,'0')='0'
      AND (TRIM(IFNULL(p_STORE_CD, '')) = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(i.STORE_CD),''),(SELECT s.STORE_CD FROM store_info s WHERE s.COMPANY_CD=i.COMPANY_CD AND s.STORE_ID=i.STORE_ID AND IFNULL(s.ISDEL,'0')='0' LIMIT 1),''), REPLACE(TRIM(IFNULL(p_STORE_CD, '')), '|', ',')) > 0)
      AND COALESCE(NULLIF(TRIM(i.PRODUCT_CD),''),(SELECT p.PRODUCT_CD FROM product_info p WHERE p.COMPANY_CD=i.COMPANY_CD AND p.PRODUCT_ID=i.PRODUCT_ID AND IFNULL(p.ISDEL,'0')='0' LIMIT 1),'')=p_PRODUCT_CD
      AND COALESCE(DATE_FORMAT(i.INVENTORY_YMD,'%Y%m%d'),(SELECT NULLIF(TRIM(t.INVENTORY_YMD),'') FROM chit_inventory_info t WHERE t.COMPANY_CD=i.COMPANY_CD AND t.INVENTORY_ID=i.INVENTORY_ID AND IFNULL(t.ISDEL,'0')='0' LIMIT 1)) BETWEEN p_FROM_YMD AND p_TO_YMD
      AND i.CHITDETAIL_ID IS NOT NULL
      AND (d.CHITDETAIL_ID IS NULL OR IFNULL(d.ISDEL,'0')<>'0' OR IFNULL(h.ISDEL,'0')<>'0' OR IFNULL(e.IS_LOCK,'0')='1');
    IF v_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A linked accounting voucher is deleted or locked'; END IF;

    SELECT COUNT(*) INTO v_count FROM chit_inventory_input i
    JOIN acc_period_lock_month m ON m.COMPANY_CD=i.COMPANY_CD AND m.PERIOD_YM=LEFT(COALESCE(DATE_FORMAT(i.INVENTORY_YMD,'%Y%m%d'),(SELECT NULLIF(TRIM(t.INVENTORY_YMD),'') FROM chit_inventory_info t WHERE t.COMPANY_CD=i.COMPANY_CD AND t.INVENTORY_ID=i.INVENTORY_ID AND IFNULL(t.ISDEL,'0')='0' LIMIT 1)),6)
      AND IFNULL(m.ISDEL,'0')='0'
    WHERE i.COMPANY_CD=p_COMPANY_CD AND IFNULL(i.ISDEL,'0')='0'
      AND (TRIM(IFNULL(p_STORE_CD, '')) = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(i.STORE_CD),''),(SELECT s.STORE_CD FROM store_info s WHERE s.COMPANY_CD=i.COMPANY_CD AND s.STORE_ID=i.STORE_ID AND IFNULL(s.ISDEL,'0')='0' LIMIT 1),''), REPLACE(TRIM(IFNULL(p_STORE_CD, '')), '|', ',')) > 0)
      AND COALESCE(NULLIF(TRIM(i.PRODUCT_CD),''),(SELECT p.PRODUCT_CD FROM product_info p WHERE p.COMPANY_CD=i.COMPANY_CD AND p.PRODUCT_ID=i.PRODUCT_ID AND IFNULL(p.ISDEL,'0')='0' LIMIT 1),'')=p_PRODUCT_CD
      AND COALESCE(DATE_FORMAT(i.INVENTORY_YMD,'%Y%m%d'),(SELECT NULLIF(TRIM(t.INVENTORY_YMD),'') FROM chit_inventory_info t WHERE t.COMPANY_CD=i.COMPANY_CD AND t.INVENTORY_ID=i.INVENTORY_ID AND IFNULL(t.ISDEL,'0')='0' LIMIT 1)) BETWEEN p_FROM_YMD AND p_TO_YMD
      AND m.STATUS<>'OPEN';
    IF v_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'An affected accounting period is not open'; END IF;

    SELECT COUNT(*) INTO v_count
    FROM chit_inventory_input i
    JOIN chitdetailinfo d ON d.COMPANY_CD=i.COMPANY_CD AND d.CHITDETAIL_ID=i.CHITDETAIL_ID
    JOIN chitinfo h ON h.COMPANY_CD=d.COMPANY_CD AND h.CHIT_ID=d.CHIT_ID
    JOIN acc_period_lock_month m ON m.COMPANY_CD=h.COMPANY_CD AND m.PERIOD_YM=LEFT(h.CHIT_YMD,6) AND IFNULL(m.ISDEL,'0')='0'
    WHERE i.COMPANY_CD=p_COMPANY_CD AND IFNULL(i.ISDEL,'0')='0'
      AND (TRIM(IFNULL(p_STORE_CD, '')) = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(i.STORE_CD),''),(SELECT s.STORE_CD FROM store_info s WHERE s.COMPANY_CD=i.COMPANY_CD AND s.STORE_ID=i.STORE_ID AND IFNULL(s.ISDEL,'0')='0' LIMIT 1),''), REPLACE(TRIM(IFNULL(p_STORE_CD, '')), '|', ',')) > 0)
      AND COALESCE(NULLIF(TRIM(i.PRODUCT_CD),''),(SELECT p.PRODUCT_CD FROM product_info p WHERE p.COMPANY_CD=i.COMPANY_CD AND p.PRODUCT_ID=i.PRODUCT_ID AND IFNULL(p.ISDEL,'0')='0' LIMIT 1),'')=p_PRODUCT_CD
      AND COALESCE(DATE_FORMAT(i.INVENTORY_YMD,'%Y%m%d'),(SELECT NULLIF(TRIM(t.INVENTORY_YMD),'') FROM chit_inventory_info t WHERE t.COMPANY_CD=i.COMPANY_CD AND t.INVENTORY_ID=i.INVENTORY_ID AND IFNULL(t.ISDEL,'0')='0' LIMIT 1)) BETWEEN p_FROM_YMD AND p_TO_YMD
      AND m.STATUS<>'OPEN';
    IF v_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A linked voucher accounting period is not open'; END IF;

    UPDATE chit_inventory_input i
    SET i.UNIT_PRICE_CC=p_NEW_PRICE, i.AMOUNT_CC=ROUND(IFNULL(i.QUANTITY,0)*p_NEW_PRICE,2),
        i.UPDATE_BY=IFNULL(p_USER,''), i.UPDATE_AT=CURRENT_TIMESTAMP
    WHERE i.COMPANY_CD=p_COMPANY_CD AND IFNULL(i.ISDEL,'0')='0'
      AND (TRIM(IFNULL(p_STORE_CD, '')) = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(i.STORE_CD),''),(SELECT s.STORE_CD FROM store_info s WHERE s.COMPANY_CD=i.COMPANY_CD AND s.STORE_ID=i.STORE_ID AND IFNULL(s.ISDEL,'0')='0' LIMIT 1),''), REPLACE(TRIM(IFNULL(p_STORE_CD, '')), '|', ',')) > 0)
      AND COALESCE(NULLIF(TRIM(i.PRODUCT_CD),''),(SELECT p.PRODUCT_CD FROM product_info p WHERE p.COMPANY_CD=i.COMPANY_CD AND p.PRODUCT_ID=i.PRODUCT_ID AND IFNULL(p.ISDEL,'0')='0' LIMIT 1),'')=p_PRODUCT_CD
      AND COALESCE(DATE_FORMAT(i.INVENTORY_YMD,'%Y%m%d'),(SELECT NULLIF(TRIM(t.INVENTORY_YMD),'') FROM chit_inventory_info t WHERE t.COMPANY_CD=i.COMPANY_CD AND t.INVENTORY_ID=i.INVENTORY_ID AND IFNULL(t.ISDEL,'0')='0' LIMIT 1)) BETWEEN p_FROM_YMD AND p_TO_YMD;

    UPDATE chitdetailinfo d
    JOIN (
        SELECT linked.CHITDETAIL_ID, SUM(IFNULL(linked.AMOUNT_CC, ROUND(IFNULL(linked.QUANTITY,0)*IFNULL(linked.UNIT_PRICE_CC,0),2))) AS NEW_AMOUNT
        FROM chit_inventory_input linked
        WHERE linked.COMPANY_CD=p_COMPANY_CD AND IFNULL(linked.ISDEL,'0')='0' AND linked.CHITDETAIL_ID IS NOT NULL
          AND linked.CHITDETAIL_ID IN (
              SELECT selected.CHITDETAIL_ID FROM chit_inventory_input selected
              WHERE selected.COMPANY_CD=p_COMPANY_CD AND IFNULL(selected.ISDEL,'0')='0' AND selected.CHITDETAIL_ID IS NOT NULL
                AND (TRIM(IFNULL(p_STORE_CD, '')) = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(selected.STORE_CD),''),(SELECT s.STORE_CD FROM store_info s WHERE s.COMPANY_CD=selected.COMPANY_CD AND s.STORE_ID=selected.STORE_ID AND IFNULL(s.ISDEL,'0')='0' LIMIT 1),''), REPLACE(TRIM(IFNULL(p_STORE_CD, '')), '|', ',')) > 0)
                AND COALESCE(NULLIF(TRIM(selected.PRODUCT_CD),''),(SELECT p.PRODUCT_CD FROM product_info p WHERE p.COMPANY_CD=selected.COMPANY_CD AND p.PRODUCT_ID=selected.PRODUCT_ID AND IFNULL(p.ISDEL,'0')='0' LIMIT 1),'')=p_PRODUCT_CD
                AND COALESCE(DATE_FORMAT(selected.INVENTORY_YMD,'%Y%m%d'),(SELECT NULLIF(TRIM(t.INVENTORY_YMD),'') FROM chit_inventory_info t WHERE t.COMPANY_CD=selected.COMPANY_CD AND t.INVENTORY_ID=selected.INVENTORY_ID AND IFNULL(t.ISDEL,'0')='0' LIMIT 1)) BETWEEN p_FROM_YMD AND p_TO_YMD
          )
        GROUP BY linked.CHITDETAIL_ID
    ) totals ON totals.CHITDETAIL_ID=d.CHITDETAIL_ID
    SET d.AMOUNT=totals.NEW_AMOUNT, d.UPDATE_BY=IFNULL(p_USER,'')
    WHERE d.COMPANY_CD=p_COMPANY_CD AND IFNULL(d.ISDEL,'0')='0';

    UPDATE chitinfo h
    JOIN (
        SELECT d.CHIT_ID, SUM(d.AMOUNT) AS NEW_AMOUNT
        FROM chitdetailinfo d
        WHERE d.COMPANY_CD=p_COMPANY_CD AND IFNULL(d.ISDEL,'0')='0'
          AND d.CHIT_ID IN (SELECT linked.CHIT_ID FROM chitdetailinfo linked
              JOIN chit_inventory_input i ON i.CHITDETAIL_ID=linked.CHITDETAIL_ID AND i.COMPANY_CD=linked.COMPANY_CD
              WHERE i.COMPANY_CD=p_COMPANY_CD AND IFNULL(i.ISDEL,'0')='0'
                AND (TRIM(IFNULL(p_STORE_CD, '')) = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(i.STORE_CD),''),(SELECT s.STORE_CD FROM store_info s WHERE s.COMPANY_CD=i.COMPANY_CD AND s.STORE_ID=i.STORE_ID AND IFNULL(s.ISDEL,'0')='0' LIMIT 1),''), REPLACE(TRIM(IFNULL(p_STORE_CD, '')), '|', ',')) > 0)
                AND COALESCE(NULLIF(TRIM(i.PRODUCT_CD),''),(SELECT p.PRODUCT_CD FROM product_info p WHERE p.COMPANY_CD=i.COMPANY_CD AND p.PRODUCT_ID=i.PRODUCT_ID AND IFNULL(p.ISDEL,'0')='0' LIMIT 1),'')=p_PRODUCT_CD
                AND COALESCE(DATE_FORMAT(i.INVENTORY_YMD,'%Y%m%d'),(SELECT NULLIF(TRIM(t.INVENTORY_YMD),'') FROM chit_inventory_info t WHERE t.COMPANY_CD=i.COMPANY_CD AND t.INVENTORY_ID=i.INVENTORY_ID AND IFNULL(t.ISDEL,'0')='0' LIMIT 1)) BETWEEN p_FROM_YMD AND p_TO_YMD)
        GROUP BY d.CHIT_ID
    ) totals ON totals.CHIT_ID=h.CHIT_ID
    SET h.AMOUNT=totals.NEW_AMOUNT, h.UPDATE_BY=IFNULL(p_USER,'')
    WHERE h.COMPANY_CD=p_COMPANY_CD AND IFNULL(h.ISDEL,'0')='0';
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.apply_inventory_update_out_price
DROP PROCEDURE IF EXISTS `apply_inventory_update_out_price`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `apply_inventory_update_out_price`(
    IN p_COMPANY_CD VARCHAR(20), IN p_STORE_CD VARCHAR(2000),
    IN p_FROM_YMD CHAR(8), IN p_TO_YMD CHAR(8),
    IN p_PRODUCT_CD VARCHAR(20), IN p_NEW_PRICE DECIMAL(18,6), IN p_USER VARCHAR(50)
)
proc: BEGIN
    DECLARE v_count INT DEFAULT 0;
    IF p_NEW_PRICE IS NULL OR p_NEW_PRICE < 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NEW_PRICE must be zero or greater';
    END IF;

    DROP TEMPORARY TABLE IF EXISTS tmp_inventory_update_out_price_targets;
    CREATE TEMPORARY TABLE tmp_inventory_update_out_price_targets ENGINE=MEMORY AS
    SELECT o.COMPANY_CD,o.INVENTORY_ID,o.OUTPUT_ID
    FROM chit_inventory_output o
    LEFT JOIN chit_inventory_info t ON t.COMPANY_CD=o.COMPANY_CD AND t.INVENTORY_ID=o.INVENTORY_ID AND IFNULL(t.ISDEL,'0')='0'
    WHERE o.COMPANY_CD=p_COMPANY_CD AND IFNULL(o.ISDEL,'0')='0'
      AND (TRIM(IFNULL(p_STORE_CD,''))='' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(o.STORE_CD),''),(SELECT s.STORE_CD FROM store_info s WHERE s.COMPANY_CD=o.COMPANY_CD AND s.STORE_ID=o.STORE_ID AND IFNULL(s.ISDEL,'0')='0' LIMIT 1),''),REPLACE(TRIM(IFNULL(p_STORE_CD,'')),'|',','))>0)
      AND COALESCE(NULLIF(TRIM(o.PRODUCT_CD),''),(SELECT p.PRODUCT_CD FROM product_info p WHERE p.COMPANY_CD=o.COMPANY_CD AND p.PRODUCT_ID=o.PRODUCT_ID AND IFNULL(p.ISDEL,'0')='0' LIMIT 1),'')=p_PRODUCT_CD
      AND COALESCE(DATE_FORMAT(o.INVENTORY_YMD,'%Y%m%d'),NULLIF(TRIM(t.INVENTORY_YMD),'')) BETWEEN p_FROM_YMD AND p_TO_YMD;
    ALTER TABLE tmp_inventory_update_out_price_targets ADD PRIMARY KEY (COMPANY_CD,INVENTORY_ID,OUTPUT_ID);

    SELECT COUNT(*) INTO v_count FROM tmp_inventory_update_out_price_targets;
    IF v_count = 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No matching inventory output rows'; END IF;

    SELECT COUNT(*) INTO v_count
    FROM tmp_inventory_update_out_price_targets target
    JOIN chit_inventory_info t ON t.COMPANY_CD=target.COMPANY_CD AND t.INVENTORY_ID=target.INVENTORY_ID AND IFNULL(t.ISDEL,'0')='0'
    LEFT JOIN chitinfo c ON c.COMPANY_CD=t.COMPANY_CD AND c.CHIT_ID=t.CHIT_ID_COGS AND IFNULL(c.ISDEL,'0')='0'
    LEFT JOIN chitinfo_ext e ON e.COMPANY_CD=c.COMPANY_CD AND e.CHIT_ID=c.CHIT_ID AND IFNULL(e.ISDEL,'0')='0'
    LEFT JOIN chitdetailinfo linked_detail ON linked_detail.COMPANY_CD=t.COMPANY_CD
        AND linked_detail.CHITDETAIL_ID=t.CHITDETAIL_ID_COGS AND linked_detail.CHIT_ID=c.CHIT_ID AND linked_detail.ISDEL='0'
    WHERE t.CHIT_ID_COGS IS NOT NULL AND (c.CHIT_ID IS NULL OR e.CHIT_ID IS NULL OR IFNULL(e.IS_LOCK,'0')='1'
        OR linked_detail.CHITDETAIL_ID IS NULL);
    IF v_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A linked COGS voucher is deleted or locked'; END IF;

    SELECT COUNT(*) INTO v_count
    FROM tmp_inventory_update_out_price_targets target
    JOIN chit_inventory_output o ON o.COMPANY_CD=target.COMPANY_CD AND o.INVENTORY_ID=target.INVENTORY_ID AND o.OUTPUT_ID=target.OUTPUT_ID
    JOIN acc_period_lock_month m ON m.COMPANY_CD=o.COMPANY_CD AND m.PERIOD_YM=LEFT(COALESCE(DATE_FORMAT(o.INVENTORY_YMD,'%Y%m%d'),(SELECT NULLIF(TRIM(t.INVENTORY_YMD),'') FROM chit_inventory_info t WHERE t.COMPANY_CD=o.COMPANY_CD AND t.INVENTORY_ID=o.INVENTORY_ID AND IFNULL(t.ISDEL,'0')='0' LIMIT 1)),6)
      AND IFNULL(m.ISDEL,'0')='0'
    WHERE m.STATUS<>'OPEN';
    IF v_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'An affected accounting period is not open'; END IF;

    SELECT COUNT(*) INTO v_count
    FROM tmp_inventory_update_out_price_targets target
    JOIN chit_inventory_info t ON t.COMPANY_CD=target.COMPANY_CD AND t.INVENTORY_ID=target.INVENTORY_ID AND IFNULL(t.ISDEL,'0')='0'
    JOIN chitinfo c ON c.COMPANY_CD=t.COMPANY_CD AND c.CHIT_ID=t.CHIT_ID_COGS AND IFNULL(c.ISDEL,'0')='0'
    JOIN acc_period_lock_month m ON m.COMPANY_CD=c.COMPANY_CD AND m.PERIOD_YM=LEFT(c.CHIT_YMD,6) AND IFNULL(m.ISDEL,'0')='0'
    WHERE m.STATUS<>'OPEN';
    IF v_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A linked COGS accounting period is not open'; END IF;

    SELECT COUNT(*) INTO v_count
    FROM tmp_inventory_update_out_price_targets target
    JOIN chit_inventory_info t ON t.COMPANY_CD=target.COMPANY_CD AND t.INVENTORY_ID=target.INVENTORY_ID AND IFNULL(t.ISDEL,'0')='0'
    JOIN chitinfo c ON c.COMPANY_CD=t.COMPANY_CD AND c.CHIT_ID=t.CHIT_ID_COGS AND IFNULL(c.ISDEL,'0')='0'
    JOIN acc_period_lock_step s ON s.COMPANY_CD=c.COMPANY_CD AND s.PERIOD_YM=LEFT(c.CHIT_YMD,6)
      AND s.STEP_CODE IN ('COGS_SUMMARY','PROFIT_LOSS_REPORT')
    WHERE s.STATUS IN ('DONE','PROCESSING');
    IF v_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A linked COGS period is locked or processing'; END IF;

    UPDATE chit_inventory_output o
    JOIN tmp_inventory_update_out_price_targets target ON target.COMPANY_CD=o.COMPANY_CD AND target.INVENTORY_ID=o.INVENTORY_ID AND target.OUTPUT_ID=o.OUTPUT_ID
    SET o.UNIT_PRICE_CC=p_NEW_PRICE, o.AMOUNT_CC=ROUND(IFNULL(o.QUANTITY,0)*p_NEW_PRICE,2),
        o.UPDATE_BY=IFNULL(p_USER,''), o.UPDATE_AT=CURRENT_TIMESTAMP;

    DROP TEMPORARY TABLE IF EXISTS tmp_inventory_update_out_price_cogs;
    CREATE TEMPORARY TABLE tmp_inventory_update_out_price_cogs ENGINE=MEMORY AS
    SELECT t.COMPANY_CD,t.CHIT_ID_COGS,t.CHITDETAIL_ID_COGS,SUM(ROUND(IFNULL(o.AMOUNT_CC,0),2)) AS COST_TOTAL
    FROM (SELECT DISTINCT COMPANY_CD,INVENTORY_ID FROM tmp_inventory_update_out_price_targets) target
    JOIN chit_inventory_info t ON t.COMPANY_CD=target.COMPANY_CD AND t.INVENTORY_ID=target.INVENTORY_ID AND IFNULL(t.ISDEL,'0')='0'
    JOIN chit_inventory_output o ON o.COMPANY_CD=t.COMPANY_CD AND o.INVENTORY_ID=t.INVENTORY_ID AND IFNULL(o.ISDEL,'0')='0'
    WHERE t.CHIT_ID_COGS IS NOT NULL
    GROUP BY t.COMPANY_CD,t.CHIT_ID_COGS,t.CHITDETAIL_ID_COGS;
    ALTER TABLE tmp_inventory_update_out_price_cogs ADD PRIMARY KEY (COMPANY_CD,CHITDETAIL_ID_COGS);

    -- Update only the linked aggregate detail; leave other IOs and manual OT rows intact.
    UPDATE chitdetailinfo d
    JOIN tmp_inventory_update_out_price_cogs c ON c.COMPANY_CD=d.COMPANY_CD
        AND c.CHITDETAIL_ID_COGS=d.CHITDETAIL_ID AND c.CHIT_ID_COGS=d.CHIT_ID
    SET d.AMOUNT=c.COST_TOTAL,d.UPDATE_BY=IFNULL(p_USER,'')
    WHERE d.ISDEL='0';

    UPDATE chitinfo h
    JOIN (SELECT COMPANY_CD,CHIT_ID,SUM(AMOUNT) AS TOTAL FROM chitdetailinfo
        WHERE ISDEL='0' GROUP BY COMPANY_CD,CHIT_ID) totals ON totals.COMPANY_CD=h.COMPANY_CD AND totals.CHIT_ID=h.CHIT_ID
    JOIN (SELECT DISTINCT COMPANY_CD,CHIT_ID_COGS FROM tmp_inventory_update_out_price_cogs) affected
        ON affected.COMPANY_CD=h.COMPANY_CD AND affected.CHIT_ID_COGS=h.CHIT_ID
    SET h.AMOUNT=totals.TOTAL,h.UPDATE_BY=IFNULL(p_USER,'') WHERE h.ISDEL='0';

    DROP TEMPORARY TABLE IF EXISTS tmp_inventory_update_out_price_cogs;
    DROP TEMPORARY TABLE IF EXISTS tmp_inventory_update_out_price_targets;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.attachInventoryCogsDetail
DROP PROCEDURE IF EXISTS `attachInventoryCogsDetail`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `attachInventoryCogsDetail`(
    IN p_companyCd VARCHAR(20),
    IN p_userId VARCHAR(50),
    IN p_transferId BIGINT,
    IN p_detailId BIGINT,
    IN p_ymd VARCHAR(8)
)
BEGIN
    DECLARE v_chitId BIGINT DEFAULT NULL;
    DECLARE v_isLock VARCHAR(10) DEFAULT NULL;
    DECLARE v_found INT DEFAULT 0;
    DECLARE v_historicalLinks INT DEFAULT 0;
    DECLARE v_periodClosed INT DEFAULT 0;
    DECLARE v_periodLocked INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_found=0;

    IF p_ymd IS NULL OR CHAR_LENGTH(p_ymd)<>8 THEN
        SELECT 'INVALID_DETAIL' AS RESULT_CODE;
    ELSE
        SET v_found=0;
        SELECT h.CHIT_ID,e.IS_LOCK,1
        INTO v_chitId,v_isLock,v_found
        FROM chitdetailinfo d
        JOIN chitinfo h ON h.COMPANY_CD=d.COMPANY_CD AND h.CHIT_ID=d.CHIT_ID
        JOIN chitinfo_ext e ON e.COMPANY_CD=h.COMPANY_CD AND e.CHIT_ID=h.CHIT_ID AND e.ISDEL='0'
        WHERE d.COMPANY_CD=p_companyCd AND d.CHITDETAIL_ID=p_detailId AND d.ISDEL='0'
        AND h.ISDEL='0' AND h.CHIT_TYPE='OT' AND h.INPUT_TYPE='AR'
        AND h.CHIT_YMD=p_ymd AND d.CHIT_YMD=p_ymd AND d.DEBIT='632' AND d.CREDIT='156'
        AND d.AMOUNT>=0 AND d.FC_TYPE='VND'
        FOR UPDATE;

        IF v_found=0 OR v_chitId IS NULL THEN
            SELECT 'INVALID_DETAIL' AS RESULT_CODE;
        ELSEIF v_isLock IS NULL OR v_isLock<>'0' THEN
            SELECT 'LOCKED' AS RESULT_CODE;
        ELSE
            SELECT IFNULL(SUM(CASE WHEN STATUS<>'OPEN' THEN 1 ELSE 0 END),0) INTO v_periodClosed
            FROM acc_period_lock_month
            WHERE COMPANY_CD=p_companyCd AND PERIOD_YM=LEFT(p_ymd,6) AND ISDEL='0'
            FOR UPDATE;
            SELECT IFNULL(SUM(CASE WHEN STATUS IN ('DONE','PROCESSING') THEN 1 ELSE 0 END),0) INTO v_periodLocked
            FROM acc_period_lock_step
            WHERE COMPANY_CD=p_companyCd AND PERIOD_YM=LEFT(p_ymd,6)
            AND STEP_CODE IN ('COGS_SUMMARY','PROFIT_LOSS_REPORT')
            FOR UPDATE;

            IF v_periodClosed>0 THEN
                SELECT 'PERIOD_CLOSED' AS RESULT_CODE;
            ELSEIF v_periodLocked>0 THEN
                SELECT 'PERIOD_LOCKED' AS RESULT_CODE;
            ELSE
                SELECT COUNT(*) INTO v_historicalLinks
                FROM chit_inventory_info
                WHERE COMPANY_CD=p_companyCd AND CHIT_ID_COGS=v_chitId AND ISDEL='0'
                AND CHITDETAIL_ID_COGS IS NULL;
                IF v_historicalLinks>0 THEN
                    SELECT 'LEGACY_LINKS' AS RESULT_CODE;
                ELSE
                    UPDATE chit_inventory_info SET CHIT_ID_COGS=v_chitId,CHITDETAIL_ID_COGS=p_detailId,
                    COGS_DETAIL_OWNED='0',UPDATE_BY=p_userId
                    WHERE COMPANY_CD=p_companyCd AND INVENTORY_ID=p_transferId AND ISDEL='0';
                    SELECT 'OK' AS RESULT_CODE;
                END IF;
            END IF;
        END IF;
    END IF;
END//
DELIMITER ;


