  `CREDIT_FC` decimal(18,6) NOT NULL DEFAULT '0.000000' COMMENT 'Số dư Có ngoại tệ',
  `EXCHANGE_RATE` decimal(18,6) NOT NULL DEFAULT '1.000000' COMMENT 'Tỷ giá',
  `SUMMARY` varchar(255) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Diễn giải',
  `NOTE` varchar(500) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  `ISDEL` char(1) COLLATE utf8_unicode_ci NOT NULL DEFAULT '0',
  `CREATE_BY` varchar(50) COLLATE utf8_unicode_ci NOT NULL DEFAULT '',
  `CREATE_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `UPDATE_BY` varchar(50) COLLATE utf8_unicode_ci NOT NULL DEFAULT '',
  `UPDATE_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `uk_before_states_department` (`COMPANY_CD`,`OPEN_YMD`,`DEPARTMENT_ID`,`ACC_ID`,`ACC_CD`,`FC_TYPE`),
  KEY `idx_before_states_department_company_cd` (`COMPANY_CD`),
  KEY `idx_before_states_department_open_ymd` (`OPEN_YMD`),
  KEY `idx_before_states_department_department_id` (`DEPARTMENT_ID`),
  KEY `idx_before_states_department_acc_id` (`ACC_ID`),
  KEY `idx_before_states_department_acc_cd` (`ACC_CD`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci COMMENT='Số dư đầu kỳ theo phòng ban';

