-- Dumping structure for procedure am_web_001.build_cash_exchange_revaluation_tmp
DROP PROCEDURE IF EXISTS `build_cash_exchange_revaluation_tmp`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `build_cash_exchange_revaluation_tmp`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_RATE_DATE DATE,
    IN p_FC_TYPE VARCHAR(255),
    IN p_CHIT_YMD_FROM VARCHAR(8),
    IN p_CHIT_YMD_TO VARCHAR(8),
    IN p_RATE_METHOD VARCHAR(30)
)
BEGIN
    DECLARE v_done INT DEFAULT 0;
    DECLARE v_flow_type VARCHAR(20) DEFAULT '';
    DECLARE v_source_module_cd VARCHAR(10) DEFAULT '';
    DECLARE v_company_cd VARCHAR(20) DEFAULT '';
    DECLARE v_chit_id BIGINT DEFAULT 0;
    DECLARE v_chitdetail_id BIGINT DEFAULT 0;
    DECLARE v_chit_cd VARCHAR(50) DEFAULT '';
    DECLARE v_chit_no VARCHAR(50) DEFAULT '';
    DECLARE v_chit_ymd VARCHAR(8) DEFAULT '';
    DECLARE v_chit_type VARCHAR(20) DEFAULT '';
    DECLARE v_chitdetail_cd VARCHAR(50) DEFAULT '';
    DECLARE v_debit VARCHAR(20) DEFAULT '';
    DECLARE v_credit VARCHAR(20) DEFAULT '';
    DECLARE v_treasury_account VARCHAR(20) DEFAULT '';
    DECLARE v_counterpart_account VARCHAR(20) DEFAULT '';
    DECLARE v_fc_type VARCHAR(10) DEFAULT '';
    DECLARE v_fc_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_old_rate DECIMAL(18,6) DEFAULT 0.000000;
    DECLARE v_old_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_in_fc DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_in_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_out_fc DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_source_sort INT DEFAULT 0;
    DECLARE v_group_key VARCHAR(80) DEFAULT '';
    DECLARE v_current_group_key VARCHAR(80) DEFAULT '';
    DECLARE v_balance_fc DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_balance_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_new_rate DECIMAL(18,6) DEFAULT 0.000000;
    DECLARE v_new_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_exchange_diff DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_diff_type VARCHAR(20) DEFAULT 'NONE';
    DECLARE v_from_ymd VARCHAR(8) DEFAULT '';
    DECLARE v_to_ymd VARCHAR(8) DEFAULT '99991231';
    DECLARE v_effective_method VARCHAR(30) DEFAULT 'WEIGHTED_AVERAGE';

    DECLARE cur_cash_exchange CURSOR FOR
        SELECT
            FLOW_TYPE,
            SOURCE_MODULE_CD,
            COMPANY_CD,
            CHIT_ID,
            CHITDETAIL_ID,
            CHIT_CD,
            CHIT_NO,
            CHIT_YMD,
            CHIT_TYPE,
            CHITDETAIL_CD,
            DEBIT,
            CREDIT,
            TREASURY_ACCOUNT,
            COUNTERPART_ACCOUNT,
            FC_TYPE,
            FC_AMOUNT,
            OLD_RATE,
            OLD_AMOUNT,
            IN_FC,
            IN_AMOUNT,
            OUT_FC,
            SOURCE_SORT
        FROM tmp_cash_exchange_revaluation_work
        ORDER BY FC_TYPE, TREASURY_ACCOUNT, CHIT_YMD, CHIT_NO, CHIT_ID, CHITDETAIL_ID, FLOW_SORT, ROW_NO;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    SET v_from_ymd = TRIM(IFNULL(p_CHIT_YMD_FROM, ''));
    SET v_to_ymd = TRIM(IFNULL(p_CHIT_YMD_TO, ''));
    SET v_effective_method = UPPER(TRIM(IFNULL(p_RATE_METHOD, '')));

    IF v_to_ymd = '' THEN
        SET v_to_ymd = '99991231';
    END IF;

    IF v_effective_method = '' OR v_effective_method = '1' OR v_effective_method = 'AVG' THEN
        SET v_effective_method = 'WEIGHTED_AVERAGE';
    END IF;

    IF v_effective_method <> 'WEIGHTED_AVERAGE' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RATE_METHOD must be WEIGHTED_AVERAGE';
    END IF;

    DROP TEMPORARY TABLE IF EXISTS tmp_cash_exchange_revaluation_work;
    CREATE TEMPORARY TABLE tmp_cash_exchange_revaluation_work
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        FLOW_TYPE VARCHAR(20) NOT NULL,
        FLOW_SORT INT NOT NULL DEFAULT 0,
        SOURCE_MODULE_CD VARCHAR(10) NOT NULL DEFAULT '',
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        CHIT_ID BIGINT NOT NULL DEFAULT 0,
        CHITDETAIL_ID BIGINT NOT NULL DEFAULT 0,
        CHIT_CD VARCHAR(50) NOT NULL DEFAULT '',
        CHIT_NO VARCHAR(50) NOT NULL DEFAULT '',
        CHIT_YMD VARCHAR(8) NOT NULL DEFAULT '',
        CHIT_TYPE VARCHAR(20) NOT NULL DEFAULT '',
        CHITDETAIL_CD VARCHAR(50) NOT NULL DEFAULT '',
        DEBIT VARCHAR(20) NOT NULL DEFAULT '',
        CREDIT VARCHAR(20) NOT NULL DEFAULT '',
        TREASURY_ACCOUNT VARCHAR(20) NOT NULL DEFAULT '',
        COUNTERPART_ACCOUNT VARCHAR(20) NOT NULL DEFAULT '',
        FC_TYPE VARCHAR(10) NOT NULL DEFAULT '',
        FC_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        OLD_RATE DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OLD_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        IN_FC DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        IN_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        OUT_FC DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        SOURCE_SORT INT NOT NULL DEFAULT 0,
        PRIMARY KEY (ROW_NO),
        INDEX idx_tmp_cash_exchange_sort (FC_TYPE, TREASURY_ACCOUNT, CHIT_YMD, CHIT_NO, CHIT_ID, CHITDETAIL_ID)
    ) ENGINE=InnoDB;

    INSERT INTO tmp_cash_exchange_revaluation_work
    (
        FLOW_TYPE,
        FLOW_SORT,
        SOURCE_MODULE_CD,
        COMPANY_CD,
        CHIT_YMD,
        TREASURY_ACCOUNT,
        FC_TYPE,
        IN_FC,
        IN_AMOUNT
    )
    SELECT
        'OPENING',
        0,
        'CA',
        b.COMPANY_CD,
        b.OPEN_YMD,
        b.ACC_CD,
        b.FC_TYPE,
        CAST(IFNULL(b.DEBIT_FC, 0) - IFNULL(b.CREDIT_FC, 0) AS DECIMAL(18,2)),
        CAST(IFNULL(b.DEBIT, 0) - IFNULL(b.CREDIT, 0) AS DECIMAL(18,2))
    FROM before_states b
    INNER JOIN
    (
        SELECT
            COMPANY_CD,
            ACC_CD,
            FC_TYPE,
            MAX(OPEN_YMD) AS OPEN_YMD
        FROM before_states
        WHERE COMPANY_CD = p_COMPANY_CD
          AND IFNULL(ISDEL, '0') = '0'
          AND (IFNULL(ACC_CD, '') LIKE '1112%' OR IFNULL(ACC_CD, '') LIKE '1122%')
          AND IFNULL(FC_TYPE, '') <> ''
          AND (IFNULL(p_FC_TYPE, '') = '' OR FIND_IN_SET(TRIM(IFNULL(FC_TYPE, '')), p_FC_TYPE) > 0)
          AND (v_to_ymd = '99991231' OR IFNULL(OPEN_YMD, '') <= v_to_ymd)
        GROUP BY COMPANY_CD, ACC_CD, FC_TYPE
    ) latest
        ON latest.COMPANY_CD = b.COMPANY_CD
       AND latest.ACC_CD = b.ACC_CD
       AND latest.FC_TYPE = b.FC_TYPE
       AND latest.OPEN_YMD = b.OPEN_YMD
    WHERE b.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(b.ISDEL, '0') = '0'
      AND (IFNULL(b.ACC_CD, '') LIKE '1112%' OR IFNULL(b.ACC_CD, '') LIKE '1122%')
      AND IFNULL(b.FC_TYPE, '') <> ''
      AND (IFNULL(b.DEBIT_FC, 0) - IFNULL(b.CREDIT_FC, 0) <> 0 OR IFNULL(b.DEBIT, 0) - IFNULL(b.CREDIT, 0) <> 0);

    INSERT INTO tmp_cash_exchange_revaluation_work
    (
        FLOW_TYPE,
        FLOW_SORT,
        SOURCE_MODULE_CD,
        COMPANY_CD,
        CHIT_ID,
        CHITDETAIL_ID,
        CHIT_CD,
        CHIT_NO,
        CHIT_YMD,
        CHIT_TYPE,
        CHITDETAIL_CD,
        DEBIT,
        CREDIT,
        TREASURY_ACCOUNT,
        COUNTERPART_ACCOUNT,
        FC_TYPE,
        FC_AMOUNT,
        OLD_RATE,
        OLD_AMOUNT,
        IN_FC,
        IN_AMOUNT,
        OUT_FC,
        SOURCE_SORT
    )
    SELECT
        CASE
            WHEN IFNULL(d.DEBIT, '') LIKE '1112%' OR IFNULL(d.DEBIT, '') LIKE '1122%' THEN 'IN'
            ELSE 'OUT'
        END,
        CASE
            WHEN IFNULL(d.DEBIT, '') LIKE '1112%' OR IFNULL(d.DEBIT, '') LIKE '1122%' THEN 1
            ELSE 2
        END,
        UPPER(IFNULL(h.INPUT_TYPE, '')),
        h.COMPANY_CD,
        h.CHIT_ID,
        d.CHITDETAIL_ID,
        h.CHIT_CD,
        h.CHIT_NO,
        h.CHIT_YMD,
        h.CHIT_TYPE,
        d.CHITDETAIL_CD,
        IFNULL(d.DEBIT, ''),
        IFNULL(d.CREDIT, ''),
        CASE
            WHEN IFNULL(d.DEBIT, '') LIKE '1112%' OR IFNULL(d.DEBIT, '') LIKE '1122%' THEN IFNULL(d.DEBIT, '')
            ELSE IFNULL(d.CREDIT, '')
        END,
        CASE
            WHEN IFNULL(d.DEBIT, '') LIKE '1112%' OR IFNULL(d.DEBIT, '') LIKE '1122%' THEN IFNULL(d.CREDIT, '')
            ELSE IFNULL(d.DEBIT, '')
        END,
        UPPER(IFNULL(d.FC_TYPE, '')),
        IFNULL(d.FC_AMOUNT, 0),
        IFNULL(d.FC_RATE, 0),
        IFNULL(d.AMOUNT, 0),
        CASE
            WHEN IFNULL(d.DEBIT, '') LIKE '1112%' OR IFNULL(d.DEBIT, '') LIKE '1122%' THEN IFNULL(d.FC_AMOUNT, 0)
            ELSE 0
        END,
        CASE
            WHEN IFNULL(d.DEBIT, '') LIKE '1112%' OR IFNULL(d.DEBIT, '') LIKE '1122%' THEN IFNULL(d.AMOUNT, 0)
            ELSE 0
        END,
        CASE
            WHEN IFNULL(d.CREDIT, '') LIKE '1112%' OR IFNULL(d.CREDIT, '') LIKE '1122%' THEN IFNULL(d.FC_AMOUNT, 0)
            ELSE 0
        END,
        IFNULL(d.SORT, 0)
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD
       AND d.CHIT_ID = h.CHIT_ID
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(h.ISDEL, '0') = '0'
      AND IFNULL(d.ISDEL, '0') = '0'
      AND IFNULL(d.FC_AMOUNT, 0) <> 0
      AND IFNULL(d.FC_TYPE, '') <> ''
      AND (IFNULL(p_FC_TYPE, '') = '' OR FIND_IN_SET(TRIM(IFNULL(d.FC_TYPE, '')), p_FC_TYPE) > 0)
      AND (v_to_ymd = '99991231' OR IFNULL(h.CHIT_YMD, '') <= v_to_ymd)
      AND (
            IFNULL(d.DEBIT, '') LIKE '1112%'
            OR IFNULL(d.DEBIT, '') LIKE '1122%'
            OR IFNULL(d.CREDIT, '') LIKE '1112%'
            OR IFNULL(d.CREDIT, '') LIKE '1122%'
      );

    DROP TEMPORARY TABLE IF EXISTS tmp_cash_exchange_revaluation_result;
    CREATE TEMPORARY TABLE tmp_cash_exchange_revaluation_result
    (
        MODULE_CD VARCHAR(10) NOT NULL DEFAULT 'CA',
        SOURCE_MODULE_CD VARCHAR(10) NOT NULL DEFAULT '',
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        CHIT_ID BIGINT NOT NULL DEFAULT 0,
        CHITDETAIL_ID BIGINT NOT NULL DEFAULT 0,
        RATE_DATE DATE NOT NULL,
        CHIT_CD VARCHAR(50) NULL,
        CHIT_NO VARCHAR(50) NULL,
        CHIT_YMD VARCHAR(8) NULL,
        CHIT_TYPE VARCHAR(20) NULL,
        CHITDETAIL_CD VARCHAR(50) NULL,
        DEBIT VARCHAR(20) NULL,
        CREDIT VARCHAR(20) NULL,
        TREASURY_ACCOUNT VARCHAR(20) NOT NULL DEFAULT '',
        COUNTERPART_ACCOUNT VARCHAR(20) NOT NULL DEFAULT '',
        GENERATED_CHITDETAIL_CD VARCHAR(20) NOT NULL DEFAULT '',
        FC_TYPE VARCHAR(10) NOT NULL,
        FC_AMOUNT DECIMAL(18,2) NOT NULL,
        OLD_RATE DECIMAL(18,6) NOT NULL,
        NEW_RATE DECIMAL(18,6) NOT NULL,
        OLD_AMOUNT DECIMAL(18,2) NOT NULL,
        NEW_AMOUNT DECIMAL(18,2) NOT NULL,
        EXCHANGE_DIFF DECIMAL(18,2) NOT NULL,
        DIFF_TYPE VARCHAR(20) NOT NULL,
        SOURCE_SORT INT NOT NULL DEFAULT 0,
        BALANCE_FC_BEFORE DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        BALANCE_AMOUNT_BEFORE DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        BALANCE_FC_AFTER DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        BALANCE_AMOUNT_AFTER DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (COMPANY_CD, CHITDETAIL_ID)
    ) ENGINE=InnoDB;

    OPEN cur_cash_exchange;

    read_loop: LOOP
        FETCH cur_cash_exchange INTO
            v_flow_type,
            v_source_module_cd,
            v_company_cd,
            v_chit_id,
            v_chitdetail_id,
            v_chit_cd,
            v_chit_no,
            v_chit_ymd,
            v_chit_type,
            v_chitdetail_cd,
            v_debit,
            v_credit,
            v_treasury_account,
            v_counterpart_account,
            v_fc_type,
            v_fc_amount,
            v_old_rate,
            v_old_amount,
            v_in_fc,
            v_in_amount,
            v_out_fc,
            v_source_sort;

        IF v_done = 1 THEN
            LEAVE read_loop;
        END IF;

        SET v_group_key = CONCAT(v_fc_type, '|', v_treasury_account);
        IF v_current_group_key <> v_group_key THEN
            SET v_current_group_key = v_group_key;
            SET v_balance_fc = 0.00;
            SET v_balance_amount = 0.00;
        END IF;

        IF v_flow_type = 'OPENING' OR v_flow_type = 'IN' THEN
            SET v_balance_fc = v_balance_fc + IFNULL(v_in_fc, 0);
            SET v_balance_amount = v_balance_amount + IFNULL(v_in_amount, 0);
        ELSEIF v_flow_type = 'OUT' THEN
            IF v_balance_fc <> 0 THEN
                SET v_new_rate = ROUND(v_balance_amount / v_balance_fc, 6);
            ELSEIF v_old_rate <> 0 THEN
                SET v_new_rate = v_old_rate;
            ELSE
                SET v_new_rate = 0.000000;
            END IF;

            SET v_new_amount = ROUND(IFNULL(v_out_fc, 0) * v_new_rate, 2);
            SET v_exchange_diff = ROUND(v_new_amount - IFNULL(v_old_amount, 0), 2);
            SET v_diff_type = CASE
                WHEN v_exchange_diff > 0 THEN 'LOSS'
                WHEN v_exchange_diff < 0 THEN 'GAIN'
                ELSE 'NONE'
            END;

            IF (v_from_ymd = '' OR v_chit_ymd >= v_from_ymd) AND (v_to_ymd = '99991231' OR v_chit_ymd <= v_to_ymd) THEN
                INSERT INTO tmp_cash_exchange_revaluation_result
                (
                    MODULE_CD,
                    SOURCE_MODULE_CD,
                    COMPANY_CD,
                    CHIT_ID,
                    CHITDETAIL_ID,
                    RATE_DATE,
                    CHIT_CD,
                    CHIT_NO,
                    CHIT_YMD,
                    CHIT_TYPE,
                    CHITDETAIL_CD,
                    DEBIT,
                    CREDIT,
                    TREASURY_ACCOUNT,
                    COUNTERPART_ACCOUNT,
                    GENERATED_CHITDETAIL_CD,
                    FC_TYPE,
                    FC_AMOUNT,
                    OLD_RATE,
                    NEW_RATE,
                    OLD_AMOUNT,
                    NEW_AMOUNT,
                    EXCHANGE_DIFF,
                    DIFF_TYPE,
                    SOURCE_SORT,
                    BALANCE_FC_BEFORE,
                    BALANCE_AMOUNT_BEFORE,
                    BALANCE_FC_AFTER,
                    BALANCE_AMOUNT_AFTER
                )
                VALUES
                (
                    'CA',
                    v_source_module_cd,
                    v_company_cd,
                    v_chit_id,
                    v_chitdetail_id,
                    p_RATE_DATE,
                    v_chit_cd,
                    v_chit_no,
                    v_chit_ymd,
                    v_chit_type,
                    v_chitdetail_cd,
                    v_debit,
                    v_credit,
                    v_treasury_account,
                    v_counterpart_account,
                    CONCAT('F', v_chitdetail_id),
                    v_fc_type,
                    v_fc_amount,
                    v_old_rate,
                    v_new_rate,
                    v_old_amount,
                    v_new_amount,
                    v_exchange_diff,
                    v_diff_type,
                    v_source_sort,
                    v_balance_fc,
                    v_balance_amount,
                    v_balance_fc - IFNULL(v_out_fc, 0),
                    v_balance_amount - v_new_amount
                );
            END IF;

            SET v_balance_fc = v_balance_fc - IFNULL(v_out_fc, 0);
            SET v_balance_amount = v_balance_amount - v_new_amount;
        END IF;
    END LOOP;

    CLOSE cur_cash_exchange;
END//
DELIMITER ;


