-- Dumping structure for procedure am_web_001.checkChitCdExists
DROP PROCEDURE IF EXISTS `checkChitCdExists`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `checkChitCdExists`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHIT_CD VARCHAR(50),
    IN p_INPUT_TYPE VARCHAR(20),
    IN p_EXCLUDE_CHIT_ID BIGINT
)
BEGIN
    SELECT 1
    FROM chitinfo
    WHERE COMPANY_CD = p_COMPANY_CD
      AND CHIT_CD = p_CHIT_CD
      AND IFNULL(INPUT_TYPE, '') = IFNULL(p_INPUT_TYPE, '')
      AND IFNULL(ISDEL, '0') = '0'
      AND (p_EXCLUDE_CHIT_ID IS NULL OR CHIT_ID <> p_EXCLUDE_CHIT_ID)
    LIMIT 1;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.checkChitInventoryTransferCd
DROP PROCEDURE IF EXISTS `checkChitInventoryTransferCd`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `checkChitInventoryTransferCd`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_TRANSFER_CD VARCHAR(30),
    IN p_EXCLUDE_TRANSFER_ID BIGINT
)
BEGIN
    SELECT CASE WHEN EXISTS (
        SELECT 1
        FROM chit_inventory_info
        WHERE COMPANY_CD = p_COMPANY_CD
          AND INVENTORY_CD = p_TRANSFER_CD
          AND IFNULL(ISDEL, '0') = '0'
          AND (p_EXCLUDE_TRANSFER_ID IS NULL OR p_EXCLUDE_TRANSFER_ID = 0 OR INVENTORY_ID <> p_EXCLUDE_TRANSFER_ID)
    ) THEN 1 ELSE 0 END AS EXISTS_YN;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.check_exists
DROP PROCEDURE IF EXISTS `check_exists`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `check_exists`(
    IN p_TABLE_NAME VARCHAR(100),
    IN p_COMPANY_FIELD VARCHAR(100),
    IN p_COMPANY_CD VARCHAR(50),
    IN p_CODE_FIELD VARCHAR(100),
    IN p_CODE_VALUE VARCHAR(255),
    IN p_ID_FIELD VARCHAR(100),
    IN p_EXCLUDE_ID BIGINT,
    OUT p_CNT INT
)
BEGIN
    SET @v_cnt = 0;

    SET @sql = CONCAT(
        'SELECT COUNT(*) INTO @v_cnt ',
        'FROM ', p_TABLE_NAME, ' ',
        'WHERE 1=1 '
    );

    IF IFNULL(p_COMPANY_FIELD, '') <> '' THEN
        SET @sql = CONCAT(@sql, ' AND ', p_COMPANY_FIELD, ' = ? ');
    END IF;

    SET @sql = CONCAT(@sql, ' AND ', p_CODE_FIELD, ' = ? ');

    IF IFNULL(p_ID_FIELD, '') <> '' THEN
        SET @sql = CONCAT(@sql, ' AND ', p_ID_FIELD, ' <> ? ');
    END IF;

    PREPARE stmt FROM @sql;

