-- Dumping structure for procedure am_web_001.clearInventoryCogsLink
DROP PROCEDURE IF EXISTS `clearInventoryCogsLink`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `clearInventoryCogsLink`(
    IN p_companyCd VARCHAR(20),
    IN p_userId VARCHAR(50),
    IN p_transferId BIGINT,
    IN p_cogsChitId BIGINT
)
BEGIN
    DECLARE v_detailId BIGINT DEFAULT NULL;
    DECLARE v_owned CHAR(1) DEFAULT '0';
    DECLARE v_found INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_found=0;

    SELECT CHITDETAIL_ID_COGS,COGS_DETAIL_OWNED,1
    INTO v_detailId,v_owned,v_found
    FROM chit_inventory_info
    WHERE COMPANY_CD=p_companyCd AND INVENTORY_ID=p_transferId AND CHIT_ID_COGS=p_cogsChitId AND ISDEL='0'
    FOR UPDATE;

    IF v_found=0 THEN
        SELECT 'NOT_FOUND' AS RESULT_CODE;
    ELSEIF v_detailId IS NULL THEN
        SELECT 'LEGACY_UNLINK' AS RESULT_CODE;
    ELSE
        UPDATE chit_inventory_info SET CHIT_ID_COGS=NULL,CHITDETAIL_ID_COGS=NULL,COGS_DETAIL_OWNED='0',UPDATE_BY=p_userId
        WHERE COMPANY_CD=p_companyCd AND INVENTORY_ID=p_transferId AND CHIT_ID_COGS=p_cogsChitId;
        UPDATE chit_inventory_output SET CHITDETAIL_ID_COGS=NULL,UPDATE_BY=p_userId
        WHERE COMPANY_CD=p_companyCd AND INVENTORY_ID=p_transferId AND ISDEL='0';
        IF v_owned='1' THEN
            UPDATE chitdetailinfo SET ISDEL='1',UPDATE_BY=p_userId WHERE COMPANY_CD=p_companyCd AND CHITDETAIL_ID=v_detailId AND ISDEL='0';
            UPDATE chitdetailinfo_ext SET ISDEL='1',UPDATE_BY=p_userId WHERE COMPANY_CD=p_companyCd AND CHITDETAIL_ID=v_detailId AND ISDEL='0';
            UPDATE chitdetaildescriptioninfo SET ISDEL='1',UPDATE_BY=p_userId WHERE COMPANY_CD=p_companyCd AND CHITDETAIL_ID=v_detailId AND ISDEL='0';
            UPDATE chitinfo SET AMOUNT=(SELECT COALESCE(SUM(AMOUNT),0) FROM chitdetailinfo
            WHERE COMPANY_CD=p_companyCd AND CHIT_ID=p_cogsChitId AND ISDEL='0'),UPDATE_BY=p_userId
            WHERE COMPANY_CD=p_companyCd AND CHIT_ID=p_cogsChitId AND ISDEL='0';
            UPDATE chitinfo h SET h.ISDEL='1',h.UPDATE_BY=p_userId
            WHERE h.COMPANY_CD=p_companyCd AND h.CHIT_ID=p_cogsChitId AND h.ISDEL='0'
            AND NOT EXISTS (SELECT 1 FROM chitdetailinfo d WHERE d.COMPANY_CD=p_companyCd AND d.CHIT_ID=p_cogsChitId AND d.ISDEL='0')
            AND NOT EXISTS (SELECT 1 FROM chit_inventory_info t WHERE t.COMPANY_CD=p_companyCd AND t.CHIT_ID_COGS=p_cogsChitId AND t.ISDEL='0');
            UPDATE chitinfo_ext e JOIN chitinfo h ON h.COMPANY_CD=e.COMPANY_CD AND h.CHIT_ID=e.CHIT_ID
            SET e.ISDEL='1',e.UPDATE_BY=p_userId WHERE h.COMPANY_CD=p_companyCd AND h.CHIT_ID=p_cogsChitId AND h.ISDEL='1';
        END IF;
        SELECT 'OK' AS RESULT_CODE;
    END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.cloneEInvoiceSellerXslTemplateDesign
DROP PROCEDURE IF EXISTS `cloneEInvoiceSellerXslTemplateDesign`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `cloneEInvoiceSellerXslTemplateDesign`(
  IN p_CONTENT_ID BIGINT UNSIGNED,
  IN p_SOURCE_DESIGN_ID BIGINT UNSIGNED,
  IN p_COMPANY_CD VARCHAR(20),
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_NEXT_NO INT DEFAULT 1;

  IF NOT EXISTS (
    SELECT 1 FROM einvoice_seller_xsl_template template
    WHERE template.XSL_ID = p_CONTENT_ID AND template.COMPANY_CD = p_COMPANY_CD AND template.ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invoice template not found';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM einvoice_seller_xsl_template_design WHERE DESIGN_ID = p_SOURCE_DESIGN_ID AND CONTENT_ID = p_CONTENT_ID) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Source design not found';
  END IF;

  SELECT COUNT(*) + 1
    INTO v_NEXT_NO
    FROM einvoice_seller_xsl_template_design
   WHERE CONTENT_ID = p_CONTENT_ID;

  INSERT INTO einvoice_seller_xsl_template_design
    (CONTENT_ID, DESIGN_NM, XSL_CONTENT, LOGO_PATH, INVOICE_BACKGROUND_PATH, INVOICE_BORDER_PATH, BACKGROUND_PATH, CREATE_BY, CREATE_AT, UPDATE_BY, UPDATE_AT)
  SELECT CONTENT_ID, CONCAT('Mẫu số ', v_NEXT_NO),
         XSL_CONTENT, LOGO_PATH, INVOICE_BACKGROUND_PATH, INVOICE_BORDER_PATH, BACKGROUND_PATH,
         p_USERID, NOW(), p_USERID, NOW()
  FROM einvoice_seller_xsl_template_design
  WHERE DESIGN_ID = p_SOURCE_DESIGN_ID AND CONTENT_ID = p_CONTENT_ID;

  SELECT DESIGN_ID, CONTENT_ID, CONTENT_ID AS XSL_ID, DESIGN_NM, XSL_CONTENT,
         LOGO_PATH, INVOICE_BACKGROUND_PATH, INVOICE_BORDER_PATH, BACKGROUND_PATH,
         1 AS IS_EDITABLE, CREATE_AT, UPDATE_AT
  FROM einvoice_seller_xsl_template_design WHERE DESIGN_ID = LAST_INSERT_ID();
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.cloneEInvoiceSellerXslTemplateForDesigner
DROP PROCEDURE IF EXISTS `cloneEInvoiceSellerXslTemplateForDesigner`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `cloneEInvoiceSellerXslTemplateForDesigner`(
  IN p_SOURCE_XSL_ID BIGINT UNSIGNED,
  IN p_COMPANY_CD VARCHAR(20),
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_NEW_XSL_ID BIGINT UNSIGNED DEFAULT 0;

  IF NOT EXISTS (
    SELECT 1 FROM einvoice_seller_xsl_template
    WHERE XSL_ID = p_SOURCE_XSL_ID AND COMPANY_CD = p_COMPANY_CD AND ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Source invoice template not found';
  END IF;

  INSERT INTO einvoice_seller_xsl_template (
    SELLER_ID, COMPANY_CD, TEMPLATE_CD, TEMPLATE_NM, THDON, KHMSHDON, KHHDON, FROM_SHDON, TO_SHDON,
    USE_MULTI_TAX_RATE, VERSION_NO, SOURCE_XSL_ID, SOURCE_TYPE, TEMPLATE_STATUS, IS_DEFAULT, IS_ACTIVE, ISDEL,
    CREATE_BY, CREATE_AT, UPDATE_BY, UPDATE_AT
  )
  SELECT SELLER_ID, COMPANY_CD, TEMPLATE_CD, CONCAT(TEMPLATE_NM, ' - Bản thiết kế'), THDON, KHMSHDON, KHHDON, FROM_SHDON, TO_SHDON,
         USE_MULTI_TAX_RATE, 1, XSL_ID, 'USER', 'DRAFT', 0, 1, 0, p_USERID, NOW(), p_USERID, NOW()
  FROM einvoice_seller_xsl_template
  WHERE XSL_ID = p_SOURCE_XSL_ID AND COMPANY_CD = p_COMPANY_CD AND ISDEL = 0;
  SET v_NEW_XSL_ID = LAST_INSERT_ID();

  INSERT INTO einvoice_seller_xsl_template_content (XSL_ID, XSL_CONTENT, UPDATE_BY, UPDATE_AT)
  SELECT v_NEW_XSL_ID, XSL_CONTENT, p_USERID, NOW()
  FROM einvoice_seller_xsl_template_content WHERE XSL_ID = p_SOURCE_XSL_ID;

  INSERT INTO einvoice_seller_xsl_template_design (
    XSL_ID, TYPE, XSL_CONTENT, DESIGN_JSON, LOGO_PATH, INVOICE_BACKGROUND_PATH, INVOICE_BORDER_PATH, BACKGROUND_PATH,
    CREATE_BY, CREATE_AT, UPDATE_BY, UPDATE_AT
  )
  SELECT v_NEW_XSL_ID, TYPE, XSL_CONTENT, DESIGN_JSON, LOGO_PATH, INVOICE_BACKGROUND_PATH, INVOICE_BORDER_PATH, BACKGROUND_PATH,
         p_USERID, NOW(), p_USERID, NOW()
  FROM einvoice_seller_xsl_template_design
  WHERE XSL_ID = p_SOURCE_XSL_ID AND TYPE IN (0, 1);

  SELECT XSL_ID, SELLER_ID, TEMPLATE_NM, SOURCE_TYPE, TEMPLATE_STATUS
  FROM einvoice_seller_xsl_template WHERE XSL_ID = v_NEW_XSL_ID;
END//
DELIMITER ;


