-- Dumping structure for procedure am_web_001.delchitdetail
DROP PROCEDURE IF EXISTS `delchitdetail`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `delchitdetail`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_INPUT_TYPE VARCHAR(20),
    IN p_CHITDETAIL_ID BIGINT,
    IN p_UPDATE_BY VARCHAR(50)
)
BEGIN
    UPDATE chitdetailinfo d
    INNER JOIN chitinfo h
        ON h.COMPANY_CD = d.COMPANY_CD
       AND h.CHIT_ID = d.CHIT_ID
    SET d.ISDEL = '1', d.UPDATE_BY = p_UPDATE_BY
    WHERE d.COMPANY_CD = p_COMPANY_CD
      AND d.CHITDETAIL_ID = p_CHITDETAIL_ID
      AND IFNULL(h.INPUT_TYPE, '') = IFNULL(p_INPUT_TYPE, '');

    DELETE FROM chitdetaildescriptioninfo WHERE COMPANY_CD = p_COMPANY_CD AND CHITDETAIL_ID = p_CHITDETAIL_ID;
    DELETE FROM chitdetailinfo_ext WHERE COMPANY_CD = p_COMPANY_CD AND CHITDETAIL_ID = p_CHITDETAIL_ID;
    DELETE FROM chitdetailinfo_vat WHERE COMPANY_CD = p_COMPANY_CD AND CHITDETAIL_ID = p_CHITDETAIL_ID;

    SELECT p_CHITDETAIL_ID AS CHITDETAIL_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.delchitinfo
DROP PROCEDURE IF EXISTS `delchitinfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `delchitinfo`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_INPUT_TYPE VARCHAR(20),
    IN p_CHIT_ID BIGINT,
    IN p_UPDATE_BY VARCHAR(50)
)
BEGIN
    DECLARE v_CHIT_CD VARCHAR(30) DEFAULT NULL;
    DECLARE v_OTHER_CHIT_ID BIGINT DEFAULT NULL;

    SELECT CHIT_CD INTO v_CHIT_CD
    FROM chitinfo
    WHERE COMPANY_CD = p_COMPANY_CD
      AND CHIT_ID = p_CHIT_ID
      AND IFNULL(INPUT_TYPE, '') = IFNULL(p_INPUT_TYPE, '')
      AND IFNULL(ISDEL, '') != '1'
    FOR UPDATE;

    IF v_CHIT_CD IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Voucher not found or already deleted';
    END IF;

    IF TRIM(v_CHIT_CD) != '' AND p_INPUT_TYPE IN ('AP', 'AR') THEN
        SELECT CHIT_ID INTO v_OTHER_CHIT_ID
        FROM chitinfo
        WHERE COMPANY_CD = p_COMPANY_CD
          AND INPUT_TYPE = p_INPUT_TYPE
          AND CHIT_CD = v_CHIT_CD
          AND CHIT_ID != p_CHIT_ID
          AND IFNULL(ISDEL, '') != '1'
        LIMIT 1 FOR UPDATE;

        IF v_OTHER_CHIT_ID IS NOT NULL THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Duplicate active voucher code; cannot safely unlink invoices';
        END IF;

        IF p_INPUT_TYPE = 'AP' THEN
            UPDATE buy_list_einvoice
            SET AUTO_CHIT_CD = ''
            WHERE COMPANY_CD = p_COMPANY_CD AND AUTO_CHIT_CD = v_CHIT_CD;
        ELSEIF p_INPUT_TYPE = 'AR' THEN
            UPDATE sell_list_einvoice
            SET AUTO_CHIT_CD = ''
            WHERE COMPANY_CD = p_COMPANY_CD AND AUTO_CHIT_CD = v_CHIT_CD;
        END IF;
    END IF;

    UPDATE chitinfo
    SET ISDEL = '1', UPDATE_BY = p_UPDATE_BY
    WHERE COMPANY_CD = p_COMPANY_CD
      AND CHIT_ID = p_CHIT_ID
      AND IFNULL(INPUT_TYPE, '') = IFNULL(p_INPUT_TYPE, '');

    UPDATE chitdetailinfo d
    INNER JOIN chitinfo h
        ON h.COMPANY_CD = d.COMPANY_CD
       AND h.CHIT_ID = d.CHIT_ID
    SET d.ISDEL = '1', d.UPDATE_BY = p_UPDATE_BY
    WHERE d.COMPANY_CD = p_COMPANY_CD
      AND d.CHIT_ID = p_CHIT_ID
      AND IFNULL(h.INPUT_TYPE, '') = IFNULL(p_INPUT_TYPE, '');

    DELETE FROM chitdescriptioninfo WHERE COMPANY_CD = p_COMPANY_CD AND CHIT_ID = p_CHIT_ID;
    DELETE FROM chitinfo_ext WHERE COMPANY_CD = p_COMPANY_CD AND CHIT_ID = p_CHIT_ID;

    DELETE detail_desc
    FROM chitdetaildescriptioninfo detail_desc
    INNER JOIN chitdetailinfo detail
        ON detail.CHITDETAIL_ID = detail_desc.CHITDETAIL_ID
       AND detail.COMPANY_CD = detail_desc.COMPANY_CD
    INNER JOIN chitinfo h
        ON h.COMPANY_CD = detail.COMPANY_CD
       AND h.CHIT_ID = detail.CHIT_ID
    WHERE detail.COMPANY_CD = p_COMPANY_CD
      AND detail.CHIT_ID = p_CHIT_ID
      AND IFNULL(h.INPUT_TYPE, '') = IFNULL(p_INPUT_TYPE, '');

    DELETE detail_ext
    FROM chitdetailinfo_ext detail_ext
    INNER JOIN chitdetailinfo detail
        ON detail.CHITDETAIL_ID = detail_ext.CHITDETAIL_ID
       AND detail.COMPANY_CD = detail_ext.COMPANY_CD
    INNER JOIN chitinfo h
        ON h.COMPANY_CD = detail.COMPANY_CD
       AND h.CHIT_ID = detail.CHIT_ID
    WHERE detail.COMPANY_CD = p_COMPANY_CD
      AND detail.CHIT_ID = p_CHIT_ID
      AND IFNULL(h.INPUT_TYPE, '') = IFNULL(p_INPUT_TYPE, '');

    DELETE detail_vat
    FROM chitdetailinfo_vat detail_vat
    INNER JOIN chitdetailinfo detail
        ON detail.CHITDETAIL_ID = detail_vat.CHITDETAIL_ID
       AND detail.COMPANY_CD = detail_vat.COMPANY_CD
    INNER JOIN chitinfo h
        ON h.COMPANY_CD = detail.COMPANY_CD
       AND h.CHIT_ID = detail.CHIT_ID
    WHERE detail.COMPANY_CD = p_COMPANY_CD
      AND detail.CHIT_ID = p_CHIT_ID
      AND IFNULL(h.INPUT_TYPE, '') = IFNULL(p_INPUT_TYPE, '');

    SELECT p_CHIT_ID AS CHIT_ID;
END//
DELIMITER ;


