-- Dumping structure for procedure am_web_001.delEInvoice
DROP PROCEDURE IF EXISTS `delEInvoice`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `delEInvoice`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_INVOICE_ID BIGINT,
  IN p_USERID VARCHAR(50)
)
BEGIN
  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF p_INVOICE_ID IS NULL OR p_INVOICE_ID <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVOICE_ID is required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM einvoice_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND INVOICE_ID = p_INVOICE_ID
      AND ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice not found';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM einvoice_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND INVOICE_ID = p_INVOICE_ID
      AND ISDEL = 0
      AND IFNULL(IS_SIGNED, 0) = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice is already signed';
  END IF;

  UPDATE einvoice_detail
  SET ISDEL = 1,
      UPDATE_BY = p_USERID,
      UPDATE_AT = NOW()
  WHERE COMPANY_CD = p_COMPANY_CD
    AND INVOICE_ID = p_INVOICE_ID
    AND ISDEL = 0;

  DELETE FROM einvoice_related_info
  WHERE COMPANY_CD = p_COMPANY_CD
    AND INVOICE_ID = p_INVOICE_ID;

  DELETE FROM einvoice_detail_special_info
  WHERE COMPANY_CD = p_COMPANY_CD
    AND INVOICE_ID = p_INVOICE_ID;

  UPDATE einvoice_info
  SET ISDEL = 1,
      UPDATE_BY = p_USERID,
      UPDATE_AT = NOW()
  WHERE COMPANY_CD = p_COMPANY_CD
    AND INVOICE_ID = p_INVOICE_ID
    AND ISDEL = 0;
END//
DELIMITER ;


