-- Dumping structure for procedure am_web_001.delEInvoiceBkeByInvoice
DROP PROCEDURE IF EXISTS `delEInvoiceBkeByInvoice`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `delEInvoiceBkeByInvoice`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_INVOICE_ID BIGINT,
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_BKE_ID BIGINT DEFAULT 0;
  DECLARE v_IS_SIGNED TINYINT DEFAULT 0;
  DECLARE v_INVOICE_SIGNED TINYINT DEFAULT 0;

  SELECT IFNULL(IS_SIGNED, 0) INTO v_INVOICE_SIGNED
  FROM einvoice_info
  WHERE COMPANY_CD = p_COMPANY_CD
    AND INVOICE_ID = p_INVOICE_ID
    AND ISDEL = 0
  LIMIT 1;

  IF IFNULL(v_INVOICE_SIGNED, 0) = 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Signed e-invoice bảng kê cannot be deleted';
  END IF;

  SELECT BKE_ID, IFNULL(IS_SIGNED, 0)
    INTO v_BKE_ID, v_IS_SIGNED
  FROM einvoice_bke_info
  WHERE COMPANY_CD = p_COMPANY_CD
    AND INVOICE_ID = p_INVOICE_ID
    AND ISDEL = 0
  LIMIT 1;

  IF IFNULL(v_IS_SIGNED, 0) = 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Signed bảng kê cannot be deleted';
  END IF;

  IF v_BKE_ID IS NOT NULL AND v_BKE_ID > 0 THEN
    UPDATE einvoice_bke_reason SET ISDEL = 1 WHERE BKE_ID = v_BKE_ID;
    UPDATE einvoice_bke_detail SET ISDEL = 1 WHERE BKE_ID = v_BKE_ID;
    UPDATE einvoice_bke_info
    SET ISDEL = 1,
        UPDATE_BY = p_USERID,
        UPDATE_AT = NOW()
    WHERE BKE_ID = v_BKE_ID;
  END IF;
END//
DELIMITER ;


