-- Dumping structure for procedure am_web_001.delPitXslTemplate
DROP PROCEDURE IF EXISTS `delPitXslTemplate`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `delPitXslTemplate`(IN p_company VARCHAR(20), IN p_xsl_id BIGINT, IN p_user VARCHAR(50))
BEGIN
  DECLARE v_default TINYINT DEFAULT 0;
  DECLARE v_used INT DEFAULT 0;
  SELECT IS_DEFAULT INTO v_default FROM pit_xsl_template
   WHERE COMPANY_CD = p_company AND XSL_ID = p_xsl_id AND ISDEL = 0 LIMIT 1;
  IF v_default IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PIT XSL template not found';
  END IF;
  IF IFNULL(v_default,0) = 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cannot delete default PIT XSL template';
  END IF;
  SELECT COUNT(*) INTO v_used FROM pit_ctu_info
   WHERE COMPANY_CD = p_company AND XSL_ID = p_xsl_id AND ISDEL = 0;
  IF IFNULL(v_used,0) > 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cannot delete template used by documents';
  END IF;
  UPDATE pit_xsl_template
     SET ISDEL = 1, IS_ACTIVE = 0, IS_DEFAULT = 0, UPDATE_BY = p_user, UPDATE_AT = NOW()
   WHERE COMPANY_CD = p_company AND XSL_ID = p_xsl_id AND ISDEL = 0;
  IF ROW_COUNT() <> 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PIT XSL template not found';
  END IF;
END//
DELIMITER ;


