-- Dumping structure for procedure am_web_001.exists_customer_cd
DROP PROCEDURE IF EXISTS `exists_customer_cd`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `exists_customer_cd`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CUSTOMER_CD VARCHAR(20)
)
BEGIN
    SELECT COUNT(*) AS CNT
    FROM customer_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND CUSTOMER_CD = p_CUSTOMER_CD
      AND IFNULL(ISDEL, '0') <> '1';
END//
DELIMITER ;


