	IF($FCType != "") THEN
		SET @sPosition = POSITION("|" IN $FCType);
		IF(@sPosition > 0) THEN
			SET @DCWayCode = SUBSTR($FCType,1,@sPosition-1);
			SET $FCType = SUBSTR($FCType,@sPosition+1,3);	
			SET @sWhereAmount = " AND PAYAMOUNT > 0";	
			IF(@DCWayCode = 1) THEN
				SET @sWhereFcType = CONCAT(" AND  IFNULL(FC_TYPE,'') = '",$FCType,"' ");	
				SET @sWhereAmount = " AND PAYAMOUNT_FC > 0 ";							
			ELSE IF(@DCWayCode = 2) THEN
				SET @sWhereFcType = CONCAT("  AND (IFNULL(FC_TYPE,'') = '' OR IFNULL(FC_TYPE,'') = '",$FCType,"') ");
				SET @sWhereAmount = " AND (PAYAMOUNT > 0 OR PAYAMOUNT_FC > 0) ";		
			END IF;
			END IF;
		END IF;
	END IF;
	-- Accept ALL or a comma-separated list of numeric CUSTOMER_ID values.
	IF $customerIDs IS NULL OR TRIM($customerIDs) = '' THEN
		SET $customerIDs = 'ALL';
	END IF;
	SET $customerIDs = TRIM($customerIDs);
	IF UPPER($customerIDs) = 'ALL' THEN SET $customerIDs = 'ALL'; END IF;
	IF UPPER($customerIDs) <> 'ALL' AND
	   $customerIDs NOT REGEXP '^[0-9]+(,[0-9]+)*$' THEN
		SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid customer IDs';
	END IF;
	
IF($sType='1') THEN

/*Payment*/
SET @V_SQL = CONCAT("
		SELECT 
				CUS1.CUSTOMER_ID AS CUSTOMER_ID,
				IFNULL(CUS1.CUSTOMER_NM,'') AS CUSTOMER_NM_VIET,
				IFNULL(CUS1.CUSTOMER_NM_EN,'') AS CUSTOMER_NM_ENG,
				IFNULL(CUS1.CUSTOMER_NM_KOR,'') AS CUSTOMER_NM_KOR,
				IFNULL(CUS1.CUSTOMER_NM_CN,'') AS CUSTOMER_NM_CHINA,
				CHIT_ID_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN -1 ELSE CHIT_TYPE_PAY END CHIT_TYPE_PAY,
				'' AS TYPE_CHIT_PAY_TEXT,
				CHIT_YMD_PAY,	
				CHIT_NO_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN 'Số dư đầu kỳ' ELSE DESCRIPTION_VIET_PAY END AS DESCRIPTION_VIET_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN 'Openning balance' ELSE DESCRIPTION_ENG_PAY END AS DESCRIPTION_ENG_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN '기초잔액' ELSE DESCRIPTION_KOR_PAY END AS DESCRIPTION_KOR_PAY,
			   CASE WHEN CHIT_ID_PAY < 0 THEN '期初余额' ELSE DESCRIPTION_CHINA_PAY END AS DESCRIPTION_CHINA_PAY,
			   
				CHIT_ID_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN -1 ELSE CHIT_TYPE_DEBT END CHIT_TYPE_DEBT,
				'' AS TYPE_CHIT_DEBT_TEXT,
				CHIT_YMD_DEBT,
				CHIT_NO_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN 'Số dư đầu kỳ' ELSE DESCRIPTION_VIET_DEBT END AS DESCRIPTION_VIET_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN 'Openning balance' ELSE DESCRIPTION_ENG_DEBT END AS DESCRIPTION_ENG_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN '기초잔액' ELSE DESCRIPTION_KOR_DEBT END AS DESCRIPTION_KOR_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN '期初余额' ELSE DESCRIPTION_CHINA_DEBT END AS DESCRIPTION_CHINA_DEBT,
				
				PAYAMOUNT,
				PAYAMOUNT_FC
		FROM (
		SELECT 
				P.PAY_CHIT_ID AS CHIT_ID_PAY,
				C.CHIT_TYPE AS CHIT_TYPE_PAY,
				C.CHIT_NO AS CHIT_NO_PAY,
				CAST(C.CHIT_YMD AS DATETIME) AS CHIT_YMD_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'VIET' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_VIET_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'ENG' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_ENG_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_KOR_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA_PAY,
				
				P.DEBIT_CHIT_ID AS CHIT_ID_DEBT,
				D.CHIT_TYPE AS CHIT_TYPE_DEBT,
				D.CHIT_NO AS CHIT_NO_DEBT,
				CAST(D.CHIT_YMD AS DATETIME) AS CHIT_YMD_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'VIET' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_VIET_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'ENG' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_ENG_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_KOR_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA_DEBT,
				
				IFNULL(SUM(P.PAYAMOUNT),0.0)as PAYAMOUNT,
				IFNULL(SUM(P.PAYAMOUNT_FC),0.0) as PAYAMOUNT_FC,
				P.CUSTOMER_ID
			FROM chit_payment P 
			LEFT JOIN chitinfo C ON P.PAY_CHIT_ID = C.CHIT_ID AND IFNULL(C.ISDEL,'') != '1' AND C.COMPANY_CD = ",QUOTE($COMPANY_CD),"
			LEFT JOIN chitinfo D ON P.DEBIT_CHIT_ID = D.CHIT_ID AND IFNULL(D.ISDEL,'') != '1' AND D.COMPANY_CD = ",QUOTE($COMPANY_CD),"
			WHERE 
				P.IS_DEBT_CLEARING !=1
				AND IFNULL(P.ISDEL,'') != '1'
				AND (
						(	
							D.CHIT_YMD >= ",$startYMD," AND D.CHIT_YMD <= ",$endYMD," AND 
							EXISTS(SELECT * FROM chitdetailinfo E WHERE C.CHIT_ID = E.CHIT_ID AND IFNULL(E.ISDEL,'') != '1' 
									AND ('",$customerIDs,"' = 'ALL' OR FIND_IN_SET(CAST(IF(C.CHIT_TYPE = 5, E.CUSTOMER_OWN_ID, E.CUSTOMER_ID) AS CHAR), '",$customerIDs,"') > 0)
									/*AND (E.DEBIT LIKE '",$sAcc_CD,"%'  OR (E.CREDIT LIKE '",$sAcc_CD,"%' AND E.AMOUNT < 0) )*/ ",@sWhereFcType,"
							) AND
							EXISTS(SELECT * FROM chitdetailinfo F WHERE D.CHIT_ID = F.CHIT_ID AND IFNULL(F.ISDEL,'') != '1' 
									AND ('",$customerIDs,"' = 'ALL' OR FIND_IN_SET(CAST(IF(D.CHIT_TYPE = 5, F.CUSTOMER_OWN_ID, F.CUSTOMER_ID) AS CHAR), '",$customerIDs,"') > 0)
									/*AND F.CREDIT LIKE '",$sAcc_CD,"%'*/ ",@sWhereFcType,"    
							)
						)
						OR P.PAY_CHIT_ID = -331 OR P.DEBIT_CHIT_ID = -331
				)
				AND P.COMPANY_CD = ",QUOTE($COMPANY_CD),"
			GROUP BY 
				P.PAY_CHIT_ID,
				P.DEBIT_CHIT_ID,
				P.CUSTOMER_ID
			) A 
			LEFT JOIN customer_info CUS1 ON A.CUSTOMER_ID = CUS1.CUSTOMER_ID AND IFNULL(CUS1.ISDEL,'0') != '1' AND CUS1.COMPANY_CD = ",QUOTE($COMPANY_CD),"
			WHERE 
				CUS1.CUSTOMER_ID IS NOT NULL
				AND (IFNULL(CHIT_NO_PAY,'') != '' OR CHIT_ID_PAY < 0) 
				AND (IFNULL(CHIT_NO_DEBT,'') != '' OR CHIT_ID_DEBT < 0)
				",@sWhereAmount,"
			ORDER BY CUS1.CUSTOMER_ID,CHIT_YMD_PAY,CHIT_NO_PAY,CHIT_YMD_DEBT,CHIT_NO_DEBT
			");
				
		PREPARE STMT FROM @V_SQL;
		EXECUTE STMT;
		DEALLOCATE PREPARE STMT;

	ELSE
	
/*Collect*/	
		SET @V_SQL = CONCAT("
			SELECT 
				CUS1.CUSTOMER_ID AS CUSTOMER_ID,
				IFNULL(CUS1.CUSTOMER_NM,'') AS CUSTOMER_NM_VIET,
				IFNULL(CUS1.CUSTOMER_NM_EN,'') AS CUSTOMER_NM_ENG,
				IFNULL(CUS1.CUSTOMER_NM_KOR,'') AS CUSTOMER_NM_KOR,
				IFNULL(CUS1.CUSTOMER_NM_CN,'') AS CUSTOMER_NM_CHINA,
				
				CHIT_ID_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN -1 ELSE CHIT_TYPE_PAY END CHIT_TYPE_PAY,
				'' AS TYPE_CHIT_PAY_TEXT,
				CHIT_YMD_PAY,	
				CHIT_NO_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN 'Số dư đầu kỳ' ELSE DESCRIPTION_VIET_PAY END AS DESCRIPTION_VIET_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN 'Openning balance' ELSE DESCRIPTION_ENG_PAY END AS DESCRIPTION_ENG_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN '기초잔액' ELSE DESCRIPTION_KOR_PAY END AS DESCRIPTION_KOR_PAY,
			   CASE WHEN CHIT_ID_PAY < 0 THEN '期初余额' ELSE DESCRIPTION_CHINA_PAY END AS DESCRIPTION_CHINA_PAY,
			
				CHIT_ID_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN -1 ELSE CHIT_TYPE_DEBT END CHIT_TYPE_DEBT,
				'' AS TYPE_CHIT_DEBT_TEXT,
				CHIT_YMD_DEBT,
				CHIT_NO_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN 'Số dư đầu kỳ' ELSE DESCRIPTION_VIET_DEBT END AS DESCRIPTION_VIET_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN 'Openning balance' ELSE DESCRIPTION_ENG_DEBT END AS DESCRIPTION_ENG_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN '기초잔액' ELSE DESCRIPTION_KOR_DEBT END AS DESCRIPTION_KOR_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN '期初余额' ELSE DESCRIPTION_CHINA_DEBT END AS DESCRIPTION_CHINA_DEBT,
				
				PAYAMOUNT,
				PAYAMOUNT_FC
		FROM (
		SELECT 
				P.COLLECT_CHIT_ID AS CHIT_ID_PAY,
				C.CHIT_TYPE AS CHIT_TYPE_PAY,
				C.CHIT_NO AS CHIT_NO_PAY,
				CAST(C.CHIT_YMD AS DATETIME) AS CHIT_YMD_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'VIET' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_VIET_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'ENG' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_ENG_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_KOR_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA_PAY,
				
				P.RECEIVABLES_CHIT_ID AS CHIT_ID_DEBT,
				D.CHIT_TYPE AS CHIT_TYPE_DEBT,
				D.CHIT_NO AS CHIT_NO_DEBT,
				CAST(D.CHIT_YMD AS DATETIME) AS CHIT_YMD_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'VIET' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_VIET_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'ENG' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_ENG_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_KOR_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA_DEBT,
				
				IFNULL(SUM(P.COLLECTAMOUNT),0.0)as PAYAMOUNT,
				IFNULL(SUM(P.COLLECTAMOUNT_FC),0.0) as PAYAMOUNT_FC,
				P.CUSTOMER_ID
			FROM chit_collect P 
			LEFT JOIN chitinfo C ON P.COLLECT_CHIT_ID = C.CHIT_ID AND IFNULL(C.ISDEL,'') != '1' AND C.COMPANY_CD = ",QUOTE($COMPANY_CD),"
			LEFT JOIN chitinfo D ON P.RECEIVABLES_CHIT_ID = D.CHIT_ID AND IFNULL(D.ISDEL,'') != '1' AND D.COMPANY_CD = ",QUOTE($COMPANY_CD),"
			WHERE 
				P.IS_DEBT_CLEARING !=1
				AND IFNULL(P.ISDEL,'') != '1' 
				AND (
						(
						D.CHIT_YMD >= ",$startYMD," AND D.CHIT_YMD <= ",$endYMD," AND 
						EXISTS(SELECT * FROM chitdetailinfo E WHERE C.CHIT_ID = E.CHIT_ID AND IFNULL(E.ISDEL,'') != '1' 
								AND ('",$customerIDs,"' = 'ALL' OR FIND_IN_SET(CAST(IF(C.CHIT_TYPE = 5, E.CUSTOMER_OWN_ID, E.CUSTOMER_ID) AS CHAR), '",$customerIDs,"') > 0)
								/*AND (E.CREDIT LIKE '",$sAcc_CD,"%'  OR (E.DEBIT LIKE '",$sAcc_CD,"%' AND E.AMOUNT < 0) )*/ ",@sWhereFcType," 
						) AND
						EXISTS(SELECT * FROM chitdetailinfo F WHERE D.CHIT_ID = F.CHIT_ID AND IFNULL(F.ISDEL,'') != '1' 
								AND ('",$customerIDs,"' = 'ALL' OR FIND_IN_SET(CAST(IF(D.CHIT_TYPE = 5, F.CUSTOMER_OWN_ID, F.CUSTOMER_ID) AS CHAR), '",$customerIDs,"') > 0)
								/*AND F.DEBIT LIKE '",$sAcc_CD,"%'*/ ",@sWhereFcType,"    
						)
					)
					OR P.COLLECT_CHIT_ID = -131 OR P.RECEIVABLES_CHIT_ID = -131
				)
				AND P.COMPANY_CD = ",QUOTE($COMPANY_CD),"
			GROUP BY 
				P.COLLECT_CHIT_ID,
				P.RECEIVABLES_CHIT_ID,
				P.CUSTOMER_ID
			) A
			LEFT JOIN customer_info CUS1 ON A.CUSTOMER_ID = CUS1.CUSTOMER_ID AND IFNULL(CUS1.ISDEL,'0') != '1' AND CUS1.COMPANY_CD = ",QUOTE($COMPANY_CD),"
			WHERE 
				CUS1.CUSTOMER_ID IS NOT NULL
				AND (IFNULL(CHIT_NO_PAY,'') != '' OR CHIT_ID_PAY < 0) 
				AND (IFNULL(CHIT_NO_DEBT,'') != '' OR CHIT_ID_DEBT < 0)
				",@sWhereAmount,"
			ORDER BY CUS1.CUSTOMER_ID,CHIT_YMD_PAY,CHIT_NO_PAY,CHIT_YMD_DEBT,CHIT_NO_DEBT
			");
				
			PREPARE STMT FROM @V_SQL;
			EXECUTE STMT;
			DEALLOCATE PREPARE STMT;

	END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getChitDebt_FromToDate
DROP PROCEDURE IF EXISTS `getChitDebt_FromToDate`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getChitDebt_FromToDate`(IN `$sType` char(1), IN `$fromYMD` varchar(8), IN `$toYMD` varchar(8), IN `$customerIDs` varchar(5000), IN `$FCType` varchar(20), IN `$sAcc_CD` varchar(20), IN `$COMPANY_CD` varchar(20))
BEGIN
	
	SET @sWhereFcType = "", @sHaving = " HAVING REMAINAMOUNT > 0 ";
	IF($FCType != "") THEN
		SET @sPosition = POSITION("|" IN $FCType);
		IF(@sPosition > 0) THEN
			SET @DCWayCode = SUBSTR($FCType,1,@sPosition-1);
			SET $FCType = SUBSTR($FCType,@sPosition+1,3);
			SET @sHaving = CONCAT(" HAVING REMAINAMOUNT > 0 ");	
			IF(@DCWayCode = 1) THEN
				SET @sHaving = CONCAT(" HAVING REMAINAMOUNT_FC > 0  ");
				SET @sWhereFcType = CONCAT(" AND IFNULL(A.FC_TYPE,'') = '",$FCType,"' ");							
			ELSE IF(@DCWayCode = 2) THEN
				SET @sHaving = CONCAT(" HAVING (REMAINAMOUNT > 0 OR REMAINAMOUNT_FC > 0)  ");
				SET @sWhereFcType = CONCAT(" AND (IFNULL(A.FC_TYPE,'') = '' OR IFNULL(A.FC_TYPE,'') = '",$FCType,"') ");	
			END IF;
			END IF;
		END IF;
	END IF;

	SET @FC = CASE WHEN $FCType IN ('USD','EUR','JPY','KRW','CNY') THEN $FCType ELSE 'USD' END;
	IF($FCType = 'VND') THEN 
		SET @FC = 'USD';
	END IF;
	-- Accept ALL or a comma-separated list of numeric CUSTOMER_ID values.
	IF $customerIDs IS NULL OR TRIM($customerIDs) = '' THEN
		SET $customerIDs = 'ALL';
	END IF;
	SET $customerIDs = TRIM($customerIDs);
	IF UPPER($customerIDs) = 'ALL' THEN SET $customerIDs = 'ALL'; END IF;
	IF UPPER($customerIDs) <> 'ALL' AND
	   $customerIDs NOT REGEXP '^[0-9]+(,[0-9]+)*$' THEN
		SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid customer IDs';
	END IF;
	
	SET @QueryYMD = CONCAT(" AND A.chit_ymd <= ",$toYMD," ");
	IF($fromYMD != '') THEN 
		SET @QueryYMD = CONCAT(@QueryYMD," AND A.chit_ymd >= ",$fromYMD," ");		
	END IF;
	
IF($sType='1') THEN


SET @V_SQL = CONCAT("
	SELECT 
			CUS1.CUSTOMER_ID AS CUSTOMER_ID,
			IFNULL(CUS1.CUSTOMER_NM,'') AS CUSTOMER_NM_VIET,
			IFNULL(CUS1.CUSTOMER_NM_EN,'') AS CUSTOMER_NM_ENG,
			IFNULL(CUS1.CUSTOMER_NM_KOR,'') AS CUSTOMER_NM_KOR,
			IFNULL(CUS1.CUSTOMER_NM_CN,'') AS CUSTOMER_NM_CHINA,
			PAY_ID,
			CHIT_ID,
			CHIT_TYPE,
			CHIT_NO,
			CHIT_YMD,
			VAT_CHIT_NO,
			VAT_YMD,
			DESCRIPTION_VIET,
			DESCRIPTION_ENG,
			DESCRIPTION_KOR,
			DESCRIPTION_CHINA,
			TIME_FOR_PAYMENT,
			AMOUNT,
			FC_AMOUNT,
			REMAINAMOUNT,
			REMAINAMOUNT_FC,
			PAYAMOUNT,
			PAYAMOUNT_FC
	FROM (			
		SELECT 
				COALESCE(MIN(P.CHITPAYMENT_ID),0) AS PAY_ID,
				-331 AS CHIT_ID,
				'-1' AS CHIT_TYPE,
				'' AS CHIT_NO,
				'' AS CHIT_YMD,
				A.CUSTOMER_ID,
				'' AS VAT_CHIT_NO,
				'' AS VAT_YMD,
				'Số dư đầu kỳ' AS DESCRIPTION_VIET,
				'Openning balance' AS DESCRIPTION_ENG, 	
				'기초잔액' AS DESCRIPTION_KOR,
				'期初余额' AS DESCRIPTION_CHINA,
				'' AS TIME_FOR_PAYMENT,
				AMOUNT,
				FC_AMOUNT,
				IFNULL(A.AMOUNT - IFNULL(SUM(P.PAYAMOUNT),0.0),0.0) as REMAINAMOUNT,
				IFNULL(A.FC_AMOUNT - IFNULL(SUM(P.PAYAMOUNT_FC),0.0),0.0) as REMAINAMOUNT_FC,
				0.0 AS PAYAMOUNT,
				0.0 AS PAYAMOUNT_FC
			FROM (
				SELECT 
					A.CUSTOMER_ID,
					IFNULL(SUM(A.DEBIT),0.0) AS AMOUNT,
					IFNULL(SUM(A.DEBIT_",@FC,"),0.0) AS FC_AMOUNT
					FROM before_states_customer A
					WHERE A.ACC_CD like '",$sAcc_CD,"%' 
				    AND ('",$customerIDs,"' = 'ALL' OR FIND_IN_SET(CAST(A.CUSTOMER_ID AS CHAR), '",$customerIDs,"') > 0)
					AND IFNULL(A.ISDEL,'') !=1
					AND A.COMPANY_CD = ",QUOTE($COMPANY_CD),"
					GROUP BY A.CUSTOMER_ID
				) A
			LEFT JOIN chit_payment P ON ifnull(P.ISDEL,'') != '1' AND P.PAY_CHIT_ID = -331  AND A.CUSTOMER_ID = P.CUSTOMER_ID AND P.COMPANY_CD = ",QUOTE($COMPANY_CD)," 
			GROUP BY A.CUSTOMER_ID,AMOUNT,FC_AMOUNT
			",@sHaving," 

		UNION ALL
		SELECT 
			COALESCE(MIN(C.CHITPAYMENT_ID),0) AS PAY_ID,
			CHIT_ID,
			CHIT_TYPE,
			CHIT_NO,
			CHIT_YMD,
			F.CUSTOMER_ID,
			VAT_CHIT_NO,
			VAT_YMD,
			DESCRIPTION_VIET,
			DESCRIPTION_ENG,
			DESCRIPTION_KOR,
			DESCRIPTION_CHINA,
			TIME_FOR_PAYMENT,
			AMOUNT,
			FC_AMOUNT,
			AMOUNT -	IFNULL(SUM(C.PAYAMOUNT),0.0) as REMAINAMOUNT,
			FC_AMOUNT - IFNULL(SUM(C.PAYAMOUNT_FC),0.0) as REMAINAMOUNT_FC,
			0.0 AS PAYAMOUNT,
			0.0 AS PAYAMOUNT_FC
	FROM(
		SELECT 
					B.CHIT_ID,

					B.CHIT_TYPE,
					B.CHIT_NO,
					A.CHIT_YMD,
					IF(B.CHIT_TYPE = 5, IF(A.DEBIT LIKE '",$sAcc_CD,"%',A.CUSTOMER_ID, A.CUSTOMER_OWN_ID), A.CUSTOMER_ID) AS CUSTOMER_ID,
					IFNULL((SELECT C.VAT_CHIT_NO FROM chitdetailinfo C WHERE  IFNULL(C.ISDEL,'')!=1 AND IFNULL(C.VAT_CHIT_NO,'')!='' AND C.CHIT_ID = A.CHIT_ID AND C.COMPANY_CD = ",QUOTE($COMPANY_CD)," LIMIT 1),'') AS VAT_CHIT_NO,
					IFNULL((SELECT C.VAT_YMD FROM chitdetailinfo C WHERE  IFNULL(C.ISDEL,'')!=1 AND IFNULL(C.VAT_CHIT_NO,'')!='' AND C.CHIT_ID = A.CHIT_ID AND C.COMPANY_CD = ",QUOTE($COMPANY_CD)," LIMIT 1),'') AS VAT_YMD,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'VIET' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_VIET,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'ENG' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_ENG,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_KOR,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE($COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA,
					IFNULL(B.TIME_FOR_PAYMENT,'') AS TIME_FOR_PAYMENT,
					IFNULL(SUM(IF(A.CREDIT LIKE '",$sAcc_CD,"%' AND A.AMOUNT < 0,-A.AMOUNT,A.AMOUNT)),0.0) AS AMOUNT,
					IFNULL(SUM(IF(A.CREDIT LIKE '",$sAcc_CD,"%' AND A.FC_AMOUNT < 0,-A.FC_AMOUNT,A.FC_AMOUNT)),0.0) AS FC_AMOUNT
				FROM chitdetailinfo A
					LEFT JOIN chitinfo B ON B.CHIT_ID = A.CHIT_ID AND (B.ISDEL IS NULL OR B.ISDEL != '1') AND B.COMPANY_CD = ",QUOTE($COMPANY_CD),"
				WHERE  
