					AND ('",$customerIDs,"' = 'ALL' OR FIND_IN_SET(CAST(A.CUSTOMER_ID AS CHAR), '",$customerIDs,"') > 0)
					",@QueryYMD,"
					AND A.DEBIT LIKE '",$sAcc_CD,"%' 
					AND IFNULL(A.ISDEL,'0') != '1' 
					",@sWhereFcType," 
					AND A.COMPANY_CD = ",QUOTE($COMPANY_CD)," 
				GROUP BY 	
					B.CHIT_ID,
					B.CHIT_NO,
					A.CHIT_YMD,
					A.CUSTOMER_ID
	 ) F
	 	LEFT JOIN chit_collect C ON ifnull(C.ISDEL,'') != '1' AND C.RECEIVABLES_CHIT_ID = F.CHIT_ID AND F.CUSTOMER_ID = C.CUSTOMER_ID AND C.COMPANY_CD = ",QUOTE($COMPANY_CD)," 
	 	GROUP BY CHIT_ID,F.CUSTOMER_ID
	 ) A
	 LEFT JOIN customer_info CUS1 ON A.CUSTOMER_ID = CUS1.CUSTOMER_ID AND IFNULL(CUS1.ISDEL,'0') != '1' AND CUS1.COMPANY_CD = ",QUOTE($COMPANY_CD)," 
	 WHERE CUS1.CUSTOMER_ID IS NOT NULL
	 	",@sHaving,"
	 ORDER BY CUSTOMER_ID,CHIT_YMD, CHIT_NO,TIME_FOR_PAYMENT;
		");
		PREPARE STMT FROM @V_SQL;
		EXECUTE STMT;
		DEALLOCATE PREPARE STMT;
	
	END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getChitDetailCode
DROP PROCEDURE IF EXISTS `getChitDetailCode`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getChitDetailCode`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHITDETAIL_ID BIGINT
)
BEGIN
    SELECT COALESCE(TRIM(CHITDETAIL_CD), '')
    FROM chitdetailinfo
    WHERE COMPANY_CD = p_COMPANY_CD
      AND CHITDETAIL_ID = p_CHITDETAIL_ID
      AND IFNULL(ISDEL, '0') = '0'
    LIMIT 1;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getchitdetailids
DROP PROCEDURE IF EXISTS `getchitdetailids`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getchitdetailids`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHIT_ID BIGINT,
    IN p_INPUT_TYPE VARCHAR(20)
)
BEGIN
    SELECT detail.CHITDETAIL_ID
    FROM chitdetailinfo detail
    INNER JOIN chitinfo header
        ON header.COMPANY_CD = detail.COMPANY_CD
       AND header.CHIT_ID = detail.CHIT_ID
    WHERE detail.COMPANY_CD = p_COMPANY_CD
      AND detail.CHIT_ID = p_CHIT_ID
      AND IFNULL(detail.ISDEL, '0') = '0'
      AND IFNULL(header.ISDEL, '0') = '0'
      AND IFNULL(header.INPUT_TYPE, '') = p_INPUT_TYPE;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getchitdetail_batch
DROP PROCEDURE IF EXISTS `getchitdetail_batch`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getchitdetail_batch`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_INPUT_TYPE VARCHAR(20),
    IN p_CHIT_IDS TEXT
)
BEGIN
    DECLARE v_chit_ids TEXT;
    SET v_chit_ids = REPLACE(IFNULL(TRIM(p_CHIT_IDS), ''), '|', ',');

    SELECT
        d.CHITDETAIL_ID,
        d.COMPANY_CD,
        d.CHIT_ID,
        d.CHITDETAIL_CD,
        d.CHIT_YMD,
        NULL AS CHIT_VMD,
        d.DEBIT,
        debit_acc.ACCTITLE_NM_VIET AS DEBIT_NM_VIET,
        debit_acc.ACCTITLE_NM_ENG AS DEBIT_NM_ENG,
        debit_acc.ACCTITLE_NM_KOR AS DEBIT_NM_KOR,
        debit_acc.ACCTITLE_NM_CHINA AS DEBIT_NM_CHINA,
        d.CREDIT,
        credit_acc.ACCTITLE_NM_VIET AS CREDIT_NM_VIET,
        credit_acc.ACCTITLE_NM_ENG AS CREDIT_NM_ENG,
        credit_acc.ACCTITLE_NM_KOR AS CREDIT_NM_KOR,
        credit_acc.ACCTITLE_NM_CHINA AS CREDIT_NM_CHINA,
        d.AMOUNT,
        d.FC_AMOUNT,
        d.FC_TYPE,
        d.FC_RATE,
        d.FC_DATETIME,
        d.SORT,
        d.ISDEL,
        NULL AS CHITDETAIL_VAT_CD,
        ext.MG_CD,
        ext.MG_CD_2,
        ext.MR_CD,
        ext.MR_CD2,
        ext.BANK_ID,
        COALESCE(bank.BANK_CD, ext.BANK_CD) AS BANK_CD,
        ext.BANK_OWN_CD,
        COALESCE(customer.CUSTOMER_CD, ext.CUSTOMER_CD) AS CUSTOMER_CD,
        ext.CUSTOMER_ID,
        customer.CUSTOMER_NM_VIET,
        customer.CUSTOMER_NM_ENG,
        customer.CUSTOMER_NM_KOR,
        customer.CUSTOMER_NM_CHINA,
        ext.CUSTOMER_OWN_CD,
        ext.DEPARTMENT_ID,
        COALESCE(department.DEPARTMENT_CD, ext.DEPARTMENT_CD) AS DEPARTMENT_CD,
        ext.DEPARTMENT_CD_2,
        ext.HASINVENTORY,
        ext.INVENTORY_YMD,
        ext.ISPAY,
        ext.ISCOLLECT,
        NULL AS VAT_INPUT_CD,
        NULL AS PRODUCT_NM,
        NULL AS UNIT_NM,
        0 AS QUANTITY,
        0 AS UNIT_PRICE,
        0 AS PRODUCT_AMOUNT,
        NULL AS VAT_TYPE,
        0 AS PERCENT,
        0 AS PRODUCT_VAT_AMOUNT,
        NULL AS PRODUCT_NOTE,
        vat.VAT_SERIAL_NO,
        vat.VAT_CHIT_NO,
        vat.VAT_CHIT_NO_2,
        vat.VAT_AMOUNT,
        vat.VAT_TAXABLE_AMOUNT,
        vat.FC_VAT_AMOUNT AS FO_VAT_AMOUNT,
        vat.VAT_ISFREE,
        vat.VAT_INVOICE_CD,
        vat.VAT_INVOICE_NM,
        vat.VAT_INFO_TYPE,
        vat.VAT_COMPANY_ISSUE,
        vat.VAT_COMPANY_ISSUE_ADDRESS,
        vat.VAT_COMPANY_ISSUE_CD,
        vat.VAT_COMPANY_TAXCD,
        vat.VAT_PRODUCT_NM,
        vat.VAT_ETC,
        vat.VAT_YMD,
        vat.VAT_YMD_2,
        vat.VAT_INQUIRY_IN,
        vat.VAT_INQUIRY_CODE,
        vat.IS_NEXTVAT,
        NULL AS UNDEFINE,
        detail_desc_vi.DESCRIPTION AS DETAIL_DESCRIPTION_VIET,
        detail_desc_en.DESCRIPTION AS DETAIL_DESCRIPTION_ENG,
        detail_desc_ko.DESCRIPTION AS DETAIL_DESCRIPTION_KOR,
        d.CREATE_BY,
        d.CREATE_AT,
        d.UPDATE_BY,
        d.UPDATE_AT 
    FROM chitdetailinfo d
    INNER JOIN chitinfo h
        ON h.COMPANY_CD = d.COMPANY_CD
       AND h.CHIT_ID = d.CHIT_ID
    LEFT JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = d.COMPANY_CD
       AND ext.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN chitdetailinfo_vat vat
        ON vat.COMPANY_CD = d.COMPANY_CD
       AND vat.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND IFNULL(vat.ISDEL, '0') = '0'
    LEFT JOIN customer_info customer
        ON customer.COMPANY_CD = d.COMPANY_CD
       AND customer.CUSTOMER_ID = ext.CUSTOMER_ID
       AND IFNULL(customer.ISDEL, '0') = '0'
    LEFT JOIN bank_info bank
        ON bank.COMPANY_CD = d.COMPANY_CD
       AND bank.BANK_ID = ext.BANK_ID
       AND IFNULL(bank.ISDEL, '0') = '0'
    LEFT JOIN department_info department
        ON department.COMPANY_CD = d.COMPANY_CD
       AND department.DEPARTMENT_ID = ext.DEPARTMENT_ID
       AND IFNULL(department.ISDEL, '0') = '0'
    LEFT JOIN acclist_info debit_acc
        ON debit_acc.COMPANY_CD = d.COMPANY_CD
       AND debit_acc.ACC_CD = d.DEBIT
       AND IFNULL(debit_acc.ISDEL, '0') = '0'
    LEFT JOIN acclist_info credit_acc
        ON credit_acc.COMPANY_CD = d.COMPANY_CD
       AND credit_acc.ACC_CD = d.CREDIT
       AND IFNULL(credit_acc.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo detail_desc_vi
        ON detail_desc_vi.COMPANY_CD = d.COMPANY_CD
       AND detail_desc_vi.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND detail_desc_vi.LANG_TYPE = 'VIET'
       AND IFNULL(detail_desc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo detail_desc_en
        ON detail_desc_en.COMPANY_CD = d.COMPANY_CD
       AND detail_desc_en.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND detail_desc_en.LANG_TYPE = 'ENG'
       AND IFNULL(detail_desc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo detail_desc_ko
        ON detail_desc_ko.COMPANY_CD = d.COMPANY_CD
       AND detail_desc_ko.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND detail_desc_ko.LANG_TYPE = 'KOR'
       AND IFNULL(detail_desc_ko.ISDEL, '0') = '0'
    WHERE d.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(h.INPUT_TYPE, '') = IFNULL(p_INPUT_TYPE, '')
      AND IFNULL(h.ISDEL, '0') = '0'
      AND IFNULL(d.ISDEL, '0') = '0'
      AND v_chit_ids <> ''
      AND FIND_IN_SET( CAST(d.CHIT_ID AS CHAR CHARACTER SET utf8) COLLATE utf8_unicode_ci, v_chit_ids COLLATE utf8_unicode_ci ) > 0
    ORDER BY d.CHIT_ID, IFNULL(d.SORT, 0), d.CHITDETAIL_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getchitinfo
DROP PROCEDURE IF EXISTS `getchitinfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getchitinfo`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_INPUT_TYPE VARCHAR(20),
    IN p_CHIT_TYPE VARCHAR(20),
    IN p_CHIT_ID BIGINT,
    IN p_SEARCH_TEXT VARCHAR(255),
    IN p_FROM_YMD VARCHAR(8),
    IN p_TO_YMD VARCHAR(8),
    IN p_PAGE_NUMBER INT,
    IN p_PAGE_SIZE INT
)
BEGIN
    DECLARE v_page_number INT DEFAULT 1;
    DECLARE v_page_size INT DEFAULT 20;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_search_text VARCHAR(255);

    SET v_page_number = IFNULL(NULLIF(p_PAGE_NUMBER, 0), 1);
    SET v_page_size = IFNULL(NULLIF(p_PAGE_SIZE, 0), 20);
    SET v_offset = (v_page_number - 1) * v_page_size;
    SET v_search_text = NULLIF(TRIM(p_SEARCH_TEXT), '');

    SELECT
        h.CHIT_ID,
        h.COMPANY_CD,
        h.CHIT_CD,
        h.CHIT_NO,
        h.CHIT_YMD,
        h.CHIT_TYPE,
        h.AMOUNT,
        h.PAYER_INFO,
        h.ISDEL,
        h.CREATE_BY,
        h.CREATE_AT,
        h.UPDATE_BY,
        h.UPDATE_AT,
        ext.IS_LOCK,
        ext.ISEXCEL,
        ext.EMAIL_EPAY,
        ext.IS_CONFIRMED,
        ext.NOTE,
        CAST(NULLIF(ext.DAY_OF_PAYMENT, '') AS SIGNED) AS DAY_OF_PAYMENT,
        ext.TIME_FOR_PAYMENT,
        ext.IS_PAYMENT,
        h.CHIT_CD_COGS,
        desc_vi.DESCRIPTION AS DESCRIPTION_VIET,
        desc_en.DESCRIPTION AS DESCRIPTION_ENG,
        desc_ko.DESCRIPTION AS DESCRIPTION_KOR,
        (
            SELECT COUNT(*)
            FROM chitdetailinfo detail
            WHERE detail.COMPANY_CD = h.COMPANY_CD
              AND detail.CHIT_ID = h.CHIT_ID
              AND IFNULL(detail.ISDEL, '0') = '0'
        ) AS DETAIL_COUNT
    FROM chitinfo h
    LEFT JOIN chitinfo_ext ext
        ON ext.COMPANY_CD = h.COMPANY_CD
       AND ext.CHIT_ID = h.CHIT_ID
       AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo desc_vi
        ON desc_vi.COMPANY_CD = h.COMPANY_CD
       AND desc_vi.CHIT_ID = h.CHIT_ID
       AND desc_vi.LANG_TYPE = 'VIET'
       AND IFNULL(desc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo desc_en
        ON desc_en.COMPANY_CD = h.COMPANY_CD
       AND desc_en.CHIT_ID = h.CHIT_ID
       AND desc_en.LANG_TYPE = 'ENG'
       AND IFNULL(desc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo desc_ko
        ON desc_ko.COMPANY_CD = h.COMPANY_CD
       AND desc_ko.CHIT_ID = h.CHIT_ID
       AND desc_ko.LANG_TYPE = 'KOR'
       AND IFNULL(desc_ko.ISDEL, '0') = '0'
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(h.INPUT_TYPE, '') = IFNULL(p_INPUT_TYPE, '')
      AND IFNULL(h.ISDEL, '0') = '0'
      AND (p_CHIT_TYPE IS NULL OR p_CHIT_TYPE = '' OR h.CHIT_TYPE = p_CHIT_TYPE)
      AND (p_CHIT_ID IS NULL OR p_CHIT_ID = 0 OR h.CHIT_ID = p_CHIT_ID)
      AND (p_FROM_YMD IS NULL OR p_FROM_YMD = '' OR h.CHIT_YMD >= p_FROM_YMD)
      AND (p_TO_YMD IS NULL OR p_TO_YMD = '' OR h.CHIT_YMD <= p_TO_YMD)
      AND (
            v_search_text IS NULL
            OR h.CHIT_CD LIKE CONCAT('%', v_search_text, '%')
            OR h.CHIT_NO LIKE CONCAT('%', v_search_text, '%')
            OR h.PAYER_INFO LIKE CONCAT('%', v_search_text, '%')
            OR ext.NOTE LIKE CONCAT('%', v_search_text, '%')
            OR desc_vi.DESCRIPTION LIKE CONCAT('%', v_search_text, '%')
          )
    ORDER BY h.CHIT_YMD DESC, h.CHIT_ID DESC
    LIMIT v_offset, v_page_size;

    SELECT COUNT(*) AS TOTAL_RECORDS
    FROM chitinfo h
    LEFT JOIN chitinfo_ext ext
        ON ext.COMPANY_CD = h.COMPANY_CD
       AND ext.CHIT_ID = h.CHIT_ID
       AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo desc_vi
        ON desc_vi.COMPANY_CD = h.COMPANY_CD
       AND desc_vi.CHIT_ID = h.CHIT_ID
       AND desc_vi.LANG_TYPE = 'VIET'
       AND IFNULL(desc_vi.ISDEL, '0') = '0'
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(h.INPUT_TYPE, '') = IFNULL(p_INPUT_TYPE, '')
      AND IFNULL(h.ISDEL, '0') = '0'
      AND (p_CHIT_TYPE IS NULL OR p_CHIT_TYPE = '' OR h.CHIT_TYPE = p_CHIT_TYPE)
      AND (p_CHIT_ID IS NULL OR p_CHIT_ID = 0 OR h.CHIT_ID = p_CHIT_ID)
      AND (p_FROM_YMD IS NULL OR p_FROM_YMD = '' OR h.CHIT_YMD >= p_FROM_YMD)
      AND (p_TO_YMD IS NULL OR p_TO_YMD = '' OR h.CHIT_YMD <= p_TO_YMD)
      AND (
            v_search_text IS NULL
            OR h.CHIT_CD LIKE CONCAT('%', v_search_text, '%')
            OR h.CHIT_NO LIKE CONCAT('%', v_search_text, '%')
            OR h.PAYER_INFO LIKE CONCAT('%', v_search_text, '%')
            OR ext.NOTE LIKE CONCAT('%', v_search_text, '%')
            OR desc_vi.DESCRIPTION LIKE CONCAT('%', v_search_text, '%')
          );
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getChitInventoryInput
DROP PROCEDURE IF EXISTS `getChitInventoryInput`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getChitInventoryInput`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHITDETAIL_IDS TEXT
)
BEGIN
    DECLARE v_chitdetail_ids TEXT;

    SET v_chitdetail_ids = REPLACE(IFNULL(TRIM(p_CHITDETAIL_IDS), ''), '|', ',');

    SELECT
        ii.INPUT_ID,
        ii.INPUT_CD,
        ii.INVENTORY_ID,
        ii.INVENTORY_CD,
        ii.CHIT_TYPE,
        ii.COMPANY_CD,
        ii.PRODUCT_ID,
        COALESCE(NULLIF(ii.PRODUCT_CD, ''), product.PRODUCT_CD, '') AS PRODUCT_CD,
        COALESCE(product.PRODUCT_NM_VIET, '') AS PRODUCT_NM_VIET,
        COALESCE(product.PRODUCT_NM_ENG, '') AS PRODUCT_NM_ENG,
        COALESCE(product.PRODUCT_NM_KOR, '') AS PRODUCT_NM_KOR,
        '' AS PRODUCT_NM_CHINA,
        ii.STORE_ID,
        COALESCE(NULLIF(ii.STORE_CD, ''), store_info.STORE_CD, '') AS STORE_CD,
        COALESCE(store_info.STORE_NM_VIET, '') AS STORE_NM_VIET,
        COALESCE(store_info.STORE_NM_ENG, '') AS STORE_NM_ENG,
        COALESCE(store_info.STORE_NM_KOR, '') AS STORE_NM_KOR,
        COALESCE(store_info.STORE_NM_CHINA, '') AS STORE_NM_CHINA,
        ii.UNIT_ID,
        COALESCE(NULLIF(ii.UNIT_CD, ''), unit_info.UNIT_CD, '') AS UNIT_CD,
        COALESCE(unit_info.UNIT_NM, '') AS UNIT_NM_VIET,
        '' AS UNIT_NM_ENG,
        '' AS UNIT_NM_KOR,
        '' AS UNIT_NM_CHINA,
        ii.QUANTITY,
        ii.UNIT_PRICE_CC,
        ii.FC_TYPE,
        ii.UNIT_PRICE_FC,
        ii.EXCHANGE_RATES,
        ii.AMOUNT_CC,
        ii.AMOUNT_FC,
        ii.AMOUNT_TOTAL,
        ii.SUMMARY,
        DATE_FORMAT(ii.INVENTORY_YMD, '%Y-%m-%dT%H:%i:%s') AS INVENTORY_YMD,
        ii.STATE,
        ii.CHITDETAIL_ID,
        ii.CHITDETAIL_CD,
        ii.SORT,
        ii.ISDEL,
        ii.CREATE_BY,
        ii.CREATE_AT,
        ii.UPDATE_BY,
        ii.UPDATE_AT
    FROM chit_inventory_input ii
    LEFT JOIN product_info product
        ON product.COMPANY_CD = ii.COMPANY_CD
       AND product.PRODUCT_ID = ii.PRODUCT_ID
       AND IFNULL(product.ISDEL, '0') = '0'
    LEFT JOIN store_info
        ON store_info.COMPANY_CD = ii.COMPANY_CD
       AND store_info.STORE_ID = ii.STORE_ID
       AND IFNULL(store_info.ISDEL, '0') = '0'
    LEFT JOIN product_unit unit_info
        ON unit_info.COMPANY_CD = ii.COMPANY_CD
       AND unit_info.UNIT_ID = ii.UNIT_ID
       AND IFNULL(unit_info.ISDEL, '0') = '0'
    WHERE ii.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(ii.ISDEL, '0') = '0'
      AND v_chitdetail_ids <> ''
      AND FIND_IN_SET( CAST(ii.CHITDETAIL_ID AS CHAR) COLLATE utf8_unicode_ci, v_chitdetail_ids COLLATE utf8_unicode_ci ) > 0
    ORDER BY COALESCE(ii.CHITDETAIL_ID, 0), COALESCE(ii.SORT, 0), ii.INPUT_ID;
END//
DELIMITER ;


