-- Dumping structure for procedure am_web_001.getChitInventoryInputIdsByLinkedChitId
DROP PROCEDURE IF EXISTS `getChitInventoryInputIdsByLinkedChitId`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getChitInventoryInputIdsByLinkedChitId`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHIT_ID BIGINT(20)
)
BEGIN
    SELECT DISTINCT ii.INPUT_ID
    FROM chit_inventory_input ii
    INNER JOIN chitdetailinfo linked
        ON linked.COMPANY_CD = ii.COMPANY_CD
       AND (
            (ii.CHITDETAIL_ID IS NOT NULL AND ii.CHITDETAIL_ID > 0 AND linked.CHITDETAIL_ID = ii.CHITDETAIL_ID)
            OR (
                (ii.CHITDETAIL_ID IS NULL OR ii.CHITDETAIL_ID = 0)
                AND TRIM(COALESCE(ii.CHITDETAIL_CD, '')) <> ''
                AND linked.CHITDETAIL_CD = TRIM(ii.CHITDETAIL_CD)
            )
       )
    INNER JOIN chitinfo linkedHeader
        ON linkedHeader.COMPANY_CD = linked.COMPANY_CD
       AND linkedHeader.CHIT_ID = linked.CHIT_ID
       AND IFNULL(linkedHeader.ISDEL, '0') = '0'
    WHERE ii.COMPANY_CD = p_COMPANY_CD
      AND linkedHeader.CHIT_ID = p_CHIT_ID
      AND IFNULL(ii.ISDEL, '0') = '0'
      AND IFNULL(linked.ISDEL, '0') = '0';
