        io.UNIT_ID,
        COALESCE(NULLIF(io.UNIT_CD, ''), unit_info.UNIT_CD, '') AS UNIT_CD,
        COALESCE(unit_info.UNIT_NM, '') AS UNIT_NM_VIET,
        '' AS UNIT_NM_ENG,
        '' AS UNIT_NM_KOR,
        '' AS UNIT_NM_CHINA,
        io.QUANTITY,
        io.UNIT_PRICE_CC,
        io.REVENUE_UNIT_PRICE_CC,
        io.FC_TYPE,
        io.UNIT_PRICE_FC,
        io.REVENUE_UNIT_PRICE_FC,
        io.EXCHANGE_RATES,
        io.AMOUNT_CC,
        io.REVENUE_AMOUNT_CC,
        io.AMOUNT_FC,
        io.REVENUE_AMOUNT_FC,
        io.REVENUE_AMOUNT_TOTAL,
        io.AMOUNT_TOTAL,
        io.SUMMARY,
        DATE_FORMAT(io.INVENTORY_YMD, '%Y-%m-%dT%H:%i:%s') AS INVENTORY_YMD,
        io.STATE,
        io.CHITDETAIL_ID,
        io.CHITDETAIL_ID_COGS,
        io.CHITDETAIL_CD,
        io.SORT,
        io.ISDEL,
        io.CREATE_BY,
        io.CREATE_AT,
        io.UPDATE_BY,
        io.UPDATE_AT
    FROM chit_inventory_output io
    LEFT JOIN product_info product
        ON product.COMPANY_CD = io.COMPANY_CD
       AND product.PRODUCT_ID = io.PRODUCT_ID
       AND IFNULL(product.ISDEL, '0') = '0'
    LEFT JOIN store_info
        ON store_info.COMPANY_CD = io.COMPANY_CD
       AND store_info.STORE_ID = io.STORE_ID
       AND IFNULL(store_info.ISDEL, '0') = '0'
    LEFT JOIN product_unit unit_info
        ON unit_info.COMPANY_CD = io.COMPANY_CD
       AND unit_info.UNIT_ID = io.UNIT_ID
       AND IFNULL(unit_info.ISDEL, '0') = '0'
    WHERE io.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(io.ISDEL, '0') = '0'
      AND v_chitdetail_ids <> ''
      AND FIND_IN_SET( CAST(io.CHITDETAIL_ID AS CHAR) COLLATE utf8_unicode_ci, v_chitdetail_ids COLLATE utf8_unicode_ci ) > 0
    ORDER BY COALESCE(io.CHITDETAIL_ID, 0), COALESCE(io.SORT, 0), io.OUTPUT_ID;
END//
DELIMITER ;


