-- Dumping structure for procedure am_web_001.getChitInventoryOutputIdsByLinkedChitId
DROP PROCEDURE IF EXISTS `getChitInventoryOutputIdsByLinkedChitId`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getChitInventoryOutputIdsByLinkedChitId`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHIT_ID BIGINT(20)
)
BEGIN
    SELECT DISTINCT io.OUTPUT_ID
    FROM chit_inventory_output io
    INNER JOIN chitdetailinfo linked
        ON linked.COMPANY_CD = io.COMPANY_CD
       AND (
            (io.CHITDETAIL_ID IS NOT NULL AND io.CHITDETAIL_ID > 0 AND linked.CHITDETAIL_ID = io.CHITDETAIL_ID)
            OR (
                (io.CHITDETAIL_ID IS NULL OR io.CHITDETAIL_ID = 0)
                AND TRIM(COALESCE(io.CHITDETAIL_CD, '')) <> ''
                AND linked.CHITDETAIL_CD = TRIM(io.CHITDETAIL_CD)
            )
       )
    INNER JOIN chitinfo linkedHeader
        ON linkedHeader.COMPANY_CD = linked.COMPANY_CD
       AND linkedHeader.CHIT_ID = linked.CHIT_ID
       AND IFNULL(linkedHeader.ISDEL, '0') = '0'
    WHERE io.COMPANY_CD = p_COMPANY_CD
      AND linkedHeader.CHIT_ID = p_CHIT_ID
      AND IFNULL(io.ISDEL, '0') = '0'
      AND IFNULL(linked.ISDEL, '0') = '0';
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getChitInventoryOutputLinkRows
DROP PROCEDURE IF EXISTS `getChitInventoryOutputLinkRows`;
