CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getChitInventoryOutputLinkRows`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_OUTPUT_IDS TEXT
)
BEGIN
    DECLARE v_output_ids TEXT;
    SET v_output_ids = CONVERT(REPLACE(IFNULL(TRIM(p_OUTPUT_IDS), ''), '|', ',') USING utf8) COLLATE utf8_unicode_ci;

    SELECT
        io.OUTPUT_ID,
        io.CHITDETAIL_ID,
        COALESCE(TRIM(io.CHITDETAIL_CD), '') AS CHITDETAIL_CD,
        linkedHeader.CHIT_ID AS LINKED_CHIT_ID
    FROM chit_inventory_output io
    LEFT JOIN chitdetailinfo linked
        ON linked.COMPANY_CD = io.COMPANY_CD
       AND (
            (io.CHITDETAIL_ID IS NOT NULL AND io.CHITDETAIL_ID > 0 AND linked.CHITDETAIL_ID = io.CHITDETAIL_ID)
            OR (
                (io.CHITDETAIL_ID IS NULL OR io.CHITDETAIL_ID = 0)
                AND TRIM(COALESCE(io.CHITDETAIL_CD, '')) <> ''
                AND linked.CHITDETAIL_CD = TRIM(io.CHITDETAIL_CD)
            )
       )
       AND IFNULL(linked.ISDEL, '0') = '0'
    LEFT JOIN chitinfo linkedHeader
        ON linkedHeader.COMPANY_CD = linked.COMPANY_CD
       AND linkedHeader.CHIT_ID = linked.CHIT_ID
       AND IFNULL(linkedHeader.ISDEL, '0') = '0'
    WHERE io.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(io.ISDEL, '0') = '0'
      AND FIND_IN_SET(CAST(io.OUTPUT_ID AS CHAR) COLLATE utf8_unicode_ci, v_output_ids COLLATE utf8_unicode_ci) > 0;
END//
