-- Dumping structure for procedure am_web_001.getChitInventoryTransfer
DROP PROCEDURE IF EXISTS `getChitInventoryTransfer`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getChitInventoryTransfer`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_INPUT_TYPE VARCHAR(20),
    IN p_CHIT_TYPE VARCHAR(20),
    IN p_TRANSFER_ID BIGINT,
    IN p_SEARCH_TEXT VARCHAR(255),
    IN p_FROM_YMD VARCHAR(8),
    IN p_TO_YMD VARCHAR(8),
    IN p_PAGE_NUMBER INT,
    IN p_PAGE_SIZE INT
)
BEGIN
    DECLARE v_page_number INT DEFAULT 1;
    DECLARE v_page_size INT DEFAULT 20;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_search_text VARCHAR(255);
    DECLARE v_chit_type VARCHAR(20);

    SET v_page_number = IFNULL(NULLIF(p_PAGE_NUMBER, 0), 1);
    SET v_page_size = IFNULL(NULLIF(p_PAGE_SIZE, 0), 20);
    SET v_offset = (v_page_number - 1) * v_page_size;
    SET v_search_text = NULLIF(TRIM(p_SEARCH_TEXT), '');
    SET v_chit_type = UPPER(NULLIF(TRIM(IFNULL(p_CHIT_TYPE, '')), ''));

    SELECT
        h.INVENTORY_ID AS TRANSFER_ID,
        h.CHIT_ID_COGS,
        h.CHITDETAIL_ID_COGS,
        CASE WHEN h.IS_COGS = '1' OR h.CHIT_ID_COGS IS NOT NULL THEN '1' ELSE '0' END AS IS_COGS,
        h.COMPANY_CD,
        h.INVENTORY_CD AS TRANSFER_CD,
        h.INVENTORY_NO AS TRANSFER_NO,
        h.INVENTORY_YMD AS TRANSFER_YMD,
        h.CHIT_TYPE,
        h.INPUT_TYPE,
        h.AMOUNT,
        CASE WHEN UPPER(IFNULL(h.CHIT_TYPE, '')) = 'IO'
            THEN COALESCE(h.REVENUE_AMOUNT, 0) ELSE 0 END AS REVENUE_AMOUNT,
        h.TOTAL_QTY,
        h.REMARK,
        h.CUSTOMER_ID,
        h.CUSTOMER_CD,
        h.SORT,
        h.ISDEL,
        h.CREATE_BY,
        h.CREATE_AT,
        h.UPDATE_BY,
        h.UPDATE_AT
    FROM chit_inventory_info h
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND (p_INPUT_TYPE IS NULL OR p_INPUT_TYPE = '' OR IFNULL(h.INPUT_TYPE, '') = p_INPUT_TYPE)
      AND IFNULL(h.ISDEL, '0') = '0'
      AND (
            v_chit_type IS NULL
            OR v_chit_type = ''
            OR UPPER(IFNULL(h.CHIT_TYPE, '')) = v_chit_type
            OR (v_chit_type = 'IA' AND UPPER(IFNULL(h.CHIT_TYPE, '')) IN ('TRANSFER', 'INVENTORY_TRANSFER', 'INVENTORY_TRANSFER_VOUCHER'))
          )
      AND (p_TRANSFER_ID IS NULL OR p_TRANSFER_ID = 0 OR h.INVENTORY_ID = p_TRANSFER_ID)
      AND (p_FROM_YMD IS NULL OR p_FROM_YMD = '' OR h.INVENTORY_YMD >= p_FROM_YMD)
      AND (p_TO_YMD IS NULL OR p_TO_YMD = '' OR h.INVENTORY_YMD <= p_TO_YMD)
      AND (
            v_search_text IS NULL
            OR h.INVENTORY_CD LIKE CONCAT('%', v_search_text, '%')
            OR h.INVENTORY_NO LIKE CONCAT('%', v_search_text, '%')
            OR h.REMARK LIKE CONCAT('%', v_search_text, '%')
          )
    ORDER BY h.INVENTORY_YMD DESC, h.INVENTORY_ID DESC
    LIMIT v_offset, v_page_size;

    SELECT COUNT(*) AS TOTAL_RECORDS
    FROM chit_inventory_info h
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND (p_INPUT_TYPE IS NULL OR p_INPUT_TYPE = '' OR IFNULL(h.INPUT_TYPE, '') = p_INPUT_TYPE)
      AND IFNULL(h.ISDEL, '0') = '0'
      AND (
            v_chit_type IS NULL
            OR v_chit_type = ''
            OR UPPER(IFNULL(h.CHIT_TYPE, '')) = v_chit_type
            OR (v_chit_type = 'IA' AND UPPER(IFNULL(h.CHIT_TYPE, '')) IN ('TRANSFER', 'INVENTORY_TRANSFER', 'INVENTORY_TRANSFER_VOUCHER'))
          )
      AND (p_TRANSFER_ID IS NULL OR p_TRANSFER_ID = 0 OR h.INVENTORY_ID = p_TRANSFER_ID)
      AND (p_FROM_YMD IS NULL OR p_FROM_YMD = '' OR h.INVENTORY_YMD >= p_FROM_YMD)
      AND (p_TO_YMD IS NULL OR p_TO_YMD = '' OR h.INVENTORY_YMD <= p_TO_YMD)
      AND (
            v_search_text IS NULL
            OR h.INVENTORY_CD LIKE CONCAT('%', v_search_text, '%')
            OR h.INVENTORY_NO LIKE CONCAT('%', v_search_text, '%')
            OR h.REMARK LIKE CONCAT('%', v_search_text, '%')
          );
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getCustomerInfoCustomerExt
DROP PROCEDURE IF EXISTS `getCustomerInfoCustomerExt`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getCustomerInfoCustomerExt`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_CUSTOMER_ID BIGINT(20),
  IN p_CUSTOMER_CD VARCHAR(20)
)
BEGIN
  SELECT
    customer.CUSTOMER_ID,
    ext.CUSTOMER_EXT_ID,
    customer.COMPANY_CD,
    customer.CUSTOMER_CD,
    customer.CATEGORY_CD,
    customer.CUSTOMER_TYPE,
    customer.CUSTOMER_NM_VIET,
    customer.CUSTOMER_NM_ENG,
    customer.CUSTOMER_NM_KOR,
    customer.CUSTOMER_NM_CHINA,
    customer.ADDRESS,
    customer.TEL,
    ext.FAX,
    ext.TAX_CD,
    ext.BANK_ID,
    COALESCE(bank.BANK_CD, '') AS BANK_CD,
    COALESCE(bank.BANK_NM, '') AS BANK_NM,
    ext.EMAIL,
    ext.NOTE,
    ext.IDNUMBER,
    ext.BUYER_NM,
    customer.ISDEL,
    customer.CREATE_AT,
    customer.CREATE_BY,
    customer.UPDATE_AT,
    customer.UPDATE_BY
  FROM customer_info customer
  LEFT JOIN (
    SELECT ext1.*
    FROM customer_ext ext1
    INNER JOIN (
      SELECT
        COMPANY_CD,
        CUSTOMER_ID,
        MAX(CUSTOMER_EXT_ID) AS CUSTOMER_EXT_ID
      FROM customer_ext
      WHERE ISDEL IS NULL OR ISDEL = '0'
      GROUP BY COMPANY_CD, CUSTOMER_ID
    ) latest_ext
      ON latest_ext.COMPANY_CD = ext1.COMPANY_CD
     AND latest_ext.CUSTOMER_ID = ext1.CUSTOMER_ID
     AND latest_ext.CUSTOMER_EXT_ID = ext1.CUSTOMER_EXT_ID
  ) ext
    ON ext.COMPANY_CD = customer.COMPANY_CD
   AND ext.CUSTOMER_ID = customer.CUSTOMER_ID
  LEFT JOIN bank_info bank
    ON ext.BANK_ID = bank.BANK_ID
  WHERE customer.COMPANY_CD = p_COMPANY_CD COLLATE utf8_unicode_ci
    AND (p_CUSTOMER_ID IS NULL OR p_CUSTOMER_ID = 0 OR customer.CUSTOMER_ID = p_CUSTOMER_ID)
    AND (p_CUSTOMER_CD IS NULL OR p_CUSTOMER_CD = '' OR customer.CUSTOMER_CD = p_CUSTOMER_CD COLLATE utf8_unicode_ci)
    AND (customer.ISDEL IS NULL OR customer.ISDEL = '0')
  ORDER BY customer.CUSTOMER_CD, customer.CUSTOMER_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getDashboardChart
DROP PROCEDURE IF EXISTS `getDashboardChart`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getDashboardChart`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_YEAR       CHAR(4)
)
BEGIN
    SELECT
        LEFT(c.CHIT_YMD, 6)                                              AS MONTH,
        COALESCE(SUM(CASE WHEN d.CREDIT LIKE '5%' THEN d.AMOUNT ELSE 0 END), 0) AS REVENUE,
        COALESCE(SUM(CASE WHEN d.DEBIT  LIKE '6%' THEN d.AMOUNT ELSE 0 END), 0) AS EXPENSE,
        COALESCE(SUM(
            CASE WHEN d.CREDIT LIKE '5%' THEN d.AMOUNT ELSE 0 END -
            CASE WHEN d.DEBIT  LIKE '6%' THEN d.AMOUNT ELSE 0 END
        ), 0)                                                            AS PROFIT
    FROM chitdetailinfo d
    INNER JOIN chitinfo c ON c.CHIT_ID = d.CHIT_ID AND c.COMPANY_CD = d.COMPANY_CD
    WHERE d.COMPANY_CD = p_COMPANY_CD AND d.ISDEL = '0' AND c.ISDEL = '0'
      AND LEFT(c.CHIT_YMD, 4) = p_YEAR
    GROUP BY LEFT(c.CHIT_YMD, 6)
    ORDER BY MONTH;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getDashboardKpi
DROP PROCEDURE IF EXISTS `getDashboardKpi`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getDashboardKpi`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_YMD   CHAR(8),
    IN p_TO_YMD     CHAR(8)
)
BEGIN
    DECLARE v_cash_balance  DECIMAL(18,2) DEFAULT 0;
    DECLARE v_revenue       DECIMAL(18,2) DEFAULT 0;
    DECLARE v_expense       DECIMAL(18,2) DEFAULT 0;
    DECLARE v_receivables   DECIMAL(18,2) DEFAULT 0;
    DECLARE v_payables      DECIMAL(18,2) DEFAULT 0;
    DECLARE v_vat_payable   DECIMAL(18,2) DEFAULT 0;
    DECLARE v_pending_count INT           DEFAULT 0;
    DECLARE v_prev_revenue  DECIMAL(18,2) DEFAULT 0;
    DECLARE v_prev_expense  DECIMAL(18,2) DEFAULT 0;
    DECLARE v_prev_from_ymd CHAR(8);
    DECLARE v_prev_to_ymd   CHAR(8);

    SET v_prev_from_ymd = DATE_FORMAT(
        DATE_SUB(STR_TO_DATE(p_FROM_YMD, '%Y%m%d'), INTERVAL 1 MONTH), '%Y%m01');
    SET v_prev_to_ymd = DATE_FORMAT(
        LAST_DAY(DATE_SUB(STR_TO_DATE(p_FROM_YMD, '%Y%m%d'), INTERVAL 1 MONTH)), '%Y%m%d');

    -- Cash & bank (111xx, 112xx)
    SELECT COALESCE(SUM(
        CASE WHEN d.DEBIT  LIKE '111%' OR d.DEBIT  LIKE '112%' THEN d.AMOUNT ELSE 0 END -
        CASE WHEN d.CREDIT LIKE '111%' OR d.CREDIT LIKE '112%' THEN d.AMOUNT ELSE 0 END
    ), 0) INTO v_cash_balance
    FROM chitdetailinfo d
    INNER JOIN chitinfo c ON c.CHIT_ID = d.CHIT_ID AND c.COMPANY_CD = d.COMPANY_CD
    WHERE d.COMPANY_CD = p_COMPANY_CD AND d.ISDEL = '0' AND c.ISDEL = '0'
      AND c.CHIT_YMD <= p_TO_YMD;

    -- Revenue (5xx credit)
    SELECT COALESCE(SUM(CASE WHEN d.CREDIT LIKE '5%' THEN d.AMOUNT ELSE 0 END), 0) INTO v_revenue
    FROM chitdetailinfo d
    INNER JOIN chitinfo c ON c.CHIT_ID = d.CHIT_ID AND c.COMPANY_CD = d.COMPANY_CD
    WHERE d.COMPANY_CD = p_COMPANY_CD AND d.ISDEL = '0' AND c.ISDEL = '0'
      AND c.CHIT_YMD >= p_FROM_YMD AND c.CHIT_YMD <= p_TO_YMD;

    -- Expense (6xx debit)
    SELECT COALESCE(SUM(CASE WHEN d.DEBIT LIKE '6%' THEN d.AMOUNT ELSE 0 END), 0) INTO v_expense
    FROM chitdetailinfo d
    INNER JOIN chitinfo c ON c.CHIT_ID = d.CHIT_ID AND c.COMPANY_CD = d.COMPANY_CD
    WHERE d.COMPANY_CD = p_COMPANY_CD AND d.ISDEL = '0' AND c.ISDEL = '0'
      AND c.CHIT_YMD >= p_FROM_YMD AND c.CHIT_YMD <= p_TO_YMD;

    -- Receivables (131x net)
    SELECT COALESCE(SUM(
        CASE WHEN d.DEBIT  LIKE '131%' THEN d.AMOUNT ELSE 0 END -
        CASE WHEN d.CREDIT LIKE '131%' THEN d.AMOUNT ELSE 0 END
    ), 0) INTO v_receivables
    FROM chitdetailinfo d
    INNER JOIN chitinfo c ON c.CHIT_ID = d.CHIT_ID AND c.COMPANY_CD = d.COMPANY_CD
    WHERE d.COMPANY_CD = p_COMPANY_CD AND d.ISDEL = '0' AND c.ISDEL = '0'
      AND c.CHIT_YMD <= p_TO_YMD;

    -- Payables (331x net)
    SELECT COALESCE(SUM(
        CASE WHEN d.CREDIT LIKE '331%' THEN d.AMOUNT ELSE 0 END -
        CASE WHEN d.DEBIT  LIKE '331%' THEN d.AMOUNT ELSE 0 END
    ), 0) INTO v_payables
    FROM chitdetailinfo d
    INNER JOIN chitinfo c ON c.CHIT_ID = d.CHIT_ID AND c.COMPANY_CD = d.COMPANY_CD
    WHERE d.COMPANY_CD = p_COMPANY_CD AND d.ISDEL = '0' AND c.ISDEL = '0'
      AND c.CHIT_YMD <= p_TO_YMD;

    -- VAT payable (3331x net)
    SELECT COALESCE(SUM(
        CASE WHEN d.CREDIT LIKE '3331%' THEN d.AMOUNT ELSE 0 END -
        CASE WHEN d.DEBIT  LIKE '3331%' THEN d.AMOUNT ELSE 0 END
    ), 0) INTO v_vat_payable
    FROM chitdetailinfo d
    INNER JOIN chitinfo c ON c.CHIT_ID = d.CHIT_ID AND c.COMPANY_CD = d.COMPANY_CD
    WHERE d.COMPANY_CD = p_COMPANY_CD AND d.ISDEL = '0' AND c.ISDEL = '0'
      AND c.CHIT_YMD <= p_TO_YMD;

    -- Pending (unlocked) vouchers
    SELECT COALESCE(COUNT(*), 0) INTO v_pending_count
    FROM chitinfo c
    INNER JOIN chitinfo_ext e ON e.CHIT_ID = c.CHIT_ID AND e.COMPANY_CD = c.COMPANY_CD
    WHERE c.COMPANY_CD = p_COMPANY_CD AND c.ISDEL = '0' AND e.ISDEL = '0'
      AND e.IS_LOCK = '0'
      AND c.CHIT_YMD >= p_FROM_YMD AND c.CHIT_YMD <= p_TO_YMD;

    -- Previous month revenue/expense for growth %
    SELECT COALESCE(SUM(CASE WHEN d.CREDIT LIKE '5%' THEN d.AMOUNT ELSE 0 END), 0) INTO v_prev_revenue
    FROM chitdetailinfo d
    INNER JOIN chitinfo c ON c.CHIT_ID = d.CHIT_ID AND c.COMPANY_CD = d.COMPANY_CD
    WHERE d.COMPANY_CD = p_COMPANY_CD AND d.ISDEL = '0' AND c.ISDEL = '0'
      AND c.CHIT_YMD >= v_prev_from_ymd AND c.CHIT_YMD <= v_prev_to_ymd;

    SELECT COALESCE(SUM(CASE WHEN d.DEBIT LIKE '6%' THEN d.AMOUNT ELSE 0 END), 0) INTO v_prev_expense
    FROM chitdetailinfo d
    INNER JOIN chitinfo c ON c.CHIT_ID = d.CHIT_ID AND c.COMPANY_CD = d.COMPANY_CD
    WHERE d.COMPANY_CD = p_COMPANY_CD AND d.ISDEL = '0' AND c.ISDEL = '0'
      AND c.CHIT_YMD >= v_prev_from_ymd AND c.CHIT_YMD <= v_prev_to_ymd;

    SELECT
        v_cash_balance                        AS CASH_BALANCE,
        v_revenue                             AS REVENUE,
        v_expense                             AS EXPENSE,
        v_revenue - v_expense                 AS PROFIT,
        v_receivables                         AS RECEIVABLES,
        v_payables                            AS PAYABLES,
        v_vat_payable                         AS VAT_PAYABLE,
        v_pending_count                       AS PENDING_VOUCHERS,
        v_prev_revenue                        AS PREV_REVENUE,
        v_prev_expense                        AS PREV_EXPENSE,
        v_prev_revenue - v_prev_expense       AS PREV_PROFIT;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getDashboardPayables
DROP PROCEDURE IF EXISTS `getDashboardPayables`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getDashboardPayables`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_TO_YMD     CHAR(8),
    IN p_TOP        INT
)
BEGIN
    SELECT
        COALESCE(ci_by_id.CUSTOMER_CD, ci_by_cd.CUSTOMER_CD, ext.CUSTOMER_CD, CAST(ext.CUSTOMER_ID AS CHAR)) AS VENDOR_CD,
        COALESCE(
            ci_by_id.CUSTOMER_NM_VIET,
            ci_by_id.CUSTOMER_NM_ENG,
            ci_by_cd.CUSTOMER_NM_VIET,
            ci_by_cd.CUSTOMER_NM_ENG,
            ci_by_id.CUSTOMER_CD,
            ci_by_cd.CUSTOMER_CD,
            ext.CUSTOMER_CD,
            CAST(ext.CUSTOMER_ID AS CHAR)
        )                                                                            AS VENDOR_NM,
        COALESCE(SUM(
            CASE WHEN d.CREDIT LIKE '331%' THEN d.AMOUNT ELSE 0 END -
            CASE WHEN d.DEBIT  LIKE '331%' THEN d.AMOUNT ELSE 0 END
        ), 0)                                                                        AS TOTAL_AMOUNT,
        COALESCE(SUM(
            CASE WHEN (d.DEBIT LIKE '331%' OR d.CREDIT LIKE '331%')
                      AND c.CHIT_YMD < DATE_FORMAT(
                              DATE_SUB(STR_TO_DATE(p_TO_YMD,'%Y%m%d'), INTERVAL 30 DAY), '%Y%m%d')
                 THEN ABS(
                     CASE WHEN d.CREDIT LIKE '331%' THEN d.AMOUNT ELSE 0 END -
                     CASE WHEN d.DEBIT  LIKE '331%' THEN d.AMOUNT ELSE 0 END
                 )
                 ELSE 0
            END
        ), 0)                                                                        AS OVERDUE_AMOUNT,
        MAX(c.CHIT_YMD)                                                              AS LAST_VOUCHER_YMD
    FROM chitdetailinfo d
    INNER JOIN chitinfo c     ON c.CHIT_ID      = d.CHIT_ID     AND c.COMPANY_CD  = d.COMPANY_CD
    INNER JOIN chitdetailinfo_ext ext ON ext.CHITDETAIL_ID = d.CHITDETAIL_ID AND ext.COMPANY_CD = d.COMPANY_CD AND ext.ISDEL = '0'
    LEFT JOIN customer_info ci_by_id ON ci_by_id.CUSTOMER_ID = ext.CUSTOMER_ID AND ci_by_id.COMPANY_CD = ext.COMPANY_CD AND ci_by_id.ISDEL = '0'
    LEFT JOIN customer_info ci_by_cd ON ci_by_id.CUSTOMER_ID IS NULL AND ci_by_cd.CUSTOMER_CD = ext.CUSTOMER_CD AND ci_by_cd.COMPANY_CD = ext.COMPANY_CD AND ci_by_cd.ISDEL = '0'
    WHERE d.COMPANY_CD = p_COMPANY_CD AND d.ISDEL = '0' AND c.ISDEL = '0'
      AND (ext.CUSTOMER_ID IS NOT NULL OR IFNULL(ext.CUSTOMER_CD, '') <> '')
      AND (d.DEBIT LIKE '331%' OR d.CREDIT LIKE '331%')
      AND c.CHIT_YMD <= p_TO_YMD
    GROUP BY 1, 2
    HAVING TOTAL_AMOUNT > 0
    ORDER BY TOTAL_AMOUNT DESC
    LIMIT p_TOP;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getDashboardPeriodLock
DROP PROCEDURE IF EXISTS `getDashboardPeriodLock`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getDashboardPeriodLock`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM  CHAR(6)
)
BEGIN
    -- RS1: month header
    SELECT
        p_PERIOD_YM                                        AS CURRENT_PERIOD,
        COALESCE(m.STATUS, 'OPEN')                         AS STATUS,
        COALESCE(m.MESSAGE, '')                            AS MESSAGE,
        COALESCE(m.LOCKED_BY, '')                          AS LOCKED_BY,
        COALESCE(DATE_FORMAT(m.LOCKED_AT, '%Y%m%d%H%i%s'), '') AS LOCKED_AT
    FROM (SELECT 1) AS _dual
    LEFT JOIN acc_period_lock_month m
        ON m.COMPANY_CD = p_COMPANY_CD AND m.PERIOD_YM = p_PERIOD_YM AND m.ISDEL = '0';

    -- RS2: step details (STEP_CODE / STEP_NAME / STATUS / MESSAGE come from real DB rows)
    SELECT
        s.STEP_CODE,
        s.STEP_NAME,
        s.STEP_ORDER,
        s.STATUS,
        COALESCE(s.MESSAGE, '')                               AS MESSAGE,
        COALESCE(DATE_FORMAT(s.STARTED_AT,  '%Y%m%d%H%i%s'), '') AS STARTED_AT,
        COALESCE(DATE_FORMAT(s.FINISHED_AT, '%Y%m%d%H%i%s'), '') AS FINISHED_AT
    FROM acc_period_lock_step s
    WHERE s.COMPANY_CD = p_COMPANY_CD AND s.PERIOD_YM = p_PERIOD_YM
    ORDER BY s.STEP_ORDER;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getDashboardReceivables
DROP PROCEDURE IF EXISTS `getDashboardReceivables`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getDashboardReceivables`(
    IN p_COMPANY_CD VARCHAR(20),
