)
BEGIN
    SELECT
        COALESCE(ci_by_id.CUSTOMER_CD, ci_by_cd.CUSTOMER_CD, ext.CUSTOMER_CD, CAST(ext.CUSTOMER_ID AS CHAR)) AS CUSTOMER_CD,
        COALESCE(
            ci_by_id.CUSTOMER_NM_VIET,
            ci_by_id.CUSTOMER_NM_ENG,
            ci_by_cd.CUSTOMER_NM_VIET,
            ci_by_cd.CUSTOMER_NM_ENG,
            ci_by_id.CUSTOMER_CD,
            ci_by_cd.CUSTOMER_CD,
            ext.CUSTOMER_CD,
            CAST(ext.CUSTOMER_ID AS CHAR)
        )                                                                            AS CUSTOMER_NM,
        COALESCE(SUM(
            CASE WHEN d.DEBIT  LIKE '131%' THEN d.AMOUNT ELSE 0 END -
            CASE WHEN d.CREDIT LIKE '131%' THEN d.AMOUNT ELSE 0 END
        ), 0)                                                                        AS TOTAL_AMOUNT,
        COALESCE(SUM(
            CASE WHEN (d.DEBIT LIKE '131%' OR d.CREDIT LIKE '131%')
                      AND c.CHIT_YMD < DATE_FORMAT(
                              DATE_SUB(STR_TO_DATE(p_TO_YMD,'%Y%m%d'), INTERVAL 30 DAY), '%Y%m%d')
                 THEN ABS(
                     CASE WHEN d.DEBIT  LIKE '131%' THEN d.AMOUNT ELSE 0 END -
                     CASE WHEN d.CREDIT LIKE '131%' THEN d.AMOUNT ELSE 0 END
                 )
                 ELSE 0
            END
        ), 0)                                                                        AS OVERDUE_AMOUNT,
        MAX(c.CHIT_YMD)                                                              AS LAST_VOUCHER_YMD
    FROM chitdetailinfo d
    INNER JOIN chitinfo c     ON c.CHIT_ID      = d.CHIT_ID     AND c.COMPANY_CD  = d.COMPANY_CD
    INNER JOIN chitdetailinfo_ext ext ON ext.CHITDETAIL_ID = d.CHITDETAIL_ID AND ext.COMPANY_CD = d.COMPANY_CD AND ext.ISDEL = '0'
    LEFT JOIN customer_info ci_by_id ON ci_by_id.CUSTOMER_ID = ext.CUSTOMER_ID AND ci_by_id.COMPANY_CD = ext.COMPANY_CD AND ci_by_id.ISDEL = '0'
    LEFT JOIN customer_info ci_by_cd ON ci_by_id.CUSTOMER_ID IS NULL AND ci_by_cd.CUSTOMER_CD = ext.CUSTOMER_CD AND ci_by_cd.COMPANY_CD = ext.COMPANY_CD AND ci_by_cd.ISDEL = '0'
    WHERE d.COMPANY_CD = p_COMPANY_CD AND d.ISDEL = '0' AND c.ISDEL = '0'
      AND (ext.CUSTOMER_ID IS NOT NULL OR IFNULL(ext.CUSTOMER_CD, '') <> '')
      AND (d.DEBIT LIKE '131%' OR d.CREDIT LIKE '131%')
      AND c.CHIT_YMD <= p_TO_YMD
    GROUP BY 1, 2
    HAVING TOTAL_AMOUNT > 0
