-- Dumping structure for procedure am_web_001.getDashboardRecentVouchers
DROP PROCEDURE IF EXISTS `getDashboardRecentVouchers`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getDashboardRecentVouchers`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_YMD   CHAR(8),
    IN p_TO_YMD     CHAR(8),
    IN p_STATUS     VARCHAR(20),
    IN p_LIMIT      INT
)
BEGIN
    SELECT
        c.CHIT_YMD                                         AS CHIT_YMD,
        c.CHIT_NO                                          AS CHIT_NO,
        c.CHIT_CD                                          AS CHIT_CD,
        c.CHIT_TYPE                                        AS CHIT_TYPE,
        COALESCE(c.AMOUNT, 0)                              AS AMOUNT,
        COALESCE(c.CREATE_BY, '')                          AS CREATE_BY,
        CASE
            WHEN e.IS_LOCK = '1'                          THEN 'LOCKED'
            WHEN e.IS_CONFIRMED = '1' AND e.IS_LOCK = '0' THEN 'CONFIRMED'
            ELSE 'PENDING'
        END                                                AS STATUS,
        COALESCE(dd.DESCRIPTION, '')                       AS DESCRIPTION
    FROM chitinfo c
    INNER JOIN chitinfo_ext e
        ON e.CHIT_ID = c.CHIT_ID AND e.COMPANY_CD = c.COMPANY_CD AND e.ISDEL = '0'
    LEFT JOIN (
        SELECT CHIT_ID, COMPANY_CD, MAX(DESCRIPTION) AS DESCRIPTION
        FROM chitdescriptioninfo
        WHERE ISDEL = '0'
        GROUP BY CHIT_ID, COMPANY_CD
    ) dd ON dd.CHIT_ID = c.CHIT_ID AND dd.COMPANY_CD = c.COMPANY_CD
    WHERE c.COMPANY_CD = p_COMPANY_CD AND c.ISDEL = '0'
      AND c.CHIT_YMD >= p_FROM_YMD AND c.CHIT_YMD <= p_TO_YMD
      AND (
            p_STATUS IS NULL
         OR p_STATUS = ''
         OR p_STATUS = 'ALL'
         OR (p_STATUS = 'PENDING'   AND e.IS_LOCK = '0' AND e.IS_CONFIRMED = '0')
         OR (p_STATUS = 'LOCKED'    AND e.IS_LOCK = '1')
         OR (p_STATUS = 'CONFIRMED' AND e.IS_CONFIRMED = '1' AND e.IS_LOCK = '0')
      )
    ORDER BY c.CHIT_YMD DESC, c.CHIT_ID DESC
    LIMIT p_LIMIT;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getDashboardTasks
DROP PROCEDURE IF EXISTS `getDashboardTasks`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getDashboardTasks`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_YMD   CHAR(8),
    IN p_TO_YMD     CHAR(8)
)
BEGIN
    DECLARE v_today_ymd  CHAR(8);
    DECLARE v_period_ym  CHAR(6);
    SET v_today_ymd = DATE_FORMAT(NOW(), '%Y%m%d');
    SET v_period_ym  = LEFT(p_FROM_YMD, 6);

    -- Unlocked vouchers in range
    SELECT 'PENDING'                  AS CATEGORY,
           'Chứng từ chưa ghi sổ'    AS LABEL,
           'warning'                  AS SEVERITY,
           '/voucher'                 AS ACTION_URL,
           COUNT(*)                   AS CNT
    FROM chitinfo c
    INNER JOIN chitinfo_ext e ON e.CHIT_ID = c.CHIT_ID AND e.COMPANY_CD = c.COMPANY_CD
    WHERE c.COMPANY_CD = p_COMPANY_CD AND c.ISDEL = '0' AND e.ISDEL = '0'
      AND e.IS_LOCK = '0'
      AND c.CHIT_YMD >= p_FROM_YMD AND c.CHIT_YMD <= p_TO_YMD

    UNION ALL

    -- Unconfirmed vouchers in range
    SELECT 'UNCONFIRMED',
           'Chứng từ chưa xác nhận',
           'info',
           '/voucher',
           COUNT(*)
    FROM chitinfo c
    INNER JOIN chitinfo_ext e ON e.CHIT_ID = c.CHIT_ID AND e.COMPANY_CD = c.COMPANY_CD
    WHERE c.COMPANY_CD = p_COMPANY_CD AND c.ISDEL = '0' AND e.ISDEL = '0'
      AND e.IS_CONFIRMED = '0' AND e.IS_LOCK = '0'
      AND c.CHIT_YMD >= p_FROM_YMD AND c.CHIT_YMD <= p_TO_YMD

    UNION ALL

    -- Receivables overdue > 30 days
    SELECT 'OVERDUE_AR',
           'Công nợ phải thu quá hạn',
           'danger',
           '/receivables',
           COUNT(DISTINCT c.CHIT_ID)
    FROM chitdetailinfo d
    INNER JOIN chitinfo c ON c.CHIT_ID = d.CHIT_ID AND c.COMPANY_CD = d.COMPANY_CD
    WHERE d.COMPANY_CD = p_COMPANY_CD AND d.ISDEL = '0' AND c.ISDEL = '0'
      AND (d.DEBIT LIKE '131%' OR d.CREDIT LIKE '131%')
      AND c.CHIT_YMD < DATE_FORMAT(
            DATE_SUB(STR_TO_DATE(v_today_ymd, '%Y%m%d'), INTERVAL 30 DAY), '%Y%m%d')

    UNION ALL

    -- Open / partially locked accounting periods in this year
    SELECT 'OPEN_PERIOD',
           'Kỳ kế toán chưa khóa sổ',
           'info',
           '/period-lock',
           COUNT(*)
    FROM acc_period_lock_month
    WHERE COMPANY_CD = p_COMPANY_CD AND ISDEL = '0'
      AND STATUS IN ('OPEN', 'PARTIAL')
      AND LEFT(PERIOD_YM, 4) = LEFT(p_FROM_YMD, 4)

    UNION ALL

    -- Period lock steps in ERROR state for requested period
    SELECT 'STEP_ERROR',
           'Bước khóa sổ bị lỗi',
           'danger',
           '/period-lock',
           COUNT(*)
    FROM acc_period_lock_step
    WHERE COMPANY_CD = p_COMPANY_CD AND STATUS = 'ERROR'
      AND PERIOD_YM = v_period_ym

    UNION ALL

    -- Missing closing entries for the period
    SELECT 'NO_CLOSING',
           'Kỳ chưa có bút toán kết chuyển',
           'warning',
           '/period-lock',
           CASE WHEN COUNT(*) = 0 THEN 1 ELSE 0 END
    FROM closingmonth_detail
    WHERE COMPANY_CD = p_COMPANY_CD AND ISDEL = '0'
      AND LEFT(CLOSE_YMD, 6) = v_period_ym;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getDashboardTaxDeadlines
DROP PROCEDURE IF EXISTS `getDashboardTaxDeadlines`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getDashboardTaxDeadlines`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM  CHAR(6)
)
BEGIN
    DECLARE v_year       CHAR(4);
    DECLARE v_month_int  INT;
    DECLARE v_next_month CHAR(6);
    DECLARE v_quarter    INT;

    SET v_year      = LEFT(p_PERIOD_YM, 4);
    SET v_month_int = CAST(RIGHT(p_PERIOD_YM, 2) AS UNSIGNED);
    SET v_next_month = DATE_FORMAT(
        DATE_ADD(STR_TO_DATE(CONCAT(p_PERIOD_YM, '01'), '%Y%m%d'), INTERVAL 1 MONTH), '%Y%m');
    SET v_quarter = CEIL(v_month_int / 3.0);

    -- Static tax deadlines
    SELECT
        'Tờ khai VAT (Tháng)'            AS REPORT_NM,
        p_PERIOD_YM                     AS PERIOD,
        CONCAT(v_next_month, '20')      AS DUE_DATE,
        'PENDING'                       AS STATUS
    UNION ALL
    SELECT 'Thuế TNCN (PIT)',
           p_PERIOD_YM,
           CONCAT(v_next_month, '20'),
           'PENDING'
    UNION ALL
    SELECT CONCAT('Thuế TNDN tạm tính Q', v_quarter),
           CONCAT(v_year, 'Q', v_quarter),
           CONCAT(v_next_month, '30'),
           'PENDING'
    UNION ALL
    SELECT 'Báo cáo BHXH',
           p_PERIOD_YM,
           CONCAT(p_PERIOD_YM, '25'),
           'PENDING'
    UNION ALL
    SELECT 'Báo cáo tình hình sử dụng HĐ',
           CONCAT(v_year, 'Q', v_quarter),
           CONCAT(v_next_month, '30'),
           'PENDING';
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getDepartmentInfo
DROP PROCEDURE IF EXISTS `getDepartmentInfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getDepartmentInfo`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_DEPARTMENT_ID BIGINT(20),
  IN p_DEPARTMENT_CD VARCHAR(20)
)
BEGIN
  SELECT
