    CREATE_BY,
    ISDEL
  FROM department_info
  WHERE COMPANY_CD = p_COMPANY_CD
    AND (p_DEPARTMENT_ID IS NULL OR p_DEPARTMENT_ID = 0 OR DEPARTMENT_ID = p_DEPARTMENT_ID)
    AND (p_DEPARTMENT_CD IS NULL OR p_DEPARTMENT_CD = '' OR DEPARTMENT_CD = p_DEPARTMENT_CD)
    AND (ISDEL IS NULL OR ISDEL = '0')
  ORDER BY DEPARTMENT_CD, DEPARTMENT_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getEInvoiceAdminSetting
DROP PROCEDURE IF EXISTS `getEInvoiceAdminSetting`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getEInvoiceAdminSetting`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_SETTING_ID BIGINT UNSIGNED,
  IN p_SETTING_TYPE VARCHAR(50),
  IN p_KEYWORD VARCHAR(200),
  IN p_INCLUDE_DELETED TINYINT
)
BEGIN
  IF p_COMPANY_CD IS NULL THEN
    SET p_COMPANY_CD = '';
  END IF;

  SET p_COMPANY_CD = TRIM(p_COMPANY_CD);

  SELECT
    s.SETTING_ID,
    s.COMPANY_CD,
    s.USER_ID,
    s.SETTING_TYPE,
    s.SETTING_KEY,
    s.SETTING_VALUE,
    s.VALUE_TYPE,
    s.ISDEL,
    s.CREATE_AT,
    s.UPDATE_AT
  FROM einvoice_admin_setting s
  WHERE (IFNULL(p_INCLUDE_DELETED, 0) = 1 OR s.ISDEL = 0)
    AND (IFNULL(p_SETTING_ID, 0) = 0 OR s.SETTING_ID = p_SETTING_ID)
    AND (s.COMPANY_CD = p_COMPANY_CD OR s.COMPANY_CD = '')
    AND (p_SETTING_TYPE IS NULL OR TRIM(p_SETTING_TYPE) = '' OR s.SETTING_TYPE = UPPER(TRIM(p_SETTING_TYPE)))
    AND (
      p_KEYWORD IS NULL
      OR TRIM(p_KEYWORD) = ''
      OR s.SETTING_TYPE LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
      OR s.SETTING_KEY LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
      OR s.SETTING_VALUE LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
    )
    AND (
      IFNULL(p_SETTING_ID, 0) > 0
      OR p_COMPANY_CD = ''
      OR s.COMPANY_CD = p_COMPANY_CD
      OR (
        s.COMPANY_CD = ''
        AND NOT EXISTS (
          SELECT 1
          FROM einvoice_admin_setting c
          WHERE c.COMPANY_CD = p_COMPANY_CD
            AND c.USER_ID = s.USER_ID
            AND c.SETTING_TYPE = s.SETTING_TYPE
            AND c.SETTING_KEY = s.SETTING_KEY
            AND (IFNULL(p_INCLUDE_DELETED, 0) = 1 OR c.ISDEL = 0)
        )
      )
    )
  ORDER BY s.SETTING_TYPE, s.SETTING_KEY, s.COMPANY_CD DESC, s.SETTING_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getEInvoiceBbanInfo
DROP PROCEDURE IF EXISTS `getEInvoiceBbanInfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getEInvoiceBbanInfo`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_BBAN_ID BIGINT,
  IN p_FROM_DATE DATE,
  IN p_TO_DATE DATE,
  IN p_KEYWORD VARCHAR(200),
  IN p_IS_SIGNED TINYINT
)
BEGIN
  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  SELECT
    b.BBAN_ID,
    b.COMPANY_CD,
    b.SELLER_ID,
    b.INVOICE_ID,
    b.REF_INVOICE_ID,
    b.PBAN,
    b.TBBAN,
    b.SBBAN,
    b.NBBAN,
    b.TCHDON,
    b.NBAN,
    b.MSTNBAN,
    b.DCNBAN,
    b.NMUA,
    b.MSTNMUA,
    b.DCNMUA,
    b.KHMSHDON,
    b.KHHDON,
    b.SHDON,
    b.NLAP,
    b.MTRACUU,
    CASE WHEN IFNULL(p_BBAN_ID, 0) > 0 THEN b.TTKHAC_XML ELSE NULL END AS TTKHAC_XML,
    CASE WHEN IFNULL(p_BBAN_ID, 0) > 0 THEN b.NDBBAN_XML ELSE NULL END AS NDBBAN_XML,
    CASE WHEN IFNULL(p_BBAN_ID, 0) > 0 THEN b.SIGNED_XML ELSE NULL END AS SIGNED_XML,
    b.IS_SIGNED,
    b.NMUA_IS_SIGNED,
    b.NMUA_SIGN_DT,
    b.IS_MAIL,
    b.CHECKSUM,
    b.CREATE_BY,
    b.CREATE_AT,
    b.UPDATE_BY,
    b.UPDATE_AT,
    b.ISDEL,
    IFNULL((
      SELECT r.TTHUE
      FROM einvoice_bban_reason r
      WHERE r.BBAN_ID = b.BBAN_ID
        AND r.ISDEL = 0
        AND r.LINE_SIDE = 4
      ORDER BY r.REASON_ID DESC
      LIMIT 1
    ), 0) AS TOTAL_AFTER_TTHUE
  FROM einvoice_bban_info b
  WHERE b.COMPANY_CD = p_COMPANY_CD
    AND b.ISDEL = 0
    AND (p_BBAN_ID IS NULL OR p_BBAN_ID = 0 OR b.BBAN_ID = p_BBAN_ID)
    AND (p_FROM_DATE IS NULL OR b.NBBAN >= p_FROM_DATE)
    AND (p_TO_DATE IS NULL OR b.NBBAN <= p_TO_DATE)
    AND (p_IS_SIGNED IS NULL OR p_IS_SIGNED < 0 OR b.IS_SIGNED = p_IS_SIGNED)
    AND (
      p_KEYWORD IS NULL
      OR TRIM(p_KEYWORD) = ''
      OR CONCAT_WS(' ', b.TBBAN, b.SBBAN, b.MTRACUU, b.NBAN, b.MSTNBAN, b.NMUA, b.MSTNMUA, b.KHMSHDON, b.KHHDON, b.SHDON) LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
    )
  ORDER BY b.NBBAN DESC, b.BBAN_ID DESC;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getEInvoiceBbanReason
DROP PROCEDURE IF EXISTS `getEInvoiceBbanReason`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getEInvoiceBbanReason`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_BBAN_ID BIGINT
)
BEGIN
  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF p_BBAN_ID IS NULL OR p_BBAN_ID <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BBAN_ID is required';
  END IF;

  SELECT
    reason.REASON_ID,
    reason.BBAN_ID,
    reason.DETAIL_ID,
    reason.LINE_SIDE,
    reason.SORT_ORDER,
    reason.LDO,
    reason.TCHAT,
    reason.STT,
    reason.MHHDVU,
    reason.THHDVU,
    reason.DVTINH,
    reason.SLUONG,
    reason.DGIA,
    reason.TLCKHAU,
    reason.STCKHAU,
    reason.THTIEN,
    reason.TSUAT,
    reason.TTHUE,
    reason.TSAUTHUE,
    reason.EXTRA_JSON,
    reason.CREATE_AT,
    reason.ISDEL
  FROM einvoice_bban_reason reason
  INNER JOIN einvoice_bban_info header
    ON header.BBAN_ID = reason.BBAN_ID
   AND header.COMPANY_CD = p_COMPANY_CD
   AND header.ISDEL = 0
  WHERE reason.BBAN_ID = p_BBAN_ID
    AND reason.ISDEL = 0
  ORDER BY reason.LINE_SIDE, reason.SORT_ORDER, reason.REASON_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getEInvoiceBkeByInvoice
DROP PROCEDURE IF EXISTS `getEInvoiceBkeByInvoice`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getEInvoiceBkeByInvoice`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_INVOICE_ID BIGINT
)
BEGIN
  -- Không dùng SELECT INTO (tránh NOT FOUND / lệch result-set với Dapper QueryMultiple).

  SELECT
    b.BKE_ID, b.COMPANY_CD, b.INVOICE_ID, b.SELLER_ID,
    b.PBAN, b.TBKE, b.KHMBKE, b.SBKE, b.NBKE, b.TCHDON,
    b.NBAN, b.MSTNBAN, b.DCNBAN, b.TCTCNHANG,
    b.NMUA, b.MSTNMUA, b.DCNMUA,
    b.TTKHAC_XML, b.SIGNED_XML, b.IS_SIGNED, b.NMUA_IS_SIGNED,
    b.CREATE_BY, b.CREATE_AT, b.UPDATE_BY, b.UPDATE_AT, b.ISDEL
  FROM einvoice_bke_info b
  WHERE b.COMPANY_CD = p_COMPANY_CD
    AND b.INVOICE_ID = p_INVOICE_ID
    AND b.ISDEL = 0
  LIMIT 1;

  SELECT
    r.REASON_ID, r.BKE_ID, r.SORT_ORDER, r.LDO, r.CREATE_AT, r.ISDEL
  FROM einvoice_bke_reason r
  INNER JOIN einvoice_bke_info b
    ON b.BKE_ID = r.BKE_ID
   AND b.COMPANY_CD = p_COMPANY_CD
   AND b.INVOICE_ID = p_INVOICE_ID
   AND b.ISDEL = 0
  WHERE r.ISDEL = 0
  ORDER BY r.SORT_ORDER, r.REASON_ID;

  SELECT
    d.DETAIL_ID, d.BKE_ID, d.STT, d.REF_INVOICE_ID,
    d.KHMSHDON, d.KHHDON, d.SHDON,
    d.THHDVGOC, d.SLGOC, d.DGGOC, d.THTGOC, d.TSGOC, d.TTGOC, d.TGTKGOC, d.TGTSTGOC,
    d.THHDVTDOI, d.SLTDOI, d.DGTDOI, d.THTTDOI, d.TSTDOI, d.TTTDOI, d.TGTTDOI, d.TGTSTTDOI,
    d.TGTCTCLECH, d.TGTTCLECH, d.TGTKCLECH, d.TGTTTCLECH,
    d.EXTRA_JSON, d.CREATE_AT, d.ISDEL
  FROM einvoice_bke_detail d
  INNER JOIN einvoice_bke_info b
    ON b.BKE_ID = d.BKE_ID
   AND b.COMPANY_CD = p_COMPANY_CD
   AND b.INVOICE_ID = p_INVOICE_ID
   AND b.ISDEL = 0
  WHERE d.ISDEL = 0
  ORDER BY IFNULL(d.STT, 999999), d.DETAIL_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getEInvoiceDecimalSetting
DROP PROCEDURE IF EXISTS `getEInvoiceDecimalSetting`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getEInvoiceDecimalSetting`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_XSL_ID BIGINT UNSIGNED,
  IN p_SETTING_ID BIGINT UNSIGNED,
  IN p_APPLY_TARGET VARCHAR(30),
  IN p_FIELD_SCOPE VARCHAR(20),
  IN p_KEYWORD VARCHAR(200),
  IN p_INCLUDE_INACTIVE TINYINT
)
BEGIN
  DECLARE v_XSL_ID BIGINT UNSIGNED DEFAULT 0;

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  SET v_XSL_ID = IFNULL(p_XSL_ID, 0);

  IF IFNULL(p_SETTING_ID, 0) > 0 THEN
    SELECT
      s.SETTING_ID,
      s.COMPANY_CD,
      s.XSL_ID,
      s.APPLY_TARGET,
      s.FIELD_SCOPE,
      s.FIELD_NAME,
      s.LABEL_TEXT,
      s.CAPTION,
      s.CURRENCY_SCOPE,
      s.DECIMAL_SCALE,
      s.ROUND_MODE,
      s.IS_ACTIVE,
      s.SORT_ORDER,
      s.NOTE,
      s.CREATE_BY,
      s.CREATE_AT,
      s.UPDATE_BY,
      s.UPDATE_AT
    FROM einvoice_decimal_setting s
    WHERE s.COMPANY_CD = p_COMPANY_CD
      AND s.SETTING_ID = p_SETTING_ID
      AND (p_APPLY_TARGET IS NULL OR TRIM(p_APPLY_TARGET) = '' OR s.APPLY_TARGET = UPPER(TRIM(p_APPLY_TARGET)))
      AND (p_FIELD_SCOPE IS NULL OR TRIM(p_FIELD_SCOPE) = '' OR s.FIELD_SCOPE = UPPER(TRIM(p_FIELD_SCOPE)))
      AND (IFNULL(p_INCLUDE_INACTIVE, 0) = 1 OR s.IS_ACTIVE = 1)
      AND (
        p_KEYWORD IS NULL
        OR TRIM(p_KEYWORD) = ''
        OR s.FIELD_NAME LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
        OR s.CAPTION LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
        OR s.LABEL_TEXT LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
        OR s.NOTE LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
      )
    ORDER BY s.APPLY_TARGET, s.FIELD_SCOPE, s.SORT_ORDER, s.FIELD_NAME, s.CURRENCY_SCOPE, s.SETTING_ID;
  ELSE
    SELECT
      s.SETTING_ID,
      s.COMPANY_CD,
      s.XSL_ID,
      s.APPLY_TARGET,
      s.FIELD_SCOPE,
      s.FIELD_NAME,
      s.LABEL_TEXT,
      s.CAPTION,
      s.CURRENCY_SCOPE,
      s.DECIMAL_SCALE,
      s.ROUND_MODE,
      s.IS_ACTIVE,
      s.SORT_ORDER,
      s.NOTE,
      s.CREATE_BY,
      s.CREATE_AT,
      s.UPDATE_BY,
      s.UPDATE_AT
    FROM einvoice_decimal_setting s
    WHERE (s.COMPANY_CD = p_COMPANY_CD OR s.COMPANY_CD = '')
      AND (
        IFNULL(s.XSL_ID, 0) = 0
        OR (
          v_XSL_ID > 0
          AND IFNULL(s.XSL_ID, 0) IN (0, v_XSL_ID)
        )
      )
      AND (p_APPLY_TARGET IS NULL OR TRIM(p_APPLY_TARGET) = '' OR s.APPLY_TARGET = UPPER(TRIM(p_APPLY_TARGET)))
      AND (p_FIELD_SCOPE IS NULL OR TRIM(p_FIELD_SCOPE) = '' OR s.FIELD_SCOPE = UPPER(TRIM(p_FIELD_SCOPE)))
      AND (IFNULL(p_INCLUDE_INACTIVE, 0) = 1 OR s.IS_ACTIVE = 1)
      AND (
        p_KEYWORD IS NULL
        OR TRIM(p_KEYWORD) = ''
        OR s.FIELD_NAME LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
        OR s.CAPTION LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
        OR s.LABEL_TEXT LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
        OR s.NOTE LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
      )
      AND NOT EXISTS (
        SELECT 1
          FROM einvoice_decimal_setting c
         WHERE c.APPLY_TARGET = s.APPLY_TARGET
           AND c.FIELD_SCOPE = s.FIELD_SCOPE
           AND c.FIELD_NAME = s.FIELD_NAME
           AND c.CURRENCY_SCOPE = s.CURRENCY_SCOPE
           AND (c.COMPANY_CD = p_COMPANY_CD OR c.COMPANY_CD = '')
           AND (
             IFNULL(c.XSL_ID, 0) = 0
             OR (
               v_XSL_ID > 0
               AND IFNULL(c.XSL_ID, 0) IN (0, v_XSL_ID)
             )
           )
           AND (IFNULL(p_INCLUDE_INACTIVE, 0) = 1 OR c.IS_ACTIVE = 1)
           AND (
             CASE
               WHEN c.COMPANY_CD = p_COMPANY_CD AND IFNULL(c.XSL_ID, 0) = v_XSL_ID AND v_XSL_ID > 0 THEN 1
               WHEN c.COMPANY_CD = p_COMPANY_CD AND IFNULL(c.XSL_ID, 0) = 0 THEN 2
               WHEN c.COMPANY_CD = '' THEN 3
               ELSE 9
             END
             <
             CASE
               WHEN s.COMPANY_CD = p_COMPANY_CD AND IFNULL(s.XSL_ID, 0) = v_XSL_ID AND v_XSL_ID > 0 THEN 1
               WHEN s.COMPANY_CD = p_COMPANY_CD AND IFNULL(s.XSL_ID, 0) = 0 THEN 2
               WHEN s.COMPANY_CD = '' THEN 3
               ELSE 9
             END
           )
      )
    ORDER BY s.APPLY_TARGET, s.FIELD_SCOPE, s.SORT_ORDER, s.FIELD_NAME, s.CURRENCY_SCOPE, s.SETTING_ID;
  END IF;
END//
DELIMITER ;


