-- Dumping structure for procedure am_web_001.getEInvoiceDetails
DROP PROCEDURE IF EXISTS `getEInvoiceDetails`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getEInvoiceDetails`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_INVOICE_IDS TEXT
)
BEGIN
  DECLARE v_invoice_ids TEXT;

  SET v_invoice_ids = REPLACE(IFNULL(TRIM(p_INVOICE_IDS), ''), '|', ',');

  SELECT
    d.DETAIL_ID,
    d.INVOICE_ID,
    d.COMPANY_CD,
    d.TCHAT,
    d.STT,
    d.MHHDVU,
    d.THHDVU,
    d.DVTINH,
    d.SLUONG,
    d.SLTHUCNHAP,
    d.DGIA,
    d.TLCKHAU,
    d.STCKHAU,
    d.THTIEN,
    d.TSUAT,
    d.TTHUE,
    d.TSAUTHUE,
    d.DGIA_VND,
    d.STCKHAU_VND,
    d.THTIEN_VND,
    d.TTHUE_VND,
    d.TSAUTHUE_VND,
    d.EXTRA_JSON,
    d.CREATE_AT,
    d.CREATE_BY,
    d.UPDATE_AT,
    d.UPDATE_BY,
    d.ISDEL
  FROM einvoice_detail d
  WHERE d.COMPANY_CD = p_COMPANY_CD
    AND d.ISDEL = 0
    AND v_invoice_ids <> ''
    AND FIND_IN_SET(CAST(d.INVOICE_ID AS CHAR CHARACTER SET utf8) COLLATE utf8_unicode_ci, v_invoice_ids COLLATE utf8_unicode_ci) > 0
  ORDER BY d.INVOICE_ID, IFNULL(d.STT, 999999), d.DETAIL_ID;

  SELECT
    s.SPECIAL_ID,
    s.COMPANY_CD,
    s.INVOICE_ID,
    s.DETAIL_ID,
    s.LHHDTRUNG,
    s.SKHUNG,
    s.SMAY,
    s.BKSPT_VCHUYEN,
    s.TNG_HANG,
    s.DCNG_HANG,
    s.MSTNG_HANG,
    s.MDDNG_HANG,
    s.EXTRA_JSON,
    s.CREATE_BY,
    s.CREATE_AT,
    s.UPDATE_BY,
    s.UPDATE_AT
  FROM einvoice_detail_special_info s
  WHERE s.COMPANY_CD = p_COMPANY_CD
    AND v_invoice_ids <> ''
    AND FIND_IN_SET(CAST(s.INVOICE_ID AS CHAR CHARACTER SET utf8) COLLATE utf8_unicode_ci, v_invoice_ids COLLATE utf8_unicode_ci) > 0
  ORDER BY s.INVOICE_ID, s.DETAIL_ID;

  SELECT
    p.PXK_ID,
    p.INVOICE_ID,
    p.PXK_TYPE,
    p.NBAN_DCHI,
    p.LDDNBO,
    p.HDKTSO,
    p.HDKTNGAY,
    p.HVTNXHANG,
    p.TNVCHUYEN,
    p.HDSO,
    p.PTVCHUYEN,
    p.EXTRA_JSON,
    p.CREATE_BY,
    p.CREATE_AT,
    p.UPDATE_BY,
    p.UPDATE_AT,
    p.ISDEL
  FROM einvoice_pxk_info p
  INNER JOIN einvoice_info i
    ON i.INVOICE_ID = p.INVOICE_ID
  WHERE i.COMPANY_CD = p_COMPANY_CD
    AND i.ISDEL = 0
    AND p.ISDEL = 0
    AND v_invoice_ids <> ''
    AND FIND_IN_SET(CAST(p.INVOICE_ID AS CHAR CHARACTER SET utf8) COLLATE utf8_unicode_ci, v_invoice_ids COLLATE utf8_unicode_ci) > 0
  ORDER BY p.INVOICE_ID, p.PXK_ID;

  SELECT
    r.RELATED_ID,
    r.COMPANY_CD,
    r.INVOICE_ID,
    r.TCHDON,
    r.IS_EXTERNAL,
    r.MSTCLQUAN,
    r.LHDCLQUAN,
    r.KHMSHDCLQUAN,
    r.KHHDCLQUAN,
    r.SHDCLQUAN,
    r.NLHDCLQUAN,
    r.LDDCTTHE,
    r.SBKCLQUAN,
    r.NBKCLQUAN,
    r.GCHU,
    r.CREATE_BY,
    r.CREATE_AT
  FROM einvoice_related_info r
  WHERE r.COMPANY_CD = p_COMPANY_CD
    AND v_invoice_ids <> ''
    AND FIND_IN_SET(CAST(r.INVOICE_ID AS CHAR CHARACTER SET utf8) COLLATE utf8_unicode_ci, v_invoice_ids COLLATE utf8_unicode_ci) > 0
  ORDER BY r.INVOICE_ID, r.RELATED_ID;
END//
DELIMITER ;


