-- Dumping structure for procedure am_web_001.getEInvoiceInfo
DROP PROCEDURE IF EXISTS `getEInvoiceInfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getEInvoiceInfo`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_INVOICE_ID BIGINT,
  IN p_FROM_DATE DATE,
  IN p_TO_DATE DATE,
  IN p_KEYWORD VARCHAR(200),
  IN p_PAGE_NUMBER INT,
  IN p_PAGE_SIZE INT,
  IN p_INCLUDE_DETAILS TINYINT,
  IN p_KHHDON VARCHAR(50),
  IN p_KHHDON_OP VARCHAR(20),
  IN p_SHDON_FROM VARCHAR(20),
  IN p_SHDON_TO VARCHAR(20),
  IN p_NMUA_TEN VARCHAR(200),
  IN p_NMUA_TEN_OP VARCHAR(20),
  IN p_NMUA_MST VARCHAR(50),
  IN p_NMUA_MST_OP VARCHAR(20),
  IN p_INVOICE_STATUS INT,
  IN p_CQT_STATUS INT,
  IN p_IS_SIGNED INT,
  IN p_TCHDON INT,
  IN p_MAIL_STATUS INT,
  IN p_CASH_REGISTER TINYINT
)
BEGIN
  DECLARE v_page_number INT DEFAULT 1;
  DECLARE v_page_size INT DEFAULT 20;
  DECLARE v_offset INT DEFAULT 0;
  DECLARE v_include_details TINYINT DEFAULT 0;
  DECLARE v_keyword VARCHAR(200);
  DECLARE v_khhdon VARCHAR(50);
  DECLARE v_khhdon_op VARCHAR(20);
  DECLARE v_shdon_from BIGINT;
  DECLARE v_shdon_to BIGINT;
  DECLARE v_nmua_ten VARCHAR(200);
  DECLARE v_nmua_ten_op VARCHAR(20);
  DECLARE v_nmua_mst VARCHAR(50);
  DECLARE v_nmua_mst_op VARCHAR(20);

  SET v_page_number = IFNULL(NULLIF(p_PAGE_NUMBER, 0), 1);
  SET v_page_size = IFNULL(NULLIF(p_PAGE_SIZE, 0), 20);
  IF v_page_number < 1 THEN
    SET v_page_number = 1;
  END IF;
  IF v_page_size < 1 THEN
    SET v_page_size = 20;
  END IF;
  SET v_offset = (v_page_number - 1) * v_page_size;
  SET v_include_details = IFNULL(p_INCLUDE_DETAILS, 0);
  SET v_keyword = NULLIF(TRIM(IFNULL(p_KEYWORD, '')), '');
  SET v_keyword = IF(v_keyword IS NULL, NULL, LOWER(v_keyword));
  SET v_khhdon = NULLIF(TRIM(IFNULL(p_KHHDON, '')), '');
  SET v_khhdon = IF(v_khhdon IS NULL, NULL, LOWER(v_khhdon));
  SET v_khhdon_op = LOWER(IFNULL(NULLIF(TRIM(IFNULL(p_KHHDON_OP, '')), ''), 'contains'));
  SET v_shdon_from = CASE
    WHEN NULLIF(TRIM(IFNULL(p_SHDON_FROM, '')), '') IS NULL THEN NULL
    ELSE CAST(TRIM(p_SHDON_FROM) AS UNSIGNED)
  END;
  SET v_shdon_to = CASE
    WHEN NULLIF(TRIM(IFNULL(p_SHDON_TO, '')), '') IS NULL THEN NULL
    ELSE CAST(TRIM(p_SHDON_TO) AS UNSIGNED)
  END;
  SET v_nmua_ten = NULLIF(TRIM(IFNULL(p_NMUA_TEN, '')), '');
  SET v_nmua_ten = IF(v_nmua_ten IS NULL, NULL, LOWER(v_nmua_ten));
  SET v_nmua_ten_op = LOWER(IFNULL(NULLIF(TRIM(IFNULL(p_NMUA_TEN_OP, '')), ''), 'contains'));
  SET v_nmua_mst = NULLIF(TRIM(IFNULL(p_NMUA_MST, '')), '');
  SET v_nmua_mst = IF(v_nmua_mst IS NULL, NULL, LOWER(v_nmua_mst));
  SET v_nmua_mst_op = LOWER(IFNULL(NULLIF(TRIM(IFNULL(p_NMUA_MST_OP, '')), ''), 'startswith'));

  DROP TEMPORARY TABLE IF EXISTS tmp_einvoice_filtered;
  CREATE TEMPORARY TABLE tmp_einvoice_filtered (
    INVOICE_ID BIGINT NOT NULL PRIMARY KEY,
    IS_SIGNED TINYINT NULL,
    SHDON_NUM BIGINT NULL,
    KHMSHDON VARCHAR(11) NULL,
    KHHDON VARCHAR(8) NULL
  );

  INSERT INTO tmp_einvoice_filtered (INVOICE_ID, IS_SIGNED, SHDON_NUM, KHMSHDON, KHHDON)
  SELECT
    i.INVOICE_ID,
    IFNULL(i.IS_SIGNED, 0),
    CAST(NULLIF(TRIM(i.SHDON), '') AS UNSIGNED),
    i.KHMSHDON,
    i.KHHDON
  FROM einvoice_info i
  LEFT JOIN einvoice_seller_info s
    ON s.SELLER_ID = i.SELLER_ID
   AND s.COMPANY_CD = i.COMPANY_CD
  WHERE i.COMPANY_CD = p_COMPANY_CD
    AND i.ISDEL = 0
    AND (p_CASH_REGISTER IS NULL OR
      (UPPER(SUBSTRING(TRIM(IFNULL(i.KHHDON, '')), 4, 1)) = 'M') = p_CASH_REGISTER)
    AND (p_INVOICE_ID IS NULL OR p_INVOICE_ID = 0 OR i.INVOICE_ID = p_INVOICE_ID)
    AND (p_FROM_DATE IS NULL OR i.NLAP >= p_FROM_DATE)
    AND (p_TO_DATE IS NULL OR i.NLAP <= p_TO_DATE)
    AND (
      v_keyword IS NULL
      OR LOWER(CONCAT_WS(' ', i.THDON, i.KHMSHDON, i.KHHDON, i.SHDON, i.MHSO, s.SELLER_NM, s.SELLER_TAX_CD, i.NMUA_TEN, i.NMUA_HVTNMHANG, i.NMUA_MST, i.MCCQT, i.MTRACUU)) LIKE CONCAT('%', v_keyword, '%')
    )
    AND (
      v_khhdon IS NULL
      OR (v_khhdon_op = 'equals' AND LOWER(IFNULL(i.KHHDON, '')) = v_khhdon)
      OR (v_khhdon_op IN ('startswith', 'starts_with') AND LOWER(IFNULL(i.KHHDON, '')) LIKE CONCAT(v_khhdon, '%'))
      OR (v_khhdon_op NOT IN ('equals', 'startswith', 'starts_with') AND LOWER(IFNULL(i.KHHDON, '')) LIKE CONCAT('%', v_khhdon, '%'))
    )
    AND (v_shdon_from IS NULL OR CAST(NULLIF(TRIM(i.SHDON), '') AS UNSIGNED) >= v_shdon_from)
    AND (v_shdon_to IS NULL OR CAST(NULLIF(TRIM(i.SHDON), '') AS UNSIGNED) <= v_shdon_to)
    AND (
      v_nmua_ten IS NULL
      OR (v_nmua_ten_op = 'equals' AND LOWER(IFNULL(i.NMUA_TEN, '')) = v_nmua_ten)
      OR (v_nmua_ten_op IN ('startswith', 'starts_with') AND LOWER(IFNULL(i.NMUA_TEN, '')) LIKE CONCAT(v_nmua_ten, '%'))
      OR (v_nmua_ten_op NOT IN ('equals', 'startswith', 'starts_with') AND LOWER(IFNULL(i.NMUA_TEN, '')) LIKE CONCAT('%', v_nmua_ten, '%'))
    )
    AND (
      v_nmua_mst IS NULL
      OR (v_nmua_mst_op = 'equals' AND LOWER(IFNULL(i.NMUA_MST, '')) = v_nmua_mst)
      OR (v_nmua_mst_op IN ('startswith', 'starts_with') AND LOWER(IFNULL(i.NMUA_MST, '')) LIKE CONCAT(v_nmua_mst, '%'))
      OR (v_nmua_mst_op NOT IN ('equals', 'startswith', 'starts_with') AND LOWER(IFNULL(i.NMUA_MST, '')) LIKE CONCAT('%', v_nmua_mst, '%'))
    )
    AND (p_INVOICE_STATUS IS NULL OR i.INVOICE_STATUS = p_INVOICE_STATUS)
    AND (
      p_CQT_STATUS IS NULL
      OR (p_CQT_STATUS = 0 AND IFNULL(i.INVOICE_STATUS, 0) <> 6 AND
        CASE WHEN UPPER(SUBSTRING(TRIM(i.KHHDON),4,1))='M' THEN IFNULL(i.INVOICE_STATUS,0)=0 ELSE IFNULL(TRIM(i.MCCQT),'')='' END)
      OR (p_CQT_STATUS = 1 AND IFNULL(i.INVOICE_STATUS,0) <> 6 AND
        CASE WHEN UPPER(SUBSTRING(TRIM(i.KHHDON),4,1))='M' THEN IFNULL(i.INVOICE_STATUS,0) IN (1,2,3,4,5) ELSE IFNULL(TRIM(i.MCCQT),'')<>'' END)
      OR (p_CQT_STATUS = 2 AND IFNULL(i.INVOICE_STATUS, 0) = 6)
    )
    AND (p_IS_SIGNED IS NULL OR IFNULL(i.IS_SIGNED, 0) = p_IS_SIGNED)
    AND (p_TCHDON IS NULL OR IFNULL(i.TCHDON, 0) = p_TCHDON)
    AND (p_MAIL_STATUS IS NULL OR IFNULL(i.MAIL_STATUS, 0) = p_MAIL_STATUS);

  DROP TEMPORARY TABLE IF EXISTS tmp_einvoice_page_ids;
  CREATE TEMPORARY TABLE tmp_einvoice_page_ids (
    INVOICE_ID BIGINT NOT NULL PRIMARY KEY
  );

  INSERT INTO tmp_einvoice_page_ids (INVOICE_ID)
  SELECT page_rows.INVOICE_ID
  FROM (
    SELECT f.INVOICE_ID
    FROM tmp_einvoice_filtered f
    ORDER BY
      IFNULL(f.IS_SIGNED, 0) ASC,
      f.SHDON_NUM DESC,
      f.KHMSHDON,
      f.KHHDON,
      f.INVOICE_ID ASC
    LIMIT v_offset, v_page_size
  ) page_rows;

  SELECT
    i.INVOICE_ID,
    i.DOC_VERSION,
    i.COMPANY_CD,
    i.SELLER_ID,
    i.XSL_ID,
    s.SELLER_NM,
    s.SELLER_TAX_CD,
    i.PBAN,
    i.THDON,
    i.KHMSHDON,
    i.KHHDON,
    i.SHDON,
    i.MHSO,
    i.NLAP,
    i.HDCTTCHINH,
    i.SBKE,
    i.NBKE,
    i.DVTTE,
    i.TGIA,
    i.HTTTOAN,
    i.MSTTCGP,
    i.TCHDON,
    i.NMUA_TEN,
    i.NMUA_MST,
    i.NMUA_MDVQHNSACH,
    i.NMUA_DCHI,
    i.NMUA_MTINH,
    i.NMUA_TTINH,
    i.NMUA_MXA,
    i.NMUA_TXA,
    i.NMUA_MKHANG,
    i.NMUA_SDTHOAI,
    i.NMUA_CCCDAN,
    i.NMUA_SHCHIEU,
    i.NMUA_DCTDTU,
    i.NMUA_HVTNMHANG,
    i.NMUA_STKNHANG,
    i.NMUA_TNHANG,
    i.TGTCTHUE,
    i.TGTKCTHUE,
    i.TGTTTHUE,
    i.TTCKTMAI,
    i.CKTMAI_GCHU,
    i.TGTKHAC,
    i.TGTTTBSO,
    i.TGTTTBCHU,
    i.TGTCTHUE_VND,
    i.TGTKCTHUE_VND,
    i.TGTTTHUE_VND,
    i.TTCKTMAI_VND,
    i.TGTKHAC_VND,
    i.TGTTTBSO_VND,
    i.DLQRCODE,
    i.MCCQT,
    i.MTRACUU,
    i.MTDIEP,
    i.MGDDTu,
    i.TAX_SUMMARY_JSON,
    i.FEE_JSON,
    i.EXTRA_JSON,
    i.XML_FTP_PATH,
    i.IS_SIGNED,
    i.INVOICE_STATUS,
    i.MAIL_STATUS,
    i.SOURCE_INVOICE_ID,
    i.ERROR_MESSAGE,
    i.CREATE_BY,
    i.CREATE_AT,
    i.UPDATE_BY,
    i.UPDATE_AT,
    i.ISDEL
  FROM tmp_einvoice_page_ids page_ids
  INNER JOIN einvoice_info i
    ON i.INVOICE_ID = page_ids.INVOICE_ID
  LEFT JOIN einvoice_seller_info s
    ON s.SELLER_ID = i.SELLER_ID
   AND s.COMPANY_CD = i.COMPANY_CD
  LEFT JOIN tmp_einvoice_filtered f
    ON f.INVOICE_ID = i.INVOICE_ID
  ORDER BY
    IFNULL(f.IS_SIGNED, 0) ASC,
    f.SHDON_NUM DESC,
    f.KHMSHDON,
    f.KHHDON,
    i.INVOICE_ID ASC;

  SELECT COUNT(*) AS TOTAL_RECORDS
  FROM tmp_einvoice_filtered;

  IF v_include_details = 1 THEN
    SELECT
      d.DETAIL_ID,
      d.INVOICE_ID,
      d.COMPANY_CD,
      d.TCHAT,
      d.STT,
      d.MHHDVU,
      d.THHDVU,
      d.DVTINH,
      d.SLUONG,
      d.SLTHUCNHAP,
      d.DGIA,
      d.TLCKHAU,
      d.STCKHAU,
      d.THTIEN,
      d.TSUAT,
      d.TTHUE,
      d.TSAUTHUE,
      d.DGIA_VND,
      d.STCKHAU_VND,
      d.THTIEN_VND,
      d.TTHUE_VND,
      d.TSAUTHUE_VND,
      d.EXTRA_JSON,
      d.CREATE_AT,
      d.CREATE_BY,
      d.UPDATE_AT,
      d.UPDATE_BY,
      d.ISDEL
    FROM einvoice_detail d
    INNER JOIN tmp_einvoice_page_ids page_ids
      ON page_ids.INVOICE_ID = d.INVOICE_ID
    WHERE d.COMPANY_CD = p_COMPANY_CD
      AND d.ISDEL = 0
    ORDER BY d.INVOICE_ID, IFNULL(d.STT, 999999), d.DETAIL_ID;

    SELECT
      sp.SPECIAL_ID,
      sp.COMPANY_CD,
      sp.INVOICE_ID,
      sp.DETAIL_ID,
      sp.LHHDTRUNG,
      sp.SKHUNG,
      sp.SMAY,
      sp.BKSPT_VCHUYEN,
      sp.TNG_HANG,
      sp.DCNG_HANG,
      sp.MSTNG_HANG,
      sp.MDDNG_HANG,
      sp.EXTRA_JSON,
      sp.CREATE_BY,
      sp.CREATE_AT,
      sp.UPDATE_BY,
      sp.UPDATE_AT
    FROM einvoice_detail_special_info sp
    INNER JOIN tmp_einvoice_page_ids page_ids
      ON page_ids.INVOICE_ID = sp.INVOICE_ID
    WHERE sp.COMPANY_CD = p_COMPANY_CD
    ORDER BY sp.INVOICE_ID, sp.DETAIL_ID;

    SELECT
      p.PXK_ID,
      p.INVOICE_ID,
      p.PXK_TYPE,
      p.NBAN_DCHI,
      p.LDDNBO,
      p.HDKTSO,
      p.HDKTNGAY,
      p.HVTNXHANG,
      p.TNVCHUYEN,
      p.HDSO,
      p.PTVCHUYEN,
      p.EXTRA_JSON,
      p.CREATE_BY,
      p.CREATE_AT,
      p.UPDATE_BY,
      p.UPDATE_AT,
      p.ISDEL
    FROM einvoice_pxk_info p
    INNER JOIN einvoice_info i
      ON i.INVOICE_ID = p.INVOICE_ID
    INNER JOIN tmp_einvoice_page_ids page_ids
      ON page_ids.INVOICE_ID = p.INVOICE_ID
    WHERE i.COMPANY_CD = p_COMPANY_CD
      AND i.ISDEL = 0
      AND p.ISDEL = 0
    ORDER BY p.INVOICE_ID, p.PXK_ID;

    SELECT
      r.RELATED_ID,
      r.COMPANY_CD,
      r.INVOICE_ID,
      r.TCHDON,
      r.IS_EXTERNAL,
      r.MSTCLQUAN,
      r.LHDCLQUAN,
      r.KHMSHDCLQUAN,
      r.KHHDCLQUAN,
      r.SHDCLQUAN,
      r.NLHDCLQUAN,
      r.LDDCTTHE,
      r.SBKCLQUAN,
      r.NBKCLQUAN,
      r.GCHU,
      r.CREATE_BY,
      r.CREATE_AT
    FROM einvoice_related_info r
    INNER JOIN tmp_einvoice_page_ids page_ids
      ON page_ids.INVOICE_ID = r.INVOICE_ID
    WHERE r.COMPANY_CD = p_COMPANY_CD
    ORDER BY r.INVOICE_ID, r.RELATED_ID;
  END IF;

  DROP TEMPORARY TABLE IF EXISTS tmp_einvoice_page_ids;
  DROP TEMPORARY TABLE IF EXISTS tmp_einvoice_filtered;
END//
DELIMITER ;


