-- Dumping structure for procedure am_web_001.getEInvoiceSeller
DROP PROCEDURE IF EXISTS `getEInvoiceSeller`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getEInvoiceSeller`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_KHHDON VARCHAR(8),
  IN p_SELLER_ID BIGINT UNSIGNED,
  IN p_XSL_ID BIGINT UNSIGNED,
  IN p_KEYWORD VARCHAR(200),
  IN p_INCLUDE_INACTIVE TINYINT,
  IN p_INCLUDE_XSL TINYINT,
  IN p_INCLUDE_ALL_TEMPLATES TINYINT
)
BEGIN
  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  SELECT
    s.SELLER_ID,
    s.COMPANY_CD,
    s.SELLER_CD,
    s.SELLER_NM,
    s.SELLER_TAX_CD,
    (SELECT CASE WHEN t.CMTMTTIEN=1 THEN t.MCCQT ELSE NULL END FROM einvoice_tkhai_info t
      WHERE t.COMPANY_CD = s.COMPANY_CD AND t.MST = s.SELLER_TAX_CD
        AND t.ISDEL = 0 AND t.CQT_STATUS = 2
      ORDER BY t.NLAP DESC, t.TKHAI_ID DESC LIMIT 1) AS MCCQT,
    s.SELLER_ADDRESS,
    s.MDDKDOANH,
    s.TDDKDOANH,
    s.DCDDKDOANH,
    xsl.THDON,
    xsl.KHMSHDON,
    xsl.KHHDON,
    xsl.FROM_SHDON,
    xsl.TO_SHDON,
    s.MCHANG,
    s.TCHANG,
    s.SDTHOAI,
    s.DCTDTU,
    s.STKNHANG,
    s.TNHANG,
    s.FAX,
    s.WEBSITE,
    COALESCE(xsld.LOGO_PATH, xsld1.LOGO_PATH) AS LOGO_PATH,
    COALESCE(xsld.INVOICE_BACKGROUND_PATH, xsld1.INVOICE_BACKGROUND_PATH) AS INVOICE_BACKGROUND_PATH,
    COALESCE(xsld.INVOICE_BORDER_PATH, xsld1.INVOICE_BORDER_PATH) AS INVOICE_BORDER_PATH,
    COALESCE(xsld.BACKGROUND_PATH, xsld1.BACKGROUND_PATH) AS BACKGROUND_PATH,
    xsl.USE_MULTI_TAX_RATE,
    xsl.XSL_ID,
    xsl.TEMPLATE_NM AS XSL_TEMPLATE_NM,
    CASE WHEN IFNULL(p_INCLUDE_XSL, 0) = 1 THEN xslc.XSL_CONTENT ELSE NULL END AS XSL_CONTENT,
    CASE WHEN IFNULL(p_INCLUDE_XSL, 0) = 1 THEN xsld1.XSL_CONTENT ELSE NULL END AS XSL_DESIGN_CONTENT,
    xsl.VERSION_NO,
    CASE
      WHEN EXISTS (
        SELECT 1
        FROM einvoice_seller_xsl_template_design d
       WHERE d.CONTENT_ID = xsl.XSL_ID
      ) OR EXISTS (
        SELECT 1
        FROM einvoice_seller_xsl_template_content c
       WHERE c.XSL_ID = xsl.XSL_ID
      ) THEN 1
      ELSE 0
    END AS HAS_XSL_TEMPLATE,
    xsl.IS_DEFAULT AS XSL_IS_DEFAULT,
    xsl.IS_ACTIVE AS XSL_IS_ACTIVE,
    s.CREATE_BY,
    s.CREATE_AT,
    s.UPDATE_BY,
    s.UPDATE_AT
  FROM einvoice_seller_info s
  INNER JOIN einvoice_seller_xsl_template xsl
    ON xsl.COMPANY_CD = s.COMPANY_CD
   AND xsl.ISDEL = 0
  LEFT JOIN einvoice_seller_xsl_template_content xslc
    ON xslc.XSL_ID = xsl.XSL_ID
  LEFT JOIN einvoice_seller_xsl_template_design xsld
    ON xsld.DESIGN_ID = xslc.CURRENT_DESIGN_ID
  LEFT JOIN einvoice_seller_xsl_template_design xsld1
    ON xsld1.CONTENT_ID = xsl.XSL_ID
   AND xsld1.DESIGN_ID = (
        SELECT MIN(d.DESIGN_ID)
          FROM einvoice_seller_xsl_template_design d
         WHERE d.CONTENT_ID = xsl.XSL_ID
      )
  WHERE s.COMPANY_CD = p_COMPANY_CD
    AND (IFNULL(p_INCLUDE_INACTIVE, 0) = 1 OR xsl.IS_ACTIVE = 1)
    AND (IFNULL(p_SELLER_ID, 0) = 0 OR s.SELLER_ID = p_SELLER_ID)
    AND (IFNULL(p_XSL_ID, 0) = 0 OR xsl.XSL_ID = p_XSL_ID)
    AND (
      IFNULL(p_XSL_ID, 0) > 0
      OR
      (IFNULL(p_INCLUDE_ALL_TEMPLATES, 0) = 1 AND IFNULL(p_KHHDON, '') = '')
      OR (IFNULL(p_KHHDON, '') <> '' AND xsl.KHHDON = TRIM(p_KHHDON))
      OR (IFNULL(p_KHHDON, '') = '' AND IFNULL(p_INCLUDE_ALL_TEMPLATES, 0) = 0 AND xsl.IS_DEFAULT = 1)
    )
    AND (
      p_KEYWORD IS NULL
      OR TRIM(p_KEYWORD) = ''
      OR s.SELLER_CD LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
      OR s.SELLER_NM LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
      OR s.SELLER_TAX_CD LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
      OR xsl.KHMSHDON LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
      OR xsl.KHHDON LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
      OR xsl.TEMPLATE_NM LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
    )
  ORDER BY s.SELLER_CD, s.SELLER_ID, xsl.IS_DEFAULT DESC, xsl.TEMPLATE_NM, xsl.XSL_ID;
END//
DELIMITER ;


