    d.LOGO_PATH,
    d.INVOICE_BACKGROUND_PATH,
    d.INVOICE_BORDER_PATH,
    d.BACKGROUND_PATH,
    1 AS IS_EDITABLE,
    IFNULL(template.IS_ACTIVE, 0) AS TEMPLATE_IS_ACTIVE,
    d.CREATE_AT,
    d.UPDATE_AT
  FROM einvoice_seller_xsl_template_design d
  INNER JOIN einvoice_seller_xsl_template template
    ON template.XSL_ID = d.CONTENT_ID
  WHERE template.COMPANY_CD = p_COMPANY_CD
    AND template.XSL_ID = p_XSL_ID
    AND template.ISDEL = 0
  ORDER BY d.DESIGN_ID DESC;
END//
DELIMITER ;


