-- Dumping structure for procedure am_web_001.getEInvoiceTbaoInfo
DROP PROCEDURE IF EXISTS `getEInvoiceTbaoInfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getEInvoiceTbaoInfo`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_TBAO_ID BIGINT,
  IN p_FROM_DATE DATE,
  IN p_TO_DATE DATE,
  IN p_KEYWORD VARCHAR(200),
  IN p_IS_SIGNED TINYINT
)
BEGIN
  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  SELECT
    TBAO_ID,
    COMPANY_CD,
    PBAN,
    MSO,
    TEN,
    LOAI,
    MCQT,
    TCQT,
    SO,
    NTBCCQT,
    MST,
    TNNT,
    DDANH,
    NTBAO,
    CASE WHEN IFNULL(p_TBAO_ID, 0) > 0 THEN XML ELSE NULL END AS XML,
    IFNULL(IS_SIGNED, 0) AS IS_SIGNED,
    IFNULL(IS_MAIL, 0) AS IS_MAIL,
    MGDDTU,
    MTDIEP,
    ERROR_MESSAGE,
    CREATE_BY,
    CREATE_AT,
    UPDATE_BY,
    UPDATE_AT,
    ISDEL
  FROM einvoice_tbao_info
  WHERE COMPANY_CD = p_COMPANY_CD
    AND ISDEL = 0
    AND (p_TBAO_ID IS NULL OR p_TBAO_ID = 0 OR TBAO_ID = p_TBAO_ID)
    AND (p_FROM_DATE IS NULL OR NTBAO >= p_FROM_DATE)
    AND (p_TO_DATE IS NULL OR NTBAO <= p_TO_DATE)
    AND (p_IS_SIGNED IS NULL OR IFNULL(IS_SIGNED, 0) = IFNULL(p_IS_SIGNED, 0))
    AND (
      p_KEYWORD IS NULL
      OR TRIM(p_KEYWORD) = ''
      OR CONCAT_WS(' ', MSO, TEN, MCQT, TCQT, SO, MST, TNNT, DDANH, MGDDTU, MTDIEP, ERROR_MESSAGE) LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
    )
  ORDER BY NTBAO DESC, TBAO_ID DESC;
END//
DELIMITER ;


