-- Dumping structure for procedure am_web_001.getEInvoiceTkhaiInfo
DROP PROCEDURE IF EXISTS `getEInvoiceTkhaiInfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getEInvoiceTkhaiInfo`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_TKHAI_ID BIGINT,
  IN p_FROM_DATE DATE,
  IN p_TO_DATE DATE,
  IN p_KEYWORD VARCHAR(200),
  IN p_IS_SIGNED TINYINT
)
BEGIN
  SELECT
    TKHAI_ID,
    COMPANY_CD,
    PBAN,
    MSO,
    TEN,
    HTHUC,
    TNNT,
    MST,
    CQTQLY,
    MCQTQLY,
    TNDDPLUAT,
    DTDDPLUAT,
    CCCDAN,
    SHCHIEU,
    MQTNDDPLUAT,
    QTICH,
    NSDDPLUAT,
    GTINH,
    DCLHE,
    DCTDTU,
    NLHE,
    DTLHE,
    DDANH,
    NLAP,
    CMA,
    CMTMTTIEN,
    KCMTMTTIEN,
    KCMA,
    NNTDBKKHAN,
    NNTKTDNUBND,
    CQXLTSCONG,
    CDLTTDCQT,
    CDLQTCTN,
    TCNNGOAI,
    CDDU,
    CDLTHDTHU,
    CBTHOP,
    CTTCTGDICH,
    HDGTGT,
    HDGTGTTHBLAI,
    HDBHANG,
    HDBHTHBLAI,
    HDTMAI,
    HDNCCNNGOAI,
    HDBTSCONG,
    HDBHDTQGIA,
    HDKHAC,
    CTU,
    CASE WHEN IFNULL(p_TKHAI_ID, 0) > 0 THEN MGDDTU ELSE NULL END AS MGDDTU,
    CASE WHEN IFNULL(p_TKHAI_ID, 0) > 0 THEN MTDIEP ELSE NULL END AS MTDIEP,
    CASE WHEN IFNULL(p_TKHAI_ID, 0) > 0 THEN XML ELSE NULL END AS XML,
    IFNULL(IS_SIGNED, 0) AS IS_SIGNED,
    IFNULL(CQT_STATUS, 0) AS CQT_STATUS,
    MCCQT,
    ERROR_MESSAGE,
    CREATE_BY,
    CREATE_AT,
    UPDATE_BY,
    UPDATE_AT,
    ISDEL
  FROM einvoice_tkhai_info
  WHERE COMPANY_CD = p_COMPANY_CD
    AND ISDEL = 0
    AND (p_TKHAI_ID IS NULL OR p_TKHAI_ID = 0 OR TKHAI_ID = p_TKHAI_ID)
    AND (p_FROM_DATE IS NULL OR NLAP >= p_FROM_DATE)
    AND (p_TO_DATE IS NULL OR NLAP <= p_TO_DATE)
    AND (p_IS_SIGNED IS NULL OR IFNULL(IS_SIGNED, 0) = IFNULL(p_IS_SIGNED, 0))
    AND (
      p_KEYWORD IS NULL
      OR TRIM(p_KEYWORD) = ''
      OR CONCAT_WS(' ', MSO, TEN, TNNT, MST, CQTQLY, MCQTQLY, TNDDPLUAT, DCLHE, DCTDTU, NLHE, DTLHE, DDANH, MGDDTU, MTDIEP, ERROR_MESSAGE) LIKE CONCAT('%', TRIM(p_KEYWORD), '%')
    )
  ORDER BY NLAP DESC, TKHAI_ID DESC;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getEInvoiceUserSetting
DROP PROCEDURE IF EXISTS `getEInvoiceUserSetting`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getEInvoiceUserSetting`(

  IN p_COMPANY_CD VARCHAR(20),

  IN p_SETTING_ID BIGINT UNSIGNED,

  IN p_USER_ID VARCHAR(50),

  IN p_KEYWORD VARCHAR(200),

  IN p_INCLUDE_DELETED TINYINT

)
BEGIN

  IF p_COMPANY_CD IS NULL THEN

    SET p_COMPANY_CD = '';

  END IF;



  SET p_COMPANY_CD = TRIM(p_COMPANY_CD);



  SELECT

    s.SETTING_ID,

    s.COMPANY_CD,

    s.USER_ID,

    s.SETTING_KEY,

    s.SETTING_VALUE,

    s.VALUE_TYPE,

    s.ISDEL,

    s.CREATE_AT,

    s.UPDATE_AT

  FROM einvoice_user_setting s

  WHERE (IFNULL(p_INCLUDE_DELETED, 0) = 1 OR s.ISDEL = 0)

    AND (IFNULL(p_SETTING_ID, 0) = 0 OR s.SETTING_ID = p_SETTING_ID)

    AND (s.COMPANY_CD = p_COMPANY_CD OR s.COMPANY_CD = '')

    AND (

      p_KEYWORD IS NULL

      OR TRIM(p_KEYWORD) = ''

      OR s.SETTING_KEY LIKE CONCAT('%', TRIM(p_KEYWORD), '%')

      OR s.SETTING_VALUE LIKE CONCAT('%', TRIM(p_KEYWORD), '%')

      OR s.USER_ID LIKE CONCAT('%', TRIM(p_KEYWORD), '%')

    )

    AND (

      IFNULL(p_SETTING_ID, 0) > 0

      OR p_COMPANY_CD = ''

      OR s.COMPANY_CD = p_COMPANY_CD

      OR (

        s.COMPANY_CD = ''

        AND NOT EXISTS (

          SELECT 1

            FROM einvoice_user_setting c

           WHERE c.COMPANY_CD = p_COMPANY_CD

             AND c.USER_ID = s.USER_ID

             AND c.SETTING_KEY = s.SETTING_KEY

             AND (IFNULL(p_INCLUDE_DELETED, 0) = 1 OR c.ISDEL = 0)

        )

      )

    )

    AND (

      IFNULL(p_SETTING_ID, 0) > 0

      OR p_USER_ID IS NULL

      OR TRIM(p_USER_ID) = ''

      OR s.USER_ID = TRIM(p_USER_ID)

      OR (

        s.USER_ID = ''

        AND NOT EXISTS (

          SELECT 1

            FROM einvoice_user_setting u

           WHERE u.SETTING_KEY = s.SETTING_KEY

             AND u.USER_ID = TRIM(p_USER_ID)

             AND (IFNULL(p_INCLUDE_DELETED, 0) = 1 OR u.ISDEL = 0)

             AND (

               u.COMPANY_CD = p_COMPANY_CD

               OR (

                 u.COMPANY_CD = ''

                 AND p_COMPANY_CD <> ''

                 AND NOT EXISTS (

                   SELECT 1

                     FROM einvoice_user_setting c

                    WHERE c.COMPANY_CD = p_COMPANY_CD

                      AND c.USER_ID = TRIM(p_USER_ID)

                      AND c.SETTING_KEY = s.SETTING_KEY

                      AND (IFNULL(p_INCLUDE_DELETED, 0) = 1 OR c.ISDEL = 0)

                 )

               )

             )

        )

      )

    )

  ORDER BY s.SETTING_KEY, s.USER_ID, s.COMPANY_CD DESC, s.SETTING_ID;

END//
DELIMITER ;


