CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getInventoryCogsBatch`(IN p_COMPANY_CD VARCHAR(20), IN p_INVENTORY_IDS TEXT)
BEGIN
    SELECT t.INVENTORY_ID,t.CHIT_ID_COGS,t.CHITDETAIL_ID_COGS,
        h.CHIT_ID,h.CHIT_CD,h.CHIT_NO,h.CHIT_YMD,h.AMOUNT,e.IS_LOCK,
        (h.CHIT_ID IS NOT NULL AND e.CHIT_ID IS NOT NULL) AS HEADER_VALID
    FROM chit_inventory_info t
    LEFT JOIN chitinfo h ON h.COMPANY_CD=t.COMPANY_CD AND h.CHIT_ID=t.CHIT_ID_COGS
        AND h.ISDEL='0' AND h.CHIT_TYPE IN ('OT','IO_COGS') AND h.INPUT_TYPE='AR'
        AND h.CHIT_YMD=t.INVENTORY_YMD
    LEFT JOIN chitinfo_ext e ON e.COMPANY_CD=h.COMPANY_CD AND e.CHIT_ID=h.CHIT_ID AND e.ISDEL='0'
    WHERE t.COMPANY_CD=p_COMPANY_CD AND t.ISDEL='0' AND t.CHIT_TYPE='IO'
        AND FIND_IN_SET(t.INVENTORY_ID,IFNULL(p_INVENTORY_IDS,''))>0;

    -- Aggregate each selected OT once, even when several IOs share it.
    SELECT d.CHIT_ID,COUNT(*) AS DETAIL_COUNT,COALESCE(SUM(d.AMOUNT),0) AS PERSISTED_TOTAL
    FROM (SELECT DISTINCT t.CHIT_ID_COGS FROM chit_inventory_info t
            WHERE t.COMPANY_CD=p_COMPANY_CD AND t.ISDEL='0' AND t.CHIT_TYPE='IO'
                AND FIND_IN_SET(t.INVENTORY_ID,IFNULL(p_INVENTORY_IDS,''))>0
                AND t.CHIT_ID_COGS IS NOT NULL) selected
    JOIN chitdetailinfo d ON d.COMPANY_CD=p_COMPANY_CD
        AND d.CHIT_ID=selected.CHIT_ID_COGS AND d.ISDEL='0'
    GROUP BY d.CHIT_ID;

    SELECT t.INVENTORY_ID,0 AS IS_LEGACY,0 AS OUTPUT_ID,
        d.CHITDETAIL_ID,d.CHITDETAIL_CD,d.DEBIT,d.CREDIT,d.AMOUNT
    FROM chit_inventory_info t
    JOIN chitinfo h ON h.COMPANY_CD=t.COMPANY_CD AND h.CHIT_ID=t.CHIT_ID_COGS
        AND h.ISDEL='0' AND h.CHIT_TYPE IN ('OT','IO_COGS') AND h.INPUT_TYPE='AR'
        AND h.CHIT_YMD=t.INVENTORY_YMD
    JOIN chitdetailinfo d ON d.COMPANY_CD=h.COMPANY_CD AND d.CHIT_ID=h.CHIT_ID
        AND d.CHIT_YMD=h.CHIT_YMD AND d.ISDEL='0' AND d.FC_TYPE='VND'
    JOIN chitdetailinfo_ext de ON de.COMPANY_CD=d.COMPANY_CD
        AND de.CHITDETAIL_ID=d.CHITDETAIL_ID AND de.ISDEL='0'
    WHERE t.COMPANY_CD=p_COMPANY_CD AND t.ISDEL='0' AND t.CHIT_TYPE='IO'
        AND FIND_IN_SET(t.INVENTORY_ID,IFNULL(p_INVENTORY_IDS,''))>0
        AND (t.CHITDETAIL_ID_COGS IS NULL OR d.CHITDETAIL_ID=t.CHITDETAIL_ID_COGS)
    UNION ALL
    SELECT t.INVENTORY_ID,1 AS IS_LEGACY,o.OUTPUT_ID,
        d.CHITDETAIL_ID,d.CHITDETAIL_CD,d.DEBIT,d.CREDIT,d.AMOUNT
    FROM chit_inventory_info t
    JOIN chitinfo h ON h.COMPANY_CD=t.COMPANY_CD AND h.CHIT_ID=t.CHIT_ID_COGS
        AND h.ISDEL='0' AND h.CHIT_TYPE IN ('OT','IO_COGS') AND h.INPUT_TYPE='AR'
        AND h.CHIT_YMD=t.INVENTORY_YMD
    JOIN chit_inventory_output o ON o.COMPANY_CD=t.COMPANY_CD
        AND o.INVENTORY_ID=t.INVENTORY_ID AND o.ISDEL='0'
    JOIN chitdetailinfo d ON d.COMPANY_CD=o.COMPANY_CD AND d.CHITDETAIL_ID=o.CHITDETAIL_ID_COGS
        AND d.CHIT_ID=h.CHIT_ID AND d.CHIT_YMD=h.CHIT_YMD AND d.ISDEL='0'
    WHERE t.COMPANY_CD=p_COMPANY_CD AND t.ISDEL='0' AND t.CHIT_TYPE='IO'
        AND FIND_IN_SET(t.INVENTORY_ID,IFNULL(p_INVENTORY_IDS,''))>0 AND t.CHITDETAIL_ID_COGS IS NULL;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getInventoryCogsForUpdate
DROP PROCEDURE IF EXISTS `getInventoryCogsForUpdate`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getInventoryCogsForUpdate`(IN p_COMPANY_CD VARCHAR(20), IN p_INVENTORY_ID BIGINT)
BEGIN
    DECLARE v_chit_id BIGINT DEFAULT NULL;
    DECLARE v_detail_id BIGINT DEFAULT NULL;
    DECLARE v_count BIGINT DEFAULT 0;
    DECLARE v_total DECIMAL(65,2) DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_chit_id=NULL;

    SELECT t.INVENTORY_ID,t.CHIT_ID_COGS,t.CHITDETAIL_ID_COGS,
        h.CHIT_ID,h.CHIT_CD,h.CHIT_NO,h.CHIT_YMD,h.AMOUNT,e.IS_LOCK,
        (h.CHIT_ID IS NOT NULL AND e.CHIT_ID IS NOT NULL) AS HEADER_VALID
    FROM chit_inventory_info t
    LEFT JOIN chitinfo h ON h.COMPANY_CD=t.COMPANY_CD AND h.CHIT_ID=t.CHIT_ID_COGS
        AND h.ISDEL='0' AND h.CHIT_TYPE IN ('OT','IO_COGS') AND h.INPUT_TYPE='AR'
        AND h.CHIT_YMD=t.INVENTORY_YMD
    LEFT JOIN chitinfo_ext e ON e.COMPANY_CD=h.COMPANY_CD AND e.CHIT_ID=h.CHIT_ID AND e.ISDEL='0'
    WHERE t.COMPANY_CD=p_COMPANY_CD AND t.ISDEL='0' AND t.CHIT_TYPE='IO'
        AND t.INVENTORY_ID=p_INVENTORY_ID FOR UPDATE;

    SELECT t.CHIT_ID_COGS,t.CHITDETAIL_ID_COGS INTO v_chit_id,v_detail_id
    FROM chit_inventory_info t WHERE t.COMPANY_CD=p_COMPANY_CD AND t.ISDEL='0' AND t.CHIT_TYPE='IO'
        AND t.INVENTORY_ID=p_INVENTORY_ID FOR UPDATE;
    SELECT COUNT(*),COALESCE(SUM(AMOUNT),0) INTO v_count,v_total
    FROM chitdetailinfo WHERE COMPANY_CD=p_COMPANY_CD AND CHIT_ID=v_chit_id AND ISDEL='0';
    SELECT v_chit_id AS CHIT_ID,v_count AS DETAIL_COUNT,v_total AS PERSISTED_TOTAL;

    IF v_detail_id IS NULL AND v_count>1 THEN
        SELECT t.INVENTORY_ID,1 AS IS_LEGACY,o.OUTPUT_ID,
        d.CHITDETAIL_ID,d.CHITDETAIL_CD,d.DEBIT,d.CREDIT,d.AMOUNT
    FROM chit_inventory_info t
    JOIN chitinfo h ON h.COMPANY_CD=t.COMPANY_CD AND h.CHIT_ID=t.CHIT_ID_COGS
        AND h.ISDEL='0' AND h.CHIT_TYPE IN ('OT','IO_COGS') AND h.INPUT_TYPE='AR'
        AND h.CHIT_YMD=t.INVENTORY_YMD
    JOIN chit_inventory_output o ON o.COMPANY_CD=t.COMPANY_CD
        AND o.INVENTORY_ID=t.INVENTORY_ID AND o.ISDEL='0'
    JOIN chitdetailinfo d ON d.COMPANY_CD=o.COMPANY_CD AND d.CHITDETAIL_ID=o.CHITDETAIL_ID_COGS
        AND d.CHIT_ID=h.CHIT_ID AND d.CHIT_YMD=h.CHIT_YMD AND d.ISDEL='0'
        WHERE t.COMPANY_CD=p_COMPANY_CD AND t.ISDEL='0' AND t.CHIT_TYPE='IO'
        AND t.INVENTORY_ID=p_INVENTORY_ID FOR UPDATE;
    ELSE
        SELECT t.INVENTORY_ID,0 AS IS_LEGACY,0 AS OUTPUT_ID,
        d.CHITDETAIL_ID,d.CHITDETAIL_CD,d.DEBIT,d.CREDIT,d.AMOUNT
    FROM chit_inventory_info t
    JOIN chitinfo h ON h.COMPANY_CD=t.COMPANY_CD AND h.CHIT_ID=t.CHIT_ID_COGS
        AND h.ISDEL='0' AND h.CHIT_TYPE IN ('OT','IO_COGS') AND h.INPUT_TYPE='AR'
        AND h.CHIT_YMD=t.INVENTORY_YMD
    JOIN chitdetailinfo d ON d.COMPANY_CD=h.COMPANY_CD AND d.CHIT_ID=h.CHIT_ID
        AND d.CHIT_YMD=h.CHIT_YMD AND d.ISDEL='0' AND d.FC_TYPE='VND'
    JOIN chitdetailinfo_ext de ON de.COMPANY_CD=d.COMPANY_CD
        AND de.CHITDETAIL_ID=d.CHITDETAIL_ID AND de.ISDEL='0'
        WHERE t.COMPANY_CD=p_COMPANY_CD AND t.ISDEL='0' AND t.CHIT_TYPE='IO'
        AND t.INVENTORY_ID=p_INVENTORY_ID
            AND (d.CHITDETAIL_ID=v_detail_id OR (v_detail_id IS NULL AND v_count=1))
        FOR UPDATE;
    END IF;

    SELECT * FROM chit_inventory_output
    WHERE COMPANY_CD=p_COMPANY_CD AND INVENTORY_ID=p_INVENTORY_ID AND ISDEL='0'
    ORDER BY SORT,OUTPUT_ID;
END//
DELIMITER ;


