-- Dumping structure for procedure am_web_001.getInventoryIssueLinksByCogsVoucher
DROP PROCEDURE IF EXISTS `getInventoryIssueLinksByCogsVoucher`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getInventoryIssueLinksByCogsVoucher`(
    IN p_companyCd VARCHAR(20),
    IN p_cogsVoucherId BIGINT,
    IN p_cogsDetailId BIGINT
)
BEGIN
    SELECT t.CHITDETAIL_ID_COGS AS CHITDETAIL_ID,t.INVENTORY_ID AS INVENTORY_CHIT_ID
    FROM chit_inventory_info t
    JOIN chitdetailinfo d ON d.COMPANY_CD=t.COMPANY_CD AND d.CHITDETAIL_ID=t.CHITDETAIL_ID_COGS
    AND d.CHIT_ID=t.CHIT_ID_COGS AND d.ISDEL='0'
    JOIN chitinfo h ON h.COMPANY_CD=d.COMPANY_CD AND h.CHIT_ID=d.CHIT_ID
    AND h.CHIT_TYPE='OT' AND h.INPUT_TYPE='AR' AND h.ISDEL='0'
    WHERE t.COMPANY_CD=p_companyCd AND t.CHIT_ID_COGS=p_cogsVoucherId
    AND t.CHIT_TYPE='IO' AND t.INPUT_TYPE='AR' AND t.ISDEL='0';

    SELECT transfer.INVENTORY_ID AS INVENTORY_CHIT_ID
    FROM chit_inventory_info transfer
    INNER JOIN chitinfo cogs
    ON cogs.COMPANY_CD=transfer.COMPANY_CD
    AND cogs.CHIT_ID=transfer.CHIT_ID_COGS
    AND cogs.CHIT_TYPE='OT'
    AND cogs.INPUT_TYPE='AR'
    AND cogs.ISDEL='0'
    WHERE transfer.COMPANY_CD=p_companyCd
    AND transfer.CHIT_TYPE='IO'
    AND transfer.INPUT_TYPE='AR'
    AND transfer.ISDEL='0'
    AND transfer.CHIT_ID_COGS=p_cogsVoucherId
    AND (p_cogsDetailId IS NULL OR transfer.CHITDETAIL_ID_COGS=p_cogsDetailId);
END//
DELIMITER ;


