-- Dumping structure for procedure am_web_001.getInventorySourceReference
DROP PROCEDURE IF EXISTS `getInventorySourceReference`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getInventorySourceReference`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_CHITDETAIL_ID BIGINT,
  IN p_CHIT_ID BIGINT,
  IN p_CHIT_CD VARCHAR(50),
  IN p_CHITDETAIL_CD VARCHAR(50)
)
BEGIN
  -- Prefer explicit detail id.
  IF IFNULL(p_CHITDETAIL_ID, 0) > 0 THEN
    SELECT
      h.CHIT_ID,
      h.CHIT_CD,
      h.CHIT_TYPE,
      d.CHITDETAIL_ID,
      d.CHITDETAIL_CD
    FROM chitdetailinfo d
    INNER JOIN chitinfo h
      ON h.COMPANY_CD = d.COMPANY_CD
     AND h.CHIT_ID = d.CHIT_ID
     AND IFNULL(h.ISDEL, '0') = '0'
    WHERE d.COMPANY_CD = p_COMPANY_CD
      AND d.CHITDETAIL_ID = p_CHITDETAIL_ID
      AND IFNULL(d.ISDEL, '0') = '0'
    LIMIT 1;
  ELSEIF IFNULL(p_CHIT_ID, 0) > 0 THEN
    -- Header id only: return first active detail (caller may only need CHIT_TYPE / CHIT_CD denorm).
    SELECT
      h.CHIT_ID,
      h.CHIT_CD,
      h.CHIT_TYPE,
      IFNULL(d.CHITDETAIL_ID, 0) AS CHITDETAIL_ID,
      IFNULL(d.CHITDETAIL_CD, '') AS CHITDETAIL_CD
    FROM chitinfo h
    LEFT JOIN chitdetailinfo d
      ON d.COMPANY_CD = h.COMPANY_CD
     AND d.CHIT_ID = h.CHIT_ID
     AND IFNULL(d.ISDEL, '0') = '0'
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.CHIT_ID = p_CHIT_ID
      AND IFNULL(h.ISDEL, '0') = '0'
    ORDER BY d.CHITDETAIL_ID
    LIMIT 1;
  ELSE
    -- Empty result set, correct column shape (MySQL needs FROM for WHERE).
    SELECT
      h.CHIT_ID,
      h.CHIT_CD,
      h.CHIT_TYPE,
      d.CHITDETAIL_ID,
      d.CHITDETAIL_CD
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
      ON d.COMPANY_CD = h.COMPANY_CD
     AND d.CHIT_ID = h.CHIT_ID
    WHERE 1 = 0;
  END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getInventorySourceVoucherByDetail
DROP PROCEDURE IF EXISTS `getInventorySourceVoucherByDetail`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getInventorySourceVoucherByDetail`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHITDETAIL_ID BIGINT
)
BEGIN
    SELECT
    header.CHIT_ID,
    header.CHIT_CD,
    header.CHIT_TYPE,
    detail.CHITDETAIL_ID,
    detail.CHITDETAIL_CD
    FROM chitdetailinfo detail
    INNER JOIN chitinfo header
    ON header.COMPANY_CD = detail.COMPANY_CD
    AND header.CHIT_ID = detail.CHIT_ID
    WHERE detail.COMPANY_CD = p_COMPANY_CD
    AND detail.CHITDETAIL_ID = p_CHITDETAIL_ID
    AND IFNULL(detail.ISDEL, '0') = '0'
    AND IFNULL(header.ISDEL, '0') = '0'
    AND IFNULL(header.CHIT_TYPE, '') IN ('PO', 'PD', 'PR', 'SO', 'SD', 'SR', 'OT')
    LIMIT 1;
END//
DELIMITER ;


