-- Dumping structure for procedure am_web_001.getNextEInvoiceBkeNo
DROP PROCEDURE IF EXISTS `getNextEInvoiceBkeNo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getNextEInvoiceBkeNo`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_YEAR INT
)
BEGIN
  DECLARE v_YEAR INT;
  DECLARE v_PREFIX VARCHAR(20);
  DECLARE v_LAST BIGINT DEFAULT 0;
  DECLARE v_FROM_BKE BIGINT DEFAULT 0;
  DECLARE v_FROM_RELATED BIGINT DEFAULT 0;

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  SET v_YEAR = IFNULL(NULLIF(p_YEAR, 0), YEAR(CURDATE()));
  SET v_PREFIX = CONCAT('BK-', v_YEAR, '-');

  SELECT IFNULL(MAX(
    CASE
      WHEN SBKE REGEXP CONCAT('^BK-', v_YEAR, '-[0-9]+$')
        THEN CAST(SUBSTRING_INDEX(SBKE, '-', -1) AS UNSIGNED)
      ELSE 0
    END
  ), 0)
  INTO v_FROM_BKE
  FROM einvoice_bke_info
  WHERE COMPANY_CD = p_COMPANY_CD
    AND ISDEL = 0
    AND SBKE LIKE CONCAT(v_PREFIX, '%');

  SELECT IFNULL(MAX(
    CASE
      WHEN SBKCLQUAN REGEXP CONCAT('^BK-', v_YEAR, '-[0-9]+$')
        THEN CAST(SUBSTRING_INDEX(SBKCLQUAN, '-', -1) AS UNSIGNED)
      ELSE 0
    END
  ), 0)
  INTO v_FROM_RELATED
  FROM einvoice_related_info
  WHERE COMPANY_CD = p_COMPANY_CD
    AND SBKCLQUAN LIKE CONCAT(v_PREFIX, '%');

  SET v_LAST = GREATEST(v_FROM_BKE, v_FROM_RELATED);

  SELECT
    CONCAT(v_PREFIX, LPAD(v_LAST + 1, 4, '0')) AS NEXT_SBKE,
    v_YEAR AS YEAR_NO,
    v_LAST + 1 AS SEQ_NO;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getNextEInvoiceShdon
DROP PROCEDURE IF EXISTS `getNextEInvoiceShdon`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getNextEInvoiceShdon`(

  IN p_COMPANY_CD VARCHAR(20),

  IN p_INVOICE_ID BIGINT,

  IN p_KHMSHDON VARCHAR(11),

  IN p_KHHDON VARCHAR(8)

)
BEGIN

  DECLARE v_KHMSHDON VARCHAR(11);

  DECLARE v_KHHDON VARCHAR(8);

  DECLARE v_FROM_SHDON BIGINT DEFAULT 1;

  DECLARE v_TO_SHDON BIGINT DEFAULT NULL;

  DECLARE v_LAST_SHDON BIGINT DEFAULT 0;

  DECLARE v_NEXT_NO BIGINT DEFAULT 1;

  DECLARE v_LAST_NLAP DATE DEFAULT NULL;



  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN

    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';

  END IF;



  SET v_KHMSHDON = TRIM(IFNULL(p_KHMSHDON, ''));

  SET v_KHHDON = TRIM(IFNULL(p_KHHDON, ''));



  SELECT

    CASE

      WHEN TRIM(IFNULL(FROM_SHDON, '')) REGEXP '^[0-9]+$' THEN CAST(TRIM(FROM_SHDON) AS UNSIGNED)

      ELSE 1

    END,

    CASE

      WHEN TRIM(IFNULL(TO_SHDON, '')) REGEXP '^[0-9]+$' THEN CAST(TRIM(TO_SHDON) AS UNSIGNED)

      ELSE NULL

    END

    INTO v_FROM_SHDON, v_TO_SHDON

    FROM einvoice_seller_xsl_template xsl

   WHERE xsl.COMPANY_CD = p_COMPANY_CD

     AND xsl.IS_ACTIVE = 1

     AND xsl.ISDEL = 0

     AND IFNULL(xsl.KHMSHDON, '') = v_KHMSHDON

     AND IFNULL(xsl.KHHDON, '') = v_KHHDON

   ORDER BY xsl.IS_DEFAULT DESC, xsl.XSL_ID

   LIMIT 1;



  IF v_FROM_SHDON IS NULL OR v_FROM_SHDON < 1 THEN

    SET v_FROM_SHDON = 1;

  END IF;



  SELECT IFNULL(MAX(CAST(SHDON AS UNSIGNED)), 0)

    INTO v_LAST_SHDON

    FROM einvoice_info

   WHERE COMPANY_CD = p_COMPANY_CD

     AND IFNULL(KHMSHDON, '') = v_KHMSHDON

     AND IFNULL(KHHDON, '') = v_KHHDON

     AND ISDEL = 0

     AND IFNULL(IS_SIGNED, 0) = 1

     AND SHDON REGEXP '^[0-9]+$'

     AND CAST(SHDON AS UNSIGNED) >= v_FROM_SHDON

     AND (v_TO_SHDON IS NULL OR CAST(SHDON AS UNSIGNED) <= v_TO_SHDON)

     AND (IFNULL(p_INVOICE_ID, 0) <= 0 OR INVOICE_ID <> p_INVOICE_ID);



  IF v_LAST_SHDON > 0 THEN

    SET v_NEXT_NO = v_LAST_SHDON + 1;

  ELSE

    SET v_NEXT_NO = v_FROM_SHDON;

  END IF;



  IF v_NEXT_NO < v_FROM_SHDON THEN

    SET v_NEXT_NO = v_FROM_SHDON;

  END IF;



  IF v_TO_SHDON IS NOT NULL AND v_NEXT_NO > v_TO_SHDON THEN

    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Exceeded maximum invoice number (TO_SHDON)';

  END IF;



  IF v_LAST_SHDON > 0 THEN

    SELECT NLAP

      INTO v_LAST_NLAP

      FROM einvoice_info

     WHERE COMPANY_CD = p_COMPANY_CD

       AND IFNULL(KHMSHDON, '') = v_KHMSHDON

       AND IFNULL(KHHDON, '') = v_KHHDON

       AND ISDEL = 0

       AND IFNULL(IS_SIGNED, 0) = 1

       AND SHDON REGEXP '^[0-9]+$'

       AND CAST(SHDON AS UNSIGNED) = v_LAST_SHDON

       AND (IFNULL(p_INVOICE_ID, 0) <= 0 OR INVOICE_ID <> p_INVOICE_ID)

     ORDER BY INVOICE_ID DESC

     LIMIT 1;

  END IF;



  SELECT CAST(v_NEXT_NO AS CHAR) AS NEXT_SHDON, v_LAST_NLAP AS LAST_NLAP;

END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getNextPitCtuNo
DROP PROCEDURE IF EXISTS `getNextPitCtuNo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getNextPitCtuNo`(IN p_company VARCHAR(20),IN p_id BIGINT)
BEGIN
 DECLARE v_series VARCHAR(6); DECLARE v_xsl BIGINT; DECLARE v_from BIGINT UNSIGNED DEFAULT 1;
 DECLARE v_to BIGINT UNSIGNED; DECLARE v_next BIGINT UNSIGNED;
 SELECT KHCTU,XSL_ID INTO v_series,v_xsl FROM pit_ctu_info WHERE COMPANY_CD=p_company AND CTU_ID=p_id AND IS_SIGNED=0 AND ISDEL=0;
 SELECT IFNULL(NULLIF(FROM_DOC_NO,0),1),NULLIF(TO_DOC_NO,0) INTO v_from,v_to FROM pit_xsl_template
  WHERE COMPANY_CD=p_company AND XSL_ID=v_xsl AND SERIES=v_series AND IS_ACTIVE=1 AND ISDEL=0 LIMIT 1;
 IF v_from IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='PIT series is not active'; END IF;
 SELECT GREATEST(v_from,IFNULL(MAX(SCTU),0)+1) INTO v_next FROM pit_ctu_info
  WHERE COMPANY_CD=p_company AND KHCTU=v_series AND IS_SIGNED=1 AND ISDEL=0 AND CTU_ID<>p_id;
 IF v_next>99999999 OR (v_to IS NOT NULL AND v_next>v_to) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='PIT number range exhausted'; END IF;
 SELECT v_next SCTU;
END//
DELIMITER ;


