-- Dumping structure for procedure am_web_001.getPitDocuments
DROP PROCEDURE IF EXISTS `getPitDocuments`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getPitDocuments`(
 IN p_company VARCHAR(20),IN p_kind VARCHAR(20),IN p_id BIGINT,IN p_from DATE,IN p_to DATE,
 IN p_keyword VARCHAR(200),IN p_signed TINYINT,IN p_cqt_status INT,IN p_offset INT,IN p_page_size INT)
BEGIN
 IF IFNULL(p_page_size,0)>0 THEN
  SELECT DOCUMENT_ID,KIND,DOC_VERSION,DOC_DATE,TAX_CD,DISPLAY_NAME,SERIES,XSL_ID,DOC_NO,
   DATA_JSON,IS_SIGNED,CQT_STATUS,ERROR_MESSAGE,MTDIEP,MGDDTU,QUEUED,UPDATE_BY,UPDATE_AT,
   CASE WHEN p_id>0 THEN RAW_XML END RAW_XML,CASE WHEN p_id>0 THEN SIGNED_XML END SIGNED_XML,CASE WHEN p_id>0 THEN RESPONSE_XML END RESPONSE_XML
  FROM pit_document WHERE COMPANY_CD=p_company AND KIND=p_kind AND ISDEL=0
   AND (IFNULL(p_id,0)=0 OR DOCUMENT_ID=p_id) AND (p_from IS NULL OR DOC_DATE>=p_from) AND (p_to IS NULL OR DOC_DATE<=p_to)
   AND (p_signed IS NULL OR IS_SIGNED=p_signed) AND (p_cqt_status IS NULL OR CQT_STATUS=p_cqt_status)
   AND (IFNULL(p_keyword,'')='' OR CONCAT_WS(' ',DISPLAY_NAME,TAX_CD,SERIES,DOC_NO) LIKE CONCAT('%',p_keyword,'%'))
  ORDER BY DOC_DATE DESC,DOCUMENT_ID DESC LIMIT p_offset,p_page_size;
 ELSE
  SELECT DOCUMENT_ID,KIND,DOC_VERSION,DOC_DATE,TAX_CD,DISPLAY_NAME,SERIES,XSL_ID,DOC_NO,
   DATA_JSON,IS_SIGNED,CQT_STATUS,ERROR_MESSAGE,MTDIEP,MGDDTU,QUEUED,UPDATE_BY,UPDATE_AT,
   CASE WHEN p_id>0 THEN RAW_XML END RAW_XML,CASE WHEN p_id>0 THEN SIGNED_XML END SIGNED_XML,CASE WHEN p_id>0 THEN RESPONSE_XML END RESPONSE_XML
  FROM pit_document WHERE COMPANY_CD=p_company AND KIND=p_kind AND ISDEL=0
   AND (IFNULL(p_id,0)=0 OR DOCUMENT_ID=p_id) AND (p_from IS NULL OR DOC_DATE>=p_from) AND (p_to IS NULL OR DOC_DATE<=p_to)
   AND (p_signed IS NULL OR IS_SIGNED=p_signed) AND (p_cqt_status IS NULL OR CQT_STATUS=p_cqt_status)
   AND (IFNULL(p_keyword,'')='' OR CONCAT_WS(' ',DISPLAY_NAME,TAX_CD,SERIES,DOC_NO) LIKE CONCAT('%',p_keyword,'%'))
  ORDER BY DOC_DATE DESC,DOCUMENT_ID DESC;
 END IF;
 SELECT COUNT(*) TOTAL_RECORDS FROM pit_document WHERE COMPANY_CD=p_company AND KIND=p_kind AND ISDEL=0
  AND (IFNULL(p_id,0)=0 OR DOCUMENT_ID=p_id) AND (p_from IS NULL OR DOC_DATE>=p_from) AND (p_to IS NULL OR DOC_DATE<=p_to)
  AND (p_signed IS NULL OR IS_SIGNED=p_signed) AND (p_cqt_status IS NULL OR CQT_STATUS=p_cqt_status)
  AND (IFNULL(p_keyword,'')='' OR CONCAT_WS(' ',DISPLAY_NAME,TAX_CD,SERIES,DOC_NO) LIKE CONCAT('%',p_keyword,'%'));
