-- Dumping structure for procedure am_web_001.getProductInfo
DROP PROCEDURE IF EXISTS `getProductInfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getProductInfo`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_PRODUCT_ID BIGINT
)
BEGIN
  SELECT
    pi.PRODUCT_ID,
    pi.COMPANY_CD,
    pi.PRODUCT_CD,
    pi.PRODUCT_NM_VIET,
    pi.PRODUCT_NM_ENG,
    pi.PRODUCT_NM_KOR,
    pi.PRODUCT_NM_CHINA,
    pi.PRODUCT_KIND_ID,
    pk.PRODUCT_KIND_CD,
    pk.PRODUCTKIND_NM_VIET,
    pi.UNIT_ID,
    pu.UNIT_CD,
    pu.UNIT_NM,
    pi.STORE_ID,
    si.STORE_CD,
    si.STORE_NM_VIET,
    pi.DIVISION,
    pi.SUMMARY,
    pi.ISDEL,
    pi.CREATE_BY,
    pi.UPDATE_BY
  FROM product_info pi
  LEFT JOIN product_kind pk
    ON pi.COMPANY_CD = pk.COMPANY_CD
   AND pi.PRODUCT_KIND_ID = pk.PRODUCT_KIND_ID
   AND IFNULL(pk.ISDEL, '0') != '1'
  LEFT JOIN product_unit pu
    ON pi.COMPANY_CD = pu.COMPANY_CD
   AND pi.UNIT_ID = pu.UNIT_ID
   AND IFNULL(pu.ISDEL, '0') != '1'
  LEFT JOIN store_info si
    ON pi.COMPANY_CD = si.COMPANY_CD
   AND pi.STORE_ID = si.STORE_ID
   AND IFNULL(si.ISDEL, '0') != '1'
  WHERE pi.COMPANY_CD = p_COMPANY_CD
    AND (p_PRODUCT_ID IS NULL OR p_PRODUCT_ID = 0 OR pi.PRODUCT_ID = p_PRODUCT_ID)
    AND IFNULL(pi.ISDEL, '0') != '1'
  ORDER BY pi.PRODUCT_CD, pi.PRODUCT_ID;
END//
DELIMITER ;


