-- Dumping structure for procedure am_web_001.getRecentUseInfo_Search
DROP PROCEDURE IF EXISTS `getRecentUseInfo_Search`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getRecentUseInfo_Search`(
	IN `p_COMPANY_CD` VARCHAR(20),
	IN `p_StartYMD` VARCHAR(8), 
	IN `p_EndYMD` VARCHAR(8),
	IN `p_ACC_CD` VARCHAR(20),
	IN `p_WHERE` VARCHAR(50)
)
BEGIN

	SELECT cdt.DEBIT,cdt.CREDIT,cdt.AMOUNT,cdt.FC_AMOUNT,cdt.FC_TYPE,cdt.FC_RATE,
			cdt_e.MG_CD, cdt_e.BANK_ID, cdt_e.CUSTOMER_ID
	
	FROM chitdetailinfo cdt
		INNER JOIN chitdetailinfo_ext cdt_e on cdt_e.COMPANY_CD = p_COMPANY_CD AND cdt_e.CHITDETAIL_ID = cdt.CHITDETAIL_ID and cdt_e.ISDEL <> '1'
		INNER JOIN chitinfo c ON c.COMPANY_CD = p_COMPANY_CD AND c.CHIT_CD = cdt.CHIT_CD and c.ISDEL != '1'
		
	WHERE cdt.COMPANY_CD = p_COMPANY_CD AND 
			cdt.chit_ymd BETWEEN p_StartYMD AND p_EndYMD AND 
			(cdt.ISDEL IS NULL OR cdt.ISDEL != '1') AND
			(
				(p_ACC_CD = '' OR (p_ACC_CD <> '' AND cdt.DEBIT like p_ACC_CD )) 
				or
				(p_ACC_CD = '' OR (p_ACC_CD <> '' AND cdt.CREDIT like p_ACC_CD ))
			)
	; 

END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getStoreInfo
DROP PROCEDURE IF EXISTS `getStoreInfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getStoreInfo`(
    IN p_COMPANY_CD   VARCHAR(20),
    IN p_STORE_ID  INT
)
BEGIN
    SELECT
    	ST.COMPANY_CD,
    	ST.STORE_ID,
		ST.STORE_CD,
		ST.STORE_NM_VIET,
		ST.STORE_NM_ENG,
		ST.STORE_NM_KOR,
		ST.STORE_NM_CHINA as __STORE_NM_CHINA,
		ST.STORE_KIND_ID,
		IFNULL(SK.STORE_KIND_CD,'') AS STORE_KIND_CD,
		IFNULL(SK.STORE_KIND_NM_VIET, '') AS STORE_KIND_NM_VIET,
		IFNULL(SK.STORE_KIND_NM_ENG, '') AS STORE_KIND_NM_ENG,
		IFNULL(SK.STORE_KIND_NM_KOR, '') AS STORE_KIND_NM_KOR,
		IFNULL(SK.STORE_KIND_NM_CHINA, '') AS __STORE_KIND_NM_CHINA,
		ST.SORT,
		ST.ISDEL,
		ST.CREATE_BY,
		ST.CREATE_AT,
		ST.UPDATE_BY,
		ST.UPDATE_AT
    FROM store_info ST
    LEFT JOIN store_kind_info SK ON  SK.COMPANY_CD  = ST.COMPANY_CD AND SK.STORE_KIND_ID = ST.STORE_KIND_ID AND SK.ISDEL = 0
    WHERE ST.COMPANY_CD = p_COMPANY_CD
      AND ST.ISDEL = 0
      AND (IFNULL(p_STORE_ID,0) = 0 OR  ST.STORE_ID = p_STORE_ID)
    ORDER BY ST.CREATE_AT DESC, ST.STORE_ID DESC;
END//
DELIMITER ;


