    IN p_OBJECT_TYPE VARCHAR(50),
    IN p_REQUESTED_CD VARCHAR(200),
    IN p_BASE_DATE DATETIME
)
BEGIN
    DECLARE prefix VARCHAR(30) DEFAULT '';
    DECLARE suffix VARCHAR(30) DEFAULT '';
    DECLARE codePattern VARCHAR(100) DEFAULT '{PREFIX}{NO}{SUFFIX}';
    DECLARE requestedCd VARCHAR(200) DEFAULT '';
    DECLARE currentNo BIGINT DEFAULT 0;
    DECLARE resolvedCurrentNo BIGINT DEFAULT 0;
    DECLARE numberLength INT DEFAULT 6;
    DECLARE resetType VARCHAR(20) DEFAULT 'NONE';
    DECLARE resetKey VARCHAR(20) DEFAULT '';
    DECLARE expectedResetKey VARCHAR(20) DEFAULT '';
    DECLARE nextNo BIGINT DEFAULT 0;
    DECLARE requestedNo BIGINT DEFAULT 0;
    DECLARE noText VARCHAR(100) DEFAULT '';
    DECLARE numericPart VARCHAR(100) DEFAULT '';
    DECLARE generatedCd VARCHAR(200) DEFAULT '';
    DECLARE finalCd VARCHAR(200) DEFAULT NULL;
    DECLARE wasSequenceUsed CHAR(1) DEFAULT '0';
    DECLARE wasUpdated CHAR(1) DEFAULT '0';
    DECLARE notFound INT DEFAULT 0;
    DECLARE noTokenPosition INT DEFAULT 0;
    DECLARE beforeNoPattern VARCHAR(100) DEFAULT '';
    DECLARE afterNoPattern VARCHAR(100) DEFAULT '';
    DECLARE beforeNo VARCHAR(200) DEFAULT '';
    DECLARE afterNo VARCHAR(200) DEFAULT '';

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET notFound = 1;

    IF p_BASE_DATE IS NULL THEN
        SET p_BASE_DATE = NOW();
    END IF;

    SET requestedCd = TRIM(COALESCE(p_REQUESTED_CD, ''));

    SELECT PREFIX, SUFFIX, IFNULL(CODE_PATTERN, '{PREFIX}{NO}{SUFFIX}'), CURRENT_NO, NUMBER_LENGTH, RESET_TYPE, RESET_KEY
    INTO prefix, suffix, codePattern, currentNo, numberLength, resetType, resetKey
    FROM sys_code_sequence
    WHERE COMPANY_CD = p_COMPANY_CD
      AND OBJECT_TYPE = p_OBJECT_TYPE
      AND IS_USE = '1'
    ORDER BY ID DESC
    LIMIT 1
    FOR UPDATE;

    IF notFound = 1 THEN
        IF requestedCd <> '' THEN
            SELECT requestedCd AS GENERATED_CD,
                   0 AS CURRENT_NO,
                   '0' AS WAS_SEQUENCE_USED,
                   '0' AS WAS_CURRENT_NO_UPDATED;
        ELSE
            SELECT NULL AS GENERATED_CD,
                   0 AS CURRENT_NO,
                   '0' AS WAS_SEQUENCE_USED,
                   '0' AS WAS_CURRENT_NO_UPDATED;
        END IF;
    ELSE
        SET wasSequenceUsed = '1';

        IF numberLength IS NULL OR numberLength <= 0 THEN
            SET numberLength = 6;
        END IF;

        SET codePattern = TRIM(IFNULL(codePattern, ''));
        IF codePattern = '' OR LOCATE('{NO}', UPPER(codePattern)) = 0 THEN
            SET codePattern = '{PREFIX}{NO}{SUFFIX}';
        END IF;

        IF resetType = 'YEAR' THEN
            SET expectedResetKey = DATE_FORMAT(p_BASE_DATE, '%Y');
        ELSEIF resetType = 'MONTH' THEN
            SET expectedResetKey = DATE_FORMAT(p_BASE_DATE, '%Y%m');
        ELSE
            SET expectedResetKey = resetKey;
        END IF;

        IF resetType <> 'NONE' AND resetKey <> expectedResetKey THEN
            SET currentNo = 0;
            SET resetKey = expectedResetKey;
        END IF;

        SET nextNo = currentNo + 1;
        SET resolvedCurrentNo = currentNo;
        SET noText = LPAD(CONVERT(nextNo, CHAR), numberLength, '0');
        SET generatedCd = codePattern;
        SET generatedCd = REPLACE(generatedCd, '{PREFIX}', IFNULL(prefix, ''));
        SET generatedCd = REPLACE(generatedCd, '{YYYY}', DATE_FORMAT(p_BASE_DATE, '%Y'));
        SET generatedCd = REPLACE(generatedCd, '{YY}', DATE_FORMAT(p_BASE_DATE, '%y'));
        SET generatedCd = REPLACE(generatedCd, '{MM}', DATE_FORMAT(p_BASE_DATE, '%m'));
        SET generatedCd = REPLACE(generatedCd, '{DD}', DATE_FORMAT(p_BASE_DATE, '%d'));
        SET generatedCd = REPLACE(generatedCd, '{NO}', noText);
        SET generatedCd = REPLACE(generatedCd, '{SUFFIX}', IFNULL(suffix, ''));

        IF requestedCd = '' OR UPPER(TRIM(requestedCd)) = UPPER(TRIM(generatedCd)) THEN
            SET finalCd = generatedCd;
            SET resolvedCurrentNo = nextNo;
            SET wasUpdated = '1';
        ELSE
            SET finalCd = requestedCd;
            SET noTokenPosition = LOCATE('{NO}', UPPER(codePattern));

            IF noTokenPosition > 0 THEN
                SET beforeNoPattern = SUBSTRING(codePattern, 1, noTokenPosition - 1);
                SET afterNoPattern = SUBSTRING(codePattern, noTokenPosition + 4);

                SET beforeNo = beforeNoPattern;
                SET beforeNo = REPLACE(beforeNo, '{PREFIX}', IFNULL(prefix, ''));
                SET beforeNo = REPLACE(beforeNo, '{YYYY}', DATE_FORMAT(p_BASE_DATE, '%Y'));
                SET beforeNo = REPLACE(beforeNo, '{YY}', DATE_FORMAT(p_BASE_DATE, '%y'));
                SET beforeNo = REPLACE(beforeNo, '{MM}', DATE_FORMAT(p_BASE_DATE, '%m'));
                SET beforeNo = REPLACE(beforeNo, '{DD}', DATE_FORMAT(p_BASE_DATE, '%d'));
                SET beforeNo = REPLACE(beforeNo, '{SUFFIX}', IFNULL(suffix, ''));

                SET afterNo = afterNoPattern;
                SET afterNo = REPLACE(afterNo, '{PREFIX}', IFNULL(prefix, ''));
                SET afterNo = REPLACE(afterNo, '{YYYY}', DATE_FORMAT(p_BASE_DATE, '%Y'));
                SET afterNo = REPLACE(afterNo, '{YY}', DATE_FORMAT(p_BASE_DATE, '%y'));
                SET afterNo = REPLACE(afterNo, '{MM}', DATE_FORMAT(p_BASE_DATE, '%m'));
                SET afterNo = REPLACE(afterNo, '{DD}', DATE_FORMAT(p_BASE_DATE, '%d'));
                SET afterNo = REPLACE(afterNo, '{SUFFIX}', IFNULL(suffix, ''));

                IF CHAR_LENGTH(requestedCd) = CHAR_LENGTH(beforeNo) + numberLength + CHAR_LENGTH(afterNo)
                   AND (beforeNo = '' OR LEFT(requestedCd, CHAR_LENGTH(beforeNo)) = beforeNo)
                   AND (afterNo = '' OR RIGHT(requestedCd, CHAR_LENGTH(afterNo)) = afterNo) THEN
                    SET numericPart = SUBSTRING(requestedCd, CHAR_LENGTH(beforeNo) + 1, numberLength);

                    IF numericPart REGEXP '^[0-9]+$' THEN
                        SET requestedNo = CAST(numericPart AS UNSIGNED);

                        IF requestedNo >= nextNo THEN
                            SET resolvedCurrentNo = requestedNo;
                            SET wasUpdated = '1';
                        END IF;
                    END IF;
                END IF;
            END IF;

            IF wasUpdated = '0' AND CHAR_LENGTH(requestedCd) >= numberLength THEN
                SET numericPart = RIGHT(requestedCd, numberLength);

                IF numericPart REGEXP '^[0-9]+$' THEN
                    SET requestedNo = CAST(numericPart AS UNSIGNED);

                    IF requestedNo >= nextNo THEN
                        SET resolvedCurrentNo = requestedNo;
                        SET wasUpdated = '1';
                    END IF;
                END IF;
            END IF;
        END IF;

        IF wasUpdated = '1' THEN
            UPDATE sys_code_sequence
            SET CURRENT_NO = resolvedCurrentNo,
                RESET_KEY = resetKey,
                UPDATE_AT = NOW()
            WHERE COMPANY_CD = p_COMPANY_CD
              AND OBJECT_TYPE = p_OBJECT_TYPE
              AND IS_USE = '1'
            ORDER BY ID DESC
            LIMIT 1;
        END IF;

        SELECT finalCd AS GENERATED_CD,
               resolvedCurrentNo AS CURRENT_NO,
               wasSequenceUsed AS WAS_SEQUENCE_USED,
               wasUpdated AS WAS_CURRENT_NO_UPDATED;
    END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getSysCodeSequencePreview
DROP PROCEDURE IF EXISTS `getSysCodeSequencePreview`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getSysCodeSequencePreview`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_OBJECT_TYPE VARCHAR(50),
    IN p_BASE_DATE DATETIME
)
BEGIN
    DECLARE v_currentNo BIGINT DEFAULT 0;
    DECLARE v_numberLength INT DEFAULT 6;
    DECLARE v_menuCode VARCHAR(80) DEFAULT '';
    DECLARE v_codeField VARCHAR(80) DEFAULT '';
    DECLARE v_prefix VARCHAR(30) DEFAULT '';
    DECLARE v_suffix VARCHAR(30) DEFAULT '';
    DECLARE v_codePattern VARCHAR(100) DEFAULT '{PREFIX}{NO}{SUFFIX}';
    DECLARE v_resetType VARCHAR(20) DEFAULT 'NONE';
    DECLARE v_resetKey VARCHAR(20) DEFAULT '';
    DECLARE v_nextNo BIGINT DEFAULT 1;
    DECLARE v_noText VARCHAR(100) DEFAULT '';
    DECLARE v_generatedCd VARCHAR(200) DEFAULT '';
    DECLARE v_expectedResetKey VARCHAR(20) DEFAULT '';
    DECLARE v_baseDate DATETIME;
    DECLARE v_notFound INT DEFAULT 0;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_notFound = 1;

    SET v_baseDate = IFNULL(p_BASE_DATE, NOW());

    IF UPPER(TRIM(IFNULL(p_OBJECT_TYPE, ''))) = '' THEN
        SELECT
            NULL AS OBJECT_TYPE,
            NULL AS MENU_CODE,
            NULL AS CODE_FIELD,
            NULL AS NEXT_CD,
            NULL AS PREFIX,
            NULL AS SUFFIX,
            '{PREFIX}{NO}{SUFFIX}' AS CODE_PATTERN,
            0 AS CURRENT_NO,
            0 AS NEXT_NO,
            0 AS NUMBER_LENGTH,
            NULL AS RESET_TYPE,
            NULL AS RESET_KEY;
    ELSE
        SET v_notFound = 0;

        SELECT
            s.PREFIX,
            IFNULL(s.MENU_CODE, ''),
            IFNULL(s.CODE_FIELD, ''),
            s.SUFFIX,
            IFNULL(s.CODE_PATTERN, '{PREFIX}{NO}{SUFFIX}'),
            s.CURRENT_NO,
            s.NUMBER_LENGTH,
            s.RESET_TYPE,
            s.RESET_KEY
        INTO
            v_prefix,
            v_menuCode,
            v_codeField,
            v_suffix,
            v_codePattern,
            v_currentNo,
            v_numberLength,
            v_resetType,
            v_resetKey
        FROM sys_code_sequence s
        WHERE s.COMPANY_CD = p_COMPANY_CD
          AND s.OBJECT_TYPE = p_OBJECT_TYPE
          AND s.IS_USE = '1'
        ORDER BY s.ID DESC
        LIMIT 1;

        IF v_notFound = 1 THEN
            SELECT
                p_OBJECT_TYPE AS OBJECT_TYPE,
                NULL AS MENU_CODE,
                NULL AS CODE_FIELD,
                NULL AS NEXT_CD,
                NULL AS PREFIX,
                NULL AS SUFFIX,
                '{PREFIX}{NO}{SUFFIX}' AS CODE_PATTERN,
                0 AS CURRENT_NO,
                0 AS NEXT_NO,
                0 AS NUMBER_LENGTH,
                NULL AS RESET_TYPE,
                NULL AS RESET_KEY;
        ELSE
            IF v_numberLength IS NULL OR v_numberLength <= 0 THEN
                SET v_numberLength = 6;
            END IF;

            SET v_codePattern = TRIM(IFNULL(v_codePattern, ''));
            IF v_codePattern = '' OR LOCATE('{NO}', UPPER(v_codePattern)) = 0 THEN
                SET v_codePattern = '{PREFIX}{NO}{SUFFIX}';
            END IF;

            IF UPPER(TRIM(IFNULL(v_resetType, 'NONE'))) = 'YEAR' THEN
                SET v_expectedResetKey = DATE_FORMAT(v_baseDate, '%Y');
            ELSEIF UPPER(TRIM(IFNULL(v_resetType, 'NONE'))) = 'MONTH' THEN
                SET v_expectedResetKey = DATE_FORMAT(v_baseDate, '%Y%m');
            ELSE
                SET v_expectedResetKey = '';
            END IF;

            IF UPPER(TRIM(IFNULL(v_resetType, 'NONE'))) <> 'NONE'
               AND IFNULL(v_resetKey, '') <> v_expectedResetKey THEN
                SET v_currentNo = 0;
            END IF;

            SET v_nextNo = v_currentNo + 1;
            SET v_noText = LPAD(CONVERT(v_nextNo, CHAR), v_numberLength, '0');
            SET v_generatedCd = v_codePattern;
            SET v_generatedCd = REPLACE(v_generatedCd, '{PREFIX}', IFNULL(v_prefix, ''));
            SET v_generatedCd = REPLACE(v_generatedCd, '{YYYY}', DATE_FORMAT(v_baseDate, '%Y'));
            SET v_generatedCd = REPLACE(v_generatedCd, '{YY}', DATE_FORMAT(v_baseDate, '%y'));
            SET v_generatedCd = REPLACE(v_generatedCd, '{MM}', DATE_FORMAT(v_baseDate, '%m'));
            SET v_generatedCd = REPLACE(v_generatedCd, '{DD}', DATE_FORMAT(v_baseDate, '%d'));
            SET v_generatedCd = REPLACE(v_generatedCd, '{NO}', v_noText);
            SET v_generatedCd = REPLACE(v_generatedCd, '{SUFFIX}', IFNULL(v_suffix, ''));

            SELECT
                p_OBJECT_TYPE AS OBJECT_TYPE,
                v_menuCode AS MENU_CODE,
                v_codeField AS CODE_FIELD,
                v_generatedCd AS NEXT_CD,
                v_prefix AS PREFIX,
                v_suffix AS SUFFIX,
                v_codePattern AS CODE_PATTERN,
                v_currentNo AS CURRENT_NO,
                v_nextNo AS NEXT_NO,
                v_numberLength AS NUMBER_LENGTH,
                v_resetType AS RESET_TYPE,
                v_expectedResetKey AS RESET_KEY;
        END IF;
    END IF;
END//
DELIMITER ;


