-- Dumping structure for procedure am_web_001.getSysNotification
DROP PROCEDURE IF EXISTS `getSysNotification`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getSysNotification`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_USER_ID VARCHAR(50),
    IN p_ROLE_CD VARCHAR(50),
    IN p_IS_READ CHAR(1),
    IN p_NOTIFICATION_TYPE VARCHAR(50),
    IN p_SOURCE_MODULE VARCHAR(50),
    IN p_KEYWORD VARCHAR(255),
    IN p_PAGE_NUMBER INT,
    IN p_PAGE_SIZE INT
)
BEGIN
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_page_number INT DEFAULT 1;
    DECLARE v_page_size INT DEFAULT 20;

    SET v_page_number = IFNULL(p_PAGE_NUMBER, 1);
    SET v_page_size = IFNULL(p_PAGE_SIZE, 20);

    IF v_page_number < 1 THEN
        SET v_page_number = 1;
    END IF;

    IF v_page_size < 1 THEN
        SET v_page_size = 20;
    END IF;

    IF v_page_size > 200 THEN
        SET v_page_size = 200;
    END IF;

    SET v_offset = (v_page_number - 1) * v_page_size;

    SELECT COUNT(*) AS TOTAL_COUNT
    FROM sys_notification n
    WHERE n.COMPANY_CD = p_COMPANY_CD
      AND (n.EXPIRED_AT IS NULL OR n.EXPIRED_AT > NOW())
      AND (p_IS_READ IS NULL OR p_IS_READ = '' OR n.IS_READ = p_IS_READ)
      AND (p_NOTIFICATION_TYPE IS NULL OR p_NOTIFICATION_TYPE = '' OR n.NOTIFICATION_TYPE = p_NOTIFICATION_TYPE)
      AND (p_SOURCE_MODULE IS NULL OR p_SOURCE_MODULE = '' OR n.SOURCE_MODULE = p_SOURCE_MODULE)
      AND (
            p_KEYWORD IS NULL OR p_KEYWORD = ''
            OR n.TITLE LIKE CONCAT('%', p_KEYWORD, '%')
            OR n.MESSAGE LIKE CONCAT('%', p_KEYWORD, '%')
          )
      AND (
            (n.USER_ID IS NULL AND n.ROLE_CD IS NULL)
            OR (p_USER_ID IS NOT NULL AND p_USER_ID <> '' AND n.USER_ID = p_USER_ID)
            OR (p_ROLE_CD IS NOT NULL AND p_ROLE_CD <> '' AND n.ROLE_CD = p_ROLE_CD)
            OR (p_USER_ID IS NOT NULL AND p_USER_ID <> '' AND n.USER_ID IS NULL AND n.ROLE_CD IS NULL)
          );

    SELECT
        n.ID,
        n.COMPANY_CD,
        n.USER_ID,
        n.ROLE_CD,
        n.NOTIFICATION_TYPE,
        n.SOURCE_MODULE,
        n.SOURCE_ID,
        n.TITLE,
        n.MESSAGE,
        n.PRIORITY,
        n.ACTION_URL,
        n.IS_READ,
        n.READ_AT,
        n.CREATE_BY,
        n.CREATE_AT,
        n.EXPIRED_AT
    FROM sys_notification n
    WHERE n.COMPANY_CD = p_COMPANY_CD
      AND (n.EXPIRED_AT IS NULL OR n.EXPIRED_AT > NOW())
      AND (p_IS_READ IS NULL OR p_IS_READ = '' OR n.IS_READ = p_IS_READ)
      AND (p_NOTIFICATION_TYPE IS NULL OR p_NOTIFICATION_TYPE = '' OR n.NOTIFICATION_TYPE = p_NOTIFICATION_TYPE)
      AND (p_SOURCE_MODULE IS NULL OR p_SOURCE_MODULE = '' OR n.SOURCE_MODULE = p_SOURCE_MODULE)
      AND (
            p_KEYWORD IS NULL OR p_KEYWORD = ''
            OR n.TITLE LIKE CONCAT('%', p_KEYWORD, '%')
            OR n.MESSAGE LIKE CONCAT('%', p_KEYWORD, '%')
          )
      AND (
            (n.USER_ID IS NULL AND n.ROLE_CD IS NULL)
            OR (p_USER_ID IS NOT NULL AND p_USER_ID <> '' AND n.USER_ID = p_USER_ID)
            OR (p_ROLE_CD IS NOT NULL AND p_ROLE_CD <> '' AND n.ROLE_CD = p_ROLE_CD)
            OR (p_USER_ID IS NOT NULL AND p_USER_ID <> '' AND n.USER_ID IS NULL AND n.ROLE_CD IS NULL)
          )
    ORDER BY n.IS_READ ASC, n.CREATE_AT DESC, n.ID DESC
    LIMIT v_offset, v_page_size;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.getSysNotificationSummary
DROP PROCEDURE IF EXISTS `getSysNotificationSummary`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `getSysNotificationSummary`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_USER_ID VARCHAR(50),
    IN p_ROLE_CD VARCHAR(50)
)
BEGIN
    SELECT
        COUNT(*) AS TOTAL_COUNT,
        SUM(CASE WHEN n.IS_READ = 'N' THEN 1 ELSE 0 END) AS UNREAD_COUNT
    FROM sys_notification n
    WHERE n.COMPANY_CD = p_COMPANY_CD
      AND (n.EXPIRED_AT IS NULL OR n.EXPIRED_AT > NOW())
      AND (
            (n.USER_ID IS NULL AND n.ROLE_CD IS NULL)
            OR (p_USER_ID IS NOT NULL AND p_USER_ID <> '' AND n.USER_ID = p_USER_ID)
            OR (p_ROLE_CD IS NOT NULL AND p_ROLE_CD <> '' AND n.ROLE_CD = p_ROLE_CD)
            OR (p_USER_ID IS NOT NULL AND p_USER_ID <> '' AND n.USER_ID IS NULL AND n.ROLE_CD IS NULL)
          );
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.get_before_states
DROP PROCEDURE IF EXISTS `get_before_states`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `get_before_states`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_OPEN_YMD CHAR(8),
    IN p_KEYWORD VARCHAR(100)
)
BEGIN
    SELECT
        A.ID,
        A.COMPANY_CD,
        A.OPEN_YMD,
        A.ACC_CD,
   	  IFNULL(B.ACCTITLE_NM_KOR,'') AS ACC_NM_KOR,
        IFNULL(B.ACCTITLE_NM_ENG,'') AS ACC_NM_ENG, 
        IFNULL(B.ACCTITLE_NM_VIET,'') AS ACC_NM_VIET,
        IFNULL(B.ACCTITLE_NM_JAPAN,'') AS ACC_NM_JAPAN,
        IFNULL(B.ACCTITLE_NM_CHINA,'') AS ACC_NM_CHINA,
        A.FC_TYPE,
        A.DEBIT,
        A.CREDIT,
        A.DEBIT_FC,
        A.CREDIT_FC,
        A.EXCHANGE_RATE,
        A.SUMMARY,
        A.NOTE,
        A.ISDEL,
        A.CREATE_BY,
        A.CREATE_AT,
        A.UPDATE_BY,
        A.UPDATE_AT
    FROM before_states A
    LEFT JOIN acclist_info B ON A.ACC_CD = B.ACC_CD AND IFNULL(B.ISDEL,'')!=1 AND IFNULL(B.ISABLEINPUT,'')=1
    WHERE A.COMPANY_CD = p_COMPANY_CD
      AND (p_OPEN_YMD = '' OR A.OPEN_YMD = p_OPEN_YMD)
      AND A.ISDEL = '0'
      AND (
            IFNULL(p_KEYWORD, '') = ''
            OR A.ACC_CD LIKE CONCAT('%', p_KEYWORD, '%')
            OR A.SUMMARY LIKE CONCAT('%', p_KEYWORD, '%')
            OR A.NOTE LIKE CONCAT('%', p_KEYWORD, '%')
          )
    ORDER BY A.ACC_CD, A.FC_TYPE, A.ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.get_before_states_bank
DROP PROCEDURE IF EXISTS `get_before_states_bank`;
