)
BEGIN
    SELECT
        A.ID,
        A.COMPANY_CD,
        A.OPEN_YMD,
        A.BANK_ID,
        C.BANK_CD,
        A.BANK_ACCOUNT_NO,
        C.BANK_NM,
        A.ACC_ID,
        A.ACC_CD,
        IFNULL(B.ACCTITLE_NM_KOR,'') AS ACC_NM_KOR,
        IFNULL(B.ACCTITLE_NM_ENG,'') AS ACC_NM_ENG, 
        IFNULL(B.ACCTITLE_NM_VIET,'') AS ACC_NM_VIET,
        IFNULL(B.ACCTITLE_NM_JAPAN,'') AS ACC_NM_JAPAN,
        IFNULL(B.ACCTITLE_NM_CHINA,'') AS ACC_NM_CHINA,
        A.FC_TYPE,
        A.DEBIT,
        A.CREDIT,
        A.DEBIT_FC,
        A.CREDIT_FC,
        A.EXCHANGE_RATE,
        A.SUMMARY,
        A.NOTE,
        A.ISDEL,
        A.CREATE_BY,
        A.CREATE_AT,
        A.UPDATE_BY,
        A.UPDATE_AT
    FROM before_states_bank A
    LEFT JOIN acclist_info B ON A.ACC_CD = B.ACC_CD AND IFNULL(B.ISDEL,'') !=1 AND IFNULL(B.ISABLEINPUT,'')=1
    LEFT JOIN bank_info C ON A.BANK_ID = C.BANK_ID AND IFNULL(C.ISDEL,'') != 1
    WHERE A.COMPANY_CD = p_COMPANY_CD
      AND (p_OPEN_YMD = '' OR A.OPEN_YMD = p_OPEN_YMD)
      AND A.ISDEL = '0'
      AND (
            IFNULL(p_KEYWORD, '') = ''
            OR A.BANK_NM LIKE CONCAT('%', p_KEYWORD, '%')
            OR A.BANK_ACCOUNT_NO LIKE CONCAT('%', p_KEYWORD, '%')
            OR A.ACC_CD LIKE CONCAT('%', p_KEYWORD, '%')
            OR A.SUMMARY LIKE CONCAT('%', p_KEYWORD, '%')
            OR A.NOTE LIKE CONCAT('%', p_KEYWORD, '%')
          )
    ORDER BY A.BANK_ID, A.BANK_ACCOUNT_NO, A.ACC_CD, A.FC_TYPE, A.ID;
END//
