-- Dumping structure for procedure am_web_001.get_before_states_customer
DROP PROCEDURE IF EXISTS `get_before_states_customer`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `get_before_states_customer`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_OPEN_YMD CHAR(8),
    IN p_KEYWORD VARCHAR(100)
)
BEGIN

    SELECT
        A.ID,
        A.COMPANY_CD,
        A.OPEN_YMD,
        A.CUSTOMER_ID,
        C.CUSTOMER_CD,

        IFNULL(C.CUSTOMER_NM_VIET, '') AS CUSTOMER_NM_VIET,
        IFNULL(C.CUSTOMER_NM_ENG, '') AS CUSTOMER_NM_ENG,
        IFNULL(C.CUSTOMER_NM_KOR, '') AS CUSTOMER_NM_KOR,
        IFNULL(C.CUSTOMER_NM_CHINA, '') AS CUSTOMER_NM_CHINA,

        A.ACC_ID,
        A.ACC_CD,

        IFNULL(B.ACCTITLE_NM_KOR, '') AS ACC_NM_KOR,
        IFNULL(B.ACCTITLE_NM_ENG, '') AS ACC_NM_ENG,
        IFNULL(B.ACCTITLE_NM_VIET, '') AS ACC_NM_VIET,
        IFNULL(B.ACCTITLE_NM_JAPAN, '') AS ACC_NM_JAPAN,
        IFNULL(B.ACCTITLE_NM_CHINA, '') AS ACC_NM_CHINA,

        A.FC_TYPE,
        A.DEBIT,
        A.CREDIT,
        A.DEBIT_FC,
        A.CREDIT_FC,
        A.EXCHANGE_RATE,
        A.SUMMARY,
        A.NOTE,
        A.ISDEL,
        A.CREATE_BY,
        A.CREATE_AT,
        A.UPDATE_BY,
        A.UPDATE_AT

    FROM before_states_customer A

    LEFT JOIN acclist_info B
        ON A.COMPANY_CD = B.COMPANY_CD
        AND A.ACC_CD = B.ACC_CD
        AND IFNULL(B.ISDEL, '0') <> '1'
        AND IFNULL(B.ISABLEINPUT, '0') = '1'

    LEFT JOIN customer_info C
        ON A.COMPANY_CD = C.COMPANY_CD
        AND A.CUSTOMER_ID = C.CUSTOMER_ID
        AND IFNULL(C.ISDEL, '0') <> '1'

    WHERE A.COMPANY_CD = p_COMPANY_CD
      AND (IFNULL(p_OPEN_YMD, '') = '' OR A.OPEN_YMD = p_OPEN_YMD)
      AND IFNULL(A.ISDEL, '0') = '0'
      AND (
            IFNULL(p_KEYWORD, '') = ''
            OR C.CUSTOMER_CD LIKE CONCAT('%', p_KEYWORD, '%')
            OR C.CUSTOMER_NM_VIET LIKE CONCAT('%', p_KEYWORD, '%')
            OR C.CUSTOMER_NM_ENG LIKE CONCAT('%', p_KEYWORD, '%')
            OR C.CUSTOMER_NM_KOR LIKE CONCAT('%', p_KEYWORD, '%')
            OR A.ACC_CD LIKE CONCAT('%', p_KEYWORD, '%')
            OR A.SUMMARY LIKE CONCAT('%', p_KEYWORD, '%')
            OR A.NOTE LIKE CONCAT('%', p_KEYWORD, '%')
          )

    ORDER BY
        A.CUSTOMER_ID,
        A.ACC_CD,
        A.FC_TYPE,
        A.ID;

END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.get_before_states_department
