)
BEGIN
    SELECT
        A.ID,
        A.COMPANY_CD,
        A.OPEN_YMD,
        A.DEPARTMENT_ID,
        C.DEPARTMENT_CD,
        IFNULL(C.DEP_NAME_KOR,'') AS DEP_NM_KOR,
        IFNULL(C.DEP_NAME_ENG,'') AS DEP_NM_ENG, 
        IFNULL(C.DEP_NAME_VIET,'') AS DEP_NM_VIET,
        IFNULL(C.DEP_NAME_CHINA,'') AS DEP_NM_CHINA,
        A.ACC_ID,
        A.ACC_CD,
        IFNULL(B.ACCTITLE_NM_KOR,'') AS ACC_NM_KOR,
        IFNULL(B.ACCTITLE_NM_ENG,'') AS ACC_NM_ENG, 
        IFNULL(B.ACCTITLE_NM_VIET,'') AS ACC_NM_VIET,
        IFNULL(B.ACCTITLE_NM_JAPAN,'') AS ACC_NM_JAPAN,
        IFNULL(B.ACCTITLE_NM_CHINA,'') AS ACC_NM_CHINA,
        A.FC_TYPE,
        A.DEBIT,
        A.CREDIT,
        A.DEBIT_FC,
        A.CREDIT_FC,
        A.EXCHANGE_RATE,
        A.SUMMARY,
        A.NOTE,
        A.ISDEL,
        A.CREATE_BY,
        A.CREATE_AT,
        A.UPDATE_BY,
