    FROM before_states_department A
    LEFT JOIN acclist_info B ON A.ACC_CD = B.ACC_CD AND IFNULL(B.ISDEL,'') !=1 AND IFNULL(B.ISABLEINPUT,'')=1
    LEFT JOIN department_info C ON A.DEPARTMENT_ID = C.DEPARTMENT_ID AND IFNULL(C.ISDEL,'') != 1
    WHERE A.COMPANY_CD = p_COMPANY_CD
      AND (p_OPEN_YMD = '' OR A.OPEN_YMD = p_OPEN_YMD)
      AND A.ISDEL = '0'
      AND (
            IFNULL(p_KEYWORD, '') = ''
            OR A.DEPARTMENT_NM LIKE CONCAT('%', p_KEYWORD, '%')
            OR A.ACC_CD LIKE CONCAT('%', p_KEYWORD, '%')
            OR A.SUMMARY LIKE CONCAT('%', p_KEYWORD, '%')
            OR A.NOTE LIKE CONCAT('%', p_KEYWORD, '%')
          )
    ORDER BY A.DEPARTMENT_ID, A.ACC_CD, A.FC_TYPE, A.ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.get_cash_exchange_revaluation_currency_lookup
