CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `get_cash_exchange_revaluation_currency_lookup`(
    IN p_COMPANY_CD VARCHAR(20)
)
BEGIN
    SELECT DISTINCT
        UPPER(IFNULL(d.FC_TYPE, '')) AS FC_TYPE
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD
       AND d.CHIT_ID = h.CHIT_ID
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(h.ISDEL, '0') = '0'
      AND IFNULL(d.ISDEL, '0') = '0'
      AND IFNULL(d.FC_AMOUNT, 0) <> 0
      AND IFNULL(d.FC_TYPE, '') <> ''
      AND (
            IFNULL(d.DEBIT, '') LIKE '1112%'
            OR IFNULL(d.DEBIT, '') LIKE '1122%'
            OR IFNULL(d.CREDIT, '') LIKE '1112%'
            OR IFNULL(d.CREDIT, '') LIKE '1122%'
      )
    ORDER BY UPPER(IFNULL(d.FC_TYPE, ''));
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.get_cash_exchange_revaluation_history
DROP PROCEDURE IF EXISTS `get_cash_exchange_revaluation_history`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `get_cash_exchange_revaluation_history`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_RATE_DATE_FROM DATE,
    IN p_RATE_DATE_TO DATE,
    IN p_FC_TYPE VARCHAR(255)
)
BEGIN
    SELECT
        r.RESULT_ID,
        r.COMPANY_CD,
        r.MODULE_CD,
        r.CHIT_ID,
        r.CHITDETAIL_ID,
        r.CHIT_CD,
        r.CHIT_NO,
        r.CHIT_YMD,
        r.CHIT_TYPE,
        r.CHITDETAIL_CD,
        r.DEBIT,
        r.CREDIT,
        r.FC_TYPE,
        DATE_FORMAT(r.RATE_DATE, '%Y-%m-%d') AS RATE_DATE,
        r.FC_AMOUNT,
        r.OLD_RATE,
        r.NEW_RATE,
        r.OLD_AMOUNT,
        r.NEW_AMOUNT,
        r.EXCHANGE_DIFF,
        r.DIFF_TYPE,
        r.CREATE_BY,
        r.CREATE_AT
    FROM exchange_revaluation_result r
    WHERE r.COMPANY_CD = p_COMPANY_CD
      AND r.MODULE_CD = 'CA'
      AND IFNULL(r.ISDEL, '0') = '0'
      AND (p_RATE_DATE_FROM IS NULL OR r.RATE_DATE >= p_RATE_DATE_FROM)
      AND (p_RATE_DATE_TO IS NULL OR r.RATE_DATE <= p_RATE_DATE_TO)
      AND (IFNULL(p_FC_TYPE, '') = '' OR FIND_IN_SET(TRIM(IFNULL(r.FC_TYPE, '')), p_FC_TYPE) > 0)
    ORDER BY r.CREATE_AT DESC, r.RESULT_ID DESC;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.get_cash_exchange_revaluation_preview
DROP PROCEDURE IF EXISTS `get_cash_exchange_revaluation_preview`;
