-- Dumping structure for procedure am_web_001.get_exchange_revaluation_preview
DROP PROCEDURE IF EXISTS `get_exchange_revaluation_preview`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `get_exchange_revaluation_preview`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_MODULE_CD VARCHAR(10),
    IN p_RATE_DATE DATE,
    IN p_FC_TYPE VARCHAR(10),
    IN p_CHIT_YMD_FROM VARCHAR(8),
    IN p_CHIT_YMD_TO VARCHAR(8)
)
BEGIN
    SELECT
        UPPER(IFNULL(h.INPUT_TYPE, '')) AS MODULE_CD,
        h.COMPANY_CD,
        h.CHIT_ID,
        d.CHITDETAIL_ID,
        h.CHIT_CD,
        h.CHIT_NO,
        h.CHIT_YMD,
        h.CHIT_TYPE,
        d.CHITDETAIL_CD,
        d.DEBIT,
        d.CREDIT,
        IFNULL(d.FC_TYPE, '') AS FC_TYPE,
        IFNULL(d.FC_AMOUNT, 0) AS FC_AMOUNT,
        IFNULL(d.FC_RATE, 0) AS OLD_RATE,
        IFNULL(d.AMOUNT, 0) AS OLD_AMOUNT,
        IFNULL(d.FC_RATE, 0) AS NEW_RATE,
        CAST(IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0) AS DECIMAL(18,2)) AS NEW_AMOUNT,
        CAST((IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0)) - IFNULL(d.AMOUNT, 0) AS DECIMAL(18,2)) AS EXCHANGE_DIFF,
        CASE
            WHEN CAST((IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0)) - IFNULL(d.AMOUNT, 0) AS DECIMAL(18,2)) > 0 THEN 'GAIN'
            WHEN CAST((IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0)) - IFNULL(d.AMOUNT, 0) AS DECIMAL(18,2)) < 0 THEN 'LOSS'
            ELSE 'NONE'
        END AS DIFF_TYPE
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD
       AND d.CHIT_ID = h.CHIT_ID
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND UPPER(IFNULL(h.INPUT_TYPE, '')) IN ('AR', 'AP')
      AND (IFNULL(p_MODULE_CD, '') = '' OR UPPER(p_MODULE_CD) = 'ALL' OR UPPER(IFNULL(h.INPUT_TYPE, '')) = UPPER(p_MODULE_CD))
      AND (IFNULL(p_FC_TYPE, '') = '' OR IFNULL(d.FC_TYPE, '') = p_FC_TYPE)
      AND (IFNULL(p_CHIT_YMD_FROM, '') = '' OR IFNULL(h.CHIT_YMD, '') >= p_CHIT_YMD_FROM)
      AND (IFNULL(p_CHIT_YMD_TO, '') = '' OR IFNULL(h.CHIT_YMD, '') <= p_CHIT_YMD_TO)
      AND IFNULL(d.FC_AMOUNT, 0) <> 0
      AND IFNULL(h.ISDEL, '0') = '0'
      AND IFNULL(d.ISDEL, '0') = '0'
    ORDER BY h.CHIT_YMD, h.CHIT_NO, d.CHITDETAIL_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.get_inventory_update_in_price
DROP PROCEDURE IF EXISTS `get_inventory_update_in_price`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `get_inventory_update_in_price`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_STORE_CD VARCHAR(2000),
    IN p_FROM_YMD CHAR(8),
    IN p_TO_YMD CHAR(8)
)
BEGIN
    IF TRIM(IFNULL(p_COMPANY_CD, '')) = '' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
    END IF;
    IF p_FROM_YMD IS NULL OR p_TO_YMD IS NULL OR p_FROM_YMD > p_TO_YMD THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A valid FROM_YMD and TO_YMD are required';
    END IF;

    SELECT
        COALESCE(NULLIF(TRIM(i.PRODUCT_CD), ''), p.PRODUCT_CD, '') AS PRODUCT_CD,
        COALESCE(NULLIF(TRIM(p.PRODUCT_NM_VIET), ''), NULLIF(TRIM(p.PRODUCT_NM_ENG), ''), '') AS PRODUCT_NAME,
        COUNT(*) AS MOVEMENT_COUNT,
        SUM(IFNULL(i.QUANTITY, 0)) AS TOTAL_QUANTITY,
        MIN(IFNULL(i.UNIT_PRICE_CC, 0)) AS CURRENT_PRICE_MIN,
        MAX(IFNULL(i.UNIT_PRICE_CC, 0)) AS CURRENT_PRICE_MAX,
        SUM(IFNULL(i.AMOUNT_CC, IFNULL(i.QUANTITY, 0) * IFNULL(i.UNIT_PRICE_CC, 0))) AS CURRENT_AMOUNT
    FROM chit_inventory_input i
    LEFT JOIN chit_inventory_info transfer_h ON transfer_h.COMPANY_CD=i.COMPANY_CD AND transfer_h.INVENTORY_ID=i.INVENTORY_ID AND IFNULL(transfer_h.ISDEL,'0')='0'
    LEFT JOIN product_info p ON p.COMPANY_CD = i.COMPANY_CD AND p.PRODUCT_ID = i.PRODUCT_ID AND IFNULL(p.ISDEL, '0') = '0'
    LEFT JOIN store_info s ON s.COMPANY_CD=i.COMPANY_CD AND s.STORE_ID=i.STORE_ID AND IFNULL(s.ISDEL,'0')='0'
    WHERE i.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(i.ISDEL, '0') = '0'
      AND COALESCE(DATE_FORMAT(i.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(transfer_h.INVENTORY_YMD), '')) BETWEEN p_FROM_YMD AND p_TO_YMD
      AND (TRIM(IFNULL(p_STORE_CD, '')) = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(i.STORE_CD), ''), s.STORE_CD, ''), REPLACE(TRIM(IFNULL(p_STORE_CD, '')), '|', ',')) > 0)
    GROUP BY COALESCE(NULLIF(TRIM(i.PRODUCT_CD), ''), p.PRODUCT_CD, ''),
             COALESCE(NULLIF(TRIM(p.PRODUCT_NM_VIET), ''), NULLIF(TRIM(p.PRODUCT_NM_ENG), ''), '')
    ORDER BY PRODUCT_CD;
END//
DELIMITER ;


