        COUNT(*) AS MOVEMENT_COUNT,
        SUM(IFNULL(o.QUANTITY, 0)) AS TOTAL_QUANTITY,
        MIN(IFNULL(o.REVENUE_UNIT_PRICE_CC, 0)) AS CURRENT_PRICE_MIN,
        MAX(IFNULL(o.REVENUE_UNIT_PRICE_CC, 0)) AS CURRENT_PRICE_MAX,
        SUM(IFNULL(o.REVENUE_AMOUNT_CC, IFNULL(o.QUANTITY, 0) * IFNULL(o.REVENUE_UNIT_PRICE_CC, 0))) AS CURRENT_AMOUNT
    FROM chit_inventory_output o
    LEFT JOIN chit_inventory_info transfer_h ON transfer_h.COMPANY_CD=o.COMPANY_CD AND transfer_h.INVENTORY_ID=o.INVENTORY_ID AND IFNULL(transfer_h.ISDEL,'0')='0'
    LEFT JOIN product_info p ON p.COMPANY_CD = o.COMPANY_CD AND p.PRODUCT_ID = o.PRODUCT_ID AND IFNULL(p.ISDEL, '0') = '0'
    LEFT JOIN store_info s ON s.COMPANY_CD=o.COMPANY_CD AND s.STORE_ID=o.STORE_ID AND IFNULL(s.ISDEL,'0')='0'
    WHERE o.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(o.ISDEL, '0') = '0'
