      AND (TRIM(IFNULL(p_STORE_CD, '')) = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(o.STORE_CD), ''), s.STORE_CD, ''), REPLACE(TRIM(IFNULL(p_STORE_CD, '')), '|', ',')) > 0)
    GROUP BY COALESCE(NULLIF(TRIM(o.PRODUCT_CD), ''), p.PRODUCT_CD, ''),
             COALESCE(NULLIF(TRIM(p.PRODUCT_NM_VIET), ''), NULLIF(TRIM(p.PRODUCT_NM_ENG), ''), '')
