-- Dumping structure for procedure am_web_001.get_inventory_valuation_movements
DROP PROCEDURE IF EXISTS `get_inventory_valuation_movements`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `get_inventory_valuation_movements`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_YMD VARCHAR(8),
    IN p_TO_YMD VARCHAR(8),
    IN p_PRODUCT_CDS TEXT,
    IN p_STORE_CDS TEXT
)
BEGIN
    DECLARE v_product_cds TEXT;
    DECLARE v_store_cds TEXT;
    DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);

    SET v_product_cds = REPLACE(IFNULL(TRIM(p_PRODUCT_CDS), ''), '|', ',');
    SET v_store_cds = REPLACE(IFNULL(TRIM(p_STORE_CDS), ''), '|', ',');
    SET v_from_ymd = NULLIF(TRIM(IFNULL(p_FROM_YMD, '')), '');
    SET v_to_ymd = NULLIF(TRIM(IFNULL(p_TO_YMD, '')), '');

    IF v_from_ymd IS NULL OR v_to_ymd IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'FROM_YMD and TO_YMD are required';
    END IF;

    IF v_from_ymd > v_to_ymd THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'FROM_YMD must be less than or equal to TO_YMD';
    END IF;

    SELECT
        'INPUT' AS FLOW_TYPE,
        ii.COMPANY_CD,
        ii.INVENTORY_ID,
        ii.CHITDETAIL_ID,
        ii.CHIT_TYPE,
        COALESCE(NULLIF(ii.PRODUCT_CD, ''), product.PRODUCT_CD, '') AS PRODUCT_CD,
        COALESCE(NULLIF(product.PRODUCT_NM_VIET, ''), '') AS PRODUCT_NAME,
        COALESCE(NULLIF(ii.STORE_CD, ''), store_info.STORE_CD, '') AS STORE_CD,
        COALESCE(NULLIF(store_info.STORE_NM_VIET, ''), '') AS STORE_NAME,
        COALESCE(DATE_FORMAT(ii.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(transfer_h.INVENTORY_YMD), '')) AS TXN_YMD,
        COALESCE(NULLIF(TRIM(ii.INVENTORY_CD), ''), NULLIF(TRIM(transfer_h.INVENTORY_CD), ''), '') AS DOCUMENT_NO,
        IFNULL(ii.QUANTITY, 0) AS QUANTITY,
        IFNULL(ii.UNIT_PRICE_CC, 0) AS UNIT_PRICE_CC,
        IFNULL(ii.AMOUNT_CC, IFNULL(ii.QUANTITY, 0) * IFNULL(ii.UNIT_PRICE_CC, 0)) AS AMOUNT_CC,
        ii.STATE
    FROM chit_inventory_input ii
    LEFT JOIN chit_inventory_info transfer_h
        ON transfer_h.COMPANY_CD = ii.COMPANY_CD
       AND transfer_h.INVENTORY_ID = ii.INVENTORY_ID
       AND IFNULL(transfer_h.ISDEL, '0') = '0'
    LEFT JOIN product_info product
        ON product.COMPANY_CD = ii.COMPANY_CD
       AND product.PRODUCT_ID = ii.PRODUCT_ID
       AND IFNULL(product.ISDEL, '0') = '0'
    LEFT JOIN store_info
        ON store_info.COMPANY_CD = ii.COMPANY_CD
       AND store_info.STORE_ID = ii.STORE_ID
       AND IFNULL(store_info.ISDEL, '0') = '0'
    WHERE ii.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(ii.ISDEL, '0') = '0'
      AND COALESCE(DATE_FORMAT(ii.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(transfer_h.INVENTORY_YMD), '')) BETWEEN v_from_ymd AND v_to_ymd
      AND (v_product_cds = '' OR FIND_IN_SET(COALESCE(NULLIF(ii.PRODUCT_CD, ''), product.PRODUCT_CD, ''), v_product_cds) > 0)
      AND (v_store_cds = '' OR FIND_IN_SET(COALESCE(NULLIF(ii.STORE_CD, ''), store_info.STORE_CD, ''), v_store_cds) > 0)

    UNION ALL

    SELECT
        'OUTPUT' AS FLOW_TYPE,
        io.COMPANY_CD,
        io.INVENTORY_ID,
        io.CHITDETAIL_ID,
        io.CHIT_TYPE,
        COALESCE(NULLIF(io.PRODUCT_CD, ''), product.PRODUCT_CD, '') AS PRODUCT_CD,
        COALESCE(NULLIF(product.PRODUCT_NM_VIET, ''), '') AS PRODUCT_NAME,
        COALESCE(NULLIF(io.STORE_CD, ''), store_info.STORE_CD, '') AS STORE_CD,
        COALESCE(NULLIF(store_info.STORE_NM_VIET, ''), '') AS STORE_NAME,
        COALESCE(DATE_FORMAT(io.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(transfer_h.INVENTORY_YMD), '')) AS TXN_YMD,
        COALESCE(NULLIF(TRIM(io.INVENTORY_CD), ''), NULLIF(TRIM(transfer_h.INVENTORY_CD), ''), '') AS DOCUMENT_NO,
        IFNULL(io.QUANTITY, 0) AS QUANTITY,
        IFNULL(io.UNIT_PRICE_CC, 0) AS UNIT_PRICE_CC,
        IFNULL(io.AMOUNT_CC, IFNULL(io.QUANTITY, 0) * IFNULL(io.UNIT_PRICE_CC, 0)) AS AMOUNT_CC,
        io.STATE
    FROM chit_inventory_output io
    LEFT JOIN chit_inventory_info transfer_h
        ON transfer_h.COMPANY_CD = io.COMPANY_CD
       AND transfer_h.INVENTORY_ID = io.INVENTORY_ID
       AND IFNULL(transfer_h.ISDEL, '0') = '0'
    LEFT JOIN product_info product
        ON product.COMPANY_CD = io.COMPANY_CD
       AND product.PRODUCT_ID = io.PRODUCT_ID
       AND IFNULL(product.ISDEL, '0') = '0'
    LEFT JOIN store_info
        ON store_info.COMPANY_CD = io.COMPANY_CD
       AND store_info.STORE_ID = io.STORE_ID
       AND IFNULL(store_info.ISDEL, '0') = '0'
    WHERE io.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(io.ISDEL, '0') = '0'
      AND COALESCE(DATE_FORMAT(io.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(transfer_h.INVENTORY_YMD), '')) BETWEEN v_from_ymd AND v_to_ymd
      AND (v_product_cds = '' OR FIND_IN_SET(COALESCE(NULLIF(io.PRODUCT_CD, ''), product.PRODUCT_CD, ''), v_product_cds) > 0)
      AND (v_store_cds = '' OR FIND_IN_SET(COALESCE(NULLIF(io.STORE_CD, ''), store_info.STORE_CD, ''), v_store_cds) > 0)

    ORDER BY PRODUCT_CD, STORE_CD, TXN_YMD, FLOW_TYPE;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.get_opening_balance_summary
DROP PROCEDURE IF EXISTS `get_opening_balance_summary`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `get_opening_balance_summary`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_OPEN_YMD VARCHAR(8),
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    SELECT
        C.ID,
        C.ITEM_CD,
        C.ITEM_NAME_VIET,
        C.ITEM_NAME_ENG,
        C.ITEM_NAME_KOR,
        C.ITEM_NAME_CHINA,
        IFNULL(S.RECORD_COUNT, 0) AS RECORD_COUNT,
        IFNULL(S.TOTAL_DEBIT, 0) AS TOTAL_DEBIT,
        IFNULL(S.TOTAL_CREDIT, 0) AS TOTAL_CREDIT,
        ABS(IFNULL(S.TOTAL_DEBIT, 0) - IFNULL(S.TOTAL_CREDIT, 0)) AS DIFF_AMOUNT,
        CASE
            WHEN IFNULL(S.RECORD_COUNT, 0) = 0
              OR (IFNULL(S.TOTAL_DEBIT, 0) = 0 AND IFNULL(S.TOTAL_CREDIT, 0) = 0) THEN 'EMPTY'
            WHEN IFNULL(S.TOTAL_DEBIT, 0) = IFNULL(S.TOTAL_CREDIT, 0) THEN 'BALANCED'
            ELSE 'UNBALANCED'
        END AS STATUS,
        C.ROUTE,
        C.NOTE
    FROM am_web_manager.opening_balance_summary_config C
    LEFT JOIN
    (
        SELECT
            'ACC' AS ITEM_CD,
            COUNT(*) AS RECORD_COUNT,
            IFNULL(SUM(IFNULL(DEBIT, 0)), 0) AS TOTAL_DEBIT,
            IFNULL(SUM(IFNULL(CREDIT, 0)), 0) AS TOTAL_CREDIT
        FROM before_states
        WHERE ISDEL = '0'
          AND COMPANY_CD = p_COMPANY_CD
          AND (IFNULL(p_OPEN_YMD, '') = '' OR OPEN_YMD = p_OPEN_YMD)

        UNION ALL

        SELECT
            'AR' AS ITEM_CD,
            COUNT(*) AS RECORD_COUNT,
            IFNULL(SUM(IFNULL(DEBIT, 0)), 0) AS TOTAL_DEBIT,
            IFNULL(SUM(IFNULL(CREDIT, 0)), 0) AS TOTAL_CREDIT
        FROM before_states_customer
        WHERE ISDEL = '0'
          AND COMPANY_CD = p_COMPANY_CD
          AND (IFNULL(p_OPEN_YMD, '') = '' OR OPEN_YMD = p_OPEN_YMD)

        UNION ALL

        SELECT
            'AP' AS ITEM_CD,
            0 AS RECORD_COUNT,
            0 AS TOTAL_DEBIT,
            0 AS TOTAL_CREDIT

        UNION ALL

        SELECT
            'INV' AS ITEM_CD,
            0 AS RECORD_COUNT,
            0 AS TOTAL_DEBIT,
            0 AS TOTAL_CREDIT

        UNION ALL

        SELECT
            'BANK' AS ITEM_CD,
            COUNT(*) AS RECORD_COUNT,
            IFNULL(SUM(IFNULL(DEBIT, 0)), 0) AS TOTAL_DEBIT,
            IFNULL(SUM(IFNULL(CREDIT, 0)), 0) AS TOTAL_CREDIT
        FROM before_states_bank
        WHERE ISDEL = '0'
          AND COMPANY_CD = p_COMPANY_CD
          AND (IFNULL(p_OPEN_YMD, '') = '' OR OPEN_YMD = p_OPEN_YMD)

        UNION ALL

        SELECT
            'FA' AS ITEM_CD,
            0 AS RECORD_COUNT,
            0 AS TOTAL_DEBIT,
            0 AS TOTAL_CREDIT
    ) S
        ON C.ITEM_CD = S.ITEM_CD
    WHERE C.ISDEL = '0'
    ORDER BY C.SORT_ORDER, C.ITEM_CD;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.get_paged
DROP PROCEDURE IF EXISTS `get_paged`;
DELIMITER //
CREATE DEFINER=`root`@`115.78.232.22` PROCEDURE `get_paged`(
    IN p_query_sql TEXT,
    IN p_count_sql TEXT,
    IN p_page INT,
    IN p_pageSize INT,
    OUT p_total_count INT
)
BEGIN
    DECLARE v_page INT;
    DECLARE v_pageSize INT;
    DECLARE v_offset BIGINT;
    DECLARE v_data_sql TEXT;
    DECLARE v_count_sql TEXT;

    SET v_page = IFNULL(p_page, 1);
    IF v_page < 1 THEN SET v_page = 1; END IF;
    SET v_pageSize = IFNULL(p_pageSize, 10);
    IF v_pageSize < 1 THEN SET v_pageSize = 10; END IF;
    SET v_offset = (v_page - 1) * v_pageSize;

    SET v_data_sql = CONCAT(p_query_sql, ' LIMIT ', v_offset, ', ', v_pageSize);

   
    SET @__data_sql = v_data_sql;
    PREPARE stmt_data FROM @__data_sql;
    EXECUTE stmt_data;
    DEALLOCATE PREPARE stmt_data;


    IF p_count_sql IS NOT NULL AND TRIM(p_count_sql) <> '' THEN
        SET @__count_sql = CONCAT('SELECT COUNT(1) INTO @__total FROM (', p_count_sql, ') AS __cnt_sub');
    ELSE
        SET @__count_sql = CONCAT('SELECT COUNT(1) INTO @__total FROM (', p_query_sql, ') AS __sub');
    END IF;

    PREPARE stmt_count FROM @__count_sql;
    EXECUTE stmt_count;
    DEALLOCATE PREPARE stmt_count;

    SET p_total_count = IFNULL(@__total, 0);
 
    SELECT p_total_count AS totalCount;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.ins_user_activity_log
DROP PROCEDURE IF EXISTS `ins_user_activity_log`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `ins_user_activity_log`(
    IN p_company_cd      VARCHAR(20),
    IN p_user_id         BIGINT,
    IN p_username        VARCHAR(100),
    IN p_user_ip         VARCHAR(50),
    IN p_user_agent      VARCHAR(500),

    IN p_action_type     VARCHAR(20),   -- INSERT / UPDATE / DELETE
    IN p_module_name     VARCHAR(100),
    IN p_table_name      VARCHAR(100),
    IN p_record_id       VARCHAR(100),

    IN p_old_data        LONGTEXT,
    IN p_new_data        LONGTEXT,

    IN p_description     VARCHAR(500),
    IN p_transaction_id  VARCHAR(100)
)
BEGIN

    -- Validate action type
    IF p_action_type NOT IN ('INSERT','UPDATE','DELETE') THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Invalid action type';
    END IF;

    INSERT INTO user_activity_log
    (
        company_cd,
        user_id,
        username,
        user_ip,
        user_agent,
        action_type,
        module_name,
        table_name,
        record_id,
        old_data,
        new_data,
        action_time,
        description,
        transaction_id
    )
    VALUES
    (
        p_company_cd,
        p_user_id,
        p_username,
        p_user_ip,
        p_user_agent,
        p_action_type,
        p_module_name,
        p_table_name,
        p_record_id,
        p_old_data,
        p_new_data,
        NOW(),
        p_description,
        p_transaction_id
    );

END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.isApprovedSigningCertificate
DROP PROCEDURE IF EXISTS `isApprovedSigningCertificate`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `isApprovedSigningCertificate`(IN p_company VARCHAR(20),IN p_scope VARCHAR(20),IN p_tax VARCHAR(14),IN p_serial VARCHAR(100))
BEGIN
 DECLARE v_method INT DEFAULT NULL;
 DECLARE v_from DATETIME DEFAULT NULL;
 DECLARE v_to DATETIME DEFAULT NULL;
 IF p_scope='PIT' THEN
  SELECT d.HTHUC,d.TNGAY,d.DNGAY INTO v_method,v_from,v_to
    FROM pit_tkhai_info h
    JOIN pit_tkhai_cts d ON d.COMPANY_CD=h.COMPANY_CD AND d.TKHAI_ID=h.TKHAI_ID AND d.ISDEL=0
   WHERE h.COMPANY_CD=p_company AND h.MST=p_tax AND h.CQT_STATUS=2 AND h.ISDEL=0
     AND UPPER(REPLACE(REPLACE(TRIM(d.SERI),' ',''),':',''))=p_serial
   ORDER BY h.NLAP DESC,h.TKHAI_ID DESC,IFNULL(d.STT,0) DESC,d.CTS_ID DESC
   LIMIT 1;
 ELSEIF p_scope='EINVOICE' THEN
  SELECT d.CTS_HTHUC,d.TNGAY,d.DNGAY INTO v_method,v_from,v_to
    FROM einvoice_tkhai_info h
    JOIN einvoice_tkhai_detail d ON d.COMPANY_CD=h.COMPANY_CD AND d.TKHAI_ID=h.TKHAI_ID AND d.ISDEL=0
   WHERE h.COMPANY_CD=p_company AND h.MST=p_tax AND h.CQT_STATUS=2 AND h.ISDEL=0 AND d.DETAIL_TYPE='CTS'
     AND UPPER(REPLACE(REPLACE(TRIM(d.SERI),' ',''),':',''))=p_serial
   ORDER BY h.NLAP DESC,h.TKHAI_ID DESC,IFNULL(d.STT,0) DESC,d.DETAIL_ID DESC
   LIMIT 1;
 ELSE
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid signing certificate scope';
 END IF;
 SELECT IF(IFNULL(v_method,0) IN (1,2) AND NOW() BETWEEN v_from AND v_to,1,0);
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.issueEInvoiceMtt
DROP PROCEDURE IF EXISTS `issueEInvoiceMtt`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `issueEInvoiceMtt`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_INVOICE_ID BIGINT,
  IN p_DOC_VERSION INT,
  IN p_SHDON VARCHAR(8),
  IN p_NLAP DATE,
  IN p_MCCQT VARCHAR(23),
  IN p_XML_FTP_PATH VARCHAR(1000),
  IN p_USER_ID VARCHAR(50)
)
BEGIN
  DECLARE v_SHDON VARCHAR(8);
  DECLARE v_KHMSHDON VARCHAR(11);
  DECLARE v_KHHDON VARCHAR(8);

  SET v_SHDON = TRIM(IFNULL(p_SHDON, ''));

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;
  IF p_INVOICE_ID IS NULL OR p_INVOICE_ID <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVOICE_ID is required';
  END IF;
  IF v_SHDON = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SHDON is required';
  END IF;
  IF p_NLAP IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NLAP is required';
  END IF;
  IF p_XML_FTP_PATH IS NULL OR TRIM(p_XML_FTP_PATH) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'XML_FTP_PATH is required';
  END IF;

  SELECT IFNULL(KHMSHDON, ''), IFNULL(KHHDON, '')
  INTO v_KHMSHDON, v_KHHDON
  FROM einvoice_info
  WHERE COMPANY_CD = p_COMPANY_CD AND INVOICE_ID = p_INVOICE_ID AND ISDEL = 0
  LIMIT 1;

  IF v_KHHDON = '' OR UPPER(SUBSTRING(TRIM(v_KHHDON), 4, 1)) <> 'M' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Not an MTT invoice.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM einvoice_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND IFNULL(KHMSHDON, '') = v_KHMSHDON
      AND IFNULL(KHHDON, '') = v_KHHDON
      AND IFNULL(SHDON, '') = v_SHDON
      AND ISDEL = 0
      AND INVOICE_ID <> p_INVOICE_ID
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice number already exists';
  END IF;

  UPDATE einvoice_info
  SET SHDON = v_SHDON,
      NLAP = p_NLAP,
      MCCQT = NULLIF(TRIM(p_MCCQT), ''),
      XML_FTP_PATH = TRIM(p_XML_FTP_PATH),
      DOC_VERSION = DOC_VERSION + 1,
      UPDATE_BY = p_USER_ID,
      UPDATE_AT = NOW()
  WHERE COMPANY_CD = p_COMPANY_CD
    AND INVOICE_ID = p_INVOICE_ID
    AND DOC_VERSION = p_DOC_VERSION
    AND ISDEL = 0
    AND IFNULL(IS_SIGNED, 0) = 0
    AND IFNULL(TRIM(SHDON), '') = ''
    AND UPPER(SUBSTRING(TRIM(KHHDON), 4, 1)) = 'M';

  IF ROW_COUNT() <> 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MTT invoice cannot be issued. Reload and try again.';
  END IF;
END//
DELIMITER ;


