          AND FA_ACC_CD = p_accCD
          AND ACQ_YMD >= '20260101'
        LIMIT 1
    )
    OR EXISTS (
        SELECT 1
        FROM fixedassets_info
        WHERE COMPANY_CD = p_COMPANY_CD
          AND FADEP_ACC_CD = p_accCD
          AND ACQ_YMD >= '20260101'
        LIMIT 1
    )
    OR EXISTS (
        SELECT 1
        FROM fixedassets_info
        WHERE COMPANY_CD = p_COMPANY_CD
          AND FAEX_ACC_CD = p_accCD
          AND ACQ_YMD >= '20260101'
        LIMIT 1
    )
    OR EXISTS (
        SELECT 1
        FROM inventory_closingmonth_detail
        WHERE COMPANY_CD = p_COMPANY_CD
          AND ACC_CD = p_accCD
          AND CLOSE_YMD >= '202512'
        LIMIT 1
    )
    OR 
	 EXISTS {
        SELECT 1
        FROM product_info
        WHERE COMPANY_CD = p_COMPANY_CD
          AND DIVISION = p_ACC_CD
        LIMIT 1*/
    ) THEN
        SET outQuery = 'Y';
    END IF;

    SELECT outQuery;
END//
DELIMITER ;


