-- Dumping structure for procedure am_web_001.lockPitTarget
DROP PROCEDURE IF EXISTS `lockPitTarget`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `lockPitTarget`(IN p_company VARCHAR(20),IN p_target VARCHAR(30),IN p_id BIGINT)
BEGIN
 IF p_target='PIT_DECLARATION' THEN SELECT * FROM pit_tkhai_info WHERE COMPANY_CD=p_company AND TKHAI_ID=p_id AND ISDEL=0 FOR UPDATE;
 ELSEIF p_target='PIT_CERTIFICATE' THEN SELECT * FROM pit_ctu_info WHERE COMPANY_CD=p_company AND CTU_ID=p_id AND ISDEL=0 FOR UPDATE;
 ELSEIF p_target='PIT_ERROR_NOTICE' THEN SELECT * FROM pit_tbao_info WHERE COMPANY_CD=p_company AND TBAO_ID=p_id AND ISDEL=0 FOR UPDATE;
 ELSE SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid PIT target'; END IF;
END//
DELIMITER ;


