-- Dumping structure for procedure am_web_001.markSysNotificationRead
DROP PROCEDURE IF EXISTS `markSysNotificationRead`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `markSysNotificationRead`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_USER_ID VARCHAR(50),
    IN p_ROLE_CD VARCHAR(50),
    IN p_ID BIGINT,
    IN p_MARK_ALL CHAR(1)
)
BEGIN
    IF UPPER(TRIM(COALESCE(p_MARK_ALL, 'N'))) = 'Y' THEN
        UPDATE sys_notification n
        SET n.IS_READ = 'Y',
            n.READ_AT = NOW()
        WHERE n.COMPANY_CD = p_COMPANY_CD
          AND n.IS_READ = 'N'
          AND (n.EXPIRED_AT IS NULL OR n.EXPIRED_AT > NOW())
          AND (
                (n.USER_ID IS NULL AND n.ROLE_CD IS NULL)
                OR (p_USER_ID IS NOT NULL AND p_USER_ID <> '' AND n.USER_ID = p_USER_ID)
                OR (p_ROLE_CD IS NOT NULL AND p_ROLE_CD <> '' AND n.ROLE_CD = p_ROLE_CD)
                OR (p_USER_ID IS NOT NULL AND p_USER_ID <> '' AND n.USER_ID IS NULL AND n.ROLE_CD IS NULL)
              );
    ELSE
        IF p_ID IS NULL OR p_ID <= 0 THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'ID is required';
        END IF;

        UPDATE sys_notification n
        SET n.IS_READ = 'Y',
            n.READ_AT = NOW()
        WHERE n.ID = p_ID
          AND n.COMPANY_CD = p_COMPANY_CD
          AND (
                (n.USER_ID IS NULL AND n.ROLE_CD IS NULL)
                OR (p_USER_ID IS NOT NULL AND p_USER_ID <> '' AND n.USER_ID = p_USER_ID)
                OR (p_ROLE_CD IS NOT NULL AND p_ROLE_CD <> '' AND n.ROLE_CD = p_ROLE_CD)
                OR (p_USER_ID IS NOT NULL AND p_USER_ID <> '' AND n.USER_ID IS NULL AND n.ROLE_CD IS NULL)
              );
    END IF;

    SELECT ROW_COUNT() AS AFFECTED_ROWS;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.migrate_inventory_cogs_direct_links
DROP PROCEDURE IF EXISTS `migrate_inventory_cogs_direct_links`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `migrate_inventory_cogs_direct_links`()
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
IF NOT EXISTS (SELECT 1 FROM information_schema.TABLES
    WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'chit_inventory_cogs')
    OR NOT EXISTS (SELECT 1 FROM information_schema.TABLES
    WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'chit_inventory_cogs_detail') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Legacy COGS tables missing; migration not applicable';
    END IF;
    IF EXISTS (
        SELECT 1 FROM chit_inventory_cogs l
        LEFT JOIN chit_inventory_info t ON t.INVENTORY_ID=l.TRANSFER_ID AND t.COMPANY_CD=l.COMPANY_CD
        LEFT JOIN chitinfo h ON h.CHIT_ID=l.CHIT_ID AND h.COMPANY_CD=l.COMPANY_CD
        WHERE t.INVENTORY_ID IS NULL OR h.CHIT_ID IS NULL OR t.CHIT_TYPE<>'IO'
           OR h.CHIT_TYPE<>'IO_COGS' OR h.INPUT_TYPE<>'AR'
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid old COGS header links: check company, voucher and type';
    END IF;
    IF EXISTS (
        SELECT 1 FROM chit_inventory_cogs_detail l
        LEFT JOIN chit_inventory_cogs h ON h.COMPANY_CD=l.COMPANY_CD AND h.TRANSFER_ID=l.TRANSFER_ID
        LEFT JOIN chit_inventory_output o ON o.COMPANY_CD=l.COMPANY_CD AND o.OUTPUT_ID=l.OUTPUT_ID AND o.INVENTORY_ID=l.TRANSFER_ID
        LEFT JOIN chitdetailinfo d ON d.COMPANY_CD=l.COMPANY_CD AND d.CHITDETAIL_ID=l.CHITDETAIL_ID AND d.CHIT_ID=h.CHIT_ID
        WHERE h.CHIT_ID IS NULL OR o.OUTPUT_ID IS NULL OR d.CHITDETAIL_ID IS NULL OR o.CHIT_TYPE<>'IO'
           OR d.DEBIT IS NULL OR d.CREDIT IS NULL OR TRIM(d.DEBIT)='' OR TRIM(d.CREDIT)=''
           OR NOT EXISTS (SELECT 1 FROM acclist_info a WHERE a.COMPANY_CD=d.COMPANY_CD AND a.ACC_CD=d.DEBIT AND a.ISDEL='0')
           OR NOT EXISTS (SELECT 1 FROM acclist_info a WHERE a.COMPANY_CD=d.COMPANY_CD AND a.ACC_CD=d.CREDIT AND a.ISDEL='0')
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid old COGS detail links: check output, company, header and accounts';
    END IF;
    IF EXISTS (
        SELECT 1 FROM chit_inventory_info t
        LEFT JOIN chit_inventory_cogs l ON l.COMPANY_CD=t.COMPANY_CD AND l.TRANSFER_ID=t.INVENTORY_ID
        LEFT JOIN chitinfo h ON h.COMPANY_CD=l.COMPANY_CD AND h.CHIT_ID=l.CHIT_ID AND h.ISDEL='0'
        LEFT JOIN chitinfo_ext e ON e.COMPANY_CD=h.COMPANY_CD AND e.CHIT_ID=h.CHIT_ID AND e.ISDEL='0'
        WHERE t.CHIT_TYPE='IO' AND t.ISDEL='0'
          AND (h.CHIT_ID IS NULL OR e.CHIT_ID IS NULL OR t.INVENTORY_YMD<>h.CHIT_YMD OR t.AMOUNT<>h.AMOUNT
            OR NOT EXISTS (SELECT 1 FROM chit_inventory_output o WHERE o.COMPANY_CD=t.COMPANY_CD AND o.INVENTORY_ID=t.INVENTORY_ID AND o.ISDEL='0')
            OR h.AMOUNT <> (SELECT SUM(d.AMOUNT) FROM chitdetailinfo d WHERE d.COMPANY_CD=h.COMPANY_CD AND d.CHIT_ID=h.CHIT_ID AND d.ISDEL='0')
            OR (SELECT COUNT(*) FROM chitdetailinfo d WHERE d.COMPANY_CD=h.COMPANY_CD AND d.CHIT_ID=h.CHIT_ID AND d.ISDEL='0')
               <> (SELECT COUNT(*) FROM chit_inventory_output o WHERE o.COMPANY_CD=t.COMPANY_CD AND o.INVENTORY_ID=t.INVENTORY_ID AND o.ISDEL='0'))
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Active issue voucher has missing/invalid COGS header, count or total';
    END IF;
    IF EXISTS (
        SELECT 1 FROM chit_inventory_output o
        LEFT JOIN chit_inventory_cogs_detail l ON l.COMPANY_CD=o.COMPANY_CD AND l.OUTPUT_ID=o.OUTPUT_ID AND l.TRANSFER_ID=o.INVENTORY_ID
        LEFT JOIN chit_inventory_cogs h ON h.COMPANY_CD=o.COMPANY_CD AND h.TRANSFER_ID=o.INVENTORY_ID
        LEFT JOIN chitdetailinfo d ON d.COMPANY_CD=o.COMPANY_CD AND d.CHITDETAIL_ID=l.CHITDETAIL_ID AND d.CHIT_ID=h.CHIT_ID AND d.ISDEL='0'
        LEFT JOIN chitdetailinfo_ext e ON e.COMPANY_CD=d.COMPANY_CD AND e.CHITDETAIL_ID=d.CHITDETAIL_ID AND e.ISDEL='0'
        WHERE o.CHIT_TYPE='IO' AND o.ISDEL='0'
          AND (d.CHITDETAIL_ID IS NULL OR e.CHITDETAIL_ID IS NULL OR o.AMOUNT_CC<0 OR d.AMOUNT<>ROUND(o.AMOUNT_CC,2))
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Active issue output has missing/invalid COGS detail link or amount';
    END IF;
-- The replacement schema already has CHIT_ID_COGS and CHITDETAIL_ID_COGS.
    -- Do not add these columns/constraints again.
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'chit_inventory_info'
          AND COLUMN_NAME = 'CHIT_ID_COGS'
    ) OR NOT EXISTS (
        SELECT 1 FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'chit_inventory_output'
          AND COLUMN_NAME = 'CHITDETAIL_ID_COGS'
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='COGS link columns missing: update schema first';
    END IF;

START TRANSACTION;
UPDATE chit_inventory_info t
INNER JOIN chit_inventory_cogs l ON l.COMPANY_CD=t.COMPANY_CD AND l.TRANSFER_ID=t.INVENTORY_ID
SET t.CHIT_ID_COGS=l.CHIT_ID;
UPDATE chit_inventory_output o
INNER JOIN chit_inventory_cogs_detail l ON l.COMPANY_CD=o.COMPANY_CD AND l.OUTPUT_ID=o.OUTPUT_ID AND l.TRANSFER_ID=o.INVENTORY_ID
SET o.CHITDETAIL_ID_COGS=l.CHITDETAIL_ID;



IF EXISTS (
        SELECT 1 FROM chit_inventory_cogs l
        LEFT JOIN chit_inventory_info t ON t.COMPANY_CD=l.COMPANY_CD AND t.INVENTORY_ID=l.TRANSFER_ID
        WHERE t.CHIT_ID_COGS IS NULL OR t.CHIT_ID_COGS<>l.CHIT_ID
    ) OR EXISTS (
        SELECT 1 FROM chit_inventory_cogs_detail l
        LEFT JOIN chit_inventory_output o ON o.COMPANY_CD=l.COMPANY_CD AND o.OUTPUT_ID=l.OUTPUT_ID AND o.INVENTORY_ID=l.TRANSFER_ID
        WHERE o.CHITDETAIL_ID_COGS IS NULL OR o.CHITDETAIL_ID_COGS<>l.CHITDETAIL_ID
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='COGS direct-link copy mismatch: old tables must NOT be dropped';
    END IF;
    COMMIT;
    DROP TABLE chit_inventory_cogs_detail;
    DROP TABLE chit_inventory_cogs;
END//
DELIMITER ;


