-- Dumping structure for procedure am_web_001.publishEInvoiceSellerXslTemplateDesign
DROP PROCEDURE IF EXISTS `publishEInvoiceSellerXslTemplateDesign`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `publishEInvoiceSellerXslTemplateDesign`(
  IN p_CONTENT_ID BIGINT UNSIGNED,
  IN p_DESIGN_ID BIGINT UNSIGNED,
  IN p_COMPANY_CD VARCHAR(20),
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_IS_ACTIVE TINYINT DEFAULT 0;
  DECLARE v_XSL LONGTEXT;

  IF NOT EXISTS (
    SELECT 1 FROM einvoice_seller_xsl_template template
    WHERE template.XSL_ID = p_CONTENT_ID AND template.COMPANY_CD = p_COMPANY_CD AND template.ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invoice template not found';
  END IF;

  SELECT IFNULL(template.IS_ACTIVE, 0)
    INTO v_IS_ACTIVE
    FROM einvoice_seller_xsl_template template
   WHERE template.XSL_ID = p_CONTENT_ID
     AND template.COMPANY_CD = p_COMPANY_CD
     AND template.ISDEL = 0
   LIMIT 1;

  IF IFNULL(v_IS_ACTIVE, 0) = 1 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Template IS_ACTIVE=1: cannot update einvoice_seller_xsl_template_content. Deactivate in ToolTaoMau first.';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM einvoice_seller_xsl_template_design
    WHERE DESIGN_ID = p_DESIGN_ID AND CONTENT_ID = p_CONTENT_ID
      AND XSL_CONTENT IS NOT NULL AND TRIM(XSL_CONTENT) <> ''
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Design with XSL_CONTENT not found';
  END IF;

  SELECT XSL_CONTENT INTO v_XSL
    FROM einvoice_seller_xsl_template_design
   WHERE DESIGN_ID = p_DESIGN_ID AND CONTENT_ID = p_CONTENT_ID
   LIMIT 1;

  INSERT INTO einvoice_seller_xsl_template_content (XSL_ID, CURRENT_DESIGN_ID, XSL_CONTENT, UPDATE_BY, UPDATE_AT)
  VALUES (p_CONTENT_ID, p_DESIGN_ID, v_XSL, p_USERID, NOW())
  ON DUPLICATE KEY UPDATE
    CURRENT_DESIGN_ID = VALUES(CURRENT_DESIGN_ID),
    XSL_CONTENT = VALUES(XSL_CONTENT),
    UPDATE_BY = VALUES(UPDATE_BY),
    UPDATE_AT = VALUES(UPDATE_AT);

  UPDATE einvoice_seller_xsl_template_design
  SET UPDATE_BY = p_USERID, UPDATE_AT = NOW()
  WHERE DESIGN_ID = p_DESIGN_ID;

  SELECT XSL_ID, CURRENT_DESIGN_ID, XSL_CONTENT, UPDATE_BY, UPDATE_AT
  FROM einvoice_seller_xsl_template_content WHERE XSL_ID = p_CONTENT_ID;
END//
DELIMITER ;


