-- Dumping structure for procedure am_web_001.reservePitDocument
DROP PROCEDURE IF EXISTS `reservePitDocument`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `reservePitDocument`(IN p_company VARCHAR(20),IN p_kind VARCHAR(20),IN p_id BIGINT)
BEGIN
 DECLARE v_series VARCHAR(6); DECLARE v_number BIGINT; DECLARE v_signed TINYINT;
 DECLARE v_xsl BIGINT; DECLARE v_from BIGINT UNSIGNED DEFAULT 1; DECLARE v_to BIGINT UNSIGNED DEFAULT NULL; DECLARE v_catalog INT DEFAULT 0;
 IF p_kind='certificate' THEN
  UPDATE pit_document
     SET DOC_DATE=CURDATE(),
         DATA_JSON=JSON_SET(DATA_JSON,'$.Fields.DATE',DATE_FORMAT(CURDATE(),'%Y-%m-%d'))
   WHERE COMPANY_CD=p_company AND KIND=p_kind AND DOCUMENT_ID=p_id AND IS_SIGNED=0 AND ISDEL=0;
 END IF;
 SELECT SERIES,DOC_NO,IS_SIGNED,XSL_ID INTO v_series,v_number,v_signed,v_xsl FROM pit_document WHERE COMPANY_CD=p_company AND KIND=p_kind AND DOCUMENT_ID=p_id AND ISDEL=0 FOR UPDATE;
 IF v_signed IS NULL OR v_signed=1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Document missing or already signed'; END IF;
 IF p_kind='certificate' AND v_number IS NULL THEN
  IF IFNULL(v_series,'')='' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='PIT SERIES is required'; END IF;
  SELECT COUNT(*), MIN(FROM_DOC_NO), MIN(TO_DOC_NO) INTO v_catalog, v_from, v_to
    FROM pit_xsl_template
   WHERE COMPANY_CD=p_company AND SERIES=v_series AND ISDEL=0 AND IS_ACTIVE=1
     AND (IFNULL(v_xsl,0)=0 OR XSL_ID=v_xsl);
  IF IFNULL(v_catalog,0)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='SERIES not registered in PIT catalog'; END IF;
  SET v_from = IFNULL(NULLIF(v_from,0),1);
  INSERT INTO pit_number_sequence(COMPANY_CD,SERIES,LAST_NO) VALUES(p_company,v_series,LAST_INSERT_ID(v_from)) ON DUPLICATE KEY UPDATE LAST_NO=LAST_INSERT_ID(LAST_NO+1);
  SET v_number=LAST_INSERT_ID();
  IF v_number>99999999 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='PIT number exceeds 8 digits'; END IF;
  IF v_to IS NOT NULL AND v_number>v_to THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='PIT number exceeds TO_DOC_NO for series'; END IF;
  UPDATE pit_document SET DOC_NO=v_number WHERE COMPANY_CD=p_company AND DOCUMENT_ID=p_id;
 END IF;
 SELECT * FROM pit_document WHERE COMPANY_CD=p_company AND KIND=p_kind AND DOCUMENT_ID=p_id;
END//
DELIMITER ;


