-- Dumping structure for procedure am_web_001.revertEInvoiceSigningReservation
DROP PROCEDURE IF EXISTS `revertEInvoiceSigningReservation`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `revertEInvoiceSigningReservation`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_INVOICE_ID BIGINT,
  IN p_SHDON VARCHAR(8),
  IN p_NLAP DATE,
  IN p_USERID VARCHAR(50)
)
BEGIN
  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF p_INVOICE_ID IS NULL OR p_INVOICE_ID <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVOICE_ID is required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM einvoice_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND INVOICE_ID = p_INVOICE_ID
      AND ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice not found';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM einvoice_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND INVOICE_ID = p_INVOICE_ID
      AND ISDEL = 0
      AND IFNULL(IS_SIGNED, 0) = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Signed e-invoice cannot revert signing reservation';
  END IF;

  UPDATE einvoice_info
  SET SHDON = NULLIF(TRIM(IFNULL(p_SHDON, '')), ''),
      NLAP = p_NLAP,
      UPDATE_BY = p_USERID,
      UPDATE_AT = NOW()
  WHERE COMPANY_CD = p_COMPANY_CD
    AND INVOICE_ID = p_INVOICE_ID
    AND ISDEL = 0
    AND IFNULL(IS_SIGNED, 0) = 0;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_account_detail_s38dn
DROP PROCEDURE IF EXISTS `rpt_account_detail_s38dn`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_account_detail_s38dn`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_ACCOUNT_CD VARCHAR(1000),
    IN p_FC_TYPE VARCHAR(255),
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_before_from_ymd VARCHAR(8);
    DECLARE v_language VARCHAR(20);
    DECLARE v_account_cd VARCHAR(1000);
    DECLARE v_fc_type VARCHAR(255);
    DECLARE v_currency_text VARCHAR(255);
    DECLARE v_report_period_text VARCHAR(255);
    DECLARE v_amount_unit_text VARCHAR(100);
    DECLARE v_company_cd VARCHAR(20);
    DECLARE v_use_fc TINYINT DEFAULT 0;
    DECLARE v_rows_inserted INT DEFAULT 0;

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;

    SET v_from_ymd = DATE_FORMAT(p_FROM_DATE, '%Y%m%d');
    SET v_to_ymd = DATE_FORMAT(p_TO_DATE, '%Y%m%d');
    SET v_before_from_ymd = DATE_FORMAT(DATE_SUB(p_FROM_DATE, INTERVAL 1 DAY), '%Y%m%d');
    SET v_company_cd = CONVERT(TRIM(IFNULL(p_COMPANY_CD, '')) USING utf8) COLLATE utf8_unicode_ci;
    SET v_language = CONVERT(UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET'))) USING utf8) COLLATE utf8_unicode_ci;
    SET v_account_cd = CONVERT(REPLACE(TRIM(IFNULL(p_ACCOUNT_CD, '')), ' ', '') USING utf8) COLLATE utf8_unicode_ci;
    SET v_fc_type = CONVERT(REPLACE(UPPER(TRIM(IFNULL(p_FC_TYPE, ''))), ' ', '') USING utf8) COLLATE utf8_unicode_ci;

    IF UPPER(v_account_cd) IN ('ALL', '*') THEN
        SET v_account_cd = '';
    END IF;

    IF v_fc_type = 'ALL' THEN
        SET v_fc_type = '';
    END IF;

    SET v_use_fc = CASE WHEN v_fc_type <> '' AND v_fc_type <> 'VND' AND LOCATE(',', v_fc_type) = 0 THEN 1 ELSE 0 END;
    SET v_currency_text = CASE WHEN v_fc_type = '' THEN 'VND' ELSE v_fc_type END;
    SET v_report_period_text = CONCAT('Từ ngày ', DATE_FORMAT(p_FROM_DATE, '%d/%m/%Y'), ' đến ngày ', DATE_FORMAT(p_TO_DATE, '%d/%m/%Y'));
    SET v_amount_unit_text = CASE WHEN v_use_fc = 1 THEN CONCAT('Loại tiền: ', v_currency_text) ELSE 'Đơn vị tính: Đồng' END;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_accounts;
    CREATE TEMPORARY TABLE tmp_account_detail_accounts
    (
        ACCOUNT_SORT INT NOT NULL AUTO_INCREMENT,
        ACC_CD VARCHAR(20) NOT NULL,
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ACCOUNT_SORT),
        UNIQUE KEY uq_tmp_account_detail_accounts_01 (ACC_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_account_detail_accounts (ACC_CD, ACCOUNT_NAME)
    SELECT
        account.ACC_CD,
        COALESCE(
            NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN account.ACCTITLE_NM_ENG
                WHEN 'KOR' THEN account.ACCTITLE_NM_KOR
                WHEN 'CHINA' THEN account.ACCTITLE_NM_CHINA
                WHEN 'JAPAN' THEN account.ACCTITLE_NM_JAPAN
                ELSE account.ACCTITLE_NM_VIET
            END), ''),
            NULLIF(TRIM(account.ACCTITLE_NM_VIET), ''),
            NULLIF(TRIM(account.ACCTITLE_NM_ENG), ''),
            account.ACC_CD
        )
    FROM acclist_info account
    INNER JOIN
    (
        SELECT ACC_CD, MAX(ACC_ID) AS ACC_ID
        FROM acclist_info
        WHERE COMPANY_CD = v_company_cd
          AND IFNULL(ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
          AND TRIM(IFNULL(ACC_CD, '')) <> ''
        GROUP BY ACC_CD
    ) latest
        ON latest.ACC_ID = account.ACC_ID
    WHERE account.COMPANY_CD = v_company_cd
      AND IFNULL(account.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
      AND (v_account_cd = '' OR FIND_IN_SET(account.ACC_CD COLLATE utf8_unicode_ci, v_account_cd COLLATE utf8_unicode_ci) > 0)
    ORDER BY account.ACC_CD;

    -- Build the selected accounts' real chart-of-accounts ancestry here. The
    -- API and TreeList receive a complete parent key from the procedure.
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_tree_accounts;
    CREATE TEMPORARY TABLE tmp_account_detail_tree_accounts
    (
        ACCOUNT_SORT INT NOT NULL AUTO_INCREMENT,
        ACC_ID INT NOT NULL,
        ACC_PARENT_ID INT NOT NULL DEFAULT 0,
        PARENT_CD VARCHAR(20) NOT NULL DEFAULT '',
        ACCOUNT_LEVEL INT NOT NULL DEFAULT 0,
        ACC_CD VARCHAR(20) NOT NULL,
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ACCOUNT_SORT),
        UNIQUE KEY uq_tmp_account_detail_tree_id (ACC_ID),
        UNIQUE KEY uq_tmp_account_detail_tree_cd (ACC_CD),
        INDEX idx_tmp_account_detail_tree_parent (ACC_PARENT_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_account_detail_tree_accounts (ACC_ID, ACC_PARENT_ID, PARENT_CD, ACCOUNT_LEVEL, ACC_CD, ACCOUNT_NAME)
    SELECT account.ACC_ID, IFNULL(account.ACC_PARENT_ID, 0), IFNULL(parent.ACC_CD, ''), IFNULL(account.ACCOUNT_LEVEL, 0), account.ACC_CD, account.ACCOUNT_NAME
    FROM
    (
        SELECT source.ACC_ID, source.ACC_PARENT_ID, source.LEVEL AS ACCOUNT_LEVEL, source.ACC_CD,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN source.ACCTITLE_NM_ENG
                WHEN 'KOR' THEN source.ACCTITLE_NM_KOR
                WHEN 'CHINA' THEN source.ACCTITLE_NM_CHINA
                WHEN 'JAPAN' THEN source.ACCTITLE_NM_JAPAN
                ELSE source.ACCTITLE_NM_VIET
            END), ''), NULLIF(TRIM(source.ACCTITLE_NM_VIET), ''),
                NULLIF(TRIM(source.ACCTITLE_NM_ENG), ''), source.ACC_CD) AS ACCOUNT_NAME
        FROM acclist_info source
        INNER JOIN tmp_account_detail_accounts selected ON selected.ACC_CD = source.ACC_CD
        INNER JOIN
        (
            SELECT ACC_CD, MAX(ACC_ID) AS ACC_ID
            FROM acclist_info
            WHERE COMPANY_CD = v_company_cd
              AND IFNULL(ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
            GROUP BY ACC_CD
        ) latest ON latest.ACC_ID = source.ACC_ID
        WHERE source.COMPANY_CD = v_company_cd
          AND IFNULL(source.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    ) account
    LEFT JOIN acclist_info parent
        ON parent.ACC_ID = account.ACC_PARENT_ID
       AND parent.COMPANY_CD = v_company_cd
       AND IFNULL(parent.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    ORDER BY account.ACC_CD;

    -- Use separate frontier/candidate tables: MySQL 5.6 cannot reopen a
    -- temporary table that is both the INSERT target and a SELECT source.
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_tree_frontier;
    CREATE TEMPORARY TABLE tmp_account_detail_tree_frontier
    (
        ACC_ID INT NOT NULL,
        PRIMARY KEY (ACC_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_tree_candidates;
    CREATE TEMPORARY TABLE tmp_account_detail_tree_candidates
    (
        ACC_ID INT NOT NULL,
        ACC_PARENT_ID INT NOT NULL DEFAULT 0,
        PARENT_CD VARCHAR(20) NOT NULL DEFAULT '',
        ACCOUNT_LEVEL INT NOT NULL DEFAULT 0,
        ACC_CD VARCHAR(20) NOT NULL,
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ACC_ID),
        UNIQUE KEY uq_tmp_account_detail_tree_candidate_cd (ACC_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_account_detail_tree_frontier (ACC_ID)
    SELECT ACC_ID FROM tmp_account_detail_tree_accounts;

    SET v_rows_inserted = 1;
    WHILE v_rows_inserted > 0 DO
        DELETE FROM tmp_account_detail_tree_candidates;
        INSERT IGNORE INTO tmp_account_detail_tree_candidates
            (ACC_ID, ACC_PARENT_ID, PARENT_CD, ACCOUNT_LEVEL, ACC_CD, ACCOUNT_NAME)
        SELECT parent.ACC_ID, IFNULL(parent.ACC_PARENT_ID, 0), IFNULL(grandparent.ACC_CD, ''), IFNULL(parent.LEVEL, 0), parent.ACC_CD,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN parent.ACCTITLE_NM_ENG
                WHEN 'KOR' THEN parent.ACCTITLE_NM_KOR
                WHEN 'CHINA' THEN parent.ACCTITLE_NM_CHINA
                WHEN 'JAPAN' THEN parent.ACCTITLE_NM_JAPAN
                ELSE parent.ACCTITLE_NM_VIET
            END), ''), NULLIF(TRIM(parent.ACCTITLE_NM_VIET), ''),
                NULLIF(TRIM(parent.ACCTITLE_NM_ENG), ''), parent.ACC_CD)
        FROM tmp_account_detail_tree_frontier child
        INNER JOIN acclist_info parent ON parent.ACC_ID = child.ACC_ID
        LEFT JOIN acclist_info grandparent ON grandparent.ACC_ID = parent.ACC_PARENT_ID
        WHERE parent.ACC_PARENT_ID > 0
          AND parent.COMPANY_CD = v_company_cd
          AND IFNULL(parent.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci;

        INSERT IGNORE INTO tmp_account_detail_tree_accounts
            (ACC_ID, ACC_PARENT_ID, PARENT_CD, ACCOUNT_LEVEL, ACC_CD, ACCOUNT_NAME)
        SELECT ACC_ID, ACC_PARENT_ID, PARENT_CD, ACCOUNT_LEVEL, ACC_CD, ACCOUNT_NAME
        FROM tmp_account_detail_tree_candidates;
        SET v_rows_inserted = ROW_COUNT();

        DELETE FROM tmp_account_detail_tree_frontier;
        INSERT IGNORE INTO tmp_account_detail_tree_frontier (ACC_ID)
        SELECT ACC_ID FROM tmp_account_detail_tree_candidates;
    END WHILE;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_tree_candidates;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_tree_frontier;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_account_paths;
    CREATE TEMPORARY TABLE tmp_account_detail_account_paths
    (
        ANCESTOR_ID INT NOT NULL,
        DESCENDANT_ID INT NOT NULL,
        ANCESTOR_CD VARCHAR(20) NOT NULL,
        DESCENDANT_CD VARCHAR(20) NOT NULL,
        PRIMARY KEY (ANCESTOR_ID, DESCENDANT_ID),
        INDEX idx_tmp_account_detail_path_descendant (DESCENDANT_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT IGNORE INTO tmp_account_detail_account_paths (ANCESTOR_ID, DESCENDANT_ID, ANCESTOR_CD, DESCENDANT_CD)
    SELECT tree.ACC_ID, tree.ACC_ID, tree.ACC_CD, tree.ACC_CD
    FROM tmp_account_detail_tree_accounts tree
    INNER JOIN tmp_account_detail_accounts selected ON selected.ACC_CD = tree.ACC_CD;

    -- Keep the recursive frontier separate from the closure table for MySQL 5.6.
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_path_frontier;
    CREATE TEMPORARY TABLE tmp_account_detail_path_frontier
    (
        ANCESTOR_ID INT NOT NULL,
        DESCENDANT_ID INT NOT NULL,
        ANCESTOR_CD VARCHAR(20) NOT NULL,
        DESCENDANT_CD VARCHAR(20) NOT NULL,
        PRIMARY KEY (ANCESTOR_ID, DESCENDANT_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_path_candidates;
    CREATE TEMPORARY TABLE tmp_account_detail_path_candidates
    (
        ANCESTOR_ID INT NOT NULL,
        DESCENDANT_ID INT NOT NULL,
        ANCESTOR_CD VARCHAR(20) NOT NULL,
        DESCENDANT_CD VARCHAR(20) NOT NULL,
        PRIMARY KEY (ANCESTOR_ID, DESCENDANT_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT IGNORE INTO tmp_account_detail_path_frontier
        (ANCESTOR_ID, DESCENDANT_ID, ANCESTOR_CD, DESCENDANT_CD)
    SELECT ANCESTOR_ID, DESCENDANT_ID, ANCESTOR_CD, DESCENDANT_CD
    FROM tmp_account_detail_account_paths;

    SET v_rows_inserted = 1;
    WHILE v_rows_inserted > 0 DO
        DELETE FROM tmp_account_detail_path_candidates;
        INSERT IGNORE INTO tmp_account_detail_path_candidates
            (ANCESTOR_ID, DESCENDANT_ID, ANCESTOR_CD, DESCENDANT_CD)
        SELECT parent.ACC_ID, paths.DESCENDANT_ID, parent.ACC_CD, paths.DESCENDANT_CD
        FROM tmp_account_detail_path_frontier paths
        INNER JOIN acclist_info child ON child.ACC_ID = paths.ANCESTOR_ID
        INNER JOIN acclist_info parent ON parent.ACC_ID = child.ACC_PARENT_ID
        WHERE child.ACC_PARENT_ID > 0
          AND child.COMPANY_CD = v_company_cd
          AND parent.COMPANY_CD = v_company_cd
          AND IFNULL(child.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
          AND IFNULL(parent.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci;

        INSERT IGNORE INTO tmp_account_detail_account_paths
            (ANCESTOR_ID, DESCENDANT_ID, ANCESTOR_CD, DESCENDANT_CD)
        SELECT ANCESTOR_ID, DESCENDANT_ID, ANCESTOR_CD, DESCENDANT_CD
        FROM tmp_account_detail_path_candidates;
        SET v_rows_inserted = ROW_COUNT();

        DELETE FROM tmp_account_detail_path_frontier;
        INSERT IGNORE INTO tmp_account_detail_path_frontier
            (ANCESTOR_ID, DESCENDANT_ID, ANCESTOR_CD, DESCENDANT_CD)
        SELECT ANCESTOR_ID, DESCENDANT_ID, ANCESTOR_CD, DESCENDANT_CD
        FROM tmp_account_detail_path_candidates;
    END WHILE;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_path_candidates;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_path_frontier;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_latest_open;
    CREATE TEMPORARY TABLE tmp_account_detail_latest_open
    (
        ACC_CD VARCHAR(20) NOT NULL,
        OPEN_YMD VARCHAR(8) NOT NULL DEFAULT '',
        PRIMARY KEY (ACC_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_account_detail_latest_open (ACC_CD, OPEN_YMD)
    SELECT account.ACC_CD, IFNULL(MAX(opening.OPEN_YMD), '')
    FROM tmp_account_detail_accounts account
    LEFT JOIN before_states opening
        ON opening.COMPANY_CD = v_company_cd
       AND opening.ACC_CD COLLATE utf8_unicode_ci = account.ACC_CD COLLATE utf8_unicode_ci
       AND IFNULL(opening.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
       AND IFNULL(opening.OPEN_YMD, '') <= v_before_from_ymd
       AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(opening.FC_TYPE, 'VND')) COLLATE utf8_unicode_ci, v_fc_type COLLATE utf8_unicode_ci) > 0)
    GROUP BY account.ACC_CD;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_opening_base;
    CREATE TEMPORARY TABLE tmp_account_detail_opening_base
    (
        ACC_CD VARCHAR(20) NOT NULL,
        OPEN_YMD VARCHAR(8) NOT NULL DEFAULT '00000000',
        DEBIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        CREDIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PRIMARY KEY (ACC_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_account_detail_opening_base (ACC_CD, OPEN_YMD, DEBIT_AMOUNT, CREDIT_AMOUNT)
    SELECT
        account.ACC_CD,
        IFNULL(NULLIF(latest.OPEN_YMD, ''), '00000000'),
        IFNULL(SUM(CASE WHEN v_use_fc = 1 THEN opening.DEBIT_FC ELSE opening.DEBIT END), 0),
        IFNULL(SUM(CASE WHEN v_use_fc = 1 THEN opening.CREDIT_FC ELSE opening.CREDIT END), 0)
    FROM tmp_account_detail_accounts account
    LEFT JOIN tmp_account_detail_latest_open latest
        ON latest.ACC_CD = account.ACC_CD
    LEFT JOIN before_states opening
        ON opening.COMPANY_CD = v_company_cd
       AND opening.ACC_CD COLLATE utf8_unicode_ci = account.ACC_CD COLLATE utf8_unicode_ci
       AND opening.OPEN_YMD = latest.OPEN_YMD
       AND IFNULL(opening.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
       AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(opening.FC_TYPE, 'VND')) COLLATE utf8_unicode_ci, v_fc_type COLLATE utf8_unicode_ci) > 0)
    GROUP BY account.ACC_CD, latest.OPEN_YMD;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_movements;
    CREATE TEMPORARY TABLE tmp_account_detail_movements
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ACCOUNT_SORT INT NOT NULL DEFAULT 0,
        ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        CHIT_YMD VARCHAR(8) NOT NULL DEFAULT '',
        ENTRY_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DOCUMENT_NO VARCHAR(50) NOT NULL DEFAULT '',
        DOCUMENT_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
        COUNTER_ACCOUNT VARCHAR(50) NOT NULL DEFAULT '',
        DEBIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        CREDIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOTE_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        SORT_NO VARCHAR(50) NOT NULL DEFAULT '',
        SORT_CHIT_ID BIGINT NOT NULL DEFAULT 0,
        SOURCE_CHIT_TYPE VARCHAR(20) NOT NULL DEFAULT '',
        SORT_DETAIL INT NOT NULL DEFAULT 0,
        SORT_SIDE INT NOT NULL DEFAULT 0,
        PRIMARY KEY (ROW_NO),
        INDEX idx_tmp_account_detail_movements_01 (ACC_CD, CHIT_YMD, SORT_NO, SORT_CHIT_ID, SORT_DETAIL, SORT_SIDE)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_account_detail_movements
    (
        ACCOUNT_SORT,
        ACC_CD,
        ACCOUNT_NAME,
        CHIT_YMD,
        ENTRY_DATE,
        DOCUMENT_NO,
        DOCUMENT_DATE,
        DESCRIPTION,
        COUNTER_ACCOUNT,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT,
        NOTE_TEXT,
        SORT_NO,
        SORT_CHIT_ID,
        SOURCE_CHIT_TYPE,
        SORT_DETAIL,
        SORT_SIDE
    )
    SELECT
        account.ACCOUNT_SORT,
        account.ACC_CD,
        account.ACCOUNT_NAME,
        COALESCE(NULLIF(TRIM(IFNULL(h.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(d.CHIT_YMD, '')), ''), ''),
        CASE WHEN IFNULL(h.CHIT_YMD, '') REGEXP '^[0-9]{8}$' THEN DATE_FORMAT(STR_TO_DATE(h.CHIT_YMD, '%Y%m%d'), '%d/%m/%Y') ELSE IFNULL(h.CHIT_YMD, '') END,
        COALESCE(NULLIF(TRIM(h.CHIT_NO), ''), NULLIF(TRIM(h.CHIT_CD), ''), ''),
        CASE
            WHEN COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD) REGEXP '^[0-9]{8}$'
            THEN DATE_FORMAT(STR_TO_DATE(COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD), '%Y%m%d'), '%d/%m/%Y')
            ELSE COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD)
        END,
        COALESCE(
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN ddesc_en.DESCRIPTION WHEN 'KOR' THEN ddesc_ko.DESCRIPTION WHEN 'CHINA' THEN ddesc_china.DESCRIPTION ELSE ddesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN hdesc_en.DESCRIPTION WHEN 'KOR' THEN hdesc_ko.DESCRIPTION WHEN 'CHINA' THEN hdesc_china.DESCRIPTION ELSE hdesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(h.PAYER_INFO), ''),
            ''
        ),
        TRIM(IFNULL(d.CREDIT, '')),
        CASE WHEN v_use_fc = 1 THEN IFNULL(d.FC_AMOUNT, 0) ELSE IFNULL(d.AMOUNT, 0) END,
        0,
        IFNULL(d.CHITDETAIL_CD, ''),
        IFNULL(h.CHIT_NO, ''),
        IFNULL(h.CHIT_ID, 0),
        IFNULL(h.CHIT_TYPE, ''),
        IFNULL(d.SORT, 0),
        1
    FROM chitdetailinfo d
    INNER JOIN tmp_account_detail_accounts account
        ON account.ACC_CD COLLATE utf8_unicode_ci = TRIM(IFNULL(d.DEBIT, '')) COLLATE utf8_unicode_ci
    INNER JOIN chitinfo h
        ON h.COMPANY_CD = d.COMPANY_CD
       AND h.CHIT_ID = d.CHIT_ID
       AND IFNULL(h.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdescriptioninfo hdesc_vi ON hdesc_vi.COMPANY_CD = h.COMPANY_CD AND hdesc_vi.CHIT_ID = h.CHIT_ID AND hdesc_vi.LANG_TYPE = 'VIET' COLLATE utf8_unicode_ci AND IFNULL(hdesc_vi.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdescriptioninfo hdesc_en ON hdesc_en.COMPANY_CD = h.COMPANY_CD AND hdesc_en.CHIT_ID = h.CHIT_ID AND hdesc_en.LANG_TYPE = 'ENG' COLLATE utf8_unicode_ci AND IFNULL(hdesc_en.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdescriptioninfo hdesc_ko ON hdesc_ko.COMPANY_CD = h.COMPANY_CD AND hdesc_ko.CHIT_ID = h.CHIT_ID AND hdesc_ko.LANG_TYPE = 'KOR' COLLATE utf8_unicode_ci AND IFNULL(hdesc_ko.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdescriptioninfo hdesc_china ON hdesc_china.COMPANY_CD = h.COMPANY_CD AND hdesc_china.CHIT_ID = h.CHIT_ID AND hdesc_china.LANG_TYPE = 'CHINA' COLLATE utf8_unicode_ci AND IFNULL(hdesc_china.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdetaildescriptioninfo ddesc_vi ON ddesc_vi.COMPANY_CD = d.COMPANY_CD AND ddesc_vi.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_vi.LANG_TYPE = 'VIET' COLLATE utf8_unicode_ci AND IFNULL(ddesc_vi.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdetaildescriptioninfo ddesc_en ON ddesc_en.COMPANY_CD = d.COMPANY_CD AND ddesc_en.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_en.LANG_TYPE = 'ENG' COLLATE utf8_unicode_ci AND IFNULL(ddesc_en.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdetaildescriptioninfo ddesc_ko ON ddesc_ko.COMPANY_CD = d.COMPANY_CD AND ddesc_ko.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_ko.LANG_TYPE = 'KOR' COLLATE utf8_unicode_ci AND IFNULL(ddesc_ko.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdetaildescriptioninfo ddesc_china ON ddesc_china.COMPANY_CD = d.COMPANY_CD AND ddesc_china.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_china.LANG_TYPE = 'CHINA' COLLATE utf8_unicode_ci AND IFNULL(ddesc_china.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    WHERE d.COMPANY_CD = v_company_cd
      AND IFNULL(d.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
      AND IFNULL(d.AMOUNT, 0) <> 0
      AND COALESCE(NULLIF(TRIM(IFNULL(h.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(d.CHIT_YMD, '')), ''), '') <= v_to_ymd
      AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(d.FC_TYPE, 'VND')) COLLATE utf8_unicode_ci, v_fc_type COLLATE utf8_unicode_ci) > 0);

    INSERT INTO tmp_account_detail_movements
    (
        ACCOUNT_SORT,
        ACC_CD,
        ACCOUNT_NAME,
        CHIT_YMD,
        ENTRY_DATE,
        DOCUMENT_NO,
        DOCUMENT_DATE,
        DESCRIPTION,
        COUNTER_ACCOUNT,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT,
        NOTE_TEXT,
        SORT_NO,
        SORT_CHIT_ID,
        SOURCE_CHIT_TYPE,
        SORT_DETAIL,
        SORT_SIDE
    )
    SELECT
        account.ACCOUNT_SORT,
        account.ACC_CD,
        account.ACCOUNT_NAME,
        COALESCE(NULLIF(TRIM(IFNULL(h.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(d.CHIT_YMD, '')), ''), ''),
        CASE WHEN IFNULL(h.CHIT_YMD, '') REGEXP '^[0-9]{8}$' THEN DATE_FORMAT(STR_TO_DATE(h.CHIT_YMD, '%Y%m%d'), '%d/%m/%Y') ELSE IFNULL(h.CHIT_YMD, '') END,
        COALESCE(NULLIF(TRIM(h.CHIT_NO), ''), NULLIF(TRIM(h.CHIT_CD), ''), ''),
        CASE
            WHEN COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD) REGEXP '^[0-9]{8}$'
            THEN DATE_FORMAT(STR_TO_DATE(COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD), '%Y%m%d'), '%d/%m/%Y')
            ELSE COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD)
        END,
        COALESCE(
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN ddesc_en.DESCRIPTION WHEN 'KOR' THEN ddesc_ko.DESCRIPTION WHEN 'CHINA' THEN ddesc_china.DESCRIPTION ELSE ddesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN hdesc_en.DESCRIPTION WHEN 'KOR' THEN hdesc_ko.DESCRIPTION WHEN 'CHINA' THEN hdesc_china.DESCRIPTION ELSE hdesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(h.PAYER_INFO), ''),
            ''
        ),
        TRIM(IFNULL(d.DEBIT, '')),
        0,
        CASE WHEN v_use_fc = 1 THEN IFNULL(d.FC_AMOUNT, 0) ELSE IFNULL(d.AMOUNT, 0) END,
        IFNULL(d.CHITDETAIL_CD, ''),
        IFNULL(h.CHIT_NO, ''),
        IFNULL(h.CHIT_ID, 0),
        IFNULL(h.CHIT_TYPE, ''),
        IFNULL(d.SORT, 0),
        2
    FROM chitdetailinfo d
    INNER JOIN tmp_account_detail_accounts account
        ON account.ACC_CD COLLATE utf8_unicode_ci = TRIM(IFNULL(d.CREDIT, '')) COLLATE utf8_unicode_ci
    INNER JOIN chitinfo h
        ON h.COMPANY_CD = d.COMPANY_CD
       AND h.CHIT_ID = d.CHIT_ID
       AND IFNULL(h.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdescriptioninfo hdesc_vi ON hdesc_vi.COMPANY_CD = h.COMPANY_CD AND hdesc_vi.CHIT_ID = h.CHIT_ID AND hdesc_vi.LANG_TYPE = 'VIET' COLLATE utf8_unicode_ci AND IFNULL(hdesc_vi.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdescriptioninfo hdesc_en ON hdesc_en.COMPANY_CD = h.COMPANY_CD AND hdesc_en.CHIT_ID = h.CHIT_ID AND hdesc_en.LANG_TYPE = 'ENG' COLLATE utf8_unicode_ci AND IFNULL(hdesc_en.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdescriptioninfo hdesc_ko ON hdesc_ko.COMPANY_CD = h.COMPANY_CD AND hdesc_ko.CHIT_ID = h.CHIT_ID AND hdesc_ko.LANG_TYPE = 'KOR' COLLATE utf8_unicode_ci AND IFNULL(hdesc_ko.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdescriptioninfo hdesc_china ON hdesc_china.COMPANY_CD = h.COMPANY_CD AND hdesc_china.CHIT_ID = h.CHIT_ID AND hdesc_china.LANG_TYPE = 'CHINA' COLLATE utf8_unicode_ci AND IFNULL(hdesc_china.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdetaildescriptioninfo ddesc_vi ON ddesc_vi.COMPANY_CD = d.COMPANY_CD AND ddesc_vi.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_vi.LANG_TYPE = 'VIET' COLLATE utf8_unicode_ci AND IFNULL(ddesc_vi.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdetaildescriptioninfo ddesc_en ON ddesc_en.COMPANY_CD = d.COMPANY_CD AND ddesc_en.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_en.LANG_TYPE = 'ENG' COLLATE utf8_unicode_ci AND IFNULL(ddesc_en.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdetaildescriptioninfo ddesc_ko ON ddesc_ko.COMPANY_CD = d.COMPANY_CD AND ddesc_ko.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_ko.LANG_TYPE = 'KOR' COLLATE utf8_unicode_ci AND IFNULL(ddesc_ko.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    LEFT JOIN chitdetaildescriptioninfo ddesc_china ON ddesc_china.COMPANY_CD = d.COMPANY_CD AND ddesc_china.CHITDETAIL_ID = d.CHITDETAIL_ID AND ddesc_china.LANG_TYPE = 'CHINA' COLLATE utf8_unicode_ci AND IFNULL(ddesc_china.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
    WHERE d.COMPANY_CD = v_company_cd
      AND IFNULL(d.ISDEL, '0') COLLATE utf8_unicode_ci = '0' COLLATE utf8_unicode_ci
      AND IFNULL(d.AMOUNT, 0) <> 0
      AND COALESCE(NULLIF(TRIM(IFNULL(h.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(d.CHIT_YMD, '')), ''), '') <= v_to_ymd
      AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(d.FC_TYPE, 'VND')) COLLATE utf8_unicode_ci, v_fc_type COLLATE utf8_unicode_ci) > 0);

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_sums;
    CREATE TEMPORARY TABLE tmp_account_detail_sums
    (
        ACC_CD VARCHAR(20) NOT NULL,
        OPENING_NET DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PERIOD_DEBIT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PERIOD_CREDIT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        ENDING_NET DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PRIMARY KEY (ACC_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_account_detail_sums (ACC_CD, OPENING_NET, PERIOD_DEBIT, PERIOD_CREDIT, ENDING_NET)
    SELECT
        account.ACC_CD,
        IFNULL(base.DEBIT_AMOUNT, 0) - IFNULL(base.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= IFNULL(base.OPEN_YMD, '00000000')
             AND movement.CHIT_YMD < v_from_ymd
            THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
            ELSE 0
        END), 0),
        IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= v_from_ymd
             AND movement.CHIT_YMD <= v_to_ymd
            THEN movement.DEBIT_AMOUNT
            ELSE 0
        END), 0),
        IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= v_from_ymd
             AND movement.CHIT_YMD <= v_to_ymd
            THEN movement.CREDIT_AMOUNT
            ELSE 0
        END), 0),
        IFNULL(base.DEBIT_AMOUNT, 0) - IFNULL(base.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= IFNULL(base.OPEN_YMD, '00000000')
             AND movement.CHIT_YMD <= v_to_ymd
            THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
            ELSE 0
        END), 0)
    FROM tmp_account_detail_accounts account
    LEFT JOIN tmp_account_detail_opening_base base
        ON base.ACC_CD = account.ACC_CD
    LEFT JOIN tmp_account_detail_movements movement
        ON movement.ACC_CD = account.ACC_CD
    GROUP BY account.ACC_CD, base.OPEN_YMD, base.DEBIT_AMOUNT, base.CREDIT_AMOUNT;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_report;
    CREATE TEMPORARY TABLE tmp_account_detail_report
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ROW_KEY VARCHAR(100) NOT NULL DEFAULT '',
        PARENT_ROW_KEY VARCHAR(100) NULL,
        ROW_SORT INT NOT NULL DEFAULT 0,
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        REPORT_GROUP_KEY VARCHAR(100) NOT NULL DEFAULT '',
        ROW_TYPE VARCHAR(30) NOT NULL DEFAULT '',
        ROW_LEVEL INT NOT NULL DEFAULT 0,
        ACCOUNT_CD_TEXT VARCHAR(1000) NOT NULL DEFAULT '',
        ACCOUNT_NAME_TEXT VARCHAR(1000) NOT NULL DEFAULT '',
        OBJECT_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        CURRENCY_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        REPORT_PERIOD_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        AMOUNT_UNIT_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        ENTRY_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DOCUMENT_NO VARCHAR(50) NOT NULL DEFAULT '',
        DOCUMENT_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
        COUNTER_ACCOUNT VARCHAR(50) NOT NULL DEFAULT '',
        DEBIT_AMOUNT DECIMAL(18,6) NULL,
        CREDIT_AMOUNT DECIMAL(18,6) NULL,
        BALANCE_DEBIT DECIMAL(18,6) NULL,
        BALANCE_CREDIT DECIMAL(18,6) NULL,
        NOTE_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        SOURCE_CHIT_ID BIGINT NULL DEFAULT NULL,
        SOURCE_CHIT_TYPE VARCHAR(20) NOT NULL DEFAULT '',
        PRIMARY KEY (ROW_NO),
        INDEX idx_tmp_account_detail_report_01 (ROW_SORT, ROW_NO)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    IF (SELECT COUNT(*) FROM tmp_account_detail_accounts) = 0 THEN
        INSERT INTO tmp_account_detail_report
        (
            ROW_KEY,
            ROW_SORT,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            ROW_TYPE,
            ROW_LEVEL,
            CURRENCY_TEXT,
            REPORT_PERIOD_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION
        )
        VALUES
        (
            'NO_ACCOUNT',
            10,
            v_company_cd,
            'ACCOUNT_DETAIL',
            'EMPTY',
            0,
            v_currency_text,
            v_report_period_text,
            v_amount_unit_text,
            'Chọn tài khoản để xem sổ chi tiết'
        );
    ELSE
        INSERT INTO tmp_account_detail_report
        (
            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            ROW_TYPE,
            ROW_LEVEL,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            OBJECT_TEXT,
            CURRENCY_TEXT,
            REPORT_PERIOD_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT,
            BALANCE_DEBIT,
            BALANCE_CREDIT
        )
        SELECT
            CONCAT(account.ACC_CD, '_GROUP'),
            CASE WHEN account.PARENT_CD = '' THEN NULL ELSE CONCAT(account.PARENT_CD, '_GROUP') END,
            account.ACCOUNT_SORT * 1000000 + 1,
            v_company_cd,
            CONCAT('ACCOUNT_DETAIL_', account.ACCOUNT_SORT, '_', account.ACC_CD),
            'GROUP',
            account.ACCOUNT_LEVEL,
            account.ACC_CD,
            account.ACCOUNT_NAME,
            '',
            v_currency_text,
            v_report_period_text,
            v_amount_unit_text,
            '',
            ROUND(SUM(IFNULL(sums.PERIOD_DEBIT, 0)), 2),
            ROUND(SUM(IFNULL(sums.PERIOD_CREDIT, 0)), 2),
            ROUND(GREATEST(SUM(IFNULL(sums.ENDING_NET, 0)), 0), 2),
            ROUND(GREATEST(-SUM(IFNULL(sums.ENDING_NET, 0)), 0), 2)
        FROM tmp_account_detail_tree_accounts account
        LEFT JOIN tmp_account_detail_account_paths paths
            ON paths.ANCESTOR_ID = account.ACC_ID
        LEFT JOIN tmp_account_detail_sums sums
            ON sums.ACC_CD = paths.DESCENDANT_CD
        GROUP BY account.ACCOUNT_SORT, account.ACC_ID, account.ACC_PARENT_ID,
            account.PARENT_CD, account.ACC_CD, account.ACCOUNT_NAME, account.ACCOUNT_LEVEL;

        INSERT INTO tmp_account_detail_report
        (
            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            ROW_TYPE,
            ROW_LEVEL,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            OBJECT_TEXT,
            CURRENCY_TEXT,
            REPORT_PERIOD_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION,
            BALANCE_DEBIT,
            BALANCE_CREDIT
        )
        SELECT
            CONCAT(account.ACC_CD, '_OPENING'),
            CONCAT(account.ACC_CD, '_GROUP'),
            account.ACCOUNT_SORT * 1000000 + 10,
            v_company_cd,
            CONCAT('ACCOUNT_DETAIL_', account.ACCOUNT_SORT, '_', account.ACC_CD),
            'OPENING_TOTAL',
            1,
            account.ACC_CD,
            account.ACCOUNT_NAME,
            '',
            v_currency_text,
            v_report_period_text,
            v_amount_unit_text,
            'Số dư đầu kỳ',
            ROUND(GREATEST(sums.OPENING_NET, 0), 2),
            ROUND(GREATEST(-sums.OPENING_NET, 0), 2)
        FROM tmp_account_detail_accounts account
        INNER JOIN tmp_account_detail_sums sums
            ON sums.ACC_CD = account.ACC_CD;

        INSERT INTO tmp_account_detail_report
        (
            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            ROW_TYPE,
            ROW_LEVEL,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            OBJECT_TEXT,
            CURRENCY_TEXT,
            REPORT_PERIOD_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION
        )
        SELECT
            CONCAT(account.ACC_CD, '_PERIOD_HEADER'),
            CONCAT(account.ACC_CD, '_GROUP'),
            account.ACCOUNT_SORT * 1000000 + 20,
            v_company_cd,
            CONCAT('ACCOUNT_DETAIL_', account.ACCOUNT_SORT, '_', account.ACC_CD),
            'SECTION',
            1,
            account.ACC_CD,
            account.ACCOUNT_NAME,
            '',
            v_currency_text,
            v_report_period_text,
            v_amount_unit_text,
            'Số phát sinh trong kỳ'
        FROM tmp_account_detail_accounts account;

        INSERT INTO tmp_account_detail_report
        (
            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            ROW_TYPE,
            ROW_LEVEL,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            OBJECT_TEXT,
            CURRENCY_TEXT,
            REPORT_PERIOD_TEXT,
            AMOUNT_UNIT_TEXT,
            ENTRY_DATE,
            DOCUMENT_NO,
            DOCUMENT_DATE,
            DESCRIPTION,
            COUNTER_ACCOUNT,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT,
            BALANCE_DEBIT,
            BALANCE_CREDIT,
            NOTE_TEXT,
            SOURCE_CHIT_ID,
            SOURCE_CHIT_TYPE
        )
        SELECT
            CONCAT('DETAIL_', running.ROW_NO),
            CONCAT(running.ACC_CD, '_PERIOD_HEADER'),
            running.ACCOUNT_SORT * 1000000 + 1000 + running.ROW_NO,
            v_company_cd,
            CONCAT('ACCOUNT_DETAIL_', running.ACCOUNT_SORT, '_', running.ACC_CD),
            'DETAIL',
            2,
            running.ACC_CD,
            running.ACCOUNT_NAME,
            '',
            v_currency_text,
            v_report_period_text,
            v_amount_unit_text,
            running.ENTRY_DATE,
            running.DOCUMENT_NO,
            running.DOCUMENT_DATE,
            running.DESCRIPTION,
            running.COUNTER_ACCOUNT,
            ROUND(running.DEBIT_AMOUNT, 2),
            ROUND(running.CREDIT_AMOUNT, 2),
            ROUND(GREATEST(running.RUNNING_NET, 0), 2),
            ROUND(GREATEST(-running.RUNNING_NET, 0), 2),
            running.NOTE_TEXT,
            running.SORT_CHIT_ID,
            running.SOURCE_CHIT_TYPE
        FROM
        (
            SELECT
                ordered_movement.*,
                @account_detail_running_balance := CASE
                    WHEN CONVERT(@account_detail_running_account USING utf8) COLLATE utf8_unicode_ci = ordered_movement.ACC_CD COLLATE utf8_unicode_ci
                    THEN @account_detail_running_balance + ordered_movement.DEBIT_AMOUNT - ordered_movement.CREDIT_AMOUNT
                    ELSE ordered_movement.OPENING_NET + ordered_movement.DEBIT_AMOUNT - ordered_movement.CREDIT_AMOUNT
                END AS RUNNING_NET,
                @account_detail_running_account := ordered_movement.ACC_CD AS TRACK_ACC
            FROM
            (
                SELECT
                    movement.ROW_NO,
                    movement.ACCOUNT_SORT,
                    movement.ACC_CD,
                    movement.ACCOUNT_NAME,
                    movement.CHIT_YMD,
                    movement.ENTRY_DATE,
                    movement.DOCUMENT_NO,
                    movement.DOCUMENT_DATE,
                    movement.DESCRIPTION,
                    movement.COUNTER_ACCOUNT,
                    movement.DEBIT_AMOUNT,
                    movement.CREDIT_AMOUNT,
                    movement.NOTE_TEXT,
                    movement.SORT_CHIT_ID,
                    movement.SOURCE_CHIT_TYPE,
                    sums.OPENING_NET
                FROM tmp_account_detail_movements movement
                INNER JOIN tmp_account_detail_sums sums
                    ON sums.ACC_CD = movement.ACC_CD
                WHERE movement.CHIT_YMD >= v_from_ymd
                  AND movement.CHIT_YMD <= v_to_ymd
                ORDER BY movement.ACCOUNT_SORT, movement.CHIT_YMD, movement.SORT_NO, movement.SORT_CHIT_ID, movement.SORT_DETAIL, movement.SORT_SIDE, movement.ROW_NO
            ) ordered_movement
            CROSS JOIN (SELECT @account_detail_running_account := CONVERT('' USING utf8) COLLATE utf8_unicode_ci, @account_detail_running_balance := 0.000000) vars
        ) running;

        INSERT INTO tmp_account_detail_report
        (
            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            ROW_TYPE,
            ROW_LEVEL,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            OBJECT_TEXT,
            CURRENCY_TEXT,
            REPORT_PERIOD_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION,
            COUNTER_ACCOUNT,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT
        )
        SELECT
            CONCAT(account.ACC_CD, '_TOTAL_PERIOD'),
            CONCAT(account.ACC_CD, '_GROUP'),
            account.ACCOUNT_SORT * 1000000 + 900000,
            v_company_cd,
            CONCAT('ACCOUNT_DETAIL_', account.ACCOUNT_SORT, '_', account.ACC_CD),
            'TOTAL_PERIOD',
            1,
            account.ACC_CD,
            account.ACCOUNT_NAME,
            '',
            v_currency_text,
            v_report_period_text,
            v_amount_unit_text,
            'Cộng số phát sinh',
            'x',
            ROUND(sums.PERIOD_DEBIT, 2),
            ROUND(sums.PERIOD_CREDIT, 2)
        FROM tmp_account_detail_accounts account
        INNER JOIN tmp_account_detail_sums sums
            ON sums.ACC_CD = account.ACC_CD;

        INSERT INTO tmp_account_detail_report
        (
            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            ROW_TYPE,
            ROW_LEVEL,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            OBJECT_TEXT,
            CURRENCY_TEXT,
            REPORT_PERIOD_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION,
            COUNTER_ACCOUNT,
            BALANCE_DEBIT,
            BALANCE_CREDIT
        )
        SELECT
            CONCAT(account.ACC_CD, '_ENDING'),
            CONCAT(account.ACC_CD, '_GROUP'),
            account.ACCOUNT_SORT * 1000000 + 900010,
            v_company_cd,
            CONCAT('ACCOUNT_DETAIL_', account.ACCOUNT_SORT, '_', account.ACC_CD),
            'ENDING_TOTAL',
            1,
            account.ACC_CD,
            account.ACCOUNT_NAME,
            '',
            v_currency_text,
            v_report_period_text,
            v_amount_unit_text,
            'Số dư cuối kỳ',
            'x',
            ROUND(GREATEST(sums.ENDING_NET, 0), 2),
            ROUND(GREATEST(-sums.ENDING_NET, 0), 2)
        FROM tmp_account_detail_accounts account
        INNER JOIN tmp_account_detail_sums sums
            ON sums.ACC_CD = account.ACC_CD;
    END IF;

    SELECT
        ROW_KEY AS __ROW_KEY,
        PARENT_ROW_KEY AS __PARENT_ROW_KEY,
        0 AS __TREE_EXPAND_ALL,
        ROW_SORT AS __ROW_SORT,
        COMPANY_CD AS __COMPANY_CD,
        REPORT_GROUP_KEY AS __REPORT_GROUP_KEY,
        ROW_TYPE AS __ROW_TYPE,
        ROW_LEVEL AS __ROW_LEVEL,
        ACCOUNT_CD_TEXT,
        ACCOUNT_NAME_TEXT,
        OBJECT_TEXT,
        CURRENCY_TEXT AS __CURRENCY_TEXT,
        REPORT_PERIOD_TEXT AS __REPORT_PERIOD_TEXT,
        AMOUNT_UNIT_TEXT AS __AMOUNT_UNIT_TEXT,
        ENTRY_DATE,
        DOCUMENT_NO,
        DOCUMENT_DATE,
        DESCRIPTION,
        COUNTER_ACCOUNT,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT,
        BALANCE_DEBIT,
        BALANCE_CREDIT,
        NOTE_TEXT,
        SOURCE_CHIT_ID AS __CHIT_ID,
        SOURCE_CHIT_TYPE AS __CHIT_TYPE,
        CASE WHEN ROW_TYPE = 'DETAIL' AND IFNULL(SOURCE_CHIT_ID, 0) > 0 THEN 'DOCUMENT' ELSE 'NONE' END AS __LINK_TYPE
    FROM tmp_account_detail_report
    ORDER BY ROW_SORT, ROW_NO;

    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_report;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_account_paths;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_tree_accounts;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_sums;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_movements;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_opening_base;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_latest_open;
    DROP TEMPORARY TABLE IF EXISTS tmp_account_detail_accounts;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_ar_aging
DROP PROCEDURE IF EXISTS `rpt_ar_aging`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_ar_aging`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_ACCOUNT_CD VARCHAR(1000),
    IN p_CUSTOMER_CD VARCHAR(1000),
    IN p_FC_TYPE VARCHAR(255),
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_language VARCHAR(20);
    DECLARE v_account_cd VARCHAR(1000);
    DECLARE v_customer_cd VARCHAR(1000);
    DECLARE v_fc_type VARCHAR(255);
    DECLARE v_use_fc TINYINT DEFAULT 0;
    DECLARE v_currency_text VARCHAR(255);
    DECLARE v_report_period_text VARCHAR(255);
    DECLARE v_account_filter_text VARCHAR(1000);
    DECLARE v_amount_unit_text VARCHAR(100);

    IF p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'toDate is required';
    END IF;

    SET v_to_ymd = DATE_FORMAT(p_TO_DATE, '%Y%m%d');
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));
    SET v_account_cd = REPLACE(TRIM(IFNULL(p_ACCOUNT_CD, '')), ' ', '');
    SET v_customer_cd = REPLACE(TRIM(IFNULL(p_CUSTOMER_CD, '')), ' ', '');
    SET v_fc_type = REPLACE(UPPER(TRIM(IFNULL(p_FC_TYPE, ''))), ' ', '');

    IF v_fc_type = 'ALL' THEN
        SET v_fc_type = '';
    END IF;

    SET v_use_fc = CASE WHEN v_fc_type <> '' AND v_fc_type <> 'VND' AND LOCATE(',', v_fc_type) = 0 THEN 1 ELSE 0 END;
    SET v_currency_text = CASE WHEN v_fc_type = '' THEN 'VND' ELSE v_fc_type END;
    SET v_report_period_text = CONCAT('Tài khoản: ', CASE WHEN v_account_cd = '' THEN 'Tất cả' ELSE v_account_cd END, '; Đến ngày ', DATE_FORMAT(p_TO_DATE, '%d/%m/%Y'));
    SET v_account_filter_text = CASE WHEN v_account_cd = '' THEN 'Tài khoản: Tất cả' ELSE CONCAT('Tài khoản: ', v_account_cd) END;
    SET v_amount_unit_text = CONCAT('Đơn vị : ', v_currency_text);

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_customer_by_id;
    CREATE TEMPORARY TABLE tmp_ar_aging_customer_by_id
    (
        CUSTOMER_ID BIGINT NOT NULL,
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (CUSTOMER_ID),
        INDEX idx_tmp_ar_aging_customer_by_id_01 (CUSTOMER_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_customer_by_id (CUSTOMER_ID, CUSTOMER_CD, CUSTOMER_NAME)
    SELECT
        customer.CUSTOMER_ID,
        TRIM(IFNULL(customer.CUSTOMER_CD, '')),
        COALESCE(
            NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN customer.CUSTOMER_NM_ENG
                WHEN 'KOR' THEN customer.CUSTOMER_NM_KOR
                WHEN 'CHINA' THEN customer.CUSTOMER_NM_CHINA
                ELSE customer.CUSTOMER_NM_VIET
            END), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_VIET), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_ENG), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_KOR), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_CHINA), ''),
            TRIM(IFNULL(customer.CUSTOMER_CD, ''))
        )
    FROM customer_info customer
    WHERE customer.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(customer.ISDEL, '0') = '0';

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_customer_by_cd;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_customer_latest_id;
    CREATE TEMPORARY TABLE tmp_ar_aging_customer_by_cd
    (
        CUSTOMER_CD VARCHAR(20) NOT NULL,
        CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (CUSTOMER_CD),
        INDEX idx_tmp_ar_aging_customer_by_cd_01 (CUSTOMER_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    CREATE TEMPORARY TABLE tmp_ar_aging_customer_latest_id
    (
        CUSTOMER_CD VARCHAR(20) NOT NULL,
        LATEST_CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        PRIMARY KEY (CUSTOMER_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_customer_latest_id (CUSTOMER_CD, LATEST_CUSTOMER_ID)
    SELECT source.CUSTOMER_CD, MAX(source.CUSTOMER_ID)
    FROM tmp_ar_aging_customer_by_id source
    WHERE source.CUSTOMER_CD <> ''
    GROUP BY source.CUSTOMER_CD;

    INSERT INTO tmp_ar_aging_customer_by_cd (CUSTOMER_CD, CUSTOMER_ID, CUSTOMER_NAME)
    SELECT by_id.CUSTOMER_CD, by_id.CUSTOMER_ID, by_id.CUSTOMER_NAME
    FROM tmp_ar_aging_customer_by_id by_id
    INNER JOIN tmp_ar_aging_customer_latest_id latest
        ON latest.CUSTOMER_CD = by_id.CUSTOMER_CD
       AND latest.LATEST_CUSTOMER_ID = by_id.CUSTOMER_ID;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_accounts;
    CREATE TEMPORARY TABLE tmp_ar_aging_accounts
    (
        ACCOUNT_SORT INT NOT NULL AUTO_INCREMENT,
        ACC_CD VARCHAR(20) NOT NULL,
        PRIMARY KEY (ACCOUNT_SORT),
        UNIQUE KEY uq_tmp_ar_aging_accounts_01 (ACC_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_accounts (ACC_CD)
    SELECT account.ACC_CD
    FROM acclist_info account
    INNER JOIN
    (
        SELECT ACC_CD, MAX(ACC_ID) AS ACC_ID
        FROM acclist_info
        WHERE COMPANY_CD = p_COMPANY_CD
          AND IFNULL(ISDEL, '0') = '0'
          AND TRIM(IFNULL(ACC_CD, '')) <> ''
        GROUP BY ACC_CD
    ) latest
        ON latest.ACC_ID = account.ACC_ID
    WHERE account.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(account.ISDEL, '0') = '0'
      AND (v_account_cd = '' OR FIND_IN_SET(account.ACC_CD, v_account_cd) > 0)
      AND (v_account_cd <> '' OR IFNULL(account.ISCUSTOMER, '0') = '1')
    ORDER BY account.ACC_CD;

    INSERT IGNORE INTO tmp_ar_aging_accounts (ACC_CD)
    SELECT source.ACC_CD
    FROM
    (
        SELECT DISTINCT TRIM(IFNULL(opening.ACC_CD, '')) AS ACC_CD
        FROM before_states_customer opening
        WHERE opening.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(opening.ISDEL, '0') = '0'
          AND TRIM(IFNULL(opening.ACC_CD, '')) <> ''
          AND IFNULL(opening.OPEN_YMD, '') <= v_to_ymd
        UNION
        SELECT DISTINCT TRIM(IFNULL(detail.DEBIT, '')) AS ACC_CD
        FROM chitdetailinfo detail
        INNER JOIN chitinfo header
            ON header.COMPANY_CD = detail.COMPANY_CD
           AND header.CHIT_ID = detail.CHIT_ID
           AND IFNULL(header.ISDEL, '0') = '0'
        INNER JOIN chitdetailinfo_ext ext
            ON ext.COMPANY_CD = detail.COMPANY_CD
           AND ext.CHITDETAIL_ID = detail.CHITDETAIL_ID
           AND IFNULL(ext.ISDEL, '0') = '0'
        WHERE detail.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(detail.ISDEL, '0') = '0'
          AND TRIM(IFNULL(detail.DEBIT, '')) <> ''
          AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <= v_to_ymd
          AND (IFNULL(ext.CUSTOMER_ID, 0) > 0 OR TRIM(IFNULL(ext.CUSTOMER_CD, '')) <> '')
        UNION
        SELECT DISTINCT TRIM(IFNULL(detail.CREDIT, '')) AS ACC_CD
        FROM chitdetailinfo detail
        INNER JOIN chitinfo header
            ON header.COMPANY_CD = detail.COMPANY_CD
           AND header.CHIT_ID = detail.CHIT_ID
           AND IFNULL(header.ISDEL, '0') = '0'
        INNER JOIN chitdetailinfo_ext ext
            ON ext.COMPANY_CD = detail.COMPANY_CD
           AND ext.CHITDETAIL_ID = detail.CHITDETAIL_ID
           AND IFNULL(ext.ISDEL, '0') = '0'
        WHERE detail.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(detail.ISDEL, '0') = '0'
          AND TRIM(IFNULL(detail.CREDIT, '')) <> ''
          AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <= v_to_ymd
          AND (IFNULL(ext.CUSTOMER_ID, 0) > 0 OR TRIM(IFNULL(ext.CUSTOMER_CD, '')) <> '')
    ) source
    LEFT JOIN
    (
        SELECT account.ACC_CD, IFNULL(account.ISCUSTOMER, '0') AS ISCUSTOMER
        FROM acclist_info account
        INNER JOIN
        (
            SELECT ACC_CD, MAX(ACC_ID) AS ACC_ID
            FROM acclist_info
            WHERE COMPANY_CD = p_COMPANY_CD
              AND IFNULL(ISDEL, '0') = '0'
            GROUP BY ACC_CD
        ) latest_account
            ON latest_account.ACC_ID = account.ACC_ID
    ) account_name
        ON account_name.ACC_CD = source.ACC_CD
    WHERE source.ACC_CD <> ''
      AND (v_account_cd = '' OR FIND_IN_SET(source.ACC_CD, v_account_cd) > 0)
      AND (v_account_cd <> '' OR IFNULL(account_name.ISCUSTOMER, '1') = '1')
    ORDER BY source.ACC_CD;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_latest_open;
    CREATE TEMPORARY TABLE tmp_ar_aging_latest_open
    (
        ACC_CD VARCHAR(20) NOT NULL,
        CUSTOMER_KEY VARCHAR(50) NOT NULL,
        OPEN_YMD VARCHAR(8) NOT NULL DEFAULT '',
        PRIMARY KEY (ACC_CD, CUSTOMER_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_latest_open (ACC_CD, CUSTOMER_KEY, OPEN_YMD)
    SELECT
        account.ACC_CD,
        CONCAT('ID:', opening.CUSTOMER_ID),
        IFNULL(MAX(opening.OPEN_YMD), '')
    FROM before_states_customer opening
    INNER JOIN tmp_ar_aging_accounts account
        ON account.ACC_CD = opening.ACC_CD
    LEFT JOIN tmp_ar_aging_customer_by_id customer
        ON customer.CUSTOMER_ID = IFNULL(opening.CUSTOMER_ID, 0)
    WHERE opening.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(opening.ISDEL, '0') = '0'
      AND IFNULL(opening.CUSTOMER_ID, 0) > 0
      AND IFNULL(opening.OPEN_YMD, '') <= v_to_ymd
      AND (v_customer_cd = '' OR FIND_IN_SET(customer.CUSTOMER_CD, v_customer_cd) > 0)
      AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(opening.FC_TYPE, 'VND')), v_fc_type) > 0)
    GROUP BY account.ACC_CD, opening.CUSTOMER_ID;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_opening;
    CREATE TEMPORARY TABLE tmp_ar_aging_opening
    (
        ACC_CD VARCHAR(20) NOT NULL,
        CUSTOMER_KEY VARCHAR(50) NOT NULL,
        CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        OPEN_YMD VARCHAR(8) NOT NULL DEFAULT '00000000',
        OPENING_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PRIMARY KEY (ACC_CD, CUSTOMER_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_opening
    (
        ACC_CD,
        CUSTOMER_KEY,
        CUSTOMER_ID,
        CUSTOMER_CD,
        CUSTOMER_NAME,
        OPEN_YMD,
        OPENING_AMOUNT
    )
    SELECT
        latest.ACC_CD,
        latest.CUSTOMER_KEY,
        opening.CUSTOMER_ID,
        IFNULL(customer.CUSTOMER_CD, ''),
        COALESCE(NULLIF(customer.CUSTOMER_NAME, ''), NULLIF(opening.CUSTOMER_NM, ''), IFNULL(customer.CUSTOMER_CD, '')),
        IFNULL(NULLIF(latest.OPEN_YMD, ''), '00000000'),
        IFNULL(SUM(CASE WHEN v_use_fc = 1 THEN opening.DEBIT_FC - opening.CREDIT_FC ELSE opening.DEBIT - opening.CREDIT END), 0)
    FROM tmp_ar_aging_latest_open latest
    INNER JOIN before_states_customer opening
        ON opening.COMPANY_CD = p_COMPANY_CD
       AND opening.ACC_CD = latest.ACC_CD
       AND CONCAT('ID:', opening.CUSTOMER_ID) = latest.CUSTOMER_KEY
       AND opening.OPEN_YMD = latest.OPEN_YMD
       AND IFNULL(opening.ISDEL, '0') = '0'
    LEFT JOIN tmp_ar_aging_customer_by_id customer
        ON customer.CUSTOMER_ID = IFNULL(opening.CUSTOMER_ID, 0)
    WHERE v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(opening.FC_TYPE, 'VND')), v_fc_type) > 0
    GROUP BY latest.ACC_CD, latest.CUSTOMER_KEY, opening.CUSTOMER_ID, customer.CUSTOMER_CD, customer.CUSTOMER_NAME, opening.CUSTOMER_NM, latest.OPEN_YMD;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_movements;
    CREATE TEMPORARY TABLE tmp_ar_aging_movements
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_KEY VARCHAR(50) NOT NULL DEFAULT '',
        CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_OWN_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        CHIT_YMD VARCHAR(8) NOT NULL DEFAULT '',
        DUE_YMD VARCHAR(8) NOT NULL DEFAULT '',
        HAS_DUE TINYINT NOT NULL DEFAULT 0,
        SIGNED_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PRIMARY KEY (ROW_NO),
        INDEX idx_tmp_ar_aging_movements_01 (ACC_CD, CUSTOMER_KEY, CHIT_YMD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_movements
    (
        ACC_CD,
        CUSTOMER_KEY,
        CUSTOMER_ID,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        CHIT_YMD,
        DUE_YMD,
        HAS_DUE,
        SIGNED_AMOUNT
    )
    SELECT
        account.ACC_CD,
        CASE
            WHEN IFNULL(ext.CUSTOMER_ID, 0) > 0 THEN CONCAT('ID:', ext.CUSTOMER_ID)
            WHEN by_cd.CUSTOMER_ID > 0 THEN CONCAT('ID:', by_cd.CUSTOMER_ID)
            ELSE CONCAT('CD:', TRIM(IFNULL(ext.CUSTOMER_CD, '')))
        END,
        COALESCE(NULLIF(ext.CUSTOMER_ID, 0), by_cd.CUSTOMER_ID, 0),
        COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), ''),
        TRIM(IFNULL(ext.CUSTOMER_OWN_CD, '')),
        COALESCE(NULLIF(by_id.CUSTOMER_NAME, ''), NULLIF(by_cd.CUSTOMER_NAME, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), CAST(IFNULL(ext.CUSTOMER_ID, 0) AS CHAR)),
        COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), ''),
        CASE
            WHEN TRIM(IFNULL(header_ext.DAY_OF_PAYMENT, '')) REGEXP '^[0-9]+$'
             AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') REGEXP '^[0-9]{8}$'
            THEN DATE_FORMAT(DATE_ADD(STR_TO_DATE(COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), '')), '%Y%m%d'), INTERVAL CAST(header_ext.DAY_OF_PAYMENT AS UNSIGNED) DAY), '%Y%m%d')
            ELSE ''
        END,
        CASE
            WHEN TRIM(IFNULL(header_ext.DAY_OF_PAYMENT, '')) REGEXP '^[0-9]+$'
             AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') REGEXP '^[0-9]{8}$'
            THEN 1
            ELSE 0
        END,
        CASE WHEN v_use_fc = 1 THEN IFNULL(detail.FC_AMOUNT, 0) ELSE IFNULL(detail.AMOUNT, 0) END
    FROM chitdetailinfo detail
    INNER JOIN tmp_ar_aging_accounts account
        ON account.ACC_CD = TRIM(IFNULL(detail.DEBIT, ''))
    INNER JOIN chitinfo header
        ON header.COMPANY_CD = detail.COMPANY_CD
       AND header.CHIT_ID = detail.CHIT_ID
       AND IFNULL(header.ISDEL, '0') = '0'
    INNER JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = detail.COMPANY_CD
       AND ext.CHITDETAIL_ID = detail.CHITDETAIL_ID
       AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN chitinfo_ext header_ext
        ON header_ext.COMPANY_CD = header.COMPANY_CD
       AND header_ext.CHIT_ID = header.CHIT_ID
       AND IFNULL(header_ext.ISDEL, '0') = '0'
    LEFT JOIN tmp_ar_aging_customer_by_id by_id
        ON by_id.CUSTOMER_ID = IFNULL(ext.CUSTOMER_ID, 0)
    LEFT JOIN tmp_ar_aging_customer_by_cd by_cd
        ON by_cd.CUSTOMER_CD = TRIM(IFNULL(ext.CUSTOMER_CD, ''))
    WHERE detail.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(detail.ISDEL, '0') = '0'
      AND IFNULL(detail.AMOUNT, 0) <> 0
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <= v_to_ymd
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <> ''
      AND (IFNULL(ext.CUSTOMER_ID, 0) > 0 OR TRIM(IFNULL(ext.CUSTOMER_CD, '')) <> '')
      AND (v_customer_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), '')), v_customer_cd) > 0)
      AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(detail.FC_TYPE, 'VND')), v_fc_type) > 0);

    INSERT INTO tmp_ar_aging_movements
    (
        ACC_CD,
        CUSTOMER_KEY,
        CUSTOMER_ID,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        CHIT_YMD,
        DUE_YMD,
        HAS_DUE,
        SIGNED_AMOUNT
    )
    SELECT
        account.ACC_CD,
        CASE
            WHEN IFNULL(ext.CUSTOMER_ID, 0) > 0 THEN CONCAT('ID:', ext.CUSTOMER_ID)
            WHEN by_cd.CUSTOMER_ID > 0 THEN CONCAT('ID:', by_cd.CUSTOMER_ID)
            ELSE CONCAT('CD:', TRIM(IFNULL(ext.CUSTOMER_CD, '')))
        END,
        COALESCE(NULLIF(ext.CUSTOMER_ID, 0), by_cd.CUSTOMER_ID, 0),
        COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), ''),
        TRIM(IFNULL(ext.CUSTOMER_OWN_CD, '')),
        COALESCE(NULLIF(by_id.CUSTOMER_NAME, ''), NULLIF(by_cd.CUSTOMER_NAME, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), CAST(IFNULL(ext.CUSTOMER_ID, 0) AS CHAR)),
        COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), ''),
        CASE
            WHEN TRIM(IFNULL(header_ext.DAY_OF_PAYMENT, '')) REGEXP '^[0-9]+$'
             AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') REGEXP '^[0-9]{8}$'
            THEN DATE_FORMAT(DATE_ADD(STR_TO_DATE(COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), '')), '%Y%m%d'), INTERVAL CAST(header_ext.DAY_OF_PAYMENT AS UNSIGNED) DAY), '%Y%m%d')
            ELSE ''
        END,
        CASE
            WHEN TRIM(IFNULL(header_ext.DAY_OF_PAYMENT, '')) REGEXP '^[0-9]+$'
             AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') REGEXP '^[0-9]{8}$'
            THEN 1
            ELSE 0
        END,
        -CASE WHEN v_use_fc = 1 THEN IFNULL(detail.FC_AMOUNT, 0) ELSE IFNULL(detail.AMOUNT, 0) END
    FROM chitdetailinfo detail
    INNER JOIN tmp_ar_aging_accounts account
        ON account.ACC_CD = TRIM(IFNULL(detail.CREDIT, ''))
    INNER JOIN chitinfo header
        ON header.COMPANY_CD = detail.COMPANY_CD
       AND header.CHIT_ID = detail.CHIT_ID
       AND IFNULL(header.ISDEL, '0') = '0'
    INNER JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = detail.COMPANY_CD
       AND ext.CHITDETAIL_ID = detail.CHITDETAIL_ID
       AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN chitinfo_ext header_ext
        ON header_ext.COMPANY_CD = header.COMPANY_CD
       AND header_ext.CHIT_ID = header.CHIT_ID
       AND IFNULL(header_ext.ISDEL, '0') = '0'
    LEFT JOIN tmp_ar_aging_customer_by_id by_id
        ON by_id.CUSTOMER_ID = IFNULL(ext.CUSTOMER_ID, 0)
    LEFT JOIN tmp_ar_aging_customer_by_cd by_cd
        ON by_cd.CUSTOMER_CD = TRIM(IFNULL(ext.CUSTOMER_CD, ''))
    WHERE detail.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(detail.ISDEL, '0') = '0'
      AND IFNULL(detail.AMOUNT, 0) <> 0
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <= v_to_ymd
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <> ''
      AND (IFNULL(ext.CUSTOMER_ID, 0) > 0 OR TRIM(IFNULL(ext.CUSTOMER_CD, '')) <> '')
      AND (v_customer_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), '')), v_customer_cd) > 0)
      AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(detail.FC_TYPE, 'VND')), v_fc_type) > 0);

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_subjects;
    CREATE TEMPORARY TABLE tmp_ar_aging_subjects
    (
        CUSTOMER_KEY VARCHAR(50) NOT NULL,
        CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_OWN_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (CUSTOMER_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_subjects (CUSTOMER_KEY, CUSTOMER_ID, CUSTOMER_CD, CUSTOMER_OWN_CD, CUSTOMER_NAME)
    SELECT
        movement.CUSTOMER_KEY,
        MAX(movement.CUSTOMER_ID),
        MAX(movement.CUSTOMER_CD),
        MAX(movement.CUSTOMER_OWN_CD),
        MAX(movement.CUSTOMER_NAME)
    FROM tmp_ar_aging_movements movement
    WHERE movement.CUSTOMER_KEY <> ''
    GROUP BY movement.CUSTOMER_KEY;

    INSERT INTO tmp_ar_aging_subjects (CUSTOMER_KEY, CUSTOMER_ID, CUSTOMER_CD, CUSTOMER_OWN_CD, CUSTOMER_NAME)
    SELECT
        opening.CUSTOMER_KEY,
        opening.CUSTOMER_ID,
        opening.CUSTOMER_CD,
        '',
        opening.CUSTOMER_NAME
    FROM tmp_ar_aging_opening opening
    ON DUPLICATE KEY UPDATE
        CUSTOMER_ID = IF(tmp_ar_aging_subjects.CUSTOMER_ID = 0, VALUES(CUSTOMER_ID), tmp_ar_aging_subjects.CUSTOMER_ID),
        CUSTOMER_CD = IF(tmp_ar_aging_subjects.CUSTOMER_CD = '', VALUES(CUSTOMER_CD), tmp_ar_aging_subjects.CUSTOMER_CD),
        CUSTOMER_NAME = IF(tmp_ar_aging_subjects.CUSTOMER_NAME = '', VALUES(CUSTOMER_NAME), tmp_ar_aging_subjects.CUSTOMER_NAME);

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_keys;
    CREATE TEMPORARY TABLE tmp_ar_aging_keys
    (
        ACC_CD VARCHAR(20) NOT NULL,
        CUSTOMER_KEY VARCHAR(50) NOT NULL,
        PRIMARY KEY (ACC_CD, CUSTOMER_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT IGNORE INTO tmp_ar_aging_keys (ACC_CD, CUSTOMER_KEY)
    SELECT ACC_CD, CUSTOMER_KEY
    FROM tmp_ar_aging_opening;

    INSERT IGNORE INTO tmp_ar_aging_keys (ACC_CD, CUSTOMER_KEY)
    SELECT ACC_CD, CUSTOMER_KEY
    FROM tmp_ar_aging_movements
    WHERE CUSTOMER_KEY <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_account_balance;
    CREATE TEMPORARY TABLE tmp_ar_aging_account_balance
    (
        ACC_CD VARCHAR(20) NOT NULL,
        CUSTOMER_KEY VARCHAR(50) NOT NULL DEFAULT '',
        TOTAL_RECEIVABLE DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOT_DUE_NO_TERM DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOT_DUE_0_30 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOT_DUE_31_60 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOT_DUE_61_90 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOT_DUE_OVER_90 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OVERDUE_0_30 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OVERDUE_31_60 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OVERDUE_61_90 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OVERDUE_OVER_90 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OVERDUE_TOTAL DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PRIMARY KEY (ACC_CD, CUSTOMER_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_account_balance
    (
        ACC_CD,
        CUSTOMER_KEY,
        TOTAL_RECEIVABLE,
        NOT_DUE_NO_TERM,
        NOT_DUE_0_30,
        NOT_DUE_31_60,
        NOT_DUE_61_90,
        NOT_DUE_OVER_90,
        OVERDUE_0_30,
        OVERDUE_31_60,
        OVERDUE_61_90,
        OVERDUE_OVER_90,
        OVERDUE_TOTAL
    )
    SELECT
        aging_key.ACC_CD,
        aging_key.CUSTOMER_KEY,
        IFNULL(MAX(opening.OPENING_AMOUNT), 0) + IFNULL(SUM(CASE WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000') THEN movement.SIGNED_AMOUNT ELSE 0 END), 0),
        IFNULL(MAX(opening.OPENING_AMOUNT), 0) + IFNULL(SUM(CASE WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000') AND movement.HAS_DUE = 0 THEN movement.SIGNED_AMOUNT ELSE 0 END), 0),
        IFNULL(SUM(CASE WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000') AND movement.HAS_DUE = 1 AND movement.DUE_YMD >= v_to_ymd AND DATEDIFF(STR_TO_DATE(movement.DUE_YMD, '%Y%m%d'), p_TO_DATE) BETWEEN 0 AND 30 THEN movement.SIGNED_AMOUNT ELSE 0 END), 0),
        IFNULL(SUM(CASE WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000') AND movement.HAS_DUE = 1 AND movement.DUE_YMD >= v_to_ymd AND DATEDIFF(STR_TO_DATE(movement.DUE_YMD, '%Y%m%d'), p_TO_DATE) BETWEEN 31 AND 60 THEN movement.SIGNED_AMOUNT ELSE 0 END), 0),
        IFNULL(SUM(CASE WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000') AND movement.HAS_DUE = 1 AND movement.DUE_YMD >= v_to_ymd AND DATEDIFF(STR_TO_DATE(movement.DUE_YMD, '%Y%m%d'), p_TO_DATE) BETWEEN 61 AND 90 THEN movement.SIGNED_AMOUNT ELSE 0 END), 0),
        IFNULL(SUM(CASE WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000') AND movement.HAS_DUE = 1 AND movement.DUE_YMD >= v_to_ymd AND DATEDIFF(STR_TO_DATE(movement.DUE_YMD, '%Y%m%d'), p_TO_DATE) > 90 THEN movement.SIGNED_AMOUNT ELSE 0 END), 0),
        IFNULL(SUM(CASE WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000') AND movement.HAS_DUE = 1 AND movement.DUE_YMD < v_to_ymd AND DATEDIFF(p_TO_DATE, STR_TO_DATE(movement.DUE_YMD, '%Y%m%d')) BETWEEN 1 AND 30 THEN movement.SIGNED_AMOUNT ELSE 0 END), 0),
        IFNULL(SUM(CASE WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000') AND movement.HAS_DUE = 1 AND movement.DUE_YMD < v_to_ymd AND DATEDIFF(p_TO_DATE, STR_TO_DATE(movement.DUE_YMD, '%Y%m%d')) BETWEEN 31 AND 60 THEN movement.SIGNED_AMOUNT ELSE 0 END), 0),
        IFNULL(SUM(CASE WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000') AND movement.HAS_DUE = 1 AND movement.DUE_YMD < v_to_ymd AND DATEDIFF(p_TO_DATE, STR_TO_DATE(movement.DUE_YMD, '%Y%m%d')) BETWEEN 61 AND 90 THEN movement.SIGNED_AMOUNT ELSE 0 END), 0),
        IFNULL(SUM(CASE WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000') AND movement.HAS_DUE = 1 AND movement.DUE_YMD < v_to_ymd AND DATEDIFF(p_TO_DATE, STR_TO_DATE(movement.DUE_YMD, '%Y%m%d')) > 90 THEN movement.SIGNED_AMOUNT ELSE 0 END), 0),
        IFNULL(SUM(CASE WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000') AND movement.HAS_DUE = 1 AND movement.DUE_YMD < v_to_ymd THEN movement.SIGNED_AMOUNT ELSE 0 END), 0)
    FROM tmp_ar_aging_keys aging_key
    LEFT JOIN tmp_ar_aging_opening opening
        ON opening.ACC_CD = aging_key.ACC_CD
       AND opening.CUSTOMER_KEY = aging_key.CUSTOMER_KEY
    LEFT JOIN tmp_ar_aging_movements movement
        ON movement.ACC_CD = aging_key.ACC_CD
       AND movement.CUSTOMER_KEY = aging_key.CUSTOMER_KEY
    GROUP BY aging_key.ACC_CD, aging_key.CUSTOMER_KEY;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_balance;
    CREATE TEMPORARY TABLE tmp_ar_aging_balance
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        CUSTOMER_KEY VARCHAR(50) NOT NULL DEFAULT '',
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_OWN_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        TOTAL_RECEIVABLE DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOT_DUE_NO_TERM DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOT_DUE_0_30 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOT_DUE_31_60 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOT_DUE_61_90 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOT_DUE_OVER_90 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OVERDUE_0_30 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OVERDUE_31_60 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OVERDUE_61_90 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OVERDUE_OVER_90 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OVERDUE_TOTAL DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PRIMARY KEY (ROW_NO),
        INDEX idx_tmp_ar_aging_balance_01 (CUSTOMER_CD, CUSTOMER_NAME)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_balance
    (
        CUSTOMER_KEY,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        TOTAL_RECEIVABLE,
        NOT_DUE_NO_TERM,
        NOT_DUE_0_30,
        NOT_DUE_31_60,
        NOT_DUE_61_90,
        NOT_DUE_OVER_90,
        OVERDUE_0_30,
        OVERDUE_31_60,
        OVERDUE_61_90,
        OVERDUE_OVER_90,
        OVERDUE_TOTAL
    )
    SELECT
        subject.CUSTOMER_KEY,
        subject.CUSTOMER_CD,
        subject.CUSTOMER_OWN_CD,
        subject.CUSTOMER_NAME,
        IFNULL(SUM(account_balance.TOTAL_RECEIVABLE), 0) AS TOTAL_RECEIVABLE,
        IFNULL(SUM(account_balance.NOT_DUE_NO_TERM), 0) AS NOT_DUE_NO_TERM,
        IFNULL(SUM(account_balance.NOT_DUE_0_30), 0) AS NOT_DUE_0_30,
        IFNULL(SUM(account_balance.NOT_DUE_31_60), 0) AS NOT_DUE_31_60,
        IFNULL(SUM(account_balance.NOT_DUE_61_90), 0) AS NOT_DUE_61_90,
        IFNULL(SUM(account_balance.NOT_DUE_OVER_90), 0) AS NOT_DUE_OVER_90,
        IFNULL(SUM(account_balance.OVERDUE_0_30), 0) AS OVERDUE_0_30,
        IFNULL(SUM(account_balance.OVERDUE_31_60), 0) AS OVERDUE_31_60,
        IFNULL(SUM(account_balance.OVERDUE_61_90), 0) AS OVERDUE_61_90,
        IFNULL(SUM(account_balance.OVERDUE_OVER_90), 0) AS OVERDUE_OVER_90,
        IFNULL(SUM(account_balance.OVERDUE_TOTAL), 0) AS OVERDUE_TOTAL
    FROM tmp_ar_aging_account_balance account_balance
    INNER JOIN tmp_ar_aging_subjects subject
        ON subject.CUSTOMER_KEY = account_balance.CUSTOMER_KEY
    GROUP BY subject.CUSTOMER_KEY, subject.CUSTOMER_CD, subject.CUSTOMER_OWN_CD, subject.CUSTOMER_NAME
    HAVING ROUND(TOTAL_RECEIVABLE, 0) <> 0
    ORDER BY subject.CUSTOMER_CD, subject.CUSTOMER_NAME, subject.CUSTOMER_KEY;

    SELECT
        CONCAT('AR_AGING_', ROW_NO) AS ROW_KEY,
        ROW_NO AS ROW_SORT,
        'DETAIL' AS ROW_TYPE,
        0 AS ROW_LEVEL,
        p_COMPANY_CD AS COMPANY_CD,
        'AR_AGING' AS REPORT_GROUP_KEY,
        v_report_period_text AS REPORT_PERIOD_TEXT,
        v_account_filter_text AS ACCOUNT_FILTER_TEXT,
        v_currency_text AS CURRENCY_TEXT,
        v_amount_unit_text AS AMOUNT_UNIT_TEXT,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        NULLIF(ROUND(TOTAL_RECEIVABLE, 0), 0) AS TOTAL_RECEIVABLE,
        NULLIF(ROUND(NOT_DUE_NO_TERM, 0), 0) AS NOT_DUE_NO_TERM,
        NULLIF(ROUND(NOT_DUE_0_30, 0), 0) AS NOT_DUE_0_30,
        NULLIF(ROUND(NOT_DUE_31_60, 0), 0) AS NOT_DUE_31_60,
        NULLIF(ROUND(NOT_DUE_61_90, 0), 0) AS NOT_DUE_61_90,
        NULLIF(ROUND(NOT_DUE_OVER_90, 0), 0) AS NOT_DUE_OVER_90,
        NULLIF(ROUND(OVERDUE_0_30, 0), 0) AS OVERDUE_0_30,
        NULLIF(ROUND(OVERDUE_31_60, 0), 0) AS OVERDUE_31_60,
        NULLIF(ROUND(OVERDUE_61_90, 0), 0) AS OVERDUE_61_90,
        NULLIF(ROUND(OVERDUE_OVER_90, 0), 0) AS OVERDUE_OVER_90,
        NULLIF(ROUND(OVERDUE_TOTAL, 0), 0) AS OVERDUE_TOTAL
    FROM tmp_ar_aging_balance
    ORDER BY CUSTOMER_CD, CUSTOMER_NAME, ROW_NO;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_balance;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_account_balance;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_keys;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_subjects;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_movements;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_opening;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_latest_open;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_accounts;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_customer_by_cd;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_customer_latest_id;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_customer_by_id;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_ar_aging_detail
DROP PROCEDURE IF EXISTS `rpt_ar_aging_detail`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_ar_aging_detail`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_ACCOUNT_CD VARCHAR(1000),
    IN p_CUSTOMER_CD VARCHAR(1000),
    IN p_FC_TYPE VARCHAR(255),
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_language VARCHAR(20);
    DECLARE v_account_cd VARCHAR(1000);
    DECLARE v_customer_cd VARCHAR(1000);
    DECLARE v_fc_type VARCHAR(255);
    DECLARE v_use_fc TINYINT DEFAULT 0;
    DECLARE v_currency_text VARCHAR(255);
    DECLARE v_report_period_text VARCHAR(255);
    DECLARE v_account_filter_text VARCHAR(1000);
    DECLARE v_customer_filter_text VARCHAR(1000);

    IF p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'toDate is required';
    END IF;

    SET v_to_ymd = DATE_FORMAT(p_TO_DATE, '%Y%m%d');
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));
    SET v_account_cd = REPLACE(TRIM(IFNULL(p_ACCOUNT_CD, '')), ' ', '');
    SET v_customer_cd = REPLACE(TRIM(IFNULL(p_CUSTOMER_CD, '')), ' ', '');
    SET v_fc_type = REPLACE(UPPER(TRIM(IFNULL(p_FC_TYPE, ''))), ' ', '');

    IF v_fc_type = 'ALL' THEN
        SET v_fc_type = '';
    END IF;

    SET v_use_fc = CASE WHEN v_fc_type <> '' AND v_fc_type <> 'VND' AND LOCATE(',', v_fc_type) = 0 THEN 1 ELSE 0 END;
    SET v_currency_text = CASE WHEN v_fc_type = '' THEN 'VND' ELSE v_fc_type END;
    SET v_report_period_text = CONCAT('Tài khoản: ', CASE WHEN v_account_cd = '' THEN 'Tất cả' ELSE v_account_cd END, '; Đến ngày ', DATE_FORMAT(p_TO_DATE, '%d/%m/%Y'));
    SET v_account_filter_text = CASE WHEN v_account_cd = '' THEN 'Tất cả' ELSE v_account_cd END;
    SET v_customer_filter_text = CASE WHEN v_customer_cd = '' THEN 'Tất cả' ELSE v_customer_cd END;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_customer_by_id;
    CREATE TEMPORARY TABLE tmp_ar_aging_detail_customer_by_id
    (
        CUSTOMER_ID BIGINT NOT NULL,
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (CUSTOMER_ID),
        INDEX idx_tmp_ar_aging_detail_customer_by_id_01 (CUSTOMER_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_detail_customer_by_id (CUSTOMER_ID, CUSTOMER_CD, CUSTOMER_NAME)
    SELECT
        customer.CUSTOMER_ID,
        TRIM(IFNULL(customer.CUSTOMER_CD, '')),
        COALESCE(
            NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN customer.CUSTOMER_NM_ENG
                WHEN 'KOR' THEN customer.CUSTOMER_NM_KOR
                WHEN 'CHINA' THEN customer.CUSTOMER_NM_CHINA
                ELSE customer.CUSTOMER_NM_VIET
            END), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_VIET), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_ENG), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_KOR), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_CHINA), ''),
            TRIM(IFNULL(customer.CUSTOMER_CD, ''))
        )
    FROM customer_info customer
    WHERE customer.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(customer.ISDEL, '0') = '0';

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_customer_by_cd;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_customer_latest_id;
    CREATE TEMPORARY TABLE tmp_ar_aging_detail_customer_by_cd
    (
        CUSTOMER_CD VARCHAR(20) NOT NULL,
        CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (CUSTOMER_CD),
        INDEX idx_tmp_ar_aging_detail_customer_by_cd_01 (CUSTOMER_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    CREATE TEMPORARY TABLE tmp_ar_aging_detail_customer_latest_id
    (
        CUSTOMER_CD VARCHAR(20) NOT NULL,
        LATEST_CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        PRIMARY KEY (CUSTOMER_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_detail_customer_latest_id (CUSTOMER_CD, LATEST_CUSTOMER_ID)
    SELECT source.CUSTOMER_CD, MAX(source.CUSTOMER_ID)
    FROM tmp_ar_aging_detail_customer_by_id source
    WHERE source.CUSTOMER_CD <> ''
    GROUP BY source.CUSTOMER_CD;

    INSERT INTO tmp_ar_aging_detail_customer_by_cd (CUSTOMER_CD, CUSTOMER_ID, CUSTOMER_NAME)
    SELECT by_id.CUSTOMER_CD, by_id.CUSTOMER_ID, by_id.CUSTOMER_NAME
    FROM tmp_ar_aging_detail_customer_by_id by_id
    INNER JOIN tmp_ar_aging_detail_customer_latest_id latest
        ON latest.CUSTOMER_CD = by_id.CUSTOMER_CD
       AND latest.LATEST_CUSTOMER_ID = by_id.CUSTOMER_ID;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_accounts;
    CREATE TEMPORARY TABLE tmp_ar_aging_detail_accounts
    (
        ACCOUNT_SORT INT NOT NULL AUTO_INCREMENT,
        ACC_CD VARCHAR(20) NOT NULL,
        PRIMARY KEY (ACCOUNT_SORT),
        UNIQUE KEY uq_tmp_ar_aging_detail_accounts_01 (ACC_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_detail_accounts (ACC_CD)
    SELECT account.ACC_CD
    FROM acclist_info account
    INNER JOIN
    (
        SELECT ACC_CD, MAX(ACC_ID) AS ACC_ID
        FROM acclist_info
        WHERE COMPANY_CD = p_COMPANY_CD
          AND IFNULL(ISDEL, '0') = '0'
          AND TRIM(IFNULL(ACC_CD, '')) <> ''
        GROUP BY ACC_CD
    ) latest
        ON latest.ACC_ID = account.ACC_ID
    WHERE account.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(account.ISDEL, '0') = '0'
      AND (v_account_cd = '' OR FIND_IN_SET(account.ACC_CD, v_account_cd) > 0)
      AND (v_account_cd <> '' OR IFNULL(account.ISCUSTOMER, '0') = '1')
    ORDER BY account.ACC_CD;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_latest_open;
    CREATE TEMPORARY TABLE tmp_ar_aging_detail_latest_open
    (
        ACC_CD VARCHAR(20) NOT NULL,
        CUSTOMER_KEY VARCHAR(50) NOT NULL,
        OPEN_YMD VARCHAR(8) NOT NULL DEFAULT '',
        PRIMARY KEY (ACC_CD, CUSTOMER_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_detail_latest_open (ACC_CD, CUSTOMER_KEY, OPEN_YMD)
    SELECT
        account.ACC_CD,
        CONCAT('ID:', opening.CUSTOMER_ID),
        IFNULL(MAX(opening.OPEN_YMD), '')
    FROM before_states_customer opening
    INNER JOIN tmp_ar_aging_detail_accounts account
        ON account.ACC_CD COLLATE utf8_unicode_ci = opening.ACC_CD COLLATE utf8_unicode_ci
    LEFT JOIN tmp_ar_aging_detail_customer_by_id customer
        ON customer.CUSTOMER_ID = IFNULL(opening.CUSTOMER_ID, 0)
    WHERE opening.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(opening.ISDEL, '0') = '0'
      AND IFNULL(opening.CUSTOMER_ID, 0) > 0
      AND IFNULL(opening.OPEN_YMD, '') <= v_to_ymd
      AND (v_customer_cd = '' OR FIND_IN_SET(customer.CUSTOMER_CD, v_customer_cd) > 0)
      AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(opening.FC_TYPE, 'VND')), v_fc_type) > 0)
    GROUP BY account.ACC_CD, opening.CUSTOMER_ID;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_lines;
    CREATE TEMPORARY TABLE tmp_ar_aging_detail_lines
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ACCOUNT_SORT INT NOT NULL DEFAULT 0,
        ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_KEY VARCHAR(50) NOT NULL DEFAULT '',
        CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_OWN_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        CHIT_YMD VARCHAR(8) NOT NULL DEFAULT '',
        TRANSACTION_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DOCUMENT_NO VARCHAR(50) NOT NULL DEFAULT '',
        INVOICE_DATE VARCHAR(20) NOT NULL DEFAULT '',
        INVOICE_NO VARCHAR(50) NOT NULL DEFAULT '',
        DESCRIPTION_1 VARCHAR(1000) NOT NULL DEFAULT '',
        TOTAL_RECEIVABLE DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOT_DUE_NO_TERM DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOT_DUE_0_30 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOT_DUE_31_60 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOT_DUE_61_90 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOT_DUE_OVER_90 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OVERDUE_0_30 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OVERDUE_31_60 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OVERDUE_61_90 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OVERDUE_OVER_90 DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        OVERDUE_TOTAL DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        SORT_CHIT_ID BIGINT NOT NULL DEFAULT 0,
        SORT_DETAIL INT NOT NULL DEFAULT 0,
        SORT_SIDE INT NOT NULL DEFAULT 0,
        PRIMARY KEY (ROW_NO),
        INDEX idx_tmp_ar_aging_detail_lines_01 (CUSTOMER_KEY, ACCOUNT_SORT, CHIT_YMD, SORT_CHIT_ID, SORT_DETAIL, SORT_SIDE)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_detail_lines
    (
        ACCOUNT_SORT,
        ACC_CD,
        CUSTOMER_KEY,
        CUSTOMER_ID,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        TOTAL_RECEIVABLE,
        NOT_DUE_NO_TERM
    )
    SELECT
        account.ACCOUNT_SORT,
        account.ACC_CD,
        latest.CUSTOMER_KEY,
        IFNULL(opening.CUSTOMER_ID, 0),
        IFNULL(customer.CUSTOMER_CD, ''),
        '',
        COALESCE(NULLIF(customer.CUSTOMER_NAME, ''), NULLIF(opening.CUSTOMER_NM, ''), IFNULL(customer.CUSTOMER_CD, '')),
        IFNULL(SUM(CASE WHEN v_use_fc = 1 THEN opening.DEBIT_FC - opening.CREDIT_FC ELSE opening.DEBIT - opening.CREDIT END), 0) AS TOTAL_RECEIVABLE,
        IFNULL(SUM(CASE WHEN v_use_fc = 1 THEN opening.DEBIT_FC - opening.CREDIT_FC ELSE opening.DEBIT - opening.CREDIT END), 0) AS NOT_DUE_NO_TERM
    FROM tmp_ar_aging_detail_latest_open latest
    INNER JOIN tmp_ar_aging_detail_accounts account
        ON account.ACC_CD = latest.ACC_CD
    INNER JOIN before_states_customer opening
        ON opening.COMPANY_CD = p_COMPANY_CD
       AND opening.ACC_CD COLLATE utf8_unicode_ci = latest.ACC_CD COLLATE utf8_unicode_ci
       AND CONCAT('ID:', opening.CUSTOMER_ID) COLLATE utf8_unicode_ci = latest.CUSTOMER_KEY COLLATE utf8_unicode_ci
       AND opening.OPEN_YMD = latest.OPEN_YMD
       AND IFNULL(opening.ISDEL, '0') = '0'
    LEFT JOIN tmp_ar_aging_detail_customer_by_id customer
        ON customer.CUSTOMER_ID = IFNULL(opening.CUSTOMER_ID, 0)
    WHERE v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(opening.FC_TYPE, 'VND')), v_fc_type) > 0
    GROUP BY account.ACCOUNT_SORT, account.ACC_CD, latest.CUSTOMER_KEY, opening.CUSTOMER_ID, customer.CUSTOMER_CD, customer.CUSTOMER_NAME, opening.CUSTOMER_NM
    HAVING ROUND(TOTAL_RECEIVABLE, 0) <> 0;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_raw;
    CREATE TEMPORARY TABLE tmp_ar_aging_detail_raw
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ACCOUNT_SORT INT NOT NULL DEFAULT 0,
        ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_KEY VARCHAR(50) NOT NULL DEFAULT '',
        CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_OWN_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        CHIT_YMD VARCHAR(8) NOT NULL DEFAULT '',
        DUE_YMD VARCHAR(8) NOT NULL DEFAULT '',
        HAS_DUE TINYINT NOT NULL DEFAULT 0,
        TRANSACTION_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DOCUMENT_NO VARCHAR(50) NOT NULL DEFAULT '',
        INVOICE_DATE VARCHAR(20) NOT NULL DEFAULT '',
        INVOICE_NO VARCHAR(50) NOT NULL DEFAULT '',
        DESCRIPTION_1 VARCHAR(1000) NOT NULL DEFAULT '',
        SIGNED_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        SORT_CHIT_ID BIGINT NOT NULL DEFAULT 0,
        SORT_DETAIL INT NOT NULL DEFAULT 0,
        SORT_SIDE INT NOT NULL DEFAULT 0,
        PRIMARY KEY (ROW_NO),
        INDEX idx_tmp_ar_aging_detail_raw_01 (CUSTOMER_KEY, ACC_CD, CHIT_YMD, SORT_CHIT_ID, SORT_DETAIL, SORT_SIDE)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_detail_raw
    (
        ACCOUNT_SORT,
        ACC_CD,
        CUSTOMER_KEY,
        CUSTOMER_ID,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        CHIT_YMD,
        DUE_YMD,
        HAS_DUE,
        TRANSACTION_DATE,
        DOCUMENT_NO,
        INVOICE_DATE,
        INVOICE_NO,
        DESCRIPTION_1,
        SIGNED_AMOUNT,
        SORT_CHIT_ID,
        SORT_DETAIL,
        SORT_SIDE
    )
    SELECT
        account.ACCOUNT_SORT,
        account.ACC_CD,
        CASE
            WHEN IFNULL(ext.CUSTOMER_ID, 0) > 0 THEN CONCAT('ID:', ext.CUSTOMER_ID)
            WHEN by_cd.CUSTOMER_ID > 0 THEN CONCAT('ID:', by_cd.CUSTOMER_ID)
            ELSE CONCAT('CD:', TRIM(IFNULL(ext.CUSTOMER_CD, '')))
        END,
        COALESCE(NULLIF(ext.CUSTOMER_ID, 0), by_cd.CUSTOMER_ID, 0),
        COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), ''),
        TRIM(IFNULL(ext.CUSTOMER_OWN_CD, '')),
        COALESCE(NULLIF(by_id.CUSTOMER_NAME, ''), NULLIF(by_cd.CUSTOMER_NAME, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), CAST(IFNULL(ext.CUSTOMER_ID, 0) AS CHAR)),
        COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), ''),
        CASE
            WHEN TRIM(IFNULL(header_ext.DAY_OF_PAYMENT, '')) REGEXP '^[0-9]+$'
             AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') REGEXP '^[0-9]{8}$'
            THEN DATE_FORMAT(DATE_ADD(STR_TO_DATE(COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), '')), '%Y%m%d'), INTERVAL CAST(header_ext.DAY_OF_PAYMENT AS UNSIGNED) DAY), '%Y%m%d')
            ELSE ''
        END,
        CASE
            WHEN TRIM(IFNULL(header_ext.DAY_OF_PAYMENT, '')) REGEXP '^[0-9]+$'
             AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') REGEXP '^[0-9]{8}$'
            THEN 1
            ELSE 0
        END,
        CASE WHEN IFNULL(header.CHIT_YMD, '') REGEXP '^[0-9]{8}$' THEN DATE_FORMAT(STR_TO_DATE(header.CHIT_YMD, '%Y%m%d'), '%d/%m/%Y') ELSE IFNULL(header.CHIT_YMD, '') END,
        COALESCE(NULLIF(TRIM(header.CHIT_NO), ''), NULLIF(TRIM(header.CHIT_CD), ''), ''),
        CASE
            WHEN IFNULL(vat.VAT_YMD, '') REGEXP '^[0-9]{8}$' THEN DATE_FORMAT(STR_TO_DATE(vat.VAT_YMD, '%Y%m%d'), '%d/%m/%Y')
            ELSE IFNULL(vat.VAT_YMD, '')
        END,
        COALESCE(NULLIF(TRIM(vat.VAT_CHIT_NO), ''), NULLIF(TRIM(vat.VAT_CHIT_NO_2), ''), NULLIF(TRIM(vat.VAT_INVOICE_CD), ''), ''),
        COALESCE(
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN ddesc_en.DESCRIPTION WHEN 'KOR' THEN ddesc_ko.DESCRIPTION WHEN 'CHINA' THEN ddesc_china.DESCRIPTION ELSE ddesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN hdesc_en.DESCRIPTION WHEN 'KOR' THEN hdesc_ko.DESCRIPTION WHEN 'CHINA' THEN hdesc_china.DESCRIPTION ELSE hdesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(header.PAYER_INFO), ''),
            ''
        ),
        CASE WHEN v_use_fc = 1 THEN IFNULL(detail.FC_AMOUNT, 0) ELSE IFNULL(detail.AMOUNT, 0) END,
        IFNULL(header.CHIT_ID, 0),
        IFNULL(detail.SORT, 0),
        1
    FROM chitdetailinfo detail
    INNER JOIN tmp_ar_aging_detail_accounts account
        ON account.ACC_CD COLLATE utf8_unicode_ci = TRIM(IFNULL(detail.DEBIT, '')) COLLATE utf8_unicode_ci
    INNER JOIN chitinfo header
        ON header.COMPANY_CD = detail.COMPANY_CD
       AND header.CHIT_ID = detail.CHIT_ID
       AND IFNULL(header.ISDEL, '0') = '0'
    INNER JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = detail.COMPANY_CD
       AND ext.CHITDETAIL_ID = detail.CHITDETAIL_ID
       AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN chitinfo_ext header_ext
        ON header_ext.COMPANY_CD = header.COMPANY_CD
       AND header_ext.CHIT_ID = header.CHIT_ID
       AND IFNULL(header_ext.ISDEL, '0') = '0'
    LEFT JOIN chitdetailinfo_vat vat
        ON vat.COMPANY_CD = detail.COMPANY_CD
       AND vat.CHITDETAIL_ID = detail.CHITDETAIL_ID
       AND IFNULL(vat.ISDEL, '0') = '0'
    LEFT JOIN tmp_ar_aging_detail_customer_by_id by_id
        ON by_id.CUSTOMER_ID = IFNULL(ext.CUSTOMER_ID, 0)
    LEFT JOIN tmp_ar_aging_detail_customer_by_cd by_cd
        ON by_cd.CUSTOMER_CD COLLATE utf8_unicode_ci = TRIM(IFNULL(ext.CUSTOMER_CD, '')) COLLATE utf8_unicode_ci
    LEFT JOIN chitdescriptioninfo hdesc_vi ON hdesc_vi.COMPANY_CD = header.COMPANY_CD AND hdesc_vi.CHIT_ID = header.CHIT_ID AND hdesc_vi.LANG_TYPE = 'VIET' AND IFNULL(hdesc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_en ON hdesc_en.COMPANY_CD = header.COMPANY_CD AND hdesc_en.CHIT_ID = header.CHIT_ID AND hdesc_en.LANG_TYPE = 'ENG' AND IFNULL(hdesc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_ko ON hdesc_ko.COMPANY_CD = header.COMPANY_CD AND hdesc_ko.CHIT_ID = header.CHIT_ID AND hdesc_ko.LANG_TYPE = 'KOR' AND IFNULL(hdesc_ko.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_china ON hdesc_china.COMPANY_CD = header.COMPANY_CD AND hdesc_china.CHIT_ID = header.CHIT_ID AND hdesc_china.LANG_TYPE = 'CHINA' AND IFNULL(hdesc_china.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_vi ON ddesc_vi.COMPANY_CD = detail.COMPANY_CD AND ddesc_vi.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_vi.LANG_TYPE = 'VIET' AND IFNULL(ddesc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_en ON ddesc_en.COMPANY_CD = detail.COMPANY_CD AND ddesc_en.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_en.LANG_TYPE = 'ENG' AND IFNULL(ddesc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_ko ON ddesc_ko.COMPANY_CD = detail.COMPANY_CD AND ddesc_ko.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_ko.LANG_TYPE = 'KOR' AND IFNULL(ddesc_ko.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_china ON ddesc_china.COMPANY_CD = detail.COMPANY_CD AND ddesc_china.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_china.LANG_TYPE = 'CHINA' AND IFNULL(ddesc_china.ISDEL, '0') = '0'
    WHERE detail.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(detail.ISDEL, '0') = '0'
      AND IFNULL(detail.AMOUNT, 0) <> 0
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <= v_to_ymd
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <> ''
      AND (IFNULL(ext.CUSTOMER_ID, 0) > 0 OR TRIM(IFNULL(ext.CUSTOMER_CD, '')) <> '')
      AND (v_customer_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), '')), v_customer_cd) > 0)
      AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(detail.FC_TYPE, 'VND')), v_fc_type) > 0);

    INSERT INTO tmp_ar_aging_detail_raw
    (
        ACCOUNT_SORT,
        ACC_CD,
        CUSTOMER_KEY,
        CUSTOMER_ID,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        CHIT_YMD,
        DUE_YMD,
        HAS_DUE,
        TRANSACTION_DATE,
        DOCUMENT_NO,
        INVOICE_DATE,
        INVOICE_NO,
        DESCRIPTION_1,
        SIGNED_AMOUNT,
        SORT_CHIT_ID,
        SORT_DETAIL,
        SORT_SIDE
    )
    SELECT
        account.ACCOUNT_SORT,
        account.ACC_CD,
        CASE
            WHEN IFNULL(ext.CUSTOMER_ID, 0) > 0 THEN CONCAT('ID:', ext.CUSTOMER_ID)
            WHEN by_cd.CUSTOMER_ID > 0 THEN CONCAT('ID:', by_cd.CUSTOMER_ID)
            ELSE CONCAT('CD:', TRIM(IFNULL(ext.CUSTOMER_CD, '')))
        END,
        COALESCE(NULLIF(ext.CUSTOMER_ID, 0), by_cd.CUSTOMER_ID, 0),
        COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), ''),
        TRIM(IFNULL(ext.CUSTOMER_OWN_CD, '')),
        COALESCE(NULLIF(by_id.CUSTOMER_NAME, ''), NULLIF(by_cd.CUSTOMER_NAME, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), CAST(IFNULL(ext.CUSTOMER_ID, 0) AS CHAR)),
        COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), ''),
        CASE
            WHEN TRIM(IFNULL(header_ext.DAY_OF_PAYMENT, '')) REGEXP '^[0-9]+$'
             AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') REGEXP '^[0-9]{8}$'
            THEN DATE_FORMAT(DATE_ADD(STR_TO_DATE(COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), '')), '%Y%m%d'), INTERVAL CAST(header_ext.DAY_OF_PAYMENT AS UNSIGNED) DAY), '%Y%m%d')
            ELSE ''
        END,
        CASE
            WHEN TRIM(IFNULL(header_ext.DAY_OF_PAYMENT, '')) REGEXP '^[0-9]+$'
             AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') REGEXP '^[0-9]{8}$'
            THEN 1
            ELSE 0
        END,
        CASE WHEN IFNULL(header.CHIT_YMD, '') REGEXP '^[0-9]{8}$' THEN DATE_FORMAT(STR_TO_DATE(header.CHIT_YMD, '%Y%m%d'), '%d/%m/%Y') ELSE IFNULL(header.CHIT_YMD, '') END,
        COALESCE(NULLIF(TRIM(header.CHIT_NO), ''), NULLIF(TRIM(header.CHIT_CD), ''), ''),
        CASE
            WHEN IFNULL(vat.VAT_YMD, '') REGEXP '^[0-9]{8}$' THEN DATE_FORMAT(STR_TO_DATE(vat.VAT_YMD, '%Y%m%d'), '%d/%m/%Y')
            ELSE IFNULL(vat.VAT_YMD, '')
        END,
        COALESCE(NULLIF(TRIM(vat.VAT_CHIT_NO), ''), NULLIF(TRIM(vat.VAT_CHIT_NO_2), ''), NULLIF(TRIM(vat.VAT_INVOICE_CD), ''), ''),
        COALESCE(
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN ddesc_en.DESCRIPTION WHEN 'KOR' THEN ddesc_ko.DESCRIPTION WHEN 'CHINA' THEN ddesc_china.DESCRIPTION ELSE ddesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN hdesc_en.DESCRIPTION WHEN 'KOR' THEN hdesc_ko.DESCRIPTION WHEN 'CHINA' THEN hdesc_china.DESCRIPTION ELSE hdesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(header.PAYER_INFO), ''),
            ''
        ),
        -CASE WHEN v_use_fc = 1 THEN IFNULL(detail.FC_AMOUNT, 0) ELSE IFNULL(detail.AMOUNT, 0) END,
        IFNULL(header.CHIT_ID, 0),
        IFNULL(detail.SORT, 0),
        2
    FROM chitdetailinfo detail
    INNER JOIN tmp_ar_aging_detail_accounts account
        ON account.ACC_CD COLLATE utf8_unicode_ci = TRIM(IFNULL(detail.CREDIT, '')) COLLATE utf8_unicode_ci
    INNER JOIN chitinfo header
        ON header.COMPANY_CD = detail.COMPANY_CD
       AND header.CHIT_ID = detail.CHIT_ID
       AND IFNULL(header.ISDEL, '0') = '0'
    INNER JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = detail.COMPANY_CD
       AND ext.CHITDETAIL_ID = detail.CHITDETAIL_ID
       AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN chitinfo_ext header_ext
        ON header_ext.COMPANY_CD = header.COMPANY_CD
       AND header_ext.CHIT_ID = header.CHIT_ID
       AND IFNULL(header_ext.ISDEL, '0') = '0'
    LEFT JOIN chitdetailinfo_vat vat
        ON vat.COMPANY_CD = detail.COMPANY_CD
       AND vat.CHITDETAIL_ID = detail.CHITDETAIL_ID
       AND IFNULL(vat.ISDEL, '0') = '0'
    LEFT JOIN tmp_ar_aging_detail_customer_by_id by_id
        ON by_id.CUSTOMER_ID = IFNULL(ext.CUSTOMER_ID, 0)
    LEFT JOIN tmp_ar_aging_detail_customer_by_cd by_cd
        ON by_cd.CUSTOMER_CD COLLATE utf8_unicode_ci = TRIM(IFNULL(ext.CUSTOMER_CD, '')) COLLATE utf8_unicode_ci
    LEFT JOIN chitdescriptioninfo hdesc_vi ON hdesc_vi.COMPANY_CD = header.COMPANY_CD AND hdesc_vi.CHIT_ID = header.CHIT_ID AND hdesc_vi.LANG_TYPE = 'VIET' AND IFNULL(hdesc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_en ON hdesc_en.COMPANY_CD = header.COMPANY_CD AND hdesc_en.CHIT_ID = header.CHIT_ID AND hdesc_en.LANG_TYPE = 'ENG' AND IFNULL(hdesc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_ko ON hdesc_ko.COMPANY_CD = header.COMPANY_CD AND hdesc_ko.CHIT_ID = header.CHIT_ID AND hdesc_ko.LANG_TYPE = 'KOR' AND IFNULL(hdesc_ko.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_china ON hdesc_china.COMPANY_CD = header.COMPANY_CD AND hdesc_china.CHIT_ID = header.CHIT_ID AND hdesc_china.LANG_TYPE = 'CHINA' AND IFNULL(hdesc_china.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_vi ON ddesc_vi.COMPANY_CD = detail.COMPANY_CD AND ddesc_vi.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_vi.LANG_TYPE = 'VIET' AND IFNULL(ddesc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_en ON ddesc_en.COMPANY_CD = detail.COMPANY_CD AND ddesc_en.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_en.LANG_TYPE = 'ENG' AND IFNULL(ddesc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_ko ON ddesc_ko.COMPANY_CD = detail.COMPANY_CD AND ddesc_ko.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_ko.LANG_TYPE = 'KOR' AND IFNULL(ddesc_ko.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_china ON ddesc_china.COMPANY_CD = detail.COMPANY_CD AND ddesc_china.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_china.LANG_TYPE = 'CHINA' AND IFNULL(ddesc_china.ISDEL, '0') = '0'
    WHERE detail.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(detail.ISDEL, '0') = '0'
      AND IFNULL(detail.AMOUNT, 0) <> 0
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <= v_to_ymd
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <> ''
      AND (IFNULL(ext.CUSTOMER_ID, 0) > 0 OR TRIM(IFNULL(ext.CUSTOMER_CD, '')) <> '')
      AND (v_customer_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), '')), v_customer_cd) > 0)
      AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(detail.FC_TYPE, 'VND')), v_fc_type) > 0);

    INSERT INTO tmp_ar_aging_detail_lines
    (
        ACCOUNT_SORT,
        ACC_CD,
        CUSTOMER_KEY,
        CUSTOMER_ID,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        CHIT_YMD,
        TRANSACTION_DATE,
        DOCUMENT_NO,
        INVOICE_DATE,
        INVOICE_NO,
        DESCRIPTION_1,
        TOTAL_RECEIVABLE,
        NOT_DUE_NO_TERM,
        NOT_DUE_0_30,
        NOT_DUE_31_60,
        NOT_DUE_61_90,
        NOT_DUE_OVER_90,
        OVERDUE_0_30,
        OVERDUE_31_60,
        OVERDUE_61_90,
        OVERDUE_OVER_90,
        OVERDUE_TOTAL,
        SORT_CHIT_ID,
        SORT_DETAIL,
        SORT_SIDE
    )
    SELECT
        raw.ACCOUNT_SORT,
        raw.ACC_CD,
        raw.CUSTOMER_KEY,
        raw.CUSTOMER_ID,
        raw.CUSTOMER_CD,
        raw.CUSTOMER_OWN_CD,
        raw.CUSTOMER_NAME,
        raw.CHIT_YMD,
        raw.TRANSACTION_DATE,
        raw.DOCUMENT_NO,
        raw.INVOICE_DATE,
        raw.INVOICE_NO,
        raw.DESCRIPTION_1,
        raw.SIGNED_AMOUNT,
        CASE WHEN raw.HAS_DUE = 0 THEN raw.SIGNED_AMOUNT ELSE 0 END,
        CASE WHEN raw.HAS_DUE = 1 AND raw.DUE_YMD >= v_to_ymd AND DATEDIFF(STR_TO_DATE(raw.DUE_YMD, '%Y%m%d'), p_TO_DATE) BETWEEN 0 AND 30 THEN raw.SIGNED_AMOUNT ELSE 0 END,
        CASE WHEN raw.HAS_DUE = 1 AND raw.DUE_YMD >= v_to_ymd AND DATEDIFF(STR_TO_DATE(raw.DUE_YMD, '%Y%m%d'), p_TO_DATE) BETWEEN 31 AND 60 THEN raw.SIGNED_AMOUNT ELSE 0 END,
        CASE WHEN raw.HAS_DUE = 1 AND raw.DUE_YMD >= v_to_ymd AND DATEDIFF(STR_TO_DATE(raw.DUE_YMD, '%Y%m%d'), p_TO_DATE) BETWEEN 61 AND 90 THEN raw.SIGNED_AMOUNT ELSE 0 END,
        CASE WHEN raw.HAS_DUE = 1 AND raw.DUE_YMD >= v_to_ymd AND DATEDIFF(STR_TO_DATE(raw.DUE_YMD, '%Y%m%d'), p_TO_DATE) > 90 THEN raw.SIGNED_AMOUNT ELSE 0 END,
        CASE WHEN raw.HAS_DUE = 1 AND raw.DUE_YMD < v_to_ymd AND DATEDIFF(p_TO_DATE, STR_TO_DATE(raw.DUE_YMD, '%Y%m%d')) BETWEEN 1 AND 30 THEN raw.SIGNED_AMOUNT ELSE 0 END,
        CASE WHEN raw.HAS_DUE = 1 AND raw.DUE_YMD < v_to_ymd AND DATEDIFF(p_TO_DATE, STR_TO_DATE(raw.DUE_YMD, '%Y%m%d')) BETWEEN 31 AND 60 THEN raw.SIGNED_AMOUNT ELSE 0 END,
        CASE WHEN raw.HAS_DUE = 1 AND raw.DUE_YMD < v_to_ymd AND DATEDIFF(p_TO_DATE, STR_TO_DATE(raw.DUE_YMD, '%Y%m%d')) BETWEEN 61 AND 90 THEN raw.SIGNED_AMOUNT ELSE 0 END,
        CASE WHEN raw.HAS_DUE = 1 AND raw.DUE_YMD < v_to_ymd AND DATEDIFF(p_TO_DATE, STR_TO_DATE(raw.DUE_YMD, '%Y%m%d')) > 90 THEN raw.SIGNED_AMOUNT ELSE 0 END,
        CASE WHEN raw.HAS_DUE = 1 AND raw.DUE_YMD < v_to_ymd THEN raw.SIGNED_AMOUNT ELSE 0 END,
        raw.SORT_CHIT_ID,
        raw.SORT_DETAIL,
        raw.SORT_SIDE
    FROM tmp_ar_aging_detail_raw raw
    LEFT JOIN tmp_ar_aging_detail_latest_open latest
        ON latest.ACC_CD = raw.ACC_CD
       AND latest.CUSTOMER_KEY = raw.CUSTOMER_KEY
    WHERE ROUND(raw.SIGNED_AMOUNT, 0) <> 0
      AND raw.CHIT_YMD >= IFNULL(latest.OPEN_YMD, '00000000');

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_groups;
    CREATE TEMPORARY TABLE tmp_ar_aging_detail_groups
    (
        GROUP_SORT INT NOT NULL AUTO_INCREMENT,
        CUSTOMER_KEY VARCHAR(50) NOT NULL DEFAULT '',
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_OWN_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (GROUP_SORT),
        UNIQUE KEY uq_tmp_ar_aging_detail_groups_01 (CUSTOMER_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_aging_detail_groups (CUSTOMER_KEY, CUSTOMER_CD, CUSTOMER_OWN_CD, CUSTOMER_NAME)
    SELECT
        line.CUSTOMER_KEY,
        MAX(line.CUSTOMER_CD),
        MAX(line.CUSTOMER_OWN_CD),
        MAX(line.CUSTOMER_NAME)
    FROM tmp_ar_aging_detail_lines line
    WHERE line.CUSTOMER_KEY <> ''
    GROUP BY line.CUSTOMER_KEY
    HAVING ROUND(SUM(line.TOTAL_RECEIVABLE), 0) <> 0
    ORDER BY MAX(line.CUSTOMER_CD), MAX(line.CUSTOMER_NAME), line.CUSTOMER_KEY;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_report;
    CREATE TEMPORARY TABLE tmp_ar_aging_detail_report
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ROW_KEY VARCHAR(120) NOT NULL DEFAULT '',
        PARENT_ROW_KEY VARCHAR(120) NULL,
        ROW_SORT BIGINT NOT NULL DEFAULT 0,
        ROW_TYPE VARCHAR(30) NOT NULL DEFAULT '',
        ROW_LEVEL INT NOT NULL DEFAULT 0,
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        REPORT_GROUP_KEY VARCHAR(120) NOT NULL DEFAULT '',
        REPORT_PERIOD_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        ACCOUNT_FILTER_TEXT VARCHAR(1000) NOT NULL DEFAULT '',
        CUSTOMER_FILTER_TEXT VARCHAR(1000) NOT NULL DEFAULT '',
        CURRENCY_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_OWN_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        TRANSACTION_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DOCUMENT_NO VARCHAR(50) NOT NULL DEFAULT '',
        INVOICE_DATE VARCHAR(20) NOT NULL DEFAULT '',
        INVOICE_NO VARCHAR(50) NOT NULL DEFAULT '',
        DESCRIPTION_1 VARCHAR(1000) NOT NULL DEFAULT '',
        TOTAL_RECEIVABLE DECIMAL(18,6) NULL,
        NOT_DUE_NO_TERM DECIMAL(18,6) NULL,
        NOT_DUE_0_30 DECIMAL(18,6) NULL,
        NOT_DUE_31_60 DECIMAL(18,6) NULL,
        NOT_DUE_61_90 DECIMAL(18,6) NULL,
        NOT_DUE_OVER_90 DECIMAL(18,6) NULL,
        OVERDUE_0_30 DECIMAL(18,6) NULL,
        OVERDUE_31_60 DECIMAL(18,6) NULL,
        OVERDUE_61_90 DECIMAL(18,6) NULL,
        OVERDUE_OVER_90 DECIMAL(18,6) NULL,
        OVERDUE_TOTAL DECIMAL(18,6) NULL,
        PRIMARY KEY (ROW_NO),
        INDEX idx_tmp_ar_aging_detail_report_01 (ROW_SORT, ROW_NO)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    IF (SELECT COUNT(*) FROM tmp_ar_aging_detail_groups) = 0 THEN
        INSERT INTO tmp_ar_aging_detail_report
        (
            ROW_KEY,
            ROW_SORT,
            ROW_TYPE,
            ROW_LEVEL,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            REPORT_PERIOD_TEXT,
            ACCOUNT_FILTER_TEXT,
            CUSTOMER_FILTER_TEXT,
            CURRENCY_TEXT,
            DESCRIPTION_1
        )
        VALUES
        (
            'AR_AGING_DETAIL_EMPTY',
            10,
            'EMPTY',
            0,
            p_COMPANY_CD,
            'AR_AGING_DETAIL',
            v_report_period_text,
            v_account_filter_text,
            v_customer_filter_text,
            v_currency_text,
            'Không có dữ liệu'
        );
    ELSE
        INSERT INTO tmp_ar_aging_detail_report
        (
            ROW_KEY,
            ROW_SORT,
            ROW_TYPE,
            ROW_LEVEL,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            REPORT_PERIOD_TEXT,
            ACCOUNT_FILTER_TEXT,
            CUSTOMER_FILTER_TEXT,
            CURRENCY_TEXT,
            CUSTOMER_CD,
            CUSTOMER_OWN_CD,
            CUSTOMER_NAME,
            DESCRIPTION_1
        )
        SELECT
            CONCAT('AR_AGING_DETAIL_GROUP_', group_row.GROUP_SORT),
            group_row.GROUP_SORT * 1000000,
            'GROUP',
            0,
            p_COMPANY_CD,
            CONCAT('AR_AGING_DETAIL_', group_row.GROUP_SORT),
            v_report_period_text,
            v_account_filter_text,
            v_customer_filter_text,
            v_currency_text,
            group_row.CUSTOMER_CD,
            group_row.CUSTOMER_OWN_CD,
            group_row.CUSTOMER_NAME,
            CONCAT('Mã số khách hàng : ', group_row.CUSTOMER_CD, ' - ', group_row.CUSTOMER_NAME)
        FROM tmp_ar_aging_detail_groups group_row;

        INSERT INTO tmp_ar_aging_detail_report
        (
            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            ROW_TYPE,
            ROW_LEVEL,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            REPORT_PERIOD_TEXT,
            ACCOUNT_FILTER_TEXT,
            CUSTOMER_FILTER_TEXT,
            CURRENCY_TEXT,
            CUSTOMER_CD,
            CUSTOMER_OWN_CD,
            CUSTOMER_NAME,
            TRANSACTION_DATE,
            DOCUMENT_NO,
            INVOICE_DATE,
            INVOICE_NO,
            DESCRIPTION_1,
            TOTAL_RECEIVABLE,
            NOT_DUE_NO_TERM,
            NOT_DUE_0_30,
            NOT_DUE_31_60,
            NOT_DUE_61_90,
            NOT_DUE_OVER_90,
            OVERDUE_0_30,
            OVERDUE_31_60,
            OVERDUE_61_90,
            OVERDUE_OVER_90,
            OVERDUE_TOTAL
        )
        SELECT
            CONCAT('AR_AGING_DETAIL_LINE_', line.ROW_NO),
            CONCAT('AR_AGING_DETAIL_GROUP_', group_row.GROUP_SORT),
            group_row.GROUP_SORT * 1000000 + line.ACCOUNT_SORT * 10000 + line.ROW_NO,
            'DETAIL',
            1,
            p_COMPANY_CD,
            CONCAT('AR_AGING_DETAIL_', group_row.GROUP_SORT),
            v_report_period_text,
            v_account_filter_text,
            v_customer_filter_text,
            v_currency_text,
            line.CUSTOMER_CD,
            line.CUSTOMER_OWN_CD,
            line.CUSTOMER_NAME,
            line.TRANSACTION_DATE,
            line.DOCUMENT_NO,
            line.INVOICE_DATE,
            line.INVOICE_NO,
            line.DESCRIPTION_1,
            NULLIF(ROUND(line.TOTAL_RECEIVABLE, 0), 0),
            NULLIF(ROUND(line.NOT_DUE_NO_TERM, 0), 0),
            NULLIF(ROUND(line.NOT_DUE_0_30, 0), 0),
            NULLIF(ROUND(line.NOT_DUE_31_60, 0), 0),
            NULLIF(ROUND(line.NOT_DUE_61_90, 0), 0),
            NULLIF(ROUND(line.NOT_DUE_OVER_90, 0), 0),
            NULLIF(ROUND(line.OVERDUE_0_30, 0), 0),
            NULLIF(ROUND(line.OVERDUE_31_60, 0), 0),
            NULLIF(ROUND(line.OVERDUE_61_90, 0), 0),
            NULLIF(ROUND(line.OVERDUE_OVER_90, 0), 0),
            NULLIF(ROUND(line.OVERDUE_TOTAL, 0), 0)
        FROM tmp_ar_aging_detail_lines line
        INNER JOIN tmp_ar_aging_detail_groups group_row
            ON group_row.CUSTOMER_KEY = line.CUSTOMER_KEY
        WHERE ROUND(line.TOTAL_RECEIVABLE, 0) <> 0;
    END IF;

    SELECT
        ROW_KEY,
        PARENT_ROW_KEY,
        ROW_SORT,
        ROW_TYPE,
        ROW_LEVEL,
        COMPANY_CD,
        REPORT_GROUP_KEY,
        REPORT_PERIOD_TEXT,
        ACCOUNT_FILTER_TEXT,
        CUSTOMER_FILTER_TEXT,
        CURRENCY_TEXT,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        TRANSACTION_DATE,
        DOCUMENT_NO,
        INVOICE_DATE,
        INVOICE_NO,
        DESCRIPTION_1,
        TOTAL_RECEIVABLE,
        NOT_DUE_NO_TERM,
        NOT_DUE_0_30,
        NOT_DUE_31_60,
        NOT_DUE_61_90,
        NOT_DUE_OVER_90,
        OVERDUE_0_30,
        OVERDUE_31_60,
        OVERDUE_61_90,
        OVERDUE_OVER_90,
        OVERDUE_TOTAL
    FROM tmp_ar_aging_detail_report
    ORDER BY ROW_SORT, ROW_NO;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_report;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_groups;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_raw;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_lines;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_latest_open;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_accounts;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_customer_by_cd;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_customer_latest_id;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_aging_detail_customer_by_id;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_ar_detail_s31dn
DROP PROCEDURE IF EXISTS `rpt_ar_detail_s31dn`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_ar_detail_s31dn`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_ACCOUNT_CD VARCHAR(1000),
    IN p_CUSTOMER_CD VARCHAR(1000),
    IN p_FC_TYPE VARCHAR(255),
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_before_from_ymd VARCHAR(8);
    DECLARE v_language VARCHAR(20);
    DECLARE v_account_cd VARCHAR(1000);
    DECLARE v_customer_cd VARCHAR(1000);
    DECLARE v_fc_type VARCHAR(255);
    DECLARE v_use_fc TINYINT DEFAULT 0;
    DECLARE v_currency_text VARCHAR(255);
    DECLARE v_report_period_text VARCHAR(255);
    DECLARE v_account_filter_text VARCHAR(1000);
    DECLARE v_customer_filter_text VARCHAR(1000);

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;

    SET v_from_ymd = DATE_FORMAT(p_FROM_DATE, '%Y%m%d');
    SET v_to_ymd = DATE_FORMAT(p_TO_DATE, '%Y%m%d');
    SET v_before_from_ymd = DATE_FORMAT(DATE_SUB(p_FROM_DATE, INTERVAL 1 DAY), '%Y%m%d');
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));
    SET v_account_cd = REPLACE(TRIM(IFNULL(p_ACCOUNT_CD, '')), ' ', '');
    SET v_customer_cd = REPLACE(TRIM(IFNULL(p_CUSTOMER_CD, '')), ' ', '');
    SET v_fc_type = REPLACE(UPPER(TRIM(IFNULL(p_FC_TYPE, ''))), ' ', '');

    IF v_fc_type = 'ALL' THEN
        SET v_fc_type = '';
    END IF;

    SET v_use_fc = CASE WHEN v_fc_type <> '' AND v_fc_type <> 'VND' AND LOCATE(',', v_fc_type) = 0 THEN 1 ELSE 0 END;
    SET v_currency_text = CASE WHEN v_fc_type = '' THEN 'VND' ELSE v_fc_type END;
    SET v_report_period_text = CONCAT('Từ ngày ', DATE_FORMAT(p_FROM_DATE, '%d/%m/%Y'), ' đến ngày ', DATE_FORMAT(p_TO_DATE, '%d/%m/%Y'));
    SET v_account_filter_text = CASE WHEN v_account_cd = '' THEN 'Tất cả' ELSE v_account_cd END;
    SET v_customer_filter_text = CASE WHEN v_customer_cd = '' THEN 'Tất cả' ELSE v_customer_cd END;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_customer_by_id;
    CREATE TEMPORARY TABLE tmp_ar_detail_customer_by_id
    (
        CUSTOMER_ID BIGINT NOT NULL,
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (CUSTOMER_ID),
        INDEX idx_tmp_ar_detail_customer_by_id_01 (CUSTOMER_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_detail_customer_by_id (CUSTOMER_ID, CUSTOMER_CD, CUSTOMER_NAME)
    SELECT
        customer.CUSTOMER_ID,
        TRIM(IFNULL(customer.CUSTOMER_CD, '')),
        COALESCE(
            NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN customer.CUSTOMER_NM_ENG
                WHEN 'KOR' THEN customer.CUSTOMER_NM_KOR
                WHEN 'CHINA' THEN customer.CUSTOMER_NM_CHINA
                ELSE customer.CUSTOMER_NM_VIET
            END), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_VIET), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_ENG), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_KOR), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_CHINA), ''),
            TRIM(IFNULL(customer.CUSTOMER_CD, ''))
        )
    FROM customer_info customer
    WHERE customer.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(customer.ISDEL, '0') = '0';

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_customer_by_cd;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_customer_latest_id;
    CREATE TEMPORARY TABLE tmp_ar_detail_customer_by_cd
    (
        CUSTOMER_CD VARCHAR(20) NOT NULL,
        CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (CUSTOMER_CD),
        INDEX idx_tmp_ar_detail_customer_by_cd_01 (CUSTOMER_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    CREATE TEMPORARY TABLE tmp_ar_detail_customer_latest_id
    (
        CUSTOMER_CD VARCHAR(20) NOT NULL,
        LATEST_CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        PRIMARY KEY (CUSTOMER_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_detail_customer_latest_id (CUSTOMER_CD, LATEST_CUSTOMER_ID)
    SELECT src.CUSTOMER_CD, MAX(src.CUSTOMER_ID) AS LATEST_CUSTOMER_ID
    FROM tmp_ar_detail_customer_by_id src
    WHERE src.CUSTOMER_CD <> ''
    GROUP BY src.CUSTOMER_CD;

    INSERT INTO tmp_ar_detail_customer_by_cd (CUSTOMER_CD, CUSTOMER_ID, CUSTOMER_NAME)
    SELECT by_id.CUSTOMER_CD, by_id.CUSTOMER_ID, by_id.CUSTOMER_NAME
    FROM tmp_ar_detail_customer_by_id by_id
    INNER JOIN tmp_ar_detail_customer_latest_id latest
        ON latest.CUSTOMER_CD = by_id.CUSTOMER_CD
       AND latest.LATEST_CUSTOMER_ID = by_id.CUSTOMER_ID;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_accounts;
    CREATE TEMPORARY TABLE tmp_ar_detail_accounts
    (
        ACCOUNT_SORT INT NOT NULL AUTO_INCREMENT,
        ACC_CD VARCHAR(20) NOT NULL,
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ACCOUNT_SORT),
        UNIQUE KEY uq_tmp_ar_detail_accounts_01 (ACC_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_detail_accounts (ACC_CD, ACCOUNT_NAME)
    SELECT
        account.ACC_CD,
        COALESCE(
            NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN account.ACCTITLE_NM_ENG
                WHEN 'KOR' THEN account.ACCTITLE_NM_KOR
                WHEN 'CHINA' THEN account.ACCTITLE_NM_CHINA
                WHEN 'JAPAN' THEN account.ACCTITLE_NM_JAPAN
                ELSE account.ACCTITLE_NM_VIET
            END), ''),
            NULLIF(TRIM(account.ACCTITLE_NM_VIET), ''),
            NULLIF(TRIM(account.ACCTITLE_NM_ENG), ''),
            account.ACC_CD
        )
    FROM acclist_info account
    INNER JOIN
    (
        SELECT ACC_CD, MAX(ACC_ID) AS ACC_ID
        FROM acclist_info
        WHERE COMPANY_CD = p_COMPANY_CD
          AND IFNULL(ISDEL, '0') = '0'
          AND TRIM(IFNULL(ACC_CD, '')) <> ''
        GROUP BY ACC_CD
    ) latest
        ON latest.ACC_ID = account.ACC_ID
    WHERE account.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(account.ISDEL, '0') = '0'
      AND (v_account_cd = '' OR FIND_IN_SET(account.ACC_CD, v_account_cd) > 0)
      AND (v_account_cd <> '' OR IFNULL(account.ISCUSTOMER, '0') = '1')
    ORDER BY account.ACC_CD;

    INSERT IGNORE INTO tmp_ar_detail_accounts (ACC_CD, ACCOUNT_NAME)
    SELECT source.ACC_CD, IFNULL(account_name.ACCOUNT_NAME, source.ACC_CD)
    FROM
    (
        SELECT DISTINCT TRIM(IFNULL(opening.ACC_CD, '')) AS ACC_CD
        FROM before_states_customer opening
        WHERE opening.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(opening.ISDEL, '0') = '0'
          AND TRIM(IFNULL(opening.ACC_CD, '')) <> ''
          AND IFNULL(opening.OPEN_YMD, '') <= v_before_from_ymd
        UNION
        SELECT DISTINCT TRIM(IFNULL(detail.DEBIT, '')) AS ACC_CD
        FROM chitdetailinfo detail
        INNER JOIN chitinfo header
            ON header.COMPANY_CD = detail.COMPANY_CD
           AND header.CHIT_ID = detail.CHIT_ID
           AND IFNULL(header.ISDEL, '0') = '0'
        INNER JOIN chitdetailinfo_ext ext
            ON ext.COMPANY_CD = detail.COMPANY_CD
           AND ext.CHITDETAIL_ID = detail.CHITDETAIL_ID
           AND IFNULL(ext.ISDEL, '0') = '0'
        WHERE detail.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(detail.ISDEL, '0') = '0'
          AND TRIM(IFNULL(detail.DEBIT, '')) <> ''
          AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <= v_to_ymd
          AND (IFNULL(ext.CUSTOMER_ID, 0) > 0 OR TRIM(IFNULL(ext.CUSTOMER_CD, '')) <> '')
        UNION
        SELECT DISTINCT TRIM(IFNULL(detail.CREDIT, '')) AS ACC_CD
        FROM chitdetailinfo detail
        INNER JOIN chitinfo header
            ON header.COMPANY_CD = detail.COMPANY_CD
           AND header.CHIT_ID = detail.CHIT_ID
           AND IFNULL(header.ISDEL, '0') = '0'
        INNER JOIN chitdetailinfo_ext ext
            ON ext.COMPANY_CD = detail.COMPANY_CD
           AND ext.CHITDETAIL_ID = detail.CHITDETAIL_ID
           AND IFNULL(ext.ISDEL, '0') = '0'
        WHERE detail.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(detail.ISDEL, '0') = '0'
          AND TRIM(IFNULL(detail.CREDIT, '')) <> ''
          AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <= v_to_ymd
          AND (IFNULL(ext.CUSTOMER_ID, 0) > 0 OR TRIM(IFNULL(ext.CUSTOMER_CD, '')) <> '')
    ) source
    LEFT JOIN
    (
        SELECT
            account.ACC_CD,
            COALESCE(NULLIF(TRIM(account.ACCTITLE_NM_VIET), ''), NULLIF(TRIM(account.ACCTITLE_NM_ENG), ''), account.ACC_CD) AS ACCOUNT_NAME,
            IFNULL(account.ISCUSTOMER, '0') AS ISCUSTOMER
        FROM acclist_info account
        INNER JOIN
        (
            SELECT ACC_CD, MAX(ACC_ID) AS ACC_ID
            FROM acclist_info
            WHERE COMPANY_CD = p_COMPANY_CD
              AND IFNULL(ISDEL, '0') = '0'
            GROUP BY ACC_CD
        ) latest_account
            ON latest_account.ACC_ID = account.ACC_ID
    ) account_name
        ON account_name.ACC_CD = source.ACC_CD
    WHERE source.ACC_CD <> ''
      AND (v_account_cd = '' OR FIND_IN_SET(source.ACC_CD, v_account_cd) > 0)
      AND (v_account_cd <> '' OR IFNULL(account_name.ISCUSTOMER, '1') = '1')
    ORDER BY source.ACC_CD;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_movements;
    CREATE TEMPORARY TABLE tmp_ar_detail_movements
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ACCOUNT_SORT INT NOT NULL DEFAULT 0,
        ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        CUSTOMER_KEY VARCHAR(80) NOT NULL DEFAULT '',
        CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_OWN_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        CHIT_YMD VARCHAR(8) NOT NULL DEFAULT '',
        ENTRY_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DOCUMENT_NO VARCHAR(50) NOT NULL DEFAULT '',
        DOCUMENT_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
        COUNTER_ACCOUNT VARCHAR(50) NOT NULL DEFAULT '',
        DISCOUNT_TERM_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        DEBIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        CREDIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        NOTE_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        SORT_NO VARCHAR(50) NOT NULL DEFAULT '',
        SORT_CHIT_TYPE VARCHAR(20) NOT NULL DEFAULT '',
        SORT_CHIT_ID BIGINT NOT NULL DEFAULT 0,
        SORT_DETAIL INT NOT NULL DEFAULT 0,
        SORT_SIDE INT NOT NULL DEFAULT 0,
        PRIMARY KEY (ROW_NO),
        INDEX idx_tmp_ar_detail_movements_01 (ACC_CD, CUSTOMER_KEY, CHIT_YMD, SORT_NO, SORT_CHIT_ID, SORT_DETAIL, SORT_SIDE)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_detail_movements
    (
        ACCOUNT_SORT,
        ACC_CD,
        ACCOUNT_NAME,
        CUSTOMER_KEY,
        CUSTOMER_ID,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        CHIT_YMD,
        ENTRY_DATE,
        DOCUMENT_NO,
        DOCUMENT_DATE,
        DESCRIPTION,
        COUNTER_ACCOUNT,
        DISCOUNT_TERM_TEXT,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT,
        NOTE_TEXT,
        SORT_NO,
        SORT_CHIT_TYPE,
        SORT_CHIT_ID,
        SORT_DETAIL,
        SORT_SIDE
    )
    SELECT
        account.ACCOUNT_SORT,
        account.ACC_CD,
        account.ACCOUNT_NAME,
        CASE
            WHEN IFNULL(ext.CUSTOMER_ID, 0) > 0 THEN CONCAT('ID:', ext.CUSTOMER_ID)
            WHEN by_cd.CUSTOMER_ID > 0 THEN CONCAT('ID:', by_cd.CUSTOMER_ID)
            ELSE CONCAT('CD:', TRIM(IFNULL(ext.CUSTOMER_CD, '')))
        END,
        COALESCE(NULLIF(ext.CUSTOMER_ID, 0), by_cd.CUSTOMER_ID, 0),
        COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), ''),
        TRIM(IFNULL(ext.CUSTOMER_OWN_CD, '')),
        COALESCE(NULLIF(by_id.CUSTOMER_NAME, ''), NULLIF(by_cd.CUSTOMER_NAME, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), CAST(IFNULL(ext.CUSTOMER_ID, 0) AS CHAR)),
        COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), ''),
        CASE WHEN IFNULL(header.CHIT_YMD, '') REGEXP '^[0-9]{8}$' THEN DATE_FORMAT(STR_TO_DATE(header.CHIT_YMD, '%Y%m%d'), '%d/%m/%Y') ELSE IFNULL(header.CHIT_YMD, '') END,
        COALESCE(NULLIF(TRIM(header.CHIT_NO), ''), NULLIF(TRIM(header.CHIT_CD), ''), ''),
        CASE
            WHEN COALESCE(NULLIF(detail.CHIT_YMD, ''), header.CHIT_YMD) REGEXP '^[0-9]{8}$'
            THEN DATE_FORMAT(STR_TO_DATE(COALESCE(NULLIF(detail.CHIT_YMD, ''), header.CHIT_YMD), '%Y%m%d'), '%d/%m/%Y')
            ELSE COALESCE(NULLIF(detail.CHIT_YMD, ''), header.CHIT_YMD)
        END,
        COALESCE(
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN ddesc_en.DESCRIPTION WHEN 'KOR' THEN ddesc_ko.DESCRIPTION WHEN 'CHINA' THEN ddesc_china.DESCRIPTION ELSE ddesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN hdesc_en.DESCRIPTION WHEN 'KOR' THEN hdesc_ko.DESCRIPTION WHEN 'CHINA' THEN hdesc_china.DESCRIPTION ELSE hdesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(header.PAYER_INFO), ''),
            ''
        ),
        TRIM(IFNULL(detail.CREDIT, '')),
        COALESCE(NULLIF(TRIM(header_ext.TIME_FOR_PAYMENT), ''), NULLIF(TRIM(header_ext.DAY_OF_PAYMENT), ''), ''),
        CASE WHEN v_use_fc = 1 THEN IFNULL(detail.FC_AMOUNT, 0) ELSE IFNULL(detail.AMOUNT, 0) END,
        0,
        IFNULL(detail.CHITDETAIL_CD, ''),
        IFNULL(header.CHIT_NO, ''),
        IFNULL(header.CHIT_TYPE, ''),
        IFNULL(header.CHIT_ID, 0),
        IFNULL(detail.SORT, 0),
        1
    FROM chitdetailinfo detail
    INNER JOIN tmp_ar_detail_accounts account
        ON account.ACC_CD = TRIM(IFNULL(detail.DEBIT, ''))
    INNER JOIN chitinfo header
        ON header.COMPANY_CD = detail.COMPANY_CD
       AND header.CHIT_ID = detail.CHIT_ID
       AND IFNULL(header.ISDEL, '0') = '0'
    INNER JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = detail.COMPANY_CD
       AND ext.CHITDETAIL_ID = detail.CHITDETAIL_ID
       AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN chitinfo_ext header_ext
        ON header_ext.COMPANY_CD = header.COMPANY_CD
       AND header_ext.CHIT_ID = header.CHIT_ID
       AND IFNULL(header_ext.ISDEL, '0') = '0'
    LEFT JOIN tmp_ar_detail_customer_by_id by_id
        ON by_id.CUSTOMER_ID = IFNULL(ext.CUSTOMER_ID, 0)
    LEFT JOIN tmp_ar_detail_customer_by_cd by_cd
        ON by_cd.CUSTOMER_CD = TRIM(IFNULL(ext.CUSTOMER_CD, ''))
    LEFT JOIN chitdescriptioninfo hdesc_vi ON hdesc_vi.COMPANY_CD = header.COMPANY_CD AND hdesc_vi.CHIT_ID = header.CHIT_ID AND hdesc_vi.LANG_TYPE = 'VIET' AND IFNULL(hdesc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_en ON hdesc_en.COMPANY_CD = header.COMPANY_CD AND hdesc_en.CHIT_ID = header.CHIT_ID AND hdesc_en.LANG_TYPE = 'ENG' AND IFNULL(hdesc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_ko ON hdesc_ko.COMPANY_CD = header.COMPANY_CD AND hdesc_ko.CHIT_ID = header.CHIT_ID AND hdesc_ko.LANG_TYPE = 'KOR' AND IFNULL(hdesc_ko.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_china ON hdesc_china.COMPANY_CD = header.COMPANY_CD AND hdesc_china.CHIT_ID = header.CHIT_ID AND hdesc_china.LANG_TYPE = 'CHINA' AND IFNULL(hdesc_china.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_vi ON ddesc_vi.COMPANY_CD = detail.COMPANY_CD AND ddesc_vi.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_vi.LANG_TYPE = 'VIET' AND IFNULL(ddesc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_en ON ddesc_en.COMPANY_CD = detail.COMPANY_CD AND ddesc_en.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_en.LANG_TYPE = 'ENG' AND IFNULL(ddesc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_ko ON ddesc_ko.COMPANY_CD = detail.COMPANY_CD AND ddesc_ko.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_ko.LANG_TYPE = 'KOR' AND IFNULL(ddesc_ko.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_china ON ddesc_china.COMPANY_CD = detail.COMPANY_CD AND ddesc_china.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_china.LANG_TYPE = 'CHINA' AND IFNULL(ddesc_china.ISDEL, '0') = '0'
    WHERE detail.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(detail.ISDEL, '0') = '0'
      AND IFNULL(detail.AMOUNT, 0) <> 0
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <= v_to_ymd
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <> ''
      AND (IFNULL(ext.CUSTOMER_ID, 0) > 0 OR TRIM(IFNULL(ext.CUSTOMER_CD, '')) <> '')
      AND (v_customer_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), '')), v_customer_cd) > 0)
      AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(detail.FC_TYPE, 'VND')), v_fc_type) > 0);

    INSERT INTO tmp_ar_detail_movements
    (
        ACCOUNT_SORT,
        ACC_CD,
        ACCOUNT_NAME,
        CUSTOMER_KEY,
        CUSTOMER_ID,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        CHIT_YMD,
        ENTRY_DATE,
        DOCUMENT_NO,
        DOCUMENT_DATE,
        DESCRIPTION,
        COUNTER_ACCOUNT,
        DISCOUNT_TERM_TEXT,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT,
        NOTE_TEXT,
        SORT_NO,
        SORT_CHIT_TYPE,
        SORT_CHIT_ID,
        SORT_DETAIL,
        SORT_SIDE
    )
    SELECT
        account.ACCOUNT_SORT,
        account.ACC_CD,
        account.ACCOUNT_NAME,
        CASE
            WHEN IFNULL(ext.CUSTOMER_ID, 0) > 0 THEN CONCAT('ID:', ext.CUSTOMER_ID)
            WHEN by_cd.CUSTOMER_ID > 0 THEN CONCAT('ID:', by_cd.CUSTOMER_ID)
            ELSE CONCAT('CD:', TRIM(IFNULL(ext.CUSTOMER_CD, '')))
        END,
        COALESCE(NULLIF(ext.CUSTOMER_ID, 0), by_cd.CUSTOMER_ID, 0),
        COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), ''),
        TRIM(IFNULL(ext.CUSTOMER_OWN_CD, '')),
        COALESCE(NULLIF(by_id.CUSTOMER_NAME, ''), NULLIF(by_cd.CUSTOMER_NAME, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), CAST(IFNULL(ext.CUSTOMER_ID, 0) AS CHAR)),
        COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), ''),
        CASE WHEN IFNULL(header.CHIT_YMD, '') REGEXP '^[0-9]{8}$' THEN DATE_FORMAT(STR_TO_DATE(header.CHIT_YMD, '%Y%m%d'), '%d/%m/%Y') ELSE IFNULL(header.CHIT_YMD, '') END,
        COALESCE(NULLIF(TRIM(header.CHIT_NO), ''), NULLIF(TRIM(header.CHIT_CD), ''), ''),
        CASE
            WHEN COALESCE(NULLIF(detail.CHIT_YMD, ''), header.CHIT_YMD) REGEXP '^[0-9]{8}$'
            THEN DATE_FORMAT(STR_TO_DATE(COALESCE(NULLIF(detail.CHIT_YMD, ''), header.CHIT_YMD), '%Y%m%d'), '%d/%m/%Y')
            ELSE COALESCE(NULLIF(detail.CHIT_YMD, ''), header.CHIT_YMD)
        END,
        COALESCE(
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN ddesc_en.DESCRIPTION WHEN 'KOR' THEN ddesc_ko.DESCRIPTION WHEN 'CHINA' THEN ddesc_china.DESCRIPTION ELSE ddesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN hdesc_en.DESCRIPTION WHEN 'KOR' THEN hdesc_ko.DESCRIPTION WHEN 'CHINA' THEN hdesc_china.DESCRIPTION ELSE hdesc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(header.PAYER_INFO), ''),
            ''
        ),
        TRIM(IFNULL(detail.DEBIT, '')),
        COALESCE(NULLIF(TRIM(header_ext.TIME_FOR_PAYMENT), ''), NULLIF(TRIM(header_ext.DAY_OF_PAYMENT), ''), ''),
        0,
        CASE WHEN v_use_fc = 1 THEN IFNULL(detail.FC_AMOUNT, 0) ELSE IFNULL(detail.AMOUNT, 0) END,
        IFNULL(detail.CHITDETAIL_CD, ''),
        IFNULL(header.CHIT_NO, ''),
        IFNULL(header.CHIT_TYPE, ''),
        IFNULL(header.CHIT_ID, 0),
        IFNULL(detail.SORT, 0),
        2
    FROM chitdetailinfo detail
    INNER JOIN tmp_ar_detail_accounts account
        ON account.ACC_CD = TRIM(IFNULL(detail.CREDIT, ''))
    INNER JOIN chitinfo header
        ON header.COMPANY_CD = detail.COMPANY_CD
       AND header.CHIT_ID = detail.CHIT_ID
       AND IFNULL(header.ISDEL, '0') = '0'
    INNER JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = detail.COMPANY_CD
       AND ext.CHITDETAIL_ID = detail.CHITDETAIL_ID
       AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN chitinfo_ext header_ext
        ON header_ext.COMPANY_CD = header.COMPANY_CD
       AND header_ext.CHIT_ID = header.CHIT_ID
       AND IFNULL(header_ext.ISDEL, '0') = '0'
    LEFT JOIN tmp_ar_detail_customer_by_id by_id
        ON by_id.CUSTOMER_ID = IFNULL(ext.CUSTOMER_ID, 0)
    LEFT JOIN tmp_ar_detail_customer_by_cd by_cd
        ON by_cd.CUSTOMER_CD = TRIM(IFNULL(ext.CUSTOMER_CD, ''))
    LEFT JOIN chitdescriptioninfo hdesc_vi ON hdesc_vi.COMPANY_CD = header.COMPANY_CD AND hdesc_vi.CHIT_ID = header.CHIT_ID AND hdesc_vi.LANG_TYPE = 'VIET' AND IFNULL(hdesc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_en ON hdesc_en.COMPANY_CD = header.COMPANY_CD AND hdesc_en.CHIT_ID = header.CHIT_ID AND hdesc_en.LANG_TYPE = 'ENG' AND IFNULL(hdesc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_ko ON hdesc_ko.COMPANY_CD = header.COMPANY_CD AND hdesc_ko.CHIT_ID = header.CHIT_ID AND hdesc_ko.LANG_TYPE = 'KOR' AND IFNULL(hdesc_ko.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_china ON hdesc_china.COMPANY_CD = header.COMPANY_CD AND hdesc_china.CHIT_ID = header.CHIT_ID AND hdesc_china.LANG_TYPE = 'CHINA' AND IFNULL(hdesc_china.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_vi ON ddesc_vi.COMPANY_CD = detail.COMPANY_CD AND ddesc_vi.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_vi.LANG_TYPE = 'VIET' AND IFNULL(ddesc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_en ON ddesc_en.COMPANY_CD = detail.COMPANY_CD AND ddesc_en.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_en.LANG_TYPE = 'ENG' AND IFNULL(ddesc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_ko ON ddesc_ko.COMPANY_CD = detail.COMPANY_CD AND ddesc_ko.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_ko.LANG_TYPE = 'KOR' AND IFNULL(ddesc_ko.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_china ON ddesc_china.COMPANY_CD = detail.COMPANY_CD AND ddesc_china.CHITDETAIL_ID = detail.CHITDETAIL_ID AND ddesc_china.LANG_TYPE = 'CHINA' AND IFNULL(ddesc_china.ISDEL, '0') = '0'
    WHERE detail.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(detail.ISDEL, '0') = '0'
      AND IFNULL(detail.AMOUNT, 0) <> 0
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <= v_to_ymd
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <> ''
      AND (IFNULL(ext.CUSTOMER_ID, 0) > 0 OR TRIM(IFNULL(ext.CUSTOMER_CD, '')) <> '')
      AND (v_customer_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), '')), v_customer_cd) > 0)
      AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(detail.FC_TYPE, 'VND')), v_fc_type) > 0);

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_latest_open;
    CREATE TEMPORARY TABLE tmp_ar_detail_latest_open
    (
        ACC_CD VARCHAR(20) NOT NULL,
        CUSTOMER_KEY VARCHAR(80) NOT NULL,
        OPEN_YMD VARCHAR(8) NOT NULL DEFAULT '',
        PRIMARY KEY (ACC_CD, CUSTOMER_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_detail_latest_open (ACC_CD, CUSTOMER_KEY, OPEN_YMD)
    SELECT
        account.ACC_CD,
        CASE
            WHEN IFNULL(opening.CUSTOMER_ID, 0) > 0 THEN CONCAT('ID:', opening.CUSTOMER_ID)
            ELSE CONCAT('NM:', TRIM(IFNULL(opening.CUSTOMER_NM, '')))
        END,
        IFNULL(MAX(opening.OPEN_YMD), '')
    FROM before_states_customer opening
    INNER JOIN tmp_ar_detail_accounts account
        ON account.ACC_CD = opening.ACC_CD
    LEFT JOIN tmp_ar_detail_customer_by_id customer
        ON customer.CUSTOMER_ID = IFNULL(opening.CUSTOMER_ID, 0)
    WHERE opening.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(opening.ISDEL, '0') = '0'
      AND (IFNULL(opening.CUSTOMER_ID, 0) > 0 OR TRIM(IFNULL(opening.CUSTOMER_NM, '')) <> '')
      AND IFNULL(opening.OPEN_YMD, '') <= v_before_from_ymd
      AND (v_customer_cd = '' OR FIND_IN_SET(customer.CUSTOMER_CD, v_customer_cd) > 0)
      AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(opening.FC_TYPE, 'VND')), v_fc_type) > 0)
    GROUP BY
        account.ACC_CD,
        CASE
            WHEN IFNULL(opening.CUSTOMER_ID, 0) > 0 THEN CONCAT('ID:', opening.CUSTOMER_ID)
            ELSE CONCAT('NM:', TRIM(IFNULL(opening.CUSTOMER_NM, '')))
        END;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_opening;
    CREATE TEMPORARY TABLE tmp_ar_detail_opening
    (
        ACC_CD VARCHAR(20) NOT NULL,
        CUSTOMER_KEY VARCHAR(80) NOT NULL,
        CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        OPEN_YMD VARCHAR(8) NOT NULL DEFAULT '00000000',
        DEBIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        CREDIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PRIMARY KEY (ACC_CD, CUSTOMER_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_detail_opening
    (
        ACC_CD,
        CUSTOMER_KEY,
        CUSTOMER_ID,
        CUSTOMER_CD,
        CUSTOMER_NAME,
        OPEN_YMD,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT
    )
    SELECT
        latest.ACC_CD,
        latest.CUSTOMER_KEY,
        IFNULL(opening.CUSTOMER_ID, 0),
        IFNULL(customer.CUSTOMER_CD, ''),
        COALESCE(NULLIF(customer.CUSTOMER_NAME, ''), NULLIF(opening.CUSTOMER_NM, ''), IFNULL(customer.CUSTOMER_CD, '')),
        IFNULL(NULLIF(latest.OPEN_YMD, ''), '00000000'),
        IFNULL(SUM(CASE WHEN v_use_fc = 1 THEN opening.DEBIT_FC ELSE opening.DEBIT END), 0),
        IFNULL(SUM(CASE WHEN v_use_fc = 1 THEN opening.CREDIT_FC ELSE opening.CREDIT END), 0)
    FROM tmp_ar_detail_latest_open latest
    INNER JOIN before_states_customer opening
        ON opening.COMPANY_CD = p_COMPANY_CD
       AND opening.ACC_CD = latest.ACC_CD
       AND CASE
            WHEN IFNULL(opening.CUSTOMER_ID, 0) > 0 THEN CONCAT('ID:', opening.CUSTOMER_ID)
            ELSE CONCAT('NM:', TRIM(IFNULL(opening.CUSTOMER_NM, '')))
           END = latest.CUSTOMER_KEY
       AND opening.OPEN_YMD = latest.OPEN_YMD
       AND IFNULL(opening.ISDEL, '0') = '0'
    LEFT JOIN tmp_ar_detail_customer_by_id customer
        ON customer.CUSTOMER_ID = IFNULL(opening.CUSTOMER_ID, 0)
    WHERE v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(opening.FC_TYPE, 'VND')), v_fc_type) > 0
    GROUP BY latest.ACC_CD, latest.CUSTOMER_KEY, opening.CUSTOMER_ID, customer.CUSTOMER_CD, customer.CUSTOMER_NAME, opening.CUSTOMER_NM, latest.OPEN_YMD;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_subjects;
    CREATE TEMPORARY TABLE tmp_ar_detail_subjects
    (
        ACC_CD VARCHAR(20) NOT NULL,
        CUSTOMER_KEY VARCHAR(80) NOT NULL,
        CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_OWN_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ACC_CD, CUSTOMER_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_detail_subjects (ACC_CD, CUSTOMER_KEY, CUSTOMER_ID, CUSTOMER_CD, CUSTOMER_OWN_CD, CUSTOMER_NAME)
    SELECT
        movement.ACC_CD,
        movement.CUSTOMER_KEY,
        MAX(movement.CUSTOMER_ID),
        MAX(movement.CUSTOMER_CD),
        MAX(movement.CUSTOMER_OWN_CD),
        MAX(movement.CUSTOMER_NAME)
    FROM tmp_ar_detail_movements movement
    WHERE movement.CUSTOMER_KEY <> ''
    GROUP BY movement.ACC_CD, movement.CUSTOMER_KEY;

    INSERT INTO tmp_ar_detail_subjects (ACC_CD, CUSTOMER_KEY, CUSTOMER_ID, CUSTOMER_CD, CUSTOMER_OWN_CD, CUSTOMER_NAME)
    SELECT
        opening.ACC_CD,
        opening.CUSTOMER_KEY,
        opening.CUSTOMER_ID,
        opening.CUSTOMER_CD,
        '',
        opening.CUSTOMER_NAME
    FROM tmp_ar_detail_opening opening
    ON DUPLICATE KEY UPDATE
        CUSTOMER_ID = IF(tmp_ar_detail_subjects.CUSTOMER_ID = 0, VALUES(CUSTOMER_ID), tmp_ar_detail_subjects.CUSTOMER_ID),
        CUSTOMER_CD = IF(tmp_ar_detail_subjects.CUSTOMER_CD = '', VALUES(CUSTOMER_CD), tmp_ar_detail_subjects.CUSTOMER_CD),
        CUSTOMER_NAME = IF(tmp_ar_detail_subjects.CUSTOMER_NAME = '', VALUES(CUSTOMER_NAME), tmp_ar_detail_subjects.CUSTOMER_NAME);

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_keys;
    CREATE TEMPORARY TABLE tmp_ar_detail_keys
    (
        ACC_CD VARCHAR(20) NOT NULL,
        CUSTOMER_KEY VARCHAR(80) NOT NULL,
        PRIMARY KEY (ACC_CD, CUSTOMER_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT IGNORE INTO tmp_ar_detail_keys (ACC_CD, CUSTOMER_KEY)
    SELECT ACC_CD, CUSTOMER_KEY
    FROM tmp_ar_detail_opening;

    INSERT IGNORE INTO tmp_ar_detail_keys (ACC_CD, CUSTOMER_KEY)
    SELECT ACC_CD, CUSTOMER_KEY
    FROM tmp_ar_detail_movements
    WHERE CUSTOMER_KEY <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_balance;
    CREATE TEMPORARY TABLE tmp_ar_detail_balance
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ACCOUNT_SORT INT NOT NULL DEFAULT 0,
        ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        CUSTOMER_KEY VARCHAR(80) NOT NULL DEFAULT '',
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_OWN_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        OPENING_NET DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PERIOD_DEBIT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PERIOD_CREDIT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        ENDING_NET DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PRIMARY KEY (ROW_NO),
        UNIQUE KEY uq_tmp_ar_detail_balance_01 (ACC_CD, CUSTOMER_KEY),
        INDEX idx_tmp_ar_detail_balance_01 (ACCOUNT_SORT, CUSTOMER_CD, CUSTOMER_NAME)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_detail_balance
    (
        ACCOUNT_SORT,
        ACC_CD,
        ACCOUNT_NAME,
        CUSTOMER_KEY,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        OPENING_NET,
        PERIOD_DEBIT,
        PERIOD_CREDIT,
        ENDING_NET
    )
    SELECT
        account.ACCOUNT_SORT,
        account.ACC_CD,
        account.ACCOUNT_NAME,
        detail_key.CUSTOMER_KEY,
        IFNULL(subject.CUSTOMER_CD, ''),
        IFNULL(subject.CUSTOMER_OWN_CD, ''),
        IFNULL(subject.CUSTOMER_NAME, ''),
        IFNULL(opening.DEBIT_AMOUNT, 0) - IFNULL(opening.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000')
             AND movement.CHIT_YMD < v_from_ymd
            THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
            ELSE 0
        END), 0),
        IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= v_from_ymd
             AND movement.CHIT_YMD <= v_to_ymd
            THEN movement.DEBIT_AMOUNT
            ELSE 0
        END), 0),
        IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= v_from_ymd
             AND movement.CHIT_YMD <= v_to_ymd
            THEN movement.CREDIT_AMOUNT
            ELSE 0
        END), 0),
        IFNULL(opening.DEBIT_AMOUNT, 0) - IFNULL(opening.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000')
             AND movement.CHIT_YMD <= v_to_ymd
            THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
            ELSE 0
        END), 0)
    FROM tmp_ar_detail_keys detail_key
    INNER JOIN tmp_ar_detail_accounts account
        ON account.ACC_CD = detail_key.ACC_CD
    INNER JOIN tmp_ar_detail_subjects subject
        ON subject.ACC_CD = detail_key.ACC_CD
       AND subject.CUSTOMER_KEY = detail_key.CUSTOMER_KEY
    LEFT JOIN tmp_ar_detail_opening opening
        ON opening.ACC_CD = detail_key.ACC_CD
       AND opening.CUSTOMER_KEY = detail_key.CUSTOMER_KEY
    LEFT JOIN tmp_ar_detail_movements movement
        ON movement.ACC_CD = detail_key.ACC_CD
       AND movement.CUSTOMER_KEY = detail_key.CUSTOMER_KEY
    GROUP BY
        account.ACCOUNT_SORT,
        account.ACC_CD,
        account.ACCOUNT_NAME,
        detail_key.CUSTOMER_KEY,
        subject.CUSTOMER_CD,
        subject.CUSTOMER_OWN_CD,
        subject.CUSTOMER_NAME,
        opening.OPEN_YMD,
        opening.DEBIT_AMOUNT,
        opening.CREDIT_AMOUNT
    HAVING
        ROUND(IFNULL(opening.DEBIT_AMOUNT, 0) - IFNULL(opening.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000')
             AND movement.CHIT_YMD < v_from_ymd
            THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
            ELSE 0
        END), 0), 0) <> 0
        OR ROUND(IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= v_from_ymd
             AND movement.CHIT_YMD <= v_to_ymd
            THEN movement.DEBIT_AMOUNT
            ELSE 0
        END), 0), 0) <> 0
        OR ROUND(IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= v_from_ymd
             AND movement.CHIT_YMD <= v_to_ymd
            THEN movement.CREDIT_AMOUNT
            ELSE 0
        END), 0), 0) <> 0
        OR ROUND(IFNULL(opening.DEBIT_AMOUNT, 0) - IFNULL(opening.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000')
             AND movement.CHIT_YMD <= v_to_ymd
            THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
            ELSE 0
        END), 0), 0) <> 0
    ORDER BY account.ACCOUNT_SORT, subject.CUSTOMER_CD, subject.CUSTOMER_NAME, detail_key.CUSTOMER_KEY;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_report;
    CREATE TEMPORARY TABLE tmp_ar_detail_report
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ROW_KEY VARCHAR(120) NOT NULL DEFAULT '',
        PARENT_ROW_KEY VARCHAR(120) NULL,
        ROW_SORT BIGINT NOT NULL DEFAULT 0,
        ROW_TYPE VARCHAR(30) NOT NULL DEFAULT '',
        ROW_LEVEL INT NOT NULL DEFAULT 0,
        DRILL_TYPE VARCHAR(20) NOT NULL DEFAULT 'NONE',
        SOURCE_DOC_TYPE VARCHAR(20) NOT NULL DEFAULT '',
        SOURCE_DOC_ID BIGINT NOT NULL DEFAULT 0,
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        REPORT_GROUP_KEY VARCHAR(120) NOT NULL DEFAULT '',
        REPORT_PERIOD_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        ACCOUNT_FILTER_TEXT VARCHAR(1000) NOT NULL DEFAULT '',
        CUSTOMER_FILTER_TEXT VARCHAR(1000) NOT NULL DEFAULT '',
        ACCOUNT_CD_TEXT VARCHAR(1000) NOT NULL DEFAULT '',
        ACCOUNT_NAME_TEXT VARCHAR(1000) NOT NULL DEFAULT '',
        CUSTOMER_CD_TEXT VARCHAR(1000) NOT NULL DEFAULT '',
        CUSTOMER_OWN_CD_TEXT VARCHAR(1000) NOT NULL DEFAULT '',
        CUSTOMER_NAME_TEXT VARCHAR(1000) NOT NULL DEFAULT '',
        CURRENCY_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        ENTRY_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DOCUMENT_NO VARCHAR(50) NOT NULL DEFAULT '',
        DOCUMENT_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
        COUNTER_ACCOUNT VARCHAR(50) NOT NULL DEFAULT '',
        DISCOUNT_TERM_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        DEBIT_AMOUNT DECIMAL(18,6) NULL,
        CREDIT_AMOUNT DECIMAL(18,6) NULL,
        BALANCE_DEBIT DECIMAL(18,6) NULL,
        BALANCE_CREDIT DECIMAL(18,6) NULL,
        NOTE_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ROW_NO),
        INDEX idx_tmp_ar_detail_report_01 (ROW_SORT, ROW_NO)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    IF (SELECT COUNT(*) FROM tmp_ar_detail_balance) = 0 THEN
        INSERT INTO tmp_ar_detail_report
        (
            ROW_KEY,
            ROW_SORT,
            ROW_TYPE,
            ROW_LEVEL,
            DRILL_TYPE,
            SOURCE_DOC_TYPE,
            SOURCE_DOC_ID,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            REPORT_PERIOD_TEXT,
            ACCOUNT_FILTER_TEXT,
            CUSTOMER_FILTER_TEXT,
            CURRENCY_TEXT,
            DESCRIPTION
        )
        VALUES
        (
            'AR_DETAIL_EMPTY',
            10,
            'EMPTY',
            0,
            'NONE',
            '',
            0,
            p_COMPANY_CD,
            'AR_DETAIL',
            v_report_period_text,
            v_account_filter_text,
            v_customer_filter_text,
            v_currency_text,
            'Không có dữ liệu'
        );
    ELSE
        INSERT INTO tmp_ar_detail_report
        (
            ROW_KEY,
            ROW_SORT,
            ROW_TYPE,
            ROW_LEVEL,
            DRILL_TYPE,
            SOURCE_DOC_TYPE,
            SOURCE_DOC_ID,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            REPORT_PERIOD_TEXT,
            ACCOUNT_FILTER_TEXT,
            CUSTOMER_FILTER_TEXT,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            CUSTOMER_CD_TEXT,
            CUSTOMER_OWN_CD_TEXT,
            CUSTOMER_NAME_TEXT,
            CURRENCY_TEXT,
            DESCRIPTION
        )
        SELECT
            CONCAT('AR_DETAIL_GROUP_', balance.ROW_NO),
            balance.ROW_NO * 1000000,
            'GROUP',
            0,
            'NONE',
            '',
            0,
            p_COMPANY_CD,
            CONCAT('AR_DETAIL_', balance.ROW_NO, '_', balance.ACC_CD, '_', balance.CUSTOMER_KEY),
            v_report_period_text,
            v_account_filter_text,
            v_customer_filter_text,
            balance.ACC_CD,
            balance.ACCOUNT_NAME,
            balance.CUSTOMER_CD,
            balance.CUSTOMER_OWN_CD,
            balance.CUSTOMER_NAME,
            v_currency_text,
            CONCAT(balance.ACC_CD, ' - ', balance.ACCOUNT_NAME, ' / ', balance.CUSTOMER_NAME)
        FROM tmp_ar_detail_balance balance;

        INSERT INTO tmp_ar_detail_report
        (
            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            ROW_TYPE,
            ROW_LEVEL,
            DRILL_TYPE,
            SOURCE_DOC_TYPE,
            SOURCE_DOC_ID,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            REPORT_PERIOD_TEXT,
            ACCOUNT_FILTER_TEXT,
            CUSTOMER_FILTER_TEXT,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            CUSTOMER_CD_TEXT,
            CUSTOMER_OWN_CD_TEXT,
            CUSTOMER_NAME_TEXT,
            CURRENCY_TEXT,
            DESCRIPTION,
            BALANCE_DEBIT,
            BALANCE_CREDIT
        )
        SELECT
            CONCAT('AR_DETAIL_OPENING_', balance.ROW_NO),
            CONCAT('AR_DETAIL_GROUP_', balance.ROW_NO),
            balance.ROW_NO * 1000000 + 10,
            'OPENING_TOTAL',
            1,
            'NONE',
            '',
            0,
            p_COMPANY_CD,
            CONCAT('AR_DETAIL_', balance.ROW_NO, '_', balance.ACC_CD, '_', balance.CUSTOMER_KEY),
            v_report_period_text,
            v_account_filter_text,
            v_customer_filter_text,
            balance.ACC_CD,
            balance.ACCOUNT_NAME,
            balance.CUSTOMER_CD,
            balance.CUSTOMER_OWN_CD,
            balance.CUSTOMER_NAME,
            v_currency_text,
            'Số dư đầu kỳ',
            NULLIF(ROUND(GREATEST(balance.OPENING_NET, 0), 2), 0),
            NULLIF(ROUND(GREATEST(-balance.OPENING_NET, 0), 2), 0)
        FROM tmp_ar_detail_balance balance;

        INSERT INTO tmp_ar_detail_report
        (
            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            ROW_TYPE,
            ROW_LEVEL,
            DRILL_TYPE,
            SOURCE_DOC_TYPE,
            SOURCE_DOC_ID,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            REPORT_PERIOD_TEXT,
            ACCOUNT_FILTER_TEXT,
            CUSTOMER_FILTER_TEXT,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            CUSTOMER_CD_TEXT,
            CUSTOMER_OWN_CD_TEXT,
            CUSTOMER_NAME_TEXT,
            CURRENCY_TEXT,
            DESCRIPTION
        )
        SELECT
            CONCAT('AR_DETAIL_PERIOD_HEADER_', balance.ROW_NO),
            CONCAT('AR_DETAIL_GROUP_', balance.ROW_NO),
            balance.ROW_NO * 1000000 + 20,
            'SECTION',
            1,
            'NONE',
            '',
            0,
            p_COMPANY_CD,
            CONCAT('AR_DETAIL_', balance.ROW_NO, '_', balance.ACC_CD, '_', balance.CUSTOMER_KEY),
            v_report_period_text,
            v_account_filter_text,
            v_customer_filter_text,
            balance.ACC_CD,
            balance.ACCOUNT_NAME,
            balance.CUSTOMER_CD,
            balance.CUSTOMER_OWN_CD,
            balance.CUSTOMER_NAME,
            v_currency_text,
            'Số phát sinh trong kỳ'
        FROM tmp_ar_detail_balance balance;

        INSERT INTO tmp_ar_detail_report
        (
            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            ROW_TYPE,
            ROW_LEVEL,
            DRILL_TYPE,
            SOURCE_DOC_TYPE,
            SOURCE_DOC_ID,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            REPORT_PERIOD_TEXT,
            ACCOUNT_FILTER_TEXT,
            CUSTOMER_FILTER_TEXT,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            CUSTOMER_CD_TEXT,
            CUSTOMER_OWN_CD_TEXT,
            CUSTOMER_NAME_TEXT,
            CURRENCY_TEXT,
            ENTRY_DATE,
            DOCUMENT_NO,
            DOCUMENT_DATE,
            DESCRIPTION,
            COUNTER_ACCOUNT,
            DISCOUNT_TERM_TEXT,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT,
            BALANCE_DEBIT,
            BALANCE_CREDIT,
            NOTE_TEXT
        )
        SELECT
            CONCAT('AR_DETAIL_LINE_', running.ROW_NO),
            CONCAT('AR_DETAIL_GROUP_', running.PAIR_SORT),
            running.PAIR_SORT * 1000000 + 1000 + running.ROW_NO,
            'DETAIL',
            2,
            CASE WHEN running.SORT_CHIT_ID > 0 AND running.SORT_CHIT_TYPE <> '' THEN 'DOCUMENT' ELSE 'NONE' END,
            running.SORT_CHIT_TYPE,
            running.SORT_CHIT_ID,
            p_COMPANY_CD,
            CONCAT('AR_DETAIL_', running.PAIR_SORT, '_', running.ACC_CD, '_', running.CUSTOMER_KEY),
            v_report_period_text,
            v_account_filter_text,
            v_customer_filter_text,
            running.ACC_CD,
            running.ACCOUNT_NAME,
            running.CUSTOMER_CD,
            running.CUSTOMER_OWN_CD,
            running.CUSTOMER_NAME,
            v_currency_text,
            running.ENTRY_DATE,
            running.DOCUMENT_NO,
            running.DOCUMENT_DATE,
            running.DESCRIPTION,
            running.COUNTER_ACCOUNT,
            running.DISCOUNT_TERM_TEXT,
            NULLIF(ROUND(running.DEBIT_AMOUNT, 2), 0),
            NULLIF(ROUND(running.CREDIT_AMOUNT, 2), 0),
            NULLIF(ROUND(GREATEST(running.RUNNING_NET, 0), 2), 0),
            NULLIF(ROUND(GREATEST(-running.RUNNING_NET, 0), 2), 0),
            running.NOTE_TEXT
        FROM
        (
            SELECT
                ordered_movement.*,
                @ar_detail_running_balance := CASE
                    WHEN CONVERT(@ar_detail_running_key USING utf8) COLLATE utf8_unicode_ci = ordered_movement.RUNNING_KEY COLLATE utf8_unicode_ci
                    THEN @ar_detail_running_balance + ordered_movement.DEBIT_AMOUNT - ordered_movement.CREDIT_AMOUNT
                    ELSE ordered_movement.OPENING_NET + ordered_movement.DEBIT_AMOUNT - ordered_movement.CREDIT_AMOUNT
                END AS RUNNING_NET,
                @ar_detail_running_key := CONVERT(ordered_movement.RUNNING_KEY USING utf8) COLLATE utf8_unicode_ci AS TRACK_KEY
            FROM
            (
                SELECT
                    movement.ROW_NO,
                    balance.ROW_NO AS PAIR_SORT,
                    movement.ACCOUNT_SORT,
                    movement.ACC_CD,
                    movement.ACCOUNT_NAME,
                    movement.CUSTOMER_KEY,
                    movement.CUSTOMER_CD,
                    movement.CUSTOMER_OWN_CD,
                    movement.CUSTOMER_NAME,
                    CONVERT(CONCAT(movement.ACC_CD, '|', movement.CUSTOMER_KEY) USING utf8) COLLATE utf8_unicode_ci AS RUNNING_KEY,
                    movement.CHIT_YMD,
                    movement.ENTRY_DATE,
                    movement.DOCUMENT_NO,
                    movement.DOCUMENT_DATE,
                    movement.DESCRIPTION,
                    movement.COUNTER_ACCOUNT,
                    movement.DISCOUNT_TERM_TEXT,
                    movement.DEBIT_AMOUNT,
                    movement.CREDIT_AMOUNT,
                    movement.NOTE_TEXT,
                    movement.SORT_CHIT_TYPE,
                    movement.SORT_CHIT_ID,
                    balance.OPENING_NET
                FROM tmp_ar_detail_movements movement
                INNER JOIN tmp_ar_detail_balance balance
                    ON balance.ACC_CD = movement.ACC_CD
                   AND balance.CUSTOMER_KEY = movement.CUSTOMER_KEY
                WHERE movement.CHIT_YMD >= v_from_ymd
                  AND movement.CHIT_YMD <= v_to_ymd
                ORDER BY balance.ROW_NO, movement.CHIT_YMD, movement.SORT_NO, movement.SORT_CHIT_ID, movement.SORT_DETAIL, movement.SORT_SIDE, movement.ROW_NO
            ) ordered_movement
            CROSS JOIN (SELECT @ar_detail_running_key := CONVERT('' USING utf8) COLLATE utf8_unicode_ci, @ar_detail_running_balance := 0.000000) vars
        ) running;

        INSERT INTO tmp_ar_detail_report
        (
            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            ROW_TYPE,
            ROW_LEVEL,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            REPORT_PERIOD_TEXT,
            ACCOUNT_FILTER_TEXT,
            CUSTOMER_FILTER_TEXT,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            CUSTOMER_CD_TEXT,
            CUSTOMER_OWN_CD_TEXT,
            CUSTOMER_NAME_TEXT,
            CURRENCY_TEXT,
            DESCRIPTION,
            COUNTER_ACCOUNT,
            DISCOUNT_TERM_TEXT,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT
        )
        SELECT
            CONCAT('AR_DETAIL_TOTAL_PERIOD_', balance.ROW_NO),
            CONCAT('AR_DETAIL_GROUP_', balance.ROW_NO),
            balance.ROW_NO * 1000000 + 900000,
            'TOTAL_PERIOD',
            1,
            p_COMPANY_CD,
            CONCAT('AR_DETAIL_', balance.ROW_NO, '_', balance.ACC_CD, '_', balance.CUSTOMER_KEY),
            v_report_period_text,
            v_account_filter_text,
            v_customer_filter_text,
            balance.ACC_CD,
            balance.ACCOUNT_NAME,
            balance.CUSTOMER_CD,
            balance.CUSTOMER_OWN_CD,
            balance.CUSTOMER_NAME,
            v_currency_text,
            'Cộng số phát sinh',
            'x',
            'x',
            NULLIF(ROUND(balance.PERIOD_DEBIT, 2), 0),
            NULLIF(ROUND(balance.PERIOD_CREDIT, 2), 0)
        FROM tmp_ar_detail_balance balance;

        INSERT INTO tmp_ar_detail_report
        (
            ROW_KEY,
            PARENT_ROW_KEY,
            ROW_SORT,
            ROW_TYPE,
            ROW_LEVEL,
            COMPANY_CD,
            REPORT_GROUP_KEY,
            REPORT_PERIOD_TEXT,
            ACCOUNT_FILTER_TEXT,
            CUSTOMER_FILTER_TEXT,
            ACCOUNT_CD_TEXT,
            ACCOUNT_NAME_TEXT,
            CUSTOMER_CD_TEXT,
            CUSTOMER_OWN_CD_TEXT,
            CUSTOMER_NAME_TEXT,
            CURRENCY_TEXT,
            DESCRIPTION,
            COUNTER_ACCOUNT,
            DISCOUNT_TERM_TEXT,
            BALANCE_DEBIT,
            BALANCE_CREDIT
        )
        SELECT
            CONCAT('AR_DETAIL_ENDING_', balance.ROW_NO),
            CONCAT('AR_DETAIL_GROUP_', balance.ROW_NO),
            balance.ROW_NO * 1000000 + 900010,
            'ENDING_TOTAL',
            1,
            p_COMPANY_CD,
            CONCAT('AR_DETAIL_', balance.ROW_NO, '_', balance.ACC_CD, '_', balance.CUSTOMER_KEY),
            v_report_period_text,
            v_account_filter_text,
            v_customer_filter_text,
            balance.ACC_CD,
            balance.ACCOUNT_NAME,
            balance.CUSTOMER_CD,
            balance.CUSTOMER_OWN_CD,
            balance.CUSTOMER_NAME,
            v_currency_text,
            'Số dư cuối kỳ',
            'x',
            'x',
            NULLIF(ROUND(GREATEST(balance.ENDING_NET, 0), 2), 0),
            NULLIF(ROUND(GREATEST(-balance.ENDING_NET, 0), 2), 0)
        FROM tmp_ar_detail_balance balance;
    END IF;

    SELECT
        ROW_KEY,
        PARENT_ROW_KEY,
        ROW_SORT,
        ROW_TYPE,
        ROW_LEVEL,
        DRILL_TYPE,
        SOURCE_DOC_TYPE,
        SOURCE_DOC_ID,
        COMPANY_CD,
        REPORT_GROUP_KEY,
        REPORT_PERIOD_TEXT,
        ACCOUNT_FILTER_TEXT,
        CUSTOMER_FILTER_TEXT,
        ACCOUNT_CD_TEXT,
        ACCOUNT_NAME_TEXT,
        CUSTOMER_CD_TEXT,
        CUSTOMER_OWN_CD_TEXT,
        CUSTOMER_NAME_TEXT,
        CURRENCY_TEXT,
        ENTRY_DATE,
        DOCUMENT_NO,
        DOCUMENT_DATE,
        DESCRIPTION,
        COUNTER_ACCOUNT,
        DISCOUNT_TERM_TEXT,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT,
        BALANCE_DEBIT,
        BALANCE_CREDIT,
        NOTE_TEXT
    FROM tmp_ar_detail_report
    ORDER BY ROW_SORT, ROW_NO;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_report;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_balance;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_keys;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_subjects;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_opening;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_latest_open;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_movements;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_accounts;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_customer_latest_id;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_customer_by_cd;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_detail_customer_by_id;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_ar_summary_s31dn
DROP PROCEDURE IF EXISTS `rpt_ar_summary_s31dn`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_ar_summary_s31dn`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_ACCOUNT_CD VARCHAR(1000),
    IN p_CUSTOMER_CD VARCHAR(1000),
    IN p_FC_TYPE VARCHAR(255),
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_before_from_ymd VARCHAR(8);
    DECLARE v_language VARCHAR(20);
    DECLARE v_account_cd VARCHAR(1000);
    DECLARE v_customer_cd VARCHAR(1000);
    DECLARE v_fc_type VARCHAR(255);
    DECLARE v_use_fc TINYINT DEFAULT 0;
    DECLARE v_currency_text VARCHAR(255);
    DECLARE v_report_period_text VARCHAR(255);
    DECLARE v_account_filter_text VARCHAR(1000);
    DECLARE v_amount_unit_text VARCHAR(100);

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;

    SET v_from_ymd = DATE_FORMAT(p_FROM_DATE, '%Y%m%d');
    SET v_to_ymd = DATE_FORMAT(p_TO_DATE, '%Y%m%d');
    SET v_before_from_ymd = DATE_FORMAT(DATE_SUB(p_FROM_DATE, INTERVAL 1 DAY), '%Y%m%d');
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));
    SET v_account_cd = REPLACE(TRIM(IFNULL(p_ACCOUNT_CD, '')), ' ', '');
    SET v_customer_cd = REPLACE(TRIM(IFNULL(p_CUSTOMER_CD, '')), ' ', '');
    SET v_fc_type = REPLACE(UPPER(TRIM(IFNULL(p_FC_TYPE, ''))), ' ', '');

    IF v_fc_type = 'ALL' THEN
        SET v_fc_type = '';
    END IF;

    SET v_use_fc = CASE WHEN v_fc_type <> '' AND v_fc_type <> 'VND' AND LOCATE(',', v_fc_type) = 0 THEN 1 ELSE 0 END;
    SET v_currency_text = CASE WHEN v_fc_type = '' THEN 'VND' ELSE v_fc_type END;
    SET v_report_period_text = CONCAT(DATE_FORMAT(p_FROM_DATE, '%d/%m/%Y'), '-', DATE_FORMAT(p_TO_DATE, '%d/%m/%Y'));
    SET v_account_filter_text = CASE WHEN v_account_cd = '' THEN 'Danh mục tài khoản : Tất cả' ELSE CONCAT('Danh mục tài khoản : ', v_account_cd) END;
    SET v_amount_unit_text = CONCAT('Đơn vị : ', v_currency_text);

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_customer_by_id;
    CREATE TEMPORARY TABLE tmp_ar_summary_customer_by_id
    (
        CUSTOMER_ID BIGINT NOT NULL,
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (CUSTOMER_ID),
        INDEX idx_tmp_ar_summary_customer_by_id_01 (CUSTOMER_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_summary_customer_by_id (CUSTOMER_ID, CUSTOMER_CD, CUSTOMER_NAME)
    SELECT
        customer.CUSTOMER_ID,
        TRIM(IFNULL(customer.CUSTOMER_CD, '')),
        COALESCE(
            NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN customer.CUSTOMER_NM_ENG
                WHEN 'KOR' THEN customer.CUSTOMER_NM_KOR
                WHEN 'CHINA' THEN customer.CUSTOMER_NM_CHINA
                ELSE customer.CUSTOMER_NM_VIET
            END), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_VIET), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_ENG), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_KOR), ''),
            NULLIF(TRIM(customer.CUSTOMER_NM_CHINA), ''),
            TRIM(IFNULL(customer.CUSTOMER_CD, ''))
        )
    FROM customer_info customer
    WHERE customer.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(customer.ISDEL, '0') = '0';

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_customer_by_cd;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_customer_latest_id;
    CREATE TEMPORARY TABLE tmp_ar_summary_customer_by_cd
    (
        CUSTOMER_CD VARCHAR(20) NOT NULL,
        CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (CUSTOMER_CD),
        INDEX idx_tmp_ar_summary_customer_by_cd_01 (CUSTOMER_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    CREATE TEMPORARY TABLE tmp_ar_summary_customer_latest_id
    (
        CUSTOMER_CD VARCHAR(20) NOT NULL,
        LATEST_CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        PRIMARY KEY (CUSTOMER_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_summary_customer_latest_id (CUSTOMER_CD, LATEST_CUSTOMER_ID)
    SELECT src.CUSTOMER_CD, MAX(src.CUSTOMER_ID) AS LATEST_CUSTOMER_ID
    FROM tmp_ar_summary_customer_by_id src
    WHERE src.CUSTOMER_CD <> ''
    GROUP BY src.CUSTOMER_CD;

    INSERT INTO tmp_ar_summary_customer_by_cd (CUSTOMER_CD, CUSTOMER_ID, CUSTOMER_NAME)
    SELECT by_id.CUSTOMER_CD, by_id.CUSTOMER_ID, by_id.CUSTOMER_NAME
    FROM tmp_ar_summary_customer_by_id by_id
    INNER JOIN tmp_ar_summary_customer_latest_id latest
        ON latest.CUSTOMER_CD = by_id.CUSTOMER_CD
       AND latest.LATEST_CUSTOMER_ID = by_id.CUSTOMER_ID;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_accounts;
    CREATE TEMPORARY TABLE tmp_ar_summary_accounts
    (
        ACCOUNT_SORT INT NOT NULL AUTO_INCREMENT,
        ACC_CD VARCHAR(20) NOT NULL,
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ACCOUNT_SORT),
        UNIQUE KEY uq_tmp_ar_summary_accounts_01 (ACC_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_summary_accounts (ACC_CD, ACCOUNT_NAME)
    SELECT
        account.ACC_CD,
        COALESCE(
            NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN account.ACCTITLE_NM_ENG
                WHEN 'KOR' THEN account.ACCTITLE_NM_KOR
                WHEN 'CHINA' THEN account.ACCTITLE_NM_CHINA
                WHEN 'JAPAN' THEN account.ACCTITLE_NM_JAPAN
                ELSE account.ACCTITLE_NM_VIET
            END), ''),
            NULLIF(TRIM(account.ACCTITLE_NM_VIET), ''),
            NULLIF(TRIM(account.ACCTITLE_NM_ENG), ''),
            account.ACC_CD
        )
    FROM acclist_info account
    INNER JOIN
    (
        SELECT ACC_CD, MAX(ACC_ID) AS ACC_ID
        FROM acclist_info
        WHERE COMPANY_CD = p_COMPANY_CD
          AND IFNULL(ISDEL, '0') = '0'
          AND TRIM(IFNULL(ACC_CD, '')) <> ''
        GROUP BY ACC_CD
    ) latest
        ON latest.ACC_ID = account.ACC_ID
    WHERE account.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(account.ISDEL, '0') = '0'
      AND (v_account_cd = '' OR FIND_IN_SET(account.ACC_CD, v_account_cd) > 0)
      AND (v_account_cd <> '' OR IFNULL(account.ISCUSTOMER, '0') = '1')
    ORDER BY account.ACC_CD;

    INSERT IGNORE INTO tmp_ar_summary_accounts (ACC_CD, ACCOUNT_NAME)
    SELECT source.ACC_CD, IFNULL(account_name.ACCOUNT_NAME, source.ACC_CD)
    FROM
    (
        SELECT DISTINCT TRIM(IFNULL(opening.ACC_CD, '')) AS ACC_CD
        FROM before_states_customer opening
        WHERE opening.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(opening.ISDEL, '0') = '0'
          AND TRIM(IFNULL(opening.ACC_CD, '')) <> ''
          AND IFNULL(opening.OPEN_YMD, '') <= v_before_from_ymd
        UNION
        SELECT DISTINCT TRIM(IFNULL(detail.DEBIT, '')) AS ACC_CD
        FROM chitdetailinfo detail
        INNER JOIN chitinfo header
            ON header.COMPANY_CD = detail.COMPANY_CD
           AND header.CHIT_ID = detail.CHIT_ID
           AND IFNULL(header.ISDEL, '0') = '0'
        INNER JOIN chitdetailinfo_ext ext
            ON ext.COMPANY_CD = detail.COMPANY_CD
           AND ext.CHITDETAIL_ID = detail.CHITDETAIL_ID
           AND IFNULL(ext.ISDEL, '0') = '0'
        WHERE detail.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(detail.ISDEL, '0') = '0'
          AND TRIM(IFNULL(detail.DEBIT, '')) <> ''
          AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <= v_to_ymd
          AND (IFNULL(ext.CUSTOMER_ID, 0) > 0 OR TRIM(IFNULL(ext.CUSTOMER_CD, '')) <> '')
        UNION
        SELECT DISTINCT TRIM(IFNULL(detail.CREDIT, '')) AS ACC_CD
        FROM chitdetailinfo detail
        INNER JOIN chitinfo header
            ON header.COMPANY_CD = detail.COMPANY_CD
           AND header.CHIT_ID = detail.CHIT_ID
           AND IFNULL(header.ISDEL, '0') = '0'
        INNER JOIN chitdetailinfo_ext ext
            ON ext.COMPANY_CD = detail.COMPANY_CD
           AND ext.CHITDETAIL_ID = detail.CHITDETAIL_ID
           AND IFNULL(ext.ISDEL, '0') = '0'
        WHERE detail.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(detail.ISDEL, '0') = '0'
          AND TRIM(IFNULL(detail.CREDIT, '')) <> ''
          AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <= v_to_ymd
          AND (IFNULL(ext.CUSTOMER_ID, 0) > 0 OR TRIM(IFNULL(ext.CUSTOMER_CD, '')) <> '')
    ) source
    LEFT JOIN
    (
        SELECT
            account.ACC_CD,
            COALESCE(NULLIF(TRIM(account.ACCTITLE_NM_VIET), ''), NULLIF(TRIM(account.ACCTITLE_NM_ENG), ''), account.ACC_CD) AS ACCOUNT_NAME,
            IFNULL(account.ISCUSTOMER, '0') AS ISCUSTOMER
        FROM acclist_info account
        INNER JOIN
        (
            SELECT ACC_CD, MAX(ACC_ID) AS ACC_ID
            FROM acclist_info
            WHERE COMPANY_CD = p_COMPANY_CD
              AND IFNULL(ISDEL, '0') = '0'
            GROUP BY ACC_CD
        ) latest_account
            ON latest_account.ACC_ID = account.ACC_ID
    ) account_name
        ON account_name.ACC_CD = source.ACC_CD
    WHERE source.ACC_CD <> ''
      AND (v_account_cd = '' OR FIND_IN_SET(source.ACC_CD, v_account_cd) > 0)
      AND (v_account_cd <> '' OR IFNULL(account_name.ISCUSTOMER, '1') = '1')
    ORDER BY source.ACC_CD;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_movements;
    CREATE TEMPORARY TABLE tmp_ar_summary_movements
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ACCOUNT_SORT INT NOT NULL DEFAULT 0,
        ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_KEY VARCHAR(50) NOT NULL DEFAULT '',
        CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_OWN_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        CHIT_YMD VARCHAR(8) NOT NULL DEFAULT '',
        DEBIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        CREDIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PRIMARY KEY (ROW_NO),
        INDEX idx_tmp_ar_summary_movements_01 (ACC_CD, CUSTOMER_KEY, CHIT_YMD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_summary_movements
    (
        ACCOUNT_SORT,
        ACC_CD,
        CUSTOMER_KEY,
        CUSTOMER_ID,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        CHIT_YMD,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT
    )
    SELECT
        account.ACCOUNT_SORT,
        account.ACC_CD,
        CASE
            WHEN IFNULL(ext.CUSTOMER_ID, 0) > 0 THEN CONCAT('ID:', ext.CUSTOMER_ID)
            WHEN by_cd.CUSTOMER_ID > 0 THEN CONCAT('ID:', by_cd.CUSTOMER_ID)
            ELSE CONCAT('CD:', TRIM(IFNULL(ext.CUSTOMER_CD, '')))
        END,
        COALESCE(NULLIF(ext.CUSTOMER_ID, 0), by_cd.CUSTOMER_ID, 0),
        COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), ''),
        TRIM(IFNULL(ext.CUSTOMER_OWN_CD, '')),
        COALESCE(NULLIF(by_id.CUSTOMER_NAME, ''), NULLIF(by_cd.CUSTOMER_NAME, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), CAST(IFNULL(ext.CUSTOMER_ID, 0) AS CHAR)),
        COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), ''),
        CASE WHEN v_use_fc = 1 THEN IFNULL(detail.FC_AMOUNT, 0) ELSE IFNULL(detail.AMOUNT, 0) END,
        0
    FROM chitdetailinfo detail
    INNER JOIN tmp_ar_summary_accounts account
        ON account.ACC_CD = TRIM(IFNULL(detail.DEBIT, ''))
    INNER JOIN chitinfo header
        ON header.COMPANY_CD = detail.COMPANY_CD
       AND header.CHIT_ID = detail.CHIT_ID
       AND IFNULL(header.ISDEL, '0') = '0'
    INNER JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = detail.COMPANY_CD
       AND ext.CHITDETAIL_ID = detail.CHITDETAIL_ID
       AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN tmp_ar_summary_customer_by_id by_id
        ON by_id.CUSTOMER_ID = IFNULL(ext.CUSTOMER_ID, 0)
    LEFT JOIN tmp_ar_summary_customer_by_cd by_cd
        ON by_cd.CUSTOMER_CD = TRIM(IFNULL(ext.CUSTOMER_CD, ''))
    WHERE detail.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(detail.ISDEL, '0') = '0'
      AND IFNULL(detail.AMOUNT, 0) <> 0
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <= v_to_ymd
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <> ''
      AND (IFNULL(ext.CUSTOMER_ID, 0) > 0 OR TRIM(IFNULL(ext.CUSTOMER_CD, '')) <> '')
      AND (v_customer_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), '')), v_customer_cd) > 0)
      AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(detail.FC_TYPE, 'VND')), v_fc_type) > 0);

    INSERT INTO tmp_ar_summary_movements
    (
        ACCOUNT_SORT,
        ACC_CD,
        CUSTOMER_KEY,
        CUSTOMER_ID,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        CHIT_YMD,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT
    )
    SELECT
        account.ACCOUNT_SORT,
        account.ACC_CD,
        CASE
            WHEN IFNULL(ext.CUSTOMER_ID, 0) > 0 THEN CONCAT('ID:', ext.CUSTOMER_ID)
            WHEN by_cd.CUSTOMER_ID > 0 THEN CONCAT('ID:', by_cd.CUSTOMER_ID)
            ELSE CONCAT('CD:', TRIM(IFNULL(ext.CUSTOMER_CD, '')))
        END,
        COALESCE(NULLIF(ext.CUSTOMER_ID, 0), by_cd.CUSTOMER_ID, 0),
        COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), ''),
        TRIM(IFNULL(ext.CUSTOMER_OWN_CD, '')),
        COALESCE(NULLIF(by_id.CUSTOMER_NAME, ''), NULLIF(by_cd.CUSTOMER_NAME, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), ''), CAST(IFNULL(ext.CUSTOMER_ID, 0) AS CHAR)),
        COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), ''),
        0,
        CASE WHEN v_use_fc = 1 THEN IFNULL(detail.FC_AMOUNT, 0) ELSE IFNULL(detail.AMOUNT, 0) END
    FROM chitdetailinfo detail
    INNER JOIN tmp_ar_summary_accounts account
        ON account.ACC_CD = TRIM(IFNULL(detail.CREDIT, ''))
    INNER JOIN chitinfo header
        ON header.COMPANY_CD = detail.COMPANY_CD
       AND header.CHIT_ID = detail.CHIT_ID
       AND IFNULL(header.ISDEL, '0') = '0'
    INNER JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = detail.COMPANY_CD
       AND ext.CHITDETAIL_ID = detail.CHITDETAIL_ID
       AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN tmp_ar_summary_customer_by_id by_id
        ON by_id.CUSTOMER_ID = IFNULL(ext.CUSTOMER_ID, 0)
    LEFT JOIN tmp_ar_summary_customer_by_cd by_cd
        ON by_cd.CUSTOMER_CD = TRIM(IFNULL(ext.CUSTOMER_CD, ''))
    WHERE detail.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(detail.ISDEL, '0') = '0'
      AND IFNULL(detail.AMOUNT, 0) <> 0
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <= v_to_ymd
      AND COALESCE(NULLIF(TRIM(IFNULL(header.CHIT_YMD, '')), ''), NULLIF(TRIM(IFNULL(detail.CHIT_YMD, '')), ''), '') <> ''
      AND (IFNULL(ext.CUSTOMER_ID, 0) > 0 OR TRIM(IFNULL(ext.CUSTOMER_CD, '')) <> '')
      AND (v_customer_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(by_id.CUSTOMER_CD, ''), NULLIF(by_cd.CUSTOMER_CD, ''), NULLIF(TRIM(IFNULL(ext.CUSTOMER_CD, '')), '')), v_customer_cd) > 0)
      AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(detail.FC_TYPE, 'VND')), v_fc_type) > 0);

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_latest_open;
    CREATE TEMPORARY TABLE tmp_ar_summary_latest_open
    (
        ACC_CD VARCHAR(20) NOT NULL,
        CUSTOMER_KEY VARCHAR(50) NOT NULL,
        OPEN_YMD VARCHAR(8) NOT NULL DEFAULT '',
        PRIMARY KEY (ACC_CD, CUSTOMER_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_summary_latest_open (ACC_CD, CUSTOMER_KEY, OPEN_YMD)
    SELECT
        account.ACC_CD,
        CONCAT('ID:', opening.CUSTOMER_ID),
        IFNULL(MAX(opening.OPEN_YMD), '')
    FROM before_states_customer opening
    INNER JOIN tmp_ar_summary_accounts account
        ON account.ACC_CD = opening.ACC_CD
    LEFT JOIN tmp_ar_summary_customer_by_id customer
        ON customer.CUSTOMER_ID = IFNULL(opening.CUSTOMER_ID, 0)
    WHERE opening.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(opening.ISDEL, '0') = '0'
      AND IFNULL(opening.CUSTOMER_ID, 0) > 0
      AND IFNULL(opening.OPEN_YMD, '') <= v_before_from_ymd
      AND (v_customer_cd = '' OR FIND_IN_SET(customer.CUSTOMER_CD, v_customer_cd) > 0)
      AND (v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(opening.FC_TYPE, 'VND')), v_fc_type) > 0)
    GROUP BY account.ACC_CD, opening.CUSTOMER_ID;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_opening;
    CREATE TEMPORARY TABLE tmp_ar_summary_opening
    (
        ACC_CD VARCHAR(20) NOT NULL,
        CUSTOMER_KEY VARCHAR(50) NOT NULL,
        CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        OPEN_YMD VARCHAR(8) NOT NULL DEFAULT '00000000',
        DEBIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        CREDIT_AMOUNT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PRIMARY KEY (ACC_CD, CUSTOMER_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_summary_opening
    (
        ACC_CD,
        CUSTOMER_KEY,
        CUSTOMER_ID,
        CUSTOMER_CD,
        CUSTOMER_NAME,
        OPEN_YMD,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT
    )
    SELECT
        latest.ACC_CD,
        latest.CUSTOMER_KEY,
        opening.CUSTOMER_ID,
        IFNULL(customer.CUSTOMER_CD, ''),
        COALESCE(NULLIF(customer.CUSTOMER_NAME, ''), NULLIF(opening.CUSTOMER_NM, ''), IFNULL(customer.CUSTOMER_CD, '')),
        IFNULL(NULLIF(latest.OPEN_YMD, ''), '00000000'),
        IFNULL(SUM(CASE WHEN v_use_fc = 1 THEN opening.DEBIT_FC ELSE opening.DEBIT END), 0),
        IFNULL(SUM(CASE WHEN v_use_fc = 1 THEN opening.CREDIT_FC ELSE opening.CREDIT END), 0)
    FROM tmp_ar_summary_latest_open latest
    INNER JOIN before_states_customer opening
        ON opening.COMPANY_CD = p_COMPANY_CD
       AND opening.ACC_CD = latest.ACC_CD
       AND CONCAT('ID:', opening.CUSTOMER_ID) = latest.CUSTOMER_KEY
       AND opening.OPEN_YMD = latest.OPEN_YMD
       AND IFNULL(opening.ISDEL, '0') = '0'
    LEFT JOIN tmp_ar_summary_customer_by_id customer
        ON customer.CUSTOMER_ID = IFNULL(opening.CUSTOMER_ID, 0)
    WHERE v_fc_type = '' OR FIND_IN_SET(UPPER(IFNULL(opening.FC_TYPE, 'VND')), v_fc_type) > 0
    GROUP BY latest.ACC_CD, latest.CUSTOMER_KEY, opening.CUSTOMER_ID, customer.CUSTOMER_CD, customer.CUSTOMER_NAME, opening.CUSTOMER_NM, latest.OPEN_YMD;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_subjects;
    CREATE TEMPORARY TABLE tmp_ar_summary_subjects
    (
        CUSTOMER_KEY VARCHAR(50) NOT NULL,
        CUSTOMER_ID BIGINT NOT NULL DEFAULT 0,
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_OWN_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (CUSTOMER_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_summary_subjects (CUSTOMER_KEY, CUSTOMER_ID, CUSTOMER_CD, CUSTOMER_OWN_CD, CUSTOMER_NAME)
    SELECT
        movement.CUSTOMER_KEY,
        MAX(movement.CUSTOMER_ID),
        MAX(movement.CUSTOMER_CD),
        MAX(movement.CUSTOMER_OWN_CD),
        MAX(movement.CUSTOMER_NAME)
    FROM tmp_ar_summary_movements movement
    WHERE movement.CUSTOMER_KEY <> ''
    GROUP BY movement.CUSTOMER_KEY;

    INSERT INTO tmp_ar_summary_subjects (CUSTOMER_KEY, CUSTOMER_ID, CUSTOMER_CD, CUSTOMER_OWN_CD, CUSTOMER_NAME)
    SELECT
        opening.CUSTOMER_KEY,
        opening.CUSTOMER_ID,
        opening.CUSTOMER_CD,
        '',
        opening.CUSTOMER_NAME
    FROM tmp_ar_summary_opening opening
    ON DUPLICATE KEY UPDATE
        CUSTOMER_ID = IF(tmp_ar_summary_subjects.CUSTOMER_ID = 0, VALUES(CUSTOMER_ID), tmp_ar_summary_subjects.CUSTOMER_ID),
        CUSTOMER_CD = IF(tmp_ar_summary_subjects.CUSTOMER_CD = '', VALUES(CUSTOMER_CD), tmp_ar_summary_subjects.CUSTOMER_CD),
        CUSTOMER_NAME = IF(tmp_ar_summary_subjects.CUSTOMER_NAME = '', VALUES(CUSTOMER_NAME), tmp_ar_summary_subjects.CUSTOMER_NAME);

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_keys;
    CREATE TEMPORARY TABLE tmp_ar_summary_keys
    (
        ACC_CD VARCHAR(20) NOT NULL,
        CUSTOMER_KEY VARCHAR(50) NOT NULL,
        PRIMARY KEY (ACC_CD, CUSTOMER_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT IGNORE INTO tmp_ar_summary_keys (ACC_CD, CUSTOMER_KEY)
    SELECT ACC_CD, CUSTOMER_KEY
    FROM tmp_ar_summary_opening;

    INSERT IGNORE INTO tmp_ar_summary_keys (ACC_CD, CUSTOMER_KEY)
    SELECT ACC_CD, CUSTOMER_KEY
    FROM tmp_ar_summary_movements
    WHERE CUSTOMER_KEY <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_balance;
    CREATE TEMPORARY TABLE tmp_ar_summary_balance
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ACCOUNT_SORT INT NOT NULL DEFAULT 0,
        ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_KEY VARCHAR(50) NOT NULL DEFAULT '',
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_OWN_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        BEGIN_NET DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PERIOD_DEBIT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PERIOD_CREDIT DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        END_NET DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        PRIMARY KEY (ROW_NO),
        INDEX idx_tmp_ar_summary_balance_01 (ACCOUNT_SORT, CUSTOMER_CD, CUSTOMER_NAME)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_summary_balance
    (
        ACCOUNT_SORT,
        ACC_CD,
        CUSTOMER_KEY,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        BEGIN_NET,
        PERIOD_DEBIT,
        PERIOD_CREDIT,
        END_NET
    )
    SELECT
        account.ACCOUNT_SORT,
        account.ACC_CD,
        summary_key.CUSTOMER_KEY,
        IFNULL(subject.CUSTOMER_CD, ''),
        IFNULL(subject.CUSTOMER_OWN_CD, ''),
        IFNULL(subject.CUSTOMER_NAME, ''),
        IFNULL(opening.DEBIT_AMOUNT, 0) - IFNULL(opening.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000')
             AND movement.CHIT_YMD < v_from_ymd
            THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
            ELSE 0
        END), 0),
        IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= v_from_ymd
             AND movement.CHIT_YMD <= v_to_ymd
            THEN movement.DEBIT_AMOUNT
            ELSE 0
        END), 0),
        IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= v_from_ymd
             AND movement.CHIT_YMD <= v_to_ymd
            THEN movement.CREDIT_AMOUNT
            ELSE 0
        END), 0),
        IFNULL(opening.DEBIT_AMOUNT, 0) - IFNULL(opening.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
            WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000')
             AND movement.CHIT_YMD <= v_to_ymd
            THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
            ELSE 0
        END), 0)
    FROM tmp_ar_summary_keys summary_key
    INNER JOIN tmp_ar_summary_accounts account
        ON account.ACC_CD = summary_key.ACC_CD
    INNER JOIN tmp_ar_summary_subjects subject
        ON subject.CUSTOMER_KEY = summary_key.CUSTOMER_KEY
    LEFT JOIN tmp_ar_summary_opening opening
        ON opening.ACC_CD = summary_key.ACC_CD
       AND opening.CUSTOMER_KEY = summary_key.CUSTOMER_KEY
    LEFT JOIN tmp_ar_summary_movements movement
        ON movement.ACC_CD = summary_key.ACC_CD
       AND movement.CUSTOMER_KEY = summary_key.CUSTOMER_KEY
    GROUP BY
        account.ACCOUNT_SORT,
        account.ACC_CD,
        summary_key.CUSTOMER_KEY,
        subject.CUSTOMER_CD,
        subject.CUSTOMER_OWN_CD,
        subject.CUSTOMER_NAME,
        opening.OPEN_YMD,
        opening.DEBIT_AMOUNT,
        opening.CREDIT_AMOUNT
    HAVING
        ROUND(
            IFNULL(opening.DEBIT_AMOUNT, 0) - IFNULL(opening.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000')
                 AND movement.CHIT_YMD < v_from_ymd
                THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
                ELSE 0
            END), 0),
            0
        ) <> 0
        OR ROUND(
            IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= v_from_ymd
                 AND movement.CHIT_YMD <= v_to_ymd
                THEN movement.DEBIT_AMOUNT
                ELSE 0
            END), 0),
            0
        ) <> 0
        OR ROUND(
            IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= v_from_ymd
                 AND movement.CHIT_YMD <= v_to_ymd
                THEN movement.CREDIT_AMOUNT
                ELSE 0
            END), 0),
            0
        ) <> 0
        OR ROUND(
            IFNULL(opening.DEBIT_AMOUNT, 0) - IFNULL(opening.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= IFNULL(opening.OPEN_YMD, '00000000')
                 AND movement.CHIT_YMD <= v_to_ymd
                THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
                ELSE 0
            END), 0),
            0
        ) <> 0
    ORDER BY account.ACCOUNT_SORT, subject.CUSTOMER_CD, subject.CUSTOMER_NAME, summary_key.CUSTOMER_KEY;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_report;
    CREATE TEMPORARY TABLE tmp_ar_summary_report
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ROW_KEY VARCHAR(100) NOT NULL DEFAULT '',
        ROW_SORT INT NOT NULL DEFAULT 0,
        ROW_TYPE VARCHAR(30) NOT NULL DEFAULT '',
        ROW_LEVEL INT NOT NULL DEFAULT 0,
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        REPORT_GROUP_KEY VARCHAR(50) NOT NULL DEFAULT 'AR_SUMMARY',
        REPORT_PERIOD_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        ACCOUNT_FILTER_TEXT VARCHAR(1000) NOT NULL DEFAULT '',
        CURRENCY_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        AMOUNT_UNIT_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        CUSTOMER_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_OWN_CD VARCHAR(20) NOT NULL DEFAULT '',
        CUSTOMER_NAME VARCHAR(255) NOT NULL DEFAULT '',
        ACCOUNT_CD VARCHAR(20) NOT NULL DEFAULT '',
        BEGIN_DEBIT DECIMAL(18,6) NULL,
        BEGIN_CREDIT DECIMAL(18,6) NULL,
        PERIOD_DEBIT DECIMAL(18,6) NULL,
        PERIOD_CREDIT DECIMAL(18,6) NULL,
        END_DEBIT DECIMAL(18,6) NULL,
        END_CREDIT DECIMAL(18,6) NULL,
        PRIMARY KEY (ROW_NO)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_ar_summary_report
    (
        ROW_KEY,
        ROW_SORT,
        ROW_TYPE,
        ROW_LEVEL,
        COMPANY_CD,
        REPORT_PERIOD_TEXT,
        ACCOUNT_FILTER_TEXT,
        CURRENCY_TEXT,
        AMOUNT_UNIT_TEXT,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        ACCOUNT_CD,
        BEGIN_DEBIT,
        BEGIN_CREDIT,
        PERIOD_DEBIT,
        PERIOD_CREDIT,
        END_DEBIT,
        END_CREDIT
    )
    SELECT
        CONCAT('AR_SUMMARY_', balance.ACC_CD, '_', balance.CUSTOMER_KEY),
        balance.ROW_NO,
        'DETAIL',
        0,
        p_COMPANY_CD,
        v_report_period_text,
        v_account_filter_text,
        v_currency_text,
        v_amount_unit_text,
        balance.CUSTOMER_CD,
        balance.CUSTOMER_OWN_CD,
        balance.CUSTOMER_NAME,
        balance.ACC_CD,
        NULLIF(ROUND(GREATEST(balance.BEGIN_NET, 0), 0), 0),
        NULLIF(ROUND(GREATEST(-balance.BEGIN_NET, 0), 0), 0),
        NULLIF(ROUND(balance.PERIOD_DEBIT, 0), 0),
        NULLIF(ROUND(balance.PERIOD_CREDIT, 0), 0),
        NULLIF(ROUND(GREATEST(balance.END_NET, 0), 0), 0),
        NULLIF(ROUND(GREATEST(-balance.END_NET, 0), 0), 0)
    FROM tmp_ar_summary_balance balance
    ORDER BY balance.ACCOUNT_SORT, balance.CUSTOMER_CD, balance.CUSTOMER_NAME, balance.CUSTOMER_KEY;

    INSERT INTO tmp_ar_summary_report
    (
        ROW_KEY,
        ROW_SORT,
        ROW_TYPE,
        ROW_LEVEL,
        COMPANY_CD,
        REPORT_PERIOD_TEXT,
        ACCOUNT_FILTER_TEXT,
        CURRENCY_TEXT,
        AMOUNT_UNIT_TEXT,
        CUSTOMER_NAME,
        BEGIN_DEBIT,
        BEGIN_CREDIT,
        PERIOD_DEBIT,
        PERIOD_CREDIT,
        END_DEBIT,
        END_CREDIT
    )
    SELECT
        'AR_SUMMARY_TOTAL',
        999999999,
        'TOTAL',
        0,
        p_COMPANY_CD,
        v_report_period_text,
        v_account_filter_text,
        v_currency_text,
        v_amount_unit_text,
        'Tổng cộng',
        NULLIF(ROUND(SUM(GREATEST(BEGIN_NET, 0)), 0), 0),
        NULLIF(ROUND(SUM(GREATEST(-BEGIN_NET, 0)), 0), 0),
        NULLIF(ROUND(SUM(PERIOD_DEBIT), 0), 0),
        NULLIF(ROUND(SUM(PERIOD_CREDIT), 0), 0),
        NULLIF(ROUND(SUM(GREATEST(END_NET, 0)), 0), 0),
        NULLIF(ROUND(SUM(GREATEST(-END_NET, 0)), 0), 0)
    FROM tmp_ar_summary_balance
    HAVING COUNT(*) > 0;

    SELECT
        ROW_KEY,
        ROW_SORT,
        ROW_TYPE,
        ROW_LEVEL,
        COMPANY_CD,
        REPORT_GROUP_KEY,
        REPORT_PERIOD_TEXT,
        ACCOUNT_FILTER_TEXT,
        CURRENCY_TEXT,
        AMOUNT_UNIT_TEXT,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        ACCOUNT_CD,
        BEGIN_DEBIT,
        BEGIN_CREDIT,
        PERIOD_DEBIT,
        PERIOD_CREDIT,
        END_DEBIT,
        END_CREDIT
    FROM tmp_ar_summary_report
    ORDER BY ROW_SORT, ROW_NO;

    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_report;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_balance;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_keys;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_subjects;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_opening;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_latest_open;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_movements;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_accounts;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_customer_by_cd;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_customer_latest_id;
    DROP TEMPORARY TABLE IF EXISTS tmp_ar_summary_customer_by_id;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_balance_sheet_b01dn
DROP PROCEDURE IF EXISTS `rpt_balance_sheet_b01dn`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_balance_sheet_b01dn`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_REPORT_VERSION VARCHAR(20),
    IN p_UNIT_DIVISOR DECIMAL(18,6),
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_from_date DATE;
    DECLARE v_begin_date DATE;
    DECLARE v_to_date DATE;
    DECLARE v_begin_ymd CHAR(8);
    DECLARE v_to_ymd CHAR(8);
    DECLARE v_report_version VARCHAR(20);
    DECLARE v_template_company_cd VARCHAR(20);
    DECLARE v_unit_divisor DECIMAL(18,6);
    DECLARE v_iteration INT DEFAULT 0;
    DECLARE v_changed_rows INT DEFAULT 0;
    DECLARE v_language VARCHAR(20);

    /* Company-level baselines (same idea as rpt_trial_balance_s06dn). */
    DECLARE v_end_close_ymd CHAR(8) DEFAULT NULL;
    DECLARE v_end_open_ymd CHAR(8) DEFAULT NULL;
    DECLARE v_end_move_from_ymd CHAR(8) DEFAULT '00000000';
    DECLARE v_begin_close_ymd CHAR(8) DEFAULT NULL;
    DECLARE v_begin_open_ymd CHAR(8) DEFAULT NULL;
    DECLARE v_begin_move_from_ymd CHAR(8) DEFAULT '00000000';
    DECLARE v_scan_from_ymd CHAR(8) DEFAULT '00000000';

    IF p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'toDate is required';
    END IF;

    SET v_to_date = p_TO_DATE;
    SET v_from_date = IFNULL(p_FROM_DATE, STR_TO_DATE(CONCAT(YEAR(p_TO_DATE), '0101'), '%Y%m%d'));
    SET v_begin_date = DATE_SUB(v_from_date, INTERVAL 1 DAY);
    SET v_to_ymd = DATE_FORMAT(v_to_date, '%Y%m%d');
    SET v_begin_ymd = DATE_FORMAT(v_begin_date, '%Y%m%d');
    SET v_report_version = IFNULL(NULLIF(TRIM(IFNULL(p_REPORT_VERSION, '')), ''), '2025');
    SET v_unit_divisor = CASE WHEN IFNULL(p_UNIT_DIVISOR, 0) = 0 THEN 1 ELSE p_UNIT_DIVISOR END;
    SET v_language = UPPER(IFNULL(NULLIF(TRIM(p_LANGUAGE), ''), 'VIET'));

    SELECT COALESCE(
        (
            SELECT template.COMPANY_CD
            FROM report_B01DN template
            WHERE template.REPORT_CODE = 'B01_DN'
              AND template.REPORT_VERSION = v_report_version
              AND template.COMPANY_CD IN (p_COMPANY_CD, '')
              AND IFNULL(template.ISDEL, '0') = '0'
            ORDER BY CASE
                WHEN template.COMPANY_CD = p_COMPANY_CD THEN 0
                ELSE 1
            END
            LIMIT 1
        ),
        ''
    )
    INTO v_template_company_cd;

    /*
        END baseline as of v_to_ymd:
        1) latest closingmonth_detail.CLOSE_YMD <= to-date
        2) else latest before_states.OPEN_YMD <= to-date
        CLOSE is end-of-day => movements start next day.
        OPEN is opening => movements include OPEN_YMD (same as previous B01).
    */
    SELECT MAX(CLOSE_YMD)
      INTO v_end_close_ymd
    FROM closingmonth_detail
    WHERE COMPANY_CD = p_COMPANY_CD
      AND ISDEL = '0'
      AND CLOSE_YMD <= v_to_ymd;

    IF v_end_close_ymd IS NOT NULL THEN
        SET v_end_move_from_ymd = DATE_FORMAT(
            DATE_ADD(STR_TO_DATE(v_end_close_ymd, '%Y%m%d'), INTERVAL 1 DAY),
            '%Y%m%d'
        );
    ELSE
        SELECT MAX(OPEN_YMD)
          INTO v_end_open_ymd
        FROM before_states
        WHERE COMPANY_CD = p_COMPANY_CD
          AND ISDEL = '0'
          AND OPEN_YMD <= v_to_ymd;

        IF v_end_open_ymd IS NOT NULL THEN
            SET v_end_move_from_ymd = v_end_open_ymd;
        ELSE
            SET v_end_move_from_ymd = '00000000';
        END IF;
    END IF;

    /*
        BEGIN baseline as of day before from-date.
    */
    SELECT MAX(CLOSE_YMD)
      INTO v_begin_close_ymd
    FROM closingmonth_detail
    WHERE COMPANY_CD = p_COMPANY_CD
      AND ISDEL = '0'
      AND CLOSE_YMD <= v_begin_ymd;

    IF v_begin_close_ymd IS NOT NULL THEN
        SET v_begin_move_from_ymd = DATE_FORMAT(
            DATE_ADD(STR_TO_DATE(v_begin_close_ymd, '%Y%m%d'), INTERVAL 1 DAY),
            '%Y%m%d'
        );
    ELSE
        SELECT MAX(OPEN_YMD)
          INTO v_begin_open_ymd
        FROM before_states
        WHERE COMPANY_CD = p_COMPANY_CD
          AND ISDEL = '0'
          AND OPEN_YMD <= v_begin_ymd;

        IF v_begin_open_ymd IS NOT NULL THEN
            SET v_begin_move_from_ymd = v_begin_open_ymd;
        ELSE
            SET v_begin_move_from_ymd = '00000000';
        END IF;
    END IF;

    SET v_scan_from_ymd = LEAST(v_begin_move_from_ymd, v_end_move_from_ymd);

    DROP TEMPORARY TABLE IF EXISTS tmp_b01_base_end;
    CREATE TEMPORARY TABLE tmp_b01_base_end
    (
        ACC_CD VARCHAR(20) NOT NULL,
        DEBIT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        CREDIT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (ACC_CD)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    DROP TEMPORARY TABLE IF EXISTS tmp_b01_base_begin;
    CREATE TEMPORARY TABLE tmp_b01_base_begin
    (
        ACC_CD VARCHAR(20) NOT NULL,
        DEBIT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        CREDIT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (ACC_CD)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    IF v_end_close_ymd IS NOT NULL THEN
        INSERT INTO tmp_b01_base_end (ACC_CD, DEBIT, CREDIT)
        SELECT ACC_CD, SUM(DEBIT), SUM(CREDIT)
        FROM closingmonth_detail
        WHERE COMPANY_CD = p_COMPANY_CD
          AND ISDEL = '0'
          AND CLOSE_YMD = v_end_close_ymd
          AND IFNULL(ACC_CD, '') <> ''
        GROUP BY ACC_CD;
    ELSEIF v_end_open_ymd IS NOT NULL THEN
        INSERT INTO tmp_b01_base_end (ACC_CD, DEBIT, CREDIT)
        SELECT ACC_CD, SUM(DEBIT), SUM(CREDIT)
        FROM before_states
        WHERE COMPANY_CD = p_COMPANY_CD
          AND ISDEL = '0'
          AND OPEN_YMD = v_end_open_ymd
          AND IFNULL(ACC_CD, '') <> ''
        GROUP BY ACC_CD;
    END IF;

    IF v_begin_close_ymd IS NOT NULL THEN
        INSERT INTO tmp_b01_base_begin (ACC_CD, DEBIT, CREDIT)
        SELECT ACC_CD, SUM(DEBIT), SUM(CREDIT)
        FROM closingmonth_detail
        WHERE COMPANY_CD = p_COMPANY_CD
          AND ISDEL = '0'
          AND CLOSE_YMD = v_begin_close_ymd
          AND IFNULL(ACC_CD, '') <> ''
        GROUP BY ACC_CD;
    ELSEIF v_begin_open_ymd IS NOT NULL THEN
        INSERT INTO tmp_b01_base_begin (ACC_CD, DEBIT, CREDIT)
        SELECT ACC_CD, SUM(DEBIT), SUM(CREDIT)
        FROM before_states
        WHERE COMPANY_CD = p_COMPANY_CD
          AND ISDEL = '0'
          AND OPEN_YMD = v_begin_open_ymd
          AND IFNULL(ACC_CD, '') <> ''
        GROUP BY ACC_CD;
    END IF;

    /*
        Movements only in [scan_from, to_ymd] via IDX_CHITINFO_03.
        No per-row join to opening thresholds (that made the previous rewrite slower).
    */
    DROP TEMPORARY TABLE IF EXISTS tmp_b01_account_move_sums;
    CREATE TEMPORARY TABLE tmp_b01_account_move_sums
    (
        ACC_CD VARCHAR(20) NOT NULL,
        END_NET DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        BEGIN_NET DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (ACC_CD)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    IF v_scan_from_ymd <= v_to_ymd THEN
        /*
            Dá»¯ liá»‡u thá»±c táº¿ Ä‘Ã£ test ráº¥t nhanh.
            Giá»¯ aggregate trá»±c tiáº¿p Ä‘á»ƒ trÃ¡nh overhead materialize/CROSS JOIN.
        */
        INSERT INTO tmp_b01_account_move_sums (ACC_CD, END_NET, BEGIN_NET)
        SELECT
            TRIM(d.DEBIT) AS ACC_CD,
            SUM(
                CASE
                    WHEN h.CHIT_YMD >= v_end_move_from_ymd
                     AND h.CHIT_YMD <= v_to_ymd
                    THEN IFNULL(d.AMOUNT, 0)
                    ELSE 0
                END
            ) AS END_NET,
            SUM(
                CASE
                    WHEN h.CHIT_YMD >= v_begin_move_from_ymd
                     AND h.CHIT_YMD <= v_begin_ymd
                    THEN IFNULL(d.AMOUNT, 0)
                    ELSE 0
                END
            ) AS BEGIN_NET
        FROM chitinfo h
        INNER JOIN chitdetailinfo d
            ON d.COMPANY_CD = h.COMPANY_CD
           AND d.CHIT_ID = h.CHIT_ID
           AND d.ISDEL = '0'
        WHERE h.COMPANY_CD = p_COMPANY_CD
          AND h.ISDEL = '0'
          AND h.CHIT_YMD >= v_scan_from_ymd
          AND h.CHIT_YMD <= v_to_ymd
          AND d.DEBIT IS NOT NULL
          AND d.DEBIT <> ''
        GROUP BY TRIM(d.DEBIT);

        INSERT INTO tmp_b01_account_move_sums (ACC_CD, END_NET, BEGIN_NET)
        SELECT
            TRIM(d.CREDIT) AS ACC_CD,
            SUM(
                CASE
                    WHEN h.CHIT_YMD >= v_end_move_from_ymd
                     AND h.CHIT_YMD <= v_to_ymd
                    THEN -IFNULL(d.AMOUNT, 0)
                    ELSE 0
                END
            ) AS END_NET,
            SUM(
                CASE
                    WHEN h.CHIT_YMD >= v_begin_move_from_ymd
                     AND h.CHIT_YMD <= v_begin_ymd
                    THEN -IFNULL(d.AMOUNT, 0)
                    ELSE 0
                END
            ) AS BEGIN_NET
        FROM chitinfo h
        INNER JOIN chitdetailinfo d
            ON d.COMPANY_CD = h.COMPANY_CD
           AND d.CHIT_ID = h.CHIT_ID
           AND d.ISDEL = '0'
        WHERE h.COMPANY_CD = p_COMPANY_CD
          AND h.ISDEL = '0'
          AND h.CHIT_YMD >= v_scan_from_ymd
          AND h.CHIT_YMD <= v_to_ymd
          AND d.CREDIT IS NOT NULL
          AND d.CREDIT <> ''
        GROUP BY TRIM(d.CREDIT)
        ON DUPLICATE KEY UPDATE
            END_NET = END_NET + VALUES(END_NET),
            BEGIN_NET = BEGIN_NET + VALUES(BEGIN_NET);
    END IF;

    DROP TEMPORARY TABLE IF EXISTS tmp_b01_account_seed;
    CREATE TEMPORARY TABLE tmp_b01_account_seed
    (
        ACC_CD VARCHAR(20) NOT NULL,
        PRIMARY KEY (ACC_CD)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT IGNORE INTO tmp_b01_account_seed (ACC_CD)
    SELECT ACC_CD FROM tmp_b01_base_end WHERE IFNULL(ACC_CD, '') <> '';

    INSERT IGNORE INTO tmp_b01_account_seed (ACC_CD)
    SELECT ACC_CD FROM tmp_b01_base_begin WHERE IFNULL(ACC_CD, '') <> '';

    INSERT IGNORE INTO tmp_b01_account_seed (ACC_CD)
    SELECT ACC_CD FROM tmp_b01_account_move_sums WHERE IFNULL(ACC_CD, '') <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_b01_account_balance;
    CREATE TEMPORARY TABLE tmp_b01_account_balance
    (
        ACC_CD VARCHAR(20) NOT NULL,
        END_NET DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        BEGIN_NET DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (ACC_CD)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b01_account_balance (ACC_CD, END_NET, BEGIN_NET)
    SELECT
        seed.ACC_CD,
        CAST(
            IFNULL(base_end.DEBIT, 0) - IFNULL(base_end.CREDIT, 0)
            + IFNULL(move.END_NET, 0) AS DECIMAL(18,2)
        ),
        CAST(
            IFNULL(base_begin.DEBIT, 0) - IFNULL(base_begin.CREDIT, 0)
            + IFNULL(move.BEGIN_NET, 0) AS DECIMAL(18,2)
        )
    FROM tmp_b01_account_seed seed
    LEFT JOIN tmp_b01_base_end base_end
        ON base_end.ACC_CD = seed.ACC_CD
    LEFT JOIN tmp_b01_base_begin base_begin
        ON base_begin.ACC_CD = seed.ACC_CD
    LEFT JOIN tmp_b01_account_move_sums move
        ON move.ACC_CD = seed.ACC_CD;

    DROP TEMPORARY TABLE IF EXISTS tmp_b01_rule;
    CREATE TEMPORARY TABLE tmp_b01_rule
    (
        ITEM_CODE VARCHAR(20) NOT NULL,
        ACC_PREFIX VARCHAR(20) NOT NULL,
        CALC_METHOD VARCHAR(30) NOT NULL,
        INDEX idx_tmp_b01_rule_01 (ITEM_CODE, ACC_PREFIX)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b01_rule (ITEM_CODE, ACC_PREFIX, CALC_METHOD)
    SELECT
        template.ITEM_CODE,
        TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(IFNULL(template.ACCOUNT_RULE, ''), ',', numbers.n), ',', -1)),
        template.CALC_METHOD
    FROM report_B01DN template
    INNER JOIN (
        SELECT 1 AS n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5
        UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10
    ) numbers
        ON numbers.n <= 1 + LENGTH(IFNULL(template.ACCOUNT_RULE, '')) - LENGTH(REPLACE(IFNULL(template.ACCOUNT_RULE, ''), ',', ''))
    WHERE template.COMPANY_CD = v_template_company_cd
      AND template.REPORT_CODE = 'B01_DN'
      AND template.REPORT_VERSION = v_report_version
      AND template.SECTION_TYPE = 'DETAIL'
      AND IFNULL(template.DATA_SOURCE_TYPE, '') = 'ACCOUNT_RULE'
      AND IFNULL(template.ACCOUNT_RULE, '') <> ''
      AND TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(IFNULL(template.ACCOUNT_RULE, ''), ',', numbers.n), ',', -1)) <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_b01_report;
    CREATE TEMPORARY TABLE tmp_b01_report
    (
        ROW_KEY VARCHAR(80) NOT NULL DEFAULT '',
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        ROW_TYPE VARCHAR(30) NOT NULL DEFAULT '',
        SORT_ORDER INT NOT NULL DEFAULT 0,
        ITEM_CODE VARCHAR(50) NULL,
        ITEM_NAME VARCHAR(1000) NULL,
        CAPTION VARCHAR(1000) NULL,
        LABEL_TEXT VARCHAR(200) NULL,
        NOTE VARCHAR(100) NOT NULL DEFAULT '',
        END_YEAR DECIMAL(18,2) NULL,
        BEGIN_YEAR DECIMAL(18,2) NULL,
        LEVEL_NO INT NOT NULL DEFAULT 0,
        FONT_BOLD CHAR(1) NOT NULL DEFAULT '0',
        FONT_ITALIC CHAR(1) NOT NULL DEFAULT '0',
        DATA_SOURCE_TYPE VARCHAR(50) NULL,
        FORMULA_EXPR VARCHAR(1000) NULL,
        REPORT_YEAR_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        REPORT_DATE_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        AMOUNT_UNIT_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ROW_KEY),
        INDEX idx_tmp_b01_report_01 (ITEM_CODE),
        INDEX idx_tmp_b01_report_02 (SORT_ORDER)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b01_report
    (
        ROW_KEY,
        COMPANY_CD,
        ROW_TYPE,
        SORT_ORDER,
        ITEM_CODE,
        ITEM_NAME,
        CAPTION,
        LABEL_TEXT,
        NOTE,
        LEVEL_NO,
        FONT_BOLD,
        FONT_ITALIC,
        DATA_SOURCE_TYPE,
        FORMULA_EXPR,
        REPORT_YEAR_TEXT,
        REPORT_DATE_TEXT,
        AMOUNT_UNIT_TEXT
    )
    SELECT
        template.ITEM_KEY,
        p_COMPANY_CD,
        template.ELEMENT_TYPE,
        template.SORT_ORDER,
        template.ITEM_CODE,
        -- ITEM_NAME: backward-compat display = indented CAPTION; LABEL_TEXT for future i18n via t_message_info.
        CONCAT(REPEAT('  ', GREATEST(IFNULL(template.LEVEL_NO, 1) - 1, 0)), IFNULL(template.CAPTION, '')),
        template.CAPTION,
        template.LABEL_TEXT,
        '',
        IFNULL(template.LEVEL_NO, 0),
        IFNULL(template.FONT_BOLD, '0'),
        IFNULL(template.FONT_ITALIC, '0'),
        IFNULL(template.DATA_SOURCE_TYPE, ''),
        template.FORMULA_EXPR,
        CASE v_language
            WHEN 'ENG' THEN CONCAT('Year ', YEAR(v_to_date))
            WHEN 'KOR' THEN CONCAT(YEAR(v_to_date), 'ë…„')
            WHEN 'CHN' THEN CONCAT(YEAR(v_to_date), 'å¹´')
            ELSE CONCAT('NÄƒm ', YEAR(v_to_date))
        END,
        CASE v_language
            WHEN 'ENG' THEN CONCAT('As at ', DATE_FORMAT(v_to_date, '%d/%m/%Y'))
            WHEN 'KOR' THEN CONCAT('ê¸°ì¤€ì¼: ', DATE_FORMAT(v_to_date, '%d/%m/%Y'))
            WHEN 'CHN' THEN CONCAT('æˆªè‡³æ—¥æœŸï¼š', DATE_FORMAT(v_to_date, '%d/%m/%Y'))
            ELSE CONCAT('Táº¡i ngÃ y ', DATE_FORMAT(v_to_date, '%d/%m/%Y'))
        END,
        CASE v_language
            WHEN 'ENG' THEN
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'Unit: million VND'
                    WHEN v_unit_divisor = 1000 THEN 'Unit: thousand VND'
                    ELSE 'Unit: VND'
                END
            WHEN 'KOR' THEN
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'ë‹¨ìœ„: ë°±ë§Œ VND'
                    WHEN v_unit_divisor = 1000 THEN 'ë‹¨ìœ„: ì²œ VND'
                    ELSE 'ë‹¨ìœ„: VND'
                END
            WHEN 'CHN' THEN
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'å•ä½ï¼šç™¾ä¸‡è¶Šå—ç›¾'
                    WHEN v_unit_divisor = 1000 THEN 'å•ä½ï¼šåƒè¶Šå—ç›¾'
                    ELSE 'å•ä½ï¼šè¶Šå—ç›¾'
                END
            ELSE
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'ÄÆ¡n vá»‹ tÃ­nh: triá»‡u Ä‘á»“ng'
                    WHEN v_unit_divisor = 1000 THEN 'ÄÆ¡n vá»‹ tÃ­nh: nghÃ¬n Ä‘á»“ng'
                    ELSE 'ÄÆ¡n vá»‹ tÃ­nh: Ä‘á»“ng'
                END
        END
    FROM report_B01DN template
    WHERE template.COMPANY_CD = v_template_company_cd
      AND template.REPORT_CODE = 'B01_DN'
      AND template.REPORT_VERSION = v_report_version
      AND template.SECTION_TYPE = 'DETAIL'
      AND IFNULL(template.ISDEL, '0') = '0'
      AND IFNULL(template.IS_VISIBLE, '1') = '1'
    ORDER BY template.SORT_ORDER;

    UPDATE tmp_b01_report report
    LEFT JOIN
    (
        SELECT
            rule.ITEM_CODE,
            SUM(CASE rule.CALC_METHOD
                WHEN 'CREDIT_MINUS_DEBIT' THEN -balance.END_NET
                WHEN 'DEBIT_ONLY' THEN GREATEST(balance.END_NET, 0)
                WHEN 'CREDIT_ONLY' THEN GREATEST(-balance.END_NET, 0)
                ELSE balance.END_NET
            END) AS END_YEAR,
            SUM(CASE rule.CALC_METHOD
                WHEN 'CREDIT_MINUS_DEBIT' THEN -balance.BEGIN_NET
                WHEN 'DEBIT_ONLY' THEN GREATEST(balance.BEGIN_NET, 0)
                WHEN 'CREDIT_ONLY' THEN GREATEST(-balance.BEGIN_NET, 0)
                ELSE balance.BEGIN_NET
            END) AS BEGIN_YEAR
        FROM tmp_b01_rule rule
        INNER JOIN tmp_b01_account_balance balance
            ON balance.ACC_CD LIKE CONCAT(rule.ACC_PREFIX, '%')
        GROUP BY rule.ITEM_CODE
    ) calc
        ON UPPER(calc.ITEM_CODE) = UPPER(report.ITEM_CODE)
    SET
        report.END_YEAR = NULLIF(ROUND(IFNULL(calc.END_YEAR, 0) / v_unit_divisor, 0), 0),
        report.BEGIN_YEAR = NULLIF(ROUND(IFNULL(calc.BEGIN_YEAR, 0) / v_unit_divisor, 0), 0)
    WHERE UPPER(IFNULL(report.DATA_SOURCE_TYPE, '')) = 'ACCOUNT_RULE';

    /*
        Tá»‘i Æ°u FORMULA cho MySQL 5.6:
        - KhÃ´ng DROP/CREATE temporary table trong WHILE.
        - tmp_b01_formula_source vÃ  tmp_b01_formula_calc chá»‰ táº¡o 1 láº§n.
        - Má»—i vÃ²ng chá»‰ TRUNCATE + INSERT + UPDATE trÃªn khoáº£ng 126 dÃ²ng.
        - Dá»«ng ngay khi káº¿t quáº£ khÃ´ng cÃ²n thay Ä‘á»•i.
    */
    DROP TEMPORARY TABLE IF EXISTS tmp_b01_formula_source;
    CREATE TEMPORARY TABLE tmp_b01_formula_source
    (
        ITEM_CODE VARCHAR(50) NULL,
        FORMULA_EXPR VARCHAR(1000) NULL,
        INDEX idx_tmp_b01_formula_source_item (ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b01_formula_source (ITEM_CODE, FORMULA_EXPR)
    SELECT ITEM_CODE, FORMULA_EXPR
    FROM tmp_b01_report
    WHERE UPPER(IFNULL(DATA_SOURCE_TYPE, '')) = 'FORMULA';

    DROP TEMPORARY TABLE IF EXISTS tmp_b01_formula_calc;
    CREATE TEMPORARY TABLE tmp_b01_formula_calc
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        END_YEAR DECIMAL(18,2) NULL,
        BEGIN_YEAR DECIMAL(18,2) NULL,
        PRIMARY KEY (ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    SET v_iteration = 0;

    formula_loop: WHILE v_iteration < 8 DO
        TRUNCATE TABLE tmp_b01_formula_calc;

        INSERT INTO tmp_b01_formula_calc (ITEM_CODE, END_YEAR, BEGIN_YEAR)
        SELECT
            formula.ITEM_CODE,
            SUM(IFNULL(child.END_YEAR, 0)) AS END_YEAR,
            SUM(IFNULL(child.BEGIN_YEAR, 0)) AS BEGIN_YEAR
        FROM tmp_b01_formula_source formula
        INNER JOIN tmp_b01_report child
            ON FIND_IN_SET(
                UPPER(IFNULL(child.ITEM_CODE, '')),
                REPLACE(
                    REPLACE(
                        REPLACE(
                            UPPER(SUBSTRING_INDEX(IFNULL(formula.FORMULA_EXPR, ''), '=', -1)),
                            ' ',
                            ''
                        ),
                        '+',
                        ','
                    ),
                    ';',
                    ','
                )
            ) > 0
        GROUP BY formula.ITEM_CODE;

        UPDATE tmp_b01_report report
        INNER JOIN tmp_b01_formula_calc calc
            ON UPPER(calc.ITEM_CODE) = UPPER(report.ITEM_CODE)
        SET
            report.END_YEAR = NULLIF(calc.END_YEAR, 0),
            report.BEGIN_YEAR = NULLIF(calc.BEGIN_YEAR, 0)
        WHERE UPPER(IFNULL(report.DATA_SOURCE_TYPE, '')) = 'FORMULA';

        SET v_changed_rows = ROW_COUNT();
        SET v_iteration = v_iteration + 1;

        IF v_changed_rows = 0 THEN
            LEAVE formula_loop;
        END IF;
    END WHILE formula_loop;

    SELECT
        ROW_KEY,
        COMPANY_CD,
        ROW_TYPE,
        ITEM_NAME,
        CAPTION,
        LABEL_TEXT,
        ITEM_CODE,
        NOTE,
        END_YEAR,
        BEGIN_YEAR,
        LEVEL_NO,
        FONT_BOLD,
        FONT_ITALIC,
        REPORT_YEAR_TEXT,
        REPORT_DATE_TEXT,
        AMOUNT_UNIT_TEXT
    FROM tmp_b01_report
    ORDER BY SORT_ORDER;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_bank_deposit_book
DROP PROCEDURE IF EXISTS `rpt_bank_deposit_book`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_bank_deposit_book`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_MODULE_CD VARCHAR(10),
    IN p_BANK_CD VARCHAR(50),
    IN p_FC_TYPE VARCHAR(10),
    
    IN p_ACCOUNT_CD VARCHAR(50),
    IN p_LANGUAGE VARCHAR(10)
)
BEGIN
    DECLARE v_bank_cd VARCHAR(50) DEFAULT '';
    DECLARE v_account_cd VARCHAR(50) DEFAULT '';
    DECLARE v_fc_type VARCHAR(10) DEFAULT '';
    DECLARE v_opening_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_opening_fc_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_total_receipt_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_total_payment_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_total_receipt_fc_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_total_payment_fc_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_closing_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_closing_fc_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_FROM_DATE VARCHAR (10) default '';
    DECLARE v_TO_DATE VARCHAR (10) default '';
    DECLARE v_MAX_CLOSE_YMD VARCHAR (10) default '';
    
    IF( p_ACCOUNT_CD IS NULL OR p_ACCOUNT_CD = '') THEN
    	SET p_ACCOUNT_CD = '112';
    END IF;

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;
	 
	 SET v_FROM_DATE 	= DATE_FORMAT(p_FROM_DATE, '%Y%m%d') ;
	 SET v_TO_DATE 	= DATE_FORMAT(p_TO_DATE, '%Y%m%d') ;
		 
    SET v_bank_cd = TRIM(IFNULL(p_BANK_CD, ''));
    SET v_fc_type = UPPER(TRIM(IFNULL(p_FC_TYPE, '')));
    
    SET v_account_cd = TRIM(IFNULL(p_ACCOUNT_CD, ''));

	
		-- ---------------------------------------------------------------------------------------	
	    -- 3. Tạo bảng tạm CHỈ chứa THÔNG TIN CHỨNG TỪ và thêm INDEX để tính toán nhanh hơn
		-- ---------------------------------------------------------------------------------------
    DROP TEMPORARY TABLE IF EXISTS tmp_bank_deposit_book_source;
    CREATE TEMPORARY TABLE tmp_bank_deposit_book_source AS
    SELECT
        'AR' AS MODULE_CD, -- BÁN HÀNG
        h.COMPANY_CD,
        h.CHIT_ID,
        d.CHITDETAIL_ID,
        h.CHIT_CD,
        h.CHIT_NO,
        h.CHIT_YMD,
        h.CHIT_TYPE,
        d.CHITDETAIL_CD,
        d.DEBIT,
        d.CREDIT,
        IFNULL(d.AMOUNT, 0) AS AMOUNT,
        IFNULL(d.FC_AMOUNT, 0) AS FC_AMOUNT,
        IFNULL(d.FC_TYPE, '') AS FC_TYPE,
        IFNULL(d.FC_RATE, 0) AS FC_RATE,
        d.FC_DATETIME,
        COALESCE(bank.BANK_CD, ext.BANK_CD) AS BANK_CD,
        ext.BANK_OWN_CD,
        COALESCE(customer.CUSTOMER_CD, ext.CUSTOMER_CD) AS CUSTOMER_CD,
        ext.CUSTOMER_ID,
        ext.ISPAY,
        ext.ISCOLLECT,
        CASE
            WHEN IFNULL(d.DEBIT, '') LIKE concat(p_ACCOUNT_CD, '%') THEN 'RECEIPT'
            WHEN IFNULL(d.CREDIT, '') LIKE concat(p_ACCOUNT_CD, '%') THEN 'PAYMENT'
            ELSE ''
        END AS BANK_FLOW_TYPE,
        CASE WHEN IFNULL(d.DEBIT, '') LIKE concat(p_ACCOUNT_CD, '%') THEN IFNULL(d.AMOUNT, 0) ELSE 0 END AS RECEIPT_AMOUNT,
        CASE WHEN IFNULL(d.CREDIT, '') LIKE concat(p_ACCOUNT_CD, '%') THEN IFNULL(d.AMOUNT, 0) ELSE 0 END AS PAYMENT_AMOUNT,
        CASE WHEN IFNULL(d.DEBIT, '') LIKE concat(p_ACCOUNT_CD, '%') THEN IFNULL(d.FC_AMOUNT, 0) ELSE 0 END AS RECEIPT_FC_AMOUNT,
        CASE WHEN IFNULL(d.CREDIT, '') LIKE concat(p_ACCOUNT_CD, '%') THEN IFNULL(d.FC_AMOUNT, 0) ELSE 0 END AS PAYMENT_FC_AMOUNT
        
--		  header_desc.DESCRIPTION AS HEADER_DESCRIPTION,
        
--		  detail_desc.DESCRIPTION AS DETAIL_DESCRIPTION,
        
--        COALESCE(NULLIF(detail_desc.DESCRIPTION, ''), NULLIF(header_desc.DESCRIPTION, ''), '') AS DESCRIPTION
    FROM chitinfo h
    INNER JOIN chitdetailinfo d ON d.COMPANY_CD = h.COMPANY_CD AND d.CHIT_ID = h.CHIT_ID 
	 LEFT JOIN chitdetailinfo_ext ext ON ext.COMPANY_CD = d.COMPANY_CD AND ext.CHITDETAIL_ID = d.CHITDETAIL_ID AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN customer_info customer ON customer.COMPANY_CD = d.COMPANY_CD AND customer.CUSTOMER_ID = ext.CUSTOMER_ID AND IFNULL(customer.ISDEL, '0') = '0'
    LEFT JOIN bank_info bank ON bank.COMPANY_CD = d.COMPANY_CD AND bank.BANK_ID = ext.BANK_ID AND IFNULL(bank.ISDEL, '0') = '0'
--    LEFT JOIN chitdescriptioninfo header_desc        ON header_desc.COMPANY_CD = h.COMPANY_CD       AND header_desc.CHIT_ID = h.CHIT_ID       AND header_desc.LANG_TYPE = 'VIET'       AND IFNULL(header_desc.ISDEL, '0') = '0'
--    LEFT JOIN chitdetaildescriptioninfo detail_desc        ON detail_desc.COMPANY_CD = d.COMPANY_CD       AND detail_desc.CHITDETAIL_ID = d.CHITDETAIL_ID       AND detail_desc.LANG_TYPE = 'VIET'       AND IFNULL(detail_desc.ISDEL, '0') = '0'
    WHERE 
	 	h.COMPANY_CD = p_COMPANY_CD 
	 	AND h.CHIT_YMD between v_FROM_DATE and v_TO_DATE
	 	AND IFNULL(h.INPUT_TYPE, '') = 'AR'
      AND IFNULL(h.ISDEL, '0') = '0'
      AND IFNULL(d.ISDEL, '0') = '0'
      AND (
            IFNULL(d.DEBIT, '') LIKE concat(p_ACCOUNT_CD, '%')
            OR 
				IFNULL(d.CREDIT, '') LIKE concat(p_ACCOUNT_CD, '%')
--            OR IFNULL(ext.BANK_ID, 0) <> 0
--            OR IFNULL(ext.BANK_CD, '') <> ''
--            OR IFNULL(ext.BANK_OWN_CD, '') <> ''
      )
    UNION ALL
    SELECT
        'AP' AS MODULE_CD, -- MUA HÀNG
        h.COMPANY_CD,
        h.CHIT_ID,
        d.CHITDETAIL_ID,
        h.CHIT_CD,
        h.CHIT_NO,
        h.CHIT_YMD,
        h.CHIT_TYPE,
        d.CHITDETAIL_CD,
        d.DEBIT,
        d.CREDIT,
        IFNULL(d.AMOUNT, 0) AS AMOUNT,
        IFNULL(d.FC_AMOUNT, 0) AS FC_AMOUNT,
        IFNULL(d.FC_TYPE, '') AS FC_TYPE,
        IFNULL(d.FC_RATE, 0) AS FC_RATE,
        d.FC_DATETIME,
        COALESCE(bank.BANK_CD, ext.BANK_CD) AS BANK_CD,
        ext.BANK_OWN_CD,
        COALESCE(customer.CUSTOMER_CD, ext.CUSTOMER_CD) AS CUSTOMER_CD,
        ext.CUSTOMER_ID,
        ext.ISPAY,
        ext.ISCOLLECT,
        CASE
            WHEN IFNULL(d.DEBIT, '') LIKE concat(p_ACCOUNT_CD, '%') THEN 'RECEIPT'
            WHEN IFNULL(d.CREDIT, '') LIKE concat(p_ACCOUNT_CD, '%') THEN 'PAYMENT'
            ELSE ''
        END AS BANK_FLOW_TYPE,
        CASE WHEN IFNULL(d.DEBIT, '') LIKE concat(p_ACCOUNT_CD, '%') THEN IFNULL(d.AMOUNT, 0) ELSE 0 END AS RECEIPT_AMOUNT,
        CASE WHEN IFNULL(d.CREDIT, '') LIKE concat(p_ACCOUNT_CD, '%') THEN IFNULL(d.AMOUNT, 0) ELSE 0 END AS PAYMENT_AMOUNT,
        CASE WHEN IFNULL(d.DEBIT, '') LIKE concat(p_ACCOUNT_CD, '%') THEN IFNULL(d.FC_AMOUNT, 0) ELSE 0 END AS RECEIPT_FC_AMOUNT,
        CASE WHEN IFNULL(d.CREDIT, '') LIKE concat(p_ACCOUNT_CD, '%') THEN IFNULL(d.FC_AMOUNT, 0) ELSE 0 END AS PAYMENT_FC_AMOUNT
--        header_desc.DESCRIPTION AS HEADER_DESCRIPTION,
--        detail_desc.DESCRIPTION AS DETAIL_DESCRIPTION,
--        COALESCE(NULLIF(detail_desc.DESCRIPTION, ''), NULLIF(header_desc.DESCRIPTION, ''), '') AS DESCRIPTION

    FROM chitinfo h
    INNER JOIN chitdetailinfo d ON d.COMPANY_CD = h.COMPANY_CD AND d.CHIT_ID = h.CHIT_ID
    LEFT JOIN chitdetailinfo_ext ext ON ext.COMPANY_CD = d.COMPANY_CD AND ext.CHITDETAIL_ID = d.CHITDETAIL_ID AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN customer_info customer ON customer.COMPANY_CD = d.COMPANY_CD AND customer.CUSTOMER_ID = ext.CUSTOMER_ID AND IFNULL(customer.ISDEL, '0') = '0'
    LEFT JOIN bank_info bank ON bank.COMPANY_CD = d.COMPANY_CD AND bank.BANK_ID = ext.BANK_ID AND IFNULL(bank.ISDEL, '0') = '0'
--    LEFT JOIN chitdescriptioninfo header_desc        ON header_desc.COMPANY_CD = h.COMPANY_CD       AND header_desc.CHIT_ID = h.CHIT_ID       AND header_desc.LANG_TYPE = 'VIET'       AND IFNULL(header_desc.ISDEL, '0') = '0'
--    LEFT JOIN chitdetaildescriptioninfo detail_desc        ON detail_desc.COMPANY_CD = d.COMPANY_CD       AND detail_desc.CHITDETAIL_ID = d.CHITDETAIL_ID       AND detail_desc.LANG_TYPE = 'VIET'       AND IFNULL(detail_desc.ISDEL, '0') = '0'

    WHERE h.COMPANY_CD = p_COMPANY_CD 
	 	AND h.CHIT_YMD between v_FROM_DATE and v_TO_DATE
		AND IFNULL(h.INPUT_TYPE, '') = 'AP'
      AND IFNULL(h.ISDEL, '0') = '0'
      AND IFNULL(d.ISDEL, '0') = '0'
      AND (
            IFNULL(d.DEBIT, '') LIKE concat(p_ACCOUNT_CD, '%')
            OR 
				IFNULL(d.CREDIT, '') LIKE concat(p_ACCOUNT_CD, '%')
--            OR IFNULL(ext.BANK_ID, 0) <> 0
--            OR IFNULL(ext.BANK_CD, '') <> ''
--            OR IFNULL(ext.BANK_OWN_CD, '') <> ''
      );

	-- ---------------------------------------------------------------------------------------
	    -- 4. Tính toán số dư đầu kỳ (Opening Balance) -> Chạy rất nhanh nhờ có Index trên bảng tạm
		-- ---------------------------------------------------------------------------------------
		select MAX(CLOSE_YMD) into v_MAX_CLOSE_YMD FROM closingmonth_detail c where c.COMPANY_CD = p_COMPANY_CD AND c.CLOSE_YMD < v_FROM_DATE  AND c.ISDEL <> '1' ;
		SET v_MAX_CLOSE_YMD = IFNULL(v_MAX_CLOSE_YMD, '0');

-- select v_MAX_CLOSE_YMD+100 as v_MAX_CLOSE_YMD;
-- call rpt_cash_book('0001', '20260901', '20261001', '','111','','VIET')						
		-- 4.1 closingmonth_detail
		-- lấy dữ liệu KHÓA SỔ gần nhất
		DROP TEMPORARY TABLE IF EXISTS tmp_closingmonth_detail;
	    CREATE TEMPORARY TABLE tmp_closingmonth_detail (
	        
--	        ACC_CD VARCHAR(20),
--	        FC_TYPE VARCHAR(10),
	        AMOUNT DECIMAL(18,2),
	        FC_AMOUNT DECIMAL(18,2)
--	        KEY idx_filter (ACC_CD, FC_TYPE) -- Giúp query số dư đầu kỳ và chi tiết cực nhanh
	    ) ENGINE=InnoDB;
		INSERT INTO tmp_closingmonth_detail
		select 
--			c.ACC_CD, 
--			c.FC_TYPE, 
			(c.DEBIT - c.CREDIT) as AMOUNT, 
			(c.DEBIT_FC - c.CREDIT_FC) as AMOUNT_FC
		from closingmonth_detail c
		where c.COMPANY_CD = p_COMPANY_CD 
			AND c.CLOSE_YMD = v_MAX_CLOSE_YMD  
			AND c.ISDEL <> '1' 
			and c.ACC_CD REGEXP concat('^', v_account_cd)
			and (c.FC_TYPE = '' or c.FC_TYPE = 'VND' or c.FC_TYPE = v_fc_type)
		;
		
		
		-- 4.2 chitinfo inUse 
		-- lấy dữ liệu : SAU TGIAN KHÓA SỔ   VS   TRƯỚC TGIAN TÌM KIẾM
		INSERT INTO tmp_closingmonth_detail
		SELECT 
--			cdt.DEBIT, cdt.CREDIT, 
			SUM(cdt.AMOUNT * (CASE WHEN DEBIT REGEXP concat('^', v_account_cd) THEN 1 ELSE -1 END)) AS AMOUNT,
			SUM(cdt.FC_AMOUNT * (CASE WHEN DEBIT REGEXP concat('^', v_account_cd) THEN 1 ELSE -1 END)) AS FC_AMOUNT

--			cdt.FC_TYPE, 
--			cdt.FC_RATE

--			SELECT * 
		FROM chitdetailinfo cdt
		WHERE cdt.COMPANY_CD = p_COMPANY_CD 			
			and cdt.CHIT_YMD between (v_MAX_CLOSE_YMD + 100) AND (v_FROM_DATE - 1) -- v_MAX_CLOSE_YMD + 100 : 100 là 1 tháng
			AND (DEBIT REGEXP concat('^', v_account_cd) OR CREDIT REGEXP concat('^', v_account_cd))
			and cdt.ISDEL <> '1' 
--			AND (cdt.FC_TYPE = '' OR cdt.FC_TYPE = 'VND' OR cdt.FC_TYPE = p_FC_TYPE )
			;



	-- 4.3
		SELECT
	        IFNULL(SUM(v.AMOUNT), 0),
	        IFNULL(SUM(v.FC_AMOUNT), 0)
	    INTO v_opening_amount, v_opening_fc_amount
	    FROM tmp_closingmonth_detail v
			;

	/*	
    SELECT
        IFNULL(SUM(IFNULL(v.RECEIPT_AMOUNT, 0) - IFNULL(v.PAYMENT_AMOUNT, 0)), 0),
        IFNULL(SUM(IFNULL(v.RECEIPT_FC_AMOUNT, 0) - IFNULL(v.PAYMENT_FC_AMOUNT, 0)), 0)
    INTO v_opening_amount, v_opening_fc_amount
    FROM tmp_bank_deposit_book_source v
    WHERE v.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(v.CHIT_YMD, '') < DATE_FORMAT(p_FROM_DATE, '%Y%m%d')
      AND (
            v_bank_cd = ''
            OR IFNULL(v.BANK_CD, '') = v_bank_cd
            OR IFNULL(v.BANK_OWN_CD, '') = v_bank_cd
          )
      AND (
            v_fc_type = ''
            OR UPPER(IFNULL(v.FC_TYPE, '')) = v_fc_type
          );
	*/


    DROP TEMPORARY TABLE IF EXISTS tmp_bank_deposit_book_detail;
    CREATE TEMPORARY TABLE tmp_bank_deposit_book_detail
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        MODULE_CD VARCHAR(10) NOT NULL DEFAULT '',
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        CHIT_ID BIGINT NOT NULL DEFAULT 0,
        CHITDETAIL_ID BIGINT NOT NULL DEFAULT 0,
        CHIT_CD VARCHAR(50) NOT NULL DEFAULT '',
        CHIT_NO VARCHAR(50) NOT NULL DEFAULT '',
        CHIT_YMD VARCHAR(8) NULL,
        CHIT_TYPE VARCHAR(20) NOT NULL DEFAULT '',
        CHITDETAIL_CD VARCHAR(50) NOT NULL DEFAULT '',
        DEBIT VARCHAR(20) NOT NULL DEFAULT '',
        CREDIT VARCHAR(20) NOT NULL DEFAULT '',
        AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        FC_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        FC_TYPE VARCHAR(10) NOT NULL DEFAULT '',
        FC_RATE DECIMAL(18,6) NOT NULL DEFAULT 0.000000,
        FC_DATETIME DATETIME NULL,
        BANK_CD VARCHAR(50) NOT NULL DEFAULT '',
        BANK_OWN_CD VARCHAR(50) NOT NULL DEFAULT '',
        CUSTOMER_CD VARCHAR(50) NOT NULL DEFAULT '',
        CUSTOMER_ID BIGINT NULL,
        ISPAY VARCHAR(10) NOT NULL DEFAULT '',
        ISCOLLECT VARCHAR(10) NOT NULL DEFAULT '',
        BANK_FLOW_TYPE VARCHAR(20) NOT NULL DEFAULT '',
        RECEIPT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PAYMENT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        RECEIPT_FC_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PAYMENT_FC_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,

--        HEADER_DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
--        DETAIL_DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
--        DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',

        RUNNING_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        RUNNING_FC_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (ROW_NO)
    );

    INSERT INTO tmp_bank_deposit_book_detail
    (
        MODULE_CD,
        COMPANY_CD,
        CHIT_ID,
        CHITDETAIL_ID,
        CHIT_CD,
        CHIT_NO,
        CHIT_YMD,
        CHIT_TYPE,
        CHITDETAIL_CD,
        DEBIT,
        CREDIT,
        AMOUNT,
        FC_AMOUNT,
        FC_TYPE,
        FC_RATE,
        FC_DATETIME,
        BANK_CD,
        BANK_OWN_CD,
        CUSTOMER_CD,
        CUSTOMER_ID,
        ISPAY,
        ISCOLLECT,
        BANK_FLOW_TYPE,
        RECEIPT_AMOUNT,
        PAYMENT_AMOUNT,
        RECEIPT_FC_AMOUNT,
        PAYMENT_FC_AMOUNT
--        HEADER_DESCRIPTION,
--        DETAIL_DESCRIPTION,
--        DESCRIPTION
    )
    SELECT
        IFNULL(v.MODULE_CD, ''),
        IFNULL(v.COMPANY_CD, ''),
        IFNULL(v.CHIT_ID, 0),
        IFNULL(v.CHITDETAIL_ID, 0),
        IFNULL(v.CHIT_CD, ''),
        IFNULL(v.CHIT_NO, ''),
        v.CHIT_YMD,
        IFNULL(v.CHIT_TYPE, ''),
        IFNULL(v.CHITDETAIL_CD, ''),
        IFNULL(v.DEBIT, ''),
        IFNULL(v.CREDIT, ''),
        IFNULL(v.AMOUNT, 0),
        IFNULL(v.FC_AMOUNT, 0),
        IFNULL(v.FC_TYPE, ''),
        IFNULL(v.FC_RATE, 0),
        v.FC_DATETIME,
        IFNULL(v.BANK_CD, ''),
        IFNULL(v.BANK_OWN_CD, ''),
        IFNULL(v.CUSTOMER_CD, ''),
        v.CUSTOMER_ID,
        IFNULL(v.ISPAY, ''),
        IFNULL(v.ISCOLLECT, ''),
        IFNULL(v.BANK_FLOW_TYPE, ''),
        IFNULL(v.RECEIPT_AMOUNT, 0),
        IFNULL(v.PAYMENT_AMOUNT, 0),
        IFNULL(v.RECEIPT_FC_AMOUNT, 0),
        IFNULL(v.PAYMENT_FC_AMOUNT, 0)
--        IFNULL(v.HEADER_DESCRIPTION, ''),
--        IFNULL(v.DETAIL_DESCRIPTION, ''),
--        IFNULL(v.DESCRIPTION, '')
    FROM tmp_bank_deposit_book_source v
    WHERE v.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(v.CHIT_YMD, '') >= DATE_FORMAT(p_FROM_DATE, '%Y%m%d')
      AND IFNULL(v.CHIT_YMD, '') <= DATE_FORMAT(p_TO_DATE, '%Y%m%d')
      AND (
            v_bank_cd = ''
            OR IFNULL(v.BANK_CD, '') = v_bank_cd
            OR IFNULL(v.BANK_OWN_CD, '') = v_bank_cd
          )
      AND (
            v_fc_type = ''
            OR UPPER(IFNULL(v.FC_TYPE, '')) = v_fc_type
          )
    ORDER BY
        IFNULL(v.CHIT_YMD, ''),
        IFNULL(v.CHIT_NO, ''),
        IFNULL(v.CHIT_ID, 0),
        IFNULL(v.CHITDETAIL_ID, 0);

    SELECT
        IFNULL(SUM(RECEIPT_AMOUNT), 0),
        IFNULL(SUM(PAYMENT_AMOUNT), 0),
        IFNULL(SUM(RECEIPT_FC_AMOUNT), 0),
        IFNULL(SUM(PAYMENT_FC_AMOUNT), 0)
    INTO
        v_total_receipt_amount,
        v_total_payment_amount,
        v_total_receipt_fc_amount,
        v_total_payment_fc_amount
    FROM tmp_bank_deposit_book_detail;

    SET v_closing_amount = v_opening_amount + v_total_receipt_amount - v_total_payment_amount;
    SET v_closing_fc_amount = v_opening_fc_amount + v_total_receipt_fc_amount - v_total_payment_fc_amount;
    SET @running_amount := v_opening_amount;
    SET @running_fc_amount := v_opening_fc_amount;


    UPDATE tmp_bank_deposit_book_detail
    SET
        RUNNING_AMOUNT = (@running_amount := @running_amount + RECEIPT_AMOUNT - PAYMENT_AMOUNT),
        RUNNING_FC_AMOUNT = (@running_fc_amount := @running_fc_amount + RECEIPT_FC_AMOUNT - PAYMENT_FC_AMOUNT)
    ORDER BY ROW_NO;

    SELECT
--        report.ROW_KEY,
--        report.ROW_TYPE,
        DATE_FORMAT(STR_TO_DATE(report.CHIT_YMD, '%Y%m%d'), '%d/%m/%Y') as CHIT_YMD, 
        
        COALESCE(cust.CUSTOMER_CD, '') AS CUSTOMER_CD,
		  
		  ( -- p_LANGUAGE
		  		CASE p_LANGUAGE
					WHEN  'VIET' 
					  	THEN -- Kiểm tra NULL và rỗng cho VIET
    							COALESCE(NULLIF(cust.CUSTOMER_NM_VIET, ''), '')
					WHEN 'ENG' 
					  	THEN -- Ưu tiên ENG, nếu NULL hoặc rỗng thì lấy VIET
    							COALESCE(NULLIF(cust.CUSTOMER_NM_ENG, ''), NULLIF(cust.CUSTOMER_NM_VIET, ''), '')
					WHEN 'KOR' 
					  	THEN -- Ưu tiên KOR, nếu NULL hoặc rỗng thì lấy ENG, tiếp đến VIET
    							COALESCE(NULLIF(cust.CUSTOMER_NM_KOR, ''), NULLIF(cust.CUSTOMER_NM_ENG, ''), NULLIF(cust.CUSTOMER_NM_VIET, ''), '')
					else 
						COALESCE(cust.CUSTOMER_NM_VIET, '')
				end
		  ) as CUSTOMER_NM,
        
        cust_e.TAX_CD AS TAX_CD,
        
        chit_v.VAT_CHIT_NO,
        
        report.CHIT_CD AS __CHIT_CD,
        report.CHIT_NO,
        
--		  report.DESCRIPTION AS DESCRIPTION,
        case when SORT_GROUP <> 2 then concat('*** ', fn_getLanguage(report.ROW_KEY, 'VIET', report.ROW_KEY), ' ***') else IFNULL(desc_V.DESCRIPTION, '') end AS DESCRIPTION_VIET,
		  case when SORT_GROUP <> 2 then concat('*** ', fn_getLanguage(report.ROW_KEY, 'ENG', report.ROW_KEY), ' ***') else IFNULL(desc_E.DESCRIPTION, '') end AS DESCRIPTION_ENG,
        case when SORT_GROUP <> 2 then concat('*** ', fn_getLanguage(report.ROW_KEY, 'KOR', report.ROW_KEY), ' ***') else IFNULL(desc_K.DESCRIPTION, '') end AS DESCRIPTION_KOR,
        
        case when SORT_GROUP <> 2 then concat('*** ', fn_getLanguage(report.ROW_KEY, 'VIET', report.ROW_KEY), ' ***') else IFNULL(desc2_V.DESCRIPTION, '') end AS DESCRIPTION2_VIET,
		  case when SORT_GROUP <> 2 then concat('*** ', fn_getLanguage(report.ROW_KEY, 'ENG', report.ROW_KEY), ' ***') else IFNULL(desc2_E.DESCRIPTION, '') end AS DESCRIPTION2_ENG,
        case when SORT_GROUP <> 2 then concat('*** ', fn_getLanguage(report.ROW_KEY, 'KOR', report.ROW_KEY), ' ***') else IFNULL(desc2_K.DESCRIPTION, '') end AS DESCRIPTION2_KOR,
        
        
		  CASE
            WHEN report.BANK_FLOW_TYPE = 'PAYMENT' THEN report.CREDIT
            WHEN report.BANK_FLOW_TYPE = 'RECEIPT' THEN report.DEBIT
            ELSE ''
        END AS ACC_CD,
        
        CASE
            WHEN report.BANK_FLOW_TYPE = 'RECEIPT' THEN report.CREDIT
            WHEN report.BANK_FLOW_TYPE = 'PAYMENT' THEN report.DEBIT
            ELSE ''
        END AS CSD_ACC_CD,

