            0.00 AS PAYMENT_FC_AMOUNT,
            
--            '' AS HEADER_DESCRIPTION,
--            '' AS DETAIL_DESCRIPTION,
--            'Opening Balance' AS DESCRIPTION,
            
            v_opening_amount AS RUNNING_AMOUNT,
