	    LEFT JOIN chitdetaildescriptioninfo desc2_E         ON desc2_E.COMPANY_CD = report.COMPANY_CD AND desc2_E.CHITDETAIL_ID = report.CHITDETAIL_ID AND desc2_E.LANG_TYPE = 'ENG' AND desc2_E.ISDEL = '0'
	    LEFT JOIN chitdetaildescriptioninfo desc2_K         ON desc2_K.COMPANY_CD = report.COMPANY_CD AND desc2_K.CHITDETAIL_ID = report.CHITDETAIL_ID AND desc2_K.LANG_TYPE = 'KOR' AND desc2_K.ISDEL = '0'
    
    ORDER BY report.SORT_GROUP, report.SORT_SEQ;

