-- Dumping structure for procedure am_web_001.rpt_bank_notice_voucher
DROP PROCEDURE IF EXISTS `rpt_bank_notice_voucher`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_bank_notice_voucher`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHIT_ID BIGINT,
    IN p_CHIT_IDS TEXT,
    IN p_LANGUAGE VARCHAR(20),
    IN p_INPUT_TYPE VARCHAR(10),
    IN p_CHIT_TYPE VARCHAR(10)
)
BEGIN
    DECLARE v_chit_ids TEXT;
    DECLARE v_language VARCHAR(20);
    DECLARE v_input_type VARCHAR(10);
    DECLARE v_chit_type VARCHAR(10);

    SET v_chit_ids = REPLACE(REPLACE(REPLACE(REPLACE(IFNULL(TRIM(p_CHIT_IDS), ''), '|', ','), ';', ','), CHAR(10), ','), CHAR(13), ',');
    SET v_chit_ids = IF(v_chit_ids = '' AND IFNULL(p_CHIT_ID, 0) > 0, CAST(p_CHIT_ID AS CHAR), v_chit_ids);
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));
    SET v_input_type = UPPER(TRIM(IFNULL(p_INPUT_TYPE, '')));
    SET v_chit_type = UPPER(TRIM(IFNULL(p_CHIT_TYPE, '')));

    SELECT
        h.CHIT_ID,
        h.COMPANY_CD,
        h.CHIT_CD,
        h.CHIT_NO,
        h.CHIT_YMD,
        h.CHIT_YMD AS HEADER_DATE_TEXT,
        h.CHIT_YMD AS SIGNATURE_DATE_TEXT,
        COALESCE(NULLIF(TRIM(h.PAYER_INFO), ''), detail.CUSTOMER_NAME, '') AS PARTNER_NAME,
        IFNULL(detail.CUSTOMER_ADDRESS, '') AS PARTNER_ADDRESS,
        COALESCE(
            NULLIF(TRIM(
                CASE v_language
                    WHEN 'ENG' THEN desc_en.DESCRIPTION
                    WHEN 'KOR' THEN desc_ko.DESCRIPTION
                    WHEN 'CHINA' THEN desc_china.DESCRIPTION
                    ELSE desc_vi.DESCRIPTION
                END
            ), ''),
            NULLIF(TRIM(ext.NOTE), ''),
            detail.DETAIL_DESCRIPTION,
            ''
        ) AS REASON,
        IFNULL(h.AMOUNT, IFNULL(detail.DETAIL_AMOUNT, 0)) AS AMOUNT,
        NULL AS AMOUNT_TEXT,
        NULL AS AMOUNT_IN_WORDS,
        CASE WHEN IFNULL(detail.FC_TYPE, '') <> '' AND IFNULL(detail.FC_AMOUNT, 0) > 0 THEN detail.FC_AMOUNT ELSE NULL END AS FC_AMOUNT,
        CASE WHEN IFNULL(detail.FC_TYPE, '') <> '' AND IFNULL(detail.FC_AMOUNT, 0) > 0 THEN detail.FC_TYPE ELSE NULL END AS FC_TYPE,
        CASE WHEN IFNULL(detail.FC_TYPE, '') <> '' AND IFNULL(detail.FC_RATE, 0) > 0 THEN detail.FC_RATE ELSE NULL END AS FC_RATE,
        NULL AS EXCHANGE_RATE_TEXT,
        NULL AS CONVERTED_AMOUNT_TEXT,
        IFNULL(detail.DEBIT_ACCOUNT, '') AS DEBIT_ACCOUNT,
        IFNULL(detail.CREDIT_ACCOUNT, '') AS CREDIT_ACCOUNT,
        IFNULL(detail.DETAIL_COUNT, 0) AS DETAIL_COUNT,
        CAST(IFNULL(detail.DETAIL_COUNT, 0) AS CHAR) AS ATTACHMENT_COUNT_TEXT,
        '........................................................' AS REFERENCE_LINE_TEXT,
        NULL AS ATTACHMENT_TEXT,
        NULL AS REFERENCE_TEXT,
        IFNULL(ext.NOTE, '') AS NOTE,
        NULL AS NOTE_TEXT,
        COALESCE(NULLIF(TRIM(h.UPDATE_BY), ''), NULLIF(TRIM(h.CREATE_BY), ''), '') AS CREATE_BY
    FROM chitinfo h
    LEFT JOIN chitinfo_ext ext ON ext.COMPANY_CD = h.COMPANY_CD AND ext.CHIT_ID = h.CHIT_ID AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo desc_vi ON desc_vi.COMPANY_CD = h.COMPANY_CD AND desc_vi.CHIT_ID = h.CHIT_ID AND desc_vi.LANG_TYPE = 'VIET' AND IFNULL(desc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo desc_en ON desc_en.COMPANY_CD = h.COMPANY_CD AND desc_en.CHIT_ID = h.CHIT_ID AND desc_en.LANG_TYPE = 'ENG' AND IFNULL(desc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo desc_ko ON desc_ko.COMPANY_CD = h.COMPANY_CD AND desc_ko.CHIT_ID = h.CHIT_ID AND desc_ko.LANG_TYPE = 'KOR' AND IFNULL(desc_ko.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo desc_china ON desc_china.COMPANY_CD = h.COMPANY_CD AND desc_china.CHIT_ID = h.CHIT_ID AND desc_china.LANG_TYPE = 'CHINA' AND IFNULL(desc_china.ISDEL, '0') = '0'
    LEFT JOIN (
        SELECT
            d.CHIT_ID,
            COUNT(*) AS DETAIL_COUNT,
            SUM(IFNULL(d.AMOUNT, 0)) AS DETAIL_AMOUNT,
            SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(UPPER(TRIM(IFNULL(d.FC_TYPE, ''))), '') ORDER BY IFNULL(d.SORT, 0), d.CHITDETAIL_ID SEPARATOR ','), ',', 1) AS FC_TYPE,
            SUM(IFNULL(d.FC_AMOUNT, 0)) AS FC_AMOUNT,
            MAX(CASE WHEN IFNULL(d.FC_RATE, 0) > 0 THEN d.FC_RATE ELSE 0 END) AS FC_RATE,
            GROUP_CONCAT(DISTINCT NULLIF(TRIM(d.DEBIT), '') ORDER BY d.DEBIT SEPARATOR ', ') AS DEBIT_ACCOUNT,
            GROUP_CONCAT(DISTINCT NULLIF(TRIM(d.CREDIT), '') ORDER BY d.CREDIT SEPARATOR ', ') AS CREDIT_ACCOUNT,
            SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(COALESCE(customer.CUSTOMER_NM_VIET, '')), '') ORDER BY IFNULL(d.SORT, 0), d.CHITDETAIL_ID SEPARATOR '\n'), '\n', 1) AS CUSTOMER_NAME,
            SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(COALESCE(customer.ADDRESS, '')), '') ORDER BY IFNULL(d.SORT, 0), d.CHITDETAIL_ID SEPARATOR '\n'), '\n', 1) AS CUSTOMER_ADDRESS,
            SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(
                COALESCE(
                    CASE v_language
                        WHEN 'ENG' THEN detail_desc_en.DESCRIPTION
                        WHEN 'KOR' THEN detail_desc_ko.DESCRIPTION
                        WHEN 'CHINA' THEN detail_desc_china.DESCRIPTION
                        ELSE detail_desc_vi.DESCRIPTION
                    END,
                    detail_desc_vi.DESCRIPTION,
                    detail_desc_en.DESCRIPTION,
                    detail_desc_ko.DESCRIPTION,
                    ''
                )
            ), '') ORDER BY IFNULL(d.SORT, 0), d.CHITDETAIL_ID SEPARATOR '\n'), '\n', 1) AS DETAIL_DESCRIPTION
        FROM chitdetailinfo d
        LEFT JOIN chitdetailinfo_ext detail_ext ON detail_ext.COMPANY_CD = d.COMPANY_CD AND detail_ext.CHITDETAIL_ID = d.CHITDETAIL_ID AND IFNULL(detail_ext.ISDEL, '0') = '0'
        LEFT JOIN customer_info customer ON customer.COMPANY_CD = detail_ext.COMPANY_CD AND customer.CUSTOMER_ID = detail_ext.CUSTOMER_ID AND IFNULL(customer.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_desc_vi ON detail_desc_vi.COMPANY_CD = d.COMPANY_CD AND detail_desc_vi.CHITDETAIL_ID = d.CHITDETAIL_ID AND detail_desc_vi.LANG_TYPE = 'VIET' AND IFNULL(detail_desc_vi.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_desc_en ON detail_desc_en.COMPANY_CD = d.COMPANY_CD AND detail_desc_en.CHITDETAIL_ID = d.CHITDETAIL_ID AND detail_desc_en.LANG_TYPE = 'ENG' AND IFNULL(detail_desc_en.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_desc_ko ON detail_desc_ko.COMPANY_CD = d.COMPANY_CD AND detail_desc_ko.CHITDETAIL_ID = d.CHITDETAIL_ID AND detail_desc_ko.LANG_TYPE = 'KOR' AND IFNULL(detail_desc_ko.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_desc_china ON detail_desc_china.COMPANY_CD = d.COMPANY_CD AND detail_desc_china.CHITDETAIL_ID = d.CHITDETAIL_ID AND detail_desc_china.LANG_TYPE = 'CHINA' AND IFNULL(detail_desc_china.ISDEL, '0') = '0'
        WHERE d.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(d.ISDEL, '0') = '0'
        GROUP BY d.CHIT_ID
    ) detail ON detail.CHIT_ID = h.CHIT_ID
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = v_input_type
      AND h.CHIT_TYPE = v_chit_type
      AND IFNULL(h.ISDEL, '0') = '0'
      AND v_chit_ids <> ''
      AND FIND_IN_SET(CAST(h.CHIT_ID AS CHAR) COLLATE utf8_unicode_ci, v_chit_ids COLLATE utf8_unicode_ci) > 0
    ORDER BY h.CHIT_YMD, h.CHIT_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_cashflow_b03dn_direct
DROP PROCEDURE IF EXISTS `rpt_cashflow_b03dn_direct`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_cashflow_b03dn_direct`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_REPORT_VERSION VARCHAR(20),
    IN p_UNIT_DIVISOR DECIMAL(18,6),
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_from_date DATE;
    DECLARE v_to_date DATE;
    DECLARE v_previous_from_date DATE;
    DECLARE v_previous_to_date DATE;
    DECLARE v_current_begin_date DATE;
    DECLARE v_previous_begin_date DATE;
    DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_previous_from_ymd VARCHAR(8);
    DECLARE v_previous_to_ymd VARCHAR(8);
    DECLARE v_current_begin_ymd VARCHAR(8);
    DECLARE v_previous_begin_ymd VARCHAR(8);
    DECLARE v_max_to_ymd VARCHAR(8);
    DECLARE v_report_version VARCHAR(20);
    DECLARE v_template_company_cd VARCHAR(20);
    DECLARE v_unit_divisor DECIMAL(18,6);
    DECLARE v_cash_account_prefixes VARCHAR(500);
    DECLARE v_iteration INT DEFAULT 0;
    DECLARE v_changed_rows INT DEFAULT 0;
    DECLARE v_language VARCHAR(20);

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;

    SET v_from_date = p_FROM_DATE;
    SET v_to_date = p_TO_DATE;
    SET v_previous_from_date = DATE_SUB(v_from_date, INTERVAL 1 YEAR);
    SET v_previous_to_date = DATE_SUB(v_to_date, INTERVAL 1 YEAR);
    SET v_current_begin_date = DATE_SUB(v_from_date, INTERVAL 1 DAY);
    SET v_previous_begin_date = DATE_SUB(v_previous_from_date, INTERVAL 1 DAY);
    SET v_from_ymd = DATE_FORMAT(v_from_date, '%Y%m%d');
    SET v_to_ymd = DATE_FORMAT(v_to_date, '%Y%m%d');
    SET v_previous_from_ymd = DATE_FORMAT(v_previous_from_date, '%Y%m%d');
    SET v_previous_to_ymd = DATE_FORMAT(v_previous_to_date, '%Y%m%d');
    SET v_current_begin_ymd = DATE_FORMAT(v_current_begin_date, '%Y%m%d');
    SET v_previous_begin_ymd = DATE_FORMAT(v_previous_begin_date, '%Y%m%d');
    SET v_max_to_ymd = IF(v_to_ymd >= v_previous_to_ymd, v_to_ymd, v_previous_to_ymd);
    SET v_report_version = IFNULL(NULLIF(TRIM(IFNULL(p_REPORT_VERSION, '')), ''), '2025');
    SET v_unit_divisor = CASE WHEN IFNULL(p_UNIT_DIVISOR, 0) = 0 THEN 1 ELSE p_UNIT_DIVISOR END;
    SET v_language = UPPER(IFNULL(NULLIF(TRIM(p_LANGUAGE), ''), 'VIET'));

    SELECT COALESCE(
        (
            SELECT template.COMPANY_CD
            FROM report_b03dntt template
            WHERE template.REPORT_CODE = 'B03_DN_TT'
              AND template.REPORT_VERSION = v_report_version
              AND template.COMPANY_CD IN (p_COMPANY_CD, '')
              -- A CONFIG-only override must not shadow the usable DETAIL template.
              AND UPPER(IFNULL(template.SECTION_TYPE, '')) = 'DETAIL'
              AND IFNULL(template.ISDEL, '0') = '0'
            ORDER BY CASE
                WHEN template.COMPANY_CD = p_COMPANY_CD THEN 0
                ELSE 1
            END
            LIMIT 1
        ),
        ''
    )
    INTO v_template_company_cd;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_numbers;
    CREATE TEMPORARY TABLE tmp_b03tt_numbers
    (
        N INT NOT NULL,
        PRIMARY KEY (N)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_numbers (N)
    SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5
    UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10
    UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15
    UNION ALL SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL SELECT 20
    UNION ALL SELECT 21 UNION ALL SELECT 22 UNION ALL SELECT 23 UNION ALL SELECT 24 UNION ALL SELECT 25
    UNION ALL SELECT 26 UNION ALL SELECT 27 UNION ALL SELECT 28 UNION ALL SELECT 29 UNION ALL SELECT 30
    UNION ALL SELECT 31 UNION ALL SELECT 32 UNION ALL SELECT 33 UNION ALL SELECT 34 UNION ALL SELECT 35
    UNION ALL SELECT 36 UNION ALL SELECT 37 UNION ALL SELECT 38 UNION ALL SELECT 39 UNION ALL SELECT 40;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_cash_prefix;
    CREATE TEMPORARY TABLE tmp_b03tt_cash_prefix
    (
        ACC_PREFIX VARCHAR(20) NOT NULL,
        PRIMARY KEY (ACC_PREFIX)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    SELECT NULLIF(TRIM(IFNULL(template.ACCOUNT_RULE, '')), '')
    INTO v_cash_account_prefixes
    FROM report_b03dntt template
    WHERE template.COMPANY_CD = v_template_company_cd
      AND template.REPORT_CODE = 'B03_DN_TT'
      AND template.REPORT_VERSION = v_report_version
      AND template.SECTION_TYPE = 'CONFIG'
      AND template.ITEM_KEY = 'CASH_ACCOUNT_PREFIXES'
      AND IFNULL(template.ISDEL, '0') = '0'
    ORDER BY template.ID DESC
    LIMIT 1;

    -- Accept the same comma/semicolon separators as the editable account rules.
    SET v_cash_account_prefixes = REPLACE(IFNULL(v_cash_account_prefixes, '111,112,113'), ';', ',');

    INSERT IGNORE INTO tmp_b03tt_cash_prefix (ACC_PREFIX)
    SELECT TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(v_cash_account_prefixes, ',', numbers.N), ',', -1))
    FROM tmp_b03tt_numbers numbers
    WHERE numbers.N <= 1 + LENGTH(v_cash_account_prefixes) - LENGTH(REPLACE(v_cash_account_prefixes, ',', ''))
      AND TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(v_cash_account_prefixes, ',', numbers.N), ',', -1)) <> '';

    -- MySQL cannot reference the same TEMPORARY TABLE twice in one statement.
    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_cash_prefix_copy;
    CREATE TEMPORARY TABLE tmp_b03tt_cash_prefix_copy
    (
        ACC_PREFIX VARCHAR(20) NOT NULL,
        PRIMARY KEY (ACC_PREFIX)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_cash_prefix_copy (ACC_PREFIX)
    SELECT ACC_PREFIX
    FROM tmp_b03tt_cash_prefix;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_period;
    CREATE TEMPORARY TABLE tmp_b03tt_period
    (
        PERIOD_TYPE VARCHAR(20) NOT NULL,
        FROM_YMD VARCHAR(8) NOT NULL,
        TO_YMD VARCHAR(8) NOT NULL,
        PRIMARY KEY (PERIOD_TYPE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_period (PERIOD_TYPE, FROM_YMD, TO_YMD)
    VALUES
    ('CURRENT', v_from_ymd, v_to_ymd),
    ('PREVIOUS', v_previous_from_ymd, v_previous_to_ymd);

    /*
        Tá»‘i Æ°u dÃ²ng tiá»n trá»±c tiáº¿p:
        - KhÃ´ng lÆ°u tá»«ng giao dá»‹ch vÃ o temporary table.
        - Aggregate ngay theo PERIOD_TYPE + FLOW_SIGN + COUNTER_ACC.
        - DÃ¹ng trá»±c tiáº¿p header.CHIT_YMD Ä‘á»ƒ táº­n dá»¥ng index ngÃ y.
        - Giá»¯ tmp_b03tt_period Ä‘á»ƒ báº£o toÃ n logic CURRENT/PREVIOUS,
          ká»ƒ cáº£ trÆ°á»ng há»£p hai khoáº£ng thá»i gian giao nhau.
    */
    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_movement;
    CREATE TEMPORARY TABLE tmp_b03tt_movement
    (
        PERIOD_TYPE VARCHAR(20) NOT NULL,
        FLOW_SIGN INT NOT NULL,
        COUNTER_ACC VARCHAR(20) NOT NULL,
        AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (PERIOD_TYPE, FLOW_SIGN, COUNTER_ACC)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    /* Tiá»n vÃ o: Ná»£ tÃ i khoáº£n tiá»n, CÃ³ tÃ i khoáº£n Ä‘á»‘i á»©ng. */
    INSERT INTO tmp_b03tt_movement
    (
        PERIOD_TYPE,
        FLOW_SIGN,
        COUNTER_ACC,
        AMOUNT
    )
    SELECT
        period.PERIOD_TYPE,
        1 AS FLOW_SIGN,
        TRIM(detail.CREDIT) AS COUNTER_ACC,
        SUM(ABS(IFNULL(detail.AMOUNT, 0))) AS AMOUNT
    FROM tmp_b03tt_period period
    STRAIGHT_JOIN chitinfo header
        ON header.COMPANY_CD = p_COMPANY_CD
       AND header.ISDEL = '0'
       AND header.CHIT_YMD >= period.FROM_YMD
       AND header.CHIT_YMD <= period.TO_YMD
    INNER JOIN chitdetailinfo detail
        ON detail.COMPANY_CD = header.COMPANY_CD
       AND detail.CHIT_ID = header.CHIT_ID
       AND detail.ISDEL = '0'
    WHERE ABS(IFNULL(detail.AMOUNT, 0)) <> 0
      AND detail.CREDIT IS NOT NULL
      AND TRIM(detail.CREDIT) <> ''
      AND EXISTS
      (
          SELECT 1
          FROM tmp_b03tt_cash_prefix cash_prefix
          WHERE TRIM(detail.DEBIT) LIKE CONCAT(cash_prefix.ACC_PREFIX, '%')
      )
      AND NOT EXISTS
      (
          SELECT 1
          FROM tmp_b03tt_cash_prefix_copy cash_prefix_copy
          WHERE TRIM(detail.CREDIT) LIKE CONCAT(cash_prefix_copy.ACC_PREFIX, '%')
      )
    GROUP BY
        period.PERIOD_TYPE,
        TRIM(detail.CREDIT);

    /* Tiá»n ra: CÃ³ tÃ i khoáº£n tiá»n, Ná»£ tÃ i khoáº£n Ä‘á»‘i á»©ng. */
    INSERT INTO tmp_b03tt_movement
    (
        PERIOD_TYPE,
        FLOW_SIGN,
        COUNTER_ACC,
        AMOUNT
    )
    SELECT
        period.PERIOD_TYPE,
        -1 AS FLOW_SIGN,
        TRIM(detail.DEBIT) AS COUNTER_ACC,
        SUM(ABS(IFNULL(detail.AMOUNT, 0))) AS AMOUNT
    FROM tmp_b03tt_period period
    STRAIGHT_JOIN chitinfo header
        ON header.COMPANY_CD = p_COMPANY_CD
       AND header.ISDEL = '0'
       AND header.CHIT_YMD >= period.FROM_YMD
       AND header.CHIT_YMD <= period.TO_YMD
    INNER JOIN chitdetailinfo detail
        ON detail.COMPANY_CD = header.COMPANY_CD
       AND detail.CHIT_ID = header.CHIT_ID
       AND detail.ISDEL = '0'
    WHERE ABS(IFNULL(detail.AMOUNT, 0)) <> 0
      AND detail.DEBIT IS NOT NULL
      AND TRIM(detail.DEBIT) <> ''
      AND EXISTS
      (
          SELECT 1
          FROM tmp_b03tt_cash_prefix cash_prefix
          WHERE TRIM(detail.CREDIT) LIKE CONCAT(cash_prefix.ACC_PREFIX, '%')
      )
      AND NOT EXISTS
      (
          SELECT 1
          FROM tmp_b03tt_cash_prefix_copy cash_prefix_copy
          WHERE TRIM(detail.DEBIT) LIKE CONCAT(cash_prefix_copy.ACC_PREFIX, '%')
      )
    GROUP BY
        period.PERIOD_TYPE,
        TRIM(detail.DEBIT);

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_direct_rule;
    CREATE TEMPORARY TABLE tmp_b03tt_direct_rule
    (
        ITEM_CODE VARCHAR(20) NOT NULL,
        FLOW_SIGN INT NOT NULL,
        ACC_PREFIX VARCHAR(20) NOT NULL,
        PRIORITY INT NOT NULL,
        INDEX idx_tmp_b03tt_direct_rule_01 (FLOW_SIGN, ACC_PREFIX, PRIORITY)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_direct_rule (ITEM_CODE, FLOW_SIGN, ACC_PREFIX, PRIORITY)
    SELECT
        report.ITEM_CODE,
        report.DIRECT_RULE_FLOW_SIGN AS FLOW_SIGN,
        TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(report.DIRECT_RULE_ACC_PREFIX, ',', numbers.N), ',', -1)) AS ACC_PREFIX,
        report.DIRECT_RULE_PRIORITY AS PRIORITY
    FROM report_b03dntt report
    INNER JOIN tmp_b03tt_numbers numbers
        ON numbers.N <= 1 + LENGTH(IFNULL(report.DIRECT_RULE_ACC_PREFIX, '')) - LENGTH(REPLACE(IFNULL(report.DIRECT_RULE_ACC_PREFIX, ''), ',', ''))
    WHERE report.COMPANY_CD = v_template_company_cd
      AND report.REPORT_CODE = 'B03_DN_TT'
      AND report.REPORT_VERSION = v_report_version
      AND IFNULL(report.ISDEL, '0') = '0'
      AND IFNULL(report.DIRECT_RULE_ACC_PREFIX, '') <> '';

    INSERT INTO tmp_b03tt_direct_rule (ITEM_CODE, FLOW_SIGN, ACC_PREFIX, PRIORITY)
    SELECT
        report.ITEM_CODE,
        report.DIRECT_RULE_FLOW_SIGN_2 AS FLOW_SIGN,
        TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(report.DIRECT_RULE_ACC_PREFIX_2, ',', numbers.N), ',', -1)) AS ACC_PREFIX,
        report.DIRECT_RULE_PRIORITY_2 AS PRIORITY
    FROM report_b03dntt report
    INNER JOIN tmp_b03tt_numbers numbers
        ON numbers.N <= 1 + LENGTH(IFNULL(report.DIRECT_RULE_ACC_PREFIX_2, '')) - LENGTH(REPLACE(IFNULL(report.DIRECT_RULE_ACC_PREFIX_2, ''), ',', ''))
    WHERE report.COMPANY_CD = v_template_company_cd
      AND report.REPORT_CODE = 'B03_DN_TT'
      AND report.REPORT_VERSION = v_report_version
      AND IFNULL(report.ISDEL, '0') = '0'
      AND IFNULL(report.DIRECT_RULE_ACC_PREFIX_2, '') <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_direct_rule_copy;
    CREATE TEMPORARY TABLE tmp_b03tt_direct_rule_copy
    (
        ITEM_CODE VARCHAR(20) NOT NULL,
        FLOW_SIGN INT NOT NULL,
        ACC_PREFIX VARCHAR(20) NOT NULL,
        PRIORITY INT NOT NULL,
        INDEX idx_tmp_b03tt_direct_rule_copy_01
            (FLOW_SIGN, ACC_PREFIX, PRIORITY)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_direct_rule_copy
    (
        ITEM_CODE,
        FLOW_SIGN,
        ACC_PREFIX,
        PRIORITY
    )
    SELECT
        ITEM_CODE,
        FLOW_SIGN,
        ACC_PREFIX,
        PRIORITY
    FROM tmp_b03tt_direct_rule;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_direct_match;
    CREATE TEMPORARY TABLE tmp_b03tt_direct_match
    (
        PERIOD_TYPE VARCHAR(20) NOT NULL,
        FLOW_SIGN INT NOT NULL,
        COUNTER_ACC VARCHAR(20) NOT NULL,
        ITEM_CODE VARCHAR(20) NOT NULL,
        INDEX idx_tmp_b03tt_direct_match_01
            (PERIOD_TYPE, FLOW_SIGN, COUNTER_ACC, ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_direct_match
    (
        PERIOD_TYPE,
        FLOW_SIGN,
        COUNTER_ACC,
        ITEM_CODE
    )
    SELECT
        movement.PERIOD_TYPE,
        movement.FLOW_SIGN,
        movement.COUNTER_ACC,
        rule.ITEM_CODE
    FROM tmp_b03tt_movement movement
    INNER JOIN tmp_b03tt_direct_rule rule
        ON rule.FLOW_SIGN = movement.FLOW_SIGN
       AND movement.COUNTER_ACC LIKE CONCAT(rule.ACC_PREFIX, '%')
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM tmp_b03tt_direct_rule_copy better_rule
        WHERE better_rule.FLOW_SIGN = movement.FLOW_SIGN
          AND movement.COUNTER_ACC LIKE CONCAT(better_rule.ACC_PREFIX, '%')
          AND better_rule.PRIORITY < rule.PRIORITY
    );

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_direct_rule_copy;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_amount;
    CREATE TEMPORARY TABLE tmp_b03tt_amount
    (
        ITEM_CODE VARCHAR(20) NOT NULL,
        PERIOD_TYPE VARCHAR(20) NOT NULL,
        VALUE_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (ITEM_CODE, PERIOD_TYPE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_amount
    (
        ITEM_CODE,
        PERIOD_TYPE,
        VALUE_AMOUNT
    )
    SELECT
        COALESCE(
            direct_match.ITEM_CODE,
            CASE
                WHEN movement.FLOW_SIGN = 1 THEN '06'
                ELSE '07'
            END
        ) AS ITEM_CODE,
        movement.PERIOD_TYPE,
        SUM(
            CASE
                WHEN movement.FLOW_SIGN = 1 THEN movement.AMOUNT
                ELSE -movement.AMOUNT
            END
        ) AS VALUE_AMOUNT
    FROM tmp_b03tt_movement movement
    LEFT JOIN tmp_b03tt_direct_match direct_match
        ON direct_match.PERIOD_TYPE = movement.PERIOD_TYPE
       AND direct_match.FLOW_SIGN = movement.FLOW_SIGN
       AND direct_match.COUNTER_ACC = movement.COUNTER_ACC
    GROUP BY
        COALESCE(
            direct_match.ITEM_CODE,
            CASE
                WHEN movement.FLOW_SIGN = 1 THEN '06'
                ELSE '07'
            END
        ),
        movement.PERIOD_TYPE;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_report;
    CREATE TEMPORARY TABLE tmp_b03tt_report
    (
        ROW_KEY VARCHAR(80) NOT NULL DEFAULT '',
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        ROW_TYPE VARCHAR(30) NOT NULL DEFAULT '',
        SORT_ORDER INT NOT NULL DEFAULT 0,
        ITEM_CODE VARCHAR(50) NULL,
        ITEM_NAME VARCHAR(1000) NULL,
        CAPTION VARCHAR(1000) NULL,
        LABEL_TEXT VARCHAR(200) NULL,
        NOTE VARCHAR(100) NOT NULL DEFAULT '',
        CURRENT_YEAR DECIMAL(18,2) NULL,
        PREVIOUS_YEAR DECIMAL(18,2) NULL,
        LEVEL_NO INT NOT NULL DEFAULT 0,
        FONT_BOLD CHAR(1) NOT NULL DEFAULT '0',
        FONT_ITALIC CHAR(1) NOT NULL DEFAULT '0',
        DATA_SOURCE_TYPE VARCHAR(50) NULL,
        FORMULA_EXPR VARCHAR(1000) NULL,
        REPORT_YEAR_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        REPORT_PERIOD_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        AMOUNT_UNIT_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ROW_KEY),
        INDEX idx_tmp_b03tt_report_01 (ITEM_CODE),
        INDEX idx_tmp_b03tt_report_02 (SORT_ORDER)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_report
    (
        ROW_KEY,
        COMPANY_CD,
        ROW_TYPE,
        SORT_ORDER,
        ITEM_CODE,
        ITEM_NAME,
        CAPTION,
        LABEL_TEXT,
        NOTE,
        LEVEL_NO,
        FONT_BOLD,
        FONT_ITALIC,
        DATA_SOURCE_TYPE,
        FORMULA_EXPR,
        REPORT_YEAR_TEXT,
        REPORT_PERIOD_TEXT,
        AMOUNT_UNIT_TEXT
    )
    SELECT
        template.ITEM_KEY,
        p_COMPANY_CD,
        template.ELEMENT_TYPE,
        template.SORT_ORDER,
        template.ITEM_CODE,
        -- ITEM_NAME: backward-compat display = indented CAPTION; LABEL_TEXT for future i18n via t_message_info.
        CONCAT(REPEAT('  ', GREATEST(IFNULL(template.LEVEL_NO, 1) - 1, 0)), IFNULL(template.CAPTION, '')),
        template.CAPTION,
        template.LABEL_TEXT,
        '',
        IFNULL(template.LEVEL_NO, 0),
        IFNULL(template.FONT_BOLD, '0'),
        IFNULL(template.FONT_ITALIC, '0'),
        IFNULL(template.DATA_SOURCE_TYPE, ''),
        template.FORMULA_EXPR,
        CASE v_language
            WHEN 'ENG' THEN CONCAT('Year ', YEAR(v_to_date))
            WHEN 'KOR' THEN CONCAT(YEAR(v_to_date), 'ë…„')
            WHEN 'CHN' THEN CONCAT(YEAR(v_to_date), 'å¹´')
            ELSE CONCAT('NÄƒm ', YEAR(v_to_date))
        END,
        CASE v_language
            WHEN 'ENG' THEN
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                     AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT('Year ', YEAR(v_to_date))
                    ELSE CONCAT(
                        'From ',
                        DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        ' to ',
                        DATE_FORMAT(v_to_date, '%d/%m/%Y')
                    )
                END
            WHEN 'KOR' THEN
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                     AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT(YEAR(v_to_date), 'ë…„')
                    ELSE CONCAT(
                        DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        'ë¶€í„° ',
                        DATE_FORMAT(v_to_date, '%d/%m/%Y'),
                        'ê¹Œì§€'
                    )
                END
            WHEN 'CHN' THEN
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                     AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT(YEAR(v_to_date), 'å¹´')
                    ELSE CONCAT(
                        'ä»Ž ',
                        DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        ' è‡³ ',
                        DATE_FORMAT(v_to_date, '%d/%m/%Y')
                    )
                END
            ELSE
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                     AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT('NÄƒm ', YEAR(v_to_date))
                    ELSE CONCAT(
                        'Tá»« ngÃ y ',
                        DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        ' Ä‘áº¿n ngÃ y ',
                        DATE_FORMAT(v_to_date, '%d/%m/%Y')
                    )
                END
        END,
        CASE v_language
            WHEN 'ENG' THEN
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'Unit: million VND'
                    WHEN v_unit_divisor = 1000 THEN 'Unit: thousand VND'
                    ELSE 'Unit: VND'
                END
            WHEN 'KOR' THEN
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'ë‹¨ìœ„: ë°±ë§Œ VND'
                    WHEN v_unit_divisor = 1000 THEN 'ë‹¨ìœ„: ì²œ VND'
                    ELSE 'ë‹¨ìœ„: VND'
                END
            WHEN 'CHN' THEN
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'å•ä½ï¼šç™¾ä¸‡è¶Šå—ç›¾'
                    WHEN v_unit_divisor = 1000 THEN 'å•ä½ï¼šåƒè¶Šå—ç›¾'
                    ELSE 'å•ä½ï¼šè¶Šå—ç›¾'
                END
            ELSE
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'ÄÆ¡n vá»‹ tÃ­nh: triá»‡u Ä‘á»“ng'
                    WHEN v_unit_divisor = 1000 THEN 'ÄÆ¡n vá»‹ tÃ­nh: nghÃ¬n Ä‘á»“ng'
                    ELSE 'ÄÆ¡n vá»‹ tÃ­nh: Ä‘á»“ng'
                END
        END
    FROM report_b03dntt template
    WHERE template.COMPANY_CD = v_template_company_cd
      AND template.REPORT_CODE = 'B03_DN_TT'
      AND template.REPORT_VERSION = v_report_version
      AND template.SECTION_TYPE = 'DETAIL'
      AND IFNULL(template.ISDEL, '0') = '0'
      AND IFNULL(template.IS_VISIBLE, '1') = '1'
    ORDER BY template.SORT_ORDER;

    UPDATE tmp_b03tt_report report
    LEFT JOIN
    (
        SELECT
            ITEM_CODE,
            SUM(CASE WHEN PERIOD_TYPE = 'CURRENT' THEN VALUE_AMOUNT ELSE 0 END) AS CURRENT_YEAR,
            SUM(CASE WHEN PERIOD_TYPE = 'PREVIOUS' THEN VALUE_AMOUNT ELSE 0 END) AS PREVIOUS_YEAR
        FROM tmp_b03tt_amount
        GROUP BY ITEM_CODE
    ) calc
        ON UPPER(calc.ITEM_CODE) = UPPER(report.ITEM_CODE)
    SET
        report.CURRENT_YEAR = NULLIF(ROUND(IFNULL(calc.CURRENT_YEAR, 0) / v_unit_divisor, 0), 0),
        report.PREVIOUS_YEAR = NULLIF(ROUND(IFNULL(calc.PREVIOUS_YEAR, 0) / v_unit_divisor, 0), 0)
    WHERE UPPER(IFNULL(report.DATA_SOURCE_TYPE, '')) = 'PROCEDURE';

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_balance_target;
    CREATE TEMPORARY TABLE tmp_b03tt_balance_target
    (
        TARGET_TYPE VARCHAR(20) NOT NULL,
        BALANCE_YMD VARCHAR(8) NOT NULL,
        PRIMARY KEY (TARGET_TYPE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_balance_target (TARGET_TYPE, BALANCE_YMD)
    VALUES
    ('CURRENT_BEGIN', v_current_begin_ymd),
    ('CURRENT_END', v_to_ymd),
    ('PREVIOUS_BEGIN', v_previous_begin_ymd),
    ('PREVIOUS_END', v_previous_to_ymd);

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_cash_account;
    CREATE TEMPORARY TABLE tmp_b03tt_cash_account
    (
        ACC_CD VARCHAR(20) NOT NULL,
        PRIMARY KEY (ACC_CD)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    /* Danh má»¥c tÃ i khoáº£n tiá»n Ä‘Ã£ khai bÃ¡o. */
    INSERT IGNORE INTO tmp_b03tt_cash_account (ACC_CD)
    SELECT DISTINCT TRIM(ACC_CD)
    FROM acclist_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND IFNULL(ISDEL, '0') = '0'
      AND ACC_CD IS NOT NULL
      AND TRIM(ACC_CD) <> ''
      AND EXISTS
      (
          SELECT 1
          FROM tmp_b03tt_cash_prefix cash_prefix
          WHERE TRIM(ACC_CD) LIKE CONCAT(cash_prefix.ACC_PREFIX, '%')
      );

    /* TÃ i khoáº£n tiá»n tá»«ng cÃ³ sá»‘ dÆ° Ä‘áº§u ká»³. */
    INSERT IGNORE INTO tmp_b03tt_cash_account (ACC_CD)
    SELECT DISTINCT TRIM(ACC_CD)
    FROM before_states
    WHERE COMPANY_CD = p_COMPANY_CD
      AND IFNULL(ISDEL, '0') = '0'
      AND ACC_CD IS NOT NULL
      AND TRIM(ACC_CD) <> ''
      AND EXISTS
      (
          SELECT 1
          FROM tmp_b03tt_cash_prefix cash_prefix
          WHERE TRIM(ACC_CD) LIKE CONCAT(cash_prefix.ACC_PREFIX, '%')
      );

    /*
        Aggregate biáº¿n Ä‘á»™ng sá»‘ dÆ° theo tÃ i khoáº£n + ngÃ y.
        KhÃ´ng cÃ²n giá»¯ tá»«ng dÃ²ng chitdetailinfo trong temporary table.
    */
    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_balance_movement;
    CREATE TEMPORARY TABLE tmp_b03tt_balance_movement
    (
        ACC_CD VARCHAR(20) NOT NULL,
        CHIT_YMD VARCHAR(8) NOT NULL,
        NET_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (ACC_CD, CHIT_YMD),
        INDEX idx_tmp_b03tt_balance_movement_ymd (CHIT_YMD)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    /* Debit - ngÃ y láº¥y trá»±c tiáº¿p tá»« header Ä‘á»ƒ táº­n dá»¥ng index. */
    INSERT INTO tmp_b03tt_balance_movement
    (
        ACC_CD,
        CHIT_YMD,
        NET_AMOUNT
    )
    SELECT
        TRIM(detail.DEBIT) AS ACC_CD,
        header.CHIT_YMD,
        SUM(IFNULL(detail.AMOUNT, 0)) AS NET_AMOUNT
    FROM chitinfo header
    INNER JOIN chitdetailinfo detail
        ON detail.COMPANY_CD = header.COMPANY_CD
       AND detail.CHIT_ID = header.CHIT_ID
       AND detail.ISDEL = '0'
    WHERE header.COMPANY_CD = p_COMPANY_CD
      AND header.ISDEL = '0'
      AND header.CHIT_YMD IS NOT NULL
      AND header.CHIT_YMD <> ''
      AND header.CHIT_YMD <= v_max_to_ymd
      AND detail.DEBIT IS NOT NULL
      AND TRIM(detail.DEBIT) <> ''
      AND EXISTS
      (
          SELECT 1
          FROM tmp_b03tt_cash_prefix cash_prefix
          WHERE TRIM(detail.DEBIT) LIKE CONCAT(cash_prefix.ACC_PREFIX, '%')
      )
    GROUP BY
        TRIM(detail.DEBIT),
        header.CHIT_YMD;

    /* Credit - ngÃ y láº¥y trá»±c tiáº¿p tá»« header Ä‘á»ƒ táº­n dá»¥ng index. */
    INSERT INTO tmp_b03tt_balance_movement
    (
        ACC_CD,
        CHIT_YMD,
        NET_AMOUNT
    )
    SELECT
        TRIM(detail.CREDIT) AS ACC_CD,
        header.CHIT_YMD,
        -SUM(IFNULL(detail.AMOUNT, 0)) AS NET_AMOUNT
    FROM chitinfo header
    INNER JOIN chitdetailinfo detail
        ON detail.COMPANY_CD = header.COMPANY_CD
       AND detail.CHIT_ID = header.CHIT_ID
       AND detail.ISDEL = '0'
    WHERE header.COMPANY_CD = p_COMPANY_CD
      AND header.ISDEL = '0'
      AND header.CHIT_YMD IS NOT NULL
      AND header.CHIT_YMD <> ''
      AND header.CHIT_YMD <= v_max_to_ymd
      AND detail.CREDIT IS NOT NULL
      AND TRIM(detail.CREDIT) <> ''
      AND EXISTS
      (
          SELECT 1
          FROM tmp_b03tt_cash_prefix cash_prefix
          WHERE TRIM(detail.CREDIT) LIKE CONCAT(cash_prefix.ACC_PREFIX, '%')
      )
    GROUP BY
        TRIM(detail.CREDIT),
        header.CHIT_YMD
    ON DUPLICATE KEY UPDATE
        NET_AMOUNT = NET_AMOUNT + VALUES(NET_AMOUNT);

    /*
        Fallback tÆ°Æ¡ng thÃ­ch dá»¯ liá»‡u cÅ©:
        náº¿u header.CHIT_YMD trá»‘ng thÃ¬ dÃ¹ng detail.CHIT_YMD nhÆ° store gá»‘c.
    */
    INSERT INTO tmp_b03tt_balance_movement
    (
        ACC_CD,
        CHIT_YMD,
        NET_AMOUNT
    )
    SELECT
        TRIM(detail.DEBIT) AS ACC_CD,
        TRIM(detail.CHIT_YMD) AS CHIT_YMD,
        SUM(IFNULL(detail.AMOUNT, 0)) AS NET_AMOUNT
    FROM chitinfo header
    INNER JOIN chitdetailinfo detail
        ON detail.COMPANY_CD = header.COMPANY_CD
       AND detail.CHIT_ID = header.CHIT_ID
       AND detail.ISDEL = '0'
    WHERE header.COMPANY_CD = p_COMPANY_CD
      AND header.ISDEL = '0'
      AND (header.CHIT_YMD IS NULL OR TRIM(header.CHIT_YMD) = '')
      AND detail.CHIT_YMD IS NOT NULL
      AND TRIM(detail.CHIT_YMD) <> ''
      AND TRIM(detail.CHIT_YMD) <= v_max_to_ymd
      AND detail.DEBIT IS NOT NULL
      AND TRIM(detail.DEBIT) <> ''
      AND EXISTS
      (
          SELECT 1
          FROM tmp_b03tt_cash_prefix cash_prefix
          WHERE TRIM(detail.DEBIT) LIKE CONCAT(cash_prefix.ACC_PREFIX, '%')
      )
    GROUP BY
        TRIM(detail.DEBIT),
        TRIM(detail.CHIT_YMD)
    ON DUPLICATE KEY UPDATE
        NET_AMOUNT = NET_AMOUNT + VALUES(NET_AMOUNT);

    INSERT INTO tmp_b03tt_balance_movement
    (
        ACC_CD,
        CHIT_YMD,
        NET_AMOUNT
    )
    SELECT
        TRIM(detail.CREDIT) AS ACC_CD,
        TRIM(detail.CHIT_YMD) AS CHIT_YMD,
        -SUM(IFNULL(detail.AMOUNT, 0)) AS NET_AMOUNT
    FROM chitinfo header
    INNER JOIN chitdetailinfo detail
        ON detail.COMPANY_CD = header.COMPANY_CD
       AND detail.CHIT_ID = header.CHIT_ID
       AND detail.ISDEL = '0'
    WHERE header.COMPANY_CD = p_COMPANY_CD
      AND header.ISDEL = '0'
      AND (header.CHIT_YMD IS NULL OR TRIM(header.CHIT_YMD) = '')
      AND detail.CHIT_YMD IS NOT NULL
      AND TRIM(detail.CHIT_YMD) <> ''
      AND TRIM(detail.CHIT_YMD) <= v_max_to_ymd
      AND detail.CREDIT IS NOT NULL
      AND TRIM(detail.CREDIT) <> ''
      AND EXISTS
      (
          SELECT 1
          FROM tmp_b03tt_cash_prefix cash_prefix
          WHERE TRIM(detail.CREDIT) LIKE CONCAT(cash_prefix.ACC_PREFIX, '%')
      )
    GROUP BY
        TRIM(detail.CREDIT),
        TRIM(detail.CHIT_YMD)
    ON DUPLICATE KEY UPDATE
        NET_AMOUNT = NET_AMOUNT + VALUES(NET_AMOUNT);

    /* Bá»• sung cÃ¡c tÃ i khoáº£n chá»‰ xuáº¥t hiá»‡n trong lá»‹ch sá»­ chá»©ng tá»«. */
    INSERT IGNORE INTO tmp_b03tt_cash_account (ACC_CD)
    SELECT DISTINCT ACC_CD
    FROM tmp_b03tt_balance_movement
    WHERE ACC_CD <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_latest_open;
    CREATE TEMPORARY TABLE tmp_b03tt_latest_open
    (
        TARGET_TYPE VARCHAR(20) NOT NULL,
        ACC_CD VARCHAR(20) NOT NULL,
        OPEN_YMD VARCHAR(8) NOT NULL,
        PRIMARY KEY (TARGET_TYPE, ACC_CD)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_latest_open
    (
        TARGET_TYPE,
        ACC_CD,
        OPEN_YMD
    )
    SELECT
        balance_target.TARGET_TYPE,
        cash_account.ACC_CD,
        IFNULL(MAX(before_state.OPEN_YMD), '00000000') AS OPEN_YMD
    FROM tmp_b03tt_balance_target balance_target
    CROSS JOIN tmp_b03tt_cash_account cash_account
    LEFT JOIN before_states before_state
        ON before_state.COMPANY_CD = p_COMPANY_CD
       AND before_state.ACC_CD = cash_account.ACC_CD
       AND IFNULL(before_state.ISDEL, '0') = '0'
       AND IFNULL(before_state.OPEN_YMD, '') <= balance_target.BALANCE_YMD
    GROUP BY
        balance_target.TARGET_TYPE,
        cash_account.ACC_CD;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_open_value;
    CREATE TEMPORARY TABLE tmp_b03tt_open_value
    (
        TARGET_TYPE VARCHAR(20) NOT NULL,
        ACC_CD VARCHAR(20) NOT NULL,
        OPEN_NET DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (TARGET_TYPE, ACC_CD)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_open_value
    (
        TARGET_TYPE,
        ACC_CD,
        OPEN_NET
    )
    SELECT
        latest_open.TARGET_TYPE,
        latest_open.ACC_CD,
        IFNULL(
            SUM(IFNULL(before_state.DEBIT, 0) - IFNULL(before_state.CREDIT, 0)),
            0
        ) AS OPEN_NET
    FROM tmp_b03tt_latest_open latest_open
    LEFT JOIN before_states before_state
        ON before_state.COMPANY_CD = p_COMPANY_CD
       AND before_state.ACC_CD = latest_open.ACC_CD
       AND before_state.OPEN_YMD = latest_open.OPEN_YMD
       AND IFNULL(before_state.ISDEL, '0') = '0'
       AND latest_open.OPEN_YMD <> '00000000'
    GROUP BY
        latest_open.TARGET_TYPE,
        latest_open.ACC_CD;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_move_balance_sum;
    CREATE TEMPORARY TABLE tmp_b03tt_move_balance_sum
    (
        TARGET_TYPE VARCHAR(20) NOT NULL,
        ACC_CD VARCHAR(20) NOT NULL,
        MOVE_NET DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (TARGET_TYPE, ACC_CD)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_move_balance_sum
    (
        TARGET_TYPE,
        ACC_CD,
        MOVE_NET
    )
    SELECT
        latest_open.TARGET_TYPE,
        latest_open.ACC_CD,
        IFNULL(SUM(balance_movement.NET_AMOUNT), 0) AS MOVE_NET
    FROM tmp_b03tt_latest_open latest_open
    INNER JOIN tmp_b03tt_balance_target balance_target
        ON balance_target.TARGET_TYPE = latest_open.TARGET_TYPE
    LEFT JOIN tmp_b03tt_balance_movement balance_movement
        ON balance_movement.ACC_CD = latest_open.ACC_CD
       AND balance_movement.CHIT_YMD >= latest_open.OPEN_YMD
       AND balance_movement.CHIT_YMD <= balance_target.BALANCE_YMD
    GROUP BY
        latest_open.TARGET_TYPE,
        latest_open.ACC_CD;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_cash_balance;
    CREATE TEMPORARY TABLE tmp_b03tt_cash_balance
    (
        TARGET_TYPE VARCHAR(20) NOT NULL,
        BALANCE_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (TARGET_TYPE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_cash_balance
    (
        TARGET_TYPE,
        BALANCE_AMOUNT
    )
    SELECT
        latest_open.TARGET_TYPE,
        SUM(
            IFNULL(open_value.OPEN_NET, 0)
            + IFNULL(move_sum.MOVE_NET, 0)
        ) AS BALANCE_AMOUNT
    FROM tmp_b03tt_latest_open latest_open
    LEFT JOIN tmp_b03tt_open_value open_value
        ON open_value.TARGET_TYPE = latest_open.TARGET_TYPE
       AND open_value.ACC_CD = latest_open.ACC_CD
    LEFT JOIN tmp_b03tt_move_balance_sum move_sum
        ON move_sum.TARGET_TYPE = latest_open.TARGET_TYPE
       AND move_sum.ACC_CD = latest_open.ACC_CD
    GROUP BY latest_open.TARGET_TYPE;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_begin_cash_line;
    CREATE TEMPORARY TABLE tmp_b03tt_begin_cash_line
    (
        CURRENT_BEGIN_AMOUNT DECIMAL(18,2) NULL,
        PREVIOUS_BEGIN_AMOUNT DECIMAL(18,2) NULL
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_begin_cash_line
    (
        CURRENT_BEGIN_AMOUNT,
        PREVIOUS_BEGIN_AMOUNT
    )
    SELECT
        MAX(
            CASE
                WHEN TARGET_TYPE = 'CURRENT_BEGIN' THEN BALANCE_AMOUNT
            END
        ) AS CURRENT_BEGIN_AMOUNT,
        MAX(
            CASE
                WHEN TARGET_TYPE = 'PREVIOUS_BEGIN' THEN BALANCE_AMOUNT
            END
        ) AS PREVIOUS_BEGIN_AMOUNT
    FROM tmp_b03tt_cash_balance;

    UPDATE tmp_b03tt_report report
    CROSS JOIN tmp_b03tt_begin_cash_line begin_cash
    SET
        report.CURRENT_YEAR = NULLIF(ROUND(IFNULL(begin_cash.CURRENT_BEGIN_AMOUNT, 0) / v_unit_divisor, 0), 0),
        report.PREVIOUS_YEAR = NULLIF(ROUND(IFNULL(begin_cash.PREVIOUS_BEGIN_AMOUNT, 0) / v_unit_divisor, 0), 0)
    WHERE report.ITEM_CODE = '60';

    /*
        Parse FORMULA má»™t láº§n vÃ  tÃ¡i sá»­ dá»¥ng cho cáº£ hai lÆ°á»£t tÃ­nh.
    */
    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_formula_expr;
    CREATE TEMPORARY TABLE tmp_b03tt_formula_expr
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        EXPR_TEXT VARCHAR(1000) NULL,
        PRIMARY KEY (ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_formula_expr
    (
        ITEM_CODE,
        EXPR_TEXT
    )
    SELECT
        ITEM_CODE,
        REPLACE(
            REPLACE(
                REPLACE(
                    UPPER(SUBSTRING_INDEX(IFNULL(FORMULA_EXPR, ''), '=', -1)),
                    ' ',
                    ''
                ),
                '-',
                '+-'
            ),
            ';',
            '+'
        ) AS EXPR_TEXT
    FROM tmp_b03tt_report
    WHERE UPPER(IFNULL(DATA_SOURCE_TYPE, '')) = 'FORMULA'
      AND IFNULL(ITEM_CODE, '') <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_formula_term;
    CREATE TEMPORARY TABLE tmp_b03tt_formula_term
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        SIGN_FACTOR INT NOT NULL DEFAULT 1,
        CHILD_ITEM_CODE VARCHAR(50) NOT NULL,
        INDEX idx_tmp_b03tt_formula_term_01 (ITEM_CODE),
        INDEX idx_tmp_b03tt_formula_term_02 (CHILD_ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_formula_term
    (
        ITEM_CODE,
        SIGN_FACTOR,
        CHILD_ITEM_CODE
    )
    SELECT
        raw.ITEM_CODE,
        CASE
            WHEN LEFT(raw.TERM_TEXT, 1) = '-' THEN -1
            ELSE 1
        END AS SIGN_FACTOR,
        REPLACE(raw.TERM_TEXT, '-', '') AS CHILD_ITEM_CODE
    FROM
    (
        SELECT
            formula.ITEM_CODE,
            TRIM(
                SUBSTRING_INDEX(
                    SUBSTRING_INDEX(formula.EXPR_TEXT, '+', numbers.N),
                    '+',
                    -1
                )
            ) AS TERM_TEXT
        FROM tmp_b03tt_formula_expr formula
        INNER JOIN tmp_b03tt_numbers numbers
            ON numbers.N <= 1
                + LENGTH(IFNULL(formula.EXPR_TEXT, ''))
                - LENGTH(REPLACE(IFNULL(formula.EXPR_TEXT, ''), '+', ''))
    ) raw
    WHERE raw.TERM_TEXT <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_formula_calc;
    CREATE TEMPORARY TABLE tmp_b03tt_formula_calc
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        CURRENT_YEAR DECIMAL(18,2) NULL,
        PREVIOUS_YEAR DECIMAL(18,2) NULL,
        PRIMARY KEY (ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    SET v_iteration = 0;

    formula_loop_1: WHILE v_iteration < 8 DO
        TRUNCATE TABLE tmp_b03tt_formula_calc;

        INSERT INTO tmp_b03tt_formula_calc
        (
            ITEM_CODE,
            CURRENT_YEAR,
            PREVIOUS_YEAR
        )
        SELECT
            term.ITEM_CODE,
            SUM(term.SIGN_FACTOR * IFNULL(child.CURRENT_YEAR, 0)) AS CURRENT_YEAR,
            SUM(term.SIGN_FACTOR * IFNULL(child.PREVIOUS_YEAR, 0)) AS PREVIOUS_YEAR
        FROM tmp_b03tt_formula_term term
        INNER JOIN tmp_b03tt_report child
            ON UPPER(child.ITEM_CODE) = UPPER(term.CHILD_ITEM_CODE)
        GROUP BY term.ITEM_CODE;

        UPDATE tmp_b03tt_report report
        INNER JOIN tmp_b03tt_formula_calc calc
            ON UPPER(calc.ITEM_CODE) = UPPER(report.ITEM_CODE)
        SET
            report.CURRENT_YEAR = NULLIF(calc.CURRENT_YEAR, 0),
            report.PREVIOUS_YEAR = NULLIF(calc.PREVIOUS_YEAR, 0)
        WHERE UPPER(IFNULL(report.DATA_SOURCE_TYPE, '')) = 'FORMULA'
          AND
          (
                NOT (report.CURRENT_YEAR <=> NULLIF(calc.CURRENT_YEAR, 0))
             OR NOT (report.PREVIOUS_YEAR <=> NULLIF(calc.PREVIOUS_YEAR, 0))
          );

        SET v_changed_rows = ROW_COUNT();
        SET v_iteration = v_iteration + 1;

        IF v_changed_rows = 0 THEN
            LEAVE formula_loop_1;
        END IF;
    END WHILE formula_loop_1;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_balance_line;
    CREATE TEMPORARY TABLE tmp_b03tt_balance_line
    (
        CURRENT_NET_CASH_FLOW DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PREVIOUS_NET_CASH_FLOW DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        CURRENT_BEGIN_CASH DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PREVIOUS_BEGIN_CASH DECIMAL(18,2) NOT NULL DEFAULT 0.00
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_balance_line
    (
        CURRENT_NET_CASH_FLOW,
        PREVIOUS_NET_CASH_FLOW,
        CURRENT_BEGIN_CASH,
        PREVIOUS_BEGIN_CASH
    )
    SELECT
        IFNULL(MAX(CASE WHEN ITEM_CODE = '50' THEN CURRENT_YEAR END), 0),
        IFNULL(MAX(CASE WHEN ITEM_CODE = '50' THEN PREVIOUS_YEAR END), 0),
        IFNULL(MAX(CASE WHEN ITEM_CODE = '60' THEN CURRENT_YEAR END), 0),
        IFNULL(MAX(CASE WHEN ITEM_CODE = '60' THEN PREVIOUS_YEAR END), 0)
    FROM tmp_b03tt_report;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03tt_end_cash_line;
    CREATE TEMPORARY TABLE tmp_b03tt_end_cash_line
    (
        CURRENT_END_AMOUNT DECIMAL(18,2) NULL,
        PREVIOUS_END_AMOUNT DECIMAL(18,2) NULL
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03tt_end_cash_line
    (
        CURRENT_END_AMOUNT,
        PREVIOUS_END_AMOUNT
    )
    SELECT
        MAX(CASE WHEN TARGET_TYPE = 'CURRENT_END' THEN BALANCE_AMOUNT END),
        MAX(CASE WHEN TARGET_TYPE = 'PREVIOUS_END' THEN BALANCE_AMOUNT END)
    FROM tmp_b03tt_cash_balance;

    UPDATE tmp_b03tt_report report
    CROSS JOIN tmp_b03tt_balance_line balance_line
    CROSS JOIN tmp_b03tt_end_cash_line end_cash
    SET
        report.CURRENT_YEAR = NULLIF(
            ROUND(IFNULL(end_cash.CURRENT_END_AMOUNT, 0) / v_unit_divisor, 0)
            - balance_line.CURRENT_NET_CASH_FLOW
            - balance_line.CURRENT_BEGIN_CASH,
            0
        ),
        report.PREVIOUS_YEAR = NULLIF(
            ROUND(IFNULL(end_cash.PREVIOUS_END_AMOUNT, 0) / v_unit_divisor, 0)
            - balance_line.PREVIOUS_NET_CASH_FLOW
            - balance_line.PREVIOUS_BEGIN_CASH,
            0
        )
    WHERE report.ITEM_CODE = '61';

    /*
        LÆ°á»£t FORMULA thá»© hai sau khi tÃ­nh ITEM_CODE = '61'.
        TÃ¡i sá»­ dá»¥ng tmp_b03tt_formula_term Ä‘Ã£ parse á»Ÿ trÃªn.
    */
    SET v_iteration = 0;

    formula_loop_2: WHILE v_iteration < 4 DO
        TRUNCATE TABLE tmp_b03tt_formula_calc;

        INSERT INTO tmp_b03tt_formula_calc
        (
            ITEM_CODE,
            CURRENT_YEAR,
            PREVIOUS_YEAR
        )
        SELECT
            term.ITEM_CODE,
            SUM(term.SIGN_FACTOR * IFNULL(child.CURRENT_YEAR, 0)) AS CURRENT_YEAR,
            SUM(term.SIGN_FACTOR * IFNULL(child.PREVIOUS_YEAR, 0)) AS PREVIOUS_YEAR
        FROM tmp_b03tt_formula_term term
        INNER JOIN tmp_b03tt_report child
            ON UPPER(child.ITEM_CODE) = UPPER(term.CHILD_ITEM_CODE)
        GROUP BY term.ITEM_CODE;

        UPDATE tmp_b03tt_report report
        INNER JOIN tmp_b03tt_formula_calc calc
            ON UPPER(calc.ITEM_CODE) = UPPER(report.ITEM_CODE)
        SET
            report.CURRENT_YEAR = NULLIF(calc.CURRENT_YEAR, 0),
            report.PREVIOUS_YEAR = NULLIF(calc.PREVIOUS_YEAR, 0)
        WHERE UPPER(IFNULL(report.DATA_SOURCE_TYPE, '')) = 'FORMULA'
          AND
          (
                NOT (report.CURRENT_YEAR <=> NULLIF(calc.CURRENT_YEAR, 0))
             OR NOT (report.PREVIOUS_YEAR <=> NULLIF(calc.PREVIOUS_YEAR, 0))
          );

        SET v_changed_rows = ROW_COUNT();
        SET v_iteration = v_iteration + 1;

        IF v_changed_rows = 0 THEN
            LEAVE formula_loop_2;
        END IF;
    END WHILE formula_loop_2;

    SELECT
        ROW_KEY,
        COMPANY_CD,
        ROW_TYPE,
        ITEM_NAME,
        CAPTION,
        LABEL_TEXT,
        ITEM_CODE,
        NOTE,
        CURRENT_YEAR,
        PREVIOUS_YEAR,
        LEVEL_NO,
        FONT_BOLD,
        FONT_ITALIC,
        DATA_SOURCE_TYPE,
        FORMULA_EXPR,
        REPORT_YEAR_TEXT,
        REPORT_PERIOD_TEXT,
        AMOUNT_UNIT_TEXT
    FROM tmp_b03tt_report
    ORDER BY SORT_ORDER;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_cashflow_b03dn_indirect
DROP PROCEDURE IF EXISTS `rpt_cashflow_b03dn_indirect`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_cashflow_b03dn_indirect`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_REPORT_VERSION VARCHAR(20),
    IN p_UNIT_DIVISOR DECIMAL(18,6),
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_from_date DATE;
    DECLARE v_to_date DATE;
    DECLARE v_previous_from_date DATE;
    DECLARE v_previous_to_date DATE;
    DECLARE v_current_begin_date DATE;
    DECLARE v_previous_begin_date DATE;
    DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_previous_from_ymd VARCHAR(8);
    DECLARE v_previous_to_ymd VARCHAR(8);
    DECLARE v_current_begin_ymd VARCHAR(8);
    DECLARE v_previous_begin_ymd VARCHAR(8);
    DECLARE v_max_to_ymd VARCHAR(8);
    DECLARE v_report_version VARCHAR(20);
    DECLARE v_template_company_cd VARCHAR(20);
    DECLARE v_unit_divisor DECIMAL(18,6);
    DECLARE v_cash_account_prefixes VARCHAR(500);
    DECLARE v_iteration INT DEFAULT 0;
    DECLARE v_changed_rows INT DEFAULT 0;
    DECLARE v_language VARCHAR(20);
    DECLARE v_balance_scan_from_ymd VARCHAR(8);

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;

    SET v_from_date = p_FROM_DATE;
    SET v_to_date = p_TO_DATE;
    SET v_previous_from_date = DATE_SUB(v_from_date, INTERVAL 1 YEAR);
    SET v_previous_to_date = DATE_SUB(v_to_date, INTERVAL 1 YEAR);
    SET v_current_begin_date = DATE_SUB(v_from_date, INTERVAL 1 DAY);
    SET v_previous_begin_date = DATE_SUB(v_previous_from_date, INTERVAL 1 DAY);
    SET v_from_ymd = DATE_FORMAT(v_from_date, '%Y%m%d');
    SET v_to_ymd = DATE_FORMAT(v_to_date, '%Y%m%d');
    SET v_previous_from_ymd = DATE_FORMAT(v_previous_from_date, '%Y%m%d');
    SET v_previous_to_ymd = DATE_FORMAT(v_previous_to_date, '%Y%m%d');
    SET v_current_begin_ymd = DATE_FORMAT(v_current_begin_date, '%Y%m%d');
    SET v_previous_begin_ymd = DATE_FORMAT(v_previous_begin_date, '%Y%m%d');
    SET v_max_to_ymd = IF(v_to_ymd >= v_previous_to_ymd, v_to_ymd, v_previous_to_ymd);
    SET v_report_version = IFNULL(NULLIF(TRIM(IFNULL(p_REPORT_VERSION, '')), ''), '2025');
    SET v_unit_divisor = CASE WHEN IFNULL(p_UNIT_DIVISOR, 0) = 0 THEN 1 ELSE p_UNIT_DIVISOR END;
    SET v_language = UPPER(IFNULL(NULLIF(TRIM(p_LANGUAGE), ''), 'VIET'));

    SELECT COALESCE(
        (
            SELECT template.COMPANY_CD
            FROM report_b03dngt template
            WHERE template.REPORT_CODE = 'B03_DN_GT'
              AND template.REPORT_VERSION = v_report_version
              AND template.COMPANY_CD IN (p_COMPANY_CD, '')
              -- A CONFIG-only override must not shadow the usable DETAIL template.
              AND UPPER(IFNULL(template.SECTION_TYPE, '')) = 'DETAIL'
              AND IFNULL(template.ISDEL, '0') = '0'
            ORDER BY CASE
                WHEN template.COMPANY_CD = p_COMPANY_CD THEN 0
                ELSE 1
            END
            LIMIT 1
        ),
        ''
    )
    INTO v_template_company_cd;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_numbers;
    CREATE TEMPORARY TABLE tmp_b03gt_numbers
    (
        N INT NOT NULL,
        PRIMARY KEY (N)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_numbers (N)
    SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5
    UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10
    UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15
    UNION ALL SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL SELECT 20
    UNION ALL SELECT 21 UNION ALL SELECT 22 UNION ALL SELECT 23 UNION ALL SELECT 24 UNION ALL SELECT 25
    UNION ALL SELECT 26 UNION ALL SELECT 27 UNION ALL SELECT 28 UNION ALL SELECT 29 UNION ALL SELECT 30
    UNION ALL SELECT 31 UNION ALL SELECT 32 UNION ALL SELECT 33 UNION ALL SELECT 34 UNION ALL SELECT 35
    UNION ALL SELECT 36 UNION ALL SELECT 37 UNION ALL SELECT 38 UNION ALL SELECT 39 UNION ALL SELECT 40;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_period;
    CREATE TEMPORARY TABLE tmp_b03gt_period
    (
        PERIOD_TYPE VARCHAR(20) NOT NULL,
        FROM_YMD VARCHAR(8) NOT NULL,
        TO_YMD VARCHAR(8) NOT NULL,
        PRIMARY KEY (PERIOD_TYPE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_period (PERIOD_TYPE, FROM_YMD, TO_YMD)
    VALUES
    ('CURRENT', v_from_ymd, v_to_ymd),
    ('PREVIOUS', v_previous_from_ymd, v_previous_to_ymd);

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_cash_prefix;
    CREATE TEMPORARY TABLE tmp_b03gt_cash_prefix
    (
        ACC_PREFIX VARCHAR(20) NOT NULL,
        PRIMARY KEY (ACC_PREFIX)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    SELECT NULLIF(TRIM(IFNULL(template.ACCOUNT_RULE, '')), '')
    INTO v_cash_account_prefixes
    FROM report_b03dngt template
    WHERE template.COMPANY_CD = v_template_company_cd
      AND template.REPORT_CODE = 'B03_DN_GT'
      AND template.REPORT_VERSION = v_report_version
      AND template.SECTION_TYPE = 'CONFIG'
      AND template.ITEM_KEY = 'CASH_ACCOUNT_PREFIXES'
      AND IFNULL(template.ISDEL, '0') = '0'
    ORDER BY template.ID DESC
    LIMIT 1;

    -- Accept the same comma/semicolon separators as the editable account rules.
    SET v_cash_account_prefixes = REPLACE(IFNULL(v_cash_account_prefixes, '111,112,113'), ';', ',');

    INSERT IGNORE INTO tmp_b03gt_cash_prefix (ACC_PREFIX)
    SELECT TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(v_cash_account_prefixes, ',', numbers.N), ',', -1))
    FROM tmp_b03gt_numbers numbers
    WHERE numbers.N <= 1 + LENGTH(v_cash_account_prefixes) - LENGTH(REPLACE(v_cash_account_prefixes, ',', ''))
      AND TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(v_cash_account_prefixes, ',', numbers.N), ',', -1)) <> '';

    -- MySQL cannot reference the same TEMPORARY TABLE twice in one statement.
    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_cash_prefix_copy;
    CREATE TEMPORARY TABLE tmp_b03gt_cash_prefix_copy
    (
        ACC_PREFIX VARCHAR(20) NOT NULL,
        PRIMARY KEY (ACC_PREFIX)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_cash_prefix_copy (ACC_PREFIX)
    SELECT ACC_PREFIX
    FROM tmp_b03gt_cash_prefix;

    /*
        Tá»‘i Æ°u dá»¯ liá»‡u phÃ¡t sinh:
        - Scan chá»©ng tá»« má»™t láº§n theo tá»«ng PERIOD_TYPE.
        - Aggregate ngay theo PERIOD_TYPE + DEBIT_ACC + CREDIT_ACC.
        - tmp_b03gt_pair Ä‘Æ°á»£c dÃ¹ng láº¡i cho:
            + dÃ²ng tiá»n trá»±c tiáº¿p;
            + biáº¿n Ä‘á»™ng tÃ i khoáº£n cá»§a phÆ°Æ¡ng phÃ¡p giÃ¡n tiáº¿p.
        - Giá»¯ fallback detail.CHIT_YMD khi header.CHIT_YMD trá»‘ng.
    */
    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_pair;
    CREATE TEMPORARY TABLE tmp_b03gt_pair
    (
        PERIOD_TYPE VARCHAR(20) NOT NULL,
        DEBIT_ACC VARCHAR(20) NOT NULL,
        CREDIT_ACC VARCHAR(20) NOT NULL,
        NET_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        ABS_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (PERIOD_TYPE, DEBIT_ACC, CREDIT_ACC),
        INDEX idx_tmp_b03gt_pair_debit (DEBIT_ACC, PERIOD_TYPE),
        INDEX idx_tmp_b03gt_pair_credit (CREDIT_ACC, PERIOD_TYPE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    /* ÄÆ°á»ng chÃ­nh: ngÃ y chá»©ng tá»« náº±m trÃªn header. */
    INSERT INTO tmp_b03gt_pair
    (
        PERIOD_TYPE,
        DEBIT_ACC,
        CREDIT_ACC,
        NET_AMOUNT,
        ABS_AMOUNT
    )
    SELECT
        period.PERIOD_TYPE,
        TRIM(IFNULL(detail.DEBIT, '')) AS DEBIT_ACC,
        TRIM(IFNULL(detail.CREDIT, '')) AS CREDIT_ACC,
        SUM(IFNULL(detail.AMOUNT, 0)) AS NET_AMOUNT,
        SUM(ABS(IFNULL(detail.AMOUNT, 0))) AS ABS_AMOUNT
    FROM tmp_b03gt_period period
    STRAIGHT_JOIN chitinfo header
        ON header.COMPANY_CD = p_COMPANY_CD
       AND header.ISDEL = '0'
       AND header.CHIT_YMD >= period.FROM_YMD
       AND header.CHIT_YMD <= period.TO_YMD
    INNER JOIN chitdetailinfo detail
        ON detail.COMPANY_CD = header.COMPANY_CD
       AND detail.CHIT_ID = header.CHIT_ID
       AND detail.ISDEL = '0'
    GROUP BY
        period.PERIOD_TYPE,
        TRIM(IFNULL(detail.DEBIT, '')),
        TRIM(IFNULL(detail.CREDIT, ''));

    /* Fallback tÆ°Æ¡ng thÃ­ch dá»¯ liá»‡u cÅ©: header ngÃ y trá»‘ng, dÃ¹ng detail.CHIT_YMD. */
    INSERT INTO tmp_b03gt_pair
    (
        PERIOD_TYPE,
        DEBIT_ACC,
        CREDIT_ACC,
        NET_AMOUNT,
        ABS_AMOUNT
    )
    SELECT
        period.PERIOD_TYPE,
        TRIM(IFNULL(detail.DEBIT, '')) AS DEBIT_ACC,
        TRIM(IFNULL(detail.CREDIT, '')) AS CREDIT_ACC,
        SUM(IFNULL(detail.AMOUNT, 0)) AS NET_AMOUNT,
        SUM(ABS(IFNULL(detail.AMOUNT, 0))) AS ABS_AMOUNT
    FROM tmp_b03gt_period period
    STRAIGHT_JOIN chitinfo header
        ON header.COMPANY_CD = p_COMPANY_CD
       AND header.ISDEL = '0'
       AND (header.CHIT_YMD IS NULL OR TRIM(header.CHIT_YMD) = '')
    INNER JOIN chitdetailinfo detail
        ON detail.COMPANY_CD = header.COMPANY_CD
       AND detail.CHIT_ID = header.CHIT_ID
       AND detail.ISDEL = '0'
       AND detail.CHIT_YMD IS NOT NULL
       AND TRIM(detail.CHIT_YMD) >= period.FROM_YMD
       AND TRIM(detail.CHIT_YMD) <= period.TO_YMD
    GROUP BY
        period.PERIOD_TYPE,
        TRIM(IFNULL(detail.DEBIT, '')),
        TRIM(IFNULL(detail.CREDIT, ''))
    ON DUPLICATE KEY UPDATE
        NET_AMOUNT = NET_AMOUNT + VALUES(NET_AMOUNT),
        ABS_AMOUNT = ABS_AMOUNT + VALUES(ABS_AMOUNT);

    /*
        DÃ²ng tiá»n trá»±c tiáº¿p Ä‘Ã£ aggregate theo tÃ i khoáº£n Ä‘á»‘i á»©ng.
        KhÃ´ng cÃ²n MOVEMENT_ID / tá»«ng dÃ²ng chitdetailinfo.
    */
    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_movement;
    CREATE TEMPORARY TABLE tmp_b03gt_movement
    (
        PERIOD_TYPE VARCHAR(20) NOT NULL,
        FLOW_SIGN INT NOT NULL,
        COUNTER_ACC VARCHAR(20) NOT NULL,
        AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (PERIOD_TYPE, FLOW_SIGN, COUNTER_ACC)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    /* Tiá»n vÃ o: Ná»£ tÃ i khoáº£n tiá»n, CÃ³ tÃ i khoáº£n Ä‘á»‘i á»©ng. */
    INSERT INTO tmp_b03gt_movement
    (
        PERIOD_TYPE,
        FLOW_SIGN,
        COUNTER_ACC,
        AMOUNT
    )
    SELECT
        pair.PERIOD_TYPE,
        1 AS FLOW_SIGN,
        pair.CREDIT_ACC AS COUNTER_ACC,
        SUM(pair.ABS_AMOUNT) AS AMOUNT
    FROM tmp_b03gt_pair pair
    WHERE pair.ABS_AMOUNT <> 0
      AND pair.CREDIT_ACC <> ''
      AND EXISTS
      (
          SELECT 1
          FROM tmp_b03gt_cash_prefix cash_prefix
          WHERE pair.DEBIT_ACC LIKE CONCAT(cash_prefix.ACC_PREFIX, '%')
      )
      AND NOT EXISTS
      (
          SELECT 1
          FROM tmp_b03gt_cash_prefix_copy cash_prefix_copy
          WHERE pair.CREDIT_ACC LIKE CONCAT(cash_prefix_copy.ACC_PREFIX, '%')
      )
    GROUP BY
        pair.PERIOD_TYPE,
        pair.CREDIT_ACC;

    /* Tiá»n ra: CÃ³ tÃ i khoáº£n tiá»n, Ná»£ tÃ i khoáº£n Ä‘á»‘i á»©ng. */
    INSERT INTO tmp_b03gt_movement
    (
        PERIOD_TYPE,
        FLOW_SIGN,
        COUNTER_ACC,
        AMOUNT
    )
    SELECT
        pair.PERIOD_TYPE,
        -1 AS FLOW_SIGN,
        pair.DEBIT_ACC AS COUNTER_ACC,
        SUM(pair.ABS_AMOUNT) AS AMOUNT
    FROM tmp_b03gt_pair pair
    WHERE pair.ABS_AMOUNT <> 0
      AND pair.DEBIT_ACC <> ''
      AND EXISTS
      (
          SELECT 1
          FROM tmp_b03gt_cash_prefix cash_prefix
          WHERE pair.CREDIT_ACC LIKE CONCAT(cash_prefix.ACC_PREFIX, '%')
      )
      AND NOT EXISTS
      (
          SELECT 1
          FROM tmp_b03gt_cash_prefix_copy cash_prefix_copy
          WHERE pair.DEBIT_ACC LIKE CONCAT(cash_prefix_copy.ACC_PREFIX, '%')
      )
    GROUP BY
        pair.PERIOD_TYPE,
        pair.DEBIT_ACC;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_direct_rule;
    CREATE TEMPORARY TABLE tmp_b03gt_direct_rule
    (
        ITEM_CODE VARCHAR(20) NOT NULL,
        FLOW_SIGN INT NOT NULL,
        ACC_PREFIX VARCHAR(20) NOT NULL,
        PRIORITY INT NOT NULL,
        INDEX idx_tmp_b03gt_direct_rule_01 (FLOW_SIGN, ACC_PREFIX, PRIORITY)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_direct_rule (ITEM_CODE, FLOW_SIGN, ACC_PREFIX, PRIORITY)
    SELECT
        report.ITEM_CODE,
        report.DIRECT_RULE_FLOW_SIGN AS FLOW_SIGN,
        TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(report.DIRECT_RULE_ACC_PREFIX, ',', numbers.N), ',', -1)) AS ACC_PREFIX,
        report.DIRECT_RULE_PRIORITY AS PRIORITY
    FROM report_b03dngt report
    INNER JOIN tmp_b03gt_numbers numbers
        ON numbers.N <= 1 + LENGTH(IFNULL(report.DIRECT_RULE_ACC_PREFIX, '')) - LENGTH(REPLACE(IFNULL(report.DIRECT_RULE_ACC_PREFIX, ''), ',', ''))
    WHERE report.COMPANY_CD = v_template_company_cd
      AND report.REPORT_CODE = 'B03_DN_GT'
      AND report.REPORT_VERSION = v_report_version
      AND IFNULL(report.ISDEL, '0') = '0'
      AND IFNULL(report.DIRECT_RULE_ACC_PREFIX, '') <> '';

    INSERT INTO tmp_b03gt_direct_rule (ITEM_CODE, FLOW_SIGN, ACC_PREFIX, PRIORITY)
    SELECT
        report.ITEM_CODE,
        report.DIRECT_RULE_FLOW_SIGN_2 AS FLOW_SIGN,
        TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(report.DIRECT_RULE_ACC_PREFIX_2, ',', numbers.N), ',', -1)) AS ACC_PREFIX,
        report.DIRECT_RULE_PRIORITY_2 AS PRIORITY
    FROM report_b03dngt report
    INNER JOIN tmp_b03gt_numbers numbers
        ON numbers.N <= 1 + LENGTH(IFNULL(report.DIRECT_RULE_ACC_PREFIX_2, '')) - LENGTH(REPLACE(IFNULL(report.DIRECT_RULE_ACC_PREFIX_2, ''), ',', ''))
    WHERE report.COMPANY_CD = v_template_company_cd
      AND report.REPORT_CODE = 'B03_DN_GT'
      AND report.REPORT_VERSION = v_report_version
      AND IFNULL(report.ISDEL, '0') = '0'
      AND IFNULL(report.DIRECT_RULE_ACC_PREFIX_2, '') <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_direct_rule_copy;
    CREATE TEMPORARY TABLE tmp_b03gt_direct_rule_copy
    (
        ITEM_CODE VARCHAR(20) NOT NULL,
        FLOW_SIGN INT NOT NULL,
        ACC_PREFIX VARCHAR(20) NOT NULL,
        PRIORITY INT NOT NULL,
        INDEX idx_tmp_b03gt_direct_rule_copy_01
            (FLOW_SIGN, ACC_PREFIX, PRIORITY)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_direct_rule_copy
    (
        ITEM_CODE,
        FLOW_SIGN,
        ACC_PREFIX,
        PRIORITY
    )
    SELECT
        ITEM_CODE,
        FLOW_SIGN,
        ACC_PREFIX,
        PRIORITY
    FROM tmp_b03gt_direct_rule;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_direct_match;
    CREATE TEMPORARY TABLE tmp_b03gt_direct_match
    (
        PERIOD_TYPE VARCHAR(20) NOT NULL,
        FLOW_SIGN INT NOT NULL,
        COUNTER_ACC VARCHAR(20) NOT NULL,
        ITEM_CODE VARCHAR(20) NOT NULL,
        INDEX idx_tmp_b03gt_direct_match_01
            (PERIOD_TYPE, FLOW_SIGN, COUNTER_ACC, ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_direct_match
    (
        PERIOD_TYPE,
        FLOW_SIGN,
        COUNTER_ACC,
        ITEM_CODE
    )
    SELECT
        movement.PERIOD_TYPE,
        movement.FLOW_SIGN,
        movement.COUNTER_ACC,
        rule.ITEM_CODE
    FROM tmp_b03gt_movement movement
    INNER JOIN tmp_b03gt_direct_rule rule
        ON rule.FLOW_SIGN = movement.FLOW_SIGN
       AND movement.COUNTER_ACC LIKE CONCAT(rule.ACC_PREFIX, '%')
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM tmp_b03gt_direct_rule_copy better_rule
        WHERE better_rule.FLOW_SIGN = movement.FLOW_SIGN
          AND movement.COUNTER_ACC LIKE CONCAT(better_rule.ACC_PREFIX, '%')
          AND better_rule.PRIORITY < rule.PRIORITY
    );

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_direct_rule_copy;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_direct_amount;
    CREATE TEMPORARY TABLE tmp_b03gt_direct_amount
    (
        ITEM_CODE VARCHAR(20) NOT NULL,
        PERIOD_TYPE VARCHAR(20) NOT NULL,
        VALUE_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (ITEM_CODE, PERIOD_TYPE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_direct_amount
    (
        ITEM_CODE,
        PERIOD_TYPE,
        VALUE_AMOUNT
    )
    SELECT
        COALESCE(
            direct_match.ITEM_CODE,
            CASE
                WHEN movement.FLOW_SIGN = 1 THEN '06'
                ELSE '07'
            END
        ) AS ITEM_CODE,
        movement.PERIOD_TYPE,
        SUM(
            CASE
                WHEN movement.FLOW_SIGN = 1 THEN movement.AMOUNT
                ELSE -movement.AMOUNT
            END
        ) AS VALUE_AMOUNT
    FROM tmp_b03gt_movement movement
    LEFT JOIN tmp_b03gt_direct_match direct_match
        ON direct_match.PERIOD_TYPE = movement.PERIOD_TYPE
       AND direct_match.FLOW_SIGN = movement.FLOW_SIGN
       AND direct_match.COUNTER_ACC = movement.COUNTER_ACC
    GROUP BY
        COALESCE(
            direct_match.ITEM_CODE,
            CASE
                WHEN movement.FLOW_SIGN = 1 THEN '06'
                ELSE '07'
            END
        ),
        movement.PERIOD_TYPE;

    /*
        Biáº¿n Ä‘á»™ng tÃ i khoáº£n cho phÆ°Æ¡ng phÃ¡p giÃ¡n tiáº¿p.
        TÃ¡i sá»­ dá»¥ng tmp_b03gt_pair, khÃ´ng scan chitinfo/chitdetailinfo láº§n ná»¯a.
    */
    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_account_period;
    CREATE TEMPORARY TABLE tmp_b03gt_account_period
    (
        ACC_CD VARCHAR(20) NOT NULL,
        PERIOD_TYPE VARCHAR(20) NOT NULL,
        NET_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (ACC_CD, PERIOD_TYPE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    /* Debit side */
    INSERT INTO tmp_b03gt_account_period
    (
        ACC_CD,
        PERIOD_TYPE,
        NET_AMOUNT
    )
    SELECT
        pair.DEBIT_ACC,
        pair.PERIOD_TYPE,
        SUM(pair.NET_AMOUNT) AS NET_AMOUNT
    FROM tmp_b03gt_pair pair
    WHERE pair.DEBIT_ACC <> ''
    GROUP BY
        pair.DEBIT_ACC,
        pair.PERIOD_TYPE;

    /* Credit side */
    INSERT INTO tmp_b03gt_account_period
    (
        ACC_CD,
        PERIOD_TYPE,
        NET_AMOUNT
    )
    SELECT
        pair.CREDIT_ACC,
        pair.PERIOD_TYPE,
        -SUM(pair.NET_AMOUNT) AS NET_AMOUNT
    FROM tmp_b03gt_pair pair
    WHERE pair.CREDIT_ACC <> ''
    GROUP BY
        pair.CREDIT_ACC,
        pair.PERIOD_TYPE
    ON DUPLICATE KEY UPDATE
        NET_AMOUNT = NET_AMOUNT + VALUES(NET_AMOUNT);

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_indirect_rule;
    CREATE TEMPORARY TABLE tmp_b03gt_indirect_rule
    (
        ITEM_CODE VARCHAR(20) NOT NULL,
        ACC_PREFIX VARCHAR(20) NOT NULL,
        SIGN_FACTOR INT NOT NULL,
        INDEX idx_tmp_b03gt_indirect_rule_01 (ACC_PREFIX, ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    -- ACCOUNT_RULE allows each tenant to override the default indirect-account rule.
    -- Syntax: +511,+515,-632 (multiple account prefixes separated by comma or semicolon).
    INSERT INTO tmp_b03gt_indirect_rule (ITEM_CODE, ACC_PREFIX, SIGN_FACTOR)
    SELECT
        configured_rule.ITEM_CODE,
        TRIM(REPLACE(REPLACE(configured_rule.TERM_TEXT, '+', ''), '-', '')) AS ACC_PREFIX,
        CASE WHEN LEFT(configured_rule.TERM_TEXT, 1) = '-' THEN -1 ELSE 1 END AS SIGN_FACTOR
    FROM
    (
        SELECT
            template.ITEM_CODE,
            TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(REPLACE(IFNULL(template.ACCOUNT_RULE, ''), ';', ','), ',', numbers.N), ',', -1)) AS TERM_TEXT
        FROM report_b03dngt template
        INNER JOIN tmp_b03gt_numbers numbers
            ON numbers.N <= 1 + LENGTH(REPLACE(IFNULL(template.ACCOUNT_RULE, ''), ';', ','))
                - LENGTH(REPLACE(REPLACE(IFNULL(template.ACCOUNT_RULE, ''), ';', ','), ',', ''))
        WHERE template.COMPANY_CD = v_template_company_cd
          AND template.REPORT_CODE = 'B03_DN_GT'
          AND template.REPORT_VERSION = v_report_version
          AND template.SECTION_TYPE = 'DETAIL'
          AND IFNULL(template.ISDEL, '0') = '0'
          AND NULLIF(TRIM(IFNULL(template.ACCOUNT_RULE, '')), '') IS NOT NULL
    ) configured_rule
    WHERE configured_rule.TERM_TEXT <> ''
      AND TRIM(REPLACE(REPLACE(configured_rule.TERM_TEXT, '+', ''), '-', '')) <> '';

    -- Keep the official default rules for rows that have not been overridden in the template.
    INSERT INTO tmp_b03gt_indirect_rule (ITEM_CODE, ACC_PREFIX, SIGN_FACTOR)
    SELECT default_rule.ITEM_CODE, default_rule.ACC_PREFIX, default_rule.SIGN_FACTOR
    FROM
    (
        SELECT '01' AS ITEM_CODE, '511' AS ACC_PREFIX, -1 AS SIGN_FACTOR
        UNION ALL SELECT '01', '515', -1
        UNION ALL SELECT '01', '632', -1
        UNION ALL SELECT '01', '635', -1
        UNION ALL SELECT '01', '641', -1
        UNION ALL SELECT '01', '642', -1
        UNION ALL SELECT '01', '711', -1
        UNION ALL SELECT '01', '811', -1
        UNION ALL SELECT '02', '214', -1
        UNION ALL SELECT '03', '229', -1
        UNION ALL SELECT '03', '352', -1
        UNION ALL SELECT '04', '413', -1
        UNION ALL SELECT '05', '515', 1
        UNION ALL SELECT '05', '711', 1
        UNION ALL SELECT '05', '811', 1
        UNION ALL SELECT '06', '635', 1
        UNION ALL SELECT '09', '131', -1
        UNION ALL SELECT '09', '136', -1
        UNION ALL SELECT '09', '138', -1
        UNION ALL SELECT '09', '141', -1
        UNION ALL SELECT '10', '151', -1
        UNION ALL SELECT '10', '152', -1
        UNION ALL SELECT '10', '153', -1
        UNION ALL SELECT '10', '154', -1
        UNION ALL SELECT '10', '155', -1
        UNION ALL SELECT '10', '156', -1
        UNION ALL SELECT '10', '157', -1
        UNION ALL SELECT '11', '331', -1
        UNION ALL SELECT '11', '333', -1
        UNION ALL SELECT '11', '334', -1
        UNION ALL SELECT '11', '335', -1
        UNION ALL SELECT '11', '336', -1
        UNION ALL SELECT '11', '337', -1
        UNION ALL SELECT '11', '338', -1
        UNION ALL SELECT '12', '242', -1
        UNION ALL SELECT '13', '121', -1
    ) default_rule
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM report_b03dngt template
        WHERE template.COMPANY_CD = v_template_company_cd
          AND template.REPORT_CODE = 'B03_DN_GT'
          AND template.REPORT_VERSION = v_report_version
          AND template.SECTION_TYPE = 'DETAIL'
          AND template.ITEM_CODE = default_rule.ITEM_CODE
          AND IFNULL(template.ISDEL, '0') = '0'
          AND NULLIF(TRIM(IFNULL(template.ACCOUNT_RULE, '')), '') IS NOT NULL
    );

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_indirect_amount;
    CREATE TEMPORARY TABLE tmp_b03gt_indirect_amount
    (
        ITEM_CODE VARCHAR(20) NOT NULL,
        PERIOD_TYPE VARCHAR(20) NOT NULL,
        VALUE_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (ITEM_CODE, PERIOD_TYPE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_indirect_amount
    (
        ITEM_CODE,
        PERIOD_TYPE,
        VALUE_AMOUNT
    )
    SELECT
        rule.ITEM_CODE,
        account_period.PERIOD_TYPE,
        SUM(rule.SIGN_FACTOR * account_period.NET_AMOUNT) AS VALUE_AMOUNT
    FROM tmp_b03gt_account_period account_period
    INNER JOIN tmp_b03gt_indirect_rule rule
        ON account_period.ACC_CD LIKE CONCAT(rule.ACC_PREFIX, '%')
    GROUP BY
        rule.ITEM_CODE,
        account_period.PERIOD_TYPE;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_direct_map;
    CREATE TEMPORARY TABLE tmp_b03gt_direct_map
    (
        TARGET_ITEM_CODE VARCHAR(20) NOT NULL,
        SOURCE_ITEM_CODE VARCHAR(20) NOT NULL,
        PRIMARY KEY (TARGET_ITEM_CODE, SOURCE_ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

