    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_mapped_direct_amount;
    CREATE TEMPORARY TABLE tmp_b03gt_mapped_direct_amount
    (
        ITEM_CODE VARCHAR(20) NOT NULL,
        PERIOD_TYPE VARCHAR(20) NOT NULL,
        VALUE_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (ITEM_CODE, PERIOD_TYPE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_mapped_direct_amount
    (
        ITEM_CODE,
        PERIOD_TYPE,
        VALUE_AMOUNT
    )
    SELECT
        direct_map.TARGET_ITEM_CODE AS ITEM_CODE,
        direct_amount.PERIOD_TYPE,
        SUM(direct_amount.VALUE_AMOUNT) AS VALUE_AMOUNT
    FROM tmp_b03gt_direct_amount direct_amount
    INNER JOIN tmp_b03gt_direct_map direct_map
        ON direct_map.SOURCE_ITEM_CODE = direct_amount.ITEM_CODE
    GROUP BY
        direct_map.TARGET_ITEM_CODE,
        direct_amount.PERIOD_TYPE;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_report_amount;
    CREATE TEMPORARY TABLE tmp_b03gt_report_amount
    (
        ITEM_CODE VARCHAR(20) NOT NULL,
        PERIOD_TYPE VARCHAR(20) NOT NULL,
        VALUE_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        INDEX idx_tmp_b03gt_report_amount_01 (ITEM_CODE, PERIOD_TYPE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_report_amount
    (
        ITEM_CODE,
        PERIOD_TYPE,
        VALUE_AMOUNT
    )
    SELECT
        ITEM_CODE,
        PERIOD_TYPE,
        VALUE_AMOUNT
    FROM tmp_b03gt_indirect_amount;

    INSERT INTO tmp_b03gt_report_amount
    (
        ITEM_CODE,
        PERIOD_TYPE,
        VALUE_AMOUNT
    )
    SELECT
        ITEM_CODE,
        PERIOD_TYPE,
        VALUE_AMOUNT
    FROM tmp_b03gt_mapped_direct_amount;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_report;
    CREATE TEMPORARY TABLE tmp_b03gt_report
    (
        ROW_KEY VARCHAR(80) NOT NULL DEFAULT '',
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        ROW_TYPE VARCHAR(30) NOT NULL DEFAULT '',
        SORT_ORDER INT NOT NULL DEFAULT 0,
        ITEM_CODE VARCHAR(50) NULL,
        ITEM_NAME VARCHAR(1000) NULL,
        CAPTION VARCHAR(1000) NULL,
        LABEL_TEXT VARCHAR(200) NULL,
        NOTE VARCHAR(100) NOT NULL DEFAULT '',
        CURRENT_YEAR DECIMAL(18,2) NULL,
        PREVIOUS_YEAR DECIMAL(18,2) NULL,
        LEVEL_NO INT NOT NULL DEFAULT 0,
        FONT_BOLD CHAR(1) NOT NULL DEFAULT '0',
        FONT_ITALIC CHAR(1) NOT NULL DEFAULT '0',
        DATA_SOURCE_TYPE VARCHAR(50) NULL,
        FORMULA_EXPR VARCHAR(1000) NULL,
        REPORT_YEAR_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        REPORT_PERIOD_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        AMOUNT_UNIT_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ROW_KEY),
        INDEX idx_tmp_b03gt_report_01 (ITEM_CODE),
        INDEX idx_tmp_b03gt_report_02 (SORT_ORDER)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_report
    (
        ROW_KEY,
        COMPANY_CD,
        ROW_TYPE,
        SORT_ORDER,
        ITEM_CODE,
        ITEM_NAME,
        CAPTION,
        LABEL_TEXT,
        NOTE,
        LEVEL_NO,
        FONT_BOLD,
        FONT_ITALIC,
        DATA_SOURCE_TYPE,
        FORMULA_EXPR,
        REPORT_YEAR_TEXT,
        REPORT_PERIOD_TEXT,
        AMOUNT_UNIT_TEXT
    )
    SELECT
        template.ITEM_KEY,
        p_COMPANY_CD,
        template.ELEMENT_TYPE,
        template.SORT_ORDER,
        template.ITEM_CODE,
        -- ITEM_NAME: backward-compat display = indented CAPTION; LABEL_TEXT for future i18n via t_message_info.
        CONCAT(REPEAT('  ', GREATEST(IFNULL(template.LEVEL_NO, 1) - 1, 0)), IFNULL(template.CAPTION, '')),
        template.CAPTION,
        template.LABEL_TEXT,
        '',
        IFNULL(template.LEVEL_NO, 0),
        IFNULL(template.FONT_BOLD, '0'),
        IFNULL(template.FONT_ITALIC, '0'),
        IFNULL(template.DATA_SOURCE_TYPE, ''),
        template.FORMULA_EXPR,
        CASE v_language
            WHEN 'ENG' THEN CONCAT('Year ', YEAR(v_to_date))
            WHEN 'KOR' THEN CONCAT(YEAR(v_to_date), 'ë…„')
            WHEN 'CHN' THEN CONCAT(YEAR(v_to_date), 'å¹´')
            ELSE CONCAT('NÄƒm ', YEAR(v_to_date))
        END,
        CASE v_language
            WHEN 'ENG' THEN
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                     AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT('Year ', YEAR(v_to_date))
                    ELSE CONCAT(
                        'From ',
                        DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        ' to ',
                        DATE_FORMAT(v_to_date, '%d/%m/%Y')
                    )
                END
            WHEN 'KOR' THEN
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                     AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT(YEAR(v_to_date), 'ë…„')
                    ELSE CONCAT(
                        DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        'ë¶€í„° ',
                        DATE_FORMAT(v_to_date, '%d/%m/%Y'),
                        'ê¹Œì§€'
                    )
                END
            WHEN 'CHN' THEN
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                     AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT(YEAR(v_to_date), 'å¹´')
                    ELSE CONCAT(
                        'ä»Ž ',
                        DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        ' è‡³ ',
                        DATE_FORMAT(v_to_date, '%d/%m/%Y')
                    )
                END
            ELSE
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                     AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT('NÄƒm ', YEAR(v_to_date))
                    ELSE CONCAT(
                        'Tá»« ngÃ y ',
                        DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        ' Ä‘áº¿n ngÃ y ',
                        DATE_FORMAT(v_to_date, '%d/%m/%Y')
                    )
                END
        END,
        CASE v_language
            WHEN 'ENG' THEN
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'Unit: million VND'
                    WHEN v_unit_divisor = 1000 THEN 'Unit: thousand VND'
                    ELSE 'Unit: VND'
                END
            WHEN 'KOR' THEN
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'ë‹¨ìœ„: ë°±ë§Œ VND'
                    WHEN v_unit_divisor = 1000 THEN 'ë‹¨ìœ„: ì²œ VND'
                    ELSE 'ë‹¨ìœ„: VND'
                END
            WHEN 'CHN' THEN
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'å•ä½ï¼šç™¾ä¸‡è¶Šå—ç›¾'
                    WHEN v_unit_divisor = 1000 THEN 'å•ä½ï¼šåƒè¶Šå—ç›¾'
                    ELSE 'å•ä½ï¼šè¶Šå—ç›¾'
                END
            ELSE
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'ÄÆ¡n vá»‹ tÃ­nh: triá»‡u Ä‘á»“ng'
                    WHEN v_unit_divisor = 1000 THEN 'ÄÆ¡n vá»‹ tÃ­nh: nghÃ¬n Ä‘á»“ng'
                    ELSE 'ÄÆ¡n vá»‹ tÃ­nh: Ä‘á»“ng'
                END
        END
    FROM report_b03dngt template
    WHERE template.COMPANY_CD = v_template_company_cd
      AND template.REPORT_CODE = 'B03_DN_GT'
      AND template.REPORT_VERSION = v_report_version
      AND template.SECTION_TYPE = 'DETAIL'
      AND IFNULL(template.ISDEL, '0') = '0'
      AND IFNULL(template.IS_VISIBLE, '1') = '1'
    ORDER BY template.SORT_ORDER;

    UPDATE tmp_b03gt_report report
    LEFT JOIN
    (
        SELECT
            ITEM_CODE,
            SUM(CASE WHEN PERIOD_TYPE = 'CURRENT' THEN VALUE_AMOUNT ELSE 0 END) AS CURRENT_YEAR,
            SUM(CASE WHEN PERIOD_TYPE = 'PREVIOUS' THEN VALUE_AMOUNT ELSE 0 END) AS PREVIOUS_YEAR
        FROM tmp_b03gt_report_amount
        GROUP BY ITEM_CODE
    ) calc
        ON UPPER(calc.ITEM_CODE) = UPPER(report.ITEM_CODE)
    SET
        report.CURRENT_YEAR = NULLIF(ROUND(IFNULL(calc.CURRENT_YEAR, 0) / v_unit_divisor, 0), 0),
        report.PREVIOUS_YEAR = NULLIF(ROUND(IFNULL(calc.PREVIOUS_YEAR, 0) / v_unit_divisor, 0), 0)
    WHERE UPPER(IFNULL(report.DATA_SOURCE_TYPE, '')) = 'PROCEDURE';

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_balance_target;
    CREATE TEMPORARY TABLE tmp_b03gt_balance_target
    (
        TARGET_TYPE VARCHAR(20) NOT NULL,
        BALANCE_YMD VARCHAR(8) NOT NULL,
        PRIMARY KEY (TARGET_TYPE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_balance_target (TARGET_TYPE, BALANCE_YMD)
    VALUES
    ('CURRENT_BEGIN', v_current_begin_ymd),
    ('CURRENT_END', v_to_ymd),
    ('PREVIOUS_BEGIN', v_previous_begin_ymd),
    ('PREVIOUS_END', v_previous_to_ymd);

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_cash_account;
    CREATE TEMPORARY TABLE tmp_b03gt_cash_account
    (
        ACC_CD VARCHAR(20) NOT NULL,
        PRIMARY KEY (ACC_CD)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    /* Danh má»¥c tÃ i khoáº£n tiá»n. */
    INSERT IGNORE INTO tmp_b03gt_cash_account (ACC_CD)
    SELECT DISTINCT TRIM(ACC_CD)
    FROM acclist_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND IFNULL(ISDEL, '0') = '0'
      AND ACC_CD IS NOT NULL
      AND TRIM(ACC_CD) <> ''
      AND EXISTS
      (
          SELECT 1
          FROM tmp_b03gt_cash_prefix cash_prefix
          WHERE TRIM(ACC_CD) LIKE CONCAT(cash_prefix.ACC_PREFIX, '%')
      );

    /* TÃ i khoáº£n tiá»n tá»«ng cÃ³ sá»‘ dÆ° Ä‘áº§u ká»³. */
    INSERT IGNORE INTO tmp_b03gt_cash_account (ACC_CD)
    SELECT DISTINCT TRIM(ACC_CD)
    FROM before_states
    WHERE COMPANY_CD = p_COMPANY_CD
      AND IFNULL(ISDEL, '0') = '0'
      AND ACC_CD IS NOT NULL
      AND TRIM(ACC_CD) <> ''
      AND EXISTS
      (
          SELECT 1
          FROM tmp_b03gt_cash_prefix cash_prefix
          WHERE TRIM(ACC_CD) LIKE CONCAT(cash_prefix.ACC_PREFIX, '%')
      );

    /*
        Bá»• sung tÃ i khoáº£n chá»‰ xuáº¥t hiá»‡n trong chá»©ng tá»«.
        Scan chitdetailinfo má»™t láº§n cho cáº£ DEBIT/CREDIT nhá» tmp_b03gt_numbers N=1..2.
    */
    INSERT IGNORE INTO tmp_b03gt_cash_account (ACC_CD)
    SELECT DISTINCT
        CASE
            WHEN side.N = 1 THEN TRIM(IFNULL(detail.DEBIT, ''))
            ELSE TRIM(IFNULL(detail.CREDIT, ''))
        END AS ACC_CD
    FROM chitdetailinfo detail
    INNER JOIN tmp_b03gt_numbers side
        ON side.N <= 2
    WHERE detail.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(detail.ISDEL, '0') = '0'
      AND
      (
          CASE
              WHEN side.N = 1 THEN TRIM(IFNULL(detail.DEBIT, ''))
              ELSE TRIM(IFNULL(detail.CREDIT, ''))
          END
      ) <> ''
      AND EXISTS
      (
          SELECT 1
          FROM tmp_b03gt_cash_prefix cash_prefix
          WHERE
              CASE
                  WHEN side.N = 1 THEN TRIM(IFNULL(detail.DEBIT, ''))
                  ELSE TRIM(IFNULL(detail.CREDIT, ''))
              END LIKE CONCAT(cash_prefix.ACC_PREFIX, '%')
      );

    /*
        XÃ¡c Ä‘á»‹nh opening date trÆ°á»›c khi scan biáº¿n Ä‘á»™ng sá»‘ dÆ°.
        Nhá» Ä‘Ã³ cÃ³ thá»ƒ bá» pháº§n lá»‹ch sá»­ trÆ°á»›c opening balance gáº§n nháº¥t.
    */
    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_latest_open;
    CREATE TEMPORARY TABLE tmp_b03gt_latest_open
    (
        TARGET_TYPE VARCHAR(20) NOT NULL,
        ACC_CD VARCHAR(20) NOT NULL,
        OPEN_YMD VARCHAR(8) NOT NULL,
        PRIMARY KEY (TARGET_TYPE, ACC_CD)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_latest_open
    (
        TARGET_TYPE,
        ACC_CD,
        OPEN_YMD
    )
    SELECT
        balance_target.TARGET_TYPE,
        cash_account.ACC_CD,
        IFNULL(MAX(before_state.OPEN_YMD), '00000000') AS OPEN_YMD
    FROM tmp_b03gt_balance_target balance_target
    CROSS JOIN tmp_b03gt_cash_account cash_account
    LEFT JOIN before_states before_state
        ON before_state.COMPANY_CD = p_COMPANY_CD
       AND before_state.ACC_CD = cash_account.ACC_CD
       AND IFNULL(before_state.ISDEL, '0') = '0'
       AND IFNULL(before_state.OPEN_YMD, '') <= balance_target.BALANCE_YMD
    GROUP BY
        balance_target.TARGET_TYPE,
        cash_account.ACC_CD;

    SELECT
        CASE
            WHEN SUM(CASE WHEN OPEN_YMD = '00000000' THEN 1 ELSE 0 END) > 0
                THEN '00000000'
            ELSE MIN(OPEN_YMD)
        END
    INTO v_balance_scan_from_ymd
    FROM tmp_b03gt_latest_open;

    SET v_balance_scan_from_ymd = IFNULL(v_balance_scan_from_ymd, '00000000');

    /*
        Biáº¿n Ä‘á»™ng sá»‘ dÆ° Ä‘Æ°á»£c aggregate theo ACC_CD + CHIT_YMD.
        KhÃ´ng giá»¯ tá»«ng dÃ²ng chá»©ng tá»« trong temporary table.
    */
    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_balance_movement;
    CREATE TEMPORARY TABLE tmp_b03gt_balance_movement
    (
        ACC_CD VARCHAR(20) NOT NULL,
        CHIT_YMD VARCHAR(8) NOT NULL,
        NET_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (ACC_CD, CHIT_YMD),
        INDEX idx_tmp_b03gt_balance_movement_ymd (CHIT_YMD)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    /* Debit - Ä‘Æ°á»ng chÃ­nh dÃ¹ng ngÃ y header. */
    INSERT INTO tmp_b03gt_balance_movement
    (
        ACC_CD,
        CHIT_YMD,
        NET_AMOUNT
    )
    SELECT
        cash_account.ACC_CD,
        header.CHIT_YMD,
        SUM(IFNULL(detail.AMOUNT, 0)) AS NET_AMOUNT
    FROM chitinfo header
    INNER JOIN chitdetailinfo detail
        ON detail.COMPANY_CD = header.COMPANY_CD
       AND detail.CHIT_ID = header.CHIT_ID
       AND detail.ISDEL = '0'
    INNER JOIN tmp_b03gt_cash_account cash_account
        ON cash_account.ACC_CD = TRIM(detail.DEBIT)
    WHERE header.COMPANY_CD = p_COMPANY_CD
      AND header.ISDEL = '0'
      AND header.CHIT_YMD IS NOT NULL
      AND header.CHIT_YMD <> ''
      AND header.CHIT_YMD >= v_balance_scan_from_ymd
      AND header.CHIT_YMD <= v_max_to_ymd
    GROUP BY
        cash_account.ACC_CD,
        header.CHIT_YMD;

    /* Credit - Ä‘Æ°á»ng chÃ­nh dÃ¹ng ngÃ y header. */
    INSERT INTO tmp_b03gt_balance_movement
    (
        ACC_CD,
        CHIT_YMD,
        NET_AMOUNT
    )
    SELECT
        cash_account.ACC_CD,
        header.CHIT_YMD,
        -SUM(IFNULL(detail.AMOUNT, 0)) AS NET_AMOUNT
    FROM chitinfo header
    INNER JOIN chitdetailinfo detail
        ON detail.COMPANY_CD = header.COMPANY_CD
       AND detail.CHIT_ID = header.CHIT_ID
       AND detail.ISDEL = '0'
    INNER JOIN tmp_b03gt_cash_account cash_account
        ON cash_account.ACC_CD = TRIM(detail.CREDIT)
    WHERE header.COMPANY_CD = p_COMPANY_CD
      AND header.ISDEL = '0'
      AND header.CHIT_YMD IS NOT NULL
      AND header.CHIT_YMD <> ''
      AND header.CHIT_YMD >= v_balance_scan_from_ymd
      AND header.CHIT_YMD <= v_max_to_ymd
    GROUP BY
        cash_account.ACC_CD,
        header.CHIT_YMD
    ON DUPLICATE KEY UPDATE
        NET_AMOUNT = NET_AMOUNT + VALUES(NET_AMOUNT);

    /* Fallback dá»¯ liá»‡u cÅ©: header.CHIT_YMD trá»‘ng, dÃ¹ng detail.CHIT_YMD. */
    INSERT INTO tmp_b03gt_balance_movement
    (
        ACC_CD,
        CHIT_YMD,
        NET_AMOUNT
    )
    SELECT
        cash_account.ACC_CD,
        TRIM(detail.CHIT_YMD),
        SUM(IFNULL(detail.AMOUNT, 0)) AS NET_AMOUNT
    FROM chitinfo header
    INNER JOIN chitdetailinfo detail
        ON detail.COMPANY_CD = header.COMPANY_CD
       AND detail.CHIT_ID = header.CHIT_ID
       AND detail.ISDEL = '0'
    INNER JOIN tmp_b03gt_cash_account cash_account
        ON cash_account.ACC_CD = TRIM(detail.DEBIT)
    WHERE header.COMPANY_CD = p_COMPANY_CD
      AND header.ISDEL = '0'
      AND (header.CHIT_YMD IS NULL OR TRIM(header.CHIT_YMD) = '')
      AND detail.CHIT_YMD IS NOT NULL
      AND TRIM(detail.CHIT_YMD) <> ''
      AND TRIM(detail.CHIT_YMD) >= v_balance_scan_from_ymd
      AND TRIM(detail.CHIT_YMD) <= v_max_to_ymd
    GROUP BY
        cash_account.ACC_CD,
        TRIM(detail.CHIT_YMD)
    ON DUPLICATE KEY UPDATE
        NET_AMOUNT = NET_AMOUNT + VALUES(NET_AMOUNT);

    INSERT INTO tmp_b03gt_balance_movement
    (
        ACC_CD,
        CHIT_YMD,
        NET_AMOUNT
    )
    SELECT
        cash_account.ACC_CD,
        TRIM(detail.CHIT_YMD),
        -SUM(IFNULL(detail.AMOUNT, 0)) AS NET_AMOUNT
    FROM chitinfo header
    INNER JOIN chitdetailinfo detail
        ON detail.COMPANY_CD = header.COMPANY_CD
       AND detail.CHIT_ID = header.CHIT_ID
       AND detail.ISDEL = '0'
    INNER JOIN tmp_b03gt_cash_account cash_account
        ON cash_account.ACC_CD = TRIM(detail.CREDIT)
    WHERE header.COMPANY_CD = p_COMPANY_CD
      AND header.ISDEL = '0'
      AND (header.CHIT_YMD IS NULL OR TRIM(header.CHIT_YMD) = '')
      AND detail.CHIT_YMD IS NOT NULL
      AND TRIM(detail.CHIT_YMD) <> ''
      AND TRIM(detail.CHIT_YMD) >= v_balance_scan_from_ymd
      AND TRIM(detail.CHIT_YMD) <= v_max_to_ymd
    GROUP BY
        cash_account.ACC_CD,
        TRIM(detail.CHIT_YMD)
    ON DUPLICATE KEY UPDATE
        NET_AMOUNT = NET_AMOUNT + VALUES(NET_AMOUNT);

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_open_value;
    CREATE TEMPORARY TABLE tmp_b03gt_open_value
    (
        TARGET_TYPE VARCHAR(20) NOT NULL,
        ACC_CD VARCHAR(20) NOT NULL,
        OPEN_NET DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (TARGET_TYPE, ACC_CD)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_open_value
    (
        TARGET_TYPE,
        ACC_CD,
        OPEN_NET
    )
    SELECT
        latest_open.TARGET_TYPE,
        latest_open.ACC_CD,
        IFNULL(
            SUM(IFNULL(before_state.DEBIT, 0) - IFNULL(before_state.CREDIT, 0)),
            0
        ) AS OPEN_NET
    FROM tmp_b03gt_latest_open latest_open
    LEFT JOIN before_states before_state
        ON before_state.COMPANY_CD = p_COMPANY_CD
       AND before_state.ACC_CD = latest_open.ACC_CD
       AND before_state.OPEN_YMD = latest_open.OPEN_YMD
       AND IFNULL(before_state.ISDEL, '0') = '0'
       AND latest_open.OPEN_YMD <> '00000000'
    GROUP BY
        latest_open.TARGET_TYPE,
        latest_open.ACC_CD;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_move_balance_sum;
    CREATE TEMPORARY TABLE tmp_b03gt_move_balance_sum
    (
        TARGET_TYPE VARCHAR(20) NOT NULL,
        ACC_CD VARCHAR(20) NOT NULL,
        MOVE_NET DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (TARGET_TYPE, ACC_CD)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_move_balance_sum
    (
        TARGET_TYPE,
        ACC_CD,
        MOVE_NET
    )
    SELECT
        latest_open.TARGET_TYPE,
        latest_open.ACC_CD,
        IFNULL(SUM(balance_movement.NET_AMOUNT), 0) AS MOVE_NET
    FROM tmp_b03gt_latest_open latest_open
    INNER JOIN tmp_b03gt_balance_target balance_target
        ON balance_target.TARGET_TYPE = latest_open.TARGET_TYPE
    LEFT JOIN tmp_b03gt_balance_movement balance_movement
        ON balance_movement.ACC_CD = latest_open.ACC_CD
       AND balance_movement.CHIT_YMD >= latest_open.OPEN_YMD
       AND balance_movement.CHIT_YMD <= balance_target.BALANCE_YMD
    GROUP BY
        latest_open.TARGET_TYPE,
        latest_open.ACC_CD;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_cash_balance;
    CREATE TEMPORARY TABLE tmp_b03gt_cash_balance
    (
        TARGET_TYPE VARCHAR(20) NOT NULL,
        BALANCE_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (TARGET_TYPE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_cash_balance
    (
        TARGET_TYPE,
        BALANCE_AMOUNT
    )
    SELECT
        latest_open.TARGET_TYPE,
        SUM(
            IFNULL(open_value.OPEN_NET, 0)
            + IFNULL(move_sum.MOVE_NET, 0)
        ) AS BALANCE_AMOUNT
    FROM tmp_b03gt_latest_open latest_open
    LEFT JOIN tmp_b03gt_open_value open_value
        ON open_value.TARGET_TYPE = latest_open.TARGET_TYPE
       AND open_value.ACC_CD = latest_open.ACC_CD
    LEFT JOIN tmp_b03gt_move_balance_sum move_sum
        ON move_sum.TARGET_TYPE = latest_open.TARGET_TYPE
       AND move_sum.ACC_CD = latest_open.ACC_CD
    GROUP BY latest_open.TARGET_TYPE;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_begin_cash_line;
    CREATE TEMPORARY TABLE tmp_b03gt_begin_cash_line
    (
        CURRENT_BEGIN_AMOUNT DECIMAL(18,2) NULL,
        PREVIOUS_BEGIN_AMOUNT DECIMAL(18,2) NULL
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_begin_cash_line
    (
        CURRENT_BEGIN_AMOUNT,
        PREVIOUS_BEGIN_AMOUNT
    )
    SELECT
        MAX(
            CASE
                WHEN TARGET_TYPE = 'CURRENT_BEGIN' THEN BALANCE_AMOUNT
            END
        ) AS CURRENT_BEGIN_AMOUNT,
        MAX(
            CASE
                WHEN TARGET_TYPE = 'PREVIOUS_BEGIN' THEN BALANCE_AMOUNT
            END
        ) AS PREVIOUS_BEGIN_AMOUNT
    FROM tmp_b03gt_cash_balance;

    UPDATE tmp_b03gt_report report
    CROSS JOIN tmp_b03gt_begin_cash_line begin_cash
    SET
        report.CURRENT_YEAR = NULLIF(ROUND(IFNULL(begin_cash.CURRENT_BEGIN_AMOUNT, 0) / v_unit_divisor, 0), 0),
        report.PREVIOUS_YEAR = NULLIF(ROUND(IFNULL(begin_cash.PREVIOUS_BEGIN_AMOUNT, 0) / v_unit_divisor, 0), 0)
    WHERE report.ITEM_CODE = '60';

    /*
        FORMULA:
        - Parse biá»ƒu thá»©c má»™t láº§n.
        - TÃ¡i sá»­ dá»¥ng cho cáº£ hai lÆ°á»£t tÃ­nh.
        - KhÃ´ng DROP/CREATE nhiá»u temporary table bÃªn trong WHILE.
        - Dá»«ng sá»›m khi káº¿t quáº£ khÃ´ng cÃ²n thay Ä‘á»•i.
    */
    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_formula_expr;
    CREATE TEMPORARY TABLE tmp_b03gt_formula_expr
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        EXPR_TEXT VARCHAR(1000) NULL,
        PRIMARY KEY (ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_formula_expr
    (
        ITEM_CODE,
        EXPR_TEXT
    )
    SELECT
        ITEM_CODE,
        REPLACE(
            REPLACE(
                REPLACE(
                    UPPER(SUBSTRING_INDEX(IFNULL(FORMULA_EXPR, ''), '=', -1)),
                    ' ',
                    ''
                ),
                '-',
                '+-'
            ),
            ';',
            '+'
        ) AS EXPR_TEXT
    FROM tmp_b03gt_report
    WHERE UPPER(IFNULL(DATA_SOURCE_TYPE, '')) = 'FORMULA'
      AND IFNULL(ITEM_CODE, '') <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_formula_term;
    CREATE TEMPORARY TABLE tmp_b03gt_formula_term
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        SIGN_FACTOR INT NOT NULL DEFAULT 1,
        CHILD_ITEM_CODE VARCHAR(50) NOT NULL,
        INDEX idx_tmp_b03gt_formula_term_01 (ITEM_CODE),
        INDEX idx_tmp_b03gt_formula_term_02 (CHILD_ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_formula_term
    (
        ITEM_CODE,
        SIGN_FACTOR,
        CHILD_ITEM_CODE
    )
    SELECT
        raw.ITEM_CODE,
        CASE
            WHEN LEFT(raw.TERM_TEXT, 1) = '-' THEN -1
            ELSE 1
        END AS SIGN_FACTOR,
        REPLACE(raw.TERM_TEXT, '-', '') AS CHILD_ITEM_CODE
    FROM
    (
        SELECT
            formula.ITEM_CODE,
            TRIM(
                SUBSTRING_INDEX(
                    SUBSTRING_INDEX(formula.EXPR_TEXT, '+', numbers.N),
                    '+',
                    -1
                )
            ) AS TERM_TEXT
        FROM tmp_b03gt_formula_expr formula
        INNER JOIN tmp_b03gt_numbers numbers
            ON numbers.N <= 1
                + LENGTH(IFNULL(formula.EXPR_TEXT, ''))
                - LENGTH(REPLACE(IFNULL(formula.EXPR_TEXT, ''), '+', ''))
    ) raw
    WHERE raw.TERM_TEXT <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_formula_calc;
    CREATE TEMPORARY TABLE tmp_b03gt_formula_calc
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        CURRENT_YEAR DECIMAL(18,2) NULL,
        PREVIOUS_YEAR DECIMAL(18,2) NULL,
        PRIMARY KEY (ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    SET v_iteration = 0;

    formula_loop_1: WHILE v_iteration < 8 DO
        TRUNCATE TABLE tmp_b03gt_formula_calc;

        INSERT INTO tmp_b03gt_formula_calc
        (
            ITEM_CODE,
            CURRENT_YEAR,
            PREVIOUS_YEAR
        )
        SELECT
            term.ITEM_CODE,
            SUM(term.SIGN_FACTOR * IFNULL(child.CURRENT_YEAR, 0)) AS CURRENT_YEAR,
            SUM(term.SIGN_FACTOR * IFNULL(child.PREVIOUS_YEAR, 0)) AS PREVIOUS_YEAR
        FROM tmp_b03gt_formula_term term
        INNER JOIN tmp_b03gt_report child
            ON UPPER(child.ITEM_CODE) = UPPER(term.CHILD_ITEM_CODE)
        GROUP BY term.ITEM_CODE;

        UPDATE tmp_b03gt_report report
        INNER JOIN tmp_b03gt_formula_calc calc
            ON UPPER(calc.ITEM_CODE) = UPPER(report.ITEM_CODE)
        SET
            report.CURRENT_YEAR = NULLIF(calc.CURRENT_YEAR, 0),
            report.PREVIOUS_YEAR = NULLIF(calc.PREVIOUS_YEAR, 0)
        WHERE UPPER(IFNULL(report.DATA_SOURCE_TYPE, '')) = 'FORMULA'
          AND
          (
                NOT (report.CURRENT_YEAR <=> NULLIF(calc.CURRENT_YEAR, 0))
             OR NOT (report.PREVIOUS_YEAR <=> NULLIF(calc.PREVIOUS_YEAR, 0))
          );

        SET v_changed_rows = ROW_COUNT();
        SET v_iteration = v_iteration + 1;

        IF v_changed_rows = 0 THEN
            LEAVE formula_loop_1;
        END IF;
    END WHILE formula_loop_1;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_balance_line;
    CREATE TEMPORARY TABLE tmp_b03gt_balance_line
    (
        CURRENT_NET_CASH_FLOW DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PREVIOUS_NET_CASH_FLOW DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        CURRENT_BEGIN_CASH DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PREVIOUS_BEGIN_CASH DECIMAL(18,2) NOT NULL DEFAULT 0.00
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_balance_line
    (
        CURRENT_NET_CASH_FLOW,
        PREVIOUS_NET_CASH_FLOW,
        CURRENT_BEGIN_CASH,
        PREVIOUS_BEGIN_CASH
    )
    SELECT
        IFNULL(MAX(CASE WHEN ITEM_CODE = '50' THEN CURRENT_YEAR END), 0),
        IFNULL(MAX(CASE WHEN ITEM_CODE = '50' THEN PREVIOUS_YEAR END), 0),
        IFNULL(MAX(CASE WHEN ITEM_CODE = '60' THEN CURRENT_YEAR END), 0),
        IFNULL(MAX(CASE WHEN ITEM_CODE = '60' THEN PREVIOUS_YEAR END), 0)
    FROM tmp_b03gt_report;

    DROP TEMPORARY TABLE IF EXISTS tmp_b03gt_end_cash_line;
    CREATE TEMPORARY TABLE tmp_b03gt_end_cash_line
    (
        CURRENT_END_AMOUNT DECIMAL(18,2) NULL,
        PREVIOUS_END_AMOUNT DECIMAL(18,2) NULL
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b03gt_end_cash_line
    (
        CURRENT_END_AMOUNT,
        PREVIOUS_END_AMOUNT
    )
    SELECT
        MAX(CASE WHEN TARGET_TYPE = 'CURRENT_END' THEN BALANCE_AMOUNT END),
        MAX(CASE WHEN TARGET_TYPE = 'PREVIOUS_END' THEN BALANCE_AMOUNT END)
    FROM tmp_b03gt_cash_balance;

    UPDATE tmp_b03gt_report report
    CROSS JOIN tmp_b03gt_balance_line balance_line
    CROSS JOIN tmp_b03gt_end_cash_line end_cash
    SET
        report.CURRENT_YEAR = NULLIF(
            ROUND(IFNULL(end_cash.CURRENT_END_AMOUNT, 0) / v_unit_divisor, 0)
            - balance_line.CURRENT_NET_CASH_FLOW
            - balance_line.CURRENT_BEGIN_CASH,
            0
        ),
        report.PREVIOUS_YEAR = NULLIF(
            ROUND(IFNULL(end_cash.PREVIOUS_END_AMOUNT, 0) / v_unit_divisor, 0)
            - balance_line.PREVIOUS_NET_CASH_FLOW
            - balance_line.PREVIOUS_BEGIN_CASH,
            0
        )
    WHERE report.ITEM_CODE = '61';

    /*
        LÆ°á»£t FORMULA thá»© hai sau khi tÃ­nh ITEM_CODE = '61'.
        TÃ¡i sá»­ dá»¥ng tmp_b03gt_formula_term Ä‘Ã£ parse á»Ÿ trÃªn.
    */
    SET v_iteration = 0;

    formula_loop_2: WHILE v_iteration < 4 DO
        TRUNCATE TABLE tmp_b03gt_formula_calc;

        INSERT INTO tmp_b03gt_formula_calc
        (
            ITEM_CODE,
            CURRENT_YEAR,
            PREVIOUS_YEAR
        )
        SELECT
            term.ITEM_CODE,
            SUM(term.SIGN_FACTOR * IFNULL(child.CURRENT_YEAR, 0)) AS CURRENT_YEAR,
            SUM(term.SIGN_FACTOR * IFNULL(child.PREVIOUS_YEAR, 0)) AS PREVIOUS_YEAR
        FROM tmp_b03gt_formula_term term
        INNER JOIN tmp_b03gt_report child
            ON UPPER(child.ITEM_CODE) = UPPER(term.CHILD_ITEM_CODE)
        GROUP BY term.ITEM_CODE;

        UPDATE tmp_b03gt_report report
        INNER JOIN tmp_b03gt_formula_calc calc
            ON UPPER(calc.ITEM_CODE) = UPPER(report.ITEM_CODE)
        SET
            report.CURRENT_YEAR = NULLIF(calc.CURRENT_YEAR, 0),
            report.PREVIOUS_YEAR = NULLIF(calc.PREVIOUS_YEAR, 0)
        WHERE UPPER(IFNULL(report.DATA_SOURCE_TYPE, '')) = 'FORMULA'
          AND
          (
                NOT (report.CURRENT_YEAR <=> NULLIF(calc.CURRENT_YEAR, 0))
             OR NOT (report.PREVIOUS_YEAR <=> NULLIF(calc.PREVIOUS_YEAR, 0))
          );

        SET v_changed_rows = ROW_COUNT();
        SET v_iteration = v_iteration + 1;

        IF v_changed_rows = 0 THEN
            LEAVE formula_loop_2;
        END IF;
    END WHILE formula_loop_2;

    SELECT
        ROW_KEY,
        COMPANY_CD,
        ROW_TYPE,
        ITEM_NAME,
        CAPTION,
        LABEL_TEXT,
        ITEM_CODE,
        NOTE,
        CURRENT_YEAR,
        PREVIOUS_YEAR,
        LEVEL_NO,
        FONT_BOLD,
        FONT_ITALIC,
        DATA_SOURCE_TYPE,
        FORMULA_EXPR,
        REPORT_YEAR_TEXT,
        REPORT_PERIOD_TEXT,
        AMOUNT_UNIT_TEXT
    FROM tmp_b03gt_report
    ORDER BY SORT_ORDER;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_cash_book
DROP PROCEDURE IF EXISTS `rpt_cash_book`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_cash_book`(
	IN `p_COMPANY_CD` VARCHAR(20), IN `p_FROM_DATE` DATE, IN `p_TO_DATE` DATE, IN `p_MODULE_CD` VARCHAR(10), IN `p_ACCOUNT_CD` VARCHAR(50), 
	IN `p_FC_TYPE` VARCHAR(10),
	IN p_LANGUAGE VARCHAR(10)

)
BEGIN
		-- ---------------------------------------------------------------------------------------
	    -- 1. Khai báo các biến cục bộ
	--    DECLARE str_Opening_Balance VARCHAR(100) DEFAULT ''; 
	--    DECLARE str_Closing_Balance VARCHAR(100) DEFAULT ''; 
		 
		 
	--    DECLARE str_Closing_Balance VARCHAR(100); set str_Closing_Balance = ''; -- fn_getLanguage(' ', p_LANGUAGE, '') ;
	    
	    DECLARE v_module_cd VARCHAR(10) DEFAULT '';
	    DECLARE v_account_cd VARCHAR(50) DEFAULT '';
	    DECLARE v_fc_type VARCHAR(10) DEFAULT '';
	    DECLARE v_opening_amount DECIMAL(18,2) DEFAULT 0.00;
	    DECLARE v_opening_fc_amount DECIMAL(18,2) DEFAULT 0.00;
	    DECLARE v_total_receipt_amount DECIMAL(18,2) DEFAULT 0.00;
	    DECLARE v_total_payment_amount DECIMAL(18,2) DEFAULT 0.00;
	    DECLARE v_total_receipt_fc_amount DECIMAL(18,2) DEFAULT 0.00;
	    DECLARE v_total_payment_fc_amount DECIMAL(18,2) DEFAULT 0.00;
	    DECLARE v_closing_amount DECIMAL(18,2) DEFAULT 0.00;
	    DECLARE v_closing_fc_amount DECIMAL(18,2) DEFAULT 0.00;
	    DECLARE v_FROM_DATE VARCHAR (10) default '';
	    DECLARE v_TO_DATE VARCHAR (10) default '';
	    DECLARE v_MAX_CLOSE_YMD VARCHAR (10) default '';
	    DECLARE v_MAX_CLOSE_YMD_NEXTDAY CHAR(8) DEFAULT NULL;
	
	
		
	--	set str_Opening_Balance = CONCAT('*** ', fn_getLanguage('OPENING_BALANCE', p_LANGUAGE, ''), ' ***') ;
	--	set str_Closing_Balance = fn_getLanguage('CLOSING_BALANCE', p_LANGUAGE, '') ;
			
		-- ---------------------------------------------------------------------------------------
	    -- 2. Kiểm tra điều kiện đầu vào (Validation)
		-- ---------------------------------------------------------------------------------------
	    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
	        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required'; -- INVALID_DATE_RANGE
	    END IF;
	    
	    IF p_FROM_DATE > p_TO_DATE THEN
	        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate'; -- DateInvalid
	    END IF;
	
		 SET v_FROM_DATE 	= DATE_FORMAT(p_FROM_DATE, '%Y%m%d') ;
		 SET v_TO_DATE 	= DATE_FORMAT(p_TO_DATE, '%Y%m%d') ;
	
		
	    -- Tối ưu hóa biến tìm kiếm để tận dụng index tốt hơn
	    SET v_module_cd = UPPER(TRIM(IFNULL(p_MODULE_CD, '')));
	    SET v_account_cd = TRIM(IFNULL(p_ACCOUNT_CD, ''));
	    SET v_fc_type = UPPER(TRIM(IFNULL(p_FC_TYPE, '')));
	
	    IF v_module_cd = 'ALL' THEN
	        SET v_module_cd = '';
	    END IF;
	    IF v_account_cd = '' THEN
	        SET v_account_cd = '111'; -- default 111 = Cash / Tien Mat
	    END IF;


		-- ---------------------------------------------------------------------------------------	
	    -- 3. Tạo bảng tạm CHỈ chứa THÔNG TIN CHỨNG TỪ và thêm INDEX để tính toán nhanh hơn
		-- ---------------------------------------------------------------------------------------
	    DROP TEMPORARY TABLE IF EXISTS tmp_cash_book_source;
	    CREATE TEMPORARY TABLE tmp_cash_book_source (
	        MODULE_CD VARCHAR(10),
	        COMPANY_CD VARCHAR(20),
	        CHIT_ID BIGINT,
	        CHITDETAIL_ID BIGINT,
	        CHIT_CD VARCHAR(50),
	        CHIT_NO VARCHAR(50),
	        CHIT_YMD VARCHAR(8),
	        CHIT_TYPE VARCHAR(20),
	        CHITDETAIL_CD VARCHAR(50),
	        DEBIT VARCHAR(20),
	        CREDIT VARCHAR(20),
	        AMOUNT DECIMAL(18,2),
	        FC_AMOUNT DECIMAL(18,2),
	        FC_TYPE VARCHAR(10),
	        FC_RATE DECIMAL(18,6),
	        FC_DATETIME DATETIME,
	        ACCOUNT_CD VARCHAR(50),
	        CUSTOMER_ID BIGINT,
	        CASH_FLOW_TYPE VARCHAR(10),
	        RECEIPT_AMOUNT DECIMAL(18,2),
	        PAYMENT_AMOUNT DECIMAL(18,2),
	        RECEIPT_FC_AMOUNT DECIMAL(18,2),
	        PAYMENT_FC_AMOUNT DECIMAL(18,2),
	        VAT_CHIT_NO VARCHAR(50),
	        PAYER_INFO VARCHAR(255),
	        PRIMARY KEY (COMPANY_CD, CHIT_ID, CHITDETAIL_ID),
	        KEY idx_filter (CHIT_YMD, MODULE_CD, ACCOUNT_CD, FC_TYPE) -- Giúp query số dư đầu kỳ và chi tiết cực nhanh
	    ) ENGINE=InnoDB;
	    -- Insert tinh gọn vào bảng nguồn (Bỏ bớt các LEFT JOIN văn bản nặng nề ở bước này)
	    INSERT INTO tmp_cash_book_source
	    SELECT
	        IFNULL(h.INPUT_TYPE, '') AS MODULE_CD,
	        h.COMPANY_CD,
	        h.CHIT_ID,
	        d.CHITDETAIL_ID,
	        h.CHIT_CD,
	        h.CHIT_NO,
	        h.CHIT_YMD,
	        h.CHIT_TYPE,
	        d.CHITDETAIL_CD,
	        d.DEBIT,
	        d.CREDIT,
	        IFNULL(d.AMOUNT, 0) AS AMOUNT,
	        IFNULL(d.FC_AMOUNT, 0) AS FC_AMOUNT,
	        IFNULL(d.FC_TYPE, '') AS FC_TYPE,
	        IFNULL(d.FC_RATE, 0) AS FC_RATE,
	        d.FC_DATETIME,
	        -- Chuyển logic LIKE ra ngoài hoặc dùng biến để so sánh rõ ràng
	        CASE WHEN d.DEBIT REGEXP concat('^', v_account_cd) THEN d.DEBIT 
	             WHEN d.CREDIT REGEXP concat('^', v_account_cd) THEN d.CREDIT 
	             ELSE '' END AS ACCOUNT_CD,
	        ext.CUSTOMER_ID,
	        CASE WHEN d.DEBIT REGEXP concat('^', v_account_cd) THEN 'RECEIPT' 
	             WHEN d.CREDIT REGEXP concat('^', v_account_cd) THEN 'PAYMENT' 
	             ELSE '' END AS CASH_FLOW_TYPE,
	        CASE WHEN d.DEBIT REGEXP concat('^', v_account_cd) THEN IFNULL(d.AMOUNT, 0) ELSE 0 END AS RECEIPT_AMOUNT,
	        CASE WHEN d.CREDIT REGEXP concat('^', v_account_cd) THEN IFNULL(d.AMOUNT, 0) ELSE 0 END AS PAYMENT_AMOUNT,
	        CASE WHEN d.DEBIT REGEXP concat('^', v_account_cd) THEN IFNULL(d.FC_AMOUNT, 0) ELSE 0 END AS RECEIPT_FC_AMOUNT,
	        CASE WHEN d.CREDIT REGEXP concat('^', v_account_cd) THEN IFNULL(d.FC_AMOUNT, 0) ELSE 0 END AS PAYMENT_FC_AMOUNT,
	        vat.VAT_CHIT_NO,
	        h.PAYER_INFO
	    FROM chitinfo h
		    INNER JOIN chitdetailinfo d 			ON d.COMPANY_CD = h.COMPANY_CD AND d.CHIT_ID = h.CHIT_ID
		    LEFT JOIN chitdetailinfo_ext ext 	ON ext.COMPANY_CD = d.COMPANY_CD AND ext.CHITDETAIL_ID = d.CHITDETAIL_ID AND ext.ISDEL <> '1'
		    LEFT JOIN chitdetailinfo_vat vat	ON vat.COMPANY_CD = d.COMPANY_CD and vat.CHITDETAIL_EXT_ID = ext.CHITDETAIL_EXT_ID and vat.ISDEL <> '1'
	    WHERE 
		 	h.COMPANY_CD = p_COMPANY_CD  
			AND h.CHIT_YMD between v_FROM_DATE and v_TO_DATE
	      AND h.INPUT_TYPE IN ('AR', 'AP')
	      AND h.ISDEL <> '1'
	      AND d.ISDEL <> '1'
	--      AND (d.DEBIT REGEXP '^111' OR d.CREDIT REGEXP '^111') -- REGEXP chạy tối ưu hơn chuỗi hàm OR LIKE phức tạp
	      AND (d.DEBIT REGEXP concat('^', v_account_cd) OR d.CREDIT REGEXP concat('^', v_account_cd)) -- REGEXP chạy tối ưu hơn chuỗi hàm OR LIKE phức tạp
	      ;
	

		-- ---------------------------------------------------------------------------------------
	    -- 4. Tính toán số dư đầu kỳ (Opening Balance) -> Chạy rất nhanh nhờ có Index trên bảng tạm
		-- ---------------------------------------------------------------------------------------
		select MAX(CLOSE_YMD) into v_MAX_CLOSE_YMD FROM closingmonth_detail c where c.COMPANY_CD = p_COMPANY_CD AND c.CLOSE_YMD < v_FROM_DATE  AND c.ISDEL <> '1' ;
		SET v_MAX_CLOSE_YMD = IFNULL(v_MAX_CLOSE_YMD, '0');

-- select v_MAX_CLOSE_YMD+100 as v_MAX_CLOSE_YMD;
-- call rpt_cash_book('0001', '20260901', '20261001', '','111','','VIET')						
		-- 4.1 closingmonth_detail
		-- lấy dữ liệu KHÓA SỔ gần nhất
		DROP TEMPORARY TABLE IF EXISTS tmp_closingmonth_detail;
	    CREATE TEMPORARY TABLE tmp_closingmonth_detail (
	        
--	        ACC_CD VARCHAR(20),
--	        FC_TYPE VARCHAR(10),
	        AMOUNT DECIMAL(18,2),
	        FC_AMOUNT DECIMAL(18,2)
--	        KEY idx_filter (ACC_CD, FC_TYPE) -- Giúp query số dư đầu kỳ và chi tiết cực nhanh
	    ) ENGINE=InnoDB;
		INSERT INTO tmp_closingmonth_detail
		select 
--			c.ACC_CD, 
--			c.FC_TYPE, 
			(c.DEBIT - c.CREDIT) as AMOUNT, 
			(c.DEBIT_FC - c.CREDIT_FC) as AMOUNT_FC
		from closingmonth_detail c
		where c.COMPANY_CD = p_COMPANY_CD 
			AND left(c.CLOSE_YMD,6) = left(v_MAX_CLOSE_YMD, 6)
			AND c.ISDEL <> '1' 
			and c.ACC_CD REGEXP concat('^', v_account_cd)
			and (c.FC_TYPE = '' or c.FC_TYPE = 'VND' or c.FC_TYPE = v_fc_type)
		;
		
		
		-- 4.2 chitinfo inUse  -- getRecentUseInfo_Search
		-- lấy dữ liệu : SAU TGIAN KHÓA SỔ   VS   TRƯỚC TGIAN TÌM KIẾM
		set v_MAX_CLOSE_YMD_NEXTDAY = concat(left(v_MAX_CLOSE_YMD,6),'31') + 1;
		
		INSERT INTO tmp_closingmonth_detail
		SELECT 
--			cdt.DEBIT, cdt.CREDIT, 
			SUM(cdt.AMOUNT * (CASE WHEN DEBIT REGEXP concat('^', v_account_cd) THEN 1 ELSE -1 END)) AS AMOUNT,
			SUM(cdt.FC_AMOUNT * (CASE WHEN DEBIT REGEXP concat('^', v_account_cd) THEN 1 ELSE -1 END)) AS FC_AMOUNT

--			cdt.FC_TYPE, 
--			cdt.FC_RATE
--			SELECT * 		
		FROM chitdetailinfo cdt
		WHERE cdt.COMPANY_CD = p_COMPANY_CD 			
			and cdt.CHIT_YMD between v_MAX_CLOSE_YMD_NEXTDAY AND (v_FROM_DATE - 1) 
			AND (DEBIT REGEXP concat('^', v_account_cd) OR CREDIT REGEXP concat('^', v_account_cd))
			and cdt.ISDEL <> '1' 
--			AND (cdt.FC_TYPE = '' OR cdt.FC_TYPE = 'VND' OR cdt.FC_TYPE = p_FC_TYPE )
			;
		
		
		-- 4.3
		-- INTO v_opening_amount   vs  v_opening_fc_amount
	    SELECT
	        IFNULL(SUM(v.AMOUNT), 0),
	        IFNULL(SUM(v.FC_AMOUNT), 0)
	    INTO v_opening_amount, v_opening_fc_amount
	    FROM tmp_closingmonth_detail v
			;

		-- ---------------------------------------------------------------------------------------
	    -- 5. Tạo bảng chi tiết trong kỳ
		-- ---------------------------------------------------------------------------------------
	    DROP TEMPORARY TABLE IF EXISTS tmp_cash_book_detail;
	    CREATE TEMPORARY TABLE tmp_cash_book_detail (
	        ROW_NO INT NOT NULL AUTO_INCREMENT,
	        MODULE_CD VARCHAR(10) DEFAULT '',
	        COMPANY_CD VARCHAR(20) DEFAULT '',
	        CHIT_ID BIGINT DEFAULT 0,
	        CHITDETAIL_ID BIGINT DEFAULT 0,
	        CHIT_CD VARCHAR(50) DEFAULT '',
	        CHIT_NO VARCHAR(50) DEFAULT '',
	        CHIT_YMD VARCHAR(8) NULL,
	        CHIT_TYPE VARCHAR(20) DEFAULT '',
	        CHITDETAIL_CD VARCHAR(50) DEFAULT '',
	        DEBIT VARCHAR(20) DEFAULT '',
	        CREDIT VARCHAR(20) DEFAULT '',
	        AMOUNT DECIMAL(18,2) DEFAULT 0.00,
	        FC_AMOUNT DECIMAL(18,2) DEFAULT 0.00,
	        FC_TYPE VARCHAR(10) DEFAULT '',
	        FC_RATE DECIMAL(18,6) DEFAULT 0.000000,
	        FC_DATETIME DATETIME NULL,
	        ACCOUNT_CD VARCHAR(50) DEFAULT '',
	        CUSTOMER_ID BIGINT NULL,
	        CASH_FLOW_TYPE VARCHAR(20) DEFAULT '',
	        RECEIPT_AMOUNT DECIMAL(18,2) DEFAULT 0.00,
	        PAYMENT_AMOUNT DECIMAL(18,2) DEFAULT 0.00,
	        RECEIPT_FC_AMOUNT DECIMAL(18,2) DEFAULT 0.00,
	        PAYMENT_FC_AMOUNT DECIMAL(18,2) DEFAULT 0.00,
	        RUNNING_AMOUNT DECIMAL(18,2) DEFAULT 0.00,
	        RUNNING_FC_AMOUNT DECIMAL(18,2) DEFAULT 0.00,
	        VAT_CHIT_NO VARCHAR(50) DEFAULT '',
	        PAYER_INFO VARCHAR(255) DEFAULT '',
	        PRIMARY KEY (ROW_NO)
	    ) ENGINE=InnoDB;
	
	    -- Lọc dữ liệu phát sinh trong kỳ đổ vào bảng chi tiết
	    INSERT INTO tmp_cash_book_detail(
	        MODULE_CD, COMPANY_CD, CHIT_ID, CHITDETAIL_ID, CHIT_CD, CHIT_NO, CHIT_YMD, CHIT_TYPE, 
	        CHITDETAIL_CD, DEBIT, CREDIT, AMOUNT, FC_AMOUNT, FC_TYPE, FC_RATE, FC_DATETIME, 
	        ACCOUNT_CD, CUSTOMER_ID, CASH_FLOW_TYPE, RECEIPT_AMOUNT, PAYMENT_AMOUNT, RECEIPT_FC_AMOUNT, PAYMENT_FC_AMOUNT, 
			  VAT_CHIT_NO, PAYER_INFO
	    )
	    SELECT 
	        v.MODULE_CD, v.COMPANY_CD, v.CHIT_ID, v.CHITDETAIL_ID, v.CHIT_CD, v.CHIT_NO, v.CHIT_YMD, v.CHIT_TYPE, 
	        v.CHITDETAIL_CD, v.DEBIT, v.CREDIT, v.AMOUNT, v.FC_AMOUNT, v.FC_TYPE, v.FC_RATE, v.FC_DATETIME, 
	        v.ACCOUNT_CD, v.CUSTOMER_ID, v.CASH_FLOW_TYPE, v.RECEIPT_AMOUNT, v.PAYMENT_AMOUNT, v.RECEIPT_FC_AMOUNT, v.PAYMENT_FC_AMOUNT, 
			  VAT_CHIT_NO, PAYER_INFO
	    FROM tmp_cash_book_source v
	    WHERE v.CHIT_YMD >= DATE_FORMAT(p_FROM_DATE, '%Y%m%d')
	      AND v.CHIT_YMD <= DATE_FORMAT(p_TO_DATE, '%Y%m%d')
	      AND (v_module_cd = '' OR v.MODULE_CD = v_module_cd)
			AND v.ACCOUNT_CD LIKE CONCAT(v_account_cd, '%') --      AND (v_account_cd = '' OR v.ACCOUNT_CD = v_account_cd OR v.ACCOUNT_CD LIKE CONCAT(v_account_cd, '%'))
	
	      AND (v_fc_type = '' OR v.FC_TYPE = v_fc_type)
	    ORDER BY v.CHIT_YMD, v.CHIT_NO, v.CHIT_ID, v.CHITDETAIL_ID;
	
	
		-- ---------------------------------------------------------------------------------------
	    -- 6. Tính tổng phát sinh trong kỳ
		-- ---------------------------------------------------------------------------------------
	    SELECT
	        IFNULL(SUM(RECEIPT_AMOUNT), 0), IFNULL(SUM(PAYMENT_AMOUNT), 0),
	        IFNULL(SUM(RECEIPT_FC_AMOUNT), 0), IFNULL(SUM(PAYMENT_FC_AMOUNT), 0)
	    INTO v_total_receipt_amount, v_total_payment_amount, 
		 		v_total_receipt_fc_amount, v_total_payment_fc_amount
	    FROM tmp_cash_book_detail;
	

-- SELECT v_opening_amount, v_total_receipt_amount, v_total_payment_amount;
-- call rpt_cash_book('0001', '20260901', '20261001', '','111','','VIET')				

	    -- Tính số dư cuối kỳ
	    SET v_closing_amount = v_opening_amount + v_total_receipt_amount - v_total_payment_amount;
	    SET v_closing_fc_amount = v_opening_fc_amount + v_total_receipt_fc_amount - v_total_payment_fc_amount;
	
	    -- 7. Cập nhật Số dư lũy tiến (Running Balance) 
	    SET @cash_running_amount := v_opening_amount;
	    SET @cash_running_fc_amount := v_opening_fc_amount;
	
	    UPDATE tmp_cash_book_detail
	    SET RUNNING_AMOUNT = (@cash_running_amount := @cash_running_amount + RECEIPT_AMOUNT - PAYMENT_AMOUNT),
	        RUNNING_FC_AMOUNT = (@cash_running_fc_amount := @cash_running_fc_amount + RECEIPT_FC_AMOUNT - PAYMENT_FC_AMOUNT)
	    ORDER BY ROW_NO;
	
	
	-- ==========================================================================================================
	-- ==========================================================================================================
	-- ==========================================================================================================
	
	    -- 8. Trả kết quả (Chỉ thực hiện nối các bảng text/văn bản ở bước cuối cùng này để giảm tải bộ nhớ)
	    SELECT
	        -- System keys (hidden by __* / ROW_KEY|ROW_TYPE convention)
	        report.ROW_KEY AS __ROW_KEY,
	        report.ROW_TYPE AS __ROW_TYPE,
			  DATE_FORMAT(STR_TO_DATE(report.CHIT_YMD, '%Y%m%d'), '%d/%m/%Y') as CHIT_YMD, 
			  
			  COALESCE(cust.CUSTOMER_CD, '') AS CUSTOMER_CD,
			  
			  ( -- p_LANGUAGE
			  		CASE p_LANGUAGE
						WHEN  'VIET' 
						  	THEN -- Kiểm tra NULL và rỗng cho VIET
	    							COALESCE(NULLIF(cust.CUSTOMER_NM_VIET, ''), '')
						WHEN 'ENG' 
						  	THEN -- Ưu tiên ENG, nếu NULL hoặc rỗng thì lấy VIET
	    							COALESCE(NULLIF(cust.CUSTOMER_NM_ENG, ''), NULLIF(cust.CUSTOMER_NM_VIET, ''), '')
						WHEN 'KOR' 
						  	THEN -- Ưu tiên KOR, nếu NULL hoặc rỗng thì lấy ENG, tiếp đến VIET
	    							COALESCE(NULLIF(cust.CUSTOMER_NM_KOR, ''), NULLIF(cust.CUSTOMER_NM_ENG, ''), NULLIF(cust.CUSTOMER_NM_VIET, ''), '')
						else 
							COALESCE(cust.CUSTOMER_NM_VIET, '')
					end
			  ) as CUSTOMER_NM,
	        
	        cust_e.TAX_CD AS TAX_CD,
	        report.VAT_CHIT_NO,
	        
	        (CASE WHEN report.CASH_FLOW_TYPE = 'RECEIPT' THEN report.CHIT_NO ELSE '' END) AS RECEIPT_NO,
	        (CASE WHEN report.CASH_FLOW_TYPE = 'PAYMENT' THEN report.CHIT_NO ELSE '' END) AS PAYMENT_NO,
			  
			  case when SORT_GROUP <> 2 then concat('*** ', fn_getLanguage(report.ROW_KEY, 'VIET', ''), ' ***') else IFNULL(desc_V.DESCRIPTION, '') end AS DESCRIPTION_VIET,
			  case when SORT_GROUP <> 2 then concat('*** ', fn_getLanguage(report.ROW_KEY, 'ENG', ''), ' ***') else IFNULL(desc_E.DESCRIPTION, '') end AS DESCRIPTION_ENG,
	        case when SORT_GROUP <> 2 then concat('*** ', fn_getLanguage(report.ROW_KEY, 'KOR', ''), ' ***') else IFNULL(desc_K.DESCRIPTION, '') end AS DESCRIPTION_KOR,
	        
	        case when SORT_GROUP <> 2 then concat('*** ', fn_getLanguage(report.ROW_KEY, 'VIET', ''), ' ***') else IFNULL(desc2_V.DESCRIPTION, '') end AS DESCRIPTION2_VIET,
			  case when SORT_GROUP <> 2 then concat('*** ', fn_getLanguage(report.ROW_KEY, 'ENG', ''), ' ***') else IFNULL(desc2_E.DESCRIPTION, '') end AS DESCRIPTION2_ENG,
	        case when SORT_GROUP <> 2 then concat('*** ', fn_getLanguage(report.ROW_KEY, 'KOR', ''), ' ***') else IFNULL(desc2_K.DESCRIPTION, '') end AS DESCRIPTION2_KOR,
	        
	        '' AS __DESCRIPTION,
	        
	        report.CSD_ACC_CD,
			  report.FC_RATE, 
			  IFNULL(case when DEBIT  LIKE '111%' then report.AMOUNT end,0.0) as DEBIT_AMOUNT,
			  IFNULL(case when DEBIT  LIKE '111%' then 0.0 end,report.AMOUNT) as CREDIT_AMOUNT,
			  report.RUNNING_AMOUNT AS BALANCE,
			  
			  IFNULL(case when DEBIT LIKE '111%' and FC_TYPE = '",v_fc_type,"' then report.FC_AMOUNT end, 0.0) as DEBIT_FC_AMOUNT,
			  IFNULL(case when DEBIT LIKE '111%' and FC_TYPE = '",v_fc_type,"' then 0.0 end, report.FC_AMOUNT) as CREDIT_FC_AMOUNT,
			  report.CUSTOMER_ID, 		  
			  report.RUNNING_FC_AMOUNT as FC_BALANCE,
			  report.PAYER_INFO as CHIT_REPORT_MIX,
	
	        -- System / drill fields (hidden by __* convention)
	        report.CHIT_ID AS __CHIT_ID,
	        report.CHIT_TYPE AS __CHIT_TYPE,
	        report.MODULE_CD AS __MODULE_CD,
	        report.CHITDETAIL_ID AS __CHITDETAIL_ID,
	        report.CHIT_NO AS __CHIT_NO,
	        report.CHIT_YMD AS __CHIT_YMD,
	        CASE WHEN report.ROW_TYPE = 'DETAIL' AND IFNULL(report.CHIT_ID, 0) > 0 THEN 'DOCUMENT' ELSE 'NONE' END AS __LINK_TYPE
			  
	    FROM (
	    		
	    		-- Số dư đầu kỳ : lbllastyearmoney_BS
	        SELECT 1 AS SORT_GROUP, 0 AS SORT_SEQ, 'OPENING_BALANCE' AS ROW_KEY, 'OPENING' AS ROW_TYPE, 
	               '' AS MODULE_CD, p_COMPANY_CD AS COMPANY_CD, 0 AS CHIT_ID, 0 AS CHITDETAIL_ID, '' AS CHIT_CD, '' AS CHIT_NO, 
	               NULL AS CHIT_YMD, '' AS CHIT_TYPE, '' AS CHITDETAIL_CD, '' AS DEBIT, '' AS CREDIT, 0.00 AS AMOUNT, 0.00 AS FC_AMOUNT, 
	               v_fc_type AS FC_TYPE, 0.000000 AS FC_RATE, NULL AS FC_DATETIME, v_account_cd AS ACCOUNT_CD, NULL AS CUSTOMER_ID, 
	               '' AS CASH_FLOW_TYPE, 0.00 AS RECEIPT_AMOUNT, 0.00 AS PAYMENT_AMOUNT, 0.00 AS RECEIPT_FC_AMOUNT, 0.00 AS PAYMENT_FC_AMOUNT, 
	               'Opening Balance' AS RAW_DESCRIPTION, '' AS CSD_ACC_CD, v_opening_amount AS RUNNING_AMOUNT, v_opening_fc_amount AS RUNNING_FC_AMOUNT, 
						'' AS VAT_CHIT_NO, '' as PAYER_INFO
	        UNION ALL
	        SELECT 2 AS SORT_GROUP, d.ROW_NO AS SORT_SEQ, CONCAT('DETAIL_', d.MODULE_CD, '_', d.CHIT_ID, '_', d.CHITDETAIL_ID, '_', d.ROW_NO) AS ROW_KEY, 'DETAIL' AS ROW_TYPE, 
	               d.MODULE_CD, d.COMPANY_CD, d.CHIT_ID, d.CHITDETAIL_ID, d.CHIT_CD, d.CHIT_NO, d.CHIT_YMD, d.CHIT_TYPE, d.CHITDETAIL_CD, d.DEBIT, d.CREDIT, 
	               d.AMOUNT, d.FC_AMOUNT, d.FC_TYPE, d.FC_RATE, d.FC_DATETIME, d.ACCOUNT_CD, d.CUSTOMER_ID, d.CASH_FLOW_TYPE, 
	               d.RECEIPT_AMOUNT, d.PAYMENT_AMOUNT, d.RECEIPT_FC_AMOUNT, d.PAYMENT_FC_AMOUNT, '' AS RAW_DESCRIPTION,
	               CASE WHEN d.CASH_FLOW_TYPE = 'RECEIPT' THEN d.CREDIT ELSE d.DEBIT END AS CSD_ACC_CD, d.RUNNING_AMOUNT, d.RUNNING_FC_AMOUNT, 
						d.VAT_CHIT_NO, d.PAYER_INFO
	        FROM tmp_cash_book_detail d
	        /*
	        UNION ALL
	        SELECT 3 AS SORT_GROUP, 0 AS SORT_SEQ, 'TOTAL_RECEIPT' AS ROW_KEY, 'TOTAL_RECEIPT' AS ROW_TYPE, 
	               '' AS MODULE_CD, p_COMPANY_CD AS COMPANY_CD, 0 AS CHIT_ID, 0 AS CHITDETAIL_ID, '' AS CHIT_CD, '' AS CHIT_NO, 
	               NULL AS CHIT_YMD, '' AS CHIT_TYPE, '' AS CHITDETAIL_CD, '' AS DEBIT, '' AS CREDIT, 0.00 AS AMOUNT, v_total_receipt_fc_amount AS FC_AMOUNT, 
	               v_fc_type AS FC_TYPE, 0.000000 AS FC_RATE, NULL AS FC_DATETIME, v_account_cd AS ACCOUNT_CD, NULL AS CUSTOMER_ID, 
	               '' AS CASH_FLOW_TYPE, v_total_receipt_amount AS RECEIPT_AMOUNT, 0.00 AS PAYMENT_AMOUNT, v_total_receipt_fc_amount AS RECEIPT_FC_AMOUNT, 0.00 AS PAYMENT_FC_AMOUNT, 
	               'Total Receipt' AS RAW_DESCRIPTION, '' AS CSD_ACC_CD, 0.00 AS RUNNING_AMOUNT, 0.00 AS RUNNING_FC_AMOUNT
	        UNION ALL
	        SELECT 4 AS SORT_GROUP, 0 AS SORT_SEQ, 'TOTAL_PAYMENT' AS ROW_KEY, 'TOTAL_PAYMENT' AS ROW_TYPE, 
	               '' AS MODULE_CD, p_COMPANY_CD AS COMPANY_CD, 0 AS CHIT_ID, 0 AS CHITDETAIL_ID, '' AS CHIT_CD, '' AS CHIT_NO, 
	               NULL AS CHIT_YMD, '' AS CHIT_TYPE, '' AS CHITDETAIL_CD, '' AS DEBIT, '' AS CREDIT, 0.00 AS AMOUNT, v_total_payment_fc_amount AS FC_AMOUNT, 
	               v_fc_type AS FC_TYPE, 0.000000 AS FC_RATE, NULL AS FC_DATETIME, v_account_cd AS ACCOUNT_CD, NULL AS CUSTOMER_ID, 
	               '' AS CASH_FLOW_TYPE, 0.00 AS RECEIPT_AMOUNT, v_total_payment_amount AS PAYMENT_AMOUNT, 0.00 AS RECEIPT_FC_AMOUNT, v_total_payment_fc_amount AS PAYMENT_FC_AMOUNT, 
	               'Total Payment' AS RAW_DESCRIPTION, '' AS CSD_ACC_CD, 0.00 AS RUNNING_AMOUNT, 0.00 AS RUNNING_FC_AMOUNT
	               */
	        UNION ALL
	        -- Số dư cuối kỳ: lblthisyearmoney_BS_2513_01
	        SELECT 5 AS SORT_GROUP, 0 AS SORT_SEQ, 'CLOSING_BALANCE' AS ROW_KEY, 'CLOSING' AS ROW_TYPE, 
	               '' AS MODULE_CD, p_COMPANY_CD AS COMPANY_CD, 0 AS CHIT_ID, 0 AS CHITDETAIL_ID, '' AS CHIT_CD, '' AS CHIT_NO, 
	               NULL AS CHIT_YMD, '' AS CHIT_TYPE, '' AS CHITDETAIL_CD, '' AS DEBIT, '' AS CREDIT, 0.00 AS AMOUNT, 0.00 AS FC_AMOUNT, 
	               v_fc_type AS FC_TYPE, 0.000000 AS FC_RATE, NULL AS FC_DATETIME, v_account_cd AS ACCOUNT_CD, NULL AS CUSTOMER_ID, 
	               '' AS CASH_FLOW_TYPE, 0.00 AS RECEIPT_AMOUNT, 0.00 AS PAYMENT_AMOUNT, 0.00 AS RECEIPT_FC_AMOUNT, 0.00 AS PAYMENT_FC_AMOUNT, 
	               'Closing Balance' AS RAW_DESCRIPTION, '' AS CSD_ACC_CD, v_closing_amount AS RUNNING_AMOUNT, v_closing_fc_amount AS RUNNING_FC_AMOUNT, 
						'' as VAT_CHIT_NO, '' as PAYER_INFO
	    ) report
	    -- Tiến hành JOIN lấy thông tin text/văn bản ở bước cuối cùng dựa trên kết quả đã thu gọn
	    LEFT JOIN customer_info cust						ON cust.COMPANY_CD = report.COMPANY_CD AND cust.CUSTOMER_ID = report.CUSTOMER_ID AND cust.ISDEL <> '1'
	    LEFT JOIN customer_ext cust_e					ON cust_e.COMPANY_CD = report.COMPANY_CD AND cust_e.CUSTOMER_ID = report.CUSTOMER_ID AND cust_e.ISDEL <> '1'
	    
	    LEFT JOIN chitdescriptioninfo desc_V         ON desc_V.COMPANY_CD = report.COMPANY_CD AND desc_V.CHIT_ID = report.CHIT_ID AND desc_V.LANG_TYPE = 'VIET' AND desc_V.ISDEL <> '1'
	    LEFT JOIN chitdescriptioninfo desc_E         ON desc_E.COMPANY_CD = report.COMPANY_CD AND desc_E.CHIT_ID = report.CHIT_ID AND desc_E.LANG_TYPE = 'ENG' AND desc_E.ISDEL <> '1'
	    LEFT JOIN chitdescriptioninfo desc_K         ON desc_K.COMPANY_CD = report.COMPANY_CD AND desc_K.CHIT_ID = report.CHIT_ID AND desc_K.LANG_TYPE = 'KOR' AND desc_K.ISDEL <> '1'
	    
	    LEFT JOIN chitdetaildescriptioninfo desc2_V         ON desc2_V.COMPANY_CD = report.COMPANY_CD AND desc2_V.CHITDETAIL_ID = report.CHITDETAIL_ID AND desc2_V.LANG_TYPE = 'VIET' AND desc2_V.ISDEL <> '1'
	    LEFT JOIN chitdetaildescriptioninfo desc2_E         ON desc2_E.COMPANY_CD = report.COMPANY_CD AND desc2_E.CHITDETAIL_ID = report.CHITDETAIL_ID AND desc2_E.LANG_TYPE = 'ENG' AND desc2_E.ISDEL <> '1'
	    LEFT JOIN chitdetaildescriptioninfo desc2_K         ON desc2_K.COMPANY_CD = report.COMPANY_CD AND desc2_K.CHITDETAIL_ID = report.CHITDETAIL_ID AND desc2_K.LANG_TYPE = 'KOR' AND desc2_K.ISDEL <> '1'
	    ORDER BY report.SORT_GROUP, report.SORT_SEQ;
	
	    -- 9. Dọn dẹp bộ nhớ bảng tạm
	--    DROP TEMPORARY TABLE IF EXISTS tmp_cash_book_detail;
	--    DROP TEMPORARY TABLE IF EXISTS tmp_cash_book_source;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_einvoice_report
DROP PROCEDURE IF EXISTS `rpt_einvoice_report`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_einvoice_report`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_FROM_DATE DATE,
  IN p_TO_DATE DATE,
  IN p_KEYWORD VARCHAR(200),
  IN p_PRINT_LAYOUT VARCHAR(30)
)
BEGIN
  DECLARE v_keyword VARCHAR(200) DEFAULT NULL;
  DECLARE v_print_layout VARCHAR(30) DEFAULT '';
  DECLARE v_period_text VARCHAR(100) DEFAULT '';

  IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
  END IF;

  IF p_FROM_DATE > p_TO_DATE THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
  END IF;

  SET v_keyword = NULLIF(TRIM(IFNULL(p_KEYWORD, '')), '');
  SET v_print_layout = UPPER(TRIM(IFNULL(p_PRINT_LAYOUT, '')));
  SET v_period_text = CONCAT('Từ ngày ', DATE_FORMAT(p_FROM_DATE, '%d-%m-%Y'), ' đến ngày ', DATE_FORMAT(p_TO_DATE, '%d-%m-%Y'));

  IF v_print_layout = 'BOOK' THEN
    DROP TEMPORARY TABLE IF EXISTS `tmp_einv_report_groups`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_einv_report_book_detail`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_einv_report_book_rows`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_einv_report_book_seq`;

    CREATE TEMPORARY TABLE `tmp_einv_report_groups`
    (
      `GROUP_NO` INT NOT NULL,
      `GROUP_LABEL` VARCHAR(255) NOT NULL,
      PRIMARY KEY (`GROUP_NO`)
    ) ENGINE=MEMORY;

    INSERT INTO `tmp_einv_report_groups`
    (`GROUP_NO`, `GROUP_LABEL`)
    VALUES
    (1, '1. Hàng hóa, dịch vụ không chịu thuế giá trị gia tăng (GTGT):'),
    (2, '2. Hàng hoá, dịch vụ không kê khai nộp thuế:'),
    (3, '3. Hàng hoá, dịch vụ chịu thuế suất GTGT 0%:'),
    (4, '4. Hàng hoá, dịch vụ chịu thuế suất GTGT 5%:'),
    (5, '5. Hàng hoá, dịch vụ chịu thuế suất GTGT 8%:'),
    (6, '6. Hàng hoá, dịch vụ chịu thuế suất GTGT 10%:');

    CREATE TEMPORARY TABLE `tmp_einv_report_book_detail`
    (
      `ROW_ID` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
      `GROUP_NO` INT NOT NULL,
      `ROW_NO_IN_GROUP` INT NOT NULL DEFAULT 0,
      `INVOICE_ID` BIGINT UNSIGNED NOT NULL,
      `SORT_NGAY_HD` DATE NULL,
      `SO_HD_SORT` BIGINT UNSIGNED NOT NULL DEFAULT 0,
      `KY_HIEU` VARCHAR(20) NULL,
      `SO_HD` VARCHAR(20) NULL,
      `NGAY_HD` VARCHAR(10) NULL,
      `KHACH_HANG` VARCHAR(400) NULL,
      `MA_SO_THUE` VARCHAR(20) NULL,
      `DOANH_SO_CHUA_THUE` DECIMAL(21,6) NOT NULL DEFAULT 0,
      `THUE_GTGT` DECIMAL(21,6) NOT NULL DEFAULT 0,
      `THUE_PHI_KHAC` DECIMAL(21,6) NOT NULL DEFAULT 0,
      `GHI_CHU` VARCHAR(500) NULL,
      `PHIEU_BAN` VARCHAR(100) NULL,
      `SAN_PHAM` VARCHAR(500) NULL,
      PRIMARY KEY (`ROW_ID`),
      KEY `IX_TMP_EINV_BOOK_GROUP` (`GROUP_NO`, `SORT_NGAY_HD`, `SO_HD_SORT`, `ROW_ID`)
    ) ENGINE=MEMORY;

    CREATE TEMPORARY TABLE `tmp_einv_report_book_rows`
    (
      `ROW_KEY` VARCHAR(50) NOT NULL,
      `ROW_TYPE` VARCHAR(20) NOT NULL,
      `ROW_LEVEL` INT NOT NULL DEFAULT 0,
      `ROW_SORT` INT NOT NULL DEFAULT 0,
      `KY_TINH_THUE_TEXT` VARCHAR(100) NULL,
      `STT` VARCHAR(255) NULL,
      `KY_HIEU` VARCHAR(20) NULL,
      `SO_HD` VARCHAR(20) NULL,
      `NGAY_HD` VARCHAR(10) NULL,
      `KHACH_HANG` VARCHAR(400) NULL,
      `MA_SO_THUE` VARCHAR(20) NULL,
      `DOANH_SO_CHUA_THUE` DECIMAL(21,6) NULL,
      `THUE_GTGT` DECIMAL(21,6) NULL,
      `THUE_PHI_KHAC` DECIMAL(21,6) NULL,
      `GHI_CHU` VARCHAR(500) NULL,
      `PHIEU_BAN` VARCHAR(100) NULL,
      `SAN_PHAM` VARCHAR(500) NULL,
      `SUMMARY_LABEL` VARCHAR(500) NULL,
      PRIMARY KEY (`ROW_KEY`),
      KEY `IX_TMP_EINV_BOOK_ROWS_SORT` (`ROW_SORT`, `ROW_KEY`)
    ) ENGINE=MEMORY;

    CREATE TEMPORARY TABLE `tmp_einv_report_book_seq`
    (
      `ROW_ID` BIGINT UNSIGNED NOT NULL,
      `ROW_NO_IN_GROUP` INT NOT NULL,
      PRIMARY KEY (`ROW_ID`)
    ) ENGINE=MEMORY;

    INSERT INTO `tmp_einv_report_book_detail`
    (
      `GROUP_NO`,
      `INVOICE_ID`,
      `SORT_NGAY_HD`,
      `SO_HD_SORT`,
      `KY_HIEU`,
      `SO_HD`,
      `NGAY_HD`,
      `KHACH_HANG`,
      `MA_SO_THUE`,
      `DOANH_SO_CHUA_THUE`,
      `THUE_GTGT`,
      `THUE_PHI_KHAC`,
      `GHI_CHU`,
      `PHIEU_BAN`,
      `SAN_PHAM`
    )
    SELECT
      src.`GROUP_NO`,
      src.`INVOICE_ID`,
      src.`SORT_NGAY_HD`,
      src.`SO_HD_SORT`,
      src.`KY_HIEU`,
      src.`SO_HD`,
      src.`NGAY_HD`,
      src.`KHACH_HANG`,
      src.`MA_SO_THUE`,
      SUM(src.`LINE_AMOUNT`) AS `DOANH_SO_CHUA_THUE`,
      SUM(CASE WHEN src.`GROUP_NO` IN (3, 4, 5, 6) THEN src.`LINE_AMOUNT` * IFNULL(src.`TAX_RATE_PERCENT`, 0) / 100 ELSE 0 END) AS `THUE_GTGT`,
      0 AS `THUE_PHI_KHAC`,
      '' AS `GHI_CHU`,
      '' AS `PHIEU_BAN`,
      LEFT(GROUP_CONCAT(NULLIF(src.`SAN_PHAM`, '') ORDER BY src.`LINE_STT` SEPARATOR ', '), 500) AS `SAN_PHAM`
    FROM (
      SELECT
        base.`INVOICE_ID`,
        base.`SORT_NGAY_HD`,
        base.`SO_HD_SORT`,
        base.`KY_HIEU`,
        base.`SO_HD`,
        base.`NGAY_HD`,
        base.`KHACH_HANG`,
        base.`MA_SO_THUE`,
        base.`LINE_AMOUNT`,
        base.`LINE_STT`,
        base.`SAN_PHAM`,
        base.`TAX_RATE_PERCENT`,
        CASE
          WHEN base.`TAX_CODE` IN ('KCT', 'KHONGCHUITHUE', 'KHONG_CHIU_THUE', 'KHONGCHIU', 'NONVAT', 'NONTAX') THEN 1
          WHEN base.`TAX_CODE` IN ('KKKNT', 'KHONGKEKHAI', 'KHONG_KE_KHAI', 'KKKNTT') THEN 2
          WHEN base.`TAX_RATE_PERCENT` = 0 THEN 3
          WHEN base.`TAX_RATE_PERCENT` = 5 THEN 4
          WHEN base.`TAX_RATE_PERCENT` = 8 THEN 5
          WHEN base.`TAX_RATE_PERCENT` = 10 THEN 6
          ELSE 6
        END AS `GROUP_NO`
      FROM (
        SELECT
          i.`INVOICE_ID`,
          i.`NLAP` AS `SORT_NGAY_HD`,
          CAST(IFNULL(NULLIF(i.`SHDON`, ''), '0') AS UNSIGNED) AS `SO_HD_SORT`,
          IFNULL(i.`KHHDON`, '') AS `KY_HIEU`,
          IFNULL(i.`SHDON`, '') AS `SO_HD`,
          IFNULL(DATE_FORMAT(i.`NLAP`, '%d-%m-%Y'), '') AS `NGAY_HD`,
          IFNULL(i.`NMUA_TEN`, '') AS `KHACH_HANG`,
          IFNULL(i.`NMUA_MST`, '') AS `MA_SO_THUE`,
          CASE
            WHEN d.`DETAIL_ID` IS NULL THEN IFNULL(i.`TGTCTHUE`, 0)
            ELSE IFNULL(d.`THTIEN`, 0)
          END AS `LINE_AMOUNT`,
          IFNULL(d.`STT`, 0) AS `LINE_STT`,
          IFNULL(d.`THHDVU`, '') AS `SAN_PHAM`,
          UPPER(REPLACE(REPLACE(TRIM(IFNULL(d.`TSUAT`, '')), ' ', ''), ',', '.')) AS `TAX_CODE`,
          CASE
            WHEN REPLACE(UPPER(REPLACE(REPLACE(TRIM(IFNULL(d.`TSUAT`, '')), ' ', ''), ',', '.')), '%', '') REGEXP '^[0-9]+(\\.[0-9]+)?$'
              THEN CAST(REPLACE(UPPER(REPLACE(REPLACE(TRIM(IFNULL(d.`TSUAT`, '')), ' ', ''), ',', '.')), '%', '') AS DECIMAL(8,3))
            ELSE NULL
          END AS `TAX_RATE_PERCENT`
        FROM `einvoice_info` i
        LEFT JOIN `einvoice_seller_info` s
          ON s.`SELLER_ID` = i.`SELLER_ID`
         AND s.`COMPANY_CD` = i.`COMPANY_CD`
         AND s.`ISDEL` = 0
        LEFT JOIN `einvoice_detail` d
          ON d.`INVOICE_ID` = i.`INVOICE_ID`
         AND d.`COMPANY_CD` = i.`COMPANY_CD`
         AND d.`ISDEL` = 0
        WHERE i.`COMPANY_CD` = p_COMPANY_CD
          AND i.`ISDEL` = 0
          AND i.`NLAP` >= p_FROM_DATE
          AND i.`NLAP` <= p_TO_DATE
          AND (
            v_keyword IS NULL
            OR CONCAT_WS(
              ' ',
              i.`THDON`,
              i.`KHMSHDON`,
              i.`KHHDON`,
              i.`SHDON`,
              s.`SELLER_NM`,
              s.`SELLER_TAX_CD`,
              i.`NMUA_TEN`,
              i.`NMUA_MST`,
              i.`NMUA_DCHI`,
              i.`MCCQT`,
              i.`MTRACUU`,
              i.`MTDIEP`,
              i.`MGDDTu`,
              i.`ERROR_MESSAGE`
            ) LIKE CONCAT('%', v_keyword, '%')
          )
      ) base
    ) src
    GROUP BY
      src.`GROUP_NO`,
      src.`INVOICE_ID`,
      src.`SORT_NGAY_HD`,
      src.`SO_HD_SORT`,
      src.`KY_HIEU`,
      src.`SO_HD`,
      src.`NGAY_HD`,
      src.`KHACH_HANG`,
      src.`MA_SO_THUE`
    ORDER BY src.`GROUP_NO`, src.`SORT_NGAY_HD`, src.`SO_HD_SORT`, src.`INVOICE_ID`;

    INSERT INTO `tmp_einv_report_book_seq`
    (`ROW_ID`, `ROW_NO_IN_GROUP`)
    SELECT
      seq.`ROW_ID`,
      seq.`ROW_NO_IN_GROUP`
    FROM (
      SELECT
        ordered.`ROW_ID`,
        @row_no := IF(@group_no = ordered.`GROUP_NO`, @row_no + 1, 1) AS `ROW_NO_IN_GROUP`,
        @group_no := ordered.`GROUP_NO` AS `GROUP_MARK`
      FROM (
        SELECT
          `ROW_ID`,
          `GROUP_NO`
        FROM `tmp_einv_report_book_detail`
        ORDER BY `GROUP_NO`, `SORT_NGAY_HD`, `SO_HD_SORT`, `ROW_ID`
      ) ordered
      CROSS JOIN (SELECT @row_no := 0, @group_no := 0) vars
    ) seq;

    UPDATE `tmp_einv_report_book_detail` detail
    JOIN `tmp_einv_report_book_seq` seq
      ON seq.`ROW_ID` = detail.`ROW_ID`
    SET detail.`ROW_NO_IN_GROUP` = seq.`ROW_NO_IN_GROUP`;

    INSERT INTO `tmp_einv_report_book_rows`
    (
      `ROW_KEY`,
      `ROW_TYPE`,
      `ROW_LEVEL`,
      `ROW_SORT`,
      `KY_TINH_THUE_TEXT`,
      `STT`,
      `KY_HIEU`,
      `SO_HD`,
      `NGAY_HD`,
      `KHACH_HANG`,
      `MA_SO_THUE`,
      `DOANH_SO_CHUA_THUE`,
      `THUE_GTGT`,
      `THUE_PHI_KHAC`,
      `GHI_CHU`,
      `PHIEU_BAN`,
      `SAN_PHAM`,
      `SUMMARY_LABEL`
    )
    SELECT
      CONCAT('SEC_', g.`GROUP_NO`),
      'SECTION',
      0,
      g.`GROUP_NO` * 100000,
      v_period_text,
      g.`GROUP_LABEL`,
      '',
      '',
      '',
      '',
      '',
      NULL,
      NULL,
      NULL,
      '',
      '',
      '',
      g.`GROUP_LABEL`
    FROM `tmp_einv_report_groups` g;

    INSERT INTO `tmp_einv_report_book_rows`
    (
      `ROW_KEY`,
      `ROW_TYPE`,
      `ROW_LEVEL`,
      `ROW_SORT`,
      `KY_TINH_THUE_TEXT`,
      `STT`,
      `KY_HIEU`,
      `SO_HD`,
      `NGAY_HD`,
      `KHACH_HANG`,
      `MA_SO_THUE`,
      `DOANH_SO_CHUA_THUE`,
      `THUE_GTGT`,
      `THUE_PHI_KHAC`,
      `GHI_CHU`,
      `PHIEU_BAN`,
      `SAN_PHAM`,
      `SUMMARY_LABEL`
    )
    SELECT
      CONCAT('DT_', detail.`ROW_ID`),
      'DETAIL',
      1,
      detail.`GROUP_NO` * 100000 + detail.`ROW_NO_IN_GROUP`,
      v_period_text,
      CAST(detail.`ROW_NO_IN_GROUP` AS CHAR),
      detail.`KY_HIEU`,
      detail.`SO_HD`,
      detail.`NGAY_HD`,
      detail.`KHACH_HANG`,
      detail.`MA_SO_THUE`,
      detail.`DOANH_SO_CHUA_THUE`,
      detail.`THUE_GTGT`,
      detail.`THUE_PHI_KHAC`,
      detail.`GHI_CHU`,
      detail.`PHIEU_BAN`,
      detail.`SAN_PHAM`,
      ''
    FROM `tmp_einv_report_book_detail` detail;

    INSERT INTO `tmp_einv_report_book_rows`
    (
      `ROW_KEY`,
      `ROW_TYPE`,
      `ROW_LEVEL`,
      `ROW_SORT`,
      `KY_TINH_THUE_TEXT`,
      `STT`,
      `KY_HIEU`,
      `SO_HD`,
      `NGAY_HD`,
      `KHACH_HANG`,
      `MA_SO_THUE`,
      `DOANH_SO_CHUA_THUE`,
      `THUE_GTGT`,
      `THUE_PHI_KHAC`,
      `GHI_CHU`,
      `PHIEU_BAN`,
      `SAN_PHAM`,
      `SUMMARY_LABEL`
    )
    SELECT
      CONCAT('TOTAL_', g.`GROUP_NO`),
      'SUBTOTAL',
      0,
      g.`GROUP_NO` * 100000 + 90000,
      v_period_text,
      '',
      '',
      '',
      '',
      '',
      '',
      IFNULL(SUM(detail.`DOANH_SO_CHUA_THUE`), 0),
      IFNULL(SUM(detail.`THUE_GTGT`), 0),
      IFNULL(SUM(detail.`THUE_PHI_KHAC`), 0),
      '',
      '',
      '',
      'TỔNG:'
    FROM `tmp_einv_report_groups` g
    LEFT JOIN `tmp_einv_report_book_detail` detail
      ON detail.`GROUP_NO` = g.`GROUP_NO`
    GROUP BY g.`GROUP_NO`;

    INSERT INTO `tmp_einv_report_book_rows`
    (
      `ROW_KEY`,
      `ROW_TYPE`,
      `ROW_LEVEL`,
      `ROW_SORT`,
      `KY_TINH_THUE_TEXT`,
      `STT`,
      `KY_HIEU`,
      `SO_HD`,
      `NGAY_HD`,
      `KHACH_HANG`,
      `MA_SO_THUE`,
      `DOANH_SO_CHUA_THUE`,
      `THUE_GTGT`,
      `THUE_PHI_KHAC`,
      `GHI_CHU`,
      `PHIEU_BAN`,
      `SAN_PHAM`,
      `SUMMARY_LABEL`
    )
    SELECT
      'GRAND_REVENUE',
      'GRAND_TOTAL',
      0,
      700000,
      v_period_text,
      '',
      '',
      '',
      '',
      '',
      '',
      IFNULL(SUM(CASE WHEN detail.`GROUP_NO` IN (3, 4, 5, 6) THEN detail.`DOANH_SO_CHUA_THUE` ELSE 0 END), 0),
      NULL,
      NULL,
      '',
      '',
      '',
      'Tổng doanh thu hàng hoá, dịch vụ bán ra chịu thuế GTGT (*)'
    FROM `tmp_einv_report_book_detail` detail;

    INSERT INTO `tmp_einv_report_book_rows`
    (
      `ROW_KEY`,
      `ROW_TYPE`,
      `ROW_LEVEL`,
      `ROW_SORT`,
      `KY_TINH_THUE_TEXT`,
      `STT`,
      `KY_HIEU`,
      `SO_HD`,
      `NGAY_HD`,
      `KHACH_HANG`,
      `MA_SO_THUE`,
      `DOANH_SO_CHUA_THUE`,
      `THUE_GTGT`,
      `THUE_PHI_KHAC`,
      `GHI_CHU`,
      `PHIEU_BAN`,
      `SAN_PHAM`,
      `SUMMARY_LABEL`
    )
    SELECT
      'GRAND_VAT',
      'GRAND_TOTAL',
      0,
      700001,
      v_period_text,
      '',
      '',
      '',
      '',
      '',
      '',
      IFNULL(SUM(CASE WHEN detail.`GROUP_NO` IN (3, 4, 5, 6) THEN detail.`THUE_GTGT` ELSE 0 END), 0),
      NULL,
      NULL,
      '',
      '',
      '',
      'Tổng số thuế GTGT của hàng hóa, dịch vụ bán ra (**)'
    FROM `tmp_einv_report_book_detail` detail;

    INSERT INTO `tmp_einv_report_book_rows`
    (
      `ROW_KEY`,
      `ROW_TYPE`,
      `ROW_LEVEL`,
      `ROW_SORT`,
      `KY_TINH_THUE_TEXT`,
      `STT`,
      `KY_HIEU`,
      `SO_HD`,
      `NGAY_HD`,
      `KHACH_HANG`,
      `MA_SO_THUE`,
      `DOANH_SO_CHUA_THUE`,
      `THUE_GTGT`,
      `THUE_PHI_KHAC`,
      `GHI_CHU`,
      `PHIEU_BAN`,
      `SAN_PHAM`,
      `SUMMARY_LABEL`
    )
    SELECT
      'GRAND_OTHER_TAX',
      'GRAND_TOTAL',
      0,
      700002,
      v_period_text,
      '',
      '',
      '',
      '',
      '',
      '',
      IFNULL(SUM(detail.`THUE_PHI_KHAC`), 0),
      NULL,
      NULL,
      '',
      '',
      '',
      'Tổng Thuế/Phí khác (***)'
    FROM `tmp_einv_report_book_detail` detail;

    SELECT
      `ROW_KEY`,
      `ROW_TYPE`,
      `ROW_LEVEL`,
      `ROW_SORT`,
      `KY_TINH_THUE_TEXT`,
      `STT`,
      `KY_HIEU`,
      `SO_HD`,
      `NGAY_HD`,
      `KHACH_HANG`,
      `MA_SO_THUE`,
      `DOANH_SO_CHUA_THUE`,
      `THUE_GTGT`,
      `THUE_PHI_KHAC`,
      `GHI_CHU`,
      `PHIEU_BAN`,
      `SAN_PHAM`,
      `SUMMARY_LABEL`
    FROM `tmp_einv_report_book_rows`
    ORDER BY `ROW_SORT`, `ROW_KEY`;
  ELSE
    SELECT
      @row_no := @row_no + 1 AS ROW_NO,
      CONCAT('EINV_', base.INVOICE_ID) AS ROW_KEY,
      base.INVOICE_ID,
      base.NLAP,
      base.THDON,
      base.KHMSHDON,
      base.KHHDON,
      base.SHDON,
      base.SELLER_NM,
      base.SELLER_TAX_CD,
      base.NMUA_TEN,
      base.NMUA_MST,
      base.NMUA_DCHI,
      base.DVTTE,
      base.TGTCTHUE,
      base.TGTKCTHUE,
      base.TGTTTHUE,
      base.TTCKTMAI,
      base.TGTKHAC,
      base.TGTTTBSO,
      base.TCHDON_TEXT,
      base.IS_SIGNED_TEXT,
      base.INVOICE_STATUS_TEXT,
      base.MCCQT,
      base.MTRACUU,
      base.MTDIEP,
      base.MGDDTU,
      base.ERROR_MESSAGE
    FROM (
      SELECT
        i.INVOICE_ID,
        i.NLAP,
        i.THDON,
        i.KHMSHDON,
        i.KHHDON,
        i.SHDON,
        IFNULL(s.SELLER_NM, '') AS SELLER_NM,
        IFNULL(s.SELLER_TAX_CD, '') AS SELLER_TAX_CD,
        IFNULL(i.NMUA_TEN, '') AS NMUA_TEN,
        IFNULL(i.NMUA_MST, '') AS NMUA_MST,
        IFNULL(i.NMUA_DCHI, '') AS NMUA_DCHI,
        IFNULL(i.DVTTE, '') AS DVTTE,
        IFNULL(i.TGTCTHUE, 0) AS TGTCTHUE,
        IFNULL(i.TGTKCTHUE, 0) AS TGTKCTHUE,
        IFNULL(i.TGTTTHUE, 0) AS TGTTTHUE,
        IFNULL(i.TTCKTMAI, 0) AS TTCKTMAI,
        IFNULL(i.TGTKHAC, 0) AS TGTKHAC,
        IFNULL(i.TGTTTBSO, 0) AS TGTTTBSO,
        CASE IFNULL(i.TCHDON, 0)
          WHEN 1 THEN 'Hóa đơn thay thế'
          WHEN 2 THEN 'Hóa đơn điều chỉnh'
          WHEN 5 THEN 'Chiết khấu thương mại'
          ELSE 'Hóa đơn gốc'
        END AS TCHDON_TEXT,
        CASE WHEN IFNULL(i.IS_SIGNED, 0) = 1 THEN 'Đã ký' ELSE 'Chưa ký' END AS IS_SIGNED_TEXT,
        CASE IFNULL(i.INVOICE_STATUS, 0)
          WHEN 1 THEN 'Hóa đơn gốc'
          WHEN 2 THEN 'Bị thay thế'
          WHEN 3 THEN 'Thay thế'
          WHEN 4 THEN 'Bị điều chỉnh'
          WHEN 5 THEN 'Điều chỉnh'
          WHEN 6 THEN 'Lỗi cấp mã CQT'
          ELSE 'Chờ xác thực'
        END AS INVOICE_STATUS_TEXT,
        IFNULL(i.MCCQT, '') AS MCCQT,
        IFNULL(i.MTRACUU, '') AS MTRACUU,
        IFNULL(i.MTDIEP, '') AS MTDIEP,
        IFNULL(i.MGDDTu, '') AS MGDDTU,
        IFNULL(i.ERROR_MESSAGE, '') AS ERROR_MESSAGE
      FROM einvoice_info i
      LEFT JOIN einvoice_seller_info s
        ON s.SELLER_ID = i.SELLER_ID
       AND s.COMPANY_CD = i.COMPANY_CD
      WHERE i.COMPANY_CD = p_COMPANY_CD
        AND i.ISDEL = 0
        AND i.NLAP >= p_FROM_DATE
        AND i.NLAP <= p_TO_DATE
        AND (
          v_keyword IS NULL
          OR CONCAT_WS(
            ' ',
            i.THDON,
            i.KHMSHDON,
            i.KHHDON,
            i.SHDON,
            s.SELLER_NM,
            s.SELLER_TAX_CD,
            i.NMUA_TEN,
            i.NMUA_MST,
            i.NMUA_DCHI,
            i.MCCQT,
            i.MTRACUU,
            i.MTDIEP,
            i.MGDDTu,
            i.ERROR_MESSAGE
          ) LIKE CONCAT('%', v_keyword, '%')
        )
      ORDER BY i.NLAP DESC, i.KHMSHDON, i.KHHDON, i.SHDON, i.INVOICE_ID DESC
    ) base
    CROSS JOIN (SELECT @row_no := 0) seq;
  END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_fa_asset_book
DROP PROCEDURE IF EXISTS `rpt_fa_asset_book`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_fa_asset_book`(
    IN p_COMPANY_CD VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_USE_START_YMD VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_LANGUAGE VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_ACC_CD VARCHAR(2000) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_ASSET_STATUS VARCHAR(500) CHARACTER SET utf8 COLLATE utf8_unicode_ci
)
BEGIN
    DECLARE v_period_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_period_ymd CHAR(8) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_period_end DATE;
    DECLARE v_lang VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci;

    DECLARE v_done INT DEFAULT 0;
    DECLARE v_asset_id BIGINT;
    DECLARE v_start_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_end_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_cur_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_first_amt DECIMAL(18,2);
    DECLARE v_normal_amt DECIMAL(18,2);
    DECLARE v_last_amt DECIMAL(18,2);
    DECLARE v_calc_amt DECIMAL(18,2);

    /*
     * Asset-level cursor.
     * Unlike rpt_fa_depreciation, this report must return one row per asset,
     * therefore depreciation is built at ASSET_ID level instead of ALLOC_ID level.
     */
    DECLARE cur_assets CURSOR FOR
        SELECT
            a.ASSET_ID,
            a.DEPRE_START_YM,
            a.DEPRE_END_YM,
            IFNULL(a.FIRST_DEPRE_AMT, 0),
            IFNULL(a.NORMAL_DEPRE_AMT, 0),
            IFNULL(a.LAST_DEPRE_AMT, 0)
        FROM fa_asset a
        WHERE a.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(a.ISDEL, '0') = '0'
          AND a.USE_START_YMD <= v_period_ymd
          AND (
                IFNULL(TRIM(p_ACC_CD), '') = ''
                OR UPPER(TRIM(p_ACC_CD)) = 'ALL'
                OR FIND_IN_SET(a.ACC_CD, REPLACE(p_ACC_CD, ' ', '')) > 0
              )
          AND (
                IFNULL(TRIM(p_ASSET_STATUS), '') = ''
                OR UPPER(TRIM(p_ASSET_STATUS)) = 'ALL'
                OR FIND_IN_SET(a.STATUS, REPLACE(p_ASSET_STATUS, ' ', '')) > 0
              );

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    /* ------------------------------------------------------------
       1. Normalize language
       ------------------------------------------------------------ */
    SET v_lang = UPPER(IFNULL(NULLIF(TRIM(p_LANGUAGE), ''), 'VIET'));

    IF v_lang IN ('EN', 'ENG', 'ENGLISH') THEN
        SET v_lang = 'ENG';
    ELSEIF v_lang IN ('KR', 'KOR', 'KOREAN') THEN
        SET v_lang = 'KOR';
    ELSEIF v_lang IN ('CN', 'CHN', 'CHINA', 'CHINESE') THEN
        SET v_lang = 'CHINA';
    ELSE
        SET v_lang = 'VIET';
    END IF;

    /* ------------------------------------------------------------
       2. Normalize report date
          Supports:
            YYYYMMDD
            YYYY-MM-DD
            DD/MM/YYYY
       ------------------------------------------------------------ */
    IF LENGTH(TRIM(IFNULL(p_USE_START_YMD, ''))) = 8
       AND TRIM(p_USE_START_YMD) REGEXP '^[0-9]{8}$' THEN

        SET v_period_ymd = TRIM(p_USE_START_YMD);
        SET v_period_end = STR_TO_DATE(v_period_ymd, '%Y%m%d');

    ELSEIF LOCATE('-', TRIM(IFNULL(p_USE_START_YMD, ''))) > 0 THEN

        SET v_period_end = STR_TO_DATE(TRIM(p_USE_START_YMD), '%Y-%m-%d');
        SET v_period_ymd = DATE_FORMAT(v_period_end, '%Y%m%d');

    ELSE

        SET v_period_end = STR_TO_DATE(TRIM(p_USE_START_YMD), '%d/%m/%Y');
        SET v_period_ymd = DATE_FORMAT(v_period_end, '%Y%m%d');

    END IF;

    IF v_period_end IS NULL OR v_period_ymd IS NULL THEN
        SET v_period_end = CURDATE();
        SET v_period_ymd = DATE_FORMAT(v_period_end, '%Y%m%d');
    END IF;

    SET v_period_ym = DATE_FORMAT(v_period_end, '%Y%m');

    /* ------------------------------------------------------------
       3. Monthly depreciation source per asset.
          POSTED rows are inserted first.
          Missing months are then filled by CALC.
       ------------------------------------------------------------ */
    DROP TEMPORARY TABLE IF EXISTS tmp_fa_book_month;

    CREATE TEMPORARY TABLE tmp_fa_book_month (
        ASSET_ID BIGINT NOT NULL,
        DEPRE_YM CHAR(6) NOT NULL,
        DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        SOURCE_TYPE VARCHAR(10) NOT NULL DEFAULT 'POSTED',
        PRIMARY KEY (ASSET_ID, DEPRE_YM)
    ) ENGINE=MEMORY;

    INSERT INTO tmp_fa_book_month (
        ASSET_ID,
        DEPRE_YM,
        DEPRE_AMT,
        SOURCE_TYPE
    )
    SELECT
        p.ASSET_ID,
        p.DEPRE_YM,
        IFNULL(p.DEPRE_AMT, 0),
        'POSTED'
    FROM fa_asset_depre_posted p
    INNER JOIN fa_asset a
        ON a.COMPANY_CD = p.COMPANY_CD
       AND a.ASSET_ID = p.ASSET_ID
       AND IFNULL(a.ISDEL, '0') = '0'
    WHERE p.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(p.CANCEL_YN, 'N') = 'N'
      AND p.DEPRE_YM <= v_period_ym
      AND a.USE_START_YMD <= v_period_ymd
      AND (
            IFNULL(TRIM(p_ACC_CD), '') = ''
            OR UPPER(TRIM(p_ACC_CD)) = 'ALL'
            OR FIND_IN_SET(a.ACC_CD, REPLACE(p_ACC_CD, ' ', '')) > 0
          )
      AND (
            IFNULL(TRIM(p_ASSET_STATUS), '') = ''
            OR UPPER(TRIM(p_ASSET_STATUS)) = 'ALL'
            OR FIND_IN_SET(a.STATUS, REPLACE(p_ASSET_STATUS, ' ', '')) > 0
          )
    ON DUPLICATE KEY UPDATE
        DEPRE_AMT = VALUES(DEPRE_AMT),
        SOURCE_TYPE = 'POSTED';

    /*
     * Fill months that have not yet been posted.
     * This follows the FIRST / NORMAL / LAST approach used by
     * rpt_fa_depreciation, but uses asset-level amounts so the asset book
     * is not duplicated by depreciation allocation lines.
     */
    SET v_done = 0;
    OPEN cur_assets;

    asset_loop: LOOP
        FETCH cur_assets
        INTO v_asset_id, v_start_ym, v_end_ym,
             v_first_amt, v_normal_amt, v_last_amt;

        IF v_done = 1 THEN
            LEAVE asset_loop;
        END IF;

        SET v_cur_ym = v_start_ym;

        WHILE v_cur_ym <= v_end_ym
          AND v_cur_ym <= v_period_ym DO

            IF NOT EXISTS (
                SELECT 1
                FROM tmp_fa_book_month t
                WHERE t.ASSET_ID = v_asset_id
                  AND t.DEPRE_YM = v_cur_ym
            ) THEN

                IF v_cur_ym = v_start_ym THEN
                    SET v_calc_amt = IFNULL(v_first_amt, 0);
                ELSEIF v_cur_ym = v_end_ym THEN
                    SET v_calc_amt = IFNULL(v_last_amt, 0);
                ELSE
                    SET v_calc_amt = IFNULL(v_normal_amt, 0);
                END IF;

                IF IFNULL(v_calc_amt, 0) <> 0 THEN
                    INSERT INTO tmp_fa_book_month (
                        ASSET_ID,
                        DEPRE_YM,
                        DEPRE_AMT,
                        SOURCE_TYPE
                    )
                    VALUES (
                        v_asset_id,
                        v_cur_ym,
                        v_calc_amt,
                        'CALC'
                    );
                END IF;

            END IF;

            SET v_cur_ym = DATE_FORMAT(
                DATE_ADD(
                    STR_TO_DATE(CONCAT(v_cur_ym, '01'), '%Y%m%d'),
                    INTERVAL 1 MONTH
                ),
                '%Y%m'
            );

        END WHILE;
    END LOOP;

    CLOSE cur_assets;

    /* ------------------------------------------------------------
       4. Summarize depreciation to one row per asset.
          OPENING_DEPRE_AMT = depreciation before report month.
          PERIOD_DEPRE_AMT  = depreciation of report month.
          ACCUM_DEPRE_AMT   = depreciation from schedule through report month.
       ------------------------------------------------------------ */
    DROP TEMPORARY TABLE IF EXISTS tmp_fa_book_summary;

    CREATE TEMPORARY TABLE tmp_fa_book_summary (
        ASSET_ID BIGINT NOT NULL,
        OPENING_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        PERIOD_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        ACCUM_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        POSTED_MONTH_COUNT INT NOT NULL DEFAULT 0,
        CALC_MONTH_COUNT INT NOT NULL DEFAULT 0,
        PRIMARY KEY (ASSET_ID)
    ) ENGINE=MEMORY;

    INSERT INTO tmp_fa_book_summary (
        ASSET_ID,
        OPENING_DEPRE_AMT,
        PERIOD_DEPRE_AMT,
        ACCUM_DEPRE_AMT,
        POSTED_MONTH_COUNT,
        CALC_MONTH_COUNT
    )
    SELECT
        t.ASSET_ID,
        SUM(CASE WHEN t.DEPRE_YM < v_period_ym
                 THEN t.DEPRE_AMT ELSE 0 END) AS OPENING_DEPRE_AMT,
        SUM(CASE WHEN t.DEPRE_YM = v_period_ym
                 THEN t.DEPRE_AMT ELSE 0 END) AS PERIOD_DEPRE_AMT,
        SUM(CASE WHEN t.DEPRE_YM <= v_period_ym
                 THEN t.DEPRE_AMT ELSE 0 END) AS ACCUM_DEPRE_AMT,
        SUM(CASE WHEN t.SOURCE_TYPE = 'POSTED' THEN 1 ELSE 0 END) AS POSTED_MONTH_COUNT,
        SUM(CASE WHEN t.SOURCE_TYPE = 'CALC' THEN 1 ELSE 0 END) AS CALC_MONTH_COUNT
    FROM tmp_fa_book_month t
    GROUP BY t.ASSET_ID;

    /* ------------------------------------------------------------
       5. Final asset book: ONE ROW / ASSET
       ------------------------------------------------------------ */
    SELECT
        a.ASSET_ID,
        a.ASSET_CD,
        a.ASSET_NM,

        a.ACC_CD,
        CASE v_lang
            WHEN 'ENG' THEN IFNULL(acc.ACCTITLE_NM_ENG, acc.ACCTITLE_NM_VIET)
            WHEN 'KOR' THEN IFNULL(acc.ACCTITLE_NM_KOR, acc.ACCTITLE_NM_VIET)
            WHEN 'CHINA' THEN IFNULL(acc.ACCTITLE_NM_CHINA, acc.ACCTITLE_NM_VIET)
            ELSE IFNULL(acc.ACCTITLE_NM_VIET, '')
        END AS ACC_NM,

        a.USE_DEPT_CD,
        CASE v_lang
            WHEN 'ENG' THEN IFNULL(dep.DEP_NAME_ENG, dep.DEP_NAME_VIET)
            WHEN 'KOR' THEN IFNULL(dep.DEP_NAME_KOR, dep.DEP_NAME_VIET)
            WHEN 'CHINA' THEN IFNULL(dep.DEP_NAME_CHINA, dep.DEP_NAME_VIET)
            ELSE IFNULL(dep.DEP_NAME_VIET, '')
        END AS USE_DEPT_NM,

        a.RECEIVE_YMD,
        a.USE_START_YMD,
        a.DEPRE_START_YM,
        a.DEPRE_END_YM,
        LAST_DAY(
            STR_TO_DATE(CONCAT(a.DEPRE_END_YM, '01'), '%Y%m%d')
        ) AS DEPRE_END_YMD,

        a.USEFUL_LIFE_MONTH,
        a.NORMAL_MONTH_COUNT,

        IFNULL(a.ORIGINAL_AMT, 0) AS ORIGINAL_AMT,

        /* Opening accumulated depreciation before the selected month:
           opening accumulation already stored in fa_asset
           + monthly depreciation before the report month. */
        LEAST(
            IFNULL(a.ORIGINAL_AMT, 0),
            IFNULL(a.ACCUM_DEPRE_AMT, 0)
            + IFNULL(s.OPENING_DEPRE_AMT, 0)
        ) AS OPENING_ACCUM_DEPRE_AMT,

        GREATEST(
            IFNULL(a.ORIGINAL_AMT, 0)
            - LEAST(
                IFNULL(a.ORIGINAL_AMT, 0),
                IFNULL(a.ACCUM_DEPRE_AMT, 0)
                + IFNULL(s.OPENING_DEPRE_AMT, 0)
              ),
            0
        ) AS OPENING_BOOK_AMT,

        /* Prevent current-period depreciation from exceeding
           the remaining book amount at beginning of month. */
        LEAST(
            IFNULL(s.PERIOD_DEPRE_AMT, 0),
            GREATEST(
                IFNULL(a.ORIGINAL_AMT, 0)
                - LEAST(
                    IFNULL(a.ORIGINAL_AMT, 0),
                    IFNULL(a.ACCUM_DEPRE_AMT, 0)
                    + IFNULL(s.OPENING_DEPRE_AMT, 0)
                  ),
                0
            )
        ) AS PERIOD_DEPRE_AMT,

        LEAST(
            IFNULL(a.ORIGINAL_AMT, 0),
            IFNULL(a.ACCUM_DEPRE_AMT, 0)
            + IFNULL(s.ACCUM_DEPRE_AMT, 0)
        ) AS ACCUM_DEPRE_AMT,

        GREATEST(
            IFNULL(a.ORIGINAL_AMT, 0)
            - LEAST(
                IFNULL(a.ORIGINAL_AMT, 0),
                IFNULL(a.ACCUM_DEPRE_AMT, 0)
                + IFNULL(s.ACCUM_DEPRE_AMT, 0)
              ),
            0
        ) AS END_BOOK_AMT,

        IFNULL(a.REMAIN_DEPRE_AMT, 0) AS REMAIN_DEPRE_AMT_MASTER,
        IFNULL(a.FIRST_DEPRE_AMT, 0) AS FIRST_DEPRE_AMT,
        IFNULL(a.NORMAL_DEPRE_AMT, 0) AS NORMAL_DEPRE_AMT,
        IFNULL(a.LAST_DEPRE_AMT, 0) AS LAST_DEPRE_AMT,

        GREATEST(
            PERIOD_DIFF(a.DEPRE_END_YM, v_period_ym),
            0
        ) AS REMAIN_MONTHS_PERIOD,

        a.ACQ_CHITINFO_ID,
        a.ACQ_CHITDETAIL_ID,
        ci_acq.CHIT_CD AS ACQ_CHIT_CD,
        COALESCE(NULLIF(ci_acq.CHIT_NO, ''), a.ACQ_CHIT_NO) AS ACQ_CHIT_NO,
        ci_acq.CHIT_YMD AS ACQ_CHIT_YMD,
        cd_acq.CHITDETAIL_CD AS ACQ_CHITDETAIL_CD,
        cd_acq.DEBIT AS ACQ_DEBIT,
        cd_acq.CREDIT AS ACQ_CREDIT,
        cd_acq.AMOUNT AS ACQ_CHITDETAIL_AMT,

        a.STATUS,
        '' as STATUS_TEXT,
        a.NOTE,

        IFNULL(s.POSTED_MONTH_COUNT, 0) AS POSTED_MONTH_COUNT,
        IFNULL(s.CALC_MONTH_COUNT, 0) AS CALC_MONTH_COUNT

    FROM fa_asset a

    LEFT JOIN acclist_info acc
        ON acc.COMPANY_CD = a.COMPANY_CD
       AND acc.ACC_CD = a.ACC_CD
       AND IFNULL(acc.ISDEL, '0') <> '1'

    LEFT JOIN department_info dep
        ON dep.COMPANY_CD = a.COMPANY_CD
       AND dep.DEPARTMENT_CD = a.USE_DEPT_CD
       AND IFNULL(dep.ISDEL, '0') <> '1'

    LEFT JOIN chitinfo ci_acq
        ON ci_acq.COMPANY_CD = a.COMPANY_CD
       AND ci_acq.CHIT_ID = a.ACQ_CHITINFO_ID
       AND IFNULL(ci_acq.ISDEL, '0') <> '1'

    LEFT JOIN chitdetailinfo cd_acq
        ON cd_acq.COMPANY_CD = a.COMPANY_CD
       AND cd_acq.CHITDETAIL_ID = a.ACQ_CHITDETAIL_ID
       AND IFNULL(cd_acq.ISDEL, '0') <> '1'

    LEFT JOIN tmp_fa_book_summary s
        ON s.ASSET_ID = a.ASSET_ID

    WHERE a.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(a.ISDEL, '0') = '0'
      AND a.USE_START_YMD <= v_period_ymd
      AND (
            IFNULL(TRIM(p_ACC_CD), '') = ''
            OR UPPER(TRIM(p_ACC_CD)) = 'ALL'
            OR FIND_IN_SET(a.ACC_CD, REPLACE(p_ACC_CD, ' ', '')) > 0
          )
      AND (
            IFNULL(TRIM(p_ASSET_STATUS), '') = ''
            OR UPPER(TRIM(p_ASSET_STATUS)) = 'ALL'
            OR FIND_IN_SET(a.STATUS, REPLACE(p_ASSET_STATUS, ' ', '')) > 0
          )

    ORDER BY a.ACC_CD, a.ASSET_CD;

    DROP TEMPORARY TABLE IF EXISTS tmp_fa_book_summary;
    DROP TEMPORARY TABLE IF EXISTS tmp_fa_book_month;

END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_fa_depreciation
DROP PROCEDURE IF EXISTS `rpt_fa_depreciation`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_fa_depreciation`(

    IN p_COMPANY_CD VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci,

    IN p_USE_START_YMD VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci,

    IN p_LANGUAGE VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci,

    IN p_ACC_CD VARCHAR(2000) CHARACTER SET utf8 COLLATE utf8_unicode_ci,

    IN p_ASSET_STATUS VARCHAR(500) CHARACTER SET utf8 COLLATE utf8_unicode_ci

)
BEGIN

    DECLARE v_period_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;

    DECLARE v_year_start_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;

    DECLARE v_period_ymd CHAR(8) CHARACTER SET utf8 COLLATE utf8_unicode_ci;

    DECLARE v_period_end DATE;

    DECLARE v_lang VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci;



    DECLARE v_done INT DEFAULT 0;

    DECLARE v_asset_id BIGINT;

    DECLARE v_alloc_id BIGINT;

    DECLARE v_start_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;

    DECLARE v_end_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;

    DECLARE v_cur_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;

    DECLARE v_depre_type VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci;

    DECLARE v_calc_amt DECIMAL(18,2);



    DECLARE cur_assets CURSOR FOR

        SELECT

            a.ASSET_ID,

            al.ALLOC_ID,

            a.DEPRE_START_YM,

            a.DEPRE_END_YM

        FROM fa_asset a

        INNER JOIN fa_asset_depre_alloc al

            ON al.COMPANY_CD = a.COMPANY_CD

           AND al.ASSET_ID = a.ASSET_ID

           AND IFNULL(al.ISDEL, '0') = '0'

        WHERE a.COMPANY_CD = p_COMPANY_CD

          AND IFNULL(a.ISDEL, '0') = '0'

          AND a.USE_START_YMD <= v_period_ymd

          AND (

                IFNULL(p_ACC_CD, '') = ''

                OR FIND_IN_SET(a.ACC_CD, REPLACE(p_ACC_CD, ' ', '')) > 0

              )

          AND (

                IFNULL(p_ASSET_STATUS, '') = ''

                OR FIND_IN_SET(a.STATUS, REPLACE(p_ASSET_STATUS, ' ', '')) > 0

              );



    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;



    SET v_lang = UPPER(IFNULL(NULLIF(TRIM(p_LANGUAGE), ''), 'VIET'));

    IF LENGTH(TRIM(IFNULL(p_USE_START_YMD, ''))) = 8

       AND TRIM(p_USE_START_YMD) REGEXP '^[0-9]{8}$' THEN

        SET v_period_ymd = TRIM(p_USE_START_YMD);

        SET v_period_end = STR_TO_DATE(v_period_ymd, '%Y%m%d');

    ELSEIF LOCATE('-', TRIM(IFNULL(p_USE_START_YMD, ''))) > 0 THEN

        SET v_period_end = STR_TO_DATE(TRIM(p_USE_START_YMD), '%Y-%m-%d');

        SET v_period_ymd = DATE_FORMAT(v_period_end, '%Y%m%d');

    ELSE

        SET v_period_end = STR_TO_DATE(TRIM(p_USE_START_YMD), '%d/%m/%Y');

        SET v_period_ymd = DATE_FORMAT(v_period_end, '%Y%m%d');

    END IF;

    IF v_period_end IS NULL OR v_period_ymd IS NULL THEN

        SET v_period_end = CURDATE();

        SET v_period_ymd = DATE_FORMAT(v_period_end, '%Y%m%d');

    END IF;



    SET v_period_ym = DATE_FORMAT(v_period_end, '%Y%m');

    SET v_year_start_ym = CONCAT(YEAR(v_period_end), '01');



    DROP TEMPORARY TABLE IF EXISTS tmp_fa_depre_alloc_month;

    CREATE TEMPORARY TABLE tmp_fa_depre_alloc_month (

        ASSET_ID BIGINT NOT NULL,

        ALLOC_ID BIGINT NOT NULL,

        DEPRE_YM CHAR(6) NOT NULL,

        DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,

        SOURCE_TYPE VARCHAR(10) NOT NULL DEFAULT 'POSTED',

        PRIMARY KEY (ASSET_ID, ALLOC_ID, DEPRE_YM)

    ) ENGINE=MEMORY;



    INSERT INTO tmp_fa_depre_alloc_month (ASSET_ID, ALLOC_ID, DEPRE_YM, DEPRE_AMT, SOURCE_TYPE)

    SELECT

        pa.ASSET_ID,

        pa.ALLOC_ID,

        pa.DEPRE_YM,

        IFNULL(pa.DEPRE_AMT, 0),

        'POSTED'

    FROM fa_asset_depre_posted_alloc pa

    INNER JOIN fa_asset_depre_posted p

        ON p.POST_ID = pa.POST_ID

       AND p.COMPANY_CD = pa.COMPANY_CD

    INNER JOIN fa_asset a

        ON a.COMPANY_CD = pa.COMPANY_CD

       AND a.ASSET_ID = pa.ASSET_ID

       AND IFNULL(a.ISDEL, '0') = '0'

    WHERE pa.COMPANY_CD = p_COMPANY_CD

      AND IFNULL(p.CANCEL_YN, 'N') = 'N'

      AND pa.ALLOC_ID IS NOT NULL

      AND a.USE_START_YMD <= v_period_ymd

      AND (

            IFNULL(p_ACC_CD, '') = ''

            OR FIND_IN_SET(a.ACC_CD, REPLACE(p_ACC_CD, ' ', '')) > 0

          )

      AND (

            IFNULL(p_ASSET_STATUS, '') = ''

            OR FIND_IN_SET(a.STATUS, REPLACE(p_ASSET_STATUS, ' ', '')) > 0

          );



    SET v_done = 0;

    OPEN cur_assets;

    asset_loop: LOOP

        FETCH cur_assets INTO v_asset_id, v_alloc_id, v_start_ym, v_end_ym;

        IF v_done = 1 THEN

            LEAVE asset_loop;

        END IF;



        SET v_cur_ym = v_start_ym;

        WHILE v_cur_ym <= v_end_ym DO

            IF NOT EXISTS (

                SELECT 1

                FROM tmp_fa_depre_alloc_month t

                WHERE t.ASSET_ID = v_asset_id

                  AND t.ALLOC_ID = v_alloc_id

                  AND t.DEPRE_YM = v_cur_ym

            ) THEN

                IF v_cur_ym = v_start_ym THEN

                    SET v_depre_type = 'FIRST';

                ELSEIF v_cur_ym = v_end_ym THEN

                    SET v_depre_type = 'LAST';

                ELSE

                    SET v_depre_type = 'NORMAL';

                END IF;



                SELECT

                    CASE v_depre_type

                        WHEN 'FIRST' THEN IFNULL(al.FIRST_ALLOC_AMT, 0)

                        WHEN 'LAST' THEN IFNULL(al.LAST_ALLOC_AMT, 0)

                        ELSE IFNULL(al.NORMAL_ALLOC_AMT, 0)

                    END

                INTO v_calc_amt

                FROM fa_asset_depre_alloc al

                WHERE al.COMPANY_CD = p_COMPANY_CD

                  AND al.ALLOC_ID = v_alloc_id

                  AND IFNULL(al.ISDEL, '0') = '0'

                LIMIT 1;



                IF IFNULL(v_calc_amt, 0) <> 0 THEN

                    INSERT INTO tmp_fa_depre_alloc_month (ASSET_ID, ALLOC_ID, DEPRE_YM, DEPRE_AMT, SOURCE_TYPE)

                    VALUES (v_asset_id, v_alloc_id, v_cur_ym, v_calc_amt, 'CALC');

                END IF;

            END IF;



            SET v_cur_ym = DATE_FORMAT(

                DATE_ADD(STR_TO_DATE(CONCAT(v_cur_ym, '01'), '%Y%m%d'), INTERVAL 1 MONTH),

                '%Y%m'

            );

        END WHILE;

    END LOOP;

    CLOSE cur_assets;



    /*
     * Summary depreciation by ASSET_ID + ALLOC_ID.
     * OPENING_DEPRE_AMT: depreciation before 01/01 of report year.
     * PERIOD_DEPRE_AMT: depreciation of selected month.
     * PERIOD_ACCUM_DEPRE_AMT: YTD depreciation from 01/01 through selected month.
     * ACCUM_DEPRE_AMT: depreciation generated/posted through selected month.
     * The asset's initial ACCUM_DEPRE_AMT is added later after being allocated to ALLOC_ID.
     */
    DROP TEMPORARY TABLE IF EXISTS tmp_fa_depre_summary;

    CREATE TEMPORARY TABLE tmp_fa_depre_summary (
        ASSET_ID BIGINT NOT NULL,
        ALLOC_ID BIGINT NOT NULL,
        OPENING_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        PERIOD_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        PERIOD_ACCUM_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        ACCUM_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        PRIMARY KEY (ASSET_ID, ALLOC_ID)
    ) ENGINE=MEMORY;

    INSERT INTO tmp_fa_depre_summary (
        ASSET_ID,
        ALLOC_ID,
        OPENING_DEPRE_AMT,
        PERIOD_DEPRE_AMT,
        PERIOD_ACCUM_DEPRE_AMT,
        ACCUM_DEPRE_AMT
    )
    SELECT
        src.ASSET_ID,
        src.ALLOC_ID,
        SUM(CASE
                WHEN src.DEPRE_YM < v_year_start_ym
                THEN src.DEPRE_AMT
                ELSE 0
            END) AS OPENING_DEPRE_AMT,
        SUM(CASE
                WHEN src.DEPRE_YM = v_period_ym
                THEN src.DEPRE_AMT
                ELSE 0
            END) AS PERIOD_DEPRE_AMT,
        SUM(CASE
                WHEN src.DEPRE_YM >= v_year_start_ym
                 AND src.DEPRE_YM <= v_period_ym
                THEN src.DEPRE_AMT
                ELSE 0
            END) AS PERIOD_ACCUM_DEPRE_AMT,
        SUM(CASE
                WHEN src.DEPRE_YM <= v_period_ym
                THEN src.DEPRE_AMT
                ELSE 0
            END) AS ACCUM_DEPRE_AMT
    FROM tmp_fa_depre_alloc_month src
    GROUP BY src.ASSET_ID, src.ALLOC_ID;


    /*
     * Allocate asset-level ORIGINAL_AMT and initial ACCUM_DEPRE_AMT to each ALLOC_ID.
     * Priority for allocation ratio:
     *   1. Planned depreciation amount of each allocation line.
     *   2. ALLOC_RATE when planned amount is zero.
     *   3. Equal split when both are unavailable.
     *
     * This prevents ORIGINAL_AMT / book value from being duplicated when one asset
     * has multiple depreciation allocation lines.
     */
    DROP TEMPORARY TABLE IF EXISTS tmp_fa_alloc_amount;

    CREATE TEMPORARY TABLE tmp_fa_alloc_amount (
        ASSET_ID BIGINT NOT NULL,
        ALLOC_ID BIGINT NOT NULL,
        ORIGINAL_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        INITIAL_ACCUM_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        PRIMARY KEY (ASSET_ID, ALLOC_ID)
    ) ENGINE=MEMORY;

    INSERT INTO tmp_fa_alloc_amount (
        ASSET_ID,
        ALLOC_ID,
        ORIGINAL_AMT,
        INITIAL_ACCUM_DEPRE_AMT
    )
    SELECT
        x.ASSET_ID,
        x.ALLOC_ID,
        ROUND(x.ORIGINAL_AMT * x.ALLOC_RATIO, 2) AS ORIGINAL_AMT,
        ROUND(x.INITIAL_ACCUM_DEPRE_AMT * x.ALLOC_RATIO, 2) AS INITIAL_ACCUM_DEPRE_AMT
    FROM (
        SELECT
            a.ASSET_ID,
            al.ALLOC_ID,
            IFNULL(a.ORIGINAL_AMT, 0) AS ORIGINAL_AMT,
            IFNULL(a.ACCUM_DEPRE_AMT, 0) AS INITIAL_ACCUM_DEPRE_AMT,
            CASE
                WHEN totals.TOTAL_PLAN_AMT <> 0 THEN
                    (
                        IFNULL(al.FIRST_ALLOC_AMT, 0)
                        + IFNULL(al.NORMAL_ALLOC_AMT, 0) * IFNULL(a.NORMAL_MONTH_COUNT, 0)
                        + IFNULL(al.LAST_ALLOC_AMT, 0)
                    ) / totals.TOTAL_PLAN_AMT
                WHEN totals.TOTAL_ALLOC_RATE <> 0 THEN
                    IFNULL(al.ALLOC_RATE, 0) / totals.TOTAL_ALLOC_RATE
                ELSE
                    1 / totals.ALLOC_COUNT
            END AS ALLOC_RATIO
        FROM fa_asset a
        INNER JOIN fa_asset_depre_alloc al
            ON al.COMPANY_CD = a.COMPANY_CD
           AND al.ASSET_ID = a.ASSET_ID
           AND IFNULL(al.ISDEL, '0') = '0'
        INNER JOIN (
            SELECT
                a2.ASSET_ID,
                SUM(
                    IFNULL(al2.FIRST_ALLOC_AMT, 0)
                    + IFNULL(al2.NORMAL_ALLOC_AMT, 0) * IFNULL(a2.NORMAL_MONTH_COUNT, 0)
                    + IFNULL(al2.LAST_ALLOC_AMT, 0)
                ) AS TOTAL_PLAN_AMT,
                SUM(IFNULL(al2.ALLOC_RATE, 0)) AS TOTAL_ALLOC_RATE,
                COUNT(*) AS ALLOC_COUNT
            FROM fa_asset a2
            INNER JOIN fa_asset_depre_alloc al2
                ON al2.COMPANY_CD = a2.COMPANY_CD
               AND al2.ASSET_ID = a2.ASSET_ID
               AND IFNULL(al2.ISDEL, '0') = '0'
            WHERE a2.COMPANY_CD = p_COMPANY_CD
              AND IFNULL(a2.ISDEL, '0') = '0'
            GROUP BY a2.ASSET_ID
        ) totals
            ON totals.ASSET_ID = a.ASSET_ID
        WHERE a.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(a.ISDEL, '0') = '0'
          AND a.USE_START_YMD <= v_period_ymd
          AND (
                IFNULL(p_ACC_CD, '') = ''
                OR FIND_IN_SET(a.ACC_CD, REPLACE(p_ACC_CD, ' ', '')) > 0
              )
          AND (
                IFNULL(p_ASSET_STATUS, '') = ''
                OR FIND_IN_SET(a.STATUS, REPLACE(p_ASSET_STATUS, ' ', '')) > 0
              )
    ) x;


    /*
     * ROUND() can create a 0.01 rounding difference across allocation lines.
     * Put the residual on the last ALLOC_ID so totals always equal the asset amount.
     */
    DROP TEMPORARY TABLE IF EXISTS tmp_fa_alloc_rounding;

    CREATE TEMPORARY TABLE tmp_fa_alloc_rounding (
        ASSET_ID BIGINT NOT NULL,
        TARGET_ALLOC_ID BIGINT NOT NULL,
        ORIGINAL_DIFF DECIMAL(18,2) NOT NULL DEFAULT 0,
        INITIAL_ACCUM_DIFF DECIMAL(18,2) NOT NULL DEFAULT 0,
        PRIMARY KEY (ASSET_ID)
    ) ENGINE=MEMORY;

    INSERT INTO tmp_fa_alloc_rounding (
        ASSET_ID,
        TARGET_ALLOC_ID,
        ORIGINAL_DIFF,
        INITIAL_ACCUM_DIFF
    )
    SELECT
        t.ASSET_ID,
        MAX(t.ALLOC_ID) AS TARGET_ALLOC_ID,
        IFNULL(a.ORIGINAL_AMT, 0) - SUM(t.ORIGINAL_AMT) AS ORIGINAL_DIFF,
        IFNULL(a.ACCUM_DEPRE_AMT, 0) - SUM(t.INITIAL_ACCUM_DEPRE_AMT) AS INITIAL_ACCUM_DIFF
    FROM tmp_fa_alloc_amount t
    INNER JOIN fa_asset a
        ON a.COMPANY_CD = p_COMPANY_CD
       AND a.ASSET_ID = t.ASSET_ID
       AND IFNULL(a.ISDEL, '0') = '0'
    GROUP BY t.ASSET_ID, a.ORIGINAL_AMT, a.ACCUM_DEPRE_AMT;

    UPDATE tmp_fa_alloc_amount t
    INNER JOIN tmp_fa_alloc_rounding r
        ON r.ASSET_ID = t.ASSET_ID
       AND r.TARGET_ALLOC_ID = t.ALLOC_ID
    SET t.ORIGINAL_AMT = t.ORIGINAL_AMT + r.ORIGINAL_DIFF,
        t.INITIAL_ACCUM_DEPRE_AMT = t.INITIAL_ACCUM_DEPRE_AMT + r.INITIAL_ACCUM_DIFF;


    SELECT
        a.ACC_CD,

        CASE v_lang
            WHEN 'ENG' THEN IFNULL(acc.ACCTITLE_NM_ENG, acc.ACCTITLE_NM_VIET)
            WHEN 'KOR' THEN IFNULL(acc.ACCTITLE_NM_KOR, acc.ACCTITLE_NM_VIET)
            WHEN 'CHINA' THEN IFNULL(acc.ACCTITLE_NM_CHINA, acc.ACCTITLE_NM_VIET)
            ELSE IFNULL(acc.ACCTITLE_NM_VIET, '')
        END AS ACC_NM,

        al.CREDIT_ACCT_CD,

        CASE v_lang
            WHEN 'ENG' THEN IFNULL(cr_acc.ACCTITLE_NM_ENG, cr_acc.ACCTITLE_NM_VIET)
            WHEN 'KOR' THEN IFNULL(cr_acc.ACCTITLE_NM_KOR, cr_acc.ACCTITLE_NM_VIET)
            WHEN 'CHINA' THEN IFNULL(cr_acc.ACCTITLE_NM_CHINA, cr_acc.ACCTITLE_NM_VIET)
            ELSE IFNULL(cr_acc.ACCTITLE_NM_VIET, '')
        END AS CREDIT_ACCT_NM,

        al.DEBIT_ACCT_CD,

        CASE v_lang
            WHEN 'ENG' THEN IFNULL(dr_acc.ACCTITLE_NM_ENG, dr_acc.ACCTITLE_NM_VIET)
            WHEN 'KOR' THEN IFNULL(dr_acc.ACCTITLE_NM_KOR, dr_acc.ACCTITLE_NM_VIET)
            WHEN 'CHINA' THEN IFNULL(dr_acc.ACCTITLE_NM_CHINA, dr_acc.ACCTITLE_NM_VIET)
            ELSE IFNULL(dr_acc.ACCTITLE_NM_VIET, '')
        END AS DEBIT_ACCT_NM,

        a.ASSET_CD,
        a.ASSET_NM,
        a.RECEIVE_YMD,
        a.USE_START_YMD,

        LAST_DAY(STR_TO_DATE(CONCAT(a.DEPRE_END_YM, '01'), '%Y%m%d')) AS DEPRE_END_YMD,

        GREATEST(
            PERIOD_DIFF(a.DEPRE_END_YM, DATE_FORMAT(CURDATE(), '%Y%m')),
            0
        ) AS REMAIN_MONTHS_TODAY,

        GREATEST(
            PERIOD_DIFF(a.DEPRE_END_YM, v_period_ym),
            0
        ) AS REMAIN_MONTHS_PERIOD,

        /* Asset original amount allocated to this ALLOC_ID. */
        IFNULL(alloc_amt.ORIGINAL_AMT, 0) AS ORIGINAL_AMT,

        /*
         * Opening is kept as requested: accumulated depreciation through 31/12
         * of the previous year = initial accumulated depreciation + posted/calc
         * depreciation before YYYY01.
         */
        IFNULL(alloc_amt.ORIGINAL_AMT, 0)
            - IFNULL(alloc_amt.INITIAL_ACCUM_DEPRE_AMT, 0)
            - IFNULL(depre_sum.OPENING_DEPRE_AMT, 0) AS OPENING_BOOK_AMT,

        /* Depreciation of the selected month only. */
        IFNULL(depre_sum.PERIOD_DEPRE_AMT, 0) AS PERIOD_DEPRE_AMT,

        /* YTD depreciation: January through selected month. */
        IFNULL(depre_sum.PERIOD_ACCUM_DEPRE_AMT, 0) AS PERIOD_ACCUM_DEPRE_AMT,

        /* Total accumulated depreciation through selected month. */
        IFNULL(alloc_amt.INITIAL_ACCUM_DEPRE_AMT, 0)
            + IFNULL(depre_sum.ACCUM_DEPRE_AMT, 0) AS ACCUM_DEPRE_AMT,

        /* Ending book value at selected month. */
        IFNULL(alloc_amt.ORIGINAL_AMT, 0)
            - IFNULL(alloc_amt.INITIAL_ACCUM_DEPRE_AMT, 0)
            - IFNULL(depre_sum.ACCUM_DEPRE_AMT, 0) AS END_BOOK_AMT

    FROM fa_asset a

    INNER JOIN fa_asset_depre_alloc al
        ON al.COMPANY_CD = a.COMPANY_CD
       AND al.ASSET_ID = a.ASSET_ID
       AND IFNULL(al.ISDEL, '0') = '0'

    LEFT JOIN acclist_info acc
        ON acc.COMPANY_CD = a.COMPANY_CD
       AND acc.ACC_CD = a.ACC_CD
       AND IFNULL(acc.ISDEL, '0') <> '1'

    LEFT JOIN acclist_info cr_acc
        ON cr_acc.COMPANY_CD = al.COMPANY_CD
       AND cr_acc.ACC_CD = al.CREDIT_ACCT_CD
       AND IFNULL(cr_acc.ISDEL, '0') <> '1'

    LEFT JOIN acclist_info dr_acc
        ON dr_acc.COMPANY_CD = al.COMPANY_CD
       AND dr_acc.ACC_CD = al.DEBIT_ACCT_CD
       AND IFNULL(dr_acc.ISDEL, '0') <> '1'

    LEFT JOIN tmp_fa_depre_summary depre_sum
        ON depre_sum.ASSET_ID = a.ASSET_ID
       AND depre_sum.ALLOC_ID = al.ALLOC_ID

    LEFT JOIN tmp_fa_alloc_amount alloc_amt
        ON alloc_amt.ASSET_ID = a.ASSET_ID
       AND alloc_amt.ALLOC_ID = al.ALLOC_ID

    WHERE a.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(a.ISDEL, '0') = '0'
      AND a.USE_START_YMD <= v_period_ymd
      AND (
            IFNULL(p_ACC_CD, '') = ''
            OR FIND_IN_SET(a.ACC_CD, REPLACE(p_ACC_CD, ' ', '')) > 0
          )
      AND (
            IFNULL(p_ASSET_STATUS, '') = ''
            OR FIND_IN_SET(a.STATUS, REPLACE(p_ASSET_STATUS, ' ', '')) > 0
          )
    ORDER BY a.ACC_CD, a.ASSET_CD, al.ALLOC_SEQ;


    DROP TEMPORARY TABLE IF EXISTS tmp_fa_alloc_rounding;
    DROP TEMPORARY TABLE IF EXISTS tmp_fa_alloc_amount;
    DROP TEMPORARY TABLE IF EXISTS tmp_fa_depre_summary;
    DROP TEMPORARY TABLE IF EXISTS tmp_fa_depre_alloc_month;

END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_fa_depreciation_period
DROP PROCEDURE IF EXISTS `rpt_fa_depreciation_period`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_fa_depreciation_period`(
    IN p_COMPANY_CD      VARCHAR(20)   CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_USE_START_YMD   VARCHAR(20)   CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_LANGUAGE        VARCHAR(20)   CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_ACC_CD          VARCHAR(2000) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_ASSET_STATUS    VARCHAR(500)  CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_DEPARTMENT_CD   VARCHAR(500)  CHARACTER SET utf8 COLLATE utf8_unicode_ci
)
BEGIN
    DECLARE v_period_end DATE;
    DECLARE v_period_ymd CHAR(8) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_period_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_year_start_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_lang VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci;

    DECLARE v_done INT DEFAULT 0;
    DECLARE v_asset_id BIGINT;
    DECLARE v_start_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_end_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_cur_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_depre_type VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_first_amt DECIMAL(18,2);
    DECLARE v_normal_amt DECIMAL(18,2);
    DECLARE v_last_amt DECIMAL(18,2);
    DECLARE v_calc_amt DECIMAL(18,2);

    /*
       Keep the same business filter direction as the legacy report:
       - account: ALL/blank = all; comma list = exact codes; single value = prefix
       - status : ALL/blank/5 = all
       - dept   : ALL/blank/A001 = all (A001 was the old "all department" value)
    */
    DECLARE cur_assets CURSOR FOR
        SELECT
            a.ASSET_ID,
            a.DEPRE_START_YM,
            a.DEPRE_END_YM,
            IFNULL(a.FIRST_DEPRE_AMT, 0),
            IFNULL(a.NORMAL_DEPRE_AMT, 0),
            IFNULL(a.LAST_DEPRE_AMT, 0)
        FROM fa_asset a
        WHERE a.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(a.ISDEL, '0') = '0'
          AND a.USE_START_YMD <= v_period_ymd
          AND (
                IFNULL(TRIM(p_ACC_CD), '') = ''
                OR UPPER(TRIM(p_ACC_CD)) = 'ALL'
                OR (
                    LOCATE(',', p_ACC_CD) > 0
                    AND FIND_IN_SET(a.ACC_CD, REPLACE(p_ACC_CD, ' ', '')) > 0
                )
                OR (
                    LOCATE(',', p_ACC_CD) = 0
                    AND a.ACC_CD LIKE CONCAT(TRIM(p_ACC_CD), '%')
                )
              )
          AND (
                IFNULL(TRIM(p_ASSET_STATUS), '') = ''
                OR UPPER(TRIM(p_ASSET_STATUS)) = 'ALL'
                OR TRIM(p_ASSET_STATUS) = '5'
                OR FIND_IN_SET(a.STATUS, REPLACE(p_ASSET_STATUS, ' ', '')) > 0
              )
          AND (
                IFNULL(TRIM(p_DEPARTMENT_CD), '') = ''
                OR UPPER(TRIM(p_DEPARTMENT_CD)) = 'ALL'
                OR UPPER(TRIM(p_DEPARTMENT_CD)) = 'A001'
                OR FIND_IN_SET(IFNULL(a.USE_DEPT_CD, ''), REPLACE(p_DEPARTMENT_CD, ' ', '')) > 0
              );

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    /* ----------------------------------------------------
       1. Normalize input
       ---------------------------------------------------- */
    SET v_lang = UPPER(IFNULL(NULLIF(TRIM(p_LANGUAGE), ''), 'VIET'));

    IF v_lang = 'EN' THEN SET v_lang = 'ENG'; END IF;
    IF v_lang = 'KR' THEN SET v_lang = 'KOR'; END IF;
    IF v_lang IN ('CN', 'CHN') THEN SET v_lang = 'CHINA'; END IF;

    IF LENGTH(TRIM(IFNULL(p_USE_START_YMD, ''))) = 8
       AND TRIM(p_USE_START_YMD) REGEXP '^[0-9]{8}$' THEN
        SET v_period_ymd = TRIM(p_USE_START_YMD);
        SET v_period_end = STR_TO_DATE(v_period_ymd, '%Y%m%d');
    ELSEIF LOCATE('-', TRIM(IFNULL(p_USE_START_YMD, ''))) > 0 THEN
        SET v_period_end = STR_TO_DATE(TRIM(p_USE_START_YMD), '%Y-%m-%d');
        SET v_period_ymd = DATE_FORMAT(v_period_end, '%Y%m%d');
    ELSEIF LOCATE('/', TRIM(IFNULL(p_USE_START_YMD, ''))) > 0 THEN
        SET v_period_end = STR_TO_DATE(TRIM(p_USE_START_YMD), '%d/%m/%Y');
        SET v_period_ymd = DATE_FORMAT(v_period_end, '%Y%m%d');
    ELSE
        SET v_period_end = NULL;
        SET v_period_ymd = NULL;
    END IF;

    IF v_period_end IS NULL OR v_period_ymd IS NULL THEN
        SET v_period_end = CURDATE();
        SET v_period_ymd = DATE_FORMAT(v_period_end, '%Y%m%d');
    END IF;

    SET v_period_ym = DATE_FORMAT(v_period_end, '%Y%m');
    SET v_year_start_ym = CONCAT(YEAR(v_period_end), '01');

    /* ----------------------------------------------------
       2. Monthly depreciation at ASSET level
          - actual posted amount first
          - calculate only when that asset/month is not posted
       ---------------------------------------------------- */
    DROP TEMPORARY TABLE IF EXISTS tmp_fa_period_month;
    CREATE TEMPORARY TABLE tmp_fa_period_month (
        ASSET_ID BIGINT NOT NULL,
        DEPRE_YM CHAR(6) NOT NULL,
        DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        SOURCE_TYPE VARCHAR(10) NOT NULL DEFAULT 'POSTED',
        PRIMARY KEY (ASSET_ID, DEPRE_YM)
    ) ENGINE=MEMORY;

    INSERT INTO tmp_fa_period_month
    (
        ASSET_ID,
        DEPRE_YM,
        DEPRE_AMT,
        SOURCE_TYPE
    )
    SELECT
        p.ASSET_ID,
        p.DEPRE_YM,
        IFNULL(p.DEPRE_AMT, 0),
        'POSTED'
    FROM fa_asset_depre_posted p
    INNER JOIN fa_asset a
        ON a.COMPANY_CD = p.COMPANY_CD
       AND a.ASSET_ID = p.ASSET_ID
       AND IFNULL(a.ISDEL, '0') = '0'
    WHERE p.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(p.CANCEL_YN, 'N') = 'N'
      AND p.DEPRE_YM <= v_period_ym
      AND a.USE_START_YMD <= v_period_ymd
      AND (
            IFNULL(TRIM(p_ACC_CD), '') = ''
            OR UPPER(TRIM(p_ACC_CD)) = 'ALL'
            OR (
                LOCATE(',', p_ACC_CD) > 0
                AND FIND_IN_SET(a.ACC_CD, REPLACE(p_ACC_CD, ' ', '')) > 0
            )
            OR (
                LOCATE(',', p_ACC_CD) = 0
                AND a.ACC_CD LIKE CONCAT(TRIM(p_ACC_CD), '%')
            )
          )
      AND (
            IFNULL(TRIM(p_ASSET_STATUS), '') = ''
            OR UPPER(TRIM(p_ASSET_STATUS)) = 'ALL'
            OR TRIM(p_ASSET_STATUS) = '5'
            OR FIND_IN_SET(a.STATUS, REPLACE(p_ASSET_STATUS, ' ', '')) > 0
          )
      AND (
            IFNULL(TRIM(p_DEPARTMENT_CD), '') = ''
            OR UPPER(TRIM(p_DEPARTMENT_CD)) = 'ALL'
            OR UPPER(TRIM(p_DEPARTMENT_CD)) = 'A001'
            OR FIND_IN_SET(IFNULL(a.USE_DEPT_CD, ''), REPLACE(p_DEPARTMENT_CD, ' ', '')) > 0
          );

    SET v_done = 0;
    OPEN cur_assets;

    asset_loop: LOOP
        FETCH cur_assets
        INTO v_asset_id, v_start_ym, v_end_ym,
             v_first_amt, v_normal_amt, v_last_amt;

        IF v_done = 1 THEN
            LEAVE asset_loop;
        END IF;

        SET v_cur_ym = v_start_ym;

        WHILE v_cur_ym <= v_end_ym
          AND v_cur_ym <= v_period_ym DO

            IF NOT EXISTS (
                SELECT 1
                FROM tmp_fa_period_month t
                WHERE t.ASSET_ID = v_asset_id
                  AND t.DEPRE_YM = v_cur_ym
            ) THEN
                IF v_cur_ym = v_start_ym THEN
                    SET v_depre_type = 'FIRST';
                    SET v_calc_amt = IFNULL(v_first_amt, 0);
                ELSEIF v_cur_ym = v_end_ym THEN
                    SET v_depre_type = 'LAST';
                    SET v_calc_amt = IFNULL(v_last_amt, 0);
                ELSE
                    SET v_depre_type = 'NORMAL';
                    SET v_calc_amt = IFNULL(v_normal_amt, 0);
                END IF;

                IF IFNULL(v_calc_amt, 0) <> 0 THEN
                    INSERT INTO tmp_fa_period_month
                    (
                        ASSET_ID,
                        DEPRE_YM,
                        DEPRE_AMT,
                        SOURCE_TYPE
                    )
                    VALUES
                    (
                        v_asset_id,
                        v_cur_ym,
                        v_calc_amt,
                        'CALC'
                    );
                END IF;
            END IF;

            SET v_cur_ym = DATE_FORMAT(
                DATE_ADD(
                    STR_TO_DATE(CONCAT(v_cur_ym, '01'), '%Y%m%d'),
                    INTERVAL 1 MONTH
                ),
                '%Y%m'
            );
        END WHILE;
    END LOOP;

    CLOSE cur_assets;

    /* ----------------------------------------------------
       3. Depreciation summary for the selected period
       ---------------------------------------------------- */
    DROP TEMPORARY TABLE IF EXISTS tmp_fa_period_summary;
    CREATE TEMPORARY TABLE tmp_fa_period_summary (
        ASSET_ID BIGINT NOT NULL,
        BEFORE_YEAR_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        BEFORE_CURRENT_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        CURRENT_MONTH_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        PERIOD_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        TOTAL_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        POSTED_MONTH_COUNT INT NOT NULL DEFAULT 0,
        CALC_MONTH_COUNT INT NOT NULL DEFAULT 0,
        PRIMARY KEY (ASSET_ID)
    ) ENGINE=MEMORY;

    INSERT INTO tmp_fa_period_summary
    (
        ASSET_ID,
        BEFORE_YEAR_DEPRE_AMT,
        BEFORE_CURRENT_DEPRE_AMT,
        CURRENT_MONTH_DEPRE_AMT,
        PERIOD_DEPRE_AMT,
        TOTAL_DEPRE_AMT,
        POSTED_MONTH_COUNT,
        CALC_MONTH_COUNT
    )
    SELECT
        t.ASSET_ID,
        SUM(CASE
                WHEN t.DEPRE_YM < v_year_start_ym
                THEN t.DEPRE_AMT ELSE 0
            END),
        SUM(CASE
                WHEN t.DEPRE_YM < v_period_ym
                THEN t.DEPRE_AMT ELSE 0
            END),
        SUM(CASE
                WHEN t.DEPRE_YM = v_period_ym
                THEN t.DEPRE_AMT ELSE 0
            END),
        SUM(CASE
                WHEN t.DEPRE_YM >= v_year_start_ym
                 AND t.DEPRE_YM <= v_period_ym
                THEN t.DEPRE_AMT ELSE 0
            END),
        SUM(CASE
                WHEN t.DEPRE_YM <= v_period_ym
                THEN t.DEPRE_AMT ELSE 0
            END),
        SUM(CASE WHEN t.SOURCE_TYPE = 'POSTED' THEN 1 ELSE 0 END),
        SUM(CASE WHEN t.SOURCE_TYPE = 'CALC' THEN 1 ELSE 0 END)
    FROM tmp_fa_period_month t
    GROUP BY t.ASSET_ID;

    /* ----------------------------------------------------
       4. Aggregate depreciation accounts.
          New schema can have multiple allocation rows per asset, while the
          legacy report had one FADEP/FAEX account. GROUP_CONCAT preserves
          all configured accounts without duplicating asset rows.
       ---------------------------------------------------- */
    DROP TEMPORARY TABLE IF EXISTS tmp_fa_period_accounts;
    CREATE TEMPORARY TABLE tmp_fa_period_accounts (
        ASSET_ID BIGINT NOT NULL,
        FADEP_ACC_CD VARCHAR(500) NULL,
        FADEP_NM_VIET VARCHAR(1000) NULL,
        FADEP_NM_ENG VARCHAR(1000) NULL,
        FADEP_NM_KOR VARCHAR(1000) NULL,
        FADEP_NM_CHINA VARCHAR(1000) NULL,
        FAEX_ACC_CD VARCHAR(500) NULL,
        FAEX_NM_VIET VARCHAR(1000) NULL,
        FAEX_NM_ENG VARCHAR(1000) NULL,
        FAEX_NM_KOR VARCHAR(1000) NULL,
        FAEX_NM_CHINA VARCHAR(1000) NULL,
        PRIMARY KEY (ASSET_ID)
    ) ENGINE=MEMORY;

    INSERT INTO tmp_fa_period_accounts
    (
        ASSET_ID,
        FADEP_ACC_CD,
        FADEP_NM_VIET,
        FADEP_NM_ENG,
        FADEP_NM_KOR,
        FADEP_NM_CHINA,
        FAEX_ACC_CD,
        FAEX_NM_VIET,
        FAEX_NM_ENG,
        FAEX_NM_KOR,
        FAEX_NM_CHINA
    )
    SELECT
        al.ASSET_ID,
        GROUP_CONCAT(DISTINCT al.DEBIT_ACCT_CD ORDER BY al.ALLOC_SEQ SEPARATOR ','),
        GROUP_CONCAT(DISTINCT IFNULL(dr.ACCTITLE_NM_VIET, al.DEBIT_ACCT_CD) ORDER BY al.ALLOC_SEQ SEPARATOR ','),
        GROUP_CONCAT(DISTINCT IFNULL(dr.ACCTITLE_NM_ENG,  IFNULL(dr.ACCTITLE_NM_VIET, al.DEBIT_ACCT_CD)) ORDER BY al.ALLOC_SEQ SEPARATOR ','),
        GROUP_CONCAT(DISTINCT IFNULL(dr.ACCTITLE_NM_KOR,  IFNULL(dr.ACCTITLE_NM_VIET, al.DEBIT_ACCT_CD)) ORDER BY al.ALLOC_SEQ SEPARATOR ','),
        GROUP_CONCAT(DISTINCT IFNULL(dr.ACCTITLE_NM_CHINA,IFNULL(dr.ACCTITLE_NM_VIET, al.DEBIT_ACCT_CD)) ORDER BY al.ALLOC_SEQ SEPARATOR ','),
        GROUP_CONCAT(DISTINCT al.CREDIT_ACCT_CD ORDER BY al.ALLOC_SEQ SEPARATOR ','),
        GROUP_CONCAT(DISTINCT IFNULL(cr.ACCTITLE_NM_VIET, al.CREDIT_ACCT_CD) ORDER BY al.ALLOC_SEQ SEPARATOR ','),
        GROUP_CONCAT(DISTINCT IFNULL(cr.ACCTITLE_NM_ENG,  IFNULL(cr.ACCTITLE_NM_VIET, al.CREDIT_ACCT_CD)) ORDER BY al.ALLOC_SEQ SEPARATOR ','),
        GROUP_CONCAT(DISTINCT IFNULL(cr.ACCTITLE_NM_KOR,  IFNULL(cr.ACCTITLE_NM_VIET, al.CREDIT_ACCT_CD)) ORDER BY al.ALLOC_SEQ SEPARATOR ','),
        GROUP_CONCAT(DISTINCT IFNULL(cr.ACCTITLE_NM_CHINA,IFNULL(cr.ACCTITLE_NM_VIET, al.CREDIT_ACCT_CD)) ORDER BY al.ALLOC_SEQ SEPARATOR ',')
    FROM fa_asset_depre_alloc al
    LEFT JOIN acclist_info dr
        ON dr.COMPANY_CD = al.COMPANY_CD
       AND dr.ACC_CD = al.DEBIT_ACCT_CD
       AND IFNULL(dr.ISDEL, '0') <> '1'
    LEFT JOIN acclist_info cr
        ON cr.COMPANY_CD = al.COMPANY_CD
       AND cr.ACC_CD = al.CREDIT_ACCT_CD
       AND IFNULL(cr.ISDEL, '0') <> '1'
    WHERE al.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(al.ISDEL, '0') = '0'
    GROUP BY al.ASSET_ID;

    /* ----------------------------------------------------
       5. Final result
          Column aliases intentionally follow the old menu contract.
       ---------------------------------------------------- */
    SELECT
        /* Asset / account / department */
        a.ASSET_CD AS FA_CD,
        a.ACC_CD AS FA_ACC_CD,
        IFNULL(a.USE_DEPT_CD, '') AS DEPARTMENT_CD,

        IFNULL(di.DEP_NAME_VIET, '') AS DEP_NAME_VIET,
        IFNULL(di.DEP_NAME_ENG,  IFNULL(di.DEP_NAME_VIET, '')) AS DEP_NAME_ENG,
        IFNULL(di.DEP_NAME_KOR,  IFNULL(di.DEP_NAME_VIET, '')) AS DEP_NAME_KOR,
        IFNULL(di.DEP_NAME_CHINA,IFNULL(di.DEP_NAME_VIET, '')) AS DEP_NAME_CHINA,

        /* Legacy setting used to conditionally show this column.
           New API always returns it; UI can hide it when needed. */
        COALESCE(NULLIF(ci.CHIT_NO, ''), NULLIF(a.ACQ_CHIT_NO, ''), '') AS CHIT_NO,

        IFNULL(acc.ACCTITLE_NM_VIET, '') AS FA_ACC_NM_VIET,
        IFNULL(acc.ACCTITLE_NM_ENG,  IFNULL(acc.ACCTITLE_NM_VIET, '')) AS FA_ACC_NM_ENG,
        IFNULL(acc.ACCTITLE_NM_KOR,  IFNULL(acc.ACCTITLE_NM_VIET, '')) AS FA_ACC_NM_KOR,
        IFNULL(acc.ACCTITLE_NM_CHINA,IFNULL(acc.ACCTITLE_NM_VIET, '')) AS FA_ACC_NM_CHINA,

        IFNULL(aa.FADEP_NM_VIET, '') AS FADEP_NM_VIET,
        IFNULL(aa.FADEP_NM_ENG, '') AS FADEP_NM_ENG,
        IFNULL(aa.FADEP_NM_KOR, '') AS FADEP_NM_KOR,
        IFNULL(aa.FADEP_NM_CHINA, '') AS FADEP_NM_CHINA,
        IFNULL(aa.FADEP_ACC_CD, '') AS FADEP_ACC_CD,

        IFNULL(aa.FAEX_NM_VIET, '') AS FAEX_NM_VIET,
        IFNULL(aa.FAEX_NM_ENG, '') AS FAEX_NM_ENG,
        IFNULL(aa.FAEX_NM_KOR, '') AS FAEX_NM_KOR,
        IFNULL(aa.FAEX_NM_CHINA, '') AS FAEX_NM_CHINA,
        IFNULL(aa.FAEX_ACC_CD, '') AS FAEX_ACC_CD,

        /* Not present in new fa_asset schema */
        '' AS MANAGEMENT_CD,
        '' AS MANAGEMENT_NM_VIET,
        '' AS MANAGEMENT_NM_ENG,
        '' AS MANAGEMENT_NM_KOR,
        '' AS MANAGEMENT_NM_CHINA,
        '' AS MANAGEMENT_CD_2,
        '' AS MANAGEMENT_NM_2_VIET,
        '' AS MANAGEMENT_NM_2_ENG,
        '' AS MANAGEMENT_NM_2_KOR,
        '' AS MANAGEMENT_NM_2_CHINA,

        a.ASSET_NM AS FA_NM,
        NULL AS FA_NM_EN,
        NULL AS FA_NM_KR,
        NULL AS FA_NM_CN,
        '' AS FA_PRODUCT_CD,

        CASE
            WHEN IFNULL(a.RECEIVE_YMD, '') REGEXP '^[0-9]{8}$'
            THEN STR_TO_DATE(a.RECEIVE_YMD, '%Y%m%d')
            ELSE NULL
        END AS ACQ_YMD,

        CASE
            WHEN IFNULL(a.USE_START_YMD, '') REGEXP '^[0-9]{8}$'
            THEN STR_TO_DATE(a.USE_START_YMD, '%Y%m%d')
            ELSE NULL
        END AS USE_YMD,

        GREATEST(
            DATEDIFF(
                v_period_end,
                STR_TO_DATE(a.USE_START_YMD, '%Y%m%d')
            ),
            0
        ) AS LAST_DAYS,

        GREATEST(
            DATEDIFF(
                LAST_DAY(STR_TO_DATE(CONCAT(a.DEPRE_END_YM, '01'), '%Y%m%d')),
                v_period_end
            ) + 1,
            0
        ) AS REMAIN_DAYS,

        IFNULL(a.USEFUL_LIFE_MONTH, 0) AS DEP_MONTH,

        GREATEST(
            PERIOD_DIFF(a.DEPRE_END_YM, v_period_ym),
            0
        ) AS REMAIN_TERM,

        IFNULL(a.ORIGINAL_AMT, 0) AS ACQ_MONEY,

        /* VAT acquisition cost is not stored in current fa_asset/chitdetailinfo */
        0.0 AS VAT_COST,

        /* Current master balance before future planned depreciation */
        GREATEST(IFNULL(a.REMAIN_DEPRE_AMT, 0), 0) AS BALANCE,

        /* Opening accumulated depreciation migrated/stored on asset master */
        GREATEST(IFNULL(a.ACCUM_DEPRE_AMT, 0), 0) AS HANG_MONEY,

        /* No stop/sale date column in new schema */
        NULL AS STOP_YMD,
        a.STATUS,
        '' as STATUS_TEXT,
        0.0 AS SALE_MONEY,

        /* Accumulated depreciation before current fiscal year */
        LEAST(
            IFNULL(a.ORIGINAL_AMT, 0),
            GREATEST(IFNULL(a.ACCUM_DEPRE_AMT, 0), 0)
            + GREATEST(IFNULL(ds.BEFORE_YEAR_DEPRE_AMT, 0), 0)
        ) AS PRE_PERIOD_ACCUMONEY,

        /* Remaining book value at beginning of current fiscal year */
        GREATEST(
            IFNULL(a.ORIGINAL_AMT, 0)
            - LEAST(
                IFNULL(a.ORIGINAL_AMT, 0),
                GREATEST(IFNULL(a.ACCUM_DEPRE_AMT, 0), 0)
                + GREATEST(IFNULL(ds.BEFORE_YEAR_DEPRE_AMT, 0), 0)
              ),
            0
        ) AS PRIOR_REMAINMONEY,

        /* Depreciation of selected month, clipped to book value before month */
        LEAST(
            GREATEST(IFNULL(ds.CURRENT_MONTH_DEPRE_AMT, 0), 0),
            GREATEST(
                IFNULL(a.ORIGINAL_AMT, 0)
                - LEAST(
                    IFNULL(a.ORIGINAL_AMT, 0),
                    GREATEST(IFNULL(a.ACCUM_DEPRE_AMT, 0), 0)
                    + GREATEST(IFNULL(ds.BEFORE_CURRENT_DEPRE_AMT, 0), 0)
                  ),
                0
            )
        ) AS DEPMONTHMONEY,

        /* Depreciation in current fiscal year up to report month */
        GREATEST(
            LEAST(
                IFNULL(a.ORIGINAL_AMT, 0),
                GREATEST(IFNULL(a.ACCUM_DEPRE_AMT, 0), 0)
                + GREATEST(IFNULL(ds.TOTAL_DEPRE_AMT, 0), 0)
            )
            - LEAST(
                IFNULL(a.ORIGINAL_AMT, 0),
                GREATEST(IFNULL(a.ACCUM_DEPRE_AMT, 0), 0)
                + GREATEST(IFNULL(ds.BEFORE_YEAR_DEPRE_AMT, 0), 0)
              ),
            0
        ) AS PERIOD_ACCUMONEY,

        /* Total accumulated depreciation as of report date */
        LEAST(
            IFNULL(a.ORIGINAL_AMT, 0),
            GREATEST(IFNULL(a.ACCUM_DEPRE_AMT, 0), 0)
            + GREATEST(IFNULL(ds.TOTAL_DEPRE_AMT, 0), 0)
        ) AS ACCUMONEY,

        /* Remaining book value as of report date */
        GREATEST(
            IFNULL(a.ORIGINAL_AMT, 0)
            - LEAST(
                IFNULL(a.ORIGINAL_AMT, 0),
                GREATEST(IFNULL(a.ACCUM_DEPRE_AMT, 0), 0)
                + GREATEST(IFNULL(ds.TOTAL_DEPRE_AMT, 0), 0)
              ),
            0
        ) AS REMAINMONEY,

        /* Legacy fields without equivalent source in the new FA schema */
        '' AS STORE_CD,
        '' AS STORE_NM,
        0.0 AS QUANTITY,
        '' AS UNIT_NM,
        '' AS VAT_CHIT_NO,
        NULL AS VAT_YMD,
        0.0 AS LIQUIDATE,

        IFNULL(a.NORMAL_DEPRE_AMT, 0) AS DEP_MONEY_MONTH_DEFAULT,
        '' AS REASON_SELL,

        /* New helper fields for the web/API layer */
        a.ASSET_ID,
        a.DEPRE_START_YM,
        a.DEPRE_END_YM,
        IFNULL(a.NORMAL_MONTH_COUNT, 0) AS NORMAL_MONTH_COUNT,
        IFNULL(ds.POSTED_MONTH_COUNT, 0) AS POSTED_MONTH_COUNT,
        IFNULL(ds.CALC_MONTH_COUNT, 0) AS CALC_MONTH_COUNT,

        CASE v_lang
            WHEN 'ENG' THEN IFNULL(acc.ACCTITLE_NM_ENG, IFNULL(acc.ACCTITLE_NM_VIET, ''))
            WHEN 'KOR' THEN IFNULL(acc.ACCTITLE_NM_KOR, IFNULL(acc.ACCTITLE_NM_VIET, ''))
            WHEN 'CHINA' THEN IFNULL(acc.ACCTITLE_NM_CHINA, IFNULL(acc.ACCTITLE_NM_VIET, ''))
            ELSE IFNULL(acc.ACCTITLE_NM_VIET, '')
        END AS FA_ACC_NM,

        CASE v_lang
            WHEN 'ENG' THEN IFNULL(di.DEP_NAME_ENG, IFNULL(di.DEP_NAME_VIET, ''))
            WHEN 'KOR' THEN IFNULL(di.DEP_NAME_KOR, IFNULL(di.DEP_NAME_VIET, ''))
            WHEN 'CHINA' THEN IFNULL(di.DEP_NAME_CHINA, IFNULL(di.DEP_NAME_VIET, ''))
            ELSE IFNULL(di.DEP_NAME_VIET, '')
        END AS DEPARTMENT_NM

    FROM fa_asset a

    LEFT JOIN acclist_info acc
        ON acc.COMPANY_CD = a.COMPANY_CD
       AND acc.ACC_CD = a.ACC_CD
       AND IFNULL(acc.ISDEL, '0') <> '1'

    LEFT JOIN department_info di
        ON di.COMPANY_CD = a.COMPANY_CD
       AND di.DEPARTMENT_CD = a.USE_DEPT_CD
       AND IFNULL(di.ISDEL, '0') <> '1'

    LEFT JOIN chitdetailinfo acqd
        ON acqd.COMPANY_CD = a.COMPANY_CD
       AND acqd.CHITDETAIL_ID = a.ACQ_CHITDETAIL_ID
       AND IFNULL(acqd.ISDEL, '0') <> '1'

    LEFT JOIN chitinfo ci
        ON ci.COMPANY_CD = a.COMPANY_CD
       AND ci.CHIT_ID = IFNULL(a.ACQ_CHITINFO_ID, acqd.CHIT_ID)
       AND IFNULL(ci.ISDEL, '0') <> '1'

    LEFT JOIN tmp_fa_period_summary ds
        ON ds.ASSET_ID = a.ASSET_ID

    LEFT JOIN tmp_fa_period_accounts aa
        ON aa.ASSET_ID = a.ASSET_ID

    WHERE a.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(a.ISDEL, '0') = '0'
      AND a.USE_START_YMD <= v_period_ymd
      AND (
            IFNULL(TRIM(p_ACC_CD), '') = ''
            OR UPPER(TRIM(p_ACC_CD)) = 'ALL'
            OR (
                LOCATE(',', p_ACC_CD) > 0
                AND FIND_IN_SET(a.ACC_CD, REPLACE(p_ACC_CD, ' ', '')) > 0
            )
            OR (
                LOCATE(',', p_ACC_CD) = 0
                AND a.ACC_CD LIKE CONCAT(TRIM(p_ACC_CD), '%')
            )
          )
      AND (
            IFNULL(TRIM(p_ASSET_STATUS), '') = ''
            OR UPPER(TRIM(p_ASSET_STATUS)) = 'ALL'
            OR TRIM(p_ASSET_STATUS) = '5'
            OR FIND_IN_SET(a.STATUS, REPLACE(p_ASSET_STATUS, ' ', '')) > 0
          )
      AND (
            IFNULL(TRIM(p_DEPARTMENT_CD), '') = ''
            OR UPPER(TRIM(p_DEPARTMENT_CD)) = 'ALL'
            OR UPPER(TRIM(p_DEPARTMENT_CD)) = 'A001'
            OR FIND_IN_SET(IFNULL(a.USE_DEPT_CD, ''), REPLACE(p_DEPARTMENT_CD, ' ', '')) > 0
          )

    ORDER BY a.ACC_CD, a.ASSET_CD;

    DROP TEMPORARY TABLE IF EXISTS tmp_fa_period_accounts;
    DROP TEMPORARY TABLE IF EXISTS tmp_fa_period_summary;
    DROP TEMPORARY TABLE IF EXISTS tmp_fa_period_month;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_fa_depreciation_report
DROP PROCEDURE IF EXISTS `rpt_fa_depreciation_report`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_fa_depreciation_report`(
    IN p_COMPANY_CD VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_USE_START_YMD VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_LANGUAGE VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_ACC_CD VARCHAR(2000) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_ASSET_STATUS VARCHAR(500) CHARACTER SET utf8 COLLATE utf8_unicode_ci
)
BEGIN
    DECLARE v_period_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_year_start_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_period_end DATE;
    DECLARE v_lang VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci;

    DECLARE v_done INT DEFAULT 0;
    DECLARE v_asset_id BIGINT;
    DECLARE v_alloc_id BIGINT;
    DECLARE v_start_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_end_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_cur_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_depre_type VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_calc_amt DECIMAL(18,2);
    
    DECLARE cur_assets CURSOR FOR
        SELECT
            a.ASSET_ID,
            al.ALLOC_ID,
            a.DEPRE_START_YM,
            a.DEPRE_END_YM
        FROM fa_asset a
        INNER JOIN fa_asset_depre_alloc al
            ON al.COMPANY_CD = a.COMPANY_CD
           AND al.ASSET_ID = a.ASSET_ID
           AND IFNULL(al.ISDEL, '0') = '0'
        WHERE a.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(a.ISDEL, '0') = '0'
          AND a.USE_START_YMD <= v_period_end
          AND (
                IFNULL(p_ACC_CD, '') = ''
                OR FIND_IN_SET(a.ACC_CD, REPLACE(p_ACC_CD, ' ', '')) > 0
              )
          AND (
                IFNULL(p_ASSET_STATUS, '') = ''
                OR FIND_IN_SET(a.STATUS, REPLACE(p_ASSET_STATUS, ' ', '')) > 0
              );

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    SET v_lang = UPPER(IFNULL(NULLIF(TRIM(p_LANGUAGE), ''), 'VIET'));
    IF LOCATE('-', TRIM(IFNULL(p_TO_DATE, ''))) > 0 THEN
        SET v_period_end = STR_TO_DATE(TRIM(p_TO_DATE), '%Y-%m-%d');
    ELSE
        SET v_period_end = STR_TO_DATE(TRIM(p_TO_DATE), '%d/%m/%Y');
    END IF;
    IF v_period_end IS NULL THEN
        SET v_period_end = CURDATE();
    END IF;

    SET v_period_ym = DATE_FORMAT(v_period_end, '%Y%m');
    SET v_year_start_ym = CONCAT(YEAR(v_period_end), '01');

    DROP TEMPORARY TABLE IF EXISTS tmp_fa_depre_alloc_month;
    CREATE TEMPORARY TABLE tmp_fa_depre_alloc_month (
        ASSET_ID BIGINT NOT NULL,
        ALLOC_ID BIGINT NOT NULL,
        DEPRE_YM CHAR(6) NOT NULL,
        DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        SOURCE_TYPE VARCHAR(10) NOT NULL DEFAULT 'POSTED',
        PRIMARY KEY (ASSET_ID, ALLOC_ID, DEPRE_YM)
    ) ENGINE=MEMORY;

    INSERT INTO tmp_fa_depre_alloc_month (ASSET_ID, ALLOC_ID, DEPRE_YM, DEPRE_AMT, SOURCE_TYPE)
    SELECT
        pa.ASSET_ID,
        pa.ALLOC_ID,
        pa.DEPRE_YM,
        IFNULL(pa.DEPRE_AMT, 0),
        'POSTED'
    FROM fa_asset_depre_posted_alloc pa
    INNER JOIN fa_asset_depre_posted p
        ON p.POST_ID = pa.POST_ID
       AND p.COMPANY_CD = pa.COMPANY_CD
    INNER JOIN fa_asset a
        ON a.COMPANY_CD = pa.COMPANY_CD
       AND a.ASSET_ID = pa.ASSET_ID
       AND IFNULL(a.ISDEL, '0') = '0'
    WHERE pa.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(p.CANCEL_YN, 'N') = 'N'
      AND pa.ALLOC_ID IS NOT NULL
      AND a.USE_START_YMD <= v_period_end
      AND (
            IFNULL(p_ACC_CD, '') = ''
            OR FIND_IN_SET(a.ACC_CD, REPLACE(p_ACC_CD, ' ', '')) > 0
          )
      AND (
            IFNULL(p_ASSET_STATUS, '') = ''
            OR FIND_IN_SET(a.STATUS, REPLACE(p_ASSET_STATUS, ' ', '')) > 0
          );

    SET v_done = 0;
    OPEN cur_assets;
    asset_loop: LOOP
        FETCH cur_assets INTO v_asset_id, v_alloc_id, v_start_ym, v_end_ym;
        IF v_done = 1 THEN
            LEAVE asset_loop;
        END IF;

        SET v_cur_ym = v_start_ym;
        WHILE v_cur_ym <= v_end_ym DO
            IF NOT EXISTS (
                SELECT 1
                FROM tmp_fa_depre_alloc_month t
                WHERE t.ASSET_ID = v_asset_id
                  AND t.ALLOC_ID = v_alloc_id
                  AND t.DEPRE_YM = v_cur_ym
            ) THEN
                IF v_cur_ym = v_start_ym THEN
                    SET v_depre_type = 'FIRST';
                ELSEIF v_cur_ym = v_end_ym THEN
                    SET v_depre_type = 'LAST';
                ELSE
                    SET v_depre_type = 'NORMAL';
                END IF;

                SELECT
                    CASE v_depre_type
                        WHEN 'FIRST' THEN IFNULL(al.FIRST_ALLOC_AMT, 0)
                        WHEN 'LAST' THEN IFNULL(al.LAST_ALLOC_AMT, 0)
                        ELSE IFNULL(al.NORMAL_ALLOC_AMT, 0)
                    END
                INTO v_calc_amt
                FROM fa_asset_depre_alloc al
                WHERE al.COMPANY_CD = p_COMPANY_CD
                  AND al.ALLOC_ID = v_alloc_id
                  AND IFNULL(al.ISDEL, '0') = '0'
                LIMIT 1;

                IF IFNULL(v_calc_amt, 0) <> 0 THEN
                    INSERT INTO tmp_fa_depre_alloc_month (ASSET_ID, ALLOC_ID, DEPRE_YM, DEPRE_AMT, SOURCE_TYPE)
                    VALUES (v_asset_id, v_alloc_id, v_cur_ym, v_calc_amt, 'CALC');
                END IF;
            END IF;

            SET v_cur_ym = DATE_FORMAT(
                DATE_ADD(STR_TO_DATE(CONCAT(v_cur_ym, '01'), '%Y%m%d'), INTERVAL 1 MONTH),
                '%Y%m'
            );
        END WHILE;
    END LOOP;
    CLOSE cur_assets;

    DROP TEMPORARY TABLE IF EXISTS tmp_fa_depre_summary;
    CREATE TEMPORARY TABLE tmp_fa_depre_summary (
        ASSET_ID BIGINT NOT NULL,
        ALLOC_ID BIGINT NOT NULL,
        OPENING_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        PERIOD_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        ACCUM_DEPRE_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        PRIMARY KEY (ASSET_ID, ALLOC_ID)
    ) ENGINE=MEMORY;

    INSERT INTO tmp_fa_depre_summary (ASSET_ID, ALLOC_ID, OPENING_DEPRE_AMT, PERIOD_DEPRE_AMT, ACCUM_DEPRE_AMT)
    SELECT
        src.ASSET_ID,
        src.ALLOC_ID,
        SUM(CASE WHEN src.DEPRE_YM < v_year_start_ym THEN src.DEPRE_AMT ELSE 0 END),
        SUM(CASE WHEN src.DEPRE_YM = v_period_ym THEN src.DEPRE_AMT ELSE 0 END),
        SUM(CASE WHEN src.DEPRE_YM <= v_period_ym THEN src.DEPRE_AMT ELSE 0 END)
    FROM tmp_fa_depre_alloc_month src
    GROUP BY src.ASSET_ID, src.ALLOC_ID;

    SELECT
        a.ACC_CD,
        CASE v_lang
            WHEN 'ENG' THEN IFNULL(acc.ACCTITLE_NM_ENG, acc.ACCTITLE_NM_VIET)
            WHEN 'KOR' THEN IFNULL(acc.ACCTITLE_NM_KOR, acc.ACCTITLE_NM_VIET)
            WHEN 'CHINA' THEN IFNULL(acc.ACCTITLE_NM_CHINA, acc.ACCTITLE_NM_VIET)
            ELSE IFNULL(acc.ACCTITLE_NM_VIET, '')
        END AS ACC_NM,
        al.CREDIT_ACCT_CD,
        CASE v_lang
            WHEN 'ENG' THEN IFNULL(cr_acc.ACCTITLE_NM_ENG, cr_acc.ACCTITLE_NM_VIET)
            WHEN 'KOR' THEN IFNULL(cr_acc.ACCTITLE_NM_KOR, cr_acc.ACCTITLE_NM_VIET)
            WHEN 'CHINA' THEN IFNULL(cr_acc.ACCTITLE_NM_CHINA, cr_acc.ACCTITLE_NM_VIET)
            ELSE IFNULL(cr_acc.ACCTITLE_NM_VIET, '')
        END AS CREDIT_ACCT_NM,
        al.DEBIT_ACCT_CD,
        CASE v_lang
            WHEN 'ENG' THEN IFNULL(dr_acc.ACCTITLE_NM_ENG, dr_acc.ACCTITLE_NM_VIET)
            WHEN 'KOR' THEN IFNULL(dr_acc.ACCTITLE_NM_KOR, dr_acc.ACCTITLE_NM_VIET)
            WHEN 'CHINA' THEN IFNULL(dr_acc.ACCTITLE_NM_CHINA, dr_acc.ACCTITLE_NM_VIET)
            ELSE IFNULL(dr_acc.ACCTITLE_NM_VIET, '')
        END AS DEBIT_ACCT_NM,
        a.ASSET_CD,
        a.ASSET_NM,
        a.RECEIVE_YMD,
        a.USE_START_YMD,
        LAST_DAY(STR_TO_DATE(CONCAT(a.DEPRE_END_YM, '01'), '%Y%m%d')) AS DEPRE_END_YMD,
        GREATEST(
            PERIOD_DIFF(a.DEPRE_END_YM, DATE_FORMAT(CURDATE(), '%Y%m')),
            0
        ) AS REMAIN_MONTHS_TODAY,
        GREATEST(
            PERIOD_DIFF(a.DEPRE_END_YM, v_period_ym),
            0
        ) AS REMAIN_MONTHS_PERIOD,
        IFNULL(a.ORIGINAL_AMT, 0) AS ORIGINAL_AMT,
        IFNULL(a.ORIGINAL_AMT, 0) - IFNULL(depre_sum.OPENING_DEPRE_AMT, 0) AS OPENING_BOOK_AMT,
        IFNULL(depre_sum.PERIOD_DEPRE_AMT, 0) AS PERIOD_DEPRE_AMT,
        IFNULL(depre_sum.PERIOD_DEPRE_AMT, 0) AS PERIOD_ACCUM_DEPRE_AMT,
        IFNULL(depre_sum.ACCUM_DEPRE_AMT, 0) AS ACCUM_DEPRE_AMT,
        IFNULL(a.ORIGINAL_AMT, 0) - IFNULL(depre_sum.ACCUM_DEPRE_AMT, 0) AS END_BOOK_AMT
    FROM fa_asset a
    INNER JOIN fa_asset_depre_alloc al
        ON al.COMPANY_CD = a.COMPANY_CD
       AND al.ASSET_ID = a.ASSET_ID
       AND IFNULL(al.ISDEL, '0') = '0'
    LEFT JOIN acclist_info acc
        ON acc.COMPANY_CD = a.COMPANY_CD
       AND acc.ACC_CD = a.ACC_CD
       AND IFNULL(acc.ISDEL, '0') <> '1'
    LEFT JOIN acclist_info cr_acc
        ON cr_acc.COMPANY_CD = al.COMPANY_CD
       AND cr_acc.ACC_CD = al.CREDIT_ACCT_CD
       AND IFNULL(cr_acc.ISDEL, '0') <> '1'
    LEFT JOIN acclist_info dr_acc
        ON dr_acc.COMPANY_CD = al.COMPANY_CD
       AND dr_acc.ACC_CD = al.DEBIT_ACCT_CD
       AND IFNULL(dr_acc.ISDEL, '0') <> '1'
    LEFT JOIN tmp_fa_depre_summary depre_sum
        ON depre_sum.ASSET_ID = a.ASSET_ID
       AND depre_sum.ALLOC_ID = al.ALLOC_ID
    WHERE a.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(a.ISDEL, '0') = '0'
      AND a.USE_START_YMD <= v_period_end
      AND (
            IFNULL(p_ACC_CD, '') = ''
            OR FIND_IN_SET(a.ACC_CD, REPLACE(p_ACC_CD, ' ', '')) > 0
          )
      AND (
            IFNULL(p_ASSET_STATUS, '') = ''
            OR FIND_IN_SET(a.STATUS, REPLACE(p_ASSET_STATUS, ' ', '')) > 0
          )
    ORDER BY a.ACC_CD, a.ASSET_CD, al.ALLOC_SEQ;

    DROP TEMPORARY TABLE IF EXISTS tmp_fa_depre_summary;
    DROP TEMPORARY TABLE IF EXISTS tmp_fa_depre_alloc_month;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_fixed_asset_info
DROP PROCEDURE IF EXISTS `rpt_fixed_asset_info`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_fixed_asset_info`(
    IN `p_COMPANY_CD` VARCHAR(20),
    IN `p_ASSET_ID` BIGINT,
    IN `p_ASSET_CD` VARCHAR(50),
    IN `p_LANGUAGE` VARCHAR(20)
)
BEGIN
    SET @rownum := 0;

    SELECT
        A.ASSET_ID,
        A.COMPANY_CD,
        A.ASSET_CD,
        A.ASSET_NM,
        A.ACC_CD,
        IFNULL(B.ACCTITLE_NM_VIET, '') AS ACC_NM_VIET,
        IFNULL(B.ACCTITLE_NM_ENG, '') AS ACC_NM_ENG,
        IFNULL(B.ACCTITLE_NM_KOR, '') AS ACC_NM_KOR,
        IFNULL(B.ACCTITLE_NM_CHINA, '') AS ACC_NM_CHINA,
        A.USE_DEPT_CD,
        A.RECEIVE_YMD,
        A.USE_START_YMD,
        A.DEPRE_START_YM,
        A.DEPRE_END_YM,
        A.USEFUL_LIFE_MONTH,
        A.NORMAL_MONTH_COUNT,
        A.ORIGINAL_AMT,
        A.ACCUM_DEPRE_AMT,
        A.REMAIN_DEPRE_AMT,
        A.FIRST_DEPRE_AMT,
        A.NORMAL_DEPRE_AMT,
        A.LAST_DEPRE_AMT,
        A.ACQ_CHITINFO_ID,
        A.ACQ_CHITDETAIL_ID,
        A.ACQ_CHIT_NO,
        A.STATUS,
        '' as STATUS_TEXT,
        A.NOTE
    FROM fa_asset A
    LEFT JOIN acclist_info B
        ON A.COMPANY_CD = B.COMPANY_CD
       AND A.ACC_CD = B.ACC_CD
       AND IFNULL(B.ISDEL, '0') <> '1'
       AND IFNULL(B.ISABLEINPUT, '0') = '1'
    WHERE A.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(A.ISDEL, '0') = '0'
      AND (
            p_ASSET_ID IS NULL
            OR p_ASSET_ID = 0
            OR A.ASSET_ID = p_ASSET_ID
          )
      AND (
            p_ASSET_CD IS NULL
            OR p_ASSET_CD = ''
            OR A.ASSET_CD = p_ASSET_CD
          )
    ORDER BY A.ASSET_CD;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_general_journal
DROP PROCEDURE IF EXISTS `rpt_general_journal`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_general_journal`(IN `p_COMPANY_CD` VARCHAR(20), IN `p_FROM_DATE` VARCHAR(8), IN `p_TO_DATE` VARCHAR(8), IN `p_LANGUAGE` VARCHAR(20)
)
    COMMENT '[C-E] Sổ nhật ký chung'
BEGIN
    DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_language VARCHAR(20);
    DECLARE v_year_text VARCHAR(50);


    SET v_from_ymd = p_FROM_DATE; -- DATE_FORMAT(IFNULL(p_FROM_DATE, MAKEDATE(YEAR(CURDATE()), 1)), '%Y%m%d');
    SET v_to_ymd = p_TO_DATE; -- DATE_FORMAT(IFNULL(p_TO_DATE, CURDATE()), '%Y%m%d');
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));
    SET v_year_text = CONCAT('Năm ', SUBSTRING(v_from_ymd, 1, 4));

-- CALL rpt_general_journal('0001', '20260901', '20260933', 'VIET')
--   SELECT p_FROM_DATE, p_TO_DATE, v_from_ymd, v_to_ymd;

    DROP TEMPORARY TABLE IF EXISTS tmp_accounting_journal_report;

    CREATE TEMPORARY TABLE tmp_accounting_journal_report
    (
        -- ROW_NO INT NOT NULL AUTO_INCREMENT,
        ROW_NO INT NULL DEFAULT 0,
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        REPORT_GROUP_KEY VARCHAR(50) NOT NULL DEFAULT 'JOURNAL',
        ROW_TYPE VARCHAR(20) NOT NULL DEFAULT '',
        REPORT_YEAR_TEXT VARCHAR(50) NOT NULL DEFAULT '',
        AMOUNT_UNIT_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        ENTRY_DATE VARCHAR(20) NOT NULL DEFAULT '',

        CHIT_NO VARCHAR(50) NOT NULL DEFAULT '',
        CHIT_TYPE VARCHAR(20) NOT NULL DEFAULT '',        
		  VAT_CHIT_NO VARCHAR(50) NULL DEFAULT '',
        VAT_YMD VARCHAR(20) NULL DEFAULT '',
        CHIT_YMD VARCHAR(20) NULL DEFAULT '',
        
        DESCRIPTION_VIET VARCHAR(1000) NOT NULL DEFAULT '',
        DESCRIPTION_ENG VARCHAR(1000) NOT NULL DEFAULT '',
        DESCRIPTION_KOR VARCHAR(1000) NOT NULL DEFAULT '',
        
		  DESCRIPTION2_VIET VARCHAR(1000) NOT NULL DEFAULT '',
        DESCRIPTION2_ENG VARCHAR(1000) NOT NULL DEFAULT '',
        DESCRIPTION2_KOR VARCHAR(1000) NOT NULL DEFAULT '',
        
        DEBIT VARCHAR(1000) NOT NULL DEFAULT '',
        CREDIT VARCHAR(1000) NOT NULL DEFAULT '',
        AMOUNT DECIMAL(18,2) NULL DEFAULT NULL,
        FC_AMOUNT DECIMAL(18,2) NULL DEFAULT NULL,
        FC_RATE DECIMAL(18,2) NULL DEFAULT NULL,
        FC_TYPE VARCHAR(10) NULL DEFAULT '',
        
        -- CUSTOMER
        CUSTOMER_ID BIGINT NULL DEFAULT 0,	
        CUSTOMER_CD VARCHAR(20) NULL DEFAULT '',
        CUSTOMER_NM VARCHAR(255) NULL DEFAULT '',
        lbl_TaxCode VARCHAR(50) NULL DEFAULT '', -- TAX_CD
        
        -- DEPARTMENT
        DEPARTMENT_ID BIGINT NULL DEFAULT 0,	-- chitdetailinfo_ext
        DEPARTMENT_CD VARCHAR(20) NULL DEFAULT '', -- chitdetailinfo_ext
        DepartmentNM VARCHAR(300) NULL DEFAULT '',
        
--        DEPARTMENT_CD_2 VARCHAR(20) NULL DEFAULT '', -- chitdetailinfo_ext
        DepartmentNM_2 VARCHAR(300) NULL DEFAULT '',
        
        
        IS_LOCK VARCHAR(10) NOT NULL DEFAULT '',
        
        PAYER_INFO VARCHAR(255) NULL DEFAULT '',
        
        LINE_NO VARCHAR(20) NULL DEFAULT '',

        
        CHIT_ID BIGINT NOT NULL DEFAULT 0,
        CHITDETAIL_ID BIGINT NOT NULL DEFAULT 0,
        
        MODULE_CD VARCHAR(10) NOT NULL DEFAULT ''
   --     , PRIMARY KEY (ROW_NO)
        
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;


-- CALL rpt_general_journal('0001', '20260901', '20260930', 'VIET')


    INSERT INTO tmp_accounting_journal_report
    (
			ROW_NO,
			
			COMPANY_CD,
			ROW_TYPE,
			REPORT_YEAR_TEXT,
			AMOUNT_UNIT_TEXT,
			ENTRY_DATE,
			
			CHIT_NO,
			CHIT_YMD,
			
			VAT_CHIT_NO,
			VAT_YMD,
			
			DESCRIPTION_VIET,
			DESCRIPTION_ENG,
			DESCRIPTION_KOR,
			DESCRIPTION2_VIET,
			DESCRIPTION2_ENG,
			DESCRIPTION2_KOR,
			
			DEBIT,
			CREDIT,
			AMOUNT,
			FC_AMOUNT,
			FC_RATE,
			FC_TYPE,
			
			CUSTOMER_ID,
			CUSTOMER_CD,
			CUSTOMER_NM,
			lbl_TaxCode, -- TAX_CD
			
			DEPARTMENT_ID,
			DEPARTMENT_CD,
			DepartmentNM,
			
--			DEPARTMENT_CD_2,
			DepartmentNM_2,
			
			IS_LOCK,
			PAYER_INFO,
			
			LINE_NO,
			
			
			CHIT_ID,
			CHITDETAIL_ID,
			CHIT_TYPE,
			MODULE_CD
    )
   
    SELECT
    	  CAST(@journal_line_no := @journal_line_no + 1 AS CHAR) AS ROW_NO,
        p_COMPANY_CD,
        'DETAIL' AS ROW_TYPE,
        v_year_text AS REPORT_YEAR_TEXT,
        'Đơn vị tính: Đồng' AS AMOUNT_UNIT_TEXT,
        rows.ENTRY_DATE,
        rows.CHIT_NO,
        rows.CHIT_YMD,

        rows.VAT_CHIT_NO,
        rows.VAT_YMD,

		  rows.DESCRIPTION_VIET,
        rows.DESCRIPTION_ENG,
        rows.DESCRIPTION_KOR,
        rows.DESCRIPTION2_VIET,
        rows.DESCRIPTION2_ENG,
        rows.DESCRIPTION2_KOR,
        
        rows.DEBIT,
        rows.CREDIT,
        rows.AMOUNT,
        rows.FC_AMOUNT,
        rows.FC_RATE,
        rows.FC_TYPE,
        
        rows.CUSTOMER_ID,
        rows.CUSTOMER_CD,
        rows.CUSTOMER_NM,
        rows.TAX_CD,
        
        rows.DEPARTMENT_ID,
			rows.DEPARTMENT_CD,
			rows.DepartmentNM,
        
--			rows.DEPARTMENT_CD_2,
			rows.DepartmentNM_2,
        
        rows.IS_LOCK,
        rows.PAYER_INFO,
        CAST(@journal_line_no := @journal_line_no + 1 AS CHAR) AS LINE_NO,

        rows.CHIT_ID,
        rows.CHITDETAIL_ID,
        rows.CHIT_TYPE,
        rows.MODULE_CD
    FROM
    (
        SELECT
            CASE WHEN IFNULL(h.CHIT_YMD, '') REGEXP '^[0-9]{8}$' THEN DATE_FORMAT(STR_TO_DATE(h.CHIT_YMD, '%Y%m%d'), '%d/%m/%Y') ELSE IFNULL(h.CHIT_YMD, '') END AS ENTRY_DATE,
            
				COALESCE(NULLIF(TRIM(h.CHIT_NO), ''), NULLIF(TRIM(h.CHIT_CD), ''), '') AS CHIT_NO,            
            CASE WHEN IFNULL(d.CHIT_YMD, h.CHIT_YMD) REGEXP '^[0-9]{8}$' THEN DATE_FORMAT(STR_TO_DATE(IFNULL(d.CHIT_YMD, h.CHIT_YMD), '%Y%m%d'), '%d/%m/%Y') ELSE IFNULL(d.CHIT_YMD, h.CHIT_YMD) END AS CHIT_YMD,
				
				v.VAT_CHIT_NO,
				v.VAT_YMD,
				
				IFNULL(desc1_vi.DESCRIPTION,'') AS DESCRIPTION_VIET,
				IFNULL(desc1_en.DESCRIPTION,'') AS DESCRIPTION_ENG,
				IFNULL(desc1_kr.DESCRIPTION,'') AS DESCRIPTION_KOR,

				IFNULL(desc2_vi.DESCRIPTION,'') AS DESCRIPTION2_VIET,
				IFNULL(desc2_en.DESCRIPTION,'') AS DESCRIPTION2_ENG,
				IFNULL(desc2_kr.DESCRIPTION,'') AS DESCRIPTION2_KOR,
				
				d.DEBIT,
				d.CREDIT,
				NULLIF(IFNULL(d.AMOUNT, 0), 0) AS AMOUNT, 
				NULLIF(IFNULL(d.FC_AMOUNT, 0), 0) AS FC_AMOUNT, 
				NULLIF(IFNULL(d.FC_RATE, 0), 0) AS FC_RATE, 
				ifnull(d.FC_TYPE,'') as FC_TYPE,
				
				c.CUSTOMER_ID,
				c.CUSTOMER_CD,
				(
					CASE
					    WHEN v_language = 'KOR' THEN
					        COALESCE(
					            NULLIF(TRIM(c.CUSTOMER_NM_KOR), ''),
					            NULLIF(TRIM(c.CUSTOMER_NM_ENG), ''),
					            c.CUSTOMER_NM_VIET
					        )
					
					    WHEN v_language = 'ENG' THEN
					        COALESCE(
					            NULLIF(TRIM(c.CUSTOMER_NM_ENG), ''),
					            c.CUSTOMER_NM_VIET
					        )
					
					    ELSE
					        c.CUSTOMER_NM_VIET
					END
				) AS CUSTOMER_NM,
				
				ce.TAX_CD,
				
				di.DEPARTMENT_ID,
				di.DEPARTMENT_CD,
				(
					CASE
					    WHEN v_language = 'KOR' THEN
					        COALESCE(
					            NULLIF(TRIM(di.DEP_NAME_KOR), ''),
					            NULLIF(TRIM(di.DEP_NAME_ENG), ''),
					            di.DEP_NAME_VIET
					        )
					
					    WHEN v_language = 'ENG' THEN
					        COALESCE(
					            NULLIF(TRIM(di.DEP_NAME_ENG), ''),
					            di.DEP_NAME_VIET
					        )
					
					    ELSE
					        di.DEP_NAME_VIET
					END
				) AS DepartmentNM,
            
            
				(
					CASE
					    WHEN v_language = 'KOR' THEN
					        COALESCE(
					            NULLIF(TRIM(di2.DEP_NAME_KOR), ''),
					            NULLIF(TRIM(di2.DEP_NAME_ENG), ''),
					            di2.DEP_NAME_VIET
					        )
					    WHEN v_language = 'ENG' THEN
					        COALESCE(
					            NULLIF(TRIM(di2.DEP_NAME_ENG), ''),
					            di2.DEP_NAME_VIET
					        )
					    ELSE
					        di2.DEP_NAME_VIET
					END
				) AS DepartmentNM_2,
            
            
            CASE WHEN IFNULL(ext.IS_LOCK, '0') = '1' THEN 'x' ELSE '' END AS IS_LOCK,
            h.PAYER_INFO,

            
            IFNULL(h.CHIT_ID, 0) AS CHIT_ID,
            IFNULL(d.CHITDETAIL_ID, 0) AS CHITDETAIL_ID,
            IFNULL(h.CHIT_TYPE, '') AS CHIT_TYPE,
            IFNULL(h.INPUT_TYPE, '') AS MODULE_CD,
            
            IFNULL(h.CHIT_YMD, '') AS SORT_YMD,
            IFNULL(h.CHIT_NO, '') AS SORT_NO,
            IFNULL(h.CHIT_ID, 0) AS SORT_CHIT_ID,
            IFNULL(d.SORT, 0) AS SORT_DETAIL,
            1 AS SORT_SIDE
        FROM chitinfo h
        INNER JOIN chitdetailinfo d ON d.COMPANY_CD = h.COMPANY_CD AND d.CHIT_ID = h.CHIT_ID AND IFNULL(d.ISDEL, '0') <> '1'
        INNER JOIN chitdetailinfo_ext de ON de.COMPANY_CD = d.COMPANY_CD AND de.CHITDETAIL_ID = d.CHITDETAIL_ID and IFNULL(de.ISDEL, '0') <> '1'
        INNER JOIN chitdetailinfo_vat v ON v.COMPANY_CD = d.COMPANY_CD AND v.CHITDETAIL_ID = d.CHITDETAIL_ID and IFNULL(v.ISDEL, '0') <> '1'
        LEFT JOIN customer_info c ON c.COMPANY_CD = d.COMPANY_CD and c.CUSTOMER_ID = de.CUSTOMER_ID and IFNULL(c.ISDEL, '0') <> '1'
        LEFT JOIN customer_ext ce ON ce.COMPANY_CD = d.COMPANY_CD and ce.CUSTOMER_ID = de.CUSTOMER_ID and IFNULL(ce.ISDEL, '0') <> '1'
        
        LEFT JOIN department_info di ON h.COMPANY_CD = di.COMPANY_CD and de.DEPARTMENT_ID = di.DEPARTMENT_ID and ifnull(di.ISDEL, '') <> '1'
        
        LEFT JOIN department_info di2 ON h.COMPANY_CD = di2.COMPANY_CD and de.DEPARTMENT_ID = di2.DEPARTMENT_ID and ifnull(di2.ISDEL, '') <> '1'
        
        LEFT JOIN chitinfo_ext ext ON ext.COMPANY_CD = h.COMPANY_CD AND ext.CHIT_ID = h.CHIT_ID AND IFNULL(ext.ISDEL, '0') <> '1'
        LEFT JOIN chitdescriptioninfo desc1_vi ON desc1_vi.COMPANY_CD = h.COMPANY_CD AND desc1_vi.CHIT_ID = h.CHIT_ID AND desc1_vi.LANG_TYPE = 'VIET' AND IFNULL(desc1_vi.ISDEL, '0') <> '1'
        LEFT JOIN chitdescriptioninfo desc1_en ON desc1_en.COMPANY_CD = h.COMPANY_CD AND desc1_en.CHIT_ID = h.CHIT_ID AND desc1_en.LANG_TYPE = 'ENG' AND IFNULL(desc1_en.ISDEL, '0') <> '1'
        LEFT JOIN chitdescriptioninfo desc1_kr ON desc1_kr.COMPANY_CD = h.COMPANY_CD AND desc1_kr.CHIT_ID = h.CHIT_ID AND desc1_kr.LANG_TYPE = 'KOR' AND IFNULL(desc1_kr.ISDEL, '0') <> '1'
        LEFT JOIN chitdetaildescriptioninfo desc2_vi ON desc2_vi.COMPANY_CD = d.COMPANY_CD AND desc2_vi.CHITDETAIL_ID = d.CHITDETAIL_ID AND desc2_vi.LANG_TYPE = 'VIET' AND IFNULL(desc2_vi.ISDEL, '0') <> '1'
        LEFT JOIN chitdetaildescriptioninfo desc2_en ON desc2_en.COMPANY_CD = d.COMPANY_CD AND desc2_en.CHITDETAIL_ID = d.CHITDETAIL_ID AND desc2_en.LANG_TYPE = 'ENG' AND IFNULL(desc2_en.ISDEL, '0') <> '1'
        LEFT JOIN chitdetaildescriptioninfo desc2_kr ON desc2_kr.COMPANY_CD = d.COMPANY_CD AND desc2_kr.CHITDETAIL_ID = d.CHITDETAIL_ID AND desc2_kr.LANG_TYPE = 'KOR' AND IFNULL(desc2_kr.ISDEL, '0') <> '1'
        WHERE h.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(h.ISDEL, '0') <> '1'
          AND IFNULL(h.CHIT_YMD, '') >= v_from_ymd
          AND IFNULL(h.CHIT_YMD, '') <= v_to_ymd
          AND IFNULL(d.AMOUNT, 0) <> 0
        
        ORDER BY SORT_YMD, SORT_NO, SORT_CHIT_ID, SORT_DETAIL, SORT_SIDE, d.CHITDETAIL_ID
    ) rows
    CROSS JOIN (SELECT @journal_line_no := 0) seed
	;

--    INSERT INTO tmp_accounting_journal_report (COMPANY_CD, ROW_TYPE, REPORT_YEAR_TEXT, AMOUNT_UNIT_TEXT)
--    SELECT p_COMPANY_CD, 'BLANK', v_year_text, 'Đơn vị tính: Đồng'
--    FROM (SELECT 1 AS N UNION ALL SELECT 2) blanks;

-- CALL rpt_general_journal('0001', '20260901', '20260930', 'VIET')


    SELECT
        ENTRY_DATE AS __ENTRY_DATE,
        CHIT_NO,
        
        CHIT_TYPE,
--        '' AS CHIT_TYPE_NM,

        VAT_CHIT_NO,
        VAT_YMD,
        CHIT_YMD,
        
		  DESCRIPTION_VIET,
        DESCRIPTION_ENG,
        DESCRIPTION_KOR,
        DESCRIPTION2_VIET,
        DESCRIPTION2_ENG,
        DESCRIPTION2_KOR,
        
        DEBIT,
        CREDIT,
        AMOUNT,
        FC_AMOUNT,
        FC_RATE,
        FC_TYPE,
        
        -- CUSTOMER_ID,
		  CUSTOMER_CD,
		  CUSTOMER_NM,
		  lbl_TaxCode, -- TAX_CD
        
        DEPARTMENT_ID AS __DEPARTMENT_ID,
			DEPARTMENT_CD,
			DepartmentNM,
			DepartmentNM_2,
			
        IS_LOCK,
        PAYER_INFO,
        LINE_NO AS __LINE_NO,

        
        

        CASE
            WHEN ROW_TYPE = 'DETAIL' AND IFNULL(CHIT_ID, 0) > 0 THEN
                CONCAT('DETAIL_', IFNULL(MODULE_CD, ''), '_', CHIT_ID, '_', IFNULL(CHITDETAIL_ID, 0), '_', ROW_NO)
            ELSE CONCAT('JOURNAL_', ROW_NO)
        END AS __ROW_KEY,
        ROW_NO AS __LINE_SORT,
        COMPANY_CD AS __COMPANY_CD,
        REPORT_GROUP_KEY AS __REPORT_GROUP_KEY,
        ROW_TYPE AS __ROW_TYPE,
        REPORT_YEAR_TEXT AS __REPORT_YEAR_TEXT,
        AMOUNT_UNIT_TEXT AS __AMOUNT_UNIT_TEXT,
        
        CHIT_ID AS __CHIT_ID,
        CHITDETAIL_ID AS __CHITDETAIL_ID,

        MODULE_CD AS __MODULE_CD,
        CASE
            WHEN ROW_TYPE = 'DETAIL' AND IFNULL(CHIT_ID, 0) > 0 THEN 'DOCUMENT'
            ELSE 'NONE'
        END AS __LINK_TYPE
    FROM tmp_accounting_journal_report
    ORDER BY ROW_NO;

    DROP TEMPORARY TABLE IF EXISTS tmp_accounting_journal_report;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_general_ledger_s02c1dn
DROP PROCEDURE IF EXISTS `rpt_general_ledger_s02c1dn`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_general_ledger_s02c1dn`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE VARCHAR(8),
    IN p_TO_DATE VARCHAR(8),
    IN p_ACCOUNT_CD VARCHAR(1000),
    IN p_LANGUAGE VARCHAR(20)
)
    COMMENT '[C-G] Sổ cái tài khoản'
BEGIN
    DECLARE v_from_date DATE;
    DECLARE v_to_date DATE;
    
    DECLARE v_year_start DATE;
    DECLARE v_quarter_start DATE;
    
	 DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_year_start_ymd VARCHAR(8);
    DECLARE v_before_year_ymd VARCHAR(8);
    DECLARE v_quarter_start_ymd VARCHAR(8);
    
    DECLARE v_language VARCHAR(20);
    DECLARE v_account_cd VARCHAR(10000);
--    DECLARE v_account_cd_text VARCHAR(10000) DEFAULT '';
--    DECLARE v_account_name_text VARCHAR(10000) DEFAULT '';
    DECLARE v_report_year_text VARCHAR(20);
    DECLARE v_opening_net DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_period_debit DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_period_credit DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_ending_net DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_quarter_debit DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_quarter_credit DECIMAL(18,2) DEFAULT 0.00;

    IF ifnull(p_FROM_DATE, '') = '' OR ifnull(p_TO_DATE, '') = '' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;

    SET v_from_date = p_FROM_DATE;
    SET v_to_date = p_TO_DATE;
    SET v_year_start = MAKEDATE(YEAR(v_from_date), 1);
    SET v_quarter_start = DATE_ADD(MAKEDATE(YEAR(v_to_date), 1), INTERVAL ((QUARTER(v_to_date) - 1) * 3) MONTH);
    SET v_from_ymd = DATE_FORMAT(v_from_date, '%Y%m%d');
    SET v_to_ymd = DATE_FORMAT(v_to_date, '%Y%m%d');
    SET v_year_start_ymd = DATE_FORMAT(v_year_start, '%Y%m%d');
    SET v_before_year_ymd = DATE_FORMAT(DATE_SUB(v_year_start, INTERVAL 1 DAY), '%Y%m%d');
    SET v_quarter_start_ymd = DATE_FORMAT(v_quarter_start, '%Y%m%d');
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));
    SET v_account_cd = REPLACE(TRIM(IFNULL(p_ACCOUNT_CD, '')), ' ', '');
    IF UPPER(v_account_cd) IN ('ALL', '*') THEN
        SET v_account_cd = '';
    END IF;
    SET v_report_year_text = CAST(YEAR(v_from_date) AS CHAR);


	-- 1. TẤT CẢ TÀI KHOẢN / ACCLIST_INFO
    DROP TEMPORARY TABLE IF EXISTS tmp_Accounts;
    CREATE TEMPORARY TABLE tmp_Accounts
    (
        ACC_CD VARCHAR(20) NULL  DEFAULT '',
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ACC_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_Accounts (ACC_CD, ACCOUNT_NAME)
    SELECT
        account.ACC_CD,
        (
	        CASE v_language 
				  	WHEN 'KOR' THEN COALESCE(NULLIF(TRIM(account.ACCTITLE_NM_KOR), ''), NULLIF(TRIM(account.ACCTITLE_NM_ENG), ''), NULLIF(TRIM(account.ACCTITLE_NM_VIET), '')) 
				  	WHEN 'ENG' THEN COALESCE(NULLIF(TRIM(account.ACCTITLE_NM_ENG), ''), NULLIF(TRIM(account.ACCTITLE_NM_VIET), '')) 
				  	ELSE account.ACCTITLE_NM_VIET
				END
			) as ACCOUNT_NAME	

    FROM acclist_info account
    WHERE account.COMPANY_CD = p_COMPANY_CD
      AND (v_account_cd = '' OR FIND_IN_SET(account.ACC_CD, v_account_cd) > 0)
      AND account.LEVEL = '1'
      AND IFNULL(account.ISDEL, '0') <> '1'
	;
	
	-- 1. TẤT CẢ TÀI KHOẢN con / ACCLIST_INFO
    DROP TEMPORARY TABLE IF EXISTS tmp_Accounts_Child;
    CREATE TEMPORARY TABLE tmp_Accounts_Child
    (
        ACC_CD VARCHAR(20) NULL  DEFAULT '',
        ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ACC_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_Accounts_Child (ACC_CD, ACCOUNT_NAME)
    SELECT
        account.ACC_CD,
        (
	        CASE v_language 
				  	WHEN 'KOR' THEN COALESCE(NULLIF(TRIM(account.ACCTITLE_NM_KOR), ''), NULLIF(TRIM(account.ACCTITLE_NM_ENG), ''), NULLIF(TRIM(account.ACCTITLE_NM_VIET), '')) 
				  	WHEN 'ENG' THEN COALESCE(NULLIF(TRIM(account.ACCTITLE_NM_ENG), ''), NULLIF(TRIM(account.ACCTITLE_NM_VIET), '')) 
				  	ELSE account.ACCTITLE_NM_VIET
				END
			) as ACCOUNT_NAME	

    FROM acclist_info account
    WHERE account.COMPANY_CD = p_COMPANY_CD
      AND (v_account_cd = '' OR account.ACC_CD REGEXP CONCAT('^(', REPLACE(v_account_cd, ',', '|'), ')'))
      AND account.ISABLEINPUT = '1'
      AND IFNULL(account.ISDEL, '0') <> '1'
	;

-- select v_account_cd; -- , * from tmp_Accounts;


	-- 2. table ALL DATA // CHỨA TẤT CẢ DỮ LIỆU KẾT QUẢ
    DROP TEMPORARY TABLE IF EXISTS tmp_general_ledger_report;
    CREATE TEMPORARY TABLE tmp_general_ledger_report
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ROW_KEY VARCHAR(100) NOT NULL DEFAULT '',
        PARENT_ROW_KEY VARCHAR(100) NULL DEFAULT NULL,
        LINE_SORT INT NOT NULL DEFAULT 0,
        ROW_LEVEL INT NOT NULL DEFAULT 0,
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        REPORT_GROUP_KEY VARCHAR(50) NOT NULL DEFAULT 'GENERAL_LEDGER',
        ROW_TYPE VARCHAR(30) NOT NULL DEFAULT '',
        ACC_CD VARCHAR(20) NULL DEFAULT '',
        
        CHIT_TYPE VARCHAR(50) NULL DEFAULT 'OT',
        CHIT_ID BIGINT NULL DEFAULT NULL,
        MODULE_CD VARCHAR(20) NULL DEFAULT NULL,
        ACCOUNT_CD VARCHAR(1000) NOT NULL DEFAULT '',
        ACCOUNT_NAME VARCHAR(1000) NOT NULL DEFAULT '',
        REPORT_YEAR_TEXT VARCHAR(20) NOT NULL DEFAULT '',
        AMOUNT_UNIT_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        -- ENTRY_DATE VARCHAR(20) NOT NULL DEFAULT '',
		  CHIT_NO VARCHAR(50) NOT NULL DEFAULT '',
        CHIT_YMD VARCHAR(10) NOT NULL DEFAULT '',
        
        DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
        CSD_ACC_CD VARCHAR(50) NOT NULL DEFAULT '',
        DEBIT_AMOUNT DECIMAL(18,2) NULL,
        CREDIT_AMOUNT DECIMAL(18,2) NULL,
        NOTE_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        CUSTOMER_ID BIGINT NULL DEFAULT 0,
        PRIMARY KEY (ROW_NO)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
	
    IF (SELECT COUNT(*) FROM tmp_Accounts) = 0 THEN
        INSERT INTO tmp_general_ledger_report
        (
            ROW_KEY,
            LINE_SORT,
            COMPANY_CD,
            ROW_TYPE,
            REPORT_YEAR_TEXT,
            AMOUNT_UNIT_TEXT,
            
            DESCRIPTION
        )
        VALUES
        (
            'NO_ACCOUNT',
            10,
            p_COMPANY_CD,
            'EMPTY',
            v_report_year_text,
            '', -- 'Đơn vị tính: đồng',
            '' -- 'Chọn tài khoản để xem sổ cái'
        );
    ELSE
        -- Emit one account node. Transaction rows below reference it as parent,
        -- so the TreeList renders the hierarchy returned by this procedure.
        INSERT INTO tmp_general_ledger_report
        (
            ROW_KEY,
            PARENT_ROW_KEY,
            LINE_SORT,
            ROW_LEVEL,
            COMPANY_CD,
            ROW_TYPE,
            ACC_CD,
            ACCOUNT_CD,
            ACCOUNT_NAME,
            REPORT_YEAR_TEXT,
            AMOUNT_UNIT_TEXT,
            CHIT_TYPE
        )
        SELECT
            CONCAT('ACCOUNT_', account.ACC_CD),
            NULL,
            10,
            0,
            p_COMPANY_CD,
            'GROUP',
            account.ACC_CD,
            account.ACC_CD,
            account.ACCOUNT_NAME,
            v_report_year_text,
            'Đơn vị tính: đồng',
            ''
        FROM tmp_Accounts account;

    /*
        SELECT
            GROUP_CONCAT(ACC_CD ORDER BY ACC_CD SEPARATOR ', '),
            GROUP_CONCAT(ACCOUNT_NAME ORDER BY ACC_CD SEPARATOR ', ')
        INTO
            v_account_cd_text,
            v_account_name_text
        FROM tmp_Accounts;

        SET v_account_cd_text = IFNULL(v_account_cd_text, '');
        SET v_account_name_text = IFNULL(v_account_name_text, '');
*/
			
			
			-- 3. ĐẦU KỲ
        DROP TEMPORARY TABLE IF EXISTS tmp_general_ledger_latest_open;
        CREATE TEMPORARY TABLE tmp_general_ledger_latest_open
        (
            ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
            OPEN_YMD VARCHAR(8) NOT NULL DEFAULT '',
            PRIMARY KEY (ACC_CD)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
/*
        INSERT INTO tmp_general_ledger_latest_open (ACC_CD, OPEN_YMD)
        SELECT account.ACC_CD, IFNULL(MAX(opening.OPEN_YMD), '')
        FROM tmp_Accounts account
        LEFT JOIN before_states opening
            ON opening.COMPANY_CD = p_COMPANY_CD
           AND opening.ACC_CD = account.ACC_CD
           AND IFNULL(opening.ISDEL, '0') <> '1'
           AND IFNULL(opening.OPEN_YMD, '') <= v_before_year_ymd
        GROUP BY account.ACC_CD;
*/
			-- 4. ĐẦU KỲ
        DROP TEMPORARY TABLE IF EXISTS tmp_general_ledger_opening_base;
        CREATE TEMPORARY TABLE tmp_general_ledger_opening_base
        (
            ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
            OPEN_YMD VARCHAR(8) NOT NULL DEFAULT '00000000',
            DEBIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            CREDIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            PRIMARY KEY (ACC_CD)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
/*
        INSERT INTO tmp_general_ledger_opening_base (ACC_CD, OPEN_YMD, DEBIT_AMOUNT, CREDIT_AMOUNT)
        SELECT
            account.ACC_CD,
            IFNULL(NULLIF(latest.OPEN_YMD, ''), '00000000'),
            IFNULL(SUM(opening.DEBIT), 0),
            IFNULL(SUM(opening.CREDIT), 0)
        FROM tmp_Accounts account
        LEFT JOIN tmp_general_ledger_latest_open latest
            ON latest.ACC_CD = account.ACC_CD
        LEFT JOIN before_states opening
            ON opening.COMPANY_CD = p_COMPANY_CD
           AND opening.ACC_CD = account.ACC_CD
           AND opening.OPEN_YMD = latest.OPEN_YMD
           AND IFNULL(opening.ISDEL, '0') <> '1'
        GROUP BY account.ACC_CD, latest.OPEN_YMD;
*/

        DROP TEMPORARY TABLE IF EXISTS tmp_Details; -- tmp_general_ledger_movements
        CREATE TEMPORARY TABLE tmp_Details
        (
            ROW_NO INT NOT NULL AUTO_INCREMENT,
            
            ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
            ACCOUNT_NAME VARCHAR(255) NOT NULL DEFAULT '',
            -- CHIT_YMD VARCHAR(8) NOT NULL DEFAULT '',
            -- ENTRY_DATE VARCHAR(20) NOT NULL DEFAULT '',
            CHIT_NO VARCHAR(50) NOT NULL DEFAULT '',
            CHIT_YMD VARCHAR(10) NOT NULL DEFAULT '',
            CHIT_ID BIGINT NULL DEFAULT NULL,
            CHIT_TYPE VARCHAR(50) NULL DEFAULT NULL,
            MODULE_CD VARCHAR(20) NULL DEFAULT NULL,
            DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
            
            CSD_ACC_CD VARCHAR(50) NOT NULL DEFAULT '',
            
            DEBIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            CREDIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            SORT_NO VARCHAR(50) NOT NULL DEFAULT '',
            SORT_CHIT_ID BIGINT NOT NULL DEFAULT 0,
            SORT_DETAIL INT NOT NULL DEFAULT 0,
            SORT_SIDE INT NOT NULL DEFAULT 0,
            CUSTOMER_ID BIGINT NULL DEFAULT 0,
            
            PRIMARY KEY (ROW_NO),
            INDEX idx_tmp_Details_01 (ACC_CD, CHIT_YMD)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

        INSERT INTO tmp_Details(ACC_CD,ACCOUNT_NAME, CHIT_NO,CHIT_ID,CHIT_TYPE,MODULE_CD,CHIT_YMD,DESCRIPTION, CSD_ACC_CD,DEBIT_AMOUNT,CREDIT_AMOUNT,SORT_NO,SORT_CHIT_ID,SORT_DETAIL,SORT_SIDE, CUSTOMER_ID)
        SELECT
            account.ACC_CD,
            account.ACCOUNT_NAME,

            h.CHIT_NO,
            h.CHIT_ID,
            h.CHIT_TYPE,
            h.INPUT_TYPE,
            d.CHIT_YMD,
            COALESCE(
                NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN desc2_en.DESCRIPTION WHEN 'KOR' THEN desc2_ko.DESCRIPTION ELSE desc2_vi.DESCRIPTION END), ''),
                NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN desc1_en.DESCRIPTION WHEN 'KOR' THEN desc1_ko.DESCRIPTION ELSE desc1_vi.DESCRIPTION END), ''),
                NULLIF(TRIM(h.PAYER_INFO), ''),
                ''
            ) as DESCRIPTION,
            TRIM(IFNULL(d.CREDIT, '')),
            IFNULL(d.AMOUNT, 0),
            0,
            IFNULL(h.CHIT_NO, ''),
            IFNULL(h.CHIT_ID, 0),
            IFNULL(d.SORT, 0),
            1 as SORT_SIDE,
            
            ext.CUSTOMER_ID
        FROM chitdetailinfo d
	        INNER JOIN tmp_Accounts account ON d.DEBIT like concat(account.ACC_CD ,'%')	        
	        INNER JOIN chitinfo h ON h.COMPANY_CD = d.COMPANY_CD AND h.CHIT_ID = d.CHIT_ID AND IFNULL(h.ISDEL, '0') <> '1'
	        
	        LEFT JOIN chitdescriptioninfo desc1_vi ON desc1_vi.COMPANY_CD = h.COMPANY_CD AND desc1_vi.CHIT_ID = h.CHIT_ID AND desc1_vi.LANG_TYPE = 'VIET' AND IFNULL(desc1_vi.ISDEL, '0') <> '1'
	        LEFT JOIN chitdescriptioninfo desc1_en ON desc1_en.COMPANY_CD = h.COMPANY_CD AND desc1_en.CHIT_ID = h.CHIT_ID AND desc1_en.LANG_TYPE = 'ENG' AND IFNULL(desc1_en.ISDEL, '0') <> '1'
	        LEFT JOIN chitdescriptioninfo desc1_ko ON desc1_ko.COMPANY_CD = h.COMPANY_CD AND desc1_ko.CHIT_ID = h.CHIT_ID AND desc1_ko.LANG_TYPE = 'KOR' AND IFNULL(desc1_ko.ISDEL, '0') <> '1'
	        
	        LEFT JOIN chitdetaildescriptioninfo desc2_vi ON desc2_vi.COMPANY_CD = d.COMPANY_CD AND desc2_vi.CHITDETAIL_ID = d.CHITDETAIL_ID AND desc2_vi.LANG_TYPE = 'VIET' AND IFNULL(desc2_vi.ISDEL, '0') <> '1'
	        LEFT JOIN chitdetaildescriptioninfo desc2_en ON desc2_en.COMPANY_CD = d.COMPANY_CD AND desc2_en.CHITDETAIL_ID = d.CHITDETAIL_ID AND desc2_en.LANG_TYPE = 'ENG' AND IFNULL(desc2_en.ISDEL, '0') <> '1'
	        LEFT JOIN chitdetaildescriptioninfo desc2_ko ON desc2_ko.COMPANY_CD = d.COMPANY_CD AND desc2_ko.CHITDETAIL_ID = d.CHITDETAIL_ID AND desc2_ko.LANG_TYPE = 'KOR' AND IFNULL(desc2_ko.ISDEL, '0') <> '1'
	        
	        LEFT JOIN chitdetailinfo_ext ext ON ext.COMPANY_CD = d.COMPANY_CD AND ext.CHITDETAIL_ID = d.CHITDETAIL_ID and ext.ISDEL <> '1'
        WHERE d.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(d.ISDEL, '0') <> '1'
          AND IFNULL(d.AMOUNT, 0) <> 0
          AND d.CHIT_YMD BETWEEN v_from_ymd and v_to_ymd;

        INSERT INTO tmp_Details(ACC_CD,ACCOUNT_NAME, CHIT_NO,CHIT_ID,CHIT_TYPE,MODULE_CD,CHIT_YMD,DESCRIPTION,CSD_ACC_CD,DEBIT_AMOUNT,CREDIT_AMOUNT,SORT_NO,SORT_CHIT_ID,SORT_DETAIL,SORT_SIDE, CUSTOMER_ID)
        SELECT
            account.ACC_CD,
            account.ACCOUNT_NAME,
            
            h.CHIT_NO,
            h.CHIT_ID,
            h.CHIT_TYPE,
            h.INPUT_TYPE,
            d.CHIT_YMD,
            COALESCE(
                NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN desc2_en.DESCRIPTION WHEN 'KOR' THEN desc2_ko.DESCRIPTION ELSE desc2_vi.DESCRIPTION END), ''),
                NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN desc1_en.DESCRIPTION WHEN 'KOR' THEN desc1_ko.DESCRIPTION ELSE desc1_vi.DESCRIPTION END), ''),
                NULLIF(TRIM(h.PAYER_INFO), ''),
                ''
            ) as DESCRIPTION,
            TRIM(IFNULL(d.DEBIT, '')),
            0,
            IFNULL(d.AMOUNT, 0),
            IFNULL(h.CHIT_NO, ''),
            IFNULL(h.CHIT_ID, 0),
            IFNULL(d.SORT, 0),
            2 as SORT_SIDE,
            ext.CUSTOMER_ID
        FROM chitdetailinfo d
	        INNER JOIN tmp_Accounts account ON d.CREDIT like concat(account.ACC_CD, '%')
	        INNER JOIN chitinfo h            ON h.COMPANY_CD = d.COMPANY_CD           AND h.CHIT_ID = d.CHIT_ID           AND IFNULL(h.ISDEL, '0') <> '1'
	        
	        LEFT JOIN chitdescriptioninfo desc1_vi ON desc1_vi.COMPANY_CD = h.COMPANY_CD AND desc1_vi.CHIT_ID = h.CHIT_ID AND desc1_vi.LANG_TYPE = 'VIET' AND IFNULL(desc1_vi.ISDEL, '0') <> '1'
	        LEFT JOIN chitdescriptioninfo desc1_en ON desc1_en.COMPANY_CD = h.COMPANY_CD AND desc1_en.CHIT_ID = h.CHIT_ID AND desc1_en.LANG_TYPE = 'ENG' AND IFNULL(desc1_en.ISDEL, '0') <> '1'
	        LEFT JOIN chitdescriptioninfo desc1_ko ON desc1_ko.COMPANY_CD = h.COMPANY_CD AND desc1_ko.CHIT_ID = h.CHIT_ID AND desc1_ko.LANG_TYPE = 'KOR' AND IFNULL(desc1_ko.ISDEL, '0') <> '1'
	        
			  LEFT JOIN chitdetaildescriptioninfo desc2_vi ON desc2_vi.COMPANY_CD = d.COMPANY_CD AND desc2_vi.CHITDETAIL_ID = d.CHITDETAIL_ID AND desc2_vi.LANG_TYPE = 'VIET' AND IFNULL(desc2_vi.ISDEL, '0') <> '1'
	        LEFT JOIN chitdetaildescriptioninfo desc2_en ON desc2_en.COMPANY_CD = d.COMPANY_CD AND desc2_en.CHITDETAIL_ID = d.CHITDETAIL_ID AND desc2_en.LANG_TYPE = 'ENG' AND IFNULL(desc2_en.ISDEL, '0') <> '1'
	        LEFT JOIN chitdetaildescriptioninfo desc2_ko ON desc2_ko.COMPANY_CD = d.COMPANY_CD AND desc2_ko.CHITDETAIL_ID = d.CHITDETAIL_ID AND desc2_ko.LANG_TYPE = 'KOR' AND IFNULL(desc2_ko.ISDEL, '0') <> '1'
	        
	        LEFT JOIN chitdetailinfo_ext ext ON ext.COMPANY_CD = d.COMPANY_CD AND ext.CHITDETAIL_ID = d.CHITDETAIL_ID and ext.ISDEL <> '1'
        WHERE d.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(d.ISDEL, '0') <> '1'
          AND IFNULL(d.AMOUNT, 0) <> 0
          AND d.CHIT_YMD BETWEEN v_from_ymd and v_to_ymd;



        DROP TEMPORARY TABLE IF EXISTS tmp_general_ledger_sums;
        CREATE TEMPORARY TABLE tmp_general_ledger_sums
        (
            ACC_CD VARCHAR(20) NOT NULL DEFAULT '',
            OPENING_NET DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            PERIOD_DEBIT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            PERIOD_CREDIT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            ENDING_NET DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            QUARTER_DEBIT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            QUARTER_CREDIT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
            PRIMARY KEY (ACC_CD)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

        INSERT INTO tmp_general_ledger_sums
        (
            ACC_CD,
            OPENING_NET,
            PERIOD_DEBIT,
            PERIOD_CREDIT,
            ENDING_NET,
            QUARTER_DEBIT,
            QUARTER_CREDIT
        )
        SELECT
            account.ACC_CD,
            IFNULL(base.DEBIT_AMOUNT, 0) - IFNULL(base.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= IFNULL(base.OPEN_YMD, '00000000')
                 AND movement.CHIT_YMD < v_year_start_ymd
                THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
                ELSE 0
            END), 0),
            IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= v_from_ymd
                 AND movement.CHIT_YMD <= v_to_ymd
                THEN movement.DEBIT_AMOUNT
                ELSE 0
            END), 0),
            IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= v_from_ymd
                 AND movement.CHIT_YMD <= v_to_ymd
                THEN movement.CREDIT_AMOUNT
                ELSE 0
            END), 0),
            IFNULL(base.DEBIT_AMOUNT, 0) - IFNULL(base.CREDIT_AMOUNT, 0) + IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= IFNULL(base.OPEN_YMD, '00000000')
                 AND movement.CHIT_YMD <= v_to_ymd
                THEN movement.DEBIT_AMOUNT - movement.CREDIT_AMOUNT
                ELSE 0
            END), 0),
            IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= v_quarter_start_ymd
                 AND movement.CHIT_YMD <= v_to_ymd
                THEN movement.DEBIT_AMOUNT
                ELSE 0
            END), 0),
            IFNULL(SUM(CASE
                WHEN movement.CHIT_YMD >= v_quarter_start_ymd
                 AND movement.CHIT_YMD <= v_to_ymd
                THEN movement.CREDIT_AMOUNT
                ELSE 0
            END), 0)
        FROM tmp_Accounts account
        LEFT JOIN tmp_general_ledger_opening_base base ON base.ACC_CD = account.ACC_CD
        LEFT JOIN tmp_Details movement ON movement.ACC_CD = account.ACC_CD
        GROUP BY account.ACC_CD, base.OPEN_YMD, base.DEBIT_AMOUNT, base.CREDIT_AMOUNT;

        SELECT
            IFNULL(SUM(OPENING_NET), 0),
            IFNULL(SUM(PERIOD_DEBIT), 0),
            IFNULL(SUM(PERIOD_CREDIT), 0),
            IFNULL(SUM(ENDING_NET), 0),
            IFNULL(SUM(QUARTER_DEBIT), 0),
            IFNULL(SUM(QUARTER_CREDIT), 0)
        INTO
            v_opening_net,
            v_period_debit,
            v_period_credit,
            v_ending_net,
            v_quarter_debit,
            v_quarter_credit
        FROM tmp_general_ledger_sums;

/*
        INSERT INTO tmp_general_ledger_report
        (
            ROW_KEY,
            PARENT_ROW_KEY,
            LINE_SORT,
            ROW_LEVEL,
            COMPANY_CD,
            ROW_TYPE,
            ACCOUNT_CD,
            ACCOUNT_NAME,
            
            REPORT_YEAR_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT
        )
        VALUES
        (
            'OPENING_BALANCE',
            10,
            p_COMPANY_CD,
            'OPENING',
            '', -- v_account_cd_text,
            '', -- v_account_name_text,
            v_report_year_text,
            'Đơn vị tính: đồng',
            
            'Số dư đầu năm',
            NULLIF(ROUND(GREATEST(v_opening_net, 0), 0), 0),
            NULLIF(ROUND(GREATEST(-v_opening_net, 0), 0), 0)
        );
*/
        INSERT INTO tmp_general_ledger_report
        (
            ROW_KEY,
            PARENT_ROW_KEY,
            LINE_SORT,
            ROW_LEVEL,
            COMPANY_CD,
            ROW_TYPE,
            
            ACC_CD, -- ACC LEVEL=1
            ACCOUNT_CD,
            ACCOUNT_NAME,
            REPORT_YEAR_TEXT,
            AMOUNT_UNIT_TEXT,
            
            CHIT_NO,
            CHIT_ID,
            CHIT_TYPE,
            MODULE_CD,
            CHIT_YMD,
            DESCRIPTION,
            CSD_ACC_CD,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT,
            CUSTOMER_ID
        )
        SELECT
            CONCAT('DETAIL_', movement.ROW_NO),
            CONCAT('ACCOUNT_', movement.ACC_CD),
            1000,
            1,
            p_COMPANY_CD,
            'DETAIL',
            
            ACC_CD, -- ACC LEVEL=1
            '', -- v_account_cd_text,
            '', -- v_account_name_text,
            v_report_year_text,
            'Đơn vị tính: đồng',

            movement.CHIT_NO,
            movement.CHIT_ID,
            movement.CHIT_TYPE,
            movement.MODULE_CD,
            movement.CHIT_YMD,
            movement.DESCRIPTION,
            movement.CSD_ACC_CD,
            NULLIF(ROUND(movement.DEBIT_AMOUNT, 0), 0),
            NULLIF(ROUND(movement.CREDIT_AMOUNT, 0), 0),
            CUSTOMER_ID
        FROM tmp_Details movement
        WHERE movement.CHIT_YMD >= v_from_ymd AND movement.CHIT_YMD <= v_to_ymd
        ORDER BY movement.CHIT_YMD, movement.SORT_NO, movement.SORT_CHIT_ID, movement.SORT_DETAIL, movement.SORT_SIDE;
/*
        INSERT INTO tmp_general_ledger_report
        (
            ROW_KEY,
            LINE_SORT,
            COMPANY_CD,
            ROW_TYPE,
            ACCOUNT_CD,
            ACCOUNT_NAME,
            REPORT_YEAR_TEXT,
            AMOUNT_UNIT_TEXT,
            DESCRIPTION,
            DEBIT_AMOUNT,
            CREDIT_AMOUNT
        )
        VALUES
        (
            'TOTAL_PERIOD',
            900000,
            p_COMPANY_CD,
            'TOTAL_PERIOD',
            '', -- v_account_cd_text,
            '', -- v_account_name_text,
            v_report_year_text,
            'Đơn vị tính: đồng',
            'Cộng số phát sinh trong tháng',
            NULLIF(ROUND(v_period_debit, 0), 0),
            NULLIF(ROUND(v_period_credit, 0), 0)
        ),
        (
            'ENDING_BALANCE',
            900010,
            p_COMPANY_CD,
            'ENDING',
            '', -- v_account_cd_text,
            '', -- v_account_name_text,
            v_report_year_text,
            'Đơn vị tính: đồng',
            'Số dư cuối tháng',
            NULLIF(ROUND(GREATEST(v_ending_net, 0), 0), 0),
            NULLIF(ROUND(GREATEST(-v_ending_net, 0), 0), 0)
        ),
        (
            'QUARTER_ACCUMULATED',
            900020,
            p_COMPANY_CD,
            'QUARTER_ACCUMULATED',
            '', -- v_account_cd_text,
            '', -- v_account_name_text,
            v_report_year_text,
            'Đơn vị tính: đồng',
            'Cộng lũy kế từ đầu quý',
            NULLIF(ROUND(v_quarter_debit, 0), 0),
            NULLIF(ROUND(v_quarter_credit, 0), 0)
        );
*/
    END IF;

    SELECT
        R.ROW_KEY as __ROW_KEY,
        R.PARENT_ROW_KEY AS __PARENT_ROW_KEY,
        R.ROW_NO AS __ROW_SORT,
        R.ROW_LEVEL AS __ROW_LEVEL,
        0 AS __TREE_EXPAND_ALL,
        R.LINE_SORT as __LINE_SORT,
        R.COMPANY_CD as __COMPANY_CD,
        R.REPORT_GROUP_KEY as __REPORT_GROUP_KEY,
        R.ROW_TYPE AS __ROW_TYPE,
        
        CASE WHEN R.ROW_TYPE = 'GROUP' THEN CONCAT(A.ACC_CD, '-', A.ACCOUNT_NAME) ELSE '' END AS ACC_CD,
        R.CHIT_TYPE,
        R.CHIT_ID AS __CHIT_ID,
        R.CHIT_TYPE AS __CHIT_TYPE,
        R.MODULE_CD AS __MODULE_CD,
        CASE WHEN R.ROW_TYPE = 'DETAIL' AND IFNULL(R.CHIT_ID, 0) > 0 THEN 'DOCUMENT' ELSE 'NONE' END AS __LINK_TYPE,
        R.CHIT_NO,
        R.CHIT_YMD,
        
--        R.CUSTOMER_ID,
        C.CUSTOMER_CD,
        (
        		CASE v_language 
				  	WHEN 'KOR' THEN COALESCE(NULLIF(TRIM(C.CUSTOMER_NM_KOR), ''), NULLIF(TRIM(C.CUSTOMER_NM_ENG), ''), NULLIF(TRIM(C.CUSTOMER_NM_VIET), '')) 
				  	WHEN 'ENG' THEN COALESCE(NULLIF(TRIM(C.CUSTOMER_NM_ENG), ''), NULLIF(TRIM(C.CUSTOMER_NM_VIET), '')) 
				  	ELSE C.CUSTOMER_NM_VIET
				END
		  )AS CUSTOMER_NM,
        
--        '' AS MG_CD, -- MÃ QUẢN LÝ
--        '' AS MG_DESC,
        
--        '' AS MG_CD_2, -- MÃ QUẢN LÝ 2
--        '' AS MG_DESC_2,
        
--        '' AS MR_DESC, -- TÊN GHI CHÚ
        
--        '' AS DEPARTMENT_CD,
--        '' AS DEPARTMENT_NM,
        
        R.ACCOUNT_CD AS __ACCOUNT_CD,
        R.ACCOUNT_NAME AS __ACCOUNT_NAME_TEXT,
        R.ACCOUNT_CD AS __ACCOUNT_CD_TEXT,

        R.REPORT_YEAR_TEXT as __REPORT_YEAR_TEXT,
        R.AMOUNT_UNIT_TEXT as __AMOUNT_UNIT_TEXT,
        
        R.DESCRIPTION,
--        '' AS DESCRIPTION2,
        
--		  '' AS lblACC_CD, -- TK
--        '' AS ACCTITLE_NM,
        
        R.CSD_ACC_CD, -- TK ĐỐI ỨNG
        (select ACCOUNT_NAME from  tmp_Accounts_Child ac where ac.ACC_CD = R.CSD_ACC_CD) AS CSD_ACCTITLE_NM,
        
        R.DEBIT_AMOUNT,
        R.CREDIT_AMOUNT,
        R.NOTE_TEXT as __NOTE_TEXT
        
        
    FROM tmp_general_ledger_report R
    	left join tmp_Accounts A ON R.ACC_CD = A.ACC_CD
    	LEFT JOIN CUSTOMER_INFO C ON C.CUSTOMER_ID = R.CUSTOMER_ID
    ORDER BY A.ACC_CD, R.LINE_SORT, R.ROW_NO;

    DROP TEMPORARY TABLE IF EXISTS tmp_general_ledger_sums;
    DROP TEMPORARY TABLE IF EXISTS tmp_Details;
    DROP TEMPORARY TABLE IF EXISTS tmp_general_ledger_opening_base;
    DROP TEMPORARY TABLE IF EXISTS tmp_general_ledger_latest_open;
    DROP TEMPORARY TABLE IF EXISTS tmp_general_ledger_report; -- RETURN
    DROP TEMPORARY TABLE IF EXISTS tmp_Accounts;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_inventory_adjust_voucher
DROP PROCEDURE IF EXISTS `rpt_inventory_adjust_voucher`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_inventory_adjust_voucher`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHIT_ID BIGINT,
    IN p_CHIT_IDS TEXT,
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_ids TEXT;
    DECLARE v_token VARCHAR(32);
    DECLARE v_language VARCHAR(20);
    DECLARE v_TOTAL VARCHAR(100); -- TỔNG
	 
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        DROP TEMPORARY TABLE IF EXISTS tmp_iv_result;
        DROP TEMPORARY TABLE IF EXISTS tmp_total_summary_row;
        DROP TEMPORARY TABLE IF EXISTS tmp_chit_inventory_details;
--        DROP TEMPORARY TABLE IF EXISTS tmp_iv_input_dates;
        DROP TEMPORARY TABLE IF EXISTS tmp_chit_inventory_info;
        DROP TEMPORARY TABLE IF EXISTS tmp_iv_ids;
        RESIGNAL;
    END;

    DROP TEMPORARY TABLE IF EXISTS tmp_iv_result;
    DROP TEMPORARY TABLE IF EXISTS tmp_total_summary_row;
    DROP TEMPORARY TABLE IF EXISTS tmp_chit_inventory_details;
--    DROP TEMPORARY TABLE IF EXISTS tmp_iv_input_dates;
    DROP TEMPORARY TABLE IF EXISTS tmp_chit_inventory_info;
    DROP TEMPORARY TABLE IF EXISTS tmp_iv_ids;

    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));
    SET v_ids = REPLACE(REPLACE(REPLACE(REPLACE(IFNULL(TRIM(p_CHIT_IDS), ''), '|', ','), ';', ','), CHAR(10), ','), CHAR(13), ',');
    IF v_ids = '' AND IFNULL(p_CHIT_ID, 0) > 0 THEN
        SET v_ids = CAST(p_CHIT_ID AS CHAR);
    END IF;
	 
	 
	 -- TỔNG
	 select (CASE
                WHEN v_language = 'ENG' THEN p.ENG
                WHEN v_language = 'KOR' THEN p.KOR                
                ELSE p.VIET
            END) INTO v_TOTAL
	 from am_web_manager.t_message_info P where `key` like 'ALL_TOTAL';
	 
	 
	 
	 
    CREATE TEMPORARY TABLE tmp_iv_ids (
        INVENTORY_ID BIGINT NOT NULL PRIMARY KEY
    ) ENGINE=InnoDB;

    -- Resolve the caller-supplied list once; all subsequent joins use indexed IDs.
    WHILE v_ids <> '' DO
        SET v_token = TRIM(SUBSTRING_INDEX(v_ids, ',', 1));
        IF v_token REGEXP '^[0-9]{1,19}$' THEN
            INSERT IGNORE INTO tmp_iv_ids (INVENTORY_ID) VALUES (CAST(v_token AS UNSIGNED));
        END IF;
        IF LOCATE(',', v_ids) > 0 THEN
            SET v_ids = SUBSTRING(v_ids, LOCATE(',', v_ids) + 1);
        ELSE
            SET v_ids = '';
        END IF;
    END WHILE;

-- 1. tmp_chit_inventory_info
    CREATE TEMPORARY TABLE tmp_chit_inventory_info ENGINE=InnoDB AS
    SELECT h.INVENTORY_ID, h.COMPANY_CD, h.INVENTORY_CD, h.INVENTORY_NO,
           h.INVENTORY_YMD, 
           MIN(DATE_FORMAT(h.INVENTORY_YMD, '%Y-%m-%dT%H:%i:%s')) AS INPUT_DATE, 
			  h.AMOUNT, h.REMARK, h.UPDATE_BY, h.CREATE_BY,
           h.CUSTOMER_ID, h.CUSTOMER_CD
    FROM chit_inventory_info h 
    WHERE h.INVENTORY_ID IN (SELECT ids.INVENTORY_ID FROM tmp_iv_ids ids)
	 	AND h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'INV'
      AND h.ISDEL = '0';
      
    ALTER TABLE tmp_chit_inventory_info ADD PRIMARY KEY (INVENTORY_ID);

-- SELECT * FROM tmp_chit_inventory_info;


-- 2.  
/*
    CREATE TEMPORARY TABLE tmp_iv_input_dates ENGINE=InnoDB AS
    SELECT ii.INVENTORY_ID AS CHIT_ID,
           IFNULL(ii.SORT, 0) AS SORT_NO,
           MIN(DATE_FORMAT(ii.INVENTORY_YMD, '%Y-%m-%dT%H:%i:%s')) AS INPUT_DATE
    FROM chit_inventory_input ii
    WHERE 
    		ii.INVENTORY_ID IN (SELECT h.INVENTORY_ID FROM tmp_chit_inventory_info h)
	 		AND ii.ISDEL = '0'
    		AND II.COMPANY_CD = p_COMPANY_CD
    GROUP BY ii.INVENTORY_ID, IFNULL(ii.SORT, 0);
    
    ALTER TABLE tmp_iv_input_dates ADD PRIMARY KEY (CHIT_ID, SORT_NO);
    
-- SELECT * FROM tmp_iv_input_dates;
*/

-- 2. 
    CREATE TEMPORARY TABLE tmp_chit_inventory_details (
        ROW_ID BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
        CHIT_ID BIGINT NOT NULL,
        PRODUCT_NAME VARCHAR(500) COLLATE utf8_unicode_ci,
        PRODUCT_CD VARCHAR(100) COLLATE utf8_unicode_ci,
        UNIT_NAME VARCHAR(255) COLLATE utf8_unicode_ci,
        QUANTITY DECIMAL(28,8),
        UNIT_PRICE DECIMAL(28,8),
        LINE_AMOUNT DECIMAL(28,8),
        STORE_NAME VARCHAR(500) COLLATE utf8_unicode_ci,
        INPUT_INVENTORY_YMD VARCHAR(32),
        OUTPUT_INVENTORY_YMD VARCHAR(32),
        KEY IX_VOUCHER (CHIT_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    -- Ordered INSERT assigns deterministic, consecutive auto-increment IDs.
    -- LINE_SORT is ROW_ID - MIN(ROW_ID) per voucher + 1; no per-line COUNT(*).
    INSERT INTO tmp_chit_inventory_details
        (CHIT_ID, PRODUCT_NAME, PRODUCT_CD, UNIT_NAME, QUANTITY, UNIT_PRICE,
         LINE_AMOUNT, STORE_NAME, INPUT_INVENTORY_YMD, OUTPUT_INVENTORY_YMD)
    SELECT io.INVENTORY_ID,
           NULLIF(TRIM(CASE
                WHEN v_language = 'ENG' THEN p.PRODUCT_NM_ENG
                WHEN v_language = 'KOR' THEN p.PRODUCT_NM_KOR
                WHEN v_language IN ('CHN', 'CHINA') THEN p.PRODUCT_NM_CHINA
                ELSE p.PRODUCT_NM_VIET
            END), ''), 
           io.PRODUCT_CD,
           u.UNIT_NM, 
           io.QUANTITY,
           io.UNIT_PRICE_CC,
           (CASE WHEN IFNULL(io.AMOUNT_CC, 0) <> 0 THEN io.AMOUNT_CC
                ELSE IFNULL(io.QUANTITY, 0) * IFNULL(io.UNIT_PRICE_CC, 0) END) as LINE_AMOUNT,
           s.STORE_NM_VIET,
        	  h.INPUT_DATE as INPUT_INVENTORY_YMD, -- d0.INPUT_DATE,
           DATE_FORMAT(io.INVENTORY_YMD, '%Y-%m-%dT%H:%i:%s') as OUTPUT_INVENTORY_YMD
    FROM tmp_chit_inventory_info h
			INNER JOIN chit_inventory_output io       ON io.COMPANY_CD = h.COMPANY_CD AND io.INVENTORY_ID = h.INVENTORY_ID      AND io.ISDEL = '0'
			LEFT JOIN product_info p       ON p.COMPANY_CD = io.COMPANY_CD      AND p.PRODUCT_ID = io.PRODUCT_ID AND IFNULL(p.ISDEL, '0') = '0'
			LEFT JOIN product_unit u       ON u.COMPANY_CD = io.COMPANY_CD      AND u.UNIT_ID = io.UNIT_ID AND IFNULL(u.ISDEL, '0') = '0'
			LEFT JOIN store_info	  s 		 ON s.COMPANY_CD = io.COMPANY_CD      AND s.STORE_ID = io.STORE_ID AND IFNULL(s.ISDEL, '0') = '0'
--			LEFT JOIN tmp_iv_input_dates d0      ON d0.CHIT_ID = io.INVENTORY_ID     AND d0.SORT_NO = IFNULL(io.SORT, 0)
    ORDER BY io.INVENTORY_ID, IFNULL(io.SORT, 0), io.OUTPUT_ID;





    CREATE TEMPORARY TABLE tmp_total_summary_row ENGINE=InnoDB AS
    SELECT CHIT_ID, COUNT(*) AS LINE_COUNT,
           MIN(ROW_ID) AS FIRST_ROW_ID,
           MIN(CASE WHEN STORE_NAME IS NOT NULL AND TRIM(STORE_NAME) <> '' THEN ROW_ID ELSE NULL END) AS FIRST_STORE_ROW_ID,
           SUM(IFNULL(QUANTITY, 0)) AS TOTAL_QUANTITY,
           SUM(IFNULL(LINE_AMOUNT, 0)) AS TOTAL_AMOUNT
    FROM tmp_chit_inventory_details
    GROUP BY CHIT_ID;
    ALTER TABLE tmp_total_summary_row ADD PRIMARY KEY (CHIT_ID);



    CREATE TEMPORARY TABLE tmp_iv_result (
        CHIT_ID BIGINT NOT NULL,
        LINE_SORT BIGINT NOT NULL,
        LINE_NO VARCHAR(20) COLLATE utf8_unicode_ci NOT NULL DEFAULT '',
        PRODUCT_NAME VARCHAR(500) COLLATE utf8_unicode_ci,
        PRODUCT_CD VARCHAR(100) COLLATE utf8_unicode_ci,
        UNIT_NAME VARCHAR(255) COLLATE utf8_unicode_ci,
        QUANTITY DECIMAL(28,8),
        UNIT_PRICE DECIMAL(28,8),
        LINE_AMOUNT DECIMAL(28,8),
        INPUT_INVENTORY_YMD VARCHAR(32),
        OUTPUT_INVENTORY_YMD VARCHAR(32),
        KEY IX_VOUCHER_ORDER (CHIT_ID, LINE_SORT)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_iv_result
      (CHIT_ID, LINE_SORT, LINE_NO, PRODUCT_NAME, PRODUCT_CD, UNIT_NAME,
       QUANTITY, UNIT_PRICE, LINE_AMOUNT, INPUT_INVENTORY_YMD, OUTPUT_INVENTORY_YMD)
    SELECT d.CHIT_ID, d.ROW_ID - s.FIRST_ROW_ID + 1,
           CAST(d.ROW_ID - s.FIRST_ROW_ID + 1 AS CHAR),
           d.PRODUCT_NAME, d.PRODUCT_CD, d.UNIT_NAME,
           d.QUANTITY, d.UNIT_PRICE, d.LINE_AMOUNT,
           d.INPUT_INVENTORY_YMD, d.OUTPUT_INVENTORY_YMD
    FROM tmp_chit_inventory_details d
    INNER JOIN tmp_total_summary_row s ON s.CHIT_ID = d.CHIT_ID;




  

    INSERT INTO tmp_iv_result
      	(CHIT_ID, LINE_SORT, LINE_NO, PRODUCT_CD, QUANTITY, LINE_AMOUNT)
    SELECT h.INVENTORY_ID, 999999, v_TOTAL, v_TOTAL,
           IFNULL(s.TOTAL_QUANTITY, 0), IFNULL(s.TOTAL_AMOUNT, 0)
    FROM tmp_chit_inventory_info h
    	LEFT JOIN tmp_total_summary_row s ON s.CHIT_ID = h.INVENTORY_ID;

-- select * from tmp_iv_result;

    -- Output fields are kept compatible with company_report_element.VALUE_FIELD.
    SELECT
        h.INVENTORY_ID AS CHIT_ID,
        h.COMPANY_CD,
		'' AS WAREHOUSE_NAME_TO,
        h.INVENTORY_CD AS CHIT_CD,
        h.INVENTORY_NO AS CHIT_NO,
        DATE_FORMAT(h.INVENTORY_YMD, '%d/%m/%Y') AS CHIT_YMD,
        DATE_FORMAT(h.INVENTORY_YMD, '%d/%m/%Y') AS HEADER_DATE_TEXT,
        DATE_FORMAT(h.INVENTORY_YMD, '%d/%m/%Y') AS SIGNATURE_DATE_TEXT,
        CASE
            WHEN v_language = 'ENG' THEN COALESCE(NULLIF(TRIM(cust.CUSTOMER_NM_ENG), ''), cust.CUSTOMER_NM_VIET, '')
            WHEN v_language = 'KOR' THEN COALESCE(NULLIF(TRIM(cust.CUSTOMER_NM_KOR), ''), NULLIF(TRIM(cust.CUSTOMER_NM_ENG), ''), cust.CUSTOMER_NM_VIET, '')
            WHEN v_language IN ('CHN', 'CHINA') THEN COALESCE(NULLIF(TRIM(cust.CUSTOMER_NM_CHINA), ''), NULLIF(TRIM(cust.CUSTOMER_NM_ENG), ''), cust.CUSTOMER_NM_VIET, '')
            ELSE cust.CUSTOMER_NM_VIET
        END AS PARTNER_NAME,
        IFNULL(cust.ADDRESS, '') AS PARTNER_ADDRESS,
        IFNULL(h.REMARK, '') AS REASON,
        IFNULL(h.REMARK, '') AS SOURCE_DOCUMENT_TEXT,
        IFNULL(first_line.STORE_NAME, '') AS WAREHOUSE_NAME,
        '' AS WAREHOUSE_LOCATION,
        IFNULL(h.AMOUNT, IFNULL(r.LINE_AMOUNT, 0)) AS AMOUNT,
        NULL AS AMOUNT_TEXT,
        NULL AS AMOUNT_IN_WORDS,
        NULL AS FC_AMOUNT,
        NULL AS FC_TYPE,
        NULL AS FC_RATE,
        NULL AS EXCHANGE_RATE_TEXT,
        NULL AS CONVERTED_AMOUNT_TEXT,
        '' AS DEBIT_ACCOUNT,
        '' AS CREDIT_ACCOUNT,
        IFNULL(r.QUANTITY, 0) AS DETAIL_COUNT,
        NULL AS ATTACHMENT_TEXT,
        NULL AS REFERENCE_TEXT,
        IFNULL(h.REMARK, '') AS NOTE,
        NULL AS NOTE_TEXT,
        COALESCE(NULLIF(TRIM(h.UPDATE_BY), ''), NULLIF(TRIM(h.CREATE_BY), ''), '') AS CREATED_BY,
        r.LINE_SORT, r.LINE_NO, r.PRODUCT_NAME, r.PRODUCT_CD, r.UNIT_NAME,
        r.QUANTITY,
        r.UNIT_PRICE,
        r.LINE_AMOUNT,
        r.INPUT_INVENTORY_YMD,
        r.OUTPUT_INVENTORY_YMD,
        h.CUSTOMER_ID,
        h.CUSTOMER_CD
    FROM tmp_iv_result r
	    INNER JOIN tmp_chit_inventory_info h ON r.CHIT_ID = h.INVENTORY_ID
--	    INNER JOIN tmp_total_summary_row s ON s.CHIT_ID = h.INVENTORY_ID
	    INNER JOIN tmp_chit_inventory_details first_line ON h.INVENTORY_ID = first_line.CHIT_ID -- first_line.ROW_ID = s.FIRST_STORE_ROW_ID
	    LEFT JOIN customer_info cust      ON cust.CUSTOMER_ID = h.CUSTOMER_ID AND cust.COMPANY_CD = p_COMPANY_CD AND IFNULL(cust.ISDEL, '0') = '0'
    ORDER BY h.INVENTORY_YMD, h.INVENTORY_ID, r.LINE_SORT;

    DROP TEMPORARY TABLE IF EXISTS tmp_iv_result;
    DROP TEMPORARY TABLE IF EXISTS tmp_total_summary_row;
    DROP TEMPORARY TABLE IF EXISTS tmp_chit_inventory_details;
--    DROP TEMPORARY TABLE IF EXISTS tmp_iv_input_dates;
    DROP TEMPORARY TABLE IF EXISTS tmp_chit_inventory_info;
    DROP TEMPORARY TABLE IF EXISTS tmp_iv_ids;

END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_inventory_detail_book
DROP PROCEDURE IF EXISTS `rpt_inventory_detail_book`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_inventory_detail_book`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_ACCOUNT_CD VARCHAR(20),
    IN p_MENU_CODE VARCHAR(100),
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_account_cd VARCHAR(20) DEFAULT '';
    DECLARE v_account_name VARCHAR(255) DEFAULT '';
    DECLARE v_menu_code VARCHAR(100) DEFAULT '';
    DECLARE v_language VARCHAR(20) DEFAULT 'VIET';
    DECLARE v_opening_quantity DECIMAL(18,4) DEFAULT 0.0000;
    DECLARE v_opening_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_total_input_quantity DECIMAL(18,4) DEFAULT 0.0000;
    DECLARE v_total_input_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_total_output_quantity DECIMAL(18,4) DEFAULT 0.0000;
    DECLARE v_total_output_amount DECIMAL(18,2) DEFAULT 0.00;
    DECLARE v_store_name VARCHAR(255) DEFAULT '';
    DECLARE v_bad_output BIGINT DEFAULT NULL;
    DECLARE v_cogs_error VARCHAR(128);

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;

    SELECT MIN(io.OUTPUT_ID) INTO v_bad_output
    FROM chit_inventory_output io
    LEFT JOIN chit_inventory_info t ON t.COMPANY_CD=io.COMPANY_CD AND t.INVENTORY_ID=io.INVENTORY_ID AND t.ISDEL='0'
    LEFT JOIN chitinfo c ON c.COMPANY_CD=t.COMPANY_CD AND c.CHIT_ID=t.CHIT_ID_COGS AND c.ISDEL='0' AND c.CHIT_TYPE IN ('OT','IO_COGS') AND c.INPUT_TYPE='AR'
    LEFT JOIN (
        SELECT COMPANY_CD,CHIT_ID,COUNT(*) AS DETAIL_COUNT,SUM(AMOUNT) AS DETAIL_AMOUNT,MIN(DEBIT) AS DEBIT,MIN(CREDIT) AS CREDIT
        FROM chitdetailinfo WHERE ISDEL='0' GROUP BY COMPANY_CD,CHIT_ID
    ) d ON d.COMPANY_CD=c.COMPANY_CD AND d.CHIT_ID=c.CHIT_ID
    LEFT JOIN chitdetailinfo linked_cogs ON linked_cogs.COMPANY_CD=t.COMPANY_CD
        AND linked_cogs.CHITDETAIL_ID=t.CHITDETAIL_ID_COGS AND linked_cogs.CHIT_ID=c.CHIT_ID
        AND linked_cogs.ISDEL='0'
    LEFT JOIN (
        SELECT COMPANY_CD,INVENTORY_ID,SUM(AMOUNT_CC) AS COST_AMOUNT
        FROM chit_inventory_output WHERE ISDEL='0' AND CHIT_TYPE='IO' GROUP BY COMPANY_CD,INVENTORY_ID
    ) totals ON totals.COMPANY_CD=io.COMPANY_CD AND totals.INVENTORY_ID=io.INVENTORY_ID
    WHERE io.COMPANY_CD=p_COMPANY_CD AND io.ISDEL='0' AND io.CHIT_TYPE='IO'
        AND DATE(io.INVENTORY_YMD) <= p_TO_DATE
        -- Only require a COGS voucher when the inventory issue has COGS enabled.
        -- Keep missing inventory headers in scope so orphaned output rows still fail validation.
        AND (t.INVENTORY_ID IS NULL OR IFNULL(t.IS_COGS,'0') <> '0')
        AND (t.INVENTORY_ID IS NULL OR c.CHIT_ID IS NULL OR NOT (
            (linked_cogs.CHITDETAIL_ID IS NOT NULL AND linked_cogs.DEBIT='632' AND linked_cogs.CREDIT='156'
                AND linked_cogs.AMOUNT>=0 AND linked_cogs.CHIT_YMD=t.INVENTORY_YMD
                AND ROUND(c.AMOUNT,2)=ROUND(d.DETAIL_AMOUNT,2))
            OR (t.CHITDETAIL_ID_COGS IS NULL AND IFNULL(d.DETAIL_COUNT,0)=1 AND d.DEBIT='632' AND d.CREDIT='156'
                AND ROUND(d.DETAIL_AMOUNT,2)=ROUND(totals.COST_AMOUNT,2)
                AND ROUND(c.AMOUNT,2)=ROUND(totals.COST_AMOUNT,2)
                AND EXISTS (SELECT 1 FROM acclist_info a WHERE a.COMPANY_CD=c.COMPANY_CD AND a.ACC_CD='632' AND a.ISDEL='0')
                AND EXISTS (SELECT 1 FROM acclist_info a WHERE a.COMPANY_CD=c.COMPANY_CD AND a.ACC_CD='156' AND a.ISDEL='0'))
            OR (t.CHITDETAIL_ID_COGS IS NULL AND EXISTS (
                SELECT 1 FROM chitdetailinfo legacy
                WHERE legacy.COMPANY_CD=io.COMPANY_CD AND legacy.CHIT_ID=c.CHIT_ID
                    AND legacy.CHITDETAIL_ID=io.CHITDETAIL_ID_COGS AND legacy.ISDEL='0'
                    AND ROUND(legacy.AMOUNT,2)=ROUND(io.AMOUNT_CC,2)
                    AND legacy.DEBIT LIKE '632%' AND legacy.CREDIT LIKE '156%'
            ))));
    IF v_bad_output IS NOT NULL THEN
        SET v_cogs_error = CONCAT('Missing or invalid COGS for inventory output ',v_bad_output);
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT=v_cogs_error;
    END IF;

    SET v_menu_code = UPPER(TRIM(IFNULL(p_MENU_CODE, '')));
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));
    SET v_account_cd = NULLIF(TRIM(IFNULL(p_ACCOUNT_CD, '')), '');
    SET v_account_cd = IFNULL(v_account_cd, CASE v_menu_code
            WHEN 'INV_REPORT_DETAIL_PRODUCT' THEN '156'
            WHEN 'INV_REPORT_DETAIL_DEPT' THEN '152'
            WHEN 'INV_REPORT_DETAIL_ACCOUNT' THEN '153'
            WHEN 'INV_REPORT_DETAIL_STORE' THEN '155'
            ELSE '152'
            END);

    SELECT COALESCE(
        NULLIF(TRIM(CASE v_language
            WHEN 'ENG' THEN account.ACCTITLE_NM_ENG
            WHEN 'KOR' THEN account.ACCTITLE_NM_KOR
            WHEN 'CHN' THEN account.ACCTITLE_NM_CHINA
            WHEN 'VIET' THEN account.ACCTITLE_NM_VIET
            ELSE account.ACCTITLE_NM_VIET
            END), ''),
        NULLIF(TRIM(account.ACCTITLE_NM_VIET), ''),
        ''
        )
    INTO v_account_name
    FROM acclist_info account
    WHERE account.COMPANY_CD = p_COMPANY_CD
        AND account.ACC_CD = v_account_cd
        AND IFNULL(account.ISDEL, '0') = '0'
    ORDER BY account.ACC_ID DESC
    LIMIT 1;

    DROP TEMPORARY TABLE IF EXISTS tmp_inventory_detail_base;
    CREATE TEMPORARY TABLE tmp_inventory_detail_base
    (
        FLOW_TYPE VARCHAR(10) NOT NULL DEFAULT '',
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        CHIT_ID BIGINT NULL,
        CHITDETAIL_ID BIGINT NULL,
        INVENTORY_ID BIGINT NOT NULL DEFAULT 0,
        DOCUMENT_NO VARCHAR(50) NOT NULL DEFAULT '',
        TXN_YMD VARCHAR(8) NOT NULL DEFAULT '',
        DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
        ACCOUNT_CD VARCHAR(20) NOT NULL DEFAULT '',
        COUNTERPART_ACCOUNT VARCHAR(20) NOT NULL DEFAULT '',
        PRODUCT_CD VARCHAR(50) NOT NULL DEFAULT '',
        PRODUCT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        STORE_CD VARCHAR(50) NOT NULL DEFAULT '',
        STORE_NAME VARCHAR(255) NOT NULL DEFAULT '',
        UNIT_NAME VARCHAR(100) NOT NULL DEFAULT '',
        UNIT_PRICE DECIMAL(18,4) NULL,
        INPUT_QUANTITY DECIMAL(18,4) NOT NULL DEFAULT 0.0000,
        INPUT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        OUTPUT_QUANTITY DECIMAL(18,4) NOT NULL DEFAULT 0.0000,
        OUTPUT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        SORT_NO INT NOT NULL DEFAULT 0
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

    INSERT INTO tmp_inventory_detail_base
    (
        FLOW_TYPE,
        COMPANY_CD,
        CHIT_ID,
        CHITDETAIL_ID,
        INVENTORY_ID,
        DOCUMENT_NO,
        TXN_YMD,
        DESCRIPTION,
        ACCOUNT_CD,
        COUNTERPART_ACCOUNT,
        PRODUCT_CD,
        PRODUCT_NAME,
        STORE_CD,
        STORE_NAME,
        UNIT_NAME,
        UNIT_PRICE,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        SORT_NO
    )
    SELECT
        'INPUT',
        ii.COMPANY_CD,
        ii.INVENTORY_ID,
        d.CHITDETAIL_ID,
        ii.INPUT_ID,
        COALESCE(NULLIF(TRIM(h.INVENTORY_NO), ''), NULLIF(TRIM(ii.INVENTORY_CD), ''), ''),
        COALESCE(DATE_FORMAT(ii.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(h.INVENTORY_YMD), '')),
        COALESCE(NULLIF(TRIM(ii.SUMMARY), ''), NULLIF(TRIM(detail_desc.DESCRIPTION), ''), NULLIF(TRIM(h.REMARK), ''), ''),
        IFNULL(d.DEBIT, ''),
        IFNULL(d.CREDIT, ''),
        COALESCE(NULLIF(TRIM(ii.PRODUCT_CD), ''), product.PRODUCT_CD, ''),
        COALESCE(NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN product.PRODUCT_NM_ENG WHEN 'KOR' THEN product.PRODUCT_NM_KOR WHEN 'CHN' THEN product.PRODUCT_NM_CHINA ELSE product.PRODUCT_NM_VIET END), ''), ii.PRODUCT_CD, ''),
        COALESCE(NULLIF(TRIM(ii.STORE_CD), ''), store_info.STORE_CD, ''),
        COALESCE(NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN store_info.STORE_NM_ENG WHEN 'KOR' THEN store_info.STORE_NM_KOR WHEN 'CHN' THEN store_info.STORE_NM_CHINA ELSE store_info.STORE_NM_VIET END), ''), ii.STORE_CD, ''),
        COALESCE(NULLIF(TRIM(unit_info.UNIT_NM), ''), ii.UNIT_CD, ''),
        NULLIF(ii.UNIT_PRICE_CC, 0),
        IFNULL(ii.QUANTITY, 0),
        CASE WHEN IFNULL(ii.AMOUNT_CC, 0) <> 0 THEN IFNULL(ii.AMOUNT_CC, 0) ELSE IFNULL(ii.QUANTITY, 0) * IFNULL(ii.UNIT_PRICE_CC, 0) END,
        0,
        0,
        IFNULL(ii.SORT, 0)
    FROM chit_inventory_input ii
    LEFT JOIN chit_inventory_info h
        ON h.COMPANY_CD = ii.COMPANY_CD
        AND h.INVENTORY_ID = ii.INVENTORY_ID
        AND IFNULL(h.ISDEL, '0') = '0'
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = ii.COMPANY_CD
        AND IFNULL(ii.CHITDETAIL_ID, 0) > 0
        AND d.CHITDETAIL_ID = ii.CHITDETAIL_ID
        AND IFNULL(d.ISDEL, '0') = '0'
    LEFT JOIN product_info product
        ON product.COMPANY_CD = ii.COMPANY_CD
        AND product.PRODUCT_ID = ii.PRODUCT_ID
        AND IFNULL(product.ISDEL, '0') = '0'
    LEFT JOIN store_info
        ON store_info.COMPANY_CD = ii.COMPANY_CD
        AND store_info.STORE_ID = ii.STORE_ID
        AND IFNULL(store_info.ISDEL, '0') = '0'
    LEFT JOIN product_unit unit_info
        ON unit_info.COMPANY_CD = ii.COMPANY_CD
        AND unit_info.UNIT_ID = ii.UNIT_ID
        AND IFNULL(unit_info.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo detail_desc
        ON detail_desc.COMPANY_CD = d.COMPANY_CD
        AND detail_desc.CHITDETAIL_ID = d.CHITDETAIL_ID
        AND detail_desc.LANG_TYPE = v_language
        AND IFNULL(detail_desc.ISDEL, '0') = '0'
    WHERE ii.COMPANY_CD = p_COMPANY_CD
        AND IFNULL(ii.ISDEL, '0') = '0'
        AND IFNULL(d.DEBIT, '') LIKE CONCAT(v_account_cd, '%')
        AND COALESCE(DATE_FORMAT(ii.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(h.INVENTORY_YMD), '')) IS NOT NULL;

    INSERT INTO tmp_inventory_detail_base
    (
        FLOW_TYPE,
        COMPANY_CD,
        CHIT_ID,
        CHITDETAIL_ID,
        INVENTORY_ID,
        DOCUMENT_NO,
        TXN_YMD,
        DESCRIPTION,
        ACCOUNT_CD,
        COUNTERPART_ACCOUNT,
        PRODUCT_CD,
        PRODUCT_NAME,
        STORE_CD,
        STORE_NAME,
        UNIT_NAME,
        UNIT_PRICE,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        SORT_NO
    )
    SELECT
        'OUTPUT',
        io.COMPANY_CD,
        io.INVENTORY_ID,
        d.CHITDETAIL_ID,
        io.OUTPUT_ID,
        COALESCE(NULLIF(TRIM(h.INVENTORY_NO), ''), NULLIF(TRIM(io.INVENTORY_CD), ''), ''),
        COALESCE(DATE_FORMAT(io.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(h.INVENTORY_YMD), '')),
        COALESCE(NULLIF(TRIM(io.SUMMARY), ''), NULLIF(TRIM(detail_desc.DESCRIPTION), ''), NULLIF(TRIM(h.REMARK), ''), ''),
        IFNULL(d.CREDIT, ''),
        IFNULL(d.DEBIT, ''),
        COALESCE(NULLIF(TRIM(io.PRODUCT_CD), ''), product.PRODUCT_CD, ''),
        COALESCE(NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN product.PRODUCT_NM_ENG WHEN 'KOR' THEN product.PRODUCT_NM_KOR WHEN 'CHN' THEN product.PRODUCT_NM_CHINA ELSE product.PRODUCT_NM_VIET END), ''), io.PRODUCT_CD, ''),
        COALESCE(NULLIF(TRIM(io.STORE_CD), ''), store_info.STORE_CD, ''),
        COALESCE(NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN store_info.STORE_NM_ENG WHEN 'KOR' THEN store_info.STORE_NM_KOR WHEN 'CHN' THEN store_info.STORE_NM_CHINA ELSE store_info.STORE_NM_VIET END), ''), io.STORE_CD, ''),
        COALESCE(NULLIF(TRIM(unit_info.UNIT_NM), ''), io.UNIT_CD, ''),
        NULLIF(io.UNIT_PRICE_CC, 0),
        0,
        0,
        IFNULL(io.QUANTITY, 0),
        CASE WHEN io.CHIT_TYPE = 'IO' THEN IFNULL(io.AMOUNT_CC, 0)
            WHEN IFNULL(io.AMOUNT_CC, 0) <> 0 THEN IFNULL(io.AMOUNT_CC, 0)
            ELSE IFNULL(io.QUANTITY, 0) * IFNULL(io.UNIT_PRICE_CC, 0) END,
        IFNULL(io.SORT, 0)
    FROM chit_inventory_output io
    LEFT JOIN chit_inventory_info h
        ON h.COMPANY_CD = io.COMPANY_CD
        AND h.INVENTORY_ID = io.INVENTORY_ID
        AND IFNULL(h.ISDEL, '0') = '0'
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = io.COMPANY_CD
        AND ((io.CHIT_TYPE = 'IO' AND d.CHIT_ID = h.CHIT_ID_COGS
                AND ((h.CHITDETAIL_ID_COGS IS NOT NULL AND d.CHITDETAIL_ID = h.CHITDETAIL_ID_COGS)
                    OR (h.CHITDETAIL_ID_COGS IS NULL AND io.CHITDETAIL_ID_COGS IS NOT NULL AND d.CHITDETAIL_ID = io.CHITDETAIL_ID_COGS)
                    OR (h.CHITDETAIL_ID_COGS IS NULL AND io.CHITDETAIL_ID_COGS IS NULL AND d.SORT = 1)))
            OR (io.CHIT_TYPE <> 'IO' AND d.CHITDETAIL_ID = io.CHITDETAIL_ID))
        AND IFNULL(d.ISDEL, '0') = '0'
    LEFT JOIN product_info product
        ON product.COMPANY_CD = io.COMPANY_CD
        AND product.PRODUCT_ID = io.PRODUCT_ID
        AND IFNULL(product.ISDEL, '0') = '0'
    LEFT JOIN store_info
        ON store_info.COMPANY_CD = io.COMPANY_CD
        AND store_info.STORE_ID = io.STORE_ID
        AND IFNULL(store_info.ISDEL, '0') = '0'
    LEFT JOIN product_unit unit_info
        ON unit_info.COMPANY_CD = io.COMPANY_CD
        AND unit_info.UNIT_ID = io.UNIT_ID
        AND IFNULL(unit_info.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo detail_desc
        ON detail_desc.COMPANY_CD = d.COMPANY_CD
        AND detail_desc.CHITDETAIL_ID = d.CHITDETAIL_ID
        AND detail_desc.LANG_TYPE = v_language
        AND IFNULL(detail_desc.ISDEL, '0') = '0'
    WHERE io.COMPANY_CD = p_COMPANY_CD
        AND IFNULL(io.ISDEL, '0') = '0'
        AND IFNULL(d.CREDIT, '') LIKE CONCAT(v_account_cd, '%')
        AND COALESCE(DATE_FORMAT(io.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(h.INVENTORY_YMD), '')) IS NOT NULL;

    SELECT
        IFNULL(SUM(INPUT_QUANTITY - OUTPUT_QUANTITY), 0),
        IFNULL(SUM(INPUT_AMOUNT - OUTPUT_AMOUNT), 0)
    INTO
        v_opening_quantity,
        v_opening_amount
    FROM tmp_inventory_detail_base
    WHERE TXN_YMD < DATE_FORMAT(p_FROM_DATE, '%Y%m%d');

    SELECT
        IFNULL(SUM(INPUT_QUANTITY), 0),
        IFNULL(SUM(INPUT_AMOUNT), 0),
        IFNULL(SUM(OUTPUT_QUANTITY), 0),
        IFNULL(SUM(OUTPUT_AMOUNT), 0)
    INTO
        v_total_input_quantity,
        v_total_input_amount,
        v_total_output_quantity,
        v_total_output_amount
    FROM tmp_inventory_detail_base
    WHERE TXN_YMD BETWEEN DATE_FORMAT(p_FROM_DATE, '%Y%m%d') AND DATE_FORMAT(p_TO_DATE, '%Y%m%d');

    SELECT CASE
            WHEN COUNT(DISTINCT NULLIF(TRIM(STORE_NAME), '')) = 1 THEN MAX(NULLIF(TRIM(STORE_NAME), ''))
            ELSE ''
            END
    INTO v_store_name
    FROM tmp_inventory_detail_base
    WHERE TXN_YMD BETWEEN DATE_FORMAT(p_FROM_DATE, '%Y%m%d') AND DATE_FORMAT(p_TO_DATE, '%Y%m%d');

    DROP TEMPORARY TABLE IF EXISTS tmp_inventory_detail_source;
    CREATE TEMPORARY TABLE tmp_inventory_detail_source
    (
        LINE_SORT INT NOT NULL AUTO_INCREMENT,
        FLOW_TYPE VARCHAR(10) NOT NULL DEFAULT '',
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        CHIT_ID BIGINT NULL,
        CHITDETAIL_ID BIGINT NULL,
        INVENTORY_ID BIGINT NOT NULL DEFAULT 0,
        DOCUMENT_NO VARCHAR(50) NOT NULL DEFAULT '',
        TXN_YMD VARCHAR(8) NOT NULL DEFAULT '',
        DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
        COUNTERPART_ACCOUNT VARCHAR(20) NOT NULL DEFAULT '',
        UNIT_PRICE DECIMAL(18,4) NULL,
        INPUT_QUANTITY DECIMAL(18,4) NOT NULL DEFAULT 0.0000,
        INPUT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        OUTPUT_QUANTITY DECIMAL(18,4) NOT NULL DEFAULT 0.0000,
        OUTPUT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (LINE_SORT)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

    INSERT INTO tmp_inventory_detail_source
    (
        FLOW_TYPE,
        COMPANY_CD,
        CHIT_ID,
        CHITDETAIL_ID,
        INVENTORY_ID,
        DOCUMENT_NO,
        TXN_YMD,
        DESCRIPTION,
        COUNTERPART_ACCOUNT,
        UNIT_PRICE,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT
    )
    SELECT
        FLOW_TYPE,
        COMPANY_CD,
        CHIT_ID,
        CHITDETAIL_ID,
        INVENTORY_ID,
        DOCUMENT_NO,
        TXN_YMD,
        DESCRIPTION,
        COUNTERPART_ACCOUNT,
        UNIT_PRICE,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT
    FROM tmp_inventory_detail_base
    WHERE TXN_YMD BETWEEN DATE_FORMAT(p_FROM_DATE, '%Y%m%d') AND DATE_FORMAT(p_TO_DATE, '%Y%m%d')
    ORDER BY TXN_YMD, DOCUMENT_NO, CHIT_ID, SORT_NO, INVENTORY_ID, FLOW_TYPE;

    DROP TEMPORARY TABLE IF EXISTS tmp_inventory_detail_report;
    CREATE TEMPORARY TABLE tmp_inventory_detail_report
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        ROW_KEY VARCHAR(50) NOT NULL DEFAULT '',
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        ROW_TYPE VARCHAR(20) NOT NULL DEFAULT '',
        ENTRY_DATE DATE NULL,
        DOCUMENT_NO VARCHAR(50) NOT NULL DEFAULT '',
        DOCUMENT_DATE DATE NULL,
        DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
        COUNTERPART_ACCOUNT VARCHAR(20) NOT NULL DEFAULT '',
        UNIT_PRICE DECIMAL(18,4) NULL,
        INPUT_QUANTITY DECIMAL(18,4) NULL,
        INPUT_AMOUNT DECIMAL(18,2) NULL,
        OUTPUT_QUANTITY DECIMAL(18,4) NULL,
        OUTPUT_AMOUNT DECIMAL(18,2) NULL,
        BALANCE_QUANTITY DECIMAL(18,4) NULL,
        BALANCE_AMOUNT DECIMAL(18,2) NULL,
        NOTE VARCHAR(255) NOT NULL DEFAULT '',
        REPORT_YEAR_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        ACCOUNT_STORE_TEXT VARCHAR(500) NOT NULL DEFAULT '',
        PRODUCT_TITLE_TEXT VARCHAR(500) NOT NULL DEFAULT '',
        AMOUNT_UNIT_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ROW_NO)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

    INSERT INTO tmp_inventory_detail_report
    (
        ROW_KEY,
        COMPANY_CD,
        ROW_TYPE,
        ENTRY_DATE,
        DOCUMENT_NO,
        DOCUMENT_DATE,
        DESCRIPTION,
        COUNTERPART_ACCOUNT,
        UNIT_PRICE,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        BALANCE_QUANTITY,
        BALANCE_AMOUNT,
        NOTE,
        REPORT_YEAR_TEXT,
        ACCOUNT_STORE_TEXT,
        PRODUCT_TITLE_TEXT,
        AMOUNT_UNIT_TEXT
    )
    VALUES
    (
        'OPENING',
        p_COMPANY_CD,
        'OPENING',
        NULL,
        '',
        NULL,
        CASE v_language WHEN 'ENG' THEN 'Opening balance' WHEN 'KOR' THEN '기초 잔액' WHEN 'CHN' THEN '期初余额' ELSE 'Số dư đầu kỳ' END,
        '',
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        v_opening_quantity,
        v_opening_amount,
        '',
        CONCAT(CASE v_language WHEN 'ENG' THEN 'Year ' WHEN 'KOR' THEN '연도 ' WHEN 'CHN' THEN '年度 ' ELSE 'Năm ' END, YEAR(p_TO_DATE)),
        CONCAT(CASE v_language WHEN 'ENG' THEN 'Account: ' WHEN 'KOR' THEN '계정: ' WHEN 'CHN' THEN '科目: ' ELSE 'Tài khoản: ' END, v_account_cd, IF(v_account_name = '', '', CONCAT(' - ', v_account_name)), '    ', CASE v_language WHEN 'ENG' THEN 'Store name: ' WHEN 'KOR' THEN '창고명: ' WHEN 'CHN' THEN '仓库名称: ' ELSE 'Tên kho: ' END, IFNULL(NULLIF(v_store_name, ''), '........')),
        CASE v_language WHEN 'ENG' THEN 'Name and specifications of raw materials, materials, tools, instruments (products, goods)' WHEN 'KOR' THEN '원재료, 재료, 공구, 기구(제품, 상품)의 명칭 및 규격' WHEN 'CHN' THEN '原材料、材料、工具、器具（产品、商品）的名称及规格' ELSE 'Tên, quy cách nguyên liệu, vật liệu, công cụ, dụng cụ (sản phẩm, hàng hóa)' END,
        CASE v_language WHEN 'ENG' THEN 'Unit: ............' WHEN 'KOR' THEN '단위: ............' WHEN 'CHN' THEN '单位: ............' ELSE 'Đơn vị tính: ............' END
    );

    SET @running_quantity = v_opening_quantity;
    SET @running_amount = v_opening_amount;

    INSERT INTO tmp_inventory_detail_report
    (
        ROW_KEY,
        COMPANY_CD,
        ROW_TYPE,
        ENTRY_DATE,
        DOCUMENT_NO,
        DOCUMENT_DATE,
        DESCRIPTION,
        COUNTERPART_ACCOUNT,
        UNIT_PRICE,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        BALANCE_QUANTITY,
        BALANCE_AMOUNT,
        NOTE,
        REPORT_YEAR_TEXT,
        ACCOUNT_STORE_TEXT,
        PRODUCT_TITLE_TEXT,
        AMOUNT_UNIT_TEXT
    )
    SELECT
        CONCAT('LINE-', source.LINE_SORT),
        source.COMPANY_CD,
        source.FLOW_TYPE,
        STR_TO_DATE(NULLIF(source.TXN_YMD, ''), '%Y%m%d'),
        source.DOCUMENT_NO,
        STR_TO_DATE(NULLIF(source.TXN_YMD, ''), '%Y%m%d'),
        source.DESCRIPTION,
        source.COUNTERPART_ACCOUNT,
        source.UNIT_PRICE,
        NULLIF(source.INPUT_QUANTITY, 0),
        NULLIF(source.INPUT_AMOUNT, 0),
        NULLIF(source.OUTPUT_QUANTITY, 0),
        NULLIF(source.OUTPUT_AMOUNT, 0),
        @running_quantity := @running_quantity + source.INPUT_QUANTITY - source.OUTPUT_QUANTITY,
        @running_amount := @running_amount + source.INPUT_AMOUNT - source.OUTPUT_AMOUNT,
        '',
        CONCAT(CASE v_language WHEN 'ENG' THEN 'Year ' WHEN 'KOR' THEN '연도 ' WHEN 'CHN' THEN '年度 ' ELSE 'Năm ' END, YEAR(p_TO_DATE)),
        CONCAT(CASE v_language WHEN 'ENG' THEN 'Account: ' WHEN 'KOR' THEN '계정: ' WHEN 'CHN' THEN '科目: ' ELSE 'Tài khoản: ' END, v_account_cd, IF(v_account_name = '', '', CONCAT(' - ', v_account_name)), '    ', CASE v_language WHEN 'ENG' THEN 'Store name: ' WHEN 'KOR' THEN '창고명: ' WHEN 'CHN' THEN '仓库名称: ' ELSE 'Tên kho: ' END, IFNULL(NULLIF(v_store_name, ''), '........')),
        CASE v_language WHEN 'ENG' THEN 'Name and specifications of raw materials, materials, tools, instruments (products, goods)' WHEN 'KOR' THEN '원재료, 재료, 공구, 기구(제품, 상품)의 명칭 및 규격' WHEN 'CHN' THEN '原材料、材料、工具、器具（产品、商品）的名称及规格' ELSE 'Tên, quy cách nguyên liệu, vật liệu, công cụ, dụng cụ (sản phẩm, hàng hóa)' END,
        CASE v_language WHEN 'ENG' THEN 'Unit: ............' WHEN 'KOR' THEN '단위: ............' WHEN 'CHN' THEN '单位: ............' ELSE 'Đơn vị tính: ............' END
    FROM tmp_inventory_detail_source source
    ORDER BY source.LINE_SORT;

    INSERT INTO tmp_inventory_detail_report
    (
        ROW_KEY,
        COMPANY_CD,
        ROW_TYPE,
        ENTRY_DATE,
        DOCUMENT_NO,
        DOCUMENT_DATE,
        DESCRIPTION,
        COUNTERPART_ACCOUNT,
        UNIT_PRICE,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        BALANCE_QUANTITY,
        BALANCE_AMOUNT,
        NOTE,
        REPORT_YEAR_TEXT,
        ACCOUNT_STORE_TEXT,
        PRODUCT_TITLE_TEXT,
        AMOUNT_UNIT_TEXT
    )
    VALUES
    (
        'TOTAL',
        p_COMPANY_CD,
        'TOTAL',
        NULL,
        '',
        NULL,
        CASE v_language WHEN 'ENG' THEN 'Total' WHEN 'KOR' THEN '월계' WHEN 'CHN' THEN '本月合计' ELSE 'Tổng cộng' END,
        'x',
        NULL,
        v_total_input_quantity,
        v_total_input_amount,
        v_total_output_quantity,
        v_total_output_amount,
        v_opening_quantity + v_total_input_quantity - v_total_output_quantity,
        v_opening_amount + v_total_input_amount - v_total_output_amount,
        '',
        CONCAT(CASE v_language WHEN 'ENG' THEN 'Year ' WHEN 'KOR' THEN '연도 ' WHEN 'CHN' THEN '年度 ' ELSE 'Năm ' END, YEAR(p_TO_DATE)),
        CONCAT(CASE v_language WHEN 'ENG' THEN 'Account: ' WHEN 'KOR' THEN '계정: ' WHEN 'CHN' THEN '科目: ' ELSE 'Tài khoản: ' END, v_account_cd, IF(v_account_name = '', '', CONCAT(' - ', v_account_name)), '    ', CASE v_language WHEN 'ENG' THEN 'Store name: ' WHEN 'KOR' THEN '창고명: ' WHEN 'CHN' THEN '仓库名称: ' ELSE 'Tên kho: ' END, IFNULL(NULLIF(v_store_name, ''), '........')),
        CASE v_language WHEN 'ENG' THEN 'Name and specifications of raw materials, materials, tools, instruments (products, goods)' WHEN 'KOR' THEN '원재료, 재료, 공구, 기구(제품, 상품)의 명칭 및 규격' WHEN 'CHN' THEN '原材料、材料、工具、器具（产品、商品）的名称及规格' ELSE 'Tên, quy cách nguyên liệu, vật liệu, công cụ, dụng cụ (sản phẩm, hàng hóa)' END,
        CASE v_language WHEN 'ENG' THEN 'Unit: ............' WHEN 'KOR' THEN '단위: ............' WHEN 'CHN' THEN '单位: ............' ELSE 'Đơn vị tính: ............' END
    );

    SELECT
        ROW_KEY AS __ROW_KEY,
        COMPANY_CD AS __COMPANY_CD,
        ROW_TYPE AS __ROW_TYPE,
        ENTRY_DATE,
        DOCUMENT_NO,
        DOCUMENT_DATE,
        DESCRIPTION,
        COUNTERPART_ACCOUNT,
        UNIT_PRICE,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        BALANCE_QUANTITY,
        BALANCE_AMOUNT,
        NOTE,
        REPORT_YEAR_TEXT AS __REPORT_YEAR_TEXT,
        ACCOUNT_STORE_TEXT,
        PRODUCT_TITLE_TEXT,
        AMOUNT_UNIT_TEXT AS __AMOUNT_UNIT_TEXT
    FROM tmp_inventory_detail_report
    ORDER BY ROW_NO;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_inventory_issue_voucher
DROP PROCEDURE IF EXISTS `rpt_inventory_issue_voucher`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_inventory_issue_voucher`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHIT_ID BIGINT,
    IN p_CHIT_IDS TEXT,
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_chit_ids TEXT;
    DECLARE v_language VARCHAR(20);
    DECLARE v_TOTAL VARCHAR(100); -- TỔNG

    SET v_chit_ids = REPLACE(REPLACE(REPLACE(REPLACE(IFNULL(TRIM(p_CHIT_IDS), ''), '|', ','), ';', ','), CHAR(10), ','), CHAR(13), ',');
    SET v_chit_ids = IF(v_chit_ids = '' AND IFNULL(p_CHIT_ID, 0) > 0, CAST(p_CHIT_ID AS CHAR), v_chit_ids);
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));
	 
	 -- TỔNG
	 select (CASE
                WHEN v_language = 'ENG' THEN p.ENG
                WHEN v_language = 'KOR' THEN p.KOR                
                ELSE p.VIET
            END) INTO v_TOTAL
	 from am_web_manager.t_message_info P where `key` like 'ALL_TOTAL';
	 
    SELECT
        h.INVENTORY_ID AS CHIT_ID,
        h.COMPANY_CD,
        h.INVENTORY_CD AS CHIT_CD,
        h.INVENTORY_NO AS CHIT_NO,
        h.INVENTORY_YMD AS CHIT_YMD,
        h.INVENTORY_YMD AS HEADER_DATE_TEXT,
        h.INVENTORY_YMD AS SIGNATURE_DATE_TEXT,
        '' AS PARTNER_NAME,
        '' AS PARTNER_ADDRESS,
        IFNULL(h.REMARK, '') AS REASON,
        IFNULL(h.REMARK, '') AS SOURCE_DOCUMENT_TEXT,
        IFNULL(summary.WAREHOUSE_NAME, '') AS WAREHOUSE_NAME,
        '' AS WAREHOUSE_LOCATION,
        IFNULL(h.AMOUNT, IFNULL(summary.TOTAL_AMOUNT, 0)) AS AMOUNT,
        NULL AS AMOUNT_TEXT,
        NULL AS AMOUNT_IN_WORDS,
        NULL AS FC_AMOUNT,
        NULL AS FC_TYPE,
        NULL AS FC_RATE,
        NULL AS EXCHANGE_RATE_TEXT,
        NULL AS CONVERTED_AMOUNT_TEXT,
        '' AS DEBIT_ACCOUNT,
        '' AS CREDIT_ACCOUNT,
        IFNULL(summary.LINE_COUNT, 0) AS DETAIL_COUNT,
        NULL AS ATTACHMENT_TEXT,
        NULL AS REFERENCE_TEXT,
        IFNULL(h.REMARK, '') AS NOTE,
        NULL AS NOTE_TEXT,
        COALESCE(NULLIF(TRIM(h.UPDATE_BY), ''), NULLIF(TRIM(h.CREATE_BY), ''), '') AS CREATED_BY,
        detail.LINE_SORT,
        detail.LINE_NO,
        detail.PRODUCT_NAME,
        detail.PRODUCT_CD,
        detail.UNIT_NAME,
        detail.REQUEST_QUANTITY,
        detail.ACTUAL_QUANTITY,
        detail.UNIT_PRICE,
        detail.LINE_AMOUNT
    FROM chit_inventory_info h
    LEFT JOIN (
        SELECT
            io.INVENTORY_ID AS CHIT_ID,
            COUNT(*) AS LINE_COUNT,
            SUM(CASE WHEN IFNULL(io.AMOUNT_CC, 0) <> 0 THEN io.AMOUNT_CC ELSE IFNULL(io.QUANTITY, 0) * IFNULL(io.UNIT_PRICE_CC, 0) END) AS TOTAL_AMOUNT,
            SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(COALESCE(store_info.STORE_NM_VIET, io.STORE_CD)), '') ORDER BY IFNULL(io.SORT, 0), io.OUTPUT_ID SEPARATOR '\n'), '\n', 1) AS WAREHOUSE_NAME
        FROM chit_inventory_output io
        LEFT JOIN store_info ON store_info.COMPANY_CD = io.COMPANY_CD AND store_info.STORE_ID = io.STORE_ID AND IFNULL(store_info.ISDEL, '0') = '0'
        WHERE io.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(io.ISDEL, '0') = '0'
        GROUP BY io.INVENTORY_ID
    ) summary ON summary.CHIT_ID = h.INVENTORY_ID
    INNER JOIN (
        SELECT
            line.CHIT_ID,
            line.LINE_SORT,
            CAST(line.LINE_SORT AS CHAR) AS LINE_NO,
            COALESCE(NULLIF(line.PRODUCT_NAME, ''), line.PRODUCT_CD, '') AS PRODUCT_NAME,
            line.PRODUCT_CD,
            COALESCE(NULLIF(line.UNIT_NAME, ''), line.UNIT_CD, '') AS UNIT_NAME,
            line.QUANTITY AS REQUEST_QUANTITY,
            line.QUANTITY AS ACTUAL_QUANTITY,
            line.UNIT_PRICE,
            line.LINE_AMOUNT
        FROM (
            SELECT
                io.OUTPUT_ID,
                io.INVENTORY_ID AS CHIT_ID,
                io.PRODUCT_CD,
                CASE v_language WHEN 'ENG' THEN product.PRODUCT_NM_ENG WHEN 'KOR' THEN product.PRODUCT_NM_KOR WHEN 'CHINA' THEN product.PRODUCT_NM_CHINA ELSE product.PRODUCT_NM_VIET END AS PRODUCT_NAME,
                io.UNIT_CD,
                unit_info.UNIT_NM AS UNIT_NAME,
                io.QUANTITY,
                io.UNIT_PRICE_CC AS UNIT_PRICE,
                CASE WHEN IFNULL(io.AMOUNT_CC, 0) <> 0 THEN io.AMOUNT_CC ELSE IFNULL(io.QUANTITY, 0) * IFNULL(io.UNIT_PRICE_CC, 0) END AS LINE_AMOUNT,
                (
                    SELECT COUNT(*)
                    FROM chit_inventory_output x
                    WHERE x.COMPANY_CD = io.COMPANY_CD
                      AND x.INVENTORY_ID = io.INVENTORY_ID
                      AND IFNULL(x.ISDEL, '0') = '0'
                      AND (IFNULL(x.SORT, 0) < IFNULL(io.SORT, 0) OR (IFNULL(x.SORT, 0) = IFNULL(io.SORT, 0) AND x.OUTPUT_ID <= io.OUTPUT_ID))
                ) AS LINE_SORT
            FROM chit_inventory_output io
            LEFT JOIN product_info product ON product.COMPANY_CD = io.COMPANY_CD AND product.PRODUCT_ID = io.PRODUCT_ID AND IFNULL(product.ISDEL, '0') = '0'
            LEFT JOIN product_unit unit_info ON unit_info.COMPANY_CD = io.COMPANY_CD AND unit_info.UNIT_ID = io.UNIT_ID AND IFNULL(unit_info.ISDEL, '0') = '0'
            WHERE io.COMPANY_CD = p_COMPANY_CD
              AND IFNULL(io.ISDEL, '0') = '0'
        ) line
        UNION ALL
/*
        SELECT
            h.INVENTORY_ID AS CHIT_ID,
            nums.N,
            '',
            '',
            '',
            '',
            NULL,
            NULL,
            NULL,
            NULL
        FROM chit_inventory_info h
        INNER JOIN (SELECT 1 AS N UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5) nums
        LEFT JOIN (
            SELECT io.INVENTORY_ID AS CHIT_ID, COUNT(*) AS LINE_COUNT
            FROM chit_inventory_output io
            WHERE io.COMPANY_CD = p_COMPANY_CD
              AND IFNULL(io.ISDEL, '0') = '0'
            GROUP BY io.INVENTORY_ID
        ) line_summary ON line_summary.CHIT_ID = h.INVENTORY_ID
        WHERE h.COMPANY_CD = p_COMPANY_CD
          AND h.INPUT_TYPE = 'AR'
          AND h.CHIT_TYPE = 'IO'
          AND IFNULL(h.ISDEL, '0') = '0'
          AND v_chit_ids <> ''
          AND FIND_IN_SET(CAST(h.INVENTORY_ID AS CHAR) COLLATE utf8_unicode_ci, v_chit_ids COLLATE utf8_unicode_ci) > 0
          AND nums.N > IFNULL(line_summary.LINE_COUNT, 0)
        UNION ALL
*/
        SELECT
            h.INVENTORY_ID AS CHIT_ID,
            999999,
            v_TOTAL COLLATE utf8_unicode_ci, -- 'Tổng',
            '',
            '',
            '',
            IFNULL(SUM(IFNULL(io.QUANTITY, 0)), 0),
            IFNULL(SUM(IFNULL(io.QUANTITY, 0)), 0),
            NULL,
            IFNULL(SUM(CASE WHEN IFNULL(io.AMOUNT_CC, 0) <> 0 THEN io.AMOUNT_CC ELSE IFNULL(io.QUANTITY, 0) * IFNULL(io.UNIT_PRICE_CC, 0) END), 0)
        FROM chit_inventory_info h
        LEFT JOIN chit_inventory_output io ON io.COMPANY_CD = h.COMPANY_CD AND io.INVENTORY_ID = h.INVENTORY_ID AND IFNULL(io.ISDEL, '0') = '0'
        WHERE h.COMPANY_CD = p_COMPANY_CD
          AND h.INPUT_TYPE = 'AR'
          AND h.CHIT_TYPE = 'IO'
          AND IFNULL(h.ISDEL, '0') = '0'
          AND v_chit_ids <> ''
          AND FIND_IN_SET(CAST(h.INVENTORY_ID AS CHAR) COLLATE utf8_unicode_ci, v_chit_ids COLLATE utf8_unicode_ci) > 0
        GROUP BY h.INVENTORY_ID
    ) detail ON detail.CHIT_ID = h.INVENTORY_ID
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'AR'
      AND h.CHIT_TYPE = 'IO'
      AND IFNULL(h.ISDEL, '0') = '0'
      AND v_chit_ids <> ''
      AND FIND_IN_SET(CAST(h.INVENTORY_ID AS CHAR) COLLATE utf8_unicode_ci, v_chit_ids COLLATE utf8_unicode_ci) > 0
    ORDER BY h.INVENTORY_YMD, h.INVENTORY_ID, detail.LINE_SORT;

    SELECT 'LINE_NO' AS COLUMN_KEY, NULL AS PARENT_KEY, 'LINE_NO' AS FIELD_NAME, 'STT' AS CAPTION, 0 AS ROW_INDEX, 0 AS COL_INDEX, 1 AS COL_SPAN, 2 AS ROW_SPAN, 0.70 AS WIDTH, 'CENTER' AS ALIGN, 'TEXT' AS FORMAT_TYPE, 10 AS SORT_ORDER
    UNION ALL SELECT 'PRODUCT_NAME', NULL, 'PRODUCT_NAME', 'Tên, nhãn hiệu, quy cách, phẩm chất vật tư, dụng cụ, sản phẩm, hàng hóa', 0, 1, 1, 2, 3.10, 'LEFT', 'TEXT', 20
    UNION ALL SELECT 'PRODUCT_CD', NULL, 'PRODUCT_CD', 'Mã số', 0, 2, 1, 2, 0.80, 'CENTER', 'TEXT', 30
    UNION ALL SELECT 'UNIT_NAME', NULL, 'UNIT_NAME', 'Đơn vị tính', 0, 3, 1, 2, 0.80, 'CENTER', 'TEXT', 40
    UNION ALL SELECT 'QUANTITY_GROUP', NULL, NULL, 'Số lượng', 0, 4, 2, 1, 2.00, 'CENTER', 'TEXT', 50
    UNION ALL SELECT 'REQUEST_QUANTITY', 'QUANTITY_GROUP', 'REQUEST_QUANTITY', 'Yêu cầu', 1, 4, 1, 1, 1.00, 'RIGHT', 'NUMBER2', 60
    UNION ALL SELECT 'ACTUAL_QUANTITY', 'QUANTITY_GROUP', 'ACTUAL_QUANTITY', 'Thực xuất', 1, 5, 1, 1, 1.00, 'RIGHT', 'NUMBER2', 70
    UNION ALL SELECT 'UNIT_PRICE', NULL, 'UNIT_PRICE', 'Đơn giá', 0, 6, 1, 2, 1.10, 'RIGHT', 'NUMBER2', 80
    UNION ALL SELECT 'LINE_AMOUNT', NULL, 'LINE_AMOUNT', 'Thành tiền', 0, 7, 1, 2, 1.20, 'RIGHT', 'NUMBER2', 90;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_inventory_opening_info
DROP PROCEDURE IF EXISTS `rpt_inventory_opening_info`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_inventory_opening_info`(
    IN `p_COMPANY_CD` VARCHAR(20),
    IN `p_INPUT_ID` BIGINT,
    IN `p_LANGUAGE` VARCHAR(20)
)
BEGIN
    SET @rownum := 0;

    SELECT
        (@rownum := @rownum + 1) AS ROW_NO,
        i.INPUT_ID,
        i.INPUT_CD,
        i.INVENTORY_ID AS TRANSFER_ID,
        IFNULL(i.INVENTORY_CD, '') AS TRANSFER_CD,
        t.INVENTORY_NO AS TRANSFER_NO,
        t.INVENTORY_YMD AS TRANSFER_YMD,
        i.COMPANY_CD,
        i.PRODUCT_ID,
        IFNULL(i.PRODUCT_CD, '') AS PRODUCT_CD,
        IFNULL(p.PRODUCT_NM_VIET, '') AS PRODUCT_NM_VIET,
        IFNULL(p.PRODUCT_NM_ENG, '') AS PRODUCT_NM_ENG,
        IFNULL(p.PRODUCT_NM_KOR, '') AS PRODUCT_NM_KOR,
        IFNULL(p.PRODUCT_NM_CHINA, '') AS PRODUCT_NM_CHINA,
        i.STORE_ID,
        IFNULL(i.STORE_CD, '') AS STORE_CD,
        IFNULL(s.STORE_NM_VIET, '') AS STORE_NM_VIET,
        IFNULL(s.STORE_NM_ENG, '') AS STORE_NM_ENG,
        IFNULL(s.STORE_NM_KOR, '') AS STORE_NM_KOR,
        IFNULL(s.STORE_NM_CHINA, '') AS STORE_NM_CHINA,
        i.UNIT_ID,
        IFNULL(i.UNIT_CD, '') AS UNIT_CD,
        IFNULL(u.UNIT_NM, '') AS UNIT_NM,
        i.QUANTITY,
        i.UNIT_PRICE_CC,
        i.AMOUNT_CC,
        i.SUMMARY,
        DATE_FORMAT(i.INVENTORY_YMD, '%Y%m%d') AS INVENTORY_YMD,
        IFNULL(i.STATE, '0') AS STATE,
        IFNULL(i.SORT, 0) AS SORT
    FROM chit_inventory_input i
    INNER JOIN chit_inventory_info t
        ON t.COMPANY_CD = i.COMPANY_CD
       AND t.INVENTORY_ID = i.INVENTORY_ID
       AND IFNULL(t.ISDEL, '0') = '0'
       AND t.CHIT_TYPE = 'IRO'
       AND t.INPUT_TYPE = 'INV'
    LEFT JOIN product_info p
        ON p.COMPANY_CD = i.COMPANY_CD
       AND p.PRODUCT_ID = i.PRODUCT_ID
       AND IFNULL(p.ISDEL, '0') = '0'
    LEFT JOIN store_info s
        ON s.COMPANY_CD = i.COMPANY_CD
       AND s.STORE_ID = i.STORE_ID
       AND IFNULL(s.ISDEL, '0') = '0'
    LEFT JOIN product_unit u
        ON u.COMPANY_CD = i.COMPANY_CD
       AND u.UNIT_ID = i.UNIT_ID
       AND IFNULL(u.ISDEL, '0') = '0'
    WHERE i.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(i.ISDEL, '0') = '0'
      AND i.CHIT_TYPE = 'IRO'
      AND (p_INPUT_ID IS NULL OR p_INPUT_ID = 0 OR i.INPUT_ID = p_INPUT_ID)
    ORDER BY i.INPUT_ID DESC;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_inventory_quantity_report
DROP PROCEDURE IF EXISTS `rpt_inventory_quantity_report`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_inventory_quantity_report`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_PRODUCT_CD TEXT,
    IN p_STORE_CD TEXT,
    IN p_REPORT_OPTION_CODE VARCHAR(100),
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_product_cd TEXT;
    DECLARE v_store_cd TEXT;
    DECLARE v_group_option VARCHAR(100);
    DECLARE v_language VARCHAR(20);
    DECLARE v_period_text VARCHAR(100);

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;

    SET v_from_ymd = DATE_FORMAT(p_FROM_DATE, '%Y%m%d');
    SET v_to_ymd = DATE_FORMAT(p_TO_DATE, '%Y%m%d');
    SET v_product_cd = REPLACE(IFNULL(TRIM(p_PRODUCT_CD), ''), '|', ',');
    SET v_store_cd = REPLACE(IFNULL(TRIM(p_STORE_CD), ''), '|', ',');
    SET v_group_option = UPPER(TRIM(IFNULL(p_REPORT_OPTION_CODE, '')));
    SET v_group_option = CASE
        WHEN v_group_option IN ('PRODUCT_KIND_PRODUCT_STORE', 'STORE_KIND_STORE_PRODUCT', 'STORE_PRODUCT', 'PRODUCT_STORE') THEN v_group_option
        ELSE 'STORE_PRODUCT_KIND_PRODUCT'
    END;
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));
    SET v_period_text = CONCAT(DATE_FORMAT(p_FROM_DATE, '%d/%m/%Y'), '~', DATE_FORMAT(p_TO_DATE, '%d/%m/%Y'));

    DROP TEMPORARY TABLE IF EXISTS tmp_inventory_quantity_movement;
    CREATE TEMPORARY TABLE tmp_inventory_quantity_movement
    (
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        TXN_YMD VARCHAR(8) NOT NULL DEFAULT '',
        STORE_KIND_CD VARCHAR(50) NOT NULL DEFAULT '',
        STORE_KIND_NAME VARCHAR(255) NOT NULL DEFAULT '',
        STORE_CD VARCHAR(50) NOT NULL DEFAULT '',
        STORE_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRODUCT_KIND_CD VARCHAR(50) NOT NULL DEFAULT '',
        PRODUCT_KIND_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRODUCT_CD VARCHAR(50) NOT NULL DEFAULT '',
        PRODUCT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        UNIT_NAME VARCHAR(100) NOT NULL DEFAULT '',
        INPUT_QUANTITY DECIMAL(18,4) NOT NULL DEFAULT 0.0000,
        INPUT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        OUTPUT_QUANTITY DECIMAL(18,4) NOT NULL DEFAULT 0.0000,
        OUTPUT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        KEY IDX_TMP_INV_QTY_01 (COMPANY_CD, TXN_YMD),
        KEY IDX_TMP_INV_QTY_02 (STORE_KIND_CD, STORE_CD, PRODUCT_KIND_CD, PRODUCT_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_inventory_quantity_movement
    (
        COMPANY_CD,
        TXN_YMD,
        STORE_KIND_CD,
        STORE_KIND_NAME,
        STORE_CD,
        STORE_NAME,
        PRODUCT_KIND_CD,
        PRODUCT_KIND_NAME,
        PRODUCT_CD,
        PRODUCT_NAME,
        UNIT_NAME,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT
    )
    SELECT
        ii.COMPANY_CD,
        COALESCE(DATE_FORMAT(ii.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(transfer_h.INVENTORY_YMD), '')),
        COALESCE(NULLIF(TRIM(store_kind.STORE_KIND_CD), ''), ''),
        COALESCE(NULLIF(TRIM(CASE v_language
            WHEN 'ENG' THEN store_kind.STORE_KIND_NM_ENG
            WHEN 'KOR' THEN store_kind.STORE_KIND_NM_KOR
            WHEN 'CHN' THEN store_kind.STORE_KIND_NM_CHINA
            ELSE store_kind.STORE_KIND_NM_VIET
        END), ''), ''),
        COALESCE(NULLIF(TRIM(ii.STORE_CD), ''), store_info.STORE_CD, ''),
        COALESCE(NULLIF(TRIM(CASE v_language
            WHEN 'ENG' THEN store_info.STORE_NM_ENG
            WHEN 'KOR' THEN store_info.STORE_NM_KOR
            WHEN 'CHN' THEN store_info.STORE_NM_CHINA
            ELSE store_info.STORE_NM_VIET
        END), ''), ii.STORE_CD, ''),
        COALESCE(NULLIF(TRIM(product_kind.PRODUCT_KIND_CD), ''), ''),
        COALESCE(NULLIF(TRIM(CASE v_language
            WHEN 'ENG' THEN product_kind.PRODUCTKIND_NM_ENG
            WHEN 'KOR' THEN product_kind.PRODUCTKIND_NM_KOR
            WHEN 'CHN' THEN product_kind.PRODUCTKIND_NM_CHINA
            ELSE product_kind.PRODUCTKIND_NM_VIET
        END), ''), ''),
        COALESCE(NULLIF(TRIM(ii.PRODUCT_CD), ''), product.PRODUCT_CD, ''),
        COALESCE(NULLIF(TRIM(CASE v_language
            WHEN 'ENG' THEN product.PRODUCT_NM_ENG
            WHEN 'KOR' THEN product.PRODUCT_NM_KOR
            WHEN 'CHN' THEN product.PRODUCT_NM_CHINA
            ELSE product.PRODUCT_NM_VIET
        END), ''), ii.PRODUCT_CD, ''),
        COALESCE(NULLIF(TRIM(unit_info.UNIT_NM), ''), ii.UNIT_CD, ''),
        IFNULL(ii.QUANTITY, 0),
        CASE
            WHEN IFNULL(ii.AMOUNT_CC, 0) <> 0 THEN IFNULL(ii.AMOUNT_CC, 0)
            ELSE IFNULL(ii.QUANTITY, 0) * IFNULL(ii.UNIT_PRICE_CC, 0)
        END,
        0,
        0
    FROM chit_inventory_input ii
    LEFT JOIN chit_inventory_info transfer_h
        ON transfer_h.COMPANY_CD = ii.COMPANY_CD
       AND transfer_h.INVENTORY_ID = ii.INVENTORY_ID
       AND IFNULL(transfer_h.ISDEL, '0') = '0'
    LEFT JOIN product_info product
        ON product.COMPANY_CD = ii.COMPANY_CD
       AND product.PRODUCT_ID = ii.PRODUCT_ID
       AND IFNULL(product.ISDEL, '0') = '0'
    LEFT JOIN product_kind product_kind
        ON product_kind.COMPANY_CD = product.COMPANY_CD
       AND product_kind.PRODUCT_KIND_ID = product.PRODUCT_KIND_ID
       AND IFNULL(product_kind.ISDEL, '0') = '0'
    LEFT JOIN product_unit unit_info
        ON unit_info.COMPANY_CD = ii.COMPANY_CD
       AND unit_info.UNIT_ID = ii.UNIT_ID
       AND IFNULL(unit_info.ISDEL, '0') = '0'
    LEFT JOIN store_info store_info
        ON store_info.COMPANY_CD = ii.COMPANY_CD
       AND store_info.STORE_ID = ii.STORE_ID
       AND IFNULL(store_info.ISDEL, '0') = '0'
    LEFT JOIN store_kind_info store_kind
        ON store_kind.COMPANY_CD = store_info.COMPANY_CD
       AND store_kind.STORE_KIND_ID = store_info.STORE_KIND_ID
       AND IFNULL(store_kind.ISDEL, '0') = '0'
    WHERE ii.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(ii.ISDEL, '0') = '0'
      AND COALESCE(DATE_FORMAT(ii.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(transfer_h.INVENTORY_YMD), '')) <= v_to_ymd
      AND (v_product_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(ii.PRODUCT_CD), ''), product.PRODUCT_CD, ''), v_product_cd) > 0)
      AND (v_store_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(ii.STORE_CD), ''), store_info.STORE_CD, ''), v_store_cd) > 0);

    INSERT INTO tmp_inventory_quantity_movement
    (
        COMPANY_CD,
        TXN_YMD,
        STORE_KIND_CD,
        STORE_KIND_NAME,
        STORE_CD,
        STORE_NAME,
        PRODUCT_KIND_CD,
        PRODUCT_KIND_NAME,
        PRODUCT_CD,
        PRODUCT_NAME,
        UNIT_NAME,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT
    )
    SELECT
        io.COMPANY_CD,
        COALESCE(DATE_FORMAT(io.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(transfer_h.INVENTORY_YMD), '')),
        COALESCE(NULLIF(TRIM(store_kind.STORE_KIND_CD), ''), ''),
        COALESCE(NULLIF(TRIM(CASE v_language
            WHEN 'ENG' THEN store_kind.STORE_KIND_NM_ENG
            WHEN 'KOR' THEN store_kind.STORE_KIND_NM_KOR
            WHEN 'CHN' THEN store_kind.STORE_KIND_NM_CHINA
            ELSE store_kind.STORE_KIND_NM_VIET
        END), ''), ''),
        COALESCE(NULLIF(TRIM(io.STORE_CD), ''), store_info.STORE_CD, ''),
        COALESCE(NULLIF(TRIM(CASE v_language
            WHEN 'ENG' THEN store_info.STORE_NM_ENG
            WHEN 'KOR' THEN store_info.STORE_NM_KOR
            WHEN 'CHN' THEN store_info.STORE_NM_CHINA
            ELSE store_info.STORE_NM_VIET
        END), ''), io.STORE_CD, ''),
        COALESCE(NULLIF(TRIM(product_kind.PRODUCT_KIND_CD), ''), ''),
        COALESCE(NULLIF(TRIM(CASE v_language
            WHEN 'ENG' THEN product_kind.PRODUCTKIND_NM_ENG
            WHEN 'KOR' THEN product_kind.PRODUCTKIND_NM_KOR
            WHEN 'CHN' THEN product_kind.PRODUCTKIND_NM_CHINA
            ELSE product_kind.PRODUCTKIND_NM_VIET
        END), ''), ''),
        COALESCE(NULLIF(TRIM(io.PRODUCT_CD), ''), product.PRODUCT_CD, ''),
        COALESCE(NULLIF(TRIM(CASE v_language
            WHEN 'ENG' THEN product.PRODUCT_NM_ENG
            WHEN 'KOR' THEN product.PRODUCT_NM_KOR
            WHEN 'CHN' THEN product.PRODUCT_NM_CHINA
            ELSE product.PRODUCT_NM_VIET
        END), ''), io.PRODUCT_CD, ''),
        COALESCE(NULLIF(TRIM(unit_info.UNIT_NM), ''), io.UNIT_CD, ''),
        0,
        0,
        IFNULL(io.QUANTITY, 0),
        CASE
            WHEN IFNULL(io.AMOUNT_CC, 0) <> 0 THEN IFNULL(io.AMOUNT_CC, 0)
            ELSE IFNULL(io.QUANTITY, 0) * IFNULL(io.UNIT_PRICE_CC, 0)
        END
    FROM chit_inventory_output io
    LEFT JOIN chit_inventory_info transfer_h
        ON transfer_h.COMPANY_CD = io.COMPANY_CD
       AND transfer_h.INVENTORY_ID = io.INVENTORY_ID
       AND IFNULL(transfer_h.ISDEL, '0') = '0'
    LEFT JOIN product_info product
        ON product.COMPANY_CD = io.COMPANY_CD
       AND product.PRODUCT_ID = io.PRODUCT_ID
       AND IFNULL(product.ISDEL, '0') = '0'
    LEFT JOIN product_kind product_kind
        ON product_kind.COMPANY_CD = product.COMPANY_CD
       AND product_kind.PRODUCT_KIND_ID = product.PRODUCT_KIND_ID
       AND IFNULL(product_kind.ISDEL, '0') = '0'
    LEFT JOIN product_unit unit_info
        ON unit_info.COMPANY_CD = io.COMPANY_CD
       AND unit_info.UNIT_ID = io.UNIT_ID
       AND IFNULL(unit_info.ISDEL, '0') = '0'
    LEFT JOIN store_info store_info
        ON store_info.COMPANY_CD = io.COMPANY_CD
       AND store_info.STORE_ID = io.STORE_ID
       AND IFNULL(store_info.ISDEL, '0') = '0'
    LEFT JOIN store_kind_info store_kind
        ON store_kind.COMPANY_CD = store_info.COMPANY_CD
       AND store_kind.STORE_KIND_ID = store_info.STORE_KIND_ID
       AND IFNULL(store_kind.ISDEL, '0') = '0'
    WHERE io.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(io.ISDEL, '0') = '0'
      AND COALESCE(DATE_FORMAT(io.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(transfer_h.INVENTORY_YMD), '')) <= v_to_ymd
      AND (v_product_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(io.PRODUCT_CD), ''), product.PRODUCT_CD, ''), v_product_cd) > 0)
      AND (v_store_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(io.STORE_CD), ''), store_info.STORE_CD, ''), v_store_cd) > 0);

    DROP TEMPORARY TABLE IF EXISTS tmp_inventory_quantity_summary;
    CREATE TEMPORARY TABLE tmp_inventory_quantity_summary
    (
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        STORE_KIND_CD VARCHAR(50) NOT NULL DEFAULT '',
        STORE_KIND_NAME VARCHAR(255) NOT NULL DEFAULT '',
        STORE_CD VARCHAR(50) NOT NULL DEFAULT '',
        STORE_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRODUCT_KIND_CD VARCHAR(50) NOT NULL DEFAULT '',
        PRODUCT_KIND_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRODUCT_CD VARCHAR(50) NOT NULL DEFAULT '',
        PRODUCT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        UNIT_NAME VARCHAR(100) NOT NULL DEFAULT '',
        BEGIN_QUANTITY DECIMAL(18,4) NOT NULL DEFAULT 0.0000,
        BEGIN_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        INPUT_QUANTITY DECIMAL(18,4) NOT NULL DEFAULT 0.0000,
        INPUT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        OUTPUT_QUANTITY DECIMAL(18,4) NOT NULL DEFAULT 0.0000,
        OUTPUT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        END_QUANTITY DECIMAL(18,4) NOT NULL DEFAULT 0.0000,
        END_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        KEY IDX_TMP_INV_QTY_SUM_01 (STORE_KIND_CD, STORE_CD, PRODUCT_KIND_CD, PRODUCT_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_inventory_quantity_summary
    (
        COMPANY_CD,
        STORE_KIND_CD,
        STORE_KIND_NAME,
        STORE_CD,
        STORE_NAME,
        PRODUCT_KIND_CD,
        PRODUCT_KIND_NAME,
        PRODUCT_CD,
        PRODUCT_NAME,
        UNIT_NAME,
        BEGIN_QUANTITY,
        BEGIN_AMOUNT,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        END_QUANTITY,
        END_AMOUNT
    )
    SELECT
        COMPANY_CD,
        STORE_KIND_CD,
        STORE_KIND_NAME,
        STORE_CD,
        STORE_NAME,
        PRODUCT_KIND_CD,
        PRODUCT_KIND_NAME,
        PRODUCT_CD,
        PRODUCT_NAME,
        UNIT_NAME,
        SUM(CASE WHEN TXN_YMD < v_from_ymd THEN INPUT_QUANTITY - OUTPUT_QUANTITY ELSE 0 END),
        SUM(CASE WHEN TXN_YMD < v_from_ymd THEN INPUT_AMOUNT - OUTPUT_AMOUNT ELSE 0 END),
        SUM(CASE WHEN TXN_YMD BETWEEN v_from_ymd AND v_to_ymd THEN INPUT_QUANTITY ELSE 0 END),
        SUM(CASE WHEN TXN_YMD BETWEEN v_from_ymd AND v_to_ymd THEN INPUT_AMOUNT ELSE 0 END),
        SUM(CASE WHEN TXN_YMD BETWEEN v_from_ymd AND v_to_ymd THEN OUTPUT_QUANTITY ELSE 0 END),
        SUM(CASE WHEN TXN_YMD BETWEEN v_from_ymd AND v_to_ymd THEN OUTPUT_AMOUNT ELSE 0 END),
        SUM(CASE WHEN TXN_YMD <= v_to_ymd THEN INPUT_QUANTITY - OUTPUT_QUANTITY ELSE 0 END),
        SUM(CASE WHEN TXN_YMD <= v_to_ymd THEN INPUT_AMOUNT - OUTPUT_AMOUNT ELSE 0 END)
    FROM tmp_inventory_quantity_movement
    WHERE TXN_YMD <> ''
    GROUP BY
        COMPANY_CD,
        STORE_KIND_CD,
        STORE_KIND_NAME,
        STORE_CD,
        STORE_NAME,
        PRODUCT_KIND_CD,
        PRODUCT_KIND_NAME,
        PRODUCT_CD,
        PRODUCT_NAME,
        UNIT_NAME
    HAVING
        ABS(SUM(CASE WHEN TXN_YMD < v_from_ymd THEN INPUT_QUANTITY - OUTPUT_QUANTITY ELSE 0 END))
        + ABS(SUM(CASE WHEN TXN_YMD < v_from_ymd THEN INPUT_AMOUNT - OUTPUT_AMOUNT ELSE 0 END))
        + ABS(SUM(CASE WHEN TXN_YMD BETWEEN v_from_ymd AND v_to_ymd THEN INPUT_QUANTITY ELSE 0 END))
        + ABS(SUM(CASE WHEN TXN_YMD BETWEEN v_from_ymd AND v_to_ymd THEN INPUT_AMOUNT ELSE 0 END))
        + ABS(SUM(CASE WHEN TXN_YMD BETWEEN v_from_ymd AND v_to_ymd THEN OUTPUT_QUANTITY ELSE 0 END))
        + ABS(SUM(CASE WHEN TXN_YMD BETWEEN v_from_ymd AND v_to_ymd THEN OUTPUT_AMOUNT ELSE 0 END))
        + ABS(SUM(CASE WHEN TXN_YMD <= v_to_ymd THEN INPUT_QUANTITY - OUTPUT_QUANTITY ELSE 0 END))
        + ABS(SUM(CASE WHEN TXN_YMD <= v_to_ymd THEN INPUT_AMOUNT - OUTPUT_AMOUNT ELSE 0 END)) > 0;

    DROP TEMPORARY TABLE IF EXISTS tmp_inventory_quantity_grouped;
    CREATE TEMPORARY TABLE tmp_inventory_quantity_grouped
    (
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        LEVEL_COUNT INT NOT NULL DEFAULT 3,
        L1_KEY VARCHAR(255) NOT NULL DEFAULT '',
        L1_SORT VARCHAR(255) NOT NULL DEFAULT '',
        L1_LABEL VARCHAR(255) NOT NULL DEFAULT '',
        L1_WAREHOUSE_NAME VARCHAR(255) NOT NULL DEFAULT '',
        L1_PRODUCT_CD VARCHAR(50) NOT NULL DEFAULT '',
        L1_PRODUCT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        L1_UNIT_NAME VARCHAR(100) NOT NULL DEFAULT '',
        L2_KEY VARCHAR(255) NOT NULL DEFAULT '',
        L2_SORT VARCHAR(255) NOT NULL DEFAULT '',
        L2_LABEL VARCHAR(255) NOT NULL DEFAULT '',
        L2_WAREHOUSE_NAME VARCHAR(255) NOT NULL DEFAULT '',
        L2_PRODUCT_CD VARCHAR(50) NOT NULL DEFAULT '',
        L2_PRODUCT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        L2_UNIT_NAME VARCHAR(100) NOT NULL DEFAULT '',
        L3_KEY VARCHAR(255) NOT NULL DEFAULT '',
        L3_SORT VARCHAR(255) NOT NULL DEFAULT '',
        L3_LABEL VARCHAR(255) NOT NULL DEFAULT '',
        L3_WAREHOUSE_NAME VARCHAR(255) NOT NULL DEFAULT '',
        L3_PRODUCT_CD VARCHAR(50) NOT NULL DEFAULT '',
        L3_PRODUCT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        L3_UNIT_NAME VARCHAR(100) NOT NULL DEFAULT '',
        BEGIN_QUANTITY DECIMAL(18,4) NOT NULL DEFAULT 0.0000,
        BEGIN_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        INPUT_QUANTITY DECIMAL(18,4) NOT NULL DEFAULT 0.0000,
        INPUT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        OUTPUT_QUANTITY DECIMAL(18,4) NOT NULL DEFAULT 0.0000,
        OUTPUT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        END_QUANTITY DECIMAL(18,4) NOT NULL DEFAULT 0.0000,
        END_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_inventory_quantity_grouped
    (
        COMPANY_CD,
        LEVEL_COUNT,
        L1_KEY,
        L1_SORT,
        L1_LABEL,
        L1_WAREHOUSE_NAME,
        L1_PRODUCT_CD,
        L1_PRODUCT_NAME,
        L1_UNIT_NAME,
        L2_KEY,
        L2_SORT,
        L2_LABEL,
        L2_WAREHOUSE_NAME,
        L2_PRODUCT_CD,
        L2_PRODUCT_NAME,
        L2_UNIT_NAME,
        L3_KEY,
        L3_SORT,
        L3_LABEL,
        L3_WAREHOUSE_NAME,
        L3_PRODUCT_CD,
        L3_PRODUCT_NAME,
        L3_UNIT_NAME,
        BEGIN_QUANTITY,
        BEGIN_AMOUNT,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        END_QUANTITY,
        END_AMOUNT
    )
    SELECT
        COMPANY_CD,
        CASE WHEN v_group_option IN ('STORE_PRODUCT', 'PRODUCT_STORE') THEN 2 ELSE 3 END,
        CASE v_group_option
            WHEN 'PRODUCT_KIND_PRODUCT_STORE' THEN CONCAT('PK:', IFNULL(NULLIF(PRODUCT_KIND_CD, ''), 'EMPTY'))
            WHEN 'PRODUCT_STORE' THEN CONCAT('P:', IFNULL(NULLIF(PRODUCT_CD, ''), 'EMPTY'), ':', IFNULL(NULLIF(UNIT_NAME, ''), 'EMPTY'))
            WHEN 'STORE_KIND_STORE_PRODUCT' THEN CONCAT('SK:', IFNULL(NULLIF(STORE_KIND_CD, ''), 'EMPTY'))
            ELSE CONCAT('S:', IFNULL(NULLIF(STORE_CD, ''), 'EMPTY'))
        END,
        CASE v_group_option
            WHEN 'PRODUCT_KIND_PRODUCT_STORE' THEN CONCAT('PK:', IFNULL(NULLIF(PRODUCT_KIND_CD, ''), '~~~'), ':', PRODUCT_KIND_NAME)
            WHEN 'PRODUCT_STORE' THEN CONCAT('P:', IFNULL(NULLIF(PRODUCT_CD, ''), '~~~'), ':', PRODUCT_NAME, ':', UNIT_NAME)
            WHEN 'STORE_KIND_STORE_PRODUCT' THEN CONCAT('SK:', IFNULL(NULLIF(STORE_KIND_CD, ''), '~~~'), ':', STORE_KIND_NAME)
            ELSE CONCAT('S:', IFNULL(NULLIF(STORE_CD, ''), '~~~'), ':', STORE_NAME)
        END,
        CASE v_group_option
            WHEN 'PRODUCT_KIND_PRODUCT_STORE' THEN CONCAT('Nhóm hàng: ', IFNULL(NULLIF(PRODUCT_KIND_CD, ''), '(trống)'), IF(PRODUCT_KIND_NAME = '', '', CONCAT(' - ', PRODUCT_KIND_NAME)))
            WHEN 'PRODUCT_STORE' THEN CONCAT('Hàng hóa: ', IFNULL(NULLIF(PRODUCT_CD, ''), '(trống)'), IF(PRODUCT_NAME = '', '', CONCAT(' - ', PRODUCT_NAME)))
            WHEN 'STORE_KIND_STORE_PRODUCT' THEN CONCAT('Tài khoản kho: ', IFNULL(NULLIF(STORE_KIND_CD, ''), '(trống)'), IF(STORE_KIND_NAME = '', '', CONCAT(' - ', STORE_KIND_NAME)))
            ELSE CONCAT('Kho: ', IFNULL(NULLIF(STORE_CD, ''), '(trống)'), IF(STORE_NAME = '', '', CONCAT(' - ', STORE_NAME)))
        END,
        CASE
            WHEN v_group_option IN ('STORE_PRODUCT_KIND_PRODUCT', 'STORE_PRODUCT') THEN CONCAT('Kho: ', IFNULL(NULLIF(STORE_CD, ''), '(trống)'), IF(STORE_NAME = '', '', CONCAT(' - ', STORE_NAME)))
            WHEN v_group_option = 'STORE_KIND_STORE_PRODUCT' THEN CONCAT('Tài khoản kho: ', IFNULL(NULLIF(STORE_KIND_CD, ''), '(trống)'), IF(STORE_KIND_NAME = '', '', CONCAT(' - ', STORE_KIND_NAME)))
            ELSE ''
        END,
        CASE WHEN v_group_option = 'PRODUCT_STORE' THEN PRODUCT_CD ELSE '' END,
        CASE
            WHEN v_group_option = 'PRODUCT_KIND_PRODUCT_STORE' THEN CONCAT('Nhóm hàng: ', IFNULL(NULLIF(PRODUCT_KIND_CD, ''), '(trống)'), IF(PRODUCT_KIND_NAME = '', '', CONCAT(' - ', PRODUCT_KIND_NAME)))
            WHEN v_group_option = 'PRODUCT_STORE' THEN IF(PRODUCT_NAME = '', PRODUCT_CD, PRODUCT_NAME)
            ELSE ''
        END,
        CASE WHEN v_group_option = 'PRODUCT_STORE' THEN UNIT_NAME ELSE '' END,
        CASE v_group_option
            WHEN 'STORE_PRODUCT_KIND_PRODUCT' THEN CONCAT('PK:', IFNULL(NULLIF(PRODUCT_KIND_CD, ''), 'EMPTY'))
            WHEN 'PRODUCT_KIND_PRODUCT_STORE' THEN CONCAT('P:', IFNULL(NULLIF(PRODUCT_CD, ''), 'EMPTY'), ':', IFNULL(NULLIF(UNIT_NAME, ''), 'EMPTY'))
            WHEN 'STORE_KIND_STORE_PRODUCT' THEN CONCAT('S:', IFNULL(NULLIF(STORE_CD, ''), 'EMPTY'))
            WHEN 'STORE_PRODUCT' THEN CONCAT('P:', IFNULL(NULLIF(PRODUCT_CD, ''), 'EMPTY'), ':', IFNULL(NULLIF(UNIT_NAME, ''), 'EMPTY'))
            ELSE CONCAT('S:', IFNULL(NULLIF(STORE_CD, ''), 'EMPTY'))
        END,
        CASE v_group_option
            WHEN 'STORE_PRODUCT_KIND_PRODUCT' THEN CONCAT('PK:', IFNULL(NULLIF(PRODUCT_KIND_CD, ''), '~~~'), ':', PRODUCT_KIND_NAME)
            WHEN 'PRODUCT_KIND_PRODUCT_STORE' THEN CONCAT('P:', IFNULL(NULLIF(PRODUCT_CD, ''), '~~~'), ':', PRODUCT_NAME, ':', UNIT_NAME)
            WHEN 'STORE_KIND_STORE_PRODUCT' THEN CONCAT('S:', IFNULL(NULLIF(STORE_CD, ''), '~~~'), ':', STORE_NAME)
            WHEN 'STORE_PRODUCT' THEN CONCAT('P:', IFNULL(NULLIF(PRODUCT_CD, ''), '~~~'), ':', PRODUCT_NAME, ':', UNIT_NAME)
            ELSE CONCAT('S:', IFNULL(NULLIF(STORE_CD, ''), '~~~'), ':', STORE_NAME)
        END,
        CASE v_group_option
            WHEN 'STORE_PRODUCT_KIND_PRODUCT' THEN CONCAT('Nhóm hàng: ', IFNULL(NULLIF(PRODUCT_KIND_CD, ''), '(trống)'), IF(PRODUCT_KIND_NAME = '', '', CONCAT(' - ', PRODUCT_KIND_NAME)))
            WHEN 'PRODUCT_KIND_PRODUCT_STORE' THEN CONCAT('Hàng hóa: ', IFNULL(NULLIF(PRODUCT_CD, ''), '(trống)'), IF(PRODUCT_NAME = '', '', CONCAT(' - ', PRODUCT_NAME)))
            WHEN 'STORE_KIND_STORE_PRODUCT' THEN CONCAT('Kho: ', IFNULL(NULLIF(STORE_CD, ''), '(trống)'), IF(STORE_NAME = '', '', CONCAT(' - ', STORE_NAME)))
            WHEN 'STORE_PRODUCT' THEN CONCAT('Hàng hóa: ', IFNULL(NULLIF(PRODUCT_CD, ''), '(trống)'), IF(PRODUCT_NAME = '', '', CONCAT(' - ', PRODUCT_NAME)))
            ELSE CONCAT('Kho: ', IFNULL(NULLIF(STORE_CD, ''), '(trống)'), IF(STORE_NAME = '', '', CONCAT(' - ', STORE_NAME)))
        END,
        CASE WHEN v_group_option IN ('STORE_KIND_STORE_PRODUCT', 'PRODUCT_STORE') THEN CONCAT('Kho: ', IFNULL(NULLIF(STORE_CD, ''), '(trống)'), IF(STORE_NAME = '', '', CONCAT(' - ', STORE_NAME))) ELSE '' END,
        CASE WHEN v_group_option IN ('PRODUCT_KIND_PRODUCT_STORE', 'STORE_PRODUCT') THEN PRODUCT_CD ELSE '' END,
        CASE
            WHEN v_group_option = 'STORE_PRODUCT_KIND_PRODUCT' THEN CONCAT('Nhóm hàng: ', IFNULL(NULLIF(PRODUCT_KIND_CD, ''), '(trống)'), IF(PRODUCT_KIND_NAME = '', '', CONCAT(' - ', PRODUCT_KIND_NAME)))
            WHEN v_group_option IN ('PRODUCT_KIND_PRODUCT_STORE', 'STORE_PRODUCT') THEN IF(PRODUCT_NAME = '', PRODUCT_CD, PRODUCT_NAME)
            ELSE ''
        END,
        CASE WHEN v_group_option IN ('PRODUCT_KIND_PRODUCT_STORE', 'STORE_PRODUCT') THEN UNIT_NAME ELSE '' END,
        CASE v_group_option
            WHEN 'PRODUCT_KIND_PRODUCT_STORE' THEN CONCAT('S:', IFNULL(NULLIF(STORE_CD, ''), 'EMPTY'))
            WHEN 'STORE_KIND_STORE_PRODUCT' THEN CONCAT('P:', IFNULL(NULLIF(PRODUCT_CD, ''), 'EMPTY'), ':', IFNULL(NULLIF(UNIT_NAME, ''), 'EMPTY'))
            ELSE CONCAT('P:', IFNULL(NULLIF(PRODUCT_CD, ''), 'EMPTY'), ':', IFNULL(NULLIF(UNIT_NAME, ''), 'EMPTY'))
        END,
        CASE v_group_option
            WHEN 'PRODUCT_KIND_PRODUCT_STORE' THEN CONCAT('S:', IFNULL(NULLIF(STORE_CD, ''), '~~~'), ':', STORE_NAME)
            WHEN 'STORE_KIND_STORE_PRODUCT' THEN CONCAT('P:', IFNULL(NULLIF(PRODUCT_CD, ''), '~~~'), ':', PRODUCT_NAME, ':', UNIT_NAME)
            ELSE CONCAT('P:', IFNULL(NULLIF(PRODUCT_CD, ''), '~~~'), ':', PRODUCT_NAME, ':', UNIT_NAME)
        END,
        CASE v_group_option
            WHEN 'PRODUCT_KIND_PRODUCT_STORE' THEN CONCAT('Kho: ', IFNULL(NULLIF(STORE_CD, ''), '(trống)'), IF(STORE_NAME = '', '', CONCAT(' - ', STORE_NAME)))
            WHEN 'STORE_KIND_STORE_PRODUCT' THEN CONCAT('Hàng hóa: ', IFNULL(NULLIF(PRODUCT_CD, ''), '(trống)'), IF(PRODUCT_NAME = '', '', CONCAT(' - ', PRODUCT_NAME)))
            ELSE CONCAT('Hàng hóa: ', IFNULL(NULLIF(PRODUCT_CD, ''), '(trống)'), IF(PRODUCT_NAME = '', '', CONCAT(' - ', PRODUCT_NAME)))
        END,
        CASE WHEN v_group_option = 'PRODUCT_KIND_PRODUCT_STORE' THEN CONCAT('Kho: ', IFNULL(NULLIF(STORE_CD, ''), '(trống)'), IF(STORE_NAME = '', '', CONCAT(' - ', STORE_NAME))) ELSE '' END,
        CASE WHEN v_group_option <> 'PRODUCT_KIND_PRODUCT_STORE' THEN PRODUCT_CD ELSE '' END,
        CASE WHEN v_group_option <> 'PRODUCT_KIND_PRODUCT_STORE' THEN IF(PRODUCT_NAME = '', PRODUCT_CD, PRODUCT_NAME) ELSE '' END,
        CASE WHEN v_group_option <> 'PRODUCT_KIND_PRODUCT_STORE' THEN UNIT_NAME ELSE '' END,
        BEGIN_QUANTITY,
        BEGIN_AMOUNT,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        END_QUANTITY,
        END_AMOUNT
    FROM tmp_inventory_quantity_summary;

    DROP TEMPORARY TABLE IF EXISTS tmp_inventory_quantity_report;
    CREATE TEMPORARY TABLE tmp_inventory_quantity_report
    (
        ROW_SORT INT NOT NULL AUTO_INCREMENT,
        SORT_KEY VARCHAR(1000) NOT NULL DEFAULT '',
        ROW_KEY VARCHAR(255) NOT NULL DEFAULT '',
        PARENT_ROW_KEY VARCHAR(255) NULL,
        ROW_TYPE VARCHAR(30) NOT NULL DEFAULT '',
        ROW_LEVEL INT NOT NULL DEFAULT 0,
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        WAREHOUSE_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRODUCT_CD VARCHAR(50) NOT NULL DEFAULT '',
        PRODUCT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        UNIT_NAME VARCHAR(100) NOT NULL DEFAULT '',
        BEGIN_QUANTITY DECIMAL(18,4) NULL,
        BEGIN_AMOUNT DECIMAL(18,2) NULL,
        INPUT_QUANTITY DECIMAL(18,4) NULL,
        INPUT_AMOUNT DECIMAL(18,2) NULL,
        OUTPUT_QUANTITY DECIMAL(18,4) NULL,
        OUTPUT_AMOUNT DECIMAL(18,2) NULL,
        END_QUANTITY DECIMAL(18,4) NULL,
        END_AMOUNT DECIMAL(18,2) NULL,
        REPORT_PERIOD_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        PRIMARY KEY (ROW_SORT)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_inventory_quantity_report
    (
        SORT_KEY,
        ROW_KEY,
        PARENT_ROW_KEY,
        ROW_TYPE,
        ROW_LEVEL,
        COMPANY_CD,
        WAREHOUSE_NAME,
        PRODUCT_CD,
        PRODUCT_NAME,
        UNIT_NAME,
        BEGIN_QUANTITY,
        BEGIN_AMOUNT,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        END_QUANTITY,
        END_AMOUNT,
        REPORT_PERIOD_TEXT
    )
    SELECT
        CONCAT(L1_SORT, '|00'),
        CONCAT('L1:', L1_KEY),
        NULL,
        'GROUP',
        0,
        COMPANY_CD,
        MAX(L1_WAREHOUSE_NAME),
        MAX(L1_PRODUCT_CD),
        MAX(L1_PRODUCT_NAME),
        MAX(L1_UNIT_NAME),
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        v_period_text
    FROM tmp_inventory_quantity_grouped
    GROUP BY COMPANY_CD, L1_KEY, L1_SORT;

    INSERT INTO tmp_inventory_quantity_report
    (
        SORT_KEY,
        ROW_KEY,
        PARENT_ROW_KEY,
        ROW_TYPE,
        ROW_LEVEL,
        COMPANY_CD,
        WAREHOUSE_NAME,
        PRODUCT_CD,
        PRODUCT_NAME,
        UNIT_NAME,
        BEGIN_QUANTITY,
        BEGIN_AMOUNT,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        END_QUANTITY,
        END_AMOUNT,
        REPORT_PERIOD_TEXT
    )
    SELECT
        CONCAT(L1_SORT, '|', L2_SORT, '|00'),
        CONCAT('L2:', L1_KEY, ':', L2_KEY),
        CONCAT('L1:', L1_KEY),
        'GROUP',
        1,
        COMPANY_CD,
        MAX(L2_WAREHOUSE_NAME),
        MAX(L2_PRODUCT_CD),
        MAX(L2_PRODUCT_NAME),
        MAX(L2_UNIT_NAME),
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        v_period_text
    FROM tmp_inventory_quantity_grouped
    WHERE LEVEL_COUNT = 3
    GROUP BY COMPANY_CD, L1_KEY, L1_SORT, L2_KEY, L2_SORT;

    INSERT INTO tmp_inventory_quantity_report
    (
        SORT_KEY,
        ROW_KEY,
        PARENT_ROW_KEY,
        ROW_TYPE,
        ROW_LEVEL,
        COMPANY_CD,
        WAREHOUSE_NAME,
        PRODUCT_CD,
        PRODUCT_NAME,
        UNIT_NAME,
        BEGIN_QUANTITY,
        BEGIN_AMOUNT,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        END_QUANTITY,
        END_AMOUNT,
        REPORT_PERIOD_TEXT
    )
    SELECT
        CONCAT(L1_SORT, '|', L2_SORT, '|', L3_SORT, '|10'),
        CONCAT('D3:', L1_KEY, ':', L2_KEY, ':', L3_KEY),
        CONCAT('L2:', L1_KEY, ':', L2_KEY),
        'DETAIL',
        2,
        COMPANY_CD,
        MAX(L3_WAREHOUSE_NAME),
        MAX(L3_PRODUCT_CD),
        MAX(L3_PRODUCT_NAME),
        MAX(L3_UNIT_NAME),
        NULLIF(SUM(BEGIN_QUANTITY), 0),
        NULLIF(SUM(BEGIN_AMOUNT), 0),
        NULLIF(SUM(INPUT_QUANTITY), 0),
        NULLIF(SUM(INPUT_AMOUNT), 0),
        NULLIF(SUM(OUTPUT_QUANTITY), 0),
        NULLIF(SUM(OUTPUT_AMOUNT), 0),
        NULLIF(SUM(END_QUANTITY), 0),
        NULLIF(SUM(END_AMOUNT), 0),
        v_period_text
    FROM tmp_inventory_quantity_grouped
    WHERE LEVEL_COUNT = 3
    GROUP BY COMPANY_CD, L1_KEY, L1_SORT, L2_KEY, L2_SORT, L3_KEY, L3_SORT;

    INSERT INTO tmp_inventory_quantity_report
    (
        SORT_KEY,
        ROW_KEY,
        PARENT_ROW_KEY,
        ROW_TYPE,
        ROW_LEVEL,
        COMPANY_CD,
        WAREHOUSE_NAME,
        PRODUCT_CD,
        PRODUCT_NAME,
        UNIT_NAME,
        BEGIN_QUANTITY,
        BEGIN_AMOUNT,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        END_QUANTITY,
        END_AMOUNT,
        REPORT_PERIOD_TEXT
    )
    SELECT
        CONCAT(L1_SORT, '|', L2_SORT, '|10'),
        CONCAT('D2:', L1_KEY, ':', L2_KEY),
        CONCAT('L1:', L1_KEY),
        'DETAIL',
        1,
        COMPANY_CD,
        MAX(L2_WAREHOUSE_NAME),
        MAX(L2_PRODUCT_CD),
        MAX(L2_PRODUCT_NAME),
        MAX(L2_UNIT_NAME),
        NULLIF(SUM(BEGIN_QUANTITY), 0),
        NULLIF(SUM(BEGIN_AMOUNT), 0),
        NULLIF(SUM(INPUT_QUANTITY), 0),
        NULLIF(SUM(INPUT_AMOUNT), 0),
        NULLIF(SUM(OUTPUT_QUANTITY), 0),
        NULLIF(SUM(OUTPUT_AMOUNT), 0),
        NULLIF(SUM(END_QUANTITY), 0),
        NULLIF(SUM(END_AMOUNT), 0),
        v_period_text
    FROM tmp_inventory_quantity_grouped
    WHERE LEVEL_COUNT = 2
    GROUP BY COMPANY_CD, L1_KEY, L1_SORT, L2_KEY, L2_SORT;

    INSERT INTO tmp_inventory_quantity_report
    (
        SORT_KEY,
        ROW_KEY,
        PARENT_ROW_KEY,
        ROW_TYPE,
        ROW_LEVEL,
        COMPANY_CD,
        WAREHOUSE_NAME,
        PRODUCT_CD,
        PRODUCT_NAME,
        UNIT_NAME,
        BEGIN_QUANTITY,
        BEGIN_AMOUNT,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        END_QUANTITY,
        END_AMOUNT,
        REPORT_PERIOD_TEXT
    )
    SELECT
        CONCAT(L1_SORT, '|', L2_SORT, '|90'),
        CONCAT('T2:', L1_KEY, ':', L2_KEY),
        CONCAT('L2:', L1_KEY, ':', L2_KEY),
        'TOTAL',
        2,
        COMPANY_CD,
        '',
        '',
        CONCAT('Tổng cộng ', MAX(L2_LABEL)),
        '',
        NULLIF(SUM(BEGIN_QUANTITY), 0),
        NULLIF(SUM(BEGIN_AMOUNT), 0),
        NULLIF(SUM(INPUT_QUANTITY), 0),
        NULLIF(SUM(INPUT_AMOUNT), 0),
        NULLIF(SUM(OUTPUT_QUANTITY), 0),
        NULLIF(SUM(OUTPUT_AMOUNT), 0),
        NULLIF(SUM(END_QUANTITY), 0),
        NULLIF(SUM(END_AMOUNT), 0),
        v_period_text
    FROM tmp_inventory_quantity_grouped
    WHERE LEVEL_COUNT = 3
    GROUP BY COMPANY_CD, L1_KEY, L1_SORT, L2_KEY, L2_SORT;

    INSERT INTO tmp_inventory_quantity_report
    (
        SORT_KEY,
        ROW_KEY,
        PARENT_ROW_KEY,
        ROW_TYPE,
        ROW_LEVEL,
        COMPANY_CD,
        WAREHOUSE_NAME,
        PRODUCT_CD,
        PRODUCT_NAME,
        UNIT_NAME,
        BEGIN_QUANTITY,
        BEGIN_AMOUNT,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        END_QUANTITY,
        END_AMOUNT,
        REPORT_PERIOD_TEXT
    )
    SELECT
        CONCAT(L1_SORT, '|99'),
        CONCAT('T1:', L1_KEY),
        CONCAT('L1:', L1_KEY),
        'TOTAL',
        1,
        COMPANY_CD,
        '',
        '',
        CONCAT('Tổng cộng ', MAX(L1_LABEL)),
        '',
        NULLIF(SUM(BEGIN_QUANTITY), 0),
        NULLIF(SUM(BEGIN_AMOUNT), 0),
        NULLIF(SUM(INPUT_QUANTITY), 0),
        NULLIF(SUM(INPUT_AMOUNT), 0),
        NULLIF(SUM(OUTPUT_QUANTITY), 0),
        NULLIF(SUM(OUTPUT_AMOUNT), 0),
        NULLIF(SUM(END_QUANTITY), 0),
        NULLIF(SUM(END_AMOUNT), 0),
        v_period_text
    FROM tmp_inventory_quantity_grouped
    GROUP BY COMPANY_CD, L1_KEY, L1_SORT;

    INSERT INTO tmp_inventory_quantity_report
    (
        SORT_KEY,
        ROW_KEY,
        PARENT_ROW_KEY,
        ROW_TYPE,
        ROW_LEVEL,
        COMPANY_CD,
        WAREHOUSE_NAME,
        PRODUCT_CD,
        PRODUCT_NAME,
        UNIT_NAME,
        BEGIN_QUANTITY,
        BEGIN_AMOUNT,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        END_QUANTITY,
        END_AMOUNT,
        REPORT_PERIOD_TEXT
    )
    SELECT
        'ZZZZ',
        'TOTAL',
        NULL,
        'TOTAL_FOOTER',
        0,
        p_COMPANY_CD,
        '',
        '',
        'Tổng cộng',
        '',
        NULLIF(SUM(BEGIN_QUANTITY), 0),
        NULLIF(SUM(BEGIN_AMOUNT), 0),
        NULLIF(SUM(INPUT_QUANTITY), 0),
        NULLIF(SUM(INPUT_AMOUNT), 0),
        NULLIF(SUM(OUTPUT_QUANTITY), 0),
        NULLIF(SUM(OUTPUT_AMOUNT), 0),
        NULLIF(SUM(END_QUANTITY), 0),
        NULLIF(SUM(END_AMOUNT), 0),
        v_period_text
    FROM tmp_inventory_quantity_grouped
    HAVING COUNT(*) > 0;

    SELECT
        ROW_KEY,
        PARENT_ROW_KEY,
        ROW_TYPE,
        ROW_LEVEL,
        ROW_SORT,
        COMPANY_CD,
        WAREHOUSE_NAME,
        PRODUCT_CD,
        PRODUCT_NAME,
        UNIT_NAME,
        BEGIN_QUANTITY,
        BEGIN_AMOUNT,
        INPUT_QUANTITY,
        INPUT_AMOUNT,
        OUTPUT_QUANTITY,
        OUTPUT_AMOUNT,
        END_QUANTITY,
        END_AMOUNT,
        REPORT_PERIOD_TEXT
    FROM tmp_inventory_quantity_report
    ORDER BY
        CASE WHEN ROW_TYPE = 'TOTAL_FOOTER' THEN 1 ELSE 0 END,
        SORT_KEY,
        ROW_SORT;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_inventory_receipt_voucher
DROP PROCEDURE IF EXISTS `rpt_inventory_receipt_voucher`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_inventory_receipt_voucher`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHIT_ID BIGINT,
    IN p_CHIT_IDS TEXT,
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_ids TEXT;
    DECLARE v_token VARCHAR(32);
    DECLARE v_language VARCHAR(20);
	 DECLARE v_TOTAL VARCHAR(100); -- TỔNG

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        DROP TEMPORARY TABLE IF EXISTS tmp_iv_result;
        DROP TEMPORARY TABLE IF EXISTS tmp_iv_summary;
        DROP TEMPORARY TABLE IF EXISTS tmp_iv_detail;
        DROP TEMPORARY TABLE IF EXISTS tmp_iv_input_dates;
        DROP TEMPORARY TABLE IF EXISTS tmp_iv_headers;
        DROP TEMPORARY TABLE IF EXISTS tmp_iv_ids;
        RESIGNAL;
    END;

    DROP TEMPORARY TABLE IF EXISTS tmp_iv_result;
    DROP TEMPORARY TABLE IF EXISTS tmp_iv_summary;
    DROP TEMPORARY TABLE IF EXISTS tmp_iv_detail;
    DROP TEMPORARY TABLE IF EXISTS tmp_iv_input_dates;
    DROP TEMPORARY TABLE IF EXISTS tmp_iv_headers;
    DROP TEMPORARY TABLE IF EXISTS tmp_iv_ids;

    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));
    SET v_ids = REPLACE(REPLACE(REPLACE(REPLACE(IFNULL(TRIM(p_CHIT_IDS), ''), '|', ','), ';', ','), CHAR(10), ','), CHAR(13), ',');
    IF v_ids = '' AND IFNULL(p_CHIT_ID, 0) > 0 THEN
        SET v_ids = CAST(p_CHIT_ID AS CHAR);
    END IF;
	 
	 -- TỔNG
	 select (CASE
                WHEN v_language = 'ENG' THEN p.ENG
                WHEN v_language = 'KOR' THEN p.KOR                
                ELSE p.VIET
            END) INTO v_TOTAL
	 from am_web_manager.t_message_info P where `key` like 'ALL_TOTAL';
	 
    CREATE TEMPORARY TABLE tmp_iv_ids (
        INVENTORY_ID BIGINT NOT NULL PRIMARY KEY
    ) ENGINE=InnoDB;

    -- Resolve the caller-supplied list once; all subsequent joins use indexed IDs.
    WHILE v_ids <> '' DO
        SET v_token = TRIM(SUBSTRING_INDEX(v_ids, ',', 1));
        IF v_token REGEXP '^[0-9]{1,19}$' THEN
            INSERT IGNORE INTO tmp_iv_ids (INVENTORY_ID) VALUES (CAST(v_token AS UNSIGNED));
        END IF;
        IF LOCATE(',', v_ids) > 0 THEN
            SET v_ids = SUBSTRING(v_ids, LOCATE(',', v_ids) + 1);
        ELSE
            SET v_ids = '';
        END IF;
    END WHILE;

    CREATE TEMPORARY TABLE tmp_iv_headers ENGINE=InnoDB AS
    SELECT h.INVENTORY_ID, h.COMPANY_CD, h.INVENTORY_CD, h.INVENTORY_NO,
           h.INVENTORY_YMD, h.AMOUNT, h.REMARK, h.UPDATE_BY, h.CREATE_BY,
           h.CUSTOMER_ID, h.CUSTOMER_CD
    FROM tmp_iv_ids ids
    INNER JOIN chit_inventory_info h ON h.INVENTORY_ID = ids.INVENTORY_ID
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'AP' AND h.CHIT_TYPE = 'IR'
      AND h.ISDEL = '0';
    ALTER TABLE tmp_iv_headers ADD PRIMARY KEY (INVENTORY_ID);

    CREATE TEMPORARY TABLE tmp_iv_detail (
        ROW_ID BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
        CHIT_ID BIGINT NOT NULL,
        PRODUCT_NAME VARCHAR(500) COLLATE utf8_unicode_ci,
        PRODUCT_CD VARCHAR(100) COLLATE utf8_unicode_ci,
        UNIT_NAME VARCHAR(255) COLLATE utf8_unicode_ci,
        QUANTITY DECIMAL(28,8),
        UNIT_PRICE DECIMAL(28,8),
        LINE_AMOUNT DECIMAL(28,8),
        STORE_NAME VARCHAR(500) COLLATE utf8_unicode_ci,
        INPUT_INVENTORY_YMD VARCHAR(32),
        OUTPUT_INVENTORY_YMD VARCHAR(32),
        KEY IX_VOUCHER (CHIT_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    -- Ordered INSERT assigns deterministic, consecutive auto-increment IDs.
    -- LINE_SORT is ROW_ID - MIN(ROW_ID) per voucher + 1; no per-line COUNT(*).
    INSERT INTO tmp_iv_detail
        (CHIT_ID, PRODUCT_NAME, PRODUCT_CD, UNIT_NAME, QUANTITY, UNIT_PRICE,
         LINE_AMOUNT, STORE_NAME, INPUT_INVENTORY_YMD, OUTPUT_INVENTORY_YMD)
    SELECT ii.INVENTORY_ID,
           COALESCE(NULLIF(TRIM(CASE
                WHEN v_language = 'ENG' THEN product.PRODUCT_NM_ENG
                WHEN v_language = 'KOR' THEN product.PRODUCT_NM_KOR
                WHEN v_language IN ('CHN', 'CHINA') THEN product.PRODUCT_NM_CHINA
                ELSE product.PRODUCT_NM_VIET
            END), ''), ii.PRODUCT_CD, ''),
           ii.PRODUCT_CD,
           COALESCE(NULLIF(unit_info.UNIT_NM, ''), ii.UNIT_CD, ''),
           ii.QUANTITY,
           ii.UNIT_PRICE_CC,
           CASE WHEN IFNULL(ii.AMOUNT_CC, 0) <> 0 THEN ii.AMOUNT_CC
                ELSE IFNULL(ii.QUANTITY, 0) * IFNULL(ii.UNIT_PRICE_CC, 0) END,
           NULLIF(TRIM(COALESCE(store_info.STORE_NM_VIET, ii.STORE_CD)), ''),
        NULL,
        NULL
    FROM tmp_iv_headers h
    INNER JOIN chit_inventory_input ii
       ON ii.COMPANY_CD = h.COMPANY_CD AND ii.INVENTORY_ID = h.INVENTORY_ID
      AND ii.ISDEL = '0'
    LEFT JOIN product_info product
       ON product.COMPANY_CD = ii.COMPANY_CD
      AND product.PRODUCT_ID = ii.PRODUCT_ID AND IFNULL(product.ISDEL, '0') = '0'
    LEFT JOIN product_unit unit_info
       ON unit_info.COMPANY_CD = ii.COMPANY_CD
      AND unit_info.UNIT_ID = ii.UNIT_ID AND IFNULL(unit_info.ISDEL, '0') = '0'
    LEFT JOIN store_info
       ON store_info.COMPANY_CD = ii.COMPANY_CD
      AND store_info.STORE_ID = ii.STORE_ID AND IFNULL(store_info.ISDEL, '0') = '0'
    ORDER BY ii.INVENTORY_ID, IFNULL(ii.SORT, 0), ii.INPUT_ID;

    CREATE TEMPORARY TABLE tmp_iv_summary ENGINE=InnoDB AS
    SELECT CHIT_ID, COUNT(*) AS LINE_COUNT,
           MIN(ROW_ID) AS FIRST_ROW_ID,
           MIN(CASE WHEN STORE_NAME IS NOT NULL AND TRIM(STORE_NAME) <> '' THEN ROW_ID ELSE NULL END) AS FIRST_STORE_ROW_ID,
           SUM(IFNULL(QUANTITY, 0)) AS TOTAL_QUANTITY,
           SUM(IFNULL(LINE_AMOUNT, 0)) AS TOTAL_AMOUNT
    FROM tmp_iv_detail
    GROUP BY CHIT_ID;
    ALTER TABLE tmp_iv_summary ADD PRIMARY KEY (CHIT_ID);

    CREATE TEMPORARY TABLE tmp_iv_result (
        CHIT_ID BIGINT NOT NULL,
        LINE_SORT BIGINT NOT NULL,
        LINE_NO VARCHAR(20) COLLATE utf8_unicode_ci NOT NULL DEFAULT '',
        PRODUCT_NAME VARCHAR(500) COLLATE utf8_unicode_ci,
        PRODUCT_CD VARCHAR(100) COLLATE utf8_unicode_ci,
        UNIT_NAME VARCHAR(255) COLLATE utf8_unicode_ci,
        QUANTITY DECIMAL(28,8),
        UNIT_PRICE DECIMAL(28,8),
        LINE_AMOUNT DECIMAL(28,8),
        INPUT_INVENTORY_YMD VARCHAR(32),
        OUTPUT_INVENTORY_YMD VARCHAR(32),
        KEY IX_VOUCHER_ORDER (CHIT_ID, LINE_SORT)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_iv_result
      (CHIT_ID, LINE_SORT, LINE_NO, PRODUCT_NAME, PRODUCT_CD, UNIT_NAME,
       QUANTITY, UNIT_PRICE, LINE_AMOUNT, INPUT_INVENTORY_YMD, OUTPUT_INVENTORY_YMD)
    SELECT d.CHIT_ID, d.ROW_ID - s.FIRST_ROW_ID + 1,
           CAST(d.ROW_ID - s.FIRST_ROW_ID + 1 AS CHAR),
           d.PRODUCT_NAME, d.PRODUCT_CD, d.UNIT_NAME,
           d.QUANTITY, d.UNIT_PRICE, d.LINE_AMOUNT,
           d.INPUT_INVENTORY_YMD, d.OUTPUT_INVENTORY_YMD
    FROM tmp_iv_detail d
    INNER JOIN tmp_iv_summary s ON s.CHIT_ID = d.CHIT_ID;

    -- Preserve at least five printed rows for every selected voucher.
    /*
    INSERT INTO tmp_iv_result (CHIT_ID, LINE_SORT, LINE_NO)
    SELECT h.INVENTORY_ID, n.N, ''
    FROM tmp_iv_headers h
    LEFT JOIN tmp_iv_summary s ON s.CHIT_ID = h.INVENTORY_ID
    CROSS JOIN (SELECT 1 AS N UNION ALL SELECT 2 UNION ALL SELECT 3
                UNION ALL SELECT 4 UNION ALL SELECT 5) n
    WHERE n.N > IFNULL(s.LINE_COUNT, 0);
*/
    INSERT INTO tmp_iv_result
      (CHIT_ID, LINE_SORT, LINE_NO, QUANTITY, LINE_AMOUNT)
    SELECT h.INVENTORY_ID, 999999, v_TOTAL,
           IFNULL(s.TOTAL_QUANTITY, 0), IFNULL(s.TOTAL_AMOUNT, 0)
    FROM tmp_iv_headers h
    LEFT JOIN tmp_iv_summary s ON s.CHIT_ID = h.INVENTORY_ID;

    -- Output fields are kept compatible with company_report_element.VALUE_FIELD.
    SELECT
        h.INVENTORY_ID AS CHIT_ID,
        h.COMPANY_CD,
        h.INVENTORY_CD AS CHIT_CD,
        h.INVENTORY_NO AS CHIT_NO,
        h.INVENTORY_YMD AS CHIT_YMD,
        h.INVENTORY_YMD AS HEADER_DATE_TEXT,
        h.INVENTORY_YMD AS SIGNATURE_DATE_TEXT,
        CASE
            WHEN v_language = 'ENG' THEN COALESCE(NULLIF(TRIM(cust.CUSTOMER_NM_ENG), ''), NULLIF(TRIM(cust.CUSTOMER_NM_VIET), ''), '')
            WHEN v_language = 'KOR' THEN COALESCE(NULLIF(TRIM(cust.CUSTOMER_NM_KOR), ''), NULLIF(TRIM(cust.CUSTOMER_NM_ENG), ''), NULLIF(TRIM(cust.CUSTOMER_NM_VIET), ''), '')
            WHEN v_language IN ('CHN', 'CHINA') THEN COALESCE(NULLIF(TRIM(cust.CUSTOMER_NM_CHINA), ''), NULLIF(TRIM(cust.CUSTOMER_NM_ENG), ''), NULLIF(TRIM(cust.CUSTOMER_NM_VIET), ''), '')
            ELSE COALESCE(NULLIF(TRIM(cust.CUSTOMER_NM_VIET), ''), '')
        END AS PARTNER_NAME,
        IFNULL(cust.ADDRESS, '') AS PARTNER_ADDRESS,
        IFNULL(h.REMARK, '') AS REASON,
        IFNULL(h.REMARK, '') AS SOURCE_DOCUMENT_TEXT,
        IFNULL(first_line.STORE_NAME, '') AS WAREHOUSE_NAME,
        '' AS WAREHOUSE_LOCATION,
        IFNULL(h.AMOUNT, IFNULL(s.TOTAL_AMOUNT, 0)) AS AMOUNT,
        NULL AS AMOUNT_TEXT,
        NULL AS AMOUNT_IN_WORDS,
        NULL AS FC_AMOUNT,
        NULL AS FC_TYPE,
        NULL AS FC_RATE,
        NULL AS EXCHANGE_RATE_TEXT,
        NULL AS CONVERTED_AMOUNT_TEXT,
        '' AS DEBIT_ACCOUNT,
        '' AS CREDIT_ACCOUNT,
        IFNULL(s.LINE_COUNT, 0) AS DETAIL_COUNT,
        NULL AS ATTACHMENT_TEXT,
        NULL AS REFERENCE_TEXT,
        IFNULL(h.REMARK, '') AS NOTE,
        NULL AS NOTE_TEXT,
        COALESCE(NULLIF(TRIM(h.UPDATE_BY), ''), NULLIF(TRIM(h.CREATE_BY), ''), '') AS CREATED_BY,
        r.LINE_SORT, r.LINE_NO, r.PRODUCT_NAME, r.PRODUCT_CD, r.UNIT_NAME,
        r.QUANTITY AS DOC_QUANTITY,
        r.QUANTITY AS ACTUAL_QUANTITY,
        r.UNIT_PRICE,
        r.LINE_AMOUNT,
        h.CUSTOMER_ID,
        h.CUSTOMER_CD
    FROM tmp_iv_headers h
    INNER JOIN tmp_iv_result r ON r.CHIT_ID = h.INVENTORY_ID
    LEFT JOIN tmp_iv_summary s ON s.CHIT_ID = h.INVENTORY_ID
    LEFT JOIN tmp_iv_detail first_line ON first_line.ROW_ID = s.FIRST_STORE_ROW_ID
    LEFT JOIN customer_info cust
      ON cust.CUSTOMER_ID = COALESCE(NULLIF(h.CUSTOMER_ID, 0), (
           SELECT MIN(ci.CUSTOMER_ID) FROM customer_info ci
           WHERE ci.COMPANY_CD = h.COMPANY_CD
             AND ci.CUSTOMER_CD = h.CUSTOMER_CD
             AND IFNULL(ci.ISDEL, '0') = '0'
         ))
     AND cust.COMPANY_CD = h.COMPANY_CD
     AND IFNULL(cust.ISDEL, '0') = '0'
    ORDER BY h.INVENTORY_YMD, h.INVENTORY_ID, r.LINE_SORT;

    DROP TEMPORARY TABLE IF EXISTS tmp_iv_result;
    DROP TEMPORARY TABLE IF EXISTS tmp_iv_summary;
    DROP TEMPORARY TABLE IF EXISTS tmp_iv_detail;
    DROP TEMPORARY TABLE IF EXISTS tmp_iv_input_dates;
    DROP TEMPORARY TABLE IF EXISTS tmp_iv_headers;
    DROP TEMPORARY TABLE IF EXISTS tmp_iv_ids;

END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_inventory_source_document_report
DROP PROCEDURE IF EXISTS `rpt_inventory_source_document_report`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_inventory_source_document_report`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_PRODUCT_CD TEXT,
    IN p_STORE_CD TEXT,
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_product_cd TEXT;
    DECLARE v_store_cd TEXT;
    DECLARE v_language VARCHAR(20);

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;

    SET v_from_ymd = DATE_FORMAT(p_FROM_DATE, '%Y%m%d');
    SET v_to_ymd = DATE_FORMAT(p_TO_DATE, '%Y%m%d');
    SET v_product_cd = REPLACE(IFNULL(TRIM(p_PRODUCT_CD), ''), '|', ',');
    SET v_store_cd = REPLACE(IFNULL(TRIM(p_STORE_CD), ''), '|', ',');
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));

    SELECT report_rows.*
    FROM
    (
        SELECT
            CONCAT('IN:', ii.INPUT_ID) AS __ROW_KEY,
            1 AS __SIDE_SORT,
            COALESCE(NULLIF(TRIM(ii.STORE_CD), ''), store_info.STORE_CD, '') AS STORE_CD,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN product_kind.PRODUCTKIND_NM_ENG
                WHEN 'KOR' THEN product_kind.PRODUCTKIND_NM_KOR
                WHEN 'CHN' THEN product_kind.PRODUCTKIND_NM_CHINA
                WHEN 'CHINA' THEN product_kind.PRODUCTKIND_NM_CHINA
                ELSE product_kind.PRODUCTKIND_NM_VIET
            END), ''), '') AS MATERIAL_GROUP_NAME,
            COALESCE(NULLIF(TRIM(product_kind.PRODUCT_KIND_CD), ''), '') AS MATERIAL_GROUP_CD,
            COALESCE(NULLIF(TRIM(ii.PRODUCT_CD), ''), product.PRODUCT_CD, '') AS PRODUCT_CD,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN product.PRODUCT_NM_ENG
                WHEN 'KOR' THEN product.PRODUCT_NM_KOR
                WHEN 'CHN' THEN product.PRODUCT_NM_CHINA
                WHEN 'CHINA' THEN product.PRODUCT_NM_CHINA
                ELSE product.PRODUCT_NM_VIET
            END), ''), ii.PRODUCT_CD, '') AS PRODUCT_NAME,
            '' AS FINISHED_PRODUCT_CD,
            CAST(NULL AS DECIMAL(18,4)) AS BOM_QUANTITY,
            COALESCE(NULLIF(TRIM(ii.UNIT_CD), ''), unit_info.UNIT_CD, '') AS UNIT_CD,
            NULLIF(ii.UNIT_PRICE_CC, 0) AS UNIT_PRICE,
            NULLIF(ii.UNIT_PRICE_FC, 0) AS UNIT_PRICE_FC,
            NULLIF(ii.QUANTITY, 0) AS INPUT_QUANTITY,
            NULLIF(CASE
                WHEN IFNULL(ii.AMOUNT_CC, 0) <> 0 THEN ii.AMOUNT_CC
                ELSE IFNULL(ii.QUANTITY, 0) * IFNULL(ii.UNIT_PRICE_CC, 0)
            END, 0) AS INPUT_AMOUNT,
            NULLIF(ii.AMOUNT_FC, 0) AS INPUT_AMOUNT_FC,
            CAST(NULL AS DECIMAL(18,2)) AS IMPORT_TAX,
            CAST(NULL AS DECIMAL(18,2)) AS OTHER_TAX,
            COALESCE(ii.SUMMARY, '') AS SUMMARY,
            CAST(NULL AS DECIMAL(18,2)) AS ALLOCATED_AMOUNT,
            CAST(NULL AS DECIMAL(18,4)) AS OUTPUT_QUANTITY,
            CAST(NULL AS DECIMAL(18,2)) AS OUTPUT_AMOUNT,
            CAST(NULL AS DECIMAL(18,2)) AS OUTPUT_AMOUNT_FC,
            COALESCE(NULLIF(TRIM(source_header.CHIT_NO), ''), NULLIF(TRIM(ii.INVENTORY_CD), ''), '') AS SOURCE_VOUCHER_NO,
            COALESCE(NULLIF(TRIM(source_header.CHIT_TYPE), ''), NULLIF(TRIM(ii.CHIT_TYPE), ''), '') AS SOURCE_VOUCHER_TYPE,
            COALESCE(NULLIF(TRIM(source_vat.VAT_CHIT_NO), ''), NULLIF(TRIM(source_vat.VAT_CHIT_NO_2), ''), NULLIF(TRIM(source_vat.VAT_INVOICE_CD), ''), '') AS INVOICE_NO,
            NULLIF(TRIM(source_vat.VAT_YMD), '') AS INVOICE_DATE,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN debit_account.ACCTITLE_NM_ENG
                WHEN 'KOR' THEN debit_account.ACCTITLE_NM_KOR
                WHEN 'CHN' THEN debit_account.ACCTITLE_NM_CHINA
                WHEN 'CHINA' THEN debit_account.ACCTITLE_NM_CHINA
                ELSE debit_account.ACCTITLE_NM_VIET
            END), ''), NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN credit_account.ACCTITLE_NM_ENG
                WHEN 'KOR' THEN credit_account.ACCTITLE_NM_KOR
                WHEN 'CHN' THEN credit_account.ACCTITLE_NM_CHINA
                WHEN 'CHINA' THEN credit_account.ACCTITLE_NM_CHINA
                ELSE credit_account.ACCTITLE_NM_VIET
            END), ''), '') AS ACCOUNT_NAME,
            COALESCE(DATE_FORMAT(ii.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(source_header.CHIT_YMD), '')) AS TXN_DATE,
            LEFT(COALESCE(DATE_FORMAT(ii.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(source_header.CHIT_YMD), '')), 6) AS TXN_MONTH,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN header_description_eng.DESCRIPTION
                WHEN 'KOR' THEN header_description_kor.DESCRIPTION
                WHEN 'CHN' THEN header_description_china.DESCRIPTION
                WHEN 'CHINA' THEN header_description_china.DESCRIPTION
                ELSE header_description_viet.DESCRIPTION
            END), ''), '') AS DESCRIPTION_1,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN detail_description_eng.DESCRIPTION
                WHEN 'KOR' THEN detail_description_kor.DESCRIPTION
                WHEN 'CHN' THEN detail_description_china.DESCRIPTION
                WHEN 'CHINA' THEN detail_description_china.DESCRIPTION
                ELSE detail_description_viet.DESCRIPTION
            END), ''), '') AS DESCRIPTION_2,
            COALESCE(NULLIF(TRIM(source_detail.DEBIT), ''), '') AS DEBIT_ACCOUNT,
            COALESCE(NULLIF(TRIM(source_detail.CREDIT), ''), '') AS CREDIT_ACCOUNT,
            COALESCE(NULLIF(TRIM(bank_info.BANK_NM), ''), '') AS BANK_NAME,
            COALESCE(NULLIF(TRIM(bank_info.ACCOUNT_NUM), ''), '') AS BANK_ACCOUNT_NO,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN customer_info.CUSTOMER_NM_ENG
                WHEN 'KOR' THEN customer_info.CUSTOMER_NM_KOR
                WHEN 'CHN' THEN customer_info.CUSTOMER_NM_CHINA
                WHEN 'CHINA' THEN customer_info.CUSTOMER_NM_CHINA
                ELSE customer_info.CUSTOMER_NM_VIET
            END), ''), '') AS CUSTOMER_NAME,
            COALESCE(NULLIF(TRIM(customer_ext.TAX_CD), ''), NULLIF(TRIM(customer_ext.IDNUMBER), ''), '') AS CUSTOMER_TAX_CODE,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN cost_object.DEP_NAME_ENG
                WHEN 'KOR' THEN cost_object.DEP_NAME_KOR
                WHEN 'CHN' THEN cost_object.DEP_NAME_CHINA
                WHEN 'CHINA' THEN cost_object.DEP_NAME_CHINA
                ELSE cost_object.DEP_NAME_VIET
            END), ''), '') AS COST_OBJECT,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN manager.MG_DESC_ENG
                WHEN 'KOR' THEN manager.MG_DESC_KOR
                ELSE manager.MG_DESC_VIET
            END), ''), '') AS MANAGER_NAME
        FROM chit_inventory_input ii
        LEFT JOIN chitdetailinfo source_detail
            ON source_detail.COMPANY_CD = ii.COMPANY_CD
           AND source_detail.CHITDETAIL_ID = ii.CHITDETAIL_ID
           AND IFNULL(source_detail.ISDEL, '0') = '0'
        LEFT JOIN chitinfo source_header
            ON source_header.COMPANY_CD = ii.COMPANY_CD
           AND source_header.CHIT_ID = COALESCE(source_detail.CHIT_ID, ii.INVENTORY_ID)
           AND IFNULL(source_header.ISDEL, '0') = '0'
        LEFT JOIN chitdetailinfo_ext detail_ext
            ON detail_ext.COMPANY_CD = ii.COMPANY_CD
           AND detail_ext.CHITDETAIL_ID = ii.CHITDETAIL_ID
           AND IFNULL(detail_ext.ISDEL, '0') = '0'
        LEFT JOIN chitdetailinfo_vat source_vat
            ON source_vat.COMPANY_CD = ii.COMPANY_CD
           AND source_vat.CHITDETAIL_ID = ii.CHITDETAIL_ID
           AND IFNULL(source_vat.ISDEL, '0') = '0'
        LEFT JOIN product_info product
            ON product.COMPANY_CD = ii.COMPANY_CD
           AND product.PRODUCT_ID = ii.PRODUCT_ID
           AND IFNULL(product.ISDEL, '0') = '0'
        LEFT JOIN product_kind product_kind
            ON product_kind.COMPANY_CD = product.COMPANY_CD
           AND product_kind.PRODUCT_KIND_ID = product.PRODUCT_KIND_ID
           AND IFNULL(product_kind.ISDEL, '0') = '0'
        LEFT JOIN product_unit unit_info
            ON unit_info.COMPANY_CD = ii.COMPANY_CD
           AND unit_info.UNIT_ID = ii.UNIT_ID
           AND IFNULL(unit_info.ISDEL, '0') = '0'
        LEFT JOIN store_info store_info
            ON store_info.COMPANY_CD = ii.COMPANY_CD
           AND store_info.STORE_ID = ii.STORE_ID
           AND IFNULL(store_info.ISDEL, '0') = '0'
        LEFT JOIN acclist_info debit_account
            ON debit_account.COMPANY_CD = ii.COMPANY_CD
           AND debit_account.ACC_CD = source_detail.DEBIT
           AND IFNULL(debit_account.ISDEL, '0') = '0'
        LEFT JOIN acclist_info credit_account
            ON credit_account.COMPANY_CD = ii.COMPANY_CD
           AND credit_account.ACC_CD = source_detail.CREDIT
           AND IFNULL(credit_account.ISDEL, '0') = '0'
        LEFT JOIN customer_info customer_info
            ON customer_info.COMPANY_CD = ii.COMPANY_CD
           AND customer_info.CUSTOMER_ID = detail_ext.CUSTOMER_ID
           AND IFNULL(customer_info.ISDEL, '0') = '0'
        LEFT JOIN customer_ext customer_ext
            ON customer_ext.COMPANY_CD = ii.COMPANY_CD
           AND customer_ext.CUSTOMER_ID = detail_ext.CUSTOMER_ID
           AND IFNULL(customer_ext.ISDEL, '0') = '0'
        LEFT JOIN bank_info bank_info
            ON bank_info.COMPANY_CD = ii.COMPANY_CD
           AND bank_info.BANK_ID = detail_ext.BANK_ID
           AND IFNULL(bank_info.ISDEL, '0') = '0'
        LEFT JOIN department_info cost_object
            ON cost_object.COMPANY_CD = ii.COMPANY_CD
           AND cost_object.DEPARTMENT_ID = detail_ext.DEPARTMENT_ID
           AND IFNULL(cost_object.ISDEL, '0') = '0'
        LEFT JOIN management_info manager
            ON manager.COMPANY_CD = ii.COMPANY_CD
           AND manager.MG_CD = detail_ext.MG_CD
           AND IFNULL(manager.ISDEL, '0') = '0'
        LEFT JOIN chitdescriptioninfo header_description_viet
            ON header_description_viet.COMPANY_CD = ii.COMPANY_CD
           AND header_description_viet.CHIT_ID = source_header.CHIT_ID
           AND header_description_viet.LANG_TYPE = 'VIET'
           AND IFNULL(header_description_viet.ISDEL, '0') = '0'
        LEFT JOIN chitdescriptioninfo header_description_eng
            ON header_description_eng.COMPANY_CD = ii.COMPANY_CD
           AND header_description_eng.CHIT_ID = source_header.CHIT_ID
           AND header_description_eng.LANG_TYPE = 'ENG'
           AND IFNULL(header_description_eng.ISDEL, '0') = '0'
        LEFT JOIN chitdescriptioninfo header_description_kor
            ON header_description_kor.COMPANY_CD = ii.COMPANY_CD
           AND header_description_kor.CHIT_ID = source_header.CHIT_ID
           AND header_description_kor.LANG_TYPE = 'KOR'
           AND IFNULL(header_description_kor.ISDEL, '0') = '0'
        LEFT JOIN chitdescriptioninfo header_description_china
            ON header_description_china.COMPANY_CD = ii.COMPANY_CD
           AND header_description_china.CHIT_ID = source_header.CHIT_ID
           AND header_description_china.LANG_TYPE = 'CHINA'
           AND IFNULL(header_description_china.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_description_viet
            ON detail_description_viet.COMPANY_CD = ii.COMPANY_CD
           AND detail_description_viet.CHITDETAIL_ID = ii.CHITDETAIL_ID
           AND detail_description_viet.LANG_TYPE = 'VIET'
           AND IFNULL(detail_description_viet.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_description_eng
            ON detail_description_eng.COMPANY_CD = ii.COMPANY_CD
           AND detail_description_eng.CHITDETAIL_ID = ii.CHITDETAIL_ID
           AND detail_description_eng.LANG_TYPE = 'ENG'
           AND IFNULL(detail_description_eng.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_description_kor
            ON detail_description_kor.COMPANY_CD = ii.COMPANY_CD
           AND detail_description_kor.CHITDETAIL_ID = ii.CHITDETAIL_ID
           AND detail_description_kor.LANG_TYPE = 'KOR'
           AND IFNULL(detail_description_kor.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_description_china
            ON detail_description_china.COMPANY_CD = ii.COMPANY_CD
           AND detail_description_china.CHITDETAIL_ID = ii.CHITDETAIL_ID
           AND detail_description_china.LANG_TYPE = 'CHINA'
           AND IFNULL(detail_description_china.ISDEL, '0') = '0'
        WHERE ii.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(ii.ISDEL, '0') = '0'
          AND COALESCE(DATE_FORMAT(ii.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(source_header.CHIT_YMD), '')) BETWEEN v_from_ymd AND v_to_ymd
          AND (v_product_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(ii.PRODUCT_CD), ''), product.PRODUCT_CD, ''), v_product_cd) > 0)
          AND (v_store_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(ii.STORE_CD), ''), store_info.STORE_CD, ''), v_store_cd) > 0)

        UNION ALL

        SELECT
            CONCAT('OUT:', io.OUTPUT_ID) AS __ROW_KEY,
            2 AS __SIDE_SORT,
            COALESCE(NULLIF(TRIM(io.STORE_CD), ''), store_info.STORE_CD, '') AS STORE_CD,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN product_kind.PRODUCTKIND_NM_ENG
                WHEN 'KOR' THEN product_kind.PRODUCTKIND_NM_KOR
                WHEN 'CHN' THEN product_kind.PRODUCTKIND_NM_CHINA
                WHEN 'CHINA' THEN product_kind.PRODUCTKIND_NM_CHINA
                ELSE product_kind.PRODUCTKIND_NM_VIET
            END), ''), '') AS MATERIAL_GROUP_NAME,
            COALESCE(NULLIF(TRIM(product_kind.PRODUCT_KIND_CD), ''), '') AS MATERIAL_GROUP_CD,
            COALESCE(NULLIF(TRIM(io.PRODUCT_CD), ''), product.PRODUCT_CD, '') AS PRODUCT_CD,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN product.PRODUCT_NM_ENG
                WHEN 'KOR' THEN product.PRODUCT_NM_KOR
                WHEN 'CHN' THEN product.PRODUCT_NM_CHINA
                WHEN 'CHINA' THEN product.PRODUCT_NM_CHINA
                ELSE product.PRODUCT_NM_VIET
            END), ''), io.PRODUCT_CD, '') AS PRODUCT_NAME,
            '' AS FINISHED_PRODUCT_CD,
            CAST(NULL AS DECIMAL(18,4)) AS BOM_QUANTITY,
            COALESCE(NULLIF(TRIM(io.UNIT_CD), ''), unit_info.UNIT_CD, '') AS UNIT_CD,
            NULLIF(io.UNIT_PRICE_CC, 0) AS UNIT_PRICE,
            NULLIF(io.UNIT_PRICE_FC, 0) AS UNIT_PRICE_FC,
            CAST(NULL AS DECIMAL(18,4)) AS INPUT_QUANTITY,
            CAST(NULL AS DECIMAL(18,2)) AS INPUT_AMOUNT,
            CAST(NULL AS DECIMAL(18,2)) AS INPUT_AMOUNT_FC,
            CAST(NULL AS DECIMAL(18,2)) AS IMPORT_TAX,
            CAST(NULL AS DECIMAL(18,2)) AS OTHER_TAX,
            COALESCE(io.SUMMARY, '') AS SUMMARY,
            CAST(NULL AS DECIMAL(18,2)) AS ALLOCATED_AMOUNT,
            NULLIF(io.QUANTITY, 0) AS OUTPUT_QUANTITY,
            NULLIF(CASE
                WHEN IFNULL(io.AMOUNT_CC, 0) <> 0 THEN io.AMOUNT_CC
                ELSE IFNULL(io.QUANTITY, 0) * IFNULL(io.UNIT_PRICE_CC, 0)
            END, 0) AS OUTPUT_AMOUNT,
            NULLIF(io.AMOUNT_FC, 0) AS OUTPUT_AMOUNT_FC,
            COALESCE(NULLIF(TRIM(source_header.CHIT_NO), ''), NULLIF(TRIM(io.INVENTORY_CD), ''), '') AS SOURCE_VOUCHER_NO,
            COALESCE(NULLIF(TRIM(source_header.CHIT_TYPE), ''), NULLIF(TRIM(io.CHIT_TYPE), ''), '') AS SOURCE_VOUCHER_TYPE,
            COALESCE(NULLIF(TRIM(source_vat.VAT_CHIT_NO), ''), NULLIF(TRIM(source_vat.VAT_CHIT_NO_2), ''), NULLIF(TRIM(source_vat.VAT_INVOICE_CD), ''), '') AS INVOICE_NO,
            NULLIF(TRIM(source_vat.VAT_YMD), '') AS INVOICE_DATE,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN debit_account.ACCTITLE_NM_ENG
                WHEN 'KOR' THEN debit_account.ACCTITLE_NM_KOR
                WHEN 'CHN' THEN debit_account.ACCTITLE_NM_CHINA
                WHEN 'CHINA' THEN debit_account.ACCTITLE_NM_CHINA
                ELSE debit_account.ACCTITLE_NM_VIET
            END), ''), NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN credit_account.ACCTITLE_NM_ENG
                WHEN 'KOR' THEN credit_account.ACCTITLE_NM_KOR
                WHEN 'CHN' THEN credit_account.ACCTITLE_NM_CHINA
                WHEN 'CHINA' THEN credit_account.ACCTITLE_NM_CHINA
                ELSE credit_account.ACCTITLE_NM_VIET
            END), ''), '') AS ACCOUNT_NAME,
            COALESCE(DATE_FORMAT(io.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(source_header.CHIT_YMD), '')) AS TXN_DATE,
            LEFT(COALESCE(DATE_FORMAT(io.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(source_header.CHIT_YMD), '')), 6) AS TXN_MONTH,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN header_description_eng.DESCRIPTION
                WHEN 'KOR' THEN header_description_kor.DESCRIPTION
                WHEN 'CHN' THEN header_description_china.DESCRIPTION
                WHEN 'CHINA' THEN header_description_china.DESCRIPTION
                ELSE header_description_viet.DESCRIPTION
            END), ''), '') AS DESCRIPTION_1,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN detail_description_eng.DESCRIPTION
                WHEN 'KOR' THEN detail_description_kor.DESCRIPTION
                WHEN 'CHN' THEN detail_description_china.DESCRIPTION
                WHEN 'CHINA' THEN detail_description_china.DESCRIPTION
                ELSE detail_description_viet.DESCRIPTION
            END), ''), '') AS DESCRIPTION_2,
            COALESCE(NULLIF(TRIM(source_detail.DEBIT), ''), '') AS DEBIT_ACCOUNT,
            COALESCE(NULLIF(TRIM(source_detail.CREDIT), ''), '') AS CREDIT_ACCOUNT,
            COALESCE(NULLIF(TRIM(bank_info.BANK_NM), ''), '') AS BANK_NAME,
            COALESCE(NULLIF(TRIM(bank_info.ACCOUNT_NUM), ''), '') AS BANK_ACCOUNT_NO,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN customer_info.CUSTOMER_NM_ENG
                WHEN 'KOR' THEN customer_info.CUSTOMER_NM_KOR
                WHEN 'CHN' THEN customer_info.CUSTOMER_NM_CHINA
                WHEN 'CHINA' THEN customer_info.CUSTOMER_NM_CHINA
                ELSE customer_info.CUSTOMER_NM_VIET
            END), ''), '') AS CUSTOMER_NAME,
            COALESCE(NULLIF(TRIM(customer_ext.TAX_CD), ''), NULLIF(TRIM(customer_ext.IDNUMBER), ''), '') AS CUSTOMER_TAX_CODE,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN cost_object.DEP_NAME_ENG
                WHEN 'KOR' THEN cost_object.DEP_NAME_KOR
                WHEN 'CHN' THEN cost_object.DEP_NAME_CHINA
                WHEN 'CHINA' THEN cost_object.DEP_NAME_CHINA
                ELSE cost_object.DEP_NAME_VIET
            END), ''), '') AS COST_OBJECT,
            COALESCE(NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN manager.MG_DESC_ENG
                WHEN 'KOR' THEN manager.MG_DESC_KOR
                ELSE manager.MG_DESC_VIET
            END), ''), '') AS MANAGER_NAME
        FROM chit_inventory_output io
        LEFT JOIN chitdetailinfo source_detail
            ON source_detail.COMPANY_CD = io.COMPANY_CD
           AND source_detail.CHITDETAIL_ID = io.CHITDETAIL_ID
           AND IFNULL(source_detail.ISDEL, '0') = '0'
        LEFT JOIN chitinfo source_header
            ON source_header.COMPANY_CD = io.COMPANY_CD
           AND source_header.CHIT_ID = COALESCE(source_detail.CHIT_ID, io.INVENTORY_ID)
           AND IFNULL(source_header.ISDEL, '0') = '0'
        LEFT JOIN chitdetailinfo_ext detail_ext
            ON detail_ext.COMPANY_CD = io.COMPANY_CD
           AND detail_ext.CHITDETAIL_ID = io.CHITDETAIL_ID
           AND IFNULL(detail_ext.ISDEL, '0') = '0'
        LEFT JOIN chitdetailinfo_vat source_vat
            ON source_vat.COMPANY_CD = io.COMPANY_CD
           AND source_vat.CHITDETAIL_ID = io.CHITDETAIL_ID
           AND IFNULL(source_vat.ISDEL, '0') = '0'
        LEFT JOIN product_info product
            ON product.COMPANY_CD = io.COMPANY_CD
           AND product.PRODUCT_ID = io.PRODUCT_ID
           AND IFNULL(product.ISDEL, '0') = '0'
        LEFT JOIN product_kind product_kind
            ON product_kind.COMPANY_CD = product.COMPANY_CD
           AND product_kind.PRODUCT_KIND_ID = product.PRODUCT_KIND_ID
           AND IFNULL(product_kind.ISDEL, '0') = '0'
        LEFT JOIN product_unit unit_info
            ON unit_info.COMPANY_CD = io.COMPANY_CD
           AND unit_info.UNIT_ID = io.UNIT_ID
           AND IFNULL(unit_info.ISDEL, '0') = '0'
        LEFT JOIN store_info store_info
            ON store_info.COMPANY_CD = io.COMPANY_CD
           AND store_info.STORE_ID = io.STORE_ID
           AND IFNULL(store_info.ISDEL, '0') = '0'
        LEFT JOIN acclist_info debit_account
            ON debit_account.COMPANY_CD = io.COMPANY_CD
           AND debit_account.ACC_CD = source_detail.DEBIT
           AND IFNULL(debit_account.ISDEL, '0') = '0'
        LEFT JOIN acclist_info credit_account
            ON credit_account.COMPANY_CD = io.COMPANY_CD
           AND credit_account.ACC_CD = source_detail.CREDIT
           AND IFNULL(credit_account.ISDEL, '0') = '0'
        LEFT JOIN customer_info customer_info
            ON customer_info.COMPANY_CD = io.COMPANY_CD
           AND customer_info.CUSTOMER_ID = detail_ext.CUSTOMER_ID
           AND IFNULL(customer_info.ISDEL, '0') = '0'
        LEFT JOIN customer_ext customer_ext
            ON customer_ext.COMPANY_CD = io.COMPANY_CD
           AND customer_ext.CUSTOMER_ID = detail_ext.CUSTOMER_ID
           AND IFNULL(customer_ext.ISDEL, '0') = '0'
        LEFT JOIN bank_info bank_info
            ON bank_info.COMPANY_CD = io.COMPANY_CD
           AND bank_info.BANK_ID = detail_ext.BANK_ID
           AND IFNULL(bank_info.ISDEL, '0') = '0'
        LEFT JOIN department_info cost_object
            ON cost_object.COMPANY_CD = io.COMPANY_CD
           AND cost_object.DEPARTMENT_ID = detail_ext.DEPARTMENT_ID
           AND IFNULL(cost_object.ISDEL, '0') = '0'
        LEFT JOIN management_info manager
            ON manager.COMPANY_CD = io.COMPANY_CD
           AND manager.MG_CD = detail_ext.MG_CD
           AND IFNULL(manager.ISDEL, '0') = '0'
        LEFT JOIN chitdescriptioninfo header_description_viet
            ON header_description_viet.COMPANY_CD = io.COMPANY_CD
           AND header_description_viet.CHIT_ID = source_header.CHIT_ID
           AND header_description_viet.LANG_TYPE = 'VIET'
           AND IFNULL(header_description_viet.ISDEL, '0') = '0'
        LEFT JOIN chitdescriptioninfo header_description_eng
            ON header_description_eng.COMPANY_CD = io.COMPANY_CD
           AND header_description_eng.CHIT_ID = source_header.CHIT_ID
           AND header_description_eng.LANG_TYPE = 'ENG'
           AND IFNULL(header_description_eng.ISDEL, '0') = '0'
        LEFT JOIN chitdescriptioninfo header_description_kor
            ON header_description_kor.COMPANY_CD = io.COMPANY_CD
           AND header_description_kor.CHIT_ID = source_header.CHIT_ID
           AND header_description_kor.LANG_TYPE = 'KOR'
           AND IFNULL(header_description_kor.ISDEL, '0') = '0'
        LEFT JOIN chitdescriptioninfo header_description_china
            ON header_description_china.COMPANY_CD = io.COMPANY_CD
           AND header_description_china.CHIT_ID = source_header.CHIT_ID
           AND header_description_china.LANG_TYPE = 'CHINA'
           AND IFNULL(header_description_china.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_description_viet
            ON detail_description_viet.COMPANY_CD = io.COMPANY_CD
           AND detail_description_viet.CHITDETAIL_ID = io.CHITDETAIL_ID
           AND detail_description_viet.LANG_TYPE = 'VIET'
           AND IFNULL(detail_description_viet.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_description_eng
            ON detail_description_eng.COMPANY_CD = io.COMPANY_CD
           AND detail_description_eng.CHITDETAIL_ID = io.CHITDETAIL_ID
           AND detail_description_eng.LANG_TYPE = 'ENG'
           AND IFNULL(detail_description_eng.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_description_kor
            ON detail_description_kor.COMPANY_CD = io.COMPANY_CD
           AND detail_description_kor.CHITDETAIL_ID = io.CHITDETAIL_ID
           AND detail_description_kor.LANG_TYPE = 'KOR'
           AND IFNULL(detail_description_kor.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_description_china
            ON detail_description_china.COMPANY_CD = io.COMPANY_CD
           AND detail_description_china.CHITDETAIL_ID = io.CHITDETAIL_ID
           AND detail_description_china.LANG_TYPE = 'CHINA'
           AND IFNULL(detail_description_china.ISDEL, '0') = '0'
        WHERE io.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(io.ISDEL, '0') = '0'
          AND COALESCE(DATE_FORMAT(io.INVENTORY_YMD, '%Y%m%d'), NULLIF(TRIM(source_header.CHIT_YMD), '')) BETWEEN v_from_ymd AND v_to_ymd
          AND (v_product_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(io.PRODUCT_CD), ''), product.PRODUCT_CD, ''), v_product_cd) > 0)
          AND (v_store_cd = '' OR FIND_IN_SET(COALESCE(NULLIF(TRIM(io.STORE_CD), ''), store_info.STORE_CD, ''), v_store_cd) > 0)
    ) report_rows
    ORDER BY
        report_rows.TXN_DATE,
        report_rows.SOURCE_VOUCHER_NO,
        report_rows.__SIDE_SORT,
        report_rows.STORE_CD,
        report_rows.PRODUCT_CD,
        report_rows.__ROW_KEY;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_management_code_book
DROP PROCEDURE IF EXISTS `rpt_management_code_book`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_management_code_book`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_ACCOUNT_CD VARCHAR(1000),
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_language VARCHAR(20);
    DECLARE v_period_text VARCHAR(255);
    DECLARE v_account_cd VARCHAR(1000);

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;

    SET v_from_ymd = DATE_FORMAT(p_FROM_DATE, '%Y%m%d');
    SET v_to_ymd = DATE_FORMAT(p_TO_DATE, '%Y%m%d');
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));
    SET v_account_cd = REPLACE(TRIM(IFNULL(p_ACCOUNT_CD, '')), ' ', '');
    SET v_period_text = CASE
        WHEN YEAR(p_FROM_DATE) = YEAR(p_TO_DATE) AND MONTH(p_FROM_DATE) = MONTH(p_TO_DATE)
        THEN CONCAT('Tháng ', LPAD(MONTH(p_TO_DATE), 2, '0'), ' năm ', YEAR(p_TO_DATE))
        ELSE CONCAT('Từ ngày ', DATE_FORMAT(p_FROM_DATE, '%d/%m/%Y'), ' đến ngày ', DATE_FORMAT(p_TO_DATE, '%d/%m/%Y'))
    END;

    DROP TEMPORARY TABLE IF EXISTS tmp_management_code;
    CREATE TEMPORARY TABLE tmp_management_code
    (
        MG_CD VARCHAR(20) NOT NULL,
        MG_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (MG_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_management_code (MG_CD, MG_NAME)
    SELECT
        management.MG_CD,
        COALESCE(
            NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN management.MG_DESC_ENG
                WHEN 'KOR' THEN management.MG_DESC_KOR
                ELSE management.MG_DESC_VIET
            END), ''),
            NULLIF(TRIM(management.MG_DESC_VIET), ''),
            NULLIF(TRIM(management.MG_DESC_ENG), ''),
            NULLIF(TRIM(management.MG_DESC_KOR), ''),
            management.MG_CD
        )
    FROM management_info management
    INNER JOIN
    (
        SELECT COMPANY_CD, MG_CD, MAX(MG_ID) AS MG_ID
        FROM management_info
        WHERE COMPANY_CD = p_COMPANY_CD
          AND IFNULL(ISDEL, '0') = '0'
          AND TRIM(IFNULL(MG_CD, '')) <> ''
        GROUP BY COMPANY_CD, MG_CD
    ) latest
        ON latest.COMPANY_CD = management.COMPANY_CD
       AND latest.MG_ID = management.MG_ID;

    DROP TEMPORARY TABLE IF EXISTS tmp_management_code_2;
    CREATE TEMPORARY TABLE tmp_management_code_2
    (
        MG_CD VARCHAR(20) NOT NULL,
        MG_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (MG_CD)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_management_code_2 (MG_CD, MG_NAME)
    SELECT MG_CD, MG_NAME FROM tmp_management_code;

    DROP TEMPORARY TABLE IF EXISTS tmp_management_department;
    CREATE TEMPORARY TABLE tmp_management_department
    (
        DEPARTMENT_ID BIGINT NOT NULL DEFAULT 0,
        DEPARTMENT_CD VARCHAR(20) NOT NULL,
        DEPARTMENT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (DEPARTMENT_CD),
        INDEX idx_tmp_management_department_01 (DEPARTMENT_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_management_department (DEPARTMENT_ID, DEPARTMENT_CD, DEPARTMENT_NAME)
    SELECT
        department.DEPARTMENT_ID,
        department.DEPARTMENT_CD,
        COALESCE(
            NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN department.DEP_NAME_ENG
                WHEN 'KOR' THEN department.DEP_NAME_KOR
                WHEN 'CHINA' THEN department.DEP_NAME_CHINA
                ELSE department.DEP_NAME_VIET
            END), ''),
            NULLIF(TRIM(department.DEP_NAME_VIET), ''),
            NULLIF(TRIM(department.DEP_NAME_ENG), ''),
            NULLIF(TRIM(department.DEP_NAME_KOR), ''),
            NULLIF(TRIM(department.DEP_NAME_CHINA), ''),
            department.DEPARTMENT_CD
        )
    FROM department_info department
    INNER JOIN
    (
        SELECT COMPANY_CD, DEPARTMENT_CD, MAX(DEPARTMENT_ID) AS DEPARTMENT_ID
        FROM department_info
        WHERE COMPANY_CD = p_COMPANY_CD
          AND IFNULL(ISDEL, '0') = '0'
          AND TRIM(IFNULL(DEPARTMENT_CD, '')) <> ''
        GROUP BY COMPANY_CD, DEPARTMENT_CD
    ) latest
        ON latest.COMPANY_CD = department.COMPANY_CD
       AND latest.DEPARTMENT_ID = department.DEPARTMENT_ID;

    DROP TEMPORARY TABLE IF EXISTS tmp_management_department_2;
    CREATE TEMPORARY TABLE tmp_management_department_2
    (
        DEPARTMENT_ID BIGINT NOT NULL DEFAULT 0,
        DEPARTMENT_CD VARCHAR(20) NOT NULL,
        DEPARTMENT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (DEPARTMENT_CD),
        INDEX idx_tmp_management_department_02 (DEPARTMENT_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_management_department_2 (DEPARTMENT_ID, DEPARTMENT_CD, DEPARTMENT_NAME)
    SELECT DEPARTMENT_ID, DEPARTMENT_CD, DEPARTMENT_NAME FROM tmp_management_department;

    DROP TEMPORARY TABLE IF EXISTS tmp_management_code_report;
    CREATE TEMPORARY TABLE tmp_management_code_report
    (
        ROW_NO INT NOT NULL AUTO_INCREMENT,
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        REPORT_GROUP_KEY VARCHAR(50) NOT NULL DEFAULT 'MANAGEMENT_CODE',
        REPORT_PERIOD_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        AMOUNT_UNIT_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        ENTRY_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DOCUMENT_NO VARCHAR(50) NOT NULL DEFAULT '',
        DOCUMENT_DATE VARCHAR(20) NOT NULL DEFAULT '',
        DESCRIPTION VARCHAR(1000) NOT NULL DEFAULT '',
        MANAGEMENT_CD VARCHAR(20) NOT NULL DEFAULT '',
        MANAGEMENT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        MANAGEMENT_CD_2 VARCHAR(20) NOT NULL DEFAULT '',
        MANAGEMENT_NAME_2 VARCHAR(255) NOT NULL DEFAULT '',
        DEPARTMENT_CD VARCHAR(20) NOT NULL DEFAULT '',
        DEPARTMENT_NAME VARCHAR(255) NOT NULL DEFAULT '',
        DEBIT_ACCOUNT VARCHAR(20) NOT NULL DEFAULT '',
        CREDIT_ACCOUNT VARCHAR(20) NOT NULL DEFAULT '',
        AMOUNT DECIMAL(18,2) NULL DEFAULT NULL,
        FOREIGN_AMOUNT DECIMAL(18,2) NULL DEFAULT NULL,
        CURRENCY VARCHAR(10) NOT NULL DEFAULT '',
        NOTE_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        SORT_MANAGEMENT_CD VARCHAR(20) NOT NULL DEFAULT '',
        SORT_DEPARTMENT_CD VARCHAR(20) NOT NULL DEFAULT '',
        SORT_YMD VARCHAR(8) NOT NULL DEFAULT '',
        SORT_NO VARCHAR(50) NOT NULL DEFAULT '',
        SORT_CHIT_ID BIGINT NOT NULL DEFAULT 0,
        SORT_DETAIL INT NOT NULL DEFAULT 0,
        PRIMARY KEY (ROW_NO),
        INDEX idx_tmp_management_code_report_01 (SORT_MANAGEMENT_CD, SORT_DEPARTMENT_CD, SORT_YMD, SORT_NO, SORT_CHIT_ID, SORT_DETAIL)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_management_code_report
    (
        COMPANY_CD,
        REPORT_PERIOD_TEXT,
        AMOUNT_UNIT_TEXT,
        ENTRY_DATE,
        DOCUMENT_NO,
        DOCUMENT_DATE,
        DESCRIPTION,
        MANAGEMENT_CD,
        MANAGEMENT_NAME,
        MANAGEMENT_CD_2,
        MANAGEMENT_NAME_2,
        DEPARTMENT_CD,
        DEPARTMENT_NAME,
        DEBIT_ACCOUNT,
        CREDIT_ACCOUNT,
        AMOUNT,
        FOREIGN_AMOUNT,
        CURRENCY,
        NOTE_TEXT,
        SORT_MANAGEMENT_CD,
        SORT_DEPARTMENT_CD,
        SORT_YMD,
        SORT_NO,
        SORT_CHIT_ID,
        SORT_DETAIL
    )
    SELECT
        p_COMPANY_CD,
        v_period_text,
        'Đơn vị tính: Đồng',
        CASE WHEN IFNULL(h.CHIT_YMD, '') REGEXP '^[0-9]{8}$' THEN DATE_FORMAT(STR_TO_DATE(h.CHIT_YMD, '%Y%m%d'), '%d/%m/%Y') ELSE IFNULL(h.CHIT_YMD, '') END,
        COALESCE(NULLIF(TRIM(h.CHIT_NO), ''), NULLIF(TRIM(h.CHIT_CD), ''), ''),
        CASE
            WHEN COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD) REGEXP '^[0-9]{8}$'
            THEN DATE_FORMAT(STR_TO_DATE(COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD), '%Y%m%d'), '%d/%m/%Y')
            ELSE COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD)
        END,
        COALESCE(
            NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN ddesc_en.DESCRIPTION
                WHEN 'KOR' THEN ddesc_ko.DESCRIPTION
                WHEN 'CHINA' THEN ddesc_china.DESCRIPTION
                ELSE ddesc_vi.DESCRIPTION
            END), ''),
            NULLIF(TRIM(CASE v_language
                WHEN 'ENG' THEN hdesc_en.DESCRIPTION
                WHEN 'KOR' THEN hdesc_ko.DESCRIPTION
                WHEN 'CHINA' THEN hdesc_china.DESCRIPTION
                ELSE hdesc_vi.DESCRIPTION
            END), ''),
            NULLIF(TRIM(h.PAYER_INFO), ''),
            ''
        ),
        IFNULL(ext.MG_CD, ''),
        IFNULL(mg1.MG_NAME, ''),
        IFNULL(ext.MG_CD_2, ''),
        IFNULL(mg2.MG_NAME, ''),
        COALESCE(NULLIF(TRIM(ext.DEPARTMENT_CD), ''), NULLIF(department_by_id.DEPARTMENT_CD, ''), ''),
        COALESCE(NULLIF(department_by_cd.DEPARTMENT_NAME, ''), NULLIF(department_by_id.DEPARTMENT_NAME, ''), ''),
        IFNULL(d.DEBIT, ''),
        IFNULL(d.CREDIT, ''),
        NULLIF(IFNULL(d.AMOUNT, 0), 0),
        NULLIF(IFNULL(d.FC_AMOUNT, 0), 0),
        IFNULL(d.FC_TYPE, ''),
        IFNULL(d.CHITDETAIL_CD, ''),
        IFNULL(ext.MG_CD, ''),
        COALESCE(NULLIF(TRIM(ext.DEPARTMENT_CD), ''), NULLIF(department_by_id.DEPARTMENT_CD, ''), ''),
        IFNULL(h.CHIT_YMD, ''),
        IFNULL(h.CHIT_NO, ''),
        IFNULL(h.CHIT_ID, 0),
        IFNULL(d.SORT, 0)
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD
       AND d.CHIT_ID = h.CHIT_ID
       AND IFNULL(d.ISDEL, '0') = '0'
    LEFT JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = d.COMPANY_CD
       AND ext.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN tmp_management_code mg1
        ON mg1.MG_CD = ext.MG_CD
    LEFT JOIN tmp_management_code_2 mg2
        ON mg2.MG_CD = ext.MG_CD_2
    LEFT JOIN tmp_management_department department_by_cd
        ON department_by_cd.DEPARTMENT_CD = ext.DEPARTMENT_CD
    LEFT JOIN tmp_management_department_2 department_by_id
        ON department_by_id.DEPARTMENT_ID = IFNULL(ext.DEPARTMENT_ID, 0)
    LEFT JOIN chitdescriptioninfo hdesc_vi
        ON hdesc_vi.COMPANY_CD = h.COMPANY_CD
       AND hdesc_vi.CHIT_ID = h.CHIT_ID
       AND hdesc_vi.LANG_TYPE = 'VIET'
       AND IFNULL(hdesc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_en
        ON hdesc_en.COMPANY_CD = h.COMPANY_CD
       AND hdesc_en.CHIT_ID = h.CHIT_ID
       AND hdesc_en.LANG_TYPE = 'ENG'
       AND IFNULL(hdesc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_ko
        ON hdesc_ko.COMPANY_CD = h.COMPANY_CD
       AND hdesc_ko.CHIT_ID = h.CHIT_ID
       AND hdesc_ko.LANG_TYPE = 'KOR'
       AND IFNULL(hdesc_ko.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_china
        ON hdesc_china.COMPANY_CD = h.COMPANY_CD
       AND hdesc_china.CHIT_ID = h.CHIT_ID
       AND hdesc_china.LANG_TYPE = 'CHINA'
       AND IFNULL(hdesc_china.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_vi
        ON ddesc_vi.COMPANY_CD = d.COMPANY_CD
       AND ddesc_vi.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND ddesc_vi.LANG_TYPE = 'VIET'
       AND IFNULL(ddesc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_en
        ON ddesc_en.COMPANY_CD = d.COMPANY_CD
       AND ddesc_en.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND ddesc_en.LANG_TYPE = 'ENG'
       AND IFNULL(ddesc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_ko
        ON ddesc_ko.COMPANY_CD = d.COMPANY_CD
       AND ddesc_ko.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND ddesc_ko.LANG_TYPE = 'KOR'
       AND IFNULL(ddesc_ko.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_china
        ON ddesc_china.COMPANY_CD = d.COMPANY_CD
       AND ddesc_china.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND ddesc_china.LANG_TYPE = 'CHINA'
       AND IFNULL(ddesc_china.ISDEL, '0') = '0'
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(h.ISDEL, '0') = '0'
      AND IFNULL(h.CHIT_YMD, '') >= v_from_ymd
      AND IFNULL(h.CHIT_YMD, '') <= v_to_ymd
      AND IFNULL(d.AMOUNT, 0) <> 0
      AND (
          v_account_cd = ''
          OR FIND_IN_SET(IFNULL(d.DEBIT, ''), v_account_cd) > 0
          OR FIND_IN_SET(IFNULL(d.CREDIT, ''), v_account_cd) > 0
      )
      AND (
          TRIM(IFNULL(ext.MG_CD, '')) <> ''
          OR TRIM(IFNULL(ext.MG_CD_2, '')) <> ''
          OR TRIM(IFNULL(ext.DEPARTMENT_CD, '')) <> ''
          OR IFNULL(ext.DEPARTMENT_ID, 0) > 0
      );

    SELECT
        COMPANY_CD,
        REPORT_GROUP_KEY,
        REPORT_PERIOD_TEXT,
        AMOUNT_UNIT_TEXT,
        ENTRY_DATE,
        DOCUMENT_NO,
        DOCUMENT_DATE,
        DESCRIPTION,
        MANAGEMENT_CD,
        MANAGEMENT_NAME,
        MANAGEMENT_CD_2,
        MANAGEMENT_NAME_2,
        DEPARTMENT_CD,
        DEPARTMENT_NAME,
        DEBIT_ACCOUNT,
        CREDIT_ACCOUNT,
        AMOUNT,
        FOREIGN_AMOUNT,
        CURRENCY,
        NOTE_TEXT
    FROM tmp_management_code_report
    ORDER BY SORT_MANAGEMENT_CD, SORT_DEPARTMENT_CD, SORT_YMD, SORT_NO, SORT_CHIT_ID, SORT_DETAIL, ROW_NO;

    DROP TEMPORARY TABLE IF EXISTS tmp_management_code_report;
    DROP TEMPORARY TABLE IF EXISTS tmp_management_department;
    DROP TEMPORARY TABLE IF EXISTS tmp_management_department_2;
    DROP TEMPORARY TABLE IF EXISTS tmp_management_code_2;
    DROP TEMPORARY TABLE IF EXISTS tmp_management_code;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_payment_voucher
DROP PROCEDURE IF EXISTS `rpt_payment_voucher`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_payment_voucher`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHIT_ID BIGINT,
    IN p_CHIT_IDS TEXT,
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_chit_ids TEXT;
    DECLARE v_language VARCHAR(20);

    SET v_chit_ids = REPLACE(REPLACE(REPLACE(REPLACE(IFNULL(TRIM(p_CHIT_IDS), ''), '|', ','), ';', ','), CHAR(10), ','), CHAR(13), ',');
    SET v_chit_ids = IF(v_chit_ids = '' AND IFNULL(p_CHIT_ID, 0) > 0, CAST(p_CHIT_ID AS CHAR), v_chit_ids);
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));

    SELECT
        h.CHIT_ID,
        h.COMPANY_CD,
        h.CHIT_CD,
        h.CHIT_NO,
        h.CHIT_YMD,
        h.CHIT_YMD AS HEADER_DATE_TEXT,
        h.CHIT_YMD AS SIGNATURE_DATE_TEXT,
        COALESCE(NULLIF(TRIM(h.PAYER_INFO), ''), detail.CUSTOMER_NAME, '') AS PARTNER_NAME,
        '' AS PARTNER_ADDRESS,
        COALESCE(
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN desc_en.DESCRIPTION WHEN 'KOR' THEN desc_ko.DESCRIPTION ELSE desc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(ext.NOTE), ''),
            detail.DETAIL_DESCRIPTION,
            ''
        ) AS REASON,
        IFNULL(h.AMOUNT, IFNULL(detail.DETAIL_AMOUNT, 0)) AS AMOUNT,
        NULL AS AMOUNT_TEXT,
        NULL AS AMOUNT_IN_WORDS,
        CASE WHEN IFNULL(detail.FC_TYPE, '') <> '' AND IFNULL(detail.FC_AMOUNT, 0) > 0 THEN detail.FC_AMOUNT ELSE NULL END AS FC_AMOUNT,
        CASE WHEN IFNULL(detail.FC_TYPE, '') <> '' AND IFNULL(detail.FC_AMOUNT, 0) > 0 THEN detail.FC_TYPE ELSE NULL END AS FC_TYPE,
        CASE WHEN IFNULL(detail.FC_TYPE, '') <> '' AND IFNULL(detail.FC_RATE, 0) > 0 THEN detail.FC_RATE ELSE NULL END AS FC_RATE,
        NULL AS EXCHANGE_RATE_TEXT,
        NULL AS CONVERTED_AMOUNT_TEXT,
        IFNULL(detail.DEBIT_ACCOUNT, '') AS DEBIT_ACCOUNT,
        IFNULL(detail.CREDIT_ACCOUNT, '') AS CREDIT_ACCOUNT,
        IFNULL(detail.DETAIL_COUNT, 0) AS DETAIL_COUNT,
        NULL AS ATTACHMENT_TEXT,
        NULL AS REFERENCE_TEXT,
        IFNULL(ext.NOTE, '') AS NOTE,
        NULL AS NOTE_TEXT,
        COALESCE(NULLIF(TRIM(h.UPDATE_BY), ''), NULLIF(TRIM(h.CREATE_BY), ''), '') AS CREATE_BY
    FROM chitinfo h
    LEFT JOIN chitinfo_ext ext ON ext.COMPANY_CD = h.COMPANY_CD AND ext.CHIT_ID = h.CHIT_ID AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo desc_vi ON desc_vi.COMPANY_CD = h.COMPANY_CD AND desc_vi.CHIT_ID = h.CHIT_ID AND desc_vi.LANG_TYPE = 'VIET' AND IFNULL(desc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo desc_en ON desc_en.COMPANY_CD = h.COMPANY_CD AND desc_en.CHIT_ID = h.CHIT_ID AND desc_en.LANG_TYPE = 'ENG' AND IFNULL(desc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo desc_ko ON desc_ko.COMPANY_CD = h.COMPANY_CD AND desc_ko.CHIT_ID = h.CHIT_ID AND desc_ko.LANG_TYPE = 'KOR' AND IFNULL(desc_ko.ISDEL, '0') = '0'
    LEFT JOIN (
        SELECT
            d.CHIT_ID,
            COUNT(*) AS DETAIL_COUNT,
            SUM(IFNULL(d.AMOUNT, 0)) AS DETAIL_AMOUNT,
            SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(UPPER(TRIM(IFNULL(d.FC_TYPE, ''))), '') ORDER BY IFNULL(d.SORT, 0), d.CHITDETAIL_ID SEPARATOR ','), ',', 1) AS FC_TYPE,
            SUM(IFNULL(d.FC_AMOUNT, 0)) AS FC_AMOUNT,
            MAX(CASE WHEN IFNULL(d.FC_RATE, 0) > 0 THEN d.FC_RATE ELSE 0 END) AS FC_RATE,
            GROUP_CONCAT(DISTINCT NULLIF(TRIM(d.DEBIT), '') ORDER BY d.DEBIT SEPARATOR ', ') AS DEBIT_ACCOUNT,
            GROUP_CONCAT(DISTINCT NULLIF(TRIM(d.CREDIT), '') ORDER BY d.CREDIT SEPARATOR ', ') AS CREDIT_ACCOUNT,
            SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(COALESCE(customer.CUSTOMER_NM_VIET, '')), '') ORDER BY IFNULL(d.SORT, 0), d.CHITDETAIL_ID SEPARATOR '\n'), '\n', 1) AS CUSTOMER_NAME,
            SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(COALESCE(detail_desc_vi.DESCRIPTION, detail_desc_en.DESCRIPTION, detail_desc_ko.DESCRIPTION, '')), '') ORDER BY IFNULL(d.SORT, 0), d.CHITDETAIL_ID SEPARATOR '\n'), '\n', 1) AS DETAIL_DESCRIPTION
        FROM chitdetailinfo d
        LEFT JOIN chitdetailinfo_ext ext ON ext.COMPANY_CD = d.COMPANY_CD AND ext.CHITDETAIL_ID = d.CHITDETAIL_ID AND IFNULL(ext.ISDEL, '0') = '0'
        LEFT JOIN customer_info customer ON customer.COMPANY_CD = ext.COMPANY_CD AND customer.CUSTOMER_ID = ext.CUSTOMER_ID AND IFNULL(customer.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_desc_vi ON detail_desc_vi.COMPANY_CD = d.COMPANY_CD AND detail_desc_vi.CHITDETAIL_ID = d.CHITDETAIL_ID AND detail_desc_vi.LANG_TYPE = 'VIET' AND IFNULL(detail_desc_vi.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_desc_en ON detail_desc_en.COMPANY_CD = d.COMPANY_CD AND detail_desc_en.CHITDETAIL_ID = d.CHITDETAIL_ID AND detail_desc_en.LANG_TYPE = 'ENG' AND IFNULL(detail_desc_en.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_desc_ko ON detail_desc_ko.COMPANY_CD = d.COMPANY_CD AND detail_desc_ko.CHITDETAIL_ID = d.CHITDETAIL_ID AND detail_desc_ko.LANG_TYPE = 'KOR' AND IFNULL(detail_desc_ko.ISDEL, '0') = '0'
        WHERE d.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(d.ISDEL, '0') = '0'
        GROUP BY d.CHIT_ID
    ) detail ON detail.CHIT_ID = h.CHIT_ID
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'AP'
      AND h.CHIT_TYPE = 'PM'
      AND IFNULL(h.ISDEL, '0') = '0'
      AND v_chit_ids <> ''
      AND FIND_IN_SET(CAST(h.CHIT_ID AS CHAR) COLLATE utf8_unicode_ci, v_chit_ids COLLATE utf8_unicode_ci) > 0
    ORDER BY h.CHIT_YMD, h.CHIT_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_pl_by_object
DROP PROCEDURE IF EXISTS `rpt_pl_by_object`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_pl_by_object`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    SELECT
        h.COMPANY_CD,
        CONCAT(DATE_FORMAT(p_FROM_DATE, '%d/%m/%Y'), '-', DATE_FORMAT(p_TO_DATE, '%d/%m/%Y')) AS REPORT_PERIOD_TEXT,
        'Đơn vị : VND' AS AMOUNT_UNIT_TEXT,
        CASE
            WHEN IFNULL(h.CHIT_YMD, '') REGEXP '^[0-9]{8}$' THEN DATE_FORMAT(STR_TO_DATE(h.CHIT_YMD, '%Y%m%d'), '%d/%m/%Y')
            ELSE IFNULL(h.CHIT_YMD, '')
        END AS TRANSACTION_DATE,
        COALESCE(NULLIF(TRIM(ext.DEPARTMENT_CD), ''), NULLIF(TRIM(department_by_id.DEPARTMENT_CD), ''), '') AS COST_OBJECT_CD,
        COALESCE(
            NULLIF(TRIM(CASE UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')))
                WHEN 'ENG' THEN department_by_cd.DEP_NAME_ENG
                WHEN 'KOR' THEN department_by_cd.DEP_NAME_KOR
                WHEN 'CHINA' THEN department_by_cd.DEP_NAME_CHINA
                ELSE department_by_cd.DEP_NAME_VIET
            END), ''),
            NULLIF(TRIM(CASE UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')))
                WHEN 'ENG' THEN department_by_id.DEP_NAME_ENG
                WHEN 'KOR' THEN department_by_id.DEP_NAME_KOR
                WHEN 'CHINA' THEN department_by_id.DEP_NAME_CHINA
                ELSE department_by_id.DEP_NAME_VIET
            END), ''),
            NULLIF(TRIM(department_by_cd.DEP_NAME_VIET), ''),
            NULLIF(TRIM(department_by_id.DEP_NAME_VIET), ''),
            NULLIF(TRIM(ext.DEPARTMENT_CD), ''),
            ''
        ) AS COST_OBJECT_NAME,
        COALESCE(NULLIF(TRIM(ext.CUSTOMER_CD), ''), NULLIF(TRIM(customer_by_id.CUSTOMER_CD), ''), '') AS CUSTOMER_CD,
        TRIM(IFNULL(ext.CUSTOMER_OWN_CD, '')) AS CUSTOMER_OWN_CD,
        COALESCE(
            NULLIF(TRIM(CASE UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')))
                WHEN 'ENG' THEN customer_by_id.CUSTOMER_NM_ENG
                WHEN 'KOR' THEN customer_by_id.CUSTOMER_NM_KOR
                WHEN 'CHINA' THEN customer_by_id.CUSTOMER_NM_CHINA
                ELSE customer_by_id.CUSTOMER_NM_VIET
            END), ''),
            NULLIF(TRIM(CASE UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')))
                WHEN 'ENG' THEN customer_by_cd.CUSTOMER_NM_ENG
                WHEN 'KOR' THEN customer_by_cd.CUSTOMER_NM_KOR
                WHEN 'CHINA' THEN customer_by_cd.CUSTOMER_NM_CHINA
                ELSE customer_by_cd.CUSTOMER_NM_VIET
            END), ''),
            NULLIF(TRIM(customer_by_id.CUSTOMER_NM_VIET), ''),
            NULLIF(TRIM(customer_by_cd.CUSTOMER_NM_VIET), ''),
            NULLIF(TRIM(ext.CUSTOMER_CD), ''),
            ''
        ) AS CUSTOMER_NAME,
        COALESCE(NULLIF(TRIM(h.CHIT_NO), ''), NULLIF(TRIM(h.CHIT_CD), ''), '') AS DOCUMENT_NO,
        COALESCE(NULLIF(TRIM(vat.VAT_CHIT_NO), ''), NULLIF(TRIM(vat.VAT_CHIT_NO_2), ''), NULLIF(TRIM(vat.VAT_INVOICE_CD), ''), '') AS INVOICE_NO,
        CASE
            WHEN IFNULL(vat.VAT_YMD, '') REGEXP '^[0-9]{8}$' THEN DATE_FORMAT(STR_TO_DATE(vat.VAT_YMD, '%Y%m%d'), '%d/%m/%Y')
            ELSE IFNULL(vat.VAT_YMD, '')
        END AS INVOICE_DATE,
        NULLIF(IFNULL(d.FC_AMOUNT, 0), 0) AS FC_AMOUNT,
        COALESCE(
            NULLIF(TRIM(CASE UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')))
                WHEN 'ENG' THEN ddesc_en.DESCRIPTION
                WHEN 'KOR' THEN ddesc_ko.DESCRIPTION
                WHEN 'CHINA' THEN ddesc_china.DESCRIPTION
                ELSE ddesc_vi.DESCRIPTION
            END), ''),
            ''
        ) AS DESCRIPTION_1,
        COALESCE(
            NULLIF(TRIM(CASE UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')))
                WHEN 'ENG' THEN hdesc_en.DESCRIPTION
                WHEN 'KOR' THEN hdesc_ko.DESCRIPTION
                WHEN 'CHINA' THEN hdesc_china.DESCRIPTION
                ELSE hdesc_vi.DESCRIPTION
            END), ''),
            NULLIF(TRIM(h.PAYER_INFO), ''),
            ''
        ) AS DESCRIPTION_2,
        IFNULL(d.DEBIT, '') AS DEBIT_ACCOUNT,
        COALESCE(
            NULLIF(TRIM(CASE UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')))
                WHEN 'ENG' THEN debit_account.ACCTITLE_NM_ENG
                WHEN 'KOR' THEN debit_account.ACCTITLE_NM_KOR
                WHEN 'CHINA' THEN debit_account.ACCTITLE_NM_CHINA
                ELSE debit_account.ACCTITLE_NM_VIET
            END), ''),
            NULLIF(TRIM(debit_account.ACCTITLE_NM_VIET), ''),
            IFNULL(d.DEBIT, '')
        ) AS DEBIT_ACCOUNT_NAME,
        IFNULL(d.CREDIT, '') AS CREDIT_ACCOUNT,
        COALESCE(
            NULLIF(TRIM(CASE UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')))
                WHEN 'ENG' THEN credit_account.ACCTITLE_NM_ENG
                WHEN 'KOR' THEN credit_account.ACCTITLE_NM_KOR
                WHEN 'CHINA' THEN credit_account.ACCTITLE_NM_CHINA
                ELSE credit_account.ACCTITLE_NM_VIET
            END), ''),
            NULLIF(TRIM(credit_account.ACCTITLE_NM_VIET), ''),
            IFNULL(d.CREDIT, '')
        ) AS CREDIT_ACCOUNT_NAME,
        CAST(NULL AS DECIMAL(18,2)) AS REVENUE_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS REVENUE_DEDUCTION_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS OTHER_REVENUE_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS MATERIAL_COST_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS LABOR_COST_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS MACHINE_COST_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS OVERHEAD_COST_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS TOTAL_COST_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS COST_REDUCTION_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS COGS_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS SELLING_COST_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS ADMIN_COST_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS OTHER_COST_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS PROFIT_LOSS_AMOUNT
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD
       AND d.CHIT_ID = h.CHIT_ID
       AND IFNULL(d.ISDEL, '0') = '0'
    LEFT JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = d.COMPANY_CD
       AND ext.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN chitdetailinfo_vat vat
        ON vat.COMPANY_CD = d.COMPANY_CD
       AND vat.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND IFNULL(vat.ISDEL, '0') = '0'
    LEFT JOIN department_info department_by_id
        ON department_by_id.COMPANY_CD = h.COMPANY_CD
       AND department_by_id.DEPARTMENT_ID = ext.DEPARTMENT_ID
       AND IFNULL(department_by_id.ISDEL, '0') = '0'
    LEFT JOIN department_info department_by_cd
        ON department_by_cd.COMPANY_CD = h.COMPANY_CD
       AND department_by_cd.DEPARTMENT_CD = ext.DEPARTMENT_CD
       AND IFNULL(department_by_cd.ISDEL, '0') = '0'
    LEFT JOIN customer_info customer_by_id
        ON customer_by_id.COMPANY_CD = h.COMPANY_CD
       AND customer_by_id.CUSTOMER_ID = ext.CUSTOMER_ID
       AND IFNULL(customer_by_id.ISDEL, '0') = '0'
    LEFT JOIN (
        SELECT COMPANY_CD, CUSTOMER_CD, MAX(CUSTOMER_ID) AS CUSTOMER_ID
        FROM customer_info
        WHERE IFNULL(ISDEL, '0') = '0'
        GROUP BY COMPANY_CD, CUSTOMER_CD
    ) customer_cd_latest
        ON customer_cd_latest.COMPANY_CD = h.COMPANY_CD
       AND customer_cd_latest.CUSTOMER_CD = ext.CUSTOMER_CD
    LEFT JOIN customer_info customer_by_cd
        ON customer_by_cd.COMPANY_CD = customer_cd_latest.COMPANY_CD
       AND customer_by_cd.CUSTOMER_ID = customer_cd_latest.CUSTOMER_ID
    LEFT JOIN (
        SELECT COMPANY_CD, ACC_CD, MAX(ACC_ID) AS ACC_ID
        FROM acclist_info
        WHERE IFNULL(ISDEL, '0') = '0'
        GROUP BY COMPANY_CD, ACC_CD
    ) debit_account_latest
        ON debit_account_latest.COMPANY_CD = h.COMPANY_CD
       AND debit_account_latest.ACC_CD = d.DEBIT
    LEFT JOIN acclist_info debit_account
        ON debit_account.COMPANY_CD = debit_account_latest.COMPANY_CD
       AND debit_account.ACC_ID = debit_account_latest.ACC_ID
    LEFT JOIN (
        SELECT COMPANY_CD, ACC_CD, MAX(ACC_ID) AS ACC_ID
        FROM acclist_info
        WHERE IFNULL(ISDEL, '0') = '0'
        GROUP BY COMPANY_CD, ACC_CD
    ) credit_account_latest
        ON credit_account_latest.COMPANY_CD = h.COMPANY_CD
       AND credit_account_latest.ACC_CD = d.CREDIT
    LEFT JOIN acclist_info credit_account
        ON credit_account.COMPANY_CD = credit_account_latest.COMPANY_CD
       AND credit_account.ACC_ID = credit_account_latest.ACC_ID
    LEFT JOIN chitdescriptioninfo hdesc_vi
        ON hdesc_vi.COMPANY_CD = h.COMPANY_CD
       AND hdesc_vi.CHIT_ID = h.CHIT_ID
       AND hdesc_vi.LANG_TYPE = 'VIET'
       AND IFNULL(hdesc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_en
        ON hdesc_en.COMPANY_CD = h.COMPANY_CD
       AND hdesc_en.CHIT_ID = h.CHIT_ID
       AND hdesc_en.LANG_TYPE = 'ENG'
       AND IFNULL(hdesc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_ko
        ON hdesc_ko.COMPANY_CD = h.COMPANY_CD
       AND hdesc_ko.CHIT_ID = h.CHIT_ID
       AND hdesc_ko.LANG_TYPE = 'KOR'
       AND IFNULL(hdesc_ko.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo hdesc_china
        ON hdesc_china.COMPANY_CD = h.COMPANY_CD
       AND hdesc_china.CHIT_ID = h.CHIT_ID
       AND hdesc_china.LANG_TYPE = 'CHINA'
       AND IFNULL(hdesc_china.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_vi
        ON ddesc_vi.COMPANY_CD = d.COMPANY_CD
       AND ddesc_vi.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND ddesc_vi.LANG_TYPE = 'VIET'
       AND IFNULL(ddesc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_en
        ON ddesc_en.COMPANY_CD = d.COMPANY_CD
       AND ddesc_en.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND ddesc_en.LANG_TYPE = 'ENG'
       AND IFNULL(ddesc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_ko
        ON ddesc_ko.COMPANY_CD = d.COMPANY_CD
       AND ddesc_ko.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND ddesc_ko.LANG_TYPE = 'KOR'
       AND IFNULL(ddesc_ko.ISDEL, '0') = '0'
    LEFT JOIN chitdetaildescriptioninfo ddesc_china
        ON ddesc_china.COMPANY_CD = d.COMPANY_CD
       AND ddesc_china.CHITDETAIL_ID = d.CHITDETAIL_ID
       AND ddesc_china.LANG_TYPE = 'CHINA'
       AND IFNULL(ddesc_china.ISDEL, '0') = '0'
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(h.ISDEL, '0') = '0'
      AND (p_FROM_DATE IS NULL OR IFNULL(h.CHIT_YMD, '') >= DATE_FORMAT(p_FROM_DATE, '%Y%m%d'))
      AND (p_TO_DATE IS NULL OR IFNULL(h.CHIT_YMD, '') <= DATE_FORMAT(p_TO_DATE, '%Y%m%d'))
      AND (TRIM(IFNULL(ext.DEPARTMENT_CD, '')) <> '' OR IFNULL(ext.DEPARTMENT_ID, 0) > 0)
    ORDER BY ext.DEPARTMENT_CD, h.CHIT_YMD, h.CHIT_NO, h.CHIT_ID, d.SORT, d.CHITDETAIL_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_pl_summary
DROP PROCEDURE IF EXISTS `rpt_pl_summary`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_pl_summary`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    SELECT
        cost_center.COMPANY_CD,
        CONCAT(DATE_FORMAT(p_FROM_DATE, '%d/%m/%Y'), '-', DATE_FORMAT(p_TO_DATE, '%d/%m/%Y')) AS REPORT_PERIOD_TEXT,
        'Đơn vị : VND' AS AMOUNT_UNIT_TEXT,
        cost_center.DEPARTMENT_CD AS COST_OBJECT_CD,
        COALESCE(
            NULLIF(TRIM(CASE UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')))
                WHEN 'ENG' THEN cost_center.DEP_NAME_ENG
                WHEN 'KOR' THEN cost_center.DEP_NAME_KOR
                WHEN 'CHINA' THEN cost_center.DEP_NAME_CHINA
                ELSE cost_center.DEP_NAME_VIET
            END), ''),
            NULLIF(TRIM(cost_center.DEP_NAME_VIET), ''),
            NULLIF(TRIM(cost_center.DEP_NAME_ENG), ''),
            NULLIF(TRIM(cost_center.DEP_NAME_KOR), ''),
            NULLIF(TRIM(cost_center.DEP_NAME_CHINA), ''),
            cost_center.DEPARTMENT_CD
        ) AS COST_OBJECT_NAME,
        CAST(NULL AS DECIMAL(18,2)) AS REVENUE_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS REVENUE_DEDUCTION_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS OTHER_REVENUE_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS MATERIAL_COST_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS LABOR_COST_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS MACHINE_COST_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS OVERHEAD_COST_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS COGS_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS SELLING_COST_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS ADMIN_COST_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS OTHER_COST_AMOUNT,
        CAST(NULL AS DECIMAL(18,2)) AS PROFIT_LOSS_AMOUNT
    FROM department_info cost_center
    WHERE cost_center.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(cost_center.ISDEL, '0') = '0'
      AND TRIM(IFNULL(cost_center.DEPARTMENT_CD, '')) <> ''
    ORDER BY cost_center.DEPARTMENT_CD, cost_center.DEPARTMENT_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_profit_loss_b02dn
DROP PROCEDURE IF EXISTS `rpt_profit_loss_b02dn`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_profit_loss_b02dn`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_REPORT_VERSION VARCHAR(20),
    IN p_UNIT_DIVISOR DECIMAL(18,6),
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_from_date DATE;
    DECLARE v_to_date DATE;
    DECLARE v_previous_from_date DATE;
    DECLARE v_previous_to_date DATE;
    DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_previous_from_ymd VARCHAR(8);
    DECLARE v_previous_to_ymd VARCHAR(8);
    DECLARE v_report_version VARCHAR(20);
    DECLARE v_template_company_cd VARCHAR(20);
    DECLARE v_unit_divisor DECIMAL(18,6);
    DECLARE v_iteration INT DEFAULT 0;
    DECLARE v_changed_rows INT DEFAULT 0;
    DECLARE v_language VARCHAR(20);

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;

    SET v_from_date = p_FROM_DATE;
    SET v_to_date = p_TO_DATE;
    SET v_previous_from_date = DATE_SUB(v_from_date, INTERVAL 1 YEAR);
    SET v_previous_to_date = DATE_SUB(v_to_date, INTERVAL 1 YEAR);
    SET v_from_ymd = DATE_FORMAT(v_from_date, '%Y%m%d');
    SET v_to_ymd = DATE_FORMAT(v_to_date, '%Y%m%d');
    SET v_previous_from_ymd = DATE_FORMAT(v_previous_from_date, '%Y%m%d');
    SET v_previous_to_ymd = DATE_FORMAT(v_previous_to_date, '%Y%m%d');
    SET v_report_version = IFNULL(NULLIF(TRIM(IFNULL(p_REPORT_VERSION, '')), ''), '2025');
    SET v_unit_divisor = CASE WHEN IFNULL(p_UNIT_DIVISOR, 0) = 0 THEN 1 ELSE p_UNIT_DIVISOR END;
    SET v_language = UPPER(IFNULL(NULLIF(TRIM(p_LANGUAGE), ''), 'VIET'));

    SELECT COALESCE(
        (
            SELECT template.COMPANY_CD
            FROM report_B02DN template
            WHERE template.REPORT_CODE = 'B02_DN'
              AND template.REPORT_VERSION = v_report_version
              AND template.COMPANY_CD IN (p_COMPANY_CD, '')
              AND IFNULL(template.ISDEL, '0') = '0'
            ORDER BY CASE
                WHEN template.COMPANY_CD = p_COMPANY_CD THEN 0
                ELSE 1
            END
            LIMIT 1
        ),
        ''
    )
    INTO v_template_company_cd;

    DROP TEMPORARY TABLE IF EXISTS tmp_b02_numbers;
    CREATE TEMPORARY TABLE tmp_b02_numbers
    (
        N INT NOT NULL,
        PRIMARY KEY (N)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b02_numbers (N)
    SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5
    UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10
    UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15
    UNION ALL SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL SELECT 20
    UNION ALL SELECT 21 UNION ALL SELECT 22 UNION ALL SELECT 23 UNION ALL SELECT 24 UNION ALL SELECT 25
    UNION ALL SELECT 26 UNION ALL SELECT 27 UNION ALL SELECT 28 UNION ALL SELECT 29 UNION ALL SELECT 30
    UNION ALL SELECT 31 UNION ALL SELECT 32 UNION ALL SELECT 33 UNION ALL SELECT 34 UNION ALL SELECT 35
    UNION ALL SELECT 36 UNION ALL SELECT 37 UNION ALL SELECT 38 UNION ALL SELECT 39 UNION ALL SELECT 40;

    DROP TEMPORARY TABLE IF EXISTS tmp_b02_rule;
    CREATE TEMPORARY TABLE tmp_b02_rule
    (
        ITEM_CODE VARCHAR(20) NOT NULL,
        ACC_PREFIX VARCHAR(20) NOT NULL,
        CALC_METHOD VARCHAR(30) NOT NULL,
        INDEX idx_tmp_b02_rule_01 (ITEM_CODE, ACC_PREFIX)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b02_rule (ITEM_CODE, ACC_PREFIX, CALC_METHOD)
    SELECT
        template.ITEM_CODE,
        TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(IFNULL(template.ACCOUNT_RULE, ''), ',', numbers.N), ',', -1)),
        template.CALC_METHOD
    FROM report_B02DN template
    INNER JOIN tmp_b02_numbers numbers
        ON numbers.N <= 1 + LENGTH(IFNULL(template.ACCOUNT_RULE, '')) - LENGTH(REPLACE(IFNULL(template.ACCOUNT_RULE, ''), ',', ''))
    WHERE template.COMPANY_CD = v_template_company_cd
      AND template.REPORT_CODE = 'B02_DN'
      AND template.REPORT_VERSION = v_report_version
      AND template.SECTION_TYPE = 'DETAIL'
      AND IFNULL(template.DATA_SOURCE_TYPE, '') = 'ACCOUNT_RULE'
      AND IFNULL(template.ACCOUNT_RULE, '') <> ''
      AND TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(IFNULL(template.ACCOUNT_RULE, ''), ',', numbers.N), ',', -1)) <> '';

    /*
        Tá»‘i Æ°u phÃ¡t sinh:
        - KhÃ´ng insert tá»«ng dÃ²ng vÃ o báº£ng táº¡m phÃ¡t sinh.
        - Lá»c trá»±c tiáº¿p h.CHIT_YMD Ä‘á»ƒ MySQL dÃ¹ng index ngÃ y.
        - Aggregate trá»±c tiáº¿p theo ACC_CD + PERIOD_TYPE.
    */
    DROP TEMPORARY TABLE IF EXISTS tmp_b02_account_turnover;
    CREATE TEMPORARY TABLE tmp_b02_account_turnover
    (
        ACC_CD VARCHAR(20) NOT NULL,
        PERIOD_TYPE VARCHAR(20) NOT NULL,
        DEBIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        CREDIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (ACC_CD, PERIOD_TYPE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    /* CURRENT - Debit */
    INSERT INTO tmp_b02_account_turnover
    (
        ACC_CD,
        PERIOD_TYPE,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT
    )
    SELECT
        TRIM(d.DEBIT) AS ACC_CD,
        'CURRENT' AS PERIOD_TYPE,
        SUM(IFNULL(d.AMOUNT, 0)) AS DEBIT_AMOUNT,
        0 AS CREDIT_AMOUNT
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD
       AND d.CHIT_ID = h.CHIT_ID
       AND d.ISDEL = '0'
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.ISDEL = '0'
      AND h.CHIT_YMD >= v_from_ymd
      AND h.CHIT_YMD <= v_to_ymd
      AND d.DEBIT IS NOT NULL
      AND TRIM(d.DEBIT) <> ''
    GROUP BY TRIM(d.DEBIT);

    /* CURRENT - Credit */
    INSERT INTO tmp_b02_account_turnover
    (
        ACC_CD,
        PERIOD_TYPE,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT
    )
    SELECT
        TRIM(d.CREDIT) AS ACC_CD,
        'CURRENT' AS PERIOD_TYPE,
        0 AS DEBIT_AMOUNT,
        SUM(IFNULL(d.AMOUNT, 0)) AS CREDIT_AMOUNT
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD
       AND d.CHIT_ID = h.CHIT_ID
       AND d.ISDEL = '0'
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.ISDEL = '0'
      AND h.CHIT_YMD >= v_from_ymd
      AND h.CHIT_YMD <= v_to_ymd
      AND d.CREDIT IS NOT NULL
      AND TRIM(d.CREDIT) <> ''
    GROUP BY TRIM(d.CREDIT)
    ON DUPLICATE KEY UPDATE
        DEBIT_AMOUNT = DEBIT_AMOUNT + VALUES(DEBIT_AMOUNT),
        CREDIT_AMOUNT = CREDIT_AMOUNT + VALUES(CREDIT_AMOUNT);

    /* PREVIOUS - Debit */
    INSERT INTO tmp_b02_account_turnover
    (
        ACC_CD,
        PERIOD_TYPE,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT
    )
    SELECT
        TRIM(d.DEBIT) AS ACC_CD,
        'PREVIOUS' AS PERIOD_TYPE,
        SUM(IFNULL(d.AMOUNT, 0)) AS DEBIT_AMOUNT,
        0 AS CREDIT_AMOUNT
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD
       AND d.CHIT_ID = h.CHIT_ID
       AND d.ISDEL = '0'
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.ISDEL = '0'
      AND h.CHIT_YMD >= v_previous_from_ymd
      AND h.CHIT_YMD <= v_previous_to_ymd
      AND d.DEBIT IS NOT NULL
      AND TRIM(d.DEBIT) <> ''
    GROUP BY TRIM(d.DEBIT);

    /* PREVIOUS - Credit */
    INSERT INTO tmp_b02_account_turnover
    (
        ACC_CD,
        PERIOD_TYPE,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT
    )
    SELECT
        TRIM(d.CREDIT) AS ACC_CD,
        'PREVIOUS' AS PERIOD_TYPE,
        0 AS DEBIT_AMOUNT,
        SUM(IFNULL(d.AMOUNT, 0)) AS CREDIT_AMOUNT
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD
       AND d.CHIT_ID = h.CHIT_ID
       AND d.ISDEL = '0'
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.ISDEL = '0'
      AND h.CHIT_YMD >= v_previous_from_ymd
      AND h.CHIT_YMD <= v_previous_to_ymd
      AND d.CREDIT IS NOT NULL
      AND TRIM(d.CREDIT) <> ''
    GROUP BY TRIM(d.CREDIT)
    ON DUPLICATE KEY UPDATE
        DEBIT_AMOUNT = DEBIT_AMOUNT + VALUES(DEBIT_AMOUNT),
        CREDIT_AMOUNT = CREDIT_AMOUNT + VALUES(CREDIT_AMOUNT);

    DROP TEMPORARY TABLE IF EXISTS tmp_b02_report;
    CREATE TEMPORARY TABLE tmp_b02_report
    (
        ROW_KEY VARCHAR(80) NOT NULL DEFAULT '',
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        ROW_TYPE VARCHAR(30) NOT NULL DEFAULT '',
        SORT_ORDER INT NOT NULL DEFAULT 0,
        ITEM_CODE VARCHAR(50) NULL,
        ITEM_NAME VARCHAR(1000) NULL,
        CAPTION VARCHAR(1000) NULL,
        LABEL_TEXT VARCHAR(200) NULL,
        NOTE VARCHAR(100) NOT NULL DEFAULT '',
        CURRENT_YEAR DECIMAL(18,2) NULL,
        PREVIOUS_YEAR DECIMAL(18,2) NULL,
        LEVEL_NO INT NOT NULL DEFAULT 0,
        FONT_BOLD CHAR(1) NOT NULL DEFAULT '0',
        FONT_ITALIC CHAR(1) NOT NULL DEFAULT '0',
        DATA_SOURCE_TYPE VARCHAR(50) NULL,
        FORMULA_EXPR VARCHAR(1000) NULL,
        REPORT_YEAR_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        REPORT_PERIOD_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        AMOUNT_UNIT_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ROW_KEY),
        INDEX idx_tmp_b02_report_01 (ITEM_CODE),
        INDEX idx_tmp_b02_report_02 (SORT_ORDER)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b02_report
    (
        ROW_KEY,
        COMPANY_CD,
        ROW_TYPE,
        SORT_ORDER,
        ITEM_CODE,
        ITEM_NAME,
        CAPTION,
        LABEL_TEXT,
        NOTE,
        LEVEL_NO,
        FONT_BOLD,
        FONT_ITALIC,
        DATA_SOURCE_TYPE,
        FORMULA_EXPR,
        REPORT_YEAR_TEXT,
        REPORT_PERIOD_TEXT,
        AMOUNT_UNIT_TEXT
    )
    SELECT
        template.ITEM_KEY,
        p_COMPANY_CD,
        template.ELEMENT_TYPE,
        template.SORT_ORDER,
        template.ITEM_CODE,
        -- ITEM_NAME: backward-compat display = indented CAPTION; LABEL_TEXT for future i18n via t_message_info.
        CONCAT(REPEAT('  ', GREATEST(IFNULL(template.LEVEL_NO, 1) - 1, 0)), IFNULL(template.CAPTION, '')),
        template.CAPTION,
        template.LABEL_TEXT,
        '',
        IFNULL(template.LEVEL_NO, 0),
        IFNULL(template.FONT_BOLD, '0'),
        IFNULL(template.FONT_ITALIC, '0'),
        IFNULL(template.DATA_SOURCE_TYPE, ''),
        template.FORMULA_EXPR,
        CASE v_language
            WHEN 'ENG' THEN CONCAT('Year ', YEAR(v_to_date))
            WHEN 'KOR' THEN CONCAT(YEAR(v_to_date), 'ë…„')
            WHEN 'CHN' THEN CONCAT(YEAR(v_to_date), 'å¹´')
            ELSE CONCAT('NÄƒm ', YEAR(v_to_date))
        END,
        CASE v_language
            WHEN 'ENG' THEN
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                     AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT('Year ', YEAR(v_to_date))
                    ELSE CONCAT(
                        'From ',
                        DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        ' to ',
                        DATE_FORMAT(v_to_date, '%d/%m/%Y')
                    )
                END
            WHEN 'KOR' THEN
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                     AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT(YEAR(v_to_date), 'ë…„')
                    ELSE CONCAT(
                        DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        'ë¶€í„° ',
                        DATE_FORMAT(v_to_date, '%d/%m/%Y'),
                        'ê¹Œì§€'
                    )
                END
            WHEN 'CHN' THEN
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                     AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT(YEAR(v_to_date), 'å¹´')
                    ELSE CONCAT(
                        'ä»Ž ',
                        DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        ' è‡³ ',
                        DATE_FORMAT(v_to_date, '%d/%m/%Y')
                    )
                END
            ELSE
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                     AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT('NÄƒm ', YEAR(v_to_date))
                    ELSE CONCAT(
                        'Tá»« ngÃ y ',
                        DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        ' Ä‘áº¿n ngÃ y ',
                        DATE_FORMAT(v_to_date, '%d/%m/%Y')
                    )
                END
        END,
        CASE v_language
            WHEN 'ENG' THEN
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'Unit: million VND'
                    WHEN v_unit_divisor = 1000 THEN 'Unit: thousand VND'
                    ELSE 'Unit: VND'
                END
            WHEN 'KOR' THEN
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'ë‹¨ìœ„: ë°±ë§Œ VND'
                    WHEN v_unit_divisor = 1000 THEN 'ë‹¨ìœ„: ì²œ VND'
                    ELSE 'ë‹¨ìœ„: VND'
                END
            WHEN 'CHN' THEN
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'å•ä½ï¼šç™¾ä¸‡è¶Šå—ç›¾'
                    WHEN v_unit_divisor = 1000 THEN 'å•ä½ï¼šåƒè¶Šå—ç›¾'
                    ELSE 'å•ä½ï¼šè¶Šå—ç›¾'
                END
            ELSE
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'ÄÆ¡n vá»‹ tÃ­nh: triá»‡u Ä‘á»“ng'
                    WHEN v_unit_divisor = 1000 THEN 'ÄÆ¡n vá»‹ tÃ­nh: nghÃ¬n Ä‘á»“ng'
                    ELSE 'ÄÆ¡n vá»‹ tÃ­nh: Ä‘á»“ng'
                END
        END
    FROM report_B02DN template
    WHERE template.COMPANY_CD = v_template_company_cd
      AND template.REPORT_CODE = 'B02_DN'
      AND template.REPORT_VERSION = v_report_version
      AND template.SECTION_TYPE = 'DETAIL'
      AND IFNULL(template.ISDEL, '0') = '0'
      AND IFNULL(template.IS_VISIBLE, '1') = '1'
    ORDER BY template.SORT_ORDER;

    UPDATE tmp_b02_report report
    LEFT JOIN
    (
        SELECT
            rule.ITEM_CODE,
            SUM(CASE WHEN turnover.PERIOD_TYPE = 'CURRENT' THEN
                CASE rule.CALC_METHOD
                    WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                    WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                    WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                    ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                END
                ELSE 0
            END) AS CURRENT_YEAR,
            SUM(CASE WHEN turnover.PERIOD_TYPE = 'PREVIOUS' THEN
                CASE rule.CALC_METHOD
                    WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                    WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                    WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                    ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                END
                ELSE 0
            END) AS PREVIOUS_YEAR
        FROM tmp_b02_rule rule
        INNER JOIN tmp_b02_account_turnover turnover
            ON turnover.ACC_CD LIKE CONCAT(rule.ACC_PREFIX, '%')
        GROUP BY rule.ITEM_CODE
    ) calc
        ON UPPER(calc.ITEM_CODE) = UPPER(report.ITEM_CODE)
    SET
        report.CURRENT_YEAR = NULLIF(ROUND(IFNULL(calc.CURRENT_YEAR, 0) / v_unit_divisor, 0), 0),
        report.PREVIOUS_YEAR = NULLIF(ROUND(IFNULL(calc.PREVIOUS_YEAR, 0) / v_unit_divisor, 0), 0)
    WHERE UPPER(IFNULL(report.DATA_SOURCE_TYPE, '')) = 'ACCOUNT_RULE';

    /*
        Tá»‘i Æ°u FORMULA:
        - Parse biá»ƒu thá»©c má»™t láº§n.
        - KhÃ´ng DROP/CREATE temporary table trong WHILE.
        - Má»—i vÃ²ng chá»‰ TRUNCATE calc + INSERT + UPDATE.
        - Dá»«ng sá»›m khi káº¿t quáº£ khÃ´ng cÃ²n thay Ä‘á»•i.
    */
    DROP TEMPORARY TABLE IF EXISTS tmp_b02_formula_expr;
    CREATE TEMPORARY TABLE tmp_b02_formula_expr
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        EXPR_TEXT VARCHAR(1000) NULL,
        PRIMARY KEY (ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b02_formula_expr
    (
        ITEM_CODE,
        EXPR_TEXT
    )
    SELECT
        ITEM_CODE,
        REPLACE(
            REPLACE(
                REPLACE(
                    UPPER(SUBSTRING_INDEX(IFNULL(FORMULA_EXPR, ''), '=', -1)),
                    ' ',
                    ''
                ),
                '-',
                '+-'
            ),
            ';',
            '+'
        ) AS EXPR_TEXT
    FROM tmp_b02_report
    WHERE UPPER(IFNULL(DATA_SOURCE_TYPE, '')) = 'FORMULA'
      AND IFNULL(ITEM_CODE, '') <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_b02_formula_term;
    CREATE TEMPORARY TABLE tmp_b02_formula_term
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        SIGN_FACTOR INT NOT NULL DEFAULT 1,
        CHILD_ITEM_CODE VARCHAR(50) NOT NULL,
        INDEX idx_tmp_b02_formula_term_01 (ITEM_CODE),
        INDEX idx_tmp_b02_formula_term_02 (CHILD_ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b02_formula_term
    (
        ITEM_CODE,
        SIGN_FACTOR,
        CHILD_ITEM_CODE
    )
    SELECT
        raw.ITEM_CODE,
        CASE
            WHEN LEFT(raw.TERM_TEXT, 1) = '-' THEN -1
            ELSE 1
        END AS SIGN_FACTOR,
        REPLACE(raw.TERM_TEXT, '-', '') AS CHILD_ITEM_CODE
    FROM
    (
        SELECT
            formula.ITEM_CODE,
            TRIM(
                SUBSTRING_INDEX(
                    SUBSTRING_INDEX(formula.EXPR_TEXT, '+', numbers.N),
                    '+',
                    -1
                )
            ) AS TERM_TEXT
        FROM tmp_b02_formula_expr formula
        INNER JOIN tmp_b02_numbers numbers
            ON numbers.N <= 1
                + LENGTH(IFNULL(formula.EXPR_TEXT, ''))
                - LENGTH(REPLACE(IFNULL(formula.EXPR_TEXT, ''), '+', ''))
    ) raw
    WHERE raw.TERM_TEXT <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_b02_formula_calc;
    CREATE TEMPORARY TABLE tmp_b02_formula_calc
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        CURRENT_YEAR DECIMAL(18,2) NULL,
        PREVIOUS_YEAR DECIMAL(18,2) NULL,
        PRIMARY KEY (ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    SET v_iteration = 0;

    formula_loop: WHILE v_iteration < 8 DO
        TRUNCATE TABLE tmp_b02_formula_calc;

        INSERT INTO tmp_b02_formula_calc
        (
            ITEM_CODE,
            CURRENT_YEAR,
            PREVIOUS_YEAR
        )
        SELECT
            term.ITEM_CODE,
            SUM(term.SIGN_FACTOR * IFNULL(child.CURRENT_YEAR, 0)) AS CURRENT_YEAR,
            SUM(term.SIGN_FACTOR * IFNULL(child.PREVIOUS_YEAR, 0)) AS PREVIOUS_YEAR
        FROM tmp_b02_formula_term term
        INNER JOIN tmp_b02_report child
            ON UPPER(child.ITEM_CODE) = UPPER(term.CHILD_ITEM_CODE)
        GROUP BY term.ITEM_CODE;

        UPDATE tmp_b02_report report
        INNER JOIN tmp_b02_formula_calc calc
            ON UPPER(calc.ITEM_CODE) = UPPER(report.ITEM_CODE)
        SET
            report.CURRENT_YEAR = NULLIF(calc.CURRENT_YEAR, 0),
            report.PREVIOUS_YEAR = NULLIF(calc.PREVIOUS_YEAR, 0)
        WHERE UPPER(IFNULL(report.DATA_SOURCE_TYPE, '')) = 'FORMULA'
          AND
          (
                NOT (report.CURRENT_YEAR <=> NULLIF(calc.CURRENT_YEAR, 0))
             OR NOT (report.PREVIOUS_YEAR <=> NULLIF(calc.PREVIOUS_YEAR, 0))
          );

        SET v_changed_rows = ROW_COUNT();
        SET v_iteration = v_iteration + 1;

        IF v_changed_rows = 0 THEN
            LEAVE formula_loop;
        END IF;
    END WHILE formula_loop;

    SELECT
        ROW_KEY,
        COMPANY_CD,
        ROW_TYPE,
        ITEM_NAME,
        CAPTION,
        LABEL_TEXT,
        ITEM_CODE,
        NOTE,
        CURRENT_YEAR,
        PREVIOUS_YEAR,
        LEVEL_NO,
        FONT_BOLD,
        FONT_ITALIC,
        REPORT_YEAR_TEXT,
        REPORT_PERIOD_TEXT,
        AMOUNT_UNIT_TEXT
    FROM tmp_b02_report
    ORDER BY SORT_ORDER;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_profit_loss_b02dntt
DROP PROCEDURE IF EXISTS `rpt_profit_loss_b02dntt`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_profit_loss_b02dntt`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_REPORT_VERSION VARCHAR(20),
    IN p_UNIT_DIVISOR DECIMAL(18,6),
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_from_date DATE;
    DECLARE v_to_date DATE;
    DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_report_version VARCHAR(20);
    DECLARE v_template_company_cd VARCHAR(20);
    DECLARE v_unit_divisor DECIMAL(18,6);
    DECLARE v_iteration INT DEFAULT 0;
    DECLARE v_changed_rows INT DEFAULT 0;
    DECLARE v_language VARCHAR(20);
    DECLARE v_from_month_ymd VARCHAR(8);
    DECLARE v_to_month_ymd VARCHAR(8);

    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate and toDate are required';
    END IF;

    IF p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;

    SET v_from_date = p_FROM_DATE;
    SET v_to_date = p_TO_DATE;
    SET v_from_ymd = DATE_FORMAT(v_from_date, '%Y%m%d');
    SET v_to_ymd = DATE_FORMAT(v_to_date, '%Y%m%d');
    SET v_report_version = IFNULL(NULLIF(TRIM(IFNULL(p_REPORT_VERSION, '')), ''), '2025');
    SET v_unit_divisor = CASE WHEN IFNULL(p_UNIT_DIVISOR, 0) = 0 THEN 1 ELSE p_UNIT_DIVISOR END;
    SET v_language = UPPER(IFNULL(NULLIF(TRIM(p_LANGUAGE), ''), 'VIET'));
    SET v_from_month_ymd = DATE_FORMAT(v_from_date, '%Y%m01');
    SET v_to_month_ymd = DATE_FORMAT(LAST_DAY(v_to_date), '%Y%m%d');

    SELECT COALESCE(
        (
            SELECT template.COMPANY_CD
            FROM report_B02DN template
            WHERE template.REPORT_CODE = 'B02_DN'
                AND template.REPORT_VERSION = v_report_version
                AND template.COMPANY_CD IN (p_COMPANY_CD, '0001', '')
                AND IFNULL(template.ISDEL, '0') = '0'
            ORDER BY CASE
                WHEN template.COMPANY_CD = p_COMPANY_CD THEN 0
                WHEN template.COMPANY_CD = '0001' THEN 1
                ELSE 2
            END
            LIMIT 1
        ),
        '0001'
    )
    INTO v_template_company_cd;

    DROP TEMPORARY TABLE IF EXISTS tmp_b02_numbers;
    CREATE TEMPORARY TABLE tmp_b02_numbers
    (
        N INT NOT NULL,
        PRIMARY KEY (N)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b02_numbers (N)
    SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5
    UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10
    UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15
    UNION ALL SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL SELECT 20
    UNION ALL SELECT 21 UNION ALL SELECT 22 UNION ALL SELECT 23 UNION ALL SELECT 24 UNION ALL SELECT 25
    UNION ALL SELECT 26 UNION ALL SELECT 27 UNION ALL SELECT 28 UNION ALL SELECT 29 UNION ALL SELECT 30
    UNION ALL SELECT 31 UNION ALL SELECT 32 UNION ALL SELECT 33 UNION ALL SELECT 34 UNION ALL SELECT 35
    UNION ALL SELECT 36 UNION ALL SELECT 37 UNION ALL SELECT 38 UNION ALL SELECT 39 UNION ALL SELECT 40;

    DROP TEMPORARY TABLE IF EXISTS tmp_b02_rule;
    CREATE TEMPORARY TABLE tmp_b02_rule
    (
        ITEM_CODE VARCHAR(20) NOT NULL,
        ACC_PREFIX VARCHAR(20) NOT NULL,
        CALC_METHOD VARCHAR(30) NOT NULL,
        INDEX idx_tmp_b02_rule_01 (ITEM_CODE, ACC_PREFIX)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b02_rule (ITEM_CODE, ACC_PREFIX, CALC_METHOD)
    SELECT
        template.ITEM_CODE,
        TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(IFNULL(template.ACCOUNT_RULE, ''), ',', numbers.N), ',', -1)),
        template.CALC_METHOD
    FROM report_B02DN template
    INNER JOIN tmp_b02_numbers numbers
        ON numbers.N <= 1 + LENGTH(IFNULL(template.ACCOUNT_RULE, ''))
            - LENGTH(REPLACE(IFNULL(template.ACCOUNT_RULE, ''), ',', ''))
    WHERE template.COMPANY_CD = v_template_company_cd
        AND template.REPORT_CODE = 'B02_DN'
        AND template.REPORT_VERSION = v_report_version
        AND template.SECTION_TYPE = 'DETAIL'
        AND IFNULL(template.DATA_SOURCE_TYPE, '') = 'ACCOUNT_RULE'
        AND IFNULL(template.ACCOUNT_RULE, '') <> ''
        AND TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(IFNULL(template.ACCOUNT_RULE, ''), ',', numbers.N), ',', -1)) <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_b02_months;
    CREATE TEMPORARY TABLE tmp_b02_months
    (
        MONTH_INDEX INT NOT NULL,
        PERIOD_KEY VARCHAR(6) NOT NULL,
        PERIOD_LABEL VARCHAR(20) NOT NULL,
        PRIMARY KEY (MONTH_INDEX)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b02_months (MONTH_INDEX, PERIOD_KEY, PERIOD_LABEL)
    SELECT
        numbers.N,
        DATE_FORMAT(DATE_ADD(v_from_date, INTERVAL numbers.N - 1 MONTH), '%Y%m'),
        DATE_FORMAT(DATE_ADD(v_from_date, INTERVAL numbers.N - 1 MONTH), '%m/%Y')
    FROM tmp_b02_numbers numbers
    WHERE numbers.N <= 1 + PERIOD_DIFF(
        DATE_FORMAT(v_to_date, '%Y%m'),
        DATE_FORMAT(v_from_date, '%Y%m')
    );

    /*
        Tối ưu:
        - Không materialize toàn bộ phát sinh vào tmp_b02_movements.
        - Lọc trực tiếp h.CHIT_YMD theo khoảng tháng để dùng index.
        - Aggregate thẳng theo ACC_CD + PERIOD_KEY.
    */
    DROP TEMPORARY TABLE IF EXISTS tmp_b02_account_turnover;
    CREATE TEMPORARY TABLE tmp_b02_account_turnover
    (
        ACC_CD VARCHAR(20) NOT NULL,
        PERIOD_KEY VARCHAR(6) NOT NULL,
        DEBIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        CREDIT_AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0.00,
        PRIMARY KEY (ACC_CD, PERIOD_KEY)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    /* Debit */
    INSERT INTO tmp_b02_account_turnover
    (
        ACC_CD,
        PERIOD_KEY,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT
    )
    SELECT
        TRIM(d.DEBIT) AS ACC_CD,
        LEFT(h.CHIT_YMD, 6) AS PERIOD_KEY,
        SUM(IFNULL(d.AMOUNT, 0)) AS DEBIT_AMOUNT,
        0 AS CREDIT_AMOUNT
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD
        AND d.CHIT_ID = h.CHIT_ID
        AND d.ISDEL = '0'
    WHERE h.COMPANY_CD = p_COMPANY_CD
        AND h.ISDEL = '0'
        AND h.CHIT_YMD >= v_from_month_ymd
        AND h.CHIT_YMD <= v_to_month_ymd
        AND d.DEBIT IS NOT NULL
        AND d.DEBIT <> ''
    GROUP BY TRIM(d.DEBIT), LEFT(h.CHIT_YMD, 6);

    /* Credit */
    INSERT INTO tmp_b02_account_turnover
    (
        ACC_CD,
        PERIOD_KEY,
        DEBIT_AMOUNT,
        CREDIT_AMOUNT
    )
    SELECT
        TRIM(d.CREDIT) AS ACC_CD,
        LEFT(h.CHIT_YMD, 6) AS PERIOD_KEY,
        0 AS DEBIT_AMOUNT,
        SUM(IFNULL(d.AMOUNT, 0)) AS CREDIT_AMOUNT
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD
        AND d.CHIT_ID = h.CHIT_ID
        AND d.ISDEL = '0'
    WHERE h.COMPANY_CD = p_COMPANY_CD
        AND h.ISDEL = '0'
        AND h.CHIT_YMD >= v_from_month_ymd
        AND h.CHIT_YMD <= v_to_month_ymd
        AND d.CREDIT IS NOT NULL
        AND d.CREDIT <> ''
    GROUP BY TRIM(d.CREDIT), LEFT(h.CHIT_YMD, 6)
    ON DUPLICATE KEY UPDATE
        DEBIT_AMOUNT = DEBIT_AMOUNT + VALUES(DEBIT_AMOUNT),
        CREDIT_AMOUNT = CREDIT_AMOUNT + VALUES(CREDIT_AMOUNT);

    DROP TEMPORARY TABLE IF EXISTS tmp_b02_report;
    CREATE TEMPORARY TABLE tmp_b02_report
    (
        ROW_KEY VARCHAR(80) NOT NULL DEFAULT '',
        COMPANY_CD VARCHAR(20) NOT NULL DEFAULT '',
        ROW_TYPE VARCHAR(30) NOT NULL DEFAULT '',
        SORT_ORDER INT NOT NULL DEFAULT 0,
        ITEM_CODE VARCHAR(50) NULL,
        ITEM_NAME VARCHAR(1000) NULL,
        CAPTION VARCHAR(1000) NULL,
        LABEL_TEXT VARCHAR(200) NULL,
        NOTE VARCHAR(100) NOT NULL DEFAULT '',
        M01 DECIMAL(18,2) NULL,
        M02 DECIMAL(18,2) NULL,
        M03 DECIMAL(18,2) NULL,
        M04 DECIMAL(18,2) NULL,
        M05 DECIMAL(18,2) NULL,
        M06 DECIMAL(18,2) NULL,
        M07 DECIMAL(18,2) NULL,
        M08 DECIMAL(18,2) NULL,
        M09 DECIMAL(18,2) NULL,
        M10 DECIMAL(18,2) NULL,
        M11 DECIMAL(18,2) NULL,
        M12 DECIMAL(18,2) NULL,
        LEVEL_NO INT NOT NULL DEFAULT 0,
        FONT_BOLD CHAR(1) NOT NULL DEFAULT '0',
        FONT_ITALIC CHAR(1) NOT NULL DEFAULT '0',
        DATA_SOURCE_TYPE VARCHAR(50) NULL,
        FORMULA_EXPR VARCHAR(1000) NULL,
        REPORT_YEAR_TEXT VARCHAR(100) NOT NULL DEFAULT '',
        REPORT_PERIOD_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        AMOUNT_UNIT_TEXT VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (ROW_KEY),
        INDEX idx_tmp_b02_report_01 (ITEM_CODE),
        INDEX idx_tmp_b02_report_02 (SORT_ORDER)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b02_report
    (
        ROW_KEY,
        COMPANY_CD,
        ROW_TYPE,
        SORT_ORDER,
        ITEM_CODE,
        ITEM_NAME,
        CAPTION,
        LABEL_TEXT,
        NOTE,
        LEVEL_NO,
        FONT_BOLD,
        FONT_ITALIC,
        DATA_SOURCE_TYPE,
        FORMULA_EXPR,
        REPORT_YEAR_TEXT,
        REPORT_PERIOD_TEXT,
        AMOUNT_UNIT_TEXT
    )
    SELECT
        template.ITEM_KEY,
        p_COMPANY_CD,
        template.ELEMENT_TYPE,
        template.SORT_ORDER,
        template.ITEM_CODE,
        CONCAT(REPEAT('  ', GREATEST(IFNULL(template.LEVEL_NO, 1) - 1, 0)), IFNULL(template.CAPTION, '')),
        template.CAPTION,
        template.LABEL_TEXT,
        '',
        IFNULL(template.LEVEL_NO, 0),
        IFNULL(template.FONT_BOLD, '0'),
        IFNULL(template.FONT_ITALIC, '0'),
        IFNULL(template.DATA_SOURCE_TYPE, ''),
        template.FORMULA_EXPR,
        CASE v_language
            WHEN 'ENG' THEN CONCAT('Year ', YEAR(v_to_date))
            WHEN 'KOR' THEN CONCAT(YEAR(v_to_date), '년')
            WHEN 'CHN' THEN CONCAT(YEAR(v_to_date), '年')
            ELSE CONCAT('Năm ', YEAR(v_to_date))
        END,
        CASE v_language
            WHEN 'ENG' THEN
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                        AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT('Year ', YEAR(v_to_date))
                    ELSE CONCAT('From ', DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        ' to ', DATE_FORMAT(v_to_date, '%d/%m/%Y'))
                END
            WHEN 'KOR' THEN
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                        AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT(YEAR(v_to_date), '년')
                    ELSE CONCAT(DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        '부터 ', DATE_FORMAT(v_to_date, '%d/%m/%Y'), '까지')
                END
            WHEN 'CHN' THEN
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                        AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT(YEAR(v_to_date), '年')
                    ELSE CONCAT('从 ', DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        ' 至 ', DATE_FORMAT(v_to_date, '%d/%m/%Y'))
                END
            ELSE
                CASE
                    WHEN DATE_FORMAT(v_from_date, '%Y%m%d') = CONCAT(YEAR(v_to_date), '0101')
                        AND DATE_FORMAT(v_to_date, '%m%d') = '1231'
                    THEN CONCAT('Năm ', YEAR(v_to_date))
                    ELSE CONCAT('Từ ngày ', DATE_FORMAT(v_from_date, '%d/%m/%Y'),
                        ' đến ngày ', DATE_FORMAT(v_to_date, '%d/%m/%Y'))
                END
        END,
        CASE v_language
            WHEN 'ENG' THEN
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'Unit: million VND'
                    WHEN v_unit_divisor = 1000 THEN 'Unit: thousand VND'
                    ELSE 'Unit: VND'
                END
            WHEN 'KOR' THEN
                CASE
                    WHEN v_unit_divisor = 1000000 THEN '단위: 백만 VND'
                    WHEN v_unit_divisor = 1000 THEN '단위: 천 VND'
                    ELSE '단위: VND'
                END
            WHEN 'CHN' THEN
                CASE
                    WHEN v_unit_divisor = 1000000 THEN '单位：百万越南盾'
                    WHEN v_unit_divisor = 1000 THEN '单位：千越南盾'
                    ELSE '单位：越南盾'
                END
            ELSE
                CASE
                    WHEN v_unit_divisor = 1000000 THEN 'Đơn vị tính: triệu đồng'
                    WHEN v_unit_divisor = 1000 THEN 'Đơn vị tính: nghìn đồng'
                    ELSE 'Đơn vị tính: đồng'
                END
        END
    FROM report_B02DN template
    WHERE template.COMPANY_CD = v_template_company_cd
        AND template.REPORT_CODE = 'B02_DN'
        AND template.REPORT_VERSION = v_report_version
        AND template.SECTION_TYPE = 'DETAIL'
        AND IFNULL(template.ISDEL, '0') = '0'
        AND IFNULL(template.IS_VISIBLE, '1') = '1'
    ORDER BY template.SORT_ORDER;

    UPDATE tmp_b02_report report
    LEFT JOIN
    (
        SELECT
            rule.ITEM_CODE,
            SUM(
                CASE
                    WHEN turnover.PERIOD_KEY = months.PERIOD_KEY
                        AND months.MONTH_INDEX = 1
                    THEN
                        CASE rule.CALC_METHOD
                            WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                            WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                            WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                            ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                        END
                    ELSE 0
                END
            ) AS M01,
            SUM(
                CASE
                    WHEN turnover.PERIOD_KEY = months.PERIOD_KEY
                        AND months.MONTH_INDEX = 2
                    THEN
                        CASE rule.CALC_METHOD
                            WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                            WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                            WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                            ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                        END
                    ELSE 0
                END
            ) AS M02,
            SUM(
                CASE
                    WHEN turnover.PERIOD_KEY = months.PERIOD_KEY
                        AND months.MONTH_INDEX = 3
                    THEN
                        CASE rule.CALC_METHOD
                            WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                            WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                            WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                            ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                        END
                    ELSE 0
                END
            ) AS M03,
            SUM(
                CASE
                    WHEN turnover.PERIOD_KEY = months.PERIOD_KEY
                        AND months.MONTH_INDEX = 4
                    THEN
                        CASE rule.CALC_METHOD
                            WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                            WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                            WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                            ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                        END
                    ELSE 0
                END
            ) AS M04,
            SUM(
                CASE
                    WHEN turnover.PERIOD_KEY = months.PERIOD_KEY
                        AND months.MONTH_INDEX = 5
                    THEN
                        CASE rule.CALC_METHOD
                            WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                            WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                            WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                            ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                        END
                    ELSE 0
                END
            ) AS M05,
            SUM(
                CASE
                    WHEN turnover.PERIOD_KEY = months.PERIOD_KEY
                        AND months.MONTH_INDEX = 6
                    THEN
                        CASE rule.CALC_METHOD
                            WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                            WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                            WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                            ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                        END
                    ELSE 0
                END
            ) AS M06,
            SUM(
                CASE
                    WHEN turnover.PERIOD_KEY = months.PERIOD_KEY
                        AND months.MONTH_INDEX = 7
                    THEN
                        CASE rule.CALC_METHOD
                            WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                            WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                            WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                            ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                        END
                    ELSE 0
                END
            ) AS M07,
            SUM(
                CASE
                    WHEN turnover.PERIOD_KEY = months.PERIOD_KEY
                        AND months.MONTH_INDEX = 8
                    THEN
                        CASE rule.CALC_METHOD
                            WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                            WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                            WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                            ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                        END
                    ELSE 0
                END
            ) AS M08,
            SUM(
                CASE
                    WHEN turnover.PERIOD_KEY = months.PERIOD_KEY
                        AND months.MONTH_INDEX = 9
                    THEN
                        CASE rule.CALC_METHOD
                            WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                            WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                            WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                            ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                        END
                    ELSE 0
                END
            ) AS M09,
            SUM(
                CASE
                    WHEN turnover.PERIOD_KEY = months.PERIOD_KEY
                        AND months.MONTH_INDEX = 10
                    THEN
                        CASE rule.CALC_METHOD
                            WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                            WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                            WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                            ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                        END
                    ELSE 0
                END
            ) AS M10,
            SUM(
                CASE
                    WHEN turnover.PERIOD_KEY = months.PERIOD_KEY
                        AND months.MONTH_INDEX = 11
                    THEN
                        CASE rule.CALC_METHOD
                            WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                            WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                            WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                            ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                        END
                    ELSE 0
                END
            ) AS M11,
            SUM(
                CASE
                    WHEN turnover.PERIOD_KEY = months.PERIOD_KEY
                        AND months.MONTH_INDEX = 12
                    THEN
                        CASE rule.CALC_METHOD
                            WHEN 'CREDIT_MINUS_DEBIT' THEN turnover.CREDIT_AMOUNT - turnover.DEBIT_AMOUNT
                            WHEN 'DEBIT_ONLY' THEN turnover.DEBIT_AMOUNT
                            WHEN 'CREDIT_ONLY' THEN turnover.CREDIT_AMOUNT
                            ELSE turnover.DEBIT_AMOUNT - turnover.CREDIT_AMOUNT
                        END
                    ELSE 0
                END
            ) AS M12
        FROM tmp_b02_rule rule
        INNER JOIN tmp_b02_account_turnover turnover
            ON turnover.ACC_CD LIKE CONCAT(rule.ACC_PREFIX, '%')
        INNER JOIN tmp_b02_months months
            ON turnover.PERIOD_KEY = months.PERIOD_KEY
        GROUP BY rule.ITEM_CODE
    ) calc
        ON UPPER(calc.ITEM_CODE) = UPPER(report.ITEM_CODE)
    SET
        report.M01 = NULLIF(ROUND(IFNULL(calc.M01, 0) / v_unit_divisor, 0), 0),
        report.M02 = NULLIF(ROUND(IFNULL(calc.M02, 0) / v_unit_divisor, 0), 0),
        report.M03 = NULLIF(ROUND(IFNULL(calc.M03, 0) / v_unit_divisor, 0), 0),
        report.M04 = NULLIF(ROUND(IFNULL(calc.M04, 0) / v_unit_divisor, 0), 0),
        report.M05 = NULLIF(ROUND(IFNULL(calc.M05, 0) / v_unit_divisor, 0), 0),
        report.M06 = NULLIF(ROUND(IFNULL(calc.M06, 0) / v_unit_divisor, 0), 0),
        report.M07 = NULLIF(ROUND(IFNULL(calc.M07, 0) / v_unit_divisor, 0), 0),
        report.M08 = NULLIF(ROUND(IFNULL(calc.M08, 0) / v_unit_divisor, 0), 0),
        report.M09 = NULLIF(ROUND(IFNULL(calc.M09, 0) / v_unit_divisor, 0), 0),
        report.M10 = NULLIF(ROUND(IFNULL(calc.M10, 0) / v_unit_divisor, 0), 0),
        report.M11 = NULLIF(ROUND(IFNULL(calc.M11, 0) / v_unit_divisor, 0), 0),
        report.M12 = NULLIF(ROUND(IFNULL(calc.M12, 0) / v_unit_divisor, 0), 0)
    WHERE UPPER(IFNULL(report.DATA_SOURCE_TYPE, '')) = 'ACCOUNT_RULE';

    /*
        Formula:
        - Parse biểu thức một lần.
        - Không DROP/CREATE 5 temporary tables ở mỗi iteration.
        - Mỗi vòng chỉ TRUNCATE calc, INSERT calc, UPDATE report.
        - Dừng sớm khi kết quả không còn thay đổi.
    */
    DROP TEMPORARY TABLE IF EXISTS tmp_b02_formula_expr;
    CREATE TEMPORARY TABLE tmp_b02_formula_expr
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        EXPR_TEXT VARCHAR(1000) NULL,
        PRIMARY KEY (ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b02_formula_expr (ITEM_CODE, EXPR_TEXT)
    SELECT
        ITEM_CODE,
        REPLACE(
            REPLACE(
                REPLACE(
                    UPPER(SUBSTRING_INDEX(IFNULL(FORMULA_EXPR, ''), '=', -1)),
                    ' ',
                    ''
                ),
                '-',
                '+-'
            ),
            ';',
            '+'
        )
    FROM tmp_b02_report
    WHERE UPPER(IFNULL(DATA_SOURCE_TYPE, '')) = 'FORMULA'
        AND IFNULL(ITEM_CODE, '') <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_b02_formula_term;
    CREATE TEMPORARY TABLE tmp_b02_formula_term
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        SIGN_FACTOR INT NOT NULL DEFAULT 1,
        CHILD_ITEM_CODE VARCHAR(50) NOT NULL,
        INDEX idx_tmp_b02_formula_term_01 (ITEM_CODE),
        INDEX idx_tmp_b02_formula_term_02 (CHILD_ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_b02_formula_term
    (
        ITEM_CODE,
        SIGN_FACTOR,
        CHILD_ITEM_CODE
    )
    SELECT
        raw.ITEM_CODE,
        CASE WHEN LEFT(raw.TERM_TEXT, 1) = '-' THEN -1 ELSE 1 END AS SIGN_FACTOR,
        REPLACE(raw.TERM_TEXT, '-', '') AS CHILD_ITEM_CODE
    FROM
    (
        SELECT
            formula.ITEM_CODE,
            TRIM(
                SUBSTRING_INDEX(
                    SUBSTRING_INDEX(formula.EXPR_TEXT, '+', numbers.N),
                    '+',
                    -1
                )
            ) AS TERM_TEXT
        FROM tmp_b02_formula_expr formula
        INNER JOIN tmp_b02_numbers numbers
            ON numbers.N <= 1
                + LENGTH(IFNULL(formula.EXPR_TEXT, ''))
                - LENGTH(REPLACE(IFNULL(formula.EXPR_TEXT, ''), '+', ''))
    ) raw
    WHERE raw.TERM_TEXT <> '';

    DROP TEMPORARY TABLE IF EXISTS tmp_b02_formula_calc;
    CREATE TEMPORARY TABLE tmp_b02_formula_calc
    (
        ITEM_CODE VARCHAR(50) NOT NULL,
        M01 DECIMAL(18,2) NULL,
        M02 DECIMAL(18,2) NULL,
        M03 DECIMAL(18,2) NULL,
        M04 DECIMAL(18,2) NULL,
        M05 DECIMAL(18,2) NULL,
        M06 DECIMAL(18,2) NULL,
        M07 DECIMAL(18,2) NULL,
        M08 DECIMAL(18,2) NULL,
        M09 DECIMAL(18,2) NULL,
        M10 DECIMAL(18,2) NULL,
        M11 DECIMAL(18,2) NULL,
        M12 DECIMAL(18,2) NULL,
        PRIMARY KEY (ITEM_CODE)
    ) ENGINE=MEMORY DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    SET v_iteration = 0;

    formula_loop: WHILE v_iteration < 8 DO
        TRUNCATE TABLE tmp_b02_formula_calc;

        INSERT INTO tmp_b02_formula_calc
        (
            ITEM_CODE,
            M01, M02, M03, M04, M05, M06,
            M07, M08, M09, M10, M11, M12
        )
        SELECT
            term.ITEM_CODE,
            SUM(term.SIGN_FACTOR * IFNULL(child.M01, 0)),
            SUM(term.SIGN_FACTOR * IFNULL(child.M02, 0)),
            SUM(term.SIGN_FACTOR * IFNULL(child.M03, 0)),
            SUM(term.SIGN_FACTOR * IFNULL(child.M04, 0)),
            SUM(term.SIGN_FACTOR * IFNULL(child.M05, 0)),
            SUM(term.SIGN_FACTOR * IFNULL(child.M06, 0)),
            SUM(term.SIGN_FACTOR * IFNULL(child.M07, 0)),
            SUM(term.SIGN_FACTOR * IFNULL(child.M08, 0)),
            SUM(term.SIGN_FACTOR * IFNULL(child.M09, 0)),
            SUM(term.SIGN_FACTOR * IFNULL(child.M10, 0)),
            SUM(term.SIGN_FACTOR * IFNULL(child.M11, 0)),
            SUM(term.SIGN_FACTOR * IFNULL(child.M12, 0))
        FROM tmp_b02_formula_term term
        INNER JOIN tmp_b02_report child
            ON UPPER(child.ITEM_CODE) = UPPER(term.CHILD_ITEM_CODE)
        GROUP BY term.ITEM_CODE;

        UPDATE tmp_b02_report report
        INNER JOIN tmp_b02_formula_calc calc
            ON UPPER(calc.ITEM_CODE) = UPPER(report.ITEM_CODE)
        SET
            report.M01 = NULLIF(calc.M01, 0),
            report.M02 = NULLIF(calc.M02, 0),
            report.M03 = NULLIF(calc.M03, 0),
            report.M04 = NULLIF(calc.M04, 0),
            report.M05 = NULLIF(calc.M05, 0),
            report.M06 = NULLIF(calc.M06, 0),
            report.M07 = NULLIF(calc.M07, 0),
            report.M08 = NULLIF(calc.M08, 0),
            report.M09 = NULLIF(calc.M09, 0),
            report.M10 = NULLIF(calc.M10, 0),
            report.M11 = NULLIF(calc.M11, 0),
            report.M12 = NULLIF(calc.M12, 0)
        WHERE UPPER(IFNULL(report.DATA_SOURCE_TYPE, '')) = 'FORMULA'
            AND
            (
                NOT (report.M01 <=> NULLIF(calc.M01, 0))
                OR NOT (report.M02 <=> NULLIF(calc.M02, 0))
                OR NOT (report.M03 <=> NULLIF(calc.M03, 0))
                OR NOT (report.M04 <=> NULLIF(calc.M04, 0))
                OR NOT (report.M05 <=> NULLIF(calc.M05, 0))
                OR NOT (report.M06 <=> NULLIF(calc.M06, 0))
                OR NOT (report.M07 <=> NULLIF(calc.M07, 0))
                OR NOT (report.M08 <=> NULLIF(calc.M08, 0))
                OR NOT (report.M09 <=> NULLIF(calc.M09, 0))
                OR NOT (report.M10 <=> NULLIF(calc.M10, 0))
                OR NOT (report.M11 <=> NULLIF(calc.M11, 0))
                OR NOT (report.M12 <=> NULLIF(calc.M12, 0))
            );

        SET v_changed_rows = ROW_COUNT();
        SET v_iteration = v_iteration + 1;

        IF v_changed_rows = 0 THEN
            LEAVE formula_loop;
        END IF;
    END WHILE formula_loop;

    SELECT
        ROW_KEY,
        COMPANY_CD,
        ROW_TYPE,
        ITEM_NAME,
        CAPTION,
        LABEL_TEXT,
        ITEM_CODE,
        NOTE,
        M01,
        M02,
        M03,
        M04,
        M05,
        M06,
        M07,
        M08,
        M09,
        M10,
        M11,
        M12,
        LEVEL_NO,
        FONT_BOLD,
        FONT_ITALIC,
        REPORT_YEAR_TEXT,
        REPORT_PERIOD_TEXT,
        AMOUNT_UNIT_TEXT
    FROM tmp_b02_report
    ORDER BY SORT_ORDER;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_purchase_journal
DROP PROCEDURE IF EXISTS `rpt_purchase_journal`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_purchase_journal`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_language VARCHAR(20);
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        DROP TEMPORARY TABLE IF EXISTS tmp_pj_source, tmp_pj_inventory, tmp_pj_weights,
            tmp_pj_lines, tmp_pj_totals, tmp_pj_rows;
        RESIGNAL;
    END;
    SET v_from_ymd=DATE_FORMAT(IFNULL(p_FROM_DATE,MAKEDATE(YEAR(CURDATE()),1)),'%Y%m%d');
    SET v_to_ymd=DATE_FORMAT(IFNULL(p_TO_DATE,CURDATE()),'%Y%m%d');
    SET v_language=UPPER(TRIM(IFNULL(p_LANGUAGE,'VIET')));
    IF NULLIF(TRIM(p_COMPANY_CD),'') IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='COMPANY_CD is required';
    END IF;
    IF v_from_ymd>v_to_ymd THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='fromDate must be earlier than or equal to toDate';
    END IF;
    DROP TEMPORARY TABLE IF EXISTS tmp_pj_source, tmp_pj_inventory, tmp_pj_weights,
        tmp_pj_lines, tmp_pj_totals, tmp_pj_rows;

    -- One row per posting. EXT/VAT have unique (company, detail, ISDEL) keys.
    -- Input VAT postings are not additional purchases.
    CREATE TEMPORARY TABLE tmp_pj_source ENGINE=InnoDB AS
    SELECT h.COMPANY_CD,h.CHIT_ID,h.CHIT_TYPE,d.CHITDETAIL_ID,h.CHIT_YMD AS ENTRY_YMD,
        COALESCE(NULLIF(TRIM(h.CHIT_NO),''),h.CHIT_CD) AS DOCUMENT_NO,
        COALESCE(NULLIF(d.CHIT_YMD,''),h.CHIT_YMD) AS DOCUMENT_YMD,
        d.DEBIT,d.CREDIT,d.SORT,
        CASE WHEN h.CHIT_TYPE IN ('PD','PR') THEN d.CREDIT ELSE d.DEBIT END AS ACCOUNT_CD,
        CASE WHEN h.CHIT_TYPE IN ('PD','PR') THEN -ABS(d.AMOUNT) ELSE d.AMOUNT END AS POSTING_AMOUNT,
        d.FC_RATE AS EXCHANGE_RATES,COALESCE(NULLIF(e.CUSTOMER_CD,''),c.CUSTOMER_CD) AS CUSTOMER_CD,
        e.CUSTOMER_OWN_CD,e.MR_CD AS NOTE_CD,
        COALESCE(NULLIF(CASE v_language WHEN 'ENG' THEN c.CUSTOMER_NM_ENG
            WHEN 'KOR' THEN c.CUSTOMER_NM_KOR WHEN 'CHINA' THEN c.CUSTOMER_NM_CHINA
            WHEN 'CHN' THEN c.CUSTOMER_NM_CHINA ELSE c.CUSTOMER_NM_VIET END,''),
            c.CUSTOMER_NM_VIET,h.PAYER_INFO,'') AS CUSTOMER_NAME,
        COALESCE(NULLIF(v.VAT_CHIT_NO,''),NULLIF(v.VAT_CHIT_NO_2,'')) AS INVOICE_NO
    FROM chitinfo h
    INNER JOIN chitdetailinfo d ON d.COMPANY_CD=h.COMPANY_CD AND d.CHIT_ID=h.CHIT_ID AND d.ISDEL='0'
    LEFT JOIN chitdetailinfo_ext e ON e.COMPANY_CD=d.COMPANY_CD
        AND e.CHITDETAIL_ID=d.CHITDETAIL_ID AND e.ISDEL='0'
    LEFT JOIN customer_info c ON c.COMPANY_CD=e.COMPANY_CD AND c.ISDEL='0'
        AND c.CUSTOMER_ID=COALESCE(NULLIF(e.CUSTOMER_ID,0),
            (SELECT MIN(c2.CUSTOMER_ID) FROM customer_info c2 WHERE c2.COMPANY_CD=e.COMPANY_CD
                AND c2.CUSTOMER_CD=e.CUSTOMER_CD AND c2.ISDEL='0'))
    LEFT JOIN chitdetailinfo_vat v ON v.COMPANY_CD=d.COMPANY_CD
        AND v.CHITDETAIL_ID=d.CHITDETAIL_ID AND v.ISDEL='0'
    WHERE h.COMPANY_CD=p_COMPANY_CD AND h.INPUT_TYPE='AP' AND h.CHIT_TYPE IN ('PO','PD','PR')
        AND h.ISDEL='0' AND h.CHIT_YMD BETWEEN v_from_ymd AND v_to_ymd
        AND IFNULL(d.DEBIT,'') NOT LIKE '133%' AND IFNULL(d.CREDIT,'') NOT LIKE '133%';
    ALTER TABLE tmp_pj_source ADD PRIMARY KEY (CHITDETAIL_ID);

    CREATE TEMPORARY TABLE tmp_pj_inventory (
        INVENTORY_KEY VARCHAR(50) NOT NULL PRIMARY KEY,CHITDETAIL_ID BIGINT NOT NULL,
        PRODUCT_ID BIGINT NULL,PRODUCT_CD VARCHAR(50),UNIT_ID BIGINT NULL,UNIT_CD VARCHAR(20),
        QUANTITY DECIMAL(24,6),UNIT_PRICE DECIMAL(24,6),AMOUNT_WEIGHT DECIMAL(24,6),
        KEY IX_PJ_DETAIL (CHITDETAIL_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
    INSERT INTO tmp_pj_inventory
    SELECT CONCAT('IN:',i.INPUT_ID),i.CHITDETAIL_ID,i.PRODUCT_ID,i.PRODUCT_CD,i.UNIT_ID,i.UNIT_CD,
        CASE WHEN s.CHIT_TYPE='PD' THEN NULL ELSE i.QUANTITY END,
        CASE WHEN s.CHIT_TYPE='PD' THEN NULL ELSE i.UNIT_PRICE_CC END,ABS(i.AMOUNT_CC)
    FROM chit_inventory_input i INNER JOIN tmp_pj_source s
        ON s.COMPANY_CD=i.COMPANY_CD AND s.CHITDETAIL_ID=i.CHITDETAIL_ID AND s.CHIT_TYPE IN ('PO','PD')
    WHERE i.COMPANY_CD=p_COMPANY_CD AND i.ISDEL='0';
    INSERT INTO tmp_pj_inventory
    SELECT CONCAT('OUT:',o.OUTPUT_ID),o.CHITDETAIL_ID,o.PRODUCT_ID,o.PRODUCT_CD,o.UNIT_ID,o.UNIT_CD,
        -ABS(o.QUANTITY),NULL,ABS(o.AMOUNT_CC)
    FROM chit_inventory_output o INNER JOIN tmp_pj_source s
        ON s.COMPANY_CD=o.COMPANY_CD AND s.CHITDETAIL_ID=o.CHITDETAIL_ID AND s.CHIT_TYPE='PR'
    WHERE o.COMPANY_CD=p_COMPANY_CD AND o.ISDEL='0';

    -- Preserve purchases without inventory, including service/accounting lines.
    CREATE TEMPORARY TABLE tmp_pj_weights AS SELECT DISTINCT CHITDETAIL_ID FROM tmp_pj_inventory;
    INSERT INTO tmp_pj_inventory (INVENTORY_KEY,CHITDETAIL_ID)
    SELECT CONCAT('ACC:',s.CHITDETAIL_ID),s.CHITDETAIL_ID
    FROM tmp_pj_source s LEFT JOIN tmp_pj_weights w ON w.CHITDETAIL_ID=s.CHITDETAIL_ID
    WHERE w.CHITDETAIL_ID IS NULL;
    DROP TEMPORARY TABLE tmp_pj_weights;
    CREATE TEMPORARY TABLE tmp_pj_weights AS
    SELECT CHITDETAIL_ID,COUNT(*) AS LINE_COUNT,SUM(AMOUNT_WEIGHT) AS TOTAL_WEIGHT,
        MAX(INVENTORY_KEY) AS LAST_KEY FROM tmp_pj_inventory GROUP BY CHITDETAIL_ID;
    ALTER TABLE tmp_pj_weights ADD PRIMARY KEY (CHITDETAIL_ID);

    -- Ledger CC amount is authoritative. Split only by stored inventory value;
    -- never divide by line count or quantities with potentially different units.
    CREATE TEMPORARY TABLE tmp_pj_lines ENGINE=InnoDB AS
    SELECT s.*,i.INVENTORY_KEY,
        CONCAT('A:',p_COMPANY_CD,':',COALESCE(NULLIF(s.ACCOUNT_CD,''),'UNLINKED')) AS ACCOUNT_KEY,
        CONCAT('A:',p_COMPANY_CD,':',COALESCE(NULLIF(s.ACCOUNT_CD,''),'UNLINKED'),':P:',
            CASE WHEN COALESCE(NULLIF(i.PRODUCT_ID,0),p.PRODUCT_ID)>0
                THEN CONCAT('ID:',COALESCE(NULLIF(i.PRODUCT_ID,0),p.PRODUCT_ID))
                WHEN NULLIF(i.PRODUCT_CD,'') IS NOT NULL THEN CONCAT('CD:',i.PRODUCT_CD)
                ELSE CONCAT('UNLINKED:',s.CHITDETAIL_ID) END) AS GROUP_KEY,
        COALESCE(NULLIF(i.PRODUCT_CD,''),p.PRODUCT_CD,'') AS PRODUCT_CD,
        COALESCE(NULLIF(CASE v_language WHEN 'ENG' THEN p.PRODUCT_NM_ENG
            WHEN 'KOR' THEN p.PRODUCT_NM_KOR WHEN 'CHINA' THEN p.PRODUCT_NM_CHINA
            WHEN 'CHN' THEN p.PRODUCT_NM_CHINA ELSE p.PRODUCT_NM_VIET END,''),
            p.PRODUCT_NM_VIET,'[Chưa liên kết sản phẩm]') AS PRODUCT_NAME,
        COALESCE(NULLIF(u.UNIT_NM,''),i.UNIT_CD,'') AS UNIT_NAME,
        COALESCE(CONCAT('ID:',COALESCE(NULLIF(i.UNIT_ID,0),u.UNIT_ID)),NULLIF(i.UNIT_CD,'')) AS UNIT_KEY,
        i.QUANTITY,i.UNIT_PRICE,w.LAST_KEY,
        CASE WHEN w.LINE_COUNT=1 THEN 1 WHEN w.TOTAL_WEIGHT>0 THEN i.AMOUNT_WEIGHT/w.TOTAL_WEIGHT
            WHEN s.POSTING_AMOUNT=0 THEN 0 END AS ALLOCATION_WEIGHT,
        CAST(NULL AS DECIMAL(24,2)) AS PURCHASE_AMOUNT
    FROM tmp_pj_source s INNER JOIN tmp_pj_inventory i ON i.CHITDETAIL_ID=s.CHITDETAIL_ID
    INNER JOIN tmp_pj_weights w ON w.CHITDETAIL_ID=s.CHITDETAIL_ID
    LEFT JOIN product_info p ON p.COMPANY_CD=s.COMPANY_CD AND p.ISDEL='0'
        AND p.PRODUCT_ID=COALESCE(NULLIF(i.PRODUCT_ID,0),
            (SELECT MIN(p2.PRODUCT_ID) FROM product_info p2 WHERE p2.COMPANY_CD=s.COMPANY_CD
                AND p2.PRODUCT_CD=i.PRODUCT_CD AND p2.ISDEL='0'))
    LEFT JOIN product_unit u ON u.COMPANY_CD=s.COMPANY_CD AND u.ISDEL='0'
        AND u.UNIT_ID=COALESCE(NULLIF(i.UNIT_ID,0),
            (SELECT MIN(u2.UNIT_ID) FROM product_unit u2 WHERE u2.COMPANY_CD=s.COMPANY_CD
                AND u2.UNIT_CD=i.UNIT_CD AND u2.ISDEL='0'));
    ALTER TABLE tmp_pj_lines ADD PRIMARY KEY (INVENTORY_KEY);
    UPDATE tmp_pj_lines SET PURCHASE_AMOUNT=ROUND(POSTING_AMOUNT*ALLOCATION_WEIGHT,2);
    DROP TEMPORARY TABLE tmp_pj_weights;
    CREATE TEMPORARY TABLE tmp_pj_weights AS
    SELECT CHITDETAIL_ID,SUM(CASE WHEN INVENTORY_KEY<>LAST_KEY THEN PURCHASE_AMOUNT ELSE 0 END) AS OTHER_AMOUNT
    FROM tmp_pj_lines GROUP BY CHITDETAIL_ID;
    UPDATE tmp_pj_lines l INNER JOIN tmp_pj_weights w ON w.CHITDETAIL_ID=l.CHITDETAIL_ID
    SET l.PURCHASE_AMOUNT=l.POSTING_AMOUNT-IFNULL(w.OTHER_AMOUNT,0)
    WHERE l.INVENTORY_KEY=l.LAST_KEY AND l.ALLOCATION_WEIGHT IS NOT NULL;

    CREATE TEMPORARY TABLE tmp_pj_totals ENGINE=InnoDB AS
    SELECT ACCOUNT_KEY,ACCOUNT_CD,GROUP_KEY,MAX(PRODUCT_CD) AS PRODUCT_CD,MAX(PRODUCT_NAME) AS PRODUCT_NAME,
        CASE WHEN COUNT(DISTINCT UNIT_KEY)=1 AND COUNT(UNIT_KEY)=COUNT(*) AND COUNT(QUANTITY)=COUNT(*)
            THEN SUM(QUANTITY) END AS QUANTITY,
        CASE WHEN COUNT(PURCHASE_AMOUNT)=COUNT(*) THEN SUM(PURCHASE_AMOUNT) END AS PURCHASE_AMOUNT,
        SUM(CASE WHEN PURCHASE_AMOUNT IS NULL THEN 1 ELSE 0 END) AS UNALLOCATED_COUNT
    FROM tmp_pj_lines GROUP BY ACCOUNT_KEY,ACCOUNT_CD,GROUP_KEY;

    CREATE TEMPORARY TABLE tmp_pj_rows (
        __ROW_KEY VARCHAR(220) NOT NULL PRIMARY KEY,__PARENT_ROW_KEY VARCHAR(220),
        __ROW_TYPE VARCHAR(20) NOT NULL,__ROW_LEVEL INT NOT NULL,__ROW_SORT INT NOT NULL,
        __ACCOUNT_CD VARCHAR(20),__ACCOUNT_KEY VARCHAR(100),__GROUP_KEY VARCHAR(180),__PRODUCT_CD VARCHAR(50),
        __ROW_LABEL TEXT,__CHIT_ID BIGINT,__CHIT_TYPE VARCHAR(20),__DEBIT VARCHAR(20),__CREDIT VARCHAR(20),
        ENTRY_DATE DATE,DOCUMENT_NO VARCHAR(50),DOCUMENT_DATE DATE,INVOICE_NO VARCHAR(50),
        CUSTOMER_CD VARCHAR(20),CUSTOMER_OWN_CD VARCHAR(20),CUSTOMER_NAME TEXT,
        COUNTER_ACCOUNT VARCHAR(20),PRODUCT_CD VARCHAR(50),PRODUCT_NAME VARCHAR(255),UNIT_NAME VARCHAR(200),
        QUANTITY DECIMAL(24,6),UNIT_PRICE DECIMAL(24,6),PURCHASE_AMOUNT DECIMAL(24,2),
        EXCHANGE_RATES DECIMAL(24,6),NOTE_CD VARCHAR(20)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
    INSERT INTO tmp_pj_rows (__ROW_KEY,__ROW_TYPE,__ROW_LEVEL,__ROW_SORT,__ACCOUNT_CD,__ACCOUNT_KEY,
        __GROUP_KEY,__PRODUCT_CD,__ROW_LABEL)
    SELECT t.ACCOUNT_KEY,'GROUP',0,0,t.ACCOUNT_CD,t.ACCOUNT_KEY,'','',
        CONCAT('Tên tài khoản: ',COALESCE(NULLIF(t.ACCOUNT_CD,''),'[Chưa có tài khoản]'),' ',
            COALESCE(NULLIF(CASE v_language WHEN 'ENG' THEN a.ACCTITLE_NM_ENG
                WHEN 'KOR' THEN a.ACCTITLE_NM_KOR ELSE a.ACCTITLE_NM_VIET END,''),a.ACCTITLE_NM_VIET,''))
    FROM (SELECT DISTINCT ACCOUNT_KEY,ACCOUNT_CD FROM tmp_pj_totals) t
    LEFT JOIN acclist_info a ON a.COMPANY_CD=p_COMPANY_CD AND a.ISDEL='0'
        AND a.ACC_ID=(SELECT MIN(a2.ACC_ID) FROM acclist_info a2 WHERE a2.COMPANY_CD=p_COMPANY_CD
            AND a2.ACC_CD=t.ACCOUNT_CD AND a2.ISDEL='0');
    INSERT INTO tmp_pj_rows (__ROW_KEY,__PARENT_ROW_KEY,__ROW_TYPE,__ROW_LEVEL,__ROW_SORT,
        __ACCOUNT_CD,__ACCOUNT_KEY,__GROUP_KEY,__PRODUCT_CD,__ROW_LABEL)
    SELECT GROUP_KEY,ACCOUNT_KEY,'GROUP',1,0,ACCOUNT_CD,ACCOUNT_KEY,GROUP_KEY,PRODUCT_CD,
        CONCAT('Mã sản phẩm: ',PRODUCT_CD,' - ',PRODUCT_NAME,
            CASE WHEN UNALLOCATED_COUNT>0 THEN ' [Chưa phân bổ giá trị]' ELSE '' END)
    FROM tmp_pj_totals;
    INSERT INTO tmp_pj_rows (__ROW_KEY,__PARENT_ROW_KEY,__ROW_TYPE,__ROW_LEVEL,__ROW_SORT,
        __ACCOUNT_CD,__ACCOUNT_KEY,__GROUP_KEY,__PRODUCT_CD,__CHIT_ID,__CHIT_TYPE,__DEBIT,__CREDIT,
        ENTRY_DATE,DOCUMENT_NO,DOCUMENT_DATE,INVOICE_NO,CUSTOMER_CD,CUSTOMER_OWN_CD,CUSTOMER_NAME,
        COUNTER_ACCOUNT,PRODUCT_CD,PRODUCT_NAME,UNIT_NAME,QUANTITY,UNIT_PRICE,PURCHASE_AMOUNT,EXCHANGE_RATES,NOTE_CD)
    SELECT CONCAT('D:',p_COMPANY_CD,':',INVENTORY_KEY),GROUP_KEY,'DETAIL',2,1,
        ACCOUNT_CD,ACCOUNT_KEY,GROUP_KEY,PRODUCT_CD,CHIT_ID,CHIT_TYPE,DEBIT,CREDIT,
        STR_TO_DATE(NULLIF(ENTRY_YMD,''),'%Y%m%d'),DOCUMENT_NO,STR_TO_DATE(NULLIF(DOCUMENT_YMD,''),'%Y%m%d'),
        INVOICE_NO,CUSTOMER_CD,CUSTOMER_OWN_CD,CUSTOMER_NAME,ACCOUNT_CD,PRODUCT_CD,PRODUCT_NAME,UNIT_NAME,
        QUANTITY,CASE WHEN CHIT_TYPE='PD' THEN NULL ELSE
            COALESCE(NULLIF(UNIT_PRICE,0),PURCHASE_AMOUNT/NULLIF(QUANTITY,0)) END,
        PURCHASE_AMOUNT,EXCHANGE_RATES,NOTE_CD FROM tmp_pj_lines;
    -- Subtotal labels use a normal text cell, so group-label rendering/export
    -- cannot hide their quantity and amount cells.
    INSERT INTO tmp_pj_rows (__ROW_KEY,__PARENT_ROW_KEY,__ROW_TYPE,__ROW_LEVEL,__ROW_SORT,
        __ACCOUNT_CD,__ACCOUNT_KEY,__GROUP_KEY,__PRODUCT_CD,CUSTOMER_NAME,QUANTITY,PURCHASE_AMOUNT)
    SELECT CONCAT(GROUP_KEY,':TOTAL'),GROUP_KEY,'SUBTOTAL',2,2,ACCOUNT_CD,ACCOUNT_KEY,GROUP_KEY,PRODUCT_CD,
        CONCAT(PRODUCT_CD,' - ',PRODUCT_NAME,
            CASE WHEN UNALLOCATED_COUNT>0 THEN ' [Chưa phân bổ giá trị]' ELSE '' END),QUANTITY,PURCHASE_AMOUNT
    FROM tmp_pj_totals;

    SELECT r.*,1 AS __KEEP_ROW_ORDER,'AP' AS __MODULE_CD,
        CASE WHEN r.__ROW_TYPE='DETAIL' THEN 'DOCUMENT' ELSE 'NONE' END AS __LINK_TYPE,
        r.__ROW_KEY AS ROW_KEY,r.__ROW_TYPE AS ROW_TYPE,r.__ROW_SORT AS LINE_SORT,
        p_COMPANY_CD AS COMPANY_CD,'JOURNAL' AS REPORT_GROUP_KEY,
        CONCAT('Năm ',LEFT(v_from_ymd,4)) AS REPORT_YEAR_TEXT,'Đơn vị tính: Đồng' AS AMOUNT_UNIT_TEXT,
        COALESCE(r.__ROW_LABEL,r.CUSTOMER_NAME) AS DESCRIPTION,
        CASE WHEN r.__ROW_TYPE='DETAIL' AND r.__DEBIT LIKE '156%' THEN r.PURCHASE_AMOUNT END AS PURCHASE_GOODS_AMOUNT,
        CASE WHEN r.__ROW_TYPE='DETAIL' AND r.__DEBIT LIKE '152%' THEN r.PURCHASE_AMOUNT END AS PURCHASE_RAW_MATERIAL_AMOUNT,
        CASE WHEN r.__ROW_TYPE='DETAIL' AND r.__DEBIT NOT LIKE '156%' AND r.__DEBIT NOT LIKE '152%'
            THEN r.__DEBIT END AS OTHER_DEBIT_ACCOUNT,
        CASE WHEN r.__ROW_TYPE='DETAIL' AND r.__DEBIT NOT LIKE '156%' AND r.__DEBIT NOT LIKE '152%'
            THEN r.PURCHASE_AMOUNT END AS OTHER_DEBIT_AMOUNT,
        CASE WHEN r.__ROW_TYPE='DETAIL' AND r.__CREDIT LIKE '331%' THEN r.PURCHASE_AMOUNT END AS SELLER_PAYABLE_AMOUNT,
        NULL AS RECEIVABLE_AMOUNT,NULL AS SALES_GOODS_AMOUNT,NULL AS SALES_FINISHED_AMOUNT,NULL AS SALES_SERVICE_AMOUNT,
        '' AS LEDGER_MARK,'' AS LINE_NO,NULL AS DEBIT_AMOUNT,NULL AS CREDIT_AMOUNT
    FROM tmp_pj_rows r ORDER BY r.__ACCOUNT_CD,r.__ACCOUNT_KEY,r.__PRODUCT_CD,r.__GROUP_KEY,
        r.__ROW_SORT,r.ENTRY_DATE,r.DOCUMENT_NO,r.__ROW_KEY;
    DROP TEMPORARY TABLE tmp_pj_source,tmp_pj_inventory,tmp_pj_weights,tmp_pj_lines,tmp_pj_totals,tmp_pj_rows;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_receipt_voucher
DROP PROCEDURE IF EXISTS `rpt_receipt_voucher`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_receipt_voucher`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHIT_ID BIGINT,
    IN p_CHIT_IDS TEXT,
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_chit_ids TEXT;
    DECLARE v_language VARCHAR(20);

    SET v_chit_ids = REPLACE(REPLACE(REPLACE(REPLACE(IFNULL(TRIM(p_CHIT_IDS), ''), '|', ','), ';', ','), CHAR(10), ','), CHAR(13), ',');
    SET v_chit_ids = IF(v_chit_ids = '' AND IFNULL(p_CHIT_ID, 0) > 0, CAST(p_CHIT_ID AS CHAR), v_chit_ids);
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));

    SELECT
        h.CHIT_ID,
        h.COMPANY_CD,
        h.CHIT_CD,
        h.CHIT_NO,
        h.CHIT_YMD,
        h.CHIT_YMD AS HEADER_DATE_TEXT,
        h.CHIT_YMD AS SIGNATURE_DATE_TEXT,
        COALESCE(NULLIF(TRIM(h.PAYER_INFO), ''), detail.CUSTOMER_NAME, '') AS PARTNER_NAME,
        '' AS PARTNER_ADDRESS,
        COALESCE(
            NULLIF(TRIM(CASE v_language WHEN 'ENG' THEN desc_en.DESCRIPTION WHEN 'KOR' THEN desc_ko.DESCRIPTION ELSE desc_vi.DESCRIPTION END), ''),
            NULLIF(TRIM(ext.NOTE), ''),
            detail.DETAIL_DESCRIPTION,
            ''
        ) AS REASON,
        IFNULL(h.AMOUNT, IFNULL(detail.DETAIL_AMOUNT, 0)) AS AMOUNT,
        NULL AS AMOUNT_TEXT,
        NULL AS AMOUNT_IN_WORDS,
        CASE WHEN IFNULL(detail.FC_TYPE, '') <> '' AND IFNULL(detail.FC_AMOUNT, 0) > 0 THEN detail.FC_AMOUNT ELSE NULL END AS FC_AMOUNT,
        CASE WHEN IFNULL(detail.FC_TYPE, '') <> '' AND IFNULL(detail.FC_AMOUNT, 0) > 0 THEN detail.FC_TYPE ELSE NULL END AS FC_TYPE,
        CASE WHEN IFNULL(detail.FC_TYPE, '') <> '' AND IFNULL(detail.FC_RATE, 0) > 0 THEN detail.FC_RATE ELSE NULL END AS FC_RATE,
        NULL AS EXCHANGE_RATE_TEXT,
        NULL AS CONVERTED_AMOUNT_TEXT,
        IFNULL(detail.DEBIT_ACCOUNT, '') AS DEBIT_ACCOUNT,
        IFNULL(detail.CREDIT_ACCOUNT, '') AS CREDIT_ACCOUNT,
        IFNULL(detail.DETAIL_COUNT, 0) AS DETAIL_COUNT,
        NULL AS ATTACHMENT_TEXT,
        NULL AS REFERENCE_TEXT,
        IFNULL(ext.NOTE, '') AS NOTE,
        NULL AS NOTE_TEXT,
        COALESCE(NULLIF(TRIM(h.UPDATE_BY), ''), NULLIF(TRIM(h.CREATE_BY), ''), '') AS CREATE_BY
    FROM chitinfo h
    LEFT JOIN chitinfo_ext ext ON ext.COMPANY_CD = h.COMPANY_CD AND ext.CHIT_ID = h.CHIT_ID AND IFNULL(ext.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo desc_vi ON desc_vi.COMPANY_CD = h.COMPANY_CD AND desc_vi.CHIT_ID = h.CHIT_ID AND desc_vi.LANG_TYPE = 'VIET' AND IFNULL(desc_vi.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo desc_en ON desc_en.COMPANY_CD = h.COMPANY_CD AND desc_en.CHIT_ID = h.CHIT_ID AND desc_en.LANG_TYPE = 'ENG' AND IFNULL(desc_en.ISDEL, '0') = '0'
    LEFT JOIN chitdescriptioninfo desc_ko ON desc_ko.COMPANY_CD = h.COMPANY_CD AND desc_ko.CHIT_ID = h.CHIT_ID AND desc_ko.LANG_TYPE = 'KOR' AND IFNULL(desc_ko.ISDEL, '0') = '0'
    LEFT JOIN (
        SELECT
            d.CHIT_ID,
            COUNT(*) AS DETAIL_COUNT,
            SUM(IFNULL(d.AMOUNT, 0)) AS DETAIL_AMOUNT,
            SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(UPPER(TRIM(IFNULL(d.FC_TYPE, ''))), '') ORDER BY IFNULL(d.SORT, 0), d.CHITDETAIL_ID SEPARATOR ','), ',', 1) AS FC_TYPE,
            SUM(IFNULL(d.FC_AMOUNT, 0)) AS FC_AMOUNT,
            MAX(CASE WHEN IFNULL(d.FC_RATE, 0) > 0 THEN d.FC_RATE ELSE 0 END) AS FC_RATE,
            GROUP_CONCAT(DISTINCT NULLIF(TRIM(d.DEBIT), '') ORDER BY d.DEBIT SEPARATOR ', ') AS DEBIT_ACCOUNT,
            GROUP_CONCAT(DISTINCT NULLIF(TRIM(d.CREDIT), '') ORDER BY d.CREDIT SEPARATOR ', ') AS CREDIT_ACCOUNT,
            SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(COALESCE(customer.CUSTOMER_NM_VIET, '')), '') ORDER BY IFNULL(d.SORT, 0), d.CHITDETAIL_ID SEPARATOR '\n'), '\n', 1) AS CUSTOMER_NAME,
            SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(COALESCE(detail_desc_vi.DESCRIPTION, detail_desc_en.DESCRIPTION, detail_desc_ko.DESCRIPTION, '')), '') ORDER BY IFNULL(d.SORT, 0), d.CHITDETAIL_ID SEPARATOR '\n'), '\n', 1) AS DETAIL_DESCRIPTION
        FROM chitdetailinfo d
        LEFT JOIN chitdetailinfo_ext ext ON ext.COMPANY_CD = d.COMPANY_CD AND ext.CHITDETAIL_ID = d.CHITDETAIL_ID AND IFNULL(ext.ISDEL, '0') = '0'
        LEFT JOIN customer_info customer ON customer.COMPANY_CD = ext.COMPANY_CD AND customer.CUSTOMER_ID = ext.CUSTOMER_ID AND IFNULL(customer.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_desc_vi ON detail_desc_vi.COMPANY_CD = d.COMPANY_CD AND detail_desc_vi.CHITDETAIL_ID = d.CHITDETAIL_ID AND detail_desc_vi.LANG_TYPE = 'VIET' AND IFNULL(detail_desc_vi.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_desc_en ON detail_desc_en.COMPANY_CD = d.COMPANY_CD AND detail_desc_en.CHITDETAIL_ID = d.CHITDETAIL_ID AND detail_desc_en.LANG_TYPE = 'ENG' AND IFNULL(detail_desc_en.ISDEL, '0') = '0'
        LEFT JOIN chitdetaildescriptioninfo detail_desc_ko ON detail_desc_ko.COMPANY_CD = d.COMPANY_CD AND detail_desc_ko.CHITDETAIL_ID = d.CHITDETAIL_ID AND detail_desc_ko.LANG_TYPE = 'KOR' AND IFNULL(detail_desc_ko.ISDEL, '0') = '0'
        WHERE d.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(d.ISDEL, '0') = '0'
        GROUP BY d.CHIT_ID
    ) detail ON detail.CHIT_ID = h.CHIT_ID
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'AR'
      AND h.CHIT_TYPE = 'RC'
      AND IFNULL(h.ISDEL, '0') = '0'
      AND v_chit_ids <> ''
      AND FIND_IN_SET(CAST(h.CHIT_ID AS CHAR) COLLATE utf8_unicode_ci, v_chit_ids COLLATE utf8_unicode_ci) > 0
    ORDER BY h.CHIT_YMD, h.CHIT_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_sales_detail
DROP PROCEDURE IF EXISTS `rpt_sales_detail`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_sales_detail`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_from_ymd VARCHAR(8);
    DECLARE v_to_ymd VARCHAR(8);
    DECLARE v_language VARCHAR(20);
    DECLARE v_group_concat_max_len BIGINT UNSIGNED DEFAULT NULL;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        DROP TEMPORARY TABLE IF EXISTS tmp_sd_source, tmp_sd_inventory, tmp_sd_weights,
            tmp_sd_lines, tmp_sd_totals, tmp_sd_rows;
        IF v_group_concat_max_len IS NOT NULL THEN
            SET SESSION group_concat_max_len=v_group_concat_max_len;
        END IF;
        RESIGNAL;
    END;

    SET v_from_ymd = DATE_FORMAT(IFNULL(p_FROM_DATE, MAKEDATE(YEAR(CURDATE()), 1)), '%Y%m%d');
    SET v_to_ymd = DATE_FORMAT(IFNULL(p_TO_DATE, CURDATE()), '%Y%m%d');
    SET v_language = UPPER(TRIM(IFNULL(p_LANGUAGE, 'VIET')));
    IF NULLIF(TRIM(p_COMPANY_CD),'') IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
    END IF;
    IF v_from_ymd > v_to_ymd THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fromDate must be earlier than or equal to toDate';
    END IF;
    DROP TEMPORARY TABLE IF EXISTS tmp_sd_source, tmp_sd_inventory, tmp_sd_weights,
        tmp_sd_lines, tmp_sd_totals, tmp_sd_rows;
    SET v_group_concat_max_len=@@SESSION.group_concat_max_len;
    SET SESSION group_concat_max_len=GREATEST(v_group_concat_max_len,65535);

    -- Revenue/contra-revenue entries only: a separate 131/333 VAT posting is
    -- not another sale. Aggregate language/VAT rows before joining inventory.
    CREATE TEMPORARY TABLE tmp_sd_source AS
    SELECT h.COMPANY_CD, h.CHIT_ID, d.CHITDETAIL_ID, h.CHIT_TYPE, h.CHIT_ID_COGS AS HEADER_COGS_ID,
        h.CHIT_YMD AS ENTRY_YMD,
        COALESCE(NULLIF(h.CHIT_NO, ''), h.CHIT_CD) AS DOCUMENT_NO,
        COALESCE(NULLIF(d.CHIT_YMD, ''), h.CHIT_YMD) AS DOCUMENT_YMD,
        COALESCE(hd.DESCRIPTION, h.PAYER_INFO, '') AS DESCRIPTION_1,
        COALESCE(dd.DESCRIPTION, '') AS DESCRIPTION_2,
        CASE WHEN d.CREDIT LIKE '511%' OR d.CREDIT LIKE '521%'
            THEN d.DEBIT ELSE d.CREDIT END AS CORRESPONDING_ACCOUNT,
        d.DEBIT, d.CREDIT, d.SORT,
        CASE WHEN h.CHIT_TYPE IN ('SD','SR') THEN -ABS(d.AMOUNT)
             WHEN d.DEBIT LIKE '511%' OR d.DEBIT LIKE '521%' THEN -d.AMOUNT
             ELSE d.AMOUNT END AS SALES_AMOUNT,
        CASE WHEN h.CHIT_TYPE IN ('SD','SR') THEN -ABS(v.VAT_AMOUNT)
             ELSE v.VAT_AMOUNT END AS TAX_AMOUNT,
        v.INVOICE_NO, v.INVOICE_YMD
    FROM chitinfo h
    INNER JOIN chitdetailinfo d ON d.COMPANY_CD=h.COMPANY_CD
        AND d.CHIT_ID=h.CHIT_ID AND d.ISDEL='0'
    LEFT JOIN (
        SELECT COMPANY_CD, CHIT_ID,
            COALESCE(MAX(CASE WHEN LANG_TYPE=v_language THEN NULLIF(DESCRIPTION,'') END),
                     MAX(CASE WHEN LANG_TYPE='VIET' THEN NULLIF(DESCRIPTION,'') END)) AS DESCRIPTION
        FROM chitdescriptioninfo WHERE COMPANY_CD=p_COMPANY_CD AND ISDEL='0'
        GROUP BY COMPANY_CD, CHIT_ID
    ) hd ON hd.COMPANY_CD=h.COMPANY_CD AND hd.CHIT_ID=h.CHIT_ID
    LEFT JOIN (
        SELECT COMPANY_CD, CHITDETAIL_ID,
            COALESCE(MAX(CASE WHEN LANG_TYPE=v_language THEN NULLIF(DESCRIPTION,'') END),
                     MAX(CASE WHEN LANG_TYPE='VIET' THEN NULLIF(DESCRIPTION,'') END)) AS DESCRIPTION
        FROM chitdetaildescriptioninfo WHERE COMPANY_CD=p_COMPANY_CD AND ISDEL='0'
        GROUP BY COMPANY_CD, CHITDETAIL_ID
    ) dd ON dd.COMPANY_CD=d.COMPANY_CD AND dd.CHITDETAIL_ID=d.CHITDETAIL_ID
    LEFT JOIN (
        SELECT COMPANY_CD, CHITDETAIL_ID, SUM(VAT_AMOUNT) AS VAT_AMOUNT,
            GROUP_CONCAT(DISTINCT COALESCE(NULLIF(VAT_CHIT_NO,''),NULLIF(VAT_CHIT_NO_2,''))
                ORDER BY VAT_CHIT_NO SEPARATOR ', ') AS INVOICE_NO,
            CASE WHEN COUNT(DISTINCT NULLIF(VAT_YMD,''))=1 THEN MAX(NULLIF(VAT_YMD,'')) END AS INVOICE_YMD
        FROM chitdetailinfo_vat WHERE COMPANY_CD=p_COMPANY_CD AND ISDEL='0'
        GROUP BY COMPANY_CD, CHITDETAIL_ID
    ) v ON v.COMPANY_CD=d.COMPANY_CD AND v.CHITDETAIL_ID=d.CHITDETAIL_ID
    WHERE h.COMPANY_CD=p_COMPANY_CD AND h.INPUT_TYPE='AR'
        AND h.CHIT_TYPE IN ('SO','SD','SR') AND h.ISDEL='0'
        AND h.CHIT_YMD BETWEEN v_from_ymd AND v_to_ymd
        AND (d.CREDIT LIKE '511%' OR d.DEBIT LIKE '511%'
             OR d.CREDIT LIKE '521%' OR d.DEBIT LIKE '521%');
    ALTER TABLE tmp_sd_source ADD PRIMARY KEY (CHITDETAIL_ID);

    CREATE TEMPORARY TABLE tmp_sd_inventory (
        INVENTORY_KEY VARCHAR(50) NOT NULL PRIMARY KEY,
        CHITDETAIL_ID BIGINT NOT NULL, PRODUCT_ID BIGINT NULL, PRODUCT_CD VARCHAR(50),
        UNIT_ID BIGINT NULL, UNIT_CD VARCHAR(20), QUANTITY DECIMAL(24,6),
        UNIT_PRICE DECIMAL(24,6), ORIGINAL_UNIT_PRICE DECIMAL(24,6),
        REVENUE_WEIGHT DECIMAL(24,6), COGS_AMOUNT DECIMAL(24,6),
        COGS_DOCUMENT_NO VARCHAR(50), COGS_DOCUMENT_YMD VARCHAR(8),
        KEY IX_SD_INVENTORY_DETAIL (CHITDETAIL_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8;
    INSERT INTO tmp_sd_inventory
    SELECT CONCAT('OUT:',o.OUTPUT_ID), o.CHITDETAIL_ID, o.PRODUCT_ID, o.PRODUCT_CD,
        o.UNIT_ID, o.UNIT_CD, o.QUANTITY, o.REVENUE_UNIT_PRICE_CC, o.UNIT_PRICE_CC,
        ABS(o.REVENUE_AMOUNT_CC),
        ROUND(CASE WHEN s.CHIT_TYPE='SD' THEN 0 ELSE COALESCE(CASE WHEN ch.CHIT_ID IS NOT NULL THEN cd.AMOUNT END,o.AMOUNT_CC) END,2),
        COALESCE(NULLIF(ch.CHIT_NO,''),ch.CHIT_CD), ch.CHIT_YMD
    FROM chit_inventory_output o
    INNER JOIN tmp_sd_source s ON s.CHITDETAIL_ID=o.CHITDETAIL_ID AND s.COMPANY_CD=o.COMPANY_CD
        AND s.CHIT_TYPE IN ('SO','SD')
    LEFT JOIN chitdetailinfo cd ON cd.COMPANY_CD=o.COMPANY_CD
        AND cd.CHITDETAIL_ID=o.CHITDETAIL_ID_COGS AND cd.ISDEL='0'
        AND cd.DEBIT LIKE '632%'
    LEFT JOIN chit_inventory_info ih ON ih.COMPANY_CD=o.COMPANY_CD
        AND ih.INVENTORY_ID=o.INVENTORY_ID AND ih.CHIT_TYPE=o.CHIT_TYPE AND ih.ISDEL='0'
    LEFT JOIN chitinfo ch ON ch.COMPANY_CD=o.COMPANY_CD
        AND ch.CHIT_ID=COALESCE(cd.CHIT_ID,ih.CHIT_ID_COGS,s.HEADER_COGS_ID) AND ch.ISDEL='0'
        AND ch.INPUT_TYPE='AR' AND ch.CHIT_TYPE IN ('OT','IO_COGS')
    WHERE o.COMPANY_CD=p_COMPANY_CD AND o.ISDEL='0';

    -- Returns use inventory INPUT, with negative revenue/quantity/cost.
    INSERT INTO tmp_sd_inventory
    SELECT CONCAT('IN:',i.INPUT_ID), i.CHITDETAIL_ID, i.PRODUCT_ID, i.PRODUCT_CD,
        i.UNIT_ID, i.UNIT_CD, -ABS(i.QUANTITY), NULL, i.UNIT_PRICE_CC,
        NULL, -ROUND(ABS(i.AMOUNT_CC),2),
        COALESCE(NULLIF(ch.CHIT_NO,''),ch.CHIT_CD),ch.CHIT_YMD
    FROM chit_inventory_input i
    INNER JOIN tmp_sd_source s ON s.CHITDETAIL_ID=i.CHITDETAIL_ID AND s.COMPANY_CD=i.COMPANY_CD
        AND s.CHIT_TYPE='SR'
    LEFT JOIN chitinfo ch ON ch.COMPANY_CD=s.COMPANY_CD AND ch.CHIT_ID=s.HEADER_COGS_ID
        AND ch.ISDEL='0' AND ch.INPUT_TYPE='AR' AND ch.CHIT_TYPE IN ('OT','IO_COGS')
    WHERE i.COMPANY_CD=p_COMPANY_CD AND i.ISDEL='0';

    -- No invented product for services or unlinked accounting lines. Each has
    -- its own group, so unrelated services are never merged by description.
    CREATE TEMPORARY TABLE tmp_sd_weights AS SELECT DISTINCT CHITDETAIL_ID FROM tmp_sd_inventory;
    INSERT INTO tmp_sd_inventory (INVENTORY_KEY,CHITDETAIL_ID)
    SELECT CONCAT('ACC:',s.CHITDETAIL_ID),s.CHITDETAIL_ID
    FROM tmp_sd_source s LEFT JOIN tmp_sd_weights w ON w.CHITDETAIL_ID=s.CHITDETAIL_ID
    WHERE w.CHITDETAIL_ID IS NULL;
    DROP TEMPORARY TABLE tmp_sd_weights;

    CREATE TEMPORARY TABLE tmp_sd_weights AS
    SELECT CHITDETAIL_ID, COUNT(*) AS LINE_COUNT, MAX(INVENTORY_KEY) AS LAST_KEY,
        SUM(ABS(REVENUE_WEIGHT)) AS REVENUE_WEIGHT, SUM(ABS(QUANTITY)) AS QUANTITY_WEIGHT
    FROM tmp_sd_inventory GROUP BY CHITDETAIL_ID;
    ALTER TABLE tmp_sd_weights ADD PRIMARY KEY (CHITDETAIL_ID);

    -- Accounting amount is authoritative. Split a posting by stored inventory
    -- revenue, otherwise quantity. No equal split when no basis is available.
    CREATE TEMPORARY TABLE tmp_sd_lines AS
    SELECT s.*, i.INVENTORY_KEY,
        CONCAT('P:',p_COMPANY_CD,':',CASE WHEN i.PRODUCT_ID IS NOT NULL AND i.PRODUCT_ID>0
            THEN CONCAT('ID:',i.PRODUCT_ID) WHEN NULLIF(i.PRODUCT_CD,'') IS NOT NULL
            THEN CONCAT('CD:',i.PRODUCT_CD) ELSE CONCAT('UNLINKED:',s.CHITDETAIL_ID) END) AS GROUP_KEY,
        COALESCE(NULLIF(i.PRODUCT_CD,''),p.PRODUCT_CD,'') AS PRODUCT_CD,
        COALESCE(NULLIF(CASE v_language WHEN 'ENG' THEN p.PRODUCT_NM_ENG
            WHEN 'KOR' THEN p.PRODUCT_NM_KOR WHEN 'CHN' THEN p.PRODUCT_NM_CHINA
            WHEN 'CHINA' THEN p.PRODUCT_NM_CHINA ELSE p.PRODUCT_NM_VIET END,''),
            p.PRODUCT_NM_VIET, NULLIF(s.DESCRIPTION_2,''),s.DESCRIPTION_1,'') AS PRODUCT_NAME,
        COALESCE(NULLIF(u.UNIT_NM,''),i.UNIT_CD,'') AS UNIT_NAME,
        COALESCE(CONCAT('ID:',NULLIF(i.UNIT_ID,0)),NULLIF(i.UNIT_CD,'')) AS UNIT_KEY,
        CASE WHEN s.CHIT_TYPE='SD' THEN NULL ELSE i.QUANTITY END AS QUANTITY,
        i.UNIT_PRICE, i.ORIGINAL_UNIT_PRICE, i.COGS_AMOUNT, i.COGS_DOCUMENT_NO, i.COGS_DOCUMENT_YMD,
        CASE WHEN w.LINE_COUNT=1 THEN 1
             WHEN w.REVENUE_WEIGHT>0 THEN ABS(i.REVENUE_WEIGHT)/w.REVENUE_WEIGHT
             WHEN w.QUANTITY_WEIGHT>0 THEN ABS(i.QUANTITY)/w.QUANTITY_WEIGHT END AS ALLOCATION_WEIGHT,
        w.LAST_KEY, w.LINE_COUNT,
        CAST(NULL AS DECIMAL(24,2)) AS LINE_AMOUNT,
        CAST(NULL AS DECIMAL(24,2)) AS LINE_TAX
    FROM tmp_sd_source s
    INNER JOIN tmp_sd_inventory i ON i.CHITDETAIL_ID=s.CHITDETAIL_ID
    INNER JOIN tmp_sd_weights w ON w.CHITDETAIL_ID=s.CHITDETAIL_ID
    LEFT JOIN product_info p ON p.COMPANY_CD=s.COMPANY_CD AND p.PRODUCT_ID=i.PRODUCT_ID AND p.ISDEL='0'
    LEFT JOIN product_unit u ON u.COMPANY_CD=s.COMPANY_CD AND u.UNIT_ID=i.UNIT_ID AND u.ISDEL='0';
    ALTER TABLE tmp_sd_lines ADD PRIMARY KEY (INVENTORY_KEY);
    UPDATE tmp_sd_lines SET LINE_AMOUNT=ROUND(SALES_AMOUNT*ALLOCATION_WEIGHT,2),
        LINE_TAX=ROUND(TAX_AMOUNT*ALLOCATION_WEIGHT,2);

    -- The last line receives rounding residual, never a duplicated posting.
    DROP TEMPORARY TABLE tmp_sd_weights;
    CREATE TEMPORARY TABLE tmp_sd_weights AS
    SELECT CHITDETAIL_ID,
        SUM(CASE WHEN INVENTORY_KEY<>LAST_KEY THEN LINE_AMOUNT ELSE 0 END) AS OTHER_AMOUNT,
        SUM(CASE WHEN INVENTORY_KEY<>LAST_KEY THEN LINE_TAX ELSE 0 END) AS OTHER_TAX
    FROM tmp_sd_lines GROUP BY CHITDETAIL_ID;
    UPDATE tmp_sd_lines l INNER JOIN tmp_sd_weights w ON w.CHITDETAIL_ID=l.CHITDETAIL_ID
    SET l.LINE_AMOUNT=l.SALES_AMOUNT-IFNULL(w.OTHER_AMOUNT,0),
        l.LINE_TAX=l.TAX_AMOUNT-IFNULL(w.OTHER_TAX,0)
    WHERE l.INVENTORY_KEY=l.LAST_KEY AND l.ALLOCATION_WEIGHT IS NOT NULL;

    CREATE TEMPORARY TABLE tmp_sd_totals AS
    SELECT GROUP_KEY, MAX(PRODUCT_CD) AS PRODUCT_CD, MAX(PRODUCT_NAME) AS PRODUCT_NAME,
        CASE WHEN COUNT(DISTINCT UNIT_KEY)=1 AND COUNT(UNIT_KEY)=COUNT(QUANTITY)
            THEN SUM(QUANTITY) END AS QUANTITY,
        SUM(LINE_AMOUNT) AS SALES_AMOUNT, SUM(COGS_AMOUNT) AS COGS_AMOUNT,
        SUM(LINE_TAX) AS TAX_AMOUNT,
        SUM(LINE_AMOUNT-IFNULL(COGS_AMOUNT,0)) AS DIFFERENCE_AMOUNT,
        SUM(CASE WHEN LINE_AMOUNT IS NULL THEN 1 ELSE 0 END) AS UNALLOCATED_COUNT
    FROM tmp_sd_lines GROUP BY GROUP_KEY;
    -- Missing allocation must not silently turn an incomplete total into zero.
    UPDATE tmp_sd_totals SET SALES_AMOUNT=NULL, DIFFERENCE_AMOUNT=NULL WHERE UNALLOCATED_COUNT>0;

    CREATE TEMPORARY TABLE tmp_sd_rows (
        __ROW_KEY VARCHAR(180) NOT NULL, __PARENT_ROW_KEY VARCHAR(180) NULL,
        __ROW_TYPE VARCHAR(20) NOT NULL, __ROW_LEVEL INT NOT NULL,
        __ROW_SORT BIGINT NOT NULL, __GROUP_KEY VARCHAR(150) NOT NULL,
        __PRODUCT_CD VARCHAR(50), __ROW_LABEL VARCHAR(1100),
        __CHIT_ID BIGINT NULL, __CHIT_TYPE VARCHAR(20) NULL,
        __DEBIT VARCHAR(20) NULL, __CREDIT VARCHAR(20) NULL,
        ENTRY_DATE DATE NULL, DOCUMENT_NO VARCHAR(50) NULL, DOCUMENT_DATE DATE NULL,
        DESCRIPTION_1 VARCHAR(1100) NULL, DESCRIPTION_2 VARCHAR(1000) NULL,
        CORRESPONDING_ACCOUNT VARCHAR(20) NULL, UNIT_NAME VARCHAR(200) NULL,
        QUANTITY DECIMAL(24,6) NULL, UNIT_PRICE DECIMAL(24,6) NULL,
        SALES_AMOUNT DECIMAL(24,2) NULL, ORIGINAL_UNIT_PRICE DECIMAL(24,6) NULL,
        COGS_AMOUNT DECIMAL(24,2) NULL, DIFFERENCE_AMOUNT DECIMAL(24,2) NULL,
        TAX_AMOUNT DECIMAL(24,2) NULL, OTHER_AMOUNT DECIMAL(24,2) NULL,
        INVOICE_DATE DATE NULL, INVOICE_NO TEXT NULL,
        COGS_DOCUMENT_NO VARCHAR(50) NULL, COGS_DOCUMENT_DATE DATE NULL,
        PRIMARY KEY (__ROW_KEY)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8;

    INSERT INTO tmp_sd_rows (__ROW_KEY,__PARENT_ROW_KEY,__ROW_TYPE,__ROW_LEVEL,__ROW_SORT,
        __GROUP_KEY,__PRODUCT_CD,__ROW_LABEL,ENTRY_DATE)
    SELECT GROUP_KEY,NULL,'GROUP',0,0,GROUP_KEY,PRODUCT_CD,
        CONCAT(CASE v_language WHEN 'ENG' THEN 'Product: ' WHEN 'KOR' THEN '제품: ' ELSE 'Mã sản phẩm: ' END,
            CASE WHEN PRODUCT_CD='' THEN '[Không có mã] ' ELSE CONCAT(PRODUCT_CD,' - ') END,PRODUCT_NAME),NULL
    FROM tmp_sd_totals;

    UPDATE tmp_sd_rows SET DESCRIPTION_1=__ROW_LABEL WHERE __ROW_TYPE='GROUP';

    INSERT INTO tmp_sd_rows (__ROW_KEY,__PARENT_ROW_KEY,__ROW_TYPE,__ROW_LEVEL,__ROW_SORT,
        __GROUP_KEY,__PRODUCT_CD,__CHIT_ID,__CHIT_TYPE,__DEBIT,__CREDIT,
        ENTRY_DATE,DOCUMENT_NO,DOCUMENT_DATE,DESCRIPTION_1,DESCRIPTION_2,CORRESPONDING_ACCOUNT,
        UNIT_NAME,QUANTITY,UNIT_PRICE,SALES_AMOUNT,ORIGINAL_UNIT_PRICE,COGS_AMOUNT,DIFFERENCE_AMOUNT,
        TAX_AMOUNT,INVOICE_DATE,INVOICE_NO,COGS_DOCUMENT_NO,COGS_DOCUMENT_DATE)
    SELECT CONCAT('D:',INVENTORY_KEY),GROUP_KEY,'DETAIL',1,1,GROUP_KEY,PRODUCT_CD,CHIT_ID,CHIT_TYPE,DEBIT,CREDIT,
        STR_TO_DATE(NULLIF(ENTRY_YMD,''),'%Y%m%d'),DOCUMENT_NO,STR_TO_DATE(NULLIF(DOCUMENT_YMD,''),'%Y%m%d'),
        DESCRIPTION_1,DESCRIPTION_2,CORRESPONDING_ACCOUNT,UNIT_NAME,QUANTITY,
        COALESCE(NULLIF(UNIT_PRICE,0),LINE_AMOUNT/NULLIF(QUANTITY,0)),LINE_AMOUNT,ORIGINAL_UNIT_PRICE,
        COGS_AMOUNT,LINE_AMOUNT-IFNULL(COGS_AMOUNT,0),LINE_TAX,
        STR_TO_DATE(NULLIF(INVOICE_YMD,''),'%Y%m%d'),INVOICE_NO,COGS_DOCUMENT_NO,
        STR_TO_DATE(NULLIF(COGS_DOCUMENT_YMD,''),'%Y%m%d')
    FROM tmp_sd_lines;

    INSERT INTO tmp_sd_rows (__ROW_KEY,__PARENT_ROW_KEY,__ROW_TYPE,__ROW_LEVEL,__ROW_SORT,
        __GROUP_KEY,__PRODUCT_CD,DESCRIPTION_1,SALES_AMOUNT,QUANTITY,COGS_AMOUNT,DIFFERENCE_AMOUNT,TAX_AMOUNT)
    SELECT CONCAT(t.GROUP_KEY,':S:',n.N),t.GROUP_KEY,
        CASE WHEN n.N=5 THEN 'SUBTOTAL' ELSE 'SUMMARY' END,1,n.N+1,t.GROUP_KEY,t.PRODUCT_CD,
        CASE n.N
            WHEN 1 THEN CASE v_language WHEN 'ENG' THEN 'Total transactions' WHEN 'KOR' THEN '발생 합계' ELSE 'Cộng số phát sinh' END
            WHEN 2 THEN CASE v_language WHEN 'ENG' THEN '- Net revenue' WHEN 'KOR' THEN '- 순매출' ELSE '- Doanh thu thuần' END
            WHEN 3 THEN CASE v_language WHEN 'ENG' THEN '- Cost of goods sold' WHEN 'KOR' THEN '- 매출원가' ELSE '- Giá vốn hàng bán' END
            WHEN 4 THEN CASE v_language WHEN 'ENG' THEN '- Gross profit' WHEN 'KOR' THEN '- 매출총이익' ELSE '- Lợi nhuận gộp' END
            ELSE NULL END,
        CASE WHEN n.N=3 THEN t.COGS_AMOUNT WHEN n.N=4 THEN t.DIFFERENCE_AMOUNT ELSE t.SALES_AMOUNT END,
        CASE WHEN n.N=5 THEN t.QUANTITY END,
        CASE WHEN n.N=5 THEN t.COGS_AMOUNT END,
        CASE WHEN n.N=5 THEN t.DIFFERENCE_AMOUNT END,
        CASE WHEN n.N=5 THEN t.TAX_AMOUNT END
    FROM tmp_sd_totals t CROSS JOIN (SELECT 1 AS N UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5) n;

    SELECT r.*, 1 AS __KEEP_ROW_ORDER, 'AR' AS __MODULE_CD,
        CASE WHEN r.__ROW_TYPE='DETAIL' THEN 'DOCUMENT' ELSE 'NONE' END AS __LINK_TYPE,
        -- Retained aliases for existing configured layouts; hidden in the new grid.
        r.__ROW_KEY AS ROW_KEY, r.__ROW_TYPE AS ROW_TYPE, r.__ROW_SORT AS LINE_SORT,
        p_COMPANY_CD AS COMPANY_CD, 'SALES_DETAIL' AS REPORT_GROUP_KEY,
        CONCAT('Năm ',LEFT(v_from_ymd,4)) AS REPORT_YEAR_TEXT, 'Đơn vị tính: Đồng' AS AMOUNT_UNIT_TEXT,
        r.DESCRIPTION_1 AS DESCRIPTION,
        CASE WHEN r.__ROW_TYPE='DETAIL' AND r.__DEBIT LIKE '131%' THEN r.SALES_AMOUNT END AS RECEIVABLE_AMOUNT,
        CASE WHEN r.__ROW_TYPE='DETAIL' AND r.__CREDIT LIKE '5111%' THEN r.SALES_AMOUNT END AS SALES_GOODS_AMOUNT,
        CASE WHEN r.__ROW_TYPE='DETAIL' AND r.__CREDIT LIKE '5112%' THEN r.SALES_AMOUNT END AS SALES_FINISHED_AMOUNT,
        CASE WHEN r.__ROW_TYPE='DETAIL' AND r.__CREDIT LIKE '5113%' THEN r.SALES_AMOUNT END AS SALES_SERVICE_AMOUNT
    FROM tmp_sd_rows r
    ORDER BY r.__PRODUCT_CD,r.__GROUP_KEY,r.__ROW_SORT,r.ENTRY_DATE,r.DOCUMENT_NO,r.__ROW_KEY;

    DROP TEMPORARY TABLE tmp_sd_source, tmp_sd_inventory, tmp_sd_weights, tmp_sd_lines, tmp_sd_totals, tmp_sd_rows;
    SET SESSION group_concat_max_len=v_group_concat_max_len;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.rpt_sales_journal
DROP PROCEDURE IF EXISTS `rpt_sales_journal`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `rpt_sales_journal`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_FROM_DATE DATE,
    IN p_TO_DATE DATE,
    IN p_LANGUAGE VARCHAR(20)
)
BEGIN
    DECLARE v_language VARCHAR(20);
    DECLARE v_saved_group_concat_max_len BIGINT UNSIGNED DEFAULT NULL;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        DROP TEMPORARY TABLE IF EXISTS tmp_gl_sales_result;
        DROP TEMPORARY TABLE IF EXISTS tmp_gl_sales_groups;
        DROP TEMPORARY TABLE IF EXISTS tmp_gl_sales_totals;
        DROP TEMPORARY TABLE IF EXISTS tmp_gl_sales_base;
        DROP TEMPORARY TABLE IF EXISTS tmp_gl_sales_tax_accounts;
        DROP TEMPORARY TABLE IF EXISTS tmp_gl_sales_invoice_scope;
        IF v_saved_group_concat_max_len IS NOT NULL THEN
            SET SESSION group_concat_max_len=v_saved_group_concat_max_len;
        END IF;
        RESIGNAL;
    END;
    IF p_FROM_DATE IS NULL OR p_TO_DATE IS NULL OR p_FROM_DATE > p_TO_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='A valid sales journal date range is required';
    END IF;
    IF NULLIF(TRIM(p_COMPANY_CD), '') IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='COMPANY_CD is required';
    END IF;
    SET v_language=UPPER(TRIM(IFNULL(p_LANGUAGE,'VIET')));
    IF v_language='CHINA' THEN SET v_language='CHN'; END IF;
    -- Count invoice identities per header. Unlabelled VAT lines may be shared only
    -- when the header does not mix different invoices.
    DROP TEMPORARY TABLE IF EXISTS tmp_gl_sales_invoice_scope;
    CREATE TEMPORARY TABLE tmp_gl_sales_invoice_scope ENGINE=MyISAM AS
    SELECT header.COMPANY_CD, header.CHIT_ID,
        COUNT(DISTINCT CASE WHEN COALESCE(NULLIF(TRIM(v.VAT_CHIT_NO), ''), NULLIF(TRIM(v.VAT_CHIT_NO_2), ''), NULLIF(TRIM(v.VAT_INVOICE_CD), ''), '') <> ''
            THEN CONCAT(COALESCE(NULLIF(TRIM(v.VAT_CHIT_NO), ''), NULLIF(TRIM(v.VAT_CHIT_NO_2), ''), NULLIF(TRIM(v.VAT_INVOICE_CD), ''), ''), '|', IFNULL(TRIM(v.VAT_SERIAL_NO), ''), '|', IFNULL(TRIM(v.VAT_YMD), ''))
            ELSE NULL END) AS INVOICE_COUNT
    FROM chitinfo header
    INNER JOIN chitdetailinfo detail ON detail.COMPANY_CD=header.COMPANY_CD
        AND detail.CHIT_ID=header.CHIT_ID AND detail.ISDEL='0'
    LEFT JOIN chitdetailinfo_vat v ON v.COMPANY_CD=detail.COMPANY_CD
        AND v.CHITDETAIL_ID=detail.CHITDETAIL_ID AND v.ISDEL='0'
    WHERE header.COMPANY_CD=p_COMPANY_CD AND header.ISDEL='0'
        AND header.INPUT_TYPE='AR' AND header.CHIT_TYPE IN ('SO','SD','SR')
        AND header.CHIT_YMD BETWEEN DATE_FORMAT(p_FROM_DATE,'%Y%m%d') AND DATE_FORMAT(p_TO_DATE,'%Y%m%d')
    GROUP BY header.COMPANY_CD, header.CHIT_ID;
    ALTER TABLE tmp_gl_sales_invoice_scope ADD PRIMARY KEY (COMPANY_CD,CHIT_ID);

    -- Account lists must not be silently truncated by the default 1024-byte limit.
    SET v_saved_group_concat_max_len=@@SESSION.group_concat_max_len;
    SET SESSION group_concat_max_len=GREATEST(v_saved_group_concat_max_len,65535);
    DROP TEMPORARY TABLE IF EXISTS tmp_gl_sales_tax_accounts;
    CREATE TEMPORARY TABLE tmp_gl_sales_tax_accounts ENGINE=MyISAM AS
    SELECT source.COMPANY_CD, source.CHITDETAIL_ID,
        GROUP_CONCAT(DISTINCT CASE WHEN tax_detail.CREDIT LIKE '3331%' THEN TRIM(tax_detail.CREDIT) ELSE TRIM(tax_detail.DEBIT) END ORDER BY CASE WHEN tax_detail.CREDIT LIKE '3331%' THEN TRIM(tax_detail.CREDIT) ELSE TRIM(tax_detail.DEBIT) END SEPARATOR ', ') AS TAX_ACCOUNT,
        GROUP_CONCAT(DISTINCT CASE WHEN tax_detail.CREDIT LIKE '3331%' THEN TRIM(tax_detail.DEBIT) ELSE TRIM(tax_detail.CREDIT) END ORDER BY CASE WHEN tax_detail.CREDIT LIKE '3331%' THEN TRIM(tax_detail.DEBIT) ELSE TRIM(tax_detail.CREDIT) END SEPARATOR ', ') AS TAX_COUNTER_ACCOUNT
    FROM tmp_gl_sales_invoice_scope scope
    INNER JOIN chitdetailinfo source ON source.COMPANY_CD=scope.COMPANY_CD
        AND source.CHIT_ID=scope.CHIT_ID AND source.ISDEL='0'
    LEFT JOIN chitdetailinfo_vat source_vat ON source_vat.COMPANY_CD=source.COMPANY_CD
        AND source_vat.CHITDETAIL_ID=source.CHITDETAIL_ID AND source_vat.ISDEL='0'
    INNER JOIN chitdetailinfo tax_detail ON tax_detail.COMPANY_CD=source.COMPANY_CD
        AND tax_detail.CHIT_ID=source.CHIT_ID AND tax_detail.ISDEL='0'
        AND ((tax_detail.CREDIT LIKE '3331%' AND IFNULL(tax_detail.DEBIT,'') NOT LIKE '3331%')
            OR (tax_detail.DEBIT LIKE '3331%' AND IFNULL(tax_detail.CREDIT,'') NOT LIKE '3331%'))
    LEFT JOIN chitdetailinfo_vat tax_vat ON tax_vat.COMPANY_CD=tax_detail.COMPANY_CD
        AND tax_vat.CHITDETAIL_ID=tax_detail.CHITDETAIL_ID AND tax_vat.ISDEL='0'
    WHERE (
        (COALESCE(NULLIF(TRIM(source_vat.VAT_CHIT_NO), ''), NULLIF(TRIM(source_vat.VAT_CHIT_NO_2), ''), NULLIF(TRIM(source_vat.VAT_INVOICE_CD), ''), '') <> '' AND COALESCE(NULLIF(TRIM(source_vat.VAT_CHIT_NO), ''), NULLIF(TRIM(source_vat.VAT_CHIT_NO_2), ''), NULLIF(TRIM(source_vat.VAT_INVOICE_CD), ''), '')=COALESCE(NULLIF(TRIM(tax_vat.VAT_CHIT_NO), ''), NULLIF(TRIM(tax_vat.VAT_CHIT_NO_2), ''), NULLIF(TRIM(tax_vat.VAT_INVOICE_CD), ''), ''))
        OR ((COALESCE(NULLIF(TRIM(source_vat.VAT_CHIT_NO), ''), NULLIF(TRIM(source_vat.VAT_CHIT_NO_2), ''), NULLIF(TRIM(source_vat.VAT_INVOICE_CD), ''), '')='' OR COALESCE(NULLIF(TRIM(tax_vat.VAT_CHIT_NO), ''), NULLIF(TRIM(tax_vat.VAT_CHIT_NO_2), ''), NULLIF(TRIM(tax_vat.VAT_INVOICE_CD), ''), '')='') AND scope.INVOICE_COUNT<=1)
    )
        AND (NULLIF(TRIM(source_vat.VAT_SERIAL_NO),'') IS NULL OR NULLIF(TRIM(tax_vat.VAT_SERIAL_NO),'') IS NULL
            OR TRIM(source_vat.VAT_SERIAL_NO)=TRIM(tax_vat.VAT_SERIAL_NO))
        AND (NULLIF(TRIM(source_vat.VAT_YMD),'') IS NULL OR NULLIF(TRIM(tax_vat.VAT_YMD),'') IS NULL
            OR TRIM(source_vat.VAT_YMD)=TRIM(tax_vat.VAT_YMD))
    GROUP BY source.COMPANY_CD, source.CHITDETAIL_ID;
    ALTER TABLE tmp_gl_sales_tax_accounts ADD PRIMARY KEY (COMPANY_CD,CHITDETAIL_ID);
    SET SESSION group_concat_max_len=v_saved_group_concat_max_len;
    SET v_saved_group_concat_max_len=NULL;

    DROP TEMPORARY TABLE IF EXISTS tmp_gl_sales_base;
    CREATE TEMPORARY TABLE tmp_gl_sales_base ENGINE=MyISAM AS
    SELECT
        CAST('' AS CHAR(300)) AS PRODUCT_GROUP,
        STR_TO_DATE(h.CHIT_YMD, '%Y%m%d') AS ENTRY_DATE,
        COALESCE(NULLIF(h.CHIT_NO, ''), h.CHIT_CD, '') AS DOCUMENT_NO,
        COALESCE(NULLIF(vat.VAT_CHIT_NO, ''), NULLIF(vat.VAT_CHIT_NO_2, ''), vat.VAT_INVOICE_CD, '') AS INVOICE_NO,
        STR_TO_DATE(NULLIF(vat.VAT_YMD, ''), '%Y%m%d') AS INVOICE_DATE,
        COALESCE(hdesc.DESCRIPTION, '') AS DESCRIPTION_1,
        COALESCE(NULLIF(ddesc.DESCRIPTION, ''), io.SUMMARY, '') AS DESCRIPTION_2,
        COALESCE(NULLIF(ext.CUSTOMER_CD, ''), customer.CUSTOMER_CD, '') AS CUSTOMER_CD,
        COALESCE(ext.CUSTOMER_OWN_CD, '') AS CUSTOMER_OWN_CD,
        COALESCE(NULLIF(CASE v_language WHEN 'ENG' THEN customer.CUSTOMER_NM_ENG WHEN 'KOR' THEN customer.CUSTOMER_NM_KOR WHEN 'CHN' THEN customer.CUSTOMER_NM_CHINA ELSE customer.CUSTOMER_NM_VIET END, ''), customer.CUSTOMER_NM_VIET, '') AS CUSTOMER_NAME,
        COALESCE(NULLIF(customer_ext.TAX_CD, ''), customer_ext.IDNUMBER, '') AS CUSTOMER_TAX_CODE,
        COALESCE(d.DEBIT, '') AS AR_ACCOUNT,
        COALESCE(d.CREDIT, '') AS REVENUE_ACCOUNT,
        COALESCE(cogs.DEBIT, aggregate_cogs.DEBIT, '') AS COGS_ACCOUNT,
        COALESCE(NULLIF(TRIM(io.PRODUCT_CD), ''), product.PRODUCT_CD, '') AS PRODUCT_CD,
        COALESCE(product.PRODUCT_NM_VIET, '') AS PRODUCT_NAME,
        COALESCE(NULLIF(io.STORE_CD, ''), store_info.STORE_CD, '') AS STORE_CD,
        COALESCE(NULLIF(CASE v_language WHEN 'ENG' THEN store_info.STORE_NM_ENG WHEN 'KOR' THEN store_info.STORE_NM_KOR WHEN 'CHN' THEN store_info.STORE_NM_CHINA ELSE store_info.STORE_NM_VIET END, ''), store_info.STORE_NM_VIET, '') AS STORE_NAME,
        COALESCE(cogs.CREDIT, aggregate_cogs.CREDIT, '') AS STOCK_ACCOUNT,
        COALESCE(ext.DEPARTMENT_CD, '') AS COST_OBJECT_CD,
        COALESCE(NULLIF(CASE v_language WHEN 'ENG' THEN department.DEP_NAME_ENG WHEN 'KOR' THEN department.DEP_NAME_KOR WHEN 'CHN' THEN department.DEP_NAME_CHINA ELSE department.DEP_NAME_VIET END, ''), department.DEP_NAME_VIET, '') AS COST_OBJECT_NAME,
        COALESCE(NULLIF(io.UNIT_CD, ''), unit_info.UNIT_CD, '') AS UNIT_CD,
        COALESCE(NULLIF(unit_info.UNIT_NM, ''), io.UNIT_CD, '') AS UNIT_NAME,
        CAST(io.QUANTITY AS DECIMAL(24,6)) AS QUANTITY,
        CAST(io.REVENUE_UNIT_PRICE_CC AS DECIMAL(24,6)) AS REVENUE_UNIT_PRICE_CC,
        CAST(io.REVENUE_AMOUNT_CC AS DECIMAL(24,6)) AS REVENUE_AMOUNT_CC,
        CAST(CASE WHEN vat.VAT_TAXABLE_AMOUNT <> 0 THEN vat.VAT_AMOUNT / vat.VAT_TAXABLE_AMOUNT * 100 ELSE NULL END AS DECIMAL(18,6)) AS VAT_RATE,
        CAST(io.REVENUE_AMOUNT_TOTAL AS DECIMAL(24,6)) AS REVENUE_AMOUNT_TOTAL,
        CAST(io.AMOUNT_CC AS DECIMAL(24,6)) AS AMOUNT_CC,
        CAST(CASE WHEN cogs.CHITDETAIL_ID IS NOT NULL OR aggregate_cogs.CHITDETAIL_ID IS NOT NULL THEN io.REVENUE_AMOUNT_CC - io.AMOUNT_CC ELSE NULL END AS DECIMAL(24,6)) AS DIFFERENCE,
        CAST(io.EXCHANGE_RATES AS DECIMAL(24,6)) AS EXCHANGE_RATES,
        COALESCE(NULLIF(UPPER(TRIM(io.FC_TYPE)), ''), 'VND') AS FC_TYPE,
        CAST(io.REVENUE_UNIT_PRICE_FC AS DECIMAL(24,6)) AS REVENUE_UNIT_PRICE_FC,
        CAST(io.REVENUE_AMOUNT_FC AS DECIMAL(24,6)) AS REVENUE_AMOUNT_FC,
        CAST(io.AMOUNT_FC AS DECIMAL(24,6)) AS AMOUNT_FC,
        CAST(CASE WHEN cogs.CHITDETAIL_ID IS NOT NULL OR aggregate_cogs.CHITDETAIL_ID IS NOT NULL THEN io.REVENUE_AMOUNT_CC - io.AMOUNT_CC ELSE NULL END AS DECIMAL(24,6)) AS GROSS_PROFIT_AMOUNT,
        tax_accounts.TAX_ACCOUNT AS TAX_ACCOUNT,
        tax_accounts.TAX_COUNTER_ACCOUNT AS TAX_COUNTER_ACCOUNT,
        COALESCE(d.CREDIT, '') AS ACCOUNT_CD,
        COALESCE(account_info.ACCTITLE_NM_VIET, '') AS ACCOUNT_NAME,
        COALESCE(ext.MR_CD, '') AS NOTE_CD,
        CASE WHEN cogs.CHITDETAIL_ID IS NOT NULL OR aggregate_cogs.CHITDETAIL_ID IS NOT NULL THEN CASE v_language WHEN 'ENG' THEN 'Posted' WHEN 'KOR' THEN '전기됨' ELSE 'Đã hạch toán' END ELSE CASE v_language WHEN 'ENG' THEN 'Not posted' WHEN 'KOR' THEN '미전기' ELSE 'Chưa hạch toán giá vốn' END END AS COGS_STATUS,
        CONCAT('P:', io.COMPANY_CD, ':', COALESCE(NULLIF(UPPER(TRIM(io.PRODUCT_CD)), ''), NULLIF(UPPER(TRIM(product.PRODUCT_CD)), ''), CONCAT('ID:', io.PRODUCT_ID), 'UNKNOWN')) AS __GROUP_KEY,
        COALESCE(CONCAT('ID:',io.UNIT_ID), CONCAT('CD:',UPPER(TRIM(io.UNIT_CD)))) AS __UNIT_KEY,
        io.OUTPUT_ID AS __OUTPUT_ID,
        io.SORT AS __DETAIL_SORT,
        h.CHIT_ID AS __CHIT_ID,
        h.CHIT_TYPE AS __CHIT_TYPE,
        CASE WHEN cogs.CHITDETAIL_ID IS NOT NULL OR aggregate_cogs.CHITDETAIL_ID IS NOT NULL THEN 1 ELSE 0 END AS __COST_KNOWN
    FROM chit_inventory_output io
    INNER JOIN chitdetailinfo d ON d.COMPANY_CD=io.COMPANY_CD AND d.CHITDETAIL_ID=io.CHITDETAIL_ID AND d.ISDEL='0'
    INNER JOIN chitinfo h ON h.COMPANY_CD=d.COMPANY_CD AND h.CHIT_ID=d.CHIT_ID AND h.ISDEL='0'
        AND h.INPUT_TYPE='AR' AND h.CHIT_TYPE IN ('SO','SD','SR')
    LEFT JOIN chitdetailinfo_ext ext ON ext.COMPANY_CD=d.COMPANY_CD AND ext.CHITDETAIL_ID=d.CHITDETAIL_ID AND ext.ISDEL='0'
    LEFT JOIN chitdetailinfo_vat vat ON vat.COMPANY_CD=d.COMPANY_CD AND vat.CHITDETAIL_ID=d.CHITDETAIL_ID AND vat.ISDEL='0'
    LEFT JOIN tmp_gl_sales_tax_accounts tax_accounts ON tax_accounts.COMPANY_CD=d.COMPANY_CD
        AND tax_accounts.CHITDETAIL_ID=d.CHITDETAIL_ID
    LEFT JOIN product_info product ON product.COMPANY_CD=io.COMPANY_CD AND product.PRODUCT_ID=io.PRODUCT_ID AND product.ISDEL='0'
    LEFT JOIN store_info ON store_info.COMPANY_CD=io.COMPANY_CD AND store_info.STORE_ID=io.STORE_ID AND store_info.ISDEL='0'
    LEFT JOIN product_unit unit_info ON unit_info.COMPANY_CD=io.COMPANY_CD AND unit_info.UNIT_ID=io.UNIT_ID AND unit_info.ISDEL='0'
    LEFT JOIN department_info department ON department.COMPANY_CD=ext.COMPANY_CD AND department.DEPARTMENT_ID=ext.DEPARTMENT_ID AND department.ISDEL='0'
    LEFT JOIN customer_info customer ON customer.COMPANY_CD=ext.COMPANY_CD AND customer.CUSTOMER_ID=ext.CUSTOMER_ID AND customer.ISDEL='0'
    LEFT JOIN customer_ext ON customer_ext.CUSTOMER_EXT_ID=(SELECT MAX(ce.CUSTOMER_EXT_ID) FROM customer_ext ce
        WHERE ce.COMPANY_CD=customer.COMPANY_CD AND ce.CUSTOMER_ID=customer.CUSTOMER_ID AND ce.ISDEL='0')
    LEFT JOIN acclist_info account_info ON account_info.ACC_ID=(SELECT MIN(a.ACC_ID) FROM acclist_info a
        WHERE a.COMPANY_CD=d.COMPANY_CD AND a.ACC_CD=d.CREDIT AND a.ISDEL='0')
    LEFT JOIN chitdetailinfo cogs ON cogs.COMPANY_CD=io.COMPANY_CD AND cogs.CHITDETAIL_ID=io.CHITDETAIL_ID_COGS AND cogs.ISDEL='0' AND cogs.DEBIT LIKE '632%'
        AND EXISTS (SELECT 1 FROM chitinfo ch WHERE ch.COMPANY_CD=cogs.COMPANY_CD AND ch.CHIT_ID=cogs.CHIT_ID AND ch.ISDEL='0' AND ch.INPUT_TYPE='AR' AND ch.CHIT_TYPE IN ('OT','IO_COGS'))
    LEFT JOIN chit_inventory_info inventory_header ON inventory_header.COMPANY_CD=io.COMPANY_CD
        AND inventory_header.INVENTORY_ID=io.INVENTORY_ID AND inventory_header.CHIT_TYPE=io.CHIT_TYPE AND inventory_header.ISDEL='0'
    LEFT JOIN chitinfo cogs_header ON cogs_header.COMPANY_CD=inventory_header.COMPANY_CD
        AND cogs_header.CHIT_ID=inventory_header.CHIT_ID_COGS AND cogs_header.ISDEL='0'
        AND cogs_header.INPUT_TYPE='AR' AND cogs_header.CHIT_TYPE IN ('OT','IO_COGS')
    -- A single aggregate cost detail supplies accounts only; never repeat its amount per output.
    LEFT JOIN chitdetailinfo aggregate_cogs ON aggregate_cogs.COMPANY_CD=io.COMPANY_CD AND aggregate_cogs.CHIT_ID=cogs_header.CHIT_ID AND aggregate_cogs.ISDEL='0'
        AND aggregate_cogs.CHITDETAIL_ID=COALESCE(inventory_header.CHITDETAIL_ID_COGS,(
        SELECT CASE WHEN COUNT(*)=1 THEN MIN(cd.CHITDETAIL_ID) ELSE NULL END FROM chitdetailinfo cd
        WHERE cd.COMPANY_CD=io.COMPANY_CD AND cd.CHIT_ID=cogs_header.CHIT_ID AND cd.ISDEL='0' AND cd.DEBIT LIKE '632%'))
    LEFT JOIN chitdescriptioninfo hdesc ON hdesc.DESC_ID=(SELECT MAX(hd.DESC_ID) FROM chitdescriptioninfo hd
        WHERE hd.COMPANY_CD=h.COMPANY_CD AND hd.CHIT_ID=h.CHIT_ID AND hd.LANG_TYPE=CASE v_language WHEN 'CHN' THEN 'CHINA' ELSE v_language END AND hd.ISDEL='0')
    LEFT JOIN chitdetaildescriptioninfo ddesc ON ddesc.DESC_ID=(SELECT MAX(dd.DESC_ID) FROM chitdetaildescriptioninfo dd
        WHERE dd.COMPANY_CD=d.COMPANY_CD AND dd.CHITDETAIL_ID=d.CHITDETAIL_ID AND dd.LANG_TYPE=CASE v_language WHEN 'CHN' THEN 'CHINA' ELSE v_language END AND dd.ISDEL='0')
    WHERE io.COMPANY_CD=p_COMPANY_CD AND io.ISDEL='0'
        AND h.CHIT_YMD BETWEEN DATE_FORMAT(p_FROM_DATE,'%Y%m%d') AND DATE_FORMAT(p_TO_DATE,'%Y%m%d');

    -- Detect join regressions instead of silently multiplying sales amounts.
    ALTER TABLE tmp_gl_sales_base ADD PRIMARY KEY (__OUTPUT_ID);

    DROP TEMPORARY TABLE IF EXISTS tmp_gl_sales_groups;
    CREATE TEMPORARY TABLE tmp_gl_sales_groups ENGINE=MyISAM AS
    SELECT __GROUP_KEY,
        MAX(PRODUCT_CD) AS PRODUCT_CD,
        MAX(PRODUCT_NAME) AS PRODUCT_NAME,
        CASE WHEN COUNT(DISTINCT __UNIT_KEY)=1 AND MIN(__UNIT_KEY)<> 'CD:' THEN SUM(QUANTITY) ELSE NULL END AS QUANTITY,
        CASE WHEN COUNT(DISTINCT __UNIT_KEY)=1 THEN MAX(UNIT_CD) ELSE '' END AS UNIT_CD,
        CASE WHEN COUNT(DISTINCT __UNIT_KEY)=1 THEN MAX(UNIT_NAME) ELSE '' END AS UNIT_NAME,
        SUM(REVENUE_AMOUNT_CC) AS REVENUE_AMOUNT_CC,
        SUM(AMOUNT_CC) AS AMOUNT_CC,
        CASE WHEN MIN(__COST_KNOWN)=1 THEN SUM(DIFFERENCE) ELSE NULL END AS DIFFERENCE,
        CASE WHEN MIN(__COST_KNOWN)=1 THEN SUM(GROSS_PROFIT_AMOUNT) ELSE NULL END AS GROSS_PROFIT_AMOUNT,
        CASE WHEN COUNT(DISTINCT FC_TYPE)=1 THEN MAX(FC_TYPE) ELSE '' END AS FC_TYPE,
        CASE WHEN COUNT(DISTINCT FC_TYPE)=1 THEN SUM(REVENUE_AMOUNT_FC) ELSE NULL END AS REVENUE_AMOUNT_FC,
        CASE WHEN COUNT(DISTINCT FC_TYPE)=1 THEN SUM(AMOUNT_FC) ELSE NULL END AS AMOUNT_FC,
        CASE WHEN COUNT(DISTINCT FC_TYPE)=1 THEN SUM(REVENUE_AMOUNT_TOTAL) ELSE NULL END AS REVENUE_AMOUNT_TOTAL
    FROM tmp_gl_sales_base GROUP BY __GROUP_KEY;

    DROP TEMPORARY TABLE IF EXISTS tmp_gl_sales_totals;
    CREATE TEMPORARY TABLE tmp_gl_sales_totals ENGINE=MyISAM AS
    SELECT MAX(PRODUCT_CD) AS PRODUCT_CD,
        MAX(PRODUCT_NAME) AS PRODUCT_NAME,
        CASE WHEN COUNT(DISTINCT __UNIT_KEY)=1 AND MIN(__UNIT_KEY)<> 'CD:' THEN SUM(QUANTITY) ELSE NULL END AS QUANTITY,
        CASE WHEN COUNT(DISTINCT __UNIT_KEY)=1 THEN MAX(UNIT_CD) ELSE '' END AS UNIT_CD,
        CASE WHEN COUNT(DISTINCT __UNIT_KEY)=1 THEN MAX(UNIT_NAME) ELSE '' END AS UNIT_NAME,
        SUM(REVENUE_AMOUNT_CC) AS REVENUE_AMOUNT_CC,
        SUM(AMOUNT_CC) AS AMOUNT_CC,
        CASE WHEN MIN(__COST_KNOWN)=1 THEN SUM(DIFFERENCE) ELSE NULL END AS DIFFERENCE,
        CASE WHEN MIN(__COST_KNOWN)=1 THEN SUM(GROSS_PROFIT_AMOUNT) ELSE NULL END AS GROSS_PROFIT_AMOUNT,
        CASE WHEN COUNT(DISTINCT FC_TYPE)=1 THEN MAX(FC_TYPE) ELSE '' END AS FC_TYPE,
        CASE WHEN COUNT(DISTINCT FC_TYPE)=1 THEN SUM(REVENUE_AMOUNT_FC) ELSE NULL END AS REVENUE_AMOUNT_FC,
        CASE WHEN COUNT(DISTINCT FC_TYPE)=1 THEN SUM(AMOUNT_FC) ELSE NULL END AS AMOUNT_FC,
        CASE WHEN COUNT(DISTINCT FC_TYPE)=1 THEN SUM(REVENUE_AMOUNT_TOTAL) ELSE NULL END AS REVENUE_AMOUNT_TOTAL
    FROM tmp_gl_sales_base HAVING COUNT(*)>0;

    DROP TEMPORARY TABLE IF EXISTS tmp_gl_sales_result;
    CREATE TEMPORARY TABLE tmp_gl_sales_result (
        __ROW_KEY VARCHAR(200) NULL,
        __PARENT_ROW_KEY VARCHAR(200) NULL,
        __ROW_TYPE VARCHAR(20) NULL,
        __ROW_LEVEL INT NULL,
        __ROOT_SORT INT NULL,
        __GROUP_SORT VARCHAR(200) NULL,
        __KIND_SORT INT NULL,
        __LINK_TYPE VARCHAR(20) NULL,
        __CHIT_ID BIGINT NULL,
        __CHIT_TYPE VARCHAR(20) NULL,
        __MODULE_CD VARCHAR(20) NULL,
        __OUTPUT_ID BIGINT NULL,
        __DETAIL_SORT INT NULL,
        PRODUCT_GROUP VARCHAR(300) NULL,
        ENTRY_DATE DATETIME NULL,
        DOCUMENT_NO VARCHAR(300) NULL,
        INVOICE_NO VARCHAR(300) NULL,
        INVOICE_DATE DATETIME NULL,
        DESCRIPTION_1 VARCHAR(1000) NULL,
        DESCRIPTION_2 VARCHAR(1000) NULL,
        CUSTOMER_CD VARCHAR(300) NULL,
        CUSTOMER_OWN_CD VARCHAR(300) NULL,
        CUSTOMER_NAME VARCHAR(300) NULL,
        CUSTOMER_TAX_CODE VARCHAR(300) NULL,
        AR_ACCOUNT VARCHAR(300) NULL,
        REVENUE_ACCOUNT VARCHAR(300) NULL,
        COGS_ACCOUNT VARCHAR(300) NULL,
        PRODUCT_CD VARCHAR(300) NULL,
        PRODUCT_NAME VARCHAR(300) NULL,
        STORE_CD VARCHAR(300) NULL,
        STORE_NAME VARCHAR(300) NULL,
        STOCK_ACCOUNT VARCHAR(300) NULL,
        COST_OBJECT_CD VARCHAR(300) NULL,
        COST_OBJECT_NAME VARCHAR(300) NULL,
        UNIT_CD VARCHAR(300) NULL,
        UNIT_NAME VARCHAR(300) NULL,
        QUANTITY DECIMAL(24,6) NULL,
        REVENUE_UNIT_PRICE_CC DECIMAL(24,6) NULL,
        REVENUE_AMOUNT_CC DECIMAL(24,6) NULL,
        VAT_RATE DECIMAL(24,6) NULL,
        REVENUE_AMOUNT_TOTAL DECIMAL(24,6) NULL,
        AMOUNT_CC DECIMAL(24,6) NULL,
        DIFFERENCE DECIMAL(24,6) NULL,
        EXCHANGE_RATES DECIMAL(24,6) NULL,
        FC_TYPE VARCHAR(300) NULL,
        REVENUE_UNIT_PRICE_FC DECIMAL(24,6) NULL,
        REVENUE_AMOUNT_FC DECIMAL(24,6) NULL,
        AMOUNT_FC DECIMAL(24,6) NULL,
        GROSS_PROFIT_AMOUNT DECIMAL(24,6) NULL,
        TAX_ACCOUNT TEXT NULL,
        TAX_COUNTER_ACCOUNT TEXT NULL,
        ACCOUNT_CD VARCHAR(300) NULL,
        ACCOUNT_NAME VARCHAR(300) NULL,
        NOTE_CD VARCHAR(300) NULL,
        COGS_STATUS VARCHAR(300) NULL
    ) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_gl_sales_result (
        __ROW_KEY,
        __PARENT_ROW_KEY,
        __ROW_TYPE,
        __ROW_LEVEL,
        __ROOT_SORT,
        __GROUP_SORT,
        __KIND_SORT,
        __LINK_TYPE,
        __CHIT_ID,
        __CHIT_TYPE,
        __MODULE_CD,
        __OUTPUT_ID,
        __DETAIL_SORT,
        PRODUCT_GROUP,
        ENTRY_DATE,
        DOCUMENT_NO,
        INVOICE_NO,
        INVOICE_DATE,
        DESCRIPTION_1,
        DESCRIPTION_2,
        CUSTOMER_CD,
        CUSTOMER_OWN_CD,
        CUSTOMER_NAME,
        CUSTOMER_TAX_CODE,
        AR_ACCOUNT,
        REVENUE_ACCOUNT,
        COGS_ACCOUNT,
        PRODUCT_CD,
        PRODUCT_NAME,
        STORE_CD,
        STORE_NAME,
        STOCK_ACCOUNT,
        COST_OBJECT_CD,
        COST_OBJECT_NAME,
        UNIT_CD,
        UNIT_NAME,
        QUANTITY,
        REVENUE_UNIT_PRICE_CC,
        REVENUE_AMOUNT_CC,
        VAT_RATE,
        REVENUE_AMOUNT_TOTAL,
        AMOUNT_CC,
        DIFFERENCE,
        EXCHANGE_RATES,
        FC_TYPE,
        REVENUE_UNIT_PRICE_FC,
        REVENUE_AMOUNT_FC,
        AMOUNT_FC,
        GROSS_PROFIT_AMOUNT,
        TAX_ACCOUNT,
        TAX_COUNTER_ACCOUNT,
        ACCOUNT_CD,
        ACCOUNT_NAME,
        NOTE_CD,
        COGS_STATUS
    )
    SELECT
        __GROUP_KEY AS __ROW_KEY,
        NULL AS __PARENT_ROW_KEY,
        'GROUP' AS __ROW_TYPE,
        0 AS __ROW_LEVEL,
        0 AS __ROOT_SORT,
        __GROUP_KEY AS __GROUP_SORT,
        0 AS __KIND_SORT,
        'NONE' AS __LINK_TYPE,
        NULL AS __CHIT_ID,
        NULL AS __CHIT_TYPE,
        NULL AS __MODULE_CD,
        NULL AS __OUTPUT_ID,
        NULL AS __DETAIL_SORT,
        CONCAT(CASE v_language WHEN 'ENG' THEN 'Product: ' WHEN 'KOR' THEN '제품: ' ELSE 'Mã sản phẩm: ' END,COALESCE(NULLIF(PRODUCT_CD,''),'?'),' - ',PRODUCT_NAME) AS PRODUCT_GROUP,
        NULL AS ENTRY_DATE,
        NULL AS DOCUMENT_NO,
        NULL AS INVOICE_NO,
        NULL AS INVOICE_DATE,
        NULL AS DESCRIPTION_1,
        NULL AS DESCRIPTION_2,
        NULL AS CUSTOMER_CD,
        NULL AS CUSTOMER_OWN_CD,
        NULL AS CUSTOMER_NAME,
        NULL AS CUSTOMER_TAX_CODE,
        NULL AS AR_ACCOUNT,
