-- Dumping structure for procedure am_web_001.save_cash_exchange_revaluation_result
DROP PROCEDURE IF EXISTS `save_cash_exchange_revaluation_result`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `save_cash_exchange_revaluation_result`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_RATE_DATE DATE,
    IN p_FC_TYPE VARCHAR(255),
    IN p_CHIT_YMD_FROM VARCHAR(8),
    IN p_CHIT_YMD_TO VARCHAR(8),
    IN p_RATE_METHOD VARCHAR(30),
    IN p_CREATE_BY VARCHAR(50)
)
BEGIN
    DECLARE v_first_result_id BIGINT DEFAULT 0;
    DECLARE v_saved_count INT DEFAULT 0;

    CALL build_cash_exchange_revaluation_tmp(
        p_COMPANY_CD,
        p_RATE_DATE,
        p_FC_TYPE,
        p_CHIT_YMD_FROM,
        p_CHIT_YMD_TO,
        p_RATE_METHOD
    );

    INSERT INTO exchange_revaluation_result
    (
        COMPANY_CD,
        MODULE_CD,
        CHIT_ID,
        CHITDETAIL_ID,
        RATE_DATE,
        CHIT_CD,
        CHIT_NO,
        CHIT_YMD,
        CHIT_TYPE,
        CHITDETAIL_CD,
        DEBIT,
        CREDIT,
        FC_TYPE,
        FC_AMOUNT,
        OLD_RATE,
        NEW_RATE,
        OLD_AMOUNT,
        NEW_AMOUNT,
        EXCHANGE_DIFF,
        DIFF_TYPE,
        CREATE_BY
    )
    SELECT
        COMPANY_CD,
        MODULE_CD,
        CHIT_ID,
        CHITDETAIL_ID,
        RATE_DATE,
        CHIT_CD,
        CHIT_NO,
        CHIT_YMD,
        CHIT_TYPE,
        CHITDETAIL_CD,
        DEBIT,
        CREDIT,
        FC_TYPE,
        FC_AMOUNT,
        OLD_RATE,
        NEW_RATE,
        OLD_AMOUNT,
        NEW_AMOUNT,
        EXCHANGE_DIFF,
        DIFF_TYPE,
        p_CREATE_BY
    FROM tmp_cash_exchange_revaluation_result
    WHERE ABS(IFNULL(EXCHANGE_DIFF, 0)) >= 0.01
       OR ABS(IFNULL(OLD_RATE, 0) - IFNULL(NEW_RATE, 0)) >= 0.000001
       OR ABS(IFNULL(OLD_AMOUNT, 0) - IFNULL(NEW_AMOUNT, 0)) >= 0.01;

    SET v_first_result_id = LAST_INSERT_ID();
    SET v_saved_count = ROW_COUNT();

    UPDATE chitdetailinfo d
    INNER JOIN tmp_cash_exchange_revaluation_result r
        ON d.COMPANY_CD = r.COMPANY_CD
       AND d.CHITDETAIL_ID = r.CHITDETAIL_ID
    SET d.FC_RATE = r.NEW_RATE,
        d.AMOUNT = r.NEW_AMOUNT,
        d.UPDATE_BY = p_CREATE_BY,
        d.UPDATE_AT = NOW()
    WHERE IFNULL(d.ISDEL, '0') = '0';

    UPDATE chitdetailinfo fx
    INNER JOIN tmp_cash_exchange_revaluation_result r
        ON fx.COMPANY_CD = r.COMPANY_CD
       AND fx.CHIT_ID = r.CHIT_ID
       AND fx.CHITDETAIL_CD = r.GENERATED_CHITDETAIL_CD
    SET fx.CHIT_YMD = r.CHIT_YMD,
        fx.DEBIT = CASE
            WHEN r.EXCHANGE_DIFF > 0 THEN '635'
            WHEN r.EXCHANGE_DIFF < 0 THEN COALESCE(NULLIF(r.COUNTERPART_ACCOUNT, ''), r.TREASURY_ACCOUNT)
            ELSE fx.DEBIT
        END,
        fx.CREDIT = CASE
            WHEN r.EXCHANGE_DIFF > 0 THEN COALESCE(NULLIF(r.COUNTERPART_ACCOUNT, ''), r.TREASURY_ACCOUNT)
            WHEN r.EXCHANGE_DIFF < 0 THEN '515'
            ELSE fx.CREDIT
        END,
        fx.AMOUNT = ABS(r.EXCHANGE_DIFF),
        fx.FC_AMOUNT = 0,
        fx.FC_TYPE = '',
        fx.FC_RATE = 0,
        fx.SORT = r.SOURCE_SORT + 1,
        fx.ISDEL = CASE WHEN ABS(IFNULL(r.EXCHANGE_DIFF, 0)) >= 0.01 THEN '0' ELSE '1' END,
        fx.UPDATE_BY = p_CREATE_BY,
        fx.UPDATE_AT = NOW();

    INSERT INTO chitdetailinfo
    (
        COMPANY_CD,
        CHIT_ID,
        CHIT_CD,
        CHITDETAIL_CD,
        CHIT_YMD,
        DEBIT,
        CREDIT,
        AMOUNT,
        FC_AMOUNT,
        FC_TYPE,
        FC_RATE,
        FC_DATETIME,
        SORT,
        ISDEL,
        CREATE_BY,
        UPDATE_BY
    )
    SELECT
        r.COMPANY_CD,
        r.CHIT_ID,
        IFNULL(r.CHIT_CD, ''),
        r.GENERATED_CHITDETAIL_CD,
        IFNULL(r.CHIT_YMD, ''),
        CASE
            WHEN r.EXCHANGE_DIFF > 0 THEN '635'
            ELSE COALESCE(NULLIF(r.COUNTERPART_ACCOUNT, ''), r.TREASURY_ACCOUNT)
        END,
        CASE
            WHEN r.EXCHANGE_DIFF > 0 THEN COALESCE(NULLIF(r.COUNTERPART_ACCOUNT, ''), r.TREASURY_ACCOUNT)
            ELSE '515'
        END,
        ABS(r.EXCHANGE_DIFF),
        0,
        '',
        0,
        NULL,
        r.SOURCE_SORT + 1,
        '0',
        p_CREATE_BY,
        p_CREATE_BY
    FROM tmp_cash_exchange_revaluation_result r
    LEFT JOIN chitdetailinfo fx
        ON fx.COMPANY_CD = r.COMPANY_CD
       AND fx.CHIT_ID = r.CHIT_ID
       AND fx.CHITDETAIL_CD = r.GENERATED_CHITDETAIL_CD
    WHERE fx.CHITDETAIL_ID IS NULL
      AND ABS(IFNULL(r.EXCHANGE_DIFF, 0)) >= 0.01;

    INSERT INTO chitdetailinfo_ext
    (
        COMPANY_CD,
        CHITDETAIL_ID,
        CHITDETAIL_CD,
        ISDEL,
        CREATE_BY,
        UPDATE_BY
    )
    SELECT
        fx.COMPANY_CD,
        fx.CHITDETAIL_ID,
        fx.CHITDETAIL_CD,
        fx.ISDEL,
        p_CREATE_BY,
        p_CREATE_BY
    FROM chitdetailinfo fx
    INNER JOIN tmp_cash_exchange_revaluation_result r
        ON fx.COMPANY_CD = r.COMPANY_CD
       AND fx.CHIT_ID = r.CHIT_ID
       AND fx.CHITDETAIL_CD = r.GENERATED_CHITDETAIL_CD
    WHERE ABS(IFNULL(r.EXCHANGE_DIFF, 0)) >= 0.01
    ON DUPLICATE KEY UPDATE
        CHITDETAIL_CD = VALUES(CHITDETAIL_CD),
        ISDEL = VALUES(ISDEL),
        UPDATE_BY = VALUES(UPDATE_BY),
        UPDATE_AT = NOW();

    UPDATE chitinfo h
    INNER JOIN (
        SELECT
            d.COMPANY_CD,
            d.CHIT_ID,
            SUM(IFNULL(d.AMOUNT, 0)) AS HEADER_AMOUNT
        FROM chitdetailinfo d
        INNER JOIN (
            SELECT DISTINCT COMPANY_CD, CHIT_ID
            FROM tmp_cash_exchange_revaluation_result
        ) affected
            ON affected.COMPANY_CD = d.COMPANY_CD
           AND affected.CHIT_ID = d.CHIT_ID
        WHERE IFNULL(d.ISDEL, '0') = '0'
        GROUP BY d.COMPANY_CD, d.CHIT_ID
    ) x
        ON h.COMPANY_CD = x.COMPANY_CD
       AND h.CHIT_ID = x.CHIT_ID
    SET h.AMOUNT = x.HEADER_AMOUNT,
        h.UPDATE_BY = p_CREATE_BY,
        h.UPDATE_AT = NOW()
    WHERE IFNULL(h.ISDEL, '0') = '0';

    SELECT
        r.RESULT_ID,
        r.COMPANY_CD,
        r.MODULE_CD,
        r.CHIT_ID,
        r.CHITDETAIL_ID,
        r.CHIT_CD,
        r.CHIT_NO,
        r.CHIT_YMD,
        r.CHIT_TYPE,
        r.CHITDETAIL_CD,
        r.DEBIT,
        r.CREDIT,
        r.FC_TYPE,
        DATE_FORMAT(r.RATE_DATE, '%Y-%m-%d') AS RATE_DATE,
        r.FC_AMOUNT,
        r.OLD_RATE,
        r.NEW_RATE,
        r.OLD_AMOUNT,
        r.NEW_AMOUNT,
        r.EXCHANGE_DIFF,
        r.DIFF_TYPE,
        r.CREATE_BY,
        r.CREATE_AT
    FROM exchange_revaluation_result r
    WHERE v_saved_count > 0
      AND r.RESULT_ID >= v_first_result_id
      AND r.RESULT_ID < v_first_result_id + v_saved_count
      AND IFNULL(r.ISDEL, '0') = '0'
    ORDER BY r.RESULT_ID;

    DROP TEMPORARY TABLE IF EXISTS tmp_cash_exchange_revaluation_result;
    DROP TEMPORARY TABLE IF EXISTS tmp_cash_exchange_revaluation_work;
END//
