-- Dumping structure for procedure am_web_001.save_exchange_revaluation_result
DROP PROCEDURE IF EXISTS `save_exchange_revaluation_result`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `save_exchange_revaluation_result`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_MODULE_CD VARCHAR(10),
    IN p_RATE_DATE DATE,
    IN p_FC_TYPE VARCHAR(255),
    IN p_CHIT_YMD_FROM VARCHAR(8),
    IN p_CHIT_YMD_TO VARCHAR(8),
    IN p_CREATE_BY VARCHAR(50)
)
BEGIN
    DECLARE v_first_result_id BIGINT DEFAULT 0;
    DECLARE v_saved_count INT DEFAULT 0;

    DROP TEMPORARY TABLE IF EXISTS tmp_exchange_revaluation_result;
    CREATE TEMPORARY TABLE tmp_exchange_revaluation_result (
        MODULE_CD VARCHAR(10) NOT NULL,
        COMPANY_CD VARCHAR(20) NOT NULL,
        CHIT_ID BIGINT(20) NOT NULL,
        CHITDETAIL_ID BIGINT(20) NOT NULL,
        RATE_DATE DATE NOT NULL,
        CHIT_CD VARCHAR(50) NULL,
        CHIT_NO VARCHAR(50) NULL,
        CHIT_YMD VARCHAR(8) NULL,
        CHIT_TYPE VARCHAR(20) NULL,
        CHITDETAIL_CD VARCHAR(50) NULL,
        DEBIT VARCHAR(20) NULL,
        CREDIT VARCHAR(20) NULL,
        FC_TYPE VARCHAR(10) NOT NULL,
        FC_AMOUNT DECIMAL(18,2) NOT NULL,
        OLD_RATE DECIMAL(18,6) NOT NULL,
        NEW_RATE DECIMAL(18,6) NOT NULL,
        OLD_AMOUNT DECIMAL(18,2) NOT NULL,
        NEW_AMOUNT DECIMAL(18,2) NOT NULL,
        EXCHANGE_DIFF DECIMAL(18,2) NOT NULL,
        DIFF_TYPE VARCHAR(20) NOT NULL,
        PRIMARY KEY (COMPANY_CD, CHITDETAIL_ID)
    ) ENGINE=InnoDB;

    INSERT INTO tmp_exchange_revaluation_result
    (
        MODULE_CD,
        COMPANY_CD,
        CHIT_ID,
        CHITDETAIL_ID,
        RATE_DATE,
        CHIT_CD,
        CHIT_NO,
        CHIT_YMD,
        CHIT_TYPE,
        CHITDETAIL_CD,
        DEBIT,
        CREDIT,
        FC_TYPE,
        FC_AMOUNT,
        OLD_RATE,
        NEW_RATE,
        OLD_AMOUNT,
        NEW_AMOUNT,
        EXCHANGE_DIFF,
        DIFF_TYPE
    )
    SELECT
        UPPER(IFNULL(h.INPUT_TYPE, '')),
        h.COMPANY_CD,
        h.CHIT_ID,
        d.CHITDETAIL_ID,
        p_RATE_DATE,
        h.CHIT_CD,
        h.CHIT_NO,
        h.CHIT_YMD,
        h.CHIT_TYPE,
        d.CHITDETAIL_CD,
        d.DEBIT,
        d.CREDIT,
        IFNULL(d.FC_TYPE, ''),
        IFNULL(d.FC_AMOUNT, 0),
        IFNULL(d.FC_RATE, 0),
        IFNULL(d.FC_RATE, 0),
        IFNULL(d.AMOUNT, 0),
        CAST(IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0) AS DECIMAL(18,2)),
        CAST((IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0)) - IFNULL(d.AMOUNT, 0) AS DECIMAL(18,2)),
        CASE
            WHEN CAST((IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0)) - IFNULL(d.AMOUNT, 0) AS DECIMAL(18,2)) > 0 THEN 'GAIN'
            WHEN CAST((IFNULL(d.FC_AMOUNT, 0) * IFNULL(d.FC_RATE, 0)) - IFNULL(d.AMOUNT, 0) AS DECIMAL(18,2)) < 0 THEN 'LOSS'
            ELSE 'NONE'
        END
    FROM chitinfo h
    INNER JOIN chitdetailinfo d
        ON d.COMPANY_CD = h.COMPANY_CD
       AND d.CHIT_ID = h.CHIT_ID
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND UPPER(IFNULL(h.INPUT_TYPE, '')) IN ('AR', 'AP')
      AND (IFNULL(p_MODULE_CD, '') = '' OR UPPER(p_MODULE_CD) = 'ALL' OR UPPER(IFNULL(h.INPUT_TYPE, '')) = UPPER(p_MODULE_CD))
      AND (IFNULL(p_FC_TYPE, '') = '' OR FIND_IN_SET(TRIM(IFNULL(d.FC_TYPE, '')), p_FC_TYPE) > 0)
      AND (IFNULL(p_CHIT_YMD_FROM, '') = '' OR IFNULL(h.CHIT_YMD, '') >= p_CHIT_YMD_FROM)
      AND (IFNULL(p_CHIT_YMD_TO, '') = '' OR IFNULL(h.CHIT_YMD, '') <= p_CHIT_YMD_TO)
      AND IFNULL(d.FC_AMOUNT, 0) <> 0
      AND IFNULL(h.ISDEL, '0') = '0'
      AND IFNULL(d.ISDEL, '0') = '0';

    INSERT INTO exchange_revaluation_result
    (
        COMPANY_CD,
        MODULE_CD,
        CHIT_ID,
        CHITDETAIL_ID,
        RATE_DATE,
        CHIT_CD,
        CHIT_NO,
        CHIT_YMD,
        CHIT_TYPE,
        CHITDETAIL_CD,
        DEBIT,
        CREDIT,
        FC_TYPE,
        FC_AMOUNT,
        OLD_RATE,
        NEW_RATE,
        OLD_AMOUNT,
        NEW_AMOUNT,
        EXCHANGE_DIFF,
        DIFF_TYPE,
        CREATE_BY
    )
    SELECT
        COMPANY_CD,
        MODULE_CD,
        CHIT_ID,
        CHITDETAIL_ID,
        RATE_DATE,
        CHIT_CD,
        CHIT_NO,
        CHIT_YMD,
        CHIT_TYPE,
        CHITDETAIL_CD,
        DEBIT,
        CREDIT,
        FC_TYPE,
        FC_AMOUNT,
        OLD_RATE,
        NEW_RATE,
        OLD_AMOUNT,
        NEW_AMOUNT,
        EXCHANGE_DIFF,
        DIFF_TYPE,
        p_CREATE_BY
    FROM tmp_exchange_revaluation_result;

    SET v_first_result_id = LAST_INSERT_ID();
    SET v_saved_count = ROW_COUNT();

    UPDATE chitdetailinfo d
    INNER JOIN tmp_exchange_revaluation_result r
        ON d.COMPANY_CD = r.COMPANY_CD
       AND d.CHITDETAIL_ID = r.CHITDETAIL_ID
    SET d.AMOUNT = r.NEW_AMOUNT,
        d.UPDATE_BY = p_CREATE_BY,
        d.UPDATE_AT = NOW()
    WHERE IFNULL(d.ISDEL, '0') = '0';

    UPDATE chitinfo h
    INNER JOIN (
        SELECT
            d.COMPANY_CD,
            d.CHIT_ID,
            SUM(IFNULL(d.AMOUNT, 0)) AS HEADER_AMOUNT
        FROM chitdetailinfo d
        INNER JOIN (
            SELECT DISTINCT COMPANY_CD, CHIT_ID
            FROM tmp_exchange_revaluation_result
        ) affected
            ON affected.COMPANY_CD = d.COMPANY_CD
           AND affected.CHIT_ID = d.CHIT_ID
        WHERE IFNULL(d.ISDEL, '0') = '0'
        GROUP BY d.COMPANY_CD, d.CHIT_ID
    ) x
        ON h.COMPANY_CD = x.COMPANY_CD
       AND h.CHIT_ID = x.CHIT_ID
    SET h.AMOUNT = x.HEADER_AMOUNT,
        h.UPDATE_BY = p_CREATE_BY,
        h.UPDATE_AT = NOW()
    WHERE IFNULL(h.ISDEL, '0') = '0';

    SELECT
        r.RESULT_ID,
        r.COMPANY_CD,
        r.MODULE_CD,
        r.CHIT_ID,
        r.CHITDETAIL_ID,
        r.CHIT_CD,
        r.CHIT_NO,
        r.CHIT_YMD,
        r.CHIT_TYPE,
        r.CHITDETAIL_CD,
        r.DEBIT,
        r.CREDIT,
        r.FC_TYPE,
        DATE_FORMAT(r.RATE_DATE, '%Y-%m-%d') AS RATE_DATE,
        r.FC_AMOUNT,
        r.OLD_RATE,
        r.NEW_RATE,
        r.OLD_AMOUNT,
        r.NEW_AMOUNT,
        r.EXCHANGE_DIFF,
        r.DIFF_TYPE,
        r.CREATE_BY,
        r.CREATE_AT
    FROM exchange_revaluation_result r
    WHERE v_saved_count > 0
      AND r.RESULT_ID >= v_first_result_id
      AND r.RESULT_ID < v_first_result_id + v_saved_count
      AND IFNULL(r.ISDEL, '0') = '0'
    ORDER BY r.RESULT_ID;

    DROP TEMPORARY TABLE IF EXISTS tmp_exchange_revaluation_result;
END//
DELIMITER ;


