CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setBankInfo`(
  IN p_BANK_ID BIGINT(20),
  IN p_COMPANY_CD VARCHAR(20),
  IN p_BANK_CD VARCHAR(50),
  IN p_BANK_NM VARCHAR(255),
  IN p_ACC_CD VARCHAR(50),
  IN p_PASSBOOK_NM VARCHAR(255),
  IN p_ACCOUNT_NUM VARCHAR(100),
  IN p_CITAD_CODE VARCHAR(50),
  IN p_REMARK VARCHAR(500),
  IN p_ISDEL CHAR(1),
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_bank_cd VARCHAR(50);

  SET v_bank_cd = TRIM(COALESCE(p_BANK_CD, ''));

  IF v_bank_cd = '' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'BANK_CD is required';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM bank_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND BANK_CD = v_bank_cd
      AND (ISDEL IS NULL OR ISDEL = '0')
      AND ((p_BANK_ID IS NULL OR p_BANK_ID = 0) OR BANK_ID <> p_BANK_ID)
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'BANK_CD already exists';
  END IF;

  IF p_BANK_ID IS NULL OR p_BANK_ID = 0 THEN
    INSERT INTO bank_info
    (
      COMPANY_CD,
      BANK_CD,
      BANK_NM,
      ACC_CD,
      PASSBOOK_NM,
      ACCOUNT_NUM,
      CITAD_CODE,
      REMARK,
      ISDEL,
      CREATE_AT,
      UPDATE_AT,
      CREATE_BY,
      UPDATE_BY
    )
    VALUES
    (
      p_COMPANY_CD,
      v_bank_cd,
      p_BANK_NM,
      p_ACC_CD,
      p_PASSBOOK_NM,
      p_ACCOUNT_NUM,
      p_CITAD_CODE,
      p_REMARK,
      COALESCE(p_ISDEL, '0'),
      NOW(),
      NOW(),
      IFNULL(p_USERID, ''),
      IFNULL(p_USERID, '')
    );
  ELSE
    UPDATE bank_info
    SET
      BANK_CD = v_bank_cd,
      BANK_NM = p_BANK_NM,
      ACC_CD = p_ACC_CD,
      PASSBOOK_NM = p_PASSBOOK_NM,
      ACCOUNT_NUM = p_ACCOUNT_NUM,
      CITAD_CODE = p_CITAD_CODE,
      REMARK = p_REMARK,
      ISDEL = COALESCE(p_ISDEL, '0'),
      UPDATE_AT = NOW(),
      UPDATE_BY = IFNULL(p_USERID, UPDATE_BY)
    WHERE COMPANY_CD = p_COMPANY_CD
      AND BANK_ID = p_BANK_ID;
  END IF;
END//
DELIMITER ;


