    SET v_inventory_ymd = CASE
        WHEN NULLIF(TRIM(COALESCE(p_INVENTORY_YMD, '')), '') IS NULL THEN NULL
        WHEN TRIM(p_INVENTORY_YMD) REGEXP '^[0-9]{14}$' THEN STR_TO_DATE(TRIM(p_INVENTORY_YMD), '%Y%m%d%H%i%s')
        WHEN TRIM(p_INVENTORY_YMD) REGEXP '^[0-9]{12}$' THEN STR_TO_DATE(TRIM(p_INVENTORY_YMD), '%Y%m%d%H%i')
        WHEN TRIM(p_INVENTORY_YMD) REGEXP '^[0-9]{8}$' THEN STR_TO_DATE(TRIM(p_INVENTORY_YMD), '%Y%m%d')
        WHEN TRIM(p_INVENTORY_YMD) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN STR_TO_DATE(TRIM(p_INVENTORY_YMD), '%Y-%m-%d')
        ELSE STR_TO_DATE(REPLACE(LEFT(TRIM(p_INVENTORY_YMD), 19), 'T', ' '), '%Y-%m-%d %H:%i:%s')
    END;

