            AMOUNT_TOTAL = COALESCE(p_AMOUNT_TOTAL, 0),
            SUMMARY = COALESCE(p_SUMMARY, ''),
            INVENTORY_YMD = v_inventory_ymd,
            STATE = COALESCE(NULLIF(TRIM(p_STATE), ''), '1'),
            CHITDETAIL_ID = NULLIF(p_CHITDETAIL_ID, 0),
            CHITDETAIL_CD = COALESCE(TRIM(p_CHITDETAIL_CD), ''),
            SORT = COALESCE(p_SORT, 0),
            ISDEL = '0',
            UPDATE_BY = COALESCE(p_USER, ''),
            UPDATE_AT = CURRENT_TIMESTAMP
        WHERE COMPANY_CD = p_COMPANY_CD
          AND OUTPUT_ID = v_output_id;
    ELSE
        INSERT INTO chit_inventory_output
        (
            OUTPUT_CD,
            INVENTORY_ID,
            INVENTORY_CD,
            CHIT_TYPE,
            COMPANY_CD,
            PRODUCT_ID,
            PRODUCT_CD,
            STORE_ID,
            STORE_CD,
            UNIT_ID,
            UNIT_CD,
            QUANTITY,
            UNIT_PRICE_CC,
            REVENUE_UNIT_PRICE_CC,
            FC_TYPE,
            UNIT_PRICE_FC,
            REVENUE_UNIT_PRICE_FC,
            EXCHANGE_RATES,
            AMOUNT_CC,
            REVENUE_AMOUNT_CC,
            AMOUNT_FC,
            REVENUE_AMOUNT_FC,
            REVENUE_AMOUNT_TOTAL,
            AMOUNT_TOTAL,
            SUMMARY,
            INVENTORY_YMD,
            STATE,
            CHITDETAIL_ID,
            CHITDETAIL_CD,
            SORT,
            ISDEL,
            CREATE_BY,
            CREATE_AT,
            UPDATE_BY,
            UPDATE_AT
        )
        VALUES
        (
            COALESCE(v_output_cd, ''),
            NULLIF(p_INVENTORY_ID, 0),
            NULLIF(TRIM(COALESCE(p_INVENTORY_CD, '')), ''),
            NULLIF(TRIM(COALESCE(p_CHIT_TYPE, '')), ''),
            p_COMPANY_CD,
            NULLIF(p_PRODUCT_ID, 0),
            COALESCE(TRIM(p_PRODUCT_CD), ''),
            NULLIF(p_STORE_ID, 0),
            COALESCE(TRIM(p_STORE_CD), ''),
            NULLIF(p_UNIT_ID, 0),
            COALESCE(TRIM(p_UNIT_CD), ''),
            COALESCE(p_QUANTITY, 0),
            COALESCE(p_UNIT_PRICE_CC, 0),
            COALESCE(p_REVENUE_UNIT_PRICE_CC, 0),
            COALESCE(NULLIF(TRIM(p_FC_TYPE), ''), 'VND'),
            COALESCE(p_UNIT_PRICE_FC, 0),
            COALESCE(p_REVENUE_UNIT_PRICE_FC, 0),
            COALESCE(p_EXCHANGE_RATES, 0),
            COALESCE(p_AMOUNT_CC, 0),
            COALESCE(p_REVENUE_AMOUNT_CC, 0),
            COALESCE(p_AMOUNT_FC, 0),
            COALESCE(p_REVENUE_AMOUNT_FC, 0),
            COALESCE(p_REVENUE_AMOUNT_TOTAL, 0),
            COALESCE(p_AMOUNT_TOTAL, 0),
            COALESCE(p_SUMMARY, ''),
            v_inventory_ymd,
            COALESCE(NULLIF(TRIM(p_STATE), ''), '1'),
            NULLIF(p_CHITDETAIL_ID, 0),
            COALESCE(TRIM(p_CHITDETAIL_CD), ''),
            COALESCE(p_SORT, 0),
            '0',
            COALESCE(p_USER, ''),
            CURRENT_TIMESTAMP,
            COALESCE(p_USER, ''),
            CURRENT_TIMESTAMP
        );

        SET v_output_id = LAST_INSERT_ID();
    END IF;

