DROP PROCEDURE IF EXISTS `setChitInventoryTransfer`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setChitInventoryTransfer`(
    IN p_TRANSFER_ID BIGINT,
    IN p_COMPANY_CD VARCHAR(20),
    IN p_TRANSFER_CD VARCHAR(30),
    IN p_TRANSFER_NO VARCHAR(50),
    IN p_TRANSFER_YMD VARCHAR(8),
    IN p_CHIT_TYPE VARCHAR(20),
    IN p_INPUT_TYPE VARCHAR(20),
    IN p_IS_COGS CHAR(1),
    IN p_AMOUNT DECIMAL(18,2),
    IN p_REVENUE_AMOUNT DECIMAL(18,2),
    IN p_TOTAL_QTY DECIMAL(18,6),
    IN p_REMARK VARCHAR(500),
    IN p_CUSTOMER_ID BIGINT,
    IN p_CUSTOMER_CD VARCHAR(20),
    IN p_SORT INT,
    IN p_USER VARCHAR(50)
)
BEGIN
    DECLARE v_transfer_id BIGINT DEFAULT NULL;
    DECLARE v_transfer_cd VARCHAR(30) DEFAULT NULL;

    SET v_transfer_id = NULLIF(p_TRANSFER_ID, 0);
    SET v_transfer_cd = NULLIF(TRIM(COALESCE(p_TRANSFER_CD, '')), '');

    IF v_transfer_id IS NOT NULL AND EXISTS (
        SELECT 1
        FROM chit_inventory_info
        WHERE COMPANY_CD = p_COMPANY_CD
          AND INVENTORY_ID = v_transfer_id
    ) THEN
        UPDATE chit_inventory_info
        SET
            INVENTORY_CD = COALESCE(v_transfer_cd, INVENTORY_CD),
            INVENTORY_NO = COALESCE(TRIM(p_TRANSFER_NO), ''),
            INVENTORY_YMD = COALESCE(TRIM(p_TRANSFER_YMD), ''),
            CHIT_TYPE = COALESCE(NULLIF(TRIM(p_CHIT_TYPE), ''), 'IA'),
            INPUT_TYPE = COALESCE(NULLIF(TRIM(p_INPUT_TYPE), ''), 'INV'),
            IS_COGS = COALESCE(NULLIF(TRIM(p_IS_COGS), ''), '0'),
            AMOUNT = COALESCE(p_AMOUNT, 0),
            REVENUE_AMOUNT = CASE WHEN UPPER(COALESCE(NULLIF(TRIM(p_CHIT_TYPE), ''), 'IA')) = 'IO'
                THEN COALESCE(p_REVENUE_AMOUNT, 0) ELSE 0 END,
            TOTAL_QTY = COALESCE(p_TOTAL_QTY, 0),
            REMARK = NULLIF(TRIM(p_REMARK), ''),
            CUSTOMER_ID = NULLIF(p_CUSTOMER_ID, 0),
            CUSTOMER_CD = NULLIF(TRIM(p_CUSTOMER_CD), ''),
            SORT = COALESCE(p_SORT, 0),
            ISDEL = '0',
            UPDATE_BY = COALESCE(p_USER, ''),
            UPDATE_AT = CURRENT_TIMESTAMP
        WHERE COMPANY_CD = p_COMPANY_CD
          AND INVENTORY_ID = v_transfer_id;
    ELSE
        INSERT INTO chit_inventory_info
        (
            COMPANY_CD,
            INVENTORY_CD,
            INVENTORY_NO,
            INVENTORY_YMD,
            CHIT_TYPE,
            INPUT_TYPE,
            IS_COGS,
            AMOUNT,
            REVENUE_AMOUNT,
            TOTAL_QTY,
            REMARK,
            CUSTOMER_ID,
            CUSTOMER_CD,
            SORT,
            ISDEL,
            CREATE_BY,
            CREATE_AT,
            UPDATE_BY,
            UPDATE_AT
        )
        VALUES
        (
            p_COMPANY_CD,
            COALESCE(v_transfer_cd, ''),
            COALESCE(TRIM(p_TRANSFER_NO), ''),
            COALESCE(TRIM(p_TRANSFER_YMD), ''),
            COALESCE(NULLIF(TRIM(p_CHIT_TYPE), ''), 'IA'),
            COALESCE(NULLIF(TRIM(p_INPUT_TYPE), ''), 'INV'),
            COALESCE(NULLIF(TRIM(p_IS_COGS), ''), '0'),
            COALESCE(p_AMOUNT, 0),
            CASE WHEN UPPER(COALESCE(NULLIF(TRIM(p_CHIT_TYPE), ''), 'IA')) = 'IO'
                THEN COALESCE(p_REVENUE_AMOUNT, 0) ELSE 0 END,
            COALESCE(p_TOTAL_QTY, 0),
            NULLIF(TRIM(p_REMARK), ''),
            NULLIF(p_CUSTOMER_ID, 0),
            NULLIF(TRIM(p_CUSTOMER_CD), ''),
            COALESCE(p_SORT, 0),
            '0',
            COALESCE(p_USER, ''),
            CURRENT_TIMESTAMP,
            COALESCE(p_USER, ''),
            CURRENT_TIMESTAMP
        );

        SET v_transfer_id = LAST_INSERT_ID();
    END IF;

    SELECT NULLIF(TRIM(INVENTORY_CD), '')
      INTO v_transfer_cd
    FROM chit_inventory_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND INVENTORY_ID = v_transfer_id
    LIMIT 1;

    IF v_transfer_cd IS NULL THEN
        SET v_transfer_cd = CONCAT(
            CASE UPPER(COALESCE(NULLIF(TRIM(p_CHIT_TYPE), ''), 'IA'))
                WHEN 'IR' THEN 'IR'
                WHEN 'IO' THEN 'IO'
                WHEN 'IA' THEN 'IA'
                ELSE 'TR'
            END,
            LPAD(v_transfer_id, 10, '0')
        );

        UPDATE chit_inventory_info
        SET INVENTORY_CD = v_transfer_cd,
            UPDATE_BY = COALESCE(p_USER, ''),
            UPDATE_AT = CURRENT_TIMESTAMP
        WHERE COMPANY_CD = p_COMPANY_CD
          AND INVENTORY_ID = v_transfer_id;
    END IF;

    SELECT v_transfer_id AS TRANSFER_ID, v_transfer_cd AS TRANSFER_CD;
END//
DELIMITER ;


