  IN p_CUSTOMER_ID BIGINT(20),
  IN p_COMPANY_CD VARCHAR(20),
  IN p_CUSTOMER_CD VARCHAR(20),
  IN p_CATEGORY_CD VARCHAR(50),
  IN p_CUSTOMER_TYPE VARCHAR(50),
  IN p_CUSTOMER_NM_VIET VARCHAR(255),
  IN p_CUSTOMER_NM_ENG VARCHAR(255),
  IN p_CUSTOMER_NM_KOR VARCHAR(255),
  IN p_CUSTOMER_NM_CHINA VARCHAR(255),
  IN p_ADDRESS VARCHAR(255),
  IN p_TEL VARCHAR(50),
  IN p_FAX VARCHAR(50),
  IN p_TAX_CD VARCHAR(50),
  IN p_BANK_ID BIGINT(20),
  IN p_EMAIL VARCHAR(100),
  IN p_NOTE TEXT,
  IN p_IDNUMBER VARCHAR(50),
  IN p_BUYER_NM VARCHAR(255),
  IN p_ISDEL CHAR(1),
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_customer_id BIGINT(20);
  DECLARE v_customer_key BIGINT(20);
  DECLARE v_customer_ext_id BIGINT(20);
  DECLARE v_customer_cd VARCHAR(20);
  DECLARE v_bank_id BIGINT(20);

  SET v_customer_cd = TRIM(COALESCE(p_CUSTOMER_CD, ''));
  SET v_bank_id = NULLIF(p_BANK_ID, 0);

  IF v_customer_cd = '' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'CUSTOMER_CD is required';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM customer_info
    WHERE COMPANY_CD = p_COMPANY_CD COLLATE utf8_unicode_ci
      AND CUSTOMER_CD = v_customer_cd COLLATE utf8_unicode_ci
      AND (ISDEL IS NULL OR ISDEL = '0')
      AND ((p_CUSTOMER_ID IS NULL OR p_CUSTOMER_ID = 0) OR CUSTOMER_ID <> p_CUSTOMER_ID)
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'CUSTOMER_CD already exists';
  END IF;

  IF p_CUSTOMER_ID IS NULL OR p_CUSTOMER_ID = 0 THEN
    INSERT INTO customer_info
    (
      COMPANY_CD,
      CUSTOMER_CD,
      CATEGORY_CD,
      CUSTOMER_TYPE,
      CUSTOMER_NM_VIET,
      CUSTOMER_NM_ENG,
      CUSTOMER_NM_KOR,
      CUSTOMER_NM_CHINA,
      ADDRESS,
      TEL,
      ISDEL,
      CREATE_AT,
      CREATE_BY,
      UPDATE_AT,
      UPDATE_BY
    )
    VALUES
    (
      p_COMPANY_CD,
      v_customer_cd,
      p_CATEGORY_CD,
      p_CUSTOMER_TYPE,
      p_CUSTOMER_NM_VIET,
      p_CUSTOMER_NM_ENG,
      p_CUSTOMER_NM_KOR,
      p_CUSTOMER_NM_CHINA,
      p_ADDRESS,
      p_TEL,
      COALESCE(p_ISDEL, '0'),
      NOW(),
      p_USERID,
      NOW(),
      p_USERID
    );

    SET v_customer_id = LAST_INSERT_ID();
  ELSE
    UPDATE customer_info
    SET
      CUSTOMER_CD = v_customer_cd,
      CATEGORY_CD = p_CATEGORY_CD,
      CUSTOMER_TYPE = p_CUSTOMER_TYPE,
      CUSTOMER_NM_VIET = p_CUSTOMER_NM_VIET,
      CUSTOMER_NM_ENG = p_CUSTOMER_NM_ENG,
      CUSTOMER_NM_KOR = p_CUSTOMER_NM_KOR,
      CUSTOMER_NM_CHINA = p_CUSTOMER_NM_CHINA,
      ADDRESS = p_ADDRESS,
      TEL = p_TEL,
      ISDEL = COALESCE(p_ISDEL, '0'),
      UPDATE_AT = NOW(),
      UPDATE_BY = p_USERID
    WHERE COMPANY_CD = p_COMPANY_CD COLLATE utf8_unicode_ci
      AND CUSTOMER_ID = p_CUSTOMER_ID;

    SET v_customer_id = p_CUSTOMER_ID;
  END IF;

  SET v_customer_key = v_customer_id;

  SET v_customer_ext_id = NULL;

  SELECT MAX(CUSTOMER_EXT_ID)
    INTO v_customer_ext_id
  FROM customer_ext
  WHERE COMPANY_CD = p_COMPANY_CD COLLATE utf8_unicode_ci
