      p_TAX_CD,
      v_bank_id,
      p_EMAIL,
      p_NOTE,
      p_IDNUMBER,
      p_BUYER_NM,
      COALESCE(p_ISDEL, '0'),
      NOW(),
      p_USERID,
      NOW(),
      p_USERID
    );
  ELSE
    UPDATE customer_ext
    SET
      FAX = p_FAX,
      TAX_CD = p_TAX_CD,
      BANK_ID = v_bank_id,
      EMAIL = p_EMAIL,
      NOTE = p_NOTE,
      IDNUMBER = p_IDNUMBER,
      BUYER_NM = p_BUYER_NM,
