  IF v_department_cd = '' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'DEPARTMENT_CD is required';
  END IF;

  IF v_parent_cd = v_department_cd THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'PARENT_CD cannot equal DEPARTMENT_CD';
  END IF;

  IF v_parent_cd <> '' AND NOT EXISTS (
    SELECT 1
    FROM department_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND DEPARTMENT_CD = v_parent_cd
      AND (ISDEL IS NULL OR ISDEL = '0')
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'PARENT_CD does not exist';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM department_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND DEPARTMENT_CD = v_department_cd
      AND (ISDEL IS NULL OR ISDEL = '0')
      AND ((p_DEPARTMENT_ID IS NULL OR p_DEPARTMENT_ID = 0) OR DEPARTMENT_ID <> p_DEPARTMENT_ID)
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'DEPARTMENT_CD already exists';
  END IF;

  IF p_DEPARTMENT_ID IS NULL OR p_DEPARTMENT_ID = 0 THEN
    INSERT INTO department_info(
      COMPANY_CD,
      DEPARTMENT_CD,
      PARENT_CD,
      DEP_NAME_KOR,
      DEP_NAME_ENG,
      DEP_NAME_VIET,
      DEP_NAME_CHINA,
      UPDATE_AT,
      UPDATE_BY,
      CREATE_AT,
      CREATE_BY,
      ISDEL
    ) VALUES (
      p_COMPANY_CD,
      v_department_cd,
      v_parent_cd,
      p_DEP_NAME_KOR,
      p_DEP_NAME_ENG,
      p_DEP_NAME_VIET,
      p_DEP_NAME_CHINA,
      DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s'),
      p_USERID,
      DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s'),
      p_USERID,
      COALESCE(p_ISDEL, '0')
    );
  ELSE
    SELECT DEPARTMENT_CD
      INTO v_old_department_cd
    FROM department_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND DEPARTMENT_ID = p_DEPARTMENT_ID
    LIMIT 1;

    UPDATE department_info
    SET
      DEPARTMENT_CD = v_department_cd,
      PARENT_CD = v_parent_cd,
      DEP_NAME_KOR = p_DEP_NAME_KOR,
      DEP_NAME_ENG = p_DEP_NAME_ENG,
      DEP_NAME_VIET = p_DEP_NAME_VIET,
      DEP_NAME_CHINA = p_DEP_NAME_CHINA,
      UPDATE_AT = DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s'),
      UPDATE_BY = p_USERID,
      ISDEL = COALESCE(p_ISDEL, '0')
    WHERE COMPANY_CD = p_COMPANY_CD
      AND DEPARTMENT_ID = p_DEPARTMENT_ID;

    IF v_old_department_cd <> '' AND v_old_department_cd <> v_department_cd THEN
      UPDATE department_info
      SET
        PARENT_CD = v_department_cd,
        UPDATE_AT = DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s'),
        UPDATE_BY = p_USERID
      WHERE COMPANY_CD = p_COMPANY_CD
        AND PARENT_CD = v_old_department_cd
        AND (ISDEL IS NULL OR ISDEL = '0');
    END IF;
  END IF;
END//
DELIMITER ;


