  IN p_VALUE_TYPE VARCHAR(20),
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_SETTING_ID BIGINT UNSIGNED DEFAULT 0;
  DECLARE v_SETTING_TYPE VARCHAR(50) DEFAULT 'GENERAL';

  IF p_SETTING_KEY IS NULL OR TRIM(p_SETTING_KEY) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SETTING_KEY is required';
  END IF;

  SET p_COMPANY_CD = IFNULL(TRIM(p_COMPANY_CD), '');
  SET p_USER_ID = IFNULL(TRIM(p_USER_ID), '');
  SET v_SETTING_TYPE = IFNULL(NULLIF(UPPER(TRIM(p_SETTING_TYPE)), ''), 'GENERAL');

  IF IFNULL(p_SETTING_ID, 0) > 0 THEN
    SELECT SETTING_ID
      INTO v_SETTING_ID
      FROM einvoice_admin_setting
     WHERE SETTING_ID = p_SETTING_ID
       AND ISDEL = 0
     LIMIT 1;

    IF IFNULL(v_SETTING_ID, 0) = 0 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice admin setting not found';
    END IF;

    UPDATE einvoice_admin_setting
       SET COMPANY_CD = p_COMPANY_CD,
           USER_ID = p_USER_ID,
           SETTING_TYPE = v_SETTING_TYPE,
           SETTING_KEY = TRIM(p_SETTING_KEY),
           SETTING_VALUE = TRIM(p_SETTING_VALUE),
           VALUE_TYPE = UPPER(TRIM(IFNULL(p_VALUE_TYPE, 'STRING'))),
           ISDEL = 0,
           UPDATE_AT = NOW()
     WHERE SETTING_ID = v_SETTING_ID;
  ELSE
    INSERT INTO einvoice_admin_setting (
      COMPANY_CD,
      USER_ID,
      SETTING_TYPE,
      SETTING_KEY,
      SETTING_VALUE,
      VALUE_TYPE,
      ISDEL,
      CREATE_AT,
      UPDATE_AT
    ) VALUES (
      p_COMPANY_CD,
      p_USER_ID,
      v_SETTING_TYPE,
      TRIM(p_SETTING_KEY),
      TRIM(p_SETTING_VALUE),
      UPPER(TRIM(IFNULL(p_VALUE_TYPE, 'STRING'))),
      0,
      NOW(),
      NOW()
    )
    ON DUPLICATE KEY UPDATE
      SETTING_VALUE = TRIM(p_SETTING_VALUE),
      VALUE_TYPE = UPPER(TRIM(IFNULL(p_VALUE_TYPE, 'STRING'))),
      ISDEL = 0,
      UPDATE_AT = NOW();

    SELECT SETTING_ID
      INTO v_SETTING_ID
      FROM einvoice_admin_setting
     WHERE COMPANY_CD = p_COMPANY_CD
       AND USER_ID = p_USER_ID
       AND SETTING_TYPE = v_SETTING_TYPE
