CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceBbanBuyerSignature`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_BBAN_ID BIGINT,
  IN p_SIGNED_XML LONGTEXT,
  IN p_CHECKSUM VARCHAR(64),
  IN p_USERID VARCHAR(50)
)
BEGIN
  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF p_BBAN_ID IS NULL OR p_BBAN_ID <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BBAN_ID is required';
  END IF;

  IF p_SIGNED_XML IS NULL OR TRIM(p_SIGNED_XML) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SIGNED_XML is required';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM einvoice_bban_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND BBAN_ID = p_BBAN_ID
      AND ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice minute not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM einvoice_bban_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND BBAN_ID = p_BBAN_ID
      AND ISDEL = 0
      AND IFNULL(IS_SIGNED, 0) = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice minute is not signed by seller';
  END IF;

  IF EXISTS (
    SELECT 1 FROM einvoice_bban_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND BBAN_ID = p_BBAN_ID
      AND ISDEL = 0
      AND IFNULL(NMUA_IS_SIGNED, 0) = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice minute is already signed by buyer';
  END IF;

  UPDATE einvoice_bban_info
  SET SIGNED_XML = p_SIGNED_XML,
      NMUA_IS_SIGNED = 1,
      NMUA_SIGN_DT = NOW(),
      CHECKSUM = NULLIF(TRIM(p_CHECKSUM), ''),
      UPDATE_BY = p_USERID,
      UPDATE_AT = NOW()
  WHERE COMPANY_CD = p_COMPANY_CD
    AND BBAN_ID = p_BBAN_ID
    AND ISDEL = 0;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.setEInvoiceBbanInfo
DROP PROCEDURE IF EXISTS `setEInvoiceBbanInfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceBbanInfo`(
  IN p_BBAN_ID BIGINT,
  IN p_COMPANY_CD VARCHAR(20),
  IN p_SELLER_ID BIGINT,
  IN p_INVOICE_ID BIGINT,
  IN p_REF_INVOICE_ID BIGINT,
  IN p_PBAN VARCHAR(6),
  IN p_TBBAN VARCHAR(100),
  IN p_SBBAN VARCHAR(50),
  IN p_NBBAN DATE,
  IN p_TCHDON TINYINT,
  IN p_NBAN VARCHAR(400),
  IN p_MSTNBAN VARCHAR(14),
  IN p_DCNBAN VARCHAR(400),
  IN p_NMUA VARCHAR(400),
  IN p_MSTNMUA VARCHAR(14),
  IN p_DCNMUA VARCHAR(400),
  IN p_KHMSHDON VARCHAR(1),
  IN p_KHHDON VARCHAR(6),
  IN p_SHDON VARCHAR(8),
  IN p_NLAP DATE,
  IN p_MTRACUU VARCHAR(100),
  IN p_TTKHAC_XML LONGTEXT,
  IN p_NDBBAN_XML LONGTEXT,
  IN p_IS_MAIL TINYINT,
  IN p_CHECKSUM VARCHAR(64),
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_BBAN_ID BIGINT DEFAULT 0;
  DECLARE v_TCHDON TINYINT DEFAULT 2;
  DECLARE v_MTRACUU VARCHAR(100);
  DECLARE v_GENERATED_MTRACUU TINYINT DEFAULT 0;

  SET v_BBAN_ID = IFNULL(p_BBAN_ID, 0);
  SET v_TCHDON = CASE WHEN IFNULL(p_TCHDON, 2) = 1 THEN 1 ELSE 2 END;
  SET v_MTRACUU = UPPER(NULLIF(TRIM(IFNULL(p_MTRACUU, '')), ''));

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF p_SBBAN IS NULL OR TRIM(p_SBBAN) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SBBAN is required';
  END IF;

  IF p_NBBAN IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NBBAN is required';
  END IF;

  IF p_NBAN IS NULL OR TRIM(p_NBAN) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NBAN is required';
  END IF;

  IF p_MSTNBAN IS NULL OR TRIM(p_MSTNBAN) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MSTNBAN is required';
  END IF;

  IF p_NMUA IS NULL OR TRIM(p_NMUA) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NMUA is required';
  END IF;

  IF p_KHMSHDON IS NULL OR TRIM(p_KHMSHDON) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'KHMSHDON is required';
  END IF;

  IF v_BBAN_ID > 0 AND NOT EXISTS (
    SELECT 1 FROM einvoice_bban_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND BBAN_ID = v_BBAN_ID
      AND ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice minute not found';
  END IF;

  IF v_BBAN_ID > 0 AND EXISTS (
    SELECT 1 FROM einvoice_bban_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND BBAN_ID = v_BBAN_ID
      AND ISDEL = 0
      AND IFNULL(IS_SIGNED, 0) = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice minute is already signed';
  END IF;

  IF v_BBAN_ID > 0 AND v_MTRACUU IS NULL THEN
    SELECT UPPER(NULLIF(TRIM(IFNULL(MTRACUU, '')), ''))
      INTO v_MTRACUU
      FROM einvoice_bban_info
     WHERE COMPANY_CD = p_COMPANY_CD
       AND BBAN_ID = v_BBAN_ID
       AND ISDEL = 0
     LIMIT 1;
  END IF;

  IF v_MTRACUU IS NULL THEN
    SET v_GENERATED_MTRACUU = 1;
    SET v_MTRACUU = CONCAT('BB', UPPER(HEX(RANDOM_BYTES(9))));
  END IF;

  WHILE v_GENERATED_MTRACUU = 1 AND EXISTS (
    SELECT 1 FROM einvoice_bban_info
     WHERE COMPANY_CD = p_COMPANY_CD
       AND MTRACUU = v_MTRACUU
       AND ISDEL = 0
       AND BBAN_ID <> v_BBAN_ID
  ) DO
    SET v_MTRACUU = CONCAT('BB', UPPER(HEX(RANDOM_BYTES(9))));
  END WHILE;

  IF v_GENERATED_MTRACUU = 0 AND EXISTS (
    SELECT 1 FROM einvoice_bban_info
     WHERE COMPANY_CD = p_COMPANY_CD
       AND MTRACUU = v_MTRACUU
       AND ISDEL = 0
       AND BBAN_ID <> v_BBAN_ID
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MTRACUU already exists';
  END IF;

  IF v_BBAN_ID = 0 THEN
    INSERT INTO einvoice_bban_info (
      COMPANY_CD,
      SELLER_ID,
      INVOICE_ID,
      REF_INVOICE_ID,
      PBAN,
      TBBAN,
      SBBAN,
      NBBAN,
      TCHDON,
      NBAN,
      MSTNBAN,
      DCNBAN,
      NMUA,
      MSTNMUA,
      DCNMUA,
      KHMSHDON,
      KHHDON,
      SHDON,
      NLAP,
      MTRACUU,
      TTKHAC_XML,
      NDBBAN_XML,
      SIGNED_XML,
      IS_SIGNED,
      NMUA_IS_SIGNED,
      NMUA_SIGN_DT,
      IS_MAIL,
      CHECKSUM,
      CREATE_BY,
      CREATE_AT,
      UPDATE_BY,
      UPDATE_AT,
      ISDEL
    ) VALUES (
      p_COMPANY_CD,
      NULLIF(p_SELLER_ID, 0),
      NULLIF(p_INVOICE_ID, 0),
      NULLIF(p_REF_INVOICE_ID, 0),
      IFNULL(NULLIF(TRIM(p_PBAN), ''), '2.1.0'),
      IFNULL(NULLIF(TRIM(p_TBBAN), ''), ''),
      IFNULL(NULLIF(TRIM(p_SBBAN), ''), ''),
      p_NBBAN,
      v_TCHDON,
      IFNULL(NULLIF(TRIM(p_NBAN), ''), ''),
      IFNULL(NULLIF(TRIM(p_MSTNBAN), ''), ''),
      NULLIF(TRIM(p_DCNBAN), ''),
      IFNULL(NULLIF(TRIM(p_NMUA), ''), ''),
      NULLIF(TRIM(p_MSTNMUA), ''),
      NULLIF(TRIM(p_DCNMUA), ''),
      IFNULL(NULLIF(TRIM(p_KHMSHDON), ''), ''),
      NULLIF(TRIM(p_KHHDON), ''),
      NULLIF(TRIM(p_SHDON), ''),
      p_NLAP,
      v_MTRACUU,
      p_TTKHAC_XML,
      p_NDBBAN_XML,
      NULL,
      0,
      0,
      NULL,
      IFNULL(p_IS_MAIL, 0),
      NULLIF(TRIM(p_CHECKSUM), ''),
      IFNULL(p_USERID, ''),
      NOW(),
      p_USERID,
      NOW(),
      0
    );
    SET v_BBAN_ID = LAST_INSERT_ID();
  ELSE
    UPDATE einvoice_bban_info
    SET SELLER_ID = NULLIF(p_SELLER_ID, 0),
        INVOICE_ID = NULLIF(p_INVOICE_ID, 0),
        REF_INVOICE_ID = NULLIF(p_REF_INVOICE_ID, 0),
        PBAN = IFNULL(NULLIF(TRIM(p_PBAN), ''), '2.1.0'),
        TBBAN = IFNULL(NULLIF(TRIM(p_TBBAN), ''), ''),
        SBBAN = IFNULL(NULLIF(TRIM(p_SBBAN), ''), ''),
        NBBAN = p_NBBAN,
        TCHDON = v_TCHDON,
        NBAN = IFNULL(NULLIF(TRIM(p_NBAN), ''), ''),
        MSTNBAN = IFNULL(NULLIF(TRIM(p_MSTNBAN), ''), ''),
        DCNBAN = NULLIF(TRIM(p_DCNBAN), ''),
        NMUA = IFNULL(NULLIF(TRIM(p_NMUA), ''), ''),
        MSTNMUA = NULLIF(TRIM(p_MSTNMUA), ''),
        DCNMUA = NULLIF(TRIM(p_DCNMUA), ''),
        KHMSHDON = IFNULL(NULLIF(TRIM(p_KHMSHDON), ''), ''),
        KHHDON = NULLIF(TRIM(p_KHHDON), ''),
        SHDON = NULLIF(TRIM(p_SHDON), ''),
        NLAP = p_NLAP,
        MTRACUU = v_MTRACUU,
        TTKHAC_XML = p_TTKHAC_XML,
        NDBBAN_XML = p_NDBBAN_XML,
        IS_MAIL = IFNULL(p_IS_MAIL, IS_MAIL),
        CHECKSUM = NULLIF(TRIM(p_CHECKSUM), ''),
        UPDATE_BY = p_USERID,
        UPDATE_AT = NOW()
    WHERE COMPANY_CD = p_COMPANY_CD
      AND BBAN_ID = v_BBAN_ID
      AND ISDEL = 0;
  END IF;

  SELECT v_BBAN_ID AS BBAN_ID;
END//
DELIMITER ;


