    SELECT 1 FROM einvoice_bban_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND BBAN_ID = p_BBAN_ID
      AND ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice minute not found';
  END IF;

  IF EXISTS (
    SELECT 1 FROM einvoice_bban_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND BBAN_ID = p_BBAN_ID
      AND ISDEL = 0
      AND IFNULL(IS_SIGNED, 0) = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice minute is already signed';
  END IF;

  UPDATE einvoice_bban_info
  SET SIGNED_XML = p_SIGNED_XML,
      IS_SIGNED = 1,
      CHECKSUM = NULLIF(TRIM(p_CHECKSUM), ''),
      UPDATE_BY = p_USERID,
      UPDATE_AT = NOW()
  WHERE COMPANY_CD = p_COMPANY_CD
    AND BBAN_ID = p_BBAN_ID
    AND ISDEL = 0;
END//
DELIMITER ;


