CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceBkeDetail`(
  IN p_DETAIL_ID BIGINT,
  IN p_BKE_ID BIGINT,
  IN p_STT INT,
  IN p_REF_INVOICE_ID BIGINT,
  IN p_KHMSHDON VARCHAR(1),
  IN p_KHHDON VARCHAR(6),
  IN p_SHDON VARCHAR(8),
  IN p_THHDVGOC VARCHAR(500),
  IN p_SLGOC DECIMAL(21,6),
  IN p_DGGOC DECIMAL(21,6),
  IN p_THTGOC DECIMAL(21,6),
  IN p_TSGOC VARCHAR(11),
  IN p_TTGOC DECIMAL(21,6),
  IN p_TGTKGOC DECIMAL(21,6),
  IN p_TGTSTGOC DECIMAL(21,6),
  IN p_THHDVTDOI VARCHAR(500),
  IN p_SLTDOI DECIMAL(21,6),
  IN p_DGTDOI DECIMAL(21,6),
  IN p_THTTDOI DECIMAL(21,6),
  IN p_TSTDOI VARCHAR(11),
  IN p_TTTDOI DECIMAL(21,6),
  IN p_TGTTDOI DECIMAL(21,6),
  IN p_TGTSTTDOI DECIMAL(21,6),
  IN p_TGTCTCLECH DECIMAL(21,6),
  IN p_TGTTCLECH DECIMAL(21,6),
  IN p_TGTKCLECH DECIMAL(21,6),
  IN p_TGTTTCLECH DECIMAL(21,6),
  IN p_EXTRA_JSON LONGTEXT
)
BEGIN
  DECLARE v_DETAIL_ID BIGINT DEFAULT 0;

  IF p_BKE_ID IS NULL OR p_BKE_ID <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BKE_ID is required';
  END IF;

  IF p_DETAIL_ID IS NOT NULL AND p_DETAIL_ID > 0 THEN
    UPDATE einvoice_bke_detail
    SET STT = p_STT,
        REF_INVOICE_ID = NULLIF(p_REF_INVOICE_ID, 0),
        KHMSHDON = IFNULL(TRIM(p_KHMSHDON), ''),
        KHHDON = NULLIF(TRIM(p_KHHDON), ''),
        SHDON = NULLIF(TRIM(p_SHDON), ''),
        THHDVGOC = NULLIF(TRIM(p_THHDVGOC), ''),
        SLGOC = p_SLGOC,
        DGGOC = p_DGGOC,
        THTGOC = p_THTGOC,
        TSGOC = NULLIF(TRIM(p_TSGOC), ''),
        TTGOC = p_TTGOC,
        TGTKGOC = p_TGTKGOC,
        TGTSTGOC = p_TGTSTGOC,
        THHDVTDOI = NULLIF(TRIM(p_THHDVTDOI), ''),
        SLTDOI = p_SLTDOI,
        DGTDOI = p_DGTDOI,
        THTTDOI = p_THTTDOI,
        TSTDOI = NULLIF(TRIM(p_TSTDOI), ''),
        TTTDOI = p_TTTDOI,
        TGTTDOI = p_TGTTDOI,
        TGTSTTDOI = p_TGTSTTDOI,
        TGTCTCLECH = p_TGTCTCLECH,
        TGTTCLECH = p_TGTTCLECH,
        TGTKCLECH = p_TGTKCLECH,
        TGTTTCLECH = p_TGTTTCLECH,
        EXTRA_JSON = NULLIF(TRIM(p_EXTRA_JSON), ''),
        ISDEL = 0
    WHERE DETAIL_ID = p_DETAIL_ID
      AND BKE_ID = p_BKE_ID;
    SET v_DETAIL_ID = p_DETAIL_ID;
  ELSE
    INSERT INTO einvoice_bke_detail (
      BKE_ID, STT, REF_INVOICE_ID,
      KHMSHDON, KHHDON, SHDON,
      THHDVGOC, SLGOC, DGGOC, THTGOC, TSGOC, TTGOC, TGTKGOC, TGTSTGOC,
      THHDVTDOI, SLTDOI, DGTDOI, THTTDOI, TSTDOI, TTTDOI, TGTTDOI, TGTSTTDOI,
      TGTCTCLECH, TGTTCLECH, TGTKCLECH, TGTTTCLECH,
      EXTRA_JSON, CREATE_AT, ISDEL
    ) VALUES (
      p_BKE_ID, p_STT, NULLIF(p_REF_INVOICE_ID, 0),
      IFNULL(TRIM(p_KHMSHDON), ''), NULLIF(TRIM(p_KHHDON), ''), NULLIF(TRIM(p_SHDON), ''),
      NULLIF(TRIM(p_THHDVGOC), ''), p_SLGOC, p_DGGOC, p_THTGOC, NULLIF(TRIM(p_TSGOC), ''), p_TTGOC, p_TGTKGOC, p_TGTSTGOC,
      NULLIF(TRIM(p_THHDVTDOI), ''), p_SLTDOI, p_DGTDOI, p_THTTDOI, NULLIF(TRIM(p_TSTDOI), ''), p_TTTDOI, p_TGTTDOI, p_TGTSTTDOI,
      p_TGTCTCLECH, p_TGTTCLECH, p_TGTKCLECH, p_TGTTTCLECH,
      NULLIF(TRIM(p_EXTRA_JSON), ''), NOW(), 0
    );
    SET v_DETAIL_ID = LAST_INSERT_ID();
  END IF;

  SELECT v_DETAIL_ID AS DETAIL_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.setEInvoiceBkeInfo
DROP PROCEDURE IF EXISTS `setEInvoiceBkeInfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceBkeInfo`(
  IN p_BKE_ID BIGINT,
  IN p_COMPANY_CD VARCHAR(20),
  IN p_INVOICE_ID BIGINT,
  IN p_SELLER_ID BIGINT,
  IN p_PBAN VARCHAR(6),
  IN p_TBKE VARCHAR(100),
  IN p_KHMBKE VARCHAR(10),
  IN p_SBKE VARCHAR(50),
  IN p_NBKE DATE,
  IN p_TCHDON TINYINT,
  IN p_NBAN VARCHAR(400),
  IN p_MSTNBAN VARCHAR(14),
  IN p_DCNBAN VARCHAR(400),
  IN p_TCTCNHANG TINYINT,
  IN p_NMUA VARCHAR(400),
  IN p_MSTNMUA VARCHAR(14),
  IN p_DCNMUA VARCHAR(400),
  IN p_TTKHAC_XML LONGTEXT,
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_BKE_ID BIGINT DEFAULT 0;

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF p_INVOICE_ID IS NULL OR p_INVOICE_ID <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVOICE_ID is required';
  END IF;

  IF p_NBKE IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NBKE is required';
  END IF;

  IF IFNULL(p_TCHDON, 0) NOT IN (1, 2) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BKe TCHDON must be 1 or 2';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM einvoice_info
    WHERE COMPANY_CD = p_COMPANY_CD AND INVOICE_ID = p_INVOICE_ID AND ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice not found';
  END IF;

  -- Đã ký gửi CQT thì không được sửa cấu trúc bảng kê.
  IF EXISTS (
    SELECT 1 FROM einvoice_info
    WHERE COMPANY_CD = p_COMPANY_CD AND INVOICE_ID = p_INVOICE_ID AND ISDEL = 0 AND IS_SIGNED = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Signed e-invoice bảng kê cannot be modified';
  END IF;

  IF EXISTS (
    SELECT 1 FROM einvoice_bke_info
    WHERE COMPANY_CD = p_COMPANY_CD AND INVOICE_ID = p_INVOICE_ID AND ISDEL = 0 AND IS_SIGNED = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Signed bảng kê cannot be modified';
  END IF;

  INSERT INTO einvoice_bke_info (
    COMPANY_CD, INVOICE_ID, SELLER_ID,
    PBAN, TBKE, KHMBKE, SBKE, NBKE, TCHDON,
    NBAN, MSTNBAN, DCNBAN, TCTCNHANG,
    NMUA, MSTNMUA, DCNMUA,
    TTKHAC_XML,
    CREATE_BY, CREATE_AT, UPDATE_BY, UPDATE_AT, ISDEL
  ) VALUES (
    p_COMPANY_CD,
    p_INVOICE_ID,
    NULLIF(p_SELLER_ID, 0),
    IFNULL(NULLIF(TRIM(p_PBAN), ''), '2.1.1'),
    IFNULL(TRIM(p_TBKE), ''),
    IFNULL(NULLIF(TRIM(p_KHMBKE), ''), '01/BK-ĐCTT'),
    IFNULL(TRIM(p_SBKE), ''),
    p_NBKE,
    IFNULL(p_TCHDON, 1),
    IFNULL(TRIM(p_NBAN), ''),
    IFNULL(TRIM(p_MSTNBAN), ''),
    NULLIF(TRIM(p_DCNBAN), ''),
    IFNULL(p_TCTCNHANG, 0),
    IFNULL(TRIM(p_NMUA), ''),
    NULLIF(TRIM(p_MSTNMUA), ''),
    NULLIF(TRIM(p_DCNMUA), ''),
    NULLIF(TRIM(p_TTKHAC_XML), ''),
    p_USERID, NOW(), p_USERID, NOW(), 0
  )
  ON DUPLICATE KEY UPDATE
    SELLER_ID = NULLIF(p_SELLER_ID, 0),
    PBAN = IFNULL(NULLIF(TRIM(p_PBAN), ''), '2.1.1'),
    TBKE = IFNULL(TRIM(p_TBKE), ''),
    KHMBKE = IFNULL(NULLIF(TRIM(p_KHMBKE), ''), '01/BK-ĐCTT'),
    SBKE = IFNULL(TRIM(p_SBKE), ''),
    NBKE = p_NBKE,
    TCHDON = IFNULL(p_TCHDON, 1),
    NBAN = IFNULL(TRIM(p_NBAN), ''),
    MSTNBAN = IFNULL(TRIM(p_MSTNBAN), ''),
    DCNBAN = NULLIF(TRIM(p_DCNBAN), ''),
    TCTCNHANG = IFNULL(p_TCTCNHANG, 0),
    NMUA = IFNULL(TRIM(p_NMUA), ''),
    MSTNMUA = NULLIF(TRIM(p_MSTNMUA), ''),
    DCNMUA = NULLIF(TRIM(p_DCNMUA), ''),
    TTKHAC_XML = NULLIF(TRIM(p_TTKHAC_XML), ''),
    UPDATE_BY = p_USERID,
    UPDATE_AT = NOW(),
    ISDEL = 0;

  SELECT BKE_ID INTO v_BKE_ID
  FROM einvoice_bke_info
  WHERE COMPANY_CD = p_COMPANY_CD AND INVOICE_ID = p_INVOICE_ID AND ISDEL = 0
  LIMIT 1;

  SELECT v_BKE_ID AS BKE_ID;
END//
DELIMITER ;


