    VALUES (p_BKE_ID, IFNULL(p_SORT_ORDER, 1), IFNULL(TRIM(p_LDO), ''), NOW(), 0);
    SET v_REASON_ID = LAST_INSERT_ID();
  END IF;

  SELECT v_REASON_ID AS REASON_ID;
END//
