-- Dumping structure for procedure am_web_001.setEInvoiceBkeSignature
DROP PROCEDURE IF EXISTS `setEInvoiceBkeSignature`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceBkeSignature`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_INVOICE_ID BIGINT,
  IN p_SIGNED_XML LONGTEXT,
  IN p_IS_SIGNED TINYINT,
  IN p_USERID VARCHAR(50)
)
BEGIN
  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF p_INVOICE_ID IS NULL OR p_INVOICE_ID <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVOICE_ID is required';
  END IF;

  IF IFNULL(p_IS_SIGNED, 0) = 1 AND (p_SIGNED_XML IS NULL OR TRIM(p_SIGNED_XML) = '') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SIGNED_XML is required when IS_SIGNED = 1';
  END IF;

  UPDATE einvoice_bke_info
  SET
    SIGNED_XML = CASE WHEN IFNULL(p_IS_SIGNED, 0) = 1 THEN p_SIGNED_XML ELSE NULL END,
    IS_SIGNED = IFNULL(p_IS_SIGNED, 0),
    UPDATE_BY = p_USERID,
    UPDATE_AT = NOW()
  WHERE COMPANY_CD = p_COMPANY_CD
    AND INVOICE_ID = p_INVOICE_ID
    AND ISDEL = 0;

  IF ROW_COUNT() = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice bảng kê not found';
  END IF;
END//
DELIMITER ;


