-- Dumping structure for procedure am_web_001.setEInvoiceDecimalSetting
DROP PROCEDURE IF EXISTS `setEInvoiceDecimalSetting`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceDecimalSetting`(
  IN p_SETTING_ID BIGINT UNSIGNED,
  IN p_COMPANY_CD VARCHAR(20),
  IN p_XSL_ID BIGINT UNSIGNED,
  IN p_APPLY_TARGET VARCHAR(30),
  IN p_FIELD_SCOPE VARCHAR(20),
  IN p_FIELD_NAME VARCHAR(50),
  IN p_LABEL_TEXT VARCHAR(100),
  IN p_CAPTION VARCHAR(255),
  IN p_CURRENCY_SCOPE VARCHAR(20),
  IN p_DECIMAL_SCALE TINYINT,
  IN p_ROUND_MODE VARCHAR(20),
  IN p_IS_ACTIVE TINYINT,
  IN p_SORT_ORDER INT,
  IN p_NOTE VARCHAR(500),
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_SETTING_ID BIGINT UNSIGNED DEFAULT 0;
  DECLARE v_XSL_ID BIGINT UNSIGNED DEFAULT 0;

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  SET v_XSL_ID = IFNULL(p_XSL_ID, 0);

  IF v_XSL_ID > 0 AND NOT EXISTS (
    SELECT 1
      FROM einvoice_seller_xsl_template xsl
     WHERE xsl.COMPANY_CD = p_COMPANY_CD
       AND xsl.XSL_ID = v_XSL_ID
       AND xsl.ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'XSL_ID is invalid';
  END IF;

  IF p_APPLY_TARGET IS NULL OR TRIM(p_APPLY_TARGET) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'APPLY_TARGET is required';
  END IF;

  IF p_FIELD_SCOPE IS NULL OR TRIM(p_FIELD_SCOPE) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'FIELD_SCOPE is required';
  END IF;

  IF p_FIELD_NAME IS NULL OR TRIM(p_FIELD_NAME) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'FIELD_NAME is required';
  END IF;

  IF IFNULL(p_SETTING_ID, 0) > 0 THEN
    SELECT SETTING_ID
      INTO v_SETTING_ID
      FROM einvoice_decimal_setting
     WHERE COMPANY_CD = p_COMPANY_CD
       AND SETTING_ID = p_SETTING_ID
     LIMIT 1;

    IF IFNULL(v_SETTING_ID, 0) = 0 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice decimal setting not found';
    END IF;

    UPDATE einvoice_decimal_setting
       SET XSL_ID = v_XSL_ID,
           APPLY_TARGET = UPPER(TRIM(p_APPLY_TARGET)),
           FIELD_SCOPE = UPPER(TRIM(p_FIELD_SCOPE)),
           FIELD_NAME = UPPER(TRIM(p_FIELD_NAME)),
           LABEL_TEXT = NULLIF(TRIM(IFNULL(p_LABEL_TEXT, '')), ''),
           CAPTION = NULLIF(TRIM(IFNULL(p_CAPTION, '')), ''),
           CURRENCY_SCOPE = UPPER(TRIM(IFNULL(p_CURRENCY_SCOPE, 'ANY'))),
           DECIMAL_SCALE = IFNULL(p_DECIMAL_SCALE, 2),
           ROUND_MODE = UPPER(TRIM(IFNULL(p_ROUND_MODE, 'ROUND'))),
           IS_ACTIVE = IFNULL(p_IS_ACTIVE, 1),
           SORT_ORDER = IFNULL(p_SORT_ORDER, 0),
           NOTE = TRIM(IFNULL(p_NOTE, '')),
           UPDATE_BY = p_USERID,
           UPDATE_AT = NOW()
     WHERE SETTING_ID = v_SETTING_ID
       AND COMPANY_CD = p_COMPANY_CD;
  ELSE
    INSERT INTO einvoice_decimal_setting (
      COMPANY_CD,
      XSL_ID,
      APPLY_TARGET,
      FIELD_SCOPE,
      FIELD_NAME,
      LABEL_TEXT,
      CAPTION,
      CURRENCY_SCOPE,
      DECIMAL_SCALE,
      ROUND_MODE,
      IS_ACTIVE,
      SORT_ORDER,
      NOTE,
      CREATE_BY,
      CREATE_AT
    ) VALUES (
      p_COMPANY_CD,
      v_XSL_ID,
      UPPER(TRIM(p_APPLY_TARGET)),
      UPPER(TRIM(p_FIELD_SCOPE)),
      UPPER(TRIM(p_FIELD_NAME)),
      NULLIF(TRIM(IFNULL(p_LABEL_TEXT, '')), ''),
      NULLIF(TRIM(IFNULL(p_CAPTION, '')), ''),
      UPPER(TRIM(IFNULL(p_CURRENCY_SCOPE, 'ANY'))),
      IFNULL(p_DECIMAL_SCALE, 2),
      UPPER(TRIM(IFNULL(p_ROUND_MODE, 'ROUND'))),
      IFNULL(p_IS_ACTIVE, 1),
      IFNULL(p_SORT_ORDER, 0),
      TRIM(IFNULL(p_NOTE, '')),
      p_USERID,
      NOW()
    );

    SET v_SETTING_ID = LAST_INSERT_ID();
  END IF;

  SELECT v_SETTING_ID AS SETTING_ID;
END//
DELIMITER ;


