    WHERE COMPANY_CD = p_COMPANY_CD
      AND INVOICE_ID = p_INVOICE_ID
      AND DETAIL_ID = v_DETAIL_ID;
  ELSEIF v_DETAIL_ID = 0 THEN
    INSERT INTO einvoice_detail (
