      p_SLTHUCNHAP,
      p_DGIA,
      p_TLCKHAU,
      IFNULL(p_STCKHAU, 0),
      IFNULL(p_THTIEN, 0),
      NULLIF(TRIM(p_TSUAT), ''),
      IFNULL(p_TTHUE, 0),
      IFNULL(p_TSAUTHUE, 0),
      p_DGIA_VND,
      IFNULL(p_STCKHAU_VND, 0),
      IFNULL(p_THTIEN_VND, 0),
      IFNULL(p_TTHUE_VND, 0),
      IFNULL(p_TSAUTHUE_VND, 0),
      p_EXTRA_JSON,
      NOW(),
      p_USERID,
      NOW(),
      p_USERID,
      0
    );
    SET v_DETAIL_ID = LAST_INSERT_ID();
  ELSE
    IF NOT EXISTS (
      SELECT 1
      FROM einvoice_detail
      WHERE COMPANY_CD = p_COMPANY_CD
        AND INVOICE_ID = p_INVOICE_ID
        AND DETAIL_ID = v_DETAIL_ID
    ) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice detail not found';
    END IF;

    UPDATE einvoice_detail
    SET TCHAT = p_TCHAT,
        STT = p_STT,
        MHHDVU = NULLIF(TRIM(p_MHHDVU), ''),
        THHDVU = NULLIF(TRIM(p_THHDVU), ''),
        DVTINH = NULLIF(TRIM(p_DVTINH), ''),
        SLUONG = p_SLUONG,
        SLTHUCNHAP = p_SLTHUCNHAP,
        DGIA = p_DGIA,
        TLCKHAU = p_TLCKHAU,
        STCKHAU = IFNULL(p_STCKHAU, 0),
        THTIEN = IFNULL(p_THTIEN, 0),
        TSUAT = NULLIF(TRIM(p_TSUAT), ''),
        TTHUE = IFNULL(p_TTHUE, 0),
        TSAUTHUE = IFNULL(p_TSAUTHUE, 0),
        DGIA_VND = p_DGIA_VND,
        STCKHAU_VND = IFNULL(p_STCKHAU_VND, 0),
        THTIEN_VND = IFNULL(p_THTIEN_VND, 0),
        TTHUE_VND = IFNULL(p_TTHUE_VND, 0),
        TSAUTHUE_VND = IFNULL(p_TSAUTHUE_VND, 0),
        EXTRA_JSON = p_EXTRA_JSON,
        UPDATE_AT = NOW(),
        UPDATE_BY = p_USERID,
        ISDEL = 0
    WHERE COMPANY_CD = p_COMPANY_CD
      AND INVOICE_ID = p_INVOICE_ID
      AND DETAIL_ID = v_DETAIL_ID;
  END IF;

  SELECT v_DETAIL_ID AS DETAIL_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.setEInvoiceDetailSpecialInfo
DROP PROCEDURE IF EXISTS `setEInvoiceDetailSpecialInfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceDetailSpecialInfo`(
  IN p_SPECIAL_ID BIGINT,
  IN p_COMPANY_CD VARCHAR(20),
  IN p_INVOICE_ID BIGINT,
  IN p_DETAIL_ID BIGINT,
  IN p_LHHDTRUNG TINYINT,
  IN p_SKHUNG VARCHAR(50),
  IN p_SMAY VARCHAR(50),
  IN p_BKSPT_VCHUYEN VARCHAR(50),
  IN p_TNG_HANG VARCHAR(255),
  IN p_DCNG_HANG VARCHAR(500),
  IN p_MSTNG_HANG VARCHAR(50),
  IN p_MDDNG_HANG VARCHAR(50),
  IN p_EXTRA_JSON LONGTEXT,
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_SPECIAL_ID BIGINT DEFAULT 0;

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF p_INVOICE_ID IS NULL OR p_INVOICE_ID <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVOICE_ID is required';
  END IF;

  IF p_DETAIL_ID IS NULL OR p_DETAIL_ID <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DETAIL_ID is required';
  END IF;

  IF IFNULL(p_LHHDTRUNG, 0) NOT IN (1, 2, 3, 4) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'LHHDTRUNG must be 1, 2, 3 or 4';
  END IF;

  INSERT INTO einvoice_detail_special_info (
    COMPANY_CD,
    INVOICE_ID,
    DETAIL_ID,
    LHHDTRUNG,
    SKHUNG,
    SMAY,
    BKSPT_VCHUYEN,
    TNG_HANG,
    DCNG_HANG,
    MSTNG_HANG,
    MDDNG_HANG,
    EXTRA_JSON,
    CREATE_BY,
    CREATE_AT,
    UPDATE_BY,
    UPDATE_AT
  ) VALUES (
    p_COMPANY_CD,
    p_INVOICE_ID,
    p_DETAIL_ID,
    p_LHHDTRUNG,
    NULLIF(TRIM(p_SKHUNG), ''),
    NULLIF(TRIM(p_SMAY), ''),
    NULLIF(TRIM(p_BKSPT_VCHUYEN), ''),
    NULLIF(TRIM(p_TNG_HANG), ''),
    NULLIF(TRIM(p_DCNG_HANG), ''),
    NULLIF(TRIM(p_MSTNG_HANG), ''),
    NULLIF(TRIM(p_MDDNG_HANG), ''),
    NULLIF(TRIM(p_EXTRA_JSON), ''),
    p_USERID,
    NOW(),
    p_USERID,
    NOW()
  )
  ON DUPLICATE KEY UPDATE
    INVOICE_ID = p_INVOICE_ID,
    LHHDTRUNG = p_LHHDTRUNG,
    SKHUNG = NULLIF(TRIM(p_SKHUNG), ''),
    SMAY = NULLIF(TRIM(p_SMAY), ''),
    BKSPT_VCHUYEN = NULLIF(TRIM(p_BKSPT_VCHUYEN), ''),
    TNG_HANG = NULLIF(TRIM(p_TNG_HANG), ''),
    DCNG_HANG = NULLIF(TRIM(p_DCNG_HANG), ''),
    MSTNG_HANG = NULLIF(TRIM(p_MSTNG_HANG), ''),
    MDDNG_HANG = NULLIF(TRIM(p_MDDNG_HANG), ''),
    EXTRA_JSON = NULLIF(TRIM(p_EXTRA_JSON), ''),
    UPDATE_BY = p_USERID,
    UPDATE_AT = NOW();

  SELECT SPECIAL_ID
    INTO v_SPECIAL_ID
    FROM einvoice_detail_special_info
   WHERE COMPANY_CD = p_COMPANY_CD
     AND DETAIL_ID = p_DETAIL_ID
   LIMIT 1;

  SELECT v_SPECIAL_ID AS SPECIAL_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.setEInvoiceInfo
DROP PROCEDURE IF EXISTS `setEInvoiceInfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceInfo`(
  IN p_INVOICE_ID BIGINT,
  IN p_COMPANY_CD VARCHAR(20),
  IN p_SELLER_ID BIGINT,
  IN p_XSL_ID BIGINT,
  IN p_PBAN VARCHAR(6),
  IN p_THDON VARCHAR(100),
  IN p_KHMSHDON VARCHAR(11),
  IN p_KHHDON VARCHAR(8),
  IN p_SHDON VARCHAR(8),
  IN p_MHSO VARCHAR(20),
  IN p_NLAP DATE,
  IN p_HDCTTCHINH TINYINT,
  IN p_SBKE VARCHAR(50),
  IN p_NBKE DATE,
  IN p_DVTTE CHAR(3),
  IN p_TGIA DECIMAL(21,2),
  IN p_HTTTOAN VARCHAR(50),
  IN p_MSTTCGP VARCHAR(14),
  IN p_TCHDON TINYINT,
  IN p_SOURCE_INVOICE_ID BIGINT,
  IN p_NMUA_TEN VARCHAR(400),
  IN p_NMUA_MST VARCHAR(14),
  IN p_NMUA_MDVQHNSACH VARCHAR(7),
  IN p_NMUA_DCHI VARCHAR(400),
  IN p_NMUA_MTINH VARCHAR(2),
  IN p_NMUA_TTINH VARCHAR(50),
  IN p_NMUA_MXA VARCHAR(5),
  IN p_NMUA_TXA VARCHAR(50),
  IN p_NMUA_MKHANG VARCHAR(50),
  IN p_NMUA_SDTHOAI VARCHAR(20),
  IN p_NMUA_CCCDAN VARCHAR(12),
  IN p_NMUA_SHCHIEU VARCHAR(20),
  IN p_NMUA_DCTDTU VARCHAR(500),
  IN p_NMUA_HVTNMHANG VARCHAR(100),
  IN p_NMUA_STKNHANG VARCHAR(30),
  IN p_NMUA_TNHANG VARCHAR(400),
  IN p_TGTCTHUE DECIMAL(21,6),
  IN p_TGTKCTHUE DECIMAL(21,6),
  IN p_TGTTTHUE DECIMAL(21,6),
  IN p_TTCKTMAI DECIMAL(21,6),
  IN p_CKTMAI_GCHU VARCHAR(1000),
  IN p_TGTKHAC DECIMAL(21,6),
  IN p_TGTTTBSO DECIMAL(21,6),
  IN p_TGTTTBCHU VARCHAR(255),
  IN p_TGTCTHUE_VND DECIMAL(21,6),
  IN p_TGTKCTHUE_VND DECIMAL(21,6),
  IN p_TGTTTHUE_VND DECIMAL(21,6),
  IN p_TTCKTMAI_VND DECIMAL(21,6),
  IN p_TGTKHAC_VND DECIMAL(21,6),
  IN p_TGTTTBSO_VND DECIMAL(21,6),
  IN p_DLQRCODE VARCHAR(512),
  IN p_MCCQT VARCHAR(34),
  IN p_MTRACUU VARCHAR(100),
  IN p_MTDIEP VARCHAR(50),
  IN p_MGDDTu VARCHAR(50),
  IN p_TAX_SUMMARY_JSON LONGTEXT,
  IN p_FEE_JSON LONGTEXT,
  IN p_EXTRA_JSON LONGTEXT,
  IN p_ERROR_MESSAGE VARCHAR(1000),
  IN p_DOC_VERSION INT,
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_INVOICE_ID BIGINT DEFAULT 0;
  DECLARE v_SHDON VARCHAR(8);
  DECLARE v_KHMSHDON VARCHAR(11);
  DECLARE v_KHHDON VARCHAR(8);
  DECLARE v_MTRACUU VARCHAR(100);
  DECLARE v_XSL_ID BIGINT DEFAULT NULL;
  DECLARE v_ROW_COUNT INT DEFAULT 0;

  SET v_INVOICE_ID = IFNULL(p_INVOICE_ID, 0);
  SET v_SHDON = TRIM(IFNULL(p_SHDON, ''));
  SET v_KHMSHDON = TRIM(IFNULL(p_KHMSHDON, ''));
  SET v_KHHDON = TRIM(IFNULL(p_KHHDON, ''));
  SET v_MTRACUU = NULLIF(TRIM(IFNULL(p_MTRACUU, '')), '');
  SET v_XSL_ID = NULLIF(IFNULL(p_XSL_ID, 0), 0);

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF p_SELLER_ID IS NULL OR p_SELLER_ID <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SELLER_ID is required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM einvoice_seller_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND SELLER_ID = p_SELLER_ID
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice seller not found';
  END IF;

  IF v_XSL_ID IS NULL THEN
    SELECT xsl.XSL_ID
      INTO v_XSL_ID
      FROM einvoice_seller_xsl_template xsl
     WHERE xsl.COMPANY_CD = p_COMPANY_CD
       AND xsl.ISDEL = 0
     ORDER BY
       CASE
         WHEN IFNULL(xsl.KHMSHDON, '') = v_KHMSHDON
          AND IFNULL(xsl.KHHDON, '') = v_KHHDON
         THEN 0
         ELSE 1
       END,
       CASE
         WHEN IFNULL(xsl.KHHDON, '') = v_KHHDON
         THEN 0
         ELSE 1
       END,
       xsl.IS_DEFAULT DESC,
       xsl.IS_ACTIVE DESC,
       xsl.XSL_ID
     LIMIT 1;
  END IF;

  IF v_XSL_ID IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM einvoice_seller_xsl_template xsl
    WHERE xsl.COMPANY_CD = p_COMPANY_CD
      AND xsl.XSL_ID = v_XSL_ID
      AND xsl.ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice XSL template not found';
  END IF;

  IF v_INVOICE_ID > 0 AND NOT EXISTS (
    SELECT 1
    FROM einvoice_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND INVOICE_ID = v_INVOICE_ID
      AND ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice not found';
  END IF;

  IF v_SHDON <> '' AND EXISTS (
    SELECT 1
    FROM einvoice_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND IFNULL(KHMSHDON, '') = v_KHMSHDON
      AND IFNULL(KHHDON, '') = v_KHHDON
      AND IFNULL(SHDON, '') = v_SHDON
      AND ISDEL = 0
      AND (v_INVOICE_ID = 0 OR INVOICE_ID <> v_INVOICE_ID)
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice number already exists';
  END IF;

  IF v_INVOICE_ID > 0 AND EXISTS (
    SELECT 1
    FROM einvoice_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND INVOICE_ID = v_INVOICE_ID
      AND ISDEL = 0
      AND IFNULL(IS_SIGNED, 0) = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice is already signed';
  END IF;

  IF v_INVOICE_ID > 0 AND IFNULL(p_DOC_VERSION, 0) <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DOC_VERSION is required';
  END IF;

  IF v_INVOICE_ID > 0 AND v_MTRACUU IS NULL THEN
    SELECT NULLIF(TRIM(IFNULL(MTRACUU, '')), '')
      INTO v_MTRACUU
      FROM einvoice_info
     WHERE COMPANY_CD = p_COMPANY_CD
       AND INVOICE_ID = v_INVOICE_ID
       AND ISDEL = 0
     LIMIT 1;
  END IF;

  IF v_MTRACUU IS NULL THEN
    REPEAT
      SET v_MTRACUU = CONCAT('TC', UPPER(HEX(RANDOM_BYTES(9))));
    UNTIL NOT EXISTS (
      SELECT 1
      FROM einvoice_info
      WHERE COMPANY_CD = p_COMPANY_CD
        AND MTRACUU = v_MTRACUU
        AND ISDEL = 0
    )
    END REPEAT;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM einvoice_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND MTRACUU = v_MTRACUU
      AND ISDEL = 0
      AND (v_INVOICE_ID = 0 OR INVOICE_ID <> v_INVOICE_ID)
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice lookup code already exists';
  END IF;

  IF v_INVOICE_ID = 0 THEN
    INSERT INTO einvoice_info (
      COMPANY_CD,
      SELLER_ID,
      XSL_ID,
      PBAN,
      THDON,
      KHMSHDON,
      KHHDON,
      SHDON,
      MHSO,
      NLAP,
      HDCTTCHINH,
      SBKE,
      NBKE,
      DVTTE,
      TGIA,
      HTTTOAN,
      MSTTCGP,
      TCHDON,
      SOURCE_INVOICE_ID,
      NMUA_TEN,
      NMUA_MST,
      NMUA_MDVQHNSACH,
      NMUA_DCHI,
      NMUA_MTINH,
      NMUA_TTINH,
      NMUA_MXA,
      NMUA_TXA,
      NMUA_MKHANG,
      NMUA_SDTHOAI,
      NMUA_CCCDAN,
      NMUA_SHCHIEU,
      NMUA_DCTDTU,
      NMUA_HVTNMHANG,
      NMUA_STKNHANG,
      NMUA_TNHANG,
      TGTCTHUE,
      TGTKCTHUE,
      TGTTTHUE,
      TTCKTMAI,
      CKTMAI_GCHU,
      TGTKHAC,
      TGTTTBSO,
      TGTTTBCHU,
      TGTCTHUE_VND,
      TGTKCTHUE_VND,
      TGTTTHUE_VND,
      TTCKTMAI_VND,
      TGTKHAC_VND,
      TGTTTBSO_VND,
      DLQRCODE,
      MCCQT,
      MTRACUU,
      MTDIEP,
      MGDDTu,
      TAX_SUMMARY_JSON,
      FEE_JSON,
      EXTRA_JSON,
      IS_SIGNED,
      ERROR_MESSAGE,
      CREATE_BY,
      CREATE_AT,
      UPDATE_BY,
      UPDATE_AT,
      ISDEL
    ) VALUES (
      p_COMPANY_CD,
      p_SELLER_ID,
      v_XSL_ID,
      IFNULL(NULLIF(TRIM(p_PBAN), ''), '2.1.0'),
      NULLIF(TRIM(p_THDON), ''),
      NULLIF(TRIM(p_KHMSHDON), ''),
      NULLIF(TRIM(p_KHHDON), ''),
      NULL,
      NULLIF(TRIM(p_MHSO), ''),
      p_NLAP,
      IFNULL(p_HDCTTCHINH, 0),
      NULLIF(TRIM(p_SBKE), ''),
      p_NBKE,
      IFNULL(NULLIF(TRIM(p_DVTTE), ''), 'VND'),
      IFNULL(p_TGIA, 1),
      NULLIF(TRIM(p_HTTTOAN), ''),
      NULLIF(TRIM(p_MSTTCGP), ''),
      IFNULL(p_TCHDON, 0),
      NULLIF(p_SOURCE_INVOICE_ID, 0),
      NULLIF(TRIM(p_NMUA_TEN), ''),
      NULLIF(TRIM(p_NMUA_MST), ''),
      NULLIF(TRIM(p_NMUA_MDVQHNSACH), ''),
      NULLIF(TRIM(p_NMUA_DCHI), ''),
      NULLIF(TRIM(p_NMUA_MTINH), ''),
      NULLIF(TRIM(p_NMUA_TTINH), ''),
      NULLIF(TRIM(p_NMUA_MXA), ''),
      NULLIF(TRIM(p_NMUA_TXA), ''),
      NULLIF(TRIM(p_NMUA_MKHANG), ''),
      NULLIF(TRIM(p_NMUA_SDTHOAI), ''),
      NULLIF(TRIM(p_NMUA_CCCDAN), ''),
      NULLIF(TRIM(p_NMUA_SHCHIEU), ''),
      NULLIF(TRIM(p_NMUA_DCTDTU), ''),
      NULLIF(TRIM(p_NMUA_HVTNMHANG), ''),
      NULLIF(TRIM(p_NMUA_STKNHANG), ''),
      NULLIF(TRIM(p_NMUA_TNHANG), ''),
      IFNULL(p_TGTCTHUE, 0),
      IFNULL(p_TGTKCTHUE, 0),
      IFNULL(p_TGTTTHUE, 0),
      IFNULL(p_TTCKTMAI, 0),
      NULLIF(TRIM(p_CKTMAI_GCHU), ''),
      IFNULL(p_TGTKHAC, 0),
      IFNULL(p_TGTTTBSO, 0),
      NULLIF(TRIM(p_TGTTTBCHU), ''),
      IFNULL(p_TGTCTHUE_VND, 0),
      IFNULL(p_TGTKCTHUE_VND, 0),
      IFNULL(p_TGTTTHUE_VND, 0),
      IFNULL(p_TTCKTMAI_VND, 0),
      IFNULL(p_TGTKHAC_VND, 0),
      IFNULL(p_TGTTTBSO_VND, 0),
      NULLIF(TRIM(p_DLQRCODE), ''),
      NULLIF(TRIM(p_MCCQT), ''),
      v_MTRACUU,
      NULLIF(TRIM(p_MTDIEP), ''),
      NULLIF(TRIM(p_MGDDTu), ''),
      p_TAX_SUMMARY_JSON,
      p_FEE_JSON,
      p_EXTRA_JSON,
      0,
      NULLIF(TRIM(p_ERROR_MESSAGE), ''),
      p_USERID,
      NOW(),
      p_USERID,
      NOW(),
      0
    );
    SET v_INVOICE_ID = LAST_INSERT_ID();
  ELSE
    UPDATE einvoice_info
    SET SELLER_ID = p_SELLER_ID,
        XSL_ID = v_XSL_ID,
        PBAN = IFNULL(NULLIF(TRIM(p_PBAN), ''), '2.1.0'),
        THDON = NULLIF(TRIM(p_THDON), ''),
        KHMSHDON = NULLIF(TRIM(p_KHMSHDON), ''),
        KHHDON = NULLIF(TRIM(p_KHHDON), ''),
        MHSO = NULLIF(TRIM(p_MHSO), ''),
        NLAP = p_NLAP,
        HDCTTCHINH = IFNULL(p_HDCTTCHINH, 0),
        SBKE = NULLIF(TRIM(p_SBKE), ''),
        NBKE = p_NBKE,
        DVTTE = IFNULL(NULLIF(TRIM(p_DVTTE), ''), 'VND'),
        TGIA = IFNULL(p_TGIA, 1),
        HTTTOAN = NULLIF(TRIM(p_HTTTOAN), ''),
        MSTTCGP = NULLIF(TRIM(p_MSTTCGP), ''),
        TCHDON = IFNULL(p_TCHDON, 0),
        SOURCE_INVOICE_ID = NULLIF(p_SOURCE_INVOICE_ID, 0),
        NMUA_TEN = NULLIF(TRIM(p_NMUA_TEN), ''),
        NMUA_MST = NULLIF(TRIM(p_NMUA_MST), ''),
        NMUA_MDVQHNSACH = NULLIF(TRIM(p_NMUA_MDVQHNSACH), ''),
        NMUA_DCHI = NULLIF(TRIM(p_NMUA_DCHI), ''),
        NMUA_MTINH = NULLIF(TRIM(p_NMUA_MTINH), ''),
        NMUA_TTINH = NULLIF(TRIM(p_NMUA_TTINH), ''),
        NMUA_MXA = NULLIF(TRIM(p_NMUA_MXA), ''),
        NMUA_TXA = NULLIF(TRIM(p_NMUA_TXA), ''),
        NMUA_MKHANG = NULLIF(TRIM(p_NMUA_MKHANG), ''),
        NMUA_SDTHOAI = NULLIF(TRIM(p_NMUA_SDTHOAI), ''),
        NMUA_CCCDAN = NULLIF(TRIM(p_NMUA_CCCDAN), ''),
        NMUA_SHCHIEU = NULLIF(TRIM(p_NMUA_SHCHIEU), ''),
        NMUA_DCTDTU = NULLIF(TRIM(p_NMUA_DCTDTU), ''),
        NMUA_HVTNMHANG = NULLIF(TRIM(p_NMUA_HVTNMHANG), ''),
        NMUA_STKNHANG = NULLIF(TRIM(p_NMUA_STKNHANG), ''),
        NMUA_TNHANG = NULLIF(TRIM(p_NMUA_TNHANG), ''),
        TGTCTHUE = IFNULL(p_TGTCTHUE, 0),
        TGTKCTHUE = IFNULL(p_TGTKCTHUE, 0),
        TGTTTHUE = IFNULL(p_TGTTTHUE, 0),
        TTCKTMAI = IFNULL(p_TTCKTMAI, 0),
        CKTMAI_GCHU = NULLIF(TRIM(p_CKTMAI_GCHU), ''),
        TGTKHAC = IFNULL(p_TGTKHAC, 0),
        TGTTTBSO = IFNULL(p_TGTTTBSO, 0),
        TGTTTBCHU = NULLIF(TRIM(p_TGTTTBCHU), ''),
        TGTCTHUE_VND = IFNULL(p_TGTCTHUE_VND, 0),
        TGTKCTHUE_VND = IFNULL(p_TGTKCTHUE_VND, 0),
        TGTTTHUE_VND = IFNULL(p_TGTTTHUE_VND, 0),
        TTCKTMAI_VND = IFNULL(p_TTCKTMAI_VND, 0),
        TGTKHAC_VND = IFNULL(p_TGTKHAC_VND, 0),
        TGTTTBSO_VND = IFNULL(p_TGTTTBSO_VND, 0),
        DLQRCODE = NULLIF(TRIM(p_DLQRCODE), ''),
        MCCQT = NULLIF(TRIM(p_MCCQT), ''),
        MTRACUU = v_MTRACUU,
        MTDIEP = NULLIF(TRIM(p_MTDIEP), ''),
        MGDDTu = NULLIF(TRIM(p_MGDDTu), ''),
        TAX_SUMMARY_JSON = p_TAX_SUMMARY_JSON,
        FEE_JSON = p_FEE_JSON,
        EXTRA_JSON = p_EXTRA_JSON,
        ERROR_MESSAGE = NULLIF(TRIM(p_ERROR_MESSAGE), ''),
        UPDATE_BY = p_USERID,
        UPDATE_AT = NOW(),
        DOC_VERSION = DOC_VERSION + 1
    WHERE COMPANY_CD = p_COMPANY_CD
      AND INVOICE_ID = v_INVOICE_ID
      AND ISDEL = 0
      AND DOC_VERSION = IFNULL(p_DOC_VERSION, 0);

    SET v_ROW_COUNT = ROW_COUNT();

    IF v_ROW_COUNT = 0 THEN
      IF EXISTS (
        SELECT 1
        FROM einvoice_info
        WHERE COMPANY_CD = p_COMPANY_CD
          AND INVOICE_ID = v_INVOICE_ID
          AND ISDEL = 0
      ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice version conflict';
      END IF;

      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice not found';
    END IF;
  END IF;

  SELECT v_INVOICE_ID AS INVOICE_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.setEInvoiceInfoMgdDTu
DROP PROCEDURE IF EXISTS `setEInvoiceInfoMgdDTu`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceInfoMgdDTu`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_INVOICE_ID BIGINT UNSIGNED,
  IN p_MGDDTu VARCHAR(50),
