-- Dumping structure for procedure am_web_001.setEInvoiceInfoReceiveXml
DROP PROCEDURE IF EXISTS `setEInvoiceInfoReceiveXml`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceInfoReceiveXml`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_INVOICE_ID BIGINT UNSIGNED,
  IN p_XML_FTP_PATH VARCHAR(1000),
  IN p_MCCQT VARCHAR(34),
  IN p_INVOICE_STATUS TINYINT,
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_SOURCE_INVOICE_ID BIGINT UNSIGNED DEFAULT NULL;
  DECLARE v_SOURCE_STATUS TINYINT DEFAULT NULL;

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF p_INVOICE_ID IS NULL OR p_INVOICE_ID <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVOICE_ID is required';
  END IF;

  IF p_XML_FTP_PATH IS NULL OR TRIM(p_XML_FTP_PATH) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'XML_FTP_PATH is required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM einvoice_info
     WHERE COMPANY_CD = TRIM(p_COMPANY_CD)
       AND INVOICE_ID = p_INVOICE_ID
       AND ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice not found';
  END IF;

  UPDATE einvoice_info
     SET XML_FTP_PATH = p_XML_FTP_PATH,
         MCCQT = IFNULL(NULLIF(TRIM(p_MCCQT), ''), MCCQT),
         INVOICE_STATUS = IFNULL(p_INVOICE_STATUS, INVOICE_STATUS),
         ERROR_MESSAGE = NULL,
         UPDATE_BY = IFNULL(TRIM(p_USERID), ''),
         UPDATE_AT = NOW()
   WHERE COMPANY_CD = TRIM(p_COMPANY_CD)
     AND INVOICE_ID = p_INVOICE_ID
     AND ISDEL = 0;

  SELECT SOURCE_INVOICE_ID
    INTO v_SOURCE_INVOICE_ID
    FROM einvoice_info
   WHERE COMPANY_CD = TRIM(p_COMPANY_CD)
     AND INVOICE_ID = p_INVOICE_ID
     AND ISDEL = 0
   LIMIT 1;

  SET v_SOURCE_STATUS = CASE IFNULL(p_INVOICE_STATUS, 0)
    WHEN 3 THEN 2
    WHEN 5 THEN 4
    ELSE NULL
  END;

  IF v_SOURCE_INVOICE_ID IS NOT NULL
     AND v_SOURCE_INVOICE_ID > 0
     AND v_SOURCE_STATUS IS NOT NULL THEN
    UPDATE einvoice_info
       SET INVOICE_STATUS = v_SOURCE_STATUS,
           UPDATE_BY = IFNULL(TRIM(p_USERID), ''),
           UPDATE_AT = NOW()
     WHERE COMPANY_CD = TRIM(p_COMPANY_CD)
       AND INVOICE_ID = v_SOURCE_INVOICE_ID
       AND ISDEL = 0;
  END IF;

  SELECT ROW_COUNT() AS AFFECTED_ROWS;
END//
DELIMITER ;


