CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceMttReceive`(IN p_COMPANY_CD VARCHAR(20), IN p_BATCH_ID VARCHAR(50), IN p_ACCEPTED TINYINT, IN p_ERROR TEXT, IN p_USER_ID VARCHAR(50))
BEGIN
 UPDATE einvoice_info i INNER JOIN einvoice_mtt_batch b ON b.COMPANY_CD=i.COMPANY_CD AND b.BATCH_ID=i.MTDIEP
 SET i.INVOICE_STATUS=CASE WHEN p_ACCEPTED=0 THEN 6 WHEN IFNULL(i.TCHDON,0)=1 THEN 3 WHEN IFNULL(i.TCHDON,0)=2 THEN 5 ELSE 1 END,
     i.ERROR_MESSAGE=LEFT(p_ERROR,1000), i.UPDATE_BY=p_USER_ID, i.UPDATE_AT=NOW()
 WHERE i.COMPANY_CD=p_COMPANY_CD AND i.MTDIEP=p_BATCH_ID AND i.ISDEL=0 AND i.IS_SIGNED=1;
 SELECT ROW_COUNT();
END//
DELIMITER ;


