-- Dumping structure for procedure am_web_001.setEInvoiceSellerInfo
DROP PROCEDURE IF EXISTS `setEInvoiceSellerInfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceSellerInfo`(
  IN p_SELLER_ID BIGINT UNSIGNED,
  IN p_COMPANY_CD VARCHAR(20),
  IN p_SELLER_CD VARCHAR(50),
  IN p_SELLER_NM VARCHAR(400),
  IN p_SELLER_TAX_CD VARCHAR(14),
  IN p_SELLER_ADDRESS VARCHAR(400),
  IN p_MDDKDOANH VARCHAR(5),
  IN p_TDDKDOANH VARCHAR(400),
  IN p_DCDDKDOANH VARCHAR(400),
  IN p_MCHANG VARCHAR(50),
  IN p_TCHANG VARCHAR(400),
  IN p_SDTHOAI VARCHAR(200),
  IN p_DCTDTU VARCHAR(50),
  IN p_STKNHANG VARCHAR(200),
  IN p_TNHANG VARCHAR(1000),
  IN p_FAX VARCHAR(20),
  IN p_WEBSITE VARCHAR(100),
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_SELLER_ID BIGINT UNSIGNED DEFAULT 0;
  DECLARE v_TAX_DIGITS VARCHAR(14) DEFAULT '';
  DECLARE v_IS_HKD TINYINT DEFAULT 0;
  DECLARE v_MDDKDOANH VARCHAR(5) DEFAULT NULL;
  DECLARE v_TDDKDOANH VARCHAR(400) DEFAULT NULL;
  DECLARE v_DCDDKDOANH VARCHAR(400) DEFAULT NULL;

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF p_SELLER_CD IS NULL OR TRIM(p_SELLER_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SELLER_CD is required';
  END IF;

  IF p_SELLER_NM IS NULL OR TRIM(p_SELLER_NM) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SELLER_NM is required';
  END IF;

  IF p_SELLER_TAX_CD IS NULL OR TRIM(p_SELLER_TAX_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SELLER_TAX_CD is required';
  END IF;

  IF p_SELLER_ADDRESS IS NULL OR TRIM(p_SELLER_ADDRESS) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SELLER_ADDRESS is required';
  END IF;

  -- Hộ kinh doanh / CNKD: MST gồm đúng 12 chữ số.
  -- Tránh REGEXP_REPLACE (MySQL 8.0.4+ only) — MariaDB/MySQL cũ dùng REPLACE + REGEXP.
  SET v_TAX_DIGITS = REPLACE(REPLACE(REPLACE(TRIM(IFNULL(p_SELLER_TAX_CD, '')), '-', ''), ' ', ''), '.', '');
  SET v_IS_HKD = IF(v_TAX_DIGITS REGEXP '^[0-9]{12}$', 1, 0);
  IF v_IS_HKD = 1 THEN
    SET v_MDDKDOANH = NULLIF(TRIM(IFNULL(p_MDDKDOANH, '')), '');
    SET v_TDDKDOANH = NULLIF(TRIM(IFNULL(p_TDDKDOANH, '')), '');
    SET v_DCDDKDOANH = NULLIF(TRIM(IFNULL(p_DCDDKDOANH, '')), '');
  ELSE
    SET v_MDDKDOANH = NULL;
    SET v_TDDKDOANH = NULL;
    SET v_DCDDKDOANH = NULL;
  END IF;

  IF IFNULL(p_SELLER_ID, 0) > 0 THEN
    SELECT SELLER_ID
      INTO v_SELLER_ID
      FROM einvoice_seller_info
     WHERE COMPANY_CD = p_COMPANY_CD
       AND SELLER_ID = p_SELLER_ID
     LIMIT 1;

    IF IFNULL(v_SELLER_ID, 0) = 0 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice seller not found';
    END IF;

    UPDATE einvoice_seller_info
       SET SELLER_CD = TRIM(p_SELLER_CD),
