CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceSellerXslTemplate`(
  IN p_XSL_ID BIGINT UNSIGNED,
  IN p_SELLER_ID BIGINT UNSIGNED,
  IN p_COMPANY_CD VARCHAR(20),
  IN p_TEMPLATE_CD VARCHAR(50),
  IN p_TEMPLATE_NM VARCHAR(255),
  IN p_THDON VARCHAR(100),
  IN p_KHMSHDON VARCHAR(11),
  IN p_KHHDON VARCHAR(8),
  IN p_FROM_SHDON VARCHAR(8),
  IN p_TO_SHDON VARCHAR(8),
  IN p_USE_MULTI_TAX_RATE TINYINT,
  IN p_LOGO_PATH VARCHAR(500),
  IN p_INVOICE_BACKGROUND_PATH VARCHAR(500),
  IN p_INVOICE_BORDER_PATH VARCHAR(500),
  IN p_BACKGROUND_PATH VARCHAR(500),
  IN p_XSL_CONTENT LONGTEXT,
  IN p_XSL_DESIGN_CONTENT LONGTEXT,
  IN p_VERSION_NO INT,
  IN p_IS_DEFAULT TINYINT,
  IN p_IS_ACTIVE TINYINT,
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_XSL_ID BIGINT UNSIGNED DEFAULT 0;
  DECLARE v_SELLER_ID BIGINT UNSIGNED DEFAULT 0;
  DECLARE v_TEMPLATE_CD VARCHAR(50);
  DECLARE v_LOGO_PATH VARCHAR(500);
  DECLARE v_INVOICE_BACKGROUND_PATH VARCHAR(500);
  DECLARE v_INVOICE_BORDER_PATH VARCHAR(500);
  DECLARE v_BACKGROUND_PATH VARCHAR(500);

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF IFNULL(p_SELLER_ID, 0) = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SELLER_ID is required';
  END IF;

  IF p_XSL_CONTENT IS NULL OR TRIM(p_XSL_CONTENT) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'XSL_CONTENT is required';
  END IF;

  SELECT SELLER_ID
    INTO v_SELLER_ID
    FROM einvoice_seller_info
   WHERE COMPANY_CD = p_COMPANY_CD
     AND SELLER_ID = p_SELLER_ID
   LIMIT 1;

  IF IFNULL(v_SELLER_ID, 0) = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice seller not found';
  END IF;

  SET v_TEMPLATE_CD = NULLIF(TRIM(IFNULL(p_TEMPLATE_CD, '')), '');
  IF v_TEMPLATE_CD IS NULL THEN
    SET v_TEMPLATE_CD = 'VAT_DEFAULT';
  END IF;

  SET v_LOGO_PATH = NULLIF(TRIM(IFNULL(p_LOGO_PATH, '')), '');
  SET v_INVOICE_BACKGROUND_PATH = NULLIF(TRIM(IFNULL(p_INVOICE_BACKGROUND_PATH, '')), '');
  SET v_INVOICE_BORDER_PATH = NULLIF(TRIM(IFNULL(p_INVOICE_BORDER_PATH, '')), '');
  SET v_BACKGROUND_PATH = NULLIF(TRIM(IFNULL(p_BACKGROUND_PATH, '')), '');

  IF IFNULL(p_XSL_ID, 0) > 0 THEN
    SELECT XSL_ID
      INTO v_XSL_ID
      FROM einvoice_seller_xsl_template
     WHERE XSL_ID = p_XSL_ID
       AND COMPANY_CD = p_COMPANY_CD
       AND ISDEL = 0
     LIMIT 1;

    IF IFNULL(v_XSL_ID, 0) = 0 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice XSL template not found';
    END IF;

    UPDATE einvoice_seller_xsl_template
       SET TEMPLATE_CD = v_TEMPLATE_CD,
           TEMPLATE_NM = NULLIF(TRIM(IFNULL(p_TEMPLATE_NM, '')), ''),
           THDON = NULLIF(TRIM(IFNULL(p_THDON, '')), ''),
           KHMSHDON = NULLIF(TRIM(IFNULL(p_KHMSHDON, '')), ''),
           KHHDON = NULLIF(TRIM(IFNULL(p_KHHDON, '')), ''),
           FROM_SHDON = NULLIF(TRIM(IFNULL(p_FROM_SHDON, '')), ''),
           TO_SHDON = NULLIF(TRIM(IFNULL(p_TO_SHDON, '')), ''),
           USE_MULTI_TAX_RATE = IFNULL(p_USE_MULTI_TAX_RATE, 0),
           VERSION_NO = IFNULL(p_VERSION_NO, 1),
           IS_DEFAULT = IFNULL(p_IS_DEFAULT, 0),
           IS_ACTIVE = IFNULL(p_IS_ACTIVE, 1),
           ISDEL = 0,
           UPDATE_BY = p_USERID,
           UPDATE_AT = NOW()
     WHERE XSL_ID = v_XSL_ID
       AND COMPANY_CD = p_COMPANY_CD;
  ELSE
    IF IFNULL(p_IS_DEFAULT, 0) = 1 THEN
      SELECT XSL_ID
        INTO v_XSL_ID
        FROM einvoice_seller_xsl_template
       WHERE COMPANY_CD = p_COMPANY_CD
         AND TEMPLATE_CD = v_TEMPLATE_CD
         AND IS_DEFAULT = 1
         AND ISDEL = 0
       ORDER BY XSL_ID DESC
       LIMIT 1;

      IF IFNULL(v_XSL_ID, 0) > 0 THEN
        UPDATE einvoice_seller_xsl_template
           SET TEMPLATE_NM = NULLIF(TRIM(IFNULL(p_TEMPLATE_NM, '')), ''),
               THDON = NULLIF(TRIM(IFNULL(p_THDON, '')), ''),
               KHMSHDON = NULLIF(TRIM(IFNULL(p_KHMSHDON, '')), ''),
               KHHDON = NULLIF(TRIM(IFNULL(p_KHHDON, '')), ''),
               FROM_SHDON = NULLIF(TRIM(IFNULL(p_FROM_SHDON, '')), ''),
               TO_SHDON = NULLIF(TRIM(IFNULL(p_TO_SHDON, '')), ''),
               USE_MULTI_TAX_RATE = IFNULL(p_USE_MULTI_TAX_RATE, 0),
               VERSION_NO = IFNULL(p_VERSION_NO, VERSION_NO),
               IS_DEFAULT = IFNULL(p_IS_DEFAULT, 1),
               IS_ACTIVE = IFNULL(p_IS_ACTIVE, 1),
               ISDEL = 0,
               UPDATE_BY = p_USERID,
               UPDATE_AT = NOW()
         WHERE XSL_ID = v_XSL_ID
           AND COMPANY_CD = p_COMPANY_CD;
      ELSE
        INSERT INTO einvoice_seller_xsl_template (
          COMPANY_CD,
          TEMPLATE_CD,
          TEMPLATE_NM,
          THDON,
          KHMSHDON,
          KHHDON,
          FROM_SHDON,
          TO_SHDON,
          USE_MULTI_TAX_RATE,
          VERSION_NO,
          IS_DEFAULT,
          IS_ACTIVE,
          ISDEL,
          CREATE_BY,
          CREATE_AT
        ) VALUES (
          p_COMPANY_CD,
          v_TEMPLATE_CD,
          NULLIF(TRIM(IFNULL(p_TEMPLATE_NM, '')), ''),
          NULLIF(TRIM(IFNULL(p_THDON, '')), ''),
          NULLIF(TRIM(IFNULL(p_KHMSHDON, '')), ''),
          NULLIF(TRIM(IFNULL(p_KHHDON, '')), ''),
          NULLIF(TRIM(IFNULL(p_FROM_SHDON, '')), ''),
          NULLIF(TRIM(IFNULL(p_TO_SHDON, '')), ''),
          IFNULL(p_USE_MULTI_TAX_RATE, 0),
          IFNULL(p_VERSION_NO, 1),
          IFNULL(p_IS_DEFAULT, 1),
          IFNULL(p_IS_ACTIVE, 1),
          0,
          p_USERID,
          NOW()
        );

        SET v_XSL_ID = LAST_INSERT_ID();
      END IF;
    ELSE
      INSERT INTO einvoice_seller_xsl_template (
        COMPANY_CD,
        TEMPLATE_CD,
        TEMPLATE_NM,
        THDON,
        KHMSHDON,
        KHHDON,
        FROM_SHDON,
        TO_SHDON,
        USE_MULTI_TAX_RATE,
        VERSION_NO,
        IS_DEFAULT,
        IS_ACTIVE,
        ISDEL,
        CREATE_BY,
        CREATE_AT
      ) VALUES (
        p_COMPANY_CD,
        v_TEMPLATE_CD,
        NULLIF(TRIM(IFNULL(p_TEMPLATE_NM, '')), ''),
        NULLIF(TRIM(IFNULL(p_THDON, '')), ''),
        NULLIF(TRIM(IFNULL(p_KHMSHDON, '')), ''),
        NULLIF(TRIM(IFNULL(p_KHHDON, '')), ''),
        NULLIF(TRIM(IFNULL(p_FROM_SHDON, '')), ''),
        NULLIF(TRIM(IFNULL(p_TO_SHDON, '')), ''),
        IFNULL(p_USE_MULTI_TAX_RATE, 0),
        IFNULL(p_VERSION_NO, 1),
        0,
        IFNULL(p_IS_ACTIVE, 0),
        0,
        p_USERID,
        NOW()
      );

      SET v_XSL_ID = LAST_INSERT_ID();
    END IF;
  END IF;

  -- Táº¡o design máº·c Ä‘á»‹nh láº§n Ä‘áº§u. Image paths seed láº§n Ä‘áº§u; sync sau khÃ´ng ghi Ä‘Ã¨ áº£nh.
  INSERT INTO einvoice_seller_xsl_template_design (
    CONTENT_ID, DESIGN_NM, XSL_CONTENT,
    LOGO_PATH, INVOICE_BACKGROUND_PATH, INVOICE_BORDER_PATH, BACKGROUND_PATH,
    CREATE_BY, CREATE_AT, UPDATE_BY, UPDATE_AT
  )
  SELECT v_XSL_ID, 'Máº«u chuáº©n',
         NULLIF(TRIM(IFNULL(p_XSL_CONTENT, p_XSL_DESIGN_CONTENT)), ''),
         v_LOGO_PATH, v_INVOICE_BACKGROUND_PATH, v_INVOICE_BORDER_PATH, v_BACKGROUND_PATH,
         p_USERID, NOW(), p_USERID, NOW()
    FROM DUAL
   WHERE NOT EXISTS (SELECT 1 FROM einvoice_seller_xsl_template_design WHERE CONTENT_ID = v_XSL_ID);

  -- Sync XSLT cho design Ä‘áº§u tiÃªn. KhÃ´ng Ä‘á»¥ng LOGO_PATH / image columns.
  UPDATE einvoice_seller_xsl_template_design
     SET XSL_CONTENT = NULLIF(TRIM(IFNULL(p_XSL_CONTENT, p_XSL_DESIGN_CONTENT)), ''),
         UPDATE_BY = p_USERID,
         UPDATE_AT = NOW()
   WHERE CONTENT_ID = v_XSL_ID
     AND DESIGN_ID = (
       SELECT min_id FROM (
         SELECT MIN(DESIGN_ID) AS min_id
           FROM einvoice_seller_xsl_template_design
          WHERE CONTENT_ID = v_XSL_ID
       ) t
     );

  IF IFNULL(p_IS_DEFAULT, 0) = 1 THEN
    UPDATE einvoice_seller_xsl_template
       SET IS_DEFAULT = 0,
           UPDATE_BY = p_USERID,
           UPDATE_AT = NOW()
     WHERE COMPANY_CD = p_COMPANY_CD
       AND TEMPLATE_CD = v_TEMPLATE_CD
       AND XSL_ID <> v_XSL_ID
       AND IS_DEFAULT = 1
       AND ISDEL = 0;
  END IF;

  SELECT v_XSL_ID AS XSL_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.setEInvoiceSellerXslTemplateDraft
DROP PROCEDURE IF EXISTS `setEInvoiceSellerXslTemplateDraft`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceSellerXslTemplateDraft`(
  IN p_CONTENT_ID BIGINT UNSIGNED,
  IN p_DESIGN_ID BIGINT UNSIGNED,
  IN p_COMPANY_CD VARCHAR(20),
  IN p_XSL_CONTENT LONGTEXT,
  IN p_LOGO_PATH VARCHAR(500),
  IN p_INVOICE_BACKGROUND_PATH VARCHAR(500),
  IN p_INVOICE_BORDER_PATH VARCHAR(500),
  IN p_BACKGROUND_PATH VARCHAR(500),
  IN p_USERID VARCHAR(50)
)
BEGIN
  IF p_XSL_CONTENT IS NULL OR TRIM(p_XSL_CONTENT) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'XSL_CONTENT is required';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM einvoice_seller_xsl_template template
    WHERE template.XSL_ID = p_CONTENT_ID AND template.COMPANY_CD = p_COMPANY_CD AND template.ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invoice template not found';
  END IF;

  UPDATE einvoice_seller_xsl_template_design
  SET XSL_CONTENT = p_XSL_CONTENT,
      LOGO_PATH = IFNULL(NULLIF(TRIM(IFNULL(p_LOGO_PATH, '')), ''), LOGO_PATH),
      INVOICE_BACKGROUND_PATH = IFNULL(NULLIF(TRIM(IFNULL(p_INVOICE_BACKGROUND_PATH, '')), ''), INVOICE_BACKGROUND_PATH),
      INVOICE_BORDER_PATH = IFNULL(NULLIF(TRIM(IFNULL(p_INVOICE_BORDER_PATH, '')), ''), INVOICE_BORDER_PATH),
      BACKGROUND_PATH = IFNULL(NULLIF(TRIM(IFNULL(p_BACKGROUND_PATH, '')), ''), BACKGROUND_PATH),
      UPDATE_BY = p_USERID,
      UPDATE_AT = NOW()
  WHERE DESIGN_ID = p_DESIGN_ID AND CONTENT_ID = p_CONTENT_ID;

  IF ROW_COUNT() = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invoice template design not found';
  END IF;

  SELECT DESIGN_ID, CONTENT_ID, CONTENT_ID AS XSL_ID, DESIGN_NM, XSL_CONTENT,
         LOGO_PATH, INVOICE_BACKGROUND_PATH, INVOICE_BORDER_PATH, BACKGROUND_PATH,
         1 AS VERSION_NO, 'USER' AS SOURCE_TYPE
  FROM einvoice_seller_xsl_template_design WHERE DESIGN_ID = p_DESIGN_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.setEInvoiceSellerXslTemplateMeta
DROP PROCEDURE IF EXISTS `setEInvoiceSellerXslTemplateMeta`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceSellerXslTemplateMeta`(
  IN p_XSL_ID BIGINT UNSIGNED,
  IN p_COMPANY_CD VARCHAR(20),
  IN p_TEMPLATE_NM VARCHAR(255),
  IN p_THDON VARCHAR(100),
  IN p_KHMSHDON VARCHAR(11),
  IN p_KHHDON VARCHAR(8),
  IN p_FROM_SHDON VARCHAR(8),
  IN p_TO_SHDON VARCHAR(8),
  IN p_USE_MULTI_TAX_RATE TINYINT,
  IN p_XSL_CONTENT LONGTEXT,
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_XSL_ID BIGINT UNSIGNED DEFAULT 0;
  DECLARE v_IS_ACTIVE TINYINT DEFAULT 0;
  DECLARE v_IS_DEFAULT TINYINT DEFAULT 0;
  DECLARE v_DESIGN_ID BIGINT UNSIGNED DEFAULT 0;
  DECLARE v_TEMPLATE_CD VARCHAR(50) DEFAULT 'VAT_DEFAULT';
  DECLARE v_TEMPLATE_NM VARCHAR(255);
  DECLARE v_FROM_SHDON VARCHAR(8);

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF NULLIF(TRIM(IFNULL(p_KHMSHDON, '')), '') IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'KHMSHDON is required';
  END IF;

  IF NULLIF(TRIM(IFNULL(p_KHHDON, '')), '') IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'KHHDON is required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM einvoice_seller_info
     WHERE COMPANY_CD = p_COMPANY_CD
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice seller not found';
  END IF;

  SET v_TEMPLATE_NM = NULLIF(TRIM(IFNULL(p_TEMPLATE_NM, '')), '');
  SET v_FROM_SHDON = IFNULL(NULLIF(TRIM(IFNULL(p_FROM_SHDON, '')), ''), '1');

  IF IFNULL(p_XSL_ID, 0) > 0 THEN
    SELECT XSL_ID, IFNULL(IS_ACTIVE, 0)
      INTO v_XSL_ID, v_IS_ACTIVE
      FROM einvoice_seller_xsl_template
     WHERE XSL_ID = p_XSL_ID
       AND COMPANY_CD = p_COMPANY_CD
       AND ISDEL = 0
     LIMIT 1;

    IF IFNULL(v_XSL_ID, 0) = 0 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice XSL template not found';
    END IF;

    IF IFNULL(v_IS_ACTIVE, 0) = 1 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cannot edit published invoice template';
    END IF;

    UPDATE einvoice_seller_xsl_template
       SET TEMPLATE_NM = IFNULL(v_TEMPLATE_NM, TEMPLATE_NM),
           THDON = NULLIF(TRIM(IFNULL(p_THDON, '')), ''),
           KHMSHDON = NULLIF(TRIM(IFNULL(p_KHMSHDON, '')), ''),
           KHHDON = NULLIF(TRIM(IFNULL(p_KHHDON, '')), ''),
           FROM_SHDON = v_FROM_SHDON,
           TO_SHDON = NULLIF(TRIM(IFNULL(p_TO_SHDON, '')), ''),
           USE_MULTI_TAX_RATE = IFNULL(p_USE_MULTI_TAX_RATE, 0),
           UPDATE_BY = p_USERID,
           UPDATE_AT = NOW()
     WHERE XSL_ID = v_XSL_ID
       AND COMPANY_CD = p_COMPANY_CD
       AND ISDEL = 0
       AND IFNULL(IS_ACTIVE, 0) = 0;
  ELSE
    IF p_XSL_CONTENT IS NULL OR TRIM(p_XSL_CONTENT) = '' THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'XSL_CONTENT is required';
    END IF;

    IF v_TEMPLATE_NM IS NULL THEN
      SET v_TEMPLATE_NM = CONCAT(
        NULLIF(TRIM(IFNULL(p_KHMSHDON, '')), ''),
        '/',
        NULLIF(TRIM(IFNULL(p_KHHDON, '')), '')
      );
    END IF;

    SELECT CASE WHEN COUNT(*) = 0 THEN 1 ELSE 0 END
      INTO v_IS_DEFAULT
      FROM einvoice_seller_xsl_template
     WHERE COMPANY_CD = p_COMPANY_CD
       AND ISDEL = 0;

    INSERT INTO einvoice_seller_xsl_template (
      COMPANY_CD,
      TEMPLATE_CD,
      TEMPLATE_NM,
      THDON,
      KHMSHDON,
      KHHDON,
      FROM_SHDON,
      TO_SHDON,
      USE_MULTI_TAX_RATE,
      VERSION_NO,
      IS_DEFAULT,
      IS_ACTIVE,
      ISDEL,
      CREATE_BY,
      CREATE_AT
    ) VALUES (
      p_COMPANY_CD,
      v_TEMPLATE_CD,
      v_TEMPLATE_NM,
      NULLIF(TRIM(IFNULL(p_THDON, '')), ''),
      NULLIF(TRIM(IFNULL(p_KHMSHDON, '')), ''),
      NULLIF(TRIM(IFNULL(p_KHHDON, '')), ''),
      v_FROM_SHDON,
      NULLIF(TRIM(IFNULL(p_TO_SHDON, '')), ''),
      IFNULL(p_USE_MULTI_TAX_RATE, 0),
      1,
      v_IS_DEFAULT,
      0,
      0,
      p_USERID,
      NOW()
    );

    SET v_XSL_ID = LAST_INSERT_ID();

    INSERT INTO einvoice_seller_xsl_template_design (
      CONTENT_ID, DESIGN_NM, XSL_CONTENT,
      CREATE_BY, CREATE_AT, UPDATE_BY, UPDATE_AT
    )
    SELECT v_XSL_ID, 'Mẫu chuẩn', p_XSL_CONTENT,
           p_USERID, NOW(), p_USERID, NOW()
      FROM DUAL
     WHERE NOT EXISTS (
       SELECT 1 FROM einvoice_seller_xsl_template_design WHERE CONTENT_ID = v_XSL_ID
     );

    SELECT MIN(DESIGN_ID)
      INTO v_DESIGN_ID
      FROM einvoice_seller_xsl_template_design
     WHERE CONTENT_ID = v_XSL_ID;

    UPDATE einvoice_seller_xsl_template_design
       SET XSL_CONTENT = p_XSL_CONTENT,
           UPDATE_BY = p_USERID,
           UPDATE_AT = NOW()
     WHERE DESIGN_ID = v_DESIGN_ID;

    INSERT INTO einvoice_seller_xsl_template_content (
      XSL_ID, CURRENT_DESIGN_ID, XSL_CONTENT, UPDATE_BY, UPDATE_AT
    ) VALUES (
      v_XSL_ID, v_DESIGN_ID, p_XSL_CONTENT, p_USERID, NOW()
    )
    ON DUPLICATE KEY UPDATE
      CURRENT_DESIGN_ID = VALUES(CURRENT_DESIGN_ID),
      XSL_CONTENT = VALUES(XSL_CONTENT),
      UPDATE_BY = VALUES(UPDATE_BY),
      UPDATE_AT = VALUES(UPDATE_AT);
  END IF;

  SELECT
    xsl.XSL_ID,
    xsl.COMPANY_CD,
    xsl.TEMPLATE_CD,
    xsl.TEMPLATE_NM,
    xsl.THDON,
    xsl.KHMSHDON,
    xsl.KHHDON,
    xsl.FROM_SHDON,
    xsl.TO_SHDON,
    xsl.USE_MULTI_TAX_RATE,
    xsl.VERSION_NO,
    xsl.IS_DEFAULT,
    xsl.IS_ACTIVE
  FROM einvoice_seller_xsl_template xsl
  WHERE xsl.XSL_ID = v_XSL_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.setEInvoiceShdon
DROP PROCEDURE IF EXISTS `setEInvoiceShdon`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceShdon`(
  IN p_COMPANY_CD VARCHAR(20),
  IN p_INVOICE_ID BIGINT,
  IN p_SHDON VARCHAR(8),
  IN p_NLAP DATE,
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_SHDON VARCHAR(8);
  DECLARE v_KHMSHDON VARCHAR(11);
  DECLARE v_KHHDON VARCHAR(8);

  SET v_SHDON = TRIM(IFNULL(p_SHDON, ''));

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF p_INVOICE_ID IS NULL OR p_INVOICE_ID <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVOICE_ID is required';
  END IF;

  IF v_SHDON = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SHDON is required';
  END IF;

  IF p_NLAP IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NLAP is required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM einvoice_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND INVOICE_ID = p_INVOICE_ID
      AND ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice not found';
  END IF;

  SELECT IFNULL(KHMSHDON, ''), IFNULL(KHHDON, '')
  INTO v_KHMSHDON, v_KHHDON
  FROM einvoice_info
  WHERE COMPANY_CD = p_COMPANY_CD
    AND INVOICE_ID = p_INVOICE_ID
    AND ISDEL = 0
  LIMIT 1;

  IF EXISTS (
