CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setEInvoiceTbaoInfo`(
  IN p_TBAO_ID BIGINT,
  IN p_COMPANY_CD VARCHAR(20),
  IN p_PBAN VARCHAR(6),
  IN p_MSO VARCHAR(15),
  IN p_TEN VARCHAR(255),
  IN p_LOAI TINYINT,
  IN p_MCQT VARCHAR(5),
  IN p_TCQT VARCHAR(100),
  IN p_SO VARCHAR(30),
  IN p_NTBCCQT DATE,
  IN p_MST VARCHAR(14),
  IN p_TNNT VARCHAR(400),
  IN p_DDANH VARCHAR(50),
  IN p_NTBAO DATE,
  IN p_MGDDTU VARCHAR(50),
  IN p_MTDIEP VARCHAR(50),
  IN p_ERROR_MESSAGE VARCHAR(1000),
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_TBAO_ID BIGINT DEFAULT 0;
  DECLARE v_LOAI TINYINT DEFAULT 1;

  SET v_TBAO_ID = IFNULL(p_TBAO_ID, 0);
  SET v_LOAI = CASE WHEN IFNULL(p_LOAI, 1) = 2 THEN 2 ELSE 1 END;

  IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  IF p_MCQT IS NULL OR TRIM(p_MCQT) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MCQT is required';
  END IF;

  IF p_TCQT IS NULL OR TRIM(p_TCQT) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'TCQT is required';
  END IF;

  IF p_TNNT IS NULL OR TRIM(p_TNNT) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'TNNT is required';
  END IF;

  IF p_DDANH IS NULL OR TRIM(p_DDANH) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DDANH is required';
  END IF;

  IF p_NTBAO IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NTBAO is required';
  END IF;

  IF v_LOAI = 2 AND (p_SO IS NULL OR TRIM(p_SO) = '') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SO is required when LOAI = 2';
  END IF;

  IF v_LOAI = 2 AND p_NTBCCQT IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NTBCCQT is required when LOAI = 2';
  END IF;

  IF v_TBAO_ID > 0 AND NOT EXISTS (
    SELECT 1 FROM einvoice_tbao_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND TBAO_ID = v_TBAO_ID
      AND ISDEL = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice error notice not found';
  END IF;

  IF v_TBAO_ID > 0 AND EXISTS (
    SELECT 1 FROM einvoice_tbao_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND TBAO_ID = v_TBAO_ID
      AND ISDEL = 0
      AND IFNULL(IS_SIGNED, 0) = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice error notice is already signed';
  END IF;

  IF v_TBAO_ID = 0 THEN
    INSERT INTO einvoice_tbao_info (
      COMPANY_CD,
      PBAN,
      MSO,
      TEN,
      LOAI,
      MCQT,
      TCQT,
      SO,
      NTBCCQT,
      MST,
      TNNT,
      DDANH,
      NTBAO,
      XML,
      IS_SIGNED,
      MGDDTU,
      MTDIEP,
      ERROR_MESSAGE,
      CREATE_BY,
      CREATE_AT,
      UPDATE_BY,
      UPDATE_AT,
      ISDEL
    ) VALUES (
      p_COMPANY_CD,
      IFNULL(NULLIF(TRIM(p_PBAN), ''), '2.1.0'),
      IFNULL(NULLIF(TRIM(p_MSO), ''), '04/SS-HĐĐT'),
      IFNULL(NULLIF(TRIM(p_TEN), ''), 'Thông báo hóa đơn điện tử có sai sót'),
      v_LOAI,
      IFNULL(NULLIF(TRIM(p_MCQT), ''), ''),
      IFNULL(NULLIF(TRIM(p_TCQT), ''), ''),
      NULLIF(TRIM(p_SO), ''),
      p_NTBCCQT,
      NULLIF(TRIM(p_MST), ''),
      IFNULL(NULLIF(TRIM(p_TNNT), ''), ''),
      IFNULL(NULLIF(TRIM(p_DDANH), ''), ''),
      p_NTBAO,
      NULL,
      0,
      NULLIF(TRIM(p_MGDDTU), ''),
      NULLIF(TRIM(p_MTDIEP), ''),
      NULLIF(TRIM(p_ERROR_MESSAGE), ''),
      p_USERID,
      NOW(),
      p_USERID,
      NOW(),
      0
    );
    SET v_TBAO_ID = LAST_INSERT_ID();
  ELSE
    UPDATE einvoice_tbao_info
    SET PBAN = IFNULL(NULLIF(TRIM(p_PBAN), ''), '2.1.0'),
        MSO = IFNULL(NULLIF(TRIM(p_MSO), ''), '04/SS-HĐĐT'),
        TEN = IFNULL(NULLIF(TRIM(p_TEN), ''), 'Thông báo hóa đơn điện tử có sai sót'),
        LOAI = v_LOAI,
        MCQT = IFNULL(NULLIF(TRIM(p_MCQT), ''), ''),
        TCQT = IFNULL(NULLIF(TRIM(p_TCQT), ''), ''),
        SO = NULLIF(TRIM(p_SO), ''),
        NTBCCQT = p_NTBCCQT,
        MST = NULLIF(TRIM(p_MST), ''),
        TNNT = IFNULL(NULLIF(TRIM(p_TNNT), ''), ''),
        DDANH = IFNULL(NULLIF(TRIM(p_DDANH), ''), ''),
        NTBAO = p_NTBAO,
        MGDDTU = COALESCE(NULLIF(TRIM(p_MGDDTU), ''), MGDDTU),
        MTDIEP = COALESCE(NULLIF(TRIM(p_MTDIEP), ''), MTDIEP),
        ERROR_MESSAGE = NULLIF(TRIM(p_ERROR_MESSAGE), ''),
        UPDATE_BY = p_USERID,
        UPDATE_AT = NOW()
    WHERE COMPANY_CD = p_COMPANY_CD
      AND TBAO_ID = v_TBAO_ID
      AND ISDEL = 0;
  END IF;

  SELECT v_TBAO_ID AS TBAO_ID;
END//
DELIMITER ;


