     LIMIT 1;



    IF IFNULL(v_SETTING_ID, 0) = 0 THEN

      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'E-invoice user setting not found';

    END IF;



    UPDATE einvoice_user_setting

