      CREATE_AT,

      UPDATE_AT

    ) VALUES (

      p_COMPANY_CD,

      p_USER_ID,

      TRIM(p_SETTING_KEY),

      TRIM(p_SETTING_VALUE),

      UPPER(TRIM(IFNULL(p_VALUE_TYPE, 'STRING'))),

      0,

      NOW(),

      NOW()

    )

    ON DUPLICATE KEY UPDATE

      SETTING_VALUE = TRIM(p_SETTING_VALUE),

      VALUE_TYPE = UPPER(TRIM(IFNULL(p_VALUE_TYPE, 'STRING'))),

      ISDEL = 0,

      UPDATE_AT = NOW();



    SELECT SETTING_ID

      INTO v_SETTING_ID

      FROM einvoice_user_setting

     WHERE COMPANY_CD = p_COMPANY_CD

       AND USER_ID = p_USER_ID

       AND SETTING_KEY = TRIM(p_SETTING_KEY)

     LIMIT 1;

  END IF;



  SELECT v_SETTING_ID AS SETTING_ID;

END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.setInventoryCogs
DROP PROCEDURE IF EXISTS `setInventoryCogs`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setInventoryCogs`(
    IN p_companyCd VARCHAR(20),
    IN p_userId VARCHAR(50),
    IN p_transferId BIGINT,
    IN p_voucherNo VARCHAR(50),
    IN p_ymd VARCHAR(8),
    IN p_total DECIMAL(18,2),
    IN p_amountProvided CHAR(1),
    IN p_chitId BIGINT,
    IN p_chitCd VARCHAR(30),
    IN p_detailId BIGINT,
    IN p_detailCd VARCHAR(30),
    IN p_summary TEXT
)
BEGIN
    DECLARE v_chitId BIGINT DEFAULT NULL;
    DECLARE v_detailId BIGINT DEFAULT NULL;
    DECLARE v_owned CHAR(1) DEFAULT '0';
    DECLARE v_accountCount INT DEFAULT 0;
    DECLARE v_otherDetailCount INT DEFAULT 0;
    DECLARE v_existingYmd VARCHAR(8) DEFAULT NULL;
    DECLARE v_found INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_found=0;

    SET v_chitId=p_chitId;
    SET v_detailId=p_detailId;

    IF p_total IS NULL OR p_total<0 THEN
        SELECT 'NEGATIVE_AMOUNT' AS RESULT_CODE;
    ELSE
        SET v_found=0;
        SELECT t.COGS_DETAIL_OWNED,1 INTO v_owned,v_found
        FROM chit_inventory_info t
        WHERE t.COMPANY_CD=p_companyCd AND t.INVENTORY_ID=p_transferId AND t.ISDEL='0';

        IF v_found=0 THEN
            SELECT 'NOT_FOUND' AS RESULT_CODE;
        ELSE
            IF v_chitId IS NOT NULL THEN
                SET v_found=0;
                SELECT h.CHIT_YMD,1 INTO v_existingYmd,v_found
                FROM chitinfo h
                WHERE h.COMPANY_CD=p_companyCd AND h.CHIT_ID=v_chitId AND h.ISDEL='0';
            END IF;

            IF v_chitId IS NOT NULL AND v_detailId IS NOT NULL AND v_detailId>0 THEN
                SELECT COUNT(*) INTO v_otherDetailCount
                FROM chitdetailinfo d
                WHERE d.COMPANY_CD=p_companyCd AND d.CHIT_ID=v_chitId AND d.ISDEL='0'
                AND d.CHITDETAIL_ID<>v_detailId;
            END IF;

            IF v_chitId IS NOT NULL AND IFNULL(v_owned,'0')<>'1' AND IFNULL(p_amountProvided,'0')<>'1' THEN
                IF v_existingYmd IS NULL OR p_ymd<>v_existingYmd THEN
                    SELECT 'DATE_MISMATCH' AS RESULT_CODE;
                ELSE
                    SELECT 'NO_CHANGE' AS RESULT_CODE;
                END IF;
            ELSE
                SELECT COUNT(*) INTO v_accountCount
                FROM acclist_info a
                WHERE a.COMPANY_CD=p_companyCd AND a.ACC_CD IN ('632','156') AND a.ISDEL='0';

                IF v_accountCount<>2 THEN
                    SELECT 'MISSING_ACCOUNTS' AS RESULT_CODE;
                ELSEIF v_chitId IS NOT NULL AND v_existingYmd IS NOT NULL AND v_existingYmd<>p_ymd AND v_otherDetailCount>0 THEN
                    SELECT 'SHARED_DATE_CHANGE' AS RESULT_CODE;
                ELSE
                    IF v_chitId IS NULL THEN
                        INSERT INTO chitinfo (COMPANY_CD,CHIT_CD,CHIT_NO,CHIT_YMD,CHIT_TYPE,INPUT_TYPE,AMOUNT,CREATE_BY,UPDATE_BY)
                        VALUES (p_companyCd,p_chitCd,p_voucherNo,p_ymd,'OT','AR',p_total,p_userId,p_userId);
                        SET v_chitId=LAST_INSERT_ID();
                        INSERT INTO chitinfo_ext (COMPANY_CD,CHIT_ID,CHIT_CD,CREATE_BY,UPDATE_BY)
                        VALUES (p_companyCd,v_chitId,p_chitCd,p_userId,p_userId);
                        UPDATE chit_inventory_info SET CHIT_ID_COGS=v_chitId
                        WHERE COMPANY_CD=p_companyCd AND INVENTORY_ID=p_transferId AND CHIT_ID_COGS IS NULL AND ISDEL='0';
                    ELSE
                        UPDATE chitinfo SET CHIT_TYPE='OT',CHIT_YMD=p_ymd,UPDATE_BY=p_userId
                        WHERE COMPANY_CD=p_companyCd AND CHIT_ID=v_chitId AND ISDEL='0';
                    END IF;

                    IF v_detailId IS NULL OR v_detailId<=0 THEN
                        INSERT INTO chitdetailinfo (COMPANY_CD,CHIT_ID,CHIT_CD,CHITDETAIL_CD,CHIT_YMD,DEBIT,CREDIT,AMOUNT,FC_TYPE,SORT,CREATE_BY,UPDATE_BY)
                        VALUES (p_companyCd,v_chitId,p_chitCd,p_detailCd,p_ymd,'632','156',p_total,'VND',1,p_userId,p_userId);
                        SET v_detailId=LAST_INSERT_ID();
                        INSERT INTO chitdetailinfo_ext (COMPANY_CD,CHITDETAIL_ID,CHITDETAIL_CD,HASINVENTORY,INVENTORY_YMD,CREATE_BY,UPDATE_BY)
                        VALUES (p_companyCd,v_detailId,p_detailCd,'0',p_ymd,p_userId,p_userId);
                    ELSE
                        UPDATE chitdetailinfo SET CHIT_YMD=p_ymd,AMOUNT=p_total,UPDATE_BY=p_userId,DEBIT='632',CREDIT='156'
                        WHERE COMPANY_CD=p_companyCd AND CHITDETAIL_ID=v_detailId AND ISDEL='0';
                        UPDATE chitdetailinfo_ext SET INVENTORY_YMD=p_ymd,UPDATE_BY=p_userId
                        WHERE COMPANY_CD=p_companyCd AND CHITDETAIL_ID=v_detailId AND ISDEL='0';
                    END IF;

                    UPDATE chit_inventory_info SET CHITDETAIL_ID_COGS=v_detailId,
                    COGS_DETAIL_OWNED=CASE WHEN (p_chitId IS NULL)=1 THEN '1' ELSE COGS_DETAIL_OWNED END,UPDATE_BY=p_userId
                    WHERE COMPANY_CD=p_companyCd AND INVENTORY_ID=p_transferId AND ISDEL='0';
                    UPDATE chitinfo SET AMOUNT=(SELECT COALESCE(SUM(AMOUNT),0) FROM chitdetailinfo
                    WHERE COMPANY_CD=p_companyCd AND CHIT_ID=v_chitId AND ISDEL='0'),UPDATE_BY=p_userId
                    WHERE COMPANY_CD=p_companyCd AND CHIT_ID=v_chitId AND ISDEL='0';
                    UPDATE chit_inventory_output SET CHITDETAIL_ID_COGS=NULL
                    WHERE COMPANY_CD=p_companyCd AND INVENTORY_ID=p_transferId AND ISDEL='0';
                    DELETE FROM chitdetaildescriptioninfo WHERE COMPANY_CD=p_companyCd AND CHITDETAIL_ID=v_detailId;
                    INSERT INTO chitdetaildescriptioninfo (COMPANY_CD,CHITDETAIL_ID,CHITDETAIL_CD,DESC_CD,LANG_TYPE,DESCRIPTION,CREATE_BY,UPDATE_BY)
                    VALUES (p_companyCd,v_detailId,p_detailCd,p_detailCd,'VIET',p_summary,p_userId,p_userId);
                    SELECT 'OK' AS RESULT_CODE;
                END IF;
            END IF;
        END IF;
    END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.setManagementInfo
DROP PROCEDURE IF EXISTS `setManagementInfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setManagementInfo`(
  IN p_MG_ID BIGINT(20),
  IN p_COMPANY_CD VARCHAR(20),
  IN p_MG_CD VARCHAR(20),
  IN p_MG_DESC_KOR VARCHAR(100),
  IN p_MG_DESC_ENG VARCHAR(100),
  IN p_MG_DESC_VIET VARCHAR(100),
  IN p_MG_CD_ROOT VARCHAR(20),
  IN p_ISDEL CHAR(1),
  IN p_USERID VARCHAR(50)
)
BEGIN
  DECLARE v_mg_cd VARCHAR(20);
  DECLARE v_mg_cd_root VARCHAR(20);

  SET v_mg_cd = TRIM(COALESCE(p_MG_CD, ''));
  SET v_mg_cd_root = TRIM(COALESCE(p_MG_CD_ROOT, ''));

  IF v_mg_cd = '' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'MG_CD is required';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM management_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND MG_CD = v_mg_cd
      AND (ISDEL IS NULL OR ISDEL = '0')
      AND ((p_MG_ID IS NULL OR p_MG_ID = 0) OR MG_ID <> p_MG_ID)
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'MG_CD already exists';
  END IF;

  IF p_MG_ID IS NULL OR p_MG_ID = 0 THEN
    INSERT INTO management_info
    (
      MG_CD,
      MG_DESC_KOR,
      MG_DESC_ENG,
      MG_DESC_VIET,
      ISDEL,
      CREATE_AT,
      CREATE_BY,
      UPDATE_AT,
      UPDATE_BY,
      MG_CD_ROOT,
      COMPANY_CD
    )
    VALUES
    (
      v_mg_cd,
      p_MG_DESC_KOR,
      p_MG_DESC_ENG,
      p_MG_DESC_VIET,
      COALESCE(p_ISDEL, '0'),
      NOW(),
      p_USERID,
      NOW(),
      p_USERID,
      v_mg_cd_root,
      p_COMPANY_CD
    );
  ELSE
    UPDATE management_info
    SET
      MG_CD = v_mg_cd,
      MG_DESC_KOR = p_MG_DESC_KOR,
      MG_DESC_ENG = p_MG_DESC_ENG,
      MG_DESC_VIET = p_MG_DESC_VIET,
      MG_CD_ROOT = v_mg_cd_root,
      ISDEL = COALESCE(p_ISDEL, '0'),
      UPDATE_AT = NOW(),
      UPDATE_BY = p_USERID
    WHERE COMPANY_CD = p_COMPANY_CD
      AND MG_ID = p_MG_ID;
  END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.setPitCtu
DROP PROCEDURE IF EXISTS `setPitCtu`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setPitCtu`(
 IN p_company VARCHAR(20),IN p_id BIGINT,IN p_version INT,IN p_xsl BIGINT,IN p_khctu VARCHAR(6),IN p_nlap DATE,
 IN p_tcctu INT,IN p_lhctlq INT,IN p_khmslq VARCHAR(11),IN p_khctlq VARCHAR(9),IN p_sctlq VARCHAR(8),IN p_nlctlq DATE,IN p_gchu VARCHAR(255),
 IN p_payer_ten VARCHAR(400),IN p_payer_mst VARCHAR(14),IN p_payer_dchi VARCHAR(400),IN p_payer_phone VARCHAR(20),
 IN p_nnt_ten VARCHAR(400),IN p_nnt_mst VARCHAR(14),IN p_nnt_dchi VARCHAR(400),IN p_qtich VARCHAR(400),IN p_cnctru INT,
 IN p_cccd VARCHAR(20),IN p_phone VARCHAR(20),IN p_email VARCHAR(50),IN p_nnt_gchu VARCHAR(255),
 IN p_ktnhap VARCHAR(250),IN p_tthang INT,IN p_dthang INT,IN p_nam INT,IN p_bhiem DECIMAL(21,6),IN p_tthien DECIMAL(21,6),
 IN p_ttncthue DECIMAL(21,6),IN p_ttntthue DECIMAL(21,6),IN p_sthue DECIMAL(21,6),IN p_user VARCHAR(50))
BEGIN
 IF IFNULL(p_id,0)=0 THEN
  INSERT INTO pit_ctu_info(COMPANY_CD,XSL_ID,KHCTU,NLAP,TCCTU,LHCTLQUAN,KHMSCTCLQUAN,KHCTCLQUAN,SCTCLQUAN,NLCTCLQUAN,GCHU,
   TCTTNHAP_TEN,TCTTNHAP_MST,TCTTNHAP_DCHI,TCTTNHAP_SDTHOAI,NNT_TEN,NNT_MST,NNT_DCHI,NNT_QTICH,NNT_CNCTRU,NNT_CCCDAN,NNT_SDTHOAI,NNT_DCTDTU,NNT_GCHU,
   KTNHAP,TTHANG,DTHANG,NAM,BHIEM,TTHIEN,TTNCTHUE,TTNTTHUE,STHUE,CREATE_BY,UPDATE_BY)
  VALUES(p_company,p_xsl,p_khctu,p_nlap,p_tcctu,p_lhctlq,p_khmslq,p_khctlq,p_sctlq,p_nlctlq,p_gchu,
   p_payer_ten,p_payer_mst,p_payer_dchi,p_payer_phone,p_nnt_ten,NULLIF(p_nnt_mst,''),p_nnt_dchi,NULLIF(p_qtich,''),p_cnctru,NULLIF(p_cccd,''),p_phone,NULLIF(p_email,''),NULLIF(p_nnt_gchu,''),
   p_ktnhap,p_tthang,p_dthang,p_nam,p_bhiem,p_tthien,p_ttncthue,p_ttntthue,p_sthue,p_user,p_user);
  SELECT LAST_INSERT_ID();
 ELSE
  UPDATE pit_ctu_info SET SCTU=CASE WHEN KHCTU<>p_khctu THEN NULL ELSE SCTU END,XSL_ID=p_xsl,KHCTU=p_khctu,NLAP=p_nlap,
   TCCTU=p_tcctu,LHCTLQUAN=p_lhctlq,KHMSCTCLQUAN=p_khmslq,KHCTCLQUAN=p_khctlq,SCTCLQUAN=p_sctlq,NLCTCLQUAN=p_nlctlq,GCHU=p_gchu,
   TCTTNHAP_TEN=p_payer_ten,TCTTNHAP_MST=p_payer_mst,TCTTNHAP_DCHI=p_payer_dchi,TCTTNHAP_SDTHOAI=p_payer_phone,
   NNT_TEN=p_nnt_ten,NNT_MST=NULLIF(p_nnt_mst,''),NNT_DCHI=p_nnt_dchi,NNT_QTICH=NULLIF(p_qtich,''),NNT_CNCTRU=p_cnctru,
   NNT_CCCDAN=NULLIF(p_cccd,''),NNT_SDTHOAI=p_phone,NNT_DCTDTU=NULLIF(p_email,''),NNT_GCHU=NULLIF(p_nnt_gchu,''),
   KTNHAP=p_ktnhap,TTHANG=p_tthang,DTHANG=p_dthang,NAM=p_nam,BHIEM=p_bhiem,TTHIEN=p_tthien,TTNCTHUE=p_ttncthue,TTNTTHUE=p_ttntthue,STHUE=p_sthue,
   RAW_XML=NULL,MTDIEP=NULL,DOC_VERSION=DOC_VERSION+1,UPDATE_BY=p_user
  WHERE COMPANY_CD=p_company AND CTU_ID=p_id AND DOC_VERSION=p_version AND IS_SIGNED=0 AND ISDEL=0;
  IF ROW_COUNT()<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Document changed or already signed'; END IF;
  SELECT p_id;
 END IF;
END//
DELIMITER ;


