-- Dumping structure for procedure am_web_001.setPitDocument
DROP PROCEDURE IF EXISTS `setPitDocument`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setPitDocument`(IN p_company VARCHAR(20),IN p_kind VARCHAR(20),IN p_id BIGINT,IN p_version INT,IN p_date DATE,IN p_tax VARCHAR(14),IN p_name VARCHAR(400),IN p_series VARCHAR(6),IN p_xsl_id BIGINT,IN p_data LONGTEXT,IN p_user VARCHAR(50))
BEGIN
 IF p_kind NOT IN ('declaration','certificate','error-notice') OR NULLIF(TRIM(p_data),'') IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid PIT document'; END IF;
 IF IFNULL(p_id,0)=0 THEN
  INSERT INTO pit_document(COMPANY_CD,KIND,DOC_DATE,TAX_CD,DISPLAY_NAME,SERIES,XSL_ID,DATA_JSON,UPDATE_BY) VALUES(p_company,p_kind,p_date,p_tax,p_name,NULLIF(p_series,''),NULLIF(p_xsl_id,0),p_data,p_user);
  SELECT LAST_INSERT_ID();
 ELSE
  UPDATE pit_document SET DOC_NO=CASE WHEN IFNULL(SERIES,'')<>IFNULL(p_series,'') THEN NULL ELSE DOC_NO END,
   DOC_DATE=p_date,TAX_CD=p_tax,DISPLAY_NAME=p_name,SERIES=NULLIF(p_series,''),XSL_ID=CASE WHEN p_kind='certificate' THEN NULLIF(p_xsl_id,0) ELSE XSL_ID END,DATA_JSON=p_data,RAW_XML=NULL,MTDIEP=NULL,DOC_VERSION=DOC_VERSION+1,UPDATE_BY=p_user,UPDATE_AT=NOW()
  WHERE COMPANY_CD=p_company AND KIND=p_kind AND DOCUMENT_ID=p_id AND DOC_VERSION=p_version AND IS_SIGNED=0 AND ISDEL=0;
  IF ROW_COUNT()<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Document changed or already signed. Reload.'; END IF;
  SELECT p_id;
 END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.setPitIncomePayer
