CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setPitIncomePayer`(
  IN p_company VARCHAR(20),
  IN p_payer_nm VARCHAR(255),
  IN p_tax_cd VARCHAR(14),
  IN p_address VARCHAR(500),
  IN p_phone VARCHAR(20),
  IN p_email VARCHAR(255),
  IN p_user VARCHAR(50)
)
BEGIN
  IF IFNULL(TRIM(p_company),'') = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;
  IF IFNULL(TRIM(p_payer_nm),'') = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PAYER_NM is required';
  END IF;
  IF IFNULL(TRIM(p_tax_cd),'') = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'TAX_CD is required';
  END IF;

  INSERT INTO pit_income_payer(
    COMPANY_CD, PAYER_NM, TAX_CD, ADDRESS, PHONE, EMAIL,
    CREATE_BY, CREATE_AT, UPDATE_BY, UPDATE_AT
  )
  VALUES(
    TRIM(p_company), TRIM(p_payer_nm), TRIM(p_tax_cd), TRIM(IFNULL(p_address,'')),
    NULLIF(TRIM(IFNULL(p_phone,'')),''), NULLIF(TRIM(IFNULL(p_email,'')),''),
    p_user, NOW(), p_user, NOW()
  )
  ON DUPLICATE KEY UPDATE
    PAYER_NM = VALUES(PAYER_NM),
    TAX_CD = VALUES(TAX_CD),
    ADDRESS = VALUES(ADDRESS),
    PHONE = VALUES(PHONE),
    EMAIL = VALUES(EMAIL),
    UPDATE_BY = p_user,
    UPDATE_AT = NOW();

  CALL getPitIncomePayer(p_company);
END//
DELIMITER ;


