 ELSEIF p_target='PIT_ERROR_NOTICE' THEN UPDATE pit_tbao_info SET MGDDTU=p_mgd WHERE COMPANY_CD=p_company AND TBAO_ID=p_id AND IS_SIGNED=1;
 END IF;
END//
