 ELSEIF p_target='PIT_ERROR_NOTICE' THEN UPDATE pit_tbao_info SET CQT_STATUS=p_status,RESPONSE_PRIORITY=p_priority,RESPONSE_XML=p_xml,ERROR_MESSAGE=p_error WHERE COMPANY_CD=p_company AND TBAO_ID=p_id AND MTDIEP=p_message AND IS_SIGNED=1 AND RESPONSE_PRIORITY<=p_priority;
 END IF;
