CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setPitSignature`(IN p_company VARCHAR(20),IN p_target VARCHAR(30),IN p_id BIGINT,IN p_version INT,IN p_xml LONGTEXT,IN p_user VARCHAR(50))
BEGIN
 IF p_target='PIT_DECLARATION' THEN UPDATE pit_tkhai_info SET SIGNED_XML=p_xml,IS_SIGNED=1,CQT_STATUS=1,DOC_VERSION=DOC_VERSION+1,UPDATE_BY=p_user WHERE COMPANY_CD=p_company AND TKHAI_ID=p_id AND DOC_VERSION=p_version AND RAW_XML IS NOT NULL AND MTDIEP IS NOT NULL AND IS_SIGNED=0 AND ISDEL=0;
 ELSEIF p_target='PIT_CERTIFICATE' THEN UPDATE pit_ctu_info SET SIGNED_XML=p_xml,IS_SIGNED=1,CQT_STATUS=1,DOC_VERSION=DOC_VERSION+1,UPDATE_BY=p_user WHERE COMPANY_CD=p_company AND CTU_ID=p_id AND DOC_VERSION=p_version AND RAW_XML IS NOT NULL AND MTDIEP IS NOT NULL AND IS_SIGNED=0 AND ISDEL=0;
 ELSEIF p_target='PIT_ERROR_NOTICE' THEN UPDATE pit_tbao_info SET SIGNED_XML=p_xml,IS_SIGNED=1,CQT_STATUS=1,DOC_VERSION=DOC_VERSION+1,UPDATE_BY=p_user WHERE COMPANY_CD=p_company AND TBAO_ID=p_id AND DOC_VERSION=p_version AND RAW_XML IS NOT NULL AND MTDIEP IS NOT NULL AND IS_SIGNED=0 AND ISDEL=0;
 END IF;
