-- Dumping structure for procedure am_web_001.setPitXslTemplate
DROP PROCEDURE IF EXISTS `setPitXslTemplate`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setPitXslTemplate`(
  IN p_company VARCHAR(20),
  IN p_xsl_id BIGINT,
  IN p_template_cd VARCHAR(50),
  IN p_template_nm VARCHAR(255),
  IN p_series VARCHAR(6),
  IN p_from_doc_no BIGINT,
  IN p_to_doc_no BIGINT,
  IN p_is_default TINYINT,
  IN p_is_active TINYINT,
  IN p_xsl_content LONGTEXT,
  IN p_logo_path VARCHAR(500),
  IN p_background_path VARCHAR(500),
  IN p_nen_path VARCHAR(500),
  IN p_user VARCHAR(50)
)
BEGIN
  DECLARE v_id BIGINT DEFAULT 0;
  DECLARE v_cd VARCHAR(50);
  DECLARE v_nm VARCHAR(255);
  DECLARE v_series VARCHAR(6);
  DECLARE v_from BIGINT UNSIGNED DEFAULT 1;
  DECLARE v_to BIGINT UNSIGNED DEFAULT NULL;
  DECLARE v_old_series VARCHAR(6);
  DECLARE v_used INT DEFAULT 0;
  DECLARE v_dup INT DEFAULT 0;

  IF IFNULL(TRIM(p_company),'') = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COMPANY_CD is required';
  END IF;

  SET v_cd = IFNULL(NULLIF(TRIM(p_template_cd),''), '03/TNCN');
  SET v_nm = NULLIF(TRIM(IFNULL(p_template_nm,'')), '');
  SET v_series = UPPER(NULLIF(TRIM(IFNULL(p_series,'')), ''));
  SET v_from = IFNULL(NULLIF(p_from_doc_no,0), 1);
  SET v_to = NULLIF(p_to_doc_no, 0);

  IF v_series IS NULL OR v_series NOT REGEXP '^CT[0-9]{2}[A-Z]{2}$' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SERIES must be CT + year + 2 letters (e.g. CT26AA)';
  END IF;
  IF v_from < 1 OR v_from > 99999999 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'FROM_DOC_NO invalid';
  END IF;
  IF v_to IS NOT NULL AND (v_to < v_from OR v_to > 99999999) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'TO_DOC_NO invalid';
  END IF;

  SELECT COUNT(*) INTO v_dup FROM pit_xsl_template
   WHERE COMPANY_CD = p_company AND SERIES = v_series AND ISDEL = 0
     AND (IFNULL(p_xsl_id,0) = 0 OR XSL_ID <> p_xsl_id);
  IF IFNULL(v_dup,0) > 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SERIES already registered for this company';
  END IF;

  IF IFNULL(p_xsl_id,0) > 0 THEN
    SELECT XSL_ID, SERIES INTO v_id, v_old_series FROM pit_xsl_template
     WHERE COMPANY_CD = p_company AND XSL_ID = p_xsl_id AND ISDEL = 0 LIMIT 1;
    IF IFNULL(v_id,0) = 0 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PIT XSL template not found';
    END IF;

    IF IFNULL(v_old_series,'') <> IFNULL(v_series,'') THEN
      SELECT COUNT(*) INTO v_used FROM pit_ctu_info
       WHERE COMPANY_CD = p_company AND ISDEL = 0
         AND (XSL_ID = v_id OR KHCTU = v_old_series);
      IF IFNULL(v_used,0) > 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cannot change SERIES after documents issued';
      END IF;
    END IF;

    UPDATE pit_xsl_template
       SET TEMPLATE_NM = IFNULL(v_nm, TEMPLATE_NM),
           SERIES = v_series,
           FROM_DOC_NO = v_from,
           TO_DOC_NO = v_to,
           IS_DEFAULT = IFNULL(p_is_default, IS_DEFAULT),
           IS_ACTIVE = IFNULL(p_is_active, IS_ACTIVE),
           UPDATE_BY = p_user,
           UPDATE_AT = NOW()
     WHERE XSL_ID = v_id AND COMPANY_CD = p_company AND ISDEL = 0;

    IF p_xsl_content IS NOT NULL AND TRIM(p_xsl_content) <> '' THEN
      INSERT INTO pit_xsl_template_content(XSL_ID, XSL_CONTENT, LOGO_PATH, BACKGROUND_PATH, NEN_PATH, UPDATE_BY, UPDATE_AT)
      VALUES(v_id, p_xsl_content, NULLIF(TRIM(IFNULL(p_logo_path,'')),''), NULLIF(TRIM(IFNULL(p_background_path,'')),''), NULLIF(TRIM(IFNULL(p_nen_path,'')),''), p_user, NOW())
      ON DUPLICATE KEY UPDATE
        XSL_CONTENT = VALUES(XSL_CONTENT),
        LOGO_PATH = COALESCE(VALUES(LOGO_PATH), LOGO_PATH),
        BACKGROUND_PATH = COALESCE(VALUES(BACKGROUND_PATH), BACKGROUND_PATH),
        NEN_PATH = COALESCE(VALUES(NEN_PATH), NEN_PATH),
        UPDATE_BY = p_user,
        UPDATE_AT = NOW();
    ELSE
      UPDATE pit_xsl_template_content
         SET LOGO_PATH = CASE WHEN p_logo_path IS NULL THEN LOGO_PATH ELSE NULLIF(TRIM(p_logo_path),'') END,
             BACKGROUND_PATH = CASE WHEN p_background_path IS NULL THEN BACKGROUND_PATH ELSE NULLIF(TRIM(p_background_path),'') END,
             NEN_PATH = CASE WHEN p_nen_path IS NULL THEN NEN_PATH ELSE NULLIF(TRIM(p_nen_path),'') END,
             UPDATE_BY = p_user,
             UPDATE_AT = NOW()
       WHERE XSL_ID = v_id;
    END IF;
  ELSE
    IF p_xsl_content IS NULL OR TRIM(p_xsl_content) = '' THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'XSL_CONTENT is required';
    END IF;
    IF v_nm IS NULL THEN SET v_nm = CONCAT('Máº«u ', v_cd, ' Â· ', v_series); END IF;

    INSERT INTO pit_xsl_template(COMPANY_CD, TEMPLATE_CD, TEMPLATE_NM, SERIES, FROM_DOC_NO, TO_DOC_NO, IS_DEFAULT, IS_ACTIVE, CREATE_BY, UPDATE_BY)
    VALUES(p_company, v_cd, v_nm, v_series, v_from, v_to, IFNULL(p_is_default,0), IFNULL(p_is_active,1), p_user, p_user);
    SET v_id = LAST_INSERT_ID();

    INSERT INTO pit_xsl_template_content(XSL_ID, XSL_CONTENT, LOGO_PATH, BACKGROUND_PATH, NEN_PATH, UPDATE_BY, UPDATE_AT)
    VALUES(v_id, p_xsl_content, NULLIF(TRIM(IFNULL(p_logo_path,'')),''), NULLIF(TRIM(IFNULL(p_background_path,'')),''), NULLIF(TRIM(IFNULL(p_nen_path,'')),''), p_user, NOW());
  END IF;

  IF IFNULL(p_is_default,0) = 1 THEN
    UPDATE pit_xsl_template
       SET IS_DEFAULT = CASE WHEN XSL_ID = v_id THEN 1 ELSE 0 END,
           UPDATE_BY = p_user,
           UPDATE_AT = NOW()
     WHERE COMPANY_CD = p_company AND TEMPLATE_CD = v_cd AND ISDEL = 0;
  END IF;

  SELECT v_id AS XSL_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.setPitXslTemplateImage
DROP PROCEDURE IF EXISTS `setPitXslTemplateImage`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setPitXslTemplateImage`(
  IN p_company VARCHAR(20),
  IN p_xsl_id BIGINT,
  IN p_kind VARCHAR(30),
  IN p_path VARCHAR(500),
  IN p_user VARCHAR(50)
)
BEGIN
  DECLARE v_id BIGINT DEFAULT 0;
  SELECT XSL_ID INTO v_id FROM pit_xsl_template
   WHERE COMPANY_CD = p_company AND XSL_ID = p_xsl_id AND ISDEL = 0 LIMIT 1;
  IF IFNULL(v_id,0) = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PIT XSL template not found';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM pit_xsl_template_content WHERE XSL_ID = v_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PIT XSL content not found';
  END IF;

  IF p_kind IN ('logo') THEN
    UPDATE pit_xsl_template_content SET LOGO_PATH = NULLIF(TRIM(IFNULL(p_path,'')),''), UPDATE_BY = p_user, UPDATE_AT = NOW() WHERE XSL_ID = v_id;
  ELSEIF p_kind IN ('background') THEN
    UPDATE pit_xsl_template_content SET BACKGROUND_PATH = NULLIF(TRIM(IFNULL(p_path,'')),''), UPDATE_BY = p_user, UPDATE_AT = NOW() WHERE XSL_ID = v_id;
  ELSEIF p_kind IN ('nen','invoice-background') THEN
    UPDATE pit_xsl_template_content SET NEN_PATH = NULLIF(TRIM(IFNULL(p_path,'')),''), UPDATE_BY = p_user, UPDATE_AT = NOW() WHERE XSL_ID = v_id;
  ELSE
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unsupported image kind';
  END IF;

  UPDATE pit_xsl_template SET UPDATE_BY = p_user, UPDATE_AT = NOW() WHERE XSL_ID = v_id;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.setProductInfo
DROP PROCEDURE IF EXISTS `setProductInfo`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setProductInfo`(
  IN p_PRODUCT_ID BIGINT,
  IN p_COMPANY_CD VARCHAR(20),
  IN p_PRODUCT_CD VARCHAR(50),
  IN p_PRODUCT_NM_VIET VARCHAR(300),
  IN p_PRODUCT_NM_ENG VARCHAR(300),
  IN p_PRODUCT_NM_KOR VARCHAR(300),
  IN p_PRODUCT_NM_CHINA VARCHAR(300),
  IN p_PRODUCT_KIND_ID BIGINT,
  IN p_UNIT_ID BIGINT,
  IN p_STORE_ID BIGINT,
  IN p_DIVISION VARCHAR(300),
  IN p_SUMMARY VARCHAR(4000),
  IN p_USERID VARCHAR(20)
)
BEGIN
  DECLARE v_product_cd VARCHAR(50);
  DECLARE v_product_kind_id BIGINT;
  DECLARE v_unit_id BIGINT;
  DECLARE v_store_id BIGINT;

  SET v_product_cd = TRIM(COALESCE(p_PRODUCT_CD, ''));
  IF v_product_cd = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PRODUCT_CD is required';
  END IF;

  -- 0 / empty → NULL (FK columns are optional)
  SET v_product_kind_id = NULLIF(p_PRODUCT_KIND_ID, 0);
  SET v_unit_id = NULLIF(p_UNIT_ID, 0);
  SET v_store_id = NULLIF(p_STORE_ID, 0);

  IF EXISTS(
    SELECT 1
    FROM product_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND PRODUCT_CD = v_product_cd
      AND IFNULL(ISDEL, '0') != '1'
      AND ((p_PRODUCT_ID IS NULL OR p_PRODUCT_ID = 0) OR PRODUCT_ID <> p_PRODUCT_ID)
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PRODUCT_CD already exists';
  END IF;

  IF p_PRODUCT_ID IS NULL OR p_PRODUCT_ID = 0 THEN
    INSERT INTO product_info (
      COMPANY_CD,
      PRODUCT_CD,
      PRODUCT_NM_VIET,
      PRODUCT_NM_ENG,
      PRODUCT_NM_KOR,
      PRODUCT_NM_CHINA,
      PRODUCT_KIND_ID,
      UNIT_ID,
      STORE_ID,
      DIVISION,
      SUMMARY,
      ISDEL,
      CREATE_BY,
      CREATE_AT,
      UPDATE_BY,
      UPDATE_AT
    ) VALUES (
      p_COMPANY_CD,
      v_product_cd,
      p_PRODUCT_NM_VIET,
      p_PRODUCT_NM_ENG,
      p_PRODUCT_NM_KOR,
      p_PRODUCT_NM_CHINA,
      v_product_kind_id,
      v_unit_id,
      v_store_id,
      p_DIVISION,
      p_SUMMARY,
      '0',
      p_USERID,
      DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s'),
      p_USERID,
      DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')
    );
    SELECT LAST_INSERT_ID() AS PRODUCT_ID;
  ELSE
    UPDATE product_info
    SET PRODUCT_CD = v_product_cd,
        PRODUCT_NM_VIET = p_PRODUCT_NM_VIET,
        PRODUCT_NM_ENG = p_PRODUCT_NM_ENG,
        PRODUCT_NM_KOR = p_PRODUCT_NM_KOR,
        PRODUCT_NM_CHINA = p_PRODUCT_NM_CHINA,
        PRODUCT_KIND_ID = v_product_kind_id,
        UNIT_ID = v_unit_id,
        STORE_ID = v_store_id,
        DIVISION = p_DIVISION,
        SUMMARY = p_SUMMARY,
        UPDATE_BY = p_USERID,
        UPDATE_AT = DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')
    WHERE COMPANY_CD = p_COMPANY_CD
      AND PRODUCT_ID = p_PRODUCT_ID;
    SELECT p_PRODUCT_ID AS PRODUCT_ID;
  END IF;
END//
DELIMITER ;


