        UPDATE_AT = DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s'),
        ISDEL = COALESCE(p_ISDEL, '0')
    WHERE COMPANY_CD = p_COMPANY_CD
      AND UNIT_ID = p_UNIT_ID;
    SELECT p_UNIT_ID AS UNIT_ID;
  END IF;
END//
DELIMITER ;


