-- Dumping structure for procedure am_web_001.setSysCodeSequence
DROP PROCEDURE IF EXISTS `setSysCodeSequence`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setSysCodeSequence`(
    IN p_ID BIGINT,
    IN p_COMPANY_CD VARCHAR(20),
    IN p_OBJECT_TYPE VARCHAR(50),
    IN p_MENU_CODE VARCHAR(80),
    IN p_CODE_FIELD VARCHAR(80),
    IN p_PREFIX VARCHAR(30),
    IN p_SUFFIX VARCHAR(30),
    IN p_CODE_PATTERN VARCHAR(100),
    IN p_CURRENT_NO BIGINT,
    IN p_NUMBER_LENGTH INT,
    IN p_RESET_TYPE VARCHAR(20),
    IN p_RESET_KEY VARCHAR(20),
    IN p_IS_USE CHAR(1)
)
BEGIN
    DECLARE v_CODE_PATTERN VARCHAR(100) DEFAULT '{PREFIX}{NO}{SUFFIX}';
    DECLARE v_IS_USE CHAR(1) DEFAULT '1';

    SET v_CODE_PATTERN = TRIM(IFNULL(p_CODE_PATTERN, ''));
    IF v_CODE_PATTERN = '' OR LOCATE('{NO}', UPPER(v_CODE_PATTERN)) = 0 THEN
        SET v_CODE_PATTERN = '{PREFIX}{NO}{SUFFIX}';
    END IF;

    SET v_IS_USE = IF(TRIM(IFNULL(p_IS_USE, '1')) = '1', '1', '0');

    IF p_ID IS NULL OR p_ID = 0 THEN
        INSERT INTO sys_code_sequence(
            COMPANY_CD,
            OBJECT_TYPE,
            MENU_CODE,
            CODE_FIELD,
            PREFIX,
            SUFFIX,
            CODE_PATTERN,
            CURRENT_NO,
            NUMBER_LENGTH,
            RESET_TYPE,
            RESET_KEY,
            IS_USE,
            CREATE_AT,
            UPDATE_AT
        ) VALUES (
            p_COMPANY_CD,
            p_OBJECT_TYPE,
            UPPER(TRIM(IFNULL(p_MENU_CODE, ''))),
            UPPER(TRIM(IFNULL(p_CODE_FIELD, ''))),
            IFNULL(p_PREFIX, ''),
            IFNULL(p_SUFFIX, ''),
            v_CODE_PATTERN,
            IFNULL(p_CURRENT_NO, 0),
            IFNULL(p_NUMBER_LENGTH, 6),
            IFNULL(p_RESET_TYPE, 'NONE'),
            IFNULL(p_RESET_KEY, ''),
            v_IS_USE,
            NOW(),
            NOW()
        );
    ELSE
        UPDATE sys_code_sequence
        SET OBJECT_TYPE = p_OBJECT_TYPE,
            MENU_CODE = UPPER(TRIM(IFNULL(p_MENU_CODE, ''))),
            CODE_FIELD = UPPER(TRIM(IFNULL(p_CODE_FIELD, ''))),
            PREFIX = IFNULL(p_PREFIX, ''),
            SUFFIX = IFNULL(p_SUFFIX, ''),
            CODE_PATTERN = v_CODE_PATTERN,
            CURRENT_NO = IFNULL(p_CURRENT_NO, 0),
            NUMBER_LENGTH = IFNULL(p_NUMBER_LENGTH, 6),
            RESET_TYPE = IFNULL(p_RESET_TYPE, 'NONE'),
            RESET_KEY = IFNULL(p_RESET_KEY, ''),
            IS_USE = v_IS_USE,
            UPDATE_AT = NOW()
        WHERE COMPANY_CD = p_COMPANY_CD
          AND ID = p_ID;
    END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.setSysNotification
DROP PROCEDURE IF EXISTS `setSysNotification`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `setSysNotification`(
    IN p_ID BIGINT,
    IN p_COMPANY_CD VARCHAR(20),
    IN p_USER_ID VARCHAR(50),
    IN p_ROLE_CD VARCHAR(50),
    IN p_NOTIFICATION_TYPE VARCHAR(50),
    IN p_SOURCE_MODULE VARCHAR(50),
    IN p_SOURCE_ID VARCHAR(100),
    IN p_TITLE VARCHAR(255),
    IN p_MESSAGE VARCHAR(1000),
    IN p_PRIORITY VARCHAR(20),
    IN p_ACTION_URL VARCHAR(500),
    IN p_IS_READ CHAR(1),
    IN p_EXPIRED_AT DATETIME,
    IN p_CREATE_BY VARCHAR(50)
)
BEGIN
    DECLARE v_title VARCHAR(255);
    DECLARE v_type VARCHAR(50);
    DECLARE v_priority VARCHAR(20);
    DECLARE v_is_read CHAR(1);

    SET v_title = TRIM(COALESCE(p_TITLE, ''));
    SET v_type = TRIM(COALESCE(p_NOTIFICATION_TYPE, ''));
    SET v_priority = UPPER(TRIM(COALESCE(p_PRIORITY, 'MEDIUM')));
    SET v_is_read = CASE WHEN UPPER(TRIM(COALESCE(p_IS_READ, 'N'))) = 'Y' THEN 'Y' ELSE 'N' END;

    IF v_title = '' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'TITLE is required';
    END IF;

    IF v_type = '' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NOTIFICATION_TYPE is required';
    END IF;

    IF v_priority NOT IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL') THEN
        SET v_priority = 'MEDIUM';
    END IF;

    IF p_ID IS NULL OR p_ID <= 0 THEN
        INSERT INTO sys_notification (
            COMPANY_CD,
            USER_ID,
            ROLE_CD,
            NOTIFICATION_TYPE,
            SOURCE_MODULE,
            SOURCE_ID,
            TITLE,
            MESSAGE,
            PRIORITY,
            ACTION_URL,
            IS_READ,
            READ_AT,
            CREATE_BY,
            CREATE_AT,
            EXPIRED_AT
        ) VALUES (
            p_COMPANY_CD,
            NULLIF(TRIM(p_USER_ID), ''),
            NULLIF(TRIM(p_ROLE_CD), ''),
            v_type,
            NULLIF(TRIM(p_SOURCE_MODULE), ''),
            NULLIF(TRIM(p_SOURCE_ID), ''),
            v_title,
            NULLIF(TRIM(p_MESSAGE), ''),
            v_priority,
            NULLIF(TRIM(p_ACTION_URL), ''),
            v_is_read,
            CASE WHEN v_is_read = 'Y' THEN NOW() ELSE NULL END,
            NULLIF(TRIM(p_CREATE_BY), ''),
            NOW(),
            p_EXPIRED_AT
        );

        SELECT LAST_INSERT_ID() AS ID;
    ELSE
        UPDATE sys_notification
        SET
            USER_ID = NULLIF(TRIM(p_USER_ID), ''),
            ROLE_CD = NULLIF(TRIM(p_ROLE_CD), ''),
            NOTIFICATION_TYPE = v_type,
            SOURCE_MODULE = NULLIF(TRIM(p_SOURCE_MODULE), ''),
            SOURCE_ID = NULLIF(TRIM(p_SOURCE_ID), ''),
            TITLE = v_title,
            MESSAGE = NULLIF(TRIM(p_MESSAGE), ''),
            PRIORITY = v_priority,
            ACTION_URL = NULLIF(TRIM(p_ACTION_URL), ''),
            IS_READ = v_is_read,
            READ_AT = CASE
                WHEN v_is_read = 'Y' AND READ_AT IS NULL THEN NOW()
                WHEN v_is_read = 'N' THEN NULL
                ELSE READ_AT
            END,
            EXPIRED_AT = p_EXPIRED_AT
        WHERE ID = p_ID
          AND COMPANY_CD = p_COMPANY_CD;

        SELECT p_ID AS ID;
    END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_chit_clearing_debt_get
DROP PROCEDURE IF EXISTS `sp_chit_clearing_debt_get`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_chit_clearing_debt_get`(
    IN `p_COMPANY_CD` varchar(20),
    IN `p_DEBT_TYPE` char(1),
    IN `p_FROM_YMD` varchar(8),
    IN `p_TO_YMD` varchar(8),
    IN `p_CUSTOMER_IDS` varchar(5000),
    IN `p_FC_TYPE` varchar(20)
)
BEGIN

	
	SET @sWhereFcType = "",@sWhereAmount=" AND PAYAMOUNT > 0 ";
	IF(p_FC_TYPE != "") THEN
		SET @sPosition = POSITION("|" IN p_FC_TYPE);
		IF(@sPosition > 0) THEN
			SET @DCWayCode = SUBSTR(p_FC_TYPE,1,@sPosition-1);
			SET p_FC_TYPE = SUBSTR(p_FC_TYPE,@sPosition+1,3);	
			SET @sWhereAmount = " AND PAYAMOUNT > 0 ";	
			IF(@DCWayCode = 1) THEN
				SET @sWhereFcType = CONCAT(" AND  IFNULL(FC_TYPE,'') = '",p_FC_TYPE,"' ");	
				SET @sWhereAmount = " AND PAYAMOUNT_FC > 0 ";							
			ELSE IF(@DCWayCode = 2) THEN
				SET @sWhereFcType = CONCAT("  AND (IFNULL(FC_TYPE,'') = '' OR IFNULL(FC_TYPE,'') = '",p_FC_TYPE,"') ");
				SET @sWhereAmount = " AND (PAYAMOUNT > 0 OR PAYAMOUNT_FC > 0) ";		
			END IF;
			END IF;
		END IF;
	END IF;
	-- Accept ALL or a comma-separated list of numeric CUSTOMER_ID values.
	IF p_CUSTOMER_IDS IS NULL OR TRIM(p_CUSTOMER_IDS) = '' THEN
		SET p_CUSTOMER_IDS = 'ALL';
	END IF;
	SET p_CUSTOMER_IDS = TRIM(p_CUSTOMER_IDS);
	IF UPPER(p_CUSTOMER_IDS) = 'ALL' THEN SET p_CUSTOMER_IDS = 'ALL'; END IF;
	IF UPPER(p_CUSTOMER_IDS) <> 'ALL' AND
	   p_CUSTOMER_IDS NOT REGEXP '^[0-9]+(,[0-9]+)*$' THEN
		SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid customer IDs';
	END IF;
	

	-- Match either clearing voucher date. NULL/empty FROM means strictly before TO.
	IF NULLIF(TRIM(p_FROM_YMD), '') IS NULL THEN
		SET @ClearingDateCondition = CONCAT(
		    '((C.CHIT_YMD < ', QUOTE(p_TO_YMD), ') OR (D.CHIT_YMD < ', QUOTE(p_TO_YMD), '))');
	ELSE
		SET @ClearingDateCondition = CONCAT(
		    '((C.CHIT_YMD >= ', QUOTE(p_FROM_YMD), ' AND C.CHIT_YMD <= ', QUOTE(p_TO_YMD),
		    ') OR (D.CHIT_YMD >= ', QUOTE(p_FROM_YMD), ' AND D.CHIT_YMD <= ', QUOTE(p_TO_YMD), '))');
	END IF;

SET @V_SQL = CONCAT("
		SELECT 
				CUS1.CUSTOMER_ID AS CUSTOMER_ID,
				IFNULL(CUS1.CUSTOMER_CD,'') AS CUSTOMER_CD,
				IFNULL(CUS1.CUSTOMER_NM_VIET,'') AS CUSTOMER_NM_VIET,
				IFNULL(CUS1.CUSTOMER_NM_ENG,'') AS CUSTOMER_NM_ENG,
				IFNULL(CUS1.CUSTOMER_NM_KOR,'') AS CUSTOMER_NM_KOR,
				
				CHITPAYMENT_ID,
				CHITCOLLECT_ID,
				CHIT_ID_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN -1 ELSE CHIT_TYPE_PAY END CHIT_TYPE_PAY,
				'' AS TYPE_CHIT_PAY_TEXT,
				CHIT_YMD_PAY,	
				CHIT_NO_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN 'Số dư đầu kỳ' ELSE DESCRIPTION_VIET_PAY END AS DESCRIPTION_VIET_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN 'Openning balance' ELSE DESCRIPTION_ENG_PAY END AS DESCRIPTION_ENG_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN '기초잔액' ELSE DESCRIPTION_KOR_PAY END AS DESCRIPTION_KOR_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN '期初余额' ELSE DESCRIPTION_CHINA_PAY END AS DESCRIPTION_CHINA_PAY,
				
				CHIT_ID_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN -1 ELSE CHIT_TYPE_DEBT END CHIT_TYPE_DEBT,
				'' AS TYPE_CHIT_DEBT_TEXT,
				CHIT_YMD_DEBT,
				CHIT_NO_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN 'Số dư đầu kỳ' ELSE DESCRIPTION_VIET_DEBT END AS DESCRIPTION_VIET_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN 'Openning balance' ELSE DESCRIPTION_ENG_DEBT END AS DESCRIPTION_ENG_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN '기초잔액' ELSE DESCRIPTION_KOR_DEBT END AS DESCRIPTION_KOR_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN '期初余额' ELSE DESCRIPTION_CHINA_DEBT END AS DESCRIPTION_CHINA_DEBT,
				
				PAYAMOUNT,
				PAYAMOUNT_FC
		FROM (
		SELECT 
				P.CHITPAYMENT_ID AS CHITPAYMENT_ID,
				(SELECT CASE WHEN COUNT(*) = 1 THEN MIN(T.CHITCOLLECT_ID) ELSE NULL END
				   FROM chit_collect T WHERE T.COMPANY_CD=P.COMPANY_CD AND T.CUSTOMER_ID=P.CUSTOMER_ID
				     AND T.IS_DEBT_CLEARING='1' AND COALESCE(T.ISDEL,'0')<>'1'
				     AND T.RECEIVABLES_CHIT_ID=P.PAY_CHIT_ID AND T.COLLECT_CHIT_ID=P.DEBIT_CHIT_ID
				     AND T.COLLECTAMOUNT=P.PAYAMOUNT AND T.COLLECTAMOUNT_FC=P.PAYAMOUNT_FC) AS CHITCOLLECT_ID,
				P.DEBIT_CHIT_ID AS CHIT_ID_DEBT,
				D.CHIT_TYPE AS CHIT_TYPE_DEBT,
				D.CHIT_NO AS CHIT_NO_DEBT,
				D.CHIT_YMD AS CHIT_YMD_DEBT ,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'VIET' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_VIET_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'ENG' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_ENG_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_KOR_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA_PAY,
				P.PAY_CHIT_ID AS CHIT_ID_PAY,
				C.CHIT_TYPE AS CHIT_TYPE_PAY,
				C.CHIT_NO AS CHIT_NO_PAY,
				C.CHIT_YMD AS CHIT_YMD_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'VIET' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_VIET_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'ENG' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_ENG_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_KOR_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA_DEBT,
				
				IFNULL(SUM(P.PAYAMOUNT),0.0)as PAYAMOUNT,
				IFNULL(SUM(P.PAYAMOUNT_FC),0.0) as PAYAMOUNT_FC,
				P.CUSTOMER_ID
			FROM chit_payment P 
			
			LEFT JOIN chitinfo C ON P.PAY_CHIT_ID = C.CHIT_ID AND IFNULL(C.ISDEL,'') != '1' AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
			LEFT JOIN chitinfo D ON P.DEBIT_CHIT_ID = D.CHIT_ID AND IFNULL(D.ISDEL,'') != '1' AND D.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
			WHERE 
				P.IS_DEBT_CLEARING = 1 AND EXISTS (SELECT 1 FROM chit_collect T WHERE T.RECEIVABLES_CHIT_ID = P.PAY_CHIT_ID AND T.COLLECT_CHIT_ID = P.DEBIT_CHIT_ID AND T.CUSTOMER_ID = P.CUSTOMER_ID AND T.COLLECTAMOUNT = P.PAYAMOUNT AND T.COLLECTAMOUNT_FC = P.PAYAMOUNT_FC AND T.IS_DEBT_CLEARING = '1' AND IFNULL(T.ISDEL,'0') <> '1' AND T.COMPANY_CD = P.COMPANY_CD)
				AND IFNULL(P.ISDEL,'') != '1'
				AND (
						(	
							",@ClearingDateCondition," AND 
							EXISTS(SELECT * FROM chitdetailinfo E INNER JOIN chitdetailinfo_ext EX ON EX.CHITDETAIL_ID = E.CHITDETAIL_ID AND EX.COMPANY_CD = E.COMPANY_CD WHERE C.CHIT_ID = E.CHIT_ID AND IFNULL(E.ISDEL,'') != '1' 
									AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(IF(C.CHIT_TYPE = 5, EX.CUSTOMER_OWN_ID, EX.CUSTOMER_ID) AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
									AND E.DEBIT LIKE '131%' ",@sWhereFcType," 
							) AND
							EXISTS(SELECT * FROM chitdetailinfo F INNER JOIN chitdetailinfo_ext FX ON FX.CHITDETAIL_ID = F.CHITDETAIL_ID AND FX.COMPANY_CD = F.COMPANY_CD WHERE D.CHIT_ID = F.CHIT_ID AND IFNULL(F.ISDEL,'') != '1' 
									AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(IF(D.CHIT_TYPE = 5, FX.CUSTOMER_OWN_ID, FX.CUSTOMER_ID) AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
									AND F.CREDIT LIKE '331%' ",@sWhereFcType,"    
							)
						)
				
						OR P.PAY_CHIT_ID IN (-131,-331) OR P.DEBIT_CHIT_ID IN (-131,-331)
				)
				AND P.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
				AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(P.CUSTOMER_ID AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
			GROUP BY 	
				P.CHITPAYMENT_ID,
				P.PAY_CHIT_ID,
				P.DEBIT_CHIT_ID,
				P.CUSTOMER_ID
			) A 
			LEFT JOIN customer_info CUS1 ON A.CUSTOMER_ID = CUS1.CUSTOMER_ID AND IFNULL(CUS1.ISDEL,'0') != '1' AND CUS1.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
			WHERE 
				CUS1.CUSTOMER_ID IS NOT NULL
				AND(IFNULL(CHIT_NO_PAY,'') != '' OR CHIT_ID_PAY < 0) 
				AND (IFNULL(CHIT_NO_DEBT,'') != '' OR CHIT_ID_DEBT < 0) 
				",@sWhereAmount,"
			ORDER BY 
				CUS1.CUSTOMER_ID,
				CHIT_YMD_PAY,
				CHIT_NO_PAY,
				CHIT_TYPE_PAY,
				CHIT_YMD_DEBT,
				CHIT_NO_DEBT,
				CHIT_TYPE_DEBT
			
			");
				
		PREPARE STMT FROM @V_SQL;
		EXECUTE STMT;
		DEALLOCATE PREPARE STMT;

END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_chit_clearing_get
DROP PROCEDURE IF EXISTS `sp_chit_clearing_get`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_chit_clearing_get`(
    IN `p_COMPANY_CD` varchar(20),
    IN `p_DEBT_TYPE` char(1),
    IN `p_FROM_YMD` varchar(8),
    IN `p_TO_YMD` varchar(8),
    IN `p_CUSTOMER_IDS` varchar(5000),
    IN `p_FC_TYPE` varchar(20),
    IN `p_ACC_CD_1` varchar(20),
    IN `p_ACC_CD_2` varchar(20)
)
BEGIN
	SET @DCWayCode = NULL;
	SET @sWhereFcType = "", @sHaving = " HAVING REMAINAMOUNT > 0 ";
	IF(p_FC_TYPE != "") THEN
		SET @sPosition = POSITION("|" IN p_FC_TYPE);
		IF(@sPosition > 0) THEN
			SET @DCWayCode = SUBSTR(p_FC_TYPE,1,@sPosition-1);
			SET p_FC_TYPE = SUBSTR(p_FC_TYPE,@sPosition+1,3);
			SET @sHaving = CONCAT(" HAVING REMAINAMOUNT > 0 ");	
			IF(@DCWayCode = 1) THEN
				SET @sHaving = CONCAT(" HAVING REMAINAMOUNT_FC > 0 ");
				SET @sWhereFcType = CONCAT(" AND IFNULL(A.FC_TYPE,'') = '",p_FC_TYPE,"' ");							
			ELSE IF(@DCWayCode = 2) THEN
				SET @sHaving = CONCAT(" HAVING REMAINAMOUNT > 0 OR REMAINAMOUNT_FC > 0 ");
				SET @sWhereFcType = CONCAT(" AND (IFNULL(A.FC_TYPE,'') = '' OR IFNULL(A.FC_TYPE,'') = '",p_FC_TYPE,"') ");	
			END IF;
			END IF;
		END IF;
	END IF;

	-- Opening balances now store one DEBIT_FC/CREDIT_FC per row with FC_TYPE.
	-- Preserve legacy unfiltered behaviour: USD is the default foreign display.
	SET @OpenFCType = CASE WHEN p_FC_TYPE IN ('USD','EUR','JPY','KRW','CNY')
	                       THEN p_FC_TYPE ELSE 'USD' END;
	SET @sWhereOpenFcType = '';
	IF NULLIF(TRIM(p_FC_TYPE), '') IS NOT NULL THEN
		IF @DCWayCode = '2' THEN
			SET @sWhereOpenFcType = CONCAT(' AND A.FC_TYPE IN (', QUOTE('VND'), ', ', QUOTE(p_FC_TYPE), ') ');
		ELSE
			SET @sWhereOpenFcType = CONCAT(' AND A.FC_TYPE = ', QUOTE(p_FC_TYPE), ' ');
		END IF;
	END IF;
	-- Accept ALL or a comma-separated list of numeric CUSTOMER_ID values.
	IF p_CUSTOMER_IDS IS NULL OR TRIM(p_CUSTOMER_IDS) = '' THEN
		SET p_CUSTOMER_IDS = 'ALL';
	END IF;
	SET p_CUSTOMER_IDS = TRIM(p_CUSTOMER_IDS);
	IF UPPER(p_CUSTOMER_IDS) = 'ALL' THEN SET p_CUSTOMER_IDS = 'ALL'; END IF;
	IF UPPER(p_CUSTOMER_IDS) <> 'ALL' AND
	   p_CUSTOMER_IDS NOT REGEXP '^[0-9]+(,[0-9]+)*$' THEN
		SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid customer IDs';
	END IF;
	
	-- Empty/NULL FROM: strictly earlier than TO. Explicit FROM: inclusive range.
	IF NULLIF(TRIM(p_FROM_YMD), '') IS NULL THEN
		SET @QueryYMD = CONCAT(' AND A.CHIT_YMD < ', QUOTE(p_TO_YMD), ' ');
	ELSE
		SET @QueryYMD = CONCAT(' AND A.CHIT_YMD >= ', QUOTE(p_FROM_YMD),
		                       ' AND A.CHIT_YMD <= ', QUOTE(p_TO_YMD), ' ');
	END IF;
	
/*Collect*/
	SET @V_SQL = CONCAT("
	SELECT 
			CUS1.CUSTOMER_ID AS CUSTOMER_ID,
			IFNULL(CUS1.CUSTOMER_CD,'') AS CUSTOMER_CD,
			IFNULL(CUS1.CUSTOMER_NM_VIET,'') AS CUSTOMER_NM_VIET,
			IFNULL(CUS1.CUSTOMER_NM_ENG,'') AS CUSTOMER_NM_ENG,
			IFNULL(CUS1.CUSTOMER_NM_KOR,'') AS CUSTOMER_NM_KOR,
			IFNULL(CUS1.CUSTOMER_NM_CHINA,'') AS CUSTOMER_NM_CHINA,
			PAY_ID,
			CHIT_ID,
			CHIT_TYPE,
			CHIT_NO,
			CHIT_YMD,
			VAT_CHIT_NO,
			VAT_YMD,
			DESCRIPTION_VIET,
			DESCRIPTION_ENG,
			DESCRIPTION_KOR,
			DESCRIPTION_CHINA,
			DAY_OF_PAYMENT,
			TIME_FOR_PAYMENT,
			AMOUNT,
			FC_AMOUNT,
			REMAINAMOUNT,
			REMAINAMOUNT_FC,
			PAYAMOUNT,
			PAYAMOUNT_FC
	FROM (			
		SELECT 
				COALESCE(MIN(P.CHITCOLLECT_ID),0) AS PAY_ID,
				-131 AS CHIT_ID,
				'-1' AS CHIT_TYPE,
				'' AS CHIT_NO,
				'' AS CHIT_YMD,
				A.CUSTOMER_ID,
				'' AS VAT_CHIT_NO,
				'' AS VAT_YMD,
				'Số dư đầu kỳ' AS DESCRIPTION_VIET,
				'Openning balance' AS DESCRIPTION_ENG, 	
				'기초잔액' AS DESCRIPTION_KOR,
				'期初余额' AS DESCRIPTION_CHINA,
				'' AS DAY_OF_PAYMENT,
				'' AS TIME_FOR_PAYMENT,
				AMOUNT,
				FC_AMOUNT,
				IFNULL(A.AMOUNT - IFNULL(SUM(P.COLLECTAMOUNT),0.0),0.0) as REMAINAMOUNT,
				IFNULL(A.FC_AMOUNT - IFNULL(SUM(P.COLLECTAMOUNT_FC),0.0),0.0) as REMAINAMOUNT_FC,
				0.0 AS PAYAMOUNT,
				0.0 AS PAYAMOUNT_FC
			FROM (
				SELECT 
					A.CUSTOMER_ID,
					IFNULL(SUM(A.DEBIT),0.0) AS AMOUNT,
					IFNULL(SUM(CASE WHEN A.FC_TYPE = @OpenFCType THEN A.DEBIT_FC ELSE 0 END),0.0) AS FC_AMOUNT
					FROM before_states_customer A
					WHERE A.ACC_CD like '",p_ACC_CD_1,"%' 
					AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(A.CUSTOMER_ID AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
					AND IFNULL(A.ISDEL,'') !=1
					",@sWhereOpenFcType,"
					AND A.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
					GROUP BY A.CUSTOMER_ID
				) A
			LEFT JOIN chit_collect P ON ifnull(P.ISDEL,'') != '1' AND P.RECEIVABLES_CHIT_ID = -131 AND P.CUSTOMER_ID = A.CUSTOMER_ID AND P.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," 
			GROUP BY A.CUSTOMER_ID,AMOUNT,FC_AMOUNT
			",@sHaving," 

		UNION ALL
		SELECT 
			COALESCE(MIN(C.CHITCOLLECT_ID),0) AS PAY_ID,
			CHIT_ID,
			CHIT_TYPE,
			CHIT_NO,
			CHIT_YMD,
			F.CUSTOMER_ID,
			VAT_CHIT_NO,
			VAT_YMD,
			DESCRIPTION_VIET,
			DESCRIPTION_ENG,
			DESCRIPTION_KOR,
			DESCRIPTION_CHINA,
			DAY_OF_PAYMENT,
			TIME_FOR_PAYMENT,
			AMOUNT,
			FC_AMOUNT,
			AMOUNT -	IFNULL(SUM(C.COLLECTAMOUNT),0.0) as REMAINAMOUNT,
			FC_AMOUNT - IFNULL(SUM(C.COLLECTAMOUNT_FC),0.0) as REMAINAMOUNT_FC,
			0.0 AS PAYAMOUNT,
			0.0 AS PAYAMOUNT_FC
	FROM(
		SELECT 
					B.CHIT_ID,

					B.CHIT_TYPE,
					B.CHIT_NO,
					A.CHIT_YMD,
					IF(B.CHIT_TYPE = 5, AX.CUSTOMER_OWN_ID, AX.CUSTOMER_ID) AS CUSTOMER_ID,
					IFNULL((SELECT V.VAT_CHIT_NO FROM chitdetailinfo C INNER JOIN chitdetailinfo_vat V ON V.COMPANY_CD = C.COMPANY_CD AND V.CHITDETAIL_ID = C.CHITDETAIL_ID WHERE IFNULL(C.ISDEL,'0') <> '1' AND IFNULL(V.VAT_CHIT_NO,'') <> '' AND C.CHIT_ID = A.CHIT_ID AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," ORDER BY C.CHITDETAIL_ID LIMIT 1),'') AS VAT_CHIT_NO,
					IFNULL((SELECT V.VAT_YMD FROM chitdetailinfo C INNER JOIN chitdetailinfo_vat V ON V.COMPANY_CD = C.COMPANY_CD AND V.CHITDETAIL_ID = C.CHITDETAIL_ID WHERE IFNULL(C.ISDEL,'0') <> '1' AND IFNULL(V.VAT_CHIT_NO,'') <> '' AND C.CHIT_ID = A.CHIT_ID AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," ORDER BY C.CHITDETAIL_ID LIMIT 1),'') AS VAT_YMD,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'VIET' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_VIET,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'ENG' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_ENG,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_KOR,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA,
					IFNULL(BX.DAY_OF_PAYMENT,'') AS DAY_OF_PAYMENT,
					IFNULL(BX.TIME_FOR_PAYMENT,'') AS TIME_FOR_PAYMENT,
					IFNULL(SUM(A.AMOUNT),0.0) AS AMOUNT,
					IFNULL(SUM(A.FC_AMOUNT),0.0) AS FC_AMOUNT
				FROM chitdetailinfo A
                    INNER JOIN chitdetailinfo_ext AX ON AX.CHITDETAIL_ID = A.CHITDETAIL_ID AND AX.COMPANY_CD = A.COMPANY_CD
					LEFT JOIN chitinfo B ON B.CHIT_ID = A.CHIT_ID AND (B.ISDEL IS NULL OR B.ISDEL != '1') AND B.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
                    LEFT JOIN chitinfo_ext BX ON BX.CHIT_ID = B.CHIT_ID AND BX.COMPANY_CD = B.COMPANY_CD
				WHERE  
					IFNULL(B.CHIT_NO,'')!=''				
					AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(IF(B.CHIT_TYPE = 5, AX.CUSTOMER_OWN_ID, AX.CUSTOMER_ID) AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
					",@QueryYMD,"
					AND A.DEBIT LIKE '",p_ACC_CD_1,"%' 
					AND IFNULL(A.ISDEL,'0') != '1' 
					",@sWhereFcType," 
					AND A.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
				GROUP BY 	
					B.CHIT_ID,
					B.CHIT_NO,
					A.CHIT_YMD,
					IF(B.CHIT_TYPE = 5, AX.CUSTOMER_OWN_ID, AX.CUSTOMER_ID)
	 ) F
	 	LEFT JOIN chit_collect C ON ifnull(C.ISDEL,'') != '1' AND C.RECEIVABLES_CHIT_ID = F.CHIT_ID AND F.CUSTOMER_ID = C.CUSTOMER_ID AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
	 	GROUP BY CHIT_ID,F.CUSTOMER_ID
	 ) A 
	 LEFT JOIN customer_info CUS1 ON A.CUSTOMER_ID = CUS1.CUSTOMER_ID AND IFNULL(CUS1.ISDEL,'0') != '1' AND CUS1.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
	 WHERE CUS1.CUSTOMER_ID IS NOT NULL
	 	",@sHaving,"
	 ORDER BY CHIT_YMD, CHIT_NO,TIME_FOR_PAYMENT;
		");
		PREPARE STMT FROM @V_SQL;
		EXECUTE STMT;
		DEALLOCATE PREPARE STMT;
	
	/*Payment*/
	SET @V_SQL = CONCAT("
				
	SELECT 
			CUS1.CUSTOMER_ID AS CUSTOMER_ID,
			IFNULL(CUS1.CUSTOMER_CD,'') AS CUSTOMER_CD,
			IFNULL(CUS1.CUSTOMER_NM_VIET,'') AS CUSTOMER_NM_VIET,
			IFNULL(CUS1.CUSTOMER_NM_ENG,'') AS CUSTOMER_NM_ENG,
			IFNULL(CUS1.CUSTOMER_NM_KOR,'') AS CUSTOMER_NM_KOR,
			IFNULL(CUS1.CUSTOMER_NM_CHINA,'') AS CUSTOMER_NM_CHINA,
			PAY_ID,
			CHIT_ID,
			CHIT_TYPE,
			CHIT_NO,
			CHIT_YMD,
			VAT_CHIT_NO,
			VAT_YMD,
			DESCRIPTION_VIET,
			DESCRIPTION_ENG,
			DESCRIPTION_KOR,
			DESCRIPTION_CHINA,
			DAY_OF_PAYMENT,
			TIME_FOR_PAYMENT,
			AMOUNT,
			FC_AMOUNT,
			REMAINAMOUNT,
			REMAINAMOUNT_FC,
			PAYAMOUNT,
			PAYAMOUNT_FC
	FROM (			
		SELECT 
				COALESCE(MIN(P.CHITPAYMENT_ID),0) AS PAY_ID,
				-331 AS CHIT_ID,
				'-1' AS CHIT_TYPE,
				'' AS CHIT_NO,
				'' AS CHIT_YMD,
				A.CUSTOMER_ID,
				'' AS VAT_CHIT_NO,
				'' AS VAT_YMD,
				'Số dư đầu kỳ' AS DESCRIPTION_VIET,
				'Openning balance' AS DESCRIPTION_ENG, 	
				'기초잔액' AS DESCRIPTION_KOR,
				'期初余额' AS DESCRIPTION_CHINA,
				'' AS DAY_OF_PAYMENT,
				'' AS TIME_FOR_PAYMENT,
				AMOUNT,
				FC_AMOUNT,
				IFNULL(A.AMOUNT - IFNULL(SUM(P.PAYAMOUNT),0.0),0.0) as REMAINAMOUNT,
				IFNULL(A.FC_AMOUNT - IFNULL(SUM(P.PAYAMOUNT_FC),0.0),0.0) as REMAINAMOUNT_FC,
				0.0 AS PAYAMOUNT,
				0.0 AS PAYAMOUNT_FC
			FROM (
				SELECT 
					A.CUSTOMER_ID,
					IFNULL(SUM(A.CREDIT),0.0) AS AMOUNT,
					IFNULL(SUM(CASE WHEN A.FC_TYPE = @OpenFCType THEN A.CREDIT_FC ELSE 0 END),0.0) AS FC_AMOUNT
					FROM before_states_customer A
					WHERE A.ACC_CD like '",p_ACC_CD_2,"%' 
				    AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(A.CUSTOMER_ID AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
					AND IFNULL(A.ISDEL,'') !=1
					",@sWhereOpenFcType,"
					AND A.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
					GROUP BY A.CUSTOMER_ID
				) A
			LEFT JOIN chit_payment P ON ifnull(P.ISDEL,'') != '1' AND P.DEBIT_CHIT_ID = -331 AND A.CUSTOMER_ID = P.CUSTOMER_ID AND P.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
			GROUP BY A.CUSTOMER_ID,AMOUNT,FC_AMOUNT
			",@sHaving," 

		UNION ALL
		SELECT 
			COALESCE(MIN(C.CHITPAYMENT_ID),0) AS PAY_ID,
			CHIT_ID,
			CHIT_TYPE,
			CHIT_NO,
			CHIT_YMD,
			F.CUSTOMER_ID,
			VAT_CHIT_NO,
			VAT_YMD,
			DESCRIPTION_VIET,
			DESCRIPTION_ENG,
			DESCRIPTION_KOR,
			DESCRIPTION_CHINA,
			DAY_OF_PAYMENT,
			TIME_FOR_PAYMENT,
			AMOUNT,
			FC_AMOUNT,
			AMOUNT -	IFNULL(SUM(C.PAYAMOUNT),0.0) as REMAINAMOUNT,
			FC_AMOUNT - IFNULL(SUM(C.PAYAMOUNT_FC),0.0) as REMAINAMOUNT_FC,
			0.0 AS PAYAMOUNT,
			0.0 AS PAYAMOUNT_FC
	FROM(
		SELECT 
					B.CHIT_ID,

					B.CHIT_TYPE,
					B.CHIT_NO,
					A.CHIT_YMD,
					IF(B.CHIT_TYPE = 5, AX.CUSTOMER_OWN_ID, AX.CUSTOMER_ID) AS CUSTOMER_ID,
					IFNULL((SELECT V.VAT_CHIT_NO FROM chitdetailinfo C INNER JOIN chitdetailinfo_vat V ON V.COMPANY_CD = C.COMPANY_CD AND V.CHITDETAIL_ID = C.CHITDETAIL_ID WHERE IFNULL(C.ISDEL,'0') <> '1' AND IFNULL(V.VAT_CHIT_NO,'') <> '' AND C.CHIT_ID = A.CHIT_ID AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," ORDER BY C.CHITDETAIL_ID LIMIT 1),'') AS VAT_CHIT_NO,
					IFNULL((SELECT V.VAT_YMD FROM chitdetailinfo C INNER JOIN chitdetailinfo_vat V ON V.COMPANY_CD = C.COMPANY_CD AND V.CHITDETAIL_ID = C.CHITDETAIL_ID WHERE IFNULL(C.ISDEL,'0') <> '1' AND IFNULL(V.VAT_CHIT_NO,'') <> '' AND C.CHIT_ID = A.CHIT_ID AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," ORDER BY C.CHITDETAIL_ID LIMIT 1),'') AS VAT_YMD,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'VIET' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_VIET,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'ENG' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_ENG,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_KOR,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA,
					IFNULL(BX.DAY_OF_PAYMENT,'') AS DAY_OF_PAYMENT,
					IFNULL(BX.TIME_FOR_PAYMENT,'') AS TIME_FOR_PAYMENT,
					IFNULL(SUM(A.AMOUNT),0.0) AS AMOUNT,
					IFNULL(SUM(A.FC_AMOUNT),0.0) AS FC_AMOUNT
				FROM chitdetailinfo A
                    INNER JOIN chitdetailinfo_ext AX ON AX.CHITDETAIL_ID = A.CHITDETAIL_ID AND AX.COMPANY_CD = A.COMPANY_CD
					LEFT JOIN chitinfo B ON B.CHIT_ID = A.CHIT_ID AND (B.ISDEL IS NULL OR B.ISDEL != '1') AND B.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
                    LEFT JOIN chitinfo_ext BX ON BX.CHIT_ID = B.CHIT_ID AND BX.COMPANY_CD = B.COMPANY_CD
				WHERE  
					IFNULL(B.CHIT_NO,'')!=''				
					AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(IF(B.CHIT_TYPE = 5, AX.CUSTOMER_OWN_ID, AX.CUSTOMER_ID) AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
					",@QueryYMD,"
					AND A.CREDIT LIKE '",p_ACC_CD_2,"%' 
					AND IFNULL(A.ISDEL,'0') != '1' 
					",@sWhereFcType," 
					AND A.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
				GROUP BY 	
					B.CHIT_ID,
					B.CHIT_NO,
					A.CHIT_YMD,
					IF(B.CHIT_TYPE = 5, AX.CUSTOMER_OWN_ID, AX.CUSTOMER_ID)
	 ) F
	 	LEFT JOIN chit_payment C ON ifnull(C.ISDEL,'') != '1' AND C.DEBIT_CHIT_ID = F.CHIT_ID AND F.CUSTOMER_ID = C.CUSTOMER_ID AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
	 	GROUP BY CHIT_ID,F.CUSTOMER_ID
	 ) A 
	  LEFT JOIN customer_info CUS1 ON A.CUSTOMER_ID = CUS1.CUSTOMER_ID AND IFNULL(CUS1.ISDEL,'0') != '1' AND CUS1.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
	 WHERE CUS1.CUSTOMER_ID IS NOT NULL
	 	",@sHaving,"
	 ORDER BY CHIT_YMD, CHIT_NO,TIME_FOR_PAYMENT;
		");
		PREPARE STMT FROM @V_SQL;
		EXECUTE STMT;
		DEALLOCATE PREPARE STMT;
		
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_chit_clearing_upsert
DROP PROCEDURE IF EXISTS `sp_chit_clearing_upsert`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_chit_clearing_upsert`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHITPAYMENT_ID BIGINT,
    IN p_CHITCOLLECT_ID BIGINT,
    IN p_RECEIVABLES_CHIT_ID BIGINT,
    IN p_PAYABLE_CHIT_ID BIGINT,
    IN p_AMOUNT DECIMAL(18,2),
    IN p_AMOUNT_FC DECIMAL(18,2),
    IN p_CUSTOMER_ID BIGINT,
    IN p_FC_TYPE VARCHAR(3),
    IN p_USERID VARCHAR(50)
)
BEGIN
    DECLARE v_lock_name VARCHAR(64);
    DECLARE v_got_lock INT DEFAULT 0;
    DECLARE v_pay_count INT DEFAULT 0;
    DECLARE v_collect_count INT DEFAULT 0;
    DECLARE v_payment_id BIGINT DEFAULT 0;
    DECLARE v_collect_id BIGINT DEFAULT 0;
    DECLARE v_existing_pay_id BIGINT DEFAULT 0;
    DECLARE v_existing_collect_id BIGINT DEFAULT 0;
    DECLARE v_p_amount DECIMAL(18,2) DEFAULT 0;
    DECLARE v_p_fc DECIMAL(18,2) DEFAULT 0;
    DECLARE v_c_amount DECIMAL(18,2) DEFAULT 0;
    DECLARE v_c_fc DECIMAL(18,2) DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
       ROLLBACK;
       IF v_got_lock=1 THEN DO RELEASE_LOCK(v_lock_name); END IF;
       RESIGNAL;
    END;
    IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD)='' THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Company required';
    END IF;
    IF p_RECEIVABLES_CHIT_ID IS NULL OR
       NOT (p_RECEIVABLES_CHIT_ID>0 OR p_RECEIVABLES_CHIT_ID=-131) OR
       p_PAYABLE_CHIT_ID IS NULL OR
       NOT (p_PAYABLE_CHIT_ID>0 OR p_PAYABLE_CHIT_ID=-331) THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid 131/331 CHIT_ID pair';
    END IF;
    SET v_lock_name=CONCAT('amnote_debt_',MD5(p_COMPANY_CD));
    SELECT GET_LOCK(v_lock_name,10) INTO v_got_lock;
    IF COALESCE(v_got_lock,0)<>1 THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Debt allocation busy; retry';
    END IF;
    START TRANSACTION;
    -- Existing mirrored rows must be present together and have identical values.
    SELECT COUNT(*),COALESCE(MAX(P.CHITPAYMENT_ID),0),
           COALESCE(MAX(P.PAYAMOUNT),0),COALESCE(MAX(P.PAYAMOUNT_FC),0)
      INTO v_pay_count,v_existing_pay_id,v_p_amount,v_p_fc
      FROM chit_payment P
     WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CUSTOMER_ID=p_CUSTOMER_ID
       AND P.IS_DEBT_CLEARING='1' AND COALESCE(P.ISDEL,'0')<>'1'
       AND P.PAY_CHIT_ID=p_RECEIVABLES_CHIT_ID
       AND P.DEBIT_CHIT_ID=p_PAYABLE_CHIT_ID;
    SELECT COUNT(*),COALESCE(MAX(P.CHITCOLLECT_ID),0),
           COALESCE(MAX(P.COLLECTAMOUNT),0),COALESCE(MAX(P.COLLECTAMOUNT_FC),0)
      INTO v_collect_count,v_existing_collect_id,v_c_amount,v_c_fc
      FROM chit_collect P
     WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CUSTOMER_ID=p_CUSTOMER_ID
       AND P.IS_DEBT_CLEARING='1' AND COALESCE(P.ISDEL,'0')<>'1'
       AND P.RECEIVABLES_CHIT_ID=p_RECEIVABLES_CHIT_ID
       AND P.COLLECT_CHIT_ID=p_PAYABLE_CHIT_ID;
    IF v_pay_count>1 OR v_collect_count>1 OR v_pay_count<>v_collect_count THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate clearing counterpart';
    END IF;
    IF v_pay_count=1 AND
       (v_p_amount<>v_c_amount OR v_p_fc<>v_c_fc OR
        v_p_amount<>COALESCE(p_AMOUNT,0) OR v_p_fc<>COALESCE(p_AMOUNT_FC,0)) THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing clearing amount differs; delete and recreate';
    END IF;
    IF COALESCE(p_CHITPAYMENT_ID,0)>0 AND p_CHITPAYMENT_ID<>v_existing_pay_id THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid payment record ID';
    END IF;
    IF COALESCE(p_CHITCOLLECT_ID,0)>0 AND p_CHITCOLLECT_ID<>v_existing_collect_id THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid collect record ID';
    END IF;
    -- Core routines have NO transaction of their own. Any failure rolls both back.
    CALL sp_chit_payment_write_core(p_COMPANY_CD,v_existing_pay_id,p_RECEIVABLES_CHIT_ID,
      p_PAYABLE_CHIT_ID,p_AMOUNT,p_AMOUNT_FC,'1',p_CUSTOMER_ID,p_FC_TYPE,p_USERID,v_payment_id);
    CALL sp_chit_collect_write_core(p_COMPANY_CD,v_existing_collect_id,p_PAYABLE_CHIT_ID,
      p_RECEIVABLES_CHIT_ID,p_AMOUNT,p_AMOUNT_FC,'1',p_CUSTOMER_ID,p_FC_TYPE,p_USERID,v_collect_id);
    COMMIT;
    DO RELEASE_LOCK(v_lock_name);
    SET v_got_lock=0;
    SELECT v_payment_id AS CHITPAYMENT_ID,v_collect_id AS CHITCOLLECT_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_chit_collect_delete
DROP PROCEDURE IF EXISTS `sp_chit_collect_delete`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_chit_collect_delete`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_RECORD_ID BIGINT,
    IN p_USERID VARCHAR(50)
)
BEGIN
    DECLARE v_lock_name VARCHAR(64);
    DECLARE v_got_lock INT DEFAULT 0;
    DECLARE v_count INT DEFAULT 0;
    DECLARE v_pair_count INT DEFAULT 0;
    DECLARE v_src_id BIGINT;
    DECLARE v_debt_id BIGINT;
    DECLARE v_customer_id BIGINT;
    DECLARE v_amount DECIMAL(18,2);
    DECLARE v_amount_fc DECIMAL(18,2);
    DECLARE v_clear CHAR(1);
    DECLARE v_pair_id BIGINT;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
       ROLLBACK;
       IF v_got_lock=1 THEN DO RELEASE_LOCK(v_lock_name); END IF;
       RESIGNAL;
    END;
    IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD)='' OR COALESCE(p_RECORD_ID,0)<=0 THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Company and positive allocation ID required';
    END IF;
    SET v_lock_name=CONCAT('amnote_debt_',MD5(p_COMPANY_CD));
    SELECT GET_LOCK(v_lock_name,10) INTO v_got_lock;
    IF COALESCE(v_got_lock,0)<>1 THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Debt allocation busy; retry';
    END IF;
    START TRANSACTION;
    SELECT COUNT(*) INTO v_count FROM `chit_collect` P
      WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CHITCOLLECT_ID=p_RECORD_ID
        AND COALESCE(P.ISDEL,'0')<>'1';
    IF v_count=1 THEN
       SELECT P.COLLECT_CHIT_ID,P.RECEIVABLES_CHIT_ID,P.CUSTOMER_ID,
              P.COLLECTAMOUNT,P.COLLECTAMOUNT_FC,P.IS_DEBT_CLEARING
       INTO v_src_id,v_debt_id,v_customer_id,v_amount,v_amount_fc,v_clear
       FROM `chit_collect` P
       WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CHITCOLLECT_ID=p_RECORD_ID FOR UPDATE;
       IF v_clear='1' THEN
          SELECT COUNT(*) INTO v_pair_count FROM `chit_collect` P
          WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CUSTOMER_ID=v_customer_id
            AND P.IS_DEBT_CLEARING='1' AND COALESCE(P.ISDEL,'0')<>'1'
            AND P.COLLECT_CHIT_ID=v_src_id AND P.RECEIVABLES_CHIT_ID=v_debt_id;
          IF v_pair_count<>1 THEN
             SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Ambiguous original clearing rows';
          END IF;
          SELECT COUNT(*),COALESCE(MAX(T.CHITPAYMENT_ID),0) INTO v_pair_count,v_pair_id
          FROM `chit_payment` T
          WHERE T.COMPANY_CD=p_COMPANY_CD AND T.CUSTOMER_ID=v_customer_id
            AND T.IS_DEBT_CLEARING='1' AND COALESCE(T.ISDEL,'0')<>'1'
            AND T.DEBIT_CHIT_ID=v_src_id AND T.PAY_CHIT_ID=v_debt_id
            AND T.PAYAMOUNT=v_amount AND T.PAYAMOUNT_FC=v_amount_fc;
          IF v_pair_count<>1 THEN
             SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Clearing pair missing/ambiguous; deletion aborted';
          END IF;
          -- Check for another active counterpart with different amount; do not conceal bad history.
          SELECT COUNT(*) INTO v_pair_count FROM `chit_payment` T
          WHERE T.COMPANY_CD=p_COMPANY_CD AND T.CUSTOMER_ID=v_customer_id
            AND T.IS_DEBT_CLEARING='1' AND COALESCE(T.ISDEL,'0')<>'1'
            AND T.DEBIT_CHIT_ID=v_src_id AND T.PAY_CHIT_ID=v_debt_id;
          IF v_pair_count<>1 THEN
             SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Ambiguous clearing mirror';
          END IF;
       END IF;
       UPDATE `chit_collect` SET ISDEL='1',UPDATE_BY=COALESCE(p_USERID,'')
        WHERE COMPANY_CD=p_COMPANY_CD AND CHITCOLLECT_ID=p_RECORD_ID AND COALESCE(ISDEL,'0')<>'1';
       IF v_clear='1' THEN
          UPDATE `chit_payment` SET ISDEL='1',UPDATE_BY=COALESCE(p_USERID,'')
           WHERE COMPANY_CD=p_COMPANY_CD AND CHITPAYMENT_ID=v_pair_id AND COALESCE(ISDEL,'0')<>'1';
       END IF;
    END IF;
    COMMIT;
    DO RELEASE_LOCK(v_lock_name);
    SET v_got_lock=0;
    SELECT v_count AS DELETED_COUNT;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_chit_collect_upsert
DROP PROCEDURE IF EXISTS `sp_chit_collect_upsert`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_chit_collect_upsert`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_RECORD_ID BIGINT,
    IN p_SOURCE_CHIT_ID BIGINT,
    IN p_DEBT_CHIT_ID BIGINT,
    IN p_AMOUNT DECIMAL(18,2),
    IN p_AMOUNT_FC DECIMAL(18,2),
    IN p_IS_DEBT_CLEARING CHAR(1),
    IN p_CUSTOMER_ID BIGINT,
    IN p_FC_TYPE VARCHAR(3),
    IN p_USERID VARCHAR(50)
)
BEGIN
    DECLARE v_lock_name VARCHAR(64);
    DECLARE v_got_lock INT DEFAULT 0;
    DECLARE v_saved_id BIGINT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      IF v_got_lock=1 THEN DO RELEASE_LOCK(v_lock_name); END IF;
      RESIGNAL;
    END;
    IF p_IS_DEBT_CLEARING IS NULL OR p_IS_DEBT_CLEARING<>'0' THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Use sp_chit_clearing_upsert for clearing';
    END IF;
    IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD)='' THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Company required';
    END IF;
    SET v_lock_name=CONCAT('amnote_debt_',MD5(p_COMPANY_CD));
    SELECT GET_LOCK(v_lock_name,10) INTO v_got_lock;
    IF COALESCE(v_got_lock,0)<>1 THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Debt allocation busy; retry';
    END IF;
    START TRANSACTION;
    CALL sp_chit_collect_write_core(p_COMPANY_CD,p_RECORD_ID,p_SOURCE_CHIT_ID,p_DEBT_CHIT_ID,
      p_AMOUNT,p_AMOUNT_FC,'0',p_CUSTOMER_ID,p_FC_TYPE,p_USERID,v_saved_id);
    COMMIT;
    DO RELEASE_LOCK(v_lock_name);
    SET v_got_lock=0;
    SELECT v_saved_id AS `CHITCOLLECT_ID`;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_chit_collect_write_core
DROP PROCEDURE IF EXISTS `sp_chit_collect_write_core`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_chit_collect_write_core`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_RECORD_ID BIGINT,
    IN p_SOURCE_CHIT_ID BIGINT,
    IN p_DEBT_CHIT_ID BIGINT,
    IN p_AMOUNT DECIMAL(18,2),
    IN p_AMOUNT_FC DECIMAL(18,2),
    IN p_CLEAR CHAR(1),
    IN p_CUSTOMER_ID BIGINT,
    IN p_FC_TYPE VARCHAR(3),
    IN p_USERID VARCHAR(50),
    OUT p_SAVED_ID BIGINT
)
BEGIN
    DECLARE v_amount DECIMAL(24,2) DEFAULT 0;
    DECLARE v_amount_fc DECIMAL(24,2) DEFAULT 0;
    DECLARE v_fc VARCHAR(3);
    DECLARE v_found_id BIGINT DEFAULT 0;
    DECLARE v_found_amount DECIMAL(24,2) DEFAULT 0;
    DECLARE v_found_fc DECIMAL(24,2) DEFAULT 0;
    DECLARE v_count INT DEFAULT 0;
    DECLARE v_mirror_count INT DEFAULT 0;
    DECLARE v_mirror_amount DECIMAL(24,2) DEFAULT 0;
    DECLARE v_mirror_fc DECIMAL(24,2) DEFAULT 0;
    DECLARE v_total DECIMAL(24,2) DEFAULT 0;
    DECLARE v_total_fc DECIMAL(24,2) DEFAULT 0;
    DECLARE v_used DECIMAL(24,2) DEFAULT 0;
    DECLARE v_used_fc DECIMAL(24,2) DEFAULT 0;

    SET p_SAVED_ID = 0;
    SET v_amount = COALESCE(p_AMOUNT,0);
    SET v_amount_fc = COALESCE(p_AMOUNT_FC,0);
    SET v_fc = COALESCE(NULLIF(UPPER(TRIM(p_FC_TYPE)),''),'VND');

    IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD)='' OR
       p_CUSTOMER_ID IS NULL OR p_CUSTOMER_ID <= 0 THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid company/customer';
    END IF;
    IF p_CLEAR NOT IN ('0','1') OR p_CLEAR IS NULL THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid clearing flag';
    END IF;

    IF v_amount < 0 OR v_amount_fc < 0 OR (v_amount=0 AND v_amount_fc=0) OR
       (v_fc='VND' AND v_amount_fc<>0) THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid allocation amounts';
    END IF;
    -- The signs of synthetic IDs are determined by accounting SIDE, not by the table alone.
    IF p_SOURCE_CHIT_ID IS NULL OR
       NOT (p_SOURCE_CHIT_ID>0 OR p_SOURCE_CHIT_ID=IF(p_CLEAR='1',-331,-131)) OR
       p_DEBT_CHIT_ID IS NULL OR
       NOT (p_DEBT_CHIT_ID>0 OR p_DEBT_CHIT_ID=-131) THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid CHIT_ID / opening balance';
    END IF;
    SELECT COUNT(*) INTO v_count FROM customer_info C
      WHERE C.COMPANY_CD=p_COMPANY_CD AND C.CUSTOMER_ID=p_CUSTOMER_ID
        AND COALESCE(C.ISDEL,'0')<>'1';
    IF v_count<>1 THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Customer not found';
    END IF;

    -- Existing PK is immutable identity, never restore a soft-deleted historical row.
    IF COALESCE(p_RECORD_ID,0)>0 THEN
       SELECT COUNT(*) INTO v_count FROM `chit_collect` P
       WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CHITCOLLECT_ID=p_RECORD_ID
         AND COALESCE(P.ISDEL,'0')<>'1'
         AND P.COLLECT_CHIT_ID=p_SOURCE_CHIT_ID AND P.RECEIVABLES_CHIT_ID=p_DEBT_CHIT_ID
         AND P.CUSTOMER_ID=p_CUSTOMER_ID AND P.IS_DEBT_CLEARING=p_CLEAR;
       IF v_count<>1 THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Active allocation identity not found';
       END IF;
       SET v_found_id=p_RECORD_ID;
       SELECT P.COLLECTAMOUNT,P.COLLECTAMOUNT_FC INTO v_found_amount,v_found_fc
       FROM `chit_collect` P WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CHITCOLLECT_ID=v_found_id FOR UPDATE;
    ELSE
       -- Only active rows participate in deduplication; deleted records are immutable audit history.
       SELECT COUNT(*),COALESCE(MAX(P.CHITCOLLECT_ID),0) INTO v_count,v_found_id
       FROM `chit_collect` P
       WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CUSTOMER_ID=p_CUSTOMER_ID
         AND P.COLLECT_CHIT_ID=p_SOURCE_CHIT_ID AND P.RECEIVABLES_CHIT_ID=p_DEBT_CHIT_ID
         AND P.IS_DEBT_CLEARING=p_CLEAR AND COALESCE(P.ISDEL,'0')<>'1';
       IF v_count>1 THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Duplicate active allocations; audit required';
       END IF;
       IF v_found_id>0 THEN
          SELECT P.COLLECTAMOUNT,P.COLLECTAMOUNT_FC INTO v_found_amount,v_found_fc
          FROM `chit_collect` P WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CHITCOLLECT_ID=v_found_id FOR UPDATE;
          IF v_found_amount<>v_amount OR v_found_fc<>v_amount_fc THEN
             SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Allocation exists; pass its ID to update';
          END IF;
       END IF;
    END IF;
    IF p_CLEAR='1' AND v_found_id>0 AND
       (v_found_amount<>v_amount OR v_found_fc<>v_amount_fc) THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Delete and recreate clearing pair to change its amount';
    END IF;

    -- Mirror lookup uses CHIT_ID + CUSTOMER_ID only; legacy detail IDs are not keys.
    IF p_CLEAR='1' THEN
       SELECT COUNT(*),COALESCE(SUM(T.PAYAMOUNT),0),COALESCE(SUM(T.PAYAMOUNT_FC),0)
         INTO v_mirror_count,v_mirror_amount,v_mirror_fc
       FROM `chit_payment` T
       WHERE T.COMPANY_CD=p_COMPANY_CD AND T.CUSTOMER_ID=p_CUSTOMER_ID
         AND T.IS_DEBT_CLEARING='1' AND COALESCE(T.ISDEL,'0')<>'1'
         AND T.DEBIT_CHIT_ID=p_SOURCE_CHIT_ID AND T.PAY_CHIT_ID=p_DEBT_CHIT_ID;
       IF v_mirror_count>1 OR
          (v_mirror_count=1 AND (v_mirror_amount<>v_amount OR v_mirror_fc<>v_amount_fc)) THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Clearing mirror missing/duplicate/mismatched';
       END IF;
    END IF;

    CALL sp_chit_debt_balance_calculate(p_COMPANY_CD,p_SOURCE_CHIT_ID,p_CUSTOMER_ID,
         IF(p_CLEAR='1','331','131'),'C',v_fc,v_total,v_total_fc,v_used,v_used_fc);
    IF p_CLEAR='1' AND v_mirror_count=1 THEN
       SET v_used=v_used-v_mirror_amount;
       SET v_used_fc=v_used_fc-v_mirror_fc;
    ELSE
       SET v_used=v_used-v_found_amount;
       SET v_used_fc=v_used_fc-v_found_fc;
    END IF;
    IF v_total+0.005<v_used+v_amount OR
       (v_amount_fc>0 AND v_total_fc+0.005<v_used_fc+v_amount_fc) THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Source balance exceeded';
    END IF;

    CALL sp_chit_debt_balance_calculate(p_COMPANY_CD,p_DEBT_CHIT_ID,p_CUSTOMER_ID,
         '131','D',v_fc,v_total,v_total_fc,v_used,v_used_fc);
    SET v_used=v_used-v_found_amount;
    SET v_used_fc=v_used_fc-v_found_fc;
    IF v_total+0.005<v_used+v_amount OR
       (v_amount_fc>0 AND v_total_fc+0.005<v_used_fc+v_amount_fc) THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Debt balance exceeded';
    END IF;

    IF v_found_id=0 THEN
       INSERT INTO `chit_collect` (COMPANY_CD,COLLECT_CHIT_ID,COLLECT_CHITDETAIL_ID,
          RECEIVABLES_CHIT_ID,RECEIVABLES_CHITDETAIL_ID,COLLECTAMOUNT,COLLECTAMOUNT_FC,
          IS_DEBT_CLEARING,CUSTOMER_ID,ISDEL,CREATE_BY,UPDATE_BY)
       VALUES(p_COMPANY_CD,p_SOURCE_CHIT_ID,0,p_DEBT_CHIT_ID,0,
          v_amount,v_amount_fc,p_CLEAR,p_CUSTOMER_ID,'0',
          COALESCE(p_USERID,''),COALESCE(p_USERID,''));
       SET v_found_id=LAST_INSERT_ID();
    ELSEIF v_found_amount<>v_amount OR v_found_fc<>v_amount_fc THEN
       UPDATE `chit_collect` SET COLLECTAMOUNT=v_amount,COLLECTAMOUNT_FC=v_amount_fc,
          UPDATE_BY=COALESCE(p_USERID,'')
       WHERE COMPANY_CD=p_COMPANY_CD AND CHITCOLLECT_ID=v_found_id AND COALESCE(ISDEL,'0')<>'1';
    END IF;
    SET p_SAVED_ID=v_found_id;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_chit_debt_balance_calculate
DROP PROCEDURE IF EXISTS `sp_chit_debt_balance_calculate`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_chit_debt_balance_calculate`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHIT_ID BIGINT,
    IN p_CUSTOMER_ID BIGINT,
    IN p_ACC_CD VARCHAR(20),
    IN p_DC_SIDE CHAR(1),
    IN p_FC_TYPE VARCHAR(3),
    OUT p_TOTAL_AMOUNT DECIMAL(24,2),
    OUT p_TOTAL_AMOUNT_FC DECIMAL(24,2),
    OUT p_ALLOC_AMOUNT DECIMAL(24,2),
    OUT p_ALLOC_AMOUNT_FC DECIMAL(24,2)
)
BEGIN
    DECLARE v_fc_type VARCHAR(3) DEFAULT 'VND';

    SET p_TOTAL_AMOUNT = 0;
    SET p_TOTAL_AMOUNT_FC = 0;
    SET p_ALLOC_AMOUNT = 0;
    SET p_ALLOC_AMOUNT_FC = 0;
    SET v_fc_type = COALESCE(NULLIF(UPPER(TRIM(p_FC_TYPE)), ''), 'VND');

    IF p_ACC_CD NOT IN ('131','331') OR p_DC_SIDE NOT IN ('D','C') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unsupported debt account/side';
    END IF;

    IF p_CHIT_ID < 0 THEN
        IF p_CHIT_ID <> -CAST(p_ACC_CD AS SIGNED) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid opening balance identity';
        END IF;
        -- Opening balances use the fixed *_FC columns, not DEBIT_USD/CREDIT_USD.
        -- Restrict both local/foreign amounts to the requested currency.
        IF p_DC_SIDE = 'D' THEN
            SELECT COALESCE(SUM(B.DEBIT),0),
                   COALESCE(SUM(CASE WHEN v_fc_type = 'VND' THEN 0 ELSE B.DEBIT_FC END),0)
              INTO p_TOTAL_AMOUNT, p_TOTAL_AMOUNT_FC
              FROM before_states_customer B
             WHERE B.COMPANY_CD = p_COMPANY_CD
               AND B.CUSTOMER_ID = p_CUSTOMER_ID
               AND B.ACC_CD LIKE CONCAT(p_ACC_CD, '%')
               AND B.FC_TYPE = v_fc_type
               AND COALESCE(B.ISDEL,'0') <> '1';
        ELSE
            SELECT COALESCE(SUM(B.CREDIT),0),
                   COALESCE(SUM(CASE WHEN v_fc_type = 'VND' THEN 0 ELSE B.CREDIT_FC END),0)
              INTO p_TOTAL_AMOUNT, p_TOTAL_AMOUNT_FC
              FROM before_states_customer B
             WHERE B.COMPANY_CD = p_COMPANY_CD
               AND B.CUSTOMER_ID = p_CUSTOMER_ID
               AND B.ACC_CD LIKE CONCAT(p_ACC_CD, '%')
               AND B.FC_TYPE = v_fc_type
               AND COALESCE(B.ISDEL,'0') <> '1';
        END IF;
    ELSEIF p_CHIT_ID > 0 THEN
        SELECT
            COALESCE(SUM(ABS(A.AMOUNT)), 0),
            COALESCE(SUM(IF(v_fc_type = 'VND',0,ABS(A.FC_AMOUNT))), 0)
        INTO p_TOTAL_AMOUNT, p_TOTAL_AMOUNT_FC
        FROM chitdetailinfo A
        INNER JOIN chitdetailinfo_ext X
          ON X.COMPANY_CD = A.COMPANY_CD AND X.CHITDETAIL_ID = A.CHITDETAIL_ID
        INNER JOIN chitinfo H
          ON H.COMPANY_CD = A.COMPANY_CD AND H.CHIT_ID = A.CHIT_ID
         AND COALESCE(H.ISDEL,'0') <> '1'
        WHERE A.COMPANY_CD = p_COMPANY_CD
          AND A.CHIT_ID = p_CHIT_ID
          AND COALESCE(A.ISDEL,'0') <> '1'
          AND ( (v_fc_type = 'VND' AND COALESCE(A.FC_TYPE,'') IN ('','VND'))
                OR (v_fc_type <> 'VND' AND A.FC_TYPE = v_fc_type) )
          AND (
              (p_DC_SIDE = 'D' AND (
                 (A.DEBIT LIKE CONCAT(p_ACC_CD,'%') AND A.AMOUNT > 0)
                 OR (A.CREDIT LIKE CONCAT(p_ACC_CD,'%') AND A.AMOUNT < 0)
              ))
              OR
              (p_DC_SIDE = 'C' AND (
                 (A.CREDIT LIKE CONCAT(p_ACC_CD,'%') AND A.AMOUNT > 0)
                 OR (A.DEBIT LIKE CONCAT(p_ACC_CD,'%') AND A.AMOUNT < 0)
              ))
          )
          AND (
              CASE WHEN H.CHIT_TYPE = 5 THEN
                CASE WHEN A.DEBIT LIKE CONCAT(p_ACC_CD,'%')
                     THEN X.CUSTOMER_ID ELSE X.CUSTOMER_OWN_ID END
              ELSE X.CUSTOMER_ID END
          ) = p_CUSTOMER_ID;
    ELSE
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CHIT_ID must not be zero';
    END IF;

    -- Canonical consumption. Paired clearing rows count only once:
    -- 131 Debit: chit_collect.RECEIVABLES_*
    -- 131 Credit: chit_collect.COLLECT_*
    -- 331 Debit: chit_payment.PAY_*
    -- 331 Credit: chit_payment.DEBIT_*
    IF p_ACC_CD = '131' AND p_DC_SIDE = 'D' THEN
        SELECT COALESCE(SUM(P.COLLECTAMOUNT),0), COALESCE(SUM(P.COLLECTAMOUNT_FC),0)
          INTO p_ALLOC_AMOUNT, p_ALLOC_AMOUNT_FC
          FROM chit_collect P
         WHERE P.COMPANY_CD = p_COMPANY_CD AND P.CUSTOMER_ID = p_CUSTOMER_ID
           AND P.RECEIVABLES_CHIT_ID = p_CHIT_ID
           AND COALESCE(P.ISDEL,'0') <> '1';
    ELSEIF p_ACC_CD = '131' AND p_DC_SIDE = 'C' THEN
        SELECT COALESCE(SUM(P.COLLECTAMOUNT),0), COALESCE(SUM(P.COLLECTAMOUNT_FC),0)
          INTO p_ALLOC_AMOUNT, p_ALLOC_AMOUNT_FC
          FROM chit_collect P
         WHERE P.COMPANY_CD = p_COMPANY_CD AND P.CUSTOMER_ID = p_CUSTOMER_ID
           AND P.COLLECT_CHIT_ID = p_CHIT_ID
           AND COALESCE(P.ISDEL,'0') <> '1';
    ELSEIF p_ACC_CD = '331' AND p_DC_SIDE = 'D' THEN
        SELECT COALESCE(SUM(P.PAYAMOUNT),0), COALESCE(SUM(P.PAYAMOUNT_FC),0)
          INTO p_ALLOC_AMOUNT, p_ALLOC_AMOUNT_FC
          FROM chit_payment P
         WHERE P.COMPANY_CD = p_COMPANY_CD AND P.CUSTOMER_ID = p_CUSTOMER_ID
           AND P.PAY_CHIT_ID = p_CHIT_ID
           AND COALESCE(P.ISDEL,'0') <> '1';
    ELSE
        SELECT COALESCE(SUM(P.PAYAMOUNT),0), COALESCE(SUM(P.PAYAMOUNT_FC),0)
          INTO p_ALLOC_AMOUNT, p_ALLOC_AMOUNT_FC
          FROM chit_payment P
         WHERE P.COMPANY_CD = p_COMPANY_CD AND P.CUSTOMER_ID = p_CUSTOMER_ID
           AND P.DEBIT_CHIT_ID = p_CHIT_ID
           AND COALESCE(P.ISDEL,'0') <> '1';
    END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_chit_debt_cleaning_get
DROP PROCEDURE IF EXISTS `sp_chit_debt_cleaning_get`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_chit_debt_cleaning_get`(
    IN `p_COMPANY_CD` varchar(20),
    IN `p_DEBT_TYPE` char(1),
    IN `p_FROM_YMD` varchar(8),
    IN `p_TO_YMD` varchar(8),
    IN `p_CUSTOMER_IDS` varchar(5000),
    IN `p_FC_TYPE` varchar(20),
    IN `p_ACC_CD` varchar(20)
)
BEGIN
	
	SET @sWhereFcType = "",@sWhereAmount=" AND PAYAMOUNT > 0 ";
	IF(p_FC_TYPE != "") THEN
		SET @sPosition = POSITION("|" IN p_FC_TYPE);
		IF(@sPosition > 0) THEN
			SET @DCWayCode = SUBSTR(p_FC_TYPE,1,@sPosition-1);
			SET p_FC_TYPE = SUBSTR(p_FC_TYPE,@sPosition+1,3);	
			SET @sWhereAmount = " AND PAYAMOUNT > 0";	
			IF(@DCWayCode = 1) THEN
				SET @sWhereFcType = CONCAT(" AND  IFNULL(FC_TYPE,'') = '",p_FC_TYPE,"' ");	
				SET @sWhereAmount = " AND PAYAMOUNT_FC > 0 ";							
			ELSE IF(@DCWayCode = 2) THEN
				SET @sWhereFcType = CONCAT("  AND (IFNULL(FC_TYPE,'') = '' OR IFNULL(FC_TYPE,'') = '",p_FC_TYPE,"') ");
				SET @sWhereAmount = " AND (PAYAMOUNT > 0 OR PAYAMOUNT_FC > 0) ";		
			END IF;
			END IF;
		END IF;
	END IF;
	-- Accept ALL or a comma-separated list of numeric CUSTOMER_ID values.
	IF p_CUSTOMER_IDS IS NULL OR TRIM(p_CUSTOMER_IDS) = '' THEN
		SET p_CUSTOMER_IDS = 'ALL';
	END IF;
	SET p_CUSTOMER_IDS = TRIM(p_CUSTOMER_IDS);
	IF UPPER(p_CUSTOMER_IDS) = 'ALL' THEN SET p_CUSTOMER_IDS = 'ALL'; END IF;
	IF UPPER(p_CUSTOMER_IDS) <> 'ALL' AND
	   p_CUSTOMER_IDS NOT REGEXP '^[0-9]+(,[0-9]+)*$' THEN
		SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid customer IDs';
	END IF;
	
	-- The debt voucher date is matched on the payable/receivable voucher (D).
	IF NULLIF(TRIM(p_FROM_YMD), '') IS NULL THEN
		SET @DebtDateCondition = CONCAT(' D.CHIT_YMD < ', QUOTE(p_TO_YMD), ' ');
	ELSE
		SET @DebtDateCondition = CONCAT(' D.CHIT_YMD >= ', QUOTE(p_FROM_YMD),
		                                ' AND D.CHIT_YMD <= ', QUOTE(p_TO_YMD), ' ');
	END IF;

IF(p_DEBT_TYPE='1') THEN

/*Payment*/
SET @V_SQL = CONCAT("
		SELECT 
				CUS1.CUSTOMER_ID AS CUSTOMER_ID,
				IFNULL(CUS1.CUSTOMER_CD,'') AS CUSTOMER_CD,
				IFNULL(CUS1.CUSTOMER_NM_VIET,'') AS CUSTOMER_NM_VIET,
				IFNULL(CUS1.CUSTOMER_NM_ENG,'') AS CUSTOMER_NM_ENG,
				IFNULL(CUS1.CUSTOMER_NM_KOR,'') AS CUSTOMER_NM_KOR,
				IFNULL(CUS1.CUSTOMER_NM_CHINA,'') AS CUSTOMER_NM_CHINA,
				CHITPAYMENT_ID,
				CHIT_ID_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN -1 ELSE CHIT_TYPE_PAY END CHIT_TYPE_PAY,
				'' AS TYPE_CHIT_PAY_TEXT,
				CHIT_YMD_PAY,	
				CHIT_NO_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN 'Số dư đầu kỳ' ELSE DESCRIPTION_VIET_PAY END AS DESCRIPTION_VIET_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN 'Openning balance' ELSE DESCRIPTION_ENG_PAY END AS DESCRIPTION_ENG_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN '기초잔액' ELSE DESCRIPTION_KOR_PAY END AS DESCRIPTION_KOR_PAY,
			   CASE WHEN CHIT_ID_PAY < 0 THEN '期初余额' ELSE DESCRIPTION_CHINA_PAY END AS DESCRIPTION_CHINA_PAY,
			   
				CHIT_ID_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN -1 ELSE CHIT_TYPE_DEBT END CHIT_TYPE_DEBT,
				'' AS TYPE_CHIT_DEBT_TEXT,
				CHIT_YMD_DEBT,
				CHIT_NO_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN 'Số dư đầu kỳ' ELSE DESCRIPTION_VIET_DEBT END AS DESCRIPTION_VIET_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN 'Openning balance' ELSE DESCRIPTION_ENG_DEBT END AS DESCRIPTION_ENG_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN '기초잔액' ELSE DESCRIPTION_KOR_DEBT END AS DESCRIPTION_KOR_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN '期初余额' ELSE DESCRIPTION_CHINA_DEBT END AS DESCRIPTION_CHINA_DEBT,
				
				PAYAMOUNT,
				PAYAMOUNT_FC
		FROM (
		SELECT 
				P.CHITPAYMENT_ID AS CHITPAYMENT_ID,
				P.PAY_CHIT_ID AS CHIT_ID_PAY,
				C.CHIT_TYPE AS CHIT_TYPE_PAY,
				C.CHIT_NO AS CHIT_NO_PAY,
				C.CHIT_YMD AS CHIT_YMD_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'VIET' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_VIET_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'ENG' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_ENG_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_KOR_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA_PAY,
				
				P.DEBIT_CHIT_ID AS CHIT_ID_DEBT,
				D.CHIT_TYPE AS CHIT_TYPE_DEBT,
				D.CHIT_NO AS CHIT_NO_DEBT,
				D.CHIT_YMD AS CHIT_YMD_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'VIET' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_VIET_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'ENG' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_ENG_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_KOR_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA_DEBT,
				
				IFNULL(SUM(P.PAYAMOUNT),0.0)as PAYAMOUNT,
				IFNULL(SUM(P.PAYAMOUNT_FC),0.0) as PAYAMOUNT_FC,
				P.CUSTOMER_ID
			FROM chit_payment P 
			LEFT JOIN chitinfo C ON P.PAY_CHIT_ID = C.CHIT_ID AND IFNULL(C.ISDEL,'') != '1' AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
			LEFT JOIN chitinfo D ON P.DEBIT_CHIT_ID = D.CHIT_ID AND IFNULL(D.ISDEL,'') != '1' AND D.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
			WHERE 
				P.IS_DEBT_CLEARING !=1
				AND IFNULL(P.ISDEL,'') != '1'
				AND (
						(	
							",@DebtDateCondition," AND 
							EXISTS(SELECT * FROM chitdetailinfo E INNER JOIN chitdetailinfo_ext EX ON EX.CHITDETAIL_ID = E.CHITDETAIL_ID AND EX.COMPANY_CD = E.COMPANY_CD WHERE C.CHIT_ID = E.CHIT_ID AND IFNULL(E.ISDEL,'') != '1' 
									AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(IF(C.CHIT_TYPE = 5, EX.CUSTOMER_OWN_ID, EX.CUSTOMER_ID) AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
									/*AND (E.DEBIT LIKE '",p_ACC_CD,"%'  OR (E.CREDIT LIKE '",p_ACC_CD,"%' AND E.AMOUNT < 0) )*/ ",@sWhereFcType,"
							) AND
							EXISTS(SELECT * FROM chitdetailinfo F INNER JOIN chitdetailinfo_ext FX ON FX.CHITDETAIL_ID = F.CHITDETAIL_ID AND FX.COMPANY_CD = F.COMPANY_CD WHERE D.CHIT_ID = F.CHIT_ID AND IFNULL(F.ISDEL,'') != '1' 
									AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(IF(D.CHIT_TYPE = 5, FX.CUSTOMER_OWN_ID, FX.CUSTOMER_ID) AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
									/*AND F.CREDIT LIKE '",p_ACC_CD,"%'*/ ",@sWhereFcType,"    
							)
						)
						OR P.PAY_CHIT_ID = -331 OR P.DEBIT_CHIT_ID = -331
				)
				AND P.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
				AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(P.CUSTOMER_ID AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
			GROUP BY P.CHITPAYMENT_ID
			) A 
			LEFT JOIN customer_info CUS1 ON A.CUSTOMER_ID = CUS1.CUSTOMER_ID AND IFNULL(CUS1.ISDEL,'0') != '1' AND CUS1.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
			WHERE 
				CUS1.CUSTOMER_ID IS NOT NULL
				AND (IFNULL(CHIT_NO_PAY,'') != '' OR CHIT_ID_PAY < 0) 
				AND (IFNULL(CHIT_NO_DEBT,'') != '' OR CHIT_ID_DEBT < 0)
				",@sWhereAmount,"
			ORDER BY CUS1.CUSTOMER_ID,CHIT_YMD_PAY,CHIT_NO_PAY,CHIT_YMD_DEBT,CHIT_NO_DEBT
			");
				
		PREPARE STMT FROM @V_SQL;
		EXECUTE STMT;
		DEALLOCATE PREPARE STMT;

	ELSE
	
/*Collect*/	
		SET @V_SQL = CONCAT("
			SELECT 
				CUS1.CUSTOMER_ID AS CUSTOMER_ID,
				IFNULL(CUS1.CUSTOMER_CD,'') AS CUSTOMER_CD,
				IFNULL(CUS1.CUSTOMER_NM_VIET,'') AS CUSTOMER_NM_VIET,
				IFNULL(CUS1.CUSTOMER_NM_ENG,'') AS CUSTOMER_NM_ENG,
				IFNULL(CUS1.CUSTOMER_NM_KOR,'') AS CUSTOMER_NM_KOR,
				IFNULL(CUS1.CUSTOMER_NM_CHINA,'') AS CUSTOMER_NM_CHINA,
				
				CHITCOLLECT_ID,
				CHIT_ID_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN -1 ELSE CHIT_TYPE_PAY END CHIT_TYPE_PAY,
				'' AS TYPE_CHIT_PAY_TEXT,
				CHIT_YMD_PAY,	
				CHIT_NO_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN 'Số dư đầu kỳ' ELSE DESCRIPTION_VIET_PAY END AS DESCRIPTION_VIET_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN 'Openning balance' ELSE DESCRIPTION_ENG_PAY END AS DESCRIPTION_ENG_PAY,
				CASE WHEN CHIT_ID_PAY < 0 THEN '기초잔액' ELSE DESCRIPTION_KOR_PAY END AS DESCRIPTION_KOR_PAY,
			   CASE WHEN CHIT_ID_PAY < 0 THEN '期初余额' ELSE DESCRIPTION_CHINA_PAY END AS DESCRIPTION_CHINA_PAY,
			
				CHIT_ID_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN -1 ELSE CHIT_TYPE_DEBT END CHIT_TYPE_DEBT,
				'' AS TYPE_CHIT_DEBT_TEXT,
				CHIT_YMD_DEBT,
				CHIT_NO_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN 'Số dư đầu kỳ' ELSE DESCRIPTION_VIET_DEBT END AS DESCRIPTION_VIET_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN 'Openning balance' ELSE DESCRIPTION_ENG_DEBT END AS DESCRIPTION_ENG_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN '기초잔액' ELSE DESCRIPTION_KOR_DEBT END AS DESCRIPTION_KOR_DEBT,
				CASE WHEN CHIT_ID_DEBT < 0 THEN '期初余额' ELSE DESCRIPTION_CHINA_DEBT END AS DESCRIPTION_CHINA_DEBT,
				
				PAYAMOUNT,
				PAYAMOUNT_FC
		FROM (
		SELECT 
				P.CHITCOLLECT_ID AS CHITCOLLECT_ID,
				P.COLLECT_CHIT_ID AS CHIT_ID_PAY,
				C.CHIT_TYPE AS CHIT_TYPE_PAY,
				C.CHIT_NO AS CHIT_NO_PAY,
				C.CHIT_YMD AS CHIT_YMD_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'VIET' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_VIET_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'ENG' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_ENG_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_KOR_PAY,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = C.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA_PAY,
				
				P.RECEIVABLES_CHIT_ID AS CHIT_ID_DEBT,
				D.CHIT_TYPE AS CHIT_TYPE_DEBT,
				D.CHIT_NO AS CHIT_NO_DEBT,
				D.CHIT_YMD AS CHIT_YMD_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'VIET' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_VIET_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'ENG' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_ENG_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_KOR_DEBT,
				(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = D.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA_DEBT,
				
				IFNULL(SUM(P.COLLECTAMOUNT),0.0)as PAYAMOUNT,
				IFNULL(SUM(P.COLLECTAMOUNT_FC),0.0) as PAYAMOUNT_FC,
				P.CUSTOMER_ID
			FROM chit_collect P 
			LEFT JOIN chitinfo C ON P.COLLECT_CHIT_ID = C.CHIT_ID AND IFNULL(C.ISDEL,'') != '1' AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
			LEFT JOIN chitinfo D ON P.RECEIVABLES_CHIT_ID = D.CHIT_ID AND IFNULL(D.ISDEL,'') != '1' AND D.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
			WHERE 
				P.IS_DEBT_CLEARING !=1
				AND IFNULL(P.ISDEL,'') != '1' 
				AND (
						(
						",@DebtDateCondition," AND 
						EXISTS(SELECT * FROM chitdetailinfo E INNER JOIN chitdetailinfo_ext EX ON EX.CHITDETAIL_ID = E.CHITDETAIL_ID AND EX.COMPANY_CD = E.COMPANY_CD WHERE C.CHIT_ID = E.CHIT_ID AND IFNULL(E.ISDEL,'') != '1' 
								AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(IF(C.CHIT_TYPE = 5, EX.CUSTOMER_OWN_ID, EX.CUSTOMER_ID) AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
								/*AND (E.CREDIT LIKE '",p_ACC_CD,"%'  OR (E.DEBIT LIKE '",p_ACC_CD,"%' AND E.AMOUNT < 0) )*/ ",@sWhereFcType," 
						) AND
						EXISTS(SELECT * FROM chitdetailinfo F INNER JOIN chitdetailinfo_ext FX ON FX.CHITDETAIL_ID = F.CHITDETAIL_ID AND FX.COMPANY_CD = F.COMPANY_CD WHERE D.CHIT_ID = F.CHIT_ID AND IFNULL(F.ISDEL,'') != '1' 
								AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(IF(D.CHIT_TYPE = 5, FX.CUSTOMER_OWN_ID, FX.CUSTOMER_ID) AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
								/*AND F.DEBIT LIKE '",p_ACC_CD,"%'*/ ",@sWhereFcType,"    
						)
					)
					OR P.COLLECT_CHIT_ID = -131 OR P.RECEIVABLES_CHIT_ID = -131
				)
				AND P.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
				AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(P.CUSTOMER_ID AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
			GROUP BY P.CHITCOLLECT_ID
			) A
			LEFT JOIN customer_info CUS1 ON A.CUSTOMER_ID = CUS1.CUSTOMER_ID AND IFNULL(CUS1.ISDEL,'0') != '1' AND CUS1.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
			WHERE 
				CUS1.CUSTOMER_ID IS NOT NULL
				AND (IFNULL(CHIT_NO_PAY,'') != '' OR CHIT_ID_PAY < 0) 
				AND (IFNULL(CHIT_NO_DEBT,'') != '' OR CHIT_ID_DEBT < 0)
				",@sWhereAmount,"
			ORDER BY CUS1.CUSTOMER_ID,CHIT_YMD_PAY,CHIT_NO_PAY,CHIT_YMD_DEBT,CHIT_NO_DEBT
			");
				
			PREPARE STMT FROM @V_SQL;
			EXECUTE STMT;
			DEALLOCATE PREPARE STMT;

	END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_chit_debt_get
DROP PROCEDURE IF EXISTS `sp_chit_debt_get`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_chit_debt_get`(
    IN `p_COMPANY_CD` varchar(20),
    IN `p_DEBT_TYPE` char(1),
    IN `p_FROM_YMD` varchar(8),
    IN `p_TO_YMD` varchar(8),
    IN `p_CUSTOMER_IDS` varchar(5000),
    IN `p_FC_TYPE` varchar(20),
    IN `p_ACC_CD` varchar(20)
)
BEGIN
	
	SET @DCWayCode = NULL;
	SET @sWhereFcType = "", @sHaving = " HAVING REMAINAMOUNT > 0 ";
	IF(p_FC_TYPE != "") THEN
		SET @sPosition = POSITION("|" IN p_FC_TYPE);
		IF(@sPosition > 0) THEN
			SET @DCWayCode = SUBSTR(p_FC_TYPE,1,@sPosition-1);
			SET p_FC_TYPE = SUBSTR(p_FC_TYPE,@sPosition+1,3);
			SET @sHaving = CONCAT(" HAVING REMAINAMOUNT > 0 ");	
			IF(@DCWayCode = 1) THEN
				SET @sHaving = CONCAT(" HAVING REMAINAMOUNT_FC > 0  ");
				SET @sWhereFcType = CONCAT(" AND IFNULL(A.FC_TYPE,'') = '",p_FC_TYPE,"' ");							
			ELSE IF(@DCWayCode = 2) THEN
				SET @sHaving = CONCAT(" HAVING (REMAINAMOUNT > 0 OR REMAINAMOUNT_FC > 0)  ");
				SET @sWhereFcType = CONCAT(" AND (IFNULL(A.FC_TYPE,'') = '' OR IFNULL(A.FC_TYPE,'') = '",p_FC_TYPE,"') ");	
			END IF;
			END IF;
		END IF;
	END IF;

	-- Opening balances now store one DEBIT_FC/CREDIT_FC per row with FC_TYPE.
	-- Preserve legacy unfiltered behaviour: USD is the default foreign display.
	SET @OpenFCType = CASE WHEN p_FC_TYPE IN ('USD','EUR','JPY','KRW','CNY')
	                       THEN p_FC_TYPE ELSE 'USD' END;
	SET @sWhereOpenFcType = '';
	IF NULLIF(TRIM(p_FC_TYPE), '') IS NOT NULL THEN
		IF @DCWayCode = '2' THEN
			SET @sWhereOpenFcType = CONCAT(' AND A.FC_TYPE IN (', QUOTE('VND'), ', ', QUOTE(p_FC_TYPE), ') ');
		ELSE
			SET @sWhereOpenFcType = CONCAT(' AND A.FC_TYPE = ', QUOTE(p_FC_TYPE), ' ');
		END IF;
	END IF;
	-- Accept ALL or a comma-separated list of numeric CUSTOMER_ID values.
	IF p_CUSTOMER_IDS IS NULL OR TRIM(p_CUSTOMER_IDS) = '' THEN
		SET p_CUSTOMER_IDS = 'ALL';
	END IF;
	SET p_CUSTOMER_IDS = TRIM(p_CUSTOMER_IDS);
	IF UPPER(p_CUSTOMER_IDS) = 'ALL' THEN SET p_CUSTOMER_IDS = 'ALL'; END IF;
	IF UPPER(p_CUSTOMER_IDS) <> 'ALL' AND
	   p_CUSTOMER_IDS NOT REGEXP '^[0-9]+(,[0-9]+)*$' THEN
		SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid customer IDs';
	END IF;
	
	-- Empty/NULL FROM: strictly earlier than TO. Explicit FROM: inclusive range.
	IF NULLIF(TRIM(p_FROM_YMD), '') IS NULL THEN
		SET @QueryYMD = CONCAT(' AND A.CHIT_YMD < ', QUOTE(p_TO_YMD), ' ');
	ELSE
		SET @QueryYMD = CONCAT(' AND A.CHIT_YMD >= ', QUOTE(p_FROM_YMD),
		                       ' AND A.CHIT_YMD <= ', QUOTE(p_TO_YMD), ' ');
	END IF;
	
IF(p_DEBT_TYPE='1') THEN


SET @V_SQL = CONCAT("
	SELECT 
			CUS1.CUSTOMER_ID AS CUSTOMER_ID,
			IFNULL(CUS1.CUSTOMER_CD,'') AS CUSTOMER_CD,
			IFNULL(CUS1.CUSTOMER_NM_VIET,'') AS CUSTOMER_NM_VIET,
			IFNULL(CUS1.CUSTOMER_NM_ENG,'') AS CUSTOMER_NM_ENG,
			IFNULL(CUS1.CUSTOMER_NM_KOR,'') AS CUSTOMER_NM_KOR,
			IFNULL(CUS1.CUSTOMER_NM_CHINA,'') AS CUSTOMER_NM_CHINA,
			PAY_ID,
			CHIT_ID,
			CHIT_TYPE,
			CHIT_NO,
			CHIT_YMD,
			VAT_CHIT_NO,
			VAT_YMD,
			DESCRIPTION_VIET,
			DESCRIPTION_ENG,
			DESCRIPTION_KOR,
			DESCRIPTION_CHINA,
			DAY_OF_PAYMENT,
			TIME_FOR_PAYMENT,
			AMOUNT,
			FC_AMOUNT,
			REMAINAMOUNT,
			REMAINAMOUNT_FC,
			PAYAMOUNT,
			PAYAMOUNT_FC
	FROM (			
		SELECT 
				COALESCE(MIN(P.CHITPAYMENT_ID),0) AS PAY_ID,
				-331 AS CHIT_ID,
				'-1' AS CHIT_TYPE,
				'' AS CHIT_NO,
				'' AS CHIT_YMD,
				A.CUSTOMER_ID,
				'' AS VAT_CHIT_NO,
				'' AS VAT_YMD,
				'Số dư đầu kỳ' AS DESCRIPTION_VIET,
				'Openning balance' AS DESCRIPTION_ENG, 	
				'기초잔액' AS DESCRIPTION_KOR,
				'期初余额' AS DESCRIPTION_CHINA,
				'' AS DAY_OF_PAYMENT,
				'' AS TIME_FOR_PAYMENT,
				AMOUNT,
				FC_AMOUNT,
				IFNULL(A.AMOUNT - IFNULL(SUM(P.PAYAMOUNT),0.0),0.0) as REMAINAMOUNT,
				IFNULL(A.FC_AMOUNT - IFNULL(SUM(P.PAYAMOUNT_FC),0.0),0.0) as REMAINAMOUNT_FC,
				0.0 AS PAYAMOUNT,
				0.0 AS PAYAMOUNT_FC
			FROM (
				SELECT 
					A.CUSTOMER_ID,
					IFNULL(SUM(A.DEBIT),0.0) AS AMOUNT,
					IFNULL(SUM(CASE WHEN A.FC_TYPE = @OpenFCType THEN A.DEBIT_FC ELSE 0 END),0.0) AS FC_AMOUNT
					FROM before_states_customer A
					WHERE A.ACC_CD like '",p_ACC_CD,"%' 
				    AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(A.CUSTOMER_ID AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
					AND IFNULL(A.ISDEL,'') !=1
					",@sWhereOpenFcType,"
					AND A.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
					GROUP BY A.CUSTOMER_ID
				) A
			LEFT JOIN chit_payment P ON ifnull(P.ISDEL,'') != '1' AND P.PAY_CHIT_ID = -331  AND A.CUSTOMER_ID = P.CUSTOMER_ID AND P.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," 
			GROUP BY A.CUSTOMER_ID,AMOUNT,FC_AMOUNT
			",@sHaving," 

		UNION ALL
		SELECT 
			COALESCE(MIN(C.CHITPAYMENT_ID),0) AS PAY_ID,
			CHIT_ID,
			CHIT_TYPE,
			CHIT_NO,
			CHIT_YMD,
			F.CUSTOMER_ID,
			VAT_CHIT_NO,
			VAT_YMD,
			DESCRIPTION_VIET,
			DESCRIPTION_ENG,
			DESCRIPTION_KOR,
			DESCRIPTION_CHINA,
			DAY_OF_PAYMENT,
			TIME_FOR_PAYMENT,
			AMOUNT,
			FC_AMOUNT,
			AMOUNT -	IFNULL(SUM(C.PAYAMOUNT),0.0) as REMAINAMOUNT,
			FC_AMOUNT - IFNULL(SUM(C.PAYAMOUNT_FC),0.0) as REMAINAMOUNT_FC,
			0.0 AS PAYAMOUNT,
			0.0 AS PAYAMOUNT_FC
	FROM(
		SELECT 
					B.CHIT_ID,

					B.CHIT_TYPE,
					B.CHIT_NO,
					A.CHIT_YMD,
					IF(B.CHIT_TYPE = 5, IF(A.DEBIT LIKE '",p_ACC_CD,"%',AX.CUSTOMER_ID, AX.CUSTOMER_OWN_ID), AX.CUSTOMER_ID) AS CUSTOMER_ID,
					IFNULL((SELECT V.VAT_CHIT_NO FROM chitdetailinfo C INNER JOIN chitdetailinfo_vat V ON V.COMPANY_CD = C.COMPANY_CD AND V.CHITDETAIL_ID = C.CHITDETAIL_ID WHERE IFNULL(C.ISDEL,'0') <> '1' AND IFNULL(V.VAT_CHIT_NO,'') <> '' AND C.CHIT_ID = A.CHIT_ID AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," ORDER BY C.CHITDETAIL_ID LIMIT 1),'') AS VAT_CHIT_NO,
					IFNULL((SELECT V.VAT_YMD FROM chitdetailinfo C INNER JOIN chitdetailinfo_vat V ON V.COMPANY_CD = C.COMPANY_CD AND V.CHITDETAIL_ID = C.CHITDETAIL_ID WHERE IFNULL(C.ISDEL,'0') <> '1' AND IFNULL(V.VAT_CHIT_NO,'') <> '' AND C.CHIT_ID = A.CHIT_ID AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," ORDER BY C.CHITDETAIL_ID LIMIT 1),'') AS VAT_YMD,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'VIET' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_VIET,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'ENG' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_ENG,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_KOR,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA,
					IFNULL(BX.DAY_OF_PAYMENT,'') AS DAY_OF_PAYMENT,
					IFNULL(BX.TIME_FOR_PAYMENT,'') AS TIME_FOR_PAYMENT,
					IFNULL(SUM(IF(A.CREDIT LIKE '",p_ACC_CD,"%' AND A.AMOUNT < 0,-A.AMOUNT,A.AMOUNT)),0.0) AS AMOUNT,
					IFNULL(SUM(IF(A.CREDIT LIKE '",p_ACC_CD,"%' AND A.FC_AMOUNT < 0,-A.FC_AMOUNT,A.FC_AMOUNT)),0.0) AS FC_AMOUNT
				FROM chitdetailinfo A
                    INNER JOIN chitdetailinfo_ext AX ON AX.CHITDETAIL_ID = A.CHITDETAIL_ID AND AX.COMPANY_CD = A.COMPANY_CD
					LEFT JOIN chitinfo B ON B.CHIT_ID = A.CHIT_ID AND (B.ISDEL IS NULL OR B.ISDEL != '1') AND B.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
                    LEFT JOIN chitinfo_ext BX ON BX.CHIT_ID = B.CHIT_ID AND BX.COMPANY_CD = B.COMPANY_CD
				WHERE  
					IFNULL(B.CHIT_NO,'')!=''				
					AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(IF(B.CHIT_TYPE = 5, IF(A.DEBIT LIKE '",p_ACC_CD,"%',AX.CUSTOMER_ID, AX.CUSTOMER_OWN_ID), AX.CUSTOMER_ID) AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
					",@QueryYMD,"
					AND (A.DEBIT LIKE '",p_ACC_CD,"%' OR (A.CREDIT LIKE '",p_ACC_CD,"%' AND A.AMOUNT < 0) ) 
					AND IFNULL(A.ISDEL,'0') != '1' 
					",@sWhereFcType," 
					AND A.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
				GROUP BY 	
					B.CHIT_ID,
					B.CHIT_NO,
					A.CHIT_YMD,
					IF(B.CHIT_TYPE = 5, IF(A.DEBIT LIKE '",p_ACC_CD,"%',AX.CUSTOMER_ID, AX.CUSTOMER_OWN_ID), AX.CUSTOMER_ID)
	 ) F
	 	LEFT JOIN chit_payment C ON ifnull(C.ISDEL,'') != '1' AND C.PAY_CHIT_ID = F.CHIT_ID AND F.CUSTOMER_ID = C.CUSTOMER_ID AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," 
	 	GROUP BY CHIT_ID,F.CUSTOMER_ID
	 ) A
	 LEFT JOIN customer_info CUS1 ON A.CUSTOMER_ID = CUS1.CUSTOMER_ID AND IFNULL(CUS1.ISDEL,'0') != '1' AND CUS1.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," 
	 WHERE CUS1.CUSTOMER_ID IS NOT NULL
	 	",@sHaving,"
	 ORDER BY CUSTOMER_ID,CHIT_YMD, CHIT_NO,TIME_FOR_PAYMENT;
		");
		PREPARE STMT FROM @V_SQL;
		EXECUTE STMT;
		DEALLOCATE PREPARE STMT;
	
	
