					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_KOR,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA,
					IFNULL(BX.DAY_OF_PAYMENT,'') AS DAY_OF_PAYMENT,
					IFNULL(BX.TIME_FOR_PAYMENT,'') AS TIME_FOR_PAYMENT,
					IFNULL(SUM(IF(A.DEBIT LIKE '",p_ACC_CD,"%' AND A.AMOUNT < 0,-A.AMOUNT,A.AMOUNT)),0.0) AS AMOUNT,
					IFNULL(SUM(IF(A.DEBIT LIKE '",p_ACC_CD,"%' AND A.FC_AMOUNT < 0,-A.FC_AMOUNT,A.FC_AMOUNT)),0.0) AS FC_AMOUNT
				FROM chitdetailinfo A
                    INNER JOIN chitdetailinfo_ext AX ON AX.CHITDETAIL_ID = A.CHITDETAIL_ID AND AX.COMPANY_CD = A.COMPANY_CD
					LEFT JOIN chitinfo B ON B.CHIT_ID = A.CHIT_ID AND (B.ISDEL IS NULL OR B.ISDEL != '1') AND B.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
                    LEFT JOIN chitinfo_ext BX ON BX.CHIT_ID = B.CHIT_ID AND BX.COMPANY_CD = B.COMPANY_CD 
				WHERE  
					IFNULL(B.CHIT_NO,'')!=''				
					AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(IF(B.CHIT_TYPE = 5, IF(A.CREDIT LIKE '",p_ACC_CD,"%', AX.CUSTOMER_OWN_ID, AX.CUSTOMER_ID), AX.CUSTOMER_ID) AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
					",@QueryYMD,"
					AND (A.CREDIT LIKE '",p_ACC_CD,"%' OR (A.DEBIT LIKE '",p_ACC_CD,"%' AND A.AMOUNT < 0) )
					AND IFNULL(A.ISDEL,'0') != '1' 
					",@sWhereFcType,"
					AND A.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," 
				GROUP BY 	
					B.CHIT_ID,
					B.CHIT_NO,
					A.CHIT_YMD,
					IF(B.CHIT_TYPE = 5, IF(A.CREDIT LIKE '",p_ACC_CD,"%', AX.CUSTOMER_OWN_ID, AX.CUSTOMER_ID), AX.CUSTOMER_ID) 
	 ) F
	 	LEFT JOIN chit_collect C ON ifnull(C.ISDEL,'') != '1' AND C.COLLECT_CHIT_ID = F.CHIT_ID AND F.CUSTOMER_ID = C.CUSTOMER_ID AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
	 	GROUP BY CHIT_ID,F.CUSTOMER_ID
	 ) A
	 LEFT JOIN customer_info CUS1 ON A.CUSTOMER_ID = CUS1.CUSTOMER_ID AND IFNULL(CUS1.ISDEL,'0') != '1' AND CUS1.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
	 WHERE CUS1.CUSTOMER_ID IS NOT NULL
	 	",@sHaving,"
	 ORDER BY CUSTOMER_ID,CHIT_YMD, CHIT_NO,TIME_FOR_PAYMENT;
		");
		PREPARE STMT FROM @V_SQL;
		EXECUTE STMT;
		DEALLOCATE PREPARE STMT;
	
	
	SET @V_SQL = CONCAT("
	SELECT 
			CUS1.CUSTOMER_ID AS CUSTOMER_ID,
			IFNULL(CUS1.CUSTOMER_CD,'') AS CUSTOMER_CD,
			IFNULL(CUS1.CUSTOMER_NM_VIET,'') AS CUSTOMER_NM_VIET,
			IFNULL(CUS1.CUSTOMER_NM_ENG,'') AS CUSTOMER_NM_ENG,
			IFNULL(CUS1.CUSTOMER_NM_KOR,'') AS CUSTOMER_NM_KOR,
			IFNULL(CUS1.CUSTOMER_NM_CHINA,'') AS CUSTOMER_NM_CHINA,
			PAY_ID,
			CHIT_ID,
			CHIT_TYPE,
			CHIT_NO,
			CHIT_YMD,
			VAT_CHIT_NO,
			VAT_YMD,
			DESCRIPTION_VIET,
			DESCRIPTION_ENG,
			DESCRIPTION_KOR,
			DESCRIPTION_CHINA,
			DAY_OF_PAYMENT,
			TIME_FOR_PAYMENT,
			AMOUNT,
			FC_AMOUNT,
			REMAINAMOUNT,
			REMAINAMOUNT_FC,
			PAYAMOUNT,
			PAYAMOUNT_FC
	FROM (			
		SELECT 
				COALESCE(MIN(P.CHITCOLLECT_ID),0) AS PAY_ID,
				-131 AS CHIT_ID,
				'-1' AS CHIT_TYPE,
				'' AS CHIT_NO,
				'' AS CHIT_YMD,
				A.CUSTOMER_ID,
				'' AS VAT_CHIT_NO,
				'' AS VAT_YMD,
				'Số dư đầu kỳ' AS DESCRIPTION_VIET,
				'Openning balance' AS DESCRIPTION_ENG, 	
				'기초잔액' AS DESCRIPTION_KOR,
				'期初余额' AS DESCRIPTION_CHINA,
				'' AS DAY_OF_PAYMENT,
				'' AS TIME_FOR_PAYMENT,
				AMOUNT,
				FC_AMOUNT,
				IFNULL(A.AMOUNT - IFNULL(SUM(P.COLLECTAMOUNT),0.0),0.0) as REMAINAMOUNT,
				IFNULL(A.FC_AMOUNT - IFNULL(SUM(P.COLLECTAMOUNT_FC),0.0),0.0) as REMAINAMOUNT_FC,
				0.0 AS PAYAMOUNT,
				0.0 AS PAYAMOUNT_FC
			FROM (
				SELECT 
					A.CUSTOMER_ID,
					IFNULL(SUM(A.DEBIT),0.0) AS AMOUNT,
					IFNULL(SUM(CASE WHEN A.FC_TYPE = @OpenFCType THEN A.DEBIT_FC ELSE 0 END),0.0) AS FC_AMOUNT
					FROM before_states_customer A
					WHERE A.ACC_CD like '",p_ACC_CD,"%' 
				    AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(A.CUSTOMER_ID AS CHAR), '",p_CUSTOMER_IDS,"') > 0) 
					AND IFNULL(A.ISDEL,'') !=1
					",@sWhereOpenFcType,"
					AND A.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," 
					GROUP BY A.CUSTOMER_ID
				) A
			LEFT JOIN chit_collect P ON ifnull(P.ISDEL,'') != '1' AND P.RECEIVABLES_CHIT_ID = -131 AND P.CUSTOMER_ID = A.CUSTOMER_ID AND P.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," 
			GROUP BY A.CUSTOMER_ID,AMOUNT,FC_AMOUNT
			",@sHaving," 

		UNION ALL
		SELECT 
			COALESCE(MIN(C.CHITCOLLECT_ID),0) AS PAY_ID,
			CHIT_ID,
			CHIT_TYPE,
			CHIT_NO,
			CHIT_YMD,
			F.CUSTOMER_ID,
			VAT_CHIT_NO,
			VAT_YMD,
			DESCRIPTION_VIET,
			DESCRIPTION_ENG,
			DESCRIPTION_KOR,
			DESCRIPTION_CHINA,
			DAY_OF_PAYMENT,
			TIME_FOR_PAYMENT,
			AMOUNT,
			FC_AMOUNT,
			AMOUNT -	IFNULL(SUM(C.COLLECTAMOUNT),0.0) as REMAINAMOUNT,
			FC_AMOUNT - IFNULL(SUM(C.COLLECTAMOUNT_FC),0.0) as REMAINAMOUNT_FC,
			0.0 AS PAYAMOUNT,
			0.0 AS PAYAMOUNT_FC
	FROM(
		SELECT 
					B.CHIT_ID,

					B.CHIT_TYPE,
					B.CHIT_NO,
					A.CHIT_YMD,
					AX.CUSTOMER_ID AS CUSTOMER_ID,
					IFNULL((SELECT V.VAT_CHIT_NO FROM chitdetailinfo C INNER JOIN chitdetailinfo_vat V ON V.COMPANY_CD = C.COMPANY_CD AND V.CHITDETAIL_ID = C.CHITDETAIL_ID WHERE IFNULL(C.ISDEL,'0') <> '1' AND IFNULL(V.VAT_CHIT_NO,'') <> '' AND C.CHIT_ID = A.CHIT_ID AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," ORDER BY C.CHITDETAIL_ID LIMIT 1),'') AS VAT_CHIT_NO,
					IFNULL((SELECT V.VAT_YMD FROM chitdetailinfo C INNER JOIN chitdetailinfo_vat V ON V.COMPANY_CD = C.COMPANY_CD AND V.CHITDETAIL_ID = C.CHITDETAIL_ID WHERE IFNULL(C.ISDEL,'0') <> '1' AND IFNULL(V.VAT_CHIT_NO,'') <> '' AND C.CHIT_ID = A.CHIT_ID AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," ORDER BY C.CHITDETAIL_ID LIMIT 1),'') AS VAT_YMD,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'VIET' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_VIET,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'ENG' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_ENG,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'KOR' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_KOR,
					(SELECT DS.DESCRIPTION FROM chitdescriptioninfo DS WHERE DS.CHIT_ID = B.CHIT_ID and DS.LANG_TYPE = 'CHINA' and (DS.ISDEL IS NULL OR DS.ISDEL != '1') AND DS.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," limit 1) AS DESCRIPTION_CHINA,
					IFNULL(BX.DAY_OF_PAYMENT,'') AS DAY_OF_PAYMENT,
					IFNULL(BX.TIME_FOR_PAYMENT,'') AS TIME_FOR_PAYMENT,
					IFNULL(SUM(A.AMOUNT),0.0) AS AMOUNT,
					IFNULL(SUM(A.FC_AMOUNT),0.0) AS FC_AMOUNT
				FROM chitdetailinfo A
                    INNER JOIN chitdetailinfo_ext AX ON AX.CHITDETAIL_ID = A.CHITDETAIL_ID AND AX.COMPANY_CD = A.COMPANY_CD
					LEFT JOIN chitinfo B ON B.CHIT_ID = A.CHIT_ID AND (B.ISDEL IS NULL OR B.ISDEL != '1') AND B.COMPANY_CD = ",QUOTE(p_COMPANY_CD),"
                    LEFT JOIN chitinfo_ext BX ON BX.CHIT_ID = B.CHIT_ID AND BX.COMPANY_CD = B.COMPANY_CD 
				WHERE  
					IFNULL(B.CHIT_NO,'')!=''				
					AND ('",p_CUSTOMER_IDS,"' = 'ALL' OR FIND_IN_SET(CAST(AX.CUSTOMER_ID AS CHAR), '",p_CUSTOMER_IDS,"') > 0)
					",@QueryYMD,"
					AND A.DEBIT LIKE '",p_ACC_CD,"%' 
					AND IFNULL(A.ISDEL,'0') != '1' 
					",@sWhereFcType," 
					AND A.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," 
				GROUP BY 	
					B.CHIT_ID,
					B.CHIT_NO,
					A.CHIT_YMD,
					AX.CUSTOMER_ID
	 ) F
	 	LEFT JOIN chit_collect C ON ifnull(C.ISDEL,'') != '1' AND C.RECEIVABLES_CHIT_ID = F.CHIT_ID AND F.CUSTOMER_ID = C.CUSTOMER_ID AND C.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," 
	 	GROUP BY CHIT_ID,F.CUSTOMER_ID
	 ) A
	 LEFT JOIN customer_info CUS1 ON A.CUSTOMER_ID = CUS1.CUSTOMER_ID AND IFNULL(CUS1.ISDEL,'0') != '1' AND CUS1.COMPANY_CD = ",QUOTE(p_COMPANY_CD)," 
	 WHERE CUS1.CUSTOMER_ID IS NOT NULL
	 	",@sHaving,"
	 ORDER BY CUSTOMER_ID,CHIT_YMD, CHIT_NO,TIME_FOR_PAYMENT;
		");
		PREPARE STMT FROM @V_SQL;
		EXECUTE STMT;
		DEALLOCATE PREPARE STMT;
	
	END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_chit_inventory_service_get
DROP PROCEDURE IF EXISTS `sp_chit_inventory_service_get`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_chit_inventory_service_get`(IN `p_COMPANY_CD` varchar(20), IN `p_FROM_YMD` varchar(8), IN `p_TO_YMD` varchar(8), IN `p_CUSTOMER_ID` bigint(20), IN `p_ALLOCATION_FILTER` tinyint(1))
BEGIN
	
			if(p_CUSTOMER_ID = 0 ) then 
				set p_CUSTOMER_ID = NULL;
			end if;
			
			SELECT
				B.CHIT_ID AS SERVICES_CHIT_ID,
				B.CHIT_CD AS SERVICES_CHIT_CD,
				B.CHIT_NO AS SERVICES_CHIT_NO,
				CHITDETAIL.CUSTOMER_ID AS CUSTOMER_ID,
				CUSTOMER.CUSTOMER_CD AS CUSTOMER_CD,
				cast(B.CHIT_YMD as datetime) as CHIT_YMD,
				VAT.VAT_CHIT_NO AS VAT_CHIT_NO,
				cast(VAT.VAT_YMD as datetime) as VAT_YMD,
				(select group_concat(cd.DESCRIPTION SEPARATOR '||') FROM chitdescriptioninfo cd WHERE cd.CHIT_ID = B.CHIT_ID AND IFNULL(cd.ISDEL,'') != '1' AND cd.COMPANY_CD = p_COMPANY_CD) as `CONTENTS`,
				CHITDETAIL.CHIT_AMOUNT AS TOTAL_COST,
				IF((CHITDETAIL.CHIT_AMOUNT -IFNULL(SERVICES.AMOUNT_SHARE,0.0)) < 0,CHITDETAIL.CHIT_AMOUNT,(CHITDETAIL.CHIT_AMOUNT -IFNULL(SERVICES.AMOUNT_SHARE,0.0))) as COST_NOT_YET_ALLOCATED,
				0.0 AS COST_NOW_ALLOCATES,
				IF((CHITDETAIL.CHIT_AMOUNT -IFNULL(SERVICES.AMOUNT_SHARE,0.0)) < 0,CHITDETAIL.CHIT_AMOUNT,(CHITDETAIL.CHIT_AMOUNT -IFNULL(SERVICES.AMOUNT_SHARE,0.0))) as COST_REMAIN
				
			FROM  CHITINFO B
				INNER JOIN 
				(
					SELECT A.CHIT_ID, IFNULL(SUM(A.AMOUNT),0) AS CHIT_AMOUNT,
					CASE WHEN MIN(IFNULL(AX.CUSTOMER_ID,0)) = MAX(IFNULL(AX.CUSTOMER_ID,0)) THEN NULLIF(MAX(AX.CUSTOMER_ID),0) ELSE NULL END AS CUSTOMER_ID
					FROM chitdetailinfo A
					LEFT JOIN chitdetailinfo_ext AX ON AX.CHITDETAIL_ID = A.CHITDETAIL_ID AND AX.COMPANY_CD = A.COMPANY_CD AND AX.ISDEL = '0'
					WHERE IFNULL(A.ISDEL,'0') != '1'
					AND (
					A.DEBIT like '151%' OR
					A.DEBIT like '152%' OR
					A.DEBIT like '153%' OR
					A.DEBIT like '155%' OR
					A.DEBIT like '156%' 
					)
					AND (p_CUSTOMER_ID IS NULL OR AX.CUSTOMER_ID = p_CUSTOMER_ID)
					AND A.COMPANY_CD = p_COMPANY_CD 
					GROUP BY A.CHIT_ID
				) AS CHITDETAIL ON CHITDETAIL.CHIT_ID = B.CHIT_ID 
				LEFT JOIN customer_info CUSTOMER ON CUSTOMER.CUSTOMER_ID = CHITDETAIL.CUSTOMER_ID AND CUSTOMER.COMPANY_CD = p_COMPANY_CD
				LEFT JOIN chitdetailinfo_vat VAT ON VAT.CHITDETAIL_ID = (
					SELECT A2.CHITDETAIL_ID FROM chitdetailinfo A2
					INNER JOIN chitdetailinfo_vat A2VAT ON A2VAT.CHITDETAIL_ID = A2.CHITDETAIL_ID AND A2VAT.COMPANY_CD = A2.COMPANY_CD AND IFNULL(A2VAT.ISDEL,'0') != '1'
					WHERE A2.CHIT_ID = B.CHIT_ID AND IFNULL(A2.ISDEL,'0') != '1'
					AND IFNULL(A2VAT.VAT_YMD,'') != '' AND IFNULL(A2VAT.VAT_CHIT_NO,'') != ''
					AND A2.COMPANY_CD = p_COMPANY_CD
					ORDER BY A2.CHITDETAIL_ID
					LIMIT 1
				) AND VAT.COMPANY_CD = p_COMPANY_CD AND IFNULL(VAT.ISDEL,'0') != '1'
				LEFT JOIN  
				
				(SELECT cs.CHIT_ID,SUM(cs.AMOUNT_SHARE) AS AMOUNT_SHARE 
				FROM chit_inventory_service cs 
				WHERE IFNULL(cs.ISDEL,'0') != '1'
				AND cs.COMPANY_CD = p_COMPANY_CD
				GROUP BY cs.CHIT_ID
				) AS SERVICES
				
				ON SERVICES.CHIT_ID = B.CHIT_ID 

				
			WHERE	B.CHIT_TYPE = 'PS'
					AND B.chit_ymd BETWEEN p_FROM_YMD AND p_TO_YMD						
					AND IFNULL(B.ISDEL,'0') != '1'
					AND B.COMPANY_CD = p_COMPANY_CD 
			HAVING (p_ALLOCATION_FILTER IS NULL OR (p_ALLOCATION_FILTER = 1 AND COST_NOT_YET_ALLOCATED = 0) OR (p_ALLOCATION_FILTER = 0 AND COST_NOT_YET_ALLOCATED <> 0))
			ORDER BY B.CHIT_YMD, B.CHIT_NO;
			
			SELECT cs.CHIT_ID AS SERVICES_CHIT_ID, cs.CHIT_CD AS SERVICES_CHIT_CD,c.CHIT_TYPE, c.CHIT_ID AS INVENTORY_CHIT_ID, c.CHIT_CD AS INVENTORY_CHIT_CD,c.CHIT_NO, CAST(c.CHIT_YMD AS DATETIME) AS CHIT_YMD, cs.AMOUNT_SHARE
			FROM chit_inventory_service cs
			INNER JOIN chitdetailinfo cd ON cd.CHITDETAIL_ID = cs.CHIT_DETAIL_ID AND cd.COMPANY_CD = p_COMPANY_CD 
			INNER JOIN chitinfo c ON c.CHIT_ID = cd.CHIT_ID AND c.COMPANY_CD = p_COMPANY_CD 
			WHERE IFNULL(cs.ISDEL,'') != '1' AND IFNULL(cd.ISDEL,'') != '1' AND IFNULL(c.ISDEL,'') != '1' 
			AND cs.COMPANY_CD = p_COMPANY_CD 
			ORDER BY c.CHIT_YMD,c.CHIT_NO;
		
	

END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_chit_payment_delete
DROP PROCEDURE IF EXISTS `sp_chit_payment_delete`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_chit_payment_delete`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_RECORD_ID BIGINT,
    IN p_USERID VARCHAR(50)
)
BEGIN
    DECLARE v_lock_name VARCHAR(64);
    DECLARE v_got_lock INT DEFAULT 0;
    DECLARE v_count INT DEFAULT 0;
    DECLARE v_pair_count INT DEFAULT 0;
    DECLARE v_src_id BIGINT;
    DECLARE v_debt_id BIGINT;
    DECLARE v_customer_id BIGINT;
    DECLARE v_amount DECIMAL(18,2);
    DECLARE v_amount_fc DECIMAL(18,2);
    DECLARE v_clear CHAR(1);
    DECLARE v_pair_id BIGINT;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
       ROLLBACK;
       IF v_got_lock=1 THEN DO RELEASE_LOCK(v_lock_name); END IF;
       RESIGNAL;
    END;
    IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD)='' OR COALESCE(p_RECORD_ID,0)<=0 THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Company and positive allocation ID required';
    END IF;
    SET v_lock_name=CONCAT('amnote_debt_',MD5(p_COMPANY_CD));
    SELECT GET_LOCK(v_lock_name,10) INTO v_got_lock;
    IF COALESCE(v_got_lock,0)<>1 THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Debt allocation busy; retry';
    END IF;
    START TRANSACTION;
    SELECT COUNT(*) INTO v_count FROM `chit_payment` P
      WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CHITPAYMENT_ID=p_RECORD_ID
        AND COALESCE(P.ISDEL,'0')<>'1';
    IF v_count=1 THEN
       SELECT P.PAY_CHIT_ID,P.DEBIT_CHIT_ID,P.CUSTOMER_ID,
              P.PAYAMOUNT,P.PAYAMOUNT_FC,P.IS_DEBT_CLEARING
       INTO v_src_id,v_debt_id,v_customer_id,v_amount,v_amount_fc,v_clear
       FROM `chit_payment` P
       WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CHITPAYMENT_ID=p_RECORD_ID FOR UPDATE;
       IF v_clear='1' THEN
          SELECT COUNT(*) INTO v_pair_count FROM `chit_payment` P
          WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CUSTOMER_ID=v_customer_id
            AND P.IS_DEBT_CLEARING='1' AND COALESCE(P.ISDEL,'0')<>'1'
            AND P.PAY_CHIT_ID=v_src_id AND P.DEBIT_CHIT_ID=v_debt_id;
          IF v_pair_count<>1 THEN
             SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Ambiguous original clearing rows';
          END IF;
          SELECT COUNT(*),COALESCE(MAX(T.CHITCOLLECT_ID),0) INTO v_pair_count,v_pair_id
          FROM `chit_collect` T
          WHERE T.COMPANY_CD=p_COMPANY_CD AND T.CUSTOMER_ID=v_customer_id
            AND T.IS_DEBT_CLEARING='1' AND COALESCE(T.ISDEL,'0')<>'1'
            AND T.RECEIVABLES_CHIT_ID=v_src_id AND T.COLLECT_CHIT_ID=v_debt_id
            AND T.COLLECTAMOUNT=v_amount AND T.COLLECTAMOUNT_FC=v_amount_fc;
          IF v_pair_count<>1 THEN
             SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Clearing pair missing/ambiguous; deletion aborted';
          END IF;
          -- Check for another active counterpart with different amount; do not conceal bad history.
          SELECT COUNT(*) INTO v_pair_count FROM `chit_collect` T
          WHERE T.COMPANY_CD=p_COMPANY_CD AND T.CUSTOMER_ID=v_customer_id
            AND T.IS_DEBT_CLEARING='1' AND COALESCE(T.ISDEL,'0')<>'1'
            AND T.RECEIVABLES_CHIT_ID=v_src_id AND T.COLLECT_CHIT_ID=v_debt_id;
          IF v_pair_count<>1 THEN
             SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Ambiguous clearing mirror';
          END IF;
       END IF;
       UPDATE `chit_payment` SET ISDEL='1',UPDATE_BY=COALESCE(p_USERID,'')
        WHERE COMPANY_CD=p_COMPANY_CD AND CHITPAYMENT_ID=p_RECORD_ID AND COALESCE(ISDEL,'0')<>'1';
       IF v_clear='1' THEN
          UPDATE `chit_collect` SET ISDEL='1',UPDATE_BY=COALESCE(p_USERID,'')
           WHERE COMPANY_CD=p_COMPANY_CD AND CHITCOLLECT_ID=v_pair_id AND COALESCE(ISDEL,'0')<>'1';
       END IF;
    END IF;
    COMMIT;
    DO RELEASE_LOCK(v_lock_name);
    SET v_got_lock=0;
    SELECT v_count AS DELETED_COUNT;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_chit_payment_upsert
DROP PROCEDURE IF EXISTS `sp_chit_payment_upsert`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_chit_payment_upsert`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_RECORD_ID BIGINT,
    IN p_SOURCE_CHIT_ID BIGINT,
    IN p_DEBT_CHIT_ID BIGINT,
    IN p_AMOUNT DECIMAL(18,2),
    IN p_AMOUNT_FC DECIMAL(18,2),
    IN p_IS_DEBT_CLEARING CHAR(1),
    IN p_CUSTOMER_ID BIGINT,
    IN p_FC_TYPE VARCHAR(3),
    IN p_USERID VARCHAR(50)
)
BEGIN
    DECLARE v_lock_name VARCHAR(64);
    DECLARE v_got_lock INT DEFAULT 0;
    DECLARE v_saved_id BIGINT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      IF v_got_lock=1 THEN DO RELEASE_LOCK(v_lock_name); END IF;
      RESIGNAL;
    END;
    IF p_IS_DEBT_CLEARING IS NULL OR p_IS_DEBT_CLEARING<>'0' THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Use sp_chit_clearing_upsert for clearing';
    END IF;
    IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD)='' THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Company required';
    END IF;
    SET v_lock_name=CONCAT('amnote_debt_',MD5(p_COMPANY_CD));
    SELECT GET_LOCK(v_lock_name,10) INTO v_got_lock;
    IF COALESCE(v_got_lock,0)<>1 THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Debt allocation busy; retry';
    END IF;
    START TRANSACTION;
    CALL sp_chit_payment_write_core(p_COMPANY_CD,p_RECORD_ID,p_SOURCE_CHIT_ID,p_DEBT_CHIT_ID,
      p_AMOUNT,p_AMOUNT_FC,'0',p_CUSTOMER_ID,p_FC_TYPE,p_USERID,v_saved_id);
    COMMIT;
    DO RELEASE_LOCK(v_lock_name);
    SET v_got_lock=0;
    SELECT v_saved_id AS `CHITPAYMENT_ID`;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_chit_payment_write_core
DROP PROCEDURE IF EXISTS `sp_chit_payment_write_core`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_chit_payment_write_core`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_RECORD_ID BIGINT,
    IN p_SOURCE_CHIT_ID BIGINT,
    IN p_DEBT_CHIT_ID BIGINT,
    IN p_AMOUNT DECIMAL(18,2),
    IN p_AMOUNT_FC DECIMAL(18,2),
    IN p_CLEAR CHAR(1),
    IN p_CUSTOMER_ID BIGINT,
    IN p_FC_TYPE VARCHAR(3),
    IN p_USERID VARCHAR(50),
    OUT p_SAVED_ID BIGINT
)
BEGIN
    DECLARE v_amount DECIMAL(24,2) DEFAULT 0;
    DECLARE v_amount_fc DECIMAL(24,2) DEFAULT 0;
    DECLARE v_fc VARCHAR(3);
    DECLARE v_found_id BIGINT DEFAULT 0;
    DECLARE v_found_amount DECIMAL(24,2) DEFAULT 0;
    DECLARE v_found_fc DECIMAL(24,2) DEFAULT 0;
    DECLARE v_count INT DEFAULT 0;
    DECLARE v_mirror_count INT DEFAULT 0;
    DECLARE v_mirror_amount DECIMAL(24,2) DEFAULT 0;
    DECLARE v_mirror_fc DECIMAL(24,2) DEFAULT 0;
    DECLARE v_total DECIMAL(24,2) DEFAULT 0;
    DECLARE v_total_fc DECIMAL(24,2) DEFAULT 0;
    DECLARE v_used DECIMAL(24,2) DEFAULT 0;
    DECLARE v_used_fc DECIMAL(24,2) DEFAULT 0;

    SET p_SAVED_ID = 0;
    SET v_amount = COALESCE(p_AMOUNT,0);
    SET v_amount_fc = COALESCE(p_AMOUNT_FC,0);
    SET v_fc = COALESCE(NULLIF(UPPER(TRIM(p_FC_TYPE)),''),'VND');

    IF p_COMPANY_CD IS NULL OR TRIM(p_COMPANY_CD)='' OR
       p_CUSTOMER_ID IS NULL OR p_CUSTOMER_ID <= 0 THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid company/customer';
    END IF;
    IF p_CLEAR NOT IN ('0','1') OR p_CLEAR IS NULL THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid clearing flag';
    END IF;
    IF v_amount < 0 OR v_amount_fc < 0 OR (v_amount=0 AND v_amount_fc=0) OR
       (v_fc='VND' AND v_amount_fc<>0) THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid allocation amounts';
    END IF;
    -- The signs of synthetic IDs are determined by accounting SIDE, not by the table alone.
    IF p_SOURCE_CHIT_ID IS NULL OR
       NOT (p_SOURCE_CHIT_ID>0 OR p_SOURCE_CHIT_ID=IF(p_CLEAR='1',-131,-331)) OR
       p_DEBT_CHIT_ID IS NULL OR
       NOT (p_DEBT_CHIT_ID>0 OR p_DEBT_CHIT_ID=-331) THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid CHIT_ID / opening balance';
    END IF;
    SELECT COUNT(*) INTO v_count FROM customer_info C
      WHERE C.COMPANY_CD=p_COMPANY_CD AND C.CUSTOMER_ID=p_CUSTOMER_ID
        AND COALESCE(C.ISDEL,'0')<>'1';
    IF v_count<>1 THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Customer not found';
    END IF;

    -- Existing PK is immutable identity, never restore a soft-deleted historical row.
    IF COALESCE(p_RECORD_ID,0)>0 THEN
       SELECT COUNT(*) INTO v_count FROM `chit_payment` P
       WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CHITPAYMENT_ID=p_RECORD_ID
         AND COALESCE(P.ISDEL,'0')<>'1'
         AND P.PAY_CHIT_ID=p_SOURCE_CHIT_ID AND P.DEBIT_CHIT_ID=p_DEBT_CHIT_ID
         AND P.CUSTOMER_ID=p_CUSTOMER_ID AND P.IS_DEBT_CLEARING=p_CLEAR;
       IF v_count<>1 THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Active allocation identity not found';
       END IF;
       SET v_found_id=p_RECORD_ID;
       SELECT P.PAYAMOUNT,P.PAYAMOUNT_FC INTO v_found_amount,v_found_fc
       FROM `chit_payment` P WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CHITPAYMENT_ID=v_found_id FOR UPDATE;
    ELSE
       -- Only active rows participate in deduplication; deleted records are immutable audit history.
       SELECT COUNT(*),COALESCE(MAX(P.CHITPAYMENT_ID),0) INTO v_count,v_found_id
       FROM `chit_payment` P
       WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CUSTOMER_ID=p_CUSTOMER_ID
         AND P.PAY_CHIT_ID=p_SOURCE_CHIT_ID AND P.DEBIT_CHIT_ID=p_DEBT_CHIT_ID
         AND P.IS_DEBT_CLEARING=p_CLEAR AND COALESCE(P.ISDEL,'0')<>'1';
       IF v_count>1 THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Duplicate active allocations; audit required';
       END IF;
       IF v_found_id>0 THEN
          SELECT P.PAYAMOUNT,P.PAYAMOUNT_FC INTO v_found_amount,v_found_fc
          FROM `chit_payment` P WHERE P.COMPANY_CD=p_COMPANY_CD AND P.CHITPAYMENT_ID=v_found_id FOR UPDATE;
          IF v_found_amount<>v_amount OR v_found_fc<>v_amount_fc THEN
             SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Allocation exists; pass its ID to update';
          END IF;
       END IF;
    END IF;
    IF p_CLEAR='1' AND v_found_id>0 AND
       (v_found_amount<>v_amount OR v_found_fc<>v_amount_fc) THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Delete and recreate clearing pair to change its amount';
    END IF;

    -- Mirror lookup uses CHIT_ID + CUSTOMER_ID only; legacy detail IDs are not keys.
    IF p_CLEAR='1' THEN
       SELECT COUNT(*),COALESCE(SUM(T.COLLECTAMOUNT),0),COALESCE(SUM(T.COLLECTAMOUNT_FC),0)
         INTO v_mirror_count,v_mirror_amount,v_mirror_fc
       FROM `chit_collect` T
       WHERE T.COMPANY_CD=p_COMPANY_CD AND T.CUSTOMER_ID=p_CUSTOMER_ID
         AND T.IS_DEBT_CLEARING='1' AND COALESCE(T.ISDEL,'0')<>'1'
         AND T.RECEIVABLES_CHIT_ID=p_SOURCE_CHIT_ID AND T.COLLECT_CHIT_ID=p_DEBT_CHIT_ID;
       IF v_mirror_count>1 OR
          (v_mirror_count=1 AND (v_mirror_amount<>v_amount OR v_mirror_fc<>v_amount_fc)) THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Clearing mirror missing/duplicate/mismatched';
       END IF;
    END IF;

    CALL sp_chit_debt_balance_calculate(p_COMPANY_CD,p_SOURCE_CHIT_ID,p_CUSTOMER_ID,
         IF(p_CLEAR='1','131','331'),'D',v_fc,v_total,v_total_fc,v_used,v_used_fc);
    IF p_CLEAR='1' AND v_mirror_count=1 THEN
       SET v_used=v_used-v_mirror_amount;
       SET v_used_fc=v_used_fc-v_mirror_fc;
    ELSE
       SET v_used=v_used-v_found_amount;
       SET v_used_fc=v_used_fc-v_found_fc;
    END IF;
    IF v_total+0.005<v_used+v_amount OR
       (v_amount_fc>0 AND v_total_fc+0.005<v_used_fc+v_amount_fc) THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Source balance exceeded';
    END IF;

    CALL sp_chit_debt_balance_calculate(p_COMPANY_CD,p_DEBT_CHIT_ID,p_CUSTOMER_ID,
         '331','C',v_fc,v_total,v_total_fc,v_used,v_used_fc);
    SET v_used=v_used-v_found_amount;
    SET v_used_fc=v_used_fc-v_found_fc;
    IF v_total+0.005<v_used+v_amount OR
       (v_amount_fc>0 AND v_total_fc+0.005<v_used_fc+v_amount_fc) THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Debt balance exceeded';
    END IF;

    IF v_found_id=0 THEN
       INSERT INTO `chit_payment` (COMPANY_CD,PAY_CHIT_ID,PAY_CHITDETAIL_ID,
          DEBIT_CHIT_ID,DEBIT_CHITDETAIL_ID,PAYAMOUNT,PAYAMOUNT_FC,
          IS_DEBT_CLEARING,CUSTOMER_ID,ISDEL,CREATE_BY,UPDATE_BY)
       VALUES(p_COMPANY_CD,p_SOURCE_CHIT_ID,0,p_DEBT_CHIT_ID,0,
          v_amount,v_amount_fc,p_CLEAR,p_CUSTOMER_ID,'0',
          COALESCE(p_USERID,''),COALESCE(p_USERID,''));
       SET v_found_id=LAST_INSERT_ID();
    ELSEIF v_found_amount<>v_amount OR v_found_fc<>v_amount_fc THEN
       UPDATE `chit_payment` SET PAYAMOUNT=v_amount,PAYAMOUNT_FC=v_amount_fc,
          UPDATE_BY=COALESCE(p_USERID,'')
       WHERE COMPANY_CD=p_COMPANY_CD AND CHITPAYMENT_ID=v_found_id AND COALESCE(ISDEL,'0')<>'1';
    END IF;
    SET p_SAVED_ID=v_found_id;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_fa_asset_alloc_get_by_asset
DROP PROCEDURE IF EXISTS `sp_fa_asset_alloc_get_by_asset`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_fa_asset_alloc_get_by_asset`(
    IN `p_COMPANY_CD` VARCHAR(20),
    IN `p_ASSET_ID` BIGINT
)
BEGIN
    SELECT
        A.ALLOC_ID,
        A.COMPANY_CD,
        A.ASSET_ID,
        A.ALLOC_SEQ,
        A.ALLOC_TYPE,
        A.ALLOC_RATE,
        A.FIRST_ALLOC_AMT,
        A.NORMAL_ALLOC_AMT,
        A.LAST_ALLOC_AMT,
        A.BALANCE_YN,

        A.DEBIT_ACCT_CD,
        IFNULL(B.ACCTITLE_NM_VIET, '')  AS DEBIT_ACC_NM_VIET,
        IFNULL(B.ACCTITLE_NM_ENG, '')   AS DEBIT_ACC_NM_ENG,
        IFNULL(B.ACCTITLE_NM_KOR, '')   AS DEBIT_ACC_NM_KOR,
        IFNULL(B.ACCTITLE_NM_CHINA, '') AS DEBIT_ACC_NM_CHINA,

        A.CREDIT_ACCT_CD,
        IFNULL(C.ACCTITLE_NM_VIET, '')  AS CREDIT_ACC_NM_VIET,
        IFNULL(C.ACCTITLE_NM_ENG, '')   AS CREDIT_ACC_NM_ENG,
        IFNULL(C.ACCTITLE_NM_KOR, '')   AS CREDIT_ACC_NM_KOR,
        IFNULL(C.ACCTITLE_NM_CHINA, '') AS CREDIT_ACC_NM_CHINA,

        A.DEPARTMENT_ID,
        IFNULL(D.DEPARTMENT_CD, '')  AS DEPARTMENT_CD,
        IFNULL(D.DEP_NAME_VIET, '')  AS DEP_NAME_VIET,
        IFNULL(D.DEP_NAME_ENG, '')   AS DEP_NAME_ENG,
        IFNULL(D.DEP_NAME_KOR, '')   AS DEP_NAME_KOR,
        IFNULL(D.DEP_NAME_CHINA, '') AS DEP_NAME_CHINA,
        A.NOTE
    FROM fa_asset_depre_alloc A
    LEFT JOIN acclist_info B 
        ON A.COMPANY_CD = B.COMPANY_CD 
       AND A.DEBIT_ACCT_CD = B.ACC_CD 
       AND IFNULL(B.ISDEL, '') <> '1'
       AND IFNULL(B.ISABLEINPUT, '') = '1'
    LEFT JOIN acclist_info C 
        ON A.COMPANY_CD = C.COMPANY_CD 
       AND A.CREDIT_ACCT_CD = C.ACC_CD 
       AND IFNULL(C.ISDEL, '') <> '1'
       AND IFNULL(C.ISABLEINPUT, '') = '1'
    LEFT JOIN department_info D
        ON A.COMPANY_CD = D.COMPANY_CD 
       AND A.DEPARTMENT_ID = D.DEPARTMENT_ID
       AND IFNULL(D.ISDEL, '') <> '1'
    WHERE A.COMPANY_CD = p_COMPANY_CD
      AND A.ASSET_ID = p_ASSET_ID
      AND A.ISDEL = '0'
    ORDER BY A.ALLOC_SEQ;
END//
DELIMITER ;


