-- Dumping structure for procedure am_web_001.sp_fa_asset_delete
DROP PROCEDURE IF EXISTS `sp_fa_asset_delete`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_fa_asset_delete`(
    IN `p_COMPANY_CD` VARCHAR(20),
    IN `p_ASSET_ID` BIGINT,
    IN `p_USER_ID` VARCHAR(50)
)
BEGIN
    DECLARE v_asset_rows INT DEFAULT 0;

    UPDATE fa_asset_depre_alloc
    SET ISDEL = '1',
        UPDATE_AT = NOW(),
        UPDATE_BY = p_USER_ID
    WHERE COMPANY_CD = p_COMPANY_CD
      AND ASSET_ID = p_ASSET_ID
      AND ISDEL = '0';

    UPDATE fa_asset
    SET ISDEL = '1',
        UPDATE_AT = NOW(),
        UPDATE_BY = p_USER_ID
    WHERE COMPANY_CD = p_COMPANY_CD
      AND ASSET_ID = p_ASSET_ID
      AND ISDEL = '0';

    SET v_asset_rows = ROW_COUNT();

    SELECT v_asset_rows AS AFFECTED_ROWS;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_fa_asset_get
DROP PROCEDURE IF EXISTS `sp_fa_asset_get`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_fa_asset_get`(
    IN `p_COMPANY_CD` VARCHAR(20),
    IN `p_ASSET_ID` BIGINT,
    IN `p_STATUS` VARCHAR(20),
    IN `p_ACC_CD` VARCHAR(20)
)
BEGIN
    SELECT
        A.ASSET_ID,
        A.COMPANY_CD,
        A.ASSET_CD,
        A.ASSET_NM,
        A.ACC_CD,
        IFNULL(B.ACCTITLE_NM_VIET, '') AS ACC_NM_VIET,
        IFNULL(B.ACCTITLE_NM_ENG, '') AS ACC_NM_ENG,
        IFNULL(B.ACCTITLE_NM_KOR, '') AS ACC_NM_KOR,
        IFNULL(B.ACCTITLE_NM_CHINA, '') AS ACC_NM_CHINA,
        A.USE_DEPT_CD,
        A.RECEIVE_YMD,
        A.USE_START_YMD,
        A.DEPRE_START_YM,
        A.DEPRE_END_YM,
        A.USEFUL_LIFE_MONTH,
        A.NORMAL_MONTH_COUNT,
        A.ORIGINAL_AMT,
        A.ACCUM_DEPRE_AMT,
        A.REMAIN_DEPRE_AMT,
        A.FIRST_DEPRE_AMT,
        A.NORMAL_DEPRE_AMT,
        A.LAST_DEPRE_AMT,
        A.ACQ_CHITINFO_ID,
        A.ACQ_CHITDETAIL_ID,
        A.ACQ_CHIT_NO,
        A.STATUS,
        '' as STATUS_TEXT,
        A.NOTE
    FROM fa_asset A
    LEFT JOIN acclist_info B
        ON A.COMPANY_CD = B.COMPANY_CD
       AND A.ACC_CD = B.ACC_CD
       AND IFNULL(B.ISDEL, '0') <> '1'
       AND IFNULL(B.ISABLEINPUT, '0') = '1'
    WHERE A.COMPANY_CD = p_COMPANY_CD
      AND IFNULL(A.ISDEL, '0') = '0'

      AND (
            p_ASSET_ID IS NULL
            OR A.ASSET_ID = p_ASSET_ID
          )

      AND (
            p_ASSET_ID IS NOT NULL
            OR p_STATUS IS NULL
            OR p_STATUS = ''
            OR A.STATUS = p_STATUS
          )

      AND (
            p_ASSET_ID IS NOT NULL
            OR p_ACC_CD IS NULL
            OR p_ACC_CD = ''
            OR A.ACC_CD = p_ACC_CD
          )

    ORDER BY A.ASSET_CD;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_fa_asset_insert
DROP PROCEDURE IF EXISTS `sp_fa_asset_insert`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_fa_asset_insert`(
    IN `p_COMPANY_CD` VARCHAR(20),
    IN `p_ASSET_CD` VARCHAR(50),
    IN `p_ASSET_NM` VARCHAR(255),
    IN `p_ACC_CD` VARCHAR(7),
