    IN `p_DEPRE_END_YM` CHAR(6),
    IN `p_USEFUL_LIFE_MONTH` DECIMAL(10,2),
    IN `p_NORMAL_MONTH_COUNT` INT,
    IN `p_ORIGINAL_AMT` DECIMAL(18,2),
    IN `p_ACCUM_DEPRE_AMT` DECIMAL(18,2),
    IN `p_REMAIN_DEPRE_AMT` DECIMAL(18,2),
    IN `p_FIRST_DEPRE_AMT` DECIMAL(18,2),
    IN `p_NORMAL_DEPRE_AMT` DECIMAL(18,2),
    IN `p_LAST_DEPRE_AMT` DECIMAL(18,2),
    IN `p_ACQ_CHITINFO_ID` BIGINT,
    IN `p_ACQ_CHITDETAIL_ID` BIGINT,
    IN `p_ACQ_CHIT_NO` VARCHAR(100),
    IN `p_STATUS` VARCHAR(20),
    IN `p_NOTE` VARCHAR(500),
    IN `p_USER_ID` VARCHAR(50)
)
BEGIN
    INSERT INTO fa_asset
    (
        COMPANY_CD,
        ASSET_CD,
        ASSET_NM,
        ACC_CD,
        USE_DEPT_CD,
        RECEIVE_YMD,
        USE_START_YMD,
        DEPRE_START_YM,
        DEPRE_END_YM,
        USEFUL_LIFE_MONTH,
        NORMAL_MONTH_COUNT,
        ORIGINAL_AMT,
        ACCUM_DEPRE_AMT,
        REMAIN_DEPRE_AMT,
        FIRST_DEPRE_AMT,
        NORMAL_DEPRE_AMT,
        LAST_DEPRE_AMT,
        ACQ_CHITINFO_ID,
        ACQ_CHITDETAIL_ID,
        ACQ_CHIT_NO,
        STATUS,
        NOTE,
        ISDEL,
        CREATE_AT,
        CREATE_BY
    )
    VALUES
    (
        p_COMPANY_CD,
        p_ASSET_CD,
        p_ASSET_NM,
        p_ACC_CD,
        p_USE_DEPT_CD,
        p_RECEIVE_YMD,
        p_USE_START_YMD,
        p_DEPRE_START_YM,
        p_DEPRE_END_YM,
        p_USEFUL_LIFE_MONTH,
        p_NORMAL_MONTH_COUNT,
        p_ORIGINAL_AMT,
        p_ACCUM_DEPRE_AMT,
        p_REMAIN_DEPRE_AMT,
        p_FIRST_DEPRE_AMT,
        p_NORMAL_DEPRE_AMT,
        p_LAST_DEPRE_AMT,
        p_ACQ_CHITINFO_ID,
        p_ACQ_CHITDETAIL_ID,
        p_ACQ_CHIT_NO,
        p_STATUS,
        p_NOTE,
        '0',
        NOW(),
        p_USER_ID
    );

    SELECT LAST_INSERT_ID() AS ASSET_ID;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_fa_asset_update
DROP PROCEDURE IF EXISTS `sp_fa_asset_update`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_fa_asset_update`(
    IN `p_ASSET_ID` BIGINT,
    IN `p_COMPANY_CD` VARCHAR(20),
    IN `p_ASSET_CD` VARCHAR(50),
    IN `p_ASSET_NM` VARCHAR(255),
    IN `p_ACC_CD` VARCHAR(7),
    IN `p_USE_DEPT_CD` VARCHAR(50),
    IN `p_RECEIVE_YMD` CHAR(8),
    IN `p_USE_START_YMD` CHAR(8),
    IN `p_DEPRE_START_YM` CHAR(6),
    IN `p_DEPRE_END_YM` CHAR(6),
    IN `p_USEFUL_LIFE_MONTH` DECIMAL(10,2),
    IN `p_NORMAL_MONTH_COUNT` INT,
    IN `p_ORIGINAL_AMT` DECIMAL(18,2),
    IN `p_ACCUM_DEPRE_AMT` DECIMAL(18,2),
    IN `p_REMAIN_DEPRE_AMT` DECIMAL(18,2),
    IN `p_FIRST_DEPRE_AMT` DECIMAL(18,2),
    IN `p_NORMAL_DEPRE_AMT` DECIMAL(18,2),
    IN `p_LAST_DEPRE_AMT` DECIMAL(18,2),
    IN `p_ACQ_CHITINFO_ID` BIGINT,
    IN `p_ACQ_CHITDETAIL_ID` BIGINT,
    IN `p_ACQ_CHIT_NO` VARCHAR(100),
    IN `p_STATUS` VARCHAR(20),
    IN `p_NOTE` VARCHAR(500),
    IN `p_USER_ID` VARCHAR(50)
)
BEGIN
    UPDATE fa_asset
    SET
        ASSET_CD = p_ASSET_CD,
        ASSET_NM = p_ASSET_NM,
        ACC_CD = p_ACC_CD,
        USE_DEPT_CD = p_USE_DEPT_CD,
        RECEIVE_YMD = p_RECEIVE_YMD,
        USE_START_YMD = p_USE_START_YMD,
        DEPRE_START_YM = p_DEPRE_START_YM,
        DEPRE_END_YM = p_DEPRE_END_YM,
        USEFUL_LIFE_MONTH = p_USEFUL_LIFE_MONTH,
        NORMAL_MONTH_COUNT = p_NORMAL_MONTH_COUNT,
        ORIGINAL_AMT = p_ORIGINAL_AMT,
        ACCUM_DEPRE_AMT = p_ACCUM_DEPRE_AMT,
        REMAIN_DEPRE_AMT = p_REMAIN_DEPRE_AMT,
        FIRST_DEPRE_AMT = p_FIRST_DEPRE_AMT,
        NORMAL_DEPRE_AMT = p_NORMAL_DEPRE_AMT,
        LAST_DEPRE_AMT = p_LAST_DEPRE_AMT,
        ACQ_CHITINFO_ID = p_ACQ_CHITINFO_ID,
        ACQ_CHITDETAIL_ID = p_ACQ_CHITDETAIL_ID,
        ACQ_CHIT_NO = p_ACQ_CHIT_NO,
        STATUS = p_STATUS,
        NOTE = p_NOTE,
        UPDATE_AT = NOW(),
        UPDATE_BY = p_USER_ID
    WHERE COMPANY_CD = p_COMPANY_CD
      AND ASSET_ID = p_ASSET_ID
      AND ISDEL = '0';
END//
DELIMITER ;


