-- Dumping structure for procedure am_web_001.sp_master_check_in_use
DROP PROCEDURE IF EXISTS `sp_master_check_in_use`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_master_check_in_use`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_MASTER_TYPE VARCHAR(50),
    IN p_MASTER_ID BIGINT,
    IN p_MASTER_CD VARCHAR(100)
)
BEGIN
    DECLARE v_TYPE VARCHAR(50) DEFAULT '';
    DECLARE v_CD VARCHAR(100) DEFAULT '';
    DECLARE v_IS_USED CHAR(1) DEFAULT 'N';
    DECLARE v_USED_TABLE VARCHAR(100) DEFAULT '';
    DECLARE v_MESSAGE VARCHAR(255) DEFAULT '';

    SET v_TYPE = LOWER(TRIM(IFNULL(p_MASTER_TYPE, '')));
    SET v_CD = TRIM(IFNULL(p_MASTER_CD, ''));

    IF v_TYPE = 'store' OR v_TYPE = 'warehouse' THEN
        IF EXISTS (
            SELECT 1
            FROM chit_inventory_input
            WHERE COMPANY_CD = p_COMPANY_CD
              AND (STORE_ID = p_MASTER_ID OR (v_CD <> '' AND STORE_CD = v_CD))
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'chit_inventory_input';
            SET v_MESSAGE = 'Kho đã phát sinh phiếu nhập kho.';
        ELSEIF EXISTS (
            SELECT 1
            FROM chit_inventory_output
            WHERE COMPANY_CD = p_COMPANY_CD
              AND (STORE_ID = p_MASTER_ID OR (v_CD <> '' AND STORE_CD = v_CD))
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'chit_inventory_output';
            SET v_MESSAGE = 'Kho đã phát sinh phiếu xuất kho.';
        ELSEIF EXISTS (
            SELECT 1
            FROM product_info
            WHERE COMPANY_CD = p_COMPANY_CD
              AND STORE_ID = p_MASTER_ID
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'product_info';
            SET v_MESSAGE = 'Kho đang được gán cho hàng hóa.';
        END IF;
    ELSEIF v_TYPE = 'store_kind' OR v_TYPE = 'warehouse_kind' THEN
        IF EXISTS (
            SELECT 1
            FROM store_info
            WHERE COMPANY_CD = p_COMPANY_CD
              AND STORE_KIND_ID = p_MASTER_ID
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'store_info';
            SET v_MESSAGE = 'Loại kho đang được gán cho kho.';
        END IF;
    ELSEIF v_TYPE = 'account' THEN
        IF EXISTS (
            SELECT 1
            FROM acclist_info
            WHERE COMPANY_CD = p_COMPANY_CD
              AND ACC_PARENT_ID = p_MASTER_ID
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'acclist_info';
            SET v_MESSAGE = 'Tài khoản đang có tài khoản con.';
        ELSEIF EXISTS (
            SELECT 1
            FROM chitdetailinfo
            WHERE COMPANY_CD = p_COMPANY_CD
              AND (DEBIT = v_CD OR CREDIT = v_CD)
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'chitdetailinfo';
            SET v_MESSAGE = 'Tài khoản đã phát sinh chứng từ.';
        ELSEIF EXISTS (
            SELECT 1
            FROM before_states
            WHERE COMPANY_CD = p_COMPANY_CD
              AND ACC_CD = v_CD
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'before_states';
            SET v_MESSAGE = 'Tài khoản đã có số dư đầu kỳ.';
        ELSEIF EXISTS (
            SELECT 1
            FROM before_states_bank
            WHERE COMPANY_CD = p_COMPANY_CD
              AND ACC_CD = v_CD
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'before_states_bank';
            SET v_MESSAGE = 'Tài khoản đã có số dư đầu kỳ ngân hàng.';
        ELSEIF EXISTS (
            SELECT 1
            FROM before_states_customer
            WHERE COMPANY_CD = p_COMPANY_CD
              AND ACC_CD = v_CD
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'before_states_customer';
            SET v_MESSAGE = 'Tài khoản đã có số dư đầu kỳ công nợ.';
        ELSEIF EXISTS (
            SELECT 1
            FROM before_states_department
            WHERE COMPANY_CD = p_COMPANY_CD
              AND ACC_CD = v_CD
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'before_states_department';
            SET v_MESSAGE = 'Tài khoản đã có số dư đầu kỳ đối tượng.';
        ELSEIF EXISTS (
            SELECT 1
            FROM bank_info
            WHERE COMPANY_CD = p_COMPANY_CD
              AND ACC_CD = v_CD
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'bank_info';
            SET v_MESSAGE = 'Tài khoản đang được gán cho ngân hàng.';
        END IF;
    ELSEIF v_TYPE = 'product' OR v_TYPE = 'item' THEN
        IF EXISTS (
            SELECT 1
            FROM chit_inventory_input
            WHERE COMPANY_CD = p_COMPANY_CD
              AND (PRODUCT_ID = p_MASTER_ID OR (v_CD <> '' AND PRODUCT_CD = v_CD))
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'chit_inventory_input';
            SET v_MESSAGE = 'Hàng hóa đã phát sinh nhập kho.';
        ELSEIF EXISTS (
            SELECT 1
            FROM chit_inventory_output
            WHERE COMPANY_CD = p_COMPANY_CD
              AND (PRODUCT_ID = p_MASTER_ID OR (v_CD <> '' AND PRODUCT_CD = v_CD))
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'chit_inventory_output';
            SET v_MESSAGE = 'Hàng hóa đã phát sinh xuất kho.';
        END IF;
    ELSEIF v_TYPE = 'product_kind' THEN
        IF EXISTS (
            SELECT 1
            FROM product_info
            WHERE COMPANY_CD = p_COMPANY_CD
              AND PRODUCT_KIND_ID = p_MASTER_ID
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'product_info';
            SET v_MESSAGE = 'Nhóm vật tư đang được gán cho hàng hóa.';
        END IF;
    ELSEIF v_TYPE = 'product_unit' OR v_TYPE = 'unit' THEN
        IF EXISTS (
            SELECT 1
            FROM product_info
            WHERE COMPANY_CD = p_COMPANY_CD
              AND UNIT_ID = p_MASTER_ID
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'product_info';
            SET v_MESSAGE = 'Đơn vị tính đang được gán cho hàng hóa.';
        ELSEIF EXISTS (
            SELECT 1
            FROM chit_inventory_input
            WHERE COMPANY_CD = p_COMPANY_CD
              AND (UNIT_ID = p_MASTER_ID OR (v_CD <> '' AND UNIT_CD = v_CD))
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'chit_inventory_input';
            SET v_MESSAGE = 'Đơn vị tính đã phát sinh nhập kho.';
        ELSEIF EXISTS (
            SELECT 1
            FROM chit_inventory_output
            WHERE COMPANY_CD = p_COMPANY_CD
              AND (UNIT_ID = p_MASTER_ID OR (v_CD <> '' AND UNIT_CD = v_CD))
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'chit_inventory_output';
            SET v_MESSAGE = 'Đơn vị tính đã phát sinh xuất kho.';
        END IF;
    ELSEIF v_TYPE = 'bank' THEN
        IF EXISTS (
            SELECT 1
            FROM chitdetailinfo_ext
            WHERE COMPANY_CD = p_COMPANY_CD
              AND (BANK_ID = p_MASTER_ID OR (v_CD <> '' AND BANK_CD = v_CD))
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'chitdetailinfo_ext';
            SET v_MESSAGE = 'Ngân hàng đã phát sinh chứng từ.';
        ELSEIF EXISTS (
            SELECT 1
            FROM before_states_bank
            WHERE COMPANY_CD = p_COMPANY_CD
              AND BANK_ID = p_MASTER_ID
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'before_states_bank';
            SET v_MESSAGE = 'Ngân hàng đã có số dư đầu kỳ.';
        END IF;
    ELSEIF v_TYPE = 'customer' THEN
        IF EXISTS (
            SELECT 1
            FROM chitdetailinfo_ext
            WHERE COMPANY_CD = p_COMPANY_CD
              AND (CUSTOMER_ID = p_MASTER_ID OR (v_CD <> '' AND CUSTOMER_CD = v_CD))
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'chitdetailinfo_ext';
            SET v_MESSAGE = 'Đối tượng đã phát sinh chứng từ.';
        ELSEIF EXISTS (
            SELECT 1
            FROM before_states_customer
            WHERE COMPANY_CD = p_COMPANY_CD
              AND CUSTOMER_ID = p_MASTER_ID
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'before_states_customer';
            SET v_MESSAGE = 'Đối tượng tập hợp chi phí đã có số dư đầu kỳ.';
        END IF;
    ELSEIF v_TYPE = 'department' THEN
        IF EXISTS (
            SELECT 1
            FROM chitdetailinfo_ext
            WHERE COMPANY_CD = p_COMPANY_CD
              AND (DEPARTMENT_ID = p_MASTER_ID OR (v_CD <> '' AND DEPARTMENT_CD = v_CD))
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'chitdetailinfo_ext';
            SET v_MESSAGE = 'Đối tượng tập hợp chi phí đã phát sinh chứng từ.';
        ELSEIF EXISTS (
            SELECT 1
            FROM before_states_department
            WHERE COMPANY_CD = p_COMPANY_CD
              AND DEPARTMENT_ID = p_MASTER_ID
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'before_states_department';
            SET v_MESSAGE = 'Đối tượng tập hợp chi phí đã có số dư đầu kỳ.';
        END IF;
    ELSEIF v_TYPE = 'management' THEN
        IF EXISTS (
            SELECT 1
            FROM chitdetailinfo_ext
            WHERE COMPANY_CD = p_COMPANY_CD
              AND (MG_CD = v_CD OR MG_CD_2 = v_CD)
              AND IFNULL(ISDEL, '0') <> '1'
            LIMIT 1
        ) THEN
            SET v_IS_USED = 'Y';
            SET v_USED_TABLE = 'chitdetailinfo_ext';
            SET v_MESSAGE = 'Mã quản lý đã phát sinh chứng từ.';
        END IF;
    ELSE
        SET v_IS_USED = 'N';
        SET v_USED_TABLE = '';
        SET v_MESSAGE = 'Loại danh mục chưa được cấu hình check sử dụng.';
    END IF;

    SELECT v_IS_USED AS IS_USED, v_USED_TABLE AS USED_TABLE, v_MESSAGE AS MESSAGE;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_closingmonth_delete
DROP PROCEDURE IF EXISTS `sp_period_lock_closingmonth_delete`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_closingmonth_delete`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6)
)
BEGIN
    DECLARE v_last_day DATE;
    DECLARE v_close_ymd CHAR(8);

    CALL sp_period_lock_fa_prepaid_last_day(p_PERIOD_YM, v_last_day);
    SET v_close_ymd = DATE_FORMAT(v_last_day, '%Y%m%d');

    DELETE
    FROM closingmonth_detail
    WHERE COMPANY_CD = p_COMPANY_CD
      AND CLOSE_YMD = v_close_ymd;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_closingmonth_snapshot
DROP PROCEDURE IF EXISTS `sp_period_lock_closingmonth_snapshot`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_closingmonth_snapshot`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6),
    IN p_BALANCE_METHOD VARCHAR(50),
    IN p_USER_ID VARCHAR(50)
)
BEGIN
    DECLARE v_from_ymd CHAR(8);
    DECLARE v_to_ymd CHAR(8);
    DECLARE v_prev_from_ymd CHAR(8);

    DECLARE v_prev_close_ymd CHAR(8) DEFAULT NULL;
    DECLARE v_open_ymd CHAR(8) DEFAULT NULL;
    DECLARE v_begin_move_from_ymd CHAR(8) DEFAULT NULL;

    /* Ngày đầu kỳ kế toán / ngày carry forward */
    DECLARE v_carryforward_ymd CHAR(8) DEFAULT NULL;

    /*
        = 1:
        Đây là kỳ đầu tiên, ngày cuối tháng chính là CARRYFORWARD_YMD.

        Ví dụ:
            CARRYFORWARD_YMD = 20251231
            p_PERIOD_YM      = 202512

        Khi đó:
            closingmonth_detail 31/12/2025
            chỉ lấy từ before_states*
            KHÔNG lấy chitinfo/chitdetailinfo.
    */
    DECLARE v_is_carryforward_period TINYINT DEFAULT 0;


    /* =========================================================
       1. XÁC ĐỊNH KHOẢNG THỜI GIAN
       ========================================================= */

    SET v_from_ymd = CONCAT(p_PERIOD_YM, '01');

    SET v_to_ymd = DATE_FORMAT(
        LAST_DAY(
            STR_TO_DATE(CONCAT(p_PERIOD_YM, '01'), '%Y%m%d')
        ),
        '%Y%m%d'
    );

    SET v_prev_from_ymd = DATE_FORMAT(
        DATE_SUB(
            STR_TO_DATE(v_from_ymd, '%Y%m%d'),
            INTERVAL 1 DAY
        ),
        '%Y%m%d'
    );


    /* =========================================================
       2. LẤY NGÀY CARRY FORWARD CỦA CÔNG TY
       ========================================================= */

    SELECT MAX(CARRYFORWARD_YMD)
      INTO v_carryforward_ymd
    FROM am_web_manager.company_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND IFNULL(ISDEL, '0') = '0';


    /*
        Chỉ xem là kỳ carry-forward khi ngày carryforward
        chính bằng ngày cuối tháng đang khóa.

        Ví dụ:
            v_to_ymd            = 20251231
            v_carryforward_ymd  = 20251231
            => kỳ đặc biệt
    */
    IF v_carryforward_ymd IS NOT NULL
       AND v_carryforward_ymd <> ''
       AND v_to_ymd = v_carryforward_ymd THEN

        SET v_is_carryforward_period = 1;

    ELSE

        SET v_is_carryforward_period = 0;

    END IF;


    /* =========================================================
       3. XÓA SNAPSHOT CŨ CỦA KỲ ĐANG CHẠY
       ========================================================= */

    DELETE
    FROM closingmonth_detail
    WHERE COMPANY_CD = p_COMPANY_CD
      AND CLOSE_YMD = v_to_ymd;


    /* =========================================================
       4. TÌM KỲ CLOSING GẦN NHẤT TRƯỚC KỲ HIỆN TẠI
       ========================================================= */

    SELECT MAX(CLOSE_YMD)
      INTO v_prev_close_ymd
    FROM closingmonth_detail
    WHERE COMPANY_CD = p_COMPANY_CD
      AND ISDEL = '0'
      AND CLOSE_YMD < v_from_ymd;


    /* =========================================================
       5. TEMP TABLE: SỐ DƯ GỐC
       ========================================================= */

    DROP TEMPORARY TABLE IF EXISTS tmp_cm_begin_base;

    CREATE TEMPORARY TABLE tmp_cm_begin_base
    (
        ACCOUNT_CD VARCHAR(20) NOT NULL DEFAULT '',
        BEGIN_DEBIT DECIMAL(18,6) NOT NULL DEFAULT 0,
        BEGIN_CREDIT DECIMAL(18,6) NOT NULL DEFAULT 0,

        PRIMARY KEY (ACCOUNT_CD)
    )
    ENGINE=InnoDB
    DEFAULT CHARSET=utf8
    COLLATE=utf8_unicode_ci;


    /* =========================================================
       6. TEMP TABLE: PHÁT SINH TỪ MỐC SỐ DƯ ĐẾN TRƯỚC KỲ
       ========================================================= */

    DROP TEMPORARY TABLE IF EXISTS tmp_cm_begin_move;

    CREATE TEMPORARY TABLE tmp_cm_begin_move
    (
        ACCOUNT_CD VARCHAR(20) NOT NULL DEFAULT '',
        PERIOD_DEBIT DECIMAL(18,6) NOT NULL DEFAULT 0,
        PERIOD_CREDIT DECIMAL(18,6) NOT NULL DEFAULT 0,

        PRIMARY KEY (ACCOUNT_CD)
    )
    ENGINE=InnoDB
    DEFAULT CHARSET=utf8
    COLLATE=utf8_unicode_ci;


    /* =========================================================
       7. TEMP TABLE: PHÁT SINH TRONG KỲ
       ========================================================= */

    DROP TEMPORARY TABLE IF EXISTS tmp_cm_period_amount;

    CREATE TEMPORARY TABLE tmp_cm_period_amount
    (
        ACCOUNT_CD VARCHAR(20) NOT NULL DEFAULT '',
        PERIOD_DEBIT DECIMAL(18,6) NOT NULL DEFAULT 0,
        PERIOD_CREDIT DECIMAL(18,6) NOT NULL DEFAULT 0,

        PRIMARY KEY (ACCOUNT_CD)
    )
    ENGINE=InnoDB
    DEFAULT CHARSET=utf8
    COLLATE=utf8_unicode_ci;


    /* =========================================================
       8. XỬ LÝ KỲ CARRY FORWARD
       ========================================================= */

    IF v_is_carryforward_period = 1 THEN

        /*
            =====================================================
            KỲ ĐẦU TIÊN

            Ví dụ:
                CARRYFORWARD_YMD = 20251231
                khóa             = 202512

            Số dư 31/12/2025 chỉ lấy từ:

                before_states
                before_states_bank
                before_states_customer
                before_states_department

            KHÔNG:
                - lấy chứng từ trước kỳ
                - lấy chứng từ trong kỳ
            =====================================================
        */

        SET v_open_ymd = v_carryforward_ymd;


        INSERT INTO tmp_cm_begin_base
        (
            ACCOUNT_CD,
            BEGIN_DEBIT,
            BEGIN_CREDIT
        )
        SELECT
            X.ACC_CD,
            SUM(IFNULL(X.DEBIT, 0)),
            SUM(IFNULL(X.CREDIT, 0))
        FROM
        (
            /* Số dư tài khoản */
            SELECT
                ACC_CD,
                DEBIT,
                CREDIT
            FROM before_states
            WHERE COMPANY_CD = p_COMPANY_CD
              AND ISDEL = '0'
              AND OPEN_YMD = v_open_ymd
              AND IFNULL(ACC_CD, '') <> ''


            UNION ALL


            /* Số dư ngân hàng */
            SELECT
                ACC_CD,
                DEBIT,
                CREDIT
            FROM before_states_bank
            WHERE COMPANY_CD = p_COMPANY_CD
              AND ISDEL = '0'
              AND OPEN_YMD = v_open_ymd
              AND IFNULL(ACC_CD, '') <> ''


            UNION ALL


            /* Số dư khách hàng */
            SELECT
                ACC_CD,
                DEBIT,
                CREDIT
            FROM before_states_customer
            WHERE COMPANY_CD = p_COMPANY_CD
              AND ISDEL = '0'
              AND OPEN_YMD = v_open_ymd
              AND IFNULL(ACC_CD, '') <> ''


            UNION ALL


            /* Số dư phòng ban */
            SELECT
                ACC_CD,
                DEBIT,
                CREDIT
            FROM before_states_department
            WHERE COMPANY_CD = p_COMPANY_CD
              AND ISDEL = '0'
              AND OPEN_YMD = v_open_ymd
              AND IFNULL(ACC_CD, '') <> ''

        ) X
        GROUP BY X.ACC_CD;


        /*
            QUAN TRỌNG:

            Không INSERT vào:
                tmp_cm_begin_move
                tmp_cm_period_amount

            => không đọc chitinfo / chitdetailinfo.
        */


    ELSE

        /* =====================================================
           9. KỲ BÌNH THƯỜNG
           ===================================================== */


        /*
            Có closingmonth trước đó
            => dùng closingmonth_detail làm số dư nền.
        */
        IF v_prev_close_ymd IS NOT NULL THEN

            INSERT INTO tmp_cm_begin_base
            (
                ACCOUNT_CD,
                BEGIN_DEBIT,
                BEGIN_CREDIT
            )
            SELECT
                ACC_CD,
                SUM(DEBIT),
                SUM(CREDIT)
            FROM closingmonth_detail
            WHERE COMPANY_CD = p_COMPANY_CD
              AND ISDEL = '0'
              AND CLOSE_YMD = v_prev_close_ymd
              AND IFNULL(ACC_CD, '') <> ''
            GROUP BY ACC_CD;


            /*
                Bắt đầu lấy phát sinh
                từ ngày sau closing gần nhất.
            */
            SET v_begin_move_from_ymd = DATE_FORMAT(
                DATE_ADD(
                    STR_TO_DATE(v_prev_close_ymd, '%Y%m%d'),
                    INTERVAL 1 DAY
                ),
                '%Y%m%d'
            );


        ELSE

            /*
                Chưa từng closing.

                Tìm số dư đầu kỳ gần nhất
                trước hoặc tại ngày đầu tháng đang khóa.

                Phần này giữ nguyên logic cũ.
            */

            SELECT MAX(OPEN_YMD)
              INTO v_open_ymd
            FROM
            (
                SELECT MAX(OPEN_YMD) AS OPEN_YMD
                FROM before_states
                WHERE COMPANY_CD = p_COMPANY_CD
                  AND ISDEL = '0'
                  AND OPEN_YMD <= v_from_ymd


                UNION ALL


                SELECT MAX(OPEN_YMD) AS OPEN_YMD
                FROM before_states_bank
                WHERE COMPANY_CD = p_COMPANY_CD
                  AND ISDEL = '0'
                  AND OPEN_YMD <= v_from_ymd


                UNION ALL


                SELECT MAX(OPEN_YMD) AS OPEN_YMD
                FROM before_states_customer
                WHERE COMPANY_CD = p_COMPANY_CD
                  AND ISDEL = '0'
                  AND OPEN_YMD <= v_from_ymd


                UNION ALL


                SELECT MAX(OPEN_YMD) AS OPEN_YMD
                FROM before_states_department
                WHERE COMPANY_CD = p_COMPANY_CD
                  AND ISDEL = '0'
                  AND OPEN_YMD <= v_from_ymd

            ) T
            WHERE OPEN_YMD IS NOT NULL;


            IF v_open_ymd IS NOT NULL THEN

                INSERT INTO tmp_cm_begin_base
                (
                    ACCOUNT_CD,
                    BEGIN_DEBIT,
                    BEGIN_CREDIT
                )
                SELECT
                    X.ACC_CD,
                    SUM(X.DEBIT),
                    SUM(X.CREDIT)
                FROM
                (
                    SELECT
                        ACC_CD,
                        DEBIT,
                        CREDIT
                    FROM before_states
                    WHERE COMPANY_CD = p_COMPANY_CD
                      AND ISDEL = '0'
                      AND OPEN_YMD = v_open_ymd
                      AND IFNULL(ACC_CD, '') <> ''


                    UNION ALL


                    SELECT
                        ACC_CD,
                        DEBIT,
                        CREDIT
                    FROM before_states_bank
                    WHERE COMPANY_CD = p_COMPANY_CD
                      AND ISDEL = '0'
                      AND OPEN_YMD = v_open_ymd
                      AND IFNULL(ACC_CD, '') <> ''


                    UNION ALL


                    SELECT
                        ACC_CD,
                        DEBIT,
                        CREDIT
                    FROM before_states_customer
                    WHERE COMPANY_CD = p_COMPANY_CD
                      AND ISDEL = '0'
                      AND OPEN_YMD = v_open_ymd
                      AND IFNULL(ACC_CD, '') <> ''


                    UNION ALL


                    SELECT
                        ACC_CD,
                        DEBIT,
                        CREDIT
                    FROM before_states_department
                    WHERE COMPANY_CD = p_COMPANY_CD
                      AND ISDEL = '0'
                      AND OPEN_YMD = v_open_ymd
                      AND IFNULL(ACC_CD, '') <> ''

                ) X
                GROUP BY X.ACC_CD;


                SET v_begin_move_from_ymd = v_open_ymd;

            ELSE

                /*
                    Không có closingmonth
                    và cũng không có before_states.
                */
                SET v_begin_move_from_ymd = '00000000';

            END IF;

        END IF;


        /* =====================================================
           10. PHÁT SINH TRƯỚC KỲ ĐANG KHÓA
           ===================================================== */

        IF v_begin_move_from_ymd IS NOT NULL
           AND v_begin_move_from_ymd <= v_prev_from_ymd THEN


            /* -----------------------------
               NỢ
               ----------------------------- */

            INSERT INTO tmp_cm_begin_move
            (
                ACCOUNT_CD,
                PERIOD_DEBIT,
                PERIOD_CREDIT
            )
            SELECT
                TRIM(CD.DEBIT),
                SUM(CD.AMOUNT),
                0
            FROM chitinfo C

            INNER JOIN chitdetailinfo CD
                ON CD.COMPANY_CD = C.COMPANY_CD
               AND CD.CHIT_ID = C.CHIT_ID
               AND CD.ISDEL = '0'

            WHERE C.COMPANY_CD = p_COMPANY_CD
              AND C.ISDEL = '0'
              AND C.CHIT_YMD >= v_begin_move_from_ymd
              AND C.CHIT_YMD <= v_prev_from_ymd
              AND IFNULL(TRIM(CD.DEBIT), '') <> ''

            GROUP BY TRIM(CD.DEBIT)

            ON DUPLICATE KEY UPDATE
                PERIOD_DEBIT =
                    PERIOD_DEBIT
                    + VALUES(PERIOD_DEBIT);


            /* -----------------------------
               CÓ
               ----------------------------- */

            INSERT INTO tmp_cm_begin_move
            (
                ACCOUNT_CD,
                PERIOD_DEBIT,
                PERIOD_CREDIT
            )
            SELECT
                TRIM(CD.CREDIT),
                0,
                SUM(CD.AMOUNT)
            FROM chitinfo C

            INNER JOIN chitdetailinfo CD
                ON CD.COMPANY_CD = C.COMPANY_CD
               AND CD.CHIT_ID = C.CHIT_ID
               AND CD.ISDEL = '0'

            WHERE C.COMPANY_CD = p_COMPANY_CD
              AND C.ISDEL = '0'
              AND C.CHIT_YMD >= v_begin_move_from_ymd
              AND C.CHIT_YMD <= v_prev_from_ymd
              AND IFNULL(TRIM(CD.CREDIT), '') <> ''

            GROUP BY TRIM(CD.CREDIT)

            ON DUPLICATE KEY UPDATE
                PERIOD_CREDIT =
                    PERIOD_CREDIT
                    + VALUES(PERIOD_CREDIT);

        END IF;


        /* =====================================================
           11. PHÁT SINH TRONG KỲ ĐANG KHÓA
           ===================================================== */


        /* -----------------------------
           NỢ
           ----------------------------- */

        INSERT INTO tmp_cm_period_amount
        (
            ACCOUNT_CD,
            PERIOD_DEBIT,
            PERIOD_CREDIT
        )
        SELECT
            TRIM(CD.DEBIT),
            SUM(CD.AMOUNT),
            0
        FROM chitinfo C

        INNER JOIN chitdetailinfo CD
            ON CD.COMPANY_CD = C.COMPANY_CD
           AND CD.CHIT_ID = C.CHIT_ID
           AND CD.ISDEL = '0'

        WHERE C.COMPANY_CD = p_COMPANY_CD
          AND C.ISDEL = '0'
          AND C.CHIT_YMD >= v_from_ymd
          AND C.CHIT_YMD <= v_to_ymd
          AND IFNULL(TRIM(CD.DEBIT), '') <> ''

        GROUP BY TRIM(CD.DEBIT)

        ON DUPLICATE KEY UPDATE
            PERIOD_DEBIT =
                PERIOD_DEBIT
                + VALUES(PERIOD_DEBIT);


        /* -----------------------------
           CÓ
           ----------------------------- */

        INSERT INTO tmp_cm_period_amount
        (
            ACCOUNT_CD,
            PERIOD_DEBIT,
            PERIOD_CREDIT
        )
        SELECT
            TRIM(CD.CREDIT),
            0,
            SUM(CD.AMOUNT)
        FROM chitinfo C

        INNER JOIN chitdetailinfo CD
            ON CD.COMPANY_CD = C.COMPANY_CD
           AND CD.CHIT_ID = C.CHIT_ID
           AND CD.ISDEL = '0'

        WHERE C.COMPANY_CD = p_COMPANY_CD
          AND C.ISDEL = '0'
          AND C.CHIT_YMD >= v_from_ymd
          AND C.CHIT_YMD <= v_to_ymd
          AND IFNULL(TRIM(CD.CREDIT), '') <> ''

        GROUP BY TRIM(CD.CREDIT)

        ON DUPLICATE KEY UPDATE
            PERIOD_CREDIT =
                PERIOD_CREDIT
                + VALUES(PERIOD_CREDIT);

    END IF;


    /* =========================================================
       12. GỘP SỐ DƯ
       ========================================================= */

    DROP TEMPORARY TABLE IF EXISTS tmp_cm_merged;

    CREATE TEMPORARY TABLE tmp_cm_merged
    (
        ACCOUNT_CD VARCHAR(20) NOT NULL DEFAULT '',

        BEGIN_DEBIT DECIMAL(18,6) NOT NULL DEFAULT 0,
        BEGIN_CREDIT DECIMAL(18,6) NOT NULL DEFAULT 0,

        MOVE_DEBIT DECIMAL(18,6) NOT NULL DEFAULT 0,
        MOVE_CREDIT DECIMAL(18,6) NOT NULL DEFAULT 0,

        PERIOD_DEBIT DECIMAL(18,6) NOT NULL DEFAULT 0,
        PERIOD_CREDIT DECIMAL(18,6) NOT NULL DEFAULT 0,

        END_NET DECIMAL(18,6) NOT NULL DEFAULT 0,

        PRIMARY KEY (ACCOUNT_CD)
    )
    ENGINE=InnoDB
    DEFAULT CHARSET=utf8
    COLLATE=utf8_unicode_ci;


    /* Danh sách account từ số dư đầu */
    INSERT INTO tmp_cm_merged
    (
        ACCOUNT_CD
    )
    SELECT ACCOUNT_CD
    FROM tmp_cm_begin_base

    ON DUPLICATE KEY UPDATE
        ACCOUNT_CD = VALUES(ACCOUNT_CD);


    /* Danh sách account từ phát sinh trước kỳ */
    INSERT INTO tmp_cm_merged
    (
        ACCOUNT_CD
    )
    SELECT ACCOUNT_CD
    FROM tmp_cm_begin_move

    ON DUPLICATE KEY UPDATE
        ACCOUNT_CD = VALUES(ACCOUNT_CD);


    /* Danh sách account từ phát sinh trong kỳ */
    INSERT INTO tmp_cm_merged
    (
        ACCOUNT_CD
    )
    SELECT ACCOUNT_CD
    FROM tmp_cm_period_amount

    ON DUPLICATE KEY UPDATE
        ACCOUNT_CD = VALUES(ACCOUNT_CD);


    /* =========================================================
       13. ĐƯA SỐ DƯ ĐẦU VÀO BẢNG GỘP
       ========================================================= */

    UPDATE tmp_cm_merged M

    INNER JOIN tmp_cm_begin_base B
        ON B.ACCOUNT_CD = M.ACCOUNT_CD

    SET
        M.BEGIN_DEBIT = B.BEGIN_DEBIT,
        M.BEGIN_CREDIT = B.BEGIN_CREDIT;


    /* =========================================================
       14. ĐƯA PHÁT SINH TRƯỚC KỲ VÀO
       ========================================================= */

    UPDATE tmp_cm_merged M

    INNER JOIN tmp_cm_begin_move BM
        ON BM.ACCOUNT_CD = M.ACCOUNT_CD

    SET
        M.MOVE_DEBIT = BM.PERIOD_DEBIT,
        M.MOVE_CREDIT = BM.PERIOD_CREDIT;


    /* =========================================================
       15. ĐƯA PHÁT SINH TRONG KỲ VÀO
       ========================================================= */

    UPDATE tmp_cm_merged M

    INNER JOIN tmp_cm_period_amount PA
        ON PA.ACCOUNT_CD = M.ACCOUNT_CD

    SET
        M.PERIOD_DEBIT = PA.PERIOD_DEBIT,
        M.PERIOD_CREDIT = PA.PERIOD_CREDIT;


    /* =========================================================
       16. TÍNH SỐ DƯ CUỐI KỲ
       ========================================================= */

    UPDATE tmp_cm_merged

    SET END_NET =
          BEGIN_DEBIT
        - BEGIN_CREDIT
        + MOVE_DEBIT
        - MOVE_CREDIT
        + PERIOD_DEBIT
        - PERIOD_CREDIT;


    /* =========================================================
       17. GHI CLOSING MONTH
       ========================================================= */

    INSERT INTO closingmonth_detail
    (
        COMPANY_CD,
        CLOSE_YMD,
        ACC_CD,
        FC_TYPE,

        DEBIT,
        CREDIT,

        DEBIT_FC,
        CREDIT_FC,

        NOTE,
        ISDEL,

        CREATE_BY,
        UPDATE_BY
    )

    SELECT
        p_COMPANY_CD,
        v_to_ymd,
        M.ACCOUNT_CD,

        'VND',


        /* =====================================================
           DEBIT
           ===================================================== */

        CASE

            /*
                Tài khoản hai bên:
                giữ độc lập tổng Nợ và Có.
            */
            WHEN IFNULL(
                    p_BALANCE_METHOD,
                    'BALANCE_ACCOUNT'
                 ) = 'BALANCE_ACCOUNT_TWO_SIDE'
                 AND IFNULL(AI.ISABLETYPE, 0) = 2
            THEN

                ROUND(
                      M.BEGIN_DEBIT
                    + M.MOVE_DEBIT
                    + M.PERIOD_DEBIT,
                    0
                )


            /*
                Tài khoản bình thường:
                lấy số dư net.
            */
            WHEN ROUND(M.END_NET, 0) > 0
            THEN ROUND(M.END_NET, 0)


            ELSE 0

        END AS DEBIT,


        /* =====================================================
           CREDIT
           ===================================================== */

        CASE

            WHEN IFNULL(
                    p_BALANCE_METHOD,
                    'BALANCE_ACCOUNT'
                 ) = 'BALANCE_ACCOUNT_TWO_SIDE'
                 AND IFNULL(AI.ISABLETYPE, 0) = 2
            THEN

                ROUND(
                      M.BEGIN_CREDIT
                    + M.MOVE_CREDIT
                    + M.PERIOD_CREDIT,
                    0
                )


            WHEN ROUND(M.END_NET, 0) < 0
            THEN ABS(
                ROUND(M.END_NET, 0)
            )


            ELSE 0

        END AS CREDIT,


        0 AS DEBIT_FC,
        0 AS CREDIT_FC,

        '',
        '0',

        p_USER_ID,
        p_USER_ID


    FROM tmp_cm_merged M

    LEFT JOIN acclist_info AI
        ON AI.COMPANY_CD = p_COMPANY_CD
       AND AI.ACC_CD = M.ACCOUNT_CD
       AND IFNULL(AI.ISDEL, '0') = '0'


    /*
        Không lưu account có số dư = 0.
    */
    WHERE
        CASE

            WHEN IFNULL(
                    p_BALANCE_METHOD,
                    'BALANCE_ACCOUNT'
                 ) = 'BALANCE_ACCOUNT_TWO_SIDE'
                 AND IFNULL(AI.ISABLETYPE, 0) = 2
            THEN

                ROUND(
                      M.BEGIN_DEBIT
                    + M.MOVE_DEBIT
                    + M.PERIOD_DEBIT,
                    0
                ) <> 0

                OR

                ROUND(
                      M.BEGIN_CREDIT
                    + M.MOVE_CREDIT
                    + M.PERIOD_CREDIT,
                    0
                ) <> 0


            ELSE

                ROUND(
                    ABS(M.END_NET),
                    0
                ) <> 0

        END;


    /* =========================================================
       18. CLEAN TEMP TABLE
       ========================================================= */

    DROP TEMPORARY TABLE IF EXISTS tmp_cm_begin_base;
    DROP TEMPORARY TABLE IF EXISTS tmp_cm_begin_move;
    DROP TEMPORARY TABLE IF EXISTS tmp_cm_period_amount;
    DROP TEMPORARY TABLE IF EXISTS tmp_cm_merged;

END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_cogs_build_xfer
DROP PROCEDURE IF EXISTS `sp_period_lock_cogs_build_xfer`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_cogs_build_xfer`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6),
    IN p_RULE_CODE VARCHAR(50)
)
proc: BEGIN
    DECLARE v_from_ymd CHAR(8);
    DECLARE v_to_ymd CHAR(8);
    DECLARE v_acc_154 VARCHAR(20);
    DECLARE v_acc_155 VARCHAR(20);
    DECLARE v_acc_632 VARCHAR(20);
    DECLARE v_has_source INT DEFAULT 0;

    SET v_from_ymd = CONCAT(p_PERIOD_YM, '01');
    SET v_to_ymd = DATE_FORMAT(LAST_DAY(STR_TO_DATE(CONCAT(p_PERIOD_YM, '01'), '%Y%m%d')), '%Y%m%d');

    DROP TEMPORARY TABLE IF EXISTS tmp_xfer_lines;
    CREATE TEMPORARY TABLE tmp_xfer_lines
    (
        TRANSFER_CODE VARCHAR(30) NOT NULL DEFAULT '',
        DEBIT_ACC VARCHAR(20) NOT NULL DEFAULT '',
        CREDIT_ACC VARCHAR(20) NOT NULL DEFAULT '',
        AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0,
        DEPARTMENT_ID BIGINT NOT NULL DEFAULT 0,
        KEY idx_tmp_xfer_lines_01 (TRANSFER_CODE)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    DROP TEMPORARY TABLE IF EXISTS tmp_154_dept;
    CREATE TEMPORARY TABLE tmp_154_dept
    (
        DEPARTMENT_ID BIGINT NOT NULL DEFAULT 0,
        AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0,
        PRIMARY KEY (DEPARTMENT_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    SELECT COUNT(*)
      INTO v_has_source
    FROM chitinfo C
    INNER JOIN chitdetailinfo CD
        ON CD.COMPANY_CD = C.COMPANY_CD
       AND CD.CHIT_ID = C.CHIT_ID
       AND CD.ISDEL = '0'
    INNER JOIN acclist_info A
        ON A.COMPANY_CD = CD.COMPANY_CD
       AND A.ACC_CD = TRIM(CD.DEBIT)
       AND IFNULL(A.ISDEL, '0') = '0'
       AND IFNULL(A.ISABLEINPUT, '0') = '1'
    WHERE C.COMPANY_CD = p_COMPANY_CD
      AND C.ISDEL = '0'
      AND C.CHIT_YMD >= v_from_ymd
      AND C.CHIT_YMD <= v_to_ymd
      AND IFNULL(TRIM(CD.DEBIT), '') <> ''
      AND IFNULL(TRIM(CD.CREDIT), '') <> ''
      AND (
            TRIM(CD.DEBIT) LIKE '621%'
         OR TRIM(CD.DEBIT) LIKE '622%'
         OR TRIM(CD.DEBIT) LIKE '623%'
         OR TRIM(CD.DEBIT) LIKE '627%'
         OR TRIM(CD.DEBIT) LIKE '154%'
      );

    IF IFNULL(v_has_source, 0) = 0 THEN
        LEAVE proc;
    END IF;

    CALL sp_period_lock_resolve_posting_acc(p_COMPANY_CD, '154', v_acc_154);

    IF p_RULE_CODE IN ('154_TO_155', '154_TO_155_TO_632') THEN
        CALL sp_period_lock_resolve_posting_acc(p_COMPANY_CD, '155', v_acc_155);
    END IF;

    IF p_RULE_CODE IN ('154_TO_632', '154_TO_155_TO_632') THEN
        CALL sp_period_lock_resolve_posting_acc(p_COMPANY_CD, '632', v_acc_632);
    END IF;

    INSERT INTO tmp_xfer_lines (TRANSFER_CODE, DEBIT_ACC, CREDIT_ACC, AMOUNT, DEPARTMENT_ID)
    SELECT
        'EXP_TO_154',
        v_acc_154,
        TRIM(CD.DEBIT),
        SUM(CD.AMOUNT),
        IFNULL(ext.DEPARTMENT_ID, 0)
    FROM chitinfo C
    INNER JOIN chitdetailinfo CD
        ON CD.COMPANY_CD = C.COMPANY_CD
       AND CD.CHIT_ID = C.CHIT_ID
       AND CD.ISDEL = '0'
    LEFT JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = CD.COMPANY_CD
       AND ext.CHITDETAIL_ID = CD.CHITDETAIL_ID
       AND ext.ISDEL = '0'
    INNER JOIN acclist_info A
        ON A.COMPANY_CD = CD.COMPANY_CD
       AND A.ACC_CD = TRIM(CD.DEBIT)
       AND IFNULL(A.ISDEL, '0') = '0'
       AND IFNULL(A.ISABLEINPUT, '0') = '1'
    WHERE C.COMPANY_CD = p_COMPANY_CD
      AND C.ISDEL = '0'
      AND C.CHIT_YMD >= v_from_ymd
      AND C.CHIT_YMD <= v_to_ymd
      AND IFNULL(TRIM(CD.DEBIT), '') <> ''
      AND IFNULL(TRIM(CD.CREDIT), '') <> ''
      AND (
            TRIM(CD.DEBIT) LIKE '621%'
         OR TRIM(CD.DEBIT) LIKE '622%'
         OR TRIM(CD.DEBIT) LIKE '623%'
         OR TRIM(CD.DEBIT) LIKE '627%'
      )
    GROUP BY TRIM(CD.DEBIT), IFNULL(ext.DEPARTMENT_ID, 0)
    HAVING SUM(CD.AMOUNT) > 0;

    INSERT INTO tmp_154_dept (DEPARTMENT_ID, AMOUNT)
    SELECT DEPARTMENT_ID, SUM(AMOUNT)
    FROM tmp_xfer_lines
    WHERE TRANSFER_CODE = 'EXP_TO_154'
    GROUP BY DEPARTMENT_ID
    ON DUPLICATE KEY UPDATE AMOUNT = AMOUNT + VALUES(AMOUNT);

    INSERT INTO tmp_154_dept (DEPARTMENT_ID, AMOUNT)
    SELECT
        IFNULL(ext.DEPARTMENT_ID, 0),
        SUM(CD.AMOUNT)
    FROM chitinfo C
    INNER JOIN chitdetailinfo CD
        ON CD.COMPANY_CD = C.COMPANY_CD
       AND CD.CHIT_ID = C.CHIT_ID
       AND CD.ISDEL = '0'
    LEFT JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = CD.COMPANY_CD
       AND ext.CHITDETAIL_ID = CD.CHITDETAIL_ID
       AND ext.ISDEL = '0'
    INNER JOIN acclist_info A
        ON A.COMPANY_CD = CD.COMPANY_CD
       AND A.ACC_CD = TRIM(CD.DEBIT)
       AND IFNULL(A.ISDEL, '0') = '0'
       AND IFNULL(A.ISABLEINPUT, '0') = '1'
    WHERE C.COMPANY_CD = p_COMPANY_CD
      AND C.ISDEL = '0'
      AND C.CHIT_YMD >= v_from_ymd
      AND C.CHIT_YMD <= v_to_ymd
      AND TRIM(CD.DEBIT) LIKE '154%'
      AND IFNULL(TRIM(CD.CREDIT), '') <> ''
    GROUP BY IFNULL(ext.DEPARTMENT_ID, 0)
    HAVING SUM(CD.AMOUNT) > 0
    ON DUPLICATE KEY UPDATE AMOUNT = AMOUNT + VALUES(AMOUNT);

    IF p_RULE_CODE IN ('154_TO_155', '154_TO_155_TO_632') THEN
        INSERT INTO tmp_xfer_lines (TRANSFER_CODE, DEBIT_ACC, CREDIT_ACC, AMOUNT, DEPARTMENT_ID)
        SELECT
            '154_TO_155',
            v_acc_155,
            v_acc_154,
            AMOUNT,
            DEPARTMENT_ID
        FROM tmp_154_dept
        WHERE AMOUNT > 0;
    END IF;

    IF p_RULE_CODE = '154_TO_632' THEN
        INSERT INTO tmp_xfer_lines (TRANSFER_CODE, DEBIT_ACC, CREDIT_ACC, AMOUNT, DEPARTMENT_ID)
        SELECT
            '154_TO_632',
            v_acc_632,
            v_acc_154,
            AMOUNT,
            DEPARTMENT_ID
        FROM tmp_154_dept
        WHERE AMOUNT > 0;
    END IF;

    IF p_RULE_CODE = '154_TO_155_TO_632' THEN
        INSERT INTO tmp_xfer_lines (TRANSFER_CODE, DEBIT_ACC, CREDIT_ACC, AMOUNT, DEPARTMENT_ID)
        SELECT
            '155_TO_632',
            v_acc_632,
            v_acc_155,
            AMOUNT,
            DEPARTMENT_ID
        FROM tmp_154_dept
        WHERE AMOUNT > 0;
    END IF;
END proc//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_cogs_calculate
DROP PROCEDURE IF EXISTS `sp_period_lock_cogs_calculate`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_cogs_calculate`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6),
    IN p_RULE_CODE VARCHAR(50),
    IN p_USER_ID VARCHAR(50)
)
BEGIN
    CALL sp_period_lock_cogs_validate(p_COMPANY_CD, p_PERIOD_YM, p_RULE_CODE, p_USER_ID);
