-- Dumping structure for procedure am_web_001.sp_period_lock_cogs_create_voucher
DROP PROCEDURE IF EXISTS `sp_period_lock_cogs_create_voucher`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_cogs_create_voucher`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6),
    IN p_RULE_CODE VARCHAR(50),
    IN p_USER_ID VARCHAR(50)
)
BEGIN
    DECLARE v_description VARCHAR(500);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        CALL sp_period_lock_cogs_rollback_period(p_COMPANY_CD, p_PERIOD_YM);
        RESIGNAL;
    END;

    SET v_description = CONCAT(
        'Tự động kết chuyển giá vốn - ',
        p_RULE_CODE,
        ' - ',
        SUBSTRING(p_PERIOD_YM, 5, 2),
        '/',
        SUBSTRING(p_PERIOD_YM, 1, 4)
    );

    CALL sp_period_lock_cogs_validate(p_COMPANY_CD, p_PERIOD_YM, p_RULE_CODE, p_USER_ID);
    CALL sp_period_lock_cogs_build_xfer(p_COMPANY_CD, p_PERIOD_YM, p_RULE_CODE);

    CALL sp_period_lock_post_xfer_group(
        p_COMPANY_CD, p_PERIOD_YM, 'COGS_SUMMARY',
        'EXP_TO_154', v_description, p_USER_ID, 'CG1'
    );

    IF p_RULE_CODE IN ('154_TO_155', '154_TO_155_TO_632') THEN
        CALL sp_period_lock_post_xfer_group(
            p_COMPANY_CD, p_PERIOD_YM, 'COGS_SUMMARY',
            '154_TO_155', v_description, p_USER_ID, 'CG2'
        );
    END IF;

    IF p_RULE_CODE = '154_TO_632' THEN
        CALL sp_period_lock_post_xfer_group(
            p_COMPANY_CD, p_PERIOD_YM, 'COGS_SUMMARY',
            '154_TO_632', v_description, p_USER_ID, 'CG3'
        );
    END IF;

    IF p_RULE_CODE = '154_TO_155_TO_632' THEN
        CALL sp_period_lock_post_xfer_group(
            p_COMPANY_CD, p_PERIOD_YM, 'COGS_SUMMARY',
            '155_TO_632', v_description, p_USER_ID, 'CG4'
        );
    END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_cogs_rollback_period
DROP PROCEDURE IF EXISTS `sp_period_lock_cogs_rollback_period`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_cogs_rollback_period`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6)
)
BEGIN
    CALL sp_period_lock_delete_lock_vouchers(
        p_COMPANY_CD,
        p_PERIOD_YM,
        'COGS_SUMMARY'
    );
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_cogs_unlock
DROP PROCEDURE IF EXISTS `sp_period_lock_cogs_unlock`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_cogs_unlock`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6),
    IN p_REASON VARCHAR(500),
    IN p_USER_ID VARCHAR(50)
)
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    CALL sp_period_lock_delete_lock_vouchers(
        p_COMPANY_CD,
        p_PERIOD_YM,
        'COGS_SUMMARY'
    );

    CALL sp_period_lock_step_upsert(
        p_COMPANY_CD,
        p_PERIOD_YM,
        'COGS_SUMMARY',
        'Báo cáo về tổng hợp giá vốn',
        2,
        'OPEN',
        'Đã mở',
        p_USER_ID
    );

    COMMIT;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_cogs_validate
DROP PROCEDURE IF EXISTS `sp_period_lock_cogs_validate`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_cogs_validate`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6),
    IN p_RULE_CODE VARCHAR(50),
    IN p_USER_ID VARCHAR(50)
)
BEGIN
    CALL sp_period_lock_step_require_done(
        p_COMPANY_CD,
        p_PERIOD_YM,
        'FA_PREPAID_LOCK',
        'Khóa TSCĐ / CP trả trước'
    );

    CALL sp_period_lock_step_require_open(
        p_COMPANY_CD,
        p_PERIOD_YM,
        'COGS_SUMMARY'
    );

    IF p_RULE_CODE NOT IN ('154_TO_155', '154_TO_155_TO_632', '154_TO_632') THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Rule kết chuyển giá vốn không hợp lệ';
    END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_current_status_get
DROP PROCEDURE IF EXISTS `sp_period_lock_current_status_get`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_current_status_get`(
    IN p_COMPANY_CD VARCHAR(20)
)
BEGIN
    /*
      Mục đích:
      - Lấy kỳ đã khóa hoàn toàn hiện tại của công ty.
      - Lấy thêm kỳ đã khóa gần nhất theo từng bước.
      - Không phụ thuộc năm đang xem trên combobox.
      - Dùng cho API overview và backend quyết định range khóa/mở từng bước.

      Ghi chú:
      - CurrentLockedPeriodYm: chỉ là kỳ LOCKED hoàn toàn trên acc_period_lock_month.
      - FaPrepaidLockedPeriodYm/CogsSummaryLockedPeriodYm/ProfitLossLockedPeriodYm:
        dùng để khóa từng bước, không bị nhầm với kỳ LOCKED hoàn toàn.
      - AnyStepLockedPeriodYm: dùng cho mở sổ, vì tháng PARTIAL vẫn còn step DONE cần mở.
    */

    DECLARE v_CURRENT_LOCKED_YM CHAR(6);
    DECLARE v_FA_PREPAID_LOCKED_YM CHAR(6);
    DECLARE v_COGS_SUMMARY_LOCKED_YM CHAR(6);
    DECLARE v_PROFIT_LOSS_LOCKED_YM CHAR(6);
    DECLARE v_ANY_STEP_LOCKED_YM CHAR(6);

    SELECT MAX(PERIOD_YM)
    INTO v_CURRENT_LOCKED_YM
    FROM acc_period_lock_month
    WHERE COMPANY_CD = p_COMPANY_CD
      AND STATUS = 'LOCKED'
      AND IFNULL(ISDEL, '0') = '0';

    SELECT MAX(PERIOD_YM)
    INTO v_FA_PREPAID_LOCKED_YM
    FROM acc_period_lock_step
    WHERE COMPANY_CD = p_COMPANY_CD
      AND STEP_CODE = 'FA_PREPAID_LOCK'
      AND STATUS = 'DONE';

    SELECT MAX(PERIOD_YM)
    INTO v_COGS_SUMMARY_LOCKED_YM
    FROM acc_period_lock_step
    WHERE COMPANY_CD = p_COMPANY_CD
      AND STEP_CODE = 'COGS_SUMMARY'
      AND STATUS = 'DONE';

    SELECT MAX(PERIOD_YM)
    INTO v_PROFIT_LOSS_LOCKED_YM
    FROM acc_period_lock_step
    WHERE COMPANY_CD = p_COMPANY_CD
      AND STEP_CODE = 'PROFIT_LOSS_REPORT'
      AND STATUS = 'DONE';

    SELECT MAX(PERIOD_YM)
    INTO v_ANY_STEP_LOCKED_YM
    FROM acc_period_lock_step
    WHERE COMPANY_CD = p_COMPANY_CD
      AND STEP_CODE IN ('FA_PREPAID_LOCK', 'COGS_SUMMARY', 'PROFIT_LOSS_REPORT')
      AND STATUS = 'DONE';

    SELECT
        IFNULL(v_CURRENT_LOCKED_YM, '') AS CurrentLockedPeriodYm,
        CASE
            WHEN v_CURRENT_LOCKED_YM IS NULL OR v_CURRENT_LOCKED_YM = ''
            THEN NULL
            ELSE CONCAT(SUBSTRING(v_CURRENT_LOCKED_YM, 5, 2), '/', SUBSTRING(v_CURRENT_LOCKED_YM, 1, 4))
        END AS CurrentLockedPeriodLabel,

        IFNULL(v_FA_PREPAID_LOCKED_YM, '') AS FaPrepaidLockedPeriodYm,
        IFNULL(v_COGS_SUMMARY_LOCKED_YM, '') AS CogsSummaryLockedPeriodYm,
        IFNULL(v_PROFIT_LOSS_LOCKED_YM, '') AS ProfitLossLockedPeriodYm,
        IFNULL(v_ANY_STEP_LOCKED_YM, '') AS AnyStepLockedPeriodYm;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_delete_lock_vouchers
DROP PROCEDURE IF EXISTS `sp_period_lock_delete_lock_vouchers`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_delete_lock_vouchers`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6),
    IN p_LOCK_STEP_CODE VARCHAR(50)
)
BEGIN
    DECLARE v_last_day DATE;
    DECLARE v_chit_ymd CHAR(8);

    CALL sp_period_lock_fa_prepaid_last_day(p_PERIOD_YM, v_last_day);
    SET v_chit_ymd = DATE_FORMAT(v_last_day, '%Y%m%d');

    DELETE dd
    FROM chitdetaildescriptioninfo dd
    INNER JOIN chitdetailinfo d
        ON d.CHITDETAIL_ID = dd.CHITDETAIL_ID
       AND d.COMPANY_CD = dd.COMPANY_CD
    INNER JOIN chitinfo h
        ON h.CHIT_ID = d.CHIT_ID
       AND h.COMPANY_CD = d.COMPANY_CD
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'LOCK'
      AND h.LOCK_STEP_CODE = p_LOCK_STEP_CODE
      AND h.CHIT_YMD = v_chit_ymd;

    DELETE ext
    FROM chitdetailinfo_ext ext
    INNER JOIN chitdetailinfo d
        ON d.CHITDETAIL_ID = ext.CHITDETAIL_ID
       AND d.COMPANY_CD = ext.COMPANY_CD
    INNER JOIN chitinfo h
        ON h.CHIT_ID = d.CHIT_ID
       AND h.COMPANY_CD = d.COMPANY_CD
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'LOCK'
      AND h.LOCK_STEP_CODE = p_LOCK_STEP_CODE
      AND h.CHIT_YMD = v_chit_ymd;

    DELETE d
    FROM chitdetailinfo d
    INNER JOIN chitinfo h
        ON h.CHIT_ID = d.CHIT_ID
       AND h.COMPANY_CD = d.COMPANY_CD
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'LOCK'
      AND h.LOCK_STEP_CODE = p_LOCK_STEP_CODE
      AND h.CHIT_YMD = v_chit_ymd;

    DELETE desc_h
    FROM chitdescriptioninfo desc_h
    INNER JOIN chitinfo h
        ON h.CHIT_ID = desc_h.CHIT_ID
       AND h.COMPANY_CD = desc_h.COMPANY_CD
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'LOCK'
      AND h.LOCK_STEP_CODE = p_LOCK_STEP_CODE
      AND h.CHIT_YMD = v_chit_ymd;

    DELETE ext_h
    FROM chitinfo_ext ext_h
    INNER JOIN chitinfo h
        ON h.CHIT_ID = ext_h.CHIT_ID
       AND h.COMPANY_CD = ext_h.COMPANY_CD
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'LOCK'
      AND h.LOCK_STEP_CODE = p_LOCK_STEP_CODE
      AND h.CHIT_YMD = v_chit_ymd;

    DELETE h
    FROM chitinfo h
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'LOCK'
      AND h.LOCK_STEP_CODE = p_LOCK_STEP_CODE
      AND h.CHIT_YMD = v_chit_ymd;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_fa_prepaid_calculate
DROP PROCEDURE IF EXISTS `sp_period_lock_fa_prepaid_calculate`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_fa_prepaid_calculate`(
    IN p_COMPANY_CD VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_PERIOD_YM CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_USER_ID VARCHAR(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci
)
BEGIN
    DECLARE v_now DATETIME;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    SET v_now = NOW();

    START TRANSACTION;

    -- Dọn dữ liệu chạy dở (active, chưa tạo CT) hoặc đã mở khóa (CANCEL_YN='Y').
    -- uk_fa_asset_depre_posted_01 = (COMPANY_CD, ASSET_ID, DEPRE_YM) — bản ghi hủy vẫn chặn INSERT mới.
    DELETE pa
    FROM fa_asset_depre_posted_alloc pa
    INNER JOIN fa_asset_depre_posted p
        ON p.POST_ID = pa.POST_ID
       AND p.COMPANY_CD = pa.COMPANY_CD
    WHERE p.COMPANY_CD = p_COMPANY_CD
      AND p.DEPRE_YM = p_PERIOD_YM
      AND (
          IFNULL(p.CANCEL_YN, 'N') = 'Y'
          OR (
              IFNULL(p.CANCEL_YN, 'N') = 'N'
              AND p.CHITINFO_ID IS NULL
          )
      );

    DELETE
    FROM fa_asset_depre_posted
    WHERE COMPANY_CD = p_COMPANY_CD
      AND DEPRE_YM = p_PERIOD_YM
      AND (
          IFNULL(CANCEL_YN, 'N') = 'Y'
          OR (
              IFNULL(CANCEL_YN, 'N') = 'N'
              AND CHITINFO_ID IS NULL
          )
      );

    -- Validate sau khi dọn dữ liệu chạy dở
    CALL sp_period_lock_fa_prepaid_validate(
        p_COMPANY_CD,
        p_PERIOD_YM,
        p_USER_ID
    );

    INSERT INTO fa_asset_depre_posted (
        COMPANY_CD,
        ASSET_ID,
        DEPRE_YM,
        DEPRE_TYPE,
        DEPRE_AMT,
        ACCUM_DEPRE_AMT,
        END_BOOK_AMT,
        CHITINFO_ID,
        CHIT_NO,
        LOCK_YN,
        CANCEL_YN,
        CREATE_AT,
        CREATE_BY
    )
    SELECT
        x.COMPANY_CD,
        x.ASSET_ID,
        x.DEPRE_YM,
        x.DEPRE_TYPE,
        x.DEPRE_AMT,
        x.ACCUM_DEPRE_AMT,
        x.END_BOOK_AMT,
        NULL AS CHITINFO_ID,
        NULL AS CHIT_NO,
        'Y' AS LOCK_YN,
        'N' AS CANCEL_YN,
        v_now AS CREATE_AT,
        p_USER_ID AS CREATE_BY
    FROM (
        SELECT
            a.COMPANY_CD,
            a.ASSET_ID,
            p_PERIOD_YM AS DEPRE_YM,

            CASE
                WHEN p_PERIOD_YM = a.DEPRE_START_YM THEN 'FIRST'
                WHEN p_PERIOD_YM = a.DEPRE_END_YM THEN 'LAST'
                ELSE 'NORMAL'
            END AS DEPRE_TYPE,

            CASE
                WHEN p_PERIOD_YM = a.DEPRE_START_YM THEN IFNULL(a.FIRST_DEPRE_AMT, 0)
                WHEN p_PERIOD_YM = a.DEPRE_END_YM THEN IFNULL(a.LAST_DEPRE_AMT, 0)
                ELSE IFNULL(a.NORMAL_DEPRE_AMT, 0)
            END AS DEPRE_AMT,

            IFNULL(a.ACCUM_DEPRE_AMT, 0)
            + IFNULL(prev.PREV_SUM, 0)
            + CASE
                WHEN p_PERIOD_YM = a.DEPRE_START_YM THEN IFNULL(a.FIRST_DEPRE_AMT, 0)
                WHEN p_PERIOD_YM = a.DEPRE_END_YM THEN IFNULL(a.LAST_DEPRE_AMT, 0)
                ELSE IFNULL(a.NORMAL_DEPRE_AMT, 0)
              END AS ACCUM_DEPRE_AMT,

            IFNULL(a.ORIGINAL_AMT, 0)
            - (
                IFNULL(a.ACCUM_DEPRE_AMT, 0)
                + IFNULL(prev.PREV_SUM, 0)
                + CASE
                    WHEN p_PERIOD_YM = a.DEPRE_START_YM THEN IFNULL(a.FIRST_DEPRE_AMT, 0)
                    WHEN p_PERIOD_YM = a.DEPRE_END_YM THEN IFNULL(a.LAST_DEPRE_AMT, 0)
                    ELSE IFNULL(a.NORMAL_DEPRE_AMT, 0)
                  END
              ) AS END_BOOK_AMT

        FROM fa_asset a
        LEFT JOIN (
            SELECT
                p.ASSET_ID,
                SUM(IFNULL(p.DEPRE_AMT, 0)) AS PREV_SUM
            FROM fa_asset_depre_posted p
            WHERE p.COMPANY_CD = p_COMPANY_CD
              AND p.DEPRE_YM < p_PERIOD_YM
              AND IFNULL(p.CANCEL_YN, 'N') = 'N'
            GROUP BY p.ASSET_ID
        ) prev ON prev.ASSET_ID = a.ASSET_ID
        WHERE a.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(a.ISDEL, '0') = '0'
          AND a.STATUS = 'IN_USE'
          AND p_PERIOD_YM BETWEEN a.DEPRE_START_YM AND a.DEPRE_END_YM
          AND NOT EXISTS (
              SELECT 1
              FROM fa_asset_depre_posted p2
              WHERE p2.COMPANY_CD = a.COMPANY_CD
                AND p2.ASSET_ID = a.ASSET_ID
                AND p2.DEPRE_YM = p_PERIOD_YM
                AND IFNULL(p2.CANCEL_YN, 'N') = 'N'
          )
    ) x
    WHERE x.DEPRE_AMT >= 0
      AND x.END_BOOK_AMT >= -0.01;

    INSERT INTO fa_asset_depre_posted_alloc (
        POST_ID,
        COMPANY_CD,
        ASSET_ID,
        DEPRE_YM,
        ALLOC_ID,
        ALLOC_SEQ,
        DEBIT_ACCT_CD,
        CREDIT_ACCT_CD,
        DEPARTMENT_ID,
        ALLOC_TYPE,
        ALLOC_RATE,
        DEPRE_AMT,
        CHITDETAIL_ID,
        CREATE_AT,
        CREATE_BY
    )
    SELECT
        p.POST_ID,
        p.COMPANY_CD,
        p.ASSET_ID,
        p.DEPRE_YM,
        al.ALLOC_ID,
        al.ALLOC_SEQ,
        al.DEBIT_ACCT_CD,
        al.CREDIT_ACCT_CD,
        al.DEPARTMENT_ID,
        al.ALLOC_TYPE,
        al.ALLOC_RATE,
        CASE p.DEPRE_TYPE
            WHEN 'FIRST' THEN IFNULL(al.FIRST_ALLOC_AMT, 0)
            WHEN 'NORMAL' THEN IFNULL(al.NORMAL_ALLOC_AMT, 0)
            WHEN 'LAST' THEN IFNULL(al.LAST_ALLOC_AMT, 0)
            ELSE 0
        END AS DEPRE_AMT,
        NULL AS CHITDETAIL_ID,
        v_now AS CREATE_AT,
        p_USER_ID AS CREATE_BY
    FROM fa_asset_depre_posted p
    INNER JOIN fa_asset_depre_alloc al
        ON al.COMPANY_CD = p.COMPANY_CD
       AND al.ASSET_ID = p.ASSET_ID
       AND IFNULL(al.ISDEL, '0') = '0'
    WHERE p.COMPANY_CD = p_COMPANY_CD
      AND p.DEPRE_YM = p_PERIOD_YM
      AND IFNULL(p.CANCEL_YN, 'N') = 'N'
      AND p.CHITINFO_ID IS NULL
      AND CASE p.DEPRE_TYPE
            WHEN 'FIRST' THEN IFNULL(al.FIRST_ALLOC_AMT, 0)
            WHEN 'NORMAL' THEN IFNULL(al.NORMAL_ALLOC_AMT, 0)
            WHEN 'LAST' THEN IFNULL(al.LAST_ALLOC_AMT, 0)
            ELSE 0
          END <> 0;

    COMMIT;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_fa_prepaid_create_voucher
DROP PROCEDURE IF EXISTS `sp_period_lock_fa_prepaid_create_voucher`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_fa_prepaid_create_voucher`(
    IN p_COMPANY_CD VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_PERIOD_YM CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_USER_ID VARCHAR(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci
)
BEGIN
    DECLARE v_not_found INT DEFAULT 0;
    DECLARE v_post_id BIGINT;
    DECLARE v_asset_id BIGINT;
    DECLARE v_asset_cd VARCHAR(50);
    DECLARE v_asset_nm VARCHAR(255);
    DECLARE v_depre_amt DECIMAL(18,2);
    DECLARE v_chit_id BIGINT;
    DECLARE v_chit_no VARCHAR(50);
    DECLARE v_chit_cd VARCHAR(30);
    DECLARE v_chit_ymd DATE;
    DECLARE v_chit_ymd_char CHAR(8);
    DECLARE v_description VARCHAR(500);
    DECLARE v_detail_cd VARCHAR(30);
    DECLARE v_detail_id BIGINT;
    DECLARE v_line_seq INT DEFAULT 0;
    DECLARE v_post_alloc_id BIGINT;
    DECLARE v_alloc_seq INT;
    DECLARE v_debit_acct VARCHAR(20);
    DECLARE v_credit_acct VARCHAR(20);
    DECLARE v_department_id BIGINT;
    DECLARE v_department_cd VARCHAR(20);
    DECLARE v_line_amt DECIMAL(18,2);

    DECLARE cur_posted CURSOR FOR
        SELECT
            p.POST_ID,
            p.ASSET_ID,
            a.ASSET_CD,
            a.ASSET_NM,
            p.DEPRE_AMT
        FROM fa_asset_depre_posted p
        INNER JOIN fa_asset a
            ON a.ASSET_ID = p.ASSET_ID
           AND a.COMPANY_CD = p.COMPANY_CD
        WHERE p.COMPANY_CD = p_COMPANY_CD
          AND p.DEPRE_YM = p_PERIOD_YM
          AND IFNULL(p.CANCEL_YN, 'N') = 'N'
          AND p.CHITINFO_ID IS NULL
        ORDER BY p.POST_ID;

    DECLARE cur_alloc CURSOR FOR
        SELECT
            pa.POST_ALLOC_ID,
            pa.ALLOC_SEQ,
            pa.DEBIT_ACCT_CD,
            pa.CREDIT_ACCT_CD,
            pa.DEPARTMENT_ID,
            pa.DEPRE_AMT
        FROM fa_asset_depre_posted_alloc pa
        WHERE pa.POST_ID = v_post_id
          AND pa.COMPANY_CD = p_COMPANY_CD
        ORDER BY pa.ALLOC_SEQ, pa.POST_ALLOC_ID;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_not_found = 1;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        CALL sp_period_lock_fa_prepaid_rollback_period(p_COMPANY_CD, p_PERIOD_YM);
        RESIGNAL;
    END;

    CALL sp_period_lock_fa_prepaid_last_day(p_PERIOD_YM, v_chit_ymd);
    SET v_chit_ymd_char = DATE_FORMAT(v_chit_ymd, '%Y%m%d');

    OPEN cur_posted;

    posted_loop: LOOP
        SET v_not_found = 0;
        FETCH cur_posted INTO v_post_id, v_asset_id, v_asset_cd, v_asset_nm, v_depre_amt;
        IF v_not_found = 1 THEN
            LEAVE posted_loop;
        END IF;

        CALL sp_period_lock_fa_prepaid_next_chit_no(p_COMPANY_CD, v_chit_ymd, v_chit_no);

        SET v_chit_cd = LEFT(CONCAT('C', DATE_FORMAT(NOW(6), '%Y%m%d%H%i%s%f'), LPAD(v_post_id, 6, '0')), 30);
        SET v_description = CONCAT('Tự động kết chuyển - ', v_asset_cd, ' - ', v_asset_nm);

        INSERT INTO chitinfo (
            COMPANY_CD,
            CHIT_CD,
            CHIT_NO,
            CHIT_YMD,
            CHIT_TYPE,
            INPUT_TYPE,
            LOCK_STEP_CODE,
            AMOUNT,
            ISDEL,
            CREATE_BY,
            UPDATE_BY
        ) VALUES (
            p_COMPANY_CD,
            v_chit_cd,
            LEFT(v_chit_no, 50),
            v_chit_ymd_char,
            'OT',
            'LOCK',
            'FA_PREPAID_LOCK',
            v_depre_amt,
            '0',
            p_USER_ID,
            p_USER_ID
        );

        SET v_chit_id = LAST_INSERT_ID();

        INSERT INTO chitinfo_ext (
            COMPANY_CD,
            CHIT_ID,
            CHIT_CD,
            IS_LOCK,
            ISEXCEL,
            IS_CONFIRMED,
            IS_PAYMENT,
            ISDEL,
            CREATE_BY,
            UPDATE_BY
        ) VALUES (
            p_COMPANY_CD,
            v_chit_id,
            LEFT(v_chit_cd, 20),
            '0',
            '0',
            '0',
            '0',
            '0',
            p_USER_ID,
            p_USER_ID
        );

        INSERT INTO chitdescriptioninfo (
            COMPANY_CD,
            CHIT_ID,
            CHIT_CD,
            DESC_CD,
            LANG_TYPE,
            DESCRIPTION,
            ISDEL,
            CREATE_BY,
            UPDATE_BY
        ) VALUES (
            p_COMPANY_CD,
            v_chit_id,
            LEFT(v_chit_cd, 20),
            LEFT(v_chit_cd, 20),
            'VIET',
            v_description,
            '0',
            p_USER_ID,
            p_USER_ID
        );

        OPEN cur_alloc;

        alloc_loop: LOOP
            SET v_not_found = 0;
            FETCH cur_alloc INTO
                v_post_alloc_id,
                v_alloc_seq,
                v_debit_acct,
                v_credit_acct,
                v_department_id,
                v_line_amt;

            IF v_not_found = 1 THEN
                LEAVE alloc_loop;
            END IF;

            SET v_line_seq = v_line_seq + 1;
            SET v_detail_cd = LEFT(CONCAT('D', DATE_FORMAT(NOW(6), '%Y%m%d%H%i%s%f'), LPAD(v_line_seq, 6, '0')), 30);

            INSERT INTO chitdetailinfo (
                COMPANY_CD,
                CHIT_ID,
                CHIT_CD,
                CHITDETAIL_CD,
                CHIT_YMD,
                DEBIT,
                CREDIT,
                AMOUNT,
                FC_AMOUNT,
                FC_RATE,
                SORT,
                ISDEL,
                CREATE_BY,
                UPDATE_BY
            ) VALUES (
                p_COMPANY_CD,
                v_chit_id,
                v_chit_cd,
                v_detail_cd,
                v_chit_ymd_char,
                v_debit_acct,
                v_credit_acct,
                v_line_amt,
                0,
                0,
                v_alloc_seq,
                '0',
                p_USER_ID,
                p_USER_ID
            );

            SET v_detail_id = LAST_INSERT_ID();

            INSERT INTO chitdetaildescriptioninfo (
                COMPANY_CD,
                CHITDETAIL_ID,
                CHITDETAIL_CD,
                DESC_CD,
                LANG_TYPE,
                DESCRIPTION,
                ISDEL,
                CREATE_BY,
                UPDATE_BY
            ) VALUES (
                p_COMPANY_CD,
                v_detail_id,
                LEFT(v_detail_cd, 20),
                LEFT(v_detail_cd, 20),
                'VIET',
                v_description,
                '0',
                p_USER_ID,
                p_USER_ID
            );

            SET v_department_cd = NULL;
            IF v_department_id IS NOT NULL THEN
                SELECT dep.DEPARTMENT_CD
                  INTO v_department_cd
                  FROM department_info dep
                 WHERE dep.DEPARTMENT_ID = v_department_id
                   AND dep.COMPANY_CD = p_COMPANY_CD
                 LIMIT 1;
            END IF;

            INSERT INTO chitdetailinfo_ext (
                COMPANY_CD,
                CHITDETAIL_ID,
                CHITDETAIL_CD,
                DEPARTMENT_ID,
                DEPARTMENT_CD,
                ISDEL,
                CREATE_BY,
                UPDATE_BY
            ) VALUES (
                p_COMPANY_CD,
                v_detail_id,
                LEFT(v_detail_cd, 20),
                v_department_id,
                v_department_cd,
                '0',
                p_USER_ID,
                p_USER_ID
            );

            UPDATE fa_asset_depre_posted_alloc
            SET CHITDETAIL_ID = v_detail_id
            WHERE POST_ALLOC_ID = v_post_alloc_id;
        END LOOP;

        CLOSE cur_alloc;

        UPDATE fa_asset_depre_posted
        SET CHITINFO_ID = v_chit_id,
            CHIT_NO = LEFT(v_chit_no, 50)
        WHERE POST_ID = v_post_id;
    END LOOP;

    CLOSE cur_posted;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_fa_prepaid_last_day
DROP PROCEDURE IF EXISTS `sp_period_lock_fa_prepaid_last_day`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_fa_prepaid_last_day`(
    IN p_PERIOD_YM CHAR(6),
    OUT p_LAST_DAY DATE
)
BEGIN
    SET p_LAST_DAY = LAST_DAY(STR_TO_DATE(CONCAT(p_PERIOD_YM, '01'), '%Y%m%d'));
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_fa_prepaid_next_chit_no
DROP PROCEDURE IF EXISTS `sp_period_lock_fa_prepaid_next_chit_no`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_fa_prepaid_next_chit_no`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_BASE_DATE DATETIME,
    OUT p_CHIT_NO VARCHAR(100)
)
BEGIN
    DECLARE v_id BIGINT DEFAULT NULL;
    DECLARE v_current_no BIGINT DEFAULT 0;
    DECLARE v_next_no BIGINT DEFAULT 0;
    DECLARE v_prefix VARCHAR(50) DEFAULT '';
    DECLARE v_suffix VARCHAR(50) DEFAULT '';
    DECLARE v_code_pattern VARCHAR(100) DEFAULT '{PREFIX}{NO}{SUFFIX}';
    DECLARE v_number_length INT DEFAULT 6;
    DECLARE v_reset_type VARCHAR(20) DEFAULT '';
    DECLARE v_reset_key VARCHAR(50) DEFAULT '';
    DECLARE v_year_key VARCHAR(4) DEFAULT '';
    DECLARE v_month_key VARCHAR(6) DEFAULT '';
    DECLARE v_no_text VARCHAR(50) DEFAULT '';

    SET p_CHIT_NO = NULL;
    SET v_year_key = DATE_FORMAT(p_BASE_DATE, '%Y');
    SET v_month_key = DATE_FORMAT(p_BASE_DATE, '%Y%m');

    START TRANSACTION;

    SELECT
        ID,
        CURRENT_NO,
        PREFIX,
        SUFFIX,
        IFNULL(NULLIF(CODE_PATTERN, ''), '{PREFIX}{NO}{SUFFIX}'),
        NUMBER_LENGTH,
        RESET_TYPE,
        RESET_KEY
    INTO
        v_id,
        v_current_no,
        v_prefix,
        v_suffix,
        v_code_pattern,
        v_number_length,
        v_reset_type,
        v_reset_key
    FROM sys_code_sequence
    WHERE COMPANY_CD = p_COMPANY_CD
      AND OBJECT_TYPE = 'OT'
      AND IFNULL(IS_USE, '1') IN ('1', 'Y')
    ORDER BY ID
    LIMIT 1
    FOR UPDATE;

    IF v_id IS NULL THEN
        ROLLBACK;
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Chua cau hinh day so chung tu OT trong sys_code_sequence';
    END IF;

    IF v_reset_type = 'YEAR' AND IFNULL(v_reset_key, '') <> v_year_key THEN
        SET v_current_no = 0;
        SET v_reset_key = v_year_key;
    ELSEIF v_reset_type = 'MONTH' AND IFNULL(v_reset_key, '') <> v_month_key THEN
        SET v_current_no = 0;
        SET v_reset_key = v_month_key;
    END IF;

    SET v_next_no = v_current_no + 1;
    SET v_no_text = LPAD(CAST(v_next_no AS CHAR), IFNULL(v_number_length, 6), '0');

    SET p_CHIT_NO = v_code_pattern;
    SET p_CHIT_NO = REPLACE(p_CHIT_NO, '{PREFIX}', IFNULL(v_prefix, ''));
    SET p_CHIT_NO = REPLACE(p_CHIT_NO, '{SUFFIX}', IFNULL(v_suffix, ''));
    SET p_CHIT_NO = REPLACE(p_CHIT_NO, '{NO}', v_no_text);
    SET p_CHIT_NO = REPLACE(p_CHIT_NO, '{YYYY}', DATE_FORMAT(p_BASE_DATE, '%Y'));
    SET p_CHIT_NO = REPLACE(p_CHIT_NO, '{YY}', DATE_FORMAT(p_BASE_DATE, '%y'));
    SET p_CHIT_NO = REPLACE(p_CHIT_NO, '{MM}', DATE_FORMAT(p_BASE_DATE, '%m'));
    SET p_CHIT_NO = REPLACE(p_CHIT_NO, '{DD}', DATE_FORMAT(p_BASE_DATE, '%d'));

    UPDATE sys_code_sequence
    SET CURRENT_NO = v_next_no,
        RESET_KEY = v_reset_key,
        UPDATE_AT = NOW()
    WHERE ID = v_id;

    COMMIT;
END//
