       AND h.COMPANY_CD = d.COMPANY_CD
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'LOCK'
      AND h.LOCK_STEP_CODE = 'FA_PREPAID_LOCK'
      AND h.CHIT_YMD = DATE_FORMAT(v_last_day, '%Y%m%d');

    DELETE ext
    FROM chitdetailinfo_ext ext
    INNER JOIN chitdetailinfo d
        ON d.CHITDETAIL_ID = ext.CHITDETAIL_ID
       AND d.COMPANY_CD = ext.COMPANY_CD
    INNER JOIN chitinfo h
        ON h.CHIT_ID = d.CHIT_ID
       AND h.COMPANY_CD = d.COMPANY_CD
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'LOCK'
      AND h.LOCK_STEP_CODE = 'FA_PREPAID_LOCK'
      AND h.CHIT_YMD = DATE_FORMAT(v_last_day, '%Y%m%d');

    DELETE d
    FROM chitdetailinfo d
    INNER JOIN chitinfo h
        ON h.CHIT_ID = d.CHIT_ID
       AND h.COMPANY_CD = d.COMPANY_CD
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'LOCK'
      AND h.LOCK_STEP_CODE = 'FA_PREPAID_LOCK'
      AND h.CHIT_YMD = DATE_FORMAT(v_last_day, '%Y%m%d');

    DELETE desc_h
    FROM chitdescriptioninfo desc_h
    INNER JOIN chitinfo h
        ON h.CHIT_ID = desc_h.CHIT_ID
       AND h.COMPANY_CD = desc_h.COMPANY_CD
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'LOCK'
      AND h.LOCK_STEP_CODE = 'FA_PREPAID_LOCK'
      AND h.CHIT_YMD = DATE_FORMAT(v_last_day, '%Y%m%d');

    DELETE ext_h
    FROM chitinfo_ext ext_h
    INNER JOIN chitinfo h
        ON h.CHIT_ID = ext_h.CHIT_ID
       AND h.COMPANY_CD = ext_h.COMPANY_CD
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'LOCK'
      AND h.LOCK_STEP_CODE = 'FA_PREPAID_LOCK'
      AND h.CHIT_YMD = DATE_FORMAT(v_last_day, '%Y%m%d');

    DELETE h
    FROM chitinfo h
    WHERE h.COMPANY_CD = p_COMPANY_CD
      AND h.INPUT_TYPE = 'LOCK'
      AND h.LOCK_STEP_CODE = 'FA_PREPAID_LOCK'
      AND h.CHIT_YMD = DATE_FORMAT(v_last_day, '%Y%m%d');

    DELETE pa
    FROM fa_asset_depre_posted_alloc pa
    INNER JOIN fa_asset_depre_posted p
        ON p.POST_ID = pa.POST_ID
       AND p.COMPANY_CD = pa.COMPANY_CD
    WHERE p.COMPANY_CD = p_COMPANY_CD
      AND p.DEPRE_YM = p_PERIOD_YM;

    DELETE
    FROM fa_asset_depre_posted
    WHERE COMPANY_CD = p_COMPANY_CD
      AND DEPRE_YM = p_PERIOD_YM;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_fa_prepaid_unlock
DROP PROCEDURE IF EXISTS `sp_period_lock_fa_prepaid_unlock`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_fa_prepaid_unlock`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6),
    IN p_REASON VARCHAR(500),
    IN p_USER_ID VARCHAR(50)
)
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    DELETE dd
    FROM chitdetaildescriptioninfo dd
    INNER JOIN chitdetailinfo d
        ON d.CHITDETAIL_ID = dd.CHITDETAIL_ID
       AND d.COMPANY_CD = dd.COMPANY_CD
    INNER JOIN fa_asset_depre_posted p
        ON p.CHITINFO_ID = d.CHIT_ID
       AND p.COMPANY_CD = d.COMPANY_CD
    WHERE p.COMPANY_CD = p_COMPANY_CD
      AND p.DEPRE_YM = p_PERIOD_YM
      AND IFNULL(p.CANCEL_YN, 'N') = 'N'
      AND p.CHITINFO_ID IS NOT NULL;

    DELETE ext
    FROM chitdetailinfo_ext ext
    INNER JOIN chitdetailinfo d
        ON d.CHITDETAIL_ID = ext.CHITDETAIL_ID
       AND d.COMPANY_CD = ext.COMPANY_CD
    INNER JOIN fa_asset_depre_posted p
        ON p.CHITINFO_ID = d.CHIT_ID
       AND p.COMPANY_CD = d.COMPANY_CD
    WHERE p.COMPANY_CD = p_COMPANY_CD
      AND p.DEPRE_YM = p_PERIOD_YM
      AND IFNULL(p.CANCEL_YN, 'N') = 'N'
      AND p.CHITINFO_ID IS NOT NULL;

    DELETE d
    FROM chitdetailinfo d
    INNER JOIN fa_asset_depre_posted p
        ON p.CHITINFO_ID = d.CHIT_ID
       AND p.COMPANY_CD = d.COMPANY_CD
    WHERE p.COMPANY_CD = p_COMPANY_CD
      AND p.DEPRE_YM = p_PERIOD_YM
      AND IFNULL(p.CANCEL_YN, 'N') = 'N'
      AND p.CHITINFO_ID IS NOT NULL;

    DELETE desc_h
    FROM chitdescriptioninfo desc_h
    INNER JOIN fa_asset_depre_posted p
        ON p.CHITINFO_ID = desc_h.CHIT_ID
       AND p.COMPANY_CD = desc_h.COMPANY_CD
    WHERE p.COMPANY_CD = p_COMPANY_CD
      AND p.DEPRE_YM = p_PERIOD_YM
      AND IFNULL(p.CANCEL_YN, 'N') = 'N'
      AND p.CHITINFO_ID IS NOT NULL;

    DELETE ext_h
    FROM chitinfo_ext ext_h
    INNER JOIN fa_asset_depre_posted p
        ON p.CHITINFO_ID = ext_h.CHIT_ID
       AND p.COMPANY_CD = ext_h.COMPANY_CD
    WHERE p.COMPANY_CD = p_COMPANY_CD
      AND p.DEPRE_YM = p_PERIOD_YM
      AND IFNULL(p.CANCEL_YN, 'N') = 'N'
      AND p.CHITINFO_ID IS NOT NULL;

    DELETE h
    FROM chitinfo h
    INNER JOIN fa_asset_depre_posted p
        ON p.CHITINFO_ID = h.CHIT_ID
       AND p.COMPANY_CD = h.COMPANY_CD
    WHERE p.COMPANY_CD = p_COMPANY_CD
      AND p.DEPRE_YM = p_PERIOD_YM
      AND IFNULL(p.CANCEL_YN, 'N') = 'N'
      AND p.CHITINFO_ID IS NOT NULL;

    UPDATE fa_asset_depre_posted_alloc pa
    INNER JOIN fa_asset_depre_posted p
        ON p.POST_ID = pa.POST_ID
       AND p.COMPANY_CD = pa.COMPANY_CD
    SET pa.CHITDETAIL_ID = NULL
    WHERE p.COMPANY_CD = p_COMPANY_CD
      AND p.DEPRE_YM = p_PERIOD_YM
      AND p.CANCEL_YN = 'N';

    UPDATE fa_asset_depre_posted
    SET CANCEL_YN = 'Y',
        LOCK_YN = 'N',
        CHITINFO_ID = NULL,
        CHIT_NO = NULL
    WHERE COMPANY_CD = p_COMPANY_CD
      AND DEPRE_YM = p_PERIOD_YM
      AND CANCEL_YN = 'N';

    CALL sp_period_lock_step_upsert(
        p_COMPANY_CD,
        p_PERIOD_YM,
        'FA_PREPAID_LOCK',
        'Khóa TSCĐ / CP trả trước',
        1,
        'OPEN',
        'Đã mở',
        p_USER_ID
    );

    COMMIT;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_fa_prepaid_validate
DROP PROCEDURE IF EXISTS `sp_period_lock_fa_prepaid_validate`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_fa_prepaid_validate`(
    IN p_COMPANY_CD VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_PERIOD_YM CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
    IN p_USER_ID VARCHAR(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci
)
BEGIN
    DECLARE v_asset_id BIGINT;
    DECLARE v_asset_cd VARCHAR(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_start_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_end_ym CHAR(6) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_depre_type VARCHAR(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_depre_amt DECIMAL(18,2);
    DECLARE v_alloc_sum DECIMAL(18,2);
    DECLARE v_msg VARCHAR(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci;
    DECLARE v_done INT DEFAULT 0;

    DECLARE cur_assets CURSOR FOR
        SELECT
            a.ASSET_ID,
            a.ASSET_CD,
            a.DEPRE_START_YM,
            a.DEPRE_END_YM,
            CASE
                WHEN p_PERIOD_YM = a.DEPRE_START_YM THEN a.FIRST_DEPRE_AMT
                WHEN p_PERIOD_YM = a.DEPRE_END_YM THEN a.LAST_DEPRE_AMT
                ELSE a.NORMAL_DEPRE_AMT
            END AS DEPRE_AMT
        FROM fa_asset a
        WHERE a.COMPANY_CD = p_COMPANY_CD
          AND IFNULL(a.ISDEL, '0') = '0'
          AND a.STATUS = 'IN_USE'
          AND p_PERIOD_YM BETWEEN a.DEPRE_START_YM AND a.DEPRE_END_YM
          AND NOT EXISTS (
              SELECT 1
              FROM fa_asset_depre_posted p
              WHERE p.COMPANY_CD = a.COMPANY_CD
                AND p.ASSET_ID = a.ASSET_ID
                AND p.DEPRE_YM = p_PERIOD_YM
                AND IFNULL(p.CANCEL_YN, 'N') = 'N'
          );

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    OPEN cur_assets;

    asset_loop: LOOP
        FETCH cur_assets
        INTO v_asset_id, v_asset_cd, v_start_ym, v_end_ym, v_depre_amt;

        IF v_done = 1 THEN
            LEAVE asset_loop;
        END IF;

        CALL sp_period_lock_fa_prepaid_resolve_depre_type(
            p_PERIOD_YM,
            v_start_ym,
            v_end_ym,
            v_depre_type
        );

        IF v_depre_amt IS NULL OR v_depre_amt < 0 THEN
            SET v_msg = LEFT(CONCAT('TSCD ', v_asset_cd, ': so khau hao thang khong hop le'), 128);
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
        END IF;

        IF NOT EXISTS (
            SELECT 1
            FROM fa_asset_depre_alloc al
            WHERE al.COMPANY_CD = p_COMPANY_CD
              AND al.ASSET_ID = v_asset_id
              AND IFNULL(al.ISDEL, '0') = '0'
        ) THEN
            SET v_msg = LEFT(CONCAT('TSCD ', v_asset_cd, ': chua co dong phan bo khau hao'), 128);
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
        END IF;

        IF EXISTS (
            SELECT 1
            FROM fa_asset_depre_alloc al
            WHERE al.COMPANY_CD = p_COMPANY_CD
              AND al.ASSET_ID = v_asset_id
              AND IFNULL(al.ISDEL, '0') = '0'
              AND (
                  IFNULL(al.DEBIT_ACCT_CD, '') = ''
                  OR IFNULL(al.CREDIT_ACCT_CD, '') = ''
              )
        ) THEN
            SET v_msg = LEFT(CONCAT('TSCD ', v_asset_cd, ': thieu tai khoan No/Co phan bo'), 128);
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
        END IF;

        IF v_depre_type = 'FIRST' AND EXISTS (
            SELECT 1
            FROM fa_asset_depre_alloc al
            WHERE al.COMPANY_CD = p_COMPANY_CD
              AND al.ASSET_ID = v_asset_id
              AND IFNULL(al.ISDEL, '0') = '0'
              AND (al.FIRST_ALLOC_AMT IS NULL OR al.FIRST_ALLOC_AMT < 0)
        ) THEN
            SET v_msg = LEFT(CONCAT('TSCD ', v_asset_cd, ': thieu FIRST_ALLOC_AMT'), 128);
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
        END IF;

        IF v_depre_type = 'NORMAL' AND EXISTS (
            SELECT 1
            FROM fa_asset_depre_alloc al
            WHERE al.COMPANY_CD = p_COMPANY_CD
              AND al.ASSET_ID = v_asset_id
              AND IFNULL(al.ISDEL, '0') = '0'
              AND (al.NORMAL_ALLOC_AMT IS NULL OR al.NORMAL_ALLOC_AMT < 0)
        ) THEN
            SET v_msg = LEFT(CONCAT('TSCD ', v_asset_cd, ': thieu NORMAL_ALLOC_AMT'), 128);
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
        END IF;

        IF v_depre_type = 'LAST' AND EXISTS (
            SELECT 1
            FROM fa_asset_depre_alloc al
            WHERE al.COMPANY_CD = p_COMPANY_CD
              AND al.ASSET_ID = v_asset_id
              AND IFNULL(al.ISDEL, '0') = '0'
              AND (al.LAST_ALLOC_AMT IS NULL OR al.LAST_ALLOC_AMT < 0)
        ) THEN
            SET v_msg = LEFT(CONCAT('TSCD ', v_asset_cd, ': thieu LAST_ALLOC_AMT'), 128);
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
        END IF;

        SELECT
            SUM(
                CASE v_depre_type
                    WHEN 'FIRST' THEN IFNULL(al.FIRST_ALLOC_AMT, 0)
                    WHEN 'NORMAL' THEN IFNULL(al.NORMAL_ALLOC_AMT, 0)
                    WHEN 'LAST' THEN IFNULL(al.LAST_ALLOC_AMT, 0)
                    ELSE 0
                END
            )
        INTO v_alloc_sum
        FROM fa_asset_depre_alloc al
        WHERE al.COMPANY_CD = p_COMPANY_CD
          AND al.ASSET_ID = v_asset_id
          AND IFNULL(al.ISDEL, '0') = '0';

        IF ABS(IFNULL(v_alloc_sum, 0) - IFNULL(v_depre_amt, 0)) > 0.01 THEN
            SET v_msg = LEFT(
                CONCAT(
                    'TSCD ',
                    v_asset_cd,
                    ': tong phan bo ',
                    CAST(IFNULL(v_alloc_sum, 0) AS CHAR),
                    ' khac khau hao ',
                    CAST(IFNULL(v_depre_amt, 0) AS CHAR)
                ),
                128
            );

            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
        END IF;

    END LOOP;

    CLOSE cur_assets;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_fiscal_start_year_get
DROP PROCEDURE IF EXISTS `sp_period_lock_fiscal_start_year_get`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_fiscal_start_year_get`(
    IN `p_COMPANY_CD` VARCHAR(20)
)
BEGIN
    /*
      Mục đích:
      - Lấy ngày đầu kỳ kế toán của công ty.
      - CARRYFORWARD_YMD có định dạng yyyyMMdd, ví dụ 20250101.
      - Backend lấy FiscalStartYmd từ store này, không lấy từ frontend.
    */

    SELECT
        CARRYFORWARD_YMD AS FiscalStartYmd
    FROM am_web_manager.company_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND IFNULL(ISDEL, '0') = '0'
    LIMIT 1;
END//
DELIMITER ;


