    )
    VALUES
    (
        p_COMPANY_CD, p_JOB_ID, p_YEAR_VALUE,
        p_FROM_PERIOD_YM, p_TO_PERIOD_YM,
        p_STEPS_TEXT, p_OPTIONS_JSON,
        p_TOTAL_STEPS, 0, 0,
