-- Dumping structure for procedure am_web_001.sp_period_lock_job_get_progress
DROP PROCEDURE IF EXISTS `sp_period_lock_job_get_progress`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_job_get_progress`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_JOB_ID VARCHAR(100)
)
BEGIN
    SELECT
        JOB_ID AS JobId,
        PERCENT_VALUE AS Percent,
        TOTAL_STEPS AS TotalSteps,
        DONE_STEPS AS DoneSteps,
        IFNULL(CURRENT_PERIOD_YM, '') AS CurrentPeriodYm,
        CASE
            WHEN CURRENT_PERIOD_YM IS NULL OR CURRENT_PERIOD_YM = ''
            THEN '-'
            ELSE CONCAT(SUBSTRING(CURRENT_PERIOD_YM, 5, 2), '/', SUBSTRING(CURRENT_PERIOD_YM, 1, 4))
        END AS CurrentPeriodLabel,
        IFNULL(CURRENT_STEP_CODE, '') AS CurrentStepCode,
        IFNULL(CURRENT_STEP_NAME, '-') AS CurrentStepName,
        IFNULL(MESSAGE, '') AS Message,
        STATUS AS Status
    FROM acc_period_lock_job
    WHERE COMPANY_CD = p_COMPANY_CD
      AND JOB_ID = p_JOB_ID
    LIMIT 1;
END//
DELIMITER ;


