-- Dumping structure for procedure am_web_001.sp_period_lock_lock_voucher_line
DROP PROCEDURE IF EXISTS `sp_period_lock_lock_voucher_line`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_lock_voucher_line`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_CHIT_ID BIGINT,
    IN p_CHIT_CD VARCHAR(30),
    IN p_CHIT_YMD_CHAR CHAR(8),
    IN p_DEBIT VARCHAR(20),
    IN p_CREDIT VARCHAR(20),
    IN p_AMOUNT DECIMAL(18,2),
    IN p_SORT INT,
    IN p_DEPARTMENT_ID BIGINT,
    IN p_DESCRIPTION VARCHAR(500),
    IN p_USER_ID VARCHAR(50)
)
BEGIN
    DECLARE v_detail_cd VARCHAR(30);
    DECLARE v_detail_id BIGINT;
    DECLARE v_department_cd VARCHAR(20) DEFAULT NULL;

    SET v_detail_cd = LEFT(CONCAT('D', DATE_FORMAT(NOW(6), '%Y%m%d%H%i%s%f'), LPAD(p_SORT, 6, '0')), 30);

    INSERT INTO chitdetailinfo (
        COMPANY_CD, CHIT_ID, CHIT_CD, CHITDETAIL_CD, CHIT_YMD, DEBIT, CREDIT, AMOUNT,
        FC_AMOUNT, FC_RATE, SORT, ISDEL, CREATE_BY, UPDATE_BY
    ) VALUES (
        p_COMPANY_CD, p_CHIT_ID, p_CHIT_CD, v_detail_cd, p_CHIT_YMD_CHAR,
        p_DEBIT, p_CREDIT, p_AMOUNT, 0, 0, p_SORT, '0', p_USER_ID, p_USER_ID
    );
    SET v_detail_id = LAST_INSERT_ID();

    INSERT INTO chitdetaildescriptioninfo (
        COMPANY_CD, CHITDETAIL_ID, CHITDETAIL_CD, DESC_CD, LANG_TYPE, DESCRIPTION,
        ISDEL, CREATE_BY, UPDATE_BY
    ) VALUES (
        p_COMPANY_CD, v_detail_id, LEFT(v_detail_cd, 20), LEFT(v_detail_cd, 20), 'VIET', p_DESCRIPTION,
        '0', p_USER_ID, p_USER_ID
    );

    IF p_DEPARTMENT_ID IS NOT NULL AND p_DEPARTMENT_ID > 0 THEN
        SELECT dep.DEPARTMENT_CD
          INTO v_department_cd
        FROM department_info dep
        WHERE dep.DEPARTMENT_ID = p_DEPARTMENT_ID
          AND dep.COMPANY_CD = p_COMPANY_CD
        LIMIT 1;
    END IF;

    INSERT INTO chitdetailinfo_ext (
        COMPANY_CD, CHITDETAIL_ID, CHITDETAIL_CD, DEPARTMENT_ID, DEPARTMENT_CD,
        ISDEL, CREATE_BY, UPDATE_BY
    ) VALUES (
        p_COMPANY_CD, v_detail_id, LEFT(v_detail_cd, 20), p_DEPARTMENT_ID, v_department_cd,
        '0', p_USER_ID, p_USER_ID
    );
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_months_get
DROP PROCEDURE IF EXISTS `sp_period_lock_months_get`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_months_get`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_YEAR INT
)
BEGIN
    /*
      Mục đích:
      - Trả về đủ 12 tháng theo năm p_YEAR.
      - Nếu DB chưa có dữ liệu thì Status mặc định OPEN.
      - Output alias PascalCase để map vào PeriodLockRowDto.
    */

    DROP TEMPORARY TABLE IF EXISTS tmp_period_lock_months;

    CREATE TEMPORARY TABLE tmp_period_lock_months (
        PERIOD_YM CHAR(6) NOT NULL PRIMARY KEY,
        PERIOD_LABEL VARCHAR(20) NOT NULL,
        FROM_YMD CHAR(8) NOT NULL,
        TO_YMD CHAR(8) NOT NULL
    );

    INSERT INTO tmp_period_lock_months (PERIOD_YM, PERIOD_LABEL, FROM_YMD, TO_YMD)
    SELECT CONCAT(p_YEAR, '01'), CONCAT('01/', p_YEAR), CONCAT(p_YEAR, '0101'), DATE_FORMAT(LAST_DAY(STR_TO_DATE(CONCAT(p_YEAR, '0101'), '%Y%m%d')), '%Y%m%d')
    UNION ALL SELECT CONCAT(p_YEAR, '02'), CONCAT('02/', p_YEAR), CONCAT(p_YEAR, '0201'), DATE_FORMAT(LAST_DAY(STR_TO_DATE(CONCAT(p_YEAR, '0201'), '%Y%m%d')), '%Y%m%d')
    UNION ALL SELECT CONCAT(p_YEAR, '03'), CONCAT('03/', p_YEAR), CONCAT(p_YEAR, '0301'), DATE_FORMAT(LAST_DAY(STR_TO_DATE(CONCAT(p_YEAR, '0301'), '%Y%m%d')), '%Y%m%d')
    UNION ALL SELECT CONCAT(p_YEAR, '04'), CONCAT('04/', p_YEAR), CONCAT(p_YEAR, '0401'), DATE_FORMAT(LAST_DAY(STR_TO_DATE(CONCAT(p_YEAR, '0401'), '%Y%m%d')), '%Y%m%d')
    UNION ALL SELECT CONCAT(p_YEAR, '05'), CONCAT('05/', p_YEAR), CONCAT(p_YEAR, '0501'), DATE_FORMAT(LAST_DAY(STR_TO_DATE(CONCAT(p_YEAR, '0501'), '%Y%m%d')), '%Y%m%d')
    UNION ALL SELECT CONCAT(p_YEAR, '06'), CONCAT('06/', p_YEAR), CONCAT(p_YEAR, '0601'), DATE_FORMAT(LAST_DAY(STR_TO_DATE(CONCAT(p_YEAR, '0601'), '%Y%m%d')), '%Y%m%d')
    UNION ALL SELECT CONCAT(p_YEAR, '07'), CONCAT('07/', p_YEAR), CONCAT(p_YEAR, '0701'), DATE_FORMAT(LAST_DAY(STR_TO_DATE(CONCAT(p_YEAR, '0701'), '%Y%m%d')), '%Y%m%d')
    UNION ALL SELECT CONCAT(p_YEAR, '08'), CONCAT('08/', p_YEAR), CONCAT(p_YEAR, '0801'), DATE_FORMAT(LAST_DAY(STR_TO_DATE(CONCAT(p_YEAR, '0801'), '%Y%m%d')), '%Y%m%d')
    UNION ALL SELECT CONCAT(p_YEAR, '09'), CONCAT('09/', p_YEAR), CONCAT(p_YEAR, '0901'), DATE_FORMAT(LAST_DAY(STR_TO_DATE(CONCAT(p_YEAR, '0901'), '%Y%m%d')), '%Y%m%d')
    UNION ALL SELECT CONCAT(p_YEAR, '10'), CONCAT('10/', p_YEAR), CONCAT(p_YEAR, '1001'), DATE_FORMAT(LAST_DAY(STR_TO_DATE(CONCAT(p_YEAR, '1001'), '%Y%m%d')), '%Y%m%d')
    UNION ALL SELECT CONCAT(p_YEAR, '11'), CONCAT('11/', p_YEAR), CONCAT(p_YEAR, '1101'), DATE_FORMAT(LAST_DAY(STR_TO_DATE(CONCAT(p_YEAR, '1101'), '%Y%m%d')), '%Y%m%d')
    UNION ALL SELECT CONCAT(p_YEAR, '12'), CONCAT('12/', p_YEAR), CONCAT(p_YEAR, '1201'), DATE_FORMAT(LAST_DAY(STR_TO_DATE(CONCAT(p_YEAR, '1201'), '%Y%m%d')), '%Y%m%d');

	 /*Xóa tháng trước ngày đầu kỳ kế toán*/
	 DELETE FROM tmp_period_lock_months
	 WHERE PERIOD_YM <
	 (SELECT LEFT(MAX(CARRYFORWARD_YMD),6)
	     FROM am_web_manager.company_info
	     WHERE COMPANY_CD = p_COMPANY_CD
	       AND IFNULL(ISDEL, '0') = '0');

    SELECT
        M.PERIOD_YM AS PeriodYm,
        M.PERIOD_LABEL AS PeriodLabel,
        M.FROM_YMD AS FromYmd,
        M.TO_YMD AS ToYmd,
        IFNULL(L.STATUS, 'OPEN') AS Status,
        DATE_FORMAT(L.LOCKED_AT, '%Y-%m-%d %H:%i:%s') AS LockedAt,
        L.LOCKED_BY AS LockedBy,
        L.MESSAGE AS Message
    FROM tmp_period_lock_months M
    LEFT JOIN acc_period_lock_month L
        ON L.COMPANY_CD = p_COMPANY_CD
       AND L.PERIOD_YM = M.PERIOD_YM
       AND IFNULL(L.ISDEL, '0') = '0'
    ORDER BY M.PERIOD_YM;

    DROP TEMPORARY TABLE IF EXISTS tmp_period_lock_months;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_month_derive_status
DROP PROCEDURE IF EXISTS `sp_period_lock_month_derive_status`;
DELIMITER //
CREATE DEFINER=`root`@`115.78.232.22` PROCEDURE `sp_period_lock_month_derive_status`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6)
)
BEGIN
    DECLARE v_TOTAL INT DEFAULT 0;
    DECLARE v_DONE INT DEFAULT 0;
    DECLARE v_PROCESSING INT DEFAULT 0;
    DECLARE v_ERROR INT DEFAULT 0;
    DECLARE v_STATUS VARCHAR(20) DEFAULT 'OPEN';

    SELECT COUNT(*),
           SUM(CASE WHEN STATUS = 'DONE' THEN 1 ELSE 0 END),
           SUM(CASE WHEN STATUS = 'PROCESSING' THEN 1 ELSE 0 END),
           SUM(CASE WHEN STATUS = 'ERROR' THEN 1 ELSE 0 END)
    INTO v_TOTAL, v_DONE, v_PROCESSING, v_ERROR
    FROM acc_period_lock_step
    WHERE COMPANY_CD = p_COMPANY_CD
      AND PERIOD_YM = p_PERIOD_YM;

    IF IFNULL(v_ERROR, 0) > 0 THEN
        SET v_STATUS = 'ERROR';
    ELSEIF IFNULL(v_PROCESSING, 0) > 0 THEN
        SET v_STATUS = 'PROCESSING';
    ELSEIF IFNULL(v_TOTAL, 0) >= 3 AND IFNULL(v_DONE, 0) >= 3 THEN
        SET v_STATUS = 'LOCKED';
    ELSEIF IFNULL(v_DONE, 0) > 0 THEN
        SET v_STATUS = 'PARTIAL';
    ELSE
        SET v_STATUS = 'OPEN';
    END IF;

    SELECT v_STATUS AS STATUS;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_month_upsert
DROP PROCEDURE IF EXISTS `sp_period_lock_month_upsert`;
DELIMITER //
CREATE DEFINER=`root`@`115.78.232.22` PROCEDURE `sp_period_lock_month_upsert`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6),
    IN p_FROM_YMD CHAR(8),
    IN p_TO_YMD CHAR(8),
    IN p_STATUS VARCHAR(20),
    IN p_MESSAGE VARCHAR(500),
    IN p_USER_ID VARCHAR(50)
)
BEGIN
    INSERT INTO acc_period_lock_month
    (
        COMPANY_CD, PERIOD_YM, FROM_YMD, TO_YMD,
        STATUS, MESSAGE, LOCKED_AT, LOCKED_BY, ISDEL,
        CREATE_BY, CREATE_AT, UPDATE_BY, UPDATE_AT
    )
    VALUES
    (
        p_COMPANY_CD, p_PERIOD_YM, p_FROM_YMD, p_TO_YMD,
        p_STATUS, p_MESSAGE,
        CASE WHEN p_STATUS = 'LOCKED' THEN NOW() ELSE NULL END,
        CASE WHEN p_STATUS = 'LOCKED' THEN p_USER_ID ELSE NULL END,
        '0', p_USER_ID, NOW(), p_USER_ID, NOW()
    )
    ON DUPLICATE KEY UPDATE
        FROM_YMD = VALUES(FROM_YMD),
        TO_YMD = VALUES(TO_YMD),
        STATUS = VALUES(STATUS),
        MESSAGE = VALUES(MESSAGE),
        LOCKED_AT = CASE WHEN VALUES(STATUS) = 'LOCKED' THEN NOW() ELSE LOCKED_AT END,
        LOCKED_BY = CASE WHEN VALUES(STATUS) = 'LOCKED' THEN p_USER_ID ELSE LOCKED_BY END,
        ISDEL = '0',
        UPDATE_BY = p_USER_ID,
        UPDATE_AT = NOW();
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_period_unlock
DROP PROCEDURE IF EXISTS `sp_period_lock_period_unlock`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_period_unlock`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6),
    IN p_STEP_CODE VARCHAR(50),
    IN p_REASON VARCHAR(500),
    IN p_USER_ID VARCHAR(50)
)
main_block: BEGIN
    DECLARE v_step_name VARCHAR(200);
    DECLARE v_step_order INT DEFAULT 0;
    DECLARE v_msg VARCHAR(1000);

    DECLARE v_step_count INT DEFAULT 0;
    DECLARE v_current_status VARCHAR(20);

    DECLARE v_done_count INT DEFAULT 0;
    DECLARE v_step_total_count INT DEFAULT 0;
    DECLARE v_month_status VARCHAR(20);

    SET v_step_order = CASE p_STEP_CODE
        WHEN 'FA_PREPAID_LOCK' THEN 1
        WHEN 'COGS_SUMMARY' THEN 2
        WHEN 'PROFIT_LOSS_REPORT' THEN 3
        ELSE 0
    END;

    SET v_step_name = CASE p_STEP_CODE
        WHEN 'FA_PREPAID_LOCK' THEN 'Khóa TSCĐ / CP trả trước'
        WHEN 'COGS_SUMMARY' THEN 'Báo cáo về tổng hợp giá vốn'
        WHEN 'PROFIT_LOSS_REPORT' THEN 'Báo cáo lãi lỗ'
        ELSE ''
    END;

    IF v_step_order = 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Bước mở sổ không hợp lệ.';
    END IF;

    SET v_msg = CASE
        WHEN IFNULL(p_REASON, '') = ''
            THEN CONCAT('Đã mở bước: ', v_step_name)
        ELSE CONCAT('Đã mở bước: ', v_step_name, ' - ', p_REASON)
    END;

    /*
        Lấy trạng thái step hiện tại.
        Nếu tháng chưa khóa thì acc_period_lock_step có thể chưa có dòng.
        Với nghiệp vụ mở sổ, trường hợp này coi như đã OPEN và bỏ qua.
    */
    SELECT COUNT(1), MAX(STATUS)
    INTO v_step_count, v_current_status
    FROM acc_period_lock_step
    WHERE COMPANY_CD = p_COMPANY_CD
      AND PERIOD_YM = p_PERIOD_YM
      AND STEP_CODE = p_STEP_CODE;

    IF v_step_count > 0 THEN

        IF v_current_status = 'OPEN' THEN
            SET v_msg = CASE
                WHEN IFNULL(p_REASON, '') = ''
                    THEN CONCAT('Bước đã mở trước đó: ', v_step_name)
                ELSE CONCAT('Bước đã mở trước đó: ', v_step_name, ' - ', p_REASON)
            END;
        ELSEIF v_current_status = 'DONE' THEN

            UPDATE acc_period_lock_task
            SET STATUS = 'OPEN',
                STARTED_AT = NULL,
                FINISHED_AT = NULL,
                MESSAGE = v_msg,
                UPDATE_BY = p_USER_ID,
                UPDATE_AT = NOW()
            WHERE COMPANY_CD = p_COMPANY_CD
              AND PERIOD_YM = p_PERIOD_YM
              AND STEP_CODE = p_STEP_CODE;

            UPDATE acc_period_lock_step
            SET STATUS = 'OPEN',
                STARTED_AT = NULL,
                FINISHED_AT = NULL,
                MESSAGE = v_msg,
                UPDATE_BY = p_USER_ID,
                UPDATE_AT = NOW()
            WHERE COMPANY_CD = p_COMPANY_CD
              AND PERIOD_YM = p_PERIOD_YM
              AND STEP_CODE = p_STEP_CODE;

        ELSE
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Bước cần mở chưa ở trạng thái DONE, không thể mở.';
        END IF;

    ELSE
        SET v_msg = CASE
            WHEN IFNULL(p_REASON, '') = ''
                THEN CONCAT('Không có dữ liệu khóa cho bước: ', v_step_name)
            ELSE CONCAT('Không có dữ liệu khóa cho bước: ', v_step_name, ' - ', p_REASON)
        END;
    END IF;

    /*
        Tính lại trạng thái tháng dựa trên các step còn DONE.
        - Không còn step DONE => OPEN
        - Còn một phần step DONE => PARTIAL
        - Đủ 3 step DONE => LOCKED
    */
    SELECT COUNT(1)
    INTO v_step_total_count
    FROM acc_period_lock_step
    WHERE COMPANY_CD = p_COMPANY_CD
      AND PERIOD_YM = p_PERIOD_YM
      AND STEP_CODE IN ('FA_PREPAID_LOCK', 'COGS_SUMMARY', 'PROFIT_LOSS_REPORT');

    SELECT COUNT(1)
    INTO v_done_count
    FROM acc_period_lock_step
    WHERE COMPANY_CD = p_COMPANY_CD
      AND PERIOD_YM = p_PERIOD_YM
      AND STEP_CODE IN ('FA_PREPAID_LOCK', 'COGS_SUMMARY', 'PROFIT_LOSS_REPORT')
      AND STATUS = 'DONE';

    SET v_month_status = CASE
        WHEN v_step_total_count = 0 THEN 'OPEN'
        WHEN v_done_count = 0 THEN 'OPEN'
        WHEN v_done_count >= 3 THEN 'LOCKED'
        ELSE 'PARTIAL'
    END;

    UPDATE acc_period_lock_month
    SET STATUS = v_month_status,
        LOCKED_AT = CASE WHEN v_month_status = 'LOCKED' THEN LOCKED_AT ELSE NULL END,
        LOCKED_BY = CASE WHEN v_month_status = 'LOCKED' THEN LOCKED_BY ELSE NULL END,
        MESSAGE = v_msg,
        UPDATE_BY = p_USER_ID,
        UPDATE_AT = NOW()
    WHERE COMPANY_CD = p_COMPANY_CD
      AND PERIOD_YM = p_PERIOD_YM
      AND IFNULL(ISDEL, '0') = '0';

END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_pl_build_xfer
DROP PROCEDURE IF EXISTS `sp_period_lock_pl_build_xfer`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_pl_build_xfer`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6)
)
proc: BEGIN
    DECLARE v_from_ymd CHAR(8);
    DECLARE v_to_ymd CHAR(8);
    DECLARE v_acc_511 VARCHAR(20);
    DECLARE v_acc_911 VARCHAR(20);
    DECLARE v_acc_4212 VARCHAR(20);
    DECLARE v_acc_8212 VARCHAR(20);
    DECLARE v_has_source INT DEFAULT 0;

    SET v_from_ymd = CONCAT(p_PERIOD_YM, '01');
    SET v_to_ymd = DATE_FORMAT(LAST_DAY(STR_TO_DATE(CONCAT(p_PERIOD_YM, '01'), '%Y%m%d')), '%Y%m%d');

    DROP TEMPORARY TABLE IF EXISTS tmp_xfer_lines;
    CREATE TEMPORARY TABLE tmp_xfer_lines
    (
        TRANSFER_CODE VARCHAR(30) NOT NULL DEFAULT '',
        DEBIT_ACC VARCHAR(20) NOT NULL DEFAULT '',
        CREDIT_ACC VARCHAR(20) NOT NULL DEFAULT '',
        AMOUNT DECIMAL(18,2) NOT NULL DEFAULT 0,
        DEPARTMENT_ID BIGINT NOT NULL DEFAULT 0,
        KEY idx_tmp_xfer_lines_01 (TRANSFER_CODE)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    DROP TEMPORARY TABLE IF EXISTS tmp_911_dept;
    CREATE TEMPORARY TABLE tmp_911_dept
    (
        DEPARTMENT_ID BIGINT NOT NULL DEFAULT 0,
        NET_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        PRIMARY KEY (DEPARTMENT_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    SELECT COUNT(*)
      INTO v_has_source
    FROM chitinfo C
    INNER JOIN chitdetailinfo CD
        ON CD.COMPANY_CD = C.COMPANY_CD
       AND CD.CHIT_ID = C.CHIT_ID
       AND CD.ISDEL = '0'
    LEFT JOIN acclist_info A_DEBIT
        ON A_DEBIT.COMPANY_CD = CD.COMPANY_CD
       AND A_DEBIT.ACC_CD = TRIM(CD.DEBIT)
       AND IFNULL(A_DEBIT.ISDEL, '0') = '0'
       AND IFNULL(A_DEBIT.ISABLEINPUT, '0') = '1'
    LEFT JOIN acclist_info A_CREDIT
        ON A_CREDIT.COMPANY_CD = CD.COMPANY_CD
       AND A_CREDIT.ACC_CD = TRIM(CD.CREDIT)
       AND IFNULL(A_CREDIT.ISDEL, '0') = '0'
       AND IFNULL(A_CREDIT.ISABLEINPUT, '0') = '1'
    WHERE C.COMPANY_CD = p_COMPANY_CD
      AND C.ISDEL = '0'
      AND C.CHIT_YMD >= v_from_ymd
      AND C.CHIT_YMD <= v_to_ymd
      AND (
            (
                IFNULL(TRIM(CD.DEBIT), '') <> ''
            AND IFNULL(TRIM(CD.CREDIT), '') <> ''
            AND A_DEBIT.ACC_CD IS NOT NULL
            AND (
                    TRIM(CD.DEBIT) LIKE '521%'
                 OR TRIM(CD.DEBIT) LIKE '632%'
                 OR TRIM(CD.DEBIT) LIKE '635%'
                 OR TRIM(CD.DEBIT) LIKE '641%'
                 OR TRIM(CD.DEBIT) LIKE '642%'
                 OR TRIM(CD.DEBIT) LIKE '811%'
                 OR TRIM(CD.DEBIT) LIKE '8211%'
                 OR TRIM(CD.DEBIT) LIKE '8212%'
                 OR TRIM(CD.DEBIT) LIKE '911%'
            )
        )
         OR (
                IFNULL(TRIM(CD.CREDIT), '') <> ''
            AND IFNULL(TRIM(CD.DEBIT), '') <> ''
            AND A_CREDIT.ACC_CD IS NOT NULL
            AND (
                    TRIM(CD.CREDIT) LIKE '511%'
                 OR TRIM(CD.CREDIT) LIKE '515%'
                 OR TRIM(CD.CREDIT) LIKE '711%'
                 OR TRIM(CD.CREDIT) LIKE '8212%'
                 OR TRIM(CD.CREDIT) LIKE '911%'
            )
        )
      );

    IF IFNULL(v_has_source, 0) = 0 THEN
        LEAVE proc;
    END IF;

    CALL sp_period_lock_resolve_posting_acc(p_COMPANY_CD, '511', v_acc_511);
    CALL sp_period_lock_resolve_posting_acc(p_COMPANY_CD, '911', v_acc_911);
    CALL sp_period_lock_resolve_posting_acc(p_COMPANY_CD, '4212', v_acc_4212);
    CALL sp_period_lock_resolve_posting_acc(p_COMPANY_CD, '8212', v_acc_8212);

    CALL sp_period_lock_pl_insert_debit_xfer(
        p_COMPANY_CD, v_from_ymd, v_to_ymd, '521', '521_TO_511', v_acc_511, NULL
    );
    CALL sp_period_lock_pl_insert_credit_xfer(
        p_COMPANY_CD, v_from_ymd, v_to_ymd, '511', '511_TO_911', NULL, v_acc_911
    );
    CALL sp_period_lock_pl_insert_credit_xfer(
        p_COMPANY_CD, v_from_ymd, v_to_ymd, '515', '515_TO_911', NULL, v_acc_911
    );
    CALL sp_period_lock_pl_insert_debit_xfer(
        p_COMPANY_CD, v_from_ymd, v_to_ymd, '632', '632_TO_911', v_acc_911, NULL
    );
    CALL sp_period_lock_pl_insert_debit_xfer(
        p_COMPANY_CD, v_from_ymd, v_to_ymd, '635', '635_TO_911', v_acc_911, NULL
    );
    CALL sp_period_lock_pl_insert_debit_xfer(
        p_COMPANY_CD, v_from_ymd, v_to_ymd, '641', '641_TO_911', v_acc_911, NULL
    );
    CALL sp_period_lock_pl_insert_debit_xfer(
        p_COMPANY_CD, v_from_ymd, v_to_ymd, '642', '642_TO_911', v_acc_911, NULL
    );
    CALL sp_period_lock_pl_insert_credit_xfer(
        p_COMPANY_CD, v_from_ymd, v_to_ymd, '711', '711_TO_911', NULL, v_acc_911
    );
    CALL sp_period_lock_pl_insert_debit_xfer(
        p_COMPANY_CD, v_from_ymd, v_to_ymd, '811', '811_TO_911', v_acc_911, NULL
    );
    CALL sp_period_lock_pl_insert_debit_xfer(
        p_COMPANY_CD, v_from_ymd, v_to_ymd, '8211', '8211_TO_911', v_acc_911, NULL
    );

    DROP TEMPORARY TABLE IF EXISTS tmp_8212_dept;
    CREATE TEMPORARY TABLE tmp_8212_dept
    (
        DEPARTMENT_ID BIGINT NOT NULL DEFAULT 0,
        NET_AMT DECIMAL(18,2) NOT NULL DEFAULT 0,
        PRIMARY KEY (DEPARTMENT_ID)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

    INSERT INTO tmp_8212_dept (DEPARTMENT_ID, NET_AMT)
    SELECT
        IFNULL(ext.DEPARTMENT_ID, 0),
        SUM(CD.AMOUNT)
    FROM chitinfo C
    INNER JOIN chitdetailinfo CD
        ON CD.COMPANY_CD = C.COMPANY_CD
       AND CD.CHIT_ID = C.CHIT_ID
       AND CD.ISDEL = '0'
    LEFT JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = CD.COMPANY_CD
       AND ext.CHITDETAIL_ID = CD.CHITDETAIL_ID
       AND ext.ISDEL = '0'
    INNER JOIN acclist_info A
        ON A.COMPANY_CD = CD.COMPANY_CD
       AND A.ACC_CD = TRIM(CD.DEBIT)
       AND IFNULL(A.ISDEL, '0') = '0'
       AND IFNULL(A.ISABLEINPUT, '0') = '1'
    WHERE C.COMPANY_CD = p_COMPANY_CD
      AND C.ISDEL = '0'
      AND C.CHIT_YMD >= v_from_ymd
      AND C.CHIT_YMD <= v_to_ymd
      AND TRIM(CD.DEBIT) LIKE '8212%'
      AND IFNULL(TRIM(CD.CREDIT), '') <> ''
    GROUP BY IFNULL(ext.DEPARTMENT_ID, 0)
    HAVING SUM(CD.AMOUNT) <> 0;

    INSERT INTO tmp_8212_dept (DEPARTMENT_ID, NET_AMT)
    SELECT
        IFNULL(ext.DEPARTMENT_ID, 0),
        -SUM(CD.AMOUNT)
    FROM chitinfo C
    INNER JOIN chitdetailinfo CD
        ON CD.COMPANY_CD = C.COMPANY_CD
       AND CD.CHIT_ID = C.CHIT_ID
       AND CD.ISDEL = '0'
    LEFT JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = CD.COMPANY_CD
       AND ext.CHITDETAIL_ID = CD.CHITDETAIL_ID
       AND ext.ISDEL = '0'
    INNER JOIN acclist_info A
        ON A.COMPANY_CD = CD.COMPANY_CD
       AND A.ACC_CD = TRIM(CD.CREDIT)
       AND IFNULL(A.ISDEL, '0') = '0'
       AND IFNULL(A.ISABLEINPUT, '0') = '1'
    WHERE C.COMPANY_CD = p_COMPANY_CD
      AND C.ISDEL = '0'
      AND C.CHIT_YMD >= v_from_ymd
      AND C.CHIT_YMD <= v_to_ymd
      AND TRIM(CD.CREDIT) LIKE '8212%'
      AND IFNULL(TRIM(CD.DEBIT), '') <> ''
    GROUP BY IFNULL(ext.DEPARTMENT_ID, 0)
    HAVING SUM(CD.AMOUNT) <> 0
    ON DUPLICATE KEY UPDATE NET_AMT = NET_AMT + VALUES(NET_AMT);

    INSERT INTO tmp_xfer_lines (TRANSFER_CODE, DEBIT_ACC, CREDIT_ACC, AMOUNT, DEPARTMENT_ID)
    SELECT
        '8212_NET',
        v_acc_911,
        v_acc_8212,
        NET_AMT,
        DEPARTMENT_ID
    FROM tmp_8212_dept
    WHERE NET_AMT > 0;

    INSERT INTO tmp_xfer_lines (TRANSFER_CODE, DEBIT_ACC, CREDIT_ACC, AMOUNT, DEPARTMENT_ID)
    SELECT
        '8212_NET',
        v_acc_8212,
        v_acc_911,
        ABS(NET_AMT),
        DEPARTMENT_ID
    FROM tmp_8212_dept
    WHERE NET_AMT < 0;

    INSERT INTO tmp_911_dept (DEPARTMENT_ID, NET_AMT)
    SELECT
        IFNULL(ext.DEPARTMENT_ID, 0),
        SUM(
            CASE
                WHEN TRIM(CD.DEBIT) LIKE '911%' THEN CD.AMOUNT
                ELSE 0
            END
        ) - SUM(
            CASE
                WHEN TRIM(CD.CREDIT) LIKE '911%' THEN CD.AMOUNT
                ELSE 0
            END
        )
    FROM chitinfo C
    INNER JOIN chitdetailinfo CD
        ON CD.COMPANY_CD = C.COMPANY_CD
       AND CD.CHIT_ID = C.CHIT_ID
       AND CD.ISDEL = '0'
    LEFT JOIN chitdetailinfo_ext ext
        ON ext.COMPANY_CD = CD.COMPANY_CD
       AND ext.CHITDETAIL_ID = CD.CHITDETAIL_ID
       AND ext.ISDEL = '0'
    WHERE C.COMPANY_CD = p_COMPANY_CD
      AND C.ISDEL = '0'
      AND C.CHIT_YMD >= v_from_ymd
      AND C.CHIT_YMD <= v_to_ymd
      AND (
            TRIM(CD.DEBIT) LIKE '911%'
         OR TRIM(CD.CREDIT) LIKE '911%'
      )
    GROUP BY IFNULL(ext.DEPARTMENT_ID, 0)
    HAVING SUM(
            CASE
                WHEN TRIM(CD.DEBIT) LIKE '911%' THEN CD.AMOUNT
                ELSE 0
            END
        ) - SUM(
            CASE
                WHEN TRIM(CD.CREDIT) LIKE '911%' THEN CD.AMOUNT
                ELSE 0
            END
        ) <> 0
    ON DUPLICATE KEY UPDATE NET_AMT = NET_AMT + VALUES(NET_AMT);

    INSERT INTO tmp_911_dept (DEPARTMENT_ID, NET_AMT)
    SELECT
        DEPARTMENT_ID,
        SUM(
            CASE
                WHEN DEBIT_ACC = v_acc_911 THEN AMOUNT
                WHEN CREDIT_ACC = v_acc_911 THEN -AMOUNT
                ELSE 0
            END
        )
    FROM tmp_xfer_lines
    WHERE TRANSFER_CODE <> '911_TO_4212'
    GROUP BY DEPARTMENT_ID
    HAVING SUM(
        CASE
            WHEN DEBIT_ACC = v_acc_911 THEN AMOUNT
            WHEN CREDIT_ACC = v_acc_911 THEN -AMOUNT
            ELSE 0
        END
    ) <> 0
    ON DUPLICATE KEY UPDATE NET_AMT = NET_AMT + VALUES(NET_AMT);

    INSERT INTO tmp_xfer_lines (TRANSFER_CODE, DEBIT_ACC, CREDIT_ACC, AMOUNT, DEPARTMENT_ID)
    SELECT
        '911_TO_4212',
        v_acc_911,
        v_acc_4212,
        NET_AMT,
        DEPARTMENT_ID
    FROM tmp_911_dept
    WHERE NET_AMT > 0;

    INSERT INTO tmp_xfer_lines (TRANSFER_CODE, DEBIT_ACC, CREDIT_ACC, AMOUNT, DEPARTMENT_ID)
    SELECT
        '911_TO_4212',
        v_acc_4212,
        v_acc_911,
        ABS(NET_AMT),
        DEPARTMENT_ID
    FROM tmp_911_dept
    WHERE NET_AMT < 0;
END proc//
DELIMITER ;


