-- Dumping structure for procedure am_web_001.sp_period_lock_pl_unlock
DROP PROCEDURE IF EXISTS `sp_period_lock_pl_unlock`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_pl_unlock`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6),
    IN p_REASON VARCHAR(500),
    IN p_USER_ID VARCHAR(50)
)
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    CALL sp_period_lock_closingmonth_delete(p_COMPANY_CD, p_PERIOD_YM);

    CALL sp_period_lock_delete_lock_vouchers(
        p_COMPANY_CD,
        p_PERIOD_YM,
        'PROFIT_LOSS_REPORT'
    );

    CALL sp_period_lock_step_upsert(
        p_COMPANY_CD,
        p_PERIOD_YM,
        'PROFIT_LOSS_REPORT',
        'Báo cáo lãi lỗ',
        3,
        'OPEN',
        'Đã mở',
        p_USER_ID
    );

    COMMIT;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_pl_validate
DROP PROCEDURE IF EXISTS `sp_period_lock_pl_validate`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_pl_validate`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6),
    IN p_BALANCE_METHOD VARCHAR(50),
    IN p_USER_ID VARCHAR(50)
)
BEGIN
    CALL sp_period_lock_step_require_done(p_COMPANY_CD, p_PERIOD_YM, 'FA_PREPAID_LOCK', 'FA');
    CALL sp_period_lock_step_require_done(p_COMPANY_CD, p_PERIOD_YM, 'COGS_SUMMARY', 'COGS');
    CALL sp_period_lock_step_require_open(p_COMPANY_CD, p_PERIOD_YM, 'PROFIT_LOSS_REPORT');

    IF p_BALANCE_METHOD NOT IN ('BALANCE_ACCOUNT', 'BALANCE_ACCOUNT_TWO_SIDE') THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Phuong phap bao cao lai lo khong hop le';
    END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_post_xfer_group
DROP PROCEDURE IF EXISTS `sp_period_lock_post_xfer_group`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_post_xfer_group`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6),
    IN p_LOCK_STEP_CODE VARCHAR(50),
    IN p_TRANSFER_CODE VARCHAR(30),
    IN p_DESCRIPTION VARCHAR(500),
    IN p_USER_ID VARCHAR(50),
    IN p_CODE_TAG VARCHAR(10)
)
proc: BEGIN
    DECLARE v_done INT DEFAULT 0;
    DECLARE v_debit VARCHAR(20);
    DECLARE v_credit VARCHAR(20);
    DECLARE v_amount DECIMAL(18,2);
    DECLARE v_dept_id BIGINT;
    DECLARE v_chit_id BIGINT;
    DECLARE v_chit_cd VARCHAR(30);
    DECLARE v_chit_ymd CHAR(8);
    DECLARE v_sort INT DEFAULT 0;
    DECLARE v_total DECIMAL(18,2) DEFAULT 0;
    DECLARE v_line_count INT DEFAULT 0;

    DECLARE cur_lines CURSOR FOR
        SELECT DEBIT_ACC, CREDIT_ACC, AMOUNT, DEPARTMENT_ID
        FROM tmp_xfer_lines
        WHERE TRANSFER_CODE = p_TRANSFER_CODE
          AND AMOUNT > 0
        ORDER BY DEPARTMENT_ID, DEBIT_ACC, CREDIT_ACC;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    SELECT IFNULL(COUNT(*), 0)
      INTO v_line_count
    FROM tmp_xfer_lines
    WHERE TRANSFER_CODE = p_TRANSFER_CODE
      AND AMOUNT > 0;

    IF v_line_count = 0 THEN
        LEAVE proc;
    END IF;

    CALL sp_period_lock_lock_voucher_begin(
        p_COMPANY_CD, p_PERIOD_YM, p_LOCK_STEP_CODE, p_DESCRIPTION, p_USER_ID, p_CODE_TAG,
        v_chit_id, v_chit_cd, v_chit_ymd
    );

    OPEN cur_lines;
    line_loop: LOOP
        SET v_done = 0;
        FETCH cur_lines INTO v_debit, v_credit, v_amount, v_dept_id;
        IF v_done = 1 THEN
            LEAVE line_loop;
        END IF;

        SET v_sort = v_sort + 1;
        SET v_total = v_total + IFNULL(v_amount, 0);

        CALL sp_period_lock_lock_voucher_line(
            p_COMPANY_CD, v_chit_id, v_chit_cd, v_chit_ymd,
            v_debit, v_credit, v_amount, v_sort, v_dept_id,
            p_DESCRIPTION, p_USER_ID
        );
    END LOOP;
    CLOSE cur_lines;

    CALL sp_period_lock_lock_voucher_end(p_COMPANY_CD, v_chit_id, v_total, p_USER_ID);
END proc//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_resolve_posting_acc
DROP PROCEDURE IF EXISTS `sp_period_lock_resolve_posting_acc`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_resolve_posting_acc`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_ACC_PREFIX VARCHAR(20),
    OUT p_ACC_CD VARCHAR(20)
)
BEGIN
    SET p_ACC_CD = NULL;

    SELECT ACC_CD
      INTO p_ACC_CD
    FROM acclist_info
    WHERE COMPANY_CD = p_COMPANY_CD
      AND IFNULL(ISDEL, '0') = '0'
      AND IFNULL(ISABLEINPUT, '0') = '1'
      AND ACC_CD LIKE CONCAT(TRIM(p_ACC_PREFIX), '%')
    ORDER BY ACC_CD ASC
    LIMIT 1;

    IF IFNULL(p_ACC_CD, '') = '' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Khong tim thay TK hach toan ISABLEINPUT=1';
    END IF;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001.sp_period_lock_steps_get
DROP PROCEDURE IF EXISTS `sp_period_lock_steps_get`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `sp_period_lock_steps_get`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_YEAR INT
)
BEGIN
    /*
      Mục đích:
      - Trả về 3 step cho mỗi tháng trong năm.
      - Nếu step chưa có dữ liệu thì Status mặc định OPEN.
      - Output alias PascalCase để map vào PeriodLockStepFlatDto.
    */

    DROP TEMPORARY TABLE IF EXISTS tmp_period_lock_months;

    CREATE TEMPORARY TABLE tmp_period_lock_months (
        PERIOD_YM CHAR(6) NOT NULL PRIMARY KEY
    );

    INSERT INTO tmp_period_lock_months (PERIOD_YM)
    SELECT CONCAT(p_YEAR, '01')
    UNION ALL SELECT CONCAT(p_YEAR, '02')
    UNION ALL SELECT CONCAT(p_YEAR, '03')
    UNION ALL SELECT CONCAT(p_YEAR, '04')
    UNION ALL SELECT CONCAT(p_YEAR, '05')
    UNION ALL SELECT CONCAT(p_YEAR, '06')
    UNION ALL SELECT CONCAT(p_YEAR, '07')
    UNION ALL SELECT CONCAT(p_YEAR, '08')
    UNION ALL SELECT CONCAT(p_YEAR, '09')
    UNION ALL SELECT CONCAT(p_YEAR, '10')
    UNION ALL SELECT CONCAT(p_YEAR, '11')
    UNION ALL SELECT CONCAT(p_YEAR, '12');

	 /*Xóa tháng trước ngày đầu kỳ kế toán*/
	 DELETE FROM tmp_period_lock_months
	 WHERE PERIOD_YM <
	 (SELECT LEFT(MAX(CARRYFORWARD_YMD),6)
	     FROM am_web_manager.company_info
	     WHERE COMPANY_CD = p_COMPANY_CD
	       AND IFNULL(ISDEL, '0') = '0');
	       
    SELECT
        M.PERIOD_YM AS PeriodYm,
        S.STEP_CODE AS StepCode,
        S.STEP_NAME AS StepName,
        S.STEP_ORDER AS StepOrder,
        IFNULL(L.STATUS, 'OPEN') AS Status,
        DATE_FORMAT(L.STARTED_AT, '%Y-%m-%d %H:%i:%s') AS StartedAt,
        DATE_FORMAT(L.FINISHED_AT, '%Y-%m-%d %H:%i:%s') AS FinishedAt,
        L.MESSAGE AS Message
    FROM tmp_period_lock_months M
    CROSS JOIN (
        SELECT 'FA_PREPAID_LOCK' AS STEP_CODE, 'Khóa TSCĐ / CP trả trước' AS STEP_NAME, 1 AS STEP_ORDER
        UNION ALL
        SELECT 'COGS_SUMMARY', 'Báo cáo về tổng hợp giá vốn', 2
        UNION ALL
        SELECT 'PROFIT_LOSS_REPORT', 'Báo cáo lãi lỗ', 3
    ) S
    LEFT JOIN acc_period_lock_step L
        ON L.COMPANY_CD = p_COMPANY_CD
       AND L.PERIOD_YM = M.PERIOD_YM
       AND L.STEP_CODE = S.STEP_CODE
    ORDER BY M.PERIOD_YM, S.STEP_ORDER;

    DROP TEMPORARY TABLE IF EXISTS tmp_period_lock_months;
END//
DELIMITER ;


