-- Dumping structure for procedure am_web_001.sp_period_lock_step_upsert
DROP PROCEDURE IF EXISTS `sp_period_lock_step_upsert`;
DELIMITER //
CREATE DEFINER=`root`@`115.78.232.22` PROCEDURE `sp_period_lock_step_upsert`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_PERIOD_YM CHAR(6),
    IN p_STEP_CODE VARCHAR(50),
    IN p_STEP_NAME VARCHAR(255),
    IN p_STEP_ORDER INT,
    IN p_STATUS VARCHAR(20),
    IN p_MESSAGE VARCHAR(500),
    IN p_USER_ID VARCHAR(50)
)
BEGIN
    INSERT INTO acc_period_lock_step
    (
        COMPANY_CD, PERIOD_YM, STEP_CODE, STEP_NAME, STEP_ORDER,
        STATUS, STARTED_AT, FINISHED_AT, MESSAGE,
        CREATE_BY, CREATE_AT, UPDATE_BY, UPDATE_AT
    )
    VALUES
    (
        p_COMPANY_CD, p_PERIOD_YM, p_STEP_CODE, p_STEP_NAME, p_STEP_ORDER,
        p_STATUS,
        CASE WHEN p_STATUS = 'PROCESSING' THEN NOW() ELSE NULL END,
        CASE WHEN p_STATUS IN ('DONE', 'ERROR') THEN NOW() ELSE NULL END,
        p_MESSAGE,
        p_USER_ID, NOW(), p_USER_ID, NOW()
    )
    ON DUPLICATE KEY UPDATE
        STEP_NAME = VALUES(STEP_NAME),
        STEP_ORDER = VALUES(STEP_ORDER),
        STATUS = VALUES(STATUS),
        STARTED_AT = CASE WHEN VALUES(STATUS) = 'PROCESSING' THEN NOW() ELSE STARTED_AT END,
        FINISHED_AT = CASE WHEN VALUES(STATUS) IN ('DONE', 'ERROR') THEN NOW() ELSE FINISHED_AT END,
        MESSAGE = VALUES(MESSAGE),
        UPDATE_BY = p_USER_ID,
        UPDATE_AT = NOW();
END//
DELIMITER ;


