-- Dumping structure for procedure am_web_001.syncSysNotificationFromRules
DROP PROCEDURE IF EXISTS `syncSysNotificationFromRules`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `syncSysNotificationFromRules`(
    IN p_COMPANY_CD VARCHAR(20),
    IN p_USER_ID VARCHAR(50),
    IN p_FROM_YMD CHAR(8),
    IN p_TO_YMD CHAR(8)
)
BEGIN
    DECLARE v_today_ymd CHAR(8);
    DECLARE v_period_ym CHAR(6);
    DECLARE v_cash_balance DECIMAL(18,2) DEFAULT 0;
    DECLARE v_pending_count INT DEFAULT 0;
    DECLARE v_overdue_ar INT DEFAULT 0;
    DECLARE v_due_payables INT DEFAULT 0;

    SET v_today_ymd = DATE_FORMAT(NOW(), '%Y%m%d');
    SET v_period_ym = LEFT(COALESCE(NULLIF(TRIM(p_FROM_YMD), ''), v_today_ymd), 6);

    DELETE FROM sys_notification
    WHERE COMPANY_CD = p_COMPANY_CD
      AND CREATE_BY = 'SYSTEM_SYNC'
      AND (USER_ID IS NULL OR USER_ID = NULLIF(TRIM(p_USER_ID), ''));

    INSERT INTO sys_notification (
        COMPANY_CD, USER_ID, ROLE_CD, NOTIFICATION_TYPE, SOURCE_MODULE, SOURCE_ID,
        TITLE, MESSAGE, PRIORITY, ACTION_URL, IS_READ, CREATE_BY, CREATE_AT
    )
    SELECT
        p_COMPANY_CD,
        NULL,
        NULL,
        t.CATEGORY,
        t.SOURCE_MODULE,
        CONCAT(v_period_ym, ':', t.CATEGORY),
        t.TITLE,
        t.MESSAGE,
        t.PRIORITY,
        t.ACTION_URL,
        'N',
        'SYSTEM_SYNC',
        NOW()
    FROM (
        SELECT
            'PENDING' AS CATEGORY,
            'VOUCHER' AS SOURCE_MODULE,
            'Chứng từ chưa ghi sổ' AS TITLE,
            CONCAT('Có ', COUNT(*), ' chứng từ chưa ghi sổ trong kỳ ', DATE_FORMAT(STR_TO_DATE(p_FROM_YMD, '%Y%m%d'), '%m/%Y'), '.') AS MESSAGE,
            'HIGH' AS PRIORITY,
            '/voucher' AS ACTION_URL
        FROM chitinfo c
        INNER JOIN chitinfo_ext e ON e.CHIT_ID = c.CHIT_ID AND e.COMPANY_CD = c.COMPANY_CD
        WHERE c.COMPANY_CD = p_COMPANY_CD AND c.ISDEL = '0' AND e.ISDEL = '0'
          AND e.IS_LOCK = '0'
          AND c.CHIT_YMD >= p_FROM_YMD AND c.CHIT_YMD <= p_TO_YMD
        HAVING COUNT(*) > 0

        UNION ALL

        SELECT
            'UNCONFIRMED',
            'VOUCHER',
            'Chứng từ chưa xác nhận',
            CONCAT('Có ', COUNT(*), ' chứng từ chưa xác nhận trong kỳ ', DATE_FORMAT(STR_TO_DATE(p_FROM_YMD, '%Y%m%d'), '%m/%Y'), '.'),
            'MEDIUM',
            '/voucher'
        FROM chitinfo c
        INNER JOIN chitinfo_ext e ON e.CHIT_ID = c.CHIT_ID AND e.COMPANY_CD = c.COMPANY_CD
        WHERE c.COMPANY_CD = p_COMPANY_CD AND c.ISDEL = '0' AND e.ISDEL = '0'
          AND e.IS_CONFIRMED = '0' AND e.IS_LOCK = '0'
          AND c.CHIT_YMD >= p_FROM_YMD AND c.CHIT_YMD <= p_TO_YMD
        HAVING COUNT(*) > 0

        UNION ALL

        SELECT
            'OVERDUE_AR',
            'RECEIVABLE',
            'Công nợ phải thu quá hạn',
            CONCAT('Có ', COUNT(DISTINCT c.CHIT_ID), ' chứng từ công nợ phải thu quá hạn 30 ngày.'),
            'HIGH',
            '/receivables'
        FROM chitdetailinfo d
        INNER JOIN chitinfo c ON c.CHIT_ID = d.CHIT_ID AND c.COMPANY_CD = d.COMPANY_CD
        WHERE d.COMPANY_CD = p_COMPANY_CD AND d.ISDEL = '0' AND c.ISDEL = '0'
          AND (d.DEBIT LIKE '131%' OR d.CREDIT LIKE '131%')
          AND c.CHIT_YMD < DATE_FORMAT(DATE_SUB(STR_TO_DATE(v_today_ymd, '%Y%m%d'), INTERVAL 30 DAY), '%Y%m%d')
        HAVING COUNT(DISTINCT c.CHIT_ID) > 0

        UNION ALL

        SELECT
            'OPEN_PERIOD',
            'PERIOD_LOCK',
            'Kỳ kế toán chưa khóa sổ',
            CONCAT('Có ', COUNT(*), ' kỳ kế toán chưa khóa sổ trong năm ', LEFT(v_period_ym, 4), '.'),
            'MEDIUM',
            '/period-lock'
        FROM acc_period_lock_month
        WHERE COMPANY_CD = p_COMPANY_CD AND ISDEL = '0'
          AND STATUS IN ('OPEN', 'PARTIAL')
          AND LEFT(PERIOD_YM, 4) = LEFT(v_period_ym, 4)
        HAVING COUNT(*) > 0

        UNION ALL

        SELECT
            'STEP_ERROR',
            'PERIOD_LOCK',
            'Bước khóa sổ bị lỗi',
            CONCAT('Có ', COUNT(*), ' bước khóa sổ bị lỗi tại kỳ ', v_period_ym, '.'),
            'CRITICAL',
            '/period-lock'
        FROM acc_period_lock_step
        WHERE COMPANY_CD = p_COMPANY_CD AND STATUS = 'ERROR'
          AND PERIOD_YM = v_period_ym
        HAVING COUNT(*) > 0

        UNION ALL

        SELECT
            'NO_CLOSING',
            'PERIOD_LOCK',
            'Kỳ chưa có bút toán kết chuyển',
            CONCAT('Kỳ ', v_period_ym, ' chưa có bút toán kết chuyển cuối kỳ.'),
            'MEDIUM',
            '/period-lock'
        FROM DUAL
        WHERE NOT EXISTS (
            SELECT 1
            FROM closingmonth_detail
            WHERE COMPANY_CD = p_COMPANY_CD AND ISDEL = '0'
              AND LEFT(CLOSE_YMD, 6) = v_period_ym
        )
    ) t;

    SELECT COALESCE(SUM(
        CASE WHEN d.DEBIT LIKE '111%' OR d.DEBIT LIKE '112%' THEN d.AMOUNT ELSE 0 END -
        CASE WHEN d.CREDIT LIKE '111%' OR d.CREDIT LIKE '112%' THEN d.AMOUNT ELSE 0 END
    ), 0) INTO v_cash_balance
    FROM chitdetailinfo d
    INNER JOIN chitinfo c ON c.CHIT_ID = d.CHIT_ID AND c.COMPANY_CD = d.COMPANY_CD
    WHERE d.COMPANY_CD = p_COMPANY_CD AND d.ISDEL = '0' AND c.ISDEL = '0'
      AND c.CHIT_YMD <= p_TO_YMD;

    IF v_cash_balance < 0 THEN
        INSERT INTO sys_notification (
            COMPANY_CD, USER_ID, ROLE_CD, NOTIFICATION_TYPE, SOURCE_MODULE, SOURCE_ID,
            TITLE, MESSAGE, PRIORITY, ACTION_URL, IS_READ, CREATE_BY, CREATE_AT
        ) VALUES (
            p_COMPANY_CD, NULL, NULL,
            'LOW_CASH', 'CASH', CONCAT(v_period_ym, ':LOW_CASH'),
            'Số dư tiền mặt/ngân hàng thấp',
            CONCAT('Số dư tiền mặt/ngân hàng hiện tại: ', FORMAT(v_cash_balance, 0), '.'),
            'HIGH', '/cash', 'N', 'SYSTEM_SYNC', NOW()
        );
    ELSEIF v_cash_balance < 1000000 THEN
        INSERT INTO sys_notification (
            COMPANY_CD, USER_ID, ROLE_CD, NOTIFICATION_TYPE, SOURCE_MODULE, SOURCE_ID,
            TITLE, MESSAGE, PRIORITY, ACTION_URL, IS_READ, CREATE_BY, CREATE_AT
        ) VALUES (
            p_COMPANY_CD, NULL, NULL,
            'LOW_CASH', 'CASH', CONCAT(v_period_ym, ':LOW_CASH'),
            'Cảnh báo dòng tiền thấp',
            CONCAT('Số dư tiền mặt/ngân hàng dưới ngưỡng cảnh báo: ', FORMAT(v_cash_balance, 0), '.'),
            'MEDIUM', '/cash', 'N', 'SYSTEM_SYNC', NOW()
        );
    END IF;

    SELECT COUNT(*) INTO v_due_payables
    FROM chitdetailinfo d
    INNER JOIN chitinfo c ON c.CHIT_ID = d.CHIT_ID AND c.COMPANY_CD = d.COMPANY_CD
    WHERE d.COMPANY_CD = p_COMPANY_CD AND d.ISDEL = '0' AND c.ISDEL = '0'
      AND (d.CREDIT LIKE '331%' OR d.DEBIT LIKE '331%')
      AND c.CHIT_YMD BETWEEN DATE_FORMAT(DATE_SUB(STR_TO_DATE(v_today_ymd, '%Y%m%d'), INTERVAL 7 DAY), '%Y%m%d')
                         AND DATE_FORMAT(DATE_ADD(STR_TO_DATE(v_today_ymd, '%Y%m%d'), INTERVAL 7 DAY), '%Y%m%d');

    IF v_due_payables > 0 THEN
        INSERT INTO sys_notification (
            COMPANY_CD, USER_ID, ROLE_CD, NOTIFICATION_TYPE, SOURCE_MODULE, SOURCE_ID,
            TITLE, MESSAGE, PRIORITY, ACTION_URL, IS_READ, CREATE_BY, CREATE_AT
        ) VALUES (
            p_COMPANY_CD, NULL, NULL,
            'DUE_AP', 'PAYABLE', CONCAT(v_period_ym, ':DUE_AP'),
            'Nhà cung cấp sắp đến hạn thanh toán',
            CONCAT('Có ', v_due_payables, ' chứng từ công nợ phải trả trong vòng 7 ngày tới.'),
            'MEDIUM', '/payables', 'N', 'SYSTEM_SYNC', NOW()
        );
    END IF;

    INSERT INTO sys_notification (
        COMPANY_CD, USER_ID, ROLE_CD, NOTIFICATION_TYPE, SOURCE_MODULE, SOURCE_ID,
        TITLE, MESSAGE, PRIORITY, ACTION_URL, IS_READ, CREATE_BY, CREATE_AT
    )
    SELECT
        p_COMPANY_CD,
        NULL,
        NULL,
        'TAX_DEADLINE',
        'TAX',
        CONCAT(v_period_ym, ':', t.REPORT_NM),
        CONCAT('Sắp đến hạn nộp: ', t.REPORT_NM),
        CONCAT('Kỳ ', t.PERIOD, ' — hạn nộp ', DATE_FORMAT(STR_TO_DATE(t.DUE_DATE, '%Y%m%d'), '%d/%m/%Y'), '.'),
        CASE
            WHEN DATEDIFF(STR_TO_DATE(t.DUE_DATE, '%Y%m%d'), STR_TO_DATE(v_today_ymd, '%Y%m%d')) <= 3 THEN 'CRITICAL'
            WHEN DATEDIFF(STR_TO_DATE(t.DUE_DATE, '%Y%m%d'), STR_TO_DATE(v_today_ymd, '%Y%m%d')) <= 7 THEN 'HIGH'
            ELSE 'MEDIUM'
        END,
        '/tax',
        'N',
        'SYSTEM_SYNC',
        NOW()
    FROM (
        SELECT
            'Tờ khai VAT (Tháng)' AS REPORT_NM,
            v_period_ym AS PERIOD,
            CONCAT(DATE_FORMAT(DATE_ADD(STR_TO_DATE(CONCAT(v_period_ym, '01'), '%Y%m%d'), INTERVAL 1 MONTH), '%Y%m'), '20') AS DUE_DATE
        UNION ALL
        SELECT 'Thuế TNCN (PIT)', v_period_ym,
            CONCAT(DATE_FORMAT(DATE_ADD(STR_TO_DATE(CONCAT(v_period_ym, '01'), '%Y%m%d'), INTERVAL 1 MONTH), '%Y%m'), '20')
    ) t
    WHERE DATEDIFF(STR_TO_DATE(t.DUE_DATE, '%Y%m%d'), STR_TO_DATE(v_today_ymd, '%Y%m%d')) BETWEEN 0 AND 14;

    SELECT COUNT(*) AS SYNCED_COUNT
    FROM sys_notification
    WHERE COMPANY_CD = p_COMPANY_CD
      AND CREATE_BY = 'SYSTEM_SYNC'
      AND (USER_ID IS NULL OR USER_ID = NULLIF(TRIM(p_USER_ID), ''));
END//
DELIMITER ;


