-- Dumping structure for procedure am_web_001._sp_fix_chit_id_phase_a
DROP PROCEDURE IF EXISTS `_sp_fix_chit_id_phase_a`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `_sp_fix_chit_id_phase_a`(IN p_batch INT)
BEGIN
  DECLARE v_n INT DEFAULT 1;
  DECLARE v_base BIGINT;
  SET v_base = (SELECT V FROM `_fix_chit_id_meta` WHERE K = 'base');
  SET SESSION innodb_lock_wait_timeout = 600;
  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  SET FOREIGN_KEY_CHECKS = 0;

  phase_a: WHILE v_n > 0 DO
    DROP TEMPORARY TABLE IF EXISTS `_batch_ids`;
    CREATE TEMPORARY TABLE `_batch_ids` (
      OLD_ID BIGINT NOT NULL PRIMARY KEY,
      NEW_ID BIGINT NOT NULL
    ) ENGINE=InnoDB;

    INSERT INTO `_batch_ids` (OLD_ID, NEW_ID)
    SELECT OLD_ID, NEW_ID FROM `_fix_chit_id_map`
    WHERE PHASE = 0 ORDER BY OLD_ID LIMIT p_batch;

    SET v_n = (SELECT COUNT(*) FROM `_batch_ids`);
    IF v_n = 0 THEN
      LEAVE phase_a;
    END IF;

    START TRANSACTION;

    UPDATE chitinfo_ext e
    INNER JOIN `_batch_ids` b ON b.OLD_ID = e.CHIT_ID
    SET e.CHIT_ID = b.NEW_ID + v_base;

    UPDATE chitdetailinfo d
    INNER JOIN `_batch_ids` b ON b.OLD_ID = d.CHIT_ID
    SET d.CHIT_ID = b.NEW_ID + v_base;

    UPDATE chitdescriptioninfo d
    INNER JOIN `_batch_ids` b ON b.OLD_ID = d.CHIT_ID
    SET d.CHIT_ID = b.NEW_ID + v_base;

    UPDATE chit_inventory_input x
    INNER JOIN `_batch_ids` b ON b.OLD_ID = x.INVENTORY_ID
    SET x.INVENTORY_ID = b.NEW_ID + v_base;

    UPDATE chit_inventory_output x
    INNER JOIN `_batch_ids` b ON b.OLD_ID = x.INVENTORY_ID
    SET x.INVENTORY_ID = b.NEW_ID + v_base;

    UPDATE chitinfo ci
    INNER JOIN `_batch_ids` b ON b.OLD_ID = ci.CHIT_ID_COGS
    SET ci.CHIT_ID_COGS = b.NEW_ID + v_base;

    UPDATE chitinfo ci
    INNER JOIN `_batch_ids` b ON b.OLD_ID = ci.CHIT_ID
    SET ci.CHIT_ID = b.NEW_ID + v_base;

    UPDATE `_fix_chit_id_map` m
    INNER JOIN `_batch_ids` b ON b.OLD_ID = m.OLD_ID
    SET m.PHASE = 1;

    COMMIT;
  END WHILE phase_a;

  SELECT 'phase_a_done' AS status,
         SUM(PHASE = 0) AS remain0,
         SUM(PHASE = 1) AS in_temp,
         SUM(PHASE = 2) AS done2
  FROM `_fix_chit_id_map`;
END//
DELIMITER ;


-- Dumping structure for procedure am_web_001._sp_fix_chit_id_phase_b
DROP PROCEDURE IF EXISTS `_sp_fix_chit_id_phase_b`;
DELIMITER //
CREATE DEFINER=`amnc9it`@`115.78.232.22` PROCEDURE `_sp_fix_chit_id_phase_b`(IN p_batch INT)
BEGIN
  DECLARE v_n INT DEFAULT 1;
  DECLARE v_base BIGINT;
  DECLARE v_next BIGINT;
  SET v_base = (SELECT V FROM `_fix_chit_id_meta` WHERE K = 'base');
  SET SESSION innodb_lock_wait_timeout = 600;
  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  SET FOREIGN_KEY_CHECKS = 0;

  phase_b: WHILE v_n > 0 DO
    DROP TEMPORARY TABLE IF EXISTS `_batch_ids`;
    CREATE TEMPORARY TABLE `_batch_ids` (
      OLD_ID BIGINT NOT NULL PRIMARY KEY,
      NEW_ID BIGINT NOT NULL,
      TEMP_ID BIGINT NOT NULL,
      KEY (TEMP_ID)
    ) ENGINE=InnoDB;

    INSERT INTO `_batch_ids` (OLD_ID, NEW_ID, TEMP_ID)
    SELECT OLD_ID, NEW_ID, NEW_ID + v_base
    FROM `_fix_chit_id_map`
    WHERE PHASE = 1 ORDER BY NEW_ID LIMIT p_batch;

    SET v_n = (SELECT COUNT(*) FROM `_batch_ids`);
    IF v_n = 0 THEN
      LEAVE phase_b;
    END IF;

    START TRANSACTION;

    UPDATE chitinfo_ext e
    INNER JOIN `_batch_ids` b ON b.TEMP_ID = e.CHIT_ID
    SET e.CHIT_ID = b.NEW_ID;

    UPDATE chitdetailinfo d
    INNER JOIN `_batch_ids` b ON b.TEMP_ID = d.CHIT_ID
    SET d.CHIT_ID = b.NEW_ID;

    UPDATE chitdescriptioninfo d
    INNER JOIN `_batch_ids` b ON b.TEMP_ID = d.CHIT_ID
    SET d.CHIT_ID = b.NEW_ID;

    UPDATE chit_inventory_input x
    INNER JOIN `_batch_ids` b ON b.TEMP_ID = x.INVENTORY_ID
    SET x.INVENTORY_ID = b.NEW_ID;

    UPDATE chit_inventory_output x
    INNER JOIN `_batch_ids` b ON b.TEMP_ID = x.INVENTORY_ID
    SET x.INVENTORY_ID = b.NEW_ID;

    UPDATE chitinfo ci
    INNER JOIN `_batch_ids` b ON b.TEMP_ID = ci.CHIT_ID_COGS
    SET ci.CHIT_ID_COGS = b.NEW_ID;

    UPDATE chitinfo ci
    INNER JOIN `_batch_ids` b ON b.TEMP_ID = ci.CHIT_ID
    SET ci.CHIT_ID = b.NEW_ID;

    UPDATE `_fix_chit_id_map` m
    INNER JOIN `_batch_ids` b ON b.OLD_ID = m.OLD_ID
    SET m.PHASE = 2;

    COMMIT;
  END WHILE phase_b;

  SET v_next = (SELECT IFNULL(MAX(CHIT_ID), 0) + 1 FROM chitinfo);
  SET @sql = CONCAT('ALTER TABLE `chitinfo` AUTO_INCREMENT = ', v_next);
  PREPARE stmt FROM @sql;
  EXECUTE stmt;
  DEALLOCATE PREPARE stmt;
  SET FOREIGN_KEY_CHECKS = 1;

  SELECT 'phase_b_done' AS status,
         MIN(CHIT_ID) mn, MAX(CHIT_ID) mx, COUNT(*) cnt,
         (MAX(CHIT_ID) - MIN(CHIT_ID) + 1) AS span
  FROM chitinfo;
END//
